        [306] = { e = 2, s = "s", r = "Single contest win; low difficulty fishing.", d = "Participate in either the Booty Bay fishing contest or the Kalu'ak Fishing Derby to win and claim this achievement. These contests are seasonal, so check event schedules before starting.", x = 2 },
        [388] = { e = 4, s = "g", r = "Grind PvP kills in cities; RNG dependent.", d = "Kill 50 enemy players within your home cities like Stormwind or Orgrimmar, which is best done during PvP open world hours. This is account-wide, making it efficient for groups to split up and farm different zones.", x = 2 },
        [389] = { e = 5, s = "s", r = "Rare drop from Gurubashi Arena boss.", d = "Loot the Arena Master trinket from Gurubashi Arena after defeating the boss that drops it. Ensure you are in the correct arena instance and ready to loot immediately upon victory.", x = 2 },
        [396] = { e = 4, s = "s", r = "Quest chain dependent on rare arena trinket.", d = "Complete Short John Mithril's specific quest chain inside Gurubashi Arena to obtain the Arena Grand Master trinket. This requires finishing a dedicated storyline within the arena environment.", x = 2 },
        [397] = { e = 3, s = "s", r = "Win one ranked match; moderate skill required.", d = "Win a single ranked arena match to unlock this achievement, which serves as the first step in the dedication chain. You must be eligible for ranked arenas and have a team ready to compete.", x = 2 },
        [398] = { e = 4, s = "g", r = "Grind 100 wins; high RNG and skill variance.", d = "Accumulate 100 wins in ranked arena matches after unlocking the previous tier, noting that this is account-wide. Plan your queue times carefully since losing streaks will significantly delay completion.", x = 2 },
        [399] = { e = 4, s = "g", r = "Requires significant arena skill and time to reach rating.", d = "Queue for 2v2 arena matches and aim to climb your personal rating to 1550. This is a time-gated achievement requiring active participation in ranked play.", x = 2 },
        [400] = { e = 5, s = "g", r = "High rating requires extensive grinding and team coordination.", d = "Complete the previous 1550 rating goal first, then continue queuing until you reach 1750 personal rating. Consistent wins are needed to progress through this chain.", x = 2 },
        [401] = { e = 5, s = "g", r = "Very high rating demands top-tier performance and luck.", d = "Finish the 1750 rating tier before attempting this one by reaching a personal rating of 2000 in 2v2. You must maintain your rank without dropping below the threshold.", x = 2 },
        [402] = { e = 4, s = "g", r = "Requires significant arena skill and time to reach rating.", d = "Switch to 3v3 arena queues and focus on climbing to a personal rating of 1550. This bracket is different from 2v2, so adjust your team composition accordingly.", x = 2 },
        [403] = { e = 5, s = "g", r = "High rating requires extensive grinding and team coordination.", d = "After hitting 1550 in 3v3, keep playing ranked matches until your personal rating reaches 1750. Ensure you do not lose too many games or you may need to grind back up.", x = 2 },
        [405] = { e = 5, s = "g", r = "Very high rating demands top-tier performance and luck.", d = "Complete the 1750 rating tier first, then push for a personal rating of 2000 in 3v3 arena. This requires sustained performance over multiple weeks.", x = 2 },
        [408] = { e = 5, s = "g", r = "Winning 10 in a row is extremely difficult due to RNG.", d = "Play ranked matches consecutively without losing ten times in a row to unlock this streak achievement. Any loss resets your counter, so avoid risky fights.", x = 2 },
        [431] = { e = 5, s = "c", r = "Legacy title requires specific raid boss kill (RNG dependent).", d = "This legacy title is earned by defeating the final boss of the original Burning Crusade raid. It is no longer available for new players to obtain.", x = 2 },
        [432] = { e = 5, s = "c", r = "Legacy title requires specific raid boss kill (RNG dependent).", d = "Obtain this title by completing the specific heroic mode requirement in the original Naxxramas raid content. This achievement is locked and cannot be earned now.", x = 2 },
        [433] = { e = 5, s = "c", r = "Legacy PvP title requires extensive arena play at level 60.", d = "Earn this PvP title by reaching a high enough arena rating during your level 60 character's lifetime. It is a legacy achievement that may no longer be active.", x = 2 },
        [434] = { e = 5, s = "c", r = "Legacy PvP title requires extensive arena play at level 60.", d = "Progress through the PvP title chain starting from Grand Marshal to eventually earn Field Marshal at level 60. These are legacy titles tied to old arena systems.", x = 2 },
        [435] = { e = 5, s = "c", r = "Legacy PvP title requires extensive arena play at level 60.", d = "Complete the preceding PvP title requirements and continue climbing arena ratings until you unlock the Commander title. This is part of a discontinued legacy chain.", x = 2 },
        [436] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Earn the Lieutenant Commander PvP title by reaching level 60 and completing the necessary reputation milestones. Focus on gaining Honor through battlegrounds and arenas to unlock this specific rank.", x = 2 },
        [437] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Secure the Knight-Champion title at level 60 by advancing your PvP standing significantly beyond standard ranks. Prioritize high-level arena matches to accelerate reputation gains efficiently.", x = 2 },
        [438] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Obtain the Knight-Captain title once you have progressed far enough in the Honor system at level 60. Consistent participation in rated PvP content is essential for this achievement.", x = 2 },
        [439] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Unlock the Knight title by earning sufficient Honor points while at level 60. Start with lower-level battlegrounds to build your reputation before tackling harder content.", x = 2 },
        [440] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Gain the Sergeant Major title by continuing to climb the PvP ladder after reaching level 60. Avoid long breaks between sessions to maintain your Honor progress.", x = 2 },
        [441] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Achieve the Master Sergeant rank by dedicating time to competitive PvP activities at level 60. This title requires a substantial amount of accumulated Honor points.", x = 2 },
        [442] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Earn the Private title as your first step in the Honor system upon reaching level 60. Simply engage in any PvP activity to begin unlocking these sequential titles.", x = 2 },
        [443] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Secure the High Warlord title by reaching an advanced stage of PvP reputation at level 60. Focus on winning matches and completing weekly PvP objectives for faster progress.", x = 2 },
        [444] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Unlock the Lieutenant General title through extensive PvP participation once you hit level 60. Treat this as a long-term goal requiring consistent engagement in battlegrounds and arenas.", x = 2 },
        [445] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Obtain the Warlord title by continuing to accumulate Honor points well past the initial ranks at level 60. Plan your leveling route to include early access to PvP zones.", x = 2 },
        [446] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Earn the General title as one of the highest honors in the PvP system at level 60. Maintain a high win rate in arenas to maximize your Honor point gains.", x = 2 },
        [447] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Complete the Champion title by reaching the pinnacle of the Honor system after leveling to 60. This final step requires significant dedication to competitive PvP activities.", x = 2 },
        [448] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Earn the Centurion PvP title by reaching level 60 and completing all required PvP milestones. Focus on gaining reputation with relevant factions and winning duels to unlock this specific rank.", x = 2 },
        [449] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Secure the Blood Guard title at level 60 through consistent PvP participation and faction reputation gains. Ensure you are active in battlegrounds or arenas to progress toward this rank efficiently.", x = 2 },
        [450] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Obtain the Senior Sergeant title by advancing your PvP standing after reaching level 60. Prioritize high-level content and maintain a positive combat record to unlock this achievement quickly.", x = 2 },
        [451] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Unlock the Stone Guard title at level 60 by contributing significantly to PvP efforts. Engage in frequent duels and team battles to satisfy the requirements for this rank.", x = 2 },
        [452] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Achieve the First Sergeant title once you are level 60 and have demonstrated sufficient PvP prowess. Continue participating in organized PvP events to reach the necessary milestone without delay.", x = 2 },
        [453] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Earn the Sergeant title at level 60 by actively engaging in player versus player combat. Regular participation in battlegrounds and arenas will help you progress through this rank smoothly.", x = 2 },
        [454] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Gain the Scout title upon reaching level 60 and completing initial PvP objectives. Start with basic duels and gradually take on more challenging content to unlock this achievement.", x = 2 },
        [468] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Secure the Grunt title at level 60 by entering the PvP system for the first time. Participate in any available combat scenarios to meet the basic requirements for this rank.", x = 2 },
        [469] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Unlock the Legionnaire title after reaching level 60 and accumulating enough PvP experience. Focus on winning matches and gaining reputation to advance through the ranks effectively.", x = 2 },
        [470] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Earn the Corporal title at level 60 by consistently performing well in PvP activities. Engage in various combat modes to build the necessary standing for this achievement.", x = 2 },
        [471] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Obtain the Sergeant title again at level 60 through dedicated PvP efforts. This may represent a specific faction or context, so ensure you are targeting the correct requirements.", x = 2 },
        [472] = { e = 1, s = "s", r = "Talk to NPC after reaching level 60.", d = "Achieve the Knight-Lieutenant title by reaching level 60 and excelling in high-level PvP content. Maintain an active presence in competitive modes to unlock this prestigious rank.", x = 2 },
        [473] = { e = 1, s = "s", r = "Talk to NPC for title.", d = "Complete the Marshal questline at level 60 to earn the title. Ensure you finish all prerequisite reputation tasks before reaching the final step.", x = 2 },
        [477] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Defeat Prince Keleseth, Skarvald, Dalronn, and Ingvar in Utgarde Keep. This is account-wide, so coordinate with friends or join a group to clear all bosses.", x = 2 },
        [478] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Clear Grand Magus Telestra, Anomalus, Ormorok, and Keristrasza in The Nexus. Use a full raid group for the hardest mechanics on these Lich King bosses.", x = 2 },
        [479] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Defeat Meathook, Chrono-Lord Epoch, Salramm, and Mal'Ganis in Caverns of Time: Stratholme. This dungeon is account-wide and requires a coordinated group run.", x = 2 },
        [480] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Kill Krik'thir, Hadronox, and Anub'arak in Azjol-Nerub. Bring a strong raid group to handle the complex mechanics of these Naxxramas-style bosses.", x = 2 },
        [481] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Defeat Prince Taldaram, Elder Nadox, Jedoga, and Herald Volazj in Ahn'kahet: The Old Kingdom. Coordinate with your group to clear all four encounters for the account-wide credit.", x = 2 },
        [482] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Clear Trollgore, Novos, King Dred, and Prophet Tharon'ja in Drak'Tharon Keep. Ensure you defeat every boss listed to complete this Lich King achievement.", x = 2 },
        [483] = { e = 4, s = "g", r = "Defeat boss in dungeon instance.", d = "Focus your raid group on defeating Cyanigosa in The Violet Hold. This specific encounter is the only requirement for this particular achievement.", x = 2 },
        [484] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Defeat Slad'ran, Moorabi, Drakkari Colossus, and Gal'darah in Gundrak. Use a full raid group to handle the multiple phases of these bosses.", x = 2 },
        [485] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Clear Maiden of Grief, The Tribunal of Ages, Krystallus, and Sjonnir in Halls of Stone. Coordinate with your party to defeat all four encounters listed.", x = 2 },
        [486] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Defeat General Bjarngrim, Ionar, Volkhan, and Loken in Halls of Lightning. Bring a full raid group to handle the complex mechanics of these bosses.", x = 2 },
        [487] = { e = 4, s = "g", r = "Defeat multiple bosses in dungeon.", d = "Clear Drakos, Mage-Lord Urom, Varos Cloudstrider, and Ley-Guardian Eregos in The Oculus. Ensure you defeat all four bosses for the account-wide credit.", x = 2 },
        [488] = { e = 3, s = "c", r = "Normal mode dungeon clear; moderate group effort.", d = "Start with Normal mode to learn boss mechanics before attempting Heroic. This is a group requirement and cannot be done solo.", x = 2 },
        [489] = { e = 4, s = "c", r = "Heroic dungeon requires skilled group coordination.", d = "Unlock Utgarde Keep first, then queue for Heroic runs. Note that this requires the base dungeon to be completed on Normal mode.", x = 2 },
        [490] = { e = 4, s = "c", r = "Heroic raid content; complex mechanics and RNG.", d = "Complete The Nexus on Normal before switching to Heroic. This is an account-wide achievement requiring a full raid group.", x = 2 },
        [491] = { e = 4, s = "c", r = "Heroic raid clear; requires skilled group play.", d = "Finish Azjol-Nerub on Normal difficulty first. You must defeat all three bosses on Heroic mode to earn the points.", x = 2 },
        [492] = { e = 4, s = "c", r = "Heroic raid clear; complex mechanics and RNG.", d = "Clear Ahn'kahet: The Old Kingdom on Normal before attempting Heroic. Ensure you have a full group for this account-wide task.", x = 2 },
        [493] = { e = 4, s = "c", r = "Heroic raid clear; requires skilled group play.", d = "Complete Drak'Tharon Keep on Normal mode first. Then coordinate with a group to defeat all bosses on Heroic difficulty.", x = 2 },
        [494] = { e = 4, s = "c", r = "Heroic raid boss; complex mechanics and RNG.", d = "Unlock The Violet Hold normally, then focus solely on defeating Cyanigosa on Heroic. This is a specific boss requirement within the dungeon.", x = 2 },
        [495] = { e = 4, s = "c", r = "Heroic dungeon clear; requires skilled group play.", d = "Clear Gundrak on Normal mode before attempting Heroic. You need a full raid group to handle the five bosses on Heroic.", x = 2 },
        [496] = { e = 4, s = "c", r = "Heroic dungeon clear; requires skilled group play.", d = "Complete Halls of Stone on Normal first. Then queue for Heroic runs to defeat all four boss encounters listed in the info.", x = 2 },
        [497] = { e = 4, s = "c", r = "Heroic dungeon clear; requires skilled group play.", d = "Finish Halls of Lightning on Normal mode before switching to Heroic. This requires a full group to handle the four bosses.", x = 2 },
        [498] = { e = 4, s = "c", r = "Heroic raid clear; complex mechanics and RNG.", d = "Clear The Oculus on Normal difficulty first. Then coordinate with a group to defeat all four bosses on Heroic mode.", x = 2 },
        [499] = { e = 5, s = "c", h = { 2186, 2187, 2185 }, r = "Heroic Utgarde Pinnacle; high skill ceiling and RNG.", d = "Complete Utgarde Pinnacle on Normal before attempting Heroic. This account-wide achievement requires defeating all four bosses on the higher difficulty.", x = 2 },
        [500] = { e = 4, s = "c", h = { 5743, 5745, 5742 }, r = "Heroic Stratholme requires a full raid group and multiple boss kills.", d = "Queue for Heroic Stratholme with a group to defeat all four bosses listed in the info field. This is account-wide and requires clearing the entire dungeon, so ensure your party composition covers all roles before starting.", x = 2 },
        [503] = { e = 1, s = "g", r = "Trivial; any quest counts toward the total.", d = "Start by accepting any available quest from nearby NPCs or daily quests; simply turn them in to build toward the 50 total. There are no time gates, but avoid repeating the same quest line if it has a limited number of copies.", x = 2 },
        [504] = { e = 2, s = "g", r = "Easy grind of standard quests once started.", d = "Since this requires completing 50 quests first, finish that achievement immediately before starting here. Treat it as a milestone by grinding daily quests and world quests to reach the next threshold quickly.", x = 2 },
        [505] = { e = 3, s = "g", r = "Moderate time investment to reach 250 quests.", d = "Continue accepting random world quests and dailies after hitting 100; do not stop until you hit 250. This is account-wide, so coordinate with friends if you want to speed up progress by sharing quest rewards.", x = 2 },
        [506] = { e = 4, s = "g", r = "Long grind requiring hundreds of quests over time.", d = "Grind through daily quests and world events to reach 500 completions. Avoid missing rare drop quests or time-gated content that might reset your count if you fail to complete them within the window.", x = 2 },
        [507] = { e = 4, s = "g", r = "Significant grind to reach 1000 quest completions.", d = "Focus on high-yield quest hubs like Stormwind, Orgrimmar, or Dalaran to efficiently reach 1000 total. Remember this is account-wide, so playing multiple characters can help if you are stuck on a specific zone.", x = 2 },
        [508] = { e = 5, s = "g", r = "Very hard; requires massive time investment or alt farming.", d = "Keep accepting any available quests until you hit 1500; prioritize daily quests for efficiency. There are no missable mechanics here, but be mindful of quest chains that require specific items or NPCs to progress.", x = 2 },
        [509] = { e = 4, s = "g", r = "Long grind for PvP kills, often requiring specific zones.", d = "Queue for PvP battlegrounds or arenas and aim for honorable kills without killing the enemy player first. This is account-wide, so playing on a server with active PvP scenes will speed up progress significantly.", x = 2 },
        [512] = { e = 3, s = "g", r = "Moderate grind; achievable with consistent PvP activity.", d = "Start by farming battlegrounds or dueling grounds to reach 1000 honorable kills first. Avoid accidental dishonorable kills by not attacking players who are already dead or using stealth attacks that count as dishonor.", x = 2 },
        [513] = { e = 2, s = "g", r = "Easy start for PvP players or those in contested zones.", d = "Begin with simple PvP activities like arena matches or battlegrounds; ensure you kill enemy players honorably before they die to other enemies. This is account-wide, so playing on a PvP-heavy server helps reach 100 quickly.", x = 2 },
        [515] = { e = 3, s = "g", r = "Moderate effort; requires sustained PvP participation.", d = "Continue farming honorable kills in battlegrounds or arenas after reaching 100. Watch out for accidental dishonorable kills that could reset your progress if you kill an enemy player who was already dead or used stealth attacks.", x = 2 },
        [516] = { e = 4, s = "g", r = "Hard grind; needs significant time in PvP environments.", d = "Grind through PvP content to reach 5000 honorable kills; avoid accidental dishonorable kills by not attacking players who are already dead. This is account-wide, so playing on a server with active PvP scenes will help you progress faster.", x = 2 },
        [518] = { e = 4, s = "g", r = "Grinding reputation to Exalted on 30 factions is a long-term task.", d = "Start by farming any available faction grinds while leveling or completing daily quests, as these are account-wide and stack across characters. Focus on factions with high rep gain rates like the Valiance Expedition or Dragonmaw Clan to speed up progress. Avoid waiting for specific events unless necessary, as grinding daily quests is usually the most efficient path.", x = 2 },
        [519] = { e = 4, s = "g", r = "Grinding reputation to Exalted on 25 factions is a long-term task.", d = "Since this requires 20 Exalted first, focus on completing the previous tier achievements before attempting this one. Farming daily quests and world bosses will quickly fill the remaining slots needed to reach the goal. Remember that reputation gains are account-wide, so you can switch characters freely to maximize efficiency.", x = 2 },
        [520] = { e = 4, s = "g", r = "Grinding reputation to Exalted on 20 factions is a long-term task.", d = "Begin by raising 15 reputations to Exalted using daily quests or faction-specific activities like dungeon runs. Once you have enough progress, continue grinding until you reach the next milestone of 20 Exalted. Be mindful that some factions may take longer to complete, so prioritize those with faster rep gain rates.", x = 2 },
        [521] = { e = 4, s = "g", r = "Grinding reputation to Exalted on 15 factions is a long-term task.", d = "Start by raising 10 reputations to Exalted through daily quests or faction-specific activities like dungeon runs. Once you have enough progress, continue grinding until you reach the next milestone of 15 Exalted. Be mindful that some factions may take longer to complete, so prioritize those with faster rep gain rates.", x = 2 },
        [522] = { e = 3, s = "c", h = { 78162, 78200, 78216 }, r = "Requires visiting specific factions; some are rare spawns or difficult.", d = "Visit any major city's reputation vendor or quest giver to start raising your first faction to Exalted. Focus on factions like Silvermoon or Valiance Expedition since they offer consistent daily gains and are accessible early in the game. Avoid missing out on rare drops by checking world events, as some factions require specific conditions to unlock.", x = 2 },
        [523] = { e = 4, s = "g", r = "Grinding reputation to Exalted on 5 factions is a long-term task.", d = "After completing the initial reputation grind, focus on raising five additional factions to Exalted using daily quests or faction-specific activities. Prioritize factions with high rep gain rates like the Valiance Expedition or Dragonmaw Clan to speed up progress. Remember that reputation gains are account-wide, so you can switch characters freely to maximize efficiency.", x = 2 },
        [524] = { e = 4, s = "g", r = "Grinding reputation to Exalted on 10 factions is a long-term task.", d = "Start by raising 10 reputations to Exalted using daily quests or faction-specific activities like dungeon runs. Once you have enough progress, continue grinding until you reach the next milestone of 15 Exalted. Be mindful that some factions may take longer to complete, so prioritize those with faster rep gain rates.", x = 2 },
        [545] = { e = 1, s = "s", r = "Visit any barber shop; trivial and takes minutes.", d = "Visit any barber shop in a major city like Stormwind or Orgrimmar to alter your appearance and complete this achievement. This is a simple task that can be done immediately upon creating a new character or visiting a barber for the first time. No special items or quests are required, so just head to the nearest barber shop.", x = 2 },
        [546] = { e = 2, s = "g", r = "Buying bank slots is easy but requires paying gold repeatedly.", d = "Purchase seven additional bank slots from any bank vendor in your capital city using gold. This achievement is account-wide and does not require specific items or quests, making it a quick task to complete. Ensure you have enough gold before attempting this, as each slot costs a significant amount.", x = 2 },
        [547] = { e = 3, s = "s", r = "Complete a specific quest chain in Dragonblight; moderate time.", d = "Complete the Dragonblight quests leading up to and including the Return to Angrathar to earn this achievement. Start by accepting the initial quest in Dragonblight and follow the chain until you reach the final objective. Be aware that some quests may require specific conditions or items, so check your quest log carefully.", x = 2 },
        [556] = { e = 4, s = "c", r = "Requires high-level gear; effort depends on character level and loot.", d = "Equip an epic item in every slot with a minimum item level of 213 before Battle for Azeroth to complete this achievement. Focus on acquiring high-level gear from raids or dungeons, as these are the primary sources of epic items. Avoid using lower-tier gear, as it will not count toward the achievement.", x = 2 },
        [557] = { e = 3, s = "c", r = "Requires superior items; moderate grind for gear acquisition.", d = "Equip a superior item in every slot with a minimum item level of 187 before Battle for Azeroth to complete this achievement. Focus on acquiring high-level gear from raids or dungeons, as these are the primary sources of superior items. Avoid using lower-tier gear, as it will not count toward the achievement.", x = 2 },
        [558] = { e = 3, s = "g", r = "Requires many kills and RNG luck.", d = "Roll for a superior item above level 185 and ensure your roll hits exactly 100 to win. This requires finding high-level loot drops where you can greed, so be ready to act quickly when the opportunity arises.", x = 2 },
        [559] = { e = 3, s = "g", r = "Requires many kills and RNG luck.", d = "Win a need roll on an item better than what you currently have by rolling 100. Look for rare drops from bosses or world events where the item quality exceeds your current gear.", x = 2 },
        [560] = { e = 4, s = "g", r = "Rare spawn in a difficult raid.", d = "Fish up Gahz'ranka in Zul'Gurub using the Mudskunk Lure, which is a rare drop from specific fish. This content is time-gated and requires fishing skill to complete successfully.", x = 2 },
        [561] = { e = 3, s = "c", r = "Quest chain completion.", d = "Complete all quests for D.E.H.T.A's Little P.I.T.A., including the Assassination of Harold Lane. Since this is account-wide, ensure your character finishes every step before the quest chain expires or becomes unavailable.", x = 2 },
        [562] = { e = 4, s = "c", h = { 1083, 1085, 1084 }, r = "Hard raid bosses in 10-man mode.", d = "Defeat Anub'Rekhan, Grand Widow Faerlina, and Maexxna in 10-player Naxxramas to claim this achievement. Coordinate with a group familiar with these bosses to minimize wipes and save time.", x = 2 },
        [563] = { e = 4, s = "c", h = { 1431, 1432, 1433 }, r = "Hard raid bosses in 25-man mode.", d = "Clear the Arachnid Quarter bosses in 25-player mode for this account-wide achievement. Ensure your raid composition is optimized for the specific mechanics of Anub'Rekhan, Grand Widow Faerlina, and Maexxna.", x = 2 },
        [564] = { e = 4, s = "c", h = { 5751, 5754, 5752 }, r = "Hard raid bosses in 10-man mode.", d = "Defeat Patchwerk, Grobbulus, Gluth, and Thaddius in 10-player Naxxramas. These bosses require precise positioning and cooldown management, so practice their mechanics before attempting the achievement.", x = 2 },
        [565] = { e = 4, s = "c", h = { 3084, 3085, 3086 }, r = "Hard raid bosses in 25-man mode.", d = "Clear the Construct Quarter in 25-player mode by defeating Patchwerk, Grobbulus, Gluth, and Thaddius. This is account-wide, so coordinate with a large group to handle the complex mechanics efficiently.", x = 2 },
        [566] = { e = 4, s = "c", h = { 8195, 8193, 8194 }, r = "Hard raid bosses in 10-man mode.", d = "Defeat Noth the Plaguebringer, Heigan the Unclean, and Loatheb in 10-player Naxxramas. Be prepared for intense mechanics like the purple mist and the Four Horsemen phase to avoid wipes.", x = 2 },
        [567] = { e = 4, s = "c", h = { 3371, 3373, 3372 }, r = "Hard raid bosses in 25-man mode.", d = "Clear the Plague Quarter in 25-player mode by defeating Noth, Heigan, and Loatheb. Ensure your raid has enough healers and damage dealers to handle the high difficulty of these encounters.", x = 2 },
        [568] = { e = 4, s = "c", h = { 3205, 3206, 3207 }, r = "Hard raid bosses in 10-man mode.", d = "Defeat Instructor Razuvious, Gothik the Harvester, and The Four Horsemen in 10-player Naxxramas. Focus on avoiding the purple mist and managing the Four Horsemen's adds carefully.", x = 2 },
        [569] = { e = 4, s = "c", h = { 5807, 5808, 5809 }, r = "Hard raid bosses in 25-man mode.", d = "Clear the Military Quarter in 25-player mode by defeating Razuvious, Gothik, and The Four Horsemen. Coordinate your raid to handle the complex mechanics of each boss without wasting time.", x = 2 },
        [572] = { e = 5, s = "s", r = "Requires high-level raid group and boss kill.", d = "Queue for Naxxramas with a full 10-man group to defeat Sapphiron. Ensure your healer and DPS are ready for his ice breath mechanics.", x = 2 },
        [573] = { e = 5, s = "s", r = "Requires high-level raid group and boss kill.", d = "Gather a full 25-player raid to enter Naxxramas and kill Sapphiron. This requires coordinating with other guilds or using the dungeon finder if available.", x = 2 },
        [574] = { e = 5, s = "s", r = "Requires high-level raid group and boss kill.", d = "Run Naxxramas in 10-player mode until you defeat Kel'Thuzad. Be prepared for his final phase and avoid standing near him during the summoning.", x = 2 },
        [575] = { e = 5, s = "s", r = "Requires high-level raid group and boss kill.", d = "Assemble a large 25-player raid to clear Naxxramas and kill Kel'Thuzad. Coordinate with other groups if you cannot find enough players alone.", x = 2 },
        [576] = { e = 4, s = "c", h = { 14879, 14877 }, r = "Requires killing all bosses; final two are hardest.", d = "Clear every boss in Naxxramas using a 10-player group to earn this account-wide achievement. You must defeat all bosses listed in the info field.", x = 2 },
        [577] = { e = 4, s = "c", h = { 8750, 8749 }, r = "Requires killing all bosses; final two are hardest.", d = "Defeat all Naxxramas bosses with a full 25-player raid. This is a significant undertaking that may require multiple runs or group coordination.", x = 2 },
