        [579] = { e = 4, s = "c", r = "Requires clearing raid with large group limits.", d = "Run Naxxramas with fewer than 21 players while defeating all bosses listed in the info field. Do not fill your group beyond this limit.", x = 2 },
        [582] = { e = 3, s = "c", h = { 82718, 82720 }, r = "Requires completing multiple objectives in one match.", d = "Play a single Alterac Valley match where you assault and defend both graveyards, towers, and kill someone in the Field of Strife. Focus on objectives to complete all tasks quickly.", x = 0 },
        [583] = { e = 3, s = "c", h = { 79682, 79683 }, r = "Requires completing multiple objectives in one match.", d = "In one Arathi Basin match, assault and defend two bases for each faction. Coordinate with your team to secure both objectives efficiently.", x = 2 },
        [584] = { e = 3, s = "c", h = { 79544, 79552 }, r = "Requires getting kills at all five bases.", d = "Get five honorable kills at each of the five bases in a single Arathi Basin battle. Spread out across the map to cover all locations.", x = 2 },
        [587] = { e = 3, s = "c", h = { 4062, 4063 }, r = "Requires getting kills at all four bases.", d = "Play Eye of the Storm and secure five honorable kills at each of the four bases in one match. Focus on objective control while farming kills.", x = 0 },
        [603] = { e = 4, s = "g", r = "Requires killing 20 players across multiple cities.", d = "This is a PvP achievement requiring you to kill five Alliance players in each listed city. Start by queuing for battlegrounds or finding groups near these zones, as solo attempts are risky and time-gated by the need for multiple kills per location.", x = 2 },
        [604] = { e = 4, s = "g", r = "Requires killing 20 players across multiple cities.", d = "Similar to the previous task, this requires killing five Horde players in specific cities. You must coordinate with friends or join PvP groups to safely eliminate targets without getting killed yourself before reaching the kill count.", x = 2 },
        [605] = { e = 1, s = "s", r = "Single event item drop or quest reward.", d = "You need to receive a Coin of Ancestry during the Lunar Festival event. Check your mailbox or vendor for these items, as they are often missable if the festival ends before you collect enough.", x = 2 },
        [606] = { e = 2, s = "g", r = "Collecting 5 items is a short grind.", d = "Collect five Coins of Ancestry first, then repeat this process until you have ten total. Since these coins are account-wide and tied to a seasonal event, ensure you check your inventory regularly during the festival window.", x = 2 },
        [607] = { e = 3, s = "g", r = "Collecting 10 items takes moderate time.", d = "Gather ten Coins of Ancestry before moving to the next tier. These items drop from specific vendors or events, so monitor the Lunar Festival duration closely to avoid missing out on future opportunities.", x = 2 },
        [608] = { e = 4, s = "g", r = "Collecting 25 items is a longer grind.", d = "Accumulate twenty-five Coins of Ancestry by participating in festival activities. This step is part of a chain, so prioritize collecting coins early while the event is active to prevent time-gating issues.", x = 2 },
        [609] = { e = 3, s = "s", r = "Single fight against a specific NPC.", d = "Receive fifty Coins of Ancestry to complete this stage. As this is the final tier in the chain, make sure you have collected all previous coins and that the festival has not ended prematurely.", x = 2 },
        [610] = { e = 4, s = "s", r = "Single fight against a high-level boss.", d = "Damage High Overlord Saurfang until he pretends to die, which is a PvP interaction. This may require waiting for specific conditions or engaging him in Orgrimmar during designated times when he is vulnerable.", x = 0 },
        [611] = { e = 4, s = "s", r = "Single fight against a high-level boss.", d = "Kill Baine Bloodhoof as part of the Legacy PvP achievements. Ensure you are in the correct zone and that no other objectives interfere with your ability to reach and defeat this target.", x = 0 },
        [612] = { e = 5, s = "s", r = "Killing Sylvanas is extremely difficult now.", d = "Defeat Lady Sylvanas Windrunner in Orgrimmar to claim this achievement. Be prepared for high-level PvP encounters, as she is a formidable opponent that may require strategic positioning or group assistance.", x = 2 },
        [613] = { e = 4, s = "s", r = "Single fight against a high-level NPC.", d = "Kill Lor'themar Theron to complete this PvP objective. This target is located in Quel'Thalas, so plan your route carefully and be ready for potential ambushes from other players or NPCs.", x = 1 },
        [614] = { e = 5, s = "c", h = { 89028 }, r = "Killing Orgrimmar leader is the hardest task.", d = "Slay the leaders of the Horde by completing related achievements like 'Killed in Quel'Thalas' and others. This account-wide achievement rewards a mount, so prioritize finishing all prerequisite tasks before the event expires.", x = 2 },
        [615] = { e = 3, s = "s", r = "Requires specific PvP kill; moderate difficulty.", d = "This is a PvP achievement requiring you to kill King Anduin Wrynn. You must engage him in combat and defeat him before he reaches zero health or escapes.", x = 2 },
