        [617] = { e = 3, s = "s", r = "Single high-level PvP kill; moderate difficulty.", d = "Defeat High Priestess Tyrande Whisperwind in a PvP setting. Ensure you have sufficient gear and group support to handle her abilities during the encounter.", x = 0 },
        [618] = { e = 4, s = "s", r = "Requires specific rare drop or event.", d = "Slay Prophet Velen as part of your PvP goals. Coordinate with friends or use battlegrounds to find opportunities to engage this target.", x = 1 },
        [619] = { e = 5, s = "c", h = { 2964 }, r = "Multiple high-level kills including rare drops.", d = "Complete the previous three achievements by slaying all Alliance leaders to earn the Black War Bear mount. This is account-wide and rewards you once all targets are defeated.", x = 2 },
