        [700] = { e = 3, s = "s", r = "Obtaining a rare PvP item requires significant play.", d = "Obtain an Insignia or Medallion of the Horde by participating in PvP activities or purchasing them from vendors. This is a legacy achievement that tracks items obtained across your entire account history.", x = 2 },
        [701] = { e = 3, s = "s", r = "Obtaining a rare PvP item requires significant play.", d = "Obtain an Insignia or Medallion of the Alliance through PvP participation or vendor purchases to complete this legacy achievement. Like the Horde version, this tracks items collected across your entire account.", x = 2 },
        [705] = { e = 4, s = "c", h = { 6562 }, r = "Grinding weapon skills to max is a long task.", d = "Raise four different weapon skills to level 400 by repeatedly hitting targets with those specific weapons. You can use training dummies or practice weapons in the world to efficiently increase your skill levels.", x = 2 },
        [706] = { e = 3, s = "s", r = "Requires obtaining a rare PvP mount or item.", d = "Obtain a Frostwolf Howler mount by completing Alterac Valley objectives or purchasing it from vendors. This is an account-wide achievement, so any character on your account can earn the item for everyone.", x = 2 },
        [707] = { e = 3, s = "s", r = "Requires obtaining a rare PvP mount or item.", d = "Obtain a Stormpike Battle Charger mount through Alterac Valley activities or vendor purchases to complete this account-wide achievement. Ensure you check all available sources as mounts may drop from specific events.", x = 2 },
        [708] = { e = 4, s = "g", r = "Requires exalted rep grind in PvP faction.", d = "Grind Alterac Valley daily quests and battlegrounds to gain Frostwolf reputation. Focus on completing faction-specific objectives for maximum rep gains per week.", x = 2 },
        [709] = { e = 4, s = "g", r = "Requires exalted rep grind in PvP faction.", d = "Complete Stormpike Guard daily quests in Alterac Valley and participate in the battleground frequently. This is account-wide, so use a high-level character to speed up progress.", x = 2 },
        [710] = { e = 4, s = "g", r = "Requires exalted rep grind in PvP faction.", d = "Farm Arathi Basin battlegrounds and complete The Forsaken Defilers dailies for reputation points. Consistent participation is key as this is account-wide.", x = 2 },
        [711] = { e = 4, s = "g", r = "Requires exalted rep grind in PvP faction.", d = "Join League of Arathor dailies in Arathi Basin and queue for the battleground often. Ensure you are at a high level to maximize rep gains efficiently.", x = 2 },
        [712] = { e = 4, s = "g", r = "Requires exalted rep grind in PvP faction.", d = "Complete Warsong Outriders dailies in Warsong Gulch and play the battleground regularly. This account-wide achievement requires consistent daily completion.", x = 2 },
        [713] = { e = 4, s = "g", r = "Requires exalted rep grind in PvP faction.", d = "Farm Silverwing Sentinels reputation through Warsong Gulch dailies and battleground participation. Consistency is crucial as this is an account-wide goal.", x = 2 },
        [714] = { e = 5, s = "c", r = "Combines three massive exalted reputation grinds.", d = "Complete all three faction-specific achievements listed above to unlock The Conqueror title. Ensure you have exalted reputation in all three battlegrounds before claiming the reward.", x = 2 },
        [726] = { e = 3, s = "g", r = "Requires fishing specific rare crawdad repeatedly.", d = "Fish in various locations across Azeroth until you obtain Mr. Pinchy's Magical Crawdad Box. Check your mail regularly as this item may take time to drop.", x = 2 },
        [727] = { e = 4, s = "c", h = { 4160 }, r = "Requires obtaining multiple rare war mounts.", d = "Purchase any available war mount from the honor vendor using your accumulated honor points. This is account-wide, so one character can unlock the achievement for all others.", x = 2 },
        [728] = { e = 3, s = "g", r = "Requires leveling three professions to max skill.", d = "Travel to Durotar and visit every unexplored zone to reveal the map. Use a high-level character with good exploration tools to speed up this process.", x = 0 },
        [730] = { e = 3, s = "g", r = "Requires leveling three professions to high skill points.", d = "Grind skill points in Fishing, First Aid, and Cooking until you reach Grand Master in each. This requires significant time investment but has no missable components or group requirements. Focus on high-yield activities like fishing near capital cities to speed up progress.", x = 2 },
        [731] = { e = 3, s = "g", r = "Requires leveling a primary profession to high skill.", d = "Level up a primary profession like Blacksmithing or Mining until you reach 225 skill points. Focus on one classic category profession to avoid wasting time leveling multiple ones.", x = 2 },
        [732] = { e = 1, s = "g", r = "Grinding profession skill points is fast and solo.", d = "Continue leveling your chosen classic profession from the previous achievement until reaching 300 skill points. Ensure you have completed the Professional Expert requirement first.", x = 2 },
        [733] = { e = 1, s = "g", r = "Grinding Outland skill points is fast and solo.", d = "Grind your primary profession to level 75 in Outland zones like Hellfire Peninsula. This is a solo task that requires no specific group, but be patient as it takes significant time to accumulate enough skill points.", x = 2 },
        [734] = { e = 1, s = "g", r = "Grinding Northrend skill points is fast and solo.", d = "Repeat the process from the previous achievement by reaching 75 skill points in your primary profession within Northrend zones. Since this is account-wide, you can switch characters or use alts to speed up progress if needed.", x = 2 },
        [735] = { e = 2, s = "c", r = "Requires two professions but both are easy grinds.", d = "Complete both the Outland and Northrend master achievements first, then focus on gaining 75 skill points in two different primary professions in Northrend. Ensure you have completed the prerequisite 'Professional Northrend Master' before starting this one.", x = 2 },
        [736] = { e = 1, s = "g", r = "Exploring Mulgore is a short solo zone run.", d = "Travel to Mulgore and explore every covered area on the map, including specific locations like Red Cloud Mesa and Palemane Rock. This is account-wide, so any character can contribute, but ensure you visit all spots to avoid missing content.", x = 0 },
        [750] = { e = 1, s = "g", r = "Exploring Northern Barrens is a short solo zone run.", d = "Head to The Barrens and uncover all hidden areas such as Boulder Lode Mine and Ratchet. Like other exploration achievements, this is account-wide, so use multiple characters or travel efficiently to reveal every spot.", x = 0 },
        [761] = { e = 1, s = "g", r = "Exploring Arathi Highlands is a short solo zone run.", d = "Explore Arathi Highlands by visiting key locations like Circle of West Binding and Stromgarde Keep. This achievement is account-wide, meaning any character can help complete it, but ensure you cover all listed areas.", x = 0 },
        [762] = { e = 4, s = "c", h = { 4157, 4153, 4155 }, r = "Exalted Horde rep requires massive time or gold grinding.", d = "Earn Exalted reputation with all six Horde factions, including Bilgewater Cartel and Thunder Bluff. This requires significant time investment and may involve completing quests or turning in items to gain enough reputation points.", x = 2 },
        [763] = { e = 4, s = "c", h = { 8081, 8079, 8082 }, r = "Exalted dungeon rep requires heavy grinding or gold.", d = "Raise all The Burning Crusade dungeon reputations to Exalted, starting with Thrallmar and Cenarion Expedition. Note that some factions have multiple sub-factions, so ensure you complete all required steps for each.", x = 1 },
        [764] = { e = 4, s = "c", h = { 4224, 4226, 4228 }, r = "Exalted dungeon rep requires heavy grinding or gold.", d = "Similar to the previous achievement, raise all The Burning Crusade dungeon reputations to Exalted, including Honor Hold and Keepers of Time. This is account-wide, so coordinate with friends or use alts to speed up progress.", x = 1 },
        [765] = { e = 1, s = "g", r = "Exploring Badlands is a short solo zone run.", d = "Explore Badlands by visiting locations like Uldaman and Camp Cagg. This is account-wide, so you can use any character to complete it, but ensure you visit every covered area on the map.", x = 0 },
        [766] = { e = 1, s = "g", r = "Exploring Blasted Lands is a short solo zone run.", d = "Travel to Blasted Lands and explore areas such as Dreadmaul Hold and The Dark Portal. This achievement is account-wide, so feel free to use multiple characters or alts to uncover all hidden spots efficiently.", x = 0 },
        [768] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Explore Tirisfal Glades by visiting locations like Deathknell and Brill. This is account-wide, so you can complete it with any character, but ensure you visit every covered area to avoid missing content.", x = 0 },
        [769] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Travel to Silverpine Forest and clear all zones including Shadowfang Keep. This is account-wide, so level up your main character first before visiting other realms.", x = 0 },
        [770] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Visit Western Plaguelands and complete the main questline to reveal the map. Ensure you visit every subzone like Andorhal and Caer Darrow.", x = 0 },
        [771] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Explore Eastern Plaguelands by visiting Light's Hope Chapel and surrounding areas. This achievement is account-wide, so coordinate with friends if needed.", x = 0 },
        [772] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Travel to Hillsbrad Foothills and visit locations like Durnholde Keep. Clear all zones to reveal the map for this account-wide achievement.", x = 0 },
        [773] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Head to The Hinterlands and explore areas like Aerie Peak and Shadra'Alor. Complete any necessary quests to unlock the full map region.", x = 0 },
        [774] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Visit Searing Gorge and clear zones such as Blackrock Mountain. This account-wide achievement requires visiting every named location in the zone.", x = 0 },
        [775] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Explore Burning Steppes by visiting Blackrock Stronghold and other key points. Ensure you have cleared all subzones to complete this account-wide goal.", x = 0 },
        [776] = { e = 1, s = "c", r = "Very small zone, quick walk.", d = "Travel to Elwynn Forest and visit locations like Goldshire and Eastvale Logging Camp. Clear the area to reveal the map for this achievement.", x = 0 },
        [777] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Visit Deadwind Pass and explore areas around Karazhan. This account-wide achievement requires visiting every named location in the zone.", x = 0 },
        [778] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Explore Duskwood by visiting Darkshire and surrounding areas like Raven Hill. Clear all zones to reveal the map for this account-wide goal.", x = 0 },
        [779] = { e = 2, s = "c", r = "Walk through zone to reveal points.", d = "Travel to Loch Modan and visit locations like Stonewrought Dam and Mo'grosh Stronghold. Ensure you have cleared all subzones to complete this achievement.", x = 0 },
        [780] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Visit Redridge Mountains and explore areas like Lakeshire and Camp Everstill. Clear the area to reveal the map for this account-wide goal.", x = 0 },
        [781] = { e = 3, s = "g", r = "Explore large zone with some difficult areas.", d = "Travel to Grom'gol Base Camp and clear all zones in Northern Stranglethorn. You must visit every named location listed in the info field to reveal the map. This is account-wide, so ensure your character explores thoroughly before logging out.", x = 0 },
        [782] = { e = 2, s = "g", r = "Walk through swamp to reveal map points.", d = "Head to Misty Valley and explore Swamp of Sorrows by visiting every marked point of interest. Clear all zones and visit ruins or camps listed in the info to fully reveal the map. This achievement is account-wide, so do not miss any locations.", x = 0 },
        [783] = { e = 4, s = "c", r = "Requires winning specific high-score PvP match.", d = "Play Eye of the Storm matches until you win with a score between 1500 and 1600 points. Aim for a dominant performance to secure the victory needed for this specific milestone. This is account-wide, so any qualifying win counts toward your progress.", x = 0 },
        [784] = { e = 5, s = "g", r = "Grind requires many wins under strict conditions.", d = "Win Eye of the Storm ten times while simultaneously holding all four bases on the map. Focus on controlling key points early in each match to maintain dominance throughout the game. This is account-wide, so track your total wins across all characters.", x = 0 },
        [802] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Start at Sentinel Hill and explore Westfall by visiting every location listed in the info field. Clear all zones and ensure you visit farms, mines, and villages to reveal the map. This is account-wide, so make sure no area remains unexplored.", x = 0 },
        [841] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Begin at Menethil Harbor and explore Wetlands by visiting every marked point of interest. Clear all zones and visit ruins or camps listed in the info to fully reveal the map. This is account-wide, so ensure you cover every location before finishing.", x = 0 },
        [842] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Travel to Shadowglen and explore Teldrassil by visiting every named location in the info field. Clear all zones and visit villages or glades listed to reveal the map. This is account-wide, so do not miss any locations on the tree.", x = 0 },
        [843] = { e = 3, s = "g", r = "Explore large zone with some difficult areas.", d = "Head to Area 52 and explore Netherstorm by visiting every marked point of interest. Clear all zones and visit ruins or holds listed in the info to fully reveal the map. This is account-wide, so ensure you cover every location before finishing.", x = 1 },
        [844] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Start at Ruins of Auberdine and explore Darkshore by visiting every location listed in the info field. Clear all zones and visit ruins or camps to reveal the map. This is account-wide, so make sure no area remains unexplored.", x = 0 },
        [845] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Travel to The Zoram Strand and explore Ashenvale by visiting every marked point of interest. Clear all zones and visit villages or posts listed in the info to fully reveal the map. This is account-wide, so ensure you cover every location before finishing.", x = 0 },
        [846] = { e = 2, s = "g", r = "Walk through zone to reveal map points.", d = "Begin at The Great Lift and explore Thousand Needles by visiting every named location in the info field. Clear all zones and visit ruins or holds listed to reveal the map. This is account-wide, so do not miss any locations in the zone.", x = 0 },
        [847] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Head to Battlescar Valley and explore Stonetalon Mountains by visiting every marked point of interest. Clear all zones and visit ruins or posts listed in the info to fully reveal the map. This is account-wide, so ensure you cover every location before finishing.", x = 0 },
        [848] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Explore Desolace by visiting all listed locations like Tethris Aran and Nijel's Point. This is an account-wide exploration achievement with no time gate, so simply travel the zone thoroughly.", x = 0 },
        [849] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Visit every marked spot in Feralas such as Dire Maul and Camp Mojache to reveal the map. Since this is account-wide, ensure your character has been there before logging out.", x = 0 },
        [850] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Travel to all locations in Dustwallow Marsh including Theramore Isle and Brackenwall Village. This achievement requires full zone exploration and is tracked account-wide.", x = 0 },
        [851] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Explore Tanaris by visiting key sites like Gadgetzan and Zul'Farrak. Walk the entire zone to reveal all covered areas on your world map.", x = 0 },
        [852] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Visit every location in Azshara from Bilgewater Harbor to Ravencrest Monument. Ensure you have visited each spot while logged into the game to count for the account-wide total.", x = 0 },
        [853] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Explore Felwood by checking off spots like Felpaw Village and Jaedenar. This is a straightforward exploration task with no special requirements beyond visiting the areas.", x = 0 },
        [854] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Visit all locations in Un'Goro Crater including Fire Plume Ridge and Lakkari Tar Pits. Simply traverse the zone to reveal the map sections for your account.", x = 0 },
        [855] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Explore Moonglade by visiting Lake Elune'ara and Stormrage Barrow Dens. This is a small zone achievement that requires you to walk through every part of the area.", x = 0 },
        [856] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Visit every location in Silithus such as Hive'Regal and The Crystal Vale. Ensure you have been to each spot while logged in to complete this account-wide goal.", x = 0 },
        [857] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Explore Winterspring by visiting spots like Frostfire Hot Springs and Winterfall Village. Walk the entire zone to reveal all covered areas for your account.", x = 0 },
        [858] = { e = 2, s = "c", r = "Walk around zone to reveal map points.", d = "Visit all locations in Ghostlands including Tranquillien and Howling Ziggurat. This achievement requires you to explore the entire zone while logged into the game.", x = 0 },
        [859] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Explore Eversong Woods by visiting Silvermoon City and Sunsail Anchorage. Make sure to visit every marked location in this Burning Crusade zone for your account.", x = 0 },
        [860] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Travel to Azuremyst Isle and visit every named location on the map to reveal fogged areas. This is account-wide, so any character can complete it for everyone.", x = 0 },
        [861] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Visit all points of interest in Bloodmyst Isle, including ruins and camps, to clear the map. Ensure you check hard-to-reach spots like high cliffs or dense woods.", x = 0 },
        [862] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Explore Hellfire Peninsula by visiting every zone marker, from outposts to major cities. Be mindful of time gates that may block access to certain areas early on.", x = 1 },
        [863] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Walk through Zangarmarsh and mark all locations like villages and ruins. Some areas are water-based, so use a flying mount or swim to reach them efficiently.", x = 1 },
        [864] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Visit every named location in Shadowmoon Valley, including the Black Temple and Netherwing Ledge. This zone is account-wide, so progress carries over between characters.", x = 1 },
        [865] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Explore Blade's Edge Mountains by visiting all camps, lairs, and villages. Use a flying mount to quickly access high-altitude areas that are often missed.", x = 1 },
        [866] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Travel across Nagrand and visit every point of interest, including the Ring of Trials and various forge camps. Flying is highly recommended for efficiency here.", x = 1 },
        [867] = { e = 3, s = "g", r = "Grinding map markers across multiple zones.", d = "Visit all locations in Terokkar Forest, including Shattrath City and both factions' strongholds. This zone is account-wide, so one character can complete it for all.", x = 1 },
        [868] = { e = 2, s = "s", r = "Visit Isle of Quel'Danas once.", d = "Explore Isle of Quel'Danas by visiting every named location on the island. This is a quick task if you have already visited the area with another character.", x = 0 },
        [869] = { e = 4, s = "g", r = "Grinding PvP kills over many days.", d = "Accumulate 50,000 honorable kills in PvP battles like Warsong Gulch or Arathi Basin. This progress is account-wide and stacks across all your characters.", x = 2 },
        [870] = { e = 5, s = "g", r = "Requires massive grind or title unlock.", d = "Reach 100,000 honorable kills to earn a title. Continue fighting in PvP after completing the previous achievement; this also unlocks the next tier at 250,000.", x = 2 },
        [872] = { e = 3, s = "s", r = "Requires winning a specific PVP match with multiple flags.", d = "In Warsong Gulch, return five enemy flags during a single match to complete this objective. Coordinate with your team to secure flag returns quickly.", x = 0 },
        [873] = { e = 4, s = "s", r = "Winning AV perfectly is difficult but achievable solo.", d = "Focus on holding your towers and protecting your captain at all costs during Alterac Valley. Do not engage in unnecessary fights that could cause a tower loss, as this fails the achievement immediately.", x = 0 },
        [875] = { e = 3, s = "g", r = "Grinding 200 arena wins takes time but scales linearly.", d = "Queue for ranked arena matches until you reach 200 wins to unlock this title. This is account-wide, so ensure your main character or any alt on the account contributes to the total count.", x = 2 },
        [876] = { e = 3, s = "g", r = "Grinding 300 arena wins takes time but scales linearly.", d = "Continue winning ranked arena matches after unlocking the previous tier to reach 300 total wins. You will receive a tabard reward upon completion of this specific milestone.", x = 2 },
        [877] = { e = 2, s = "s", r = "Baking a cake is quick once the recipe is known.", d = "Cook the Delicious Chocolate Cake recipe in your cooking profession to complete this task. Ensure you have the correct ingredients and skill level before attempting to bake it.", x = 2 },
        [878] = { e = 3, s = "g", r = "Catching rare fish requires time and luck but scales.", d = "Fish in various zones until you catch one of the listed rare fish, such as the Steelscale Crushfish or 103 Pound Mightfish. These drops are random, so be prepared to fish extensively across different locations.", x = 2 },
        [889] = { e = 1, s = "s", r = "Buying a mount is trivial if you have gold.", d = "Purchase the Journeyman Riding skill from a trainer to unlock this achievement. This is often required before you can buy higher-level riding skills in later expansions.", x = 2 },
        [890] = { e = 2, s = "s", r = "Learning expert riding is quick once the prerequisite is met.", d = "Learn the Expert Riding skill from a trainer after completing the previous riding tier. This step is necessary to progress toward flying mounts in Azeroth.", x = 2 },
        [892] = { e = 1, s = "s", r = "Buying an artisan mount is trivial if you have gold.", d = "Buy the Artisan Riding skill from a trainer to complete this legacy character achievement. Note that this does not grant flight but is part of the riding progression chain.", x = 2 },
        [893] = { e = 4, s = "g", r = "Getting the hippogryph requires finding a specific rare mob.", d = "Travel to Zangarmarsh and locate the Cenarion Expedition to obtain the Cenarion War Hippogryph mount. This mount is account-wide, so any character can use it once acquired.", x = 1 },
        [894] = { e = 3, s = "g", r = "Reaching exalted reputation takes time and grinding quests.", d = "Complete quests for the Sha'tari Skyguard in Nagrand until you reach Exalted reputation. Once exalted, claim your flying mount reward to finish this achievement.", x = 1 },
        [896] = { e = 3, s = "g", r = "Reaching exalted reputation takes time and grinding quests.", d = "Quest through Ogri'la in Zangarmarsh to earn Exalted status with the local ogre faction. This reputation grind is account-wide and unlocks a specific flying mount.", x = 1 },
        [897] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Complete quests for the Shattered Sun Offensive in Nagrand until you reach Exalted reputation. This achievement is account-wide, allowing any character on your account to benefit from the resulting rewards.", x = 1 },
        [898] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Grind Netherwing reputation daily quests until you reach Exalted, as this is account-wide and requires consistent effort over time. Avoid missing the weekly reset timers to speed up progress significantly.", x = 1 },
        [899] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Focus on completing Kurenai daily quests in Shattrath City to earn reputation efficiently toward Exalted status. This achievement is account-wide, so ensure your main character completes the tasks first.", x = 1 },
        [900] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Farm Sporeggar reputation through daily quests and world drops in Nagrand until you hit Exalted. Be patient as this faction often requires significant grinding time.", x = 1 },
        [901] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Complete Mag'har daily quests in Durotar to gain reputation points needed for Exalted status. This is account-wide, so prioritize it early if you plan to play Horde characters later.", x = 1 },
        [902] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Grind Consortium reputation via daily quests in Shattrath City until reaching Exalted. Note that this faction has strict time gates based on weekly resets.", x = 1 },
        [903] = { e = 4, s = "g", r = "Grinding reputation to Exalted takes many hours.", d = "Choose either The Scryers or The Aldor in Shattrath and grind their respective daily quests to Exalted. You only need one faction, so pick the one with easier quest availability.", x = 1 },
        [905] = { e = 2, s = "c", h = { 6325, 6326, 6327 }, r = "Daily quests are easy but require multiple steps.", d = "Complete all five of Old Man Barlo's fishing dailies in Stormwind Harbor, ensuring you turn them in before the weekly reset. These quests are account-wide and may require specific rare fish drops.", x = 2 },
        [906] = { e = 2, s = "c", h = { 4840, 4841, 4838 }, r = "Daily quests are easy but require multiple steps.", d = "Finish The Rokk's four cooking daily quests in Orgrimmar or Thunder Bluff, turning them in promptly to avoid missing the weekly timer. This is account-wide and requires specific recipes.", x = 2 },
        [907] = { e = 5, s = "g", r = "Requires massive PvP grind to Exalted in all factions.", d = "Grind Warsong Gulch, Arathi Basin, and Alterac Valley battlegrounds to Exalted reputation with each faction. This takes a long time due to high rep requirements per battleground.", x = 2 },
        [908] = { e = 4, s = "g", r = "Grinding 100 BGs is a long-term time sink.", d = "Play 100 max-level battlegrounds of any type to complete this achievement quickly. It is account-wide, so use alts if available or queue consistently as the main character.", x = 2 },
        [909] = { e = 4, s = "g", r = "Grinding 100 BGs is a long-term time sink.", d = "Duplicate the process for the second 'Call to Arms!' entry by completing another 100 max-level battlegrounds. Ensure your characters are at the correct level before starting.", x = 2 },
        [910] = { e = 2, s = "c", r = "Visit 13 dungeon elders; trivial once inside.", d = "Visit each dungeon listed in the info field and use the Lunar Festival honor mechanic on the specific Elder NPCs inside. This is time-gated to the festival event window only.", x = 2 },
        [911] = { e = 2, s = "c", r = "Visit ~18 Kalimdor elders; trivial once found.", d = "Start this during the Lunar Festival event to access all Elders. Travel across Kalimdor zones like Razor Hill and Azshara, checking each Elder's location in the info list. Do not miss any as they are account-wide but time-gated by the event.", x = 2 },
        [912] = { e = 2, s = "c", r = "Visit ~18 Eastern Kingdoms elders; trivial.", d = "Complete this alongside Elders of Kalimdor while the Lunar Festival is active. Visit Eastern Kingdoms zones such as Goldshire and Zul'Gurub to honor every Elder listed. Ensure you finish all before the event ends since they are account-wide.", x = 2 },
        [913] = { e = 4, s = "c", h = { 4953 }, r = "Requires all sub-achievements; Elders of Cataclysm hardest.", d = "This is a collection achievement requiring all other Lunar Festival tasks plus specific quests like Elune's Blessing. Prioritize completing the Elders of Kalimdor and Eastern Kingdoms first, then handle the remaining sub-achievements.", x = 2 },
        [914] = { e = 1, s = "c", r = "Visit 3 capital city elders; very easy.", d = "Honor the three Horde capital city Elders located in Orgrimmar, Thunder Bluff, and Undercity. This is straightforward if you visit these cities during the Lunar Festival event window.", x = 2 },
        [915] = { e = 1, s = "c", r = "Visit 3 capital city elders; very easy.", d = "Visit Darnassus, Ironforge, and Stormwind to honor the Alliance capital city Elders. Complete this quickly during the Lunar Festival as it is account-wide and time-sensitive.", x = 2 },
        [937] = { e = 2, s = "s", r = "Defeat Omen in a single event; easy.", d = "Defeat Omen to complete Elune's Blessing, which grants a title and points. This quest is part of the main Lunar Festival requirements and must be done during the event.", x = 2 },
        [938] = { e = 3, s = "g", r = "Complete Hemet quests chain in Northrend.", d = "Follow Hemet Nesingwary's quests in Northrend up to Post-partum Aggression for this achievement. Start early as these are long chains that may expire or become harder later.", x = 2 },
        [939] = { e = 2, s = "g", r = "Complete Hemet quests chain in Nagrand.", d = "Complete all of Hemet's Nagrand quests ending with The Ultimate Bloodsport. These are account-wide and should be done while the content is available in Outland.", x = 1 },
        [940] = { e = 2, s = "g", r = "Complete Hemet quests chain in Stranglethorn.", d = "Finish Stranglethorn Vale quests for Hemet up to Big Game Hunter. This is an account-wide achievement so ensure you do not miss any steps in the chain.", x = 0 },
        [941] = { e = 3, s = "c", r = "Requires completing three other quest chains.", d = "Collect this by completing the three specific regional quest chains listed in the info. Start these early as they are account-wide and depend on Hemet's availability.", x = 2 },
        [942] = { e = 4, s = "g", r = "Grinding reputation to Exalted is time-consuming.", d = "Grind reputation with Timbermaw Hold, Sporeggar, and Kurenai from Unfriendly to Exalted. Use world quests or daily activities in Pandaria for efficient gains before the title expires.", x = 2 },
        [943] = { e = 4, s = "g", r = "Grinding 126k rep across three factions is a long task.", d = "Gain Exalted reputation with Timbermaw Hold, Sporeggar, and The Mag'har. Focus on Pandaria content like world quests to speed up this account-wide title requirement.", x = 2 },
        [944] = { e = 4, s = "g", r = "Grinding 42k rep alone is a significant time investment.", d = "Start by completing Timbermaw Hold quests in Eastern Plaguelands to reach Exalted quickly. This is a Classic-only achievement, so ensure you are playing on the correct server version.", x = 0 },
        [945] = { e = 4, s = "g", r = "Grinding 84k rep across two factions requires many hours.", d = "Grind reputation with both the Argent Dawn and Argent Crusade until you hit Exalted for each faction separately. Be patient as this requires significant time investment across multiple zones and dungeons.", x = 2 },
        [946] = { e = 4, s = "g", r = "Grinding 42k rep is a substantial solo grind.", d = "Focus your efforts entirely on earning Exalted status with the Argent Dawn in Eastern Plaguelands. This is a Classic achievement, so do not confuse it with the combined version.", x = 0 },
        [947] = { e = 4, s = "g", r = "Grinding 42k rep in WotLK content takes many hours.", d = "Complete quests and run dungeons in Northrend to earn Exalted status specifically with the Argent Crusade. Since this is Wrath of the Lich King content, ensure you are on the appropriate expansion server.", x = 2 },
        [948] = { e = 4, s = "g", r = "Grinding 252k rep across six factions is a massive task.", d = "Grind reputation with all six Alliance factions until reaching Exalted with each one individually. This will take a long time due to the high reputation requirements for every faction.", x = 2 },
        [949] = { e = 4, s = "g", r = "Grinding 42k rep with Kalu'ak is a long grind.", d = "Travel to Sholazar Basin in Pandaria and complete quests for The Kalu'ak to earn Exalted status. This is a Wrath of the Lich King achievement, so verify your server expansion level first.", x = 2 },
        [950] = { e = 4, s = "g", r = "Grinding 42k rep with Frenzyheart Tribe takes time.", d = "Complete quests in Sholazar Basin specifically for the Frenzyheart Tribe to reach Exalted status. Focus on local activities and avoid wasting time on other factions in the zone.", x = 2 },
        [951] = { e = 4, s = "g", r = "Grinding 42k rep with The Oracles is a long task.", d = "Earn Exalted status with The Oracles by completing their specific quest chain in Sholazar Basin. This is part of the Wrath of the Lich King reputation system, so check your server expansion.", x = 2 },
        [952] = { e = 4, s = "g", r = "Grinding 84k rep across two factions is very time-consuming.", d = "You must earn Exalted status with both The Oracles and the Frenzyheart Tribe to complete this achievement. Start by grinding one faction first before moving to the other in Sholazar Basin.", x = 2 },
        [953] = { e = 4, s = "g", r = "Grinding 84k rep across two Cenarion factions takes hours.", d = "Grind reputation with both the Cenarion Circle and Cenarion Expedition until reaching Exalted for each. This requires extensive time investment across multiple zones and is a major long-term goal.", x = 2 },
        [955] = { e = 4, s = "g", r = "Grinding 42k rep with Hydraxian Waterlords is a long task.", d = "Complete quests in Stranglethorn Vale to earn Exalted status with the Hydraxian Waterlords. This is a Classic achievement, so ensure you are playing on the correct server version.", x = 0 },
        [956] = { e = 4, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Grind reputation in Outland with the Brood of Nozdormu until reaching Exalted status. This is a Classic achievement, so verify you are on the appropriate server expansion before starting.", x = 0 },
        [957] = { e = 4, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Grind daily quests in Zandalar until exalted. This is account-wide so any character can finish it for everyone.", x = 2 },
        [958] = { e = 4, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Farm the Ashtongue Deathsworn in Ashran or via dailies to reach Exalted quickly.", x = 1 },
        [959] = { e = 4, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Complete daily quests for The Scale of the Sands in Nazjatar until you hit Exalted.", x = 1 },
        [960] = { e = 4, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Grind dailies in Suramar to earn Exalted with The Violet Eye as soon as possible.", x = 1 },
        [961] = { e = 3, s = "c", r = "Requires completing 8 specific daily quests.", d = "Do the eight specific Frenzyheart daily quests every day until they are all completed.", x = 2 },
        [962] = { e = 3, s = "c", r = "Requires completing 8 specific daily quests.", d = "Complete the eight Oracles dailies in Northrend; ensure you finish each one before resetting.", x = 2 },
        [963] = { e = 1, s = "c", r = "Simple visit to scattered candy buckets.", d = "Visit every Candy Bucket location listed for Kalimdor during Hallow's End event.", x = 2 },
        [964] = { e = 2, s = "s", r = "Single jump from a high place without dying.", d = "Jump off cliffs or use fall damage mechanics to drop 65 yards without taking fatal damage.", x = 2 },
        [965] = { e = 1, s = "c", r = "Simple visit to scattered candy buckets.", d = "Visit all Candy Buckets in Kalimdor during Hallow's End; check the full list for every zone.", x = 2 },
        [966] = { e = 1, s = "c", r = "Simple visit to scattered candy buckets.", d = "Travel to Eastern Kingdoms and visit every Candy Bucket location listed for this region.", x = 2 },
        [967] = { e = 1, s = "c", r = "Simple visit to scattered candy buckets.", d = "Visit all remaining Candy Buckets in Eastern Kingdoms during Hallow's End to finish the set.", x = 2 },
        [968] = { e = 1, s = "c", r = "Visit 12 locations; trivial walk-through.", d = "Go to Outland and visit every Candy Bucket location listed for that zone during the event.", x = 2 },
        [969] = { e = 1, s = "c", r = "Visit 14 locations; trivial walk-through.", d = "Visit every Candy Bucket location in Outland during Hallow's End. This is time-gated to the event window and requires you to physically travel to each zone listed in the info field.", x = 2 },
        [971] = { e = 2, s = "c", r = "Requires three sub-achievements to finish.", d = "First complete the individual Tricks and Treats achievements for Eastern Kingdoms, Kalimdor, and Outland. Once all three are done, this account-wide achievement will automatically unlock.", x = 2 },
        [972] = { e = 1, s = "s", r = "Single event interaction; very fast.", d = "Travel to any inn during Hallow's End and interact with the Candy Bucket NPC. You must receive treats from at least one bucket to complete this specific objective.", x = 2 },
        [973] = { e = 4, s = "g", r = "Grinding 5 daily quests takes days.", d = "Start by accepting daily quests immediately upon logging in each day. This is a cumulative account-wide counter that resets daily, so consistency is key to progress.", x = 2 },
        [974] = { e = 4, s = "g", r = "Grinding 50 dailies requires significant time.", d = "This requires you to first finish the 5 Daily Quests Completed achievement. Continue accepting and finishing dailies every day until your total quest count reaches fifty.", x = 2 },
        [975] = { e = 4, s = "g", r = "Grinding 200 dailies is a long task.", d = "Unlock this by completing the 50 Daily Quests milestone. Keep grinding daily quests across all zones to reach the two hundred quest total required here.", x = 2 },
        [976] = { e = 5, s = "g", r = "Grinding 500 dailies takes many days.", d = "Prerequisite is finishing the 200 Daily Quests achievement. Maintain a strict daily routine of accepting and completing quests until you hit the five hundred mark.", x = 2 },
        [977] = { e = 5, s = "g", r = "Grinding 1000 dailies is a massive grind.", d = "Requires the 500 Daily Quests Completed achievement first. This is a long-term goal requiring hundreds of days of consistent daily quest completion across all available zones.", x = 2 },
        [978] = { e = 4, s = "g", r = "3000 quests total requires long-term play.", d = "Unlock this after reaching 2000 total quests completed. It rewards the title The Seeker and requires you to finish a massive volume of any quest type over time.", x = 2 },
        [979] = { e = 1, s = "s", r = "Single event interaction; very fast.", d = "Obtain a Mask item during the Hallow's End event period. This is time-gated content; if you miss the event window, you cannot complete this achievement without waiting for it to return.", x = 2 },
        [981] = { e = 1, s = "s", r = "Single item use; trivial action.", d = "Use a Tooth Pick item while standing near a Candy Bucket during Hallow's End. Ensure you have the item in your inventory and interact with the bucket to trigger the sparkle effect.", x = 2 },
        [1005] = { e = 2, s = "c", r = "Kill one of each race; trivial in PvP zones.", d = "Defeat an honorable killing blow against every single Alliance race listed in the info field. This is account-wide and time-gated to PvP availability for those specific races.", x = 2 },
        [1006] = { e = 3, s = "g", r = "Grind 50 kills in cities; easy but requires time.", d = "Kill enemy players in your home cities, focusing on PvP zones like Stormwind or Orgrimmar to reach 50 kills quickly. Avoid accidental deaths by staying near friendly NPCs and using defensive abilities when possible.", x = 2 },
        [1007] = { e = 4, s = "g", r = "Exalted with faction takes significant grinding.", d = "Grind daily quests and world events in Northrend to earn Exalted with The Wyrmrest Accord efficiently. This faction is account-wide, so progress carries over across characters.", x = 2 },
        [1008] = { e = 4, s = "g", r = "Exalted with Kirin Tor requires substantial effort.", d = "Complete Kirin Tor daily quests and turn in reputation items to reach Exalted status quickly. Focus on zones like Dalaran or Northrend for consistent gains.", x = 2 },
        [1009] = { e = 4, s = "g", r = "Exalted with Ebon Blade is a long grind.", d = "Join the Ebon Blade faction by completing their daily quests and turning in reputation items in Northrend. This is account-wide, so share progress with other characters if needed.", x = 2 },
        [1010] = { e = 5, s = "c", h = { 7010 }, r = "Requires exalted with four factions; very hard checklist.", d = "Grind all four factions to Exalted before unlocking this achievement, as it requires a total of 42,000 reputation per faction. Start with Argent Crusade and Wyrmrest Accord for faster progress.", x = 2 },
        [1011] = { e = 4, s = "g", r = "Exalted with Horde Expedition is a long grind.", d = "Earn Exalted with the Horde Expedition by completing their daily quests and turning in reputation items in Northrend. This is account-wide, so progress carries over across characters.", x = 2 },
        [1012] = { e = 4, s = "g", r = "Exalted with Alliance Vanguard is a long grind.", d = "Grind daily quests and world events in Northrend to earn Exalted with the Alliance Vanguard efficiently. Focus on zones like Dalaran or Northrend for consistent gains.", x = 2 },
        [1014] = { e = 5, s = "c", r = "Requires 35 exalted reps; massive cumulative effort.", d = "Raise 35 reputations to Exalted by grinding daily quests, world events, and turning in reputation items. Start with factions you already have high standing with to save time.", x = 2 },
        [1015] = { e = 5, s = "c", r = "Requires 40 exalted reps; massive cumulative effort.", d = "Continue raising additional reputations to Exalted after reaching 35 for this achievement. Focus on factions you haven't completed yet to reach the total of 40 efficiently.", x = 2 },
        [1017] = { e = 1, s = "s", r = "Obtain any pet; trivial and instant.", d = "Obtain any companion pet by catching wild pets, purchasing from vendors, or completing quests. This is account-wide, so progress carries over across characters.", x = 2 },
        [1020] = { e = 3, s = "c", h = { 60637 }, r = "Collect 10 tabards; moderate effort via crafting/buying.", d = "Unlock 10 tabard slot appearances by earning them through achievements, world events, and vendor purchases. Focus on factions you already have high standing with to save time.", x = 2 },
        [1021] = { e = 1, s = "g", r = "Collecting 25 tabards is trivial once unlocked.", d = "Unlock additional tabard slot appearances after reaching 10 for this achievement. Focus on factions you haven't completed yet to reach the total of 25 efficiently.", x = 2 },
        [1022] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Visit every zone listed in the info field to find and interact with the flame objects. Since this is account-wide, you can do these tasks on any character, but ensure you cover all required zones before moving on.", x = 2 },
        [1023] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Travel across Kalimdor zones to honor the flames as indicated in the info list. This task is account-wide, so use a level-appropriate character to efficiently clear each zone without missing any locations.", x = 2 },
        [1024] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Honor the flames in Outland by visiting all zones specified in the info data. As this is account-wide, you may complete these on any character once you have access to Outland content.", x = 1 },
        [1025] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Desecrate the Horde's bonfires across Eastern Kingdoms by visiting each zone in the info list. This is account-wide, so feel free to use any character to complete the tasks efficiently.", x = 2 },
        [1026] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Desecrate the Horde's bonfires in Kalimdor zones listed in the info field. Since this is account-wide, you can tackle these on any character once you have reached the appropriate level for each zone.", x = 2 },
        [1027] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Desecrate the Horde's bonfires in Outland by visiting all zones mentioned in the info data. This is account-wide, allowing you to use any character to complete the tasks after unlocking Outland.", x = 1 },
        [1028] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Desecrate the Alliance's bonfires in Eastern Kingdoms by visiting each zone in the info list. This is account-wide, so you can complete these on any character once you have access to the zones.", x = 2 },
        [1029] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Desecrate the Alliance's bonfires in Kalimdor by visiting all zones specified in the info field. As this is account-wide, use any character to efficiently clear each zone without missing locations.", x = 2 },
        [1030] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Desecrate the Alliance's bonfires in Outland by visiting all zones listed in the info data. This is account-wide, so you can complete these on any character once you have access to Outland content.", x = 2 },
        [1031] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Honor the flames of Eastern Kingdoms by visiting each zone in the info list. Since this is account-wide, you can use any character to complete these tasks efficiently across all zones.", x = 2 },
        [1032] = { e = 3, s = "c", r = "Visit many zones; easy but requires travel time.", d = "Honor the flames of Kalimdor by visiting all zones specified in the info field. This is account-wide, so feel free to use any character to clear each zone without missing any locations.", x = 2 },
        [1033] = { e = 4, s = "c", r = "Grind across all Outland zones to desecrate bonfires.", d = "Honor the flames of Outland by visiting all zones mentioned in the info data. As this is account-wide, you can complete these on any character once you have unlocked Outland content.", x = 2 },
        [1034] = { e = 4, s = "c", r = "Complete multiple Flame Warden achievements across regions.", d = "Complete the five Flame Warden achievements for each region and expansion listed in the info field to earn this title. Since these are account-wide, ensure all characters on your account contribute or wait until one character finishes them first. There is no time gate, but you must finish all sub-achievements before claiming the main reward.", x = 2 },
        [1035] = { e = 4, s = "c", r = "Grind all Extinguishing achievements across all zones.", d = "Finish every Extinguishing achievement across all zones and expansions as specified in the required list. This task is account-wide, so coordinate with friends or wait for a character to complete the set first. No specific time limit exists, but ensure you do not miss any regional sub-goals.", x = 2 },
        [1036] = { e = 4, s = "c", r = "Complete multiple Flame Keeper achievements across regions.", d = "Complete all Flame Keeper achievements for each region and expansion detailed in the info field. These are account-wide requirements, so one character can finish them for everyone on your account. There is no time gate, but verify you have completed every single sub-achievement before claiming the reward.", x = 2 },
        [1037] = { e = 4, s = "c", r = "Grind all Extinguishing achievements across all zones.", d = "Finish all Extinguishing achievements for the Alliance side as listed in the required info field. This is an account-wide task, so one character can complete it for your entire account. No time gate applies, but ensure you do not miss any regional sub-goals before claiming the reward.", x = 2 },
        [1038] = { e = 5, s = "c", h = { 29044, 29042 }, r = "Requires completing multiple complex seasonal event achievements.", d = "Complete all six Midsummer achievements listed in the info field to earn the Flame Warden title and 20 points. These include seasonal events like Ice the Frost Lord and Burning Hot Pole Dance, which may be time-gated if you miss the event window. Coordinate with friends or wait for a character to finish them first since they are account-wide.", x = 2 },
        [1039] = { e = 5, s = "c", h = { 29048, 29046 }, r = "Requires completing multiple complex seasonal event achievements.", d = "Finish all six Midsummer achievements listed in the info field to earn the Flame Keeper title and 20 points. These include seasonal events like Ice the Frost Lord and Burning Hot Pole Dance, which may be time-gated if you miss the event window. Coordinate with friends or wait for a character to finish them first since they are account-wide.", x = 2 },
        [1040] = { e = 4, s = "c", r = "Grind quests for both factions during Hallow's End.", d = "Complete the four Hallow's End quests listed in the info field to ruin the Horde celebration and foil their attempts. This is an account-wide task, so one character can complete it for your entire account. Be aware that Hallow's End is a seasonal event with a strict time window.", x = 2 },
        [1041] = { e = 4, s = "c", r = "Grind quests for both factions during Hallow's End.", d = "Complete the four Hallow's End quests listed in the info field to ruin the Alliance celebration and foil their attempts. This is an account-wide task, so one character can complete it for your entire account. Be aware that Hallow's End is a seasonal event with a strict time window.", x = 2 },
        [1145] = { e = 3, s = "s", r = "Single quest objective with specific mechanics.", d = "Complete the quest A Thief's Reward by stealing flames from enemy capital cities as described in the info field. This achievement is account-wide, so one character can finish it for your entire account. Ensure you target the correct capitals during the Midsummer event to avoid missing the opportunity.", x = 2 },
        [1151] = { e = 3, s = "g", r = "Kill 50 players in a specific AV location.", d = "Kill 50 enemy players inside the Hall of the Stormpike during Alterac Valley battles as specified in the info field. This is an account-wide task, so one character can complete it for your entire account. You must participate in multiple AV matches to accumulate enough kills.", x = 0 },
        [1153] = { e = 2, s = "s", r = "Defend 3 bases in one Arathi Basin match.", d = "Defend three bases within a single Arathi Basin battle as required by the info field. This is an account-wide task, so one character can complete it for your entire account. Focus on holding the central base or rotating between all three to meet the requirement efficiently.", x = 2 },
        [1157] = { e = 2, s = "s", r = "Find a duelist and win once.", d = "Win a duel against another player as stated in the info field to earn this achievement. This is an account-wide task, so one character can complete it for your entire account. You can find duels via the PvP menu or by challenging other players directly.", x = 2 },
        [1159] = { e = 3, s = "g", r = "Grind arena matches to reach 2200 rating.", d = "Queue for 2v2 arena matches and climb the rating ladder until you hit 2200 personal rating. This is a grind requiring consistent wins; do not stop if you drop below the threshold.", x = 2 },
        [1160] = { e = 3, s = "g", r = "Grind arena matches to reach 2200 rating.", d = "Join 3v3 arena queues and focus on winning matches to increase your personal rating to 2200. Ensure your team composition synergizes well for faster progression.", x = 2 },
        [1162] = { e = 4, s = "g", r = "Win 10 ranked matches in a row.", d = "Play ranked arena matches without losing a single game while maintaining a rating above 1800. A loss resets the streak, so be prepared for tough matches.", x = 2 },
        [1164] = { e = 3, s = "c", h = { 82730, 82732 }, r = "Win AV with both mines controlled.", d = "Queue for Alterac Valley and prioritize capturing both mines early to maintain control throughout the match. Winning with both mines secured is mandatory.", x = 0 },
        [1165] = { e = 1, s = "s", r = "Equip a specific bag item.", d = "Purchase or obtain Haris Pilton's Gigantique Bag from a vendor or auction house, then equip it in your character's bag slot. This item is account-wide.", x = 2 },
        [1166] = { e = 3, s = "g", r = "Loot a rare drop in Alterac Valley.", d = "Play Alterac Valley and ensure your team kills the NPC Tigule to loot his autographed picture. Coordinate with teammates to secure this specific drop.", x = 0 },
        [1167] = { e = 4, s = "c", h = { 29080, 29084 }, r = "Complete multiple difficult AV objectives.", d = "Complete all listed Alterac Valley sub-achievements before unlocking this one. Review each prerequisite achievement to ensure none are missed during gameplay.", x = 2 },
        [1169] = { e = 4, s = "c", h = { 4419, 4420 }, r = "Complete multiple difficult AB objectives.", d = "Finish every Arathi Basin sub-achievement listed in the requirements. Some involve specific objectives like defending or capturing flags, so play diverse roles.", x = 2 },
        [1171] = { e = 4, s = "c", h = { 5645, 5643 }, r = "Complete multiple difficult Eye of the Storm objectives.", d = "Complete all Warsong Gulch sub-achievements, including unique ones like Ironman which requires playing solo. Plan your strategy accordingly for each task.", x = 2 },
        [1172] = { e = 4, s = "c", h = { 1419, 1421 }, r = "Complete multiple difficult Warsong Gulch objectives.", d = "Complete every listed Warsong Gulch sub-achievement before the arena mode changes or server resets occur. Some sub-tasks like 'Ironman' require specific playstyles that may conflict with others. Check each sub-achievement status regularly to ensure none are missed during your runs.", x = 2 },
        [1174] = { e = 5, s = "c", h = { 1053, 1050 }, r = "Requires completing all prior arena grinds.", d = "Finish all arena-related achievements listed in the description to unlock this Legacy title. Start with lower rating brackets and work your way up.", x = 2 },
        [1175] = { e = 4, s = "c", h = { 1061, 1058, 1062 }, r = "Requires completing multiple difficult battleground achievements.", d = "Unlock every battleground master achievement first, including Alterac Valley, Arathi Basin, Warsong Gulch, and Eye of the Storm. This is a long-term goal requiring extensive PvP experience.", x = 2 },
        [1176] = { e = 1, s = "g", r = "Looting gold is trivial and scales linearly.", d = "Start by looting any gold from mobs or vendors until you reach 100 total. This is the first step in a long chain, so keep farming efficiently without stopping for other tasks.", x = 2 },
        [1177] = { e = 1, s = "g", r = "Requires more loot but still very easy to get.", d = "Once you finish the previous tier, continue looting gold to hit 1,000 total. Since this requires the prior achievement, ensure you have completed it before attempting this one.", x = 2 },
        [1178] = { e = 1, s = "g", r = "Looting gold is trivial and scales linearly.", d = "Proceed to loot 5,000 gold after unlocking the earlier tiers. Farming high-level mobs or selling crafted items will help you reach this threshold faster.", x = 2 },
        [1180] = { e = 1, s = "g", r = "Looting gold is trivial and scales linearly.", d = "After reaching 25k gold, focus on looting an additional 10,000 gold. This step is part of a cumulative chain, so track your total carefully to avoid missing the next tier.", x = 2 },
        [1181] = { e = 1, s = "g", r = "Looting gold is trivial and scales linearly.", d = "Continue the gold-looting chain by accumulating 25,000 gold total. High-level content or selling rare drops will speed up progress significantly at this stage.", x = 2 },
        [1182] = { e = 3, s = "g", r = "Requires earning a specific amount from quests over time.", d = "Complete quests specifically for their reward gold to reach 10,000 from quest rewards. Avoid counting loot from mobs or vendors, as only quest rewards count toward this achievement.", x = 2 },
        [1183] = { e = 2, s = "c", r = "Sampling event beers is easy but requires visiting multiple spots.", d = "Participate in Brewfest and sample all 12 featured beers listed in the info field. Do not drink them all at once; acquire each one to ensure you meet the requirement.", x = 2 },
        [1184] = { e = 2, s = "c", r = "Collecting specific event items is straightforward.", d = "During Brewfest, collect every beer listed in the achievement description without drinking them immediately. Keep a list of acquired beers to avoid missing any rare or event-specific brews.", x = 2 },
        [1185] = { e = 3, s = "c", r = "Requires eating multiple specific foods during an event.", d = "Participate in Brewfest events and eat 8 of the specific food items listed. These foods are often sold at festival stands, so check vendors regularly during the event.", x = 2 },
        [1186] = { e = 4, s = "s", r = "Defending a camp is a single, time-consuming event.", d = "Defend the Brewfest camp against Dark Iron dwarves and complete the associated quest. This is a time-gated event, so only attempt it when Brewfest is active in your region.", x = 2 },
        [1188] = { e = 3, s = "g", r = "Requires shooting multiple players with a specific item.", d = "Use the Silver Shafted Arrow during Love is in the Air events to shoot 10 players. Ensure you have enough arrows and target other players carefully to avoid wasting shots.", x = 2 },
        [1189] = { e = 3, s = "c", r = "Multiple storylines across Hellfire Peninsula.", d = "Complete all listed Hellfire Peninsula storylines for your faction. Check the quest log for specific objectives like 'Disrupt the Burning Legion' and ensure you finish each one before moving on.", x = 1 },
        [1190] = { e = 3, s = "c", r = "Multiple storylines across Zangarmarsh.", d = "Complete all Zangarmarsh quests first to unlock the zone's full story. Do not skip any sub-quests as they are required for this account-wide achievement.", x = 1 },
        [1191] = { e = 3, s = "c", r = "Multiple storylines across Terokkar Forest.", d = "Focus on Terokkar Forest quests specifically for the Alliance faction. Ensure you complete every listed storyline before moving to other zones.", x = 1 },
        [1192] = { e = 3, s = "c", r = "Multiple storylines across Nagrand.", d = "Finish all Nagrand storylines available to the Alliance. These quests often involve specific NPCs and locations within the zone.", x = 1 },
        [1193] = { e = 3, s = "c", r = "Multiple storylines across Blade's Edge Mountains.", d = "Complete every quest in Blade's Edge Mountains regardless of faction. Some objectives may require visiting multiple zones or defeating specific bosses.", x = 1 },
        [1194] = { e = 3, s = "c", r = "Multiple storylines across Netherstorm.", d = "Clear all Netherstorm quests including the Consortium and Violet Tower storylines. Be prepared for high-level content and potential time gates.", x = 1 },
        [1195] = { e = 3, s = "c", r = "Multiple storylines across Shadowmoon Valley.", d = "Finish Shadowmoon Valley quests like Akama's Promise and The Dark Conclave. Some of these require specific items or rare drops.", x = 1 },
        [1203] = { e = 2, s = "g", r = "Collecting specific beers during Brewfest.", d = "Attend Brewfest events to collect all unique beers listed. Do not drink them immediately as you need to acquire each one separately.", x = 2 },
        [1206] = { e = 3, s = "g", r = "Finding and showing love to many critters.", d = "Use the /love command on every critter species listed across Azeroth. This includes common animals and rare creatures found in various zones.", x = 0 },
        [1225] = { e = 3, s = "g", r = "Fishing at specific nodes in Outland.", d = "Fish at each specific node listed to catch a fish from that school. Visit different fishing spots to ensure you cover all required nodes.", x = 1 },
        [1243] = { e = 1, s = "s", r = "Learning a single fishing ability.", d = "Learn the Fishing skill and any relevant abilities to find fish. This usually involves reaching a certain skill level or completing specific training quests.", x = 2 },
        [1244] = { e = 3, s = "c", r = "Reading many books in the library.", d = "Read every book listed in the original version available in-game. These books are often found in libraries or as quest rewards.", x = 2 },
        [1248] = { e = 3, s = "g", r = "Requires collecting 25 unique pets via various methods.", d = "Collect exactly 25 unique pets by defeating bosses, completing quests, or trading with other players. Avoid duplicates to maximize your progress efficiently.", x = 2 },
        [1250] = { e = 3, s = "g", r = "Requires collecting 50 unique pets, extending the grind.", d = "Farm rare pet dailies and complete the Lil' Game Hunter quest chain to unlock Stinker. This is account-wide, so coordinate with friends to speed up collection.", x = 2 },
        [1251] = { e = 4, s = "s", r = "Highly RNG dependent on flag carrier spawns and timing.", d = "Queue for Warsong Gulch immediately after the flag spawns and rush the enemy flag room. Focus on killing two carriers before they exit; this requires high burst damage.", x = 0 },
        [1252] = { e = 3, s = "g", r = "Requires killing 100 flag carriers in WSG over time.", d = "Grind Warsong Gulch repeatedly, prioritizing kills on flag carriers over other objectives. This is account-wide, so any character can contribute to the total count.", x = 0 },
        [1254] = { e = 4, s = "s", r = "Extremely RNG dependent on turkey spawn rates and timing.", d = "Farm turkeys in Northrend during Winter Veil or similar events, using a fast kill method like area-of-effect spells. You must complete this within a strict three-minute window.", x = 2 },
        [1255] = { e = 3, s = "s", r = "Time-gated event requiring specific holiday participation.", d = "Participate in Feast of Winter Veil and wait for Muradin Bronzebeard to appear. Throw a snowball at him quickly before the event ends or he despawns.", x = 2 },
        [1257] = { e = 3, s = "g", r = "Requires fishing in multiple specific junk nodes across zones.", d = "Fish specifically in wreck nodes like Steam Pump Flotsam and Bloodsail Wreckage. This is account-wide, so fish with any character once you locate these spots.", x = 2 },
        [1258] = { e = 4, s = "s", r = "RNG dependent on enemy buffs and AoE mechanics.", d = "Play Eye of the Storm and look for opponents glowing with the Berserker buff. Kill them quickly before they finish their power-up duration.", x = 0 },
        [1259] = { e = 4, s = "s", r = "RNG dependent on enemy speed buff spawns and timing.", d = "In Warsong Gulch, target players moving unusually fast due to the speed buff. Eliminate them while they are vulnerable to secure the kill.", x = 0 },
        [1260] = { e = 3, s = "s", r = "Time-gated event requiring specific holiday participation.", d = "Equip Synthebrew Goggles during Brewfest and intentionally fall off cliffs or high platforms. Ensure you do not die before falling the full 65 yards.", x = 2 },
        [1261] = { e = 4, s = "s", r = "RNG dependent on G.N.E.R.D. buff duration and kill count.", d = "Accept the G.N.E.R.D. buff and engage in combat to earn honorable kills. Avoid taking lethal damage, as dying resets your progress toward the ten required kills.", x = 2 },
        [1262] = { e = 3, s = "c", h = { 798 }, r = "Requires completing multiple Outland quest achievements.", d = "Complete all listed Outland quests, including those in Hellfire, Terokkar, Nagrand, and Blade's Edge. This is account-wide, so finish them with any character you prefer.", x = 1 },
        [1263] = { e = 2, s = "g", r = "Walk through zone to reveal map areas.", d = "Travel to Howling Fjord and explore every covered area on the map using flying mounts or ground travel. Ensure all zones are revealed before leaving the region.", x = 2 },
        [1264] = { e = 2, s = "g", r = "Walk through zone to reveal map areas.", d = "Travel to Borean Tundra and visit every listed location on the map. Use flying mounts if available to speed up exploration of scattered points like Temple City of En'kilah.", x = 2 },
        [1265] = { e = 2, s = "g", r = "Walk through zone to reveal map areas.", d = "Fly to Dragonblight and mark all zones including Galakrond's Rest and Naxxramas. Ensure you visit the Forgotten Shore as it requires extra steps to reveal.", x = 2 },
        [1266] = { e = 2, s = "g", r = "Walk through zone to reveal map areas.", d = "Head to Grizzly Hills and check off locations like Conquest Hold and Drakil'jin Ruins. Flying is highly recommended here due to the large map size.", x = 2 },
        [1267] = { e = 2, s = "g", r = "Walk through zone to reveal map areas.", d = "Explore Zul'Drak by visiting all altars and Gundrak. This zone has many hidden points, so fly over every hill and ruin to ensure nothing is missed.", x = 2 },
        [1268] = { e = 2, s = "g", r = "Walk through zone to reveal map areas.", d = "Visit Sholazar Basin landmarks such as River's Heart and Makers' Overlook. The water surface hides some points, so swim or use a mount to check every spot.", x = 2 },
        [1269] = { e = 3, s = "g", r = "Large snowy zone with some difficult terrain.", d = "Fly through Storm Peaks to find locations like Brunnhildar Village and Ulduar. Some areas are high up, so look carefully at peaks and floating islands.", x = 2 },
        [1270] = { e = 4, s = "g", r = "Icecrown Citadel and frozen zones are tough.", d = "Enter Icecrown Citadel and explore the surrounding frozen zones including Onslaught Harbor. Check every gate and ruin inside the citadel to reveal all map points.", x = 2 },
        [1271] = { e = 3, s = "c", h = { 62948 }, r = "Most quests are easy; one requires solo speed.", d = "Complete the Hellfire Peninsula storylines by finishing specific quests listed in the achievement info. Focus on main quest hubs like Falcon Watch and Spinebreaker Post.", x = 1 },
        [1272] = { e = 3, s = "c", r = "Complete several storylines in Terokkar Forest.", d = "Finish Terokkar Forest quests such as The Skettis Offensive and Refugee Caravan. Follow the main storyline to ensure all required objectives are completed.", x = 1 },
        [1273] = { e = 3, s = "c", r = "Complete several storylines in Nagrand zone.", d = "Complete Nagrand storylines including Birth of a Warchief and Throne of the Elements. Visit key locations like Lantresor of the Blade to progress the quest chain.", x = 1 },
        [1275] = { e = 4, s = "s", r = "Requires specific solo timing and skill.", d = "Do the Fires Over Skettis quest solo without grouping. Use high-damage abilities to clear enemies quickly and finish within the strict two-minute time limit.", x = 1 },
        [1276] = { e = 3, s = "s", r = "Time trial requires specific gear and solo play.", d = "Complete Bomb Them Again! alone to avoid group penalties. Spam your bomb ability rapidly to defeat targets before the timer runs out.", x = 1 },
        [1277] = { e = 3, s = "s", r = "Time trial requires specific gear and solo play.", d = "Queue solo for Wyrmrest Temple and rush through the defense phase to finish under three minutes. Do not group up, as this achievement requires you to be alone.", x = 2 },
        [1281] = { e = 4, s = "g", r = "High RNG event; needs many attempts to succeed.", d = "During Lunar Festival, stand near the red rocket clusters and spam your ranged attack to clear them quickly. You must destroy ten clusters within twenty-five seconds, so aim for high damage output.", x = 2 },
        [1282] = { e = 3, s = "s", r = "Time trial requires specific mount and event timing.", d = "Wait for Winter Veil events in Dalaran, then mount a flying reindeer before accepting the Bomb Them Again quest. Complete the objective while staying mounted on the reindeer to earn the title.", x = 2 },
        [1283] = { e = 4, s = "c", h = { 4356, 4349, 4359 }, r = "Classic dungeons are easy but require many runs.", d = "Run through every classic dungeon listed in the info field, starting with Deadmines and ending with Blackrock Depths. These are account-wide, so ensure all characters on your account complete them.", x = 2 },
        [1284] = { e = 4, s = "c", h = { 4104, 4089, 4097 }, r = "BC dungeons are easy but require many runs.", d = "Complete all Burning Crusade dungeons from Hellfire Ramparts to Magister's Terrace, including the extra instance. This is account-wide, so coordinate with friends or use a dungeon finder for efficiency.", x = 2 },
        [1285] = { e = 5, s = "c", h = { 6187, 6188, 6189 }, r = "Classic raids are hard; requires group and RNG.", d = "Clear the four classic raids: Molten Core, Blackwing Lair, Temple of Ahn'Qiraj, and Ruins of Ahn'Qiraj. These are account-wide achievements, so make sure every character on your account completes them.", x = 2 },
        [1286] = { e = 5, s = "c", h = { 4392, 4387, 4390 }, r = "BC raids are hard; requires group and RNG.", d = "Finish all Burning Crusade raids from Karazhan to Sunwell Plateau in any difficulty. Since this is account-wide, ensure each character on your account clears at least one raid instance.", x = 2 },
        [1287] = { e = 5, s = "c", h = { 871, 875, 876 }, r = "Heroic dungeons are hard; requires group and RNG.", d = "Complete the heroic versions of all Burning Crusade dungeons listed in the info field. This is account-wide, so plan a group run where every character finishes the heroic version of each dungeon.", x = 2 },
        [1288] = { e = 4, s = "c", h = { 4627, 4617, 4626 }, r = "Northrend dungeons are moderate but require many runs.", d = "Run through every Northrend dungeon from Utgarde Keep to Utgarde Pinnacle, including time-gated instances like Caverns of Time. These are account-wide, so ensure all characters complete them.", x = 2 },
        [1289] = { e = 5, s = "c", h = { 6170, 6171, 6179 }, r = "Heroic Northrend dungeons are hard; requires group.", d = "Clear the heroic versions of all Northrend dungeons listed in the info field. This is account-wide, so coordinate with friends or use a dungeon finder to finish each heroic instance.", x = 2 },
        [1291] = { e = 3, s = "s", r = "Event-specific interaction; timing dependent.", d = "During Love is in the Air, meet another player in Dalaran for a Romantic Picnic and eat Buttermilk Delight together. You must be at the picnic table during the event window to trigger the achievement.", x = 2 },
        [1295] = { e = 2, s = "g", r = "Grind for 25 crashes during a seasonal event.", d = "Participate in Winter Veil events and use your Crashin' Thrashin' Racer to gain crashes. Aim for twenty-five crashes within the event duration, as this is account-wide.", x = 2 },
        [1296] = { e = 4, s = "c", r = "Requires specific Heroic dungeon timing and mechanics.", d = "Defeat Krik'thir on Heroic while keeping the three Watchers alive by avoiding their aggro and not killing them prematurely. This requires careful tanking and damage control to prevent accidental deaths before the final boss dies.", x = 2 },
        [1297] = { e = 4, s = "c", r = "Requires defeating a boss before a specific mechanic triggers.", d = "Focus all damage on Hadronox immediately upon entering his arena to stop him from webbing the doors and spawning adds. Do not engage other mobs or linger near the entrance, as this wastes critical time before the timer expires.", x = 2 },
        [1307] = { e = 3, s = "s", r = "Defeating a raid boss in Classic mode.", d = "Run Upper Blackrock Spire Classic with a group capable of handling General Drakkisath quickly, as this is legacy content no longer available in current expansions. Ensure your party composition matches the classic mechanics required for this specific encounter.", x = 2 },
        [1308] = { e = 2, s = "s", r = "Winning a specific PvP arena match.", d = "Queue for Strand of the Ancients and win any match to claim this point; it serves as a prerequisite for the veteran version. Play aggressively but avoid unnecessary deaths that could prolong the match beyond the time limit.", x = 0 },
        [1309] = { e = 4, s = "g", r = "Grinding 100 PvP victories is time-consuming.", d = "Complete 100 victories in Strand of the Ancients, which requires account-wide progress and consistent queue participation. This is a grind requiring significant time investment as each win counts toward the total regardless of character level or class.", x = 0 },
        [1310] = { e = 2, s = "s", r = "Capturing a relic within a short time limit.", d = "Capture the Titan Relic within four minutes by coordinating with your team to secure objectives efficiently. Avoid unnecessary fights that waste time, focusing solely on completing the capture objective before the timer runs out.", x = 0 },
        [1311] = { e = 4, s = "c", h = { 5009, 5010, 5028 }, r = "Killing extremely rare creatures is difficult RNG.", d = "Kill one of the listed rare Outland creatures, such as Ambassador Jerrikar or Bog Lurker, which are extremely hard to find. Use a high-level character with good detection abilities and be patient, as these mobs spawn rarely and may require extensive world exploration.", x = 1 },
        [1312] = { e = 5, s = "g", r = "Grinding all rare creatures requires massive luck/time.", d = "Complete all rare Outland creature kills after earning Medium Rare, requiring extensive grinding across multiple zones. Track your progress carefully since missing even one mob means restarting the entire collection process for this achievement.", x = 1 },
        [1356] = { e = 3, s = "c", h = { 63750, 63752, 63754 }, r = "Completing multiple quest chains in one zone.", d = "Finish all Howling Fjord storylines by completing specific quests listed in the achievement details. Follow the quest chain sequentially and ensure you complete every required objective to unlock this zone-specific achievement.", x = 2 },
        [1357] = { e = 3, s = "c", h = { 64038, 64040, 64042 }, r = "Completing multiple quest chains in another zone.", d = "Complete Grizzly Hills storylines including Ursoc, the Bear God, and other key quests. Engage with local NPCs and follow the main storyline to progress through all necessary objectives for this region.", x = 2 },
        [1358] = { e = 3, s = "c", h = { 63894, 63896, 63898 }, r = "Completing multiple quest chains in a third zone.", d = "Finish Borean Tundra storylines like The Fate of Farseer Grimwalker and others listed. Work through the quest chain methodically, ensuring you complete every step before moving on to subsequent objectives in the zone.", x = 2 },
        [1359] = { e = 4, s = "c", h = { 63857, 63852, 63856 }, r = "Requires completing multiple difficult Dragonblight quests.", d = "Complete Dragonblight storylines including The Taunka and Traitors to the Horde. Follow the main quest line carefully and engage with key NPCs to progress through all required objectives for this achievement.", x = 2 },
        [1396] = { e = 3, s = "c", r = "Find and honor many scattered NPCs across zones.", d = "Start by queuing for Northrend dungeons or World Quests to find the Elders efficiently. Since this is account-wide and time-gated by the Lunar Festival event, complete it immediately while the NPCs are active.", x = 2 },
        [1428] = { e = 5, s = "s", r = "High RNG requirement for consecutive mine hits.", d = "Travel to Sparksocket Minefield in Northrend and intentionally walk into mine explosions without jumping or rolling. You must survive ten consecutive hits without landing, so be prepared for significant damage.", x = 2 },
        [1457] = { e = 3, s = "g", r = "Explore map areas to reveal hidden zones.", d = "Fly over Crystalsong Forest using a mount to reveal all hidden map areas quickly. This is account-wide and can be done anytime the zone is accessible, making it a low-effort task.", x = 2 },
        [1502] = { e = 3, s = "s", r = "Fast-paced PvP objective with time limit.", d = "Queue for Warsong Gulch PVP matches and rush the flag immediately upon spawning to capture it under 75 seconds. Practice this in lower-level brackets if you struggle with the timer.", x = 0 },
        [1516] = { e = 4, s = "c", h = { 3237, 3240, 3241 }, r = "Includes heavy grind for rare fish and RNG.", d = "Begin by completing the sub-achievements listed in the info field, such as catching specific fish types or reaching fishing milestones. Work through these systematically to unlock the main title reward.", x = 2 },
        [1517] = { e = 3, s = "g", r = "Catch specific fish at various locations.", d = "Fish in every specific node listed in the info field, ensuring you catch at least one fish from each location. This requires visiting various Northrend fishing spots and checking your collection after each session.", x = 2 },
        [1552] = { e = 4, s = "s", r = "Requires precise timing and luck with RNG.", d = "Locate Festival Firecrackers during the Lunar Festival event and use ranged attacks to shoot ten of them within thirty seconds. Aim for high-damage weapons or abilities to maximize damage per second.", x = 2 },
        [1556] = { e = 2, s = "g", r = "Simple fishing task to reach count of 25.", d = "Fish in any available water zone until you have caught twenty-five items total. This is account-wide and can be completed quickly by focusing on high-yield fishing spots.", x = 2 },
        [1557] = { e = 2, s = "g", r = "Continue fishing until reaching count of 50.", d = "Continue fishing from your previous count to reach fifty items, noting that this requires the prior achievement. Maintain a steady pace to avoid missing the event window if applicable.", x = 2 },
        [1558] = { e = 3, s = "g", r = "Fishing grind increases with higher counts.", d = "Fish until you have caught one hundred items, building on your progress from the previous milestone. This is account-wide and can be done in any fishing zone with active nodes.", x = 2 },
        [1559] = { e = 4, s = "g", r = "Significant time investment to reach 250 fish.", d = "Keep fishing to reach two hundred fifty items, ensuring you do not reset your counter unnecessarily. This achievement is part of a chain, so track your total count carefully.", x = 2 },
        [1560] = { e = 2, s = "g", r = "Grinding fishing is easy but takes time.", d = "Fish until you have caught five hundred items, continuing the progression from the previous milestone. This is account-wide and can be completed efficiently by targeting dense fish populations.", x = 2 },
        [1561] = { e = 3, s = "g", r = "More fish required makes it a longer grind.", d = "Fish randomly in any zone until you hit the cap; this is account-wide so progress carries across characters. No specific location is required, but avoid zones with low fish spawn rates to save time.", x = 2 },
        [1563] = { e = 4, s = "c", h = { 6976, 6986, 6977 }, r = "Cooking titles require rare recipes and RNG.", d = "Complete all listed sub-achievements first, as they often unlock cooking recipes or titles needed for others. Some require rare ingredients like the Northrend Gourmet, so ensure you have access to those zones before starting.", x = 2 },
        [1576] = { e = 4, s = "c", h = { 5129, 5130 }, r = "Specific boss kills in difficult instances.", d = "Travel to Nagrand and Zul'Drak to finish the Ring of Blood and Ampitheater of Anguish quests. These are time-gated by expansion content availability, so do not delay until later expansions overwrite them.", x = 2 },
        [1596] = { e = 4, s = "c", h = { 5240, 5241 }, r = "Storyline quests involve complex mechanics.", d = "Finish the Drakuru storyline in Dragonmaw Keep within Northrend. This is a main quest chain that may become unavailable if you wait too long or miss the zone's active state.", x = 2 },
        [1638] = { e = 5, s = "s", r = "Defeating a raid boss is very hard.", d = "Defeat Captain Skyshatter during the Dragonmaw race on Netherwing Ledge in The Burning Crusade. This requires being at the correct level and having access to the Isle of Quel'Danas content.", x = 1 },
        [1656] = { e = 5, s = "c", r = "Raid bosses require groups and high skill.", d = "Complete all Hallow's End sub-achievements listed, which involve specific NPCs and events during the holiday. These are time-gated to the Feast of Winter Veil event window each year.", x = 2 },
        [1658] = { e = 4, s = "c", h = { 16559, 16558, 16560 }, r = "Requires defeating multiple LFR/Mythic+ bosses including raid leaders.", d = "Defeat all listed Lich King raid and dungeon bosses in both normal and heroic modes as required. This achievement is time-gated by the removal of these instances from the game. Prioritize completing this before any major content updates or expansions that remove these raids.", x = 2 },
        [1676] = { e = 4, s = "c", r = "Many quests across zones is a long grind.", d = "Finish every quest achievement listed for Eastern Kingdoms zones like Stormwind and Elwynn. Start with low-level quests first to avoid missing any that expire or become unobtainable later.", x = 0 },
        [1678] = { e = 4, s = "c", r = "Many quests across zones is a long grind.", d = "Complete all Kalimdor quest achievements starting from Orgrimmar and Darnassus. Some involve rare drops or specific NPCs, so check each sub-achievement carefully before moving on.", x = 0 },
        [1683] = { e = 3, s = "c", h = { 17101, 17103, 17102 }, r = "Event-specific tasks with some RNG elements.", d = "Participate in Brewfest events to complete the listed achievements like brewing special drinks and visiting locations. This is time-gated to the annual Brewfest holiday window.", x = 2 },
        [1685] = { e = 3, s = "c", h = { 15127, 15125, 15126 }, r = "Event-specific interaction with specific NPCs.", d = "Use Mistletoe on specific Horde NPCs during Winter Veil. These targets are account-wide, so one character can complete them for everyone if you know their locations.", x = 2 },
        [1686] = { e = 2, s = "c", r = "Visit 9 NPCs in different zones during event.", d = "Use Mistletoe on specific Alliance NPCs during Winter Veil. Similar to the Horde version, this is account-wide and requires visiting multiple zones like Stormwind and Stranglethorn Vale.", x = 2 },
        [1687] = { e = 3, s = "g", r = "Use item on 10 specific race/class combos.", d = "Apply Handful of Snowflakes to each listed race/class combination during Winter Veil. This is account-wide and time-gated, so ensure you have access to all required characters or use an alt for efficiency.", x = 2 },
        [1688] = { e = 2, s = "c", r = "Cook 3 recipes during the event week.", d = "Cook the three specific recipes during Winter Veil, as this is a time-gated event. Ensure you have the necessary ingredients and cooking skill before the holiday ends.", x = 2 },
        [1689] = { e = 1, s = "s", r = "Open one present under the tree.", d = "Wait for presents to appear under the tree in Dalaran and open one immediately. This is account-wide but requires the event timer to be active.", x = 2 },
        [1690] = { e = 2, s = "s", r = "Use disguise kit and dance once in Dalaran.", d = "Use your Disguise kit to become a snowman, then find another player doing the same in Dalaran to dance together. Coordinate with friends or wait for others online.", x = 2 },
        [1691] = { e = 4, s = "c", h = { 10393 }, r = "Requires completing other events; On Metzen is hardest.", d = "This is a hub achievement requiring all listed sub-achievements; start them early since many are time-gated by seasonal events.", x = 2 },
        [1693] = { e = 4, s = "c", h = { 11125 }, r = "Requires completing other events; Rocket event is hardest.", d = "Complete the Love is in the Air set before the event ends, as these rewards include a title and are account-wide.", x = 2 },
        [1694] = { e = 3, s = "g", r = "Open boxes until drop procures dress.", d = "Locate and open Lovely Dress Boxes to receive the black dress; this may require specific vendors or quest completion during the event.", x = 2 },
        [1695] = { e = 2, s = "s", r = "Complete one specific quest chain.", d = "Talk to Snagglebolt in Dalaran to assist with the Crown Chemical Co. plot, which involves a short quest chain available only during Love is in the Air.", x = 2 },
        [1696] = { e = 3, s = "g", r = "Shoot fireworks 10 times within time limit.", d = "Use fireworks quickly in a safe area like Dalaran; aim for efficiency since you must launch ten within twenty seconds.", x = 2 },
        [1699] = { e = 3, s = "g", r = "Use item on 11 specific race/class combos.", d = "Apply rose petals to every listed race/class combination, which includes many rare pairings; check your character list carefully to avoid missing any.", x = 2 },
        [1700] = { e = 4, s = "g", r = "Requires rare drop from specific quest chain.", d = "Obtain the Truesilver Shafted Arrow from Snagglebolt to get the Peddlefeet pet; this is account-wide and requires the event to be active.", x = 2 },
        [1701] = { e = 3, s = "g", r = "Collecting 8 specific items from a limited event.", d = "Eat all eight heart candies listed, which are obtained through various event activities; track your progress to ensure you consume every flavor.", x = 2 },
        [1702] = { e = 3, s = "g", r = "Sampling 4 specific candies during the event.", d = "Sample all four specific candies available during Love is in the Air; these are usually given as quest rewards or vendor items.", x = 2 },
        [1703] = { e = 3, s = "s", r = "Obtaining one bouquet from a limited-time vendor.", d = "Buy Red or Ebon Roses from vendors during the Love is in the Air event to complete this quickly.", x = 2 },
        [1704] = { e = 3, s = "c", h = { 11190 }, r = "Requires visiting 5 specific zones; Culling of Stratholme is hardest.", d = "Find and pity the Love Fool NPC at specific PvP zones like Wintergrasp or Arathi Basin while the event is active.", x = 2 },
        [1717] = { e = 3, s = "s", r = "Winning a single Wintergrasp battle.", d = "Win a single battle in Wintergrasp to unlock this; it is often a prerequisite for other Wintergrasp achievements.", x = 2 },
        [1718] = { e = 4, s = "g", r = "Grinding 100 wins requires many days of PvP.", d = "Win 100 battles in Wintergrasp; join organized groups or use the queue system to speed up progress significantly.", x = 2 },
        [1721] = { e = 5, s = "s", r = "Defeating Archavon in 25-man mode is a raid boss fight.", d = "Defeat Archavon the Stone Watcher in a 25-player group during the Wintergrasp event for this specific version.", x = 2 },
        [1722] = { e = 4, s = "s", r = "Defeating Archavon in 10-man mode is a hard raid fight.", d = "Defeat Archavon the Stone Watcher in a 10-player group; ensure your raid composition is balanced for this difficulty.", x = 2 },
        [1723] = { e = 4, s = "g", r = "Killing 100 players with vehicles takes significant time.", d = "Kill 100 players using vehicles or cannons in Wintergrasp; coordinate with teammates to maximize cannon usage.", x = 2 },
        [1727] = { e = 3, s = "s", r = "Destroying one tower is a single objective.", d = "Destroy one of the three towers in Wintergrasp by focusing fire on them during the battle.", x = 2 },
        [1737] = { e = 3, s = "c", r = "Destroying 4 specific vehicles; roughly equal difficulty.", d = "Destroy all four specific vehicles in Wintergrasp; prioritize targeting them early to prevent repairs.", x = 2 },
        [1751] = { e = 4, s = "g", r = "Killing 20 mounted players with a cannon is a grind.", d = "Kill 20 mounted players using the tower cannon; aim for flying or riding mounts for easy kills.", x = 2 },
        [1752] = { e = 4, s = "c", h = { 14249, 14250, 14253 }, r = "Requires completing multiple difficult Wintergrasp sub-achievements.", d = "Complete all listed Wintergrasp achievements first; this is a summary title that unlocks after finishing the others.", x = 2 },
        [1755] = { e = 3, s = "s", r = "Needs a fast capture, but achievable with good positioning.", d = "Attack and capture Wintergrasp within 10 minutes; start immediately upon spawn to avoid missing the time limit.", x = 2 },
        [1757] = { e = 4, s = "c", r = "Requires perfect defense without losing any walls.", d = "Defend the beach without losing any walls by holding key choke points and healing teammates constantly. This is a time-gated achievement that requires full group coordination to complete before the event ends.", x = 0 },
        [1761] = { e = 3, s = "g", r = "Grinding 100 successful charges is tedious but straightforward.", d = "Plant Seaforium charges on enemy walls and focus fire them down quickly while avoiding damage. Since this tracks account-wide, coordinate with friends to maximize progress across different servers or sessions.", x = 0 },
        [1762] = { e = 4, s = "s", r = "Winning without losing vehicles requires high skill and luck.", d = "Win a battle without losing any siege vehicles by protecting your own turrets and healing them immediately after taking hits. This requires disciplined positioning and strong group support throughout the entire match.", x = 0 },
        [1763] = { e = 3, s = "g", r = "Destroying 100 vehicles is a long grind but easy per kill.", d = "Destroy enemy vehicles using turret attacks rather than melee or ranged abilities for efficiency. Focus on high-value targets first to clear the field quickly and avoid unnecessary vehicle losses.", x = 0 },
        [1764] = { e = 3, s = "g", r = "Killing 100 players carrying seaforium is a long grind.", d = "Kill players carrying Seaforium by tracking their movement and focusing down carriers before they can plant charges. This is account-wide so team up with others to speed up progress significantly.", x = 0 },
        [1765] = { e = 2, s = "s", r = "Disarming two charges in one battle is easy for most.", d = "Disarm two Seaforium charges in a single battle by coordinating with your team to focus one charge at a time. Do not split your group too thin or you may fail the condition if both charges aren't disabled together.", x = 0 },
        [1766] = { e = 3, s = "s", r = "Killing 10 players in a single battle is moderate difficulty.", d = "Kill ten players in the Courtyard of the Ancients during one battle by grouping up and focusing on enemies near the spawn area. This is a high-difficulty objective that requires strong DPS and tanking capabilities from your entire group.", x = 0 },
        [1777] = { e = 2, s = "g", r = "Cooking 15 recipes is easy if you have the ingredients.", d = "Cook fifteen specific Northrend recipes listed in the achievement description to unlock the next tier. Start by gathering ingredients from local vendors or fishing spots to avoid missing any required dishes.", x = 2 },
        [1778] = { e = 3, s = "g", r = "Cooking 30 recipes takes longer but remains solo-friendly.", d = "Cook thirty additional Northrend recipes after completing the previous tier to continue progressing through the chain. Ensure you have access to all necessary ingredients before attempting each new recipe to save time.", x = 2 },
        [1779] = { e = 4, s = "g", r = "Cooking 45 recipes is a significant time investment alone.", d = "Cook forty-five total Northrend recipes by continuing to prepare dishes from the expanded list provided. Keep an eye on ingredient availability and cook multiple dishes simultaneously if possible for faster completion.", x = 2 },
        [1780] = { e = 1, s = "c", r = "Buy and eat four common foods.", d = "Eat each of the four specific emotion foods listed in the achievement description to complete this collection. These items are often sold by vendors or dropped from certain quests so check your local sources first.", x = 2 },
        [1781] = { e = 2, s = "g", r = "Feed critters quickly; RNG affects speed slightly.", d = "Use Critter Bites on wild critters and quickly tame them within three minutes to reach the count of ten. This requires fast reaction times and may need multiple attempts if some critters resist taming initially.", x = 2 },
        [1782] = { e = 3, s = "c", r = "Complete five daily cooking quests in Dalaran.", d = "Visit Katherine Lee in Dalaran daily to turn in the five specific food quests listed in her info field. Since these are account-wide, one character can complete them all for everyone. Do not delay, as dailies reset weekly and you must finish each unique quest before the timer expires.", x = 2 },
        [1783] = { e = 3, s = "c", r = "Complete five daily cooking quests in Dalaran.", d = "Go to Awilo Lon'gomba in Dalaran every week to accept and turn in his five distinct cooking daily quests. These tasks are account-wide, so one player can finish them for your entire group. Remember that dailies reset on Monday, so plan your weekly schedule around these specific recipes.", x = 2 },
        [1785] = { e = 2, s = "c", r = "Cook and deliver feasts in four battlegrounds.", d = "Cook a Great Feast before entering Alterac Valley, Arathi Basin, Warsong Gulch, or Eye of the Storm to unlock the achievement. You must deliver this feast in each battleground individually; simply winning is not enough. This can be done solo or with friends, but ensure you have the recipe learned first.", x = 2 },
        [1786] = { e = 3, s = "c", r = "Complete four specific feats with an orphan.", d = "Take your orphan companion into battlegrounds like Eye of the Storm or Alterac Valley to complete specific capture and assault feats. You must physically bring the orphan along; they cannot follow you from other zones. Complete each listed feat once per account, noting that some actions require active participation in the battle.", x = 2 },
        [1788] = { e = 2, s = "c", r = "Eat seven sweets while an orphan watches.", d = "Eat any of the seven listed sweets while your orphan companion is present to progress this achievement. You can eat them quickly in a safe zone or during travel without needing to fight. Ensure the orphan follows you closely, as leaving them behind will reset the condition for that specific sweet.", x = 2 },
        [1789] = { e = 3, s = "g", r = "Complete five daily quests with an orphan.", d = "Accept and complete five different daily quests while your orphan companion is following you to earn this achievement. Dailies reset weekly, so aim to do these early in the week when possible. You can switch between dailies freely, but keep the orphan with you throughout the entire process.", x = 2 },
        [1790] = { e = 4, s = "s", r = "Defeat a raid boss with an orphan present.", d = "Bring your orphan into Utgarde Pinnacle and defeat King Ymiron to complete this specific Children's Week task. This is a high-level dungeon run, so ensure your group or solo gear is sufficient for the boss fight. The achievement unlocks immediately upon defeating the boss with the companion present.", x = 2 },
        [1791] = { e = 1, s = "s", r = "Use hearthstone once with an orphan nearby.", d = "Use your Hearthstone while your orphan companion is following you to instantly complete this easy objective. You can do this from any major city or safe zone without needing to travel far. Simply ensure the orphan follows you before clicking the hearthstone button to secure the point.", x = 2 },
        [1792] = { e = 3, s = "g", r = "Quest for a rare pet; RNG involved.", d = "Complete Children's Week questing objectives to earn one of the special reward pets listed in the event info. These pets are account-wide, so one character can collect them for everyone. Check your quest log regularly during the event window, as these rewards may not appear after the event ends.", x = 2 },
        [1793] = { e = 4, s = "c", r = "Requires completing the raid boss achievement.", d = "Finish all five specific Children's Week achievements listed in the info field to unlock the Matron/Patron title. This is a meta-achievement requiring you to complete the sub-tasks like defeating bosses or eating sweets. Start early in the event week, as missing the window means you must wait for the next year.", x = 2 },
        [1795] = { e = 2, s = "g", r = "Learn 25 recipes; requires gathering materials.", d = "Learn twenty-five unique cooking recipes by accepting profession quests or finding trainers to reach this milestone. Focus on learning new recipes rather than just leveling up your skill, as duplicates do not count. This achievement is account-wide, so one character can learn all recipes for the whole group.", x = 2 },
        [1796] = { e = 3, s = "g", r = "Learn 50 recipes; takes longer than first tier.", d = "Continue learning cooking recipes until you have mastered fifty unique ones to unlock this next tier of the profession chain. You must build on your progress from the previous 25-recipe achievement; do not reset your skill. This is account-wide, so one player can finish it for everyone once they hit the count.", x = 2 },
        [1797] = { e = 4, s = "g", r = "Learn 75 recipes; significant time investment.", d = "Start cooking immediately after learning the Short Order Cook skill to begin unlocking recipes. Focus on gathering basic ingredients like meat and vegetables from any zone you visit. Do not wait for rare drops; simply cook common dishes repeatedly until you hit the 75-recipe threshold.", x = 2 },
        [1798] = { e = 4, s = "g", r = "Learn 100 recipes; requires extensive gathering.", d = "Continue cooking diverse meals to reach the 100-recipe requirement for this title. Since many recipes unlock automatically as you level professions, ensure you cook everything available in your current zone before moving on. This step is purely cumulative, so there are no specific rare items or time gates to worry about.", x = 2 },
        [1799] = { e = 5, s = "g", r = "Learn 160 recipes; very long grind for solo.", d = "Unlock the Iron Chef title by learning all 160 cooking recipes available in the game. You must cook every single recipe at least once, including those requiring rare ingredients from raids or world bosses. Plan your runs around these specific drops to ensure you do not miss any unique dishes.", x = 2 },
        [1800] = { e = 4, s = "c", h = { 16533 }, r = "Cook specific Outland dishes; one is rare spawn.", d = "Cook the specific list of Outland recipes provided in the achievement description, including items like Delicious Chocolate Cake and Blackened Trout. This is an account-wide achievement, so one character can complete it for everyone on your realm. Ensure you have access to Outland zones or use a portal to cook these unique dishes.", x = 2 },
        [1801] = { e = 2, s = "g", r = "Brew a specific lager; simple crafting task.", d = "Brew Captain Rumsey's Lager by gathering the necessary brewing materials and visiting the appropriate zone for this recipe. This is likely a rare drop or specific quest reward, so be prepared to wait for it to appear in your bags. Once brewed, simply consume the item to claim the achievement points.", x = 2 },
        [1816] = { e = 4, s = "s", r = "Specific raid boss fight with strict mechanics.", d = "Defeat Cyanigosa in The Violet Hold on Heroic difficulty without using Defense Control Crystals and while keeping Prison Seal Integrity at 100%. This requires a coordinated group strategy to avoid breaking the seal during the fight. Do not use the crystals as a crutch; plan your damage rotation to kill the boss before the seal breaks.", x = 2 },
        [1817] = { e = 5, s = "s", r = "Defeat specific boss on Heroic; high difficulty.", d = "Clear The Culling of Stratholme on Heroic difficulty and defeat the Infinite Corruptor to earn this account-wide title. Ensure your group is prepared for the mechanics of this specific raid encounter before attempting it. Once defeated, the achievement unlocks for all characters on your account automatically.", x = 2 },
        [1832] = { e = 4, s = "g", r = "Sample 50 dishes; requires travel and RNG.", d = "Sample 50 different kinds of dishes by eating various foods found in the world or crafted by professions. Visit different zones and try local specialties to quickly increase your count. Keep track of unique food items you have eaten to avoid duplicates and maximize efficiency.", x = 2 },
        [1833] = { e = 4, s = "g", r = "Drink 25 beverages; requires finding vendors.", d = "Drink 25 different types of beverages found in the world or crafted by alchemy and engineering. Explore various zones to find unique drinks like wines, ales, and potions. Consume them once to count towards your total; you do not need to stockpile them.", x = 2 },
        [1834] = { e = 4, s = "s", r = "Defeat boss with specific debuff active.", d = "Defeat General Bjarngrim in the Halls of Lightning on Heroic difficulty while he has a Temporary Electrical Charge. This mechanic requires timing your damage output to strike him down during the specific charge window. Coordinate with your group to focus fire only when this debuff is active.", x = 2 },
        [1836] = { e = 1, s = "s", r = "Simple fishing task in starting city.", d = "Fish up Old Crafty in Orgrimmar by casting your line in the designated fishing spots within the city. This fish may be rare or require specific bait, so be patient and try different locations if you do not catch it immediately. Once caught, claim the achievement instantly.", x = 2 },
        [1837] = { e = 1, s = "s", r = "Simple fishing task in starting city.", d = "Fish up Old Ironjaw in Ironforge by casting your line in the fishing spots located within the city walls. Like other rare fish, this may require patience or specific bait to appear. Catch it once and you will immediately unlock the achievement without needing to do anything else.", x = 2 },
        [1856] = { e = 4, s = "c", r = "Highly skilled 10-man raid kill required.", d = "Gather a full 10-man group and run Patchwerk on Normal difficulty. You must kill him in under three minutes, so focus entirely on DPS immediately upon entering the arena.", x = 2 },
        [1857] = { e = 4, s = "c", r = "Highly skilled 25-man raid kill required.", d = "This requires a full 25-player raid group to defeat Patchwerk quickly. Coordinate with your raid leader to ensure everyone is present and ready for maximum damage output right away.", x = 2 },
        [1858] = { e = 4, s = "c", r = "Timed 10-man raid kill with mechanics.", d = "Start this run by defeating Anub'Rekhan first, then immediately pull Maexxna. You have only twenty minutes after Anub's death to kill her, so do not delay or clear trash mobs.", x = 2 },
        [1859] = { e = 4, s = "c", r = "Timed 25-man raid kill with mechanics.", d = "Similar to the ten-player version, you must defeat Anub'Rekhan before pulling Maexxna in a twenty-five-player raid. Ensure your entire group is ready to burst damage instantly upon entering the arena.", x = 2 },
        [1860] = { e = 4, s = "c", r = "Fast Heroic dungeon clear required.", d = "Run Azjol-Nerub on Heroic and kill Anub'arak as fast as possible. You have only four minutes, so skip any unnecessary trash pulls and focus solely on defeating the boss quickly.", x = 2 },
        [1862] = { e = 4, s = "c", r = "Very fast Heroic dungeon clear required.", d = "Defeat Herald Volazj on Heroic in under two minutes by avoiding his mechanics and focusing all damage on him immediately. This is a time-gated achievement that requires efficient raid execution.", x = 2 },
        [1864] = { e = 4, s = "c", r = "Heroic dungeon kill with specific buff.", d = "You must enter Gundrak while under the effects of Eck Residue to defeat Gal'darah. Apply the buff before starting the fight and maintain it throughout the entire encounter.", x = 2 },
        [1865] = { e = 5, s = "c", h = { 10999, 11002, 10997 }, r = "Full Violet Hold Heroic run required.", d = "This account-wide achievement requires defeating all six bosses in The Violet Hold on Heroic difficulty. You must complete every boss in the dungeon sequentially to claim the points.", x = 2 },
        [1866] = { e = 4, s = "c", r = "Extremely fast Heroic dungeon clear.", d = "Defeat the Maiden of Grief on Heroic in under one minute. This is a time-gated fight that requires your group to deal massive damage instantly upon engaging the boss.", x = 2 },
        [1867] = { e = 4, s = "c", r = "Fast Heroic dungeon clear required.", d = "Run Halls of Lightning on Heroic and kill Loken within two minutes. Focus all your damage output immediately after the boss spawns to meet the strict time limit.", x = 2 },
        [1868] = { e = 5, s = "s", r = "Highly skilled raiding required with strict time limit.", d = "Defeat Drakos the Interrogator first in The Oculus on Heroic, then immediately pull Ley-Guardian Eregos. You have twenty minutes after Drakos dies to kill Eregos before the timer expires.", x = 2 },
        [1869] = { e = 5, s = "s", r = "Extreme skill check; nearly impossible for new players.", d = "Defeat Malygos in ten-player mode while keeping your total damage below nine thousand. Monitor your group's DPS carefully and avoid overkill to ensure you meet this specific condition.", x = 2 },
        [1870] = { e = 4, s = "s", r = "Difficult raid mechanics with low player count requirement.", d = "Defeat Malygos in 25-player mode with fewer than 21 players present. Start the fight immediately and avoid unnecessary deaths to keep the group size low.", x = 2 },
        [1871] = { e = 5, s = "c", h = { 10558, 10559, 10557 }, r = "Requires specific rare mounts and high-level raiding.", d = "Visit The Oculus on Heroic three times, each time riding a different drake (Amber, Emerald, or Ruby). Ensure you are mounted before engaging Eregos for credit.", x = 2 },
        [1872] = { e = 4, s = "g", r = "Intense speed run requiring perfect execution.", d = "Farm Risen Zombies in The Culling of Stratholme on Heroic by focusing all damage on them. Aim to kill 100 within one minute using high DPS and efficient positioning.", x = 2 },
        [1873] = { e = 5, s = "s", r = "Extremely tight time window on a difficult boss.", d = "Start the Skadi gauntlet event and defeat her within three minutes. Coordinate your group to minimize pull times and maximize damage output immediately upon spawning.", x = 2 },
        [1874] = { e = 5, s = "s", r = "Requires top-tier raid performance and speed.", d = "Defeat Malygos in 10-player mode within six minutes. Maintain high DPS and avoid unnecessary deaths to keep the timer under control.", x = 2 },
        [1875] = { e = 5, s = "s", r = "Difficult raid mechanics with strict time limit.", d = "Defeat Malygos in 25-player mode within six minutes. Coordinate your group to minimize pull times and maximize damage output immediately upon spawning.", x = 2 },
        [1876] = { e = 4, s = "s", r = "High-level raiding required; difficult encounter.", d = "Defeat Sartharion the Onyx Guardian in 10-player mode. Ensure you have a full group ready as this is a timed encounter with specific mechanics.", x = 2 },
        [1877] = { e = 5, s = "c", h = { 10135, 10136, 10134 }, r = "Requires defeating multiple bosses with specific mechanics.", d = "Defeat Sartharion and the Twilight Drakes in 25-player mode with fewer than 21 players. Coordinate your group to minimize pull times and maximize damage output immediately upon spawning.", x = 2 },
        [1919] = { e = 4, s = "s", r = "Difficult raiding with strict condition to avoid shattering.", d = "Defeat Prince Keleseth in Utgarde Keep on Heroic without shattering any Frost Tombs. Avoid using abilities that trigger the tomb mechanic or accidentally break them during combat.", x = 2 },
        [1936] = { e = 2, s = "s", r = "Simple event participation; obtainable during Brewfest.", d = "Participate in Brewfest events to complete the quest line and obtain the Wolpertinger pet. This achievement is time-gated to the event duration so plan accordingly.", x = 2 },
        [1956] = { e = 2, s = "c", r = "Read 8 books in Dalaran; takes under an hour.", d = "Read all volumes of The Schools of Arcane Magic in Dalaran to unlock this achievement. Visit the library inside Dalaran and interact with each book title listed in the info.", x = 2 },
        [1957] = { e = 3, s = "g", r = "Fish for rare coins; RNG makes it take hours.", d = "Fish up various gold coins from the fountain in Dalaran. This is account-wide, so any character can contribute by fishing at the fountain location.", x = 2 },
        [1958] = { e = 2, s = "s", r = "Fish one specific rat from a fountain.", d = "Fish for the Giant Sewer Rat in The Underbelly zone of Dalaran. This is a simple fishing achievement with no time gate or group requirement.", x = 2 },
        [1996] = { e = 4, s = "c", r = "Requires 10-player Naxx run without deaths.", d = "Run Naxxramas as a full 10-player raid to defeat Heigan without anyone dying. Avoid the green mist mechanic by keeping distance and using crowd control carefully.", x = 2 },
        [1997] = { e = 4, s = "c", r = "Requires specific mechanics on Grand Widow Faerlina.", d = "Clear Naxxramas with a full group to kill Grand Widow Faerlina while preventing her frenzy. Do not dispel her curse or use abilities that trigger the frenzy effect.", x = 2 },
        [1998] = { e = 3, s = "g", r = "Cook until you get the award; RNG involved.", d = "Cook any dish to earn a Cooking Award from the NPC in your capital city. You can repeat this process until you reach the next tier of awards.", x = 2 },
        [1999] = { e = 4, s = "g", r = "Need 10 awards; RNG makes this a long grind.", d = "Continue cooking dishes to collect ten total Cooking Awards. This is an account-wide achievement, so any character on your account can contribute to the count.", x = 2 },
        [2000] = { e = 4, s = "g", r = "Need 25 awards; RNG makes this a long grind.", d = "Cook more dishes until you have twenty-five total awards. Keep cooking consistently as this tracks across all characters on your account.", x = 2 },
        [2001] = { e = 4, s = "g", r = "Need 50 awards; RNG makes this a long grind.", d = "Reach fifty Cooking Awards by continuing to cook daily. There is no time limit, so pace yourself over several days if needed.", x = 2 },
        [2002] = { e = 4, s = "g", r = "Need 100 awards; RNG makes this a very long grind.", d = "Cook until you reach one hundred total awards. This final tier requires consistent effort but has no special mechanics or group requirements.", x = 2 },
        [2016] = { e = 3, s = "c", r = "Complete 8 daily quests in Grizzly Hills PvP.", d = "Complete all listed daily quests in Grizzly Hills PvP to earn this title. Ensure you finish every single quest before the daily reset timer expires.", x = 2 },
        [2017] = { e = 3, s = "c", r = "Complete 9 daily quests in Grizzly Hills PvP.", d = "Finish the second set of Grizzly Hills PvP dailies for the same title. Like the previous one, complete all listed quests before they reset each day.", x = 2 },
        [2018] = { e = 4, s = "c", r = "Requires completing multiple specific daily dungeon quests.", d = "Do the specific Northrend daily dungeon quests listed to unlock this legacy achievement. These are account-wide and must be completed within their daily windows.", x = 2 },
        [2019] = { e = 4, s = "c", r = "Requires defeating many different Northrend raid bosses.", d = "Complete all listed Northrend daily dungeon quests marked as Proof of Demise. This is an account-wide legacy achievement that tracks your progress across all characters.", x = 2 },
        [2036] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "Pull Keristrasza and constantly cleanse Intense Cold stacks to stay under two. Coordinate with your healer to manage the debuff timer carefully, as missing a cleanse will fail the run immediately.", x = 2 },
        [2037] = { e = 5, s = "s", r = "Requires perfect mechanics and high skill against a boss.", d = "Focus on keeping Chaotic Rifts intact by avoiding area-of-effect damage near them. Communicate with your group to prioritize healing rifts over dealing damage when they appear during the fight.", x = 2 },
        [2038] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "Defeat Elder Nadox while ensuring no Ahn'kahar Guardians die before him. Keep aggro management tight and avoid pulling extra adds that could cause accidental guardian deaths.", x = 2 },
        [2039] = { e = 4, s = "s", r = "Requires specific mechanics and luck during a raid fight.", d = "Engage King Dred and actively hunt Drakkari Gutrippers or Scytheclaw during the fight. Ensure your group focuses on killing these specific mobs to reach the count of six before defeating the boss.", x = 2 },
        [2040] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "Prevent Moorabi from transforming into a mammoth by managing his transformation mechanic strictly. Use crowd control or interrupts effectively to stop him from changing forms at any point during the encounter.", x = 2 },
        [2041] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "Defeat Ichoron while preventing Ichor Globules from merging. Assign specific players to monitor and destroy globules before they combine, requiring constant attention throughout the fight.", x = 2 },
        [2042] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "This account-wide achievement requires defeating Volkhan without shattering more than four Brittle Golems. Coordinate with your group to protect golems from excessive damage, as this failure condition affects all characters on your account.", x = 2 },
        [2043] = { e = 5, s = "s", r = "Requires specific mechanics and luck during a raid fight.", d = "Force Svala Sorrowgrave to kill a Scourge Hulk by managing her adds correctly. Ensure the Hulk survives long enough for Svala to attack it, which may require specific add management strategies during the encounter.", x = 2 },
        [2044] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "Defeat Ley-Guardian Eregos without anyone using a Ruby Drake in your party. Verify that no player has equipped or used this mount before starting the fight to avoid instant failure.", x = 2 },
        [2045] = { e = 5, s = "s", r = "High RNG mechanic makes this very difficult to complete.", d = "Complete the Eregos encounter without any party member using an Emerald Drake. Double-check all mounts and items beforehand, as using this drake will cause the achievement to fail permanently for your group.", x = 2 },
        [2046] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Defeat Ley-Guardian Eregos while ensuring no one uses an Amber Drake during the fight. Confirm that all party members have removed any equipped drakes before entering the instance to prevent accidental failure.", x = 2 },
        [2047] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Defeat Sartharion in 10-player mode without taking Lava Strike damage. Coordinate with your group to manage the lava mechanic carefully, as even one hit will cause you to lose this account-wide achievement.", x = 2 },
        [2048] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Gather a full 25-player group and defeat Sartharion without taking damage from Lava Strike. This requires precise positioning to avoid the boss's lava attacks while maintaining DPS pressure.", x = 2 },
        [2049] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Start by killing one Twilight Drake before engaging Sartharion in 10-player mode. Keep the remaining drake alive until the fight concludes to complete this step of the chain.", x = 2 },
        [2050] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Repeat the previous fight but ensure two Twilight Drakes survive until Sartharion's defeat. This requires careful management of adds and damage output during the encounter.", x = 2 },
        [2051] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Defeat Sartharion with all three Twilight Drakes still alive to earn the title Of the Nightfall. Coordinate your group to protect the drakes while maximizing damage on the boss.", x = 2 },
        [2052] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Begin the 25-player chain by engaging Sartharion with at least one Twilight Drake alive. Focus on keeping the drake safe while dealing sufficient damage to the boss.", x = 2 },
        [2053] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Progress to defeating Sartharion with two Twilight Drakes alive in 25-player mode. Maintain high group coordination to prevent accidental deaths of the remaining drakes.", x = 2 },
        [2054] = { e = 5, s = "s", r = "Heroic raid boss with strict mechanic and RNG.", d = "Complete the final 25-player step by killing Sartharion while all three Twilight Drakes remain alive. This grants the title Twilight Vanquisher and requires excellent group control.", x = 2 },
        [2056] = { e = 5, s = "s", r = "Heroic dungeon boss with strict mechanic and RNG.", d = "Defeat Jedoga Shadowseeker in Ahn'kahet without killing any Twilight Volunteers. Avoid aggroing or damaging these specific mobs during the entire encounter to secure this achievement.", x = 2 },
        [2057] = { e = 5, s = "s", r = "Heroic dungeon boss with strict mechanic and RNG.", d = "Fight Novos the Summoner in Drak'Tharon Keep while preventing undead minions from reaching the floor. Use crowd control and kiting strategies to keep adds contained safely.", x = 2 },
        [2058] = { e = 5, s = "s", r = "Heroic dungeon boss with strict mechanic and RNG.", d = "Defeat Slad'ran in Gundrak without getting wrapped by snakes. Stay mobile and avoid standing near snake spawns or using abilities that trigger the wrapping mechanic.", x = 2 },
        [2076] = { e = 1, s = "s", r = "Buy mount from NPC in Dalaran.", d = "Travel to Dalaran and speak with Mei Francis to purchase the Armored Brown Bear mount. This is an account-wide achievement, so any character can claim it once obtained.", x = 2 },
        [2077] = { e = 1, s = "s", r = "Buy mount from NPC in Dalaran.", d = "Visit Mei Francis in Dalaran again to buy the Wooly Mammoth mount. Like the previous mount, this is account-wide and requires no specific quest completion.", x = 2 },
        [2078] = { e = 1, s = "s", r = "Buy mount from NPC in Dalaran.", d = "Talk to Mei Francis in Dalaran once you have the required mount collection items. This is account-wide and requires no specific raid or dungeon completion.", x = 2 },
        [2080] = { e = 3, s = "s", r = "Win PvP match for rare drop.", d = "Participate in Wintergrasp battles to earn Black War Mammoths from defeated enemies. Note that this currency often has a weekly cap and may be missable if not collected promptly.", x = 2 },
        [2082] = { e = 4, s = "g", r = "Grind reputation to obtain mount.", d = "Grind Ice Mammoths by defeating elite mobs in Northrend zones or specific dungeons. This achievement is account-wide but can take significant time depending on your level and gear.", x = 2 },
        [2083] = { e = 5, s = "g", r = "High rep grind for rare mount.", d = "Defeat the Grand Ice Mammoth boss found in specific Northrend instances. Ensure you are prepared for high-level content as this drop is rare and account-wide.", x = 2 },
        [2084] = { e = 1, s = "s", r = "Buy item from NPC in Dalaran.", d = "Visit the Kirin Tor vendor in Dalaran to purchase any of the listed rings. You must buy at least one item to complete this collection achievement.", x = 2 },
        [2085] = { e = 3, s = "g", r = "Grind drops to reach count of 50.", d = "Farm Stone Keeper's Shards from specific Northrend dungeons or world bosses. Start with the first tier and work your way up as you accumulate more shards.", x = 2 },
        [2086] = { e = 4, s = "g", r = "Grind drops; requires previous tier.", d = "Continue farming Stone Keeper's Shards until you reach the next threshold. These achievements are chained, so completing one automatically unlocks the next requirement.", x = 2 },
        [2087] = { e = 5, s = "g", r = "Heavy grind; requires previous tiers.", d = "Keep accumulating shards from Northrend content to hit the 250 mark. Be aware that shard drops can be inconsistent, so plan extra farming sessions.", x = 2 },
        [2088] = { e = 5, s = "g", r = "Very heavy grind; requires previous tiers.", d = "Farm more shards to reach the 500 milestone. This stage often requires dedicated group runs due to the volume needed for completion.", x = 2 },
        [2089] = { e = 5, s = "g", r = "Extreme grind; requires all previous tiers.", d = "Push your shard farming to the final 1000 count. Once complete, you will have unlocked all Stone Keeper's Shard achievements available in this chain.", x = 2 },
        [2090] = { e = 3, s = "c", r = "Requires competitive arena ranking; moderate grind.", d = "Compete in Arena matches during an active season to earn the Challenger title. Titles reset each season, so check current requirements before starting.", x = 2 },
        [2091] = { e = 4, s = "c", r = "High arena rating needed; significant time investment.", d = "Reach Gladiator rank in Arena to earn both the title and a custom mount. This is highly competitive and requires consistent high-level performance throughout a season.", x = 2 },
        [2092] = { e = 3, s = "c", r = "Arena title; moderate grind depending on skill.", d = "Queue for Arena matches and focus on winning duels to earn the Duelist title. This is a seasonal goal, so check current season requirements before starting.", x = 2 },
        [2093] = { e = 4, s = "c", r = "High arena rating needed; significant time investment.", d = "Similar to the previous one, queue for Arena matches and aim for higher ranks to unlock the Rival title. Ensure you are active during an active arena season.", x = 2 },
        [2094] = { e = 3, s = "g", r = "Fishing specific coins from fountain; steady grind.", d = "Fish at the Dalaran fountain repeatedly until you collect all listed copper coins. This is account-wide, so one character can complete it for everyone.", x = 2 },
        [2095] = { e = 3, s = "g", r = "Fishing specific coins from fountain; steady grind.", d = "Return to the Dalaran fountain and fish specifically for silver coins from the NPC list provided. Like the copper coins, this tracks across your entire account.", x = 2 },
        [2096] = { e = 3, s = "c", r = "Requires completing other coin fishing achievements.", d = "Complete both previous coin fishing achievements plus the gold coin quest to finish The Coin Master. You will receive a toy reward upon completion.", x = 2 },
        [2097] = { e = 1, s = "s", r = "Buy mount from vendor; trivial task.", d = "Purchase or earn either a Mekgineer's Chopper or a Mechano-hog mount from available vendors. Both options count toward this single achievement.", x = 2 },
        [2136] = { e = 4, s = "c", r = "Heroic dungeons require group and multiple runs.", d = "Run all listed Heroic dungeon achievements to unlock the Red Proto-Drake mount. This requires completing specific boss kills or objectives in each dungeon.", x = 2 },
        [2137] = { e = 5, s = "c", r = "Raid achievements; requires group, rare drops, RNG.", d = "Clear all listed 10-player raid achievements by defeating bosses under specific conditions. Coordinate with a group to handle these complex requirements efficiently.", x = 2 },
        [2138] = { e = 5, s = "c", r = "Raid achievements; requires group, rare drops, RNG.", d = "Complete the same set of objectives as the 10-player version but in 25-player raids. Ensure your entire raid group is ready for these larger encounters.", x = 2 },
        [2139] = { e = 4, s = "c", r = "Specific Naxxramas kill condition; moderate difficulty.", d = "Run Naxxramas in 25-player mode and defeat Heigan the Unclean without any raid member dying. This is a strict no-death requirement for the entire group.", x = 2 },
        [2140] = { e = 5, s = "s", r = "Requires specific group coordination and RNG in a raid.", d = "Defeat Grand Widow Faerlina in Naxxramas 25-player mode while preventing frenzy effects on yourself or others. Do not dispel her frenzy debuff to succeed.", x = 2 },
        [2141] = { e = 3, s = "g", r = "Collecting 10 mounts takes time but scales linearly.", d = "Collect ten unique mounts that can be used by a single character. This is account-wide, so gather them once and they count for all characters.", x = 2 },
        [2142] = { e = 3, s = "g", r = "Collecting 25 mounts is a longer grind than the previous one.", d = "Start by collecting basic starter mounts and daily rewards, then focus on rare drops from world bosses or dungeons. Remember this is account-wide, so coordinate with friends to share the grind efficiently.", x = 2 },
        [2143] = { e = 3, s = "g", r = "Collecting 50 mounts is a significant but steady grind.", d = "Once you have 25 mounts, continue hunting for rare spawns and completing mount-specific quests. This achievement chains directly after the previous one, so maintain your collection momentum without resetting your progress.", x = 2 },
        [2144] = { e = 4, s = "c", h = { 10459, 10462, 29069 }, r = "World events checklist; some sub-achievements are rare RNG.", d = "Complete all listed world event achievements first, as some may be time-gated or missable if events expire. Prioritize seasonal events like Winter Veil or Hallow's End to secure rare mounts and rewards quickly.", x = 2 },
        [2146] = { e = 5, s = "s", r = "Strict gear check and coordination make this very hard.", d = "Run Naxxramas 10-player with a frost-resistance capped group, ensuring no one exceeds 100 frost resist before pulling Sapphiron. Coordinate gear choices carefully to avoid accidental overcapping during the encounter setup.", x = 2 },
        [2147] = { e = 5, s = "s", r = "Same strict requirements as the 10-player version in a larger group.", d = "Gather a 25-player raid group for Naxxramas and ensure everyone wears low-frost-resist gear before engaging Sapphiron. This requires precise communication with your raid leader to manage resistances effectively.", x = 2 },
        [2148] = { e = 5, s = "s", r = "Requires specific mount and precise timing in a raid.", d = "Purchase or obtain a hover disk mount before attempting this fight, as you must ride it to deliver the killing blow to Scion of Eternity. Practice timing your kill on the boss while mounted to avoid accidental dismounts.", x = 2 },
        [2149] = { e = 5, s = "s", r = "Same strict requirements as the 10-player version in a larger group.", d = "Similar to the 10-player version, secure a hover disk and coordinate with a large group for the 25-player run. Ensure your mount is equipped before entering the instance to avoid delays during the encounter.", x = 2 },
        [2150] = { e = 5, s = "s", r = "Highly precise timing and coordination required for both splits.", d = "Defeat Grand Magus Telestra on Heroic by killing all her images within five seconds of each split. Communicate clearly with your party to synchronize image kills and avoid missing any splits.", x = 2 },
        [2151] = { e = 4, s = "s", r = "Requires specific mechanics execution and RNG on a heroic boss.", d = "Monitor Trollgore's Consume stacks closely in Drak'Tharon Keep, aiming to kill him before reaching ten stacks. Use high-damage abilities or cooldowns strategically to accelerate the fight without triggering the mechanic prematurely.", x = 2 },
        [2152] = { e = 4, s = "s", r = "Requires full group coordination and specific mechanic triggers.", d = "Ensure at least five unique party members get impaled during Gal'darah's fight by positioning yourself and others near the boss's attack zones. Coordinate movement to maximize impale chances without compromising survival.", x = 2 },
        [2153] = { e = 4, s = "s", r = "Heroic Violet Hold with strict no-kill mechanic.", d = "Avoid killing any void sentries while fighting Zuramat in The Violet Hold, as this will fail the achievement. Focus your damage on Zuramat and use crowd control abilities to protect nearby sentries from accidental hits.", x = 2 },
        [2154] = { e = 4, s = "s", r = "Heroic Halls of Stone with strict tanking.", d = "Protect Brann Bronzebeard at all costs during the Tribunal of Ages encounter by using shields or taunts to draw aggro away from him. Coordinate with healers and tanks to keep him safe throughout the entire fight.", x = 2 },
        [2155] = { e = 3, s = "g", r = "Heroic Halls of Stone plus killing sludges.", d = "Pull Sjonnir on Heroic and immediately focus on the Iron Sludge adds. Ensure your group prioritizes killing five sludges before or during the fight without letting them spawn too many times.", x = 2 },
        [2156] = { e = 4, s = "s", r = "Heroic Utgarde with strict single-pass mechanic.", d = "Start by defeating Grauf in a single run to unlock Skadi's mechanics. Once unlocked, defeat Skadi on Heroic difficulty in Utgarde Pinnacle to complete this achievement.", x = 2 },
        [2157] = { e = 4, s = "s", r = "Heroic Utgarde with strict Bane avoidance.", d = "Pull King Ymiron on Heroic and coordinate with your party to avoid triggering the Bane mechanic entirely. Communicate clearly so no one accidentally activates the boss's special ability.", x = 2 },
        [2176] = { e = 4, s = "s", r = "Naxx Heroic 4 Horsemen timing coordination.", d = "Run Naxxramas in 10-player mode and time the deaths of the Four Horsemen so they all occur within fifteen seconds. Use cooldowns or damage boosts to synchronize their final blows.", x = 2 },
        [2177] = { e = 4, s = "s", r = "Naxx Heroic 4 Horsemen timing in 25.", d = "Gather a full twenty-five player group for Naxxramas and repeat the synchronization strategy used for the ten-player version. Ensure all four Horsemen die within the same fifteen-second window.", x = 2 },
        [2178] = { e = 4, s = "s", r = "Naxx Heroic Thaddius charge avoidance.", d = "Defeat Thaddius in 10-player mode while keeping your entire raid away from both the positive and negative charge zones. Coordinate movement carefully to avoid crossing the electrified areas.", x = 2 },
        [2179] = { e = 4, s = "s", r = "Naxx Heroic Thaddius charge avoidance in 25.", d = "Assemble a twenty-five player group for Naxxramas and defeat Thaddius without anyone touching the charged platforms. Maintain strict positioning to prevent accidental contact with the hazards.", x = 2 },
        [2180] = { e = 3, s = "s", r = "Naxx Heroic Thaddius with low player count.", d = "Gather fewer than nine players for a Naxxramas run to face Thaddius. Ensure your small group avoids the charge zones while defeating him in this undermanned scenario.", x = 2 },
        [2181] = { e = 3, s = "s", r = "Naxx Heroic Thaddius with very low count.", d = "Form a group with fewer than twenty-one players for Naxxramas and defeat Thaddius without touching the charges. This requires careful coordination to manage the raid size and avoid hazards.", x = 2 },
        [2182] = { e = 4, s = "s", r = "Naxx Heroic Loatheb strict no-spore kill.", d = "Run Loatheb in 10-player mode and ignore all spore adds completely. Focus your damage on the boss while letting spores despawn naturally or avoiding them entirely to prevent accidental kills.", x = 2 },
        [2183] = { e = 5, s = "c", r = "Requires perfect execution in a high-difficulty 25-player raid.", d = "Assemble a twenty-five player group for Naxxramas and defeat Loatheb without killing any spores. Coordinate with your raid to avoid damaging spore adds during the encounter.", x = 2 },
        [2184] = { e = 3, s = "g", r = "Requires killing specific adds during a standard boss fight.", d = "Pull Kel'Thuzad in 10-player mode and kill at least eighteen abominations in his chamber before defeating him. Prioritize clearing the adds while managing the boss's mechanics effectively.", x = 2 },
        [2185] = { e = 4, s = "g", r = "High-difficulty raid with strict add kill count requirement.", d = "Focus on killing Abominations in Kel'Thuzad's chamber immediately after spawning to reach the count of 18 before defeating him. Ensure your group prioritizes these adds over the boss to avoid wasting time-gated progress.", x = 2 },
        [2186] = { e = 5, s = "c", r = "Requires flawless performance across all Naxxramas bosses.", d = "This is a high-difficulty legacy achievement requiring zero deaths across all Naxxramas bosses in one lockout. Coordinate with your raid leader to use defensive cooldowns and healers wisely, as any death resets the entire progress.", x = 2 },
        [2187] = { e = 4, s = "c", r = "Requires flawless performance across all Naxxramas bosses.", d = "Similar to The Immortal but for ten-player mode, this requires perfect execution without any deaths. Practice boss mechanics thoroughly and communicate constantly with your healer to maintain zero casualties throughout the raid.", x = 2 },
        [2188] = { e = 3, s = "g", r = "Fast-paced kill count requiring high DPS and coordination.", d = "Spawn the Rookery Whelps and immediately use high-damage abilities or AoE attacks to kill 50 within 15 seconds. You will likely need to repeat this many times as it is a cumulative account-wide goal.", x = 0 },
        [2189] = { e = 4, s = "c", r = "Requires multiple successful runs of a specific PvP mode.", d = "Equip a turret and focus fire on enemy vehicles during a single PvP battle to destroy five of them. Coordinate with your team to suppress defenders so you can safely operate the turret without being interrupted.", x = 0 },
        [2190] = { e = 3, s = "g", r = "Requires multiple successful runs of a specific PvP objective.", d = "Target players carrying Seaforium in Arathi Basin and kill them quickly to secure this account-wide achievement. Focus on high-value targets while avoiding unnecessary deaths that could prolong the battle.", x = 0 },
        [2191] = { e = 4, s = "g", r = "Requires accumulating many kills in a specific PvP zone.", d = "Engage enemies aggressively in the Courtyard of the Ancients during Arathi Basin to accumulate kills. This is a cumulative account-wide goal, so participate frequently in PvP battles to reach the total of 100.", x = 0 },
        [2192] = { e = 3, s = "s", r = "Single battle objective with strict vehicle preservation.", d = "Defend your siege vehicles at all costs during Strand of the Ancients battles. Avoid risky engagements that could lead to vehicle destruction, as losing even one prevents completion of this specific requirement.", x = 0 },
        [2193] = { e = 4, s = "c", r = "Requires multiple successful runs of a specific PvP objective.", d = "Plant Seaforium charges against walls in Arathi Basin and ensure they detonate successfully to damage the structure. Repeat this process until you have planted five damaging charges in a single battle for the account-wide goal.", x = 0 },
        [2194] = { e = 5, s = "c", h = { 8972, 8976, 8983 }, r = "Requires completing many difficult Strand of the Ancients tasks.", d = "Complete all listed Strand of the Ancients sub-achievements first, as this is a summary achievement. Prioritize the specific tasks like defending walls and destroying vehicles to unlock this final title.", x = 2 },
        [2199] = { e = 4, s = "c", r = "Grind 10 kills across 10 different Wintergrasp zones.", d = "Rotate through different Wintergrasp zones to kill ten players in each area listed. Use ranged classes or kiting tactics to safely accumulate kills without taking excessive damage from the opposing team.", x = 2 },
        [2200] = { e = 5, s = "s", r = "Requires perfect defense against all attackers simultaneously.", d = "Defend the beach walls in Strand of the Ancients by repelling attackers and repairing damage quickly. Losing any wall resets progress for this specific requirement, so maintain constant vigilance during the battle.", x = 0 },
        [2256] = { e = 4, s = "c", h = { 9829, 9830, 9831 }, r = "Kill one of many extremely rare Northrend bosses.", d = "Start by farming rare Northrend mobs like Loque'nahak or Old Crystalbark, as these are often missable due to time gates. Focus on specific zones where they spawn and be prepared for high difficulty encounters. Complete this before moving to the full list in Frostbitten.", x = 2 },
        [2257] = { e = 5, s = "c", h = { 8950, 8951, 8952 }, r = "Grind all extremely rare Northrend bosses after first set.", d = "This requires finishing Northern Exposure first, so ensure all previous rare kills are done. Farm remaining mobs systematically across Northrend, noting that some may have limited spawn times or require specific conditions. Plan your route to minimize travel time between zones.", x = 2 },
        [2357] = { e = 4, s = "s", r = "Legacy quest requiring specific class and old content.", d = "Complete the warlock quest line for the Dreadsteed of Xoroth, which is a legacy achievement with no points. Ensure you follow the correct quest chain and do not miss any steps, as this content may be unavailable in current expansions.", x = 2 },
        [2358] = { e = 4, s = "s", r = "Legacy quest requiring specific class and old content.", d = "Finish the paladin quest to obtain a Charger, which is a legacy achievement with no points. Follow the quest chain carefully, as missing steps could make it impossible to complete if the content is no longer available.", x = 2 },
        [2359] = { e = 4, s = "s", r = "Legacy quest requiring specific class and old content.", d = "Complete the druid quest for Swift Flight Form, another legacy achievement with no points. Ensure you follow the correct quest chain and do not miss any steps, as this content may be unavailable in current expansions.", x = 2 },
        [2416] = { e = 3, s = "s", r = "Time-limited event with RNG element during Noblegarden.", d = "Participate in Noblegarden events to lay an egg in Un'Goro Crater's Golakka Hot Springs as a rabbit. This is time-gated to the event period, so check the calendar and prepare your pet beforehand.", x = 2 },
        [2417] = { e = 3, s = "g", r = "Collect 25 event items available only during Noblegarden.", d = "Eat 25 Noblegarden Chocolates during the event, which is part of a chain leading to Chocoholic. Monitor your count carefully, as missing the event window will make this unachievable.", x = 2 },
        [2418] = { e = 3, s = "g", r = "Collect 100 event items available only during Noblegarden.", d = "Consume 100 Noblegarden Chocolates after completing Chocolate Lover, continuing the time-gated event chain. Keep track of your progress and ensure you finish within the event duration to avoid missing out.", x = 2 },
        [2419] = { e = 3, s = "c", r = "Find pets in four specific towns during Noblegarden.", d = "Find your pet Spring Rabbit another companion in each listed town during Noblegarden. Visit Azure Watch, Dolanaar, Goldshire, and Kharanos sequentially, ensuring you complete all towns before the event ends.", x = 2 },
        [2420] = { e = 3, s = "s", r = "Place an item in a specific location during event.", d = "Hide a Brightly Colored Egg in Silvermoon City during Noblegarden, which is time-gated to the event period. Locate the correct hiding spot early, as missing the event will make this unachievable.", x = 2 },
        [2421] = { e = 1, s = "s", r = "Pick up an egg and hide it in Stormwind.", d = "Hide a Brightly Colored Egg in Stormwind City during Noblegarden, another time-gated task. Find the designated location quickly, as the event window is limited and may not recur.", x = 2 },
        [2422] = { e = 1, s = "c", r = "Use flowers on anyone; trivial for all races.", d = "Use Spring Flowers to place rabbit ears on players of each race listed during Noblegarden. Visit all races' towns or gather groups to complete this efficiently before the event ends.", x = 2 },
        [2436] = { e = 2, s = "g", r = "Plant flowers in five desert zones quickly.", d = "Use the Spring Florist's Pouch during Noblegarden week to plant flowers in all listed desert zones. This is a time-gated event, so you must wait for the specific holiday to complete it.", x = 2 },
        [2476] = { e = 3, s = "c", h = { 9971, 9972, 9973 }, r = "Destroy four vehicles; requires PvP participation.", d = "Queue for Wintergrasp and destroy every listed vehicle type while the zone is active. You can do this solo or with friends, but ensure the PvP instance is running first.", x = 2 },
        [2497] = { e = 2, s = "g", r = "Find pets in four towns; simple interaction.", d = "Participate in Noblegarden to find a Spring Rabbit partner in each town listed. This requires the holiday event to be active and is account-wide.", x = 2 },
        [2516] = { e = 3, s = "g", r = "Collect 75 unique pets; requires hunting or buying.", d = "Catch or purchase 75 unique pets from various sources like dungeons, raids, and world drops. Keep track of your collection as some pets are missable once their source content is no longer available.", x = 2 },
        [2536] = { e = 4, s = "g", r = "Grind for 100 mounts; many are rare drops.", d = "Grind for mounts by completing quests, defeating bosses, and trading with other players until you own 100 unique ones. This is a long-term goal that benefits from account-wide progress.", x = 2 },
        [2537] = { e = 4, s = "g", r = "Grind for 100 mounts; many are rare drops.", d = "Similar to the previous mount achievement, focus on acquiring 100 distinct mounts usable by your character. Prioritize rare drops and quest rewards to speed up completion.", x = 2 },
        [2556] = { e = 3, s = "g", r = "Kill various pests across multiple zones.", d = "Kill various pests found in different zones like Northrend and Outland. These mobs are often common but require visiting multiple regions to find all species.", x = 2 },
        [2557] = { e = 1, s = "s", r = "Use /love command on listed critters instantly.", d = "Use the /love command on specific critters in Northrend and other areas. Ensure you visit every zone where these creatures spawn to avoid missing any.", x = 2 },
        [2576] = { e = 1, s = "s", r = "Wear specific items and kiss an NPC or player.", d = "Wear the specified tuxedo outfit and kiss a player in an elegant dress during Noblegarden. This is a social event requiring coordination with another player.", x = 2 },
        [2676] = { e = 1, s = "s", r = "Find a brightly colored egg in Stormwind.", d = "Search for brightly colored eggs dropped by specific mobs or found in certain areas during Noblegarden. These drops are rare, so be patient and thorough.", x = 2 },
        [2716] = { e = 1, s = "s", r = "Visit class trainer at level 30.", d = "Visit your class trainer at level 30 to activate Dual Talent Specialization. This is a one-time action that unlocks additional talent points for your character.", x = 2 },
        [2756] = { e = 2, s = "g", r = "Train to become an Aspirant.", d = "Travel to the Argent Tournament in Northrend and complete the initial training quests to become an Aspirant. This starts the chain of achievements for the tournament.", x = 2 },
        [2758] = { e = 2, s = "g", r = "Train to become a Valiant.", d = "Start by completing the initial Argent Tournament quests to become a Valiant. This is time-gated as you must reach level 60 and complete specific pre-reqs before accessing the tournament grounds.", x = 2 },
        [2760] = { e = 4, s = "c", h = { 7112 }, r = "Grind 42k rep with Darnassus.", d = "Focus on earning reputation with Darnassus by completing daily quests and turning in items. You need Exalted status and the Champion title to unlock this achievement permanently.", x = 2 },
        [2761] = { e = 4, s = "c", h = { 7898 }, r = "Grind 42k rep with Exodar.", d = "Grind reputation with the Exodar faction through their specific dailies and world drops. Ensure you have the base Champion title before attempting to reach Exalted for this reward.", x = 2 },
        [2762] = { e = 4, s = "c", h = { 6993 }, r = "Grind 42k rep with Gnomeregan.", d = "Complete daily quests for Gnomeregan Exiles to gain reputation quickly. This achievement requires both the Champion title and Exalted status with that specific faction.", x = 2 },
        [2763] = { e = 4, s = "c", h = { 11151 }, r = "Grind 42k rep with Ironforge.", d = "Turn in items and complete dailies for Ironforge to build up your reputation. You must first obtain the Champion of Ironforge title before reaching Exalted status.", x = 2 },
        [2764] = { e = 4, s = "c", h = { 10358 }, r = "Grind 42k rep with Stormwind.", d = "Grind Stormwind reputation by doing their daily quests and turning in world drops. This achievement unlocks only after you have both the Champion title and Exalted standing.", x = 2 },
        [2765] = { e = 4, s = "c", h = { 7901 }, r = "Grind 42k rep with Orgrimmar.", d = "Focus on Orgrimmar dailies and reputation gains to reach Exalted status. You need the base Champion of Orgrimmar title as a prerequisite for this specific achievement.", x = 2 },
        [2766] = { e = 4, s = "c", h = { 14358 }, r = "Grind 42k rep with Sen'jin.", d = "Complete daily quests for Sen'jin Village to earn Darkspear Troll reputation. Reach Exalted and secure the Champion title before claiming this achievement reward.", x = 2 },
        [2767] = { e = 4, s = "c", h = { 8473 }, r = "Grind 42k rep with Silvermoon.", d = "Grind Silvermoon City reputation through their specific dailies and world drops. You must hold the Champion of Silvermoon title and be Exalted to complete this.", x = 2 },
        [2768] = { e = 4, s = "c", h = { 8561 }, r = "Grind 42k rep with Thunder Bluff.", d = "Turn in items and do dailies for Thunder Bluff to gain reputation. This achievement requires you to be Exalted with Thunder Bluff and hold the Champion title.", x = 2 },
        [2769] = { e = 4, s = "g", r = "Requires exalted reputation grind with Undercity faction.", d = "Complete Undercity daily quests and turn in world drops to build reputation. You need the Champion of the Undercity title and Exalted status to finish this.", x = 2 },
        [2770] = { e = 5, s = "c", h = { 8505, 8509, 8506 }, r = "Requires exalted with all Alliance factions; heavy grind.", d = "You must complete all individual faction achievements listed in the requirements first. This account-wide achievement unlocks only after every single race's champion title is obtained.", x = 2 },
        [2771] = { e = 5, s = "c", h = { 8564, 8565, 8568 }, r = "Requires exalted with all Horde factions; heavy grind.", d = "Complete all individual 'Champion' achievements for every Horde faction first. Once finished, earn exalted reputation with the Argent Tournament to unlock this account-wide title.", x = 2 },
        [2772] = { e = 3, s = "s", r = "Requires defeating a player in mounted duels.", d = "Locate the mounted duel arena at the Argent Tournament and defeat any other player there. This can be done solo or by asking a friend for help.", x = 2 },
        [2773] = { e = 4, s = "g", r = "Requires unmasking and defeating the Black Knight repeatedly.", d = "Find the Black Knight in the tournament grounds and engage him in combat to unmask and defeat him. Ensure you have enough health potions before starting this fight.", x = 2 },
        [2777] = { e = 3, s = "s", r = "Requires completing Darnassus faction quests for tournament entry.", d = "Earn reputation with Darnassus until you qualify for the Argent Tournament representation. Complete any prerequisite quests if available in your region.", x = 2 },
        [2778] = { e = 3, s = "s", r = "Requires completing Exodar faction quests for tournament entry.", d = "Gain sufficient reputation with the Exodar to earn the right to represent them at the tournament. Check local quest boards for specific reputation gainers.", x = 2 },
        [2779] = { e = 3, s = "s", r = "Requires completing Gnomeregan faction quests for tournament entry.", d = "Complete quests and earn reputation with Gnomeregan Exiles to unlock their representation rights. This may require visiting specific zones or dungeons.", x = 2 },
        [2780] = { e = 3, s = "s", r = "Requires completing Ironforge faction quests for tournament entry.", d = "Reach the required reputation level with Ironforge to become their champion at the tournament. Focus on daily quests in Durotar for efficient gains.", x = 2 },
        [2781] = { e = 3, s = "s", r = "Requires completing Stormwind faction quests for tournament entry.", d = "Earn enough reputation with Stormwind to represent them at the Argent Tournament. Visit Stormwind City and complete available quests or turn-ins.", x = 2 },
        [2782] = { e = 5, s = "c", h = { 2160, 2161, 2162 }, r = "Requires exalted with all Alliance factions; heavy grind.", d = "Unlock representation rights for every Alliance faction before attempting this achievement. It is account-wide, so coordinate with friends if needed.", x = 2 },
        [2783] = { e = 3, s = "s", r = "Requires completing Orgrimmar faction quests for tournament entry.", d = "Complete the necessary quests and reputation tasks to represent Orgrimmar at the tournament. Start with daily quests in Durotar for quick progress.", x = 2 },
        [2784] = { e = 2, s = "s", r = "Talk to NPC in Orgrimmar.", d = "Earn reputation with Sen'jin Village to unlock their representation rights. Look for specific quest chains or reputation vendors nearby.", x = 2 },
        [2785] = { e = 2, s = "s", r = "Talk to NPC in Silvermoon.", d = "Gain enough reputation with Silvermoon City to represent them at the tournament. Focus on quests in Eastern Plaguelands and Silvermoon itself.", x = 2 },
        [2786] = { e = 2, s = "s", r = "Talk to NPC in Thunder Bluff.", d = "Start by completing the Argent Tournament intro quests to unlock Thunder Bluff representation. Focus on winning races or defeating champions there to earn your faction's title.", x = 2 },
        [2787] = { e = 2, s = "s", r = "Talk to NPC in Undercity.", d = "Complete the initial Argent Tournament storyline to gain access to Undercity representation. Participate in local events and races to unlock this specific champion status.", x = 2 },
        [2788] = { e = 4, s = "c", h = { 3426, 3427, 3428 }, r = "Requires exalted status with all Horde factions.", d = "Unlock every individual Horde faction champion title first by visiting their respective tournament rings. Once all are earned, the combined Champion of the Horde achievement will complete automatically.", x = 2 },
        [2796] = { e = 1, s = "s", r = "Join club at Brewfest event.", d = "Visit any tavern during Brewfest to join the Brew of the Month club instantly. This is a simple one-time interaction with no combat or complex requirements involved.", x = 2 },
        [2798] = { e = 3, s = "c", h = { 29040 }, r = "Requires completing specific seasonal garden tasks.", d = "Complete all individual Noblegarden sub-achievements listed in the info field before claiming this umbrella title. Ensure you finish every specific event task to unlock the Noble Gardener status.", x = 2 },
        [2816] = { e = 5, s = "c", h = { 10316, 10317, 10318 }, r = "Needs exalted status with all Horde factions.", d = "Unlock and complete the base champion achievements for every Horde faction at the Argent Tournament first. After securing all individual titles, defeat the top rider in each ring to finish this challenge.", x = 2 },
        [2817] = { e = 5, s = "c", h = { 10740, 10741, 10736 }, r = "Needs exalted status with all Alliance factions.", d = "Earn Exalted reputation with every Alliance faction at the Argent Tournament to unlock the Crusader title. This requires extensive grinding of daily quests and tournaments across all zones. Ensure you complete all necessary sub-achievements for each race before moving on to the next.", x = 2 },
        [2836] = { e = 4, s = "c", h = { 8518, 8520, 8521 }, r = "Requires winning races against every faction.", d = "Best a rider from every racial faction at the Argent Tournament by winning their specific tournaments. This is purely skill-based and requires practice with different mounts and tactics. There are no time gates, but you must visit each tournament location to unlock the respective races.", x = 2 },
        [2886] = { e = 3, s = "s", r = "Defeat Ulduar Siege bosses in 10-man.", d = "Defeat all four bosses listed in the info field within Ulduar using a 10-player group. Ensure you clear the Siege area specifically, as other raid zones do not count toward this legacy goal.", x = 2 },
        [2887] = { e = 3, s = "s", r = "Defeat Ulduar Siege bosses in 25-man.", d = "Gather a 25-player group to defeat the same four bosses found in the Siege area of Ulduar. This requires higher gear and coordination than the 10-player version but follows the same boss list.", x = 2 },
        [2888] = { e = 4, s = "c", h = { 7863, 7864, 7862 }, r = "Requires defeating three specific raid bosses in 10-player mode.", d = "Clear all three bosses listed in the Antechamber area using a 10-player group. Focus on defeating Assembly of Iron, Kologarn, and Auriaya to complete this legacy objective.", x = 2 },
        [2889] = { e = 5, s = "c", h = { 14402, 14403, 14404 }, r = "Requires defeating three specific raid bosses in 25-player mode.", d = "Assemble a 25-player group to defeat the three Antechamber bosses: Assembly of Iron, Kologarn, and Auriaya. This is a legacy raid goal that requires high-level gear and coordination.", x = 2 },
        [2890] = { e = 4, s = "c", h = { 12576, 12578, 12577 }, r = "Requires defeating three specific raid bosses in 10-player mode.", d = "Queue for Ulduar 10-man and defeat Hodir, Thorim, Freya, and Mimiron in any order. Ensure you complete these before the raid lockout expires to avoid missing out.", x = 2 },
        [2891] = { e = 5, s = "c", h = { 10323, 10324, 10325 }, r = "Requires defeating three specific raid bosses in 25-player mode.", d = "Queue for Ulduar 25-man and defeat Hodir, Thorim, Freya, and Mimiron in any order. Ensure you complete these before the raid lockout expires to avoid missing out.", x = 2 },
        [2892] = { e = 4, s = "c", h = { 7529, 7528 }, r = "Requires defeating two specific raid bosses in 10-player mode.", d = "Queue for Ulduar 10-man and defeat General Vezax and Yogg-Saron within your weekly lockout. Note that this achievement is account-wide, so any character on your account can claim it.", x = 2 },
        [2893] = { e = 5, s = "c", h = { 10721, 10720 }, r = "Requires defeating two specific raid bosses in 25-player mode.", d = "Queue for Ulduar 25-man and defeat General Vezax and Yogg-Saron within your weekly lockout. Note that this achievement is account-wide, so any character on your account can claim it.", x = 2 },
        [2894] = { e = 5, s = "c", h = { 12342, 12345 }, r = "Requires clearing all four Ulduar raid sections in 10-player mode.", d = "Complete all four Ulduar raid sections in 10-player mode during a single week to unlock the account-wide achievement. Plan your runs carefully as you cannot restart once the lockout hits.", x = 2 },
        [2895] = { e = 5, s = "c", h = { 14109, 14107 }, r = "Requires clearing all four Ulduar raid sections in 25-player mode.", d = "Complete all four Ulduar raid sections in 25-player Heroic mode during a single week to unlock the account-wide achievement. Plan your runs carefully as you cannot restart once the lockout hits.", x = 2 },
        [2903] = { e = 5, s = "c", r = "Requires perfect runs (no deaths) through all Ulduar raids in 10-player.", d = "Defeat every boss in Ulduar 10-man without any deaths during each encounter within a single lockout period. This is extremely difficult and requires a highly skilled group with zero tolerance for mistakes.", x = 2 },
        [2904] = { e = 5, s = "c", r = "Requires perfect runs (no deaths) through all Ulduar raids in 25-player.", d = "Defeat every boss in Ulduar 25-man without any deaths during each encounter within a single lockout period. This is extremely difficult and requires a highly skilled group with zero tolerance for mistakes.", x = 2 },
        [2905] = { e = 4, s = "s", r = "Requires a specific RNG outcome on Flame Leviathan without repairs.", d = "Queue for Flame Leviathan in 10-man and defeat it on the first try without anyone repairing their vehicle. Coordinate with your group to ensure no one repairs before the kill is secured.", x = 2 },
        [2906] = { e = 5, s = "s", r = "Requires a specific RNG outcome on Flame Leviathan in 25-player.", d = "Queue for Flame Leviathan in 25-man and defeat it on the first try without anyone repairing their vehicle. Coordinate with your group to ensure no one repairs before the kill is secured.", x = 2 },
        [2907] = { e = 4, s = "c", h = { 8995, 8996, 8997 }, r = "Requires defeating Flame Leviathan in three specific vehicles.", d = "Defeat Flame Leviathan in 10-player mode while using each of the three available vehicles. This is a legacy achievement that may become unobtainable if the vehicle system is removed. Coordinate with your group to switch vehicles between pulls without causing a System Shutdown.", x = 2 },
        [2908] = { e = 4, s = "c", h = { 7822, 7820, 7821 }, r = "Requires defeating Flame Leviathan in three specific vehicles.", d = "Defeat Flame Leviathan in 25-player mode while using each of the three available vehicles. Similar to the 10-player version, this is time-gated by potential removal of the vehicle system. Ensure your group can handle the increased difficulty and coordinate vehicle switches effectively.", x = 2 },
        [2909] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Destroy a Flame Leviathan Defense Turret in 10-player mode during the raid encounter. This is part of a larger set of legacy achievements tied to the vehicle system. Focus on destroying turrets early in the fight before switching vehicles to avoid missing this objective.", x = 2 },
        [2910] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Destroy a Flame Leviathan Defense Turret in 25-player mode during the raid encounter. Like the 10-player version, this is time-gated by potential removal of the vehicle system. Coordinate with your group to prioritize turret destruction before switching vehicles.", x = 2 },
        [2911] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Defeat Flame Leviathan in 10-player mode without causing a System Shutdown during the encounter. This requires careful management of the raid's health and avoiding actions that trigger shutdowns. Practice this with your group to ensure you can complete the fight without triggering the shutdown mechanic.", x = 2 },
        [2912] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Defeat Flame Leviathan in 25-player mode without causing a System Shutdown during the encounter. Similar to the 10-player version, this is time-gated by potential removal of the vehicle system. Coordinate with your group to manage health and avoid shutdowns while switching vehicles.", x = 2 },
        [2913] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Queue for the Flame Leviathan raid and ensure at least one Orbital Defense System is active before killing the boss. This is a time-gated legacy achievement that requires specific mechanics during the fight.", x = 2 },
        [2914] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Complete the previous 10-player achievement first, then run the raid again with two Orbital Defense Systems active simultaneously. Coordinate with your group to maintain both systems until the boss is defeated.", x = 2 },
        [2915] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Finish the prior 10-player chain and bring three Orbital Defense Systems online before defeating Flame Leviathan. This requires precise timing and coordination as a legacy raid achievement.", x = 2 },
        [2916] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "Unlock this by completing the 10-player version first, then run the 25-player mode with two systems active. Ensure you have enough players to fill the raid before starting the encounter.", x = 2 },
        [2917] = { e = 5, s = "s", r = "Requires specific raid mechanics and high-level gear.", d = "Complete the previous 25-player chain and activate three Orbital Defense Systems before killing Flame Leviathan. This is a legacy achievement requiring specific group coordination in 25-player mode.", x = 2 },
        [2918] = { e = 4, s = "s", r = "Requires specific raid mechanics and high-level gear.", d = "Queue for the 25-player Flame Leviathan raid and keep one Orbital Defense System active throughout the fight. You must complete this before unlocking the higher system count achievements in 25-player mode.", x = 2 },
        [2919] = { e = 4, s = "s", r = "High-skill raid boss fight with strict mechanic.", d = "Queue for Razorscale in 10-man and defeat her while limiting her flight phase to exactly once. Communicate clearly with your team to avoid triggering extra flights that will fail the achievement.", x = 2 },
        [2921] = { e = 5, s = "s", r = "Very hard 25-man version of difficult boss.", d = "Queue for Razorscale in 25-man and defeat her while limiting her flight phase to exactly once. Communicate clearly with your team to avoid triggering extra flights that will fail the achievement.", x = 2 },
        [2923] = { e = 4, s = "g", r = "Grinding 25 specific kills with strict mechanic.", d = "Run Razorscale in 10-man and focus on dodging his Flame Breath while tanking Dark Rune Guardian Dwarves. Ensure your group has high damage output to kill the dwarves quickly before they heal back up.", x = 2 },
        [2924] = { e = 5, s = "g", r = "Hard 25-man grind requiring precise boss mechanics.", d = "Run Razorscale in 25-man using a dedicated Flame Breath dodging strategy similar to the 10-man version. Coordinate with your raid leader to ensure consistent positioning for all players.", x = 2 },
        [2925] = { e = 3, s = "s", r = "Moderate skill check on specific boss mechanic.", d = "In Ignis, wait for the Iron Constructs to spawn and shatter both within five seconds before killing him. This requires precise timing and coordination between your raid members.", x = 2 },
        [2926] = { e = 4, s = "s", r = "Harder 25-man version of mechanic-based fight.", d = "Repeat the Ignis strategy in 25-man by shattering two Iron Constructs quickly before defeating the boss. Ensure your group is ready to act immediately when the constructs appear.", x = 2 },
        [2927] = { e = 3, s = "s", r = "Moderate chance to survive specific boss event.", d = "Survive being thrown into Ignis's Slag Pot by staying alive after the throw occurs. This often happens during specific phases of the fight, so be prepared for unexpected damage.", x = 2 },
        [2928] = { e = 4, s = "s", r = "Harder 25-man version of survival mechanic.", d = "Run the same Slag Pot survival mechanic in 25-man mode. Timing and positioning are key to surviving the throw without taking fatal damage from the pot.", x = 2 },
        [2929] = { e = 3, s = "s", r = "Moderate speedrun requiring specific boss mechanics.", d = "Defeat Ignis within four minutes in 25-man by optimizing your rotation and minimizing downtime. Use efficient cooldowns and avoid unnecessary deaths to stay under the time limit.", x = 2 },
        [2930] = { e = 4, s = "s", r = "Harder 10-man speedrun with strict mechanic.", d = "Run Ignis in 10-man with a focus on speed, aiming to defeat him within four minutes. Coordinate your damage output and minimize any delays during the fight.", x = 2 },
        [2931] = { e = 4, s = "s", r = "High-skill raid fight requiring precise boss management.", d = "In XT-002 Deconstructor, prevent XS-013 from healing by interrupting or killing it before it can recover health. This requires careful monitoring of both bosses and quick reactions.", x = 2 },
        [2932] = { e = 5, s = "s", r = "Very hard 25-man version of complex boss fight.", d = "Repeat the XT-002 strategy in 25-man to stop XS-013 from healing. Ensure your raid is prepared to handle the additional complexity of managing two bosses simultaneously.", x = 2 },
        [2933] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Use XE-321 Boombots to kill 20 XS-013 Scrapbots within twelve seconds. This requires precise timing and coordination with your raid to maximize the boombot's effectiveness.", x = 2 },
        [2934] = { e = 5, s = "s", r = "High skill ceiling; requires perfect mechanics execution.", d = "Defeat XT-002 Deconstructor without any raid member dying from a Gravity Bomb. Position players carefully and use defensive cooldowns to avoid fatal damage during the fight.", x = 2 },
        [2935] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Coordinate with your healer to use XE-321 Boombots on XS-013 Scrapbots immediately upon spawning. You must kill all twenty within twelve seconds or the timer expires.", x = 2 },
        [2936] = { e = 5, s = "s", r = "High skill ceiling; requires perfect mechanics execution.", d = "Assign a dedicated tank to pull XT-002 Deconstructor and ensure no raid member dies from Gravity Bombs. Use defensive cooldowns proactively during this encounter.", x = 2 },
        [2937] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Focus on speed kills for XT-002 Deconstructor in ten-player mode to finish under two hundred five seconds. Maintain high damage output throughout the fight.", x = 2 },
        [2938] = { e = 5, s = "s", r = "High skill ceiling; requires perfect mechanics execution.", d = "Coordinate your raid's damage rotation to defeat XT-002 Deconstructor within two hundred five seconds in twenty-five-player mode. Avoid unnecessary downtime or healing phases.", x = 2 },
        [2939] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Ensure Runemaster Molgeim is the last member alive when defeating the Assembly of Iron in ten-player mode. Protect him with healers and defensive abilities until the end.", x = 2 },
        [2940] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Protect Stormcaller Brundir as the final survivor during the Assembly of Iron encounter in ten-player mode. Use crowd control to manage adds threatening him.", x = 2 },
        [2941] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Keep Steelbreaker alive until the very end of the Assembly of Iron fight in ten-player mode. Prioritize his survival over other raid members during critical phases.", x = 2 },
        [2942] = { e = 5, s = "s", r = "High skill ceiling; requires perfect mechanics execution.", d = "In twenty-five-player mode, ensure Runemaster Molgeim survives as the last member alive against the Assembly of Iron. Coordinate healing resources to support him effectively.", x = 2 },
        [2943] = { e = 5, s = "s", r = "High skill ceiling; requires perfect mechanics execution.", d = "Protect Stormcaller Brundir until he is the sole survivor during the twenty-five-player Assembly of Iron encounter. Manage adds carefully to prevent him from dying early.", x = 2 },
        [2944] = { e = 5, s = "s", r = "High skill ceiling; requires perfect mechanics execution.", d = "Ensure Steelbreaker remains the last living member when defeating the Assembly of Iron in twenty-five-player mode. Focus healing on him while managing other threats.", x = 2 },
        [2945] = { e = 4, s = "c", r = "Requires specific flask + raid boss kill.", d = "Consume an Iron Boot Flask before starting the Assembly of Iron fight in ten-player mode. Maintain its effect throughout the entire encounter to complete the achievement.", x = 2 },
        [2946] = { e = 4, s = "c", r = "Requires specific flask + raid boss kill.", d = "Drink an Iron Boot Flask and keep its effect active while defeating the Assembly of Iron in twenty-five-player mode. Monitor the flask duration carefully during the fight.", x = 2 },
        [2947] = { e = 4, s = "c", r = "High skill ceiling; avoid damage on boss.", d = "Start by kiting Stormcaller Brundir away from the group to avoid Chain Lightning and Lightning Whirl. Keep him stunned or controlled until the raid is ready to wipe if necessary, as this fight requires precise timing.", x = 2 },
        [2948] = { e = 4, s = "c", r = "High skill ceiling; avoid damage on boss.", d = "Use the same kiting strategy as the 10-player version but coordinate with a larger group. Ensure everyone stays together so Brundir cannot isolate and cast his dangerous spells on individuals.", x = 2 },
        [2951] = { e = 4, s = "c", r = "Requires specific mechanic execution on boss.", d = "Focus your damage on Kologarn's core while ignoring the arms to keep them intact. Do not use area-of-effect abilities that might accidentally destroy the limbs before defeating the boss.", x = 2 },
        [2952] = { e = 4, s = "c", r = "Requires specific mechanic execution on boss.", d = "Similar to the 10-player version, concentrate all damage on Kologarn's body. Avoid spreading damage too widely to prevent destroying his arms prematurely during the encounter.", x = 2 },
        [2953] = { e = 4, s = "c", r = "Requires precise timing and damage control.", d = "Prioritize destroying both arms quickly before switching focus to Kologarn. You must kill the arms and then the boss within a strict 12-second window after the first arm dies.", x = 2 },
        [2954] = { e = 4, s = "c", r = "Requires precise timing and damage control.", d = "Coordinate with your group to rapidly destroy both arms before engaging Kologarn directly. Timing is critical here, as you need to finish the boss within 12 seconds of the last arm destruction.", x = 2 },
        [2955] = { e = 4, s = "c", r = "High skill ceiling; avoid specific mechanic.", d = "Position players carefully to avoid Focused Eyebeams, which target specific individuals. Use crowd control or movement abilities to ensure no one gets hit by these eye beams during the fight.", x = 2 },
        [2956] = { e = 4, s = "c", r = "High skill ceiling; avoid specific mechanic.", d = "In 25-player mode, maintain tight formation and use defensive cooldowns to avoid Focused Eyebeams. Communication is key to ensuring no raid member takes damage from this mechanic.", x = 2 },
        [2957] = { e = 4, s = "c", r = "Requires completing multiple complex raid tasks.", d = "Complete all listed Ulduar achievements first, as this one requires them. This includes defeating bosses under specific conditions and collecting rare drops like the Rusted Proto-Drake mount.", x = 2 },
        [2958] = { e = 4, s = "c", r = "Requires completing multiple complex raid tasks.", d = "Finish every required 25-player achievement before attempting this one. It grants the Ironbound Proto-Drake mount once all sub-achievements are completed, so plan your raid runs accordingly.", x = 2 },
        [2959] = { e = 4, s = "g", r = "Grinding 25 spawns while raiding adds significant time.", d = "Use abilities that spawn Rubble creatures to reach the count of 25 before defeating Kologarn. Monitor the counter closely and ensure you do not kill the boss until the requirement is met.", x = 2 },
        [2960] = { e = 4, s = "g", r = "Grinding 25 spawns while raiding adds significant time.", d = "Coordinate with your group to spawn enough Rubble creatures quickly. Once you hit 25 spawns, proceed to defeat Kologarn immediately to secure this achievement without resetting progress.", x = 2 },
        [2961] = { e = 4, s = "c", r = "High RNG chance to avoid a specific mechanic.", d = "Coordinate with your healer to avoid Flash Freeze adds entirely by kiting or using defensive cooldowns. This is a strict no-hit achievement where even one player touching the effect fails it permanently.", x = 2 },
        [2962] = { e = 4, s = "c", r = "High RNG chance to avoid a specific mechanic.", d = "Same strategy as the 10-player version but requires tighter coordination in a larger group to manage adds without taking damage. Ensure everyone knows exactly when to pull back from the boss.", x = 2 },
        [2963] = { e = 4, s = "c", r = "Requires precise positioning and luck with NPCs.", d = "Keep all friendly NPCs alive by avoiding AoE damage and not letting them die during mechanics. Do not use abilities that might accidentally kill a summoned pet or NPC helper.", x = 2 },
        [2965] = { e = 4, s = "c", r = "Requires precise positioning and luck with NPCs.", d = "Manage your group size carefully to protect NPCs in the larger raid format. Avoid pulling too many adds at once which could overwhelm your healers and cause NPC deaths.", x = 2 },
        [2967] = { e = 4, s = "c", r = "High RNG chance to avoid a specific mechanic.", d = "Monitor Biting Cold stacks closely and use cleansing abilities immediately before reaching three stacks. Coordinate with your healer to wipe stacks quickly if anyone gets hit.", x = 2 },
        [2968] = { e = 4, s = "c", r = "High RNG chance to avoid a specific mechanic.", d = "The larger group makes managing cold stacks harder due to more targets, so ensure everyone cleans up their debuffs promptly. Use defensive cooldowns proactively to prevent stacking too high.", x = 2 },
        [2969] = { e = 3, s = "s", r = "Requires specific buffs but no complex mechanics.", d = "Stack your buffs by waiting for the right moment when Toasty Fire, Storm Power, and Starlight are all active simultaneously. Coordinate with raid members who have these specific buffs.", x = 2 },
        [2970] = { e = 3, s = "s", r = "Requires specific buffs but no complex mechanics.", d = "In 25-player mode, finding three people with the required buffs at once is easier but requires precise timing. Wait for the boss phase where all three buff sources are available.", x = 2 },
        [2971] = { e = 4, s = "c", r = "High RNG chance to avoid a specific mechanic.", d = "Dodge Lightning Charge mechanics carefully and communicate clearly so no one stands in the lightning path. This is a strict no-hit achievement similar to the Flash Freeze requirement.", x = 2 },
        [2972] = { e = 4, s = "c", r = "High RNG chance to avoid a specific mechanic.", d = "The larger group increases the risk of someone missing a dodge roll, so emphasize communication and movement. Ensure everyone knows exactly where the lightning will strike before it happens.", x = 2 },
        [2973] = { e = 4, s = "c", h = { 9132 }, r = "Requires defeating three specific raid bosses in 10-player.", d = "Defeat Thorim while also killing the Ancient Rune Giant and Runic Colossus in the same run. This requires managing multiple bosses simultaneously without triggering any other failure conditions.", x = 2 },
        [2974] = { e = 5, s = "c", r = "Same bosses as 2973 but requires 25-player group.", d = "Same as the 10-player version but with more resources to handle the additional bosses. Coordinate your pulls to ensure all three targets are defeated in one continuous fight.", x = 2 },
        [2975] = { e = 4, s = "s", r = "Requires specific debuff during a boss fight.", d = "Use a haste trinket or food to gain Aura of Celerity before Thorim's fight. Ensure your group is ready for the 10-player encounter and avoid any mechanics that could interrupt your buff.", x = 2 },
        [2976] = { e = 5, s = "s", r = "Same as 2975 but requires 25-player group.", d = "Follow the same steps as the 10-player version but coordinate with a larger group. Maintain your haste buff throughout the entire Thorim encounter to secure the achievement.", x = 2 },
        [2977] = { e = 4, s = "c", r = "Requires specific boss mechanics and Sif presence.", d = "Keep Sif alive in the arena while pulling Thorim inside for the 10-player mode. Do not let Sif die before forcing Thorim into the arena to complete this step.", x = 2 },
        [2978] = { e = 5, s = "c", r = "Same as 2977 but requires 25-player group.", d = "Repeat the process with a 25-player group, ensuring Sif remains alive while dragging Thorim into the arena. Coordinate your pulls carefully to avoid accidental deaths.", x = 2 },
        [2979] = { e = 4, s = "c", r = "Requires defeating three specific bosses in quick succession.", d = "Kill Elder Brightleaf, Elder Ironbranch, and Elder Stonebark in rapid succession within 15 seconds. Use efficient rotations and cooldowns to minimize downtime between kills.", x = 2 },
        [2980] = { e = 3, s = "s", r = "Time limit makes it harder than normal but doable solo.", d = "Start the Conservatory of Life fight immediately and rush through adds to reach Freya within 20 minutes. Keep your damage high and avoid unnecessary delays during the encounter.", x = 2 },
        [2981] = { e = 4, s = "s", r = "Same as 2980 but requires 25-player group.", d = "Coordinate with a 25-player group to defeat Freya quickly after killing the first creature in the Conservatory of Life. Maintain momentum to stay under the time limit.", x = 2 },
        [2982] = { e = 4, s = "s", r = "Requires stacking debuff during a boss fight.", d = "Apply Attuned to Nature stacks to Freya before defeating her for the 10-player version. Ensure you have enough stacks by managing your abilities and cooldowns effectively.", x = 2 },
        [2983] = { e = 5, s = "s", r = "Same as 2982 but requires 25-player group.", d = "Repeat the process with a 25-player group, focusing on stacking Attuned to Nature on Freya before her defeat. Communicate with your team to maximize stack efficiency.", x = 2 },
        [2984] = { e = 4, s = "c", r = "Requires defeating multiple specific mobs in quick succession.", d = "Defeat the specified mobs in Underbog within 10 seconds using a coordinated 25-player group. Focus fire on the required targets and avoid pulling unnecessary adds.", x = 2 },
        [2985] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Follow the same strategy as the 25-player version but with a smaller group in Underbog. Ensure your team is ready to kill the mobs quickly within the time limit.", x = 2 },
        [2989] = { e = 4, s = "c", h = { 7600, 7601, 7602 }, r = "Mimiron requires perfect dodging of multiple mechanics.", d = "Defeat Mimiron in Ulduar while avoiding all proximity mines, rocket strikes, and bomb bots. Coordinate with your group to minimize damage taken from these specific abilities.", x = 2 },
        [2995] = { e = 4, s = "s", r = "Specific boss mechanic execution in 25-player mode.", d = "In 25-player Mimiron, ensure the Assault Bot targets you or a tank while he uses Rocket Strike to kill it. Coordinate with the bot's AI so its final attack hits the boss instead of your party.", x = 2 },
        [2996] = { e = 4, s = "s", r = "High-skill requirement to avoid specific raid-wide damage.", d = "For General Vezax in 10-player, use Shadow Dodge cooldowns immediately when the warning appears to avoid Shadow Crash. Ensure every raid member has their dodge ready before the boss casts the ability.", x = 2 },
        [2997] = { e = 4, s = "s", r = "High-skill requirement to avoid specific raid-wide damage.", d = "In 25-player Vezax, maintain strict dodging discipline as the raid cooldowns are more spread out. Communicate clearly so no one misses a Shadow Crash warning during the fight.", x = 2 },
        [3002] = { e = 4, s = "c", h = { 12061 }, r = "Algalon requires precise timing on multiple mechanics.", d = "To defeat Algalon in 25-player, close three Black Holes within ten seconds by having multiple players cast their abilities simultaneously. Practice timing this sequence to ensure all portals shut before the timer expires.", x = 2 },
        [3003] = { e = 4, s = "c", h = { 8239 }, r = "Algalon requires precise timing on multiple mechanics.", d = "In 10-player Algalon, coordinate your team to close three Black Holes within ten seconds using high-level portal abilities. Ensure everyone is ready to cast instantly when the mechanic triggers to avoid failure.", x = 2 },
        [3006] = { e = 4, s = "s", r = "Requires specific boss mechanic execution in a raid.", d = "Against Auriaya in 10-player, focus damage on her while ignoring the Sanctum Sentries completely. Do not attack the sentries or they will destroy your achievement progress permanently.", x = 2 },
        [3007] = { e = 4, s = "s", r = "Requires specific boss mechanic execution in a raid.", d = "In 25-player Auriaya, avoid damaging the Sanctum Sentries entirely while focusing fire on the boss. Any damage to the sentries will reset your progress and make the fight much harder.", x = 2 },
        [3008] = { e = 4, s = "s", r = "High-skill requirement to avoid insanity debuff in raid.", d = "For Yogg-Saron in 10-player, ensure no raid member goes insane by avoiding his gaze mechanic strictly. Use defensive cooldowns and positioning to prevent insanity debuffs during the encounter.", x = 2 },
        [3009] = { e = 2, s = "s", r = "Simple interaction with an NPC under specific conditions.", d = "To kiss Sara in Ulduar while she is angry, wait for her to be hostile before using the emote. This requires specific timing as her mood changes dynamically during the raid instance.", x = 2 },
        [3010] = { e = 4, s = "s", r = "High-skill requirement to avoid insanity debuff in raid.", d = "In 25-player Yogg-Saron, prevent any raid member from going insane by carefully managing gaze mechanics. Coordinate dodges and use defensive abilities to keep everyone safe from insanity effects.", x = 2 },
        [3011] = { e = 4, s = "c", r = "Requires specific raid mechanics and group coordination.", d = "For the 25-player Sara kiss achievement, time your emote when she is visibly angry with you. This state changes frequently, so monitor her reactions closely before attempting the action.", x = 2 },
        [3012] = { e = 5, s = "c", r = "Highly skilled execution with strict time limit.", d = "To defeat Yogg-Saron in under seven minutes in 10-player, optimize your damage rotation and minimize downtime between phases. Focus on efficient DPS to complete the fight quickly without unnecessary delays.", x = 2 },
        [3013] = { e = 5, s = "c", r = "Highly skilled execution with strict time limit.", d = "Start this immediately after Yogg-Saron spawns to maximize the 7-minute window. Ensure your group knows the pull mechanics and has a clear plan to avoid unnecessary deaths that waste time.", x = 2 },
        [3014] = { e = 5, s = "c", h = { 9928 }, r = "Requires precise timing and high-level raid skill.", d = "This requires killing all nine guardians instantly upon spawning in 10-player mode. Coordinate with your raid leader to focus fire immediately and do not engage the main boss until the timer is safe.", x = 2 },
        [3015] = { e = 4, s = "c", r = "Requires specific boss mechanics in a difficult raid.", d = "You must experience all three specific visions listed in the info field during a single run. Ensure every player sees the required events before the encounter ends to avoid missing account-wide progress.", x = 2 },
        [3016] = { e = 4, s = "c", r = "Requires specific boss mechanics in a difficult raid.", d = "Same requirements as the 10-player version but with more damage output available in 25-player mode. Focus on ensuring all three visions are witnessed by at least one player in your group.", x = 2 },
        [3017] = { e = 5, s = "c", h = { 9931 }, r = "Requires precise timing and high-level raid skill.", d = "This is identical to the 10-player guardian kill but requires a larger group. The main pitfall is managing crowd control and damage so you can clear all nine guardians within the strict 12-second limit.", x = 2 },
        [3036] = { e = 4, s = "s", r = "Difficult boss fight requiring specific mechanics.", d = "Defeat Algalon in 10-player mode to earn the Starcaller title. Ensure your group is prepared for his mechanics as this content is no longer available in current expansions.", x = 2 },
        [3037] = { e = 5, s = "s", r = "Very difficult boss fight requiring specific mechanics.", d = "Complete the same encounter as the 10-player version but with 25 players for the The Astral Walker title. Be mindful that larger groups may need better coordination to handle Algalon's mechanics efficiently.", x = 2 },
        [3056] = { e = 4, s = "c", r = "Requires complex raid mechanics and coordination.", d = "First complete the prerequisite 'Nuked from Orbit' achievement in 10-player mode. Then defeat Flame Leviathan while keeping all four orbital defense systems active throughout the entire fight.", x = 2 },
        [3057] = { e = 5, s = "c", r = "Very difficult boss fight requiring specific mechanics.", d = "Repeat the process for the 25-player version after completing the 10-player prerequisite. Maintain strict damage control to ensure the orbital systems remain active until the boss is defeated.", x = 2 },
        [3058] = { e = 4, s = "s", r = "Difficult boss fight requiring specific mechanics.", d = "Defeat XT-002 Deconstructor only after successfully destroying his heart mechanic in 10-player mode. Coordinate your team to focus on the heart phase without letting the boss heal or reset.", x = 2 },
        [3059] = { e = 4, s = "s", r = "Requires specific 25-player raid mechanics and coordination.", d = "Perform the same heart destruction sequence as the 10-player version but with a larger group in 25-player mode. Ensure your healers can manage the increased damage from the larger party size.", x = 2 },
        [3076] = { e = 4, s = "s", r = "Needs specific boss mechanic execution in 10-player raid.", d = "Defeat Auriaya while simultaneously engaging and defeating the Feral Defender in 10-player mode. This requires precise timing to switch targets without losing progress on either boss.", x = 2 },
        [3077] = { e = 4, s = "s", r = "Needs specific boss mechanic execution in 25-player raid.", d = "Defeat Auriaya while simultaneously killing the Feral Defender. Ensure your raid group focuses on both targets to avoid missing this condition during the fight.", x = 2 },
        [3097] = { e = 4, s = "g", r = "High-pressure timed kill count requiring precise execution.", d = "Run the Ulduar gauntlet in 10-player mode and destroy 100 Steelforged Defenders within 10 seconds. Coordinate your team to maximize DPS on these adds quickly.", x = 2 },
        [3098] = { e = 4, s = "g", r = "High-pressure timed kill count requiring precise execution.", d = "Run the Ulduar gauntlet in 25-player mode and destroy 100 Steelforged Defenders within 10 seconds. Use the larger group to clear adds faster than in 10-player.", x = 2 },
        [3118] = { e = 4, s = "s", r = "Requires rapid sequential kills of three specific bosses.", d = "Defeat Elder Brightleaf, Elder Ironbranch, and Elder Stonebark in rapid succession during the Ulduar gauntlet. Time your kills so each occurs within a 15-second window.", x = 2 },
        [3136] = { e = 4, s = "s", r = "PvP boss fight requiring group coordination and skill.", d = "Queue for Wintergrasp in 10-player mode and defeat Emalon the Storm Watcher. This requires coordinating with other players to secure the boss efficiently.", x = 2 },
        [3137] = { e = 4, s = "s", r = "PvP boss fight requiring larger group coordination and skill.", d = "Queue for Wintergrasp in 25-player mode and defeat Emalon the Storm Watcher. The larger group makes securing the boss significantly easier than in 10-player.", x = 2 },
        [3138] = { e = 4, s = "s", r = "Requires specific raid mechanic timing and luck.", d = "In Mimiron's Factory, force him to use Rocket Strike on an Assault Bot to kill it. Coordinate with your raid to position the bot correctly for this specific mechanic.", x = 2 },
        [3141] = { e = 4, s = "s", r = "Complex raid mechanic requiring precise boss management.", d = "Defeat Yogg-Saron in 10-player mode using two or fewer Keepers. Start by unlocking the achievement chain from Three Lights down to Alone in the Darkness.", x = 2 },
        [3157] = { e = 4, s = "s", r = "Complex raid mechanic requiring precise boss management.", d = "Defeat Yogg-Saron in 10-player mode with three or fewer Keepers. This is the first step in the achievement chain, so ensure you have enough Keeper support available.", x = 2 },
        [3158] = { e = 4, s = "s", r = "Complex raid mechanic requiring precise boss management.", d = "Defeat Yogg-Saron in 10-player mode using one or fewer Keepers. You must complete Two Lights first, so plan your raid composition to minimize Keeper usage.", x = 2 },
        [3159] = { e = 4, s = "s", r = "High-skill raid boss fight with strict mechanic.", d = "Defeat Yogg-Saron in 10-player mode without any Keeper assistance. This is the hardest version of the fight, requiring you to unlock all previous steps in the chain first.", x = 2 },
        [3161] = { e = 4, s = "c", r = "Requires specific low-keeper count on hard boss.", d = "Defeat Yogg-Saron in 25-player mode with three or fewer Keepers. Similar to the 10-player version, start by unlocking the full achievement chain before attempting this specific condition.", x = 2 },
        [3162] = { e = 4, s = "c", r = "Intermediate step in Yogg-Saron keeper chain.", d = "Start with Two Lights in the Darkness (25 player) by bringing two Keepers to Yogg-Saron. You must complete this before attempting One Light or Alone in the Darkness. This is a legacy achievement requiring specific raid composition and timing.", x = 2 },
        [3163] = { e = 4, s = "c", r = "Intermediate step in Yogg-Saron keeper chain.", d = "Begin with Two Lights in the Darkness (25 player) to unlock One Light in the Darkness. Bring only one Keeper or none if you already have the previous title. Ensure you do not accidentally bring extra Keepers during the fight.", x = 2 },
        [3164] = { e = 4, s = "s", r = "High-skill raid boss fight with strict mechanic.", d = "Complete One Light in the Darkness first to unlock Alone in the Darkness. You must defeat Yogg-Saron without any Keepers present. This is the hardest version and requires careful group management to avoid summoning extra Keepers.", x = 2 },
        [3176] = { e = 4, s = "s", r = "Requires specific encounter condition on Thorim.", d = "Start with Siffed (10 player) before attempting Lose Your Illusion. Bring Sif into Thorim's fight in a 10-player group. Do not kill Sif during the encounter or you will fail the achievement.", x = 2 },
        [3177] = { e = 4, s = "s", r = "Requires specific mechanic execution on Freya.", d = "Begin with Knock on Wood (10 player) to unlock Knock, Knock on Wood. Leave at least one Elder alive while defeating Freya in a 10-player group. Watch the Elders closely to ensure you do not kill them all.", x = 2 },
        [3178] = { e = 4, s = "s", r = "Requires precise tanking and mechanics on Freya.", d = "Start with Knock on Wood (10 player) to unlock Knock, Knock on Wood. Leave at least two Elders alive during Freya's fight. This requires precise damage control and positioning to protect the remaining Elders.", x = 2 },
        [3179] = { e = 4, s = "s", r = "Requires perfect mechanic execution on Freya.", d = "Complete Knock, Knock on Wood first to unlock Knock, Knock, Knock on Wood. You must leave all three Elders alive while defeating Freya. This is extremely difficult and requires a highly skilled group with perfect execution.", x = 2 },
        [3180] = { e = 4, s = "s", r = "Requires specific encounter condition on Mimiron.", d = "Defeat Mimiron after activating his Self-Destruct mechanism in a 10-player raid. Activate the mechanism before killing him to trigger the achievement. Be prepared for increased difficulty as the boss becomes more dangerous.", x = 2 },
        [3181] = { e = 4, s = "s", r = "Requires defeating specific boss before main fight.", d = "Defeat the Saronite Animus first, then proceed to General Vezax in a 10-player raid. Ensure you kill the Animus before engaging Vezax to unlock the achievement. This requires careful planning and coordination with your group.", x = 2 },
        [3182] = { e = 4, s = "s", r = "Requires defeating boss before cache shatters.", d = "Defeat Hodir before he shatters his rare cache in a 10-player raid. Monitor the cache closely and ensure it does not break during the fight. This requires precise timing and damage management to avoid triggering the cache's destruction.", x = 2 },
        [3183] = { e = 5, s = "s", r = "Requires specific raid mechanics and coordination.", d = "Start with Siffed (25 player) before attempting Lose Your Illusion (25 player). Bring Sif into Thorim's fight in a 25-player group. Do not kill Sif during the encounter or you will fail the achievement.", x = 2 },
        [3184] = { e = 5, s = "s", r = "High difficulty raid encounter with RNG element.", d = "Defeat Hodir before he shatters his rare cache in a 25-player raid. Monitor the cache closely and ensure it does not break during the fight. This requires precise timing and damage management to avoid triggering the cache's destruction.", x = 2 },
        [3185] = { e = 5, s = "s", r = "Difficult raid mechanics requiring precise execution.", d = "Run Freya in 25-player mode and focus on keeping at least one Elder alive until the fight ends. This requires careful positioning and damage control to avoid wiping out all three Elders prematurely.", x = 2 },
        [3186] = { e = 5, s = "s", r = "Extremely difficult raid mechanics with strict constraints.", d = "Complete the previous achievement first, then repeat Freya while ensuring two Elders survive. Maintain strict area denial and healing focus to prevent accidental deaths during the encounter.", x = 2 },
        [3187] = { e = 5, s = "s", r = "Most difficult Freya encounter requiring perfect play.", d = "Finish the chain by defeating Freya with all three Elders still alive. This demands perfect execution and coordination, as any stray damage will cause failure.", x = 2 },
        [3188] = { e = 4, s = "s", r = "Requires defeating a specific boss in raid mode.", d = "Defeat General Vezax immediately after killing the Saronite Animus in 25-player mode. Ensure you do not reset the encounter or leave the boss alive too long before transitioning.", x = 2 },
        [3189] = { e = 4, s = "s", r = "Requires activating self-destruct and defeating Mimiron.", d = "Activate Mimiron's Self-Destruct mechanism and defeat him in 25-player mode. Timing is critical; wait for the self-destruct phase to begin before engaging the final mechanics.", x = 2 },
        [3217] = { e = 3, s = "c", h = { 11176 }, r = "Five daily quests; one involves rare drop RNG.", d = "Complete all five of Marcia Chase's daily fishing quests to earn points. These are account-wide and reset daily, so check her board regularly for new objectives.", x = 2 },
        [3218] = { e = 4, s = "g", r = "Requires fishing up a specific rare mount.", d = "Fish in zones like Deepholm or Northrend until you obtain the Sea Turtle mount. This is a rare drop, so be patient and fish extensively across different pools.", x = 2 },
        [3237] = { e = 5, s = "s", r = "Highly restrictive raid mechanics with strict damage rules.", d = "Defeat Mimiron in 25-player mode without anyone taking hits from mines, rockets, or bomb bots. Use damage mitigation tools and avoid standing near explosive objects during the fight.", x = 2 },
        [3296] = { e = 4, s = "s", r = "Requires obtaining a specific item via crafting or drops.", d = "Obtain the Chef's Hat by completing cooking-related achievements or quests. Check current world events and profession rewards for opportunities to acquire this item.", x = 2 },
        [3456] = { e = 1, s = "s", r = "Simple interaction during a limited-time event.", d = "Participate in Day of the Dead event and dance with Catrina to become a skeleton. This is time-gated and only available during the specific holiday window.", x = 2 },
        [3457] = { e = 1, s = "s", r = "One-time event interaction.", d = "Join Pirates' Day event and drink with Dread Captain DeMeza to join her crew. This is also time-limited and requires being online during the event period.", x = 2 },
        [3478] = { e = 2, s = "c", r = "Simple sub-achievements to complete.", d = "Complete all Pilgrim's Bounty sub-achievements listed in the info field. These are account-wide and tied to Thanksgiving events, so plan ahead for the holiday season.", x = 2 },
        [3556] = { e = 1, s = "c", r = "Visit four capitals once.", d = "Visit Ironforge, Stormwind, Darnassus, and The Exodar during Pilgrim's Bounty to feast at the Bountiful Table. Ensure you are in each capital city while the event is active, as this cannot be completed after the holiday ends.", x = 2 },
        [3557] = { e = 1, s = "c", r = "Visit four capitals once.", d = "Go to Orgrimmar, Thunder Bluff, Undercity, and Silvermoon City to eat a complete feast at every Horde capital. Do this only during the Pilgrim's Bounty event window, or you will miss these points permanently.", x = 2 },
        [3558] = { e = 1, s = "c", r = "Try five dishes once each.", d = "Eat one sample of each specific dish listed at any Bountiful Table during the event. You can do this in any order across all capitals while the holiday is active.", x = 2 },
        [3559] = { e = 2, s = "c", r = "Kill eight specific rogue classes.", d = "Use your Turkey Shooter to hit Rogues of every race and faction listed. This requires you to be near a Rogue of that specific race and faction during the event.", x = 2 },
        [3576] = { e = 1, s = "c", r = "Cook five recipes once each.", d = "Cook one of each Pilgrim's Bounty dish using your cooking profession. You must have the recipe unlocked and sufficient materials available during the event window.", x = 2 },
        [3577] = { e = 1, s = "c", r = "Cook five recipes once each.", d = "This achievement is identical to 3576; simply cook every dish listed in the info field while the event is running. No special conditions beyond having the recipes and ingredients differ from other years.", x = 2 },
        [3578] = { e = 2, s = "g", r = "Hunt turkeys until timer ends.", d = "Hunt Wild Turkeys in any zone until you reach the Turkey Triumph threshold. This is a volume-based achievement that can be done quickly if you focus on turkey zones during the event.", x = 2 },
        [3579] = { e = 1, s = "s", r = "One-time interaction at table.", d = "Stand next to another player at a Bountiful Table and bounce food off their head. Coordinate with a friend or use a macro to trigger this repeatedly for all required dishes.", x = 2 },
        [3580] = { e = 2, s = "c", r = "Visit four enemy capitals once.", d = "Wear Pilgrim's Attire, Dress, or Robe while sitting at the Bountiful Table in each enemy capital. You must be wearing the correct gear set and seated simultaneously during the event.", x = 2 },
        [3581] = { e = 2, s = "c", r = "Visit four enemy capitals once.", d = "This is the Alliance version of 3580; wear your Pilgrim's gear and sit at tables in Stormwind, Darnassus, Ironforge, and The Exodar. Ensure you are flagged as Alliance if required by the table mechanics.", x = 2 },
        [3582] = { e = 4, s = "s", r = "Requires specific rare drop and boss kill.", d = "Defeat Talon King Ikiss while wearing a Pilgrim's Hat plus Dress, Robe, or Attire. This boss fight is time-gated to the event window, so plan your gear before engaging him.", x = 2 },
        [3596] = { e = 4, s = "g", r = "Grinding multiple daily quests over time.", d = "Complete every daily quest listed in the info field for Pilgrim's Bounty. These dailies reset each day during the event, so prioritize them early to avoid missing any due to the holiday ending.", x = 2 },
        [3597] = { e = 4, s = "g", r = "Grinding multiple daily quests over time.", d = "Run the Pilgrim's Bounty dailies every week during the event window, as they reset only then. Focus on completing all five specific tasks to earn the full 10 points before the holiday ends.", x = 2 },
        [3676] = { e = 4, s = "s", r = "Requires exalted status and city unlock.", d = "Grind daily quests for The Silver Covenant faction until you reach exalted status at the Argent Tournament. Once exalted, speak with the appropriate NPC to unlock your city's representation rights and claim the achievement.", x = 2 },
        [3677] = { e = 4, s = "s", r = "Requires exalted status and city unlock.", d = "Complete Sunreaver daily quests repeatedly to gain reputation points until you achieve exalted standing with them. After reaching exalted, visit the Crusader's Quartermaster to secure your city's representation slot in the tournament.", x = 2 },
        [3736] = { e = 2, s = "s", r = "Simple purchase and mount usage.", d = "Save gold to purchase an Argent Pony from Dame Evniki Kapsalis and ride it at least once to trigger the achievement. Ensure you have sufficient funds before attempting this task as it is a one-time purchase requirement.", x = 2 },
        [3776] = { e = 4, s = "s", r = "Requires winning a competitive PvP event.", d = "Queue for Isle of Conquest matches until your team secures a victory, which will immediately grant the required points. This achievement unlocks further progression toward veteran status once completed successfully.", x = 2 },
        [3777] = { e = 4, s = "g", r = "Grinding 100 wins in a competitive mode.", d = "Win 100 consecutive or total victories in Isle of Conquest to unlock this account-wide milestone. Track your win count carefully since it requires significant time investment and consistent performance across many matches.", x = 2 },
        [3778] = { e = 4, s = "c", h = { 8556, 8552, 8553 }, r = "Requires defeating multiple specific raid bosses.", d = "Defeat all eight bosses within the Trial of the Champion dungeon, starting with normal difficulty if needed before attempting heroic versions. Complete each boss encounter individually to ensure credit is awarded for every single one listed in the requirements.", x = 2 },
        [3797] = { e = 4, s = "s", r = "Specific mechanic required during a raid fight.", d = "In 10-player Icehowl encounters, keep at least two Snobolds alive while defeating the main boss to satisfy this specific condition. Coordinate with your group to avoid killing the adds prematurely during the fight sequence.", x = 2 },
        [3798] = { e = 4, s = "s", r = "Specific mechanic required during a raid fight.", d = "During 10-player runs, ensure all enemy heroes are eliminated within 60 seconds after the first one dies. Communicate clearly with your team to rush down remaining targets immediately upon the initial kill.", x = 2 },
        [3799] = { e = 4, s = "s", r = "Specific mechanic required during a raid fight.", d = "Defeat the Twin Val'kyr in under three minutes during a 10-player run by focusing damage efficiently. Use high-damage abilities and coordinated crowd control to minimize downtime between phases of the encounter.", x = 2 },
        [3800] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Kill 25 Swarm Scarabs within 30 seconds during a 10-player Icehowl fight by prioritizing these adds early in the battle. Assign specific players to focus on them while others handle main targets to meet the tight time limit.", x = 2 },
        [3802] = { e = 5, s = "c", h = { 7553, 7537, 7554 }, r = "Needs multiple specific boss kills on Heroic difficulty.", d = "Visit the Trial of the Champion multiple times on Heroic Difficulty, suppressing five different memories before defeating Argent Confessor Paletress each time. Ensure each visit is separate and meets all memory suppression requirements to count toward the achievement.", x = 2 },
        [3803] = { e = 4, s = "s", r = "Requires perfect execution to avoid the hammer mechanic.", d = "Start on Heroic and ensure Eadric uses his own hammer for the kill. Focus your damage rotation to finish him quickly while avoiding his melee attacks.", x = 2 },
        [3804] = { e = 5, s = "s", r = "High skill ceiling; requires flawless avoidance of explosions.", d = "Defeat the Black Knight on Heroic without anyone taking ghoul explosion damage. Keep the group tightly clustered and use defensive cooldowns immediately when the ghoul appears.", x = 2 },
        [3808] = { e = 5, s = "g", r = "Requires many attempts to reach the chest with high health.", d = "Run Trial of the Grand Crusader in 10-player mode to reach a Tribute Chest with at least 25 attempts remaining. This requires careful management of your attempt counter and avoiding unnecessary deaths.", x = 2 },
        [3809] = { e = 5, s = "g", r = "Requires significantly more attempts than previous step.", d = "Complete the previous tribute step, then repeat runs until you have 45 attempts left when reaching a Tribute Chest. Monitor your attempt count closely to avoid missing the threshold.", x = 2 },
        [3810] = { e = 5, s = "g", r = "Requires maximum attempts; extremely difficult RNG grind.", d = "Finish the prior step and push for exactly 50 attempts remaining at a Tribute Chest. This is the final tier of the 10-player tribute chain and requires precise attempt tracking.", x = 2 },
        [3812] = { e = 4, s = "c", h = { 9670, 9671, 9668 }, r = "Needs defeating all bosses in a specific raid instance.", d = "Defeat every boss in Trial of the Grand Crusader on Heroic with a full 25-player group. Ensure you clear all bosses including the Faction Champions to complete this account-wide requirement.", x = 2 },
        [3813] = { e = 5, s = "s", r = "Requires complex mechanics and precise boss management.", d = "Kill Icehowl while keeping at least four Snobolds alive in your party. Use crowd control or kiting tactics to preserve the snobolds during the fight.", x = 2 },
        [3815] = { e = 4, s = "s", r = "Requires fast execution and good raid coordination.", d = "Defeat the Twin Val'kyr within three minutes on Heroic with a 25-player group. Coordinate your team's damage output and use efficient cooldowns to meet the strict time limit.", x = 2 },
        [3816] = { e = 4, s = "s", r = "Same as 3800 but in larger group; still requires timing.", d = "Kill 25 Swarm Scarabs in under thirty seconds during the Twin Val'kyr encounter. Focus fire on them immediately upon spawning while managing the main boss mechanics.", x = 2 },
        [3817] = { e = 5, s = "g", r = "Requires many attempts to reach the chest with high health.", d = "Run Trial of the Grand Crusader in 25-player mode to reach a Tribute Chest with at least 25 attempts remaining. Manage your group's deaths carefully to maintain a high attempt count.", x = 2 },
        [3818] = { e = 5, s = "c", r = "Requires high-level raiding with strict RNG and group coordination.", d = "Complete the previous step and continue running until you have 45 attempts left at a Tribute Chest. Track your attempt counter meticulously to avoid falling below the required number.", x = 2 },
        [3819] = { e = 5, s = "c", r = "Requires higher RNG luck than previous tribute achievement.", d = "Finish the prior tier by reaching a Tribute Chest with exactly 50 attempts remaining. This is the final step in the 25-player tribute chain and demands precise attempt management.", x = 2 },
        [3836] = { e = 4, s = "s", r = "Defeating a specific PVP boss requires skilled group coordination.", d = "Gather a full 10-player group to defeat Koralon the Flame Watcher in Wintergrasp. This is a time-gated achievement that requires specific dungeon finder settings or manual grouping.", x = 2 },
        [3837] = { e = 4, s = "s", r = "Defeating a specific PVP boss in larger group is harder.", d = "Coordinate with a large guild or raid group to form a 25-player team for the harder Koralon encounter. Ensure everyone knows the mechanics before attempting this time-sensitive event.", x = 2 },
        [3844] = { e = 4, s = "g", r = "Requires farming dungeons/raids for a long time to reach count.", d = "Grind dungeons and raids consistently to collect 1000 Emblems of Heroism, Valor, Conquest, Triumph, or Frost. This is account-wide, so play with friends who also need these currencies.", x = 2 },
        [3845] = { e = 2, s = "c", r = "Single battle objectives are easy if you participate actively.", d = "Play a single Isle of Conquest match and focus on completing all four objectives: assault a base, defend a base, destroy a vehicle, and kill a player. Coordinate with your team to cover these tasks efficiently.", x = 2 },
        [3846] = { e = 2, s = "s", r = "Winning a match with specific zones is straightforward.", d = "Win an Isle of Conquest battle while your team holds both the Quarry and Oil Refinery simultaneously. Prioritize capturing these resource points early in the match to secure this win condition.", x = 2 },
        [3847] = { e = 1, s = "g", r = "Capturing vehicles is trivial once the battle starts.", d = "Control all four specific vehicles (Glaive Thrower, Siege Engine, Demolisher, Catapult) during one Isle of Conquest battle. Coordinate with your team to capture and hold these vehicles until the match ends.", x = 2 },
        [3848] = { e = 2, s = "s", r = "Using bombs on gates is easy if you have them.", d = "Use five Seaforium Bombs on enemy gates within a single Isle of Conquest battle. Save your bombs for the final push when the enemy is vulnerable near their gates.", x = 2 },
        [3849] = { e = 2, s = "s", r = "Using huge bombs is slightly harder but still single battle.", d = "Use five Huge Seaforium Bombs on enemy gates in one match. These are rare drops, so you may need to run multiple battles or wait for specific drop rates.", x = 2 },
        [3850] = { e = 2, s = "g", r = "Destroying vehicles and players with turrets is easy grind.", d = "Destroy ten vehicles and kill one hundred players using turrets during Isle of Conquest. Focus your turret placement on high-traffic areas to maximize kills and vehicle destruction.", x = 2 },
        [3851] = { e = 2, s = "s", r = "Winning match with all zones is standard PVP objective.", d = "Win an Isle of Conquest battle while controlling all five resource points: Quarry, Oil Refinery, Shipyard, Siege Workshop, and Hangar. This requires a second win after completing the previous achievement.", x = 2 },
        [3852] = { e = 3, s = "g", r = "Requires disarming 25 bombs in a chaotic PvP arena.", d = "Disarm twenty-five bombs across Isle of Conquest matches. Coordinate with your team to clear bomb sites quickly, as they can be dangerous and time-consuming if ignored.", x = 2 },
        [3853] = { e = 4, s = "c", h = { 7431, 7432, 7433 }, r = "Need kills in all 5 zones; some are hard to reach.", d = "Kill one player at each of the six specific locations in a single Isle of Conquest battle. Plan your route to cover all zones and ensure kills happen in every required area before the match ends.", x = 2 },
        [3854] = { e = 3, s = "s", r = "Requires specific timing and luck to enter courtyard.", d = "Enter the enemy courtyard immediately after spawning to secure this before gates close. Watch for patrols that might block your path early on.", x = 2 },
        [3855] = { e = 4, s = "g", r = "Kill 10 players with Glaive Thrower without dying.", d = "Stand near a Glaive Thrower and focus fire on players without taking damage yourself. This requires precise timing as you must survive while dealing kills.", x = 2 },
        [3856] = { e = 3, s = "g", r = "Destroy various vehicles; requires finding them in battle.", d = "Destroy all listed vehicles by targeting them directly during the battle. Prioritize high-value targets like the Demolisher to clear objectives quickly.", x = 2 },
        [3857] = { e = 4, s = "c", h = { 10582, 10590, 10580 }, r = "Requires completing all sub-achievements including hard ones.", d = "Complete every sub-achievement listed in the info field before time runs out. Start with easier tasks like gathering resources or destroying vehicles first.", x = 2 },
        [3916] = { e = 4, s = "c", h = { 4342, 4343, 4345 }, r = "Defeat all ToC bosses; requires raid group and skill.", d = "Defeat all Trial of the Crusader bosses in 25-player mode to unlock this. Ensure your group is prepared for each encounter sequentially.", x = 2 },
        [3917] = { e = 4, s = "c", h = { 7421, 7422, 7424 }, r = "Defeat all ToC bosses; requires raid group and skill.", d = "Clear every boss in the Trial of the Crusader using a 10-player group. Coordinate with friends or find a guild for better success rates.", x = 2 },
        [3918] = { e = 5, s = "c", h = { 7634, 7635, 7637 }, r = "Heroic ToC requires high-level raid group and coordination.", d = "Finish the Trial of the Grand Crusader in Heroic mode after completing the previous achievement. This requires a full 10-player raid ready for high difficulty.", x = 2 },
        [3936] = { e = 4, s = "s", r = "Requires precise timing to kill two bosses within 10s.", d = "Kill Acidmaw and Dreadscale within ten seconds of each other in a 10-player group. Time your kills carefully to meet the strict window requirement.", x = 2 },
        [3937] = { e = 4, s = "s", r = "Requires precise timing to kill two bosses within 10s.", d = "Repeat the previous strategy but with a 25-player group. Ensure enough players are present to handle both bosses simultaneously for the timer.", x = 2 },
        [3957] = { e = 4, s = "c", h = { 7937, 7943, 7944 }, r = "Requires completing all sub-achievements including hard ones.", d = "Complete all Isle of Conquest sub-achievements including vehicle destruction and courtyard entry. Start with resource gathering tasks before engaging in combat.", x = 2 },
        [3996] = { e = 4, s = "c", r = "Requires specific boss mechanics and timing in a raid.", d = "Defeat Lord Jaraxxus while keeping at least two Mistresses of Pain alive. Manage adds carefully to maintain the required condition during the fight.", x = 2 },
        [3997] = { e = 4, s = "c", r = "Same as above but in larger 25-player raids.", d = "Perform the same strategy as the 10-player version but with a larger group. Ensure your raid composition can sustain multiple bosses simultaneously.", x = 2 },
        [4016] = { e = 4, s = "c", r = "Requires precise timing to kill three raid bosses quickly.", d = "Queue for the Lich King raid with a full group to defeat Archavon, Emalon, and Koralon consecutively. You must kill each boss within 60 seconds of the previous one, so coordinate your pulls carefully.", x = 2 },
        [4017] = { e = 4, s = "c", r = "Same as above but in larger 25-player raids.", d = "Gather a full 25-player group to defeat Archavon, Emalon, and Koralon consecutively. Ensure you kill each boss within 60 seconds of the previous one to complete this timed sequence.", x = 2 },
        [4080] = { e = 3, s = "c", r = "Requires specific item restrictions during a raid run.", d = "Complete A Tribute to Insanity in a 10-player raid while ensuring no member uses Coliseum or higher-tier gear. This legacy achievement requires strict adherence to item restrictions for the entire group.", x = 2 },
        [4176] = { e = 3, s = "c", r = "Requires winning PvP while holding two specific zones.", d = "Queue for Isle of Conquest and focus on capturing the Quarry and Oil Refinery before fighting the final boss. Secure these two zones early to win the match and earn points.", x = 2 },
        [4177] = { e = 3, s = "c", r = "Requires winning PvP while holding five specific zones.", d = "First complete Resource Glut by controlling all five zones, then repeat the process to capture them again. You must win a second Isle of Conquest while holding every zone simultaneously.", x = 2 },
        [4256] = { e = 3, s = "c", r = "Requires destroying four specific vehicles in PvP.", d = "Queue for Isle of Conquest and actively destroy enemy vehicles like Glaive Throwers and Demolishers during the match. This account-wide achievement tracks total vehicle destructions regardless of your team's win state.", x = 2 },
        [4296] = { e = 3, s = "c", r = "Requires defeating all bosses in a specific dungeon.", d = "Defeat all bosses in Trial of the Champion on Normal difficulty to unlock the Heroic version. Ensure you kill every boss listed in the info field before moving to higher difficulties.", x = 2 },
        [4297] = { e = 4, s = "c", r = "Same as above but on harder Heroic difficulty.", d = "Complete Normal Trial of the Champion first, then queue for Heroic mode to defeat all bosses again. Note that some boss models differ between Normal and Heroic runs in this dungeon.", x = 2 },
        [4298] = { e = 4, s = "c", r = "Same as above but on harder Heroic difficulty.", d = "Finish Normal Trial of the Champion before attempting Heroic difficulty. Be aware that specific boss IDs change between difficulties, so ensure you are targeting the correct encounter list.", x = 2 },
        [4316] = { e = 4, s = "g", r = "Requires collecting a large number of emblems over time.", d = "Farm dungeons and raids to collect a total of 2500 Emblems of any type. This account-wide goal requires consistent play over time as emblems drop from various sources.", x = 2 },
        [4396] = { e = 4, s = "s", r = "Requires a full raid group to defeat a boss.", d = "Queue for Onyxia's Lair in 10-player mode and defeat the boss to complete this achievement. Ensure your group composition is suitable for the raid mechanics before starting.", x = 2 },
        [4397] = { e = 5, s = "s", r = "Requires a full raid group; harder than 10-player.", d = "Gather a full 25-player group to defeat Onyxia in her lair. This version requires a larger team size compared to the 10-player variant listed separately.", x = 2 },
        [4402] = { e = 4, s = "s", r = "Requires a raid group and tight timing.", d = "Run Onyxia with a skilled group to clear mechanics quickly and avoid adds. This is time-gated and requires precise execution in 10-player mode.", x = 2 },
        [4403] = { e = 5, s = "s", r = "Requires a raid group and heavy RNG luck.", d = "Use a healer or tank to kill whelplings instantly after liftoff, then focus fire on Onyxia immediately. Timing is critical as the hatch window is very short.", x = 2 },
        [4404] = { e = 4, s = "s", r = "Requires a raid group and perfect avoidance.", d = "Position your group carefully during Deep Breath casts and use crowd control to avoid damage. Ensure no player takes even a single tick of breath damage.", x = 2 },
        [4405] = { e = 5, s = "s", r = "Requires a full raid group and tight timing.", d = "Repeat the strategy from id=4402 but in 25-player mode where mechanics are harder due to more targets. Coordinate with your raid leader for speed.", x = 2 },
        [4406] = { e = 5, s = "s", r = "Requires a full raid group and heavy RNG luck.", d = "Follow the same whelping strategy as id=4403 but manage the larger group size in 25-player mode. Clear adds efficiently before Onyxia attacks.", x = 2 },
        [4407] = { e = 5, s = "s", r = "Requires a full raid group and perfect avoidance.", d = "Execute the Deep Breath avoidance from id=4404 within a 25-player raid. Communication is vital to prevent anyone taking damage in this larger group.", x = 2 },
        [4436] = { e = 2, s = "g", r = "Simple event participation; counter scales down.", d = "Complete Winter Veil events and defeat Sylvanas, Lor'themar, and Eitrigg using ranged attacks or pelting mechanics. These are account-wide and require event participation.", x = 2 },
        [4437] = { e = 2, s = "g", r = "Simple event participation; counter scales down.", d = "Finish the remaining Winter Veil leaders Muradin, Velen, and Tyrande similarly to id=4436. Ensure you have access to these specific world events.", x = 2 },
        [4476] = { e = 3, s = "g", r = "Grinding dungeons with random players takes hours.", d = "Queue for random heroic dungeons repeatedly until your total grouped player count reaches ten. This is a grind that accumulates across all characters.", x = 2 },
        [4477] = { e = 4, s = "g", r = "Requires many dungeon runs to group with 50 people.", d = "Continue queuing random heroics after id=4476 to reach fifty total grouped players. You will earn the title The Patient upon completion.", x = 2 },
        [4478] = { e = 3, s = "g", r = "Grinding 100 random players takes a few hours.", d = "Keep running random heroics until you have grouped with one hundred unique players. This final step grants the Perky Pug pet and the title.", x = 2 },
        [4516] = { e = 4, s = "s", r = "Requires defeating multiple bosses in a raid instance.", d = "Defeat both bosses in The Forge of Souls dungeon. Start with normal mode first to learn mechanics before attempting heroic if required next.", x = 2 },
        [4517] = { e = 4, s = "s", r = "Requires defeating multiple bosses in a raid instance.", d = "Complete the Pit of Saron bosses on Normal first to unlock Heroic. This is account-wide, so ensure your group has all necessary keys before attempting higher difficulties.", x = 2 },
        [4518] = { e = 4, s = "s", r = "Requires defeating multiple bosses including the Lich King.", d = "Finish The Halls of Reflection Normal run to access Heroic content. Be prepared for the Lich King encounter as it is a required step in the progression chain.", x = 2 },
        [4519] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and skill requirements.", d = "Unlock Heroic Forge of Souls by clearing the Normal version first. This achievement requires defeating both bosses on Heroic and is tracked account-wide.", x = 2 },
        [4520] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and skill requirements.", d = "Clear The Pit of Saron on Heroic after unlocking it from Normal. Coordinate with your group to ensure all three boss keys are obtained for the account-wide reward.", x = 2 },
        [4521] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and skill requirements.", d = "Unlock Heroic Halls of Reflection by completing the Normal version first. Focus on surviving the Lich King encounter as it is a mandatory part of the achievement requirements.", x = 2 },
        [4522] = { e = 4, s = "s", r = "Requires specific mechanics and coordination in Heroic.", d = "Defeat Bronjahm on Heroic while keeping at least four Corrupted Soul Fragments alive. Use defensive cooldowns and healing to manage the fragment mechanic during the fight.", x = 2 },
        [4523] = { e = 4, s = "s", r = "Requires avoiding a specific mechanic in Heroic.", d = "Kill Devourer of Souls on Heroic without letting him cast Phantom Blast. Coordinate your team's crowd control and damage output to prevent this specific ability from landing.", x = 2 },
        [4526] = { e = 4, s = "s", r = "Requires speed and coordination to escape quickly.", d = "Escape The Halls of Reflection on Heroic in under six minutes. Practice the run multiple times to optimize movement and minimize downtime between encounters for the speed requirement.", x = 2 },
        [4527] = { e = 4, s = "s", r = "Requires defeating raid bosses in a specific group size.", d = "Clear The Frostwing Halls in 10-player mode before moving to Heroic. Ensure your group composition includes healers and tanks capable of handling Sindragosa and Valithria Dreamwalker.", x = 2 },
        [4528] = { e = 4, s = "s", r = "Requires defeating raid bosses in a specific group size.", d = "Complete The Plagueworks in 10-player mode as the next step after Frostwing Halls. Prepare for Festergut, Rotface, and Professor Putricide with appropriate raid buffs and mechanics knowledge.", x = 2 },
        [4529] = { e = 4, s = "c", r = "Requires full raid group and multiple boss kills.", d = "Finish The Crimson Hall in 10-player mode to unlock Heroic content. Focus on managing the Blood Prince Council mechanics before proceeding to defeat Blood-Queen Lana'thel.", x = 2 },
        [4530] = { e = 4, s = "s", r = "Final raid boss requires full group coordination.", d = "Defeat the Lich King in 10-player mode after clearing The Crimson Hall. This final raid boss grants a title and unlocks the Bane of the Fallen King achievement chain.", x = 2 },
        [4531] = { e = 4, s = "c", r = "Requires killing first four bosses with a raid.", d = "Clear the first four bosses in normal mode to unlock this account-wide achievement. Start with Marrowgar and work through Deathwhisper, Gunship Battle, and The Deathbringer without needing heroic difficulty.", x = 2 },
        [4532] = { e = 4, s = "c", r = "Requires defeating every boss in the raid.", d = "Defeat every boss in Icecrown Citadel normal mode to complete this account-wide goal. You must finish the previous four bosses first, then clear Plagueworks, Crimson Hall, Frostwing Halls, and The Frozen Throne.", x = 2 },
        [4534] = { e = 4, s = "s", r = "Specific mechanic requires skilled raid execution.", d = "Defeat Lord Marrowgar while keeping all raid members free of impaling spikes for over eight seconds. Coordinate spike removal immediately after the boss casts the ability to avoid failure.", x = 2 },
        [4535] = { e = 4, s = "s", r = "Requires specific boss mechanics and raid setup.", d = "Kill Lady Deathwhisper with at least five different cultist types active simultaneously. Use specific mechanics or buffs to spawn distinct cultists before pulling the final phase.", x = 2 },
        [4536] = { e = 4, s = "s", r = "Specific mechanic requires skilled raid execution.", d = "Win the Gunship Battle ensuring no raid member visits the enemy ship more than twice total. Assign a dedicated team to handle the enemy gunship while others focus on your own.", x = 2 },
        [4537] = { e = 4, s = "s", r = "Requires specific boss mechanics and raid timing.", d = "Defeat The Deathbringer before Mark of the Fallen Champion is cast three times. Rush the kill or use crowd control to interrupt the boss quickly during this phase.", x = 2 },
        [4538] = { e = 4, s = "s", r = "Specific mechanic requires skilled raid execution.", d = "Kill Rotface without allowing a Big Ooze to cast Unstable Ooze Explosion. Monitor oozes closely and kill them before they can trigger their dangerous ability.", x = 2 },
        [4539] = { e = 4, s = "c", r = "Requires two specific boss kills with mechanics.", d = "Defeat Blood-Queen Lana'thel once as a vampire and again without becoming one. Complete the normal run first to get the vampire version, then retry normally for the second part.", x = 2 },
        [4577] = { e = 4, s = "s", r = "Specific mechanic requires skilled raid execution.", d = "Defeat Festergut while ensuring no raid member ever reaches three stacks of Inoculated. Avoid drinking his blood or using abilities that grant these stacks during the entire fight.", x = 2 },
        [4578] = { e = 4, s = "s", r = "Specific mechanic requires skilled raid execution.", d = "Kill Professor Putricide without using Regurgitated Ooze on the Abomination. Do not use this specific ability at any point during the encounter to satisfy the condition.", x = 2 },
        [4579] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Enter every portal spawned by Valithria Dreamwalker before healing her to full health. Prioritize entering portals immediately upon spawning rather than focusing on healing the boss.", x = 2 },
        [4580] = { e = 4, s = "s", r = "Requires strict damage control during a raid fight.", d = "Defeat Sindragosa without any raid member receiving more than five stacks of Mystic Buffet. Manage food buffs carefully and avoid overeating during the fight to stay under the limit.", x = 2 },
        [4581] = { e = 4, s = "g", r = "Requires killing multiple adds before the final boss.", d = "Pull Vile Spirits immediately to prevent explosions before engaging the Lich King in 10-player mode. This requires tight coordination and quick kills, as missing a spirit makes the achievement impossible.", x = 2 },
        [4582] = { e = 4, s = "s", r = "Requires high skill to avoid a specific damage cap.", d = "Defeat the Blood Council while ensuring no raid member takes over 23,000 spell damage from a single hit. Use defensive cooldowns proactively and avoid standing in AoE spells to meet this strict damage cap.", x = 2 },
        [4583] = { e = 5, s = "s", r = "Defeating the raid boss is the primary difficulty.", d = "Complete the Lich King encounter in 10-player Heroic mode to earn the Bane of the Fallen King title. Ensure you have already defeated The Frozen Throne as a prerequisite for this raid key.", x = 2 },
        [4584] = { e = 5, s = "s", r = "Defeating the raid boss in 25-player is very hard.", d = "Defeat the Lich King in 25-player Heroic mode to claim the Light of Dawn title. This is a massive group effort requiring full raid attendance and coordination.", x = 2 },
        [4585] = { e = 4, s = "s", r = "Requires finding and defeating a rare spawn in PvP.", d = "Queue for Wintergrasp with a 10-player group to defeat Toravon the Ice Watcher. Timing matters, as this boss only spawns during specific events in the zone.", x = 2 },
        [4586] = { e = 5, s = "s", r = "25-player version of the previous achievement is harder.", d = "Gather a full 25-player raid group to defeat Toravon the Ice Watcher in Wintergrasp. Ensure everyone is ready for the larger scale of this heroic version of the encounter.", x = 2 },
        [4596] = { e = 3, s = "c", r = "Requires completing several distinct steps across zones.", d = "Follow the quest chain starting with recovering Quel'Delar's hilt, then draw the blade, reforge it, purify it in the Sunwell, and finally present it to complete the Argent Tournament achievement.", x = 2 },
        [4597] = { e = 5, s = "s", r = "Defeating the raid boss is the primary difficulty.", d = "Defeat the Lich King in 25-player mode to unlock The Frozen Throne title and progress toward The Light of Dawn. This is a major milestone requiring a full raid group.", x = 2 },
        [4598] = { e = 3, s = "g", r = "Requires earning a large amount of reputation.", d = "Earn Exalted reputation with the Ashen Verdict faction to receive the Of the Ashen Verdict title. This is account-wide, so coordinate with friends or join groups to speed up the grind.", x = 2 },
        [4601] = { e = 4, s = "s", r = "Requires precise timing and coordination in a raid.", d = "Allow Necrotic Plague stacks to reach 30 before killing the Lich King in 10-player mode. Do not use cleansing abilities until the very end of the fight to satisfy this condition.", x = 2 },
        [4602] = { e = 5, s = "c", h = { 17216, 17220, 17222 }, r = "Requires full heroic raid clears; high RNG and mechanics.", d = "Complete all listed 10-player Icecrown Citadel achievements, including dungeon clears and raid milestones, to earn the Bloodbathed Frostbrood Vanquisher mount. Start with dungeon requirements before tackling the raid.", x = 2 },
        [4603] = { e = 5, s = "c", h = { 14631, 14627, 14632 }, r = "Requires full heroic raid clears; high RNG and mechanics.", d = "Finish every 25-player Icecrown Citadel achievement listed to unlock the Icebound Frostbrood Vanquisher mount. Ensure you have completed all prerequisite raids and dungeons before attempting this final goal.", x = 2 },
        [4604] = { e = 5, s = "c", h = { 13908, 13911, 13910 }, r = "Requires defeating multiple raid bosses; high skill/RNG.", d = "Clear the first four bosses of Icecrown Citadel in 25-player mode to unlock this account-wide achievement. Start with Lord Marrowgar and work through the raid normally, as no special conditions apply beyond the group size requirement.", x = 2 },
        [4605] = { e = 5, s = "c", h = { 15021, 15022, 15023 }, r = "Requires defeating multiple raid bosses; high skill/RNG.", d = "Defeat all bosses in The Plagueworks section of Icecrown Citadel using a full 25-player group. This is part of the main raid progression and requires no specific mechanics other than completing the encounter with the correct number of players.", x = 2 },
        [4606] = { e = 5, s = "c", h = { 12797, 12798 }, r = "Requires defeating multiple raid bosses; high skill/RNG.", d = "Complete The Crimson Hall bosses in 25-player mode as part of your standard Icecrown Citadel run. Ensure you have a full group to progress through Blood Prince Council and Blood-Queen Lana'thel without interruption.", x = 2 },
        [4607] = { e = 5, s = "c", h = { 15026, 15027 }, r = "Requires defeating multiple raid bosses; high skill/RNG.", d = "Finish The Frostwing Halls in 25-player mode by defeating Valithria Dreamwalker and Sindragosa. Treat this as a standard raid progression step, ensuring your group size meets the requirement for the entire section.", x = 2 },
        [4608] = { e = 5, s = "c", h = { 13852, 13855, 13856 }, r = "Requires clearing entire raid; high skill and RNG.", d = "Defeat every boss in Icecrown Citadel in 25-player mode to earn this high-point achievement. You must complete all raid sections including The Frozen Throne, so plan your run to cover the entire instance.", x = 2 },
        [4610] = { e = 5, s = "s", r = "High-skill execution on a single boss fight.", d = "Defeat Lord Marrowgar while keeping all raid members free of impalement for over eight seconds. Coordinate with healers and tanks to manage adds carefully and avoid letting anyone stay pinned down too long.", x = 2 },
        [4611] = { e = 5, s = "s", r = "High-skill execution with specific RNG condition.", d = "Kill Lady Deathwhisper with at least five different types of Cultists active simultaneously. Use abilities that spawn varied cultist types before the fight ends to meet this condition without resetting the encounter.", x = 2 },
        [4612] = { e = 5, s = "s", r = "High-skill execution on Gunship Battle mechanics.", d = "Win the Gunship Battle ensuring no raid member visits the enemy ship more than once. Assign specific players to handle each wave and avoid overloading any single person with multiple boarding attempts.", x = 2 },
        [4613] = { e = 5, s = "s", r = "High-skill execution with specific RNG condition.", d = "Defeat The Deathbringer before Mark of the Fallen Champion is cast five times. Focus on interrupting the boss's casting and managing adds quickly to prevent reaching the five-cast limit during the fight.", x = 2 },
        [4614] = { e = 5, s = "s", r = "High-skill execution with specific RNG condition.", d = "Kill Rotface without allowing a Big Ooze to cast Unstable Ooze Explosion. Monitor the oozes closely and kill them before they can use this ability to avoid triggering the achievement failure condition.", x = 2 },
        [4615] = { e = 5, s = "c", r = "Requires specific raid composition and avoiding a buff entirely.", d = "Defeat Festergut while ensuring no raid member ever reaches three stacks of Inoculated. Manage the plague mechanics carefully and avoid letting anyone accumulate too many stacks before killing the boss.", x = 2 },
        [4616] = { e = 5, s = "c", r = "Requires precise mechanics execution on a difficult boss.", d = "Kill Professor Putricide without using Regurgitated Ooze on the Abomination. Avoid casting this specific ability during the fight to satisfy the condition and complete the encounter successfully.", x = 2 },
        [4617] = { e = 5, s = "c", r = "Relies on RNG and strict damage cap management in raid.", d = "Coordinate with healers to cap single-target damage at 24,999. Use low-damage nukes or melee attacks during the Blood Council fight. Ensure no accidental AoE spells hit anyone hard.", x = 2 },
        [4618] = { e = 5, s = "c", h = { 17059, 17060 }, r = "Requires two specific fight outcomes with RNG mechanics.", d = "First run Lana'thel as a vampire by drinking her blood; second run avoid it entirely. Coordinate with healers to manage the transformation mechanic carefully between runs.", x = 2 },
        [4619] = { e = 5, s = "c", r = "High coordination needed to enter portals before boss heals.", d = "Prioritize running through Valithria's portals immediately upon spawning rather than healing her. Do not focus on healing until all portals are entered.", x = 2 },
        [4620] = { e = 5, s = "c", r = "Requires avoiding a specific buff on all raid members.", d = "Monitor Mystic Buffet stacks closely during Sindragosa. Use dispels or cooldowns to prevent anyone from reaching five stacks before the kill.", x = 2 },
        [4621] = { e = 5, s = "c", r = "Relies entirely on RNG to stack debuff to high number.", d = "Let Necrotic Plague stack naturally without using cleansing abilities until it hits 30. Avoid defensive cooldowns that might clear the debuff early.", x = 2 },
        [4622] = { e = 5, s = "c", r = "Requires killing adds before they explode in a raid fight.", d = "Kill every Vile Spirit immediately upon spawning before they explode. Assign specific players to track and eliminate them quickly.", x = 2 },
        [4624] = { e = 3, s = "s", r = "Standard dungeon run with specific encounter timing.", d = "Enter Shadowfang Keep during the Love is in the Air event. Locate and defeat the three Crown Chemical Co. apothecaries together.", x = 2 },
        [4628] = { e = 5, s = "c", h = { 14545, 14546, 14547 }, r = "Requires defeating multiple high-difficulty raid bosses.", d = "Queue for Icecrown Citadel Heroic 10-man and clear the first four bosses sequentially. Complete this before moving to other raid wings.", x = 2 },
        [4629] = { e = 5, s = "c", h = { 15522, 15523 }, r = "Requires defeating multiple high-difficulty raid bosses.", d = "Progress through The Plagueworks wing in Heroic 10-man mode. Defeat Festergut, Rotface, and Professor Putricide in order.", x = 2 },
        [4630] = { e = 5, s = "c", h = { 14555, 14556 }, r = "Requires defeating multiple high-difficulty raid bosses.", d = "Clear The Crimson Hall in Heroic 10-man mode. Focus on defeating the Blood Prince Council and Blood-Queen Lana'thel.", x = 2 },
        [4631] = { e = 4, s = "c", h = { 14348, 14347 }, r = "Requires full raid group and defeating multiple bosses.", d = "Advance through The Frostwing Halls in Heroic 10-man mode. Rescue Valithria Dreamwalker and defeat Sindragosa as the final step.", x = 2 },
        [4632] = { e = 4, s = "c", h = { 16801, 16798 }, r = "Requires full raid group and defeating multiple bosses.", d = "Queue for Icecrown Citadel Heroic 25-man and clear the first four bosses. Ensure your group is large enough to handle the mechanics efficiently.", x = 2 },
        [4633] = { e = 4, s = "c", h = { 18153, 18154 }, r = "Requires full raid group and defeating multiple bosses.", d = "Gather a full 25-player group to clear Festergut, Rotface, and Professor Putricide in Heroic Icecrown Citadel. This is account-wide, so coordinate with friends or guild members before entering the raid.", x = 2 },
        [4634] = { e = 4, s = "c", h = { 17442, 17441 }, r = "Requires full raid group and defeating multiple bosses.", d = "Assemble a 25-player team to defeat Blood-Queen Lana'thel and the Blood Prince Council in Heroic mode. Ensure your group has sufficient healing and damage output for these mechanics-heavy encounters.", x = 2 },
        [4635] = { e = 4, s = "c", h = { 17446, 17445 }, r = "Requires full raid group and defeating multiple bosses.", d = "Form a large 25-player group to rescue Valithria Dreamwalker and kill Sindragosa in the Frostwing Halls. Be prepared for complex mechanics that require precise coordination from all raid members.", x = 2 },
        [4636] = { e = 4, s = "c", h = { 18716, 18717 }, r = "Requires full raid group and defeating all bosses.", d = "Start with Storming the Citadel in 10-player Heroic to unlock the rest of Icecrown Citadel. Clear each wing sequentially, noting that this achievement is account-wide and requires a full roster.", x = 2 },
        [4637] = { e = 4, s = "c", h = { 17314, 17310 }, r = "Requires full raid group and defeating all bosses.", d = "Complete all five wings of Icecrown Citadel in 25-player Heroic mode, starting with Storming the Citadel. This massive undertaking requires organizing multiple groups or a very large raid over several sessions.", x = 2 },
        [4815] = { e = 4, s = "s", r = "Requires specific raid group to defeat a single boss.", d = "Defeat Halion in The Ruby Sanctum using a standard 25-player group before attempting Heroic. Ensure you have the necessary questline completed and are ready for the challenging mechanics of the first boss.", x = 2 },
        [4816] = { e = 4, s = "s", r = "Requires specific raid group to defeat a single boss.", d = "After defeating Halion in normal mode, recruit a 25-player group to tackle the Heroic version. This encounter is significantly harder, so ensure your team composition and gear are optimized for high difficulty.", x = 2 },
        [4817] = { e = 4, s = "s", r = "Requires specific raid group to defeat a single boss.", d = "Clear Halion in The Ruby Sanctum with a 10-player group as the first step. Once completed, you can progress to the Heroic version of this raid instance if desired.", x = 2 },
        [4818] = { e = 4, s = "s", r = "Requires specific raid group to defeat a single boss.", d = "Defeat Halion in 10-player Heroic mode after clearing the normal version. This requires a well-coordinated group capable of handling the increased difficulty and mechanics of the Heroic encounter.", x = 2 },
        [4825] = { e = 3, s = "g", r = "Requires exploring large zone with many points to find.", d = "Travel to Vashj'ir and explore every zone to reveal the map, including deep underwater areas. Use flight paths or swimming to access hidden regions and complete the exploration requirements efficiently.", x = 3 },
        [4826] = { e = 1, s = "s", r = "Trivial level check for legacy characters.", d = "This legacy achievement unlocks automatically upon reaching level 85 before the Shadowlands expansion. No action is needed other than leveling your character to the required threshold in a previous expansion era.", x = 3 },
        [4827] = { e = 3, s = "g", r = "Requires visiting multiple zones to see changes.", d = "Visit all listed locations across Kalimdor and the Eastern Kingdoms to witness Cataclysm changes. Fly or travel to each site to trigger the visual updates and complete the exploration requirements.", x = 3 },
        [4833] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat Ascendant Lord Obsidius in Blackrock Caverns to unlock the Heroic version. This is a straightforward dungeon kill with no special time gates or group requirements beyond standard dungeon composition.", x = 3 },
        [4839] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat Ozumat in Throne of the Tides for this achievement. It is a normal mode kill that unlocks Heroic; ensure you clear the dungeon fully before leaving to avoid missing any hidden mechanics.", x = 3 },
        [4840] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat Erudax in Grim Batol to complete this part of the dungeon set. This boss is accessible in normal mode and unlocks the Heroic version; no rare drops or specific timing are needed.", x = 3 },
        [4841] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat Rajh in Halls of Origination to claim this achievement. It is a standard dungeon kill that serves as the prerequisite for the Heroic version; focus on survival during his phase transitions.", x = 3 },
        [4842] = { e = 3, s = "g", r = "Requires defeating all bosses in one raid.", d = "Defeat all bosses in Blackwing Descent raid normal mode to earn these points. You must clear Magmaw, Omnotron, Maloriak, Atramedes, Chimaeron, and Nefarian; this unlocks the Heroic raid tier.", x = 3 },
        [4844] = { e = 4, s = "c", h = { 16681, 16682, 16683 }, r = "Requires completing multiple heroic dungeons.", d = "Complete every Cataclysm heroic dungeon achievement listed in the info field. This account-wide goal requires you to finish all normal mode bosses first, then re-run each dungeon on Heroic difficulty.", x = 3 },
        [4845] = { e = 4, s = "c", h = { 16707, 16718, 16692 }, r = "Requires completing all Cataclysm dungeon achievements.", d = "Finish every Cataclysm dungeon achievement including the main boss kills and other listed tasks. Completing this entire set unlocks the Volcanic Stone Drake mount; plan your rotation carefully to hit all sub-goals.", x = 3 },
        [4846] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat High Priestess Azil in The Stonecore dungeon normal mode. This kill is required before attempting the Heroic version; ensure you survive her phase changes and avoid unnecessary deaths.", x = 3 },
        [4847] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat Asaad in The Vortex Pinnacle to complete this achievement. It is a standard dungeon kill that unlocks the Heroic tier; focus on managing his adds and damage phases effectively.", x = 3 },
        [4848] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat Siamat, Lord of the South Wind in Lost City of the Tol'vir. This is the final boss of the dungeon normal mode; clear the instance fully before engaging him to avoid failure.", x = 3 },
        [4849] = { e = 4, s = "s", r = "Requires specific raid mechanics and timing.", d = "Damage Nefarian below 50% health before he lands for the final confrontation in Blackwing Descent. This requires careful raid management during his flight phase; do not kill him until this condition is met.", x = 3 },
        [4850] = { e = 4, s = "c", h = { 13129, 13131 }, r = "Valiona/Theralion and Ascendant Council are hardest.", d = "Defeat all bosses in the Bastion of Twilight raid normal mode. You must clear Halfus, Valiona and Theralion, Ascendant Council, and Cho'gall; this unlocks the Heroic version of the raid.", x = 3 },
        [4851] = { e = 4, s = "c", h = { 12486 }, r = "Al'Akir is the dominant difficulty factor.", d = "Defeat Conclave of Wind and Al'Akir in Throne of the Four Winds. This is a time-gated achievement requiring Cataclysm content to be unlocked first.", x = 3 },
        [4852] = { e = 4, s = "g", r = "Requires killing fiends then defeating raid bosses.", d = "Kill six Twilight Fiends in the Twilight Realm before defeating Valiona and Theralion in the Bastion of Twilight. Ensure you complete the prerequisite kills on the fiends first.", x = 3 },
        [4853] = { e = 5, s = "c", h = { 16602, 16605, 16614 }, r = "Heroic raids and specific mechanics dominate effort.", d = "Complete all listed Heroic raid achievements to earn this title and mount. This is a massive account-wide goal requiring significant time investment across multiple raids.", x = 3 },
        [4854] = { e = 3, s = "g", r = "Requires finding rare artifacts via archaeology.", d = "Find your first rare artifact to start the archaeology chain. You can obtain these from any zone while leveling or in dungeons once you have an archaeologist.", x = 3 },
        [4855] = { e = 3, s = "g", r = "Requires finding ten rare artifacts total.", d = "Locate ten rare artifacts total to progress your archaeology titles. Keep digging in various zones and dungeons until you hit the count.", x = 3 },
        [4856] = { e = 3, s = "g", r = "Requires finding twenty rare artifacts total.", d = "Find twenty rare artifacts to reach the next archaeology tier. This requires extensive exploration across Azeroth, often needing multiple characters or long play sessions.", x = 3 },
        [4857] = { e = 2, s = "g", r = "Relatively easy to gain archaeology skill points.", d = "Gain 150 skill points by excavating dig sites in archaeology zones. Focus on high-yield sites and use the Archaeology profession to maximize your progress.", x = 3 },
        [4858] = { e = 3, s = "c", h = { 16732 }, r = "Scepter of Charlga is the hardest to get.", d = "Recover all seven specific scepters from various races. These drop from rare mobs or world bosses, so check current loot tables for their locations.", x = 3 },
        [4859] = { e = 3, s = "c", r = "Requires discovering multiple Dark Iron artifacts.", d = "Discover seven Dark Iron artifacts to complete this set. These are found in the Deepholm zone and require finding specific chests or defeating local elites.", x = 3 },
        [4863] = { e = 2, s = "g", r = "Exploring zones is straightforward and fast.", d = "Explore every corner of Hyjal by revealing all covered map areas. Fly around the zone and check for hidden caves or fogged-in regions to clear.", x = 3 },
        [4864] = { e = 3, s = "g", r = "Grinding exploration points in Deepholm.", d = "Explore Deepholm by revealing all covered map areas. Use flight paths and dig sites to uncover every section of this dungeon zone.", x = 3 },
        [4865] = { e = 3, s = "g", r = "Grinding exploration points in Uldum.", d = "Explore Uldum by revealing all covered map areas. Fly over the desert and visit every dig site to ensure no zones remain unexplored.", x = 3 },
        [4866] = { e = 3, s = "g", r = "Grinding exploration points in Twilight Highlands.", d = "Travel to Twilight Highlands and explore every zone until the map is fully revealed. This is a time-gated achievement requiring Cataclysm content access, so ensure you have the expansion unlocked before starting.", x = 3 },
        [4868] = { e = 3, s = "g", r = "Requires exploring all Cataclysm zones.", d = "Visit Hyjal, Vashj'ir, Deepholm, Uldum, and Twilight Highlands to unlock their exploration status. This is account-wide, so any character can contribute by simply visiting these zones.", x = 3 },
        [4869] = { e = 3, s = "c", h = { 64872 }, r = "Killing The Tidehunter is the hardest part.", d = "Complete all Vashj'ir storylines listed in the achievement info. Note that some quests may be Alliance-exclusive, so ensure you are on the correct faction or use an alternate account if needed.", x = 3 },
        [4870] = { e = 3, s = "c", r = "Completing Mount Hyjal storylines.", d = "Finish all Mount Hyjal quest objectives including defeating Firelord and completing shrine tasks. These are account-wide, so progress made by any character counts toward the total.", x = 3 },
        [4871] = { e = 2, s = "c", r = "Completing Deepholm storylines.", d = "Complete Deepholm storylines such as collecting pillar fragments and mending the wound. This requires access to Deepholm, which is part of the Cataclysm expansion content.", x = 3 },
        [4872] = { e = 2, s = "c", r = "Completing Uldum storylines.", d = "Finish all Uldum quests including dealing with the Dark Pharaoh and Schnottz. These are account-wide achievements, so any character can help complete them.", x = 3 },
        [4873] = { e = 3, s = "c", r = "Completing Twilight Highlands storylines.", d = "Complete Twilight Highlands storylines like Firebeard's quest and The Eye of Twilight. Be aware this is Alliance-only, so Horde players must use an alternate account or wait for future changes.", x = 3 },
        [4874] = { e = 4, s = "g", r = "Grinding 100 daily quests in Tol Barad.", d = "Grind 100 daily quests in Tol Barad Peninsula. This can be time-consuming due to the daily reset limit, so plan your rotations carefully to maximize efficiency.", x = 3 },
        [4875] = { e = 3, s = "c", r = "Requires completing other Cataclysm achievements.", d = "Complete all Cataclysm quest achievements listed under this category. These are essentially meta-achievements that require finishing the other specific storylines first.", x = 3 },
        [4881] = { e = 3, s = "g", r = "Grinding reputation with Earthen Ring.", d = "Earn Exalted reputation with the Earthen Ring faction. This typically involves completing quests and turning in items in zones like Deepholm or Twilight Highlands.", x = 3 },
        [4882] = { e = 3, s = "g", r = "Grinding reputation to Exalted takes time.", d = "Reach Exalted status with the Guardians of Hyjal. Focus on quests and world events in Mount Hyjal to gain reputation efficiently.", x = 3 },
        [4883] = { e = 3, s = "g", r = "Grinding reputation to Exalted takes time.", d = "Gain Exalted reputation with Therazane. This usually involves completing specific quests or turning in items related to the Therazane storyline in Deepholm.", x = 3 },
        [4884] = { e = 3, s = "g", r = "Grinding reputation to Exalted takes time.", d = "Earn Exalted with Ramkahen Tol'vir in Uldum for Cataclysm content. This is account-wide and requires grinding reputation through daily quests or world drops.", x = 3 },
        [4885] = { e = 3, s = "g", r = "Grinding reputation to Exalted takes time.", d = "Reach Exalted status with the Wildhammer Clan by completing their specific reputation quests in Dragonblight. Ensure you are on the right faction side before starting.", x = 3 },
        [4886] = { e = 3, s = "g", r = "Grinding reputation to Exalted takes time.", d = "Gain Exalted with the Dragonmaw Clan via their unique reputation chain in Dragonblight. This is account-wide and often requires group assistance for rare drops.", x = 3 },
        [4888] = { e = 2, s = "s", r = "Ride a camel once in Uldum.", d = "Obtain a single-hump camel mount inside Uldum during Cataclysm content. Do not miss this opportunity as the mount cannot be obtained later.", x = 3 },
        [4892] = { e = 3, s = "c", h = { 12636, 62622, 62623 }, r = "Complete multiple specific quests in zone.", d = "Complete all listed Eastern Plaguelands quests to finish this storyline achievement. Check your quest log regularly to ensure no major storylines are skipped.", x = 0 },
        [4893] = { e = 3, s = "c", h = { 12639, 62650, 62653 }, r = "Complete multiple specific quests in zone.", d = "Finish the Western Plaguelands storylines by completing every required quest in that zone. These often involve faction-specific objectives so choose your side carefully.", x = 0 },
        [4894] = { e = 3, s = "c", h = { 15530, 15531, 62683 }, r = "Complete multiple specific quests in zone.", d = "Complete all Silverpine Forest quests including the repetitive On the Battlefront series. This is a large volume of work and may take significant time.", x = 0 },
        [4895] = { e = 3, s = "c", h = { 12642, 62626, 62627 }, r = "Complete multiple specific quests in zone.", d = "Clear Hillsbrad Foothills storylines by finishing each listed quest. Some involve faction reputation so ensure you are aligned correctly before starting.", x = 0 },
        [4896] = { e = 3, s = "c", h = { 65137, 65246 }, r = "Complete multiple specific quests in zone.", d = "Finish Arathi Highlands quests which include faction-specific objectives and daily turns. Make sure to complete both Alliance and Horde sides if required.", x = 0 },
        [4897] = { e = 3, s = "c", r = "Complete multiple specific quests in zone.", d = "Complete Hinterlands storylines by finishing all listed quests. This area often has time-gated content so do not delay your progress unnecessarily.", x = 0 },
        [4899] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Finish Loch Modan Alliance-only quests including the repetitive Farstrider Lodge turns. Since this is account-wide, any character can contribute to the total count.", x = 0 },
        [4900] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Complete Badlands storylines which include major Cataclysm-era quests like The Day that Deathwing Came. Ensure you are in the right zone before starting these specific tasks.", x = 0 },
        [4901] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Start these Burning Steppes quests immediately upon reaching Stranglethorn Vale. Complete them in order to unlock the next storyline, as missing steps will require a full region reset.", x = 0 },
        [4902] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Head to Redridge Mountains and follow the quest chain starting with The Gnoll Offensive. Finish all sub-quests quickly before leaving the zone to avoid time-gating issues.", x = 0 },
        [4903] = { e = 3, s = "c", r = "Multiple zone quests including a grind.", d = "Begin Westfall quests like Crime Scene Investigation early in your Alliance career. Note that some steps require killing many Defias members, so be prepared for repetitive combat.", x = 0 },
        [4904] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Travel to Swamp of Sorrows and start with Bogpaddle immediately. This chain involves significant world events; do not leave the zone until you finish Dar'Khan Drathir.", x = 0 },
        [4905] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Start Cape of Stranglethorn quests in Booty Bay right away. These involve multiple factions and rare mobs, so ensure you have a group for the tougher encounters.", x = 0 },
        [4906] = { e = 3, s = "c", r = "Multiple zone quests including a grind.", d = "Go to Northern Stranglethorn and begin with Yenniku without delay. This area has high-level content; bring a healer if you plan to tackle the expedition quests alone.", x = 0 },
        [4908] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Complete Ghostlands quests starting in Tranquillien as soon as you arrive. The Dar'Khan Drathir quest is long and requires specific NPC interactions, so plan your route carefully.", x = 0 },
        [4909] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Start Blasted Lands quests with Razelikh immediately upon entering the zone. This chain leads to major world events; do not skip any steps or you will need to restart.", x = 0 },
        [4910] = { e = 3, s = "c", r = "Multiple zone quests with some grinding.", d = "Head to Searing Gorge and begin with Thorium Advance right away. These quests involve raiding content; ensure your group is ready for high-level bosses before starting.", x = 0 },
        [4914] = { e = 2, s = "g", r = "Grinding profession skill points is easy.", d = "Grind two primary professions like Mining and Herbalism to gain Cataclysm skill points. Focus on gathering nodes in new zones to maximize efficiency without wasting time.", x = 3 },
        [4915] = { e = 3, s = "g", r = "Grinding 525 skill points across four professions takes several hours.", d = "Level up Fishing, First Aid, Cooking, and Archaeology simultaneously by doing daily quests. This legacy achievement requires massive XP, so grind consistently over many hours.", x = 3 },
        [4916] = { e = 2, s = "g", r = "Gaining 75 cooking skill points in a zone is quick and easy.", d = "Cook recipes in the Cataclysm category to gain skill points quickly. Visit cooking trainers frequently to unlock new recipes and avoid missing out on rare ingredients.", x = 3 },
        [4917] = { e = 2, s = "g", r = "Fishing up 75 skill points in a zone takes under an hour.", d = "Fish in any zone with Cataclysm content to gain skill points. This is a grind that requires no specific group but benefits from high-level fishing spots.", x = 3 },
        [4918] = { e = 3, s = "g", r = "Grinding First Aid to Grand Master level requires several hours of play.", d = "Grind First Aid by healing NPCs or completing quests until you reach Grand Master Medic. Note that this achievement chains directly into the Zen Master title.", x = 3 },
        [4919] = { e = 2, s = "g", r = "Gaining 225 archaeology skill points is a short, manageable grind.", d = "Dig up artifacts in any zone to gain Archaeology skill points. You must first unlock Journeyman Archaeologist before starting this chain of achievements.", x = 3 },
        [4920] = { e = 2, s = "g", r = "Gaining 300 archaeology skill points continues the easy progression.", d = "Continue digging artifacts to reach Artisan Archaeologist. This is a straightforward grind that requires no special items or group members.", x = 3 },
        [4921] = { e = 2, s = "g", r = "Gaining 375 archaeology skill points remains a short grind.", d = "Keep excavating ruins to gain Master Archaeologist status. Ensure you have unlocked the previous tier before attempting this milestone.", x = 3 },
        [4922] = { e = 2, s = "g", r = "Gaining 450 archaeology skill points is still an easy task.", d = "Dig up more artifacts to reach Grand Master Archaeologist. This step is purely skill-based and does not require rare drops or specific locations.", x = 3 },
        [4923] = { e = 2, s = "g", r = "Reaching the final archaeology tier is a quick completion.", d = "Finish your archaeology grind to become Illustrious Grand Master Archaeologist. This completes the main chain before moving to Zen Master status.", x = 3 },
        [4924] = { e = 2, s = "g", r = "Grinding 75 skill points in any Cataclysm profession is very easy.", d = "Grind any primary profession in a Cataclysm zone to gain 75 skill points. Examples include mining in Dazar'alor or herbalism in Suramar.", x = 3 },
        [4925] = { e = 3, s = "c", h = { 63432, 63434, 63436 }, r = "Completing Ashenvale quests involves multiple steps and some difficult fights.", d = "Complete the listed Ashenvale quests for Alliance characters. These are account-wide and often require visiting specific zones like Maestra's Post.", x = 0 },
        [4926] = { e = 3, s = "c", h = { 63308, 63310, 63312 }, r = "Bloodmyst Isle quests require completing several storylines with difficult bosses.", d = "Finish the Bloodmyst Isle quest chain for Alliance players. This involves defeating the Triumvirate members and completing lore-related objectives.", x = 0 },
        [4927] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Complete the Azshara quests available to Horde characters. Be aware that some of these may involve rare drops or specific zone traversal.", x = 0 },
        [4928] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Finish the Darkshore quest line for Alliance players. This area is part of the original game and contains several story-driven objectives.", x = 0 },
        [4929] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Complete all listed Dustwallow Marsh quests for Alliance. Start with the main storylines and ensure you finish every sub-quest to avoid missing points.", x = 0 },
        [4930] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Finish all Desolace quests available to any faction. These are often grouped by zone events, so check your quest log for the specific storyline requirements.", x = 0 },
        [4931] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Complete every Felwood quest listed. This area has many scattered objectives, so ensure you visit all key locations like Wildheart Point and Bloodvenom Post.", x = 0 },
        [4932] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Finish all Silithus quests for any faction. Focus on the Twilight's Run storyline first as it often unlocks other related objectives in the zone.", x = 0 },
        [4933] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Complete all Northern Barrens quests for Horde. Start with Far Watch and work through the Kolkar storyline to unlock subsequent rewards.", x = 0 },
        [4934] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Finish all Feralas quests for Alliance. These involve nature-themed storylines; ensure you interact with all relevant NPCs in the Twilight Highlands border area.", x = 0 },
        [4935] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Complete all Tanaris quests for any faction. The Southsea Pirates storyline is a good starting point, followed by the bug-related objectives.", x = 0 },
        [4936] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Finish all Stonetalon Mountains quests for Alliance. Clearing a Path is usually the first step, leading into the Warlord and Seldarria storylines.", x = 0 },
        [4937] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Complete all Southern Barrens quests for Alliance. Start with Honor's Stand and Northwatch Hold, then proceed to Teegan's Expedition and other objectives.", x = 0 },
        [4938] = { e = 2, s = "c", r = "Zone storylines; easy solo completion.", d = "Finish all Thousand Needles quests for any faction. The Treasure Trove is a primary objective; ensure you collect all necessary items before moving on.", x = 0 },
        [4939] = { e = 2, s = "c", r = "Complete several zone storylines in Un'Goro.", d = "Complete all Un'Goro Crater quests for any faction. These involve observing world events and specific characters like Maximillian in the crater zone.", x = 0 },
        [4940] = { e = 2, s = "c", r = "Complete several zone storylines in Winterspring.", d = "Finish all Winterspring quests for any faction. Start with The Winterfall Furbolg storyline and ensure you complete all winter-themed objectives in the area.", x = 0 },
        [4956] = { e = 3, s = "g", r = "Grind through 5 random dungeon quests.", d = "Start any dungeon quest chain immediately upon entering a dungeon to begin the counter. No special strategy is needed, just ensure you accept and finish five quests before turning in your next one.", x = 3 },
        [4957] = { e = 3, s = "g", r = "Grind through 20 random dungeon quests.", d = "This requires completing the previous 5-quest achievement first, so focus on dungeon quests consistently across multiple runs. There are no rare drops or time gates, making this a straightforward grind once started.", x = 3 },
        [4958] = { e = 3, s = "c", r = "Complete three specific zone storylines.", d = "Complete all three Ring of Blood instances in Nagrand, Zul'Drak, and Twilight Highlands to unlock this account-wide title. These are raid-level dungeons that may require group coordination but have no missable elements.", x = 3 },
        [4959] = { e = 2, s = "s", r = "Finish a single quest chain in Mount Hyjal.", d = "Progress through the Mount Hyjal jousting quests sequentially until you reach the Egg Wave finale. This is account-wide and requires no specific class, just following the quest chain to completion.", x = 3 },
        [4960] = { e = 3, s = "s", r = "Complete a specific long quest chain in Twilight Highlands.", d = "Finish the Crucible of Carnage quest line in Twilight Highlands up to The Twilight Terror! Ensure you accept each new quest as it becomes available to avoid missing steps.", x = 3 },
        [4961] = { e = 2, s = "s", r = "Finish a single quest chain in Uldum.", d = "Complete the Coffer of Promise quests in Uldum leading up to Harrison Jones and the Temple of Uldum. This account-wide achievement has no time gate but requires finishing the full chain.", x = 3 },
        [4975] = { e = 3, s = "s", r = "Defeat a specific boss in Vashj'ir.", d = "Defeat the Whale Shark in Vashj'ir by finding him in his lair; he drops no loot so focus solely on killing him for the achievement. No group is strictly necessary, though one may help with aggro management.", x = 3 },
        [4976] = { e = 2, s = "c", r = "Complete several zone storylines in Ashenvale.", d = "Complete all listed Ashenvale storylines for your faction, starting with The Corrupted Heart of the Forest. This is account-wide and requires no specific order, just finishing each quest in the region.", x = 0 },
        [4978] = { e = 2, s = "c", r = "Complete several zone storylines in Dustwallow Marsh.", d = "Finish every Dustwallow Marsh storyline quest listed in the achievement info. These are account-wide and can be done in any order once you have access to the zone.", x = 0 },
        [4979] = { e = 2, s = "c", r = "Complete several zone storylines in Feralas.", d = "Complete all Feralas storylines including The Fate of Taerar and Muisek. This account-wide achievement has no time gate, so take your time exploring the region if needed.", x = 0 },
        [4980] = { e = 2, s = "c", r = "Complete several short quests in one zone.", d = "Grind through all Stonetalon Mountains quests like A Short-Lived Victory and Legionnaire. Since this is account-wide, coordinate with friends if you want to speed up completion.", x = 0 },
        [4981] = { e = 2, s = "c", r = "Complete several short quests in one zone.", d = "Finish every Southern Barrens quest chain from Hunter's Hill to Spearhead. This account-wide achievement has no rare drops or time gates, making it a safe grind for any class.", x = 0 },
        [4982] = { e = 3, s = "c", h = { 64874 }, r = "Requires killing many specific fish (x130).", d = "Complete all listed Vashj'ir storylines to finish this account-wide achievement, ensuring you do not miss any required quests or rare drops like The Tidehunter which requires 130 kills. Start by accepting the initial quest chain and follow it through to completion while checking off each sub-achievement in your log.", x = 3 },
        [4995] = { e = 2, s = "c", r = "Explore a zone and find marked points.", d = "Explore every zone listed within Stranglethorn Vale, including Booty Bay and Crystalvein Mine, to reveal all covered areas on the world map. This is an account-wide exploration task so ensure you visit every location personally or have friends help cover any missed spots.", x = 0 },
        [4996] = { e = 2, s = "c", r = "Explore a zone and find marked points.", d = "Travel to The Barrens and explore zones like Bael Modan and Razorfen Kraul to uncover hidden areas and complete the exploration requirements. Since this is account-wide, coordinate with friends if you need help reaching specific hard-to-find locations quickly.", x = 0 },
        [5060] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Form a group capable of Heroic difficulty and defeat Ascendant Lord Obsidius in Blackrock Caverns, noting that this dungeon requires Cataclysm expansion access. Prepare your gear and skills beforehand as the encounter can be challenging on higher difficulties.", x = 3 },
        [5061] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Gather a team to face Ozumat in Throne of the Tides on Heroic mode, ensuring you have the necessary item level and knowledge of mechanics. This dungeon is time-gated by expansion availability so verify you are in Cataclysm content before starting.", x = 3 },
        [5062] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Defeat Erudax in Grim Batol on Heroic difficulty with a prepared group, paying attention to the boss's specific mechanics that require coordination. Ensure your party composition covers all roles needed for this challenging raid dungeon encounter.", x = 3 },
        [5063] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Assemble a group to defeat High Priestess Azil in The Stonecore on Heroic mode, requiring careful execution of her abilities and phase transitions. This achievement needs the Cataclysm expansion so confirm you have access before attempting the dungeon.", x = 3 },
        [5064] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Face Asaad in The Vortex Pinnacle on Heroic difficulty with a well-coordinated team to handle the complex mechanics involved. Prepare your group thoroughly as this boss fight demands precise timing and role fulfillment.", x = 3 },
        [5065] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Defeat Rajh in Halls of Origination on Heroic mode by forming a capable group familiar with the dungeon's layout and boss patterns. This achievement requires Cataclysm expansion access so ensure you are ready before entering the instance.", x = 3 },
        [5066] = { e = 3, s = "s", r = "Requires finding and defeating one boss.", d = "Challenge Siamat, Lord of the South Wind in Lost City of the Tol'vir on Heroic difficulty with a prepared party to manage her multiple phases. Coordinate your group's abilities effectively as this boss fight tests teamwork and strategic planning.", x = 3 },
        [5083] = { e = 2, s = "s", r = "One dungeon boss kill; trivial for a group.", d = "Defeat Vanessa VanCleef in Deadmines on Heroic difficulty by forming a group strong enough for the increased challenge level. This dungeon requires Cataclysm expansion access so verify your character meets the level and gear requirements before starting.", x = 3 },
        [5093] = { e = 2, s = "s", r = "One dungeon boss kill; trivial for a group.", d = "Gather a team to defeat Lord Godfrey in Shadowfang Keep on Heroic mode, ensuring you have the necessary gear and group composition. This achievement is tied to Cataclysm content so confirm you are ready for the increased difficulty before attempting the boss fight.", x = 3 },
        [5094] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Queue for Blackwing Descent Heroic and defeat Magmaw to earn this achievement. Ensure your group is prepared for the raid's mechanics before starting.", x = 3 },
        [5107] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Defeat Omnotron Defense System in Blackwing Descent on Heroic by coordinating with your team. This boss requires precise timing and damage management.", x = 3 },
        [5108] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Take down Maloriak in Blackwing Descent on Heroic difficulty as part of your raid progression. Focus on avoiding his elemental attacks during the fight.", x = 3 },
        [5109] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Defeat Atramedes in Blackwing Descent on Heroic to complete this objective. Be ready for his complex mechanics and high damage phases.", x = 3 },
        [5115] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Challenge Chimaeron in Blackwing Descent on Heroic mode. This boss demands strong coordination and attention to his multiple phases.", x = 3 },
        [5116] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Defeat Nefarian in Blackwing Descent on Heroic for this achievement and the title Blackwing's Bane. Prepare your group for his intense mechanics.", x = 3 },
        [5117] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Queue for Bastion of Twilight Heroic and defeat Valiona and Theralion together. Their fight requires careful positioning and damage control.", x = 3 },
        [5118] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Defeat Halfus Wyrmbreaker in Bastion of Twilight on Heroic difficulty. His mechanics involve managing adds and avoiding his devastating attacks.", x = 3 },
        [5119] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Take down the Ascendant Council in Bastion of Twilight on Heroic. This encounter is challenging and requires a well-coordinated team effort.", x = 3 },
        [5120] = { e = 4, s = "s", r = "Heroic raid boss; requires coordination and gear.", d = "Defeat Cho'gall in Bastion of Twilight on Heroic to complete this achievement. His fight involves managing multiple phases and avoiding his attacks.", x = 3 },
        [5121] = { e = 3, s = "s", r = "Single heroic raid boss kill.", d = "Challenge Sinestra in Bastion of Twilight on Heroic for the achievement and the title Dragonslayer. Her mechanics require precise execution from your group.", x = 3 },
        [5122] = { e = 3, s = "s", r = "Single heroic raid boss kill.", d = "Defeat Conclave of Wind in Throne of the Four Winds on Heroic difficulty. This boss requires managing adds and avoiding his powerful attacks.", x = 3 },
        [5123] = { e = 3, s = "s", r = "Single heroic raid boss kill.", d = "Queue for Throne of the Four Winds on Heroic mode immediately after unlocking it in Cataclysm. This is a time-gated achievement that requires the raid to be available; do not delay starting this content once you can access it.", x = 3 },
        [5180] = { e = 1, s = "s", r = "Buy skill from NPC after quest.", d = "Complete the Into the Wild Blue Yonder quest chain first to unlock Master Riding. Once finished, visit a riding trainer in your capital city to purchase the skill and claim the achievement instantly.", x = 3 },
        [5191] = { e = 3, s = "g", r = "Collect archaeology artifacts via digging.", d = "This archaeology achievement is account-wide and requires finding specific artifacts from the Darkmoon Faire event. Participate in the annual Darkmoon Faire to locate Pyramond's story items, as they are not available outside that event.", x = 3 },
        [5192] = { e = 3, s = "g", r = "Collect archaeology artifacts via digging.", d = "Gather these artifacts during the Darkmoon Faire event to complete this archaeology achievement. Since it is account-wide, any character on your account can contribute to finding the required items for the main story.", x = 3 },
        [5193] = { e = 3, s = "g", r = "Collect archaeology artifacts via digging.", d = "Collect the listed artifacts while attending the Darkmoon Faire event. This achievement tracks progress across all characters on your account, so ensure you are present at the fair when these specific drops occur.", x = 3 },
        [5208] = { e = 2, s = "g", r = "Win 2 PvP battles.", d = "Start playing Twin Peaks PvP battles to win two matches and unlock this achievement. You must personally participate in the battles; spectating or using other characters does not count toward your personal progress.", x = 3 },
        [5209] = { e = 4, s = "g", r = "Grind 100 PvP victories.", d = "After unlocking the previous step, continue playing Twin Peaks until you reach 100 total victories. This is a grind that requires consistent participation in the arena mode across multiple sessions to accumulate enough wins.", x = 3 },
        [5210] = { e = 3, s = "g", r = "Carry flag 2 times in PvP.", d = "Play Twin Peaks and focus on capturing the flag yourself at least twice. You must be the one carrying the flag when it is captured; teammates cannot substitute for your personal contribution to this specific goal.", x = 3 },
        [5211] = { e = 4, s = "g", r = "Grind returning 50 flags as defender.", d = "Defend the base in Twin Peaks and return flags as a defender fifty times. This requires active participation in defense roles rather than offense, so position yourself near the base to intercept enemy flag carriers effectively.", x = 3 },
        [5213] = { e = 4, s = "g", r = "Grind killing 100 flag carriers.", d = "Kill one hundred flag carriers while playing Twin Peaks. Focus on targeting players holding the flag during matches, as this specific kill type is required and standard enemy kills do not count toward this total.", x = 3 },
        [5214] = { e = 3, s = "g", r = "Grinding 100 flag carriers takes several hours of PvP.", d = "Kill one hundred flag carriers specifically belonging to the Alliance faction in Twin Peaks. This achievement tracks your kills against opposing team members carrying flags, so ensure you are targeting the correct faction during battles.", x = 3 },
        [5215] = { e = 3, s = "s", r = "Requires a specific win condition in one match.", d = "Win a Twin Peaks match with a final score of three to zero while securing at least one killing blow. Aim for a dominant victory where your team overwhelms the opponent quickly, and make sure you deal damage that results in a kill.", x = 3 },
        [5216] = { e = 4, s = "s", r = "Winning under 7 minutes is difficult and RNG-dependent.", d = "Focus on objective play and map control rather than pure dueling to secure wins quickly. Practice your route from the start gate to avoid unnecessary delays. This is a repeatable PvP achievement requiring multiple attempts.", x = 3 },
        [5219] = { e = 3, s = "s", r = "Killing 2 specific targets before they leave is hard.", d = "Prioritize killing enemy flag carriers near the Wildhammer Stronghold before they can retreat. Coordinate with teammates to focus fire on these targets immediately upon spotting them. This requires a single battle where you must kill two specific NPCs.", x = 3 },
        [5220] = { e = 3, s = "s", r = "Killing 2 specific targets before they leave is hard.", d = "Target enemy flag carriers near the Dragonmaw Forge area instead of chasing them elsewhere. Use crowd control abilities to prevent them from escaping quickly. You need to secure two kills in one match without leaving the zone.", x = 3 },
        [5221] = { e = 4, s = "s", r = "Capturing flag under 75s requires high skill and luck.", d = "Grab the flag immediately upon spawning and sprint directly to your capture point. Ignore all combat until you have secured the flag and returned it safely. Timing is critical as the 75-second limit applies to the entire process.", x = 3 },
        [5222] = { e = 4, s = "s", r = "Capturing flag under 75s requires high skill and luck.", d = "This entry appears identical to 5221; focus on grabbing and returning the flag within 75 seconds. Avoid engaging in prolonged fights that delay your return trip. Consistent execution of this objective is key.", x = 3 },
        [5223] = { e = 5, s = "c", r = "Requires completing all other Twin Peaks achievements first.", d = "Complete all other Twin Peaks achievements listed in the description before claiming this one. It acts as a summary reward for finishing the entire set. Ensure you have earned every prerequisite achievement first.", x = 3 },
        [5226] = { e = 3, s = "g", r = "Capturing 9 flags in one match is a long grind.", d = "Capture and return nine flags within a single battle to earn this title. You do not need to win the match, just complete the objective count. Coordinate with your team to cycle through flag captures efficiently.", x = 3 },
        [5227] = { e = 3, s = "g", r = "Capturing 9 flags in one match is a long grind.", d = "This entry is identical to 5226; focus on capturing nine flags in one game. Do not worry about winning the match, only the flag count matters. Keep moving between objectives to maximize your capture rate.", x = 3 },
        [5228] = { e = 3, s = "g", r = "Killing 5 Dwarves takes time and focus in one match.", d = "Aggressively hunt Dwarves near your base or while defending your flags. You need five kills in a single battle, so prioritize these targets over others. This is repeatable across multiple matches until the counter fills.", x = 3 },
        [5229] = { e = 3, s = "g", r = "Killing 5 Orcs takes time and focus in one match.", d = "Focus your attacks on Orcs during the match to reach the kill count of five. Do not let them retreat without engaging if you need these kills. This achievement is repeatable and requires a single battle per attempt.", x = 3 },
        [5230] = { e = 1, s = "s", r = "Single emote combo in PvP; trivial if conditions met.", d = "Wait for both speed and berserk power-ups to activate before grabbing the flag. Perform the roar emote while holding the flag under these buffs. Timing your ability usage with the buff duration is essential here.", x = 3 },
        [5231] = { e = 1, s = "s", r = "Win one match after being behind; single event.", d = "Let your team fall behind by two points early in the match to trigger this condition. Once behind, focus entirely on winning the battle from that deficit. This requires a specific score state before you can start fighting for victory.", x = 3 },
        [5245] = { e = 1, s = "s", r = "Win one match; account-wide flag makes it trivial.", d = "Queue for the Battle for Gilneas and win your first match to unlock this achievement. Ensure you are on the winning team before the timer ends.", x = 0 },
        [5246] = { e = 3, s = "g", r = "Grind 100 wins; effort shrinks steadily with each victory.", d = "This requires 100 total victories, so queue frequently in PUG groups. Track your wins via the game UI or a third-party tracker to avoid missing the count.", x = 0 },
        [5247] = { e = 3, s = "s", r = "Single match requirement; partial progress irrelevant.", d = "Focus on aggressive flag capture and defense to achieve a perfect 1500-0 score. Avoid risky plays that could lead to a loss or a low final margin.", x = 0 },
        [5248] = { e = 2, s = "g", r = "Collect 50 flags; steady progress reduces remaining effort.", d = "Prioritize capturing flags over killing enemies, as you need to physically take 50 of them. Do not let the enemy team hold any flag for too long.", x = 0 },
        [5249] = { e = 1, s = "s", r = "Assault two bases in one match; single event.", d = "Split your group between assaulting one base and defending another within the same match. Coordinate with teammates to ensure both objectives are hit.", x = 0 },
        [5250] = { e = 1, s = "s", r = "Defend two bases in one match; single event.", d = "Position yourself near a base that is under attack and help recapture it twice in one game. Communication is key to successfully defending two locations.", x = 0 },
        [5251] = { e = 3, s = "g", r = "Grind 10 recaps; steady progress reduces remaining effort.", d = "You must recap the flag ten times while defending, which often requires switching between bases. Stay mobile and ready to rush any base under threat.", x = 0 },
        [5252] = { e = 3, s = "s", r = "Single match with specific resource deficit; partial progress irrelevant.", d = "Start by capturing flags immediately to build a resource lead before the enemy can catch up. Avoid prolonged fights that drain your team's resources quickly.", x = 0 },
        [5253] = { e = 3, s = "g", r = "Grind 10 wins under condition; steady progress reduces effort.", d = "Win ten matches while simultaneously holding all three flags at the end. This requires strong teamwork and strategic positioning to maintain control of every base.", x = 0 },
        [5254] = { e = 3, s = "s", r = "Single match with time limit; partial progress irrelevant.", d = "Play aggressively from the start to secure a victory within six minutes. Focus on quick flag captures rather than grinding for kills or resources.", x = 0 },
        [5255] = { e = 3, s = "s", r = "Requires winning a PvP match with a score margin.", d = "Win by a narrow margin of 100 points or less to complete this challenge. Avoid overwhelming the enemy team too early and aim for a close finish.", x = 0 },
        [5256] = { e = 4, s = "c", h = { 19250, 19251 }, r = "Must assault and defend bases in one match.", d = "In a single match, switch roles to assault one base and defend another. Coordinate with your team to ensure both actions happen before the game ends.", x = 0 },
        [5257] = { e = 4, s = "g", r = "Grinding 30 kills across three specific bases.", d = "Queue for Battle for Gilneas and focus your team on securing kills at all three bases in one match. You must get exactly ten honorable kills at the Lighthouse, Mines, and Waterworks during a single run to complete this.", x = 0 },
        [5258] = { e = 5, s = "c", h = { 15743, 15747 }, r = "Requires completing multiple difficult sub-achievements.", d = "Complete every other Battle for Gilneas achievement listed in the info field before unlocking this one. Since it requires finishing specific sub-achievements, ensure you have cleared all prerequisites first.", x = 3 },
        [5262] = { e = 3, s = "s", r = "Timing an emote under a rare spawn event.", d = "Queue for a match and wait for the double rainbow to appear in the arena after a victory. Immediately use the /gasp emote while standing under it to claim this rare moment.", x = 0 },
        [5266] = { e = 4, s = "g", r = "Grinding arena rating to reach the threshold.", d = "Play 3v3 Arena matches until your personal rating reaches at least 2400. This is a time-gated achievement that requires you to climb the ladder in the 3v3 bracket.", x = 3 },
        [5267] = { e = 4, s = "g", r = "Continuing grind from previous rating tier.", d = "Continue playing 3v3 Arena matches until your personal rating hits 2700. You must first complete the 2400 rating achievement before this one becomes available.", x = 3 },
        [5268] = { e = 3, s = "s", r = "Winning a single rated battleground match.", d = "Win any single rated battleground match to earn this title. There are no specific class or faction requirements, just a standard victory in a rated queue.", x = 3 },
        [5269] = { e = 3, s = "s", r = "Winning a single rated battleground match.", d = "Win any single rated battleground match as a Horde player. This mirrors the Alliance version and requires only one win in a rated battleground context.", x = 3 },
        [5281] = { e = 4, s = "g", r = "Grinding specific mechanics on Heroic dungeon boss.", d = "Run Blackrock Caverns Heroic with a healer who can cleanse Rom'ogg's Skullcracker ability quickly. You need to kill ten Angered Earth elementals before defeating the boss to trigger this condition.", x = 3 },
        [5282] = { e = 4, s = "s", r = "Requires precise timing and coordination with mechanics.", d = "In Blackrock Caverns Heroic, let Corla's three zealots evolve fully without killing them first. Once they transform, defeat the evolved versions and then kill Corla to finish.", x = 3 },
        [5283] = { e = 4, s = "g", r = "Grinding stacks on a specific boss mechanic.", d = "Run Blackrock Caverns Heroic and wait for Karsh Steelbender to accumulate fifteen stacks of Superheated Quicksilver Armor. Do not kill him until he reaches this specific stack count.", x = 3 },
        [5284] = { e = 4, s = "s", r = "Requires specific mechanic execution on a raid boss.", d = "Run Blackrock Caverns Heroic with a party that can manage Crepuscular Veil stacks strictly. Ensure no one hits four stacks before defeating Ascendant Lord Obsidius.", x = 3 },
        [5285] = { e = 3, s = "s", r = "Timing-based mechanic during a dungeon encounter.", d = "Run Throne of the Tides Heroic and wait for Lady Naz'jar to use her Geyser ability on a minion. Let her kill that specific target to trigger this legacy achievement.", x = 3 },
        [5286] = { e = 3, s = "g", r = "Requires defeating specific adds with an active buff.", d = "Pull the Unyielding Behemoth immediately after Tidal Surge triggers to maximize damage windows. Coordinate your group to focus fire this specific mechanic while maintaining mobility against other adds.", x = 3 },
        [5287] = { e = 4, s = "g", r = "High-speed kill requirement against multiple adds.", d = "This requires a coordinated burst window during High Priestess Azil's phase; ensure your DPS rotation is ready instantly when Disciples spawn. Do not wait for the full wave to appear before engaging.", x = 3 },
        [5288] = { e = 4, s = "s", r = "Requires perfect avoidance of a specific mechanic.", d = "Avoid standing near static sources and use movement abilities to dodge Static Cling effects throughout the entire Asaad encounter. Position yourself carefully during phase transitions to minimize exposure time.", x = 3 },
        [5289] = { e = 3, s = "g", r = "Collecting multiple items in one dungeon run.", d = "Collect Golden Orbs efficiently by prioritizing them over other mechanics during your single run through Vortex Pinnacle. Ensure no one drops orbs before you secure all five in one visit.", x = 3 },
        [5290] = { e = 3, s = "g", r = "Requires killing specific adds with an active buff.", d = "Defeat the three Burning Souls quickly during High Prophet Barim's encounter to complete this objective. Focus your damage on these specific targets while managing the main boss mechanics.", x = 3 },
        [5291] = { e = 4, s = "g", r = "High-speed kill requirement against many adds.", d = "Time your burst damage to kill 20 Frenzied Crocolisks within a tight 10-second window during Lockmaw's phase. Coordinate with your group to maximize simultaneous damage output.", x = 3 },
        [5292] = { e = 3, s = "s", r = "Requires specific buff stacks on a raid boss.", d = "Stack Lightning Charge on yourself before engaging Siamat, Lord of the South Wind, to meet the requirement for victory. Maintain these stacks throughout the fight until the boss is defeated.", x = 3 },
        [5293] = { e = 4, s = "s", r = "Requires interrupting a long-duration mechanic.", d = "Interrupt Temple Guardian Anhuur's singing ability immediately if it exceeds 15 seconds to prevent Reverberating Hymn from completing. Use crowd control or interrupts strategically during his performance phases.", x = 3 },
        [5294] = { e = 3, s = "s", r = "Requires using a specific mount during a fight.", d = "Summon a camel mount before engaging Earthrager Ptah and maintain it throughout the entire fight in Halls of Origination. Ensure you do not dismount accidentally during critical moments.", x = 3 },
        [5295] = { e = 3, s = "s", r = "Requires interrupting a boss recharge phase.", d = "Defeat Rajh quickly before his recharging phase completes to avoid losing progress on this achievement. Focus your group's damage output on interrupting his recharge cycles.", x = 3 },
        [5296] = { e = 3, s = "s", r = "Requires precise timing and a skilled group.", d = "Optimize your run through Vault of Lights by minimizing downtime between pulls and avoiding unnecessary deaths. Aim to complete the entire dungeon within five minutes from entry.", x = 3 },
        [5297] = { e = 4, s = "c", r = "High RNG dependency on specific boss debuff.", d = "Apply Modgud's Malice debuff to General Umbriss before engaging him in Grim Batol. Coordinate with your group to maintain this effect until the boss is defeated.", x = 3 },
        [5298] = { e = 4, s = "c", r = "Requires precise mechanics and high skill.", d = "Focus on killing Faceless Corruptors instantly to prevent them from casting Twilight Corruption on eggs. This requires tight coordination and quick reaction times during the Erudax fight.", x = 3 },
        [5300] = { e = 4, s = "c", r = "Requires specific boss mechanics execution.", d = "Prioritize killing drakes immediately after spawning to meet the ten-second window before engaging Halfus. Treat the Emerald Whelp pack as a single drake for this requirement.", x = 3 },
        [5301] = { e = 4, s = "g", r = "Requires extensive archaeology digging across zones.", d = "This is an account-wide archaeology achievement requiring specific Tol'vir artifacts found in Uldum. You must excavate these items regardless of your character's level or class.", x = 3 },
        [5304] = { e = 4, s = "c", r = "Requires precise raid mechanics and coordination.", d = "Ensure every raid member maintains at least seven stacks of Wind Chill before engaging the Conclave of Wind. Use cooldowns and movement to avoid losing stacks during the fight.", x = 3 },
        [5305] = { e = 4, s = "c", r = "Requires specific boss debuff management.", d = "Apply Feedback debuffs to Al'Akir early in the encounter and maintain them throughout the entire fight. Coordinate with healers and damage dealers to keep the buff active.", x = 3 },
        [5306] = { e = 4, s = "c", r = "Requires precise raid mechanics and coordination.", d = "Avoid touching Magmaw's parasites and use crowd control abilities to prevent infection spreading through the raid. Position your group carefully to minimize parasite exposure.", x = 3 },
        [5307] = { e = 4, s = "c", r = "Requires precise raid mechanics and coordination.", d = "Neutralize all four attack types simultaneously by coordinating damage output and positioning. Assign specific players to handle each mechanic to avoid taking unnecessary damage.", x = 3 },
        [5308] = { e = 4, s = "c", r = "Requires precise raid mechanics and coordination.", d = "Monitor sound levels constantly during the Atramedes fight, as loud abilities can trigger the achievement failure condition. Use in-game volume settings and communication tools to stay under fifty percent.", x = 3 },
        [5309] = { e = 4, s = "c", r = "Requires precise raid mechanics and coordination.", d = "Accept that up to two deaths are allowed but aim for a clean run. Focus on minimizing damage intake while managing Chimaeron's mechanics efficiently.", x = 3 },
        [5310] = { e = 4, s = "c", r = "Requires precise boss mechanics execution.", d = "Kill twelve Aberrations within ten seconds before defeating Maloriak. Coordinate your team to focus fire on these adds quickly to meet the time limit.", x = 3 },
        [5311] = { e = 4, s = "c", r = "Requires precise raid control to limit mechanic spawns.", d = "Limit Liquid Ice patches created by Elementium Monstrosity to exactly one during the fight. Use crowd control and damage rotation to prevent additional patches from forming.", x = 3 },
        [5312] = { e = 4, s = "c", r = "Requires careful raid management during a difficult boss fight.", d = "Monitor Corrupted Blood levels closely and defeat Cho'gall before any raid member exceeds thirty percent corruption. Use defensive cooldowns and movement strategies to manage this mechanic effectively.", x = 3 },
        [5315] = { e = 3, s = "g", r = "Requires finding and excavating multiple unique artifacts.", d = "Start Archaeology and dig sites daily to find common artifacts. Focus on low-level sites first for quick progress, but note that some artifacts are rare drops or require specific site types.", x = 3 },
        [5317] = { e = 2, s = "g", r = "Requires killing a small number of mobs with one shot.", d = "Queue for the Fire From the Sky daily in Uldum and wait for the artillery shell event. Kill ten infantry instantly with one shot; this requires precise timing during the quest window.", x = 3 },
        [5318] = { e = 3, s = "s", r = "Requires completing a specific chain of quests in Vashj'ir.", d = "Travel to Vashj'ir and complete the Neptulon quest chain sequentially up to Defending the Rift. This is account-wide, so ensure your main character finishes it before moving on.", x = 3 },
        [5319] = { e = 3, s = "s", r = "Duplicate entry; requires completing a specific chain of quests.", d = "This entry duplicates 5318; simply follow the same advice for Vashj'ir Neptulon quests. Complete them in order to unlock the next stage of the account-wide achievement chain.", x = 3 },
        [5320] = { e = 3, s = "s", r = "Requires completing a specific quest chain in Twilight Highlands.", d = "Go to Twilight Highlands and finish the Twilight's Hammer quest line ending with Skullcrusher the Mountain. This is account-wide, so coordinate with friends if you need help finding the final quests.", x = 3 },
        [5321] = { e = 3, s = "s", r = "Duplicate entry; requires completing a specific quest chain.", d = "This entry duplicates 5320; repeat the same process for the Twilight Highlands quest chain. Ensure you have completed all previous steps in the account-wide progression before starting.", x = 3 },
        [5322] = { e = 3, s = "g", r = "Requires winning ten rated battlegrounds.", d = "Queue for rated battlegrounds and win ten matches to earn this title. It is account-wide, so any win on your account counts toward the total required for the next tier.", x = 3 },
        [5323] = { e = 3, s = "g", r = "Requires winning ten rated battlegrounds on the Horde side.", d = "Win ten rated battlegrounds while playing as a Horde character to unlock this specific title. Note that wins count toward the larger account-wide chain regardless of faction played.", x = 3 },
        [5324] = { e = 3, s = "g", r = "Requires winning twenty-five rated battlegrounds.", d = "Continue winning rated battlegrounds until you reach twenty-five total for this tier. This is part of a longer chain, so track your progress carefully to avoid missing the next step.", x = 3 },
        [5325] = { e = 3, s = "g", r = "Requires winning seventy-five rated battlegrounds.", d = "Win seventy-five rated battlegrounds to unlock the Veteran title and wolf mount. This requires significant time investment, so queue regularly and aim for high win rates efficiently.", x = 3 },
        [5326] = { e = 4, s = "g", r = "Requires winning 300 rated battlegrounds.", d = "Reach three hundred total wins to earn the Warbringer title and epic wolf. This is the final step in the chain, requiring patience and consistent participation in rated battlegrounds over time.", x = 3 },
        [5327] = { e = 3, s = "g", r = "Requires winning 25 rated battlegrounds.", d = "Win twenty-five rated battlegrounds as an Alliance character for this specific title. Like others, it feeds into the larger account-wide progression, so track your faction-specific wins carefully.", x = 3 },
        [5328] = { e = 4, s = "g", r = "Requires winning 75 rated battlegrounds.", d = "Queue for rated battlegrounds and win matches to reach 75 wins, which unlocks the next tier. This is account-wide so any character's progress counts toward your total. No specific strategy is needed beyond standard winning tactics.", x = 3 },
        [5329] = { e = 4, s = "g", r = "Requires winning 300 rated battlegrounds.", d = "Continue queueing until you hit 300 wins to claim the Warbound title and mount. Since this requires the previous achievement, ensure you have already unlocked it first. Progress carries over across all characters on your account.", x = 3 },
        [5330] = { e = 4, s = "g", r = "Requires reaching 1100 rating.", d = "Play rated battlegrounds or blitz until your rating reaches 1100 to earn the Private title. Focus on consistent performance rather than just winning every match to climb the ladder efficiently.", x = 3 },
        [5331] = { e = 4, s = "g", r = "Requires reaching 1200 rating.", d = "Keep playing rated content to push your rating from 1100 up to 1200 for the Corporal title. Your current rating resets occasionally, so monitor it closely after each season or major update.", x = 3 },
        [5332] = { e = 4, s = "g", r = "Requires reaching 1300 rating.", d = "Aim for a rating of 1300 in either mode to unlock the Sergeant title. Consistent participation is key as you climb through the mid-tier ratings where competition intensifies.", x = 3 },
        [5333] = { e = 4, s = "g", r = "Requires reaching 1400 rating.", d = "Push your rating past 1400 to earn the Master Sergeant title. This step requires steady wins and may take longer if you face tougher opponents in higher brackets.", x = 3 },
        [5334] = { e = 4, s = "g", r = "Requires reaching 1500 rating.", d = "Reach 1500 rating to claim the Sergeant Major title. Be prepared for increased difficulty as you approach this milestone, so maintain a positive mindset during losses.", x = 3 },
        [5335] = { e = 4, s = "g", r = "Requires reaching 1600 rating.", d = "Continue climbing to hit 1600 rating for the Knight title. This range often sees significant matchmaking adjustments, so adapt your playstyle accordingly to stay competitive.", x = 3 },
        [5336] = { e = 4, s = "g", r = "Requires reaching 1700 rating.", d = "Achieve 1700 rating to unlock the Knight-Lieutenant title. At this level, teamwork and objective control become even more critical for securing wins and gaining rating.", x = 3 },
        [5337] = { e = 4, s = "g", r = "Requires reaching 1800 rating.", d = "Strive for 1800 rating to earn the Knight-Captain title. Expect a steeper climb here as you face highly skilled opponents who will test your tactical knowledge.", x = 3 },
        [5338] = { e = 4, s = "g", r = "Requires significant time to reach high rating.", d = "Reach 1900 rating to obtain the Centurion title. This is a high-difficulty threshold where consistency and adaptability are essential for progress.", x = 3 },
        [5339] = { e = 4, s = "g", r = "Requires significant time to reach higher rating.", d = "Push your rating to 2000 to claim the Lieutenant Commander title. This final step in the chain demands peak performance and often requires grinding through many matches.", x = 3 },
        [5340] = { e = 4, s = "g", r = "Requires significant time to reach even higher rating.", d = "Grind Rated Battlegrounds until you hit 2100 rating to earn the Commander title. Focus on winning matches rather than just playing, as losses reset your progress toward the goal.", x = 3 },
        [5341] = { e = 4, s = "g", r = "Requires significant time to reach very high rating.", d = "Continue climbing from 2100 to 2200 rating for the Marshal title. Maintain a positive win rate to avoid falling back below the required threshold.", x = 3 },
        [5342] = { e = 4, s = "g", r = "Requires significant time to reach extremely high rating.", d = "Push your rating from 2200 up to 2300 for the Warlord title. Consistent performance in both standard and Blitz modes helps speed up this process.", x = 3 },
        [5343] = { e = 4, s = "g", r = "Requires significant time to reach maximum rating.", d = "Reach 2400 rating to claim the Grand Marshal title. This is a high-level goal requiring sustained success over many matches.", x = 3 },
        [5345] = { e = 2, s = "g", r = "Moderate grind to reach lower rating threshold.", d = "Start your journey by earning 1100 rating for the Scout title. New players should focus on learning mechanics while aiming for consistent wins.", x = 3 },
        [5346] = { e = 2, s = "g", r = "Moderate grind to reach slightly higher rating.", d = "Advance from 1100 to 1200 rating to get the Grunt title. Early game mistakes are common, so prioritize survival and team objectives.", x = 3 },
        [5347] = { e = 2, s = "g", r = "Moderate grind to reach mid-range rating.", d = "Climb from 1200 to 1300 rating for the Sergeant title. Improve your positioning and damage output to secure more victories.", x = 3 },
        [5348] = { e = 2, s = "g", r = "Moderate grind to reach upper-mid rating.", d = "Reach 1400 rating to earn the Senior Sergeant title. At this level, mastering class abilities becomes crucial for maintaining a positive rating.", x = 3 },
        [5349] = { e = 2, s = "g", r = "Moderate grind to reach high rating.", d = "Push your rating to 1500 for the First Sergeant title. You will face tougher opponents, so adapt your strategy accordingly.", x = 3 },
        [5350] = { e = 2, s = "g", r = "Moderate grind to reach very high rating.", d = "Achieve 1600 rating to obtain the Stone Guard title. This milestone requires strong teamwork and effective use of cooldowns.", x = 3 },
        [5351] = { e = 4, s = "g", r = "Requires significant time to reach 1700 rating.", d = "Grind from 1600 to 1700 rating for the Blood Guard title. Expect increased competition as you approach higher tiers.", x = 3 },
        [5352] = { e = 4, s = "g", r = "Higher rating requires more wins than lower ones.", d = "Finalize your progression by reaching 1800 rating for the Legionnaire title. This is an excellent benchmark for a well-rounded player.", x = 3 },
        [5353] = { e = 4, s = "g", r = "Reaching 2000 rating takes considerable effort.", d = "Play Rated Battlegrounds consistently to climb the ladder. Focus on winning matches and avoiding early elimination to reach 2000 rating efficiently.", x = 3 },
        [5354] = { e = 4, s = "g", r = "Rating 2100 is a substantial grind.", d = "Continue playing Rated Battlegrounds after reaching Champion. Maintain a high win rate to push your rating past 2100 for the next title.", x = 3 },
        [5355] = { e = 4, s = "g", r = "Rating 2200 requires consistent high-level play.", d = "Keep climbing in Rated Battlegrounds from Lieutenant General. Consistent performance is key to earning the General title at 2200 rating.", x = 3 },
        [5356] = { e = 4, s = "g", r = "Reaching 2400 rating is a long-term goal.", d = "Aim for High Warlord by reaching 2400 rating. This requires sustained success in Rated Battlegrounds over multiple seasons.", x = 3 },
        [5357] = { e = 4, s = "g", r = "Rating 2300 is difficult to achieve solo.", d = "Reach Field Marshal at 2300 rating between General and High Warlord. Play regularly to maintain your standing on the ladder.", x = 3 },
        [5359] = { e = 4, s = "g", r = "1900 rating is a moderate but lengthy grind.", d = "Start with Knight-Champion by earning 1900 rating. This is the first major milestone in the Rated Battlegrounds title progression.", x = 3 },
        [5363] = { e = 4, s = "g", r = "Massive kill count requires long-term grinding.", d = "Grind honorable kills across all PvP activities until you reach 250,000 total; this unlocks the Bloodthirsty title. It is an account-wide goal that requires consistent participation in battlegrounds and arenas.", x = 3 },
        [5366] = { e = 2, s = "s", r = "Simple avoidance mechanic in a dungeon.", d = "Run Deadmines Heroic as a tank or healer to avoid taking damage from the Fire Wall mechanic during Glubtok. This is a missable achievement if you fail to survive the specific encounter phase.", x = 3 },
        [5367] = { e = 2, s = "g", r = "Requires killing many small mobs during a fight.", d = "During Helix Gearbreaker in Deadmines Heroic, focus on killing Mine Rats without letting them spawn too many more. You need exactly 20 kills before defeating the main boss to secure this achievement.", x = 3 },
        [5368] = { e = 2, s = "s", r = "Simple tanking mechanic in a dungeon.", d = "In Deadmines Heroic, keep the Prototype Reaper above 90% health until Foe Reaper 5000 dies. This requires careful damage management and may require a dedicated healer or tank to monitor its health.", x = 3 },
        [5369] = { e = 4, s = "c", r = "Requires specific mechanics on Heroic Deadmines.", d = "In Deadmines Heroic, ensure three Freezing Vapors cast Coalesce on Admiral Ripsnarl. Coordinate with your group to trigger this mechanic reliably.", x = 3 },
        [5370] = { e = 2, s = "s", r = "Simple avoidance mechanic in one encounter.", d = "During the Cookie encounter in Deadmines Heroic, limit Nauseated stacks to one or fewer. Avoid standing near sources of nausea to prevent failure.", x = 3 },
        [5371] = { e = 4, s = "c", r = "Time limit and specific boss mechanics required.", d = "Use a Nightmare Elixir and immediately engage Vanessa VanCleef within five minutes in Deadmines Heroic. Time your pull carefully to meet the requirement.", x = 3 },
        [5372] = { e = 3, s = "g", r = "Requires farming gear to meet item level.", d = "Equip epic items in all slots with item level 359 or higher before Battle for Azeroth. Ensure every piece meets the minimum threshold.", x = 3 },
        [5373] = { e = 3, s = "g", r = "Requires farming gear to meet item level.", d = "Equip superior items in all slots with item level 333 or higher prior to Battle for Azeroth. Check your gear's item level carefully.", x = 3 },
        [5374] = { e = 5, s = "c", r = "Grinding 45 factions is extremely time-consuming.", d = "Raise forty-five reputations to Exalted across your account. Focus on factions that offer efficient grinding methods to reach the goal quickly.", x = 3 },
        [5375] = { e = 4, s = "g", r = "Requires extensive grinding to reach Exalted.", d = "Earn Exalted with Baradin's Wardens by completing Tol Barad quests and donating gold. This is account-wide, so coordinate with friends to speed up the grind.", x = 3 },
        [5376] = { e = 4, s = "g", r = "Requires extensive grinding to reach Exalted.", d = "Reach Exalted with Hellscream's Reach through daily quests in Orgrimmar and PvP activities. Note that this reputation is account-wide and requires significant time investment.", x = 3 },
        [5412] = { e = 4, s = "s", r = "Winning the war requires significant preparation.", d = "Win the battle for Tol Barad by defeating all enemy commanders on your side of the map. This achievement unlocks subsequent Tol Barad Veteran requirements.", x = 3 },
        [5415] = { e = 3, s = "g", r = "Requires destroying multiple towers over time.", d = "Destroy a tower in Tol Barad by capturing it during the main battle. Focus on securing high-ground towers for easier defense and destruction.", x = 3 },
        [5416] = { e = 4, s = "s", r = "Defeating the Pit Lord requires high skill.", d = "Defeat Pit Lord Argaloth after winning the Tol Barad battle. He spawns near the center of the map once the battle concludes.", x = 3 },
        [5417] = { e = 5, s = "g", r = "Winning 25 battles is a massive time sink.", d = "Win 25 battles for Tol Barad to earn Veteran status. This is account-wide and requires consistent participation in weekly or daily battles.", x = 3 },
        [5418] = { e = 4, s = "g", r = "Requires winning 25 battles in a contested PvP zone.", d = "Duplicate the previous achievement by winning another 25 Tol Barad battles. Ensure your characters are geared up for repeated combat success.", x = 3 },
        [5442] = { e = 3, s = "c", h = { 16832 }, r = "Recruiting all 8 characters; one is a rare spawn.", d = "Recruit all eight characters into Fiona's traveling party in Eastern Plaguelands. Complete the associated quests and visit each NPC to finalize recruitment.", x = 0 },
        [5443] = { e = 3, s = "c", h = { 20556 }, r = "Collecting E'ko from various creatures; one is rare.", d = "Obtain E'ko from various creatures in Winterspring by killing them. This is account-wide, so group up with friends to clear the area efficiently.", x = 0 },
        [5444] = { e = 3, s = "g", r = "Blast 12 goats in under a minute with specific gear.", d = "Blast 12 Billy Goats in under one minute using the Billy Goat Blaster. Practice your aim and ensure you have enough ammo for rapid fire.", x = 0 },
        [5445] = { e = 4, s = "s", r = "Defeat boss without taking damage from specific mechanics.", d = "Defeat Fungalmancer Glop during the daily quest without taking damage from Boomshrooms. Use crowd control abilities to avoid his explosive attacks.", x = 3 },
        [5446] = { e = 3, s = "g", r = "Complete a daily quest 10 times in Deepholm.", d = "Complete the Glop, Son of Glop daily quest ten times. This is account-wide, so coordinate with friends to maximize completion speed.", x = 3 },
        [5447] = { e = 4, s = "s", r = "Complete daily within strict time limit without damage.", d = "Start the Restless Brood daily in Deepholm and immediately strike the Resonating Crystal before moving to the boss. You must kill the boss within 90 seconds of striking the crystal, so rush straight through without looting or chatting.", x = 3 },
        [5448] = { e = 3, s = "s", r = "Gain stacks in a specific raid encounter without damage.", d = "Run Archmage Xylem's Trial of Fire in Azshara while avoiding all damage to build stacks safely. Do not use defensive cooldowns that interrupt your rotation if they cause you to take damage from the environment.", x = 0 },
        [5449] = { e = 3, s = "g", r = "Complete a daily quest 10 times to earn a pet.", d = "Complete the Lost in the Deeps daily quest ten times; this is account-wide so play with any character. Since it is a daily, plan to grind it every day until you reach the count.", x = 3 },
        [5450] = { e = 2, s = "s", r = "Stand in specific effects simultaneously; no combat needed.", d = "Find an area where multiple mushroom effects overlap and stand still to trigger all four debuffs simultaneously. Check your status effects frequently as they may wear off before you collect the last one.", x = 3 },
        [5451] = { e = 3, s = "s", r = "Endure a specific event in Twilight Highlands.", d = "Travel to the Twilight Highlands and enter Iso'rath's nightmare instance to endure the required duration. This is account-wide, so any character can complete it once you are inside.", x = 3 },
        [5452] = { e = 3, s = "s", r = "Witness three specific visions of an NPC.", d = "Locate the Naz'jar Battlemaiden in Vashj'ir and talk to her to witness all three visions. Ensure you do not leave the area before seeing each vision to avoid missing any.", x = 3 },
        [5453] = { e = 3, s = "s", r = "Requires finding a specific hidden secret in Darkshore.", d = "Go to Darkshore and investigate the Maw of the Void to discover the secret buried beneath it. This is a simple discovery achievement with no complex mechanics involved.", x = 0 },
        [5454] = { e = 2, s = "s", r = "Ride the Rocketway once; short and straightforward.", d = "Board the Rocketway in Azshara and ride from start to finish without dismounting or taking damage. Make sure you have enough gold for the ticket and that your mount is ready.", x = 0 },
        [5455] = { e = 3, s = "g", r = "Loot gold slowly; effort shrinks as count rises.", d = "Loot items worth 50,000 gold total; this is account-wide so farm gold with any character. Farm high-value loot drops or sell excess materials to reach the threshold quickly.", x = 3 },
        [5456] = { e = 4, s = "g", r = "Requires significantly more gold than the previous one.", d = "Loot items worth 100,000 gold total; this requires completing the previous 50k achievement first. Continue farming gold until you hit the higher threshold for account-wide credit.", x = 3 },
        [5469] = { e = 3, s = "g", r = "Find 50 unique artifacts; steady progress required.", d = "Dig up 50 unique common artifacts in archaeology sites across Azeroth. Focus on zones with many dig sites and avoid repeating artifact types to maximize efficiency.", x = 3 },
        [5470] = { e = 3, s = "g", r = "Find 100 unique artifacts; builds on previous work.", d = "Find 100 unique common artifacts after completing the previous tier. Keep digging until you have collected enough distinct artifacts, as duplicates do not count toward this goal.", x = 3 },
        [5471] = { e = 4, s = "g", r = "Learn 200 recipes; requires extensive profession time.", d = "Start by learning basic recipes and leveling your cooking skill to unlock new ones efficiently. Focus on gathering ingredients while questing or grinding mobs to maximize recipe discovery without wasting time.", x = 3 },
        [5472] = { e = 3, s = "g", r = "Cook 15 specific recipes; moderate effort per recipe.", d = "Cook the listed Cataclysm recipes repeatedly until you hit 15 of each; this is account-wide so any character can contribute. Ensure you have the required skill level and gather materials before cooking to avoid missing out on specific items.", x = 3 },
        [5473] = { e = 3, s = "g", r = "Cook 30 recipes; builds on previous cooking achievements.", d = "Continue cooking the same set of recipes to reach 30 of each, building on your progress from the previous tier. This requires patience as you must cook duplicates, so plan your material gathering sessions accordingly.", x = 3 },
        [5474] = { e = 2, s = "c", r = "Complete daily quests in Stormwind; low difficulty.", d = "Check the daily quests for Stormwind and complete them in order, ensuring you don't miss any due to time gates. These are account-wide, so coordinate with friends if needed or grind alone during off-peak hours.", x = 3 },
        [5475] = { e = 2, s = "c", r = "Complete daily quests in Orgrimmar; low difficulty.", d = "Complete the Orgrimmar cooking dailies similarly, noting that some may require specific ingredients found only in certain zones. Prioritize these daily quests early each day to avoid losing progress due to reset timers.", x = 3 },
        [5476] = { e = 2, s = "c", r = "Complete daily fishing quests in Stormwind; low difficulty.", d = "Finish all Stormwind fishing dailies by targeting the listed fish and completing associated tasks. Be mindful of daily resets and ensure you catch unique species required for completion.", x = 3 },
        [5477] = { e = 3, s = "c", r = "Requires completing multiple daily quests over time.", d = "Grind through Orgrimmar fishing dailies, focusing on catching rare fish and completing side objectives. Time-gating is a risk here, so plan your sessions around daily reset times to maximize efficiency.", x = 3 },
        [5478] = { e = 3, s = "g", r = "Collecting many specific freshwater fish via fishing.", d = "Catch 42 different freshwater fish by exploring various zones like Winterspring or Loch Modan. Use bait strategically and check fishing hotspots to find elusive species without wasting too much time.", x = 3 },
        [5479] = { e = 3, s = "g", r = "Collecting many specific saltwater fish via fishing.", d = "Target saltwater fish in coastal areas like Stranglethorn Vale or Azuremyst Isle, using appropriate bait for deep-sea creatures. Some rare fish may require specific conditions, so research spawn times and locations beforehand.", x = 3 },
        [5480] = { e = 2, s = "g", r = "Crafting a large number of bandages quickly.", d = "Craft Dense Embersilk Bandages by gathering embersilk cloth and tailoring them in bulk. This is a straightforward grind but can be time-consuming if you lack the necessary materials or skill level.", x = 3 },
        [5481] = { e = 3, s = "c", r = "Requires exploring ruins and killing specific mobs.", d = "Explore Thundermar Ruins thoroughly while killing Warlord Halthar, Karkrog the Exterminator, The Black Recluse spider, and Korthalon the Black. Ensure you visit every corner of the zone to satisfy the exploration requirement.", x = 3 },
        [5482] = { e = 3, s = "c", r = "Requires exploring ruins and killing specific mobs.", d = "Repeat the Thundermar Ruins exploration for Dragonmaw allies, targeting High Shaman MacKilligan, Dillan MacHurley, Gunwald Greybeard, Cliff Thundermar, The Black Recluse spider, and Korthalon the Black. Coordinate with group members if needed to clear all objectives efficiently.", x = 3 },
        [5483] = { e = 1, s = "s", r = "Simple timed interaction with a trampoline object.", d = "Find the trampoline in Whistling Grove and bounce continuously without touching the ground or walls. This is purely a solo activity with no time gate, but patience is key to reaching 20 consecutive bounces.", x = 3 },
        [5486] = { e = 3, s = "c", r = "Requires honorable kills across three Tol Barad zones.", d = "Queue for Tol Barad daily battles and focus your kills on the three specific zones listed in the achievement tracker. Since this is account-wide, any character can contribute, so coordinate with friends to cover all locations efficiently.", x = 3 },
        [5487] = { e = 2, s = "g", r = "Destroying siege engines during battles over time.", d = "Join large-scale Tol Barad battles and target deployed siege engines as they appear on the field. Destroying them requires focus during the battle, but there is no time limit if you persist through multiple events.", x = 3 },
        [5488] = { e = 3, s = "c", r = "Requires destroying three specific siege engines in one battle.", d = "During a single Tol Barad battle, prioritize destroying three siege engines before the event ends. This can be done solo or in a group, but ensure you do not leave the battlefield prematurely.", x = 3 },
        [5489] = { e = 4, s = "c", h = { 29108 }, r = "Requires completing multiple Tol Barad achievements including veteran status.", d = "Complete all listed Tol Barad sub-achievements to unlock this title. Since it requires finishing other specific goals, start with the easier ones like honorable kills and sabotage tasks first.", x = 3 },
        [5490] = { e = 4, s = "c", h = { 29110 }, r = "Requires completing multiple Tol Barad achievements including veteran status.", d = "Similar to the previous achievement, finish all required Tol Barad milestones including pit lord defeats and tower destructions. Coordinate with your account's characters to ensure every sub-goal is completed before claiming the reward.", x = 3 },
        [5501] = { e = 3, s = "c", r = "Requires multiple storylines in Twilight Highlands.", d = "Complete the full Twilight Highlands storyline quests for your faction, starting with returning to the highlands and progressing through each major plot point. This is account-wide, so any character can help finish the remaining story segments.", x = 3 },
        [5503] = { e = 4, s = "s", r = "Heroic dungeon boss with specific mechanic failure.", d = "In Heroic Shadowfang Keep, defeat Baron Ashbury while ensuring his Stay of Execution ability does not heal him. Use crowd control or damage-over-time strategies to interrupt his healing window consistently.", x = 3 },
        [5504] = { e = 4, s = "s", r = "Heroic dungeon boss with specific mechanic failure.", d = "Defeat Commander Springvale in Heroic Shadowfang Keep by preventing Unholy Empowerment from activating. Focus on keeping the boss below the empowerment threshold through constant pressure and proper cooldown management.", x = 3 },
        [5505] = { e = 4, s = "g", r = "Grinding 12 kills then defeating a Heroic boss.", d = "Use Pistol Barrage to kill 12 Bloodthirsty Ghouls before engaging Lord Godfrey in Heroic Shadowfang Keep. This requires precise timing and positioning, so practice the ability usage on lower difficulties first if needed.", x = 3 },
        [5506] = { e = 5, s = "c", h = { 17002, 16994, 17003 }, r = "Requires completing multiple raids and heroic dungeons.", d = "Complete all listed heroic dungeons and raids including Blackwing Descent and The Bastion of Twilight to earn the title. Start with the easier heroic dungeons to build gear before tackling the final raid content.", x = 3 },
        [5511] = { e = 4, s = "g", r = "Grinding archaeology artifacts across many races.", d = "Dig up archaeology artifacts from each race by exploring various zones and completing dig sites across Azeroth. This is account-wide, so share progress with friends to speed up collecting rare race-specific items.", x = 3 },
        [5518] = { e = 3, s = "s", r = "Waiting for Deathwing to kill you once.", d = "This achievement requires a specific boss kill by Deathwing in Cataclysm. Ensure you are present during the encounter and accept the fatal blow to complete it.", x = 3 },
        [5535] = { e = 4, s = "g", r = "Grinding 1000 Valor points over time.", d = "Valor Points are account-wide and earned through PvP activities like Battlegrounds and Arenas. Farm these consistently as they unlock higher tier currency goals.", x = 3 },
        [5536] = { e = 4, s = "g", r = "Grinding 5000 Valor points over time.", d = "You must first earn 1000 Valor Points before unlocking this milestone. Continue farming PvP content to accumulate the required points efficiently.", x = 3 },
        [5537] = { e = 4, s = "g", r = "Grinding 25,000 Valor points over time.", d = "This step requires 5000 Valor Points as a prerequisite. Keep participating in rated PvP modes to reach the next threshold quickly.", x = 3 },
        [5538] = { e = 4, s = "g", r = "Grinding 50,000 Valor points over time.", d = "Accumulate 25,000 Valor Points first, then farm additional points to reach this goal. Consistent PvP participation is key for large currency totals.", x = 3 },
        [5539] = { e = 4, s = "g", r = "Grinding 50,000 Conquest points over time.", d = "Conquest Points are earned in Rated Battlegrounds and Arenas. Reach the 25,000 point requirement before attempting this higher tier achievement.", x = 3 },
        [5540] = { e = 2, s = "g", r = "Grindable currency; trivial once active.", d = "Start by earning 5000 Conquest Points, then continue farming rated PvP content to reach the 25,000 point milestone needed for this goal.", x = 3 },
        [5541] = { e = 1, s = "g", r = "Small grind; trivial for active players.", d = "Earn 1000 Conquest Points first through rated PvP activities. This unlocks the next tier and helps you progress toward larger currency goals.", x = 3 },
        [5542] = { e = 1, s = "g", r = "Tiny grind; trivial for active players.", d = "This is the entry-level Conquest achievement requiring only 1000 points. Farm any rated PvP mode to quickly accumulate enough points for this goal.", x = 3 },
        [5546] = { e = 3, s = "s", r = "Specific mechanic trial; moderate difficulty.", d = "Enter Archmage Xylem's Trial of Frost in Azshara and focus on gaining Essence of Ice stacks while avoiding all damage to reach the required count.", x = 0 },
        [5547] = { e = 3, s = "s", r = "Specific mechanic trial; moderate difficulty.", d = "In Archmage Xylem's Trial of Shadow, trap Weeping Souls without taking any damage. Use traps strategically and maintain your health throughout the encounter.", x = 0 },
        [5548] = { e = 2, s = "c", r = "Collect critters; easy checklist grind.", d = "Use the /love command on various critters found across Azeroth to complete this collection. Check the full list of animals to ensure you have loved them all.", x = 3 },
        [5552] = { e = 2, s = "s", r = "Specific PvP condition; moderate effort.", d = "Queue for Twin Peaks and aim to win by a narrow margin. If you fall behind early, stay aggressive but avoid overextending until the score gap closes.", x = 3 },
        [5718] = { e = 4, s = "c", h = { 14753, 14750, 14751 }, r = "Daily quests; some are rare spawns.", d = "Complete all listed Tol Barad daily quests on your character or any alt since it is account-wide. Check the quest log frequently as these dailies reset weekly.", x = 3 },
        [5719] = { e = 4, s = "c", h = { 12552, 12535, 12562 }, r = "Daily quests; some are rare spawns.", d = "This is a duplicate entry for the same Tol Barad achievement; complete the daily quests listed in the info field to finish it.", x = 3 },
        [5723] = { e = 4, s = "g", r = "Grinding rep to Exalted is long.", d = "Grind reputation grinds with factions that offer Exalted rewards or use world drop vendors. Track your progress carefully as you need exactly fifty unique reputations.", x = 3 },
        [5743] = { e = 4, s = "s", r = "Zero tolerance raid encounter; hard.", d = "Run Zul'Gurub Heroic and strictly avoid the specific poison effects from High Priest Venoxis. Coordinate with your group to cleanse or mitigate these debuffs immediately.", x = 3 },
        [5744] = { e = 4, s = "c", h = { 19542, 19543, 19544 }, r = "Kill all bosses; some are rare spawns.", d = "Clear all listed bosses in Zul'Gurub Heroic mode to earn this achievement. Ensure you have the necessary gear and group composition for Heroic difficulty.", x = 3 },
        [5749] = { e = 1, s = "s", r = "One-time mount ability test.", d = "Transform into a dragon form using the appropriate ability while carrying an ally to complete this mount-related task. This usually requires specific class abilities or items.", x = 3 },
        [5750] = { e = 3, s = "c", r = "Heroic dungeon with totem mechanic.", d = "Defeat Halazzi in Zul'Aman Heroic without killing his totems. Focus your damage on the boss while avoiding totem aggro and using crowd control wisely.", x = 3 },
        [5751] = { e = 4, s = "g", r = "Grinding daily quests for long time.", d = "Accept and complete daily quests consistently across all zones to reach the two-thousand-five-hundred mark. This is a long-term goal requiring steady play over many weeks.", x = 3 },
        [5752] = { e = 3, s = "g", r = "Grinding quest gold over time.", d = "Earn gold specifically from quest rewards rather than world drops or vendors. Track your earnings and prioritize high-value quests to reach thirty-thousand gold efficiently.", x = 3 },
        [5753] = { e = 4, s = "c", r = "Many rare food items to find.", d = "Sample every listed Cataclysm food item by eating them once. Visit various zones like Gilneas or the Isle of Giants to find these specific delicacies.", x = 3 },
        [5754] = { e = 4, s = "c", r = "Many rare drinks to find.", d = "Drink each listed Cataclysm beverage to complete this collection. These items are often found in world drops, vendor lists, or specific zone vendors across Azeroth.", x = 3 },
        [5755] = { e = 3, s = "g", r = "Collecting many tabard appearances.", d = "Unlock the tabard slot in your character's appearance settings first. Then equip different tabards to count toward the total of thirty required appearances.", x = 3 },
        [5759] = { e = 4, s = "c", r = "Heroic dungeon with tight timing.", d = "Run Zul'Gurub Heroic and focus on killing Twisted Spirits quickly during Jin'do's phase. Ensure you kill twenty within fifteen seconds or the achievement will fail.", x = 3 },
        [5760] = { e = 3, s = "c", r = "Heroic dungeon with movement mechanic.", d = "Pull Daakara in Zul'Aman Heroic and keep your entire group inside the turquoise stonework circle. Never step outside the boundary until he is defeated.", x = 3 },
        [5761] = { e = 4, s = "c", r = "Heroic dungeon with multiple saves.", d = "In Zul'Aman Heroic, use the Hex removal ability on every potential victim before they die. Save all NPCs listed in the info to complete the set.", x = 3 },
        [5762] = { e = 3, s = "s", r = "Heroic dungeon with pet mechanic.", d = "Defeat Bloodlord Mandokir in Zul'Gurub Heroic while protecting Ohgan at all costs. Do not kill Ohgan or you will miss this specific requirement.", x = 3 },
        [5765] = { e = 4, s = "c", r = "Heroic dungeon with feeding prep.", d = "Feed Temple Rats to four of Bethekk's Pride cats before engaging High Priestess Kilnara in Zul'Aman Heroic. Ensure all four cats are fed first.", x = 3 },
        [5768] = { e = 4, s = "s", r = "Heroic dungeon requires group coordination and gear.", d = "This is the main raid clear for Zul'Gurub on Heroic Difficulty. Defeat Jin'do the Godbreaker to unlock this and related achievements.", x = 3 },
        [5769] = { e = 4, s = "s", r = "Heroic dungeon requires group coordination and gear.", d = "Clear all bosses in Zul'Aman on Heroic Difficulty to earn this title. It requires defeating Daakara as the final boss of the dungeon.", x = 3 },
        [5779] = { e = 2, s = "g", r = "Easy to eat cookies; just need many stacks.", d = "Cook and eat Chocolate Cookies repeatedly until you reach ninety-one stacks of the Satisfied buff. This is a grind but has no time limit.", x = 3 },
        [5794] = { e = 1, s = "s", r = "Talk to guild members or donate gold/items.", d = "Earn Exalted reputation with your guild to unlock this achievement. You must be in an active guild and complete all necessary reputation tasks.", x = 3 },
        [5799] = { e = 4, s = "s", r = "High skill raid fight with strict mechanics.", d = "In Firelands, activate both of Fandral's Flames simultaneously while avoiding the Kneel to the Flame mechanic. Coordinate your raid to avoid damage.", x = 3 },
        [5802] = { e = 4, s = "c", h = { 18260, 18258, 18262 }, r = "Raid bosses; hardest are RNG-dependent or mechanics.", d = "Defeat all bosses in the Firelands raid instance on any difficulty. This includes Ragnaros and every other boss listed in the info field.", x = 3 },
        [5803] = { e = 4, s = "s", r = "Heroic raid boss requires group and high gear.", d = "Queue for Firelands Heroic with a prepared raid group to defeat Ragnaros. Ensure your team has sufficient healing and damage output as this is a time-gated achievement requiring the full raid to be present.", x = 3 },
        [5804] = { e = 4, s = "s", r = "Heroic raid boss requires group and high gear.", d = "Defeat Majordomo Fandral Staghelm in Firelands Heroic mode with a coordinated raid. This boss requires precise mechanics management and is best tackled after clearing earlier Firelands bosses to ensure group readiness.", x = 3 },
        [5805] = { e = 4, s = "s", r = "Heroic raid boss requires group and high gear.", d = "Bring a full raid to Firelands Heroic to defeat Baleroc. Coordinate with your team to handle his tank swap mechanics efficiently, as this encounter can be challenging for groups not familiar with the fight.", x = 3 },
        [5806] = { e = 4, s = "s", r = "Heroic raid boss requires group and high gear.", d = "Queue for Firelands Heroic and defeat Shannox with a prepared raid. Focus on managing her adds and avoiding her cleave attacks, ensuring all raid members are positioned correctly during key phases.", x = 3 },
        [5807] = { e = 4, s = "s", r = "Heroic raid boss requires group and high gear.", d = "Defeat Beth'tilac in Firelands Heroic with a full raid group. Pay close attention to her web mechanics and ensure no raid member is caught in the webs while dealing with her adds.", x = 3 },
        [5808] = { e = 4, s = "s", r = "Heroic raid boss requires group and high gear.", d = "Queue for Firelands Heroic to defeat Lord Rhyolith. This boss requires careful positioning and timing of his armor phases, making it essential to have a well-coordinated raid group ready.", x = 3 },
        [5809] = { e = 3, s = "s", r = "Heroic raid boss kill.", d = "Defeat Alysrazor in Firelands Heroic with a prepared raid. Manage her flight phase mechanics carefully and ensure all raid members avoid her area-of-effect attacks during the encounter.", x = 3 },
        [5810] = { e = 4, s = "g", r = "Requires precise dodging during a long fight.", d = "Defeat Lord Rhyolith in Firelands Heroic without causing him to turn left while his armor is intact. This requires precise timing and positioning, as any mistake can cause him to turn left and fail the achievement.", x = 3 },
        [5813] = { e = 4, s = "g", r = "Heroic boss kill with strict zero-hit requirement.", d = "Defeat Alysrazor in Firelands Heroic without any raid member being hit by specific attacks. Coordinate with your team to avoid her area-of-effect abilities like Brushfire and Fiery Tornado throughout the encounter.", x = 3 },
        [5821] = { e = 3, s = "s", r = "Specific mechanic during a Heroic raid fight.", d = "During Beth'tilac in Firelands Heroic, only kill Cinderweb Drones while they are atop the web canopy. This requires careful timing and positioning to ensure you do not damage them when they are on the ground.", x = 3 },
        [5823] = { e = 4, s = "g", r = "Winning 150 rated battlegrounds is a long grind.", d = "Win 150 rated battlegrounds as part of the Alliance faction. This is a long-term goal requiring consistent participation in rated battlegrounds and can be tracked through your character's achievement progress.", x = 3 },
        [5824] = { e = 4, s = "g", r = "Winning 150 rated battlegrounds is a long grind.", d = "Win 150 rated battlegrounds as part of the Horde faction. Similar to the Alliance version, this requires consistent participation in rated battlegrounds and tracking your wins towards the goal.", x = 3 },
        [5827] = { e = 3, s = "g", r = "Requires significant reputation grinding.", d = "Earn Exalted with the Avengers of Hyjal by completing their reputation quests and turning in items. This is a long-term grind requiring significant time investment, so focus on daily quests first before tackling world drops or dungeons for extra rep points.", x = 3 },
        [5828] = { e = 4, s = "c", h = { 17746, 17750, 17752 }, r = "Requires completing all listed Firelands raid achievements.", d = "Complete all Firelands raid achievements listed, including heroic bosses and specific encounter milestones like Death from Above. Coordinate with your raid group to ensure every member contributes to these objectives, as some require specific mechanics or kills that cannot be soloed.", x = 3 },
        [5829] = { e = 3, s = "s", r = "Complex single-fight mechanic with multiple sub-goals.", d = "During a single Shannox fight, drag him to each specified location before killing him. This requires careful planning and coordination with your raid to avoid accidentally defeating him prematurely, so communicate clearly with your group about the order of locations.", x = 3 },
        [5830] = { e = 4, s = "g", r = "Heroic boss kill with strict zero-torment requirement.", d = "Defeat Baleroc while keeping all raid members under three Torment stacks. Use defensive cooldowns and healing efficiently to manage the Torment mechanic, as exceeding the limit will reset progress and require another attempt.", x = 3 },
        [5835] = { e = 2, s = "c", r = "Visiting scattered locations in Northrend and Dalaran.", d = "Visit every Candy Bucket in Northrend zones during Hallow's End events. These are account-wide achievements, so coordinate with friends or join a group to cover all locations quickly before the event ends.", x = 3 },
        [5836] = { e = 2, s = "c", r = "Visiting scattered locations in Northrend and Dalaran.", d = "Complete the second set of Candy Buckets in Northrend by visiting each listed location during Hallow's End. Ensure you visit all spots in both this and the previous achievement to avoid missing any buckets due to overlapping or separate event timers.", x = 3 },
        [5837] = { e = 1, s = "c", r = "Visit scattered buckets; trivial and fast.", d = "Visit all Candy Buckets in Cataclysm zones like Mount Hyjal, Twilight Highlands, and Vashj'ir during Hallow's End. These are account-wide, so team up with others to cover multiple zones efficiently before the event concludes.", x = 3 },
        [5838] = { e = 1, s = "c", r = "Visit scattered buckets; trivial and fast.", d = "Finish the second set of Cataclysm Candy Buckets by visiting each location listed. Like other Hallow's End achievements, these are account-wide and time-gated, so prioritize them early in the event to avoid missing out on rewards.", x = 3 },
        [5841] = { e = 2, s = "c", r = "Daily quests grind; easy solo completion.", d = "Complete all Ironforge cooking daily quests to earn this achievement. Check your quest log regularly for new dailies, as they reset daily and may vary based on current game events or NPC availability.", x = 3 },
        [5842] = { e = 2, s = "c", r = "Daily quests grind; easy solo completion.", d = "Finish all Darnassus cooking dailies by accepting and completing each quest in the list. These are account-wide and time-gated, so plan your profession time around their reset schedule to avoid delays.", x = 3 },
        [5843] = { e = 2, s = "c", r = "Daily quests grind; easy solo completion.", d = "Complete every Thunder Bluff cooking daily quest listed. Like other cooking achievements, these are account-wide and require consistent daily effort, so set aside time each day to grind through them efficiently.", x = 3 },
        [5844] = { e = 2, s = "c", r = "Daily quests grind; easy solo completion.", d = "Finish all Undercity cooking dailies by completing each quest in the list. These are account-wide and time-gated, so prioritize them early in the event or during off-peak hours to avoid conflicts with other activities.", x = 3 },
        [5845] = { e = 2, s = "c", r = "Combines faction dailies; moderate total time.", d = "Start by visiting the four capital cities to complete the Let's Do Lunch cooking quests. Since these are account-wide, any character can finish them once you have learned Cooking.", x = 3 },
        [5847] = { e = 2, s = "c", r = "Daily fishing quests; easy solo completion.", d = "Travel to Ironforge and queue for each of the five daily fishing quests listed in the info field. These reset daily, so plan your schedule around completing all five within a week.", x = 3 },
        [5848] = { e = 2, s = "c", r = "Daily fishing quests; easy solo completion.", d = "Head to Darnassus and complete the five specific daily fishing quests available there. Remember that these are account-wide, allowing any character on your account to contribute.", x = 3 },
        [5849] = { e = 2, s = "c", r = "Combines faction dailies; moderate total time.", d = "Go to Thunder Bluff and finish the five daily fishing quests listed in the achievement info. Like other capital city fishing dailies, these reset every 24 hours.", x = 3 },
        [5850] = { e = 2, s = "c", r = "Daily fishing quests; easy solo completion.", d = "Visit Undercity and complete the five daily fishing quests available in that zone. Once you have finished all four city sets, this summary achievement will unlock automatically.", x = 3 },
        [5851] = { e = 2, s = "c", r = "Combines faction dailies; moderate total time.", d = "This achievement simply requires you to finish all other Fish or Cut Bait achievements first. There is no separate action needed; just ensure every capital city set is complete.", x = 3 },
        [5853] = { e = 1, s = "c", r = "Trivial: Visit 4 cities with an item.", d = "Equip the Gaudy Winter Veil Sweater and use your Chorus Book in enemy capitals during the Feast of Winter Veil event. Note that this is time-gated to the specific holiday window each year.", x = 3 },
        [5854] = { e = 1, s = "c", r = "Trivial: Visit 4 cities with an item.", d = "Use your Chorus Book in friendly capitals while wearing the Gaudy Winter Veil Sweater during the holiday event. This part of the achievement unlocks after finishing the enemy capital versions.", x = 3 },
        [5855] = { e = 4, s = "s", r = "Hard: Requires specific raid mechanics and RNG.", d = "Enter Molten Core and defeat Ragnaros while ensuring three Living Meteors are ignited by Lava Wave before killing him. This is a raid boss fight that requires coordination with your group.", x = 3 },
        [5858] = { e = 3, s = "c", r = "Moderate: Save 4 prisoners on Heroic Zul'Aman.", d = "Queue for Heroic Zul'Aman and focus on saving all four prisoners before they are sacrificed. This achievement is account-wide, so any character can complete it.", x = 3 },
        [5859] = { e = 2, s = "c", r = "Easy: Complete a few zone quests.", d = "Travel to Mount Hyjal and the Molten Front to find and complete the Leyara quest chain. Be aware that this content may be time-gated or require specific zone access.", x = 3 },
        [5860] = { e = 3, s = "g", r = "Moderate: Repeat daily quest 10 times.", d = "Complete the Vigilance on Wings daily quest in Mount Hyjal ten times total. Since it is a daily, you will need to visit the zone repeatedly over several days.", x = 3 },
        [5861] = { e = 2, s = "c", r = "Easy: Kill 4 specific mobs in a zone.", d = "Slay the four named minions in Sethria's Roost, which is time-gated by the Molten Front attack. Ensure you are in the zone during the event window to complete this account-wide objective.", x = 3 },
        [5862] = { e = 1, s = "g", r = "Trivial: Collect stacks during a quest.", d = "Accept Call the Flock in Mount Hyjal and use your mount ability 65 times while the quest is active. This requires a flying mount and cannot be done outside that specific quest state.", x = 3 },
        [5864] = { e = 2, s = "s", r = "Easy: Win one duel while on a quest.", d = "Start The Protectors of Hyjal quest before entering Sethria's Roost to enable duels. Win any duel there while the quest remains active in your log.", x = 3 },
        [5865] = { e = 1, s = "c", r = "Trivial: Wave at 7 NPCs in a zone.", d = "Wave at each listed NPC in Sethria's Roost, including Hemet Nesingwary and Nat Pagle. This is account-wide, so one character can complete it for everyone.", x = 3 },
        [5866] = { e = 3, s = "c", r = "Moderate: Unlock multiple objectives in an event.", d = "Participate in the Molten Front attack to unlock all listed objectives like recruiting allies and building structures. These are time-gated events that require group participation.", x = 3 },
        [5867] = { e = 4, s = "s", r = "Hard: Solo kill without taking specific damage.", d = "Solo a Molten Behemoth in the Molten Front while avoiding Molten Stomp and Fiery Boulder abilities. Use movement skills or defensive cooldowns to survive these specific attacks.", x = 3 },
        [5868] = { e = 2, s = "c", r = "Simple quest chain with minor mechanics.", d = "Help each named critter defeat fire elementals, which is account-wide so one player can finish it for all accounts. Locate the specific critters in their respective zones within Hyjal.", x = 3 },
        [5869] = { e = 4, s = "c", h = { 19151, 19150, 19149 }, r = "Elite bosses require specific mechanics and RNG.", d = "Slay each elite invader using the specified method, such as avoiding Gout of Flame or killing Galenges before his second weakness. These conditions must be met during the Molten Front event.", x = 3 },
        [5870] = { e = 2, s = "c", r = "Talk to NPCs during a short event.", d = "Speak with every listed character during the Molten Front attack to complete this account-wide objective. Ensure you are in the zone when the event is active.", x = 3 },
        [5871] = { e = 3, s = "c", r = "Medium difficulty combat challenges in Molten Flow.", d = "Complete three specific challenges in the Molten Flow, including killing a Flamewaker Sentinel while it carries someone. These require precise timing and positioning during the event.", x = 3 },
        [5872] = { e = 2, s = "s", r = "Reach a specific high point once.", d = "Climb to the highest point in Widow's Clutch within the Molten Front zone. Use flying mounts or climbing abilities if available to reach the peak quickly.", x = 3 },
        [5873] = { e = 4, s = "c", h = { 2952, 2953, 2956 }, r = "Lieutenants require avoiding special attacks.", d = "Slay each Lieutenant of Flame in Ragnaros' Reach without taking damage from their special attacks. This is account-wide and requires careful positioning during the event window.", x = 3 },
        [5874] = { e = 3, s = "g", r = "Bomb multiple elementals in a run.", d = "Start this by flying to Molten Front and locating the six specific elementals listed in the info field. You must bomb them during an active bombing run event, so wait for the correct window or join a group doing the daily. Do not kill them normally; you need to use the bombing mechanic on each one to complete the quest.", x = 3 },
        [5875] = { e = 5, s = "g", r = "Collecting 150 unique pets is a long grind.", d = "Begin by catching any pet you find in your world, as this achievement requires collecting 150 unique companions total. Since it is part of a chain, ensure you have completed previous pet collection goals before starting if applicable. There is no time limit, but aim to catch pets from various sources like dailies and rare drops to reach the count efficiently.", x = 3 },
        [5876] = { e = 4, s = "g", r = "Collecting 100 unique pets takes time.", d = "This goal requires catching 100 unique pets, which is a subset of the larger Menagerie achievement. Start early by exploring different zones and completing pet-related quests to build your collection gradually. Remember that you only need one of each species, so avoid duplicates and focus on finding new types.", x = 3 },
        [5877] = { e = 3, s = "c", r = "Complete several combat challenges in Molten Flow.", d = "To earn this, you must collect 300 unique pets, which is a significant long-term goal requiring patience and exploration. Begin by catching common pets from dailies and world drops, then hunt for rare ones as your collection grows. This achievement has no time gate, but it will take many hours of play to reach the final count.", x = 3 },
        [5879] = { e = 4, s = "c", h = { 20301, 20302 }, r = "Depends on completing other hard achievements.", d = "This title requires completing several other Molten Front achievements listed in the info field, so tackle them one by one starting with the easiest. Some sub-achievements may have time gates or require specific events, so check their requirements before beginning. Plan your route through Molten Front to efficiently complete multiple objectives in a single visit.", x = 3 },
        [5995] = { e = 5, s = "s", r = "Heroic dungeon with strict healer damage rules.", d = "You must defeat Echo of Tyrande on Heroic difficulty without taking damage from her Shadow Gauntlet phase, which requires careful positioning and healing management. Ensure your healer can avoid all damage during the gauntlet, as any hit will fail the achievement. Coordinate with your group to survive the encounter cleanly before engaging the final boss.", x = 3 },
        [6006] = { e = 2, s = "c", r = "Visit 8 NPCs in accessible zones; trivial travel.", d = "Find and honor the eight Elders located in zones opened by Cataclysm, such as Twilight Highlands and Uldum. Visit each zone and locate the specific Elder NPC listed in the info field to interact with them. This is account-wide, so you can complete it from any character once you have access to those zones.", x = 3 },
        [6007] = { e = 2, s = "g", r = "Kill bonfires in Northrend; steady progress.", d = "Desecrate all Horde bonfires across Northrend by using the appropriate item or ability found during Midsummer events. Travel through each zone listed in the info field and locate the specific bonfire objects to interact with them. This is account-wide, so one character can complete it for everyone once the items are obtained.", x = 3 },
        [6008] = { e = 2, s = "g", r = "Honor flames across Northrend zones; easy grind.", d = "Honor the flames in Northrend by interacting with flame objects in each of the seven zones listed. These are typically found in open world areas and may require specific events or times to appear. Since this is account-wide, you can complete it from any character once you have visited all locations.", x = 3 },
        [6009] = { e = 2, s = "g", r = "Honor flames in Cataclysm zones; simple task.", d = "Similar to the previous achievement, honor the flames in Northrend by visiting all seven zones listed in the info field. Look for flame objects in each zone and interact with them during Midsummer events. This is account-wide, so ensure you cover every zone before the event ends if there is a time limit.", x = 3 },
        [6010] = { e = 2, s = "g", r = "Desecrate Alliance bonfires; straightforward grind.", d = "Desecrate all Alliance bonfires in Northrend by finding and interacting with them across the eight zones listed. These are distinct from Horde bonfires and require separate interaction. This is account-wide, so one character can complete it for everyone once all locations are visited.", x = 3 },
        [6011] = { e = 2, s = "g", r = "Honor flames in Cataclysm zones; easy task.", d = "Honor the flames in Cataclysm zones by visiting each of the five zones listed in the info field. Look for flame objects in open world areas and interact with them during Midsummer events. This is account-wide, so you can complete it from any character once you have accessed all required zones.", x = 3 },
        [6012] = { e = 2, s = "g", r = "Honor flames in Cataclysm zones; simple grind.", d = "Visit Vashj'ir, Twilight Highlands, Hyjal, Deepholm, and Uldum to honor their bonfires. This is account-wide but requires you to be in each zone; ensure all zones are accessible before starting.", x = 3 },
        [6013] = { e = 2, s = "g", r = "Desecrate Horde bonfires in two zones; easy.", d = "Travel to Twilight Highlands and Uldum to desecrate Horde bonfires. Note that this is account-wide, so coordinate with friends if you cannot visit both zones yourself.", x = 3 },
        [6014] = { e = 2, s = "g", r = "Desecrate Alliance bonfires in two zones; easy.", d = "Go to Twilight Highlands and Uldum to desecrate Alliance bonfires. Like the previous one, this is account-wide, so make sure you can reach both locations.", x = 3 },
        [6019] = { e = 2, s = "s", r = "Visit Darkmoon Faire once; trivial event.", d = "Simply attend the Darkmoon Faire event when it is active in your region. Do not miss the event window as attendance is time-gated and cannot be completed later.", x = 3 },
        [6020] = { e = 2, s = "g", r = "Play 5 games at faire; quick completion.", d = "Play five different games at the Darkmoon Faire, such as Cannon Blast or Shooting Gallery. This is account-wide, so play with friends to cover all game types quickly.", x = 3 },
        [6021] = { e = 3, s = "s", r = "Score bullseye once; RNG factor adds slight time.", d = "Launch yourself from the Cannon and aim for the bullseye target. Practice your timing during the event window, as missing this shot means waiting for the next Faire.", x = 3 },
        [6022] = { e = 1, s = "s", r = "Instant completion upon visiting the Faire.", d = "Visit the Shooting Gallery game at the Darkmoon Faire and score a Quick Shot. This is time-gated to the event duration, so prioritize it while the faire is active.", x = 3 },
        [6023] = { e = 2, s = "s", r = "Quick solo fight with guaranteed trinket drop.", d = "Win the Darkmoon Deathmatch arena battle to receive the Pit Fighter trinket. You must win this specific match once before unlocking the next achievement in the chain.", x = 3 },
        [6024] = { e = 3, s = "g", r = "Requires repeating the Deathmatch 12 times.", d = "Win the Darkmoon Deathmatch twelve times total to get the Master Pit Fighter trinket. This requires significant time investment and is account-wide, so team up for efficiency.", x = 3 },
        [6025] = { e = 1, s = "s", r = "Instant completion upon riding the pony.", d = "Ride the Darkmoon Pony mount available at the Faire. Ensure you have enough gold or reputation to purchase it if necessary, as this is a one-time requirement per account.", x = 3 },
        [6026] = { e = 3, s = "g", r = "Requires collecting and consuming many items.", d = "Eat and drink every single food and beverage item sold at the Darkmoon Faire. This is tedious but straightforward; just buy everything available while the event lasts.", x = 3 },
        [6027] = { e = 3, s = "c", h = { 20529 }, r = "Requires dungeon runs; one artifact is rare.", d = "Complete dungeons to obtain all five specific Darkmoon Artifacts and turn them in. These items are rare drops or quest rewards, so be prepared for RNG or specific dungeon runs.", x = 3 },
        [6028] = { e = 3, s = "c", r = "Requires battleground runs for artifacts.", d = "Visit the Darkmoon Faire and complete all three battleground artifact quests. These turn-ins are account-wide, so any character can finish them for everyone.", x = 3 },
        [6029] = { e = 4, s = "g", r = "Combines all Faire artifacts into one long list.", d = "Collect nine specific Darkmoon Artifacts by completing various Faire quests. Since this is account-wide, have one character gather all items and mail them to others if needed.", x = 3 },
        [6030] = { e = 3, s = "c", r = "Requires visiting all friendly capital cities.", d = "Launch fireworks in every friendly capital city listed in the achievement info. Ensure you visit each specific city to trigger the fireworks event successfully.", x = 3 },
        [6031] = { e = 3, s = "c", r = "Requires visiting all hostile capital cities.", d = "Launch fireworks in every friendly capital city listed in this specific achievement entry. Complete the same steps as the other city launch achievement for your faction.", x = 3 },
        [6032] = { e = 4, s = "g", r = "Requires completing five specific profession quests.", d = "Complete at least five profession-based quests available at the Darkmoon Faire. You can do these on any character since the progress is account-wide.", x = 3 },
        [6045] = { e = 4, s = "s", r = "Rare drop boss in a contested zone event.", d = "Defeat Occu'thar during Tol Barad battles. This requires participating in the Tol Barad Peninsula battleground and defeating the boss there.", x = 3 },
        [6070] = { e = 4, s = "s", r = "Requires specific mechanics and timing on a raid boss.", d = "Run Well of Eternity Heroic and damage Mannoroth while Varo'then is alive to trigger his sacrifice. Do not kill Varo'then before Mannoroth takes enough damage.", x = 3 },
        [6084] = { e = 4, s = "s", r = "Strict avoidance mechanic required for the entire fight.", d = "Defeat Ultraxion in Dragon Soul without any raid member taking Hour of Twilight more than once. Coordinate with your group to avoid stacking the debuff on anyone.", x = 3 },
        [6089] = { e = 3, s = "g", r = "Requires collecting 20 barrels before killing the boss.", d = "Kill Ook-Ook in Stormstout Brewery after throwing twenty Rolling Brew Barrels at him. Use Heroic difficulty and ensure you throw enough barrels before engaging the boss.", x = 4 },
        [6105] = { e = 4, s = "s", r = "Strict avoidance mechanic required for the entire fight.", d = "Defeat Warmaster Blackhorn without letting Twilight Barrages damage the Skyfire. Protect the Skyfire objective throughout the entire encounter to complete this part of the raid.", x = 3 },
        [6106] = { e = 4, s = "c", h = { 20099, 20098, 20100 }, r = "Four separate raid bosses must be defeated on Heroic.", d = "Defeat all bosses listed in the info who lay siege to Wyrmrest Temple. This includes Morchok, Warlord Zon'ozz, Yor'sahj, and Hagara within the Dragon Soul raid.", x = 3 },
        [6107] = { e = 4, s = "c", h = { 20104, 20105, 20106 }, r = "Four separate raid bosses must be defeated on Heroic.", d = "Defeat all encounters leading up to Deathwing's fall in Dragon Soul. You must clear Ultraxion, Warmaster Blackhorn, Spine of Deathwing, and Madness of Deathwing.", x = 3 },
        [6108] = { e = 3, s = "s", r = "Single encounter in Tol Barad arena, moderate difficulty.", d = "Start this by joining the Tol Barad garrison battles as soon as they open. You must defeat Alizabal during these events, so coordinate with your faction mates to ensure she is targeted correctly before the battle ends.", x = 3 },
        [6109] = { e = 4, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Queue for Heroic Dragon Soul and focus on defeating Morchok first. This boss drops a rare item that can help you progress through the rest of the raid efficiently without needing specific group compositions.", x = 3 },
        [6110] = { e = 4, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Defeat Warlord Zon'ozz in Heroic Dragon Soul by managing his adds and avoiding his cleave attacks. Ensure your healer is ready for the high damage phases to secure a quick kill.", x = 3 },
        [6111] = { e = 4, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Yor'sahj requires precise positioning during his phase transitions; keep moving to avoid ground effects. Coordinate with your raid leader to handle the adds that spawn during his final phase effectively.", x = 3 },
        [6112] = { e = 4, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Hagara the Stormbinder is a solo-friendly encounter where you must dodge her lightning strikes while kiting her around the arena. Use your mobility skills to stay out of her storm zones during the fight.", x = 3 },
        [6113] = { e = 4, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Ultraxion drops a rare item that can be used to complete other achievements later. Focus on avoiding his shadow orbs and managing the adds that spawn in his final phase carefully.", x = 3 },
        [6114] = { e = 4, s = "s", r = "Heroic raid boss kill requires group coordination.", d = "Warmaster Blackhorn requires careful management of his adds and avoiding his cleave attacks. Ensure your raid is positioned correctly to handle the large number of enemies he spawns during the fight.", x = 3 },
        [6115] = { e = 4, s = "s", r = "Heroic raid boss kill requires group coordination.", d = "The Spine of Deathwing encounter involves managing multiple phases and avoiding environmental hazards. Coordinate with your raid to handle the adds that spawn in each phase effectively.", x = 3 },
        [6116] = { e = 4, s = "s", r = "Heroic raid boss kill requires group coordination.", d = "Destroying Deathwing is the final step in the Heroic Dragon Soul raid. Ensure your raid is prepared for the intense mechanics of his final phase and coordinate to avoid taking excessive damage.", x = 3 },
        [6117] = { e = 4, s = "s", r = "Heroic dungeon boss kill requires group coordination.", d = "Defeat Murozond in Heroic End Time by managing his adds and avoiding his cleave attacks. Ensure your raid is positioned correctly to handle the large number of enemies he spawns during the fight.", x = 3 },
        [6118] = { e = 4, s = "s", r = "Heroic dungeon boss kill requires group coordination.", d = "Mannoroth in Well of Eternity requires precise positioning and managing his adds. Use your mobility skills to stay out of his fire zones and coordinate with your raid to handle the large number of enemies he spawns.", x = 3 },
        [6119] = { e = 4, s = "s", r = "Heroic dungeon boss kill requires group coordination.", d = "Archbishop Benedictus in Hour of Twilight requires careful management of his adds and avoiding his cleave attacks. Ensure your raid is positioned correctly to handle the large number of enemies he spawns during the fight.", x = 3 },
        [6127] = { e = 4, s = "s", r = "Heroic dungeon with strict mechanic requires group coordination.", d = "Pull Peroth'arn alone or with a healer to avoid Eye of Peroth'arn detection. Ensure no one is hit by the eye mechanic before killing him on Heroic.", x = 3 },
        [6128] = { e = 3, s = "g", r = "Requires specific mechanic execution then boss kill.", d = "Start bouncing the Void off players immediately after spawning it. Defeat Warlord Zon'ozz only after hitting the bounce counter ten times.", x = 3 },
        [6129] = { e = 4, s = "c", h = { 20620, 20621, 20622 }, r = "Requires boss kill plus specific color combos.", d = "Use specific color combinations during Yor'sahj phases before killing him. Complete all required combos on Normal or Heroic difficulty first.", x = 3 },
        [6130] = { e = 4, s = "s", r = "Heroic dungeon boss kill with minor sub-step.", d = "Kill two Risen Ghouls during the Highborne phase in End Time. Then proceed to defeat Echo of Sylvanas on Heroic difficulty.", x = 3 },
        [6132] = { e = 4, s = "g", r = "Requires killing many mobs then defeating boss.", d = "Kill ten Twilight Sparks before engaging Archbishop Benedictus. Ensure you have the kill count before starting the final boss fight.", x = 3 },
        [6133] = { e = 4, s = "s", r = "Heroic raid boss kill with specific roll sequence.", d = "Trick Deathwing into rolling Left, Right, Left, Right during the Spine encounter. Defeat him after completing this specific sequence.", x = 3 },
        [6169] = { e = 4, s = "c", h = { 19803, 19811, 19812 }, r = "Raid content with multiple difficult mechanics and RNG.", d = "Complete all listed Dragon Soul raid achievements first. This is a collection goal requiring every sub-achievement to be finished.", x = 3 },
        [6174] = { e = 5, s = "s", r = "Highly specific mechanic requiring perfect raid coordination.", d = "Keep players spread out during Morchok's Black Blood channel phase. Ensure no two players are within five yards of each other.", x = 3 },
        [6175] = { e = 3, s = "s", r = "Specific phase mechanic during a standard raid fight.", d = "Ensure all raid members are in the Lightning Conduit before destroying the final Crystal Conductor. Coordinate positioning carefully during Hagara's lightning phase.", x = 3 },
        [6177] = { e = 4, s = "s", r = "Requires defeating the final boss of a hard raid.", d = "Defeat Deathwing on Normal or Heroic difficulty to earn the title. This is a standard boss kill requirement for the raid.", x = 3 },
        [6180] = { e = 3, s = "c", h = { 19387, 19388, 19389 }, r = "Multiple specific encounter orders required for completion.", d = "Start the encounter on each Aspect's platform and let Deathwing assault them first. Complete all four aspect assaults before finishing the fight.", x = 3 },
        [6193] = { e = 2, s = "s", r = "Legacy status check, trivial if level was reached.", d = "Reach level 90 before entering Shadowlands expansion. This legacy achievement tracks your character's level prior to the latest expansion.", x = 3 },
        [6300] = { e = 3, s = "c", h = { 21357, 21350 }, r = "Multiple story quests with some difficult mechanics.", d = "Complete all listed Jade Forest quests in any order, as this is account-wide and requires no specific group composition. Finish the storylines to unlock the achievement without worrying about time gates or rare drops.", x = 4 },
        [6301] = { e = 3, s = "c", h = { 10764, 10765 }, r = "Multiple story quests with some difficult mechanics.", d = "Finish every Valley of the Four Winds quest listed in the info field to earn these points. This is account-wide so progress carries across characters, and there are no missable elements mentioned.", x = 4 },
        [6332] = { e = 3, s = "s", r = "Rare spawn event requiring specific conditions to kill.", d = "Defeat the Darkmoon Rabbit during the Darkmoon Faire event to complete this task. Ensure you attend the Faire when it is active, as the rabbit only spawns then.", x = 4 },
        [6348] = { e = 1, s = "s", r = "Simple item level check, trivial if gear is obtained.", d = "Equip a superior item of at least item level 450 in every gear slot before Battle for Azeroth. Check your inventory carefully since this legacy achievement has no points but unlocks the next tier.", x = 4 },
        [6349] = { e = 2, s = "s", r = "Item level check, easy once high-level gear is acquired.", d = "Equip an epic item of at least item level 476 in every slot prior to Battle for Azeroth. This requires upgrading your gear significantly and is part of a progression chain.", x = 4 },
        [6350] = { e = 3, s = "g", r = "Collecting many specific critters across the zone.", d = "Use the /love command on all listed critters in Pandaria, including those with hidden entries like Shrine Fly. This is account-wide so one character can complete it for everyone.", x = 4 },
        [6351] = { e = 2, s = "c", r = "Walk through zone to reveal map areas.", d = "Travel to Jade Forest and interact with every location listed to reveal covered map areas. You do not need to complete quests here, just visit the named spots.", x = 4 },
        [6365] = { e = 4, s = "g", r = "Grind cooking skill points in Pandaria.", d = "Cook Pandaria-specific recipes repeatedly until you gain 75 skill points in that category. Focus on local ingredients and daily cooking events to speed up progress.", x = 4 },
        [6366] = { e = 4, s = "g", r = "Grind reputation to Exalted with Shado-Pan.", d = "Grind reputation with the Shado-Pan faction until you reach Exalted status. This is account-wide so start early, as gaining rep takes significant time and gold.", x = 4 },
        [6374] = { e = 5, s = "c", r = "Complete all Challenge Mode dungeons.", d = "Clear every Challenge Mode dungeon in Pandaria with a Bronze rating or higher to unlock the title. You can do this solo or in groups, but ensure your team meets the minimum difficulty.", x = 4 },
        [6375] = { e = 5, s = "c", r = "Complete all Challenge Mode dungeons.", d = "Complete all Challenge Mode dungeons with a Silver rating or better to earn the mount. Progress carries forward from Bronze, so aim for higher ratings as you improve your group.", x = 4 },
        [6378] = { e = 5, s = "c", r = "Complete all Challenge Mode dungeons.", d = "Finish every Challenge Mode dungeon with a Gold rating to unlock the transmogrification set. This is the final tier and requires consistent high-level performance across all dungeons.", x = 4 },
        [6394] = { e = 4, s = "s", r = "Specific mechanic run in Scholomance Heroic.", d = "Defeat Rattlegore on Heroic while keeping his Rusting stacks at 5 or fewer by interrupting his casts quickly. Do not let him reach the cap before killing him, as this is missable if you fail to kill him in time.", x = 4 },
        [6396] = { e = 4, s = "s", r = "Specific mechanic run in Scholomance Heroic.", d = "Focus fire on Krastinovian Carver to build Boiling Bloodthirst stacks without letting him heal or escape. Aim for exactly 99 stacks before finishing him off, as going over will reset the counter.", x = 4 },
        [6400] = { e = 2, s = "s", r = "Solve puzzle to drop Hozen Clinger.", d = "Use crowd control abilities to force the Hozen Clinger to drop down from its ledge in Stormstout Brewery. Coordinate with your group to keep it stunned until it releases its grip.", x = 4 },
        [6402] = { e = 3, s = "g", r = "Collect 30 hidden Golden Hoplings.", d = "Search every corner of Stormstout Brewery for Golden Hoplings, using stealth or careful movement to avoid aggro. Collect all 30 hidden pets before leaving the instance to secure your reward.", x = 4 },
        [6420] = { e = 3, s = "g", r = "Smash 100 Virmen with one swing.", d = "Equip a hammer and spam basic attacks on Virmen in one swing to count them toward your total. Ensure you are not interrupted mid-swing, as each hit must be a single continuous motion.", x = 4 },
        [6427] = { e = 5, s = "c", r = "Complex mechanic requiring full group coordination.", d = "Coordinate with 8 players and Scarlet Defenders to get caught in Armsmaster Harlan's Blades of Light simultaneously. Time your movement so everyone is hit at once before defeating him on Heroic.", x = 4 },
        [6455] = { e = 3, s = "c", r = "Requires specific mechanics coordination in a raid.", d = "Defeat the Terracotta Army without taking Devastating Arc, Stomp, or Energizing Smash damage during Unbalanced phases. Communicate with your raid to avoid these mechanics while executing Opportunistic Strikes together.", x = 4 },
        [6456] = { e = 3, s = "s", r = "Heroic dungeon boss kill with minor mechanic.", d = "Complete Stormstout Brewery on Heroic by defeating Yan-Zhu the Uncasked after unlocking the dungeon. This requires prior completion of the normal version and careful management of his abilities.", x = 4 },
        [6457] = { e = 2, s = "s", r = "Normal dungeon boss kill, straightforward.", d = "Defeat Yan-Zhu the Uncasked in any difficulty to unlock this achievement first. Once completed, you can proceed to the Heroic version for additional points.", x = 4 },
        [6458] = { e = 3, s = "c", r = "Requires clearing first three raid bosses.", d = "Defeat the first three bosses in Mogu'shan Vaults: Stone Guard, Feng the Accursed, and Gara'jal the Spiritbinder. This is account-wide, so coordinate with friends or guildmates if needed.", x = 4 },
        [6460] = { e = 3, s = "s", r = "Heroic dungeon boss with avoidable mechanics.", d = "Avoid Corrupted Water, Hydrolance, and Wash Away mechanics while fighting Wise Mari on Heroic in Temple of the Jade Serpent. Use crowd control to manage adds and minimize damage taken.", x = 4 },
        [6462] = { e = 3, s = "g", r = "Requires winning 250 pet battles total.", d = "Win 250 pet battles across all categories to earn this title. Track your wins carefully, as missing this milestone means restarting from zero for future tiers.", x = 4 },
        [6469] = { e = 2, s = "s", r = "Normal dungeon boss kill, straightforward.", d = "Defeat Taran Zhu on Normal difficulty first. This is a standard dungeon achievement with no special mechanics or time limits.", x = 4 },
        [6470] = { e = 3, s = "s", r = "Heroic dungeon boss kill with minor mechanic.", d = "Complete the Normal version before attempting Heroic. Ensure you have enough gear to handle the increased difficulty of Taran Zhu.", x = 4 },
        [6471] = { e = 4, s = "c", r = "Requires max hatred stacks on all party members.", d = "On Heroic, keep your party's hatred bars full throughout the entire fight. Use abilities that generate hatred and avoid healing unless necessary to maintain stacks.", x = 4 },
        [6472] = { e = 3, s = "s", r = "Heroic dungeon boss with specific Sha mechanic.", d = "First clear all Sha imprisoned in the Sealed Chambers questline. Then defeat Sha of Violence on Heroic difficulty to complete this requirement.", x = 4 },
        [6475] = { e = 3, s = "s", r = "Requires buff uptime during boss fight.", d = "Defeat Sha of Doubt in Temple of the Jade Serpent while holding Purified Water buff. Consume the water item before engaging the boss.", x = 4 },
        [6476] = { e = 2, s = "g", r = "Requires collecting stacks from a specific mob.", d = "On Heroic difficulty, kill Mantid Conscripts in Gate of the Setting Sun to gain Resin Residue stacks. You need three stacks total.", x = 4 },
        [6477] = { e = 2, s = "s", r = "Single timed event with low RNG.", d = "During Master Snowdrift on Heroic, wait for defeated Shado-Pan Novices to bow before they heal. Bow back immediately to secure the achievement.", x = 4 },
        [6478] = { e = 3, s = "s", r = "Timed kill on Heroic dungeon.", d = "On Heroic difficulty in Mogu'shan Palace, kill Gekkan within five minutes of the Glintrok Scout spotting you. Coordinate with your group for speed.", x = 4 },
        [6479] = { e = 4, s = "g", r = "High RNG requirement within short window.", d = "During Saboteur Kip'tilak on Heroic, trigger fifteen explosions in fifteen seconds. Use explosive abilities or items frequently to meet the timer.", x = 4 },
        [6480] = { e = 3, s = "s", r = "Standard Heroic dungeon boss kill.", d = "Defeat Sha of Anger in Kun-Lai Summit. This is a straightforward dungeon kill with no specific mechanics mentioned in the data.", x = 4 },
        [6485] = { e = 3, s = "s", r = "Timed mechanic on specific boss.", d = "On Heroic difficulty, wait until General Pa'valak has twenty Detonate stacks before killing him. Do not kill him too early or the achievement will fail.", x = 4 },
        [6517] = { e = 2, s = "s", r = "Standard Heroic dungeon encounter.", d = "Defeat Salyis's Warband in Valley of the Four Winds. This is a standard raid encounter with no special conditions listed.", x = 4 },
        [6518] = { e = 4, s = "g", r = "Requires specific setup and RNG.", d = "You must kill Living Amber in Burning Amber until eight pools overlap before entering Heart of Fear to defeat Un'sok on Normal or Heroic. This is a strict time gate because the achievement expires once you enter the raid without meeting the condition first.", x = 4 },
        [6531] = { e = 3, s = "s", r = "Skill-based Heroic dungeon run.", d = "Defeat Jandice Barov in Scholomance Heroic by never clicking any false images that appear during the fight. Focus entirely on the real boss and ignore all visual distractions to avoid failing the requirement.", x = 4 },
        [6534] = { e = 3, s = "c", r = "Multiple zone storylines to complete.", d = "Complete every listed quest in the Jade Forest storyline, which includes both Horde-specific tasks and major story events. Ensure you finish these before leaving the zone as this achievement is account-wide but region-locked.", x = 4 },
        [6535] = { e = 3, s = "c", r = "Multiple zone storylines to complete.", d = "Finish all Alliance quests in Krasarang Wilds including Zhu's Watch and The Incursion to unlock this achievement. These are account-wide, so coordinate with your faction group to clear them efficiently.", x = 4 },
        [6536] = { e = 3, s = "c", r = "Multiple zone storylines to complete.", d = "Complete the full Horde quest chain in Krasarang Wilds starting with Zhu's Watch and ending at Dawnchaser Retreat. Do not miss any sub-objectives since the entire storyline must be finished for credit.", x = 4 },
        [6537] = { e = 3, s = "c", r = "Multiple zone storylines to complete.", d = "Clear all Kun-Lai Summit quests for your faction, ensuring you complete major events like The Thunder King and Temple of the White Tiger. This is account-wide, so plan your route carefully to avoid missing content.", x = 4 },
        [6538] = { e = 3, s = "c", r = "Complete multiple zone storylines.", d = "Finish every Horde-specific quest in Kun-Lai Summit including Kota Peak and Zouchin Village before moving on. Missing even one quest will prevent you from earning this achievement permanently.", x = 4 },
        [6539] = { e = 3, s = "c", r = "Complete multiple zone storylines.", d = "Complete the Townlong Steppes storyline by finishing key quests like On Hatred's Path and Tai Ho's Investigation. These are account-wide, so ensure your character completes them while in the zone.", x = 4 },
        [6540] = { e = 3, s = "c", r = "Complete multiple zone storylines.", d = "Finish all Dread Wastes quests including The First Paragons and Like a Deck Boss to claim this achievement. Be mindful that some of these may have time gates or be missable if you leave too early.", x = 4 },
        [6541] = { e = 3, s = "c", r = "Combines other Pandaria quest achievements.", d = "This Loremaster achievement requires completing all previous Pandaria quest chains listed in the info field. Start with the Jade Forest quests first, then progress through Krasarang, Kun-Lai, Townlong, and Dread Wastes systematically.", x = 4 },
        [6543] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Earn Exalted reputation with the August Celestials by completing daily quests and turning in items like Sha Crystals. This is account-wide, so maximize your gains by doing dailies across multiple characters if possible.", x = 4 },
        [6544] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Reach Exalted status with The Tillers through farming crops, turning in materials, and completing their reputation quests. Since this is account-wide, use any character to grind the necessary reputation quickly.", x = 4 },
        [6545] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Grind reputation with the Klaxxi faction until you reach Exalted status. This is an account-wide achievement, so any character can contribute to your progress.", x = 4 },
        [6546] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Earn Exalted reputation with the Golden Lotus faction. Focus on completing daily quests and world events in Pandaria to speed up this process.", x = 4 },
        [6547] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Reach Exalted status with The Anglers by fishing in various locations across Pandaria. This is account-wide, so one character can help the whole account.", x = 4 },
        [6548] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Grind reputation with The Lorewalkers until you achieve Exalted status. Visit their faction hubs and complete available quests to make progress.", x = 4 },
        [6550] = { e = 4, s = "g", r = "Requires significant reputation grinding.", d = "Earn Exalted reputation with the Order of the Cloud Serpent first. Note that this requires Exalted with The Serpent Riders before you can unlock this achievement.", x = 4 },
        [6551] = { e = 4, s = "g", r = "Requires massive item collection grind.", d = "Complete daily quests for Halfhill Market characters to reach Best Friends status with one person. This is the first step in a chain of friendship achievements.", x = 4 },
        [6552] = { e = 4, s = "g", r = "Requires grinding reputation with 10 NPCs to max level.", d = "Finish all individual character friendships at Halfhill Market to unlock this achievement. Ensure you have completed the previous 'Friend on the Farm' requirement.", x = 4 },
        [6553] = { e = 4, s = "s", r = "High skill ceiling raid fight with strict leg mechanic.", d = "Defeat Garalon in Heart of Fear without destroying his legs. Use a tanky group and avoid using abilities that damage the boss's limbs during the fight.", x = 4 },
        [6554] = { e = 2, s = "g", r = "Capture 10 pets is quick for most players.", d = "Capture ten pets in pet battles to earn this achievement. Start by battling wild pets in zones like Valdrakken or Stormsong Valley for easy captures.", x = 4 },
        [6555] = { e = 2, s = "g", r = "Capture 25 pets follows the first step easily.", d = "Capture twenty-five pets total in pet battles. This is a chain achievement, so you must complete the previous one before starting this step.", x = 4 },
        [6556] = { e = 3, s = "g", r = "Capture 50 pets requires more time than previous steps.", d = "Capture fifty pets in pet battles to unlock this milestone. Consider using Strong Pet Traps as rewards from the previous achievement to help with future captures.", x = 4 },
        [6557] = { e = 3, s = "g", r = "Capture 100 pets is a moderate grind for pet tamers.", d = "Reach one hundred captured pets in pet battles for this final tier. Keep battling wild pets and completing pet battle quests to reach the goal.", x = 4 },
        [6558] = { e = 4, s = "g", r = "Winning pet battles in many zones takes significant time.", d = "Start by winning battles in one zone from each continent to unlock the next tier. Note that Felwood requires ten wins, so prioritize it early to avoid time-gating later.", x = 4 },
        [6559] = { e = 4, s = "g", r = "Extending zone wins to 30 requires extensive travel.", d = "Complete Local Pet Mauler first, then systematically win battles across all remaining zones. This chain is account-wide, so coordinate with friends if you need specific rare zone drops.", x = 4 },
        [6560] = { e = 4, s = "g", r = "Winning pet battles in all zones is a long grind.", d = "Finish Traveling Pet Mauler before attempting this 60-zone goal. Ensure you have a strong team ready since some zones may require higher-level pets or specific strategies.", x = 4 },
        [6566] = { e = 1, s = "g", r = "Leveling one pet to 5 takes only a few minutes.", d = "Begin with any pet and win battles to level it up; do not skip steps as each tier requires the previous one. This unlocks your third battle slot, so prioritize leveling quickly.", x = 4 },
        [6567] = { e = 2, s = "g", r = "Leveling a pet to 10 is slightly more time consuming.", d = "Continue battling with your starter pet until it reaches level 10. Keep an eye on its health to avoid losing it during this progression phase.", x = 4 },
        [6568] = { e = 2, s = "g", r = "Leveling a pet to 15 is still an easy task.", d = "Push your pet from level 10 to 15 using consistent wins. Remember that account-wide progress means you can share pets with other characters if needed.", x = 4 },
        [6569] = { e = 1, s = "g", r = "Trivial: Level a single pet to 20.", d = "Level your pet to 20 next, maintaining a balanced team composition for easier victories. Avoid rushing into high-level zones until your pet is ready.", x = 4 },
        [6570] = { e = 1, s = "g", r = "Easy: Level one pet from 20 to 25.", d = "Reach level 25 by focusing on battles that yield experience without risking your pet's survival. This tier unlocks significant progression benefits for future content.", x = 4 },
        [6571] = { e = 3, s = "c", r = "Moderate: Requires hunting many rare spawns.", d = "Capture wild pets when they are critically low on health to earn points efficiently. Practice timing your attacks to maximize damage output during these critical moments.", x = 4 },
        [6578] = { e = 4, s = "g", r = "Hard: Grind 15 pets to level 25.", d = "Raise fifteen distinct pets to level 25 before moving forward. Start by leveling multiple pets simultaneously to speed up this lengthy process effectively.", x = 4 },
        [6579] = { e = 3, s = "g", r = "Moderate: Grind 15 pets to level 10.", d = "Level fifteen pets to 10 first, ensuring you have a diverse roster ready for the next stage. Use lower-level zones to farm experience without wasting high-tier pets.", x = 4 },
        [6580] = { e = 4, s = "g", r = "Hard: Grind 30 pets to level 10.", d = "Expand your roster by leveling thirty pets to level 10 total. Coordinate with group members if possible to share battle opportunities and accelerate completion.", x = 4 },
        [6581] = { e = 4, s = "g", r = "Hard: Grind 30 pets to level 25.", d = "Start by catching common pets in starter zones to level them quickly, as this is the first step in the Pro Pet Crew chain. Focus on raising exactly 30 different pets to level 25 before moving on, since you cannot progress without completing this prerequisite. There are no rare drops involved, so simply grind battles until your pet collection reaches the target count.", x = 4 },
        [6582] = { e = 4, s = "g", r = "Hard: Grind 75 pets to level 25.", d = "This achievement requires you to raise 75 distinct pets to level 25, which takes significantly longer than the previous tier. Continue leveling up your existing pets or catch new ones from zones you have already visited to efficiently reach the goal. Remember that this is account-wide, so any progress made on other characters counts toward your total.", x = 4 },
        [6583] = { e = 4, s = "g", r = "Hard: Grind 75 pets to level 10.", d = "Begin by catching low-level pets in your starting zone and battle them until they reach level 10 for a total of 75 different species. This achievement does not require the Pro Pet Crew addon, but you must have completed the Rookie Pet Crew chain first. Avoid using high-level pets early on to ensure you are leveling up the correct number of unique creatures.", x = 4 },
        [6584] = { e = 2, s = "c", r = "Easy: Win battles in four major cities.", d = "Travel to each major Alliance city listed in the info field and win at least one battle within its borders. Since this is account-wide, you can complete these wins on any character once you have unlocked the ability to enter pet battles. Ensure you visit Stormwind, Ironforge, Darnassus, and The Exodar specifically, as missing even one city will prevent completion.", x = 4 },
        [6585] = { e = 4, s = "c", r = "Hard: Catch dozens of rare Kalimdor pets.", d = "Explore Kalimdor zones systematically to catch every listed pet, paying close attention to rare spawns that may drop infrequently. This achievement is account-wide, so you can catch pets on any character once the region is unlocked. Be patient with rare drops like the Adder or Alpine Chipmunk, as they may take time to appear in random encounters.", x = 4 },
        [6586] = { e = 4, s = "c", r = "Hard: Catch dozens of rare Eastern Kingdoms pets.", d = "Systematically clear Eastern Kingdoms zones to collect all required pets, noting that some are rare spawns requiring multiple attempts. This achievement unlocks after completing the Kalimdor Safari and is account-wide, allowing you to finish it on any character. Watch for specific creatures like the Black Lamb or Crimson Moth which may only appear in certain sub-zones.", x = 4 },
        [6587] = { e = 3, s = "g", r = "Requires catching many pets in Outland zones.", d = "Visit Outland zones such as Hellfire Rampart and Terokkar Forest to catch every pet listed in the achievement info. Some pets here are rare drops, so be prepared to spend considerable time grinding battles for creatures like the Fel Flame or Clefthoof Runt. This is account-wide, so you can complete it on any character once you have access to Outland content.", x = 4 },
        [6588] = { e = 3, s = "g", r = "Requires catching many pets in Northrend zones.", d = "Travel to Northrend and methodically catch every pet in that region, including rare spawns like the Arctic Fox Kit or Devouring Maggot. Since this achievement is account-wide, you can finish it on any character after unlocking Northrend content. Be aware that some pets may only appear during specific weather conditions or in limited spawn rates.", x = 4 },
        [6589] = { e = 3, s = "g", r = "Requires catching many pets in Pandaria zones.", d = "Explore Pandaria zones to catch every pet listed, including rare ones like the Emperor Crab or Feverbite Hatchling which require patience. This achievement is account-wide and becomes available once you have access to Pandaria content. Focus on clearing all sub-zones thoroughly, as some pets may only spawn in specific locations within larger areas.", x = 4 },
        [6590] = { e = 2, s = "c", h = { 21499, 21500, 21502 }, r = "Depends on completing four other safari achievements.", d = "Complete all five regional Safari achievements listed in the info field before claiming this final title. This is a milestone achievement that unlocks after finishing Eastern Kingdoms, Kalimdor, Outland, Northrend, and Pandaria safaris. There are no rare drops involved here; simply ensure you have earned each individual Safari first.", x = 4 },
        [6591] = { e = 3, s = "g", r = "Requires winning 1000 pet battles total.", d = "Win 1000 pet battles by engaging in random encounters or structured battles across all zones. This achievement is account-wide and requires you to first complete the Master Pet Battler tier. You can grind this efficiently by queuing for battles in any zone once you have unlocked the ability to enter them.", x = 4 },
        [6592] = { e = 4, s = "g", r = "Requires winning 5000 pet battles total.", d = "Continue winning pet battles until you reach 5000 total wins, which is a significant time investment requiring consistent grinding. This achievement unlocks after completing Grand Master Pet Battler and is account-wide, so progress carries over across characters. There are no rare drops or special conditions; simply keep battling until the counter reaches the target.", x = 4 },
        [6593] = { e = 2, s = "g", r = "Requires winning 50 pet battles total.", d = "Win 50 total pet battles to unlock this tier. Start by defeating wild pets in zones like Stranglethorn Vale or Azshara for easy wins.", x = 4 },
        [6594] = { e = 1, s = "g", r = "Requires winning only 10 pet battles total.", d = "This is the very first step; simply win your first 10 pet battles anywhere in Azeroth to complete it immediately.", x = 4 },
        [6595] = { e = 2, s = "g", r = "Requires winning 10 PvP pet battles.", d = "You must win PvP pet battles specifically, so head to Battlegrounds or use the Pet Battle trainer in Orgrimmar/Ironforge.", x = 4 },
        [6596] = { e = 3, s = "g", r = "Requires winning 50 PvP pet battles.", d = "After unlocking Pet Brawler, continue winning 50 more PvP battles. Note that these do not count toward your total battle wins.", x = 4 },
        [6597] = { e = 4, s = "g", r = "Requires winning 250 PvP pet battles.", d = "Win 250 PvP pet battles total. This is a long grind requiring consistent daily play in battlegrounds or arenas.", x = 4 },
        [6598] = { e = 4, s = "g", r = "Requires winning 1000 PvP pet battles.", d = "Reach 1000 PvP wins for this title. Be patient as this requires significant time investment over many weeks of gameplay.", x = 4 },
        [6599] = { e = 4, s = "g", r = "Requires winning 5000 PvP battles.", d = "Win 5000 PvP battles for the final tier. This is a massive grind that may take hundreds of hours to complete.", x = 4 },
        [6600] = { e = 2, s = "g", r = "Earn points by playing battles.", d = "Earn 300 achievement points from any pet battle activity. Focus on winning battles rather than just completing storylines for faster progress.", x = 4 },
        [6601] = { e = 3, s = "c", r = "Defeat one master tamer per continent.", d = "Defeat at least one master tamer in each major zone. Visit zones like Stranglethorn Vale or Azshara to find your first target quickly.", x = 4 },
        [6602] = { e = 4, s = "c", r = "Defeat all Kalimdor pet tamers.", d = "Defeat all listed Kalimdor tamers including Zunta and Dagra the Fierce. Check local gossip menus for their locations after unlocking the quest.", x = 4 },
        [6603] = { e = 4, s = "c", r = "Defeat all Eastern Kingdoms pet tamers.", d = "Defeat all Eastern Kingdoms tamers like Julia Stevens and Old MacDonald. These are often found in zones like Azshara or Stranglethorn Vale.", x = 4 },
        [6604] = { e = 3, s = "c", r = "Defeat all Outland pet tamers.", d = "Defeat all Outland tamers including Nicki Tinytech and Ras'an. Visit zones like Terokkar Forest or Nagrand to locate these specific targets.", x = 4 },
        [6605] = { e = 3, s = "c", r = "Defeat all Northrend pet tamers.", d = "Defeat all listed Northrend Pet Tamers to unlock daily quests. This is account-wide and requires no specific group, but ensure you have access to each zone first.", x = 4 },
        [6606] = { e = 3, s = "c", r = "Defeat all Pandaria pet tamers.", d = "Clear every Pandaria Pet Tamer listed in the info field. You can do this solo once you reach Pandaria, as these are standard battle encounters.", x = 4 },
        [6607] = { e = 4, s = "c", r = "Complete all regional taming achievements.", d = "Finish all previous taming achievements including Outland, Northrend, Cataclysm, and Kalimdor/EK to earn the title. Start with older zones if your account is new.", x = 4 },
        [6608] = { e = 3, s = "c", r = "Capture one pet from each family.", d = "Capture one pet from each of the ten families listed. This is account-wide so any character can contribute, but you must physically capture them.", x = 4 },
        [6609] = { e = 4, s = "g", r = "Level every pet family to 10.", d = "Level a single pet from each family to level 10 first. This unlocks the next tier and requires no group, just time for battles.", x = 4 },
        [6610] = { e = 4, s = "g", r = "Level every pet family to 25.", d = "Raise every family pet to level 25 after completing the previous tier. No group is needed, but be patient as leveling takes many battles.", x = 4 },
        [6611] = { e = 3, s = "c", r = "Requires finding and capturing pets across all continents.", d = "Complete all regional Pet Mauler achievements listed in the info field. These are account-wide and require defeating specific tamers in each continent.", x = 4 },
        [6612] = { e = 3, s = "c", r = "Requires capturing pets in every Kalimdor zone.", d = "Capture a pet in every Kalimdor zone listed. Start with accessible zones like Ashenvale or Durotar if you are new to that region.", x = 4 },
        [6613] = { e = 3, s = "c", r = "Requires capturing pets in every Eastern Kingdoms zone.", d = "Get a pet from each Eastern Kingdoms zone listed. Some zones like Northern Stranglethorn have multiple requirements, so check the full list carefully.", x = 4 },
        [6614] = { e = 3, s = "c", r = "Requires capturing pets in every Outland zone.", d = "Capture a pet in every Outland zone listed. This is account-wide and can be done solo once you are level 60+ and in Outland.", x = 4 },
        [6615] = { e = 3, s = "c", r = "Requires capturing pets in every Northrend zone.", d = "Capture a pet in each Northrend zone listed. Ensure you have the correct trainer unlocked for this category before starting.", x = 4 },
        [6616] = { e = 3, s = "c", r = "Requires capturing pets in every Pandaria zone.", d = "Capture a pet in every Pandaria zone listed. This is account-wide and requires visiting each zone to find the specific tamer or spawn point.", x = 4 },
        [6618] = { e = 2, s = "g", r = "Winning 10 consecutive battles is a steady grind.", d = "Start by winning your first pet battle to unlock the streak counter, then focus on quick wins to build momentum. Avoid risky battles that could break your chain early in the process.", x = 4 },
        [6619] = { e = 3, s = "g", r = "Winning 25 consecutive battles requires significant luck.", d = "Once you have the previous achievement, continue playing pet battles without losing to reach 25 consecutive victories. This requires consistent performance and avoiding difficult opponents until you are confident.", x = 4 },
        [6620] = { e = 4, s = "g", r = "PvP pet battles without deaths is very difficult.", d = "Queue for PvP pet battles and aim to win five in a row while keeping all your pets alive at all times. Do not let any pet die, as this will reset the counter immediately.", x = 4 },
        [6621] = { e = 3, s = "c", r = "Requires winning a battle in each major Horde city.", d = "Travel to each Horde city listed in the achievement description and win one pet battle per location. Ensure you have completed the prerequisite chain before attempting these specific city challenges.", x = 4 },
        [6622] = { e = 3, s = "c", r = "Requires completing both Alliance and Horde city lists.", d = "Complete both the Horde and Alliance versions of the Big City Pet Brawlin' achievements first, then claim this final title. Make sure to visit all major cities for both factions to unlock the necessary sub-achievements.", x = 4 },
        [6671] = { e = 4, s = "s", r = "Specific encounter condition makes this hard to get.", d = "Enter Temple of the Jade Serpent on Heroic difficulty and collect four Seeds of Doubt during the Sha of Doubt encounter. Defeat the boss while these seeds are active to complete the task successfully.", x = 4 },
        [6674] = { e = 3, s = "c", h = { 21786, 21787, 21812 }, r = "Requires mimicking specific boss abilities in a raid.", d = "Face Feng the Accursed in Normal or Heroic mode and mimic every listed ability before defeating him. Pay close attention to his attacks and use your pet's mimic ability on each one shown.", x = 4 },
        [6683] = { e = 4, s = "s", r = "High skill ceiling; requires precise crowd control management.", d = "In Heart of Fear, fight Wind Lord Mel'jarak without crowd-controlling more than two swarms simultaneously. Manage your crowd control abilities carefully to avoid exceeding the limit during the encounter.", x = 4 },
        [6684] = { e = 4, s = "s", r = "Requires perfect pet management and high raid DPS.", d = "Defeat Houndmaster Braun in Scarlet Halls on Heroic difficulty without killing any hounds. Prioritize taking down the boss while avoiding unnecessary damage to the hounds around him.", x = 4 },
        [6686] = { e = 3, s = "c", r = "Timing specific mechanics is difficult but doable solo.", d = "In Mogu'shan Vaults, deactivate six Empyreal Focuses within ten seconds before defeating Elegon. Coordinate with your raid group to ensure quick activation of all focuses during the fight.", x = 4 },
        [6687] = { e = 4, s = "s", r = "Requires full raid coordination and specific mechanic execution.", d = "During Subetai the Swift encounter, get hit by Pillage and then have your entire raid dance together. Ensure everyone in your group is ready to perform the required action immediately after being struck.", x = 4 },
        [6688] = { e = 3, s = "c", h = { 27716 }, r = "Requires killing a rare mob before the boss fight.", d = "In Siege of Niuzao Temple, kill Sik'thik Amberwing before facing Commander Vo'jak on Heroic difficulty. This prerequisite must be met regardless of the difficulty level chosen for the main encounter.", x = 4 },
        [6689] = { e = 4, s = "s", r = "Requires defeating multiple bosses in a specific dungeon.", d = "Complete all Terrace of Endless Spring bosses on Normal or Heroic. This is account-wide and requires a full raid group to defeat the final Sha of Fear boss.", x = 4 },
        [6713] = { e = 2, s = "g", r = "Collecting scattered mobs is tedious but straightforward.", d = "Gather the Jade Quilen in Mogu'Shan Palace on Heroic difficulty. Ensure you are running the dungeon specifically for this collection as they do not drop on Normal.", x = 4 },
        [6715] = { e = 3, s = "c", h = { 22191 }, r = "Requires defeating multiple bosses while under a debuff.", d = "Consume a Polyformic Acid Potion before entering any Pandaria raid or dungeon on Heroic. You must defeat at least one boss while the potion effect is active to claim credit.", x = 4 },
        [6716] = { e = 2, s = "g", r = "Exploring zones to find lore objects is time-consuming.", d = "Locate and interact with all Saurok lore objects scattered across Pandaria zones. This is an exploration achievement that requires visiting specific hidden locations in both normal and capital cities.", x = 4 },
        [6717] = { e = 4, s = "c", h = { 22249 }, r = "Requires precise timing to kill each boss last.", d = "Defeat each Protector of the Endless as the final boss alive on Normal or Heroic. Use a healer to keep the group alive while you focus on killing the last remaining protector in every encounter.", x = 4 },
        [6718] = { e = 3, s = "s", r = "Straightforward progression through the first half of a raid.", d = "Clear the first three bosses of Heart of Fear on any difficulty. This is account-wide and serves as an introductory step before tackling the full raid content.", x = 4 },
        [6719] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Defeat Stone Guard in Mogu'shan Vaults on Heroic difficulty. Ensure your group composition handles the adds effectively since this boss requires precise mechanics management.", x = 4 },
        [6720] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Kill Feng the Accursed in Mogu'shan Vaults on Heroic difficulty. Coordinate with your team to manage his phase transitions and avoid taking excessive damage during the fight.", x = 4 },
        [6721] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Defeat Gara'jal the Spiritbinder in Mogu'shan Vaults on Heroic difficulty. Be prepared for complex mechanics that require strong coordination among raid members to survive his abilities.", x = 4 },
        [6722] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Complete the Four Kings encounter in Mogu'shan Vaults on Heroic difficulty. This boss fight demands careful positioning and timing to avoid being overwhelmed by multiple adds.", x = 4 },
        [6723] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Defeat Elegon in Mogu'shan Vaults on Heroic difficulty. Manage the raid's resources carefully as Elegon has high damage output and requires precise execution of his mechanics.", x = 4 },
        [6724] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Kill the Will of the Emperor in Mogu'shan Vaults on Heroic difficulty. This final boss encounter grants a title upon completion and requires mastering all previous raid mechanics.", x = 4 },
        [6725] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Queue for Heroic Imperial Vizier Zor'lok with a group that can handle mechanics like the cage and adds. This is a time-gated achievement from the Pandaria expansion era, so you cannot start it now without using an older account or waiting for legacy content to return.", x = 4 },
        [6726] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Gather a capable raid group to defeat Blade Lord Ta'yak on Heroic difficulty in Heart of Fear. Like other Pandaria raids, this is time-gated and requires the expansion to be active or accessed via legacy servers.", x = 4 },
        [6727] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Defeat Garalon on Heroic by managing his charge attacks and avoiding the ground slam mechanics. This achievement is time-gated and only available during the Pandaria expansion window or through specific legacy content access.", x = 4 },
        [6728] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Queue for Heroic Wind Lord Mel'jarak, focusing on dodging his tornadoes and managing the elemental adds. This raid boss is time-gated and requires you to have played during the Pandaria expansion era.", x = 4 },
        [6729] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Bring a group to kill Amber-Shaper Un'sok on Heroic, watching for his stone skin mechanics and adds. This achievement is time-gated and cannot be completed in the current retail version of the game.", x = 4 },
        [6730] = { e = 4, s = "s", r = "Heroic raid boss requires a full group.", d = "Defeat Grand Empress Shek'zeer on Heroic by managing her phase transitions and add spawns. This raid encounter is time-gated and requires access to legacy Pandaria content.", x = 4 },
        [6731] = { e = 4, s = "c", r = "Heroic raid boss requires group coordination and RNG.", d = "Queue for the Protectors of the Endless on Heroic in Terrace of Endless Spring, managing their stacking mechanics. This achievement is time-gated and was only available during the original release of the expansion.", x = 4 },
        [6732] = { e = 4, s = "c", r = "Heroic raid boss requires group coordination and RNG.", d = "Defeat Tsulong on Heroic by handling his charge attacks and avoiding the ground slam abilities. This raid boss is time-gated and requires you to have played during the Pandaria expansion era.", x = 4 },
        [6733] = { e = 4, s = "c", r = "Heroic raid boss requires group coordination and RNG.", d = "Bring a group to kill Lei Shi on Heroic, managing his lightning mechanics and add spawns. This achievement is time-gated and cannot be completed in the current retail version of the game.", x = 4 },
        [6734] = { e = 4, s = "c", r = "Heroic raid boss requires group coordination and RNG.", d = "Defeat the Sha of Fear on Heroic to earn the title The Fearless, managing his phase mechanics carefully. This raid boss is time-gated and requires access to legacy Pandaria content.", x = 4 },
        [6736] = { e = 3, s = "s", r = "Specific mechanic trigger on Heroic dungeon boss.", d = "Use Xin the Weaponmaster's secret defense mechanism on Heroic difficulty in Mogu'shan Palace. This achievement is time-gated and requires you to have played during the Pandaria expansion era.", x = 4 },
        [6739] = { e = 2, s = "g", r = "Winning a PvP arena match is relatively quick.", d = "Win a match in Silvershard Mines PvP arena to complete this victory achievement. Note that this is part of a chain leading to the Veteran version, which may also be time-gated depending on current game state.", x = 4 },
        [6740] = { e = 3, s = "s", r = "Winning a specific PvP dungeon requires finding a group.", d = "Queue for the Temple of Kotmogu dungeon until you secure a victory. This achievement is account-wide and requires no specific group composition beyond beating the final boss.", x = 4 },
        [6742] = { e = 5, s = "g", r = "Grinding 60 reputations to Exalted is extremely time-consuming.", d = "Grind daily reputation vendors or complete faction quests to raise 60 reputations to Exalted. Note that this is an account-wide achievement, so progress carries over across all characters.", x = 4 },
        [6753] = { e = 4, s = "g", r = "Looting 2 billion gold requires extensive farming.", d = "Loot gold from dungeons, raids, and world drops until you reach 200,000 total. This is an account-wide tracker, so farming on one character benefits everyone.", x = 4 },
        [6754] = { e = 3, s = "c", r = "Finding scattered lore objects takes exploration time.", d = "Explore Pandaria to find four specific Mogu lore objects located in the Valley of the Emperors, The Lost Dynasty, Spirit Binders, and The Thunder King zones.", x = 4 },
        [6755] = { e = 2, s = "s", r = "Defeating a normal dungeon boss is straightforward.", d = "Complete the normal version of Mogu'shan Palace first to unlock the Heroic difficulty. Defeat Xin the Weaponmaster on Normal mode to claim this achievement.", x = 4 },
        [6756] = { e = 3, s = "s", r = "Heroic dungeon requires finding a group and gear.", d = "Queue for Mogu'shan Palace on Heroic difficulty after completing the normal version. You must defeat Xin the Weaponmaster again under these harder conditions.", x = 4 },
        [6757] = { e = 2, s = "s", r = "Standard dungeon boss kill on normal difficulty.", d = "Run Temple of the Jade Serpent on Normal difficulty and defeat the Sha of Doubt. This unlocks the prerequisite for the Heroic version of this dungeon.", x = 4 },
        [6758] = { e = 3, s = "s", r = "Heroic dungeon requires better gear and coordination.", d = "Complete Temple of the Jade Serpent on Heroic difficulty to finish the chain. Ensure you are prepared for higher-level mechanics before attempting this run.", x = 4 },
        [6759] = { e = 3, s = "s", r = "Heroic dungeon boss kill with specific mechanics.", d = "First clear Gate of the Setting Sun on Normal difficulty, then queue for the Heroic version. Defeat Raigonn to complete both steps of this achievement chain.", x = 4 },
        [6760] = { e = 3, s = "s", r = "Heroic dungeon boss kill on normal difficulty.", d = "Clear Scarlet Halls on Normal mode before attempting the Heroic run. Defeat Flameweaver Koegler on Heroic difficulty to earn the points for this entry.", x = 4 },
        [6761] = { e = 3, s = "s", r = "Heroic dungeon boss kill with specific mechanics.", d = "Complete Scarlet Monastery on Normal difficulty first, then switch to Heroic mode. You must defeat High Inquisitor Whitemane on Heroic to finish this achievement.", x = 4 },
        [6762] = { e = 3, s = "s", r = "Heroic dungeon boss kill on normal difficulty.", d = "Finish Scholomance on Normal difficulty before attempting the Heroic version. Defeat Darkmaster Gandling on Heroic mode to complete this final dungeon achievement.", x = 4 },
        [6763] = { e = 3, s = "s", r = "Heroic dungeon boss kill with specific mechanics.", d = "Defeat Wing Leader Ner'onok on Heroic difficulty in Siege of Niuzao Temple. Ensure you have access to the dungeon before attempting this specific wing leader encounter.", x = 4 },
        [6821] = { e = 4, s = "g", r = "Grinding 50 specific kills within a short time limit.", d = "Farm Expired Test Subjects in Scholomance Heroic, aiming for 50 kills within a strict 20-second window. Coordinate with your group to maximize damage output and avoid unnecessary downtime between pulls.", x = 4 },
        [6822] = { e = 4, s = "s", r = "Heroic boss kill requiring specific buff timing.", d = "Defeat Ner'onok on Heroic while maintaining the Tenwu's Resolve buff throughout the entire fight. Keep an eye on the buff timer and ensure it is active before the boss dies.", x = 4 },
        [6823] = { e = 3, s = "s", r = "Raid boss kill with pet requirement for all members.", d = "Bring canine companion pets to your raid group and defeat the Stone Guard in Mogu'shan Vaults. Verify every member has a pet equipped before engaging the encounter.", x = 4 },
        [6824] = { e = 4, s = "s", r = "Raid boss kill requiring specific debuff on all members.", d = "Defeat Lei Shi on Normal or Heroic while ensuring all raid members have Parasitic Clutch active. Monitor debuff timers carefully to prevent anyone from losing the effect before the kill.", x = 4 },
        [6825] = { e = 4, s = "s", r = "Raid boss kill avoiding a specific mechanic entirely.", d = "Defeat the Sha of Fear without any raid member being feared by Dread Spray or Breath of Fear. Use appropriate crowd control and defensive cooldowns to mitigate fear effects immediately.", x = 4 },
        [6826] = { e = 4, s = "g", r = "Grinding 55 factions to Exalted is a massive time sink.", d = "Raise 55 different reputations to Exalted across your account, noting that this is a cumulative goal. Prioritize factions with efficient reputation gain methods to save time.", x = 4 },
        [6827] = { e = 4, s = "g", r = "Requires grinding massive amounts of XP with specific factions.", d = "Earn Exalted with all Pandaren factions listed for the Honor version of the achievement. This requires significant grinding and may take considerable time depending on your current progress.", x = 4 },
        [6828] = { e = 4, s = "g", r = "Requires grinding massive amounts of XP with specific factions.", d = "Earn Exalted with all Pandaren factions listed for the Adventure version of the achievement. Similar to the previous one, focus on efficient reputation gain strategies.", x = 4 },
        [6830] = { e = 3, s = "g", r = "Grinding profession skill points is moderate but tedious.", d = "Gain 75 skill points in a single Pandaria-category primary profession like Engineering or Alchemy. Focus on leveling up your chosen profession efficiently to reach the required skill points.", x = 4 },
        [6835] = { e = 3, s = "g", r = "Requires grinding two professions to Pandaria skill caps.", d = "Obtain 75 skill points in two different Pandaria-category primary professions after completing the first achievement. Select two professions you enjoy and level them simultaneously for efficiency.", x = 4 },
        [6836] = { e = 4, s = "g", r = "Grinding 600 skill points in four legacy professions is hard.", d = "Accumulate 600 skill points each in Fishing, First Aid, Cooking, and Archaeology. These legacy achievements require extensive grinding and may take a long time to complete.", x = 4 },
        [6837] = { e = 4, s = "g", r = "Grinding 600 archaeology skill points requires extensive digging.", d = "Grind archaeology dig sites until you hit 600 skill points, noting that this is a prerequisite for the next tier. You can do this solo by repeatedly excavating artifacts in any zone with active dig sites. There are no time gates, but rare drops from excavations may be needed to maximize your points efficiently.", x = 4 },
        [6838] = { e = 4, s = "g", r = "Grinding 600 first aid skill points requires many mobs.", d = "Focus on finding first aid trainers and completing quests that award large skill point gains to reach 600 quickly. This achievement is account-wide and has no time gate, so you can start it at any level once you learn the profession. Avoid wasting time on low-yield healing quests if you are behind on points.", x = 4 },
        [6839] = { e = 3, s = "g", r = "Grinding fishing skill points is moderate but takes time.", d = "Fish in Pandaria zones like Kun-Lai Summit or Valley of the Four Winds to gain 75 skill points in that specific category. Since this is a category-specific goal, ensure your fishing skill is high enough to catch rare fish without wasting time. No group is needed, but some rare fish may drop only from specific world events.", x = 4 },
        [6844] = { e = 4, s = "c", h = { 90, 91, 92 }, r = "Defeating final raid bosses requires high-level gear and groups.", d = "Defeat the final three bosses of Mogu'shan Vaults in order: Four Kings, Elegon, and Will of the Emperor. This requires completing the first half of the raid before attempting these encounters. Coordinate with your group to handle the mechanics of each boss efficiently as this is account-wide.", x = 4 },
        [6845] = { e = 4, s = "c", h = { 22261, 22262, 22264 }, r = "Defeating final raid bosses requires high-level gear and groups.", d = "Clear Heart of Fear by defeating Wind Lord Mel'jarak, Amber-Shaper Un'sok, and Grand Empress Shek'zeer in sequence. Ensure you have completed the first half of the raid before tackling these final bosses. This achievement is account-wide, so coordinate with your guild or group to handle the challenging mechanics.", x = 4 },
        [6846] = { e = 3, s = "c", r = "Finding lore objects is moderate but requires thorough exploration.", d = "Explore Pandaria to find all Jinyu lore objects scattered across zones like Kun-Lai Summit and Valdrakken. Use a map tool or guide to locate these specific items, as they are often hidden in hard-to-reach areas. This is an exploration achievement with no time gate, but some objects may require rare drops or specific conditions.", x = 4 },
        [6847] = { e = 3, s = "c", r = "Collecting scattered lore objects across Pandaria zones.", d = "Discover all Yaungol lore objects by exploring Pandaria zones and completing related quests or finding hidden items. These objects are often tied to Yaungol culture and may require visiting specific locations or defeating certain enemies. No group is needed, but some objects might be rare drops from world events.", x = 4 },
        [6850] = { e = 3, s = "c", r = "Collecting scattered Hozen lore objects in Pandaria.", d = "Find all Hozen lore objects in Pandaria by exploring zones like Kun-Lai Summit and completing related quests. These items are often hidden in hard-to-reach areas or require specific conditions to unlock. This achievement is account-wide, so coordinate with your group if needed for difficult encounters.", x = 4 },
        [6851] = { e = 4, s = "g", r = "Grinding pet battles to find all families.", d = "Win solo pet battles against every family by collecting a diverse team of pets and testing them against different opponents. Start by battling common families like Aquatic and Beast before moving to rarer ones like Dragonkin or Mechanical. This is account-wide, so ensure your pets are well-leveled and equipped for each encounter.", x = 4 },
        [6855] = { e = 3, s = "c", r = "Collecting scattered Shaohao lore objects in Pandaria.", d = "Discover all Shaohao lore objects by exploring Pandaria zones and completing related quests or finding hidden items. These objects are often tied to Shaohao's story and may require visiting specific locations or defeating certain enemies. This is an exploration achievement with no time gate, but some objects might be rare drops.", x = 4 },
        [6856] = { e = 3, s = "c", r = "Collecting scattered Liu Lang lore objects in Pandaria.", d = "Find all Liu Lang lore objects by exploring Pandaria zones and completing related quests or finding hidden items. These objects are often tied to Liu Lang's story and may require visiting specific locations or defeating certain enemies. This is an exploration achievement with no time gate, but some objects might be rare drops.", x = 4 },
        [6857] = { e = 3, s = "c", r = "Collecting scattered Mantid lore objects in Pandaria.", d = "Discover all Mantid lore objects by exploring Pandaria zones and completing related quests or finding hidden items. These objects are often tied to the Mantid Swarm's story and may require visiting specific locations or defeating certain enemies. This is an exploration achievement with no time gate, but some objects might be rare drops.", x = 4 },
        [6858] = { e = 3, s = "c", r = "Collecting scattered Monk lore objects in Pandaria.", d = "Find the five specific Monk lore objects scattered across Pandaria zones. Check your quest log for 'Pandaren Fighting Tactics' and similar items to track progress, as missing these collectibles makes the achievement missable.", x = 4 },
        [6874] = { e = 4, s = "c", h = { 28621 }, r = "Requires specific Saturday timing for some scenarios.", d = "Play all listed scenarios on a Saturday to earn points; note that this is account-wide but requires playing on a specific day of the week. You can queue for multiple scenarios in one session if they are available.", x = 4 },
        [6882] = { e = 4, s = "g", r = "Grinding 100 PvP victories in a rated arena.", d = "Queue for Temple of Kotmogu PvP and win 100 matches total across all realms. This is account-wide, so play with friends or find groups to speed up the grind significantly.", x = 4 },
        [6883] = { e = 4, s = "g", r = "Grinding 100 PvP victories in Silvershard Mines.", d = "Complete 100 victories in Silvershard Mines PvP. Like other arena achievements, this counts toward your account total, so coordinate with a group to maximize win rates efficiently.", x = 4 },
        [6884] = { e = 4, s = "s", r = "Challenge mode requires specific gear and skill.", d = "Enter the Temple of the Jade Serpent Challenge Mode for the first time. This unlocks the bronze tier and serves as the starting point for the entire rating progression chain.", x = 4 },
        [6885] = { e = 4, s = "s", r = "Requires completing challenge with Bronze rating.", d = "Repeat runs in Temple of the Jade Serpent until your rating reaches Bronze or higher. You must complete the Challenger achievement first, then focus on improving your team's performance.", x = 4 },
        [6886] = { e = 3, s = "g", r = "Requires clearing dungeon with specific rating.", d = "Continue grinding Temple of the Jade Serpent to reach Silver rating. This requires consistent high-level play and may need a dedicated group to maintain the necessary skill ceiling.", x = 4 },
        [6887] = { e = 3, s = "g", r = "Requires clearing dungeon with higher rating.", d = "Push your rating to Gold in Temple of the Jade Serpent for the final tier and teleport unlock. This is the hardest step, requiring top-tier coordination and strategy from your group.", x = 4 },
        [6888] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Start Stormstout Brewery Challenge Mode immediately after unlocking it. Treat this like a dungeon run where you must clear the instance to progress through the rating tiers.", x = 4 },
        [6889] = { e = 3, s = "g", r = "Requires clearing dungeon with Bronze rating.", d = "Grind Stormstout Brewery until your team achieves Bronze rating. Focus on learning the mechanics quickly, as the Bronze tier is often easier than expected for well-coordinated groups.", x = 4 },
        [6890] = { e = 3, s = "g", r = "Requires clearing dungeon with Silver rating.", d = "Advance through Silver rating in Stormstout Brewery with a skilled group. The difficulty increases noticeably here, so ensure everyone knows their roles before attempting higher ratings.", x = 4 },
        [6891] = { e = 3, s = "g", r = "Requires clearing dungeon with Gold rating.", d = "Reach Gold rating in Stormstout Brewery to complete the chain and unlock the teleport ability. This final tier demands precise execution and may require multiple attempts with different compositions.", x = 4 },
        [6892] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Queue for Mogu'shan Palace Challenge Mode immediately after unlocking the dungeon. This is account-wide, so one completion unlocks the next tier for all characters.", x = 4 },
        [6893] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Start Shado-Pan Monastery Challenge Mode once you are ready. Remember that this achievement is account-wide and will unlock the Bronze tier for your entire account.", x = 4 },
        [6894] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Queue for Gate of the Setting Sun Challenge Mode to begin the progression chain. This is account-wide, so completing it unlocks the next tier for all characters on your account.", x = 4 },
        [6895] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Begin Scarlet Halls Challenge Mode as soon as you can queue. This achievement is account-wide, meaning one completion unlocks the next tier for every character.", x = 0 },
        [6896] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Start Scarlet Monastery Challenge Mode to begin the progression chain. This is account-wide, so completing it unlocks the next tier for all characters on your account.", x = 0 },
        [6897] = { e = 3, s = "g", r = "Requires completing challenge mode instance.", d = "Queue for Scholomance Challenge Mode once you are ready. This achievement is account-wide, meaning one completion unlocks the next tier for every character.", x = 0 },
        [6898] = { e = 4, s = "s", r = "Requires finding a group for high-level Challenge Mode.", d = "Begin Siege of Niuzao Temple Challenge Mode to start the progression chain. This is account-wide, so completing it unlocks the next tier for all characters on your account.", x = 4 },
        [6899] = { e = 4, s = "g", r = "Grinding Bronze rating requires multiple runs with a group.", d = "Complete Mogu'shan Palace Challenge Mode with a Bronze rating or better. You must first complete the Challenger achievement, and this is account-wide.", x = 4 },
        [6900] = { e = 4, s = "g", r = "Grinding Silver rating requires multiple runs with a group.", d = "Achieve a Silver rating or better in Mogu'shan Palace Challenge Mode. This requires completing the Bronze tier first and is account-wide.", x = 4 },
        [6901] = { e = 5, s = "g", r = "Gold rating is extremely difficult and requires top-tier groups.", d = "Reach a Gold rating in Mogu'shan Palace Challenge Mode to unlock the teleport ability. You must complete the Silver tier first, and this is account-wide.", x = 4 },
        [6902] = { e = 4, s = "s", r = "Requires finding a group for high-level Challenge Mode.", d = "Complete Shado-Pan Monastery Challenge Mode with a Bronze rating or better. This requires the Challenger achievement and is account-wide.", x = 4 },
        [6903] = { e = 4, s = "g", r = "Grinding Silver rating requires multiple runs with a group.", d = "Achieve a Silver rating in Shado-Pan Monastery Challenge Mode. You must first complete the Bronze tier, and this is account-wide.", x = 4 },
        [6904] = { e = 5, s = "g", r = "Gold rating is extremely difficult and requires top-tier groups.", d = "Queue for Shado-Pan Monastery Challenge Mode and aim for a Gold rating to unlock the teleport. This is account-wide, so any character can complete it once you have the Silver requirement.", x = 4 },
        [6905] = { e = 4, s = "s", r = "Requires finding a group for high-level Challenge Mode.", d = "First queue for Gate of the Setting Sun Challenger to unlock the Bronze tier. Then repeat runs until you hit Silver and finally Gold ratings.", x = 4 },
        [6906] = { e = 4, s = "g", r = "Grinding Silver rating requires multiple runs with a group.", d = "You must complete the Bronze version first before attempting Silver or Gold. Keep running the dungeon with a group focused on high damage output to push your rating up.", x = 4 },
        [6907] = { e = 5, s = "g", r = "Gold rating is extremely difficult and requires top-tier groups.", d = "Reach the Silver rating before trying for Gold. Once you hit Gold, you unlock the teleport ability for this dungeon, which is account-wide.", x = 4 },
        [6908] = { e = 4, s = "s", r = "Requires finding a group for high-level Challenge Mode.", d = "Start by queuing for Scarlet Halls Challenger to access the Bronze tier. Focus on consistent performance to move through the Silver and Gold ratings sequentially.", x = 0 },
        [6909] = { e = 4, s = "g", r = "Grinding Silver rating requires multiple runs with a group.", d = "Complete the Bronze run first, then grind for Silver. You cannot attempt higher tiers until you have unlocked the previous one in the chain.", x = 0 },
        [6910] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Achieve Silver rating before attempting Gold. Finishing the Gold tier unlocks the teleport to Scarlet Halls for your entire account.", x = 0 },
        [6911] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Queue for Scarlet Monastery Challenger to begin the Bronze tier. Consistent high-level performance is needed to progress through Silver and finally Gold.", x = 0 },
        [6912] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "You must finish the Bronze run before unlocking Silver. Repeat runs with a skilled group to steadily increase your rating without missing content.", x = 0 },
        [6913] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Reach Silver first, then push for Gold to unlock the teleport reward. This achievement is account-wide, so any character can claim it once requirements are met.", x = 0 },
        [6914] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Start with Scholomance Challenger to unlock Bronze. There is no time gate, but you must complete lower tiers before attempting higher ratings.", x = 0 },
        [6915] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Complete Bronze and Silver first; Gold requires a high rating on the same dungeon. No specific rare drops or missable content exist for these Challenge Mode achievements.", x = 0 },
        [6916] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Complete Scholomance Challenge Mode with a Silver rating first to unlock the Gold requirement, as this is account-wide and time-gated by level.", x = 0 },
        [6917] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Start Siege of Niuzao Temple Challenge Mode immediately after unlocking it; you must earn Bronze before attempting Silver or Gold tiers.", x = 4 },
        [6918] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Progress through the Bronze tier first to unlock Silver, then repeat runs until your rating improves to meet the next threshold.", x = 4 },
        [6919] = { e = 3, s = "c", r = "Requires specific dungeon runs and rating improvement.", d = "Once you have Silver, focus on optimizing your group's performance to reach a Gold rating for the teleport reward and final tier.", x = 4 },
        [6920] = { e = 4, s = "c", r = "Must complete all listed Challenge Mode dungeons first.", d = "Check your account-wide list of Challenge Mode dungeons; complete any missing ones first since some may be time-gated or require specific levels.", x = 4 },
        [6922] = { e = 3, s = "c", r = "Requires specific raid kill order and timing.", d = "In Heart of Fear, coordinate with your group to kill two Kor'thik Reavers within 10 seconds before pulling Grand Empress Shek'zeer on Normal or Heroic.", x = 4 },
        [6923] = { e = 3, s = "s", r = "Requires running a specific scenario boss fight.", d = "Participate in the Brewmoon Festival scenario and focus entirely on defeating Warbringer Qobi, as this is a specific scenario achievement.", x = 4 },
        [6924] = { e = 4, s = "g", r = "Requires farming Valor points over many hours/days.", d = "Farm Valor Points through dungeons and raids consistently; note that earning 50,000 points is required before you can earn the next 50,000.", x = 4 },
        [6925] = { e = 3, s = "c", h = { 22873, 22874, 22875 }, r = "Requires completing multiple heroic dungeons; first three are hardest.", d = "Complete all listed Heroic Pandaria dungeon achievements first, as they are prerequisites for this summary achievement which tracks your overall progress.", x = 4 },
        [6926] = { e = 3, s = "c", h = { 22886, 22889 }, r = "Requires killing multiple Sha; Doubt and Violence are hardest.", d = "Defeat every Sha manifestation on Normal or Heroic difficulty; ensure you have completed the Tranquil Master kill list before claiming the title.", x = 4 },
        [6927] = { e = 3, s = "c", h = { 22894, 22895 }, r = "Requires completing many dungeon achievements; first two are hardest.", d = "Finish all Pandaria Heroic dungeon achievements and related content to unlock this summary achievement, which rewards a mount upon completion.", x = 4 },
        [6928] = { e = 3, s = "s", r = "Specific mechanic fight in Scarlet Monastery Heroic.", d = "In Scarlet Monastery Heroic, use abilities or mechanics to set Brother Korloff's training dummies on fire before defeating him for the Burning Man title.", x = 4 },
        [6929] = { e = 4, s = "c", h = { 23444 }, r = "Requires killing many Judicators before final boss; Whitemane is hardest.", d = "Start by killing 13 revived Scarlet Judicators before engaging Whitemane, as she must cast Mass Resurrection first. Ensure you do not kill the resurrected adds until after she uses her ability on Heroic difficulty.", x = 4 },
        [6930] = { e = 3, s = "s", r = "Requires perfecting a scenario run without mistakes.", d = "Complete the Brewmoon Festival scenario while actively preventing any Bataari invaders from setting the village on fire. Focus your defensive efforts immediately upon spawn to avoid triggering the failure condition.", x = 4 },
        [6931] = { e = 2, s = "c", h = { 22925 }, r = "Requires using various defenses; Briaw Shan is hardest.", d = "Personally activate every single defense mechanism available during the Brewmoon Festival scenario to claim this title. Do not rely on party members; you must manually use each item yourself.", x = 4 },
        [6932] = { e = 4, s = "c", h = { 22938, 22939 }, r = "Requires completing many raid achievements; first two are hardest.", d = "This is a collection achievement requiring you to complete all listed Pandaria raid sub-achievements first. Since it grants an account-wide mount, ensure your entire guild or group works toward the specific raid goals together.", x = 4 },
        [6933] = { e = 4, s = "s", r = "High-difficulty raid encounter with strict mechanic.", d = "Win the Tsulong encounter by prioritizing the protection of the Enchanted Plant over killing adds. Keep the plant alive throughout the entire fight to secure the achievement.", x = 4 },
        [6936] = { e = 4, s = "s", r = "Requires specific setup and execution in Heart of Fear.", d = "Light all four braziers in Heart of Fear before engaging Blade Lord Ta'yak on Normal or Heroic difficulty. Maintain the lit state until the boss is defeated without letting them go out.", x = 4 },
        [6937] = { e = 4, s = "c", r = "Requires specific debuff management during a raid encounter.", d = "Defeat Imperial Vizier Zor'lok only after ensuring every single raid member has the Zealous Parasite debuff active. Coordinate with your group to apply the parasite before starting the encounter.", x = 4 },
        [6941] = { e = 5, s = "g", r = "Top 0.5% ranking requires massive win count and high skill.", d = "Play rated battlegrounds consistently until you reach 50 wins and secure a top 0.5% ranking at the end of a season. Note that this requires finishing within a specific seasonal timeframe.", x = 4 },
        [6942] = { e = 5, s = "g", r = "Top 0.5% ranking requires massive win count and high skill.", d = "Similar to the Horde version, play rated battlegrounds for the Alliance side to reach 50 wins and top 0.5% standing by season's end. Timing is critical as these ranks reset with each new PvP season.", x = 4 },
        [6943] = { e = 3, s = "g", r = "Requires completing 100 scenarios, a moderate time investment.", d = "Complete exactly 100 different scenarios in Pandaria to unlock this achievement. Track your progress carefully as the next tier of this chain is currently inactive.", x = 4 },
        [6945] = { e = 2, s = "s", r = "Specific mechanic in one dungeon run; doable with practice.", d = "Defeat Raigonn in the Mantid Swarm encounter without killing any of the summoned Mantid reinforcements. Use crowd control and area denial abilities to protect the adds until the boss dies.", x = 4 },
        [6946] = { e = 3, s = "s", r = "Requires specific add management in a heroic dungeon.", d = "Keep three Empowered Zombies alive while defeating Thalnos the Soulrender on Heroic difficulty. Do not kill these specific adds, as losing them will cause the achievement to fail.", x = 4 },
        [6947] = { e = 2, s = "c", r = "Mechanic-based objective; partial progress is irrelevant but achievable.", d = "Coordinate with your team to capture all four orbs simultaneously during a single match. Focus on securing the center first, then quickly grab the scattered orbs before they despawn or are taken by opponents.", x = 4 },
        [6950] = { e = 3, s = "s", r = "Requires precise timing and coordination in a PvP mode.", d = "Position yourself in the arena center and hold an orb for 90 seconds while defending against enemy attacks. Avoid moving to other zones until the timer is nearly complete to ensure success.", x = 4 },
        [6969] = { e = 4, s = "g", r = "Exploring a large zone thoroughly takes several hours of travel.", d = "Travel through Pandaria and interact with every named location listed in the info field to reveal map areas. Use flight paths or flying mounts to efficiently visit distant points like Stormstout Brewery.", x = 4 },
        [6970] = { e = 3, s = "g", r = "Requires killing 100 specific enemies over multiple matches.", d = "Focus on killing enemies that are currently holding an orb, as standard kills do not count. This requires active participation in orb control rather than just farming mobs.", x = 4 },
        [6971] = { e = 4, s = "s", r = "High-skill coordination required to win with all orbs active.", d = "Win a match while your team maintains control of all four orbs at the moment of victory. Coordinate with teammates to keep the center orb and quickly retake others if lost.", x = 4 },
        [6972] = { e = 3, s = "g", r = "Requires accumulating significant points over many matches.", d = "Play multiple matches to accumulate 8,000 victory points for your team. Consistent participation in ranked or casual battles will eventually reach this threshold.", x = 4 },
        [6973] = { e = 4, s = "g", r = "Grinding 100 kills while holding an orb in PvP.", d = "Kill enemies while you are personally holding an orb to count toward the total. Switch between orbs frequently to maximize kills without dropping the current one.", x = 4 },
        [6974] = { e = 3, s = "c", r = "Exploring all Pandaria zones is moderate effort.", d = "Visit every region listed in the info field, including Townlong Steppes and Dread Wastes, to fully explore Pandaria. Use flying mounts to speed up visiting remote areas like the Vale of Eternal Blossoms.", x = 4 },
        [6975] = { e = 2, s = "g", r = "Exploring one zone takes under an hour solo.", d = "Explore Krasarang Wilds by interacting with all named locations such as The Forbidden Jungle and Unga Ingoo. Flying is highly recommended to cover the large, dense jungle terrain efficiently.", x = 4 },
        [6976] = { e = 2, s = "g", r = "Exploring Kun-Lai Summit is easy for a level 85.", d = "Interact with every location in Kun-Lai Summit, from Binan Village to Mount Neverest. Use flying mounts to access high peaks and hidden caves quickly for faster completion.", x = 4 },
        [6977] = { e = 3, s = "g", r = "Exploring Townlong Steppes takes a few hours.", d = "Visit all named spots in Townlong Steppes, including the Sumprushes and Niuzao Temple. Flying is essential here due to the scattered layout of camps and ruins.", x = 4 },
        [6978] = { e = 2, s = "g", r = "Exploring Dread Wastes is easy with flight paths.", d = "Explore every region listed for Pandaria Explorer, starting with Jade Forest and ending with Dread Wastes. Ensure you visit each sub-region to unlock the full achievement.", x = 4 },
        [6979] = { e = 2, s = "g", r = "Exploring Vale of Eternal Blossoms is easy solo.", d = "Travel to Pandaria and visit every listed location on your map to reveal them. This is account-wide and requires no group, but ensure you have completed the main story questline first.", x = 4 },
        [6980] = { e = 4, s = "s", r = "Requires specific PvP match conditions and luck.", d = "Queue for Temple of Kotmogu and focus on grabbing orbs while killing opponents holding them in one match. This is PvP only and requires a full group to complete efficiently.", x = 4 },
        [6981] = { e = 5, s = "c", h = { 24556, 24557, 24558 }, r = "Requires completing all other Kotmogu achievements first.", d = "Complete all sub-achievements listed under this title by playing various modes of Temple of Kotmogu. You must finish every prerequisite achievement before unlocking the main reward.", x = 4 },
        [7039] = { e = 4, s = "s", r = "Escort objective in PvP arena requires coordination.", d = "Play Silvershard Mines and successfully escort a mine cart from spawn to the depot without dying or losing control. This requires coordination with your team to protect the cart.", x = 4 },
        [7049] = { e = 4, s = "c", h = { 27230, 27231, 27232 }, r = "Requires specific track combinations in a single match.", d = "In a single Silvershard Mines match, capture carts on all five distinct track sets. Plan your route carefully to ensure you hit every track type before the match ends.", x = 4 },
        [7056] = { e = 4, s = "s", r = "Requires raiding Gara'jal and activating the artifact.", d = "Run Gara'jal the Spiritbinder in Mogu'shan Vaults and activate the Ancient Mogu Artifact during the encounter. This is a raid achievement that requires specific timing and group coordination.", x = 4 },
        [7057] = { e = 3, s = "s", r = "Requires specific timing and positioning in a PvP match.", d = "Queue for Silvershard Mines and steal an enemy cart near the depot before it caps, then secure it yourself. Timing your movement to intercept carts just before they finish is key.", x = 4 },
        [7062] = { e = 4, s = "g", r = "Killing 250 enemies while defending requires sustained effort.", d = "Defend a mine cart in Silvershard Mines for the duration of the match while killing 250 enemies. Stay near the cart and focus fire on attackers to reach the kill count.", x = 4 },
        [7099] = { e = 4, s = "s", r = "Capturing five carts without dying is a high-skill single run.", d = "Capture five mine carts in one Silvershard Mines game without dying once. This is extremely difficult and requires a high-level team that can protect you while you run for carts.", x = 4 },
        [7100] = { e = 4, s = "s", r = "Winning perfectly without losing any cart is extremely difficult.", d = "Win a Silvershard Mines match where your team captures every cart before the enemy gets any. Coordinate with your group to prioritize capturing over killing opponents.", x = 4 },
        [7102] = { e = 3, s = "g", r = "Capturing 100 carts takes time but shrinks steadily.", d = "Capture 100 mine carts total in Silvershard Mines across multiple matches. This is account-wide, so play frequently and aim for every cart that spawns.", x = 4 },
        [7103] = { e = 2, s = "s", r = "Getting two buffs simultaneously is rare but achievable quickly.", d = "In Silvershard Mines, stack buffs to gain both Berserking and Restoration simultaneously. Use defensive abilities to survive while maintaining offensive pressure to trigger both effects.", x = 4 },
        [7106] = { e = 4, s = "c", h = { 24549, 24551, 24552 }, r = "Dominated by the hardest single-run Silvershard Mines achievements.", d = "Start by completing the Silvershard Mines Veteran achievement first to unlock other content. Complete each sub-achievement sequentially as they often require specific mechanics or rare drops that may not reappear if missed.", x = 4 },
        [7230] = { e = 2, s = "c", r = "Finding three shrines is easy once you know where to look.", d = "Travel across Pandaria to locate and interact with the three Brewfather Shrines. Ensure you visit all locations in the zone before leaving, as these shrines are missable once you progress too far.", x = 4 },
        [7231] = { e = 4, s = "s", r = "Completing a scenario stage perfectly without mistakes is hard.", d = "In Unga Ingoo Stage 2, focus on protecting the cauldron from Brewmaster minions. Coordinate with your group to clear threats quickly while keeping an eye on the brew level.", x = 4 },
        [7232] = { e = 5, s = "s", r = "Beating a stage in under four minutes requires perfect execution.", d = "Run through Unga Ingoo Stage 2 multiple times to shave off time. Optimize your rotation and movement to defeat bosses efficiently without unnecessary delays or deaths.", x = 4 },
        [7239] = { e = 4, s = "s", r = "Defeating a boss while avoiding a specific mechanic is hard.", d = "During Captain Ook's fight in Monkey in the Middle, avoid letting him pick up oranges dropped by minions. Focus on killing threats that drop oranges before they reach him.", x = 4 },
        [7248] = { e = 3, s = "c", r = "Beating all scenario bosses is moderate effort across multiple runs.", d = "Complete all Unga Ingoo boss encounters to unlock this achievement. Make sure you defeat every boss listed in the info field, including protected ones like the Keg.", x = 4 },
        [7249] = { e = 3, s = "s", r = "Single boss fight in a scenario.", d = "Defeat Captain Ook in Unga Ingoo by managing his mechanics and avoiding unnecessary damage. This is a core requirement for other related achievements in the scenario.", x = 4 },
        [7252] = { e = 3, s = "s", r = "Single boss fight in a scenario.", d = "Enter A Brewing Storm and focus on defeating Borokhula the Destroyer. Use appropriate tactics to handle her abilities while coordinating with your party members.", x = 4 },
        [7257] = { e = 4, s = "c", r = "High RNG requirement to avoid specific mechanic.", d = "In A Brewing Storm, position yourself carefully to avoid Borokhula's Swamp Smash ability. Communicate with your group to ensure no one takes this specific hit during the fight.", x = 4 },
        [7258] = { e = 4, s = "c", r = "Requires managing multiple adds and mechanics.", d = "Finish A Brewing Storm while keeping all six Thunderpaw Guardians alive. Prioritize protecting them over killing enemies if necessary, and use healing or defensive cooldowns wisely.", x = 4 },
        [7261] = { e = 4, s = "c", r = "Heavy RNG requirement to dodge lightning for party.", d = "Brew the Boomer Brew in A Brewing Storm without anyone getting hit by lightning. Dodge lightning attacks carefully and coordinate with your party to minimize exposure during critical moments.", x = 4 },
        [7265] = { e = 3, s = "s", r = "Single boss fight in a scenario.", d = "Enter the Greenstone Village scenario and defeat Vengeful Hui. Be prepared for challenging mechanics and ensure your group is ready to handle the boss's abilities effectively.", x = 4 },
        [7266] = { e = 4, s = "c", r = "Requires avoiding specific item usage mechanic.", d = "Start the Greenstone Village scenario and avoid drinking any Volatile Greenstone Brew. If you accidentally drink one, restart the scenario immediately to reset your progress.", x = 4 },
        [7267] = { e = 3, s = "g", r = "Collecting items while avoiding damage.", d = "Carry six stolen kegs through the Greenstone Village scenario without taking damage or letting them explode. Move carefully around enemies and environmental hazards to ensure safe delivery.", x = 4 },
        [7268] = { e = 3, s = "s", r = "Single boss fight in a scenario.", d = "Complete the Temple of Kotmogu scenario and defeat General Zhun. Ensure you finish all other objectives before engaging him for full credit.", x = 4 },
        [7269] = { e = 4, s = "c", r = "Requires avoiding aggro from multiple mobs.", d = "Navigate the Temple of Kotmogu scenario while avoiding aggro from Zhun'ji Maulers and Ancestral Horrors. Use stealth or careful positioning to bypass these mobs without triggering them.", x = 4 },
        [7270] = { e = 4, s = "c", r = "Requires avoiding specific item usage mechanic.", d = "Defeat General Zhu in the Temple of Kotmogu scenario without using any artifact orbs. Save your orbs for emergencies or skip abilities that require them.", x = 4 },
        [7271] = { e = 3, s = "s", r = "Single scenario completion event.", d = "Finish all objectives in the Arena of Annihilation scenario to claim this achievement. Ensure you complete every step before time runs out.", x = 4 },
        [7272] = { e = 3, s = "c", r = "Defeat three bosses in a scenario; straightforward but requires completion.", d = "Defeat Cloudbender Kobo, Maki Waterblade, and Satay Byu in the Arena of Annihilation scenario. Coordinate with your group to handle all three bosses efficiently.", x = 4 },
        [7273] = { e = 3, s = "s", r = "One specific run with a mechanic; trivial once known.", d = "Complete the Arena of Annihilation scenario while preventing anyone from taking damage from Flame Walls. Position yourself away from walls or use abilities that mitigate fire damage.", x = 4 },
        [7274] = { e = 1, s = "g", r = "Fish until exalted; steady progress, very low difficulty.", d = "Reach Exalted reputation with Nat Pagle to earn this account-wide fishing achievement. Focus on completing his daily quests and turning in rare catches.", x = 4 },
        [7275] = { e = 2, s = "s", r = "Step on a trap in a scenario; easy and quick.", d = "Enter the Crypt of Forgotten Kings scenario and intentionally step on a floor trap. Look for glowing or marked tiles that trigger the trap mechanism.", x = 4 },
        [7276] = { e = 3, s = "s", r = "Defeat one boss avoiding damage; requires skill but short.", d = "Defeat the Abomination of Anger in the Crypt of Forgotten Kings without taking damage from red clouds. Stay out of cloud areas or use damage reduction abilities when near them.", x = 4 },
        [7281] = { e = 3, s = "g", r = "Find one treasure; easy to start, part of a larger chain.", d = "Explore Pandaria to locate one of the hidden lost treasures scattered across the zone. Check caves, ruins, and hard-to-reach areas for these collectibles.", x = 4 },
        [7282] = { e = 3, s = "g", r = "Find five treasures; requires more time than the first one.", d = "Start by finding the first lost treasure to unlock the next step. These items are scattered across Pandaria and require exploration, so check every zone thoroughly. Do not worry about time gates as these are account-wide collectibles.", x = 4 },
        [7283] = { e = 3, s = "g", r = "Find ten treasures; moderate grind, part of a chain.", d = "Continue hunting for lost treasures after completing the previous tier. Since you need ten more, keep exploring new areas or revisit old ones where items might spawn again. This is purely a collection task with no strict time limit.", x = 4 },
        [7284] = { e = 3, s = "g", r = "Find twenty treasures; longest grind in the chain, still easy.", d = "Finish collecting twenty treasures to earn your title. Once done, celebrate by checking your character name for the new title. No special conditions exist beyond finding all the hidden chests.", x = 4 },
        [7285] = { e = 4, s = "g", r = "Complete 25 dailies in one day; requires significant time investment.", d = "Pick up any available daily quests in Pandaria and complete them before the server resets. Aim to finish all tasks quickly to ensure you hit the twenty-five quest count. Missing a reset means waiting another day, so prioritize these over other activities.", x = 4 },
        [7286] = { e = 3, s = "c", r = "Defeat eleven challengers; straightforward but involves many fights.", d = "Travel to the Temple of the White Tiger and defeat each challenger listed in the info field. Some opponents may be tough, so bring appropriate gear or group up if needed. Ensure you kill every single one to claim the achievement.", x = 4 },
        [7287] = { e = 3, s = "c", r = "Defeat multiple challengers in a scenario; easy once entered.", d = "Go to the Cradle of Chi-Ji and challenge every opponent there. This area is distinct from the White Tiger temple, so navigate carefully. Defeating all challengers will grant you this specific quest completion.", x = 4 },
        [7288] = { e = 1, s = "s", r = "Quick timed kill event in a specific zone.", d = "Head to Niuzao Temple and quickly kill mantid attackers within five seconds. Use high burst damage abilities or group up for faster kills. Timing is critical here, so practice your rotation before attempting the full count.", x = 4 },
        [7289] = { e = 2, s = "g", r = "Short repetitive task with no failure penalty.", d = "Find a serpent hatchling and bounce the ball twenty-five times without dropping it. This requires patience and precise timing, as missing once resets the counter. Stay calm and focus on smooth movements during the sequence.", x = 4 },
        [7290] = { e = 1, s = "s", r = "Instant win upon finishing the race first.", d = "Participate in the Sky Race and aim to cross the finish line before anyone else. Optimize your mount speed and take shortcuts if available. Winning gives you this achievement, so avoid collisions that could slow you down.", x = 4 },
        [7291] = { e = 2, s = "g", r = "Repeatable race requiring buff stacking logic.", d = "Race in the Sky Race while maintaining ten stacks of the Fleet Winds buff. Monitor your buff duration closely to ensure it doesn't expire before crossing the line. Plan your route to maximize speed without losing the buff.", x = 4 },
        [7292] = { e = 1, s = "s", r = "One-time action to harvest the first crop.", d = "Visit a farming area and successfully harvest your first crop to unlock this achievement. Ensure you have the right tools equipped and follow any quest steps if prompted. This marks your entry into Pandaria's farming mechanics.", x = 4 },
        [7293] = { e = 2, s = "g", r = "Linear counter requiring 100 crops over time.", d = "Harvest crops repeatedly until you reach one hundred total. Track your progress carefully as missing the count resets nothing but wastes time. Farming zones are safe for grinding, so focus solely on harvesting without distractions.", x = 4 },
        [7294] = { e = 1, s = "s", r = "Single harvest event for a special crop type.", d = "Start the Tiller questline immediately upon reaching Pandaria to unlock farming. Harvest your first special crop as soon as it spawns, which is a one-time requirement you cannot miss later.", x = 4 },
        [7295] = { e = 3, s = "c", h = { 23952 }, r = "Requires specific weather conditions for each item.", d = "Check the weather forecast daily and harvest all listed vegetables on high-yield days. This is account-wide but requires specific timing; do not wait until the expansion ends to start farming.", x = 4 },
        [7296] = { e = 1, s = "s", r = "Simple retrieval and return of a lost item.", d = "Talk to Old Man Thistle in the Tiller area to receive the treasure location. Return the item promptly, as this quest may despawn if you leave the zone too long.", x = 4 },
        [7297] = { e = 3, s = "c", h = { 30248 }, r = "Requires unlocking multiple distinct hero companions.", d = "Complete the Shado-Pan Garrison quests to unlock each guardian's reputation. Visit them individually at the garrison once unlocked to earn their company.", x = 4 },
        [7298] = { e = 4, s = "g", r = "Extensive daily completion across many different heroes.", d = "Queue for daily quests with each specific Shado-Pan hero and complete 15 runs per person. This is account-wide, so coordinate with friends or do it solo over time.", x = 4 },
        [7299] = { e = 3, s = "c", h = { 27588 }, r = "Requires completing specific sets without companions.", d = "Accept the Omnia Mystics, Wu Kao Assassins, and Blackguard Defenders dailies without bringing a companion. Avoid leaving Townlong Steppes during these runs to satisfy the condition.", x = 4 },
        [7300] = { e = 1, s = "g", r = "Grinding profession skill points is trivial.", d = "Grill food repeatedly in any zone with a cooking trainer or NPC vendor until you gain 75 skill points. This is account-wide, so progress on one character benefits all others.", x = 4 },
        [7301] = { e = 1, s = "g", r = "Grinding profession skill points is trivial.", d = "Cook wok dishes continuously to earn 75 skill points for the Wok method. Use high-level ingredients to speed up leveling if possible.", x = 4 },
        [7302] = { e = 1, s = "g", r = "Grinding profession skill points is trivial.", d = "Brew various potions and drinks to accumulate 75 skill points in the Pot category. Check your profession window to ensure you are gaining points correctly.", x = 4 },
        [7303] = { e = 1, s = "g", r = "Grinding profession skill points is trivial.", d = "Steam vegetables and meats repeatedly until you reach 75 skill points for the Steamer method. This is a grind but straightforward with no special conditions.", x = 4 },
        [7304] = { e = 1, s = "g", r = "Grinding profession skill points is trivial.", d = "Bake breads and pastries to gain 75 skill points in the Oven category. Ensure you are cooking items that count toward this specific sub-tree.", x = 4 },
        [7305] = { e = 1, s = "g", r = "Grinding profession skill points is trivial.", d = "Brew beverages consistently to reach 75 skill points for the Brew method. Like other profession achievements, this is account-wide and can be done on any character.", x = 4 },
        [7306] = { e = 2, s = "c", r = "Requires mastering all six cooking disciplines.", d = "Cook all six Pandaren dishes repeatedly until you hit 75 skill points in each category to unlock the title. This is account-wide and requires no specific group, just consistent cooking.", x = 4 },
        [7307] = { e = 4, s = "c", r = "Strict kill counts make Wu Kao dailies hard.", d = "Complete the full Wu Kao daily set while strictly tracking mantid kills to match the exact required number. Do not kill extra mobs or you will fail the condition for this achievement.", x = 4 },
        [7308] = { e = 5, s = "c", r = "Zero-damage requirement makes Blackguard dailies very hard.", d = "Run each Shado-Pan Blackguard daily quest without taking any damage from monsters, which requires careful positioning and healing. Use a healer or defensive cooldowns to ensure zero damage taken during the entire run.", x = 4 },
        [7309] = { e = 4, s = "c", r = "Requires specific barrel drop and RNG luck.", d = "Place a Highly Explosive Oil Barrel near Gai-Cho combatants and detonate it to kill at least 15 enemies instantly. Positioning is key to maximizing the barrel's blast radius for this objective.", x = 4 },
        [7310] = { e = 2, s = "s", r = "Completing a single quest chain is easy.", d = "Complete the Shado-Pan finale quest \"Surprise Attack!\" as part of the main storyline progression in Pandaria. Ensure you finish all prior daily quests before attempting this final step.", x = 4 },
        [7312] = { e = 4, s = "c", r = "Klaxxi Paragons are rare drops requiring time.", d = "Travel to the Vale of Eternal Blossoms and recover all listed Klaxxi Paragons by defeating their respective bosses. This is account-wide, so coordinate with friends if needed for difficult encounters.", x = 4 },
        [7313] = { e = 3, s = "c", r = "Requires 5 specific buffs on Klaxxi dailies.", d = "Complete five Klaxxi daily quests while maintaining each specific buff listed in the requirements. Manage your cooldowns carefully to keep the active buff up throughout the entire quest chain.", x = 4 },
        [7314] = { e = 2, s = "s", r = "Grow one bug and fight it once.", d = "Grow a Kunchong to full size using food buffs and then release it for its rampage. Feed it appropriately before releasing to ensure it reaches maximum potential.", x = 4 },
        [7315] = { e = 3, s = "c", r = "Complete several Golden Lotus milestones.", d = "Complete all Golden Lotus milestones in the Vale of Eternal Blossoms, including defeating bosses and completing story quests. This is account-wide and requires finishing the main Pandaria storyline first.", x = 4 },
        [7316] = { e = 2, s = "c", r = "Bomb multiple targets on one daily quest.", d = "During the \"Dark Skies\" daily quest, bomb all listed targets including Garalon and various Amber enemies. Use your class's bomb ability or macro to hit every target efficiently.", x = 4 },
        [7317] = { e = 3, s = "c", r = "Defeat various Vale enemies in order.", d = "Defeat all powerful enemies within the Vale of Eternal Blossoms, including bosses like Cracklefang and Vicejaw. Some may require group help, so form a party if needed for tougher encounters.", x = 4 },
        [7318] = { e = 2, s = "s", r = "Find key and open one cache.", d = "Find a Guo-Lai Vault Key from world drops or quests, then use it to open an Ancient Guo-Lai Cache. Keys are rare, so be patient or trade with other players if necessary.", x = 4 },
        [7319] = { e = 4, s = "c", r = "Survive two difficult damage-free challenges.", d = "Complete the Survival Ring challenges in Golden Lotus without taking damage. This is account-wide and requires precise timing to avoid any hits during the specific Flame and Blade trials.", x = 4 },
        [7320] = { e = 3, s = "s", r = "Kill 10 mobs in a short time window.", d = "Defeat 10 Shado-Pan Trainees within a 10-second burst window in the Challenge Ring. Coordinate with your group for maximum damage output to clear this quickly before the timer expires.", x = 4 },
        [7321] = { e = 3, s = "g", r = "Kill 60 hivelings with torch chain reaction.", d = "Kill 60 Krik'thik Hivelings using a single Shado-Pan torch in the Golden Lotus instance. This is account-wide and requires careful positioning to maintain the torch's active state while clearing waves.", x = 4 },
        [7322] = { e = 2, s = "s", r = "Complete a timed obstacle course.", d = "Complete the Serpent Spine roll course in under 70 seconds. Practice your movement speed and timing beforehand, as this is account-wide and any delay will cause you to fail.", x = 4 },
        [7323] = { e = 1, s = "s", r = "Use statue ability to kill one enemy.", d = "Use a Mogu Statue's Crushing Slam ability to kill an opponent in Golden Lotus. Coordinate with your party to lure enemies into the statue's range for this account-wide achievement.", x = 4 },
        [7324] = { e = 4, s = "c", r = "Complete two raids without taking damage.", d = "Complete The Crumbling Hall and The Thunder Below without taking any damage from any source. This is account-wide and requires strict avoidance of all environmental hazards and enemy attacks.", x = 4 },
        [7325] = { e = 3, s = "c", r = "Requires learning profession and finding a student.", d = "Teach an apprentice to become an expert in cooking by completing the training chain. This is account-wide and involves finding a willing player to train alongside you for the required recipes.", x = 4 },
        [7326] = { e = 3, s = "g", r = "Cooking specific recipes repeatedly takes time.", d = "Cook 15 specific Pandaren recipes listed in the achievement description. Start with basic ingredients found in Gadgetzan or Krasarang Wilds and ensure you have the necessary cooking skill to unlock these items.", x = 4 },
        [7327] = { e = 3, s = "g", r = "More cooking required after previous achievement.", d = "Cook 30 of the same Pandaren recipes required for the previous achievement. This is a direct follow-up that requires significantly more food preparation, so plan your gathering and cooking sessions efficiently.", x = 4 },
        [7328] = { e = 3, s = "g", r = "Learning many recipes is a long process.", d = "Learn all 240 available cooking recipes to progress toward the Ironpaw Chef title. You must learn every recipe in the profession tree, which often requires visiting multiple zones or completing specific quests.", x = 4 },
        [7329] = { e = 3, s = "g", r = "Sampling many foods takes significant time.", d = "Travel to Pandaria and sample various foods like Sliced Peaches and Red Bean Buns from NPCs or vendors. This is an account-wide exploration achievement that requires visiting different zones in the region.", x = 4 },
        [7330] = { e = 3, s = "g", r = "Sampling more delicacies requires extensive travel.", d = "Sample a variety of Pandaren delicacies found throughout the zone. Eat these items from vendors or NPCs to track your progress, as this is account-wide and does not require cooking them yourself.", x = 4 },
        [7331] = { e = 4, s = "c", h = { 24094 }, r = "Rare artifacts require specific drops or events.", d = "Start archaeology and dig for the Three Brewfathers artifacts, which drop from specific ruins or vendors. These items are account-wide so play multiple characters to speed up collection. No time gates exist, but rare drops may require extensive digging.", x = 4 },
        [7332] = { e = 4, s = "c", h = { 24108 }, r = "Rare artifacts require specific drops or events.", d = "Focus on finding the Broken Hearted artifacts by excavating relevant zones like Kun-Lai or Pandaria. Since these drop randomly, check vendor lists and dig frequently across different ruins. Account-wide progress means any character's finds count toward your total.", x = 4 },
        [7333] = { e = 4, s = "c", h = { 24102 }, r = "Rare artifacts require specific drops or events.", d = "Locate the Four Celestials artifacts in their respective zones, as each corresponds to a specific dragon soul area. Digging is the primary method, so prioritize high-yield sites and use excavation tools efficiently. All items are account-wide, allowing shared progress across your characters.", x = 4 },
        [7334] = { e = 4, s = "c", h = { 24098 }, r = "Rare artifacts require specific drops or events.", d = "Seek out Instruments of Cruelty artifacts by exploring dungeons or digging in themed ruins. Some pieces may be rare drops, so patience is key when excavating. Remember that all discoveries contribute to your account-wide achievement total.", x = 4 },
        [7335] = { e = 4, s = "c", h = { 24113 }, r = "Rare artifacts require specific drops or events.", d = "Find Symbols of Strength artifacts through archaeology digs in Pandaria and Kun-Lai. These items often appear as uncommon finds, so maximize your excavation efforts in active zones. Progress is tracked account-wide, making it easier to complete with multiple characters.", x = 4 },
        [7336] = { e = 4, s = "c", h = { 24118 }, r = "Rare artifacts require specific drops or events.", d = "Excavate Stone Servants artifacts by focusing on ruins that yield Mogu or ancient stone-themed items. Digging remains the main method, though some pieces may be rare drops requiring persistence. Account-wide tracking ensures all your characters contribute to the final count.", x = 4 },
        [7337] = { e = 4, s = "g", r = "Requires finding and excavating multiple rare artifacts.", d = "Locate Documents of a Dark History artifacts by digging in historical zones like Kun-Lai or Pandaria. These items are uncommon finds, so prioritize high-yield excavation sites for faster completion. Progress is shared across your entire account, simplifying the process.", x = 4 },
        [7338] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Restore five Pandaren Tea Sets by finding broken versions in ruins and using archaeology tools to repair them. This task requires active digging and may involve rare drops depending on zone difficulty. Account-wide progress allows any character to contribute to restoring the sets.", x = 4 },
        [7339] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Find and restore five Pandaren Game Boards through excavation in relevant zones. These artifacts are uncommon finds, so dig frequently across multiple ruins to increase your chances. All restoration efforts count toward your account-wide achievement total.", x = 4 },
        [7340] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Restore five Twin Stein Sets of Brewfather Quan Tou Kuo by locating broken versions in ruins. Use archaeology tools to repair them, focusing on zones with high drop rates for these specific items. Account-wide tracking ensures progress accumulates across all your characters.", x = 4 },
        [7341] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Locate and restore five Walking Canes of Brewfather Ren Yun through diligent excavation. These artifacts are uncommon finds, so prioritize active digging in Pandaria or Kun-Lai zones. All restoration efforts contribute to your account-wide achievement total.", x = 4 },
        [7342] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Find and restore five Empty Kegs of Brewfather Xin Wo Yin by exploring relevant ruins. Use archaeology tools to repair them, focusing on zones with high drop rates for these specific items. Account-wide progress allows any character to help complete the collection.", x = 4 },
        [7343] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Start Archaeology and dig for the Carved Bronze Mirror fragment. Restore five pieces at a local archaeologist to complete this account-wide chain.", x = 4 },
        [7344] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Begin digging for Gold-Inlaid Porcelain Funerary Figurine fragments. You must restore five of these items at an archaeologist to finish.", x = 4 },
        [7345] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Locate Apothecary Tin fragments by excavating ruins. Restore the required five pieces at a profession trainer to claim your points.", x = 4 },
        [7346] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Dig for Pearls of Yu'lon fragments found in specific zones. Restore five pearls at an archaeologist node to complete this collection.", x = 4 },
        [7347] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Excavate Standards of Niuzao fragments from ancient sites. Bring the five restored items to a trainer to finish this account-wide goal.", x = 4 },
        [7348] = { e = 4, s = "g", r = "Requires restoring 5 specific sets via archaeology.", d = "Find Manacles of Rebellion fragments by digging in ruins. Restore five sets at an archaeologist station to unlock these points.", x = 4 },
        [7349] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Search for Cracked Mogu Runestone fragments scattered across the world. Restore five stones at a profession trainer to complete the set.", x = 4 },
        [7350] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Dig up Terracotta Arms fragments from excavation sites. Restore five items at an archaeologist node to finish this collection chain.", x = 4 },
        [7351] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Locate Petrified Bone Whip fragments by exploring ruins. Restore five whips at a trainer to complete this account-wide achievement.", x = 4 },
        [7352] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Excavate Thunder King Insignia fragments from ancient locations. Bring five restored insignias to an archaeologist to finish the task.", x = 4 },
        [7353] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Find Edicts of the Thunder King fragments by digging. Restore five edicts at a profession trainer to claim your points.", x = 4 },
        [7354] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Dig for Iron Amulet fragments found in various zones. Restore five amulets at an archaeologist node to complete this collection.", x = 4 },
        [7355] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Start by excavating the Warlord's Branding Irons from any dig site. You must restore five of these items to complete the achievement.", x = 4 },
        [7356] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Excavate Mogu Coins from dig sites and restore them until you have five total. This is account-wide, so progress carries across characters.", x = 4 },
        [7357] = { e = 2, s = "g", r = "Grinding archaeology sites for 5 items.", d = "Focus on restoring Worn Monument Ledgers found during excavations. You need to collect and restore five of these items.", x = 4 },
        [7358] = { e = 3, s = "g", r = "Grinding archaeology sites for 20 items.", d = "Excavate Pandaren Tea Sets from dig sites and restore twenty of them. This achievement is account-wide and requires no specific group.", x = 4 },
        [7359] = { e = 3, s = "g", r = "Grinding archaeology sites for 20 items.", d = "Look for Pandaren Game Boards in excavation results and restore twenty total. Progress is shared across your entire account.", x = 4 },
        [7360] = { e = 3, s = "g", r = "Grinding archaeology sites for 20 items.", d = "Excavate Twin Stein Sets of Brewfather Quan Tou Kuo and restore twenty units. Ensure you are digging enough sites to find these rare items.", x = 4 },
        [7361] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Restore twenty Walking Canes of Brewfather Ren Yun found during archaeology digs. This is an account-wide achievement that does not require a group.", x = 4 },
        [7362] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Excavate Empty Kegs of Brewfather Xin Wo Yin and restore twenty of them. Keep digging until you have enough to meet the count.", x = 4 },
        [7363] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Find Carved Bronze Mirrors in excavation results and restore twenty total. These items are account-wide and do not require a group.", x = 4 },
        [7364] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Excavate Gold-Inlaid Porcelain Funerary Figurines and restore twenty units. This achievement is account-wide and relies on random dig site drops.", x = 4 },
        [7365] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Restore twenty Apothecary Tins found during archaeology excavations. You can complete this alone as it is an account-wide achievement.", x = 4 },
        [7366] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Excavate Pearls of Yu'lon from dig sites and restore twenty total. This rare drop is account-wide and does not require a group.", x = 4 },
        [7367] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Start by restoring one Standard of Niuzao to unlock the main quest. Farm these items from archaeology dig sites until you have twenty, then restore them all at once.", x = 4 },
        [7368] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Locate a Manacles of Rebellion site and begin restoring fragments immediately after unlocking the quest. Continue digging until you collect twenty pieces for completion.", x = 4 },
        [7369] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Unlock the Cracked Mogu Runestone quest by restoring one fragment first. Farm these from archaeology sites until you have twenty, then restore them to finish the achievement.", x = 4 },
        [7370] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Restore a Terracotta Arm to start the collection process. Keep digging at archaeology sites until you gather twenty arms, then restore them all to complete the goal.", x = 4 },
        [7371] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Begin by restoring one Petrified Bone Whip to unlock the main quest. Farm these items from archaeology dig sites until you have twenty, then restore them all at once.", x = 4 },
        [7372] = { e = 4, s = "g", r = "Grinding archaeology nodes for specific fragments.", d = "Restore a Thunder King Insignia to start collecting. Continue excavating archaeology sites until you have twenty insignias, then restore them all to finish the achievement.", x = 4 },
        [7373] = { e = 4, s = "g", r = "Grinding 20 archaeology fragments is a long process.", d = "Unlock the Edicts of the Thunder King quest by restoring one fragment first. Farm these from archaeology sites until you have twenty, then restore them all to complete the goal.", x = 4 },
        [7374] = { e = 4, s = "g", r = "Grinding 20 archaeology fragments is a long process.", d = "Start by restoring one Iron Amulet to unlock the main quest. Farm these items from archaeology dig sites until you have twenty, then restore them all at once.", x = 4 },
        [7375] = { e = 4, s = "g", r = "Grinding 20 archaeology fragments is a long process.", d = "Restore a Warlord's Branding Iron to begin collecting. Continue digging at archaeology sites until you gather twenty irons, then restore them all to finish the achievement.", x = 4 },
        [7376] = { e = 4, s = "g", r = "Grinding 20 archaeology fragments is a long process.", d = "Unlock the Mogu Coin quest by restoring one fragment first. Farm these from archaeology sites until you have twenty, then restore them all to complete the goal.", x = 4 },
        [7377] = { e = 4, s = "g", r = "Grinding 20 archaeology fragments is a long process.", d = "Start by restoring one Worn Monument Ledger to unlock the main quest. Farm these items from archaeology dig sites until you have twenty, then restore them all at once.", x = 4 },
        [7378] = { e = 5, s = "c", h = { 65891, 65894, 65897 }, r = "Grinding five professions to 75 is a massive task.", d = "Level five primary professions to skill 75 using Pandaria-specific recipes and materials found in the region. Start with gathering professions like Mining or Herbalism to gather resources for crafting professions.", x = 4 },
        [7379] = { e = 5, s = "c", r = "Grinding all professions to 75 is a massive task.", d = "Start by leveling all primary professions to 75 in Pandaria; this requires significant time and material gathering. Ensure you have access to the necessary zones for each profession before beginning.", x = 4 },
        [7380] = { e = 2, s = "s", r = "Leveling two characters is straightforward and easy.", d = "Create one character for each faction and level them to max; this is account-wide so plan your leveling order carefully.", x = 4 },
        [7381] = { e = 1, s = "s", r = "Visiting a shrine is a trivial single step.", d = "Travel to the Jade Forest and visit the Shrine of Fellowship to complete Chen Stormstout's questline.", x = 4 },
        [7382] = { e = 4, s = "c", r = "Leveling two classes to max is a long grind.", d = "Level two different classes to max; this unlocks the next tier in the character collection chain.", x = 4 },
        [7383] = { e = 5, s = "c", r = "Leveling three classes is a very long grind.", d = "Add a third class to your roster and level it to max; ensure you have completed the previous tier first.", x = 4 },
        [7384] = { e = 5, s = "c", r = "Leveling five classes is an extremely long grind.", d = "Expand your roster to five different classes at max level; this is the final step in the character collection chain.", x = 4 },
        [7385] = { e = 4, s = "c", h = { 24273, 24274, 24275 }, r = "Requires completing multiple specific scenario achievements.", d = "Complete all Brewmaster scenario achievements listed in the info field; these are specific to the Pandaria expansion scenarios.", x = 4 },
        [7386] = { e = 3, s = "g", r = "Uncle Bigpocket spawns rarely; requires waiting or farming.", d = "Travel to Kun-Lai Summit and speak with Uncle Bigpocket to obtain the Grand Expedition Yak mount.", x = 4 },
        [7410] = { e = 5, s = "g", r = "Requires completing 5000 daily quests, a massive time investment.", d = "Complete daily quests consistently; this is a long-term goal that requires dedication over many weeks or months.", x = 4 },
        [7411] = { e = 5, s = "g", r = "Requires completing 10000 daily quests, an extreme grind.", d = "Continue completing daily quests until you reach the 10,000 mark; this builds on the previous achievement.", x = 4 },
        [7413] = { e = 2, s = "s", r = "Single boss kill in a classic dungeon; straightforward.", d = "Defeat Flameweaver Koegler in Scarlet Halls; ensure you have the necessary gear and group composition for this classic dungeon boss.", x = 0 },
        [7433] = { e = 1, s = "s", r = "Trivial to level a pet to 3 with any battle pet.", d = "Raise any pet to level 3 in Pet Battles; this is a simple early-game goal that unlocks further pet battle content.", x = 4 },
        [7436] = { e = 4, s = "g", r = "Requires capturing 200 pets; significant time and RNG involved.", d = "Start by battling wild pets in any zone to capture them; this is a grind requiring patience but no specific group. Do not worry about rarity yet, just focus on quantity until you hit 200 captures.", x = 4 },
        [7437] = { e = 2, s = "c", h = { 27332 }, r = "Defeat one champion; most are easy, some slightly harder.", d = "Locate and defeat any single Pandarian champion listed in the info field to complete this step. These enemies spawn randomly across Pandaria, so explore various zones or use a guide to find their current locations.", x = 4 },
        [7438] = { e = 3, s = "c", h = { 27269 }, r = "Defeat one of each champion; Mantids can be tricky.", d = "After completing the previous achievement, you must now defeat at least one of each specific champion type listed. Ensure you have cleared all unique types before moving on to the full collection.", x = 4 },
        [7439] = { e = 5, s = "c", h = { 27408 }, r = "Defeat every champion including rare spawns and heavy RNG.", d = "This final Pandaria champion hunt requires defeating every single variant listed in the info field, which includes rare spawns and specific bosses. Plan your route carefully as some champions are missable or require specific conditions to appear.", x = 4 },
        [7462] = { e = 3, s = "g", r = "Requires finding and capturing at least one rare pet.", d = "Begin hunting for pets marked as 'Rare' rarity in the wild; these drop from specific mobs or events. Keep an eye on your collection log to track progress toward capturing your first rare pet.", x = 4 },
        [7463] = { e = 5, s = "g", r = "Requires capturing 10 rare pets; extremely RNG dependent.", d = "Once you have one rare pet, continue hunting for more until you reach ten total. Rare pets are less common than normal ones, so be prepared for a longer grinding session compared to standard captures.", x = 4 },
        [7464] = { e = 4, s = "g", r = "Requires capturing 50 rare pets; slow RNG grind.", d = "This stage requires capturing fifty rare pets in total, making it a significant time investment. Focus on high-yield zones known for rare pet spawns and consider using efficient battle strategies to speed up the process.", x = 4 },
        [7465] = { e = 2, s = "s", r = "Single uncommon pet capture; trivial once found.", d = "Target pets with 'Uncommon' rarity instead of rare ones; they appear more frequently but still require specific encounters. Check your collection log regularly to ensure you are capturing the correct rarity tier.", x = 4 },
        [7479] = { e = 4, s = "c", h = { 27682 }, r = "Requires Heroic Shado-Pan Monastery; hardest sub-req.", d = "Complete all listed sub-achievements related to the Shado-Pan before claiming this title. Review each requirement carefully as missing even one will prevent you from earning the Shado-Master title and its associated rewards.", x = 4 },
        [7482] = { e = 3, s = "g", r = "Grinding 100 points takes several hours of battles.", d = "Engage in pet battles across various zones to earn achievement points; aim for 100 points total. Focus on battles that offer higher point rewards or are easier to win to maximize your efficiency.", x = 4 },
        [7483] = { e = 3, s = "g", r = "Continues grind to 200 points; moderate time.", d = "Continue battling pets to reach 200 achievement points, building on your previous progress. Maintain a steady pace by selecting challenging but winnable opponents to keep earning points consistently.", x = 4 },
        [7498] = { e = 3, s = "g", r = "Defeating 15 master tamers is a steady grind.", d = "Defeat fifteen master pet tamers located across different continents listed in the info field. These trainers are often found in specific zones and may require higher-level pets or strategic team compositions to overcome.", x = 4 },
        [7499] = { e = 3, s = "g", r = "Defeating 40 master tamers; longer but same task.", d = "Defeat 40 master pet tamers across all zones, starting with Eastern Kingdoms if accessible. This is account-wide and requires no specific group composition beyond having a strong team.", x = 4 },
        [7500] = { e = 4, s = "g", r = "Collecting 250 unique pets is a massive grind.", d = "Collect 250 unique pets by completing the Littlest Pet Shop chain first. Focus on daily quests and world drops to reach this milestone efficiently before moving to higher counts.", x = 4 },
        [7501] = { e = 4, s = "g", r = "Collecting 400 unique pets; very long grind.", d = "Continue collecting pets until you reach 400, following the previous achievement's chain. Be patient as rare pets may take time to drop or require specific scenarios.", x = 4 },
        [7502] = { e = 3, s = "s", r = "Single boss kill; moderate difficulty and time.", d = "Defeat the Ik'thik Colossus boss in Pandaria, which is a single-player encounter. Ensure your character is geared enough for this high-level raid content before attempting it.", x = 4 },
        [7509] = { e = 4, s = "c", h = { 28637 }, r = "Requires specific Saturday events; Theramore's Fall is hardest.", d = "Complete all listed scenarios on a Saturday to earn the Scenaturdist title. Note that some scenarios like Theramore's Fall have multiple difficulty versions requiring separate completion.", x = 4 },
        [7518] = { e = 3, s = "s", r = "Attending festival ceremonies; single event step.", d = "Attend the Wanderer's Festival opening or closing ceremonies for this achievement. Check your calendar for festival dates and ensure you are in the correct zone during the event window.", x = 4 },
        [7520] = { e = 4, s = "c", r = "Requires finding and completing multiple specific quests.", d = "Complete various lore-related quest achievements to unlock the Loremaster title and colors. Review available quests in Pandaria and later expansions to track progress systematically.", x = 4 },
        [7521] = { e = 3, s = "g", r = "Grinding pet battle points takes time but is straightforward.", d = "Earn 400 pet battle achievement points by battling trainers and completing dailies. Start with Ultimate Trainer content if available, as it offers significant point rewards quickly.", x = 4 },
        [7522] = { e = 4, s = "s", r = "Requires completing a full scenario with specific boss kills.", d = "Complete the Crypt of Forgotten Kings scenario by defeating its final boss. This is a self-contained instance that can be done solo or in a small group.", x = 4 },
        [7523] = { e = 4, s = "s", r = "Requires completing a full scenario with specific conditions.", d = "Finish the Theramore's Fall scenario on any difficulty to claim the achievement. Ensure you complete all objectives including the main boss fight within the time limit.", x = 4 },
        [7524] = { e = 4, s = "s", r = "Requires completing a full scenario with specific conditions.", d = "Complete the harder version of Theramore's Fall for its specific achievement requirement. This may require better gear and coordination compared to the easier variant.", x = 4 },
        [7525] = { e = 3, s = "c", r = "Requires defeating multiple pet tamers in one zone.", d = "Defeat all Pet Tamers in Cataclysm, including Brok, Bordin Steadyfist, Goz Banefury, and Obalis. These encounters are located in specific zones within the expansion area.", x = 4 },
        [7526] = { e = 4, s = "s", r = "Requires perfect playthrough of a specific scenario boss fight.", d = "Start the Theramore scenario and focus on dodging Gash'nul's totem destruction mechanics while dealing damage. Avoid standing near his totems as they will instantly fail the achievement if destroyed.", x = 4 },
        [7527] = { e = 4, s = "s", r = "Requires perfect playthrough of a specific scenario boss fight.", d = "Begin the Theramore scenario immediately and ensure your party stays behind Gatecrusher's ram and stone-thrower attacks. Do not let anyone take damage from these specific abilities or the achievement will reset.", x = 4 },
        [7529] = { e = 4, s = "s", r = "Requires perfect playthrough of a specific scenario boss fight.", d = "Enter the Theramore high-level scenario and prioritize keeping Baldruc's totems intact while focusing fire on him. Watch for his totem summoning mechanics and avoid standing near them during the fight.", x = 4 },
        [7530] = { e = 4, s = "s", r = "Requires perfect playthrough of a specific scenario boss fight.", d = "Start the Theramore high-level scenario and position your group to avoid Big Bessa's ram and cannon shots. Ensure no player takes damage from these abilities as they will prevent completion.", x = 4 },
        [7533] = { e = 3, s = "s", r = "Requires completing a specific legendary quest chapter.", d = "Complete the Breath of the Black Prince quest within the Legendary 5.0 Chapter I storyline to unlock this legacy achievement. This is a one-time requirement that cannot be missed once the chapter concludes.", x = 4 },
        [7534] = { e = 3, s = "s", r = "Requires completing a specific legendary quest chapter.", d = "Join Wrathion's Alliance trials after landing on the beach in the specified scenario. Complete all required objectives quickly as this account-wide achievement may have time limits or specific sequence requirements.", x = 4 },
        [7535] = { e = 4, s = "s", r = "Requires completing a specific high-level legendary quest chain.", d = "Finish the Heart of the Thunder King quest during Legendary 5.0 Chapter III to unlock this legacy achievement. Ensure you deliver the heart correctly as missing this step will make the achievement unobtainable.", x = 4 },
        [7536] = { e = 4, s = "s", r = "Requires completing a specific high-level legendary quest chain.", d = "Accompany Wrathion on his journey to collect blessings from the four August Celestials in Legendary 5.0 Chapter IV. Complete the Cloak of Virtue quest at the end to finalize this account-wide legacy achievement.", x = 4 },
        [7601] = { e = 2, s = "g", r = "Visit multiple locations; effort decreases as each is visited.", d = "Visit every Candy Bucket location listed in Pandaria zones during Hallow's End event. This account-wide achievement requires checking all specific coordinates, so make a thorough map run while the event is active.", x = 4 },
        [7602] = { e = 2, s = "g", r = "Visit multiple locations; effort decreases as each is visited.", d = "Travel to all Candy Bucket locations across Pandaria zones during Hallow's End for this account-wide achievement. Ensure you visit every single location listed in the info field before the event ends.", x = 4 },
        [7611] = { e = 3, s = "g", r = "Catch all native fish types; steady progress reduces remaining work.", d = "Fish in all Pandaria zones to catch each native fish type listed in the achievement requirements. This account-wide achievement requires catching specific rare fish, so check your fishing logs regularly.", x = 4 },
        [7612] = { e = 4, s = "g", r = "Restore and display many artifacts; requires archaeology digging.", d = "Restore and display all pristine Pandaren and Mogu artifacts in your Archaeology collection for this account-wide achievement. Complete every artifact discovery and ensure they are displayed before moving on to other content.", x = 4 },
        [7614] = { e = 3, s = "g", r = "Complete multiple daily quests at a specific location.", d = "Start by completing the Angler's Wharf dailies daily to unlock all required fishing quests. Do not miss any day as this is account-wide and time-gated by the weekly reset.", x = 4 },
        [7860] = { e = 5, s = "g", r = "Requires obtaining 150 mounts; significant grind or RNG involved.", d = "Grind for mounts across all zones until you hit 150 total; ensure they are usable by a single character. This is account-wide so coordinate with friends to speed up progress.", x = 4 },
        [7862] = { e = 5, s = "g", r = "Requires obtaining 150 mounts; significant grind or RNG involved.", d = "This is the Horde version of the same mount collection goal as id 7860. Simply obtain 150 mounts usable by a single character while playing on your Horde account.", x = 4 },
        [7908] = { e = 3, s = "s", r = "Complete a specific quest chain involving pet battles.", d = "Complete the Grand Master Aki questline in Pet Battles to unlock this achievement. Ensure you finish all prior steps in the Aki storyline before attempting the final quest.", x = 4 },
        [7928] = { e = 4, s = "c", h = { 31151, 31166 }, r = "Alliance campaign has multiple steps; some are harder than others.", d = "Queue for Operation: Shieldwall campaigns as an Alliance player and complete every listed storyline quest. Do not skip any faction-specific quests even if they seem optional.", x = 4 },
        [7929] = { e = 4, s = "c", h = { 31178, 31180 }, r = "Horde campaign has multiple steps; some are harder than others.", d = "Queue for Dominance Offensive campaigns as a Horde player and finish all associated storylines. Check your quest log frequently to ensure no Alliance-only or missed objectives remain.", x = 4 },
        [7932] = { e = 4, s = "c", h = { 31183, 31186, 31189 }, r = "Requires finding and defeating three specific champions in Krasarang Wilds.", d = "Travel to Krasarang Wilds and defeat the three opposing faction champions located in that zone. You must kill all three specific champions listed in the achievement requirements.", x = 4 },
        [7933] = { e = 4, s = "s", r = "Needs a specific raid encounter mechanic on Normal or Heroic difficulty.", d = "Run through Mogu'shan Vaults on Normal or Heroic difficulty and fly through the discs above the Engine of Nalak'sha. Ensure you have a flying mount ready before entering the raid instance.", x = 4 },
        [7934] = { e = 5, s = "g", r = "Requires collecting all classic raid pets, many of which are rare drops.", d = "Collect all battle pets from classic raids like Molten Core or Blackwing Lair. Some may be rare drops, so run these specific raids repeatedly until every pet is obtained.", x = 4 },
        [7936] = { e = 2, s = "s", r = "Simple quest completion to unlock a daily pet battle quest.", d = "Complete the Pandaren Spirit Tamer questline in Pet Battles to unlock daily quests. Finish all prerequisite steps before claiming the final reward for this achievement.", x = 4 },
        [7937] = { e = 1, s = "s", r = "Winning one brawl during the campaign is trivial once started.", d = "Participate in any brawl during the Pandaria campaign era to win and claim this legacy achievement. No specific rank is needed, just a single victory counts.", x = 4 },
        [7939] = { e = 4, s = "g", r = "Requires reaching Rank 7 in Brawl'gar Arena, needing significant wins.", d = "Climb the ranks in Brawl'gar Arena until you reach Rank 7 during the Pandaria campaign. Focus on winning brawls consistently to advance your arena rating quickly.", x = 4 },
        [7940] = { e = 4, s = "g", r = "Requires reaching Rank 7 in Bizmo's Brawlpub, needing significant wins.", d = "Focus on completing Brawlpub brawls to gain ranks quickly. Do not stop at Rank 6; you must reach Rank 7 before the season ends.", x = 4 },
        [7941] = { e = 4, s = "g", r = "Requires reaching Rank 8 in Bizmo's Brawlpub, slightly harder than Rank 7.", d = "Continue fighting in Brawlpub until you hit Rank 8. This unlocks the Brawler title and completes the Pandaria season chain.", x = 4 },
        [7942] = { e = 4, s = "g", r = "Requires reaching Rank 8 in Brawl'gar Arena, slightly harder than Rank 7.", d = "Switch to Brawl'gar Arena in Orgrimmar and repeat the process to reach Rank 8 there. Ensure you are active during the Draenor campaign.", x = 4 },
        [7943] = { e = 1, s = "s", r = "Just cheering after a win is trivial once the brawl happens.", d = "Watch a teammate win a brawl while standing near them to trigger the cheer interaction. This is often missed if you leave too early.", x = 4 },
        [7944] = { e = 3, s = "s", r = "Requires specific item usage on an NPC during the Draenor campaign.", d = "Wait for spectators to become angry after losing, then use an Expired Blackout Brew on them. Timing is key as they reset quickly.", x = 4 },
        [7945] = { e = 4, s = "g", r = "Winning ten brawls with a specific buff requires significant arena time.", d = "Accumulate ten stacks of You Stink! by insulting opponents before winning the brawl. Do not win without the full stack count.", x = 4 },
        [7946] = { e = 5, s = "g", r = "Requires defeating multiple rare brawl bosses.", d = "This achievement tracks rare brawl bosses; ensure you defeat every specific boss listed in the category. Some may be missable if seasons end.", x = 4 },
        [7947] = { e = 2, s = "s", r = "Simple invitation event with no grind.", d = "Travel to Deeprun Tram and accept an invitation from Bizmo to start brawling. This is the mandatory first step for both seasons.", x = 4 },
        [7948] = { e = 2, s = "s", r = "Simple invitation event with no grind.", d = "Go to The Valley of Honor in Orgrimmar and accept an invitation from Brawl'gar Arena. You must be invited to trigger this.", x = 4 },
        [7949] = { e = 1, s = "s", r = "Single portal interaction during campaign.", d = "Speak to Willard Bubbles in Orgrimmar and take his portal immediately. Do not ignore the NPC or you may miss the interaction window.", x = 4 },
        [7950] = { e = 1, s = "s", r = "Single portal interaction during campaign.", d = "Find Zippi Gallox in Stormwind and accept her portal offer. This is a quick task but requires locating the specific NPC first.", x = 4 },
        [7984] = { e = 3, s = "g", r = "Kill 3 specific targets in a scenario.", d = "Play the Dagger in the Dark scenario and specifically target the Darkhatched Lizard-Lord's reinforcements with Water Jets. Kill three of them to complete it.", x = 4 },
        [7986] = { e = 4, s = "s", r = "Strict mechanic on a single boss fight.", d = "Start the Vol'jin scenario and immediately avoid standing in Healing Wards while fighting Rak'gor. Coordinate with your group to ensure no one enters these zones during the entire encounter.", x = 4 },
        [7987] = { e = 3, s = "g", r = "Destroy multiple eggs before timer ends.", d = "Prioritize destroying all eggs before Broodmaster Noshi drops to 20% health. Focus fire on egg clusters rather than healing or damage-over-time effects to save time.", x = 4 },
        [7988] = { e = 2, s = "s", r = "Complete a single scenario instance.", d = "Complete the full A Little Patience scenario objectives without interruption. Ensure you finish all construction phases and final boss encounters to claim this title.", x = 4 },
        [7989] = { e = 1, s = "s", r = "Single step within a scenario fight.", d = "Participate in building Jinyu defenses during the A Little Patience scenario. Stay near the specific construction points assigned to your faction to trigger the achievement.", x = 4 },
        [7990] = { e = 1, s = "s", r = "Single step within a scenario fight.", d = "Help construct Dwarf defenses while playing through the A Little Patience scenario. Position yourself correctly at the designated build sites for the Dwarf faction.", x = 4 },
        [7991] = { e = 1, s = "s", r = "Single step within a scenario fight.", d = "Assist in building Gnome defenses during the A Little Patience scenario. Locate and interact with the specific Gnome construction zones to complete this task.", x = 4 },
        [7992] = { e = 1, s = "s", r = "Simple scenario objective requiring minimal effort.", d = "Aid Night Elf defense construction within the A Little Patience scenario. Find the Night Elf build points and remain there until the structure is finished.", x = 4 },
        [7993] = { e = 1, s = "s", r = "Simple scenario objective requiring minimal effort.", d = "Work with Master Brownstone to build Pandaren defenses in the A Little Patience scenario. Ensure you complete the specific Pandaren construction objectives before moving on.", x = 4 },
        [7994] = { e = 2, s = "g", r = "Collecting one treasure takes a short exploration trip.", d = "Search Pandaria for any single Treasure of Pandaria to start this chain. These items are account-wide, so one character can unlock them for everyone.", x = 4 },
        [7995] = { e = 3, s = "g", r = "Requires finding five treasures across Pandaria zones.", d = "Collect five Treasures of Pandaria by exploring the zone thoroughly. Since these are account-wide, you only need to find five total across all characters.", x = 4 },
        [7996] = { e = 4, s = "g", r = "Finding ten treasures requires significant exploration time.", d = "Gather ten Treasures of Pandaria to unlock the next tier. Continue exploring Pandaria until your account reaches this collection threshold.", x = 4 },
        [7997] = { e = 5, s = "g", r = "Collecting all 18 treasures is a long account-wide grind.", d = "Find all eighteen Treasures of Pandaria to complete the set. This requires extensive exploration across the entire zone and is account-wide.", x = 4 },
        [8008] = { e = 4, s = "s", r = "Requires completing a specific legendary chapter quest.", d = "Complete the Chapter II Horde questline after landing on the beach to prove superiority to Wrathion. Ensure you finish 'The Soul of the Horde' as this is the specific requirement listed in the info field.", x = 4 },
        [8009] = { e = 3, s = "s", r = "Completing the full scenario takes moderate time.", d = "Start the Dagger in the Dark scenario and escort Voljin through the encounter without failing the objective. This achievement unlocks only after successfully completing the entire scenario sequence.", x = 4 },
        [8010] = { e = 2, s = "s", r = "Completing the scenario fort objective is straightforward.", d = "Complete the Lion's Landing scenario by reaching the final victory condition. Note that this is a group activity requiring coordination with other players to finish the fort defense.", x = 4 },
        [8011] = { e = 3, s = "s", r = "Requires careful play to keep all NPCs alive.", d = "Play defensively in Lion's Landing to ensure all five non-player characters survive the encounter. Avoid taking unnecessary damage or letting enemies kill your allies during the scenario.", x = 4 },
        [8012] = { e = 4, s = "c", r = "Must use every single item in the scenario.", d = "Use every available weapon and power-up item during the Lion's Landing scenario to unlock this account-wide achievement. Collect items like the Lever-Action Boomstick and various power-ups while playing through the map.", x = 4 },
        [8013] = { e = 3, s = "s", r = "Completing the domination point scenario takes moderate time.", d = "Complete the Domination Point scenario by securing the final objective against enemy forces. Coordinate with your group to hold the point until the scenario timer runs out or victory is achieved.", x = 4 },
        [8014] = { e = 3, s = "s", r = "Survive a timed scenario with multiple NPCs.", d = "Protect all five non-player characters during the Domination Point scenario to earn this survival achievement. Focus on crowd control and healing to prevent allies from dying before the end.", x = 4 },
        [8015] = { e = 3, s = "g", r = "Collect specific items during a scenario.", d = "Utilize every weapon and power-up in the Domination Point scenario, including items like the Reaver Bomb and Rocket Launcher. Make sure to pick up and use each unique item listed in the requirements.", x = 4 },
        [8016] = { e = 4, s = "s", r = "Defeat a raid boss in a specific scenario.", d = "Defeat Commander Tel'vrak during the Assault on Zan'vess scenario to complete this specific encounter achievement. Focus your damage output on the commander while managing the surrounding threats.", x = 4 },
        [8017] = { e = 5, s = "s", r = "Strict no-kill requirement on a raid boss.", d = "Complete Assault on Zan'vess without killing any Zan'thik Swarmers to earn the For the Swarm achievement. Use crowd control abilities and kiting tactics to avoid accidentally hitting these specific enemies.", x = 4 },
        [8020] = { e = 3, s = "s", r = "Win a single brawl encounter.", d = "Win a brawl during the Pandaria campaign to unlock this legacy achievement. Participate in any available brawl event and secure a victory against the opposing team.", x = 4 },
        [8022] = { e = 4, s = "c", r = "Defeat multiple rare brawl bosses.", d = "Defeat specific rare brawl bosses that appear during the Pandaria campaign to complete this set of achievements. Monitor the brawl events for these unique encounters and prepare appropriate strategies.", x = 4 },
        [8023] = { e = 5, s = "c", r = "Complete multiple difficult reputation achievements.", d = "Complete the specific Klaxxi Paragon achievements listed in your info to earn this title. Ensure you have finished all prerequisite tasks before claiming the reward, as it is account-wide.", x = 4 },
        [8028] = { e = 4, s = "s", r = "Defeat a raid boss on the Isle of Thunder.", d = "Defeat Nalak, the Storm Lord on the Isle of Thunder raid instance. This requires a full group and sufficient gear for the boss mechanics.", x = 4 },
        [8030] = { e = 5, s = "g", r = "Grind massive amount of Valor points.", d = "Start the Test of Valor quest chain and accumulate 30,000 Valor Points from PvP activities. Note that this legacy achievement may be time-gated or require specific seasonal content.", x = 4 },
        [8031] = { e = 5, s = "g", r = "Grind massive amount of Valor points.", d = "Start the Test of Valor quest chain for your Horde character and earn 30,000 Valor Points. Follow the same steps as the Alliance version but ensure you are on the correct faction.", x = 4 },
        [8037] = { e = 4, s = "s", r = "Defeat raid boss without taking harmful mutations.", d = "Defeat Primordius in Throne of Thunder without anyone taking a harmful mutation debuff. Coordinate with your group to avoid the mutation mechanic during the fight.", x = 4 },
        [8038] = { e = 4, s = "s", r = "Defeat raid boss without killing specific mobs.", d = "Defeat Horridon in Throne of Thunder while preventing any Zandalari Dinomancers from being killed. Use ranged attacks or kiting strategies to protect these NPCs.", x = 4 },
        [8042] = { e = 1, s = "s", r = "Simple world event interaction.", d = "Locate and desecrate the Horde bonfire in Pandaria during the Midsummer event. This is a world event, so check your calendar for availability.", x = 4 },
        [8043] = { e = 1, s = "s", r = "Simple world event interaction.", d = "Find and desecrate the Alliance bonfire in Pandaria during the Midsummer event. Coordinate with friends or wait for other players to complete their side first.", x = 4 },
        [8044] = { e = 2, s = "c", r = "Visit zones; no rare spawns or RNG.", d = "Honor the flames of Pandaria by visiting all listed zones, including both factions' areas. This is account-wide, so one character can unlock it for everyone.", x = 1 },
        [8045] = { e = 2, s = "c", r = "Visit zones; no rare spawns or RNG.", d = "Honor the flames of Pandaria across all specified zones for your specific faction. Visit each zone to complete the requirement and claim the title.", x = 1 },
        [8049] = { e = 3, s = "c", r = "Collect lore objects across Pandaria.", d = "Discover every lore object related to the Zandalari prophecy scattered throughout Pandaria. Explore all regions thoroughly, as these items are often hidden in hard-to-reach places.", x = 4 },
        [8050] = { e = 3, s = "c", r = "Collect lore objects across Pandaria.", d = "Find all lore objects concerning Lei-Shen and the Thunder King across Pandaria. Check both faction zones and ensure you have interacted with every relevant object.", x = 4 },
        [8051] = { e = 3, s = "c", r = "Collect lore objects across Pandaria.", d = "Read every Mogu Origins lore object in Pandaria to unlock this achievement. Ensure you have completed the main story quests first, as some objects are only accessible after progressing through the zone.", x = 4 },
        [8052] = { e = 4, s = "c", h = { 31793, 31794, 31795 }, r = "Requires completing multiple BG titles.", d = "Complete all Master achievements for Battlegrounds like Gilneas and Isle of Conquest to earn the Khan title. This requires high-level PvP skill and is account-wide once finished.", x = 4 },
        [8055] = { e = 4, s = "c", h = { 31799, 31800, 31801 }, r = "Requires completing multiple BG titles.", d = "Finish the same battleground Master achievements listed in the previous entry to secure your title. Focus on mastering mechanics for each specific battleground to ensure success.", x = 4 },
        [8056] = { e = 3, s = "s", r = "Single heroic raid boss kill.", d = "Defeat Jin'rokh the Breaker on Heroic difficulty in Throne of Thunder. Coordinate with your raid group carefully, as this boss requires precise execution and good gear.", x = 4 },
        [8057] = { e = 3, s = "s", r = "Single heroic raid boss kill.", d = "Kill Horridon on Heroic difficulty within Throne of Thunder. This encounter is challenging and demands strong DPS output and coordinated mechanics from your entire raid team.", x = 4 },
        [8058] = { e = 3, s = "s", r = "Single heroic raid boss kill.", d = "Defeat the Council of Elders on Heroic difficulty in Throne of Thunder. Prepare for a multi-phase fight that tests your group's ability to handle complex mechanics quickly.", x = 4 },
        [8059] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Bring your raid to Tortos on Heroic difficulty in Throne of Thunder. This boss fight is intense and requires careful positioning and damage management throughout the encounter.", x = 4 },
        [8060] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Conquer Megaera on Heroic difficulty in Throne of Thunder. Ensure your raid has sufficient healing and crowd control capabilities to survive her aggressive abilities.", x = 4 },
        [8061] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Defeat Ji-Kun on Heroic difficulty in Throne of Thunder. This boss is a major challenge that requires perfect execution of mechanics and strong raid coordination.", x = 4 },
        [8062] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Kill Durumu the Forgotten on Heroic difficulty in Throne of Thunder. Focus on managing his adds and maintaining high damage output to defeat him efficiently.", x = 4 },
        [8063] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Defeat Primordius on Heroic difficulty in Throne of Thunder. This encounter is notorious for its mechanics, so practice with your raid before attempting it seriously.", x = 4 },
        [8064] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Bring your raid to the Dark Animus on Heroic difficulty in Throne of Thunder. Ensure your group is well-gearred and coordinated to handle this final boss effectively.", x = 4 },
        [8065] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Queue for Heroic Iron Qon in Throne of Thunder. Ensure your group is prepared for the raid's mechanics as this is a timed achievement if you miss the weekly reset.", x = 4 },
        [8066] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Defeat the Twin Empyreans on Heroic difficulty within Throne of Thunder. This boss requires specific mechanics management and should be done with a coordinated group to avoid wipes.", x = 4 },
        [8067] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Complete Lei Shen on Heroic difficulty in Throne of Thunder to earn the Storm's End title. Coordinate your team carefully as this boss has complex mechanics that require precise execution.", x = 4 },
        [8068] = { e = 4, s = "s", r = "Heroic raid boss; requires group and gear.", d = "Defeat Ra-den in Throne of Thunder on either Normal or Heroic difficulty. Focus on managing his adds and avoiding the dangerous mechanics to secure the achievement quickly.", x = 4 },
        [8069] = { e = 4, s = "c", h = { 32274, 32275, 32276 }, r = "Account-wide Heroic raid bosses; requires group.", d = "Clear all bosses at the entrance to Throne of Thunder for the Last Stand of the Zandalari. This includes Jin'rokh, Horridon, and the Council of Elders, so ensure you have a full group ready.", x = 4 },
        [8070] = { e = 4, s = "c", h = { 32278, 32279, 32280 }, r = "Account-wide Heroic raid bosses; requires group.", d = "Defeat Tortos, Megaera, and Ji-Kun in the Forgotten Depths beneath Throne of Thunder. These bosses are account-wide, so coordinate with friends or guildmates to complete them efficiently.", x = 4 },
        [8071] = { e = 4, s = "c", r = "Full raid clear required.", d = "Clear Durumu, Primordius, and Dark Animus in the Halls of Flesh-Shaping beneath Throne of Thunder. Watch out for their unique mechanics as they can be challenging without proper preparation.", x = 4 },
        [8072] = { e = 4, s = "c", r = "Full raid clear required.", d = "Defeat Iron Qon, Twin Empyreans, and Lei Shen in the Pinnacle of Storms within Throne of Thunder. This is a multi-boss achievement, so plan your run to tackle all three efficiently.", x = 4 },
        [8073] = { e = 5, s = "c", h = { 31809 }, r = "Strict mechanics on high-difficulty raid.", d = "Complete the Cage Match by defeating the Council of Elders without any creature leaving the center rings. Communicate clearly with your group to keep pets and summons contained throughout the fight.", x = 4 },
        [8077] = { e = 4, s = "c", r = "Specific mechanic in high-difficulty raid.", d = "Kick a Whirl Turtle shell through five or more other turtles while defeating Tortos in Throne of Thunder. Time your kicks carefully during the boss mechanics to maximize shell penetration.", x = 4 },
        [8078] = { e = 3, s = "g", r = "Killing mobs in a zone.", d = "Kill ten Zandalari Warscouts and five Zandalari Warbringers for the Zul'Again achievement. This is account-wide, so you can complete it while leveling or during any Pandaria content.", x = 4 },
        [8080] = { e = 1, s = "s", r = "Simple quest completion.", d = "Complete the Beasts of Fable quest to earn the Fabled Pandaren Tamer title. This unlocks a daily pet battle quest, so ensure you have the necessary pets and gear before starting.", x = 4 },
        [8081] = { e = 5, s = "c", r = "Requires killing all unique spawns.", d = "Farm the Dark Animus chamber repeatedly on Normal or Heroic until you have killed all 24 unique Dark Ritualists. Since this requires separate visits, ensure you clear the entire encounter each time to avoid missing any specific boss.", x = 4 },
        [8082] = { e = 5, s = "c", r = "Strict mechanic on high-difficulty raid.", d = "Defeat Megaera on Normal or Heroic while strictly avoiding her head-cutting mechanics for all three elemental types. Coordinate with your group to focus damage away from the heads until she is defeated.", x = 4 },
        [8086] = { e = 4, s = "c", r = "Specific sequence in high-difficulty raid.", d = "Start by killing Lu'lin before Suen drops below 30% health, then immediately switch focus to defeating Suen. This sequence must happen within a single visit to the Dark Animus chamber.", x = 4 },
        [8087] = { e = 5, s = "c", r = "Strict avoidance mechanics in raid.", d = "Survive Iron Qon without taking damage from his five specific abilities listed in the achievement info. Use proper positioning and cooldowns to dodge Burning Cinders, Frozen Blood, Storm Cloud, Rushing Winds, and Frozen Solid.", x = 4 },
        [8090] = { e = 4, s = "c", r = "Specific sequence in high-difficulty raid.", d = "Defeat Lei Shen on Normal or Heroic only after disabling all four Conduits first. You must interact with each conduit to disable it before engaging the final boss phase.", x = 4 },
        [8093] = { e = 2, s = "g", r = "Earning currency over time.", d = "Earn 25,000 Conquest Points during Season 13 by participating in PvP activities and completing seasonal objectives. This is account-wide and requires active participation in the specific season timeframe.", x = 4 },
        [8094] = { e = 3, s = "s", r = "Requires specific mechanics during a raid encounter.", d = "Fight Jin'rokh the Breaker on Normal or Heroic and aim to collide two Focused Lightning Orbs simultaneously. Position yourself carefully to guide the orbs into each other without destroying them prematurely.", x = 4 },
        [8097] = { e = 3, s = "s", r = "Requires careful play in a single raid fight.", d = "Defeat Ji-Kun on Normal or Heroic while keeping the Golden Egg intact throughout the entire fight. Avoid any mechanics that could damage the egg, as breaking it will fail the achievement.", x = 4 },
        [8098] = { e = 3, s = "s", r = "Requires specific mechanics during a raid encounter.", d = "Face Durumu the Forgotten on Normal or Heroic and reveal all three colored Fog Beasts (Orange, Purple, Green). Use specific abilities or interactions to expose each beast before defeating the boss.", x = 4 },
        [8099] = { e = 4, s = "c", h = { 32071, 32074, 32077 }, r = "Multiple distinct objectives across different zones.", d = "Complete the entire Isle of Thunder storyline by finishing every quest listed in the achievement info. This includes all major story nodes and is account-wide, so ensure no quests are missed.", x = 4 },
        [8100] = { e = 3, s = "c", h = { 31952 }, r = "Requires defeating multiple specific summonable bosses.", d = "Defeat at least one summonable boss from the Isle of Thunder list to start this chain. You can choose any available boss, but note that defeating all of them is required for the next achievement.", x = 4 },
        [8101] = { e = 4, s = "c", h = { 31954, 31955, 31956 }, r = "Requires defeating all remaining summonable bosses.", d = "After completing Pay to Slay, defeat every remaining summonable boss listed in the Isle of Thunder section. This requires clearing multiple encounters and is account-wide, so plan your rotations efficiently.", x = 4 },
        [8103] = { e = 4, s = "g", r = "Requires finding and killing many rare mobs.", d = "Farm the Isle of Thunder rare mobs like Haywire Sunreaver Construct and Goda. Since this is account-wide, any character can contribute to progress. Ensure you are in the correct zone as these specific rares only spawn there.", x = 4 },
        [8104] = { e = 2, s = "s", r = "Simple objective to find a specific item.", d = "Locate and loot a Trove of the Thunder King on the Isle of Thunder. This is a rare drop, so be patient or check if other players have already looted one nearby to trigger the quest.", x = 4 },
        [8105] = { e = 3, s = "s", r = "Requires completing a quest within a time limit.", d = "Accept The Crumbled Chamberlain and immediately rush to complete it within ten minutes. Do not engage in any combat or exploration until the timer starts, as missing this window makes the achievement missable.", x = 4 },
        [8106] = { e = 4, s = "c", h = { 32252, 32251, 32250 }, r = "Requires multiple difficult tasks in treasure runs.", d = "Enter a Trove of the Thunder King to access the Hall of the Thunder King goals. You must loot chests and slay God-Hulk Gulkan in a single run, so coordinate with your group for efficiency.", x = 4 },
        [8107] = { e = 4, s = "g", r = "Requires killing a large number of mobs quickly.", d = "Find Ihgaluk Roaches near the entrance to the Court of Bones and kill two hundred within one minute. This requires high damage output or a fast group to clear the area quickly before the timer expires.", x = 4 },
        [8108] = { e = 2, s = "c", h = { 31984 }, r = "Most forms are easy; Sacrificed Kroshik is hard.", d = "Use /bow while Kroshik transforms into his various forms like Baby Kroshik or Sacrificed Kroshik. You must bow to each specific form listed to complete the requirement for this account-wide achievement.", x = 4 },
        [8109] = { e = 3, s = "c", r = "Summon and defeat one of three specific mogu bosses.", d = "Summon and defeat ancient mogu such as Haqin of the Hundred Spears in the Court of Bones. This is part of a chain, so finish this before moving on to the next related quest.", x = 4 },
        [8110] = { e = 4, s = "c", h = { 31990, 31991, 31992 }, r = "Defeat all three mogu bosses; requires prior completion of 8109.", d = "Complete the previous Mogu Below-gu quest first, then summon and defeat all listed ancient mogu. Ensure you have cleared the earlier requirement as this achievement explicitly requires it.", x = 4 },
        [8111] = { e = 3, s = "s", r = "Requires specific potion and buff active simultaneously.", d = "Consume a Zandalari Potion while standing near a Loa to gain its buff simultaneously. Time your potion usage carefully so both effects are active at the same moment for credit.", x = 4 },
        [8112] = { e = 4, s = "g", r = "Rare blue Hatchling Skyscreamer requires significant RNG luck.", d = "Wait patiently for the rare blue Hatchling Skyscreamer to spawn in the Isle of Thunder. Once it appears, use a taunt or crowd control ability to shoo it away without killing it.", x = 4 },
        [8114] = { e = 3, s = "s", r = "Survive 90 seconds on pillars; manageable but requires focus.", d = "Jump onto the pillars in the Swollen Vault and survive for ninety seconds. Avoid falling off by moving carefully between platforms while dodging any environmental hazards or enemies.", x = 4 },
        [8115] = { e = 4, s = "g", r = "Requires defeating Metal Lord Mono-Han with specific mechanic stacks.", d = "Defeat Metal Lord Mono-Han while maintaining ten stacks of Power Surge. Use abilities that grant this buff and manage your cooldowns to keep the stacks up throughout the fight.", x = 4 },
        [8116] = { e = 4, s = "c", r = "Slay boss without killing adds; requires precise combat control.", d = "Start the Isle of Thunder questline and focus on slaying Fleshcrafter Hoku while avoiding damage to Possessed Blood. This is a timed achievement, so complete it before the event timer expires or you will miss it permanently.", x = 4 },
        [8117] = { e = 2, s = "s", r = "Use ward to finish opponent; straightforward mechanic.", d = "Use perimeter wards dropped by Sunreaver or Kirin Tor NPCs to finish off enemies during Isle of Thunder events. Ensure you have access to these faction-specific quests early in the expansion to secure this objective.", x = 4 },
        [8118] = { e = 3, s = "g", r = "Knock beastcaller off mount; requires patience and timing.", d = "Locate Zandalari Beastcallers on their mounts and use high mobility skills to knock them down without killing them. This requires precise timing, so be ready to react quickly when they land or take damage.", x = 4 },
        [8119] = { e = 4, s = "c", h = { 32001, 32002 }, r = "Kill Guardian Tak'u with all blessings and no blessings active.", d = "Kill Guardian Tak'u twice: once with all four blessings active and again with none active. Coordinate with your group to manage blessing status carefully between attempts to avoid wasting time.", x = 4 },
        [8120] = { e = 3, s = "s", r = "Destroy vase using specific charge attack; single event.", d = "Equip the Loa-Infused Bloodhorn and use its charge attack to destroy the Priceless Zandalari Vase during Isle of Thunder events. Time your attacks precisely to hit the vase before it despawns or moves out of range.", x = 4 },
        [8121] = { e = 5, s = "c", h = { 32006, 32007, 32021 }, r = "Complete entire Isle of Thunder questline; massive time commitment.", d = "Complete every listed Isle of Thunder achievement first, as this title requires all sub-achievements including timed ones like You Made Me Bleed My Own Blood. Prioritize account-wide tasks early since some cannot be completed after the expansion's time gate closes.", x = 4 },
        [8123] = { e = 4, s = "s", r = "Requires defeating a raid boss on Isle of Giants.", d = "Defeat Oondasta on the Isle of Giants by completing the relevant dungeon or world boss event. Check current patch requirements, as this may require specific keys or group coordination depending on your server state.", x = 4 },
        [8124] = { e = 5, s = "c", h = { 32091, 32092, 32095 }, r = "Needs Heroic Throne of Thunder bosses; high RNG.", d = "Complete all Heroic Throne of Thunder raid achievements listed, including killing every boss and collecting rare drops like Lightning Overload. This is a massive undertaking requiring multiple raids, so plan your progression carefully to avoid missing any sub-objectives.", x = 4 },
        [8205] = { e = 4, s = "g", r = "Requires Exalted reputation grind with faction.", d = "Earn Exalted with Operation: Shieldwall by completing reputation quests and turning in items during the relevant event window. Reputation gains are often capped per day, so maximize daily rewards before the expansion ends.", x = 4 },
        [8206] = { e = 4, s = "g", r = "Requires Exalted reputation grind with faction.", d = "Reach Exalted status with the Dominance Offensive through questing and turning in materials during its active period. This faction has limited time gates, so prioritize it early in your Pandaria journey.", x = 4 },
        [8208] = { e = 4, s = "g", r = "Requires Exalted reputation grind with faction.", d = "Gain Exalted with the Kirin Tor Offensive by completing their specific quests and turning in resources while the event is available. Reputation caps may apply daily, so grind efficiently before the expansion concludes.", x = 4 },
        [8209] = { e = 4, s = "g", r = "Requires Exalted reputation grind with faction.", d = "Achieve Exalted with the Sunreaver Onslaught by finishing their quest chain and turning in items during the designated timeframe. Like other factions, this has a hard time gate, so do not delay starting these quests.", x = 4 },
        [8210] = { e = 4, s = "g", r = "Requires Exalted reputation grind with faction.", d = "Grind daily Shado-Pan Assault quests and world events to gain reputation efficiently. Focus on Exalted rewards first, as this achievement is account-wide but requires significant time investment.", x = 4 },
        [8212] = { e = 3, s = "g", r = "Requires looting rare books from trolls on Isle of Thunder.", d = "Farm the Isle of Thunder for rare Zandalari troll drops like Iron-Bound and Blood-Spattered Journals. These items are missable if you leave the zone without looting them, so prioritize clearing trash mobs.", x = 4 },
        [8218] = { e = 4, s = "g", r = "Requires grinding Conquest points in Season 13.", d = "Earn Conquest Points by completing PvP objectives in Season 13. This is a time-gated achievement tied to specific seasonal rules, so check current season requirements before starting.", x = 4 },
        [8219] = { e = 4, s = "c", h = { 32186, 32187, 32188 }, r = "Requires restoring multiple rare Mantid artifacts.", d = "Use Archaeology to restore all Mantid artifacts listed in the info field. Ensure you have enough excavation points and display them in your dig site to complete this account-wide goal.", x = 4 },
        [8220] = { e = 4, s = "g", r = "Requires restoring 5 specific rare banners.", d = "Focus on restoring exactly five Banners of the Mantid Empire first. This is a prerequisite for higher-tier collector achievements, so track your progress carefully during excavation runs.", x = 4 },
        [8221] = { e = 4, s = "g", r = "Requires restoring 20 specific rare banners.", d = "After completing the five-banner goal, continue excavating until you have twenty Banners. Remember that this requires finishing the previous tier first, so plan your archaeology sessions accordingly.", x = 4 },
        [8222] = { e = 3, s = "g", r = "Grinding archaeology sites for 5 items takes hours.", d = "Target five Ancient Sap Feeders for restoration before moving to the twenty count. These artifacts drop from specific Mantid sites, so explore thoroughly during each dig session.", x = 4 },
        [8223] = { e = 4, s = "g", r = "Restoring 20 items requires significant time investment.", d = "Complete the five-Feeder tier first, then grind for twenty total. This is a chain achievement, meaning you cannot skip steps or start at the higher count directly.", x = 4 },
        [8224] = { e = 3, s = "g", r = "Grinding archaeology sites for 5 items takes hours.", d = "Restore five Praying Mantids as your initial archaeology target. These items are distinct from other artifacts, so verify drops against the required list to avoid wasting excavation points.", x = 4 },
        [8225] = { e = 4, s = "g", r = "Restoring 20 items requires significant time investment.", d = "Finish the five-Mantid goal before attempting the twenty count. This sequential requirement means you must fully complete one tier before unlocking the next in the chain.", x = 4 },
        [8226] = { e = 3, s = "g", r = "Grinding archaeology sites for 5 items takes hours.", d = "Aim for five Inert Sound Beacons first during your archaeology runs. These are rare drops that require careful monitoring of dig site loot tables to ensure you don't miss them.", x = 4 },
        [8227] = { e = 4, s = "g", r = "Restoring 20 items requires significant time investment.", d = "Complete the five-Beacon tier before progressing to twenty. Since this is a chain achievement, failing to finish the lower count will block access to the higher one permanently.", x = 4 },
        [8228] = { e = 3, s = "g", r = "Grinding archaeology sites for 5 items takes hours.", d = "Start Archaeology and dig sites to find Paragon fragments. Restore five remains by combining fragments at a Dig Site; this is account-wide so share progress with friends.", x = 4 },
        [8229] = { e = 4, s = "g", r = "Restoring 20 items requires significant time investment.", d = "Continue restoring Paragon remains until you reach twenty total. This requires completing the previous achievement first and relies on consistent site digging.", x = 4 },
        [8230] = { e = 3, s = "g", r = "Grinding archaeology sites for 5 items takes hours.", d = "Focus your archaeology efforts on Mantid sites to restore five lamps. These drops are account-wide, so coordinate with other players for faster completion.", x = 4 },
        [8231] = { e = 4, s = "g", r = "Restoring 20 items requires significant time investment.", d = "Progress from the previous step by restoring twenty Mantid lamps. Keep digging at Mantid ruins until the counter fills up.", x = 4 },
        [8232] = { e = 3, s = "g", r = "Grinding archaeology sites for 5 items takes hours.", d = "Target Pollen Collector remains by visiting specific archaeology sites. Restore five of them to unlock the next tier of this account-wide collection.", x = 4 },
        [8233] = { e = 4, s = "g", r = "Restoring 20 items requires significant time investment.", d = "Finish the Pollen Collectors set by restoring twenty total remains. This requires persistent site visits and combining fragments at Dig Sites.", x = 4 },
        [8234] = { e = 1, s = "g", r = "Simple archaeology dig; trivial once started.", d = "Look for Kypari Sap Containers in archaeology sites to restore five of them. These are account-wide, so team up with others to speed up progress.", x = 4 },
        [8235] = { e = 1, s = "g", r = "Same as previous; just more containers needed.", d = "Complete the Kypari set by restoring twenty containers. Continue digging at relevant sites until you have enough fragments for the final restores.", x = 4 },
        [8293] = { e = 4, s = "c", h = { 32750, 32751, 32752 }, r = "RNG-heavy pet collection from old raids.", d = "Farm battle pets from Karazhan, Serpentshrine Cavern, and Tempest Keep to collect all listed pets. This is account-wide, so coordinate with friends to get rare drops faster.", x = 4 },
        [8294] = { e = 2, s = "s", r = "Single scenario completion; moderate time.", d = "Complete the Secrets of Ragefire scenario by killing Overseer Elaglo. Ensure you have access to the Pandaria expansion content before starting this task.", x = 4 },
        [8295] = { e = 3, s = "c", h = { 32878 }, r = "Same as above but requires zero damage.", d = "Run the same scenario but keep your Gob Squad pets alive at all costs. Any damage taken will fail this specific achievement requirement.", x = 4 },
        [8297] = { e = 3, s = "g", r = "10 PvP pet battles; moderate grind.", d = "Win ten PvP pet battles using a full team of level 25 pets via the Find Battle feature. Start with easier opponents to build your win streak safely.", x = 4 },
        [8298] = { e = 4, s = "g", r = "50 battles required; significant time investment.", d = "Start this chain by winning PvP pet battles with a full team of level 25 pets via Find Battle. You must complete the previous tier first, so ensure you have the Merciless Pet Brawler before attempting Vengeful. Note that these are account-wide achievements, meaning progress carries across all characters.", x = 4 },
        [8300] = { e = 5, s = "g", r = "250 battles; heavy grind or RNG issues.", d = "After unlocking Vengeful Pet Brawler, continue grinding PvP pet battles to reach the 250 win threshold for Brutal Pet Brawler. This is a straightforward grind requiring no specific strategy beyond maintaining your team at level 25. Remember that rewards like the Stunted Direhorn are account-wide.", x = 4 },
        [8301] = { e = 5, s = "g", r = "1000 battles; extreme time commitment.", d = "To earn Deadly Pet Brawler, you need to win 1000 PvP pet battles with a full level 25 team after completing Brutal Pet Brawler. This is a long-term goal that may take significant time depending on your playstyle and luck. The title reward is account-wide.", x = 4 },
        [8302] = { e = 4, s = "g", r = "200 mounts; long grind with RNG factors.", d = "Obtain 200 unique mounts for a single character to complete Mount Parade, starting with any available mount from dailies or world drops. Be aware that some mounts are rare or require specific events, so plan your collection strategy carefully. This achievement is account-wide.", x = 4 },
        [8304] = { e = 4, s = "g", r = "Same as above but different mount type.", d = "Similar to the previous Mount Parade, gather 200 unique mounts for a single character, but focus on different sources if you already have some from the Alliance version. Ensure you do not duplicate mounts when counting toward this specific achievement. The reward is account-wide.", x = 4 },
        [8306] = { e = 2, s = "c", h = { 33149, 33148, 33150 }, r = "Quest chain; moderate effort with multiple steps.", d = "Complete the Durotar 5.3 storyline quests and weekly Battlefield: Barrens to earn the Hordebreaker title. This legacy achievement requires finishing specific story arcs from Patch 5.3, so check your quest log for any missing objectives. The title is account-wide.", x = 4 },
        [8307] = { e = 2, s = "c", r = "Weekly quest chain in Durotar.", d = "Finish the Durotar 5.3 storyline quests and weekly Battlefield: Barrens to earn the Darkspear Revolutionary title. Ensure you complete all Horde-specific objectives related to Vol'jin's uprising. This legacy achievement is account-wide.", x = 4 },
        [8310] = { e = 4, s = "s", r = "Heroic scenario boss fight.", d = "Defeat Borokhula the Destroyer in A Brewing Storm on Heroic Difficulty by forming a group and using appropriate tactics for the boss mechanics. This scenario requires coordination with other players to succeed. The achievement is account-wide.", x = 4 },
        [8311] = { e = 4, s = "s", r = "Heroic Ancient Mogu Crypt run.", d = "Complete the Crypt of Forgotten Kings scenario on Heroic Difficulty by defeating all bosses within the time limit. Form a group if needed, as some encounters are challenging solo. This achievement is account-wide.", x = 4 },
        [8312] = { e = 4, s = "s", r = "Heroic Blood in the Snow scenario.", d = "Finish the Blood in the Snow scenario on Heroic Difficulty by completing all objectives and defeating the final boss. Coordinate with your group to manage the scenario's mechanics effectively. The achievement is account-wide.", x = 4 },
        [8314] = { e = 4, s = "s", r = "Defeat Admiral Hagman in scenario.", d = "Defeat Admiral Hagman in the Battle on the High Seas scenario by coordinating with your group to handle his abilities. This may require multiple attempts depending on your team composition. The achievement is account-wide.", x = 4 },
        [8315] = { e = 4, s = "s", r = "Defeat Admiral Hodgson in scenario.", d = "Defeat Admiral Hodgson in the Battle on the High Seas scenario using a similar strategy as for Hagman. Ensure your group is prepared for his unique mechanics and health pool. This achievement is account-wide.", x = 4 },
        [8316] = { e = 4, s = "s", r = "Complete Blood in the Snow scenario.", d = "Complete the Blood in the Snow scenario to earn this account-wide achievement and its chair reward.", x = 4 },
        [8317] = { e = 4, s = "s", r = "Complete Dark Heart of Pandaria.", d = "Finish the Dark Heart of Pandaria scenario on any difficulty to claim your 10 points.", x = 4 },
        [8318] = { e = 5, s = "s", r = "Heroic Dark Heart scenario run.", d = "Run the Dark Heart of Pandaria scenario specifically on Heroic Difficulty to unlock this variant.", x = 4 },
        [8319] = { e = 4, s = "s", r = "Pick up three artifacts in scenario.", d = "Pick up three special artifacts in one run of Dark Heart of Pandaria for the Super Combo bonus.", x = 4 },
        [8325] = { e = 4, s = "c", r = "Legendary cloak and Garrosh quest.", d = "Work with Wrathion to craft your legendary cloak and defeat Garrosh Hellscream to gain the Legend of Pandaria title.", x = 4 },
        [8327] = { e = 4, s = "s", r = "Heroic Secrets of Ragefire run.", d = "Complete the Secrets of Ragefire scenario on Heroic Difficulty, ensuring you kill Overseer Elaglo.", x = 4 },
        [8329] = { e = 1, s = "s", r = "Use one item in one scenario run.", d = "Use every basket of Shimmerweed in a single Blood in the Snow run to achieve this goal.", x = 4 },
        [8330] = { e = 1, s = "s", r = "Avoid a specific ability in one run.", d = "Prevent Hekima from casting Hekima's Wisdom during your Blood in the Snow scenario attempt.", x = 4 },
        [8331] = { e = 2, s = "s", r = "Win a standard PvP match once.", d = "Win a match in Deepwind Gorge PvP to secure this victory achievement.", x = 4 },
        [8332] = { e = 4, s = "g", r = "Grind 100 wins; effort scales down steadily.", d = "Accumulate 100 total victories in Deepwind Gorge, as this tracks across all characters on your account.", x = 4 },
        [8333] = { e = 3, s = "s", r = "Win with a high score in one match.", d = "Win Deepwind Gorge with a perfect score of 1600 to 0 for the Perfection title.", x = 4 },
        [8335] = { e = 2, s = "g", r = "Grind to rank 9 in a seasonal pub.", d = "Reach Rank 9 with Bizmo's Brawlpub during the Pandaria campaign era to complete this legacy task.", x = 4 },
        [8336] = { e = 3, s = "g", r = "Grind to rank 10; slightly harder than rank 9.", d = "Focus on completing the Pandaria campaign quests to unlock Bizmo's Brawlpub. Engage in daily brawls consistently until you reach Rank 10, as this is a time-gated legacy achievement tied to that specific expansion era.", x = 4 },
        [8337] = { e = 2, s = "g", r = "Grind to rank 9 in a seasonal arena.", d = "Participate regularly in Brawl'gar Arena during the Pandaria campaign. You must reach Rank 9 before the content becomes unavailable, so prioritize this while you have access to the original arena mechanics.", x = 4 },
        [8338] = { e = 3, s = "g", r = "Grind to rank 10; slightly harder than rank 9.", d = "Continue competing in Brawl'gar Arena until you hit Rank 10. This is a straightforward grind that requires consistent participation during the Pandaria expansion window before the achievement becomes missable.", x = 4 },
        [8339] = { e = 4, s = "c", h = { 32898, 32905 }, r = "Defeat many bosses; RNG-heavy drops dominate.", d = "First complete the Pandaria version of \"Collect Your Deck\" to unlock access to Season 2 bosses. Then, defeat all listed Draenor Brawler's Guild bosses in any order to earn the right to purchase their challenge cards.", x = 4 },
        [8340] = { e = 4, s = "c", r = "Defeat a long list of Brawler's Guild bosses.", d = "Defeat every boss listed for the Pandaria campaign version of this achievement. This is a straightforward completion task that requires no specific strategy, just consistent runs through the Brawler's Guild during that expansion.", x = 4 },
        [8342] = { e = 4, s = "c", h = { 32924, 32931 }, r = "Defeat many bosses; RNG-heavy drops dominate.", d = "Ensure you have completed the Pandaria prerequisite first, then defeat all listed Draenor bosses. This achievement unlocks purchasing cards for those specific bosses, so verify your progress matches the required list before claiming it.", x = 4 },
        [8343] = { e = 4, s = "c", r = "Requires defeating multiple rare Brawler's Guild bosses.", d = "Defeat all specified Brawler's Guild bosses during the Pandaria campaign. Treat this as a checklist of encounters you must clear sequentially or in any order while the game version is active.", x = 4 },
        [8347] = { e = 2, s = "s", r = "One-time scenario run with specific avoidance mechanic.", d = "Play the Battle on the High Seas Scenario solo or with a party that avoids taking cannon fire. Coordinate movement carefully to ensure no member gets hit, as even one hit will fail this specific scenario achievement.", x = 4 },
        [8348] = { e = 5, s = "g", r = "Requires completing all daily pet battle quests across expansions.", d = "Complete all listed pet battle daily quests across every expansion zone. This is a massive grind requiring you to visit each daily quest giver repeatedly until the entire list is checked off for your account.", x = 4 },
        [8350] = { e = 2, s = "g", r = "Grinding 50 mine captures in a PvP zone.", d = "Travel to Deepwind Gorge and assault mines using PvP mechanics or specific quests. You need to accumulate 50 successful assaults, so focus on high-yield spots where mine spawns are frequent during the relevant game era.", x = 4 },
        [8351] = { e = 2, s = "g", r = "Grinding 50 mine cart captures in a PvP zone.", d = "Capture 50 mine carts in Deepwind Gorge by interacting with them before they despawn. This requires patience and positioning near cart spawn points to ensure you can claim enough without dying or missing the opportunity.", x = 4 },
        [8354] = { e = 1, s = "s", r = "Simple fall mechanic achievable quickly in one match.", d = "Jump off cliffs or use movement abilities in Deepwind Gorge to fall at least 25 yards. Ensure you do not die during the fall, as this is a simple distance check that can be done quickly with practice.", x = 4 },
        [8355] = { e = 2, s = "s", r = "Occasional event during a single Deepwind Gorge match.", d = "Queue for Deepwind Gorge and focus on protecting your mine cart from enemy players. If they steal it, try to kill them before they exit the base zone.", x = 4 },
        [8358] = { e = 3, s = "c", r = "Requires completing four specific actions in one match.", d = "Play multiple matches of Deepwind Gorge until you have assaulted a mine, defended one, captured a cart, and returned it all in one session.", x = 4 },
        [8359] = { e = 2, s = "g", r = "Grinding four personal captures within a single match.", d = "Focus on capturing the enemy mine cart four times during a single match; this requires active participation rather than just defending your own side.", x = 4 },
        [8360] = { e = 4, s = "c", r = "Requires completing all other Deepwind Gorge and Brawler's Guild achievements.", d = "Complete all listed Deepwind Gorge sub-achievements, including winning matches and earning specific titles like 'Gorgeous' for account-wide recognition.", x = 4 },
        [8364] = { e = 2, s = "s", r = "One-time Heroic run of the Battle on the High Seas scenario.", d = "Enter the Battle on the High Seas scenario and defeat Admiral Hagman on Heroic difficulty; ensure you are prepared for high-level combat.", x = 4 },
        [8366] = { e = 2, s = "s", r = "One-time Heroic run of the Battle on the High Seas scenario.", d = "Complete the same scenario but target Admiral Hodgson instead, requiring similar heroic-level preparation and coordination with your group.", x = 4 },
        [8368] = { e = 2, s = "s", r = "Single scenario run with manageable mechanics.", d = "Enter the Crypt of Forgotten Kings scenario and accumulate 20 stacks of Uncontrolled Anger before defeating the Abomination of Anger.", x = 4 },
        [8381] = { e = 4, s = "g", r = "Requires significant PvP time and RNG luck.", d = "Participate in Season 14 PvP to earn Conquest Points; aim for 27,000 total points while playing regularly throughout the season.", x = 4 },
        [8382] = { e = 4, s = "g", r = "Requires significant PvP time and RNG luck.", d = "Similar to the previous achievement but targets Arena points instead of Conquest; engage in arena matches consistently to reach the goal.", x = 4 },
        [8397] = { e = 4, s = "g", r = "Many cats; some are rare drops or events.", d = "Collect various cat pets through pet battles or other means; some may be rare, so check available sources for each specific cat listed.", x = 4 },
        [8410] = { e = 3, s = "s", r = "One-time scenario with specific win condition.", d = "Complete the Celestial Tournament scenario by winning all required rounds; ensure your team is well-prepared for the challenging boss encounters.", x = 4 },
        [8448] = { e = 3, s = "s", r = "Single raid encounter with a mechanic.", d = "Defeat General Nazgrim in Siege of Orgrimmar on Normal or higher difficulty while keeping Gamon alive and active throughout the battle.", x = 4 },
        [8450] = { e = 4, s = "g", r = "Requires significant PvP time and RNG luck.", d = "Focus on high-level PvP arenas or battlegrounds to earn Conquest Points efficiently during Season 15. Avoid low-impact activities like world PvP as they yield minimal points. This achievement is time-gated to the specific season and cannot be completed later.", x = 4 },
        [8451] = { e = 4, s = "g", r = "Requires significant PvP time and RNG luck.", d = "Complete the same tasks as the Hard version but aim for a lower point total if you lack top-tier gear. Prioritize consistent arena participation over random battlegrounds to maximize your daily earnings. Ensure you are in Season 15, as this is no longer active and cannot be earned now.", x = 4 },
        [8453] = { e = 3, s = "s", r = "Single raid encounter with multiple objectives.", d = "Start by defeating the Vale of Eternal Sorrows bosses before entering the main raid. Rescue all prisoners and Ji Firepaw during the fight with the Dark Shaman on Normal or higher. Do not skip the rescue mechanics, as missing them will prevent you from completing this specific objective.", x = 4 },
        [8454] = { e = 4, s = "c", h = { 33696, 33629, 34024 }, r = "Multiple raids; some bosses are very hard.", d = "Begin by clearing the prelude Vale of Eternal Sorrows and then tackle Siege of Orgrimmar bosses in order. Complete all sub-objectives like rescuing prisoners and defeating specific raid members to unlock the mount reward. This is account-wide, so coordinate with your group to ensure every boss kill counts toward the total.", x = 4 },
        [8458] = { e = 3, s = "s", r = "Single raid instance with multiple bosses.", d = "Clear the Vale of Eternal Sorrows prelude raid first by defeating Immerseus, Norushen, and the Sha of Pride. Ensure you have a capable group since these bosses require coordinated mechanics. This achievement unlocks after beating all four specific boss objectives listed in the info.", x = 4 },
        [8459] = { e = 3, s = "s", r = "Single raid instance with multiple bosses.", d = "Enter Siege of Orgrimmar and defeat the exterior bosses including Galakras and General Nazgrim. Focus on the main raid progression to hit these targets naturally. Do not rush into the inner sanctum before clearing the Gates of Retribution section.", x = 4 },
        [8461] = { e = 5, s = "c", h = { 33470, 33472 }, r = "Requires Mythic Siege of Orgrimmar raid clears.", d = "Progress through the raid until you reach The Underhold area to fight Malkorok, Thok, and Spoils of Pandaria. Ensure your group is prepared for these high-difficulty encounters as they often require specific strategies. Complete this section before moving deeper into Garrosh's inner sanctum.", x = 4 },
        [8462] = { e = 5, s = "c", h = { 33475 }, r = "Requires Mythic Siege of Orgrimmar raid clears.", d = "Finish the raid by defeating Siegecrafter Blackfuse, the Klaxxi Paragons, and finally Garrosh Hellscream in the inner sanctum. Prepare for intense mechanics as these are end-game encounters. This achievement completes the main raid progression after clearing The Underhold.", x = 4 },
        [8463] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "First complete Heroic Immerseus to unlock Mythic difficulty, then defeat him again on Mythic mode. Ensure your group is well-gearred and skilled for higher difficulties. This is a time-gated achievement requiring specific seasonal or expansion content availability.", x = 4 },
        [8465] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Clear Heroic Fallen Protectors first, then re-queue them on Mythic difficulty to earn the achievement. Coordinate with your group to handle the increased damage and mechanics. This requires completing the lower tier version before attempting the harder variant.", x = 4 },
        [8466] = { e = 5, s = "s", r = "Requires specific Mythic difficulty trial completion.", d = "Defeat Norushen on Heroic mode initially, then challenge him again on Mythic difficulty for the achievement. Prepare for his trial mechanics which are more demanding at higher levels. Ensure your group can handle the increased complexity before starting the Mythic run.", x = 4 },
        [8467] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Complete Heroic Sha of Pride first to unlock Mythic difficulty, then defeat him again on Mythic mode. This boss requires precise timing and coordination from your entire group. Do not attempt Mythic without clearing the Heroic version as a prerequisite.", x = 4 },
        [8468] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Defeat Galakras on Heroic first to unlock Mythic. Ensure your group is prepared for the added mechanics and increased damage output.", x = 4 },
        [8469] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Complete Iron Juggernaut on Heroic before attempting Mythic. The fight requires precise timing; practice the pull mechanics with a full raid.", x = 4 },
        [8470] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Start by killing Kor'kron Dark Shaman on Heroic. Be ready for the intense damage phases and coordinate your raid's healing resources carefully.", x = 4 },
        [8471] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Defeat General Nazgrim on Heroic to unlock Mythic. Watch out for his adds and ensure your raid can handle the sustained pressure.", x = 4 },
        [8472] = { e = 5, s = "s", r = "Requires specific Mythic difficulty kill.", d = "Begin with Malkorok on Heroic to prepare for Mythic. The fight involves complex mechanics; communicate clearly with your raid members throughout.", x = 4 },
        [8478] = { e = 5, s = "s", r = "Requires specific Mythic difficulty event completion.", d = "Complete the Spoils of Pandaria event on Heroic first. This requires coordination and timing; ensure everyone is ready for the dynamic challenges.", x = 4 },
        [8479] = { e = 5, s = "s", r = "Mythic raid boss requires group and high skill.", d = "Defeat Thok the Bloodthirsty on Heroic to unlock Mythic. Manage his adds effectively and keep your raid's health stable during intense phases.", x = 4 },
        [8480] = { e = 5, s = "s", r = "Mythic raid boss requires group and high skill.", d = "Start with Siegecrafter Blackfuse on Heroic before moving to Mythic. The fight demands precise positioning; practice the mechanics with a full group.", x = 4 },
        [8481] = { e = 5, s = "s", r = "Mythic raid encounter requires group coordination.", d = "Defeat the Klaxxi Paragons on Heroic first. Each boss has unique mechanics; ensure your raid is prepared for the varied challenges ahead.", x = 4 },
        [8482] = { e = 5, s = "s", r = "Mythic boss fight requires full raid group.", d = "Complete Garrosh Hellscream on Heroic to unlock Mythic. This final boss requires flawless execution; coordinate with your raid for the best chance at success.", x = 4 },
        [8484] = { e = 4, s = "g", r = "Requires winning 100 matches or 40 rated BGs.", d = "Win 100 Arena (3v3) or 40 Rated Battlegrounds in Season 14. Focus on consistent performance and adapt to different match-ups for steady progress.", x = 4 },
        [8485] = { e = 4, s = "g", r = "Requires winning 100 matches or 40 rated BGs.", d = "Achieve the same goal as id=8484: win 100 Arena or 40 Rated BGs in Season 14. Maintain high performance and adapt strategies for each match.", x = 4 },
        [8486] = { e = 2, s = "s", r = "Simple trial run, usually done in minutes.", d = "Start by queuing for the Bronze Damage trial at the Proving Grounds. Complete the basic encounter to unlock the Silver tier immediately after.", x = 4 },
        [8487] = { e = 2, s = "s", r = "Simple trial run, usually done in minutes.", d = "Queue for the Bronze Tank trial and focus on maintaining your health bar while dealing damage. Finish this before moving to the Silver requirement.", x = 4 },
        [8488] = { e = 2, s = "s", r = "Simple trial run, usually done in minutes.", d = "Enter the Bronze Healer trial and prioritize keeping the group alive during the encounter. Once done, you can progress to the Silver tier.", x = 4 },
        [8491] = { e = 3, s = "g", r = "Requires completing Bronze trial first then more.", d = "You must finish the Bronze Damage achievement first before attempting the Silver version. Queue up again once the prerequisite is marked complete.", x = 4 },
        [8492] = { e = 3, s = "g", r = "Requires completing Bronze tank trial first.", d = "Complete the Bronze Tank trial to unlock the Silver Tank challenge. Ensure your tanking skills are solid before queuing for the harder tier.", x = 4 },
        [8493] = { e = 3, s = "g", r = "Requires completing Bronze healer trial first.", d = "Finish the Bronze Healer trial as a prerequisite for the Silver version. Focus on healing efficiency and survival mechanics during the run.", x = 4 },
        [8496] = { e = 3, s = "g", r = "Requires unlocking prior tiers first.", d = "Unlock this by completing the Silver Damage trial first. The Gold tier introduces tougher mechanics, so practice your rotation before queuing.", x = 4 },
        [8497] = { e = 3, s = "g", r = "Requires unlocking prior tiers first.", d = "Complete the Silver Tank trial to gain access to the Gold Tank challenge. Be prepared for increased damage intake and tighter cooldown management.", x = 4 },
        [8498] = { e = 3, s = "g", r = "Requires unlocking prior tiers first.", d = "Finish the Silver Healer trial before attempting the Gold version. The encounter will demand higher healing throughput and better group coordination.", x = 4 },
        [8501] = { e = 3, s = "g", r = "Grind through waves after tier unlock.", d = "Reach Wave 10 of the Endless Damage trial only after finishing the Gold tier. This stage tests your ability to sustain damage output over a longer duration.", x = 4 },
        [8502] = { e = 3, s = "g", r = "Grind through waves after tier unlock.", d = "Complete the Gold Tank trial to unlock the Endless Tank Wave 10 challenge. Expect significantly higher enemy health pools and attack speeds.", x = 4 },
        [8503] = { e = 3, s = "g", r = "Grind through waves after tier unlock.", d = "Finish the Gold Healer trial before attempting the Endless Healer Wave 10. This stage requires managing resources carefully over an extended fight.", x = 4 },
        [8504] = { e = 3, s = "g", r = "Grind through waves after tier unlock.", d = "Complete Wave 10 first to unlock this trial. Farm the Proving Grounds repeatedly until you clear Wave 20 without dying or failing the timer.", x = 4 },
        [8505] = { e = 3, s = "g", r = "Grind through waves after tier unlock.", d = "Unlock Wave 10 before attempting this tanking trial. Focus on maintaining aggro and surviving longer than the previous waves to reach Wave 20.", x = 4 },
        [8506] = { e = 3, s = "g", r = "Grind through waves after tier unlock.", d = "Finish Wave 10 first to access this healer trial. Prioritize keeping the group alive while pushing through the increasing difficulty of Wave 20.", x = 4 },
        [8507] = { e = 3, s = "g", r = "Requires full chain completion first.", d = "Complete Wave 20 first to unlock this harder damage trial. Be prepared for significantly tougher mechanics and longer run times at Wave 30.", x = 4 },
        [8508] = { e = 3, s = "g", r = "Requires full chain completion first.", d = "Finish Wave 20 before attempting this tanking challenge. Expect much higher damage intake and stricter survivability requirements when reaching Wave 30.", x = 4 },
        [8509] = { e = 3, s = "g", r = "Requires full chain completion first.", d = "Complete Wave 20 first to unlock this healer trial. Manage group health carefully as the encounter difficulty spikes dramatically at Wave 30.", x = 4 },
        [8518] = { e = 2, s = "c", r = "Defeat 12 trainers; trivial combat, no RNG.", d = "Defeat every trainer listed in the Celestial Tournament, including rare ones like Xu-Fu and Chi-Chi. Ensure you have all required pets before starting to avoid missing content.", x = 4 },
        [8519] = { e = 3, s = "g", r = "Collect 4 pets via battles or drops.", d = "Collect all four celestial pets by defeating their respective trainers or obtaining them via other means. Verify your collection is complete before claiming the achievement.", x = 4 },
        [8520] = { e = 3, s = "c", r = "Stomp mines then boss; standard raid mechanics.", d = "Run Siege of Orgrimmar Normal or higher and stomp six crawler mines before killing Iron Juggernaut. Do not kill the boss until all mines are destroyed.", x = 4 },
        [8521] = { e = 4, s = "c", h = { 33599 }, r = "Boss fight with strict no-pride RNG constraint.", d = "Start the Sha of Pride fight only after Norushen dies and ensure no player gains pride from manifestations. Coordinate with your group to avoid accidental pride gain.", x = 4 },
        [8527] = { e = 3, s = "s", r = "Open cage after boss; minor timing step.", d = "Defeat Thok the Bloodthirsty on Normal or higher, then open the cage to let the snail eat his corpse. Ensure the cage is opened after the fight ends.", x = 4 },
        [8528] = { e = 4, s = "c", r = "Raid phase with yard/RNG constraints.", d = "During Desperate Measures, transfer the Mark of Anguish to five unique players over 200 yards before defeating Fallen Protectors. Coordinate movement carefully to meet distance and player count requirements.", x = 4 },
        [8529] = { e = 4, s = "c", r = "Raid fight requiring specific kill order.", d = "Start by assigning one player to tank Mantids and another to tank Mogu, ensuring no single person hits both types. Coordinate damage so that only the designated tanks take kills from their respective faction. This requires strict role assignment at the start of the fight.", x = 4 },
        [8530] = { e = 4, s = "s", r = "Boss fight with strict NPC survival rule.", d = "Keep your party focused on Galakras and ignore any stray adds or NPCs that might die. Use defensive cooldowns and healing to protect friendly NPCs, as even one death will fail the achievement. Do not engage enemies outside the main arena unless necessary for survival.", x = 4 },
        [8531] = { e = 4, s = "c", h = { 34021 }, r = "Defeat Paragons; one requires heavy RNG.", d = "You must assume the mantle of three different Paragons before defeating them all in a single run. Plan your rotation carefully to switch roles between Wind-Reaver, Bloodseeker, and others without resetting progress. Ensure you complete the final phase after transforming into at least three unique forms.", x = 4 },
        [8532] = { e = 4, s = "s", r = "Boss fight with strict corruption avoidance.", d = "Avoid letting corruption fuse with the Amalgam by killing corrupted adds quickly before they merge. Monitor the arena for fusion events and prioritize eliminating them immediately. This requires precise timing and coordination to prevent accidental fusions during high-damage phases.", x = 4 },
        [8533] = { e = 3, s = "s", r = "Single boss kill on Timeless Isle.", d = "Travel to the Timeless Isle and locate Ordos, Fire-God of the Yaungol, for a straightforward kill. No special mechanics or conditions are mentioned beyond defeating him directly. Ensure you have sufficient gear and group composition for this legacy raid encounter.", x = 4 },
        [8535] = { e = 4, s = "c", r = "Four Celestial trials; moderate combat grind.", d = "Visit the Timeless Isle and complete trials against all four Celestials: Chi-Ji, Niuzao, Xuen, and Yu'lon. Each trial requires combat victory, so prepare appropriate strategies for each boss type. Complete them in any order but ensure you defeat each one individually.", x = 4 },
        [8536] = { e = 2, s = "s", r = "Kill 10 mobs then raid boss; straightforward.", d = "Defeat Immerseus only after killing 10 Tears of the Vale during the same raid run. Track your progress carefully and do not restart the fight prematurely. Ensure all Tears are eliminated before engaging Immerseus for the final phase.", x = 4 },
        [8537] = { e = 4, s = "g", r = "Killing 18 specific targets with a single shot is RNG heavy.", d = "Use an Iron Star to kill 18 Kor'kron Warbringers in one go, then proceed to defeat Garrosh. Coordinate your group to maximize damage from a single Iron Star cast. Avoid spreading kills across multiple stars or failing to hit the required count.", x = 4 },
        [8538] = { e = 3, s = "s", r = "Transform mob then raid boss; standard progression.", d = "Transform a Corrupted Skullsplitter into a Corrupted Amalgamation before engaging Malkorok. Follow the transformation steps precisely and ensure the process completes successfully. Then defeat Malkorok without resetting the achievement progress.", x = 4 },
        [8543] = { e = 2, s = "c", r = "Avoid destroying weapons during a normal raid fight.", d = "Defeat Siegecrafter Blackfuse while preserving all weapons: Laser Turret, Electromagnet, Missile Turret, and Crawler Mines. Avoid using abilities or mechanics that destroy these items. Monitor their status throughout the fight to prevent accidental destruction.", x = 4 },
        [8641] = { e = 3, s = "g", r = "Winning 100 arena or 40 rated BGs is a grind.", d = "Win 100 Arena matches or 40 Rated Battlegrounds in Season 15 to earn this legacy achievement. Choose whichever mode suits your playstyle better and track your wins carefully. Note that this is time-gated to Season 15, so plan accordingly.", x = 4 },
        [8642] = { e = 3, s = "g", r = "Winning 100 arena or 40 rated BGs is a grind.", d = "Same as above: win 100 Arena or 40 Rated BG matches in Season 15 for the Vicious Saddle mount. Focus on consistent performance and avoid losing too many matches. Track your progress using in-game tools or external trackers if needed.", x = 4 },
        [8671] = { e = 3, s = "c", r = "Complete multiple Draenor storylines; moderate effort.", d = "Start the Frostfire Ridge storylines by completing the initial Horde quests listed in the info field to unlock the treasure map. Focus on finishing each specific quest objective sequentially as they are time-gated and require progression through the zone. Do not miss any of the listed quest IDs, as completing them all is necessary for this account-wide achievement.", x = 5 },
        [8679] = { e = 4, s = "s", r = "Heroic/Mythic Garrosh is a long raid fight.", d = "Defeat Garrosh Hellscream in Siege of Orgrimmar on Heroic or Mythic difficulty to earn both titles simultaneously. Ensure your group composition can handle the high difficulty before attempting the raid boss fight. This is a one-time kill requirement, so make sure you are prepared for the encounter mechanics.", x = 4 },
        [8680] = { e = 4, s = "s", r = "Heroic/Mythic Garrosh is a long raid fight.", d = "Defeat Garrosh Hellscream in Siege of Orgrimmar on Heroic or Mythic difficulty to earn both titles simultaneously. Ensure your group composition can handle the high difficulty before attempting the raid boss fight. This is a one-time kill requirement, so make sure you are prepared for the encounter mechanics.", x = 4 },
        [8697] = { e = 1, s = "s", r = "Run one Proving Grounds trial with wrong spec.", d = "Complete any Basic trial at the Proving Grounds while playing a specialization that is not suited for it to earn points. Try using a class or spec like a Mage in a tanking trial or a Warrior in a DPS trial. This achievement tracks account-wide, so you can switch characters between trials as needed.", x = 4 },
        [8699] = { e = 2, s = "s", r = "Shoot down a flyer; quick PvP interaction.", d = "Shoot down another player's Crashin' Thrashin' Flyer with your own during Winter Veil to complete this event-specific task. Coordinate with friends or other players in the area to target each other for maximum efficiency. This achievement is time-gated to the Winter Veil holiday, so plan to do it during that specific event window.", x = 4 },
        [8712] = { e = 3, s = "g", r = "Kill many unique Timeless Isle creatures; steady grind.", d = "Defeat all listed creatures on the Timeless Isle by exploring the zone thoroughly and engaging with common mobs. Use a high-level character or group up to quickly clear out the various spawn points for these creatures. This achievement is account-wide, so you can switch characters between different areas of the island as needed.", x = 4 },
        [8714] = { e = 4, s = "c", r = "Requires finding and killing many rare mobs on the Timeless Isle.", d = "Defeat all rare creatures on the Timeless Isle by locating their specific spawn points and engaging them carefully. These rares often require specific tactics or group coordination to defeat efficiently. Since this is account-wide, you can use multiple characters to clear different areas of the island simultaneously.", x = 4 },
        [8715] = { e = 3, s = "g", r = "Requires farming reputation with a specific NPC over time.", d = "Earn Exalted status with Emperor Shaohao by completing reputation quests and turning in items in Pandaria. Focus on the main questline and daily activities that grant reputation points to reach the required level quickly. This achievement is account-wide, so you can switch characters between different factions or zones as needed.", x = 4 },
        [8716] = { e = 4, s = "c", r = "Requires obtaining a rare item from an event then using it.", d = "Use the Censer of Eternal Agony obtained from Speaker Gulan on the Timeless Isle to complete this PvP-related task. Ensure you have the censer item before attempting to use it in the designated area on the island. This achievement is time-gated to specific events or conditions, so check the game data for any additional requirements.", x = 4 },
        [8717] = { e = 3, s = "g", r = "Requires farming a specific currency to reach rank 1.", d = "Obtain 10 Bloody Coins as an Emissary of Ordos or Ordon Fire-Watcher by completing daily quests and turning in items on the Timeless Isle. This is the first step in a chain, so focus on earning coins efficiently before moving to the next rank. The achievement is account-wide, allowing you to switch characters between different areas of the island as needed.", x = 4 },
        [8718] = { e = 3, s = "g", r = "Requires farming a specific currency to reach rank 2.", d = "Obtain 100 Bloody Coins as an Emissary of Ordos or Ordon Fire-Watcher by continuing to complete daily quests and turning in items on the Timeless Isle. This requires completing the previous Candlekeeper achievement, so ensure you have already earned that before attempting this one. The achievement is account-wide, allowing you to switch characters between different areas of the island as needed.", x = 4 },
        [8719] = { e = 3, s = "g", r = "Requires farming a specific currency to reach rank 3.", d = "Obtain 500 Bloody Coins as an Emissary of Ordos or Ordon Fire-Watcher by completing daily quests and turning in items on the Timeless Isle. This requires completing the previous Oathguard achievement, so ensure you have already earned that before attempting this one. The achievement is account-wide, allowing you to switch characters between different areas of the island as needed.", x = 4 },
        [8720] = { e = 3, s = "g", r = "Requires farming a specific currency to reach rank 4.", d = "Start as an Emissary of Ordos or Ordon Fire-Watcher to farm Bloody Coins, aiming for Rank 4 first. You must use the Blazebinder NPC to convert coins into the achievement item, so keep your rank high before spending resources.", x = 4 },
        [8721] = { e = 3, s = "g", r = "Requires farming a specific currency to reach rank 5.", d = "After completing Kilnmaster, continue farming Bloody Coins as a Fire-Watcher at Rank 5. This step grants you the Fire-Watcher title, so ensure you have enough coins before turning them in to Blazebinder.", x = 4 },
        [8722] = { e = 4, s = "c", r = "Requires finding and consuming many scattered items across the zone.", d = "Visit every source of Timeless Nutriment on the island, including specific items like Crispfruit and Yak Roast. Check all locations thoroughly as missing even one item will prevent completion since these sources do not respawn frequently.", x = 4 },
        [8723] = { e = 4, s = "c", r = "Requires finding several rare artifacts hidden in specific spots.", d = "Search for lost pandaren artifacts scattered across the Timeless Isle, such as the Cloudstrike Family Helm or Flameheart Shawl. These items are rare drops, so you may need to run multiple groups or use high-level characters to increase drop rates.", x = 4 },
        [8724] = { e = 3, s = "c", r = "Requires visiting four specific shrines to receive blessings.", d = "Locate and visit all four Celestial Shrines on the island to receive blessings from Niuzao, Yu'lon, Chi-Ji, and Xuen. Ensure you have completed previous exploration tasks first, as shrine access may be gated by reputation or quest progression.", x = 4 },
        [8725] = { e = 4, s = "c", r = "Requires checking many suspicious locations for hidden loot.", d = "Interact with suspicious objects like Giant Clams, Glinting Sand, and Fiery Altars throughout the island for hidden loot. Do not skip any area, as some lootables are one-time only and can be missed easily.", x = 4 },
        [8726] = { e = 3, s = "c", r = "Requires jumping puzzle mechanics and RNG drops.", d = "Find and open the Gleaming, Rope-Bound, and Mist-Covered Treasure Chests, which often require solving jump puzzles or defeating guardians. These chests are rare spawns, so explore every corner of the island repeatedly.", x = 4 },
        [8727] = { e = 3, s = "c", r = "Requires finding specific loot from pirate encounters.", d = "Collect Sunken Treasure, Blackguard's Jetsam, and Gleaming Treasure Satchel from pirate-related events or world drops. Since these are rare items, consider joining a group to increase your chances of obtaining them quickly.", x = 4 },
        [8728] = { e = 4, s = "c", r = "Collecting many rare items with RNG factors.", d = "Gather all rare Timeless Isle items listed in the achievement, including Cursed Swabby Helmet and Giant Purse of Timeless Coins. Many of these are rare drops or quest rewards, so prioritize high-level characters and repeatable activities.", x = 4 },
        [8729] = { e = 3, s = "c", r = "Finding chests scattered across the island.", d = "Locate Moss-Covered, Skull-Covered, Sturdy, Smoldering, and Blazing chests scattered across the island. Some require specific conditions to open, so check each chest carefully before assuming it is unobtainable.", x = 4 },
        [8730] = { e = 2, s = "s", r = "Solving a single riddle puzzle.", d = "Find Rolo's Riddle location on the Timeless Isle and solve the puzzle by interacting with the correct objects. This is a one-time event, so ensure you have completed any prerequisite quests first.", x = 4 },
        [8743] = { e = 2, s = "s", r = "Completing one specific quest objective.", d = "Help Zarhym find his body in the Cavern of Lost Spirits, which may require solving environmental puzzles or defeating guardians. This task is account-wide and often needs a group to handle the challenging mechanics inside the cave.", x = 4 },
        [8784] = { e = 3, s = "c", r = "Finding scattered artifacts across the island.", d = "Travel to the Timeless Isle and locate all four lost Pandaren artifacts scattered across its zones. Ensure you have access to the island first, as this is account-wide and requires prior exploration.", x = 4 },
        [8843] = { e = 2, s = "s", r = "Defeating a dungeon boss once.", d = "Enter Skyreach in Draenor and defeat High Sage Viryx on Normal difficulty. This unlocks the next tier of achievements for the same dungeon.", x = 5 },
        [8844] = { e = 3, s = "s", r = "Requires Heroic difficulty run of the dungeon.", d = "Queue for Heroic Skyreach and kill High Sage Viryx to earn this achievement. You must complete the normal version first if you haven't already.", x = 5 },
        [8845] = { e = 2, s = "c", r = "Completing a series of zone quests.", d = "Complete all listed Shadowmoon Valley storylines for your faction. These quests are account-wide, so ensure your alt characters also finish them if needed.", x = 5 },
        [8871] = { e = 3, s = "s", r = "Requires Challenge Mode run with group.", d = "Start Challenge Mode in Skyreach to begin the rating progression chain. This is account-wide and unlocks subsequent bronze through gold tiers.", x = 5 },
        [8872] = { e = 4, s = "s", r = "Requires high rating in Challenge Mode.", d = "Complete Skyreach Challenge Mode with a Bronze or better rating. Focus on efficient gameplay to quickly reach the next tier in the chain.", x = 5 },
        [8873] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Achieve a Silver rating in Skyreach Challenge Mode. Continue optimizing your team composition and strategy to push for higher ratings.", x = 5 },
        [8874] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Reach a Gold rating in Skyreach Challenge Mode. This final tier unlocks the ability to teleport directly to the dungeon from any location.", x = 5 },
        [8875] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Enter Bloodmaul Slag Mines in Challenge Mode to start its progression chain. This is account-wide and requires a full group.", x = 5 },
        [8876] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Complete Bloodmaul Slag Mines Challenge Mode with a Bronze rating. Maintain consistent performance to advance through the bronze tier quickly.", x = 5 },
        [8877] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Achieve a Silver rating in Bloodmaul Slag Mines Challenge Mode. Adjust your tactics if needed to ensure you meet the higher difficulty threshold.", x = 5 },
        [8878] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Reach a Gold rating in Bloodmaul Slag Mines Challenge Mode. This completes the chain and grants teleportation access to the dungeon.", x = 5 },
        [8879] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Start by queuing for Auchindoun Challenge Mode with a group capable of handling the mechanics. You must complete the dungeon once to unlock the Bronze rating requirement before progressing further in the chain.", x = 5 },
        [8880] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "After unlocking the dungeon, focus on optimizing your rotation and positioning to achieve at least a Bronze rating. This step is account-wide, so any character can contribute to the progress once unlocked.", x = 5 },
        [8881] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "To move from Bronze to Silver, refine your team's coordination and minimize deaths or mechanics failures. Consistent performance will push your rating higher without needing to restart the dungeon.", x = 5 },
        [8882] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Aim for a Gold rating by mastering all encounters and ensuring zero wipes during the run. Achieving this unlocks the teleport ability and completes the Auchindoun legacy chain.", x = 5 },
        [8883] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Begin Shadowmoon Burial Grounds Challenge Mode with a well-coordinated group to complete it for the first time. This initial completion is necessary to unlock the Bronze rating tier for the dungeon.", x = 5 },
        [8884] = { e = 2, s = "s", r = "Requires one successful Challenge Mode run.", d = "Once unlocked, run Shadowmoon repeatedly to climb from Bronze to Silver rating. Focus on speed and accuracy to ensure your team meets the higher rating thresholds efficiently.", x = 5 },
        [8885] = { e = 3, s = "c", r = "Requires prior Bronze run; moderate difficulty.", d = "Progressing to Gold requires flawless execution of all mechanics and minimal downtime between pulls. Practice with experienced players if needed to secure the top-tier rating consistently.", x = 5 },
        [8886] = { e = 4, s = "c", r = "Gold rating demands high skill and coordination.", d = "Securing a Gold rating in Shadowmoon unlocks the teleport ability for this zone. Ensure your team is fully prepared before attempting the final rating tier to avoid frustration.", x = 5 },
        [8887] = { e = 3, s = "c", r = "First run of Grimrail; moderate difficulty.", d = "Queue for Grimrail Depot Challenge Mode with a group ready to handle its unique mechanics. Completing it once unlocks the Bronze rating requirement and allows further progression in the chain.", x = 5 },
        [8888] = { e = 3, s = "c", r = "Requires prior Challenger run; moderate difficulty.", d = "Run Grimrail Depot repeatedly to improve your rating from Bronze to Silver. Pay attention to enemy patterns and positioning to reduce deaths and increase your overall performance score.", x = 5 },
        [8889] = { e = 4, s = "c", r = "Silver rating demands high skill and coordination.", d = "Advance to Gold by refining your team's strategy and minimizing errors during encounters. Consistent high-level play will push your rating up without needing to restart the dungeon frequently.", x = 5 },
        [8890] = { e = 5, s = "c", r = "Gold rating is extremely difficult for most groups.", d = "Achieving a Gold rating in Grimrail Depot unlocks the teleport ability for this zone. Ensure your group is skilled enough to handle the challenges before attempting the final rating tier.", x = 5 },
        [8891] = { e = 3, s = "c", r = "First run of UBRS; moderate difficulty.", d = "Start by queuing for Upper Blackrock Spire Challenge Mode with a group. You must complete the dungeon once to unlock the next tier, so do not stop after your first run.", x = 5 },
        [8892] = { e = 3, s = "c", r = "Requires prior Challenger run; moderate difficulty.", d = "Queue again until you achieve a Bronze rating or higher. This unlocks the Silver requirement, so keep playing immediately without resetting your progress.", x = 5 },
        [8893] = { e = 4, s = "c", r = "Silver rating demands high skill and coordination.", d = "Continue queuing to reach a Silver rating, then push for Gold. Each tier is account-wide and requires you to beat the previous rating threshold first.", x = 5 },
        [8894] = { e = 5, s = "c", r = "Gold rating is extremely difficult for most groups.", d = "Reach a Gold rating to unlock the teleport ability. This final tier grants a character unlock reward, so ensure your group composition is optimized for speed.", x = 5 },
        [8895] = { e = 5, s = "c", r = "Requires completing all other WotD Challenge Modes.", d = "Complete every Warlords of Draenor Challenge Mode dungeon at least once. You must visit each dungeon to track progress toward the main title.", x = 5 },
        [8897] = { e = 5, s = "c", r = "Requires completing all other WotD Challenge Modes.", d = "Queue for all WotD dungeons until you hit a Bronze rating across the board. This unlocks the Indomitable title and sets you up for higher tiers.", x = 5 },
        [8898] = { e = 4, s = "c", r = "Requires completing all WotD Challenge Mode dungeons.", d = "Push your ratings to Silver or better in every WotD dungeon. You will receive the Challenger's War Yeti mount upon reaching this milestone.", x = 5 },
        [8899] = { e = 4, s = "c", r = "Requires completing all WotD Challenge Mode dungeons.", d = "Achieve a Gold rating in all WotD Challenge Mode dungeons. This final tier unlocks a set of cosmetic weapon appearances for your characters.", x = 5 },
        [8919] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Complete the specific Talador storylines listed in the info field for your faction. These quests are account-wide and unlock the Treasure Map reward.", x = 5 },
        [8920] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Finish the required Talador storylines for your Alliance character. Ensure you complete all listed quests to claim the associated treasure map unlock.", x = 5 },
        [8921] = { e = 3, s = "s", r = "Single major questline event in Tanaan.", d = "Complete the Assault on the Dark Portal questline as an Alliance character. This is a one-time requirement tied specifically to your faction's intro content.", x = 5 },
        [8922] = { e = 3, s = "s", r = "Single major questline event in Tanaan.", d = "Finish the Assault on the Dark Portal questline as a Horde character. Do not confuse this with the Alliance version, as they are separate requirements.", x = 5 },
        [8923] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Complete the Gorgrond Alliance storyline quests listed in the info field. This is account-wide and unlocks a treasure map once finished.", x = 5 },
        [8924] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Finish the Gorgrond Horde storyline quests provided in the info data. Like the Alliance version, this is account-wide and rewards a treasure map.", x = 5 },
        [8925] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Work through the Spires of Arak Alliance quest chain listed below. This account-wide achievement unlocks the Spires of Arak treasure map upon completion.", x = 5 },
        [8926] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Complete the Spires of Arak Horde quest chain shown in the info. Finish these account-wide quests to unlock the corresponding treasure map.", x = 5 },
        [8927] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Finish the Nagrand Alliance storyline quests listed in the data. This account-wide achievement grants the Nagrand treasure map when all steps are done.", x = 5 },
        [8928] = { e = 3, s = "c", r = "Multiple zone quests and storylines to complete.", d = "Complete the Nagrand Horde quest chain provided in the info field. Once finished, this account-wide achievement unlocks the Nagrand treasure map.", x = 5 },
        [8929] = { e = 4, s = "c", r = "Requires specific raid mechanics and garrison setup.", d = "Defeat Flamebender Ka'graz without killing Aknor Steelbringer on Normal or higher after securing your garrison. This is a specific raid mechanic requirement for the follower reward.", x = 5 },
        [8930] = { e = 5, s = "s", r = "Strict timing requirement on a high-difficulty raid boss.", d = "Complete the Blast Furnace encounter in Blackrock Foundry by defeating all four Primal Elementalists within 10 seconds on Normal or higher. Timing is critical here to avoid failing the achievement.", x = 5 },
        [8932] = { e = 5, s = "s", r = "Requires defeating a raid boss on Mythic difficulty.", d = "Defeat Flamebender Ka'graz in Blackrock Foundry specifically on Mythic difficulty. Ensure you are running the correct difficulty setting before starting the encounter.", x = 5 },
        [8933] = { e = 1, s = "s", r = "Trivial action requiring only visiting the garrison.", d = "Relieve yourself in your garrison outhouse to complete this simple task. This is a personal achievement and does not require group assistance.", x = 5 },
        [8935] = { e = 4, s = "c", r = "Requires exploring all six Draenor zones completely.", d = "Explore all listed Draenor regions including Frostfire Ridge, Shadowmoon Valley, Gorgrond, Talador, Spires of Arak, and Nagrand. This is account-wide and requires visiting every zone.", x = 5 },
        [8937] = { e = 4, s = "c", r = "Requires finding and revealing many specific points in one zone.", d = "Explore Frostfire Ridge by revealing all covered areas on the world map. You must visit specific locations like Bladespire Citadel and Bloodmaul Stronghold to finish this part of the exploration achievement.", x = 5 },
        [8938] = { e = 4, s = "c", r = "Requires finding and revealing many specific points in one zone.", d = "Travel to Shadowmoon Valley and visit every named location listed in the info field. Ensure you clear all zones thoroughly, as missing a small area can delay completion until future updates.", x = 5 },
        [8939] = { e = 4, s = "c", r = "Requires finding and revealing many specific points in one zone.", d = "Visit Gorgrond and interact with each zone name to reveal the map. This is account-wide, so any character visiting these areas contributes to your progress.", x = 5 },
        [8940] = { e = 4, s = "c", r = "Requires finding and revealing many specific points in one zone.", d = "Explore Talador by visiting every listed location such as Shattrath City and Fort Wrynn. Since this is account-wide, you can use any character to finish the map quickly.", x = 5 },
        [8941] = { e = 4, s = "c", r = "Requires finding and revealing many specific points in one zone.", d = "Travel to Spires of Arak and visit all zones like Skettis and Sethekk Hollow. Make sure to check every corner, as some areas may be hidden behind terrain or fog.", x = 5 },
        [8942] = { e = 4, s = "c", r = "Requires finding and revealing many specific points in one zone.", d = "Go to Nagrand and interact with each location name including Oshu'gun and Telaar. This achievement is account-wide, so you can complete it from any zone in the region.", x = 5 },
        [8947] = { e = 4, s = "s", r = "Requires triggering a specific event during a raid fight.", d = "Run Highmaul Normal or higher and kill six Maggots before defeating The Butcher. Use ranged classes to kite maggot spawns while pulling adds away from the boss.", x = 5 },
        [8948] = { e = 5, s = "c", r = "High-skill Mythic raid boss with strict mechanics.", d = "Defeat Kargath Bladefist on Normal or higher without destroying any Fire Pillars. Avoid using area damage that hits pillars and coordinate with your group to protect them.", x = 5 },
        [8949] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Complete the Highmaul raid on Mythic difficulty to earn this title. Ensure your group is prepared for higher mechanics and better loot before attempting this run.", x = 5 },
        [8952] = { e = 5, s = "g", r = "Requires catching many rare drops before final boss.", d = "Catch twenty Falling Ashes during Blackhand in Blackrock Foundry Normal or higher. Use a ranged class to collect ashes while managing the fight's adds carefully.", x = 5 },
        [8956] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Defeat Beastlord Darmac on Mythic difficulty in Blackrock Foundry. Coordinate your group for high-level mechanics and ensure everyone is ready for increased damage output.", x = 5 },
        [8958] = { e = 5, s = "c", r = "Strict mechanic on Mythic raid boss requires perfect play.", d = "Fight the Twin Ogron in Highmaul Normal or higher while keeping their Disposition below 30%. Use crowd control to manage adds and avoid aggro spikes.", x = 5 },
        [8960] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Complete the Highmaul raid on Mythic difficulty to defeat The Butcher. Prepare your group for advanced mechanics and ensure everyone is geared appropriately for this challenge.", x = 5 },
        [8961] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Queue for Highmaul on Mythic difficulty and defeat Tectus. Ensure your group is prepared for the specific mechanics of this encounter to avoid wipes.", x = 5 },
        [8962] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Defeat Brackenspore in Highmaul on Mythic difficulty. Coordinate with your raid group to handle the boss's abilities efficiently during the run.", x = 5 },
        [8963] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Complete the Twin Ogron encounter in Highmaul on Mythic difficulty. Focus on managing the adds and mechanics specific to this fight.", x = 5 },
        [8964] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Defeat Ko'ragh in Highmaul on Mythic difficulty. Ensure your team is ready for the Felbreaker Lord mechanic during the encounter.", x = 5 },
        [8965] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Complete Imperator Mar'gok in Highmaul on Mythic difficulty to earn the Empire's Twilight title. This requires a full raid group and careful execution of all mechanics.", x = 5 },
        [8966] = { e = 5, s = "s", r = "Mythic difficulty requires high-level group coordination.", d = "Defeat Gruul in Blackrock Foundry on Mythic difficulty. Assemble a capable raid group and prepare for the intense mechanics of this boss fight.", x = 5 },
        [8967] = { e = 4, s = "s", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Oregorger in Blackrock Foundry on Mythic difficulty. Coordinate with your team to manage the adds and mechanics effectively during the encounter.", x = 5 },
        [8968] = { e = 4, s = "s", r = "Mythic raid bosses require group coordination and gear.", d = "Defeat Hans'gar and Franzok in Blackrock Foundry on Mythic difficulty. Ensure your raid is prepared for the specific mechanics of this boss fight.", x = 5 },
        [8969] = { e = 4, s = "s", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Operator Thogar in Blackrock Foundry on Mythic difficulty. Focus on managing the trains and mechanics specific to this encounter with your raid group.", x = 5 },
        [8970] = { e = 4, s = "s", r = "Mythic raid encounter requires group coordination and gear.", d = "Complete the Blast Furnace encounter in Blackrock Foundry on Mythic difficulty. Coordinate with your team to handle the mechanics of this fight successfully.", x = 5 },
        [8971] = { e = 4, s = "s", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Kromog in Blackrock Foundry on Mythic difficulty. Ensure your raid group is prepared for the specific mechanics of this boss encounter.", x = 5 },
        [8972] = { e = 4, s = "s", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat the Iron Maidens in Blackrock Foundry on Mythic difficulty. Coordinate with your team to manage the adds and mechanics of this fight effectively.", x = 5 },
        [8973] = { e = 4, s = "s", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Warlord Blackhand on Mythic difficulty to earn the title Ironbane; ensure your group is prepared for high-level mechanics. This achievement requires a full raid and cannot be completed solo or on lower difficulties.", x = 5 },
        [8974] = { e = 4, s = "s", r = "Highmaul Mythic+ style mechanic requires specific conditions.", d = "Destroy all eight Motes of Tectus within 10 seconds of each other in Highmaul on Normal or higher. Coordinate with your team to minimize downtime between kills, as missing the timer window will fail the achievement.", x = 5 },
        [8975] = { e = 3, s = "c", r = "Requires stacking debuff then defeating boss in Highmaul.", d = "Gain 15 stacks of Burning Infusion before defeating Brackenspore in Highmaul on Normal or higher. Monitor your debet counters carefully during the fight to ensure you meet the stack requirement before the boss dies.", x = 5 },
        [8976] = { e = 4, s = "s", r = "Highmaul Mythic+ style mechanic requires specific conditions.", d = "Defeat Ko'ragh in Highmaul while keeping Overflowing Energy orbs off the ground and players without Nullification Barrier. Use crowd control and movement strategies to prevent orbs from spawning or touching anyone, as this condition is strict.", x = 5 },
        [8977] = { e = 4, s = "c", r = "Requires empowering boss then defeating Imperator Mar'gok.", d = "Empower a Fortified Replicating Gorian Warmage before defeating Imperator Mar'gok in Highmaul on Normal or higher. Ensure the warmage is empowered correctly during the encounter, as failing to do so will reset progress.", x = 5 },
        [8978] = { e = 3, s = "c", r = "Requires collecting ores then defeating Gruul in BF.", d = "Collect three Pristine True Iron Ores before defeating Gruul in Blackrock Foundry on Normal or higher. Gather these ores from specific locations in the raid instance and bring them to the grinder before engaging Gruul.", x = 5 },
        [8979] = { e = 4, s = "c", r = "Requires defeating a raid boss on Normal difficulty.", d = "Deposit Volatile Ore in the Ore Grinder before defeating Oregorger in Blackrock Foundry on Normal or higher. Complete this step early in the raid run to avoid missing the opportunity if the boss dies prematurely.", x = 5 },
        [8980] = { e = 4, s = "c", r = "Requires specific mechanics during a raid encounter.", d = "Defeat Hans'gar and Franzok in Blackrock Foundry without any raid member being crushed by a stamping press. Position your group carefully to avoid standing near presses, as even one death will fail the achievement.", x = 5 },
        [8981] = { e = 4, s = "c", r = "Requires defeating a raid boss with specific prep.", d = "Cause Beastlord Darmac to mount each beast before defeating him in Blackrock Foundry on Normal or higher. Use crowd control and damage abilities to force mounts onto specific beasts, ensuring all three are mounted first.", x = 5 },
        [8982] = { e = 4, s = "s", r = "Requires defeating a specific rare spawn in raid.", d = "Engineer the demise of an Exulting Wind-Up Train Wrecker in Blackrock Foundry on Normal or higher. Coordinate with your team to trigger the train wreck mechanic efficiently, as timing is critical for success.", x = 5 },
        [8983] = { e = 4, s = "c", r = "Requires defeating a raid boss with mechanic timing.", d = "Defeat 10 Grasping Earth hands within 5 seconds before defeating Kromog in Blackrock Foundry on Normal or higher. Focus damage on the hands quickly to meet the time limit, as delays will cause failure.", x = 5 },
        [8984] = { e = 4, s = "s", r = "Requires precise timing to kill multiple mobs.", d = "Defeat the Iron Maidens within 10 seconds of each other in Blackrock Foundry on Normal or higher. Prioritize killing them rapidly during their spawn window, as exceeding the time limit will reset progress.", x = 5 },
        [8985] = { e = 5, s = "c", h = { 36012, 36013, 36014 }, r = "Requires completing all other Draenor raid achievements.", d = "Complete all listed Highmaul and Blackrock Foundry raid achievements to unlock the mount. Start with Highmaul since it unlocks the main title, then clear Blackrock Foundry wings in any order.", x = 5 },
        [8986] = { e = 4, s = "s", r = "Requires defeating multiple bosses in one wing.", d = "Finish Highmaul Wing 1 first by defeating Kargath Bladefist, The Butcher, and Brackenspore. This unlocks the next wing and is required for the main raid title.", x = 5 },
        [8987] = { e = 4, s = "s", r = "Requires defeating multiple bosses in one wing.", d = "Clear Highmaul Wing 2 bosses Tectus, Twin Ogron, and Ko'ragh immediately after completing Wing 1. Do not skip this section as it is mandatory for progressing to Mar'gok.", x = 5 },
        [8988] = { e = 4, s = "s", r = "Requires defeating the final raid boss of a wing.", d = "Defeat Imperator Mar'gok only after clearing Wings 1 and 2 of Highmaul. This final boss completes the entire Highmaul raid section and grants the main title.", x = 5 },
        [8989] = { e = 4, s = "s", r = "Requires defeating multiple bosses in one wing.", d = "Clear the Slagworks wing in Blackrock Foundry by defeating Gruul, Oregorger, and Blast Furnace. This is the first wing of the foundry raid and must be done before moving deeper.", x = 5 },
        [8990] = { e = 4, s = "s", r = "Requires defeating multiple bosses in one wing.", d = "Progress to the Black Forge wing after clearing Slagworks to defeat Hans'gar, Flamebender Ka'graz, and Kromog. Ensure you have a capable group for these mechanics-heavy encounters.", x = 5 },
        [8991] = { e = 4, s = "c", h = { 37136, 37137, 37138 }, r = "Requires defeating three specific raid bosses.", d = "Finish the Iron Assembly wing by defeating Beastlord Darmac, Operator Thogar, and the Iron Maidens. This is the penultimate wing before facing Blackhand in the final encounter.", x = 5 },
        [8992] = { e = 4, s = "s", r = "Defeating a final raid boss is difficult.", d = "Defeat Warlord Blackhand as the final step of the Blackrock Foundry raid. Ensure your group is prepared for his mechanics to secure this last achievement and complete the title.", x = 5 },
        [8993] = { e = 4, s = "c", r = "Requires specific mechanics and timing in raid.", d = "Run Bloodmaul Slag Mines on Heroic difficulty while keeping Calamity and Ruination alive until you kill Magmolatus. This is a specific condition that can be missed if not monitored carefully.", x = 5 },
        [8997] = { e = 2, s = "g", r = "Challenge mode run with rating requirement.", d = "Start Challenge Mode in Iron Docks to earn the Challenger title first. You must complete this before attempting any rating tiers, as it unlocks the subsequent Bronze achievement.", x = 5 },
        [8998] = { e = 2, s = "g", r = "Repeat runs to achieve higher rating.", d = "After unlocking Challenger, run Iron Docks Challenge Mode again aiming for a Bronze rating or higher. This step is account-wide and builds toward the Silver tier requirement.", x = 5 },
        [8999] = { e = 3, s = "g", r = "Higher rating requires more skilled runs.", d = "Once you have Bronze, repeat runs to achieve a Silver rating in Iron Docks Challenge Mode. Continue this progression chain until you reach Gold to complete the full legacy set.", x = 5 },
        [9000] = { e = 3, s = "g", r = "Gold rating demands significant skill/time.", d = "First complete Iron Docks: Silver to unlock the Challenge Mode, then run it with a team aiming for Gold rating. Be prepared for time-gating as this is account-wide and requires high-level coordination.", x = 5 },
        [9001] = { e = 2, s = "g", r = "Challenge mode run with rating requirement.", d = "Start by defeating The Everbloom Challenger on Heroic difficulty to unlock the Bronze tier. This is account-wide so coordinate with friends or use the group finder tool.", x = 5 },
        [9002] = { e = 2, s = "g", r = "Repeat runs to achieve higher rating.", d = "After unlocking the previous tier, run The Everbloom Challenge Mode again to achieve a Bronze rating or better. Progress through this chain sequentially as each step unlocks the next difficulty target.", x = 5 },
        [9003] = { e = 3, s = "g", r = "Higher rating requires more skilled runs.", d = "Complete the Challenge Mode with a Silver rating after securing Bronze. Maintain consistent performance as you advance toward Gold, noting that these are account-wide achievements requiring group play.", x = 5 },
        [9004] = { e = 3, s = "g", r = "Gold rating demands significant skill/time.", d = "Finish The Everbloom Challenge Mode with a Gold rating to unlock teleportation and complete the series. This final tier demands precise mechanics and coordination from your entire party.", x = 5 },
        [9005] = { e = 4, s = "c", r = "Requires specific boss mechanics and timing.", d = "Locate Gug'rokk in Bloodmaul Slag Mines on Heroic difficulty and defeat him alongside Croman the Barbarian after finding his sword. Ensure you have the prerequisite quest completed before attempting this encounter.", x = 5 },
        [9007] = { e = 4, s = "c", r = "Requires specific kill count and precise timing during a raid encounter.", d = "In Grimrail Depot on Heroic, abruptly remove 20 enemies from the Grimrail to defeat Nitrogg Thundertower. Verify you meet the specific criteria listed in the achievement info before starting the fight.", x = 5 },
        [9008] = { e = 4, s = "c", r = "Requires perfect avoidance of specific adds during a raid fight.", d = "Defeat Gug'rokk in Bloodmaul Slag Mines on Heroic without killing any Unstable Slag mobs. Focus your damage and crowd control away from these specific enemies to secure the kill condition.", x = 5 },
        [9017] = { e = 4, s = "c", r = "Requires precise mechanics management to prevent boss healing in a raid.", d = "In The Everbloom on Heroic, defeat Witherbark while preventing him from replenishing his Aqueous Energy. Monitor his energy bar closely during the fight to avoid triggering the reset mechanic.", x = 5 },
        [9018] = { e = 4, s = "c", r = "Requires specific rune setup and perfect timing during a raid encounter.", d = "Defeat Sadana Bloodfury in Shadowmoon Burial Grounds on Heroic using only the runes matching her active lunar cycle. Check the current moon phase and ensure your rune setup matches before engaging the boss.", x = 5 },
        [9023] = { e = 5, s = "c", r = "Extremely tight timing requirement to kill adds before boss fight starts.", d = "In Auchindoun on Heroic, defeat Soulbinder Nyami after killing 12 fallen Auchenai protectors within a 3-second window. Coordinate with your group to quickly clear these adds before pulling the main encounter.", x = 5 },
        [9024] = { e = 4, s = "c", r = "Requires destroying specific items before engaging the raid bosses.", d = "Destroy all Priceless Paraphernalia in Grimrail Depot on Heroic before defeating Railmaster Rocketspark and Borka the Brute. Complete this objective first as it is a strict prerequisite for the boss kill.", x = 5 },
        [9025] = { e = 4, s = "c", r = "Requires feeding a large number of specific mobs before boss fight.", d = "Start by feeding Bonemaw 25 Corpse Skitterlings on Normal difficulty before switching to Heroic. Ensure you have enough time to farm the skitterlings without rushing into the fight.", x = 5 },
        [9026] = { e = 5, s = "c", r = "Requires killing two specific adds within a very short time window.", d = "Defeat Ner'zhul on Heroic after killing two Ritual of Bones skeletons within five seconds of each other. Coordinate with your group to ensure rapid kills.", x = 5 },
        [9037] = { e = 4, s = "s", r = "Standard raid boss kill on Heroic difficulty requires preparation.", d = "Complete the Normal Bloodmaul Slag Mines dungeon first to unlock the Heroic version for this achievement. Focus on defeating Gug'rokk efficiently.", x = 5 },
        [9038] = { e = 4, s = "s", r = "Standard raid boss kill on Heroic difficulty requires preparation.", d = "Finish the Normal Iron Docks dungeon before attempting the Heroic version. Skulloc is the target boss in both difficulties.", x = 5 },
        [9039] = { e = 4, s = "s", r = "Standard raid boss kill on Heroic difficulty requires preparation.", d = "Clear Auchindoun on Normal difficulty first to unlock the Heroic version. Defeat Teron'gor as the final boss in the instance.", x = 5 },
        [9041] = { e = 4, s = "s", r = "Standard raid boss kill on Heroic difficulty requires preparation.", d = "Complete Shadowmoon Burial Grounds on Normal difficulty before moving to Heroic. Ner'zhul is the final boss you must defeat.", x = 5 },
        [9042] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Finish Upper Blackrock Spire on Normal difficulty first to unlock the Heroic version. Warlord Zaela is the target boss in both difficulties.", x = 5 },
        [9043] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Complete Grimrail Depot on Normal difficulty first to unlock the Heroic version. Defeat Skylord Tovra as the final boss in the instance.", x = 5 },
        [9044] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Finish The Everbloom on Normal difficulty first to unlock the Heroic version. Yalnu is the target boss you must defeat in both difficulties.", x = 5 },
        [9045] = { e = 4, s = "s", r = "Heroic UBRS with strict mechanic limit.", d = "Defeat Orebender Gor'ashan on Heroic Upper Blackrock Spire without letting him cast Thundering Cacophony four times. Use crowd control and damage mitigation strategies effectively.", x = 5 },
        [9046] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Complete Bloodmaul Slag Mines on Normal difficulty first to unlock the Heroic version. Defeat Gug'rokk efficiently in the Heroic instance.", x = 5 },
        [9047] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Finish Iron Docks on Normal difficulty first to unlock the Heroic version. Skulloc is the target boss you must defeat in both difficulties.", x = 5 },
        [9049] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Queue for Heroic Auchindoun with a group capable of handling Teron'gor. Ensure you are prepared for the final encounter mechanics before starting.", x = 5 },
        [9052] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Run Grimrail Depot on Heroic to defeat Skylord Tovra. This dungeon is time-gated and requires a coordinated group to complete efficiently.", x = 5 },
        [9053] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Defeat Yalnu in The Everbloom on Heroic difficulty. Be ready for the boss mechanics as this instance has specific encounter phases.", x = 5 },
        [9054] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Clear Shadowmoon Burial Grounds on Heroic to kill Ner'zhul. Coordinate with your group to manage the multiple adds during the fight.", x = 5 },
        [9055] = { e = 3, s = "s", r = "Standard heroic dungeon boss kill.", d = "Complete Upper Blackrock Spire on Heroic to defeat Warlord Zaela. Ensure you have a healer and DPS capable of handling the final boss.", x = 5 },
        [9056] = { e = 4, s = "g", r = "Requires killing 20 whelps in 10s.", d = "This achievement requires killing 20 Ragewing Whelps in 10 seconds during the Ragewing the Untamed fight on Heroic UBRS. It is extremely difficult and often requires a dedicated group focused solely on this mechanic.", x = 5 },
        [9057] = { e = 4, s = "c", r = "Requires killing a specific elite mob multiple times in a raid.", d = "Kill Warlord Zaela on Heroic UBRS while also defeating 5 Emberscale Ironflight before the boss dies. You must prioritize killing the Ironflight adds early in the encounter.", x = 5 },
        [9058] = { e = 3, s = "s", r = "Triggered by one event during the dungeon run.", d = "Trigger and complete the Leeroy Jenkins escort event on Heroic UBRS. This requires specific quest progression and timing to assist him with his shoulders.", x = 5 },
        [9060] = { e = 1, s = "s", r = "Automatic upon reaching level 100 before Shadowlands.", d = "Reach level 100 before entering Shadowlands to earn this legacy achievement. Once you enter the new expansion, this status becomes locked permanently.", x = 5 },
        [9069] = { e = 4, s = "c", r = "Requires defeating many specific trainers with a rare pet.", d = "Defeat all listed trainers in Pet Battles using an Elekk Plushie on your team. This is account-wide and requires visiting specific locations across Azeroth.", x = 5 },
        [9070] = { e = 3, s = "g", r = "Requires leveling a plushie to level 25.", d = "Level up your Elekk Plushie pet to level 25 in Pet Battles. Ensure you have enough resources to train it without hitting the level cap early.", x = 5 },
        [9071] = { e = 4, s = "c", r = "Requires collecting many specific decoded messages from an NPC.", d = "Collect all decoded messages from Blingtron 5000 for the Engineering achievement. This is account-wide and requires completing various engineering quests across multiple zones.", x = 5 },
        [9072] = { e = 3, s = "g", r = "Requires completing a storyline and reaching Exalted reputation.", d = "Complete the Terokk's Legacy storyline first, then grind reputation with Arakkoa Outcasts until Exalted to earn the title. This is account-wide and cannot be missed if you finish the main Draenor questline.", x = 5 },
        [9076] = { e = 2, s = "g", r = "Place 10 work orders at the Lumber Mill in Garrison.", d = "Place 10 Work Orders at the Lumber Mill in your garrison to unlock this step. You can queue these up quickly while doing other Garrison tasks, but ensure you have a lumber mill available.", x = 5 },
        [9077] = { e = 3, s = "g", r = "Place 50 work orders at the Lumber Mill in Garrison.", d = "After completing Choppin' Some Logs, place 50 more Work Orders at the Lumber Mill to progress. This is account-wide and rewards the Lumberjack title upon completion.", x = 5 },
        [9078] = { e = 3, s = "g", r = "Place 100 work orders at the Lumber Mill in Garrison.", d = "Place 100 Work Orders at the Lumber Mill after finishing Choppin' Some More Logs. This step is part of a chain and requires prior completion of earlier logging achievements.", x = 5 },
        [9080] = { e = 3, s = "g", r = "Place 100 work orders at the Lumber Mill in Garrison.", d = "Complete this by placing 100 Work Orders at the Lumber Mill, which also requires Choppin' Some More Logs first. It rewards the Timber Lord title and is account-wide.", x = 5 },
        [9081] = { e = 4, s = "c", r = "Requires killing specific mobs with a rare item in raid.", d = "Defeat Skulloc on Heroic Iron Docks using a single Iron Star to kill four Ogron Laborers without them being in combat beforehand. Coordinate with your group to time the star drop correctly.", x = 5 },
        [9082] = { e = 4, s = "c", r = "Heroic dungeon with strict no-damage mechanics.", d = "Defeat Skulloc on Heroic Iron Docks while ensuring no player takes damage from Cannon Barrage or Backdraft abilities. Use cover and positioning to avoid these specific mechanics during the fight.", x = 5 },
        [9083] = { e = 4, s = "c", r = "Heroic dungeon requiring specific boss alive condition.", d = "Defeat Fleshrender Nok'gar on Heroic Iron Docks while keeping Siegemaster Olugar, Pitwarden Gwarnok, and Champion Druna alive throughout the encounter. This requires careful management of adds and boss health.", x = 5 },
        [9087] = { e = 5, s = "g", r = "Grinding all primary professions to max level.", d = "Raise all primary professions to 100 skill points in the Draenor category for a total of 50 points. You must grind each profession individually, so plan your leveling route carefully.", x = 5 },
        [9094] = { e = 3, s = "c", r = "Multiple garrison building achievements required.", d = "Complete all listed garrison building achievements including Draftsman, Master Builder, and Keepin' Busy to earn the Architect title. Start with smaller buildings first as they unlock larger ones.", x = 5 },
        [9095] = { e = 2, s = "g", r = "Upgrading buildings to level 2 is quick.", d = "Upgrade all garrison buildings to level 2 by activating at least two small, two medium, and one large structure. This unlocks the next tier of building achievements in the chain.", x = 5 },
        [9096] = { e = 3, s = "g", r = "Upgrading remaining buildings to level 3.", d = "Upgrade all garrison buildings to level 3 after reaching Builder status. Ensure you have activated three small, two medium, and two large buildings before claiming this achievement.", x = 5 },
        [9097] = { e = 2, s = "c", r = "Building specific structures is straightforward.", d = "Construct all four preset garrison buildings immediately upon arrival. This is a one-time requirement that cannot be missed later.", x = 5 },
        [9098] = { e = 1, s = "s", r = "Upgrading one building to level 3 is easy.", d = "Upgrade any building to level 3 first, as this unlocks the next tier upgrade achievement in the chain.", x = 5 },
        [9099] = { e = 1, s = "s", r = "Upgrading one building to level 2 is trivial.", d = "Upgrade any building to level 2 before attempting level 3. This is a sequential step in the garrison progression.", x = 5 },
        [9100] = { e = 3, s = "g", r = "Garrison upgrade costs gold and time.", d = "Upgrade your entire garrison to tier 2 first. You must complete this before moving on to tier 3 upgrades.", x = 5 },
        [9101] = { e = 4, s = "g", r = "Tier 3 garrison requires significant investment.", d = "Upgrade your garrison to tier 3 after reaching tier 2. This is the final step in the main garrison upgrade chain.", x = 5 },
        [9102] = { e = 5, s = "c", r = "PvP victory with strict map control is hard.", d = "Coordinate with a group to control all Road of Glory points while killing the opposing commander. Solo attempts are highly unlikely to succeed.", x = 5 },
        [9103] = { e = 4, s = "g", r = "Requires killing many Alliance players in Ashran to loot specific items.", d = "Loot racial items from fallen Alliance players during Ashran battles. This is account-wide and requires active PvP participation.", x = 5 },
        [9104] = { e = 4, s = "g", r = "Requires killing many Horde players in Ashran to loot specific items.", d = "Loot racial items from fallen Horde players during Ashran battles. Like the other bounty hunter achievement, this is account-wide.", x = 5 },
        [9105] = { e = 3, s = "c", h = { 37620, 38944 }, r = "Needs completing events in multiple zones; some areas are difficult.", d = "Participate in every listed Ashran PvP event to complete the Tour of Duty. Missing an event makes this achievement missable.", x = 5 },
        [9106] = { e = 2, s = "s", r = "Just need to find and activate one specific book item.", d = "Find and activate a class-specific epic book dropped in Ashran. This is account-wide and requires you to be present when it drops.", x = 5 },
        [9107] = { e = 3, s = "g", r = "Requires recruiting 5 followers; takes time but is straightforward.", d = "Recruit five followers by completing recruitment quests at your garrison. You can recruit multiple followers simultaneously if available.", x = 5 },
        [9108] = { e = 3, s = "g", r = "Requires recruiting 10 followers; builds on previous step.", d = "Recruit ten followers total, which requires completing the previous five follower achievement first. Continue recruiting until you reach the limit.", x = 5 },
        [9109] = { e = 3, s = "g", r = "Requires recruiting 25 followers; takes longer but consistent effort.", d = "Recruit followers by completing quests and using the recruitment hall until you have 25 total. This is account-wide, so help friends if needed to speed up progress.", x = 5 },
        [9110] = { e = 4, s = "g", r = "Raising a single follower to level 40 is time-consuming.", d = "Focus on leveling one follower at a time through missions and dungeons until they reach level 40. Do not stop early, as this unlocks higher-level requirements later.", x = 5 },
        [9111] = { e = 4, s = "g", r = "Requires raising 10 followers to level 40; significant time investment.", d = "You must raise ten followers to the maximum level of 100, not just 40. Prioritize high-value followers for efficient leveling during your daily missions.", x = 5 },
        [9125] = { e = 3, s = "g", r = "Learning 20 blueprints takes time but is a steady grind.", d = "Open blueprints from mission rewards and the recruitment hall until you have learned twenty unique designs. Keep an eye on your collection tracker to avoid duplicates.", x = 5 },
        [9126] = { e = 3, s = "g", r = "Learning 40 blueprints; builds on previous step with more work.", d = "Continue learning blueprints from all sources until you reach forty total. This is a grind that requires consistent daily play and opening loot.", x = 5 },
        [9128] = { e = 3, s = "g", r = "Learning 60 blueprints; longest grind in the chain but consistent.", d = "Reach sixty learned blueprints by maximizing your mission rewards and checking the recruitment hall regularly. Avoid missing any rare blueprint drops during this phase.", x = 5 },
        [9129] = { e = 4, s = "g", r = "Grinding followers to level 40 takes significant time.", d = "Raise twenty followers to level 100, which is higher than the previous tier. Use high-level missions and dungeons to maximize experience gain efficiently.", x = 5 },
        [9130] = { e = 2, s = "s", r = "Recruiting a rare follower is easy once found.", d = "Recruit a Rare follower by completing specific world quests or events that have a chance to drop them. Check your recruitment hall frequently for new arrivals.", x = 5 },
        [9131] = { e = 4, s = "s", r = "Epic followers are extremely rare and hard to find.", d = "Find an Epic follower through rare world events or special missions. These are harder to find, so be patient and check the recruitment hall often.", x = 5 },
        [9132] = { e = 1, s = "s", r = "Visiting a friend's garrison is trivial.", d = "Visit a friend's garrison in Draenor and use the wave command to complete this social achievement. Coordinate with friends who have their garrison unlocked.", x = 5 },
        [9133] = { e = 2, s = "g", r = "Completing 10 missions is quick for most players.", d = "Complete ten garrison missions by doing daily quests and world events. Track your progress carefully as you may miss some if you stop playing for a while.", x = 5 },
        [9134] = { e = 2, s = "g", r = "Completing 50 missions is a moderate grind.", d = "Finish fifty total garrison missions by consistently completing daily objectives and special events. This is a long-term goal that requires regular engagement with the game.", x = 5 },
        [9138] = { e = 3, s = "g", r = "Completing 100 missions requires several hours of play.", d = "Start by queuing for any available mission slot and repeat daily. These are account-wide, so maximize your Garrison's production to speed up completion.", x = 5 },
        [9139] = { e = 4, s = "g", r = "Completing 500 missions is a long grind.", d = "Continue running standard missions after unlocking the next tier. Focus on high-yield slots to reach the 500 count efficiently.", x = 5 },
        [9140] = { e = 4, s = "g", r = "Completing 1000 missions is a very long grind.", d = "Keep filling all available mission slots every day until you hit 1000. This is a long-term grind requiring consistent daily play.", x = 5 },
        [9141] = { e = 3, s = "s", r = "Rare missions are uncommon but not impossible.", d = "Wait for the rare mission timer to activate and complete it immediately. Do not skip this step as it unlocks the next tier.", x = 5 },
        [9142] = { e = 4, s = "g", r = "Completing 50 rare missions is a difficult grind.", d = "Farm rare missions specifically after the first one is done. These appear randomly, so check your Garrison frequently for new opportunities.", x = 5 },
        [9143] = { e = 5, s = "g", r = "Completing 300 rare missions is an extreme grind.", d = "Prioritize rare mission slots over standard ones to reach 300 quickly. This requires patience as rare missions spawn infrequently.", x = 5 },
        [9145] = { e = 2, s = "s", r = "One-time mission completion.", d = "Look for the treasure icon on your mission queue and complete it first. It is a specific mission type distinct from standard patrols.", x = 5 },
        [9146] = { e = 2, s = "s", r = "One-time mission completion.", d = "Queue for patrol missions which appear regularly in your Garrison. Ensure you have enough resources to sustain continuous patrol runs.", x = 5 },
        [9147] = { e = 3, s = "c", h = { 37945, 37948 }, r = "Requires completing two other garrison missions.", d = "Unlock and complete all sub-achievements listed below this one first. This is a hub achievement that tracks your overall mission progress.", x = 5 },
        [9150] = { e = 2, s = "s", r = "One-time mission completion.", d = "Find exploration missions which often involve traveling to specific zones. These are distinct from standard patrol or treasure missions.", x = 5 },
        [9152] = { e = 3, s = "g", r = "Requires completing multiple invasions.", d = "Trigger an invasion event and defend your Garrison successfully. Invasions are time-limited events that require active participation during the window.", x = 5 },
        [9162] = { e = 4, s = "g", r = "Requires high-level invasion performance.", d = "Complete an invasion while maintaining a Bronze rating or higher. Avoid taking too much damage to ensure you meet the rating requirement.", x = 5 },
        [9164] = { e = 4, s = "g", r = "Requires higher-level invasion performance.", d = "Complete garrison invasions until you reach Silver rating. This unlocks the next tier and requires prior Bronze completion.", x = 5 },
        [9165] = { e = 5, s = "g", r = "Requires very high invasion performance.", d = "Finish more invasions to achieve Gold rating after unlocking Silver. Consistent high-level defense is key here.", x = 5 },
        [9167] = { e = 4, s = "g", r = "Requires completing ten invasions.", d = "Complete ten total garrison invasions to earn this title. It is account-wide and chains directly into the next invasion achievement.", x = 5 },
        [9168] = { e = 3, s = "s", r = "Win a single brawl event.", d = "Win any brawl during the Draenor campaign to unlock this legacy title. Ensure you have access to Brawler's Guild first.", x = 5 },
        [9169] = { e = 4, s = "g", r = "Requires reaching rank 4 in brawls.", d = "Reach Rank 4 with Bizmo's Brawlpub after winning your first brawl. This unlocks further progression and a specific item reward.", x = 5 },
        [9170] = { e = 5, s = "g", r = "Requires reaching high rank in brawls.", d = "Advance to Rank 8 at Bizmo's Brawlpub to earn the Brawler title. Continue grinding brawls until you hit this rank threshold.", x = 5 },
        [9171] = { e = 4, s = "c", h = { 37794, 37932, 37796 }, r = "Defeating multiple rare brawl bosses requires significant grinding.", d = "Defeat all listed rare brawl bosses during the campaign. This is account-wide and requires finding specific high-difficulty encounters.", x = 5 },
        [9172] = { e = 3, s = "s", r = "Requires unlocking and winning one specific brawl match.", d = "Win a brawl to start the Brawler's Guild legacy chain. This mirrors the standard version but tracks separately in some contexts.", x = 5 },
        [9173] = { e = 4, s = "g", r = "Reaching Rank 4 requires many wins in Brawl'gar Arena.", d = "Reach Rank 4 at Brawl'gar Arena after winning your first brawl. Note that this uses a different arena location than Bizmo's.", x = 5 },
        [9174] = { e = 5, s = "g", r = "Reaching Rank 8 is a very long grind requiring hundreds of wins.", d = "Progress to Rank 8 at Brawl'gar Arena for the Brawler title. Continue fighting in this specific arena until you reach rank eight.", x = 5 },
        [9175] = { e = 4, s = "c", h = { 37941, 37938, 37800 }, r = "Defeating multiple rare brawl bosses requires significant grinding.", d = "Defeat all rare brawl bosses listed for this account-wide achievement. Ensure you clear every single boss name mentioned in the info.", x = 5 },
        [9176] = { e = 4, s = "c", h = { 37803, 37806, 37809 }, r = "Defeating multiple Brawler's Guild bosses requires significant grinding.", d = "Defeat all standard Brawler's Guild bosses to complete your collection. This unlocks a special wrap item and requires full roster clearance.", x = 5 },
        [9177] = { e = 4, s = "c", h = { 37849, 37852, 37855 }, r = "Defeating multiple Brawler's Guild bosses requires significant grinding.", d = "Complete the Brawler's Guild campaign first to unlock this achievement. Defeat all listed bosses in any order; it is account-wide so play with friends if needed.", x = 5 },
        [9181] = { e = 4, s = "c", h = { 39591, 39592, 39593 }, r = "Completing multiple garrison invasions without damage is a grind.", d = "Build your garrison and complete every invasion without letting buildings fall. This requires high-level characters and good defense skills to protect structures during attacks.", x = 5 },
        [9203] = { e = 4, s = "g", r = "Successfully completing an invasion requires repeated attempts.", d = "Queue for the Shadow Council invasion event at your garrison. Ensure you have enough players to handle the elite enemies before the timer runs out.", x = 5 },
        [9204] = { e = 4, s = "g", r = "Successfully completing an invasion requires repeated attempts.", d = "Wait for the Ogre invasion event and defend your garrison. Bring a strong group capable of handling heavy hitters and tanking damage effectively.", x = 5 },
        [9205] = { e = 4, s = "g", r = "Successfully completing an invasion requires repeated attempts.", d = "Participate in the Iron Horde invasion when it appears. Focus on protecting key buildings while dealing with the numerous elite enemies spawned during the event.", x = 5 },
        [9206] = { e = 4, s = "g", r = "Successfully completing an invasion requires repeated attempts.", d = "Defend against the Shadowmoon Clan during their specific invasion event. Coordinate with your group to clear waves quickly before they destroy your garrison structures.", x = 5 },
        [9207] = { e = 3, s = "s", r = "Requires specific garrison invasion completion.", d = "Complete the Goren invasion by defending your garrison successfully. Prioritize keeping buildings intact while managing the unique mechanics of this specific enemy faction.", x = 5 },
        [9208] = { e = 3, s = "s", r = "Requires specific garrison invasion completion.", d = "Finish the Botani invasion without losing any structures. Use crowd control abilities to manage the large number of enemies that spawn during this event.", x = 5 },
        [9209] = { e = 4, s = "c", h = { 41501, 41496, 41497 }, r = "Needs gold rating on all invasions; high RNG.", d = "Earn Gold rating in every max-level garrison invasion to unlock this achievement. This requires mastering each faction's mechanics and maintaining high performance across all events.", x = 5 },
        [9210] = { e = 3, s = "s", r = "Requires visiting a friend's garrison.", d = "Visit a friend's garrison and use the /wave command to complete this social achievement. Ensure your friend has their garrison unlocked and ready for visitors.", x = 5 },
        [9211] = { e = 4, s = "g", r = "Grinding follower power to 625 takes time.", d = "Level up your followers until one reaches item level 625. Focus on equipping the best gear available and completing follower quests to increase their power efficiently.", x = 5 },
        [9212] = { e = 4, s = "g", r = "Grinding follower power to 650 takes time.", d = "Continue leveling your strongest follower to reach item level 650. This builds upon the previous achievement and requires obtaining higher-tier equipment for your followers.", x = 5 },
        [9213] = { e = 4, s = "g", r = "Requires leveling 10 followers to max power.", d = "Focus on raising your highest-level followers first to reach the 650 threshold quickly. This is an account-wide goal, so coordinate with friends if you have low-level characters.", x = 5 },
        [9214] = { e = 5, s = "c", h = { 37959 }, r = "Exalted rep requires massive PvP grind.", d = "Grind Wrynn's Vanguard reputation through daily quests and world events until you reach Exalted. Note that this requires a significant time investment as it is account-wide.", x = 5 },
        [9215] = { e = 5, s = "c", h = { 37961 }, r = "Exalted rep requires massive PvP grind.", d = "Similar to the previous achievement, grind Vol'jin's Spear reputation to Exalted status. You can speed this up by completing faction-specific daily quests and world events.", x = 5 },
        [9216] = { e = 4, s = "c", r = "Requires killing all rare Ashran mobs.", d = "These rare creatures in Ashran are often missed due to the chaotic PvP environment. Ensure you have a clear view of the battlefield and communicate with your team to track them down.", x = 5 },
        [9217] = { e = 4, s = "s", r = "Time-limited boss kill in PvP zone.", d = "Fangraal is a time-sensitive target that must be killed within eight minutes of spawning. Coordinate with your group to focus fire on him immediately upon his appearance.", x = 5 },
        [9218] = { e = 4, s = "g", r = "Requires looting 100 artifact fragments from players.", d = "Loot Artifact Fragments from enemy players during Ashran battles. This is a grind that requires consistent participation in PvP events and careful tracking of your progress.", x = 5 },
        [9219] = { e = 3, s = "g", r = "Grinding loot from PvP is moderate but tedious.", d = "Continue looting Artifact Fragments to reach the next tier of this achievement chain. Ensure you are actively engaging in PvP encounters to maximize your loot opportunities.", x = 5 },
        [9220] = { e = 4, s = "g", r = "Double the grind makes this significantly harder.", d = "Loot more Artifact Fragments to complete the third degree of this grind. This requires sustained engagement in Ashran battles and careful management of your inventory.", x = 5 },
        [9222] = { e = 4, s = "g", r = "Killing 5000 players is a long, tedious grind.", d = "Kill enemy players outside the Road of Glory in Ashran. Be mindful of the achievement tracker to ensure you are counting kills correctly and avoiding accidental misses.", x = 5 },
        [9223] = { e = 4, s = "s", r = "Requires specific raid conditions and zero deaths.", d = "Defeat Yalnu on Heroic difficulty without any Kirin Tor Battle-Mages dying. This requires careful coordination and strategy within The Everbloom dungeon to protect your mages.", x = 5 },
        [9224] = { e = 4, s = "c", h = { 39898, 39899, 39900 }, r = "Defeating all captains is a long checklist grind.", d = "Defeat all Alliance Captains in the Road of Glory during Ashran battles. Focus on these specific targets while engaging in PvP to ensure you do not miss any captains.", x = 5 },
        [9225] = { e = 4, s = "c", h = { 39914, 39915, 39916 }, r = "Defeating all captains is a long checklist grind.", d = "Defeat all Horde Captains in the Road of Glory during Ashran battles. Similar to the Alliance achievement, focus on these specific targets while engaging in PvP.", x = 5 },
        [9228] = { e = 4, s = "s", r = "Timing the kill requires specific PvP knowledge.", d = "Kill Elliott Van Rook immediately upon spawning to prevent him from casting Ice Block, as this is a time-gated objective that can be missed if you wait too long. Focus on securing the kill quickly rather than engaging in prolonged combat.", x = 5 },
        [9233] = { e = 5, s = "g", r = "Legacy achievement; points are no longer earnable.", d = "Accumulate 27,000 Conquest Points during Warlords of Draenor Season 1 by participating in Rated Battlegrounds and PvP activities. This legacy achievement is time-gated to the expansion's first season and cannot be earned later.", x = 5 },
        [9234] = { e = 5, s = "g", r = "Legacy achievement; points are no longer earnable.", d = "Earn 27,000 Conquest Points in Warlords of Draenor Season 1, which requires active participation in rated battlegrounds or arena matches during that specific timeframe. Ensure you are playing during the correct season as this is a legacy goal.", x = 5 },
        [9236] = { e = 5, s = "c", h = { 37997, 37998 }, r = "Legacy achievement; matches are no longer winnable.", d = "Win either 100 Arena (3v3) matches or 40 Rated Battleground matches during Warlords of Draenor Season 1 to unlock the Vicious Saddle mount reward. Choose the path that suits your preferred PvP format for efficiency.", x = 5 },
        [9238] = { e = 5, s = "c", h = { 38000, 38001 }, r = "Legacy achievement; matches are no longer winnable.", d = "Secure 100 Arena wins or 40 Rated Battleground victories in Warlords of Draenor Season 1, noting that this is a time-limited legacy achievement. Prioritize one activity over the other based on your team's strength to reach the goal faster.", x = 5 },
        [9243] = { e = 4, s = "g", r = "Grinding follower levels is tedious and time-consuming.", d = "Raise 20 followers' item level to 650 using your Garrison crafting and training facilities, as this account-wide goal benefits from upgrading multiple followers simultaneously. Focus on high-level dungeons or raids to quickly boost follower power levels.", x = 5 },
        [9244] = { e = 2, s = "s", r = "Requires a group but is a single invasion run.", d = "Complete a garrison invasion with exactly three players in your party to satisfy the group requirement for this achievement. Coordinate with friends or guild members to form the necessary trio before starting the invasion.", x = 5 },
        [9246] = { e = 3, s = "g", r = "Crafting 50 items takes several hours of garrison time.", d = "Craft 50 Epic items from Draenor by utilizing your Garrison's crafting stations and gathering resources efficiently. This account-wide goal can be accelerated by focusing on high-yield recipes that drop frequently in raids or dungeons.", x = 5 },
        [9248] = { e = 4, s = "g", r = "Grinding 5000 honorable kills is a long-term task.", d = "Accumulate 5,000 honorable kills in Draenor through PvP activities like Rated Battlegrounds and World PvP zones. Engage in frequent combat scenarios to quickly build up the required honor points for this milestone.", x = 5 },
        [9250] = { e = 3, s = "g", r = "Collecting 10 rings in one session requires luck and time.", d = "Collect 10 Blazing Rings during a single Firebird's Challenge flight session at Darkmoon Faire, ensuring you stay airborne long enough to gather them all. This is part of a chain and requires careful timing during the event.", x = 5 },
        [9251] = { e = 4, s = "g", r = "Collecting 25 rings is harder RNG than the previous step.", d = "Gather 25 Blazing Rings in one continuous Firebird's Challenge flight session, building upon your previous achievement of collecting 10 rings. Maintain focus on the challenge duration to maximize ring collection opportunities.", x = 5 },
        [9252] = { e = 5, s = "g", r = "Collecting 50 rings in one session is extremely difficult RNG.", d = "Collect 50 Blazing Rings during a single Firebird's Challenge flight session, which is the final step in the Darkmoon Faire flying sequence. Ensure you have completed the earlier ring collection achievements before attempting this goal.", x = 5 },
        [9255] = { e = 4, s = "c", h = { 38104, 38100, 38103 }, r = "Requires completing multiple Mythic raid bosses.", d = "Queue for Mythic raids in Gorgrond, starting with Gruul and Oregorger since they are often easier to clear first. Complete all listed raid bosses before the expansion ends as this is account-wide and time-gated by content removal.", x = 5 },
        [9256] = { e = 3, s = "c", r = "Releasing prisoners depends on PvP zone control and time.", d = "Travel to Ashran during PvP events to locate and release prisoners from the Horde Prison for Commander Jobby Shortsight and Marshal Andrea DeSousa. Coordinate with your faction's allies or wait for major battles to free these specific NPCs quickly.", x = 5 },
        [9257] = { e = 3, s = "c", r = "Releasing prisoners depends on PvP zone control and time.", d = "Visit the Alliance Prison in Ashran to rescue Warlord Jugan, General Lizzie Heartbane, and Marshal Lyrdrea Daybreaker during active PvP events. This requires being on the Alliance side and may need a group to handle the surrounding combat safely.", x = 5 },
        [9264] = { e = 3, s = "g", r = "Winning 2000 pet battles is a steady grind.", d = "Participate in random pet battles or queue for specific arenas to reach 2000 wins efficiently, as this is account-wide and does not require high-level pets. Avoid losing too many battles by using strong starter pets early on.", x = 5 },
        [9265] = { e = 4, s = "g", r = "Collecting 100k crystals takes significant time and luck.", d = "Farm Apexis Crystals from Mythic raids, dungeons, and world bosses in Draenor, focusing on high-yield sources like the Blackrock Foundry or Iron Docks. Save crystals for later use as they are needed for Garrison upgrades and cannot be easily obtained after the expansion.", x = 5 },
        [9389] = { e = 2, s = "s", r = "A single holiday event interaction.", d = "Obtain the holiday necklace from vendors during Love is in the Air events and complete the associated quest to unleash its power. This is a seasonal event achievement, so ensure you participate while the event is active to avoid missing it.", x = 5 },
        [9391] = { e = 4, s = "c", r = "Requires completing multiple heroic dungeons.", d = "Clear all Heroic dungeons in Draenor, including Upper Blackrock Spire and Skyreach, using a group of at least five players. Prioritize these before the expansion ends since they are account-wide and time-sensitive.", x = 5 },
        [9392] = { e = 2, s = "s", r = "Temporary buff achievable quickly in a zone.", d = "Gather friends or use party tools to stack Love Rays on yourself until you have 10 active simultaneously. This is part of a chain, so complete it quickly before moving to the next step in the Love is in the Air event.", x = 5 },
        [9393] = { e = 2, s = "s", r = "Temporary buff achievable quickly in a zone.", d = "Continue stacking Love Rays to reach 25 active simultaneously after completing the previous step. Coordinate with others or use buffs to maximize your count efficiently during the event window.", x = 5 },
        [9394] = { e = 2, s = "s", r = "Temporary buff achievable quickly in a zone.", d = "Reach 50 Love Rays by coordinating with many players or using group tools, then claim the True Love Prism toy reward. This is the final step in the chain and requires careful timing before the event ends.", x = 5 },
        [9396] = { e = 4, s = "c", r = "Requires completing multiple heroic dungeons.", d = "Complete all Heroic dungeon achievements listed under Draenor Dungeon Hero to unlock the Frostplains Battleboar mount. Ensure you finish these before the expansion concludes, as they are account-wide and time-gated.", x = 5 },
        [9400] = { e = 4, s = "g", r = "Requires killing multiple rare elites in a zone.", d = "Travel to Gorgrond to hunt rare elites like Biolante and Roardan the Sky Terror, which may require specific locations or conditions. Use a group to handle these dangerous encounters efficiently and avoid missing any due to their rarity.", x = 5 },
        [9401] = { e = 3, s = "g", r = "Requires collecting items from specific enemies.", d = "Farm Hardened Thornvines in Gorgrond by killing Shredders or looting them directly until you have twelve. This is account-wide, so any character can contribute to the total count quickly.", x = 5 },
        [9402] = { e = 3, s = "c", r = "Requires completing multiple arena challenges.", d = "First complete the Sparring Arena achievement to unlock the Proofs of Strength questline in Gorgrond. Then defeat the specific bosses listed in the achievement description to earn the required Gronnling Scale and other items.", x = 5 },
        [9405] = { e = 3, s = "g", r = "Requires completing a large number of work orders.", d = "Start your garrison immediately after reaching level 10 to begin completing Work Orders. Focus on simple tasks like chopping wood or mining ore to reach 125 completions as fast as possible.", x = 5 },
        [9406] = { e = 3, s = "g", r = "Requires completing a larger number of work orders.", d = "This achievement requires you to finish 250 Work Orders, so continue doing daily and weekly orders from the previous tier. You will unlock Level 3 profession blueprints upon completion, making this a good time to upgrade your garrison professions.", x = 5 },
        [9407] = { e = 3, s = "g", r = "Requires completing an even larger number of work orders.", d = "Reach 750 total Work Orders by continuing the grind from the previous tiers. Since this is account-wide, you can queue up multiple characters to speed up progress if you have them ready.", x = 5 },
        [9408] = { e = 5, s = "s", r = "Time-sensitive PvP event with high difficulty.", d = "Join a group familiar with Ashran mechanics and wait for Kronus to spawn during the Horde's turn. You must defeat him within eight minutes of his summoning, so coordinate your team's damage output carefully.", x = 5 },
        [9409] = { e = 3, s = "g", r = "Grinding archaeology skill points takes hours.", d = "Dig up archaeology sites across Draenor to gain skill points toward 700. This is account-wide, so dig with any character while leveling or completing other tasks to accumulate points efficiently.", x = 5 },
        [9410] = { e = 4, s = "c", h = { 38625 }, r = "Requires finding rare artifacts across Draenor.", d = "Restore all pristine Draenor Clans artifacts by digging up their corresponding archaeology sites and assembling the pieces. Once restored, display them in your garrison hall to complete this account-wide collection achievement.", x = 5 },
        [9411] = { e = 4, s = "c", h = { 38637 }, r = "Requires finding rare Ogre artifacts.", d = "Focus on Ogre-themed archaeology sites to restore and display all required Ogre artifacts in your garrison. Ensure you have enough space in your hall before restoring each item to avoid clutter issues.", x = 5 },
        [9412] = { e = 4, s = "c", h = { 38649 }, r = "Requires finding rare Arakkoa artifacts.", d = "Locate and dig up Arakkoa archaeology sites to restore the specific artifacts listed for this achievement. Display them in your garrison once restored, noting that some may require rare drops from specific zones.", x = 5 },
        [9413] = { e = 3, s = "c", r = "Finding scattered artifacts takes moderate time.", d = "Dig up various Draenor Clans archaeology sites to discover the listed artifacts. Once discovered, you must restore and display them in your garrison hall, which may take time depending on drop rates.", x = 5 },
        [9414] = { e = 3, s = "c", r = "Finding scattered Ogre artifacts takes hours.", d = "Target Ogre-themed archaeology sites to discover the required artifacts for this achievement. After discovery, restore and display them in your garrison, keeping track of progress as some items are rare drops.", x = 5 },
        [9415] = { e = 3, s = "c", r = "Finding scattered Arakkoa artifacts takes hours.", d = "Start Archaeology and dig at Skettis sites to find Arakkoa artifacts; display them in your museum to complete this account-wide goal. Note that some items are rare drops or require specific excavation zones.", x = 5 },
        [9419] = { e = 4, s = "c", h = { 38725 }, r = "Requires finding all rare Draenor artifacts.", d = "Excavate all Draenor artifacts from various zones and upgrade them to pristine versions for your museum display. This is account-wide, so coordinate with friends if you need help finding rare pieces quickly.", x = 5 },
        [9422] = { e = 4, s = "g", r = "Finding 30 rare artifacts is a long grind.", d = "Focus on digging up rare artifacts across all excavation sites; aim for the 'It Belongs in a Museum!' achievement first as it unlocks this one. Keep an eye on your collection to ensure no rare items are missed.", x = 5 },
        [9423] = { e = 2, s = "s", r = "Killing world bosses in Gorgrond takes hours.", d = "Travel to Gorgrond and defeat Tarlna the Ageless and Drov the Ruiner world bosses. These spawns appear regularly, so check the map or use a tracking tool to find them efficiently.", x = 5 },
        [9425] = { e = 2, s = "s", r = "Killing Rukhmar in Spires of Arak takes hours.", d = "Head to Spires of Arak and defeat Rukhmar, who appears as a world boss in specific zones. Time your visit when he respawns to avoid wasting time waiting for his next appearance.", x = 5 },
        [9426] = { e = 3, s = "s", r = "Requires specific event outfit and boss kill.", d = "Buy the Day of the Dead contender outfit and hunt contenders during the event window. Defeat one contender to unlock this achievement before moving on to the next in the chain.", x = 5 },
        [9427] = { e = 3, s = "g", r = "Grinding 20 kills in a specific outfit takes moderate time.", d = "Wear your contender outfit and defeat twenty contenders while the Day of the Dead event is active. This requires persistence as contenders may be elusive or require specific conditions to spawn.", x = 5 },
        [9428] = { e = 3, s = "g", r = "Grinding 50 kills is longer but same activity as previous.", d = "Continue hunting contenders with your outfit equipped until you reach fifty kills for this account-wide achievement. Plan your sessions around event timers to maximize progress without interruption.", x = 5 },
        [9429] = { e = 3, s = "c", h = { 38803 }, r = "Quests add complexity; grinding work orders is moderate effort.", d = "Place seventy-five work orders at the Lumber Mill in your garrison and complete the associated quests. Ensure you have enough resources and time to manage the mill's production queue effectively.", x = 5 },
        [9432] = { e = 3, s = "s", r = "Requires finding specific items and timing them correctly.", d = "Visit the Shadowmoon Enclave and activate all three incantations from Forbidden Tomes simultaneously. Check each tome's location and ensure their effects are active before completing the quest.", x = 5 },
        [9433] = { e = 3, s = "s", r = "Specific boss fight with a mechanic restriction.", d = "Defeat Kenos in the Shadowmoon Enclave without using Void Implosion or killing any Coalesced Void Fragments. Use stealth or kiting tactics to avoid triggering these conditions during the fight.", x = 5 },
        [9434] = { e = 3, s = "s", r = "Requires specific condition during a void encounter.", d = "Enter the void realm in the Shadowmoon Enclave while possessing Power Overwhelming to complete this objective. Coordinate with group members to maintain the buff and reach the required zone safely.", x = 5 },
        [9435] = { e = 3, s = "s", r = "Maintain buff for 10 minutes in a specific zone.", d = "Start by destroying Sargerei supplies in Socrethar's Rise to gain a buff, then maintain that effect for ten minutes without interruption. This is time-gated and requires focus during the fight, so plan your rotation carefully to avoid losing the debuff.", x = 5 },
        [9436] = { e = 2, s = "g", r = "Destroying 5 items is quick compared to other grinds.", d = "Locate and destroy five Draenic Darkstones in Socrethar's Rise as quickly as possible since this is account-wide and cannot be missed later. Focus on one instance per character if needed to ensure all accounts complete the objective efficiently.", x = 5 },
        [9437] = { e = 3, s = "s", r = "Defeating a specific boss in a raid-like instance.", d = "Defeat Demidos, Devourer of Lights in Socrethar's Rise using a capable group or solo if your character is high enough level. Ensure you are prepared for this boss fight as it may require specific tactics or gear depending on your current progression.", x = 5 },
        [9450] = { e = 3, s = "g", r = "Grinding 50 traps is moderate time investment.", d = "Begin by trapping creatures to place fifty Work Orders at the Barn in your garrison, starting with easier targets first. This is account-wide and part of a chain, so track your progress carefully to avoid missing out on subsequent rewards.", x = 5 },
        [9451] = { e = 3, s = "g", r = "Grinding 250 traps takes longer but same activity.", d = "Continue trapping creatures to reach two hundred fifty Work Orders after completing the previous achievement. Maintain steady progress by focusing on high-yield areas or using efficient trapping methods to speed up completion.", x = 5 },
        [9452] = { e = 3, s = "g", r = "Grinding 500 traps is the longest grind in this list.", d = "Reach five hundred Work Orders by consistently trapping creatures in the world, building on your earlier efforts. This final step requires significant time investment, so plan sessions around available downtime to finish efficiently.", x = 5 },
        [9453] = { e = 2, s = "g", r = "Grinding 500 stones is a moderate solo task.", d = "Mine five hundred Draenic Stones from any location in Draenor, prioritizing nodes near your current zone for convenience. This is account-wide and unlocks a blueprint, so ensure you have enough mining skill to collect them effectively.", x = 5 },
        [9454] = { e = 2, s = "g", r = "Grinding 500 seeds is a moderate solo task.", d = "Gather five hundred Draenic Seeds through herbalism across Draenor, focusing on dense herb patches for faster collection. Like other gathering achievements, this is account-wide, so coordinate with friends if possible to speed up completion.", x = 5 },
        [9455] = { e = 3, s = "g", r = "Fishing 100 specific fish takes several hours.", d = "Catch one hundred Enormous Fire Ammonite fish in Draenor waters, targeting known spawning areas for efficiency. This is account-wide and requires patience, as these fish may be rare or require specific fishing skill levels.", x = 5 },
        [9456] = { e = 3, s = "g", r = "Fishing 100 specific eels takes several hours.", d = "Fish up one hundred Enormous Abyssal Gulper Eels from suitable locations in Draenor, checking spawn rates to maximize your catch rate. As with other fishing achievements, this is account-wide and benefits from dedicated sessions near popular fishing spots.", x = 5 },
        [9457] = { e = 3, s = "g", r = "Fishing 100 specific fish takes several hours.", d = "Catch one hundred Enormous Blackwater Whiptail fish by visiting appropriate zones in Draenor where they commonly appear. Be prepared for potential time gating if spawns are limited, so plan your fishing routes accordingly to avoid delays.", x = 5 },
        [9458] = { e = 3, s = "g", r = "Fishing 100 specific fish takes several hours.", d = "Gather one hundred Enormous Blind Lake Sturgeon from designated areas in Draenor, focusing on lakes or rivers with high spawn rates. This achievement is account-wide and requires consistent effort over time to complete successfully.", x = 5 },
        [9459] = { e = 3, s = "g", r = "Fishing 100 specific fish takes several hours.", d = "Fish Enormous Fat Sleeper in Draenor waters until you hit 100. This is account-wide so any character can contribute. No rare drops or time gates apply here.", x = 5 },
        [9460] = { e = 3, s = "g", r = "Fishing 100 specific fish takes several hours.", d = "Target the Enormous Jawless Skulker fish found in Draenor zones. Farm these consistently as the achievement tracks account-wide progress. Avoid missing content by checking your fishing log regularly.", x = 5 },
        [9461] = { e = 3, s = "g", r = "Fishing 100 specific fish takes several hours.", d = "Complete all listed Angler achievements to unlock the Fishing Shack and Level 3 Blueprint. Ensure you have access to Draenor zones before starting this chain. It is account-wide so coordinate with friends if needed.", x = 5 },
        [9462] = { e = 4, s = "c", r = "Requires completing all sub-achievements including fishing grinds.", d = "Win 150 pet battles specifically within Draenor zones to earn this title. You can use any pet and battle mode available in the region. This tracks account-wide so multiple characters help speed up progress.", x = 5 },
        [9463] = { e = 2, s = "g", r = "Winning 150 battles is a moderate solo task.", d = "Grind primary professions in Draenor until you gain 100 skill points to unlock the Artisan title. Focus on one profession at a time for efficiency. This is account-wide so any character's progress counts.", x = 5 },
        [9464] = { e = 3, s = "g", r = "Gaining 100 skill points requires significant grinding.", d = "Focus on one primary profession and grind skill points specifically in Draenor zones. Avoid leveling up your character too much before starting to ensure you gain the required points efficiently.", x = 5 },
        [9468] = { e = 2, s = "g", r = "Grinding salvage from missions takes under an hour.", d = "Open 100 pieces of Salvage obtained from Garrison missions in Draenor. Ensure you have an active Garrison and run missions frequently. This achievement is account-wide so multiple characters can help reach the goal.", x = 5 },
        [9469] = { e = 3, s = "g", r = "Reputation grind is moderate but requires time.", d = "Earn Exalted reputation with the Arakkoa Outcasts by completing quests and turning in items. Farm this efficiently as it is account-wide. Be aware that reputation gains may be slow without daily quest completion.", x = 5 },
        [9470] = { e = 3, s = "g", r = "Reputation grind is moderate but requires time.", d = "Reach Exalted status with the Council of Exarchs through various Draenor activities. This requires consistent effort and is account-wide so friends can assist. Check your reputation tracker often to avoid missing out on rewards.", x = 5 },
        [9471] = { e = 3, s = "g", r = "Reputation grind is moderate but requires time.", d = "Gain Exalted reputation with the Frostwolf Orcs by doing world quests and turning in items. This is account-wide so you can farm it quickly with multiple characters. Ensure you are in Draenor zones to gain progress.", x = 5 },
        [9472] = { e = 3, s = "g", r = "Reputation grind is moderate but requires time.", d = "Earn Exalted status with the Steamwheedle Preservation Society via quests and world events. This achievement is account-wide so coordinate with friends for faster completion. Avoid missing content by staying active in Draenor zones.", x = 5 },
        [9473] = { e = 4, s = "g", r = "Ashran PvP rep is hard due to activity requirements.", d = "Achieve Exalted reputation with Vol'jin's Spear during Ashran battles and events. This is account-wide so multiple characters can contribute to the goal. Be prepared for PvP action as this requires active participation in Ashran.", x = 5 },
        [9474] = { e = 4, s = "g", r = "Ashran PvP rep is hard due to activity requirements.", d = "Focus on Ashran PvP battles to earn Wrynn's Vanguard reputation. This is a group activity requiring active participation in the zone.", x = 5 },
        [9475] = { e = 3, s = "g", r = "Reputation grind is moderate but requires time.", d = "Farm Laughing Skull Orcs reputation through world quests and dungeons in Draenor. Complete daily objectives for efficient gains.", x = 5 },
        [9476] = { e = 3, s = "g", r = "Reputation grind is moderate but requires time.", d = "Earn Sha'tari Defense reputation by completing specific faction quests and turning in materials. Check your quest log for daily tasks.", x = 5 },
        [9477] = { e = 3, s = "c", r = "Requires Exalted with three specific Draenor factions.", d = "Unlock Exalted with any three Draenor Horde factions to complete this account-wide achievement. Prioritize the easiest factions first.", x = 5 },
        [9478] = { e = 3, s = "c", r = "Requires Exalted with three specific Draenor factions.", d = "Unlock Exalted with any three Draenor Alliance factions to complete this account-wide achievement. Focus on high-yield reputation sources.", x = 5 },
        [9479] = { e = 2, s = "s", r = "Single event to break an egg in a zone.", d = "Travel to Darktide Roost and locate the Giant Rylak Egg to break it. Ensure you are in the correct zone before starting.", x = 5 },
        [9481] = { e = 2, s = "g", r = "Timed kill count in a specific zone.", d = "Drive the Rylakinator-3000 in Darktide Roost and defeat ten Darkwing Adolescents within three minutes. Start immediately upon mounting the vehicle.", x = 5 },
        [9483] = { e = 2, s = "s", r = "Single bait-and-kill event with no timer.", d = "Use the Rylakinator-3000 to bait a Darkwing Matron into ambushing you in Darktide Roost. Position yourself near her spawn point.", x = 5 },
        [9486] = { e = 5, s = "c", r = "Extremely tight RNG window for multiple runes.", d = "Activate twelve different Fel Runes in Shattrath City as quickly as possible while avoiding damage. Practice the sequence beforehand if needed.", x = 5 },
        [9487] = { e = 3, s = "g", r = "Gold farming is steady but requires time.", d = "Grind gold in Draenor by selling loot and completing vendor quests until you reach ten thousand total. Use your garrison for passive income.", x = 5 },
        [9491] = { e = 3, s = "c", r = "Multiple distinct campaign chapters to complete.", d = "Complete all listed Garrison Campaign chapters for the Alliance faction. Follow the quest chain order to unlock subsequent chapters.", x = 5 },
        [9492] = { e = 3, s = "c", r = "Multiple distinct campaign chapters to complete.", d = "Complete all listed Garrison Campaign chapters for the Horde faction. Ensure you have the correct faction reputation before starting.", x = 5 },
        [9493] = { e = 4, s = "s", r = "High-skill timed jump on a specific boss.", d = "Practice jumping over Archmage Sol's firebloom rings on Heroic difficulty, focusing on timing your movement within 5 seconds of each explosion. This is a solo challenge that requires precise positioning and may require multiple attempts to clear all five jumps.", x = 5 },
        [9494] = { e = 2, s = "g", r = "Recruiting followers is quick and steady.", d = "Recruit followers by completing garrison quests and defeating enemies in the world; this achievement tracks total recruits across your account. Ensure you have enough gold and reputation to afford follower recruitment costs as you progress toward the 40-follower goal.", x = 5 },
        [9495] = { e = 3, s = "g", r = "Collecting bones from PvP across zones.", d = "Collect Broken Bones from defeated players in PvP zones across Draenor, which requires participating in battlegrounds or world PvP. This is a grind that depends on other players being present, so it may take significant time to gather enough bones.", x = 5 },
        [9497] = { e = 2, s = "g", r = "Looting waystones is straightforward farming.", d = "Loot Ogre Waystones dropped by enemies in the world; these items are not rare but require extensive exploration and combat. Focus on high-level zones where ogres spawn frequently to speed up collection of the 500 required waystones.", x = 5 },
        [9498] = { e = 1, s = "s", r = "Simple interaction with one bodyguard.", d = "Become a Personal Wingman with one Barracks Bodyguard by completing specific quests or interactions related to that unit. This is the first step in a chain, so complete it before moving on to the full Wingmen achievement.", x = 5 },
        [9499] = { e = 2, s = "c", r = "Requires interacting with all bodyguards.", d = "Unlock all Barracks Bodyguards as Personal Wingmen by progressing through the previous steps and interacting with each unit individually. This achievement requires account-wide progress and may involve multiple characters or extensive garrison management.", x = 5 },
        [9500] = { e = 2, s = "g", r = "Grinding skill points is fast and easy.", d = "Gain cooking skill points in Draenor recipes by cooking meals that use local ingredients; focus on high-level zones for better drops. Track your progress carefully as you need exactly 100 skill points in this specific category.", x = 5 },
        [9501] = { e = 3, s = "c", r = "Cooking 20 recipes takes a few hours total.", d = "Cook 20 different Draenor recipes listed in the achievement description, which includes various meats and seafood from the region. Use multiple characters or alts to speed up recipe discovery if you lack time to try every dish manually.", x = 5 },
        [9502] = { e = 3, s = "c", r = "Sampling foods is quick but requires travel.", d = "Sample Draenor foods by eating meals cooked by yourself or others; this tracks unique food types consumed rather than quantity. Visit garrison kitchens or trade with other players to access the full list of available dishes.", x = 5 },
        [9503] = { e = 2, s = "g", r = "Fishing skill points are gained very quickly.", d = "Gain fishing skill points in Draenor zones by catching local fish species; focus on areas known for high-level aquatic life. This grind can be done solo and benefits from using a fishing rod with higher stats.", x = 5 },
        [9505] = { e = 4, s = "g", r = "700 First Aid points requires significant time.", d = "Earn 700 first aid skill points by bandaging wounds in the world or completing quests that reward healing items. This is a legacy achievement requiring substantial time investment, so consider using alts to accelerate progress.", x = 5 },
        [9506] = { e = 4, s = "c", h = { 39242 }, r = "Cooking points are the slowest grind here.", d = "Accumulate 700 skill points each in Fishing, First Aid, Cooking, and Archaeology by engaging with these professions regularly. This account-wide achievement benefits from multiple characters grinding different skills simultaneously.", x = 5 },
        [9507] = { e = 3, s = "g", r = "Grinding two professions is moderate effort.", d = "Start this account-wide achievement by leveling two primary professions to max skill in Draenor. Focus on gathering nodes there to gain the required points efficiently.", x = 5 },
        [9508] = { e = 4, s = "c", h = { 39293 }, r = "Completing all Nemesis quests takes many days.", d = "Complete all Nemesis quests at Gladiator's Sanctum and finish Fight, Kill, Salute! at Highmaul Coliseum. Ensure you are Horde as this requires specific faction content.", x = 5 },
        [9509] = { e = 3, s = "s", r = "Single quest is moderate difficulty.", d = "Head to Gladiator's Sanctum in the Garrison to complete the Nemesis: Draenei Destroyer quest for your title.", x = 5 },
        [9510] = { e = 3, s = "s", r = "Single quest is moderate difficulty.", d = "Locate and finish the Nemesis: Dwarfstalker quest at Gladiator's Sanctum to earn the associated title.", x = 5 },
        [9511] = { e = 3, s = "s", r = "Single quest is moderate difficulty.", d = "Complete the Nemesis: Gnomebane quest available at Gladiator's Sanctum within the Garrison hub.", x = 5 },
        [9512] = { e = 3, s = "s", r = "Single quest is moderate difficulty.", d = "Finish the Nemesis: Manslayer quest at Gladiator's Sanctum to claim your reward title.", x = 5 },
        [9513] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Complete the Nemesis: Scourge of the Kaldorei quest at Gladiator's Sanctum for your faction-specific title.", x = 5 },
        [9514] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Finish the Nemesis: Terror of the Tushui quest at Gladiator's Sanctum to earn the corresponding title.", x = 5 },
        [9515] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Complete the Nemesis: Worgen Hunter quest at Gladiator's Sanctum within the Garrison area.", x = 5 },
        [9516] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Finish the Nemesis: Slayer of Sin'dorei quest at Gladiator's Sanctum to obtain your title.", x = 5 },
        [9517] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Complete the Nemesis: Death Stalker quest at Gladiator's Sanctum to earn the Death Stalker title.", x = 5 },
        [9518] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Finish the Nemesis: Killer of Kezan quest at Gladiator's Sanctum to claim your unique title.", x = 5 },
        [9519] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Complete the Nemesis: Orcslayer quest at the Gladiator's Sanctum to earn your title. Ensure you have access to the Garrison and the specific quest giver before starting.", x = 5 },
        [9520] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Finish the Nemesis: Huojin's Fall quest located at the Gladiator's Sanctum for your title reward. This is a straightforward completion task within the Garrison interface.", x = 5 },
        [9521] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Complete the Nemesis: The Butcher quest at the Gladiator's Sanctum to claim your title. Verify you are in the correct Garrison zone before accepting the objective.", x = 5 },
        [9522] = { e = 2, s = "s", r = "One-time quest completion at a specific location.", d = "Finish the Nemesis: Troll Hunter quest at the Gladiator's Sanctum to obtain your title. This achievement requires accessing the specific Garrison quest line.", x = 5 },
        [9523] = { e = 4, s = "g", r = "Requires completing 50 separate patrol missions.", d = "Complete fifty garrison patrol missions by sending your troops out regularly. Note that this is account-wide and unlocks the Barracks at Level 3.", x = 5 },
        [9524] = { e = 4, s = "g", r = "Requires completing 50 separate treasure missions.", d = "Finish fifty garrison treasure missions to earn your title. This achievement tracks across all characters on your account once started.", x = 5 },
        [9526] = { e = 2, s = "c", r = "Train 6 mounts; requires prior capture quests.", d = "Fully train all six mounts at your Stables by completing the required training quests. Ensure you have unlocked the Stables and completed the intro to husbandry first.", x = 5 },
        [9527] = { e = 3, s = "g", r = "Craft/use items; grind scales with count.", d = "Use at least six different inventions at your Workshop to complete this achievement. You must craft or use items like the Robo-Rooster and Sticky Grenade Launcher.", x = 5 },
        [9528] = { e = 3, s = "c", r = "Complete specific storyline quests in zone.", d = "Complete the Shadowmoon Valley storyline involving Gul'dan to earn these points. This is an account-wide achievement tied to specific Alliance quests in Draenor.", x = 5 },
        [9529] = { e = 3, s = "c", r = "Complete specific storyline quests in zone.", d = "Finish the Frostfire Ridge storyline featuring Gul'dan for your points. Ensure you are on the Horde side and have progressed through the relevant Draenor content.", x = 5 },
        [9530] = { e = 2, s = "s", r = "Find one item; trivial search.", d = "Locate Bodrick Grey's tattered journal page inside Bloodmaul Stronghold to complete this part. Search thoroughly as these items can be hidden in hard-to-reach spots.", x = 5 },
        [9531] = { e = 2, s = "s", r = "Find one item; trivial search.", d = "Find Shadow Hunter Bwu'ja's tattered journal page within Bloodmaul Stronghold. Be prepared to explore the entire stronghold, including upper levels, to locate this item.", x = 5 },
        [9533] = { e = 3, s = "g", r = "Free 50 slaves; grind scales with count.", d = "Head straight to Bloodmaul Stronghold and free slaves via the main questline until you hit 50. This is account-wide, so any character can finish it for everyone.", x = 5 },
        [9534] = { e = 2, s = "s", r = "Eat specific food combo; trivial.", d = "Eat all three specific food items simultaneously in Bloodmaul Stronghold while standing still to trigger the buff. Ensure you have access to the vendor selling these unique consumables first.", x = 5 },
        [9535] = { e = 3, s = "g", r = "Punt 100 eggs; grind scales with count.", d = "Go to Magnarok and punt Goren Eggs using your ranged ability until you reach 100 kills. This is account-wide, so one character can complete it for the whole group.", x = 5 },
        [9536] = { e = 3, s = "g", r = "Defeat 20 slagged enemies; grind scales.", d = "Use goren acid on enemies in Magnarok before killing them to slag them, then defeat 20 such targets. You must use the specific acid ability on each enemy before they die.", x = 5 },
        [9537] = { e = 2, s = "s", r = "Complete quest without specific item.", d = "Complete Rekindling an Old Flame without using a Kindling Flame item to rekindle the essence. Avoid picking up or using that specific quest item during the entire process.", x = 5 },
        [9538] = { e = 2, s = "c", r = "Complete 6 capture quests; checklist.", d = "Equip the Black Claw of Sethe and defeat all six listed mount-in-training targets in Nagrand. You must carry the claw while killing each unique enemy type.", x = 5 },
        [9539] = { e = 4, s = "g", r = "Grinding 6 of each specific enemy while holding a quest item.", d = "Equip the Garn-Tooth Necklace and repeat the same process as Advanced Husbandry, defeating all six specific targets in Nagrand. This grants you the Stable Master title upon completion.", x = 5 },
        [9540] = { e = 4, s = "g", r = "Grinding 6 of each specific enemy while holding a different quest item.", d = "Travel to Mok'gol Watchpost and kill the elite Warsong named Karosh Blackwind. Ensure you are in the correct zone and targeting the rare NPC specifically.", x = 5 },
        [9541] = { e = 3, s = "s", r = "Killing four specific rare NPCs in Nagrand.", d = "Travel to Nagrand and locate Mok'gol Watchpost to find the elite Warsong NPC. This is an account-wide achievement, so coordinate with friends or wait for a rare spawn if you are solo.", x = 5 },
        [9543] = { e = 3, s = "g", r = "Completing 50 garrison invasions, which can be done solo.", d = "Complete garrison invasions repeatedly until you reach 50 successes. This requires having an Invasion Specialist hero assigned to your garrison before starting.", x = 5 },
        [9545] = { e = 2, s = "s", r = "Upgrading the garrison to tier 2 is a quick step.", d = "Upgrade your garrison buildings sequentially until you reach tier 2 status. You must complete the prerequisite quests and gather resources for each upgrade step.", x = 5 },
        [9546] = { e = 2, s = "s", r = "Upgrading the garrison to tier 3 is a quick step.", d = "Continue upgrading your garrison from tier 2 to tier 3 by completing all necessary quests and gathering required materials. Ensure no upgrades are missed in the chain.", x = 5 },
        [9547] = { e = 1, s = "g", r = "Throwing 20 Awesomefish is trivial and account-wide.", d = "Fish for Awesomefish in any body of water and throw them to complete this account-wide task. It is a simple grind with no time gates or group requirements.", x = 5 },
        [9548] = { e = 3, s = "s", r = "Finding buried objects in one zone is a straightforward quest.", d = "Travel to Mok'gol Watchpost in Nagrand during the Sunspring event to find all Warsong objects. This achievement is missable if you do not collect every item before the event ends.", x = 5 },
        [9551] = { e = 4, s = "s", r = "Heroic dungeon with strict mechanics and RNG on Azzakel.", d = "Run Auchindoun on Heroic and focus entirely on killing Azzakel without damaging any other demons. You must coordinate with your group to avoid aggroing extra adds during the fight.", x = 5 },
        [9552] = { e = 4, s = "s", r = "Heroic dungeon with specific debuff management on Teron'gor.", d = "Defeat Teron'gor in Auchindoun Heroic while maintaining the Curtain of Flame buff throughout the entire encounter. Ensure your tank and healers keep the debuff active to avoid failure.", x = 5 },
        [9562] = { e = 3, s = "c", h = { 39841, 39842, 39843 }, r = "Most are assaults; Mok'gol, Socrethar's Rise, and Darktide Roost are hardest.", d = "Complete all listed Assault objectives for the Horde Garrison Campaign in Draenor. These are account-wide but require specific faction progression and may be time-gated by event windows.", x = 5 },
        [9564] = { e = 3, s = "c", h = { 39858, 39859, 39860 }, r = "Most are assaults; Mok'gol, Socrethar's Rise, and Darktide Roost are hardest.", d = "Complete all listed Assault objectives for the Alliance Garrison Campaign in Draenor. Like the Horde version, this is account-wide and tied to specific garrison campaign progress.", x = 5 },
        [9565] = { e = 3, s = "g", r = "Grinding 125 trap orders takes a few hours.", d = "Place 125 Work Orders at your Barn by trapping creatures in the world using The Trap Game. This requires active play in Draenor zones and is a grind that cannot be rushed.", x = 5 },
        [9571] = { e = 4, s = "c", h = { 39934, 39935, 39936 }, r = "Killing specific rare bosses in Broken Precipice.", d = "Defeat Durg Spinecrusher, Bonebreaker, and Pit Slayer within the Broken Precipice dungeon. Ensure you clear all trash mobs before engaging these specific bosses to avoid unintended deaths.", x = 5 },
        [9572] = { e = 1, s = "s", r = "Simple Bronze trial is quick to complete.", d = "Complete the Bronze Damage trial at the Proving Grounds to unlock the next tier. This is a solo activity with no time gate but requires consistent DPS checks.", x = 4 },
        [9573] = { e = 2, s = "s", r = "Silver trial takes slightly longer than Bronze.", d = "Finish the Silver Damage trial after unlocking Bronze to progress further. You must complete the previous tier first as it is a strict requirement for advancement.", x = 4 },
        [9574] = { e = 3, s = "s", r = "Gold trial requires more skill or time.", d = "Achieve the Gold Damage trial once you have completed Silver. This step continues the linear progression of damage trials available at the Proving Grounds.", x = 4 },
        [9575] = { e = 4, s = "s", r = "Wave 10 Endless is a significant challenge.", d = "Complete Wave 10 of the Endless Damage trial after reaching Gold status. Be prepared for a longer session as endless modes scale in difficulty and duration.", x = 4 },
        [9576] = { e = 5, s = "s", r = "Wave 20 requires high skill or luck.", d = "Complete Wave 10 first to unlock this trial. Focus on maximizing damage output while managing cooldowns efficiently. This is account-wide and requires no group.", x = 4 },
        [9577] = { e = 5, s = "s", r = "Wave 30 is very difficult and time-consuming.", d = "Finish Wave 20 before attempting Wave 30. You will receive a title upon completion. Ensure your rotation is optimized for sustained damage.", x = 4 },
        [9578] = { e = 1, s = "s", r = "Simple Bronze tank trial is quick to complete.", d = "Start with the Bronze trial to unlock higher tiers. Use defensive cooldowns sparingly and focus on survival mechanics. This unlocks the Silver tier next.", x = 4 },
        [9579] = { e = 2, s = "s", r = "Silver tank trial takes slightly longer than Bronze.", d = "Complete the Bronze trial first, then progress through Silver. Master tanking rotations and threat generation early. You will unlock Gold after finishing Silver.", x = 4 },
        [9580] = { e = 3, s = "s", r = "Gold tank trial requires more skill or time.", d = "Finish Silver before attempting Gold. Focus on maintaining high threat while surviving longer than previous waves. This unlocks the Endless Tank chain.", x = 4 },
        [9581] = { e = 4, s = "s", r = "Wave 10 Endless tank is a significant challenge.", d = "Complete Gold first to unlock Wave 10 of Endless Tank. Prepare for increasing difficulty by managing resources carefully. This is account-wide and soloable.", x = 4 },
        [9582] = { e = 3, s = "g", r = "Requires completing Wave 10 first; moderate difficulty.", d = "Finish Wave 10 before attempting Wave 20. Expect tougher mechanics and higher damage intake. Optimize your defensive cooldowns for this wave specifically.", x = 4 },
        [9583] = { e = 4, s = "g", r = "Wave 30 is significantly harder than Wave 20.", d = "Complete Wave 20 to unlock Wave 30. You will receive a title upon finishing. Ensure you can handle the increased mob count and damage.", x = 4 },
        [9584] = { e = 3, s = "g", r = "Bronze trial requires learning mechanics; moderate effort.", d = "Start with Bronze Healer to unlock Silver. Focus on keeping your party alive while managing mana efficiently. This unlocks the next tier automatically.", x = 4 },
        [9585] = { e = 3, s = "g", r = "Silver trial is harder than Bronze but manageable.", d = "Complete Bronze first, then progress through Silver. Master healing rotations and emergency cooldowns early. You will unlock Gold after finishing Silver.", x = 4 },
        [9586] = { e = 4, s = "g", r = "Gold trial requires high skill or gear; moderate grind.", d = "Finish Silver before attempting Gold. Focus on sustained healing output and resource management. This unlocks the Endless Healer chain next.", x = 4 },
        [9587] = { e = 4, s = "g", r = "Endless Wave 10 is harder than standard Gold trial.", d = "Complete Gold first to unlock Wave 10 of Endless Healer. Prepare for increasing difficulty by managing resources carefully. This is account-wide and soloable.", x = 4 },
        [9588] = { e = 4, s = "g", r = "Endless Wave 20 requires sustained performance; hard grind.", d = "Complete Wave 10 first to unlock this trial. Use a healer spec and focus on survival mechanics rather than damage output.", x = 4 },
        [9589] = { e = 5, s = "g", r = "Wave 30 is the hardest Endless trial; very hard grind.", d = "Finish Wave 20 immediately to earn the title. This unlocks the final wave in the chain, so do not skip it.", x = 4 },
        [9590] = { e = 2, s = "s", r = "Just run a wrong spec trial once; easy and quick.", d = "Start any Basic trial while playing a class or spec that is clearly mismatched for the encounter type.", x = 4 },
        [9598] = { e = 4, s = "g", r = "Collecting 250 mounts is a long-term collection grind.", d = "Grind mounts across all zones until you own exactly 250 unique ones. This is account-wide, so share progress with friends.", x = 5 },
        [9599] = { e = 4, s = "g", r = "Collecting 250 mounts is a long-term collection grind.", d = "This is a duplicate entry for the same mount collection goal; simply ensure your total unique mount count reaches 250.", x = 5 },
        [9600] = { e = 3, s = "c", h = { 40000 }, r = "Requires two evolutions; Shadow Hulk is the harder one.", d = "Evolve your Lost Veil Anzu pet into both the Shadow Hulk and Gluttonous Giant forms to complete this objective.", x = 5 },
        [9601] = { e = 4, s = "c", h = { 39997, 42419, 42420 }, r = "Requires evolving a mount and defeating multiple rare/elite mobs.", d = "Evolve your pet into every available form in the Lost Veil Anzu, including the rare Giga Sentinel and Mecha Plunderer.", x = 5 },
        [9602] = { e = 3, s = "c", r = "Multiple bonus objectives in one zone require some travel.", d = "Visit all four bonus objective zones in Shadowmoon Valley while on the Alliance side of Draenor to claim them.", x = 5 },
        [9605] = { e = 3, s = "c", r = "Several bonus objectives across different sub-zones of Spires of Arak.", d = "Complete the specific bonus objectives listed for Spires of Arak before leaving the zone or resetting your account.", x = 5 },
        [9606] = { e = 3, s = "c", r = "Multiple bonus objectives in Frostfire Ridge require travel.", d = "Finish all three bonus objectives in Frostfire Ridge while playing as a Horde character to unlock this achievement.", x = 5 },
        [9607] = { e = 3, s = "c", r = "Many bonus objectives across Gorgrond zones require travel.", d = "Complete every listed bonus objective in Gorgrond, including the arena and canyon locations, before moving on.", x = 5 },
        [9610] = { e = 4, s = "c", h = { 40030, 40031 }, r = "Finding specific ancient relics often requires extensive searching.", d = "Explore Broken Precipice thoroughly to find and unearth all four ancient ogre relics hidden within the zone.", x = 5 },
        [9612] = { e = 3, s = "g", r = "Escort quest with morale requirement takes time to complete.", d = "Head to Skettis Ruins and escort Arakkoa outcasts to Darkscryers until you reach 100 total morale. This is a straightforward escort chain with no time limit, so just keep moving between objectives without dying.", x = 5 },
        [9613] = { e = 2, s = "s", r = "Simple interaction-based objective in a specific area.", d = "Go to the Spires of Arak zone within Skettis Ruins and wait for Kaliri fish to spawn near water edges. Interrupt their eating animation quickly to steal the fish before they consume it, then eat it yourself immediately.", x = 5 },
        [9615] = { e = 3, s = "c", r = "Multiple bonus objectives in Nagrand require travel and completion.", d = "Complete all three Nagrand bonus objectives by visiting Hemet's Happy Hunting Grounds, Ironfist Harbor, and Snarlpaw Ledge during your normal zone exploration. These track account-wide so you can finish them at any time while in Nagrand.", x = 5 },
        [9617] = { e = 2, s = "s", r = "Defeating a single boss in a specific instance.", d = "Enter Gorian Proving Grounds and defeat Krud the Eviscerator as a solo or group target within the instance. Ensure you kill him before leaving the dungeon to secure your progress for this specific achievement.", x = 5 },
        [9619] = { e = 5, s = "c", h = { 40118, 40119 }, r = "Requires defeating multiple raid bosses on Heroic or higher.", d = "Queue for Heroic or higher difficulty dungeons and raids listed in the info field, starting with easier ones like Bloodmaul Slag Mines. Track each boss name carefully since missing one means restarting that specific kill count later.", x = 5 },
        [9630] = { e = 4, s = "g", r = "Accumulating 5000 honorable kills is a long-term grind.", d = "Grind any Draenor content including dungeons, world quests, or PvP to accumulate 5000 honorable kills. This is account-wide so play with friends if you want faster progress without needing specific zones.", x = 5 },
        [9631] = { e = 5, s = "c", h = { 40154, 40150, 40153 }, r = "Requires full Mythic raid progression and specific boss kills.", d = "Complete all Mythic raid achievements listed in the info field, which requires running Highmaul, Blackrock Foundry, and other raids on Mythic difficulty. Start with easier bosses first to build up your group's gear before tackling harder encounters.", x = 5 },
        [9632] = { e = 1, s = "s", r = "Simple interaction with existing game mechanics.", d = "Visit Shattrath City and combine all three types of Rune Crystals at the designated location to complete this quest. Check your inventory for any missing crystal types before heading to the city to save time.", x = 5 },
        [9633] = { e = 4, s = "c", h = { 40171, 40380 }, r = "Requires defeating multiple rare elites in Shattrath.", d = "Farm rare creatures in Shattrath City like Bombardier Gu'gok and Avatar of Socrethar by running around the zone repeatedly. These mobs spawn randomly, so be patient and cover different areas to find them all.", x = 5 },
        [9634] = { e = 4, s = "g", r = "Grinding 30 kills with a specific buff effect.", d = "Activate Arkonite Empowerment buff and defeat 30 Shadow Council members in Shattrath City while the effect is active. Keep the buff up by consuming food or items if needed, and focus on killing council members specifically.", x = 5 },
        [9635] = { e = 2, s = "g", r = "Collecting floating orcs is tedious but straightforward.", d = "Find and burn 40 floating orc corpses scattered across Shattrath City using your profession abilities or manual interaction. These bodies appear randomly, so explore thoroughly and check ground frequently for new spawns.", x = 5 },
        [9636] = { e = 1, s = "s", r = "Quick interaction to free guards in Shattrath.", d = "Locate captured guards in Shattrath City and free them by interacting with their cages or completing related quests. This is account-wide so you can help friends if they are stuck on specific guards.", x = 5 },
        [9637] = { e = 2, s = "g", r = "Burning missives is a simple repetitive task.", d = "Head to Shattrath City and burn Sargerei Missives found on the ground or from vendors. This is account-wide, so any character can help you reach the goal quickly.", x = 5 },
        [9638] = { e = 4, s = "c", h = { 40201, 40206 }, r = "Requires defeating multiple rare elites in Shattrath.", d = "Locate and kill the specific rare elites listed in Shattrath City; they often spawn near major quest hubs. Be patient as some rares have long respawn timers.", x = 5 },
        [9639] = { e = 2, s = "s", r = "Complete a single quest instance at the Coliseum.", d = "Travel to Highmaul Coliseum in your Garrison and complete the Fight, Kill, Salute! quest chain. Ensure you have a garrison built before starting.", x = 5 },
        [9640] = { e = 5, s = "c", h = { 40213 }, r = "Requires legendary questline completion and raid boss kill.", d = "Start Khadgar's legendary questline by defeating Kairozdormu in raid content. This is a time-gated achievement that requires high-level gear and group coordination.", x = 5 },
        [9641] = { e = 5, s = "c", h = { 40215 }, r = "Part of a complex legendary questline requiring raids.", d = "Progress through the Highmaul raid quests to save Khadgar from Gul'dan. Complete these specific story quests in order to unlock the next chapter.", x = 5 },
        [9642] = { e = 5, s = "c", h = { 40217, 40218 }, r = "Requires completing specific legendary quests and raid content.", d = "Finish the Blackrock Foundry legendary questline by completing the specified objectives within the raid. Ensure you have access to the raid before attempting this.", x = 5 },
        [9643] = { e = 5, s = "g", r = "Requires collecting 600 unique pets; massive RNG grind.", d = "Collect 600 unique pets by catching them in the wild or purchasing from vendors. This is a massive long-term goal that benefits from using all characters.", x = 5 },
        [9654] = { e = 2, s = "g", r = "Farm mutagen stacks in a specific zone.", d = "Gather Mutagen stacks in Everbloom Wilds by completing related quests or defeating enemies. Monitor your stack count to avoid missing the target.", x = 5 },
        [9655] = { e = 3, s = "c", h = { 40304, 40307, 40310 }, r = "Defeat multiple rare mobs; some are difficult RNG.", d = "Find and defeat all rare creatures listed in The Pit area. These rares may be elusive, so check multiple locations within the zone.", x = 5 },
        [9656] = { e = 2, s = "g", r = "Find and turn in scattered items in a zone.", d = "Locate the Iron Horde Attack Plans hidden in The Pit. Search thoroughly as these items are often placed in obscure spots.", x = 5 },
        [9658] = { e = 3, s = "c", r = "Hold three pillars simultaneously; requires timing.", d = "Stand near all three pillars of power in Everbloom Wilds at once to trigger the achievement. Coordinate with friends if needed to hold positions simultaneously.", x = 5 },
        [9659] = { e = 2, s = "s", r = "Single timed event with a launcher mechanic.", d = "Use the Iron Troop Launcher in The Pit and aim for four rings within three minutes. Practice your timing as this can be tricky under pressure.", x = 5 },
        [9663] = { e = 1, s = "s", r = "Consume three consumables simultaneously; trivial.", d = "Gather the three specific fruits in Everbloom Wilds and apply their effects simultaneously to trigger the achievement. Ensure you have all items active before leaving the zone, as this is a single-target buff check.", x = 5 },
        [9667] = { e = 2, s = "g", r = "Burn 100 trees; simple repetitive action.", d = "Use fire-based attacks or abilities on trees in Everbloom Wilds until you ignite 100 of them. This is account-wide and can be done solo without any specific quest chain.", x = 5 },
        [9670] = { e = 3, s = "g", r = "Collect 25 toys; requires finding or crafting items.", d = "Purchase toys from vendors across Azeroth to reach the count of 25, which unlocks the next tier. Keep track of your total count as this progress carries over between characters.", x = 5 },
        [9671] = { e = 3, s = "g", r = "Collect 50 toys; continues previous grind.", d = "Continue buying toys until you reach 50 total; this requires completing the previous toy collection achievement first. No specific location is needed since toys are account-wide collectibles.", x = 5 },
        [9672] = { e = 3, s = "g", r = "Collect 100 toys; continues previous grind.", d = "Keep acquiring toys from various vendors to hit the 100 mark, unlocking the next tier automatically. This is purely a collection goal with no time limit or group requirement.", x = 5 },
        [9673] = { e = 3, s = "g", r = "Collect 150 toys; continues previous grind.", d = "Reach 150 total toys to complete this set and earn the Robo-Gnomebulator toy as a reward. Ensure you finish the prior toy milestones before claiming this specific achievement.", x = 5 },
        [9674] = { e = 3, s = "c", r = "Requires completing multiple bonus objectives in Talador.", d = "Complete all listed bonus objectives in Talador, which may require visiting multiple zones or finishing specific quests. Check each objective individually as they are separate requirements for this single achievement.", x = 5 },
        [9678] = { e = 3, s = "g", r = "Grinding rare spawns in Everbloom Wilds takes time.", d = "Defeat every rare creature listed in Everbloom Wilds, including bosses and elites that drop from world events. This is account-wide so you can farm them on any character once defeated.", x = 5 },
        [9685] = { e = 4, s = "g", r = "Collecting all Draenor pets requires significant hunting.", d = "Catch all available Draenor battle pets by exploring the zone and completing related quests or catching wild spawns. Some may require specific conditions like time of day or defeating a particular enemy first.", x = 5 },
        [9686] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Aquatic pets is a grind.", d = "Queue up for Master Tamer battles in Broken Isles using only aquatic pets to defeat each target 12 times. You must switch pet types between runs, so plan your team composition carefully.", x = 5 },
        [9687] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Beast pets is a grind.", d = "Repeat the same process as the aquatic achievement but equip beast-type pets instead. Ensure your current roster includes enough beasts to handle all twelve masters efficiently.", x = 5 },
        [9688] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Critter pets is a grind.", d = "Do the identical routine using critter pets, swapping teams between each master tamer encounter. This is account-wide so progress persists across characters once you start the chain.", x = 5 },
        [9689] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Dragonkin pets is a grind.", d = "Defeat the 12 Master Tamers in Broken Isles using only Dragonkin pets, ensuring you have all required breeds before starting. This is account-wide and requires specific pet collection prior to attempting the battles.", x = 5 },
        [9690] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Elemental pets is a grind.", d = "Complete this by defeating all 12 Master Tamers with Elemental pets; gather your full set of Elementals first as this is account-wide. Do not mix pet types or you will need to restart the tamers.", x = 5 },
        [9691] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Flying pets is a grind.", d = "Defeat the 12 Master Tamers using Flying pets only, which requires collecting specific breeds before engaging in battle. This achievement is account-wide and cannot be completed with non-flying alternatives.", x = 5 },
        [9692] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Humanoid pets is a grind.", d = "Win battles against all 12 Master Tamers exclusively with Humanoid pets; ensure you have the necessary breeds collected beforehand. This is account-wide and progress carries over across characters.", x = 5 },
        [9693] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Magic pets is a grind.", d = "Defeat the 12 Master Tamers using Magic pets only, requiring you to collect specific breeds prior to starting. Progress is tracked account-wide so coordinate with other characters if needed.", x = 5 },
        [9694] = { e = 4, s = "g", r = "Defeating 12 tamers with specific Mechanical pets is a grind.", d = "Complete this by defeating all 12 Master Tamers with Mechanical pets; gather your full set of mechanical breeds first. This is account-wide and requires no mixing of pet types during battles.", x = 5 },
        [9695] = { e = 4, s = "c", h = { 52821 }, r = "Requires defeating 12 specific tamers with rare Undead pets.", d = "Defeat the 12 Master Tamers using Undead pets only, ensuring you have collected all required undead breeds beforehand. This achievement is account-wide and progress is shared across your characters.", x = 5 },
        [9696] = { e = 4, s = "c", r = "Depends on completing multiple other difficult achievements first.", d = "Unlock this by completing every single sub-achievement listed in the info field, including all pet battle categories and other garrison tasks. It rewards the Nightmare Treant and requires full completion of prerequisites.", x = 5 },
        [9703] = { e = 2, s = "g", r = "Requires completing 10 specific inn quests in Draenor.", d = "Complete at least 10 specific Inn quests in your Garrison; these are repeatable or multi-step objectives found within the inn interface. Focus on completing unique story quests first to maximize progress efficiently.", x = 5 },
        [9705] = { e = 4, s = "g", r = "Grinding Nagrand mobs while holding a rare item.", d = "Defeat all six specified mount-training targets in Nagrand while holding the Black Claw of Sethe, which is a Horde-only item. Ensure you have the correct item equipped before engaging these specific enemies.", x = 5 },
        [9706] = { e = 4, s = "g", r = "Grinding Nagrand mobs while holding a different rare item.", d = "Defeat the same six mount-training targets in Nagrand while carrying the Garn-Tooth Necklace, another Horde-specific item. This grants the Stable Master title upon completion of all required kills.", x = 5 },
        [9707] = { e = 3, s = "s", r = "Requires equipping specific high-level gear in all slots.", d = "Equip a superior item in every slot with an item level of at least 608 before Battle for Azeroth launches. Check your inventory for Mystically Superior gear and fill any missing slots to meet the criteria.", x = 5 },
        [9708] = { e = 3, s = "s", r = "Requires equipping specific higher-level gear in all slots.", d = "Equip an epic in every slot before Battle for Azeroth, as this requirement cannot be met later. Start by farming high-level gear from raids or dungeons to reach the 640 item level threshold quickly.", x = 5 },
        [9710] = { e = 2, s = "g", r = "Poisoning 10 kegs is a straightforward repeatable task.", d = "Visit Iron Siegeworks and repeatedly poison Kegs of Impaler Ale until you have destroyed ten. This is account-wide, so any character can contribute to the progress.", x = 5 },
        [9711] = { e = 2, s = "g", r = "Destroying 10 warplans is a straightforward repeatable task.", d = "Head to Iron Siegeworks and destroy Secret Warplans scattered throughout the area. Ensure you complete this before leaving Draenor, as it is account-wide but tied to that zone.", x = 5 },
        [9713] = { e = 4, s = "c", r = "Collecting all drake mounts often requires rare drops or events.", d = "Collect all listed drake mounts by purchasing them from vendors or defeating specific bosses. This achievement is account-wide, so gather mounts across multiple characters if needed.", x = 5 },
        [9714] = { e = 5, s = "s", r = "Defeating a specific boss in Ashran is difficult and RNG-based.", d = "Travel to Ashran and defeat Muk'Mar Raz to win Kor'lok's favor for your faction. Coordinate with your team to ensure the boss dies before the event ends.", x = 5 },
        [9715] = { e = 5, s = "s", r = "Defeating a specific boss in Ashran is difficult and RNG-based.", d = "Go to Ashran and kill Gaul Dun Firok to secure your faction's favor from Kor'lok. This requires being present during the Ashran battle and defeating the specific bodyguard.", x = 5 },
        [9724] = { e = 3, s = "c", r = "Requires visiting multiple NPCs and defeating them.", d = "Locate and defeat all listed Pet Tamers in Draenor, including those in garrisons or open world. Track down each tamer individually as they may be in different zones.", x = 5 },
        [9726] = { e = 3, s = "g", r = "Collecting 10 treasures takes a few hours of exploration.", d = "Explore Draenor thoroughly to find ten treasures, avoiding Tanaan Jungle. Use a scanning tool or follow treasure maps to locate hidden chests efficiently.", x = 5 },
        [9727] = { e = 4, s = "g", r = "Collecting 50 treasures requires significant time and luck.", d = "Continue exploring Draenor to discover fifty additional treasures beyond the initial ten. Maintain your scanning tools active and revisit areas you may have missed earlier.", x = 5 },
        [9728] = { e = 5, s = "g", r = "Collecting 200 treasures is a very long grind.", d = "Discover two hundred total treasures in Draenor excluding Tanaan Jungle for this grand achievement. This requires extensive exploration, so plan routes that cover all major zones systematically.", x = 5 },
        [9738] = { e = 4, s = "c", h = { 41513 }, r = "Completing all Nemesis quests is a major time sink.", d = "Complete all Nemesis quests at the Gladiator's Sanctum and finish Fight, Kill, Salute! at Highmaul Coliseum. Ensure you have access to both garrison locations before starting these specific tasks.", x = 5 },
        [9755] = { e = 2, s = "s", r = "Just run the race once to complete it.", d = "Participate in a Darkmoon Faire event to complete either Welcome to the Darkmoon Races or The Real Race with the Racing Strider. Attend the faire during its active weeks to unlock this opportunity.", x = 5 },
        [9756] = { e = 3, s = "g", r = "Need to finish under 25 tolls, requiring practice.", d = "Start by completing The Real Race with the Racing Strider to unlock the next tier. Focus on minimizing tolls spent rather than pure speed, as you must finish under 25 tolls. This is a repeatable achievement once unlocked, so no content is missable.", x = 5 },
        [9759] = { e = 4, s = "g", r = "Finishing under 20 tolls is harder and takes time.", d = "You must first complete Darkmoon Racer Novice before attempting this tier. Aim to finish the race within 20 tolls by optimizing your path and avoiding unnecessary collisions. Like the previous tier, you can retry this repeatedly after unlocking it.", x = 5 },
        [9760] = { e = 5, s = "g", r = "Finishing under 15 tolls is a difficult challenge.", d = "Unlock this by finishing the Racing Strider race in under 15 tolls after beating the Novice tier. Practice running efficiently to lower your toll count significantly below the limit before attempting the achievement again. There are no time gates or rare drops associated with this step.", x = 5 },
        [9761] = { e = 5, s = "g", r = "Finishing under 11 tolls is extremely hard RNG.", d = "Complete the previous Leadfoot tier, then focus on finishing the race in under 11 tolls. This is a high-difficulty challenge requiring precise navigation to avoid toll costs. Be patient and retry often as there are no missable elements or group requirements.", x = 5 },
        [9764] = { e = 5, s = "g", r = "Rocketeer race with 11 toll limit is very hard.", d = "Unlock this by first completing Blast Off! with the Rocketeer vehicle. You must then finish the race within 11 tolls, which is very tight. This achievement grants a toy reward upon completion but requires careful route planning to succeed.", x = 5 },
        [9766] = { e = 4, s = "g", r = "Rocketeer race with 15 tolls is a tough grind.", d = "Start with the Blast Off! quest to unlock the Rocketeer vehicle for racing. Progress through Bronze and Silver tiers by improving your time efficiency until you can finish under 15 tolls. Each tier is repeatable once unlocked, so take your time mastering the course.", x = 5 },
        [9769] = { e = 2, s = "g", r = "Requires completing the race within a low toll limit.", d = "Begin the Rocketeer chain by completing Blast Off! to unlock the vehicle. Work toward finishing the race within 20 tolls before moving on to Silver. This step is purely skill-based with no group requirements or rare drops to worry about.", x = 5 },
        [9770] = { e = 1, s = "g", r = "Higher toll limit makes this significantly easier.", d = "This is the entry-level achievement for the Rocketeer vehicle, requiring you to finish in under 25 tolls. Complete it first to unlock the Bronze tier and access better vehicles later. There are no pitfalls here other than needing to actually complete the initial race.", x = 5 },
        [9780] = { e = 2, s = "g", r = "Similar to Rocketeer but with a different racer.", d = "Start by completing The Real Race with the Powermonger within 25 tolls to unlock the next tier. This vehicle is slower, so focus on taking the shortest path possible to avoid excessive toll costs. No group members are needed for this solo-friendly achievement.", x = 5 },
        [9781] = { e = 2, s = "g", r = "Requires previous achievement and tighter toll limit.", d = "Unlock this after beating Go-Getter by finishing the Powermonger race in under 20 tolls. The Powermonger is a heavy vehicle, so plan your route carefully to minimize toll expenses. You can retry this repeatedly once the prerequisite is met.", x = 5 },
        [9783] = { e = 2, s = "g", r = "Tighter toll limit increases difficulty slightly.", d = "Progress from Bronze to Silver by improving your Powermonger run time to under 15 tolls. This requires significant practice as the vehicle is cumbersome and prone to high toll costs. Ensure you have completed the previous tier before attempting this challenge.", x = 5 },
        [9785] = { e = 2, s = "g", r = "Very tight toll limit requires skill or luck.", d = "Complete the Silver tier first, then aim for an impressive run under 11 tolls with the Powermonger. This final tier in the chain rewards a toy upon success. There are no time gates or rare drops, just pure skill and route optimization.", x = 5 },
        [9786] = { e = 2, s = "g", r = "Requires completing the race within a low toll limit.", d = "Start the Darkmoon Faire race with Wanderluster and aim to finish under 25 tolls. This is a time-gated event that requires you to complete the race quickly; do not wait for the next day or you will miss the window.", x = 5 },
        [9787] = { e = 2, s = "g", r = "Requires previous achievement and tighter toll limit.", d = "Unlock this after Wayfarer by racing Wanderluster under 20 tolls. Practice your route beforehand to shave off time, as missing the daily race timer makes this achievement impossible for that day.", x = 5 },
        [9790] = { e = 2, s = "g", r = "Tighter toll limit increases difficulty slightly.", d = "Progress from Bronze by finishing Wanderluster races in under 15 tolls. You must complete the previous tier first, and rushing through the course is essential to meet the stricter time limit.", x = 5 },
        [9792] = { e = 2, s = "g", r = "Very tight toll limit requires skill or luck.", d = "Achieve Gold status with Wanderluster by finishing within 11 tolls for a toy reward. This requires significant practice on the track layout and optimal speed boosts to beat the tight deadline.", x = 5 },
        [9793] = { e = 2, s = "g", r = "Requires completing the race within a low toll limit.", d = "Begin the Big Race chain with Racing Strider, aiming for under 40 tolls. Treat this like a standard race but focus on maintaining high speed throughout the longer course to stay within the limit.", x = 5 },
        [9794] = { e = 1, s = "g", r = "Higher toll limit makes this significantly easier.", d = "Unlock Novice status by completing the Big Race with Racing Strider in under 35 tolls. You must have the previous achievement, so plan your run carefully to avoid wasting time on unnecessary actions.", x = 5 },
        [9795] = { e = 2, s = "g", r = "Grind to finish race within toll limit.", d = "Advance to Jockey by finishing the Big Race with Racing Strider in under 30 tolls. Consistent practice is needed here as the time margin becomes tighter compared to the earlier tiers.", x = 5 },
        [9797] = { e = 2, s = "g", r = "Grind to finish race within lower toll limit.", d = "Reach Leadfoot status by completing the Big Race with Racing Strider within 25 tolls. This stage demands precise driving skills and familiarity with shortcuts to ensure you beat the clock reliably.", x = 5 },
        [9799] = { e = 2, s = "g", r = "Grind to finish race within even lower toll limit.", d = "Finish the Roadhog tier by racing Racing Strider under 20 tolls for a toy reward. This is one of the hardest tiers, so master the track mechanics before attempting it during the limited daily window.", x = 5 },
        [9800] = { e = 2, s = "g", r = "Grind to finish race with Rocketeer within tolls.", d = "Start the Rocketeer chain by completing the Big Race with Rocketeer within 40 tolls. Unlike other mounts, Rocketeer has unique handling; learn its controls immediately to maximize your speed potential.", x = 5 },
        [9801] = { e = 2, s = "g", r = "Grind to finish race with Rocketeer in fewer tolls.", d = "Unlock Bronze Rocketeer status by finishing the race with Rocketeer in under 30 tolls. You must complete the previous tier first, and using Rocketeer's special abilities effectively is key to meeting this goal.", x = 5 },
        [9803] = { e = 2, s = "g", r = "Grind to finish race with Rocketeer in even fewer tolls.", d = "Progress to Silver Rocketeer by completing the race with Rocketeer within 25 tolls. This requires unlocking Bronze first and practicing your route extensively to handle the vehicle's unique physics under time pressure.", x = 5 },
        [9805] = { e = 2, s = "g", r = "Grind to finish race with Rocketeer in very few tolls.", d = "Start at Darkmoon Faire and race the Rocketeer. You must finish within 20 tolls to unlock the next tier, so aim for speed early.", x = 5 },
        [9806] = { e = 2, s = "g", r = "Grind to finish race with Wanderluster within tolls.", d = "Race the Wanderluster to complete the Vagabond achievement. This is a prerequisite for the Bronze tier, so do not skip it.", x = 5 },
        [9807] = { e = 2, s = "g", r = "Grind to finish race with Wanderluster in fewer tolls.", d = "After unlocking Vagabond, race the Wanderluster again but target 30 tolls this time to earn the Bronze title.", x = 5 },
        [9809] = { e = 2, s = "g", r = "Grind to finish race with Wanderluster in even fewer tolls.", d = "Unlock the Silver tier by racing the Wanderluster within 25 tolls. Keep improving your speed to reach the next goal.", x = 5 },
        [9811] = { e = 2, s = "g", r = "Grind to finish race with Wanderluster in very few tolls.", d = "Complete the Gold tier by finishing the race with the Wanderluster in under 20 tolls for a toy reward.", x = 5 },
        [9812] = { e = 2, s = "g", r = "Grind to finish race with Powermonger within tolls.", d = "Begin racing the Powermonger to complete the Goal-Oriented achievement. This unlocks the Bronze tier and starts the chain.", x = 5 },
        [9813] = { e = 1, s = "s", r = "Single race run with no RNG.", d = "Race the Powermonger within 30 tolls after unlocking Goal-Oriented to earn the Bronze title.", x = 5 },
        [9815] = { e = 2, s = "s", r = "Slightly harder race, still single event.", d = "Progress to Silver by racing the Powermonger within 25 tolls. Consistent practice will help you meet this tighter time limit.", x = 5 },
        [9817] = { e = 3, s = "s", r = "Harder race requiring skill or luck.", d = "Finish the Gold tier by racing the Powermonger in under 20 tolls to receive the Darkmoon Cannon toy.", x = 5 },
        [9819] = { e = 1, s = "s", r = "Simple flight test, trivial to do.", d = "Use the Wanderluster's Glider and stay airborne for over 10 seconds. Avoid landing early or you will fail the timer.", x = 5 },
        [9824] = { e = 3, s = "g", r = "Collecting many pets from raids/dungeons.", d = "Gather all listed Burning Crusade pets from Black Temple, Hyjal Summit, and Sunwell. This is account-wide, so check your collection carefully.", x = 5 },
        [9825] = { e = 3, s = "c", h = { 42686, 42687, 42699 }, r = "Quest chain; final quests are hardest.", d = "Visit Harrison Jones in your Garrison to complete all six Relic Hunter quests. Ensure you have the necessary garrison level before starting.", x = 5 },
        [9826] = { e = 3, s = "s", r = "Single invasion run with good rating.", d = "Start by completing the Golden Defender achievement first, as it is a hard requirement. Focus on one invasion at a time to maximize your Platinum rating without rushing. Note that this requires specific garrison buildings and may take significant grinding.", x = 5 },
        [9827] = { e = 4, s = "c", h = { 42710, 42711, 42712 }, r = "All invasions; some factions are harder.", d = "You must earn a Platinum rating in every single max-level invasion type listed. Since this is account-wide, coordinate with friends if you lack certain factions or need extra time to grind ratings on difficult bosses.", x = 5 },
        [9828] = { e = 3, s = "g", r = "Collecting many music rolls over time.", d = "Purchase music rolls from the garrison vendor until you have ten unique tracks. Be patient as some songs are rare drops that may take many attempts to obtain before unlocking the next tier.", x = 5 },
        [9833] = { e = 3, s = "c", h = { 43378, 43379, 43380 }, r = "Quest chain; some quests are harder.", d = "Locate and complete all listed Draenor quest achievements, which often involve specific zones or NPCs. Ensure you finish these early in your leveling process, as they can become missable once certain content is cleared or zones are no longer accessible.", x = 5 },
        [9836] = { e = 3, s = "c", h = { 42766, 42767, 42764 }, r = "Quest chain; final quests are hardest.", d = "Visit Harrison Jones in your garrison to accept the six Relic Hunter quests. Complete them in any order, but be aware that some relics may require specific dungeon runs or world bosses to obtain before turning them in.", x = 5 },
        [9838] = { e = 4, s = "c", h = { 42809, 42810, 42811 }, r = "Many bosses; some require high skill.", d = "Defeat all listed Draenor raid bosses while having Pepe the Trans-Dimensional Bird as your mount companion. This is account-wide, so you can help friends out if they are stuck on a particular boss.", x = 5 },
        [9858] = { e = 4, s = "c", h = { 42930, 42931, 42932 }, r = "Requires defeating multiple rare garrison raid bosses.", d = "Summon and defeat every Garrison raid boss using your garrison's special ability. These fights are often shorter than normal raids but require attention to mechanics; ensure your buildings are upgraded to unlock the summons.", x = 5 },
        [9885] = { e = 2, s = "g", r = "Score hits in a short mini-game session.", d = "Play the Tonk Challenge minigame at Darkmoon Faire until you score 45 hits in a single session. This can be done solo and is relatively quick, so grab the controller toy early if available.", x = 5 },
        [9894] = { e = 2, s = "g", r = "Land rings in a simple carnival mini-game.", d = "Participate in the Ring Toss minigame at Darkmoon Faire to toss ten rings onto Dubenko. Aim for accuracy rather than speed, as missing too many will reset your progress for the session.", x = 5 },
        [9897] = { e = 3, s = "c", h = { 43321 }, r = "Collect music rolls; one rare spawn is difficult.", d = "Similar to the Alliance version, collect ten unique music rolls for your garrison jukebox. Prioritize rare drops and check your collection frequently to avoid grinding the same common tracks repeatedly.", x = 5 },
        [9900] = { e = 4, s = "c", h = { 43096, 43102 }, r = "Complete many exploration missions including rare ones.", d = "Complete all listed exploration missions in your garrison, which involve digging up specific sites. Some missions may require prior quest completion or building upgrades, so review the requirements before starting each one.", x = 5 },
        [9901] = { e = 5, s = "c", h = { 43119 }, r = "Requires completing other hard achievements first.", d = "Finish the Master Relic Hunter achievement first to unlock this next step. Once done, you will receive Harrison Jones as a follower, so ensure you have completed all his associated quests beforehand.", x = 5 },
        [9906] = { e = 2, s = "g", r = "Collect heirlooms from vendors or drops easily.", d = "Start by buying any heirloom from a vendor or auction house to unlock the chain. You must collect five distinct heirlooms, so check your mailbox for rewards from other achievements like 'Where's the Mailbox?' before moving on.", x = 5 },
        [9908] = { e = 3, s = "g", r = "Collect more heirlooms; requires some time.", d = "Continue collecting heirlooms until you reach fifteen total, which will unlock the next tier. This is account-wide, so buy extra copies if needed to speed up progress without waiting for drops.", x = 5 },
        [9909] = { e = 4, s = "g", r = "Collect many heirlooms; takes significant time.", d = "Gather thirty-five heirlooms in total to earn this milestone and its mount reward. Since heirlooms are rare drops or vendor items, plan to purchase duplicates early rather than relying solely on random loot.", x = 5 },
        [9911] = { e = 2, s = "g", r = "Collect a single heirloom item easily.", d = "Purchase your first heirloom immediately after starting the game to unlock this prerequisite achievement. It is account-wide, so any character can contribute to the count once you have at least one item in your inventory.", x = 5 },
        [9912] = { e = 3, s = "c", h = { 43289 }, r = "Collect music rolls; one rare spawn is difficult.", d = "Build a garrison and collect twenty music rolls from various sources like world drops or vendors. Ensure you complete the 'Ten Hit Tunes' prerequisite first, as this achievement is specific to your faction's garrison.", x = 5 },
        [9914] = { e = 3, s = "c", h = { 43356 }, r = "Collect music rolls; one rare spawn is difficult.", d = "Similar to the Alliance version, build a Horde garrison and gather twenty music tracks. Focus on collecting rolls from different expansions to avoid time-gating issues since some tracks are rare or event-specific.", x = 5 },
        [9923] = { e = 4, s = "c", h = { 43376, 43377, 43364 }, r = "Requires completing multiple specific Draenor quest chains.", d = "Complete all listed Draenor quest achievements in any order, as they do not depend on each other. Prioritize quests that drop heirlooms or music rolls to make multiple achievements progress simultaneously.", x = 5 },
        [9924] = { e = 4, s = "c", h = { 43390, 43407, 43404 }, r = "Requires visiting many locations including raids and dungeons.", d = "Visit every location listed and use the S.E.L.F.I.E. camera to take a photo with an NPC. Some locations like Onyxia's Lair require raid access, so ensure you have the necessary gear before attempting these shots.", x = 5 },
        [9928] = { e = 4, s = "c", h = { 43419 }, r = "Requires completing specific Garrison achievements to unlock follower.", d = "Complete the 'Don't Call Me Junior' achievement by finishing specific garrison quests. This unlocks Harrison Jones as a follower, so prioritize the required quest chain in your garrison hub.", x = 5 },
        [9972] = { e = 5, s = "s", r = "High RNG requirement to keep Ariok alive during raid.", d = "Defeat Kilrogg Deadeye in Hellfire Citadel while keeping Ariok alive on Normal or higher difficulty. Coordinate with your raid group to protect Ariok during the fight, as his death will void this achievement permanently.", x = 5 },
        [9979] = { e = 4, s = "c", r = "Requires defeating specific bosses in a specific order.", d = "Kill the Soul of the Crone before engaging Gorefiend in Hellfire Citadel on Normal or higher. This sequence is mandatory, so ensure your healer can handle the extra mechanics when pulling both targets.", x = 5 },
        [9983] = { e = 2, s = "g", r = "Simple mini-game requiring some points but easy to complete.", d = "Play Whack-a-Gnoll at Darkmoon Faire until you score forty-five points in a single session. This event is time-gated to specific weekends, so plan your playtime accordingly and aim for high accuracy quickly.", x = 5 },
        [9988] = { e = 5, s = "s", r = "Strict raid mechanic with zero tolerance for holding item.", d = "Defeat Shadow-Lord Iskar on Normal or higher while ensuring no player holds the Eye of Anzu for over five seconds. Coordinate your team to immediately toss the item upon pickup to avoid failure.", x = 5 },
        [9989] = { e = 4, s = "c", r = "Requires defeating boss without killing specific add.", d = "Kill Tyrant Velhari without harming the Ancient Enforcer boss during the encounter. Focus damage away from the enforcer and use crowd control if needed to protect it.", x = 5 },
        [10010] = { e = 3, s = "s", r = "Standard dungeon kill requiring normal or heroic completion.", d = "Simply defeat Raigonn in Gate of the Setting Sun dungeon on Normal or higher difficulty. No special mechanics are required beyond standard completion.", x = 4 },
        [10011] = { e = 3, s = "s", r = "Standard dungeon kill requiring normal or heroic completion.", d = "Defeat Wing Leader Ner'onok in Siege of Niuzao Temple without dying or failing the encounter. Ensure your group is prepared for the wing leader's mechanics.", x = 4 },
        [10012] = { e = 5, s = "s", r = "High RNG requirement to avoid absorbing damage from fissures.", d = "Fight Fel Lord Zakuun in Hellfire Citadel while avoiding all Rumbling Fissure abilities. Stay away from fissures and coordinate with your raid to prevent absorption.", x = 5 },
        [10013] = { e = 5, s = "s", r = "High RNG requirement to survive all waves without taking damage.", d = "Defeat Kormrok in Hellfire Citadel without taking damage from any of his waves. Use defensive cooldowns and positioning to survive the wave mechanics.", x = 5 },
        [10015] = { e = 4, s = "c", h = { 43706, 43709, 43718 }, r = "Requires collecting many rare music rolls across expansions.", d = "Collect all music rolls for your garrison jukebox, including tracks from previous expansions. This is account-wide, so ensure all characters contribute to gathering tracks.", x = 5 },
        [10016] = { e = 4, s = "c", h = { 43740, 43761, 43760 }, r = "Requires collecting many rare music rolls across expansions.", d = "Gather every available music roll for the Horde garrison jukebox across all expansions. Work with other players if needed since this achievement is account-wide.", x = 5 },
        [10017] = { e = 2, s = "g", r = "Repeatable missions with steady progress toward goal.", d = "Complete ten Naval Bonus Missions in your garrison to unlock this achievement. These missions may require specific resources or time-gated events, so plan accordingly.", x = 5 },
        [10018] = { e = 4, s = "c", h = { 43784, 43785, 43789 }, r = "Requires extensive exploration and lore collection in Draenor.", d = "Finish all listed Draenor exploration achievements including exploring the zone, becoming a Loremaster, and securing the region. This unlocks the Soaring Skyterror mount reward.", x = 5 },
        [10019] = { e = 3, s = "s", r = "Single raid boss kill; requires group but straightforward.", d = "Defeat Archimonde in Hellfire Citadel as the final boss of the raid. Ensure your group is ready for his mechanics before attempting this high-difficulty encounter.", x = 5 },
        [10020] = { e = 4, s = "c", h = { 43792, 43793, 43794 }, r = "Requires defeating multiple upper-wing raid bosses.", d = "Defeat Fel Lord Zakuun, Xhul'horac, and Mannoroth in the upper reaches of Hellfire Citadel. Complete these bosses on Normal or higher to earn the Destructor's Rise achievement.", x = 5 },
        [10021] = { e = 3, s = "s", r = "Single quest step; requires specific legendary ring acquisition.", d = "Start this legacy quest by accepting Khadgar's initial tasks to unlock the legendary ring. Ensure you have access to the relevant zones before beginning, as some steps may be time-gated or require specific reputation levels.", x = 5 },
        [10023] = { e = 4, s = "c", h = { 43812, 43811, 43810 }, r = "Requires defeating multiple lower-wing raid bosses.", d = "Begin with Hellfire Assault in Wing 1 of Hellfire Citadel, then proceed to Iron Reaver and Kormrok. This wing is accessible early in the raid progression, so plan your group composition accordingly for these specific bosses.", x = 5 },
        [10024] = { e = 4, s = "c", h = { 43816, 43814, 43815 }, r = "Requires defeating multiple mid-wing raid bosses.", d = "Move to Wing 2 after clearing the first section to face Hellfire High Council, Kilrogg Deadeye, and Gorefiend. These encounters require a full raid group, so coordinate with friends or guild members before entering.", x = 5 },
        [10025] = { e = 4, s = "c", h = { 43819, 43820, 43818 }, r = "Requires defeating multiple upper-wing raid bosses.", d = "Complete the upper reaches of Hellfire Citadel by defeating Shadow-Lord Iskar, Socrethar the Eternal, and Tyrant Velhari in Wing 3. This final wing often requires higher gear levels, so ensure your group is well-equipped before starting.", x = 5 },
        [10026] = { e = 5, s = "s", r = "High-difficulty raid encounter with strict mechanic requirement.", d = "During Hellfire Assault on Normal or higher difficulty, monitor the Hellfire Cannons' health closely to keep them above 90%. This mechanic requires constant attention during the fight, so assign a dedicated player to track it.", x = 5 },
        [10027] = { e = 5, s = "s", r = "Mythic difficulty raid boss; requires high skill and group.", d = "Unlock Mythic difficulty for Hellfire Assault by first completing the Normal version and meeting the raid's gear requirements. Note that Mythic runs are significantly harder and may require additional resources or group coordination.", x = 5 },
        [10030] = { e = 4, s = "c", h = { 43850 }, r = "Requires specific loot and Mythic Mannoroth kill.", d = "First kill a Doom Lord using Empowered Felseeker, then defeat Mannoroth on Normal difficulty or higher. This achievement involves specific mechanics, so ensure your group knows how to handle the Doom Lord encounter before proceeding.", x = 5 },
        [10032] = { e = 4, s = "s", r = "Mythic Iron Reaver is a long grind.", d = "Defeat Iron Reaver on Mythic difficulty after unlocking the raid's Mythic mode. This encounter is challenging and requires precise execution, so practice with your group before attempting the achievement.", x = 5 },
        [10033] = { e = 4, s = "s", r = "Mythic Kormrok requires significant time.", d = "Complete the Mythic version of Kormrok by first clearing the Normal difficulty and ensuring your raid meets the gear threshold. This boss has complex mechanics that demand high coordination and skill.", x = 5 },
        [10034] = { e = 4, s = "s", r = "Mythic High Council is a long fight.", d = "Face Hellfire High Council on Mythic difficulty after unlocking the raid's highest setting. This encounter is one of the most demanding in the expansion, so prepare your group thoroughly before attempting it.", x = 5 },
        [10035] = { e = 4, s = "s", r = "Mythic Kilrogg Deadeye is a long grind.", d = "Complete 25 Naval Bonus Missions by participating in garrison naval events. These missions are account-wide and require a Naval Bonus Specialist, so ensure you have the necessary specialization unlocked.", x = 5 },
        [10036] = { e = 2, s = "g", r = "25 missions are quick but repetitive.", d = "Finish 25 Naval Bonus Missions to earn the Naval Bonus Expert title. This achievement is account-wide and requires consistent participation in naval events, so plan your schedule accordingly.", x = 5 },
        [10037] = { e = 4, s = "s", r = "Mythic Shadow-Lord Iskar is a long grind.", d = "Queue for Mythic Hellfire Citadel and defeat Shadow-Lord Iskar. Ensure you are in a Mythic+ group or have access to Mythic raid content, as this cannot be done on lower difficulties.", x = 5 },
        [10038] = { e = 4, s = "s", r = "Mythic Fel Lord Zakuun is a long grind.", d = "Defeat Fel Lord Zakuun in Mythic Hellfire Citadel. This requires a high-level Mythic raid group; do not attempt this on Normal or Heroic modes as the achievement will not count.", x = 5 },
        [10039] = { e = 4, s = "s", r = "Mythic Xhul'horac is a long grind.", d = "Kill Xhul'horac in Mythic Hellfire Citadel. Coordinate with your raid leader to ensure the encounter is run on Mythic difficulty, as lower difficulties will not grant this achievement.", x = 5 },
        [10040] = { e = 4, s = "s", r = "Mythic Socrethar is a long grind.", d = "Defeat Socrethar the Eternal in Mythic Hellfire Citadel. This boss requires a full Mythic raid group; ensure you are prepared for high-level mechanics before starting the encounter.", x = 5 },
        [10041] = { e = 4, s = "s", r = "Mythic Tyrant Velhari is a long grind.", d = "Kill Tyrant Velhari in Mythic Hellfire Citadel. You must be in a Mythic raid instance; attempting this on Normal or Heroic will not count toward your achievement progress.", x = 5 },
        [10042] = { e = 4, s = "s", r = "Mythic Mannoroth is a long grind.", d = "Defeat Mannoroth in Mythic Hellfire Citadel. This is a Mythic-only encounter; ensure your group is ready for the highest difficulty before engaging the boss to secure the points.", x = 5 },
        [10043] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss mechanics.", d = "Kill Archimonde in Mythic Hellfire Citadel to earn both the achievement and the Defiler's End title. This is a high-difficulty raid encounter requiring a coordinated Mythic group; do not attempt on lower difficulties.", x = 5 },
        [10052] = { e = 4, s = "c", h = { 44001, 44002, 44003 }, r = "Requires hunting rare spawns; some drops are RNG based.", d = "Collect all listed fel-corrupted pets in Tanaan Jungle for the Tiny Terrors achievement. This is account-wide and requires hunting specific rare spawns; ensure you have completed the Fel Legendary Pets prerequisite first.", x = 5 },
        [10053] = { e = 4, s = "c", h = { 44031, 44032, 44033 }, r = "Requires finding rare spawns with specific outfits; RNG involved.", d = "Find Pepe in all four outfits (Pirate, Viking, Knight, Ninja) to complete I Found Pepe. This is account-wide and requires locating specific NPCs or events; check various zones for these unique appearances.", x = 5 },
        [10054] = { e = 5, s = "s", r = "Strict timing requirement on a raid boss fight.", d = "Defeat the three Hellfire High Council members within 10 seconds of each other on Normal or higher. Coordinate your group to kill them in rapid succession without long pauses between kills to meet the time limit.", x = 5 },
        [10057] = { e = 3, s = "g", r = "Requires killing many elite mobs before the final boss.", d = "Kill ten Hellfire Guardians before defeating Iron Reaver in Hellfire Citadel on Normal or higher. Track your guardian kills carefully during the raid; missing this count will require restarting the encounter.", x = 5 },
        [10059] = { e = 4, s = "c", h = { 45355, 44073, 44375 }, r = "Requires completing multiple distinct storylines and quests.", d = "Complete all listed Highmountain storylines for Ain't No Mountain High Enough. This is account-wide and requires finishing specific quests in Highmountain; ensure you have access to Legion content or use a character that has completed these.", x = 6 },
        [10061] = { e = 4, s = "c", h = { 44087, 44088, 44089 }, r = "Requires defeating all raid champions; some are rare spawns.", d = "Defeat all four Hellfire Citadel champions, including Terrorfist and Deathtalon, as this is account-wide. Start with the main raid progression to unlock these encounters early.", x = 5 },
        [10067] = { e = 3, s = "c", h = { 44193, 44194, 44195 }, r = "Requires completing multiple Garrison campaign chapters.", d = "Complete every chapter in the Tanaan Jungle Garrison Campaign, starting with 'All Hands On Deck'. Ensure you finish all story quests before moving on.", x = 5 },
        [10068] = { e = 2, s = "c", r = "Requires visiting and completing daily objectives at various POIs.", d = "Visit each daily objective point of interest like Ironhold Harbor and Ruins of Kra'nak to complete the list. Check your map frequently for new dailies.", x = 5 },
        [10069] = { e = 4, s = "g", r = "Requires farming a specific mob for a large number of items.", d = "Farm Blackfang Claws from saberon in Fang'rila until you have 5,000. This is account-wide, so any character can contribute to the total count.", x = 5 },
        [10070] = { e = 5, s = "c", h = { 44256 }, r = "Includes Grand Warlock Nethekurse which is a rare spawn with RNG drop.", d = "Use a Jungle Hunter spec to kill all rare creatures in Tanaan Jungle, including Grand Warlock Nethekurse who drops frequently. Clear zones systematically to avoid missing rares.", x = 5 },
        [10071] = { e = 3, s = "s", r = "Requires defeating a specific boss in Tanaan Jungle.", d = "Defeat Supreme Lord Kazzak in Tanaan Jungle once he becomes available through the main raid progression.", x = 5 },
        [10072] = { e = 4, s = "c", h = { 44999, 45000 }, r = "Requires completing multiple Tanaan Jungle achievements including rare spawns and exploration.", d = "Finish all listed achievements including Hellbane and Jungle Stalker first, as they unlock the title reward. This is a major milestone achievement.", x = 5 },
        [10073] = { e = 4, s = "s", r = "Needs defeating Archimonde with a specific debuff active on Normal or higher.", d = "Enter Hellfire Citadel on Normal difficulty or higher and defeat Archimonde while the Doomfire buff remains active. Do not let the debuff expire before killing the boss, as this makes the achievement missable.", x = 5 },
        [10074] = { e = 3, s = "c", h = { 44205 }, r = "Involves completing several Garrison campaign chapters with one major invasion quest.", d = "Complete all Garrison Campaign chapters again if needed for specific objectives, ensuring you finish 'The Cipher of Damnation' last.", x = 5 },
        [10075] = { e = 3, s = "c", r = "Requires visiting and completing objectives at multiple POIs in Tanaan Jungle daily.", d = "Clear all daily objective POIs in Tanaan Jungle like The Fel Forge and Throne of Kil'jaeden. Return often as dailies reset weekly.", x = 5 },
        [10076] = { e = 4, s = "s", r = "Needs defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Unlock Heroic Bloodmaul Slag Mines first, then run Mythic to defeat Gug'rokk. This requires prior dungeon completion before attempting the harder version.", x = 5 },
        [10079] = { e = 4, s = "s", r = "Requires defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Complete Iron Docks on Heroic difficulty before attempting Mythic to defeat Skulloc. Ensure you have the necessary gear and group for the higher difficulty.", x = 5 },
        [10080] = { e = 4, s = "s", r = "Needs defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "First clear Auchindoun on Heroic to unlock Mythic. Then assemble a skilled group for the Mythic run against Teron'gor, as this content is time-gated and requires specific mechanics.", x = 5 },
        [10081] = { e = 4, s = "s", r = "Requires defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Complete Skyreach on Heroic first. You must then defeat High Sage Viryx on Mythic difficulty; note that this boss fight has strict mechanics that demand a prepared team.", x = 5 },
        [10082] = { e = 4, s = "s", r = "Needs defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Clear Grimrail Depot on Heroic to access the Mythic version. Defeat Skylord Tovra quickly, as this dungeon is time-gated and requires efficient execution of its mechanics.", x = 5 },
        [10083] = { e = 4, s = "s", r = "Requires defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Finish The Everbloom on Heroic before attempting Mythic. You must defeat Yalnu on Mythic difficulty, which involves complex mechanics that require a coordinated group effort.", x = 5 },
        [10084] = { e = 4, s = "s", r = "Needs defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Clear Shadowmoon Burial Grounds on Heroic to unlock the Mythic version. Defeat Ner'zhul on Mythic, being mindful of time gates and the specific mechanics required for this encounter.", x = 5 },
        [10085] = { e = 4, s = "s", r = "Requires defeating a dungeon boss on Mythic difficulty after unlocking Heroic.", d = "Complete Upper Blackrock Spire on Heroic first. Then run it on Mythic to defeat Warlord Zaela, keeping in mind that this dungeon is time-gated and requires precise mechanics.", x = 5 },
        [10086] = { e = 4, s = "c", r = "Strict timing mechanic adds significant difficulty.", d = "Run Hellfire Citadel Normal or higher with a group capable of handling the Soul mechanic. You must kill 20 Haunting Souls within 10 seconds before defeating Socrethar the Eternal.", x = 5 },
        [10087] = { e = 3, s = "c", r = "Avoiding mechanics requires skill but is doable solo.", d = "Clear Hellfire Citadel on Normal or higher while strictly avoiding Shadowfel Annihilations. This requires careful positioning and awareness to prevent triggering the mechanic during the Xhul'horac fight.", x = 5 },
        [10088] = { e = 4, s = "g", r = "Requires farming PvP content over multiple seasons.", d = "Grind PvP activities in Warlords Season 2 Heroic difficulty to earn 27,000 Conquest Points. This is a legacy achievement with a time gate, so start early and play consistently.", x = 5 },
        [10089] = { e = 4, s = "g", r = "Requires farming PvP content over multiple seasons.", d = "Grind PvP activities in Warlords Season 2 Arena difficulty to earn 27,000 Conquest Points. Since this is legacy content with a time gate, begin as soon as the season opens.", x = 5 },
        [10090] = { e = 4, s = "g", r = "Requires farming PvP content over multiple seasons.", d = "Grind PvP activities in Warlords Season 3 Heroic difficulty to earn 27,000 Conquest Points. This legacy achievement has a time gate, so prioritize it early in the season.", x = 5 },
        [10091] = { e = 4, s = "g", r = "Requires farming PvP content over multiple seasons.", d = "Grind PvP activities in Warlords Season 3 Arena difficulty to earn 27,000 Conquest Points. As this is legacy content with a time gate, start immediately when the season begins.", x = 5 },
        [10092] = { e = 3, s = "c", r = "Win count is grindy but achievable solo eventually.", d = "Focus on winning 3v3 Arena matches in Warlords Season 2, as this is the faster path to the Vicious Saddle mount. Avoid Rated Battlegrounds unless you prefer that mode, but note the season timer may expire soon.", x = 5 },
        [10093] = { e = 3, s = "c", r = "Win count is grindy but achievable solo eventually.", d = "This achievement mirrors the previous one; simply win 100 Arena matches or 40 Rated BGs in Warlords Season 2. Ensure you are playing during the active season to avoid missing out on the Vicious Saddle mount reward.", x = 5 },
        [10148] = { e = 2, s = "s", r = "Quest chain to get legendary ring is straightforward.", d = "Start by accepting Khadgar's quests in your garrison to begin acquiring the legendary ring components. Complete \"Draenor's Blessing\" as part of this chain, but be aware that legendary crafting can take significant time and specific resources.", x = 5 },
        [10149] = { e = 5, s = "c", r = "Requires completing all other Hellfire Citadel achievements first.", d = "Queue for Hellfire Citadel raids and aim to complete all listed sub-achievements like \"Nearly Indestructible\" and \"Turning the Tide.\" This is account-wide, so coordinate with your raid group to cover every objective efficiently before the raid closes.", x = 5 },
        [10154] = { e = 3, s = "g", r = "Farming naval missions takes time but is consistent.", d = "Unlock Naval Combat missions in your garrison and complete 50 of them to earn the Expert title. Prioritize these missions early since they are time-gated by the expansion's lifecycle and require specific naval combat specialists.", x = 5 },
        [10155] = { e = 3, s = "g", r = "Farming naval missions takes time but is consistent.", d = "Complete 25 Naval Siege missions after unlocking the required specialist. These missions are part of a chain, so ensure you progress through the prerequisite \"Naval Siege Specialist\" achievement first to keep your garrison bonuses active.", x = 5 },
        [10156] = { e = 3, s = "g", r = "Requires completing 25 specific naval combat missions.", d = "Begin by completing 25 Naval Combat missions to unlock the Specialist title. This is the first step in a chain leading to the Expert rank, so do not skip this phase or you will miss out on subsequent rewards.", x = 5 },
        [10159] = { e = 3, s = "g", r = "Requires completing 25 specific naval treasure missions.", d = "Start with 25 Naval Treasure missions to earn the Specialist title. These missions are distinct from combat or siege tasks, so check your garrison menu regularly to queue up treasure hunting expeditions without delay.", x = 5 },
        [10160] = { e = 4, s = "g", r = "Requires 50 missions plus the previous achievement.", d = "After earning the Naval Treasure Specialist title, complete an additional 25 missions to reach the Expert rank. Be mindful that these missions may have limited availability depending on the game's current naval event schedule.", x = 5 },
        [10161] = { e = 3, s = "g", r = "Requires completing 10 specific naval siege missions.", d = "Complete 10 Naval Siege missions first to unlock the Specialist title. This is a short-term goal, but ensure you do not delay it too long as garrison achievements often expire with the expansion.", x = 5 },
        [10162] = { e = 3, s = "g", r = "Requires completing 10 specific naval training missions.", d = "Finish 10 Naval Training missions to earn the Specialist title. These are quick objectives, so prioritize them early in your garrison progression to unlock the next tier of training missions and rewards.", x = 5 },
        [10163] = { e = 4, s = "g", r = "Requires 25 missions plus the previous achievement.", d = "Once you have the Naval Training Specialist title, complete 25 more training missions to reach Expert status. Keep an eye on mission availability, as these can be time-sensitive and may not always be available in your garrison.", x = 5 },
        [10164] = { e = 4, s = "c", h = { 44531, 44533, 44532 }, r = "Meta achievement requiring completion of multiple expert naval missions.", d = "Start by completing the specific naval meta-achievements listed in the info field to unlock the title. Focus on one expert category at a time, such as combat or treasure hunting, to track progress easily. Be aware that this is account-wide and requires full access to all naval mission types.", x = 5 },
        [10165] = { e = 5, s = "c", h = { 44539, 44537, 53205 }, r = "Requires upgrading all ships to Epic, a very hard task.", d = "You must upgrade every single ship type listed in the info field to Epic rarity before claiming the achievement. Prioritize gathering resources for the most expensive ships first, as they often require more time and gold. This is account-wide, so ensure your entire account has completed the upgrades.", x = 5 },
        [10166] = { e = 4, s = "c", h = { 44554, 44547, 44555 }, r = "Requires obtaining all naval equipment blueprints.", d = "Collect all the specific naval equipment blueprints listed in the info field by completing various garrison missions and world events. Some items like the Blast Furnace may be rare drops or require specific quest chains to unlock. Check your collection frequently as missing even one blueprint will prevent completion.", x = 5 },
        [10167] = { e = 5, s = "c", h = { 44813, 44815, 44818 }, r = "Requires completing all rare naval missions.", d = "Complete every Rare Naval Mission listed in the info field, noting that some must be done three times. Start with the easier missions first to build up your fleet and resources needed for the harder ones. This is account-wide and requires you to chart a course before accessing these specific rare content slots.", x = 5 },
        [10168] = { e = 2, s = "s", r = "Single step to upgrade shipyard to level 3.", d = "Upgrade your shipyard directly to level 3 as indicated in the info field, ensuring you have enough garrison resources. Do not stop at level 2, or you will miss this step in the chain. This achievement is tied to the Naval Fleet prerequisite, so ensure that is completed first.", x = 5 },
        [10169] = { e = 2, s = "s", r = "Single step to upgrade shipyard to level 2.", d = "Upgrade your shipyard to level 2 as the first step in the naval progression chain. Gather the necessary resources and complete any associated garrison quests to reach this level. Once done, you can immediately proceed to upgrade it further for the next achievement.", x = 5 },
        [10170] = { e = 3, s = "g", r = "Grinding 50 naval missions takes several hours.", d = "Complete exactly 50 Naval Missions to earn this title and receive the Admiral's Compass reward. Track your mission count carefully since completing more than needed does not hurt but ensures faster completion of subsequent tiers. This is account-wide, so missions completed by any character count toward your total.", x = 5 },
        [10172] = { e = 4, s = "g", r = "Grinding 100 missions is a long solo task.", d = "Finish 100 Naval Missions after unlocking the Seaman achievement to progress as a Petty Officer. Continue running naval missions efficiently, perhaps focusing on high-reward ones to speed up the process. Remember that this is account-wide and builds directly into the Fleet Commander requirement.", x = 5 },
        [10173] = { e = 5, s = "g", r = "500 missions is a massive grind requiring days.", d = "Accumulate 500 total Naval Missions by continuing to run missions after reaching the Petty Officer tier. This is a grind, so consider running multiple missions in a row or using efficient routes. Once you hit the count, you will unlock the path to becoming an Admiral.", x = 5 },
        [10174] = { e = 5, s = "g", r = "1000 missions is an extreme solo grind.", d = "Complete 1000 Naval Missions total to achieve the highest naval rank and claim your rewards. This is a long-term goal requiring consistent play over many weeks or months. Ensure you have unlocked all previous tiers first, as this achievement has no direct prerequisites other than the mission count.", x = 5 },
        [10177] = { e = 2, s = "s", r = "Building a shipyard is a quick single step.", d = "Construct a shipyard at your garrison to unlock the entire naval progression chain. Visit the garrison menu and build the shipyard structure if it is not already there. This is the very first step in the naval series, so do it early in your Draenor playthrough.", x = 5 },
        [10253] = { e = 4, s = "s", r = "Mythic raid boss requires a group and time.", d = "Defeat Gorefiend specifically on Mythic difficulty within Hellfire Citadel to earn this raid achievement. Ensure you are running the correct difficulty setting and that your group is prepared for the high-level mechanics. This is a single-player or group requirement depending on how you approach the boss, but the difficulty must be set correctly.", x = 5 },
        [10255] = { e = 3, s = "g", r = "Grinding 100 missions is a moderate solo task.", d = "Start by completing any available naval missions to reach the Seaman requirement quickly. Focus on daily content to efficiently hit the 100 mission count needed for this title.", x = 5 },
        [10256] = { e = 4, s = "c", h = { 44560 }, r = "Rare missions are RNG dependent and time consuming.", d = "Unlock all rare naval missions first, then queue for them repeatedly until you complete three of each listed objective. Note that some missions may have long cooldowns or require specific group compositions.", x = 5 },
        [10258] = { e = 4, s = "c", h = { 44820, 44823 }, r = "Rare missions are RNG dependent and time consuming.", d = "This is the Horde version of the previous achievement; follow the same strategy as id=10256 but ensure you are on the Horde faction to unlock these specific rare missions.", x = 5 },
        [10259] = { e = 4, s = "g", r = "Killing 25 rare creatures is a long solo grind.", d = "Prioritize killing rare creatures in Tanaan Jungle, focusing on those with high drop rates or easier mechanics to reach the 25 kill count. Be aware that some rares may be missable if they despawn before you defeat them.", x = 5 },
        [10260] = { e = 3, s = "c", h = { 44878, 44882 }, r = "Exploring map is moderate but requires travel.", d = "Explore every zone of Tanaan Jungle by interacting with world objects and defeating enemies in covered areas. This is a time-gated achievement, so complete it early before the zone becomes inaccessible.", x = 5 },
        [10261] = { e = 3, s = "g", r = "Finding 20 treasures takes a few hours of searching.", d = "Search for treasure chests scattered throughout Tanaan Jungle, using addons or guides to locate them efficiently. Ensure you collect all 20 treasures before moving on to the next tier of this chain.", x = 5 },
        [10262] = { e = 4, s = "g", r = "Requires finding 51 specific treasures across the zone.", d = "After completing id=10261, continue searching for the remaining treasures in Tanaan Jungle until all 51 are discovered. This is account-wide, so coordinate with friends if you want to speed up the process.", x = 5 },
        [10265] = { e = 4, s = "c", h = { 45009 }, r = "Depends on Jungle Treasure Master which is a grind.", d = "Complete all listed achievements in this category first, as they are prerequisites for earning the title of the Jungle. Some quests may be time-gated or require specific story progression.", x = 5 },
        [10275] = { e = 3, s = "g", r = "Requires completing 500 naval missions in the garrison.", d = "Queue for naval missions daily to accumulate 500 completions efficiently. This is a grind-heavy achievement, so plan your time accordingly and consider grouping with others to speed up progress.", x = 5 },
        [10276] = { e = 3, s = "g", r = "Requires completing 1000 naval missions in the garrison.", d = "Continue completing naval missions after reaching the Fleet Commander rank to hit the 1000 mission goal. This is another long-term grind, so maintain consistency in your daily routine.", x = 5 },
        [10307] = { e = 4, s = "c", h = { 45109 }, r = "Includes rare mission 'The House Always Wins' requiring RNG.", d = "Unlock and complete all rare naval missions listed, ensuring you meet any faction or level requirements. Some of these may be missable if not completed within a certain timeframe or after zone changes.", x = 5 },
        [10348] = { e = 4, s = "g", r = "Requires finding 100 specific treasures outside Tanaan Jungle.", d = "Explore Draenor zones outside Tanaan Jungle to find treasures, using addons to track progress toward the 100 treasure goal. This is account-wide, so coordinate with friends to cover more ground efficiently.", x = 5 },
        [10349] = { e = 5, s = "c", h = { 45691 }, r = "Requires earning Revered rep with Horde factions via heavy RNG.", d = "Grind Revered with Horde factions in Tanaan Jungle; this is account-wide so play any class. Avoid missing daily quests as reputation caps are strict.", x = 5 },
        [10350] = { e = 5, s = "c", h = { 45693 }, r = "Requires earning Revered rep with Alliance factions via heavy RNG.", d = "Grind Revered with Alliance factions in Tanaan Jungle; this is account-wide so play any class. Avoid missing daily quests as reputation caps are strict.", x = 5 },
        [10353] = { e = 2, s = "c", r = "Collecting five specific toys is relatively easy.", d = "Buy or find the five Crashin' Thrashin' Iron Armada toys during Winter Veil events. These drop from specific vendors or world drops and are account-wide.", x = 5 },
        [10354] = { e = 3, s = "g", r = "Requires collecting 200 toys, a moderate grind.", d = "Open toy chests to reach 200 toys for the Toymaster chain. This is account-wide, so share progress across characters if you have multiple alts.", x = 5 },
        [10355] = { e = 4, s = "g", r = "Requires obtaining 300 mounts, a long-term collection goal.", d = "Collect 300 unique mounts usable by one character; this is account-wide. Focus on rare drops and vendor purchases rather than just buying duplicates.", x = 5 },
        [10356] = { e = 4, s = "g", r = "Requires obtaining 300 mounts, a long-term collection goal.", d = "Collect 300 unique mounts usable by one character; this is account-wide. Focus on rare drops and vendor purchases rather than just buying duplicates.", x = 5 },
        [10365] = { e = 2, s = "s", r = "Find a specific NPC in a zone; trivial once located.", d = "Find Spooky Pepe in his scarecrow costume during Hallow's End events. He appears randomly in specific zones like Teldrassil or Stormwind.", x = 5 },
        [10398] = { e = 2, s = "s", r = "Talk to an NPC and stand near a drum; very easy.", d = "Travel to Highmountain and visit the Thunder Drum to join a drum circle event. Ensure you are present when the event timer starts.", x = 6 },
        [10411] = { e = 5, s = "c", r = "Requires Mythic Maw of Souls; high skill ceiling and RNG.", d = "Run Maw of Souls on Mythic difficulty and rescue the Val'kyr before they die. This requires a full group and specific dungeon completion.", x = 6 },
        [10412] = { e = 5, s = "c", r = "Requires Mythic Maw of Souls with strict group buff condition.", d = "Defeat Helya in Maw of Souls on Mythic while everyone wears the Poor Unfortunate Souls set. Coordinate with your group to equip the set first.", x = 6 },
        [10413] = { e = 5, s = "c", r = "Requires Mythic Maw of Souls; heavy RNG on killing order.", d = "Kill six Risen Warriors before defeating Ymiron in Maw of Souls on Mythic. Use a tanky setup to survive the adds while killing them quickly.", x = 6 },
        [10456] = { e = 5, s = "c", r = "Requires Mythic Eye of Azshara; strict zero-death mechanic.", d = "Defeat Warlord Parjesh in Eye of Azshara on Mythic without losing any Hatecoil Shellbreakers. Protect the adds carefully during the boss fight.", x = 6 },
        [10457] = { e = 5, s = "c", r = "Requires Mythic Eye of Azshara; strict mechanic and RNG.", d = "Run Eye of Azshara Mythic with a Curse of the Witch active to destroy Saltsea Globules before killing Lady Hatecoil. Ensure you maintain the curse on one target while pulling adds to hit the 11 globule count.", x = 6 },
        [10458] = { e = 5, s = "c", r = "Requires Mythic Eye of Azshara; strict zero-hit mechanic.", d = "Defeat the Wrath of Azshara on Mythic without taking Magic or Frost Resonance damage. Use defensive cooldowns and positioning to avoid these specific mechanics during the fight.", x = 6 },
        [10459] = { e = 3, s = "s", r = "Complete a quest line; moderate time but no RNG.", d = "Complete the Balance of Power quest line in your Class Hall to unlock the new artifact appearance. This is account-wide, so any character can finish it for everyone.", x = 6 },
        [10460] = { e = 3, s = "s", r = "Locate hidden appearance; requires exploration but no grind.", d = "Locate and unlock a hidden artifact appearance by completing specific class hall quests or events. Check your class hall interface for available hidden options once unlocked.", x = 6 },
        [10461] = { e = 5, s = "c", r = "Requires multiple steps including rare drop and campaign.", d = "Unlock all four base color variations for your original artifact by recovering Pillars of Creation and completing Light's Charge. Finish the first order campaign effort to ensure all colors are available.", x = 6 },
        [10542] = { e = 5, s = "c", r = "Requires Mythic Halls of Valor; strict mechanic and RNG.", d = "Splash all four vrykul kings with a Mug of Mead in Halls of Valor Mythic. Coordinate with your group to throw mugs at each king during the encounter.", x = 6 },
        [10543] = { e = 4, s = "c", r = "Mythic dungeon boss with strict zero-fail condition.", d = "Defeat Odyn on Mythic ensuring no Stormforged Obliterators successfully cast Surge. Monitor add spawns and kill them quickly before they can use this mechanic.", x = 6 },
        [10544] = { e = 3, s = "g", r = "Requires specific mechanic timing on Mythic boss.", d = "Allow a Storm Drake to gain 10 Killing Blow stacks before defeating it in Halls of Valor Mythic. Do not kill the drake immediately; let it build up the stacks first.", x = 6 },
        [10553] = { e = 4, s = "c", r = "Mythic boss requiring specific Heroic encounter state.", d = "Defeat Millificent Manastorm on Violet Hold Mythic after she becomes very cross with you. Progress through the encounter until her aggression meter fills before finishing the fight.", x = 6 },
        [10554] = { e = 3, s = "g", r = "Requires killing a specific mob before the boss.", d = "Slay a Black Bile mob before defeating Festerface in Assault on Violet Hold Mythic. Keep an eye on trash mobs to ensure you kill one of these specific targets first.", x = 6 },
        [10555] = { e = 4, s = "c", r = "Mythic raid boss with pre-fight RNG requirement.", d = "Defeat Nythendra in The Emerald Nightmare after squishing 15 Glow Bugs on Normal or higher difficulty. Clear out the glowing bugs during the raid encounter before killing the boss.", x = 6 },
        [10561] = { e = 1, s = "s", r = "Simple spell learn in PvP or Arena.", d = "Enter any Battleground or Arena to learn the Honorable Medallion spell. This is a one-time unlock that applies to your account once you complete the requirement.", x = 6 },
        [10575] = { e = 3, s = "g", r = "Requires quenching embers during Mythic raid fight.", d = "Defeat Krosus in The Nighthold after quenching 15 Burning Embers on Normal difficulty or higher. This is a raid achievement, so coordinate with your group to ensure embers are collected before the final boss encounter.", x = 6 },
        [10580] = { e = 4, s = "g", r = "Grinding 3200 skill points across four professions.", d = "Obtain 800 skill points in Fishing, First Aid, Cooking, and Archaeology. Since this is account-wide, any character can contribute, but focus on leveling these specific professions first as they do not carry over from previous expansions.", x = 6 },
        [10581] = { e = 3, s = "g", r = "Requires grinding two professions to 100 skill points.", d = "Reach 100 skill points in a Legion-category primary profession twice to earn this title. Start by leveling one profession to max, then immediately begin the second; remember that secondary professions like Mining or Herbalism do not count toward this specific goal.", x = 6 },
        [10582] = { e = 3, s = "g", r = "Grinding one profession to 100 skill points.", d = "Gain 100 skill points in any single Legion-category primary profession. This is a stepping stone for the next achievement, so prioritize leveling one craftable or gathering profession to its cap before moving on.", x = 6 },
        [10583] = { e = 4, s = "c", r = "Requires raising all 12 professions to max skill.", d = "Raise all primary professions to 100 skill points in the Legion category. Since this is account-wide, you can switch characters freely, but note that secondary professions like Mining and Herbalism are excluded from this specific set of goals.", x = 6 },
        [10585] = { e = 1, s = "s", r = "Simple quest completion to unlock forge.", d = "Learn how to use the Obliterum Forge by completing the quest Firing Up the Forge. This unlocks a new crafting mechanic, so ensure you have the necessary materials and time to complete the initial tutorial before attempting mass production.", x = 6 },
        [10586] = { e = 3, s = "g", r = "Crafting 50 items takes a few hours of grinding.", d = "Obliterate 50 crafted items in the Obliterum Forge. You can craft any item using the forge, but be mindful of material costs; this is account-wide so multiple characters can help reach the goal faster.", x = 6 },
        [10587] = { e = 4, s = "s", r = "Requires high RNG luck to get 250k points in one run.", d = "Achieve 250,000 points in a single jewelcrafting minigame. This requires patience and consistent play, as the point total resets if you switch characters or leave the game; stick with one character to maximize progress.", x = 6 },
        [10588] = { e = 3, s = "g", r = "Reaching level 20 in the tutorial requires repeated attempts.", d = "Reach level 20 in the Blingtron Circuit Tutorial minigame. This is an engineering-specific achievement, so ensure you have the required engineering skill and materials before attempting the tutorial sequence.", x = 6 },
        [10589] = { e = 3, s = "g", r = "Gaining 100 skill points involves cooking many dishes.", d = "Obtain 100 skill points in the Legion category of cooking. Focus on completing quests and cooking recipes that grant experience points, as this is a prerequisite for other cooking-related achievements.", x = 6 },
        [10591] = { e = 2, s = "s", r = "Completing one specific quest is straightforward.", d = "Work with Nomi to open the test kitchen by completing the associated quest. This unlocks new cooking opportunities, so ensure you have the necessary ingredients and time to complete the quest before proceeding.", x = 6 },
        [10592] = { e = 3, s = "g", r = "Placing 100 work orders requires repeated visits to Nomi.", d = "Place 100 work orders with Nomi to earn this achievement. This is account-wide, so multiple characters can contribute, but be mindful of the daily limit on work orders if applicable; plan your cooking sessions accordingly.", x = 6 },
        [10593] = { e = 1, s = "s", r = "Obtaining a buff is trivial and takes minutes.", d = "Cook Yummy Bacon recipes repeatedly until you secure the 6-hour buff, as it is a rare drop with no guaranteed method. This achievement is not time-gated but requires patience and luck to obtain the specific buff item.", x = 6 },
        [10594] = { e = 3, s = "g", r = "Fishing for skill points requires catching many fish.", d = "Fish in Legion zones to gain skill points toward the 100-point goal for this category. Since fishing skill gains are account-wide, you can fish anywhere in the expansion without needing a specific character.", x = 6 },
        [10595] = { e = 4, s = "c", r = "Catching rare fish is RNG-heavy and time-consuming.", d = "Catch any of the listed rare Legion fish to complete this set; these drops are random and may require extensive fishing sessions. Ensure you have high enough fishing skill to catch them before attempting this achievement.", x = 6 },
        [10596] = { e = 4, s = "c", r = "Completing the full list of rare fish is a long grind.", d = "Complete 'A Cast Above the Rest' first, then fish for all remaining rare Legion fish to finish this account-wide goal. Some of these fish are harder to find than others, so be prepared for a long grind.", x = 6 },
        [10597] = { e = 3, s = "g", r = "Catching 100 normal fish takes several hours of fishing.", d = "Fish normally in Legion zones until you reach 100 normal fish catches; this count is shared across your entire account. You do not need rare fish for this specific achievement.", x = 6 },
        [10598] = { e = 4, s = "c", r = "Completing 20 world quests involves significant travel and RNG.", d = "Accept and complete any of the available Fishing World Quests in Legion to progress toward the 20 required completions. These quests appear randomly, so check your quest log frequently for new opportunities.", x = 6 },
        [10599] = { e = 2, s = "g", r = "Grinding skill points is moderate but soloable.", d = "Gain First Aid skill points by bandaging yourself or others until you reach 800 total points. This is a legacy achievement that requires unlocking Draenor Medic first if you are starting fresh.", x = 6 },
        [10600] = { e = 3, s = "g", r = "Grinding archaeology skill points takes several hours.", d = "Dig up artifacts in Legion zones to earn Archaeology skill points toward the 800-point goal. Unlock the prerequisite Draenor Archaeologist achievement before attempting this one if you are new to the expansion.", x = 6 },
        [10601] = { e = 4, s = "c", h = { 47803 }, r = "Crown Jewels of Suramar is the hardest rare find.", d = "Excavate rare archaeological finds from any dig site in Legion to complete this set; these drops are random and account-wide. You only need one of each listed item to finish the achievement.", x = 6 },
        [10602] = { e = 4, s = "c", r = "Crown Jewels of Suramar is the hardest rare find.", d = "Complete 'Surveying the Land' first, then collect eight specific rare archaeological finds to progress further. These items drop randomly from dig sites, so you may need to excavate many artifacts before getting all required pieces.", x = 6 },
        [10603] = { e = 5, s = "c", r = "Requires all rares including the very hard Crown Jewels.", d = "Finish 'This Side Up' next, then hunt for every remaining rare archaeological find listed in this achievement. Some of these are extremely rare drops, making this a lengthy process that requires patience and luck.", x = 6 },
        [10604] = { e = 5, s = "c", r = "Restoring all artifacts is a massive account-wide grind.", d = "Restore all pristine Legion artifacts by excavating enough dig sites to unlock each one; this is an account-wide goal requiring significant time investment. Prioritize finding the rarer artifacts first since they take longer to obtain.", x = 6 },
        [10605] = { e = 3, s = "c", r = "Grinding common artifacts is moderate but tedious.", d = "Focus on finding common Legion artifacts from any digsite, as this is account-wide and requires one of each item. Prioritize sites that drop multiple artifacts to speed up completion.", x = 6 },
        [10606] = { e = 4, s = "g", r = "Finding all Titan relic pieces requires extensive travel.", d = "Help Brann find all pieces for his titan relic by exploring various zones and completing specific archaeology tasks. This achievement is account-wide, so coordinate with friends if needed.", x = 6 },
        [10607] = { e = 3, s = "g", r = "Completing 50 digsites is a moderate time investment.", d = "Complete 50 Legion Digsites to unlock this achievement, which is part of a chain leading to higher counts. Start early as it builds toward the next tier.", x = 6 },
        [10608] = { e = 4, s = "g", r = "Completing 100 digsites is a long grind.", d = "Finish 100 Legion Digsites, building on the previous milestone. This is account-wide and requires consistent archaeology play across multiple zones.", x = 6 },
        [10609] = { e = 5, s = "g", r = "Completing 250 digsites is an extremely long grind.", d = "Reach 250 Legion Digsites to earn the title The Groundbreaker. This is a long-term goal requiring extensive archaeology efforts over time.", x = 6 },
        [10610] = { e = 4, s = "s", r = "Requires specific Mythic dungeon run with mechanics.", d = "Disable watchposts and defeat Patrol Captain Gerdo in Court of Stars on Mythic difficulty for this achievement. Ensure all conditions are met before engaging him.", x = 6 },
        [10611] = { e = 3, s = "s", r = "Requires specific Mythic dungeon run with timing.", d = "Witness the conversation between Advisor Melandrus and Grand Magistrix Elisande in Court of Stars on Mythic difficulty. Be present during the cutscene to complete it.", x = 6 },
        [10617] = { e = 2, s = "c", r = "Quest chain is straightforward and account-wide.", d = "Establish relations with the Nightfallen by completing their storylines, including unlocking Suramar World Quests. Follow quest chains carefully to avoid missing steps.", x = 6 },
        [10626] = { e = 1, s = "s", r = "Simple race event with no complex requirements.", d = "Help Zoom win the snail race in Stonedark Grotto for this simple achievement. Participate in the event and ensure Zoom wins the race.", x = 6 },
        [10627] = { e = 2, s = "s", r = "Short climb to a specific location point.", d = "Ascend to the top of Nashal's Watch in Stormheim to complete this exploration achievement. Climb the structure fully to trigger the completion.", x = 6 },
        [10663] = { e = 5, s = "c", r = "Raid boss fight with strict RNG item requirement.", d = "Defeat Ysondre in The Emerald Nightmare while all raid members have Dream Essences from all four gateway locations on Normal or higher. Coordinate with your group to collect essences before the fight.", x = 6 },
        [10665] = { e = 2, s = "g", r = "Exploration grind across a zone is moderate.", d = "Explore Azsuna by revealing covered areas of the world map, including specific zones like Faronaar and Temple of Lights. Travel thoroughly across the zone to uncover all regions.", x = 6 },
        [10666] = { e = 2, s = "g", r = "Exploration grind across a zone is moderate.", d = "Explore Val'sharah by visiting every named location listed in the info field. This is account-wide and requires revealing all covered map areas, so ensure you visit each zone completely before moving on.", x = 6 },
        [10667] = { e = 2, s = "g", r = "Exploration grind across a zone is moderate.", d = "Visit every named location in Highmountain to reveal the map. Since this is account-wide, coordinate with friends if needed to cover all zones efficiently without missing any spots.", x = 6 },
        [10668] = { e = 2, s = "g", r = "Exploration grind across a zone is moderate.", d = "Explore Stormheim by visiting all listed locations, including the Maw of Nashal. This achievement is account-wide, so make sure every zone is fully explored before claiming the reward.", x = 6 },
        [10669] = { e = 2, s = "g", r = "Exploration grind across a zone is moderate.", d = "Travel to Suramar and visit each named location to reveal the map. As this is account-wide, ensure you complete all zones thoroughly to avoid missing any required areas.", x = 6 },
        [10671] = { e = 1, s = "s", r = "Automatic legacy status check, no action needed.", d = "This legacy achievement tracks if you reached level 110 before Shadowlands. You cannot earn it now; check your character history or ignore it as it is already resolved for most players.", x = 6 },
        [10672] = { e = 4, s = "g", r = "High reputation grind with significant point totals.", d = "Earn Revered reputation with all six Broken Isles factions listed. Farm daily quests and world drops efficiently, noting that this is account-wide so progress carries across characters.", x = 6 },
        [10678] = { e = 4, s = "c", r = "Strict mechanics and positioning required in a raid.", d = "Defeat Skorpyron in The Nighthold Normal or higher while keeping all players inside the center rings. Do not leave the rings during the fight, as this is a strict requirement for completion.", x = 6 },
        [10679] = { e = 5, s = "s", r = "High difficulty dungeon with strict buff requirement.", d = "Defeat Ash'Golm in Vault of the Wardens Mythic while keeping all party members Fired Up. Coordinate with your group to maintain buffs throughout the entire encounter without dropping any.", x = 6 },
        [10680] = { e = 4, s = "s", r = "Complex mechanics on a Mythic+ dungeon boss.", d = "Defeat Cordana in Vault of the Wardens Mythic after navigating Creeping Doom correctly. Ensure you do not hold Elune's Light while she is airborne to satisfy the achievement criteria.", x = 6 },
        [10681] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Collect 100 unique head slot appearances by equipping various gear and transmogs. This is account-wide, so use multiple characters or trade items to reach the count faster.", x = 6 },
        [10682] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Gather 100 unique chest slot appearances through gear collection and transmogging. Since this is account-wide, equip different sets across your characters to unlock all required items quickly.", x = 6 },
        [10684] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Acquire 100 distinct leg slot appearances by equipping various armor pieces. This is account-wide, so utilize multiple characters or trade channels to find and equip rare leggings efficiently.", x = 6 },
        [10685] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Unlock any feet item first to start the counter, then equip different sets from vendors or drops until you hit 100 unique looks. Since this is account-wide, coordinate with friends to share rare items if needed.", x = 6 },
        [10686] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Equip various waist items like belts and pants from your inventory or mail; aim for 100 distinct appearances by mixing sets. This is account-wide so you can collect them across all characters without repeating the same look.", x = 6 },
        [10687] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Back pieces are often found in raids or world drops, so focus on getting unique ones rather than just any item. You need 200 total, so plan to grind high-level content where rare back armor appears frequently.", x = 6 },
        [10688] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Wrist items include bracers and gloves; equip different sets from your collection until you reach 100 unique appearances. Check mail for old gear that might count toward this goal if you have many characters.", x = 6 },
        [10689] = { e = 3, s = "g", r = "Requires collecting many items across the game.", d = "Combine weapon and off-hand slots by equipping various swords, daggers, bows, etc., aiming for 100 distinct looks. Many weapons drop from world bosses or raids, so explore different zones for variety.", x = 6 },
        [10690] = { e = 2, s = "g", r = "Small count of tabards makes this easier.", d = "Tabards are rare but can be bought from vendors or dropped in dungeons; you only need 15 unique ones. Focus on getting tabards from different factions or event rewards to complete this quickly.", x = 6 },
        [10691] = { e = 1, s = "g", r = "Collecting items is trivial once unlocked.", d = "Shirt slot items include tunics and robes; equip different sets from your inventory until you have 15 unique appearances. This is account-wide so share rare shirts with friends if needed.", x = 6 },
        [10692] = { e = 1, s = "g", r = "Collecting items is trivial once unlocked.", d = "Shoulder pieces are common in raids and world drops; aim for 100 unique looks by mixing armor types like plate, mail, and cloth. Check your mail for old shoulder items from previous expansions.", x = 6 },
        [10693] = { e = 1, s = "g", r = "Collecting items is trivial once unlocked.", d = "Hand slot items include gloves and bracers; equip different sets from your collection until you reach 100 unique appearances. Many hand items drop from world bosses or raids, so explore different zones for variety.", x = 6 },
        [10694] = { e = 2, s = "c", h = { 48897 }, r = "Requires unlocking other slots; Tabard is hardest.", d = "Complete all individual Fashionista achievements first before unlocking this one, as it requires every sub-achievement to be finished. This is account-wide so coordinate with friends to share rare items if needed.", x = 6 },
        [10696] = { e = 5, s = "g", r = "High RNG requirement makes this very hard.", d = "Defeat Gul'dan in The Nighthold after killing 16 Eyes of Gul'dan within 3 seconds on Normal or higher difficulty. Coordinate with your group to quickly kill the eyes before engaging the final boss.", x = 6 },
        [10697] = { e = 4, s = "c", r = "Requires specific mechanics and raid progress.", d = "Activate all spotlights around the Nightwell before defeating the Chronomatic Anomaly in The Nighthold on Normal or higher difficulty. Ensure you interact with every spotlight location before starting the final encounter.", x = 6 },
        [10698] = { e = 4, s = "c", h = { 48971 }, r = "Storyline completion takes significant time.", d = "Complete all Val'sharah storylines in any order; this is account-wide and requires finishing specific quests like Archdruid of the Vale.", x = 6 },
        [10699] = { e = 5, s = "g", r = "Heavy RNG and specific raid mechanics.", d = "Run The Nighthold Normal or higher to get betrayed by an Infinite Whelpling before defeating Grand Magistrix Elisande.", x = 6 },
        [10704] = { e = 5, s = "g", r = "High skill ceiling and strict damage limits.", d = "Defeat Tichondrius on Normal or higher without taking damage from Echoes of the Void; use defensive cooldowns and avoid void mechanics.", x = 6 },
        [10706] = { e = 2, s = "g", r = "Recruiting troops is easy but takes time.", d = "Recruit five troops at your class hall to unlock this achievement; it is account-wide and part of a larger chain.", x = 6 },
        [10707] = { e = 4, s = "s", r = "Requires Mythic dungeon run with specific mechanics.", d = "Clear Vault of the Wardens on Mythic difficulty to illuminate and free the Specter of Vengeance.", x = 6 },
        [10709] = { e = 3, s = "g", r = "Finding pages takes time but is doable solo.", d = "Read all pages of Illysanna Ravencrest's diary in Black Rook Hold; this is account-wide and requires finding scattered items.", x = 6 },
        [10710] = { e = 3, s = "s", r = "Requires specific Mythic dungeon run and boss kill order.", d = "Defeat the Amalgam of Souls on Mythic difficulty after killing a Frustrated Soul in Black Rook Hold.", x = 6 },
        [10711] = { e = 4, s = "s", r = "High difficulty raid fight with strict no-kill mechanic.", d = "Kill Illysanna Ravencrest on Mythic without damaging her allies; coordinate with your group to focus only on the boss.", x = 6 },
        [10722] = { e = 3, s = "g", r = "Account-wide fishing grind; effort scales linearly with count.", d = "Fish all specified coins from the Broken Isles Dalaran fountain; this is account-wide and may take significant time.", x = 6 },
        [10742] = { e = 3, s = "s", r = "Raid fight requiring food management and specific difficulty.", d = "Defeat Trilliax in The Nighthold on Normal or higher while consuming no more than 20 Toxic Slices.", x = 6 },
        [10743] = { e = 2, s = "s", r = "Quest-based PvP achievement; requires reaching rank 50.", d = "Reach Prestige level 1, rank 50 for the Alliance by completing the quest The Victor's Spoils.", x = 6 },
        [10745] = { e = 2, s = "s", r = "Quest-based PvP achievement; requires reaching rank 50.", d = "Reach Prestige level 1, rank 50 for the Horde by completing the quest The Victor's Spoils.", x = 6 },
        [10746] = { e = 3, s = "s", r = "Requires completing artifact upgrade campaign quests.", d = "Complete your Order Campaign questline to unlock the new artifact weapon appearance. This is a straightforward progression task with no time gates or group requirements.", x = 6 },
        [10747] = { e = 2, s = "c", r = "Collect specific artifact color unlock quests.", d = "Unlock all four color variations for your upgraded artifact by completing the specific upgrade quests listed in the info field. Ensure you finish each required step sequentially as they are tied to artifact upgrades.", x = 6 },
        [10748] = { e = 3, s = "c", r = "Requires valor points and specific artifact upgrade quests.", d = "Unlock the valorous artifact colors by finishing the associated quests, which may require reaching certain reputation levels or completing specific challenges. Check your quest log for the exact requirements listed under Artifacts - Valorous Color Unlocks.", x = 6 },
        [10749] = { e = 2, s = "c", r = "Requires reaching high honor levels; effort scales with rank.", d = "Unlock the war-torn artifact colors by gaining enough Honor points to reach levels 10, 30, 50, and 80. This is a solo-friendly achievement but requires significant time spent in PvP or battlegrounds.", x = 6 },
        [10750] = { e = 3, s = "s", r = "Specific artifact appearance unlock condition.", d = "The hidden artifact appearance unlock depends on completing the Fighting with Style: Hidden prerequisite. Since no specific quests are listed, ensure you have completed all related Legion content first.", x = 6 },
        [10753] = { e = 4, s = "s", r = "Raid fight requiring specific mechanic (keeping pet alive).", d = "Defeat Ursoc in The Emerald Nightmare while keeping Tur Ragepaw alive on Normal difficulty or higher. This requires careful raid mechanics management and coordination during the encounter.", x = 6 },
        [10754] = { e = 4, s = "s", r = "Requires specific raid mechanics and group coordination.", d = "Defeat High Botanist Tel'arn with all raid members afflicted by Arcane Exposure on Normal difficulty or higher. Coordinate your group to maintain the debuff throughout the entire fight.", x = 6 },
        [10755] = { e = 4, s = "g", r = "Grinding multiple phases of a complex raid encounter.", d = "Defeat Xavius in The Emerald Nightmare while hitting creatures in the dark during each phase of the encounter. Ensure your raid is prepared to handle these additional mechanics without losing progress.", x = 6 },
        [10756] = { e = 3, s = "c", h = { 51599 }, r = "Mostly travel; one zone requires heavy RNG drops.", d = "Activate all leyline feeds in Suramar by completing the associated quests listed in the info field. This is an account-wide achievement, so any character can contribute to unlocking it.", x = 6 },
        [10761] = { e = 4, s = "g", r = "Grinding multiple professions to high star levels.", d = "Upgrade all star recipes in one primary Legion profession to two stars or higher. Choose a single profession and focus on upgrading its recipes to meet the requirement efficiently.", x = 6 },
        [10762] = { e = 3, s = "g", r = "Cooking many recipes, some requiring rare ingredients.", d = "Cook 15 of the listed Legion recipes, which includes various dishes like Salt and Pepper Shank and Deep-Fried Mossgill. This is an account-wide achievement, so any character can help complete it.", x = 6 },
        [10763] = { e = 3, s = "c", h = { 50080 }, r = "Mostly quests; one requires defeating a rare giant.", d = "Complete the Azsuna storylines by finishing the quests listed in the info field. These are account-wide achievements, so you can progress them with any character in your group.", x = 6 },
        [10764] = { e = 2, s = "s", r = "Equip check only; gear acquisition ignored.", d = "Equip a superior item in every slot with at least item level 790 before Battle for Azeroth launches. This is time-gated and requires you to farm gear from Legion raids or dungeons early on, as higher item levels will invalidate the achievement later.", x = 6 },
        [10765] = { e = 3, s = "s", r = "Equip check only; requires high-level gear.", d = "Gear up with epic items of minimum item level 840 prior to Battle for Azeroth. You must complete this before the expansion release, so plan your raid runs carefully to reach this threshold without upgrading further.", x = 6 },
        [10766] = { e = 4, s = "s", r = "Requires specific dungeon completion on Mythic.", d = "Defeat Dresaron in Darkheart Thicket on Mythic difficulty only after slaying Hatespawn Abomination. This is a sequential requirement, so ensure you kill the abomination first before attempting the final boss.", x = 6 },
        [10769] = { e = 4, s = "s", r = "Requires specific raid mechanic execution on Mythic.", d = "Kill Shade of Xavius in Darkheart Thicket on Mythic while he has 10 stacks of Apocalyptic Empowerment. Watch his mechanics closely to build the stacks without wiping, as this is a specific window during the fight.", x = 6 },
        [10770] = { e = 3, s = "s", r = "Finding a rare spawn in the world.", d = "Find Pepe wearing tiny goggles for The Tangerine Traveler achievement. This is account-wide and requires locating the specific NPC, so check all major Legion zones or use a guide if you cannot find him.", x = 6 },
        [10771] = { e = 4, s = "s", r = "Requires specific raid mechanic execution on Normal+.", d = "Defeat Elerethe Renferal in The Emerald Nightmare on Normal or higher after destroying all Pulsing Egg Sacs. You must clear every sac before killing her, making this a multi-stage encounter requiring coordination.", x = 6 },
        [10772] = { e = 4, s = "c", h = { 50217, 50218, 50219 }, r = "Requires specific mechanics on a raid boss without cleansing adds.", d = "Kill Cenarius in The Emerald Nightmare on Normal or higher without cleansing any Forces of Nightmare. Avoid using cleanse abilities on Dryads, Treants, Wisps, and Drakes to preserve the achievement progress.", x = 6 },
        [10773] = { e = 4, s = "s", r = "Mythic dungeon with strict zero-damage mechanic against specific ability.", d = "Defeat Ivanyr in The Arcway on Mythic difficulty without taking damage from Charged Bolt. Position yourself carefully to avoid the bolt mechanic, as any damage taken will reset your progress for this run.", x = 6 },
        [10774] = { e = 3, s = "g", r = "Requires collecting 10 orbs in one session of a timed challenge.", d = "Gather 10 Emerald Orbs during a single session of Aviana's Challenge in Sylvan Falls. Complete this quest chain quickly without logging out, as breaking the session will reset your orb count toward the goal.", x = 6 },
        [10775] = { e = 4, s = "s", r = "Mythic dungeon with strict zero-expiration mechanic on pools.", d = "Defeat Corstilax in The Arcway on Mythic without letting any Nightwell Energy pools expire. Monitor the timers on all pools closely and clear them before they vanish to maintain achievement eligibility.", x = 6 },
        [10776] = { e = 4, s = "s", r = "Mythic dungeon with strict zero-kill mechanic on specific adds.", d = "Kill Advisor Vandros in The Arcway on Mythic without killing any Timeless Wraiths. Use crowd control or kiting strategies to avoid pulling wraiths, as their deaths will permanently fail the achievement.", x = 6 },
        [10778] = { e = 3, s = "g", r = "Requires earning Exalted reputation, typically a multi-hour grind.", d = "Reach Exalted reputation with The Nightfallen faction for account-wide credit. Farm quests and turn-ins efficiently in Suramar, noting that this is time-gated by Legion's end and cannot be completed post-expansion.", x = 6 },
        [10780] = { e = 4, s = "s", r = "Mythic raid boss fight requires group coordination and gear.", d = "Start with Normal difficulty to unlock the boss kill credit. Progress through normal content before attempting Heroic or Mythic versions if you want higher rewards.", x = 6 },
        [10781] = { e = 4, s = "s", r = "Heroic raid boss fight requires group coordination and gear.", d = "Complete the Normal version first as a prerequisite. Ensure your group is well-geared for Heroic mechanics before queuing up to avoid wipes and frustration.", x = 6 },
        [10782] = { e = 5, s = "s", r = "Mythic raid boss fight requires high-end gear and group coordination.", d = "You must finish Heroic first; this tier requires significant gear upgrades. Coordinate with a dedicated Mythic+ group or find a guild willing to run it for you.", x = 6 },
        [10783] = { e = 4, s = "s", r = "Mythic dungeon boss fight requires group coordination and gear.", d = "Begin on Normal difficulty to secure the initial kill credit. This dungeon is time-gated in some cases, so plan your runs carefully to avoid missing content.", x = 6 },
        [10784] = { e = 4, s = "s", r = "Heroic dungeon boss fight requires group coordination and gear.", d = "Finish Normal before attempting Heroic or Mythic versions. The boss mechanics become more complex, so ensure your group understands the patterns before increasing difficulty.", x = 6 },
        [10785] = { e = 5, s = "s", r = "Mythic dungeon boss fight requires high-end gear and group coordination.", d = "Complete Heroic first as a strict requirement for Mythic. This tier demands high-level gear and coordination; consider joining an established Mythic+ team for success.", x = 6 },
        [10786] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Start with Normal difficulty to unlock the boss kill credit. Progress through normal content before attempting Heroic or Mythic versions if you want higher rewards.", x = 6 },
        [10788] = { e = 5, s = "s", r = "Requires Heroic+ raid clear; high RNG and skill floor.", d = "Complete the Normal version first as a prerequisite. Ensure your group is well-geared for Heroic mechanics before queuing up to avoid wipes and frustration.", x = 6 },
        [10789] = { e = 5, s = "s", r = "Requires Mythic raid clear; very high difficulty.", d = "You must finish Heroic first; this tier requires significant gear upgrades. Coordinate with a dedicated Mythic+ group or find a guild willing to run it for you.", x = 6 },
        [10790] = { e = 4, s = "c", h = { 50291, 50294, 50297 }, r = "Multiple long quests; some involve heavy combat or RNG.", d = "Complete all listed Stormheim questlines in any order since they are account-wide. Check your quest log regularly to ensure no storyline tasks are missed during the expansion.", x = 6 },
        [10793] = { e = 3, s = "c", r = "Several short quests in one zone; moderate total time.", d = "Track down and complete every quest given by the Sixtrigger brothers in Stormheim. These quests often appear randomly, so be vigilant while exploring the zone.", x = 6 },
        [10795] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Start with Normal difficulty to unlock the boss kill credit. Progress through normal content before attempting Heroic or Mythic versions if you want higher rewards.", x = 6 },
        [10796] = { e = 5, s = "s", r = "Requires Heroic+ raid clear; high RNG and skill floor.", d = "Start with the base dungeon to unlock Heroic. Defeat Dargrul on Heroic first before attempting Mythic. This is a time-gated achievement requiring Legion content.", x = 6 },
        [10797] = { e = 5, s = "s", r = "Requires Mythic raid clear; very high difficulty.", d = "Complete the base and Heroic versions of Neltharion's Lair first. Then queue for or group up to run the dungeon on Mythic difficulty to finish this step.", x = 6 },
        [10798] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Finish the base Assault on Violet Hold dungeon first. You must complete this before unlocking Heroic and Mythic versions of the same raid instance.", x = 6 },
        [10799] = { e = 5, s = "s", r = "Requires Heroic+ raid clear; high RNG and skill floor.", d = "Unlock Heroic by completing the base version of Assault on Violet Hold. Defeat the leader on Heroic difficulty to earn points before moving to Mythic.", x = 6 },
        [10800] = { e = 5, s = "s", r = "Requires Mythic raid clear; very high difficulty.", d = "Complete the base and Heroic Assault on Violet Hold runs first. Then run the dungeon on Mythic difficulty to defeat the leader and finish this achievement.", x = 6 },
        [10801] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Finish the base Vault of the Wardens dungeon to unlock higher difficulties. Defeat Cordana Felsong on normal mode before progressing to Heroic or Mythic.", x = 6 },
        [10802] = { e = 4, s = "c", r = "Requires Heroic dungeon completion and specific boss kill.", d = "Complete the base and Mythic versions of Vault of the Wardens first. Then run the dungeon on Heroic difficulty to defeat Cordana Felsong for this achievement.", x = 6 },
        [10803] = { e = 5, s = "c", r = "Mythic difficulty requires high gear and group coordination.", d = "Finish the base and Heroic Vault of the Wardens runs first. Queue for or group up to run the dungeon on Mythic difficulty to complete this step.", x = 6 },
        [10804] = { e = 4, s = "c", r = "Requires dungeon completion and specific boss kill.", d = "Complete the base Black Rook Hold dungeon to unlock higher difficulties. Defeat Lord Kur'talos Ravencrest on normal mode before attempting Heroic or Mythic versions.", x = 6 },
        [10805] = { e = 4, s = "c", r = "Heroic difficulty requires group coordination and gear.", d = "Finish the base and Mythic Black Rook Hold runs first. Then run the dungeon on Heroic difficulty to defeat Lord Kur'talos Ravencrest for this achievement.", x = 6 },
        [10806] = { e = 5, s = "c", r = "Mythic difficulty requires high gear and group coordination.", d = "Complete the base and Heroic Black Rook Hold versions first. Then run the dungeon on Mythic difficulty to defeat Lord Kur'talos Ravencrest and finish this step.", x = 6 },
        [10807] = { e = 4, s = "c", r = "Requires dungeon completion and specific boss kill.", d = "Finish the base Maw of Souls dungeon to unlock higher difficulties. Defeat Helya on normal mode before progressing to Heroic or Mythic versions of the raid.", x = 6 },
        [10808] = { e = 5, s = "c", r = "Mythic difficulty requires high gear and group coordination.", d = "First complete Normal Maw of Souls, then queue for Heroic to defeat Helya. This is a time-gated achievement; you cannot start it until the dungeon's normal version is finished.", x = 6 },
        [10809] = { e = 5, s = "c", r = "Mythic difficulty requires high gear and group coordination.", d = "You must finish the Heroic achievement first before attempting Mythic difficulty. Ensure your group can handle the higher mechanics and damage requirements for this final tier.", x = 6 },
        [10813] = { e = 5, s = "c", r = "Mythic dungeon requires high gear and group coordination.", d = "Complete The Arcway on Normal or Heroic first to unlock this. Then find a high-level Mythic+ group capable of defeating Advisor Vandros quickly.", x = 6 },
        [10816] = { e = 5, s = "c", r = "Mythic dungeon requires high gear and group coordination.", d = "Finish Court of Stars on Normal or Heroic before attempting the Mythic version. This requires a coordinated group to handle the complex mechanics of Advisor Melandrus.", x = 6 },
        [10817] = { e = 4, s = "s", r = "Single fight with strict mechanics and timing.", d = "This is a time-gated achievement where you must defeat Aluriel within specific zones quickly. Coordinate with your raid group to minimize downtime between phases and avoid unnecessary deaths.", x = 6 },
        [10818] = { e = 5, s = "c", h = { 50362, 50363, 50364 }, r = "Requires defeating multiple high-difficulty raid bosses.", d = "Complete all three Normal/Emerald Nightmare wings first to unlock this account-wide achievement. You must defeat Nythendra, Elerethe Renferal, and Il'gynoth in any order once unlocked.", x = 6 },
        [10819] = { e = 4, s = "c", h = { 50367, 50368, 50366 }, r = "Requires defeating multiple raid bosses on Normal or higher.", d = "Finish the third wing of The Emerald Nightmare on Normal or Heroic to unlock this. Then defeat Xavius, ensuring your group can handle his mechanics efficiently.", x = 6 },
        [10820] = { e = 4, s = "s", r = "Defeating a specific raid boss requires significant time and gear.", d = "This is a time-gated achievement requiring you to defeat Aluriel within specific zones quickly. Coordinate with your raid group to minimize downtime between phases and avoid unnecessary deaths.", x = 6 },
        [10821] = { e = 5, s = "s", r = "Mythic Nythendra is a high-difficulty single encounter requiring coordination.", d = "Complete the Normal Nythendra achievement first before attempting Mythic difficulty. Ensure your group can handle the higher mechanics and damage requirements for this final tier.", x = 6 },
        [10822] = { e = 5, s = "s", r = "Mythic Elerethe Renferal is a high-difficulty single encounter.", d = "Finish the Normal Elerethe Renferal achievement before attempting Mythic difficulty. This requires a coordinated group to handle the complex mechanics of Advisor Melandrus.", x = 6 },
        [10823] = { e = 5, s = "s", r = "Mythic Il'gynoth is a high-difficulty single encounter requiring coordination.", d = "Complete the Normal Il'gynoth achievement first before attempting Mythic difficulty. Ensure your group can handle the higher mechanics and damage requirements for this final tier.", x = 6 },
        [10824] = { e = 5, s = "s", r = "Mythic Ursoc is a high-difficulty single encounter requiring coordination.", d = "Finish the Normal Ursoc achievement before attempting Mythic difficulty. This requires a coordinated group to handle the complex mechanics of Advisor Melandrus.", x = 6 },
        [10825] = { e = 5, s = "s", r = "Mythic Dragons of Nightmare is a high-difficulty single encounter.", d = "Queue for the Emerald Nightmare raid and defeat all three bosses on Mythic difficulty. This is a group requirement that cannot be soloed, so coordinate with friends or find a guild group.", x = 6 },
        [10826] = { e = 5, s = "s", r = "Mythic Cenarius is a high-difficulty single encounter requiring coordination.", d = "Complete the Emerald Nightmare raid on Mythic difficulty to defeat Cenarius. Ensure you have enough healers and damage dealers since this is a high-difficulty group encounter.", x = 6 },
        [10827] = { e = 5, s = "s", r = "Mythic Xavius is a high-difficulty single encounter with title reward.", d = "Defeat Xavius in the Emerald Nightmare on Mythic difficulty to earn the title The Dreamer. This requires a full raid group and is time-gated by Legion expansion availability.", x = 6 },
        [10829] = { e = 4, s = "c", h = { 50390, 50388, 50389 }, r = "Requires defeating multiple raid bosses within the Nighthold.", d = "Clear all bosses in Nighthold Wing 1 including Skorpyron, Trilliax, and Chronomatic Anomaly. This achievement is account-wide, so any character on your account can contribute to the progress.", x = 6 },
        [10830] = { e = 4, s = "g", r = "Requires specific mechanic execution and multiple attempts on Il'gynoth.", d = "Defeat Il'gynoth in The Emerald Nightmare after inflicting 20 Nightmare Explosions within 10 seconds. Coordinate with your raid group to focus damage on the Eye during the encounter.", x = 6 },
        [10837] = { e = 4, s = "c", h = { 50394, 50395, 50396 }, r = "Requires defeating multiple raid bosses within The Nighthold.", d = "Clear all bosses in Nighthold Wing 2 including Spellblade Aluriel, Star Augur Etraeus, and High Botanist Tel'arn. This is account-wide, so progress carries over between characters.", x = 6 },
        [10838] = { e = 4, s = "c", r = "Requires completing all Nighthold wings.", d = "Defeat all bosses in Nighthold Wing 3 including Krosus, Tichondrius, and Grand Magistrix Elisande. Ensure you have a full raid group ready for these challenging encounters.", x = 6 },
        [10839] = { e = 4, s = "s", r = "Defeating Gul'dan requires raiding.", d = "Defeat Gul'dan atop The Nighthold to complete this achievement. This is the final boss of the raid and requires a Mythic+ or higher difficulty run.", x = 6 },
        [10840] = { e = 5, s = "c", r = "Mythic Skorpyron is a heavy RNG boss.", d = "Queue for The Nighthold raid and defeat Skorpyron on Mythic difficulty. This requires a full group and is part of the larger Mythic Nighthold achievement set.", x = 6 },
        [10842] = { e = 5, s = "c", r = "Mythic Chronomatic Anomaly is a heavy RNG boss.", d = "Defeat Chronomatic Anomaly in The Nighthold on Mythic difficulty. Coordinate with your raid to handle the mechanics of this specific boss encounter.", x = 6 },
        [10843] = { e = 5, s = "c", r = "Mythic Trilliax is a heavy RNG boss.", d = "Defeat Trilliax in The Nighthold on Mythic difficulty. This is a group requirement and part of the Mythic Nighthold achievement chain.", x = 6 },
        [10844] = { e = 5, s = "c", r = "Mythic Spellblade Aluriel is a heavy RNG boss.", d = "Defeat Spellblade Aluriel in The Nighthold on Mythic difficulty. Ensure your raid group is prepared for the mechanics of this specific boss encounter.", x = 6 },
        [10845] = { e = 5, s = "c", r = "Mythic Star Augur Etraeus is a heavy RNG boss.", d = "Queue for Mythic The Nighthold and defeat Star Augur Etraeus. This is a standard raid boss kill with no special gating.", x = 6 },
        [10846] = { e = 5, s = "c", r = "Mythic High Botanist Tel'arn is a heavy RNG boss.", d = "Run Mythic The Nighthold to defeat High Botanist Tel'arn. Ensure you are on Mythic difficulty as specified.", x = 6 },
        [10847] = { e = 5, s = "c", r = "Mythic Tichondrius is a heavy RNG boss.", d = "Defeat Tichondrius in Mythic The Nighthold. This requires a full raid group and the specific Mythic difficulty setting.", x = 6 },
        [10848] = { e = 5, s = "c", r = "Mythic Krosus is a heavy RNG boss.", d = "Queue for Mythic The Nighthold to defeat Krosus. He is an early boss in the raid instance.", x = 6 },
        [10849] = { e = 5, s = "c", r = "Mythic Grand Magistrix Elisande is a heavy RNG boss.", d = "Defeat Grand Magistrix Elisande on Mythic difficulty in The Nighthold. She is a later boss requiring high gear.", x = 6 },
        [10850] = { e = 5, s = "c", r = "Mythic Gul'dan requires raiding and RNG.", d = "Complete the entire Mythic The Nighthold raid to defeat Gul'dan. This final boss drop grants you the Vengeance Incarnate title.", x = 6 },
        [10851] = { e = 4, s = "c", r = "Requires defeating a specific rare spawn in a raid.", d = "First defeat a Well-Traveled Nether Elemental on Normal or higher in Suramar, then kill Star Augur Etraeus in Mythic The Nighthold.", x = 6 },
        [10852] = { e = 3, s = "g", r = "Grinding artifact knowledge levels takes time but is straightforward.", d = "Visit your Class Hall researchers and complete quests until you reach Artifact Knowledge level 10. This is account-wide progress.", x = 6 },
        [10853] = { e = 4, s = "c", r = "Requires learning all artifact traits, a lengthy research process.", d = "Finish the previous artifact knowledge achievement to learn everything about your weapon. Speak with all researchers in your Class Hall.", x = 6 },
        [10875] = { e = 3, s = "s", r = "One specific fight condition in a dungeon on Mythic.", d = "Run Mythic Neltharion's Lair and wait for Naraxas to gain 6 Ravenous stacks before defeating her. Do not kill her too early.", x = 6 },
        [10876] = { e = 4, s = "c", h = { 50545 }, r = "Requires completing many pet battles; 'Size Doesn't Matter' is the hardest.", d = "Complete 30 Pet Battle World Quests across the Broken Isles zones. This is account-wide and requires finding specific world quest markers.", x = 6 },
        [10877] = { e = 3, s = "c", r = "Collecting five rare items across the Broken Isles takes time.", d = "Locate and recover all five Pillars of Creation scattered across the Broken Isles. This is an account-wide collection achievement.", x = 6 },
        [10991] = { e = 2, s = "s", r = "Reaching Prestige Level 1 is quick after gaining enough reputation.", d = "Start PvP immediately to begin gaining Prestige levels. This is a linear progression with no time gates, so just play battlegrounds or arenas consistently until you hit level 1.", x = 6 },
        [10992] = { e = 2, s = "s", r = "Reaching Prestige Level 2 follows quickly after level 1.", d = "Continue playing PvP content after completing the previous step. You must reach Prestige Level 2, which requires finishing the prior achievement first.", x = 6 },
        [10993] = { e = 2, s = "s", r = "Reaching Prestige Level 3 is a short step from level 2.", d = "Keep up your PvP activity to unlock Prestige Level 3. No special mechanics exist here; simply maintain your progress from the earlier steps.", x = 6 },
        [10994] = { e = 3, s = "c", r = "Completing the class order campaign involves multiple steps.", d = "Complete your specific class Order Hall campaign quests in any order. This is a solo task with no time limit, so finish all available chapters for your class.", x = 6 },
        [10995] = { e = 2, s = "s", r = "Reaching Prestige Level 4 is a short step from level 3.", d = "Reach Prestige Level 4 by continuing PvP play. Ensure you have finished the previous prestige steps first, as this unlocks automatically upon hitting the level.", x = 6 },
        [10996] = { e = 3, s = "c", r = "Collecting all snail imprints in Neltharion's Lair takes time.", d = "Enter Neltharion's Lair and use the Ketchum Tablet to collect snail imprints. This is a solo dungeon run with no time gate, but you must find every named snail drop.", x = 6 },
        [11066] = { e = 2, s = "g", r = "Farm a mob for a specific item count.", d = "Farm Dalaran's Underbelly zone to gather 20,000 Sightless Eyes. This is a grind that can be done solo or in groups, and the mount reward is account-wide.", x = 6 },
        [11124] = { e = 3, s = "c", h = { 51583, 51590, 51592 }, r = "Multiple storylines; some involve heavy RNG or difficult fights.", d = "Complete all Suramar story quests listed in your quest log. These are main storyline tasks with no time gate, so just follow the narrative flow for your faction.", x = 6 },
        [11125] = { e = 2, s = "c", r = "Activate scattered objects in one zone.", d = "Travel across Suramar to activate every teleporter zone. This is a solo exploration task with no time limit, but ensure you visit all districts to trigger them.", x = 6 },
        [11126] = { e = 3, s = "g", r = "Grind world quests until count reaches 50.", d = "Complete any available World Quests in your current zone until you hit 50. These are account-wide and have no time gate, so just do whatever quests appear on your map.", x = 6 },
        [11127] = { e = 3, s = "g", r = "Grind world quests until count reaches 200.", d = "Continue doing World Quests after the previous milestone to reach 200 total. This is a cumulative grind with no expiration, so keep playing daily content.", x = 6 },
        [11128] = { e = 4, s = "g", r = "Significant grind to reach 500 world quests.", d = "Keep completing World Quests until you hit 500 total. Since these are account-wide and have no time gate, simply continue doing daily quests over time.", x = 6 },
        [11129] = { e = 4, s = "g", r = "Long grind to reach 1000 world quests.", d = "Grind world quests in any zone until you hit 1,000 completions, as this is account-wide and requires no specific group. Focus on high-yield zones like Azsuna or Suramar to speed up progress significantly. Do not worry about missing content since there are no time gates for these cumulative counters.", x = 6 },
        [11130] = { e = 5, s = "g", r = "Very long grind; requires hundreds of hours.", d = "Continue farming world quests after reaching 1,000 to unlock the next tier at 2,500 completions. This is purely a volume achievement so playing multiple characters or using group finder helps accelerate your total count. No special mechanics or rare drops are needed beyond standard quest completion.", x = 6 },
        [11131] = { e = 5, s = "g", r = "Extreme grind; likely impossible without daily resets.", d = "Push forward with world quests until you reach the 5,000 milestone, keeping an eye on your total account-wide count. You can mix solo and group content freely as long as you maintain a steady flow of completions. There are no hidden requirements or missable elements for this specific threshold.", x = 6 },
        [11132] = { e = 5, s = "g", r = "Massive grind; effectively unobtainable for most.", d = "Aim for 10,000 world quest completions by consistently playing through available zones over an extended period. This is entirely account-wide so leveling multiple characters simultaneously will drastically reduce the time needed. Simply avoid downtime and keep accepting quests whenever possible to reach this final tier.", x = 6 },
        [11133] = { e = 3, s = "c", r = "Collect mana items; some classes have rare drops.", d = "Equip every Ancient Mana Increaser item you find in Suramar to max out your mana capacity for this achievement. Check your inventory regularly as these items drop from specific mobs or world events in the zone. Once equipped, verify your total capacity matches the requirement before claiming the points.", x = 6 },
        [11135] = { e = 4, s = "c", h = { 51638, 51642, 51649 }, r = "Complete three campaigns; some require high-level gear.", d = "Complete three different class Order Campaigns in your Legion Class Hall to earn this achievement. You can choose any three classes and finish their respective heroic campaigns without needing specific order hall upgrades first. Just ensure you select distinct classes rather than repeating the same one multiple times.", x = 6 },
        [11136] = { e = 4, s = "c", h = { 52377, 52380, 52385 }, r = "Requires completing five separate class campaigns.", d = "Finish five unique class Order Campaigns after completing the previous tier, expanding your roster of completed heroes. This requires selecting five different classes and finishing their epic-level campaigns within the Legion expansion content. No time gates exist, but you must have access to all relevant class halls in Suramar.", x = 6 },
        [11138] = { e = 4, s = "g", r = "Grinding first aid quests across the Broken Isles.", d = "Accept and complete ten first aid quests from wounded travelers scattered across the Broken Isles zones. These quests appear as floating text prompts when near injured NPCs, so keep your healing kit ready at all times. The achievement is account-wide, meaning any character can contribute to the total count.", x = 6 },
        [11139] = { e = 5, s = "c", h = { 55982, 55983, 55984 }, r = "Requires completing all first aid quests including rare ones.", d = "Help every single wounded traveler in the Broken Isles by completing all available first aid quest variants. This includes both initial and follow-up quests that may appear after the first tier is finished. Since it covers all factions and zones, prioritize high-density areas like Stormheim or Highmountain for efficiency.", x = 6 },
        [11144] = { e = 4, s = "c", r = "Unlocking every artifact trait is a long grind.", d = "Unlock every single artifact trait for one specific weapon by earning them through world quests and dungeons. Choose a weapon you enjoy using to make the grind more enjoyable while tracking progress on each trait individually. There are no time limits, but ensure you do not delete your character before unlocking all traits.", x = 6 },
        [11157] = { e = 3, s = "c", r = "Completing several specific Legion quest lines.", d = "Complete four specific Legion lore achievements listed in the description by finishing their associated quest chains. These include locations like Azsuna and Val'sharah, so explore those zones thoroughly to find the required storylines. The achievement is account-wide, so any character can contribute to unlocking these lore milestones.", x = 6 },
        [11159] = { e = 4, s = "g", r = "Grinding to Exalted with multiple factions.", d = "Reach Exalted reputation with one faction from the Broken Isles list such as the Valarjar or Highmountain Tribe. Focus on daily quests and world events in their respective zones to gain reputation efficiently without wasting time. Once you hit Exalted, claim your points immediately as this status does not carry over if you leave the expansion.", x = 6 },
        [11160] = { e = 4, s = "g", r = "Defeating eight specific world bosses on the Broken Isles.", d = "Defeat eight of the listed Legion world bosses like Na'zak or Nithogg. This is account-wide and requires no group, but be patient as these spawn on a timer.", x = 6 },
        [11162] = { e = 5, s = "s", r = "Requires a high-level Mythic dungeon run with strict timing.", d = "First unlock Challenge Mode for your dungeon, then run it with a level 10+ keystone to finish under the time limit. You must already have the Keystone Conqueror achievement.", x = 6 },
        [11163] = { e = 4, s = "c", r = "Completing multiple specific Mythic dungeon achievements.", d = "Complete all Legion Mythic dungeons listed in the info field to earn this title and its mount reward. Ensure you are on Mythic difficulty for every single dungeon.", x = 6 },
        [11164] = { e = 3, s = "c", r = "Completing several Heroic dungeon runs.", d = "Finish all Legion Heroic dungeons listed in the requirements. This is account-wide, so coordinate with friends or use a dungeon finder group.", x = 6 },
        [11165] = { e = 4, s = "s", r = "Requires reaching Prestige level 6 in PvP.", d = "Reach Prestige level 6 in PvP to earn this crest. Grind arenas or battlegrounds until you hit the required prestige tier.", x = 6 },
        [11166] = { e = 4, s = "s", r = "Duplicate of 11165; requires reaching Prestige level 6 in PvP.", d = "This is a duplicate entry for reaching Prestige level 6; simply focus on gaining Arena Points and Battleground wins to advance your Prestige rank.", x = 6 },
        [11167] = { e = 4, s = "c", r = "Requires reaching Prestige level 10 via PvP grind.", d = "Reach Prestige level 10 in PvP to earn this crest. Continue grinding arena matches after completing the previous prestige milestones.", x = 6 },
        [11168] = { e = 4, s = "c", r = "Duplicate entry; requires reaching Prestige level 10 via PvP grind.", d = "This is a duplicate entry for reaching Prestige level 10; keep playing PvP content until your Prestige counter hits ten.", x = 6 },
        [11169] = { e = 5, s = "c", r = "Requires reaching Prestige level 14, a very high PvP threshold.", d = "Reach Prestige level 14 in PvP to earn this crest. Maintain consistent arena participation to climb through the higher prestige tiers efficiently.", x = 6 },
        [11170] = { e = 5, s = "c", r = "Duplicate entry; requires reaching Prestige level 14 via PvP grind.", d = "This is a duplicate entry for reaching Prestige level 14; focus on high-level arena brackets to maximize your Prestige gain speed.", x = 6 },
        [11171] = { e = 3, s = "g", r = "Grinding all class artifacts takes several hours but is doable solo.", d = "Obtain every artifact available to your specific class by completing the relevant Legion Class Hall quests. Check your class hall NPC for the current quest line.", x = 6 },
        [11173] = { e = 2, s = "c", r = "Unlocking colors requires honor grinding, achievable in under an hour.", d = "Unlock all four color variations for your war-torn artifact appearance by earning Honor at levels 10, 30, 50, and 80. Grind PvP to accumulate enough Honor points.", x = 6 },
        [11175] = { e = 2, s = "g", r = "Reading scattered chapters is a short exploration task.", d = "Read all seven chapters of The Beginner's Guide to Dimensional Rifting scattered across Azsuna in any order. These quests are time-gated by the Legion expansion release, so you cannot complete them before entering that content.", x = 6 },
        [11176] = { e = 4, s = "g", r = "Collecting 300 toys requires significant time farming or purchasing.", d = "Collect 300 toys from vendors or world drops while playing Crashin' Thrashin' Commander to unlock this account-wide achievement. Note that some toys may be rare drops or require specific events, so patience is key.", x = 6 },
        [11177] = { e = 5, s = "g", r = "Raising 70 reputations to Exalted is a massive long-term grind.", d = "Raise exactly 70 faction reputations to Exalted; do not over-level any single faction beyond what is needed. This is account-wide and often requires grinding multiple zones simultaneously to save time.", x = 6 },
        [11178] = { e = 2, s = "s", r = "Mounting Stormtalon is a single event after obtaining the mount.", d = "Mount Stormtalon in Storm's Reach, which is located in the Broken Isles zone of Suramar. Ensure you have the mount learned before attempting this specific location requirement.", x = 6 },
        [11180] = { e = 3, s = "c", r = "Completing Legion raid achievements involves multiple raids but is standard content.", d = "Complete all listed Legion raid achievements by finishing raids like Buggy Fight and Webbing Crashers. Some are rare drops or require specific boss kills, so check your progress after each raid clear.", x = 6 },
        [11181] = { e = 4, s = "g", r = "Clearing all Legion dungeons with Mythic keystones requires repeated runs.", d = "Run every Legion dungeon with a Mythic Keystone to earn the Legacy achievement. This includes both normal and heroic versions of dungeons like Eye of Azshara and Darkheart Thicket.", x = 6 },
        [11183] = { e = 4, s = "g", r = "Requires timed Mythic+ dungeon runs; difficulty scales with key level.", d = "Complete any Level 2 or higher Mythic dungeon within the time limit to start the Keystone chain. You must finish this before moving on to higher-level challenges.", x = 6 },
        [11184] = { e = 5, s = "g", r = "High-level timed dungeons require significant gear and skill.", d = "Progress to Level 5+ Mythic dungeons after unlocking Level 2+, ensuring you meet the time limit each run. This is a sequential requirement, so do not skip levels.", x = 6 },
        [11185] = { e = 5, s = "g", r = "Very high-level timed dungeons are extremely difficult solo.", d = "Reach Level 7+ Mythic dungeon completion for the next tier in the Keystone chain. Be aware that higher-level keys require stronger gear and group coordination.", x = 6 },
        [11186] = { e = 3, s = "c", h = { 52347, 52353, 52354 }, r = "Requires finding specific rare spawns in four different zones.", d = "Find Tehd and Marius in Azsuna, Highmountain, Val'sharah, and Stormheim to aid them in demon encounters. Each zone has a unique encounter, so travel between zones as needed.", x = 6 },
        [11188] = { e = 3, s = "g", r = "Exploring all regions takes time but is straightforward.", d = "Explore all regions of the Broken Isles including Azsuna, Val'sharah, Highmountain, Stormheim, and Suramar. Use the map or exploration tools to ensure every region is fully discovered.", x = 6 },
        [11189] = { e = 4, s = "g", r = "Collecting 100 unique world quests requires extensive travel and RNG.", d = "Complete 100 different Legion World Quests by accepting and finishing unique quests across the Broken Isles. Avoid repeating quest lines to maximize variety and track your count carefully.", x = 6 },
        [11190] = { e = 5, s = "c", h = { 52371, 52372, 52373 }, r = "Depends on completing other major Legion achievements first.", d = "Finish Broken Isles Explorer and Loremaster of Legion first, as they unlock the rest. Complete all listed sub-achievements to earn increased mount speed in the zone.", x = 6 },
        [11212] = { e = 2, s = "g", r = "Recruiting troops is quick and easy at the class hall.", d = "Recruit your class hall troops immediately upon unlocking the feature to start the chain. You must gather exactly twenty units before moving to the next tier.", x = 6 },
        [11213] = { e = 2, s = "g", r = "Continuing troop recruitment is simple after the first batch.", d = "Continue recruiting until you have one hundred total troops. This is a cumulative goal that builds directly on raising your initial army.", x = 6 },
        [11214] = { e = 3, s = "g", r = "Completing 10 missions involves some travel and questing.", d = "Accept and complete ten class hall missions from the available quests. Track your progress carefully as this unlocks the next milestone in the chain.", x = 6 },
        [11215] = { e = 4, s = "g", r = "Reaching 50 missions requires substantial time investment.", d = "Keep completing missions until you reach fifty total completions. This step bridges the gap between early exploration and the massive final goal.", x = 6 },
        [11216] = { e = 4, s = "g", r = "Completing 100 missions is a long-term commitment.", d = "Finish one hundred mission completions to unlock the next tier. Be patient as this requires significant time spent on daily or weekly objectives.", x = 6 },
        [11217] = { e = 3, s = "g", r = "Grinding 500 missions takes several hours of solo play.", d = "Complete five hundred missions total for this final tier. Plan your schedule around high-yield missions to reach this large number efficiently.", x = 6 },
        [11218] = { e = 1, s = "s", r = "Completing one specific mission is trivial and quick.", d = "Look for specific class hall missions that reward dungeon quests and complete them once. This is a one-time check rather than a cumulative count.", x = 6 },
        [11219] = { e = 1, s = "s", r = "Completing one specific mission is trivial and quick.", d = "Find and finish a class hall mission that specifically rewards a raid quest. Ensure you accept the correct quest before turning it in to claim credit.", x = 6 },
        [11220] = { e = 3, s = "g", r = "Collecting 8 champions requires finding them across zones.", d = "Collect eight unique champions by completing their specific recruitment quests. Do not miss any as this requirement is fixed at exactly eight.", x = 6 },
        [11221] = { e = 4, s = "g", r = "Leveling 8 champions to max takes significant time grinding.", d = "Level all eight collected champions to level one hundred and ten. Use appropriate training methods to speed up the leveling process for each unit.", x = 6 },
        [11222] = { e = 4, s = "g", r = "Power leveling 8 champions requires extensive content completion.", d = "Raise your champions to item level eight hundred and fifty using gear from raids or dungeons. This final step requires equipping them with high-level items before submission.", x = 6 },
        [11223] = { e = 3, s = "c", r = "Researching upgrades involves multiple distinct steps.", d = "Research your Class Hall upgrades in any order; this is purely account-wide and requires no specific group. Simply ensure you have completed the sixth tier of research for your chosen class hall to finish.", x = 6 },
        [11232] = { e = 2, s = "s", r = "Completing a specific quest chain is under an hour.", d = "Complete the quest Time to Collect after killing the Sixtrigger Brothers in Stormheim. This is a solo-friendly quest that grants you the title The Gullible upon completion.", x = 6 },
        [11233] = { e = 4, s = "g", r = "Catching all pets involves rare RNG and long hunting.", d = "Catch every pet listed in the Broken Isles Safari by exploring all zones and dungeons. Many pets are rare drops or require specific encounters, so be patient and thorough across all Broken Isles content.", x = 6 },
        [11240] = { e = 3, s = "c", r = "Finding three specific tomes requires searching multiple zones.", d = "Unearth Harbinger stories by collecting Waterlogged, Fel-Ravaged, and Cursed Tomes found in Legion zones. This is account-wide, so any character can contribute to the progress of this achievement.", x = 6 },
        [11256] = { e = 4, s = "g", r = "Discovering 35 treasures in a zone is a long grind.", d = "Discover all 35 treasures in Azsuna by thoroughly exploring the zone and checking hidden locations. Use a flying mount or ground travel to ensure you do not miss any secret spots while completing this account-wide goal.", x = 6 },
        [11257] = { e = 4, s = "g", r = "Discovering 40 treasures in a zone is a long grind.", d = "Find all 40 treasures in Highmountain to earn the Skyhorn Storage Chest reward. Explore every corner of the zone carefully, as some treasures are hidden behind rocks or require specific interactions.", x = 6 },
        [11258] = { e = 3, s = "g", r = "Collecting 40 items requires time and travel.", d = "Locate 40 treasures in Val'sharah to receive the Kaldorei Treasure Trove. This account-wide achievement requires careful exploration of the forest zone, often needing a flying mount to access high perches.", x = 6 },
        [11259] = { e = 3, s = "g", r = "Collecting 60 items requires time and travel.", d = "Discover 60 treasures in Stormheim by thoroughly searching the snowy landscapes. Some treasures may be behind rocks or require specific actions, so take your time to ensure you find all of them.", x = 6 },
        [11260] = { e = 3, s = "g", r = "Collecting 45 items requires time and travel.", d = "Find 45 treasures in Suramar by exploring the city and surrounding areas. This account-wide achievement requires checking hidden spots and interacting with objects throughout the zone to complete.", x = 6 },
        [11261] = { e = 4, s = "c", h = { 53810 }, r = "Many vignettes; one is a rare spawn event.", d = "Complete all special encounters listed for Azsuna, including vignettes like Valiyaka the Stormbringer. These are often solo-friendly but require specific triggers or boss kills, so review each encounter's requirements carefully.", x = 6 },
        [11262] = { e = 4, s = "c", h = { 53837 }, r = "Many vignettes; one involves a haunted house.", d = "Finish all special encounters in Val'sharah, such as Gorebeak and Seersei. These vignettes are account-wide and may require specific boss kills or interactions found during normal zone exploration.", x = 6 },
        [11263] = { e = 4, s = "c", h = { 53864 }, r = "Many vignettes; one is a rare spawn event.", d = "Complete all special encounters in Stormheim, including Glimar Ironfist and The Nameless King. These vignettes are account-wide and often involve defeating specific bosses or completing unique events within the zone.", x = 6 },
        [11264] = { e = 4, s = "c", h = { 53879 }, r = "Many vignettes; one requires defeating a boss.", d = "Start by completing the Vignettes for Highmountain to unlock all special encounters listed in the info field. Visit each location sequentially to defeat bosses like Sekhan and The Beastly Boxer, ensuring you do not miss any rare drops or timed events. This achievement is account-wide, so coordinate with friends if specific encounters require group play.", x = 6 },
        [11265] = { e = 4, s = "c", h = { 53906 }, r = "Many vignettes; one is a rare spawn event.", d = "Begin by finishing the Suramar Vignettes to access all required special encounters such as Garvrulg and Elfbane. Travel through each zone in Suramar to complete the listed objectives, watching for rare drops that may not respawn frequently. Since this is account-wide, you can share progress with friends if certain fights need a group.", x = 6 },
        [11276] = { e = 2, s = "s", r = "Simple interaction with an existing bonfire.", d = "Locate the Horde bonfire in Frostfire Ridge during the Midsummer event and desecrate it immediately upon arrival. This task is time-gated to the specific event window, so do not delay once the event starts. Ensure you are in Draenor when the event begins to avoid missing this opportunity.", x = 6 },
        [11277] = { e = 2, s = "s", r = "Simple interaction with an existing bonfire.", d = "Find the Alliance bonfire in Shadowmoon Valley and desecrate it while the Midsummer event is active. This achievement is time-sensitive, so prioritize it as soon as the event launches to prevent missing out. No group is needed, but be ready to move quickly between zones if multiple bonfires exist.", x = 6 },
        [11278] = { e = 2, s = "s", r = "Simple interaction with an existing bonfire.", d = "Head to Suramar during the Midsummer event and desecrate the Horde bonfire located there. This task is time-gated, so complete it within the event duration or you will miss it permanently. Check the map for the exact location of the bonfire before engaging any enemies.", x = 6 },
        [11279] = { e = 2, s = "s", r = "Simple interaction with an existing bonfire.", d = "Locate the Alliance bonfire in Suramar and desecrate it during the Midsummer event window. This achievement is time-sensitive, so act quickly once the event begins to avoid missing out. No group is required, but ensure you are in the correct zone when the event starts.", x = 6 },
        [11280] = { e = 3, s = "c", r = "Grind across multiple zones for honor points.", d = "Honor the flames in Azsuna, Val'Sharah, Highmountain, Stormheim, and Suramar to complete this account-wide achievement. Visit each zone during the Midsummer event and interact with the flame markers listed in the info field. This task is time-gated, so prioritize it while the event is active.", x = 6 },
        [11282] = { e = 3, s = "c", r = "Grind across multiple zones for honor points.", d = "Honor the flames in Azsuna, Val'Sharah, Highmountain, Stormheim, and Suramar for the Keeper version of this achievement. Follow the same steps as the Warden title but ensure you complete all zones listed in the info field. This is account-wide and time-gated to the Midsummer event.", x = 6 },
        [11283] = { e = 3, s = "c", r = "Grind across multiple zones for honor points.", d = "Honor the flames in Spires of Arak, Talador, Nagrand, Gorgrond, and Shadowmoon Valley for the Draenor Warden title. Visit each zone during the Midsummer event and interact with the flame markers provided in the info field. This task is time-gated, so complete it while the event is active.", x = 6 },
        [11284] = { e = 3, s = "c", r = "Grind across multiple zones for honor points.", d = "Honor the flames in Spires of Arak, Talador, Nagrand, Gorgrond, and Frostfire Ridge for the Draenor Keeper title. Follow the same process as the Warden but ensure you cover all zones listed in the info field. This is account-wide and time-gated to the Midsummer event.", x = 6 },
        [11296] = { e = 5, s = "s", r = "Requires specific old content completion.", d = "Complete both vanilla Hunter Epic quests to obtain Rhok'delar, Longbow of the Ancient Keepers, and Lok'delar, Stave of the Ancient Keepers. These items are required for this Legacy achievement, so focus on finishing the epic quests first. This is account-wide, so you can share progress with friends if needed.", x = 6 },
        [11297] = { e = 4, s = "s", r = "Requires specific old content completion.", d = "Finish the Vanilla Priest Epic quest to acquire Benediction and Anathema for this Legacy achievement. Prioritize completing the epic quest line as it may be time-gated or require specific conditions. This is account-wide, so coordinate with friends if the quest involves group mechanics.", x = 6 },
        [11298] = { e = 3, s = "c", h = { 55194 }, r = "Gloves require massive RNG grind.", d = "Farm the Class Hall armor pieces from Legion class hall vendors or world drops, noting that some items like gloves and shoulders have high drop counts. Prioritize farming these early in Legion to avoid missing out on the set bonus while leveling your character.", x = 6 },
        [11320] = { e = 4, s = "g", r = "Grinding rare pets from old raids.", d = "Queue for Ulduar, Trial of the Crusader, and Icecrown Citadel raids repeatedly until you collect every listed pet from their respective encounter loot tables. Be patient as some pets are rare drops that may take many runs to obtain.", x = 6 },
        [11335] = { e = 4, s = "c", h = { 55380 }, r = "Mythic Karazhan Opera Hell is hard.", d = "Complete all three Opera Hall plays in Return to Karazhan on Mythic difficulty, ensuring you defeat the final boss of each play to unlock the achievement. This requires a dedicated group capable of handling high-level dungeon mechanics.", x = 6 },
        [11337] = { e = 4, s = "s", r = "Requires specific raid condition met.", d = "Run Trial of Valor on Normal or higher difficulty and focus on defeating Odyn after acquiring Runic Mastery from the previous bosses. Ensure your raid composition supports the specific mechanics required for this encounter.", x = 6 },
        [11338] = { e = 5, s = "s", r = "Highly difficult Mythic dungeon mechanic.", d = "Defeat Moroes in Return to Karazhan on Mythic difficulty by killing all four dinner guests within a ten-second window before proceeding to the boss fight. Coordinate with your group to minimize downtime between guest kills.", x = 6 },
        [11340] = { e = 2, s = "c", r = "Quests are mostly story-based steps.", d = "Follow the Suramar storyline quests starting from Lockdown through Breaking the Nighthold, ensuring you complete every step in the chain. This account-wide achievement requires finishing the entire narrative arc without skipping any major quest objectives.", x = 6 },
        [11377] = { e = 4, s = "c", r = "Requires specific raid mechanics and coordination on Normal or higher.", d = "Attempt to defeat Helya in Trial of Valor on Normal or higher difficulty while keeping all but one raid member afflicted with Fetid Rot. Coordinate your group's abilities and cooldowns to maintain the debuff throughout the encounter.", x = 6 },
        [11386] = { e = 4, s = "c", r = "Requires precise timing with Guarm's mechanics in a raid setting.", d = "Defeat Guarm in Trial of Valor on Normal or higher difficulty after successfully taking his Chew Toy through all three Guardian's Breaths phases. Timing is crucial as you must manage the toy's durability while progressing through the fight.", x = 6 },
        [11394] = { e = 4, s = "c", r = "Requires defeating three specific bosses within the Trial of Valor raid.", d = "Clear all three bosses in Trial of Valor by defeating Odyn, Guarm, and Helya on Normal or higher difficulty to unlock this account-wide achievement. Start with the earlier bosses if possible, as later encounters may require specific raid compositions.", x = 6 },
        [11396] = { e = 5, s = "c", r = "Mythic difficulty adds significant complexity and RNG to the fight.", d = "Queue for Trial of Valor on Mythic difficulty and focus solely on defeating Odyn, ensuring your group can handle the increased mechanics and damage output. This is a significant challenge requiring high-level coordination and gear.", x = 6 },
        [11397] = { e = 5, s = "c", r = "Mythic difficulty adds significant complexity and RNG to the fight.", d = "Defeat Guarm in Trial of Valor on Mythic difficulty, which demands precise execution of complex mechanics and strong raid performance. Prepare your group with appropriate consumables and strategies to handle the heightened threat levels.", x = 6 },
        [11398] = { e = 5, s = "c", r = "Mythic difficulty adds significant complexity and RNG to the fight.", d = "Tackle Helya in Trial of Valor on Mythic difficulty, requiring a well-coordinated team capable of managing her challenging mechanics. Ensure all raid members are prepared for the intense combat demands of this final boss encounter.", x = 6 },
        [11426] = { e = 5, s = "c", r = "Requires Heroic or higher difficulty for all three bosses in the raid.", d = "Complete the Heroic Trial of Valor raid with your group. Ensure you have access to all three bosses: Odyn, Guarm, and Helya.", x = 6 },
        [11427] = { e = 3, s = "c", r = "Requires completing multiple specific quests involving rare spawns or mechanics.", d = "Finish the Murky quest chain in Legion to earn the Mrgrglhjorn toy. This is account-wide and requires completing specific claw-themed quests.", x = 6 },
        [11429] = { e = 5, s = "c", r = "Mythic difficulty in Return to Karazhan requires high-level raid coordination.", d = "Defeat Viz'aduum the Watcher on Mythic difficulty in Return to Karazhan. You must first unlock the dungeon before attempting this boss.", x = 6 },
        [11430] = { e = 5, s = "c", r = "Requires specific interaction with an NPC on Mythic difficulty.", d = "Speak with the Image of Medivh while running Return to Karazhan on Mythic difficulty. This triggers a specific interaction within the raid instance.", x = 6 },
        [11431] = { e = 5, s = "c", r = "Requires defeating a boss while riding mounts, adding significant difficulty.", d = "Defeat a Mana Devourer while your entire party rides Rodents of Usual Size in Legion dungeons. Coordinate with your group to mount up before pulling.", x = 6 },
        [11432] = { e = 5, s = "c", r = "Requires defeating a boss while all party members have a specific debuff.", d = "Defeat the Shade of Medivh on Mythic Return to Karazhan while every player has the Paranoid buff active. Ensure all members maintain this status during the fight.", x = 6 },
        [11433] = { e = 4, s = "g", r = "Requires four Mythic dungeon clears; time-consuming but deterministic.", d = "Collect all four Sealed Tomes from Return to Karazhan on Mythic difficulty. This is account-wide and requires clearing specific areas in the dungeon.", x = 6 },
        [11446] = { e = 4, s = "c", h = { 56767 }, r = "Depends on Part One completion and other zone exploration tasks.", d = "Complete Broken Isles Pathfinder Part One first, then finish the required exploration achievements. You will receive increased mount speed in the Broken Isles as a reward.", x = 6 },
        [11468] = { e = 3, s = "g", r = "Requires significant PvP activity to reach Prestige Level 5.", d = "Reach Prestige Level 5 in PvP to unlock this legacy achievement. This is part of a chain leading toward higher prestige levels.", x = 6 },
        [11469] = { e = 3, s = "g", r = "Continues the grind for Prestige Level 6 after previous level.", d = "Advance your PvP rank to Prestige Level 6. You must already have Prestige Level 5 before attempting this next step in the legacy chain.", x = 6 },
        [11470] = { e = 3, s = "g", r = "Continues the grind for Prestige Level 7 after previous level.", d = "Reach Prestige Level 7 in PvP by continuing to earn honor and prestige points. This unlocks the path toward Prestige Level 8.", x = 6 },
        [11471] = { e = 3, s = "g", r = "Continues the grind for Prestige Level 8 after previous level.", d = "Achieve Prestige Level 8 in PvP to complete this segment of the legacy chain. Continue grinding PvP content to progress further.", x = 6 },
        [11472] = { e = 3, s = "g", r = "Continues the grind for Prestige Level 9 after previous level.", d = "Grind PvP matches until your character reaches Prestige Level 9, noting that this is a long-term progression goal often requiring significant time investment. Ensure you do not hate the grind by balancing it with other activities to avoid burnout before hitting the next milestone.", x = 6 },
        [11474] = { e = 5, s = "g", r = "Requires completing specific world quests 20 times each; very time-consuming.", d = "Complete each Free-For-All PvP World Quest exactly twenty times, as these are repeatable objectives that contribute toward a prestigious war mount reward. Since this is account-wide, coordinate with friends or play solo across different zones to maximize efficiency without missing any specific quest types.", x = 6 },
        [11475] = { e = 5, s = "g", r = "Requires completing Operation Murloc Freedom 20 times; very time-consuming.", d = "Finish Operation Murloc Freedom twenty times to earn points for this achievement, which is tracked on your entire account rather than just your character. Treat this as a repeatable daily-like task and prioritize it when you have spare time to avoid forgetting the count.", x = 6 },
        [11476] = { e = 5, s = "g", r = "Requires completing Bareback Brawl 20 times; very time-consuming.", d = "Participate in Bareback Brawl events twenty times, keeping track of your progress since missing these opportunities can delay completion indefinitely. These events are often found in specific zones, so check local event schedules or ask other players for locations to ensure you don't miss any runs.", x = 6 },
        [11477] = { e = 5, s = "g", r = "Requires completing Black Rook Rumble 20 times; very time-consuming.", d = "Complete Black Rook Rumble twenty times, focusing on finding the event quickly as it may not be available every day. Remember that this achievement is account-wide, so playing with a group can help you finish faster if you struggle to find the event alone.", x = 6 },
        [11478] = { e = 5, s = "g", r = "Requires completing Darkbrul Arena 20 times; very time-consuming.", d = "Finish Darkbrul Arena twenty times, being mindful that these arenas are rare and time-gated events that require patience to complete repeatedly. Plan your schedule around when these events appear in specific zones to ensure you reach the required count without wasting time.", x = 6 },
        [11543] = { e = 2, s = "c", r = "Walk around map to reveal zones.", d = "Explore every covered area on the Broken Shore map by visiting key locations like Deliverance Point and Deadwood Landing. This achievement is account-wide, so make sure to travel with a group if certain areas are difficult to access solo during your current level range.", x = 6 },
        [11544] = { e = 3, s = "c", r = "Complete four assault quests in zones.", d = "Repel all Legion assaults across Azsuna, Highmountain, Stormheim, and Val'sharah by completing the specific battle quests listed in the achievement info. These events are often time-limited, so check your calendar or group chat for upcoming assault dates to avoid missing out on progress.", x = 6 },
        [11545] = { e = 2, s = "s", r = "Grind reputation to Revered status.", d = "Earn Revered status with the Armies of Legionfall faction, which typically requires extensive reputation grinding through world quests and dungeons. Note that this achievement has a next step in its chain, so plan your reputation gains carefully to unlock subsequent rewards efficiently.", x = 6 },
        [11546] = { e = 3, s = "c", r = "Complete main Legionfall campaign quests.", d = "Complete the entire Legionfall campaign by finishing all associated quests, including Assault on Broken Shore and Defending Broken Isles. This is a major storyline achievement, so ensure you follow the quest chain sequentially without skipping any critical steps to avoid missing content.", x = 6 },
        [11560] = { e = 2, s = "s", r = "Win one brawl fight.", d = "Win a brawl during the Broken Isles campaign, which is part of a legacy series requiring participation in specific seasonal events. Be aware that this achievement may have time gates or limited availability windows, so prioritize it while the event is active.", x = 6 },
        [11561] = { e = 2, s = "s", r = "Win one brawl fight.", d = "Win another brawl during the Broken Isles campaign to complete the second half of this legacy achievement set. Like its counterpart, this requires engaging in seasonal brawls, so monitor event schedules and prepare your character accordingly to maximize success rates.", x = 6 },
        [11563] = { e = 4, s = "g", r = "Grind Brawler's Guild to Rank 4.", d = "Queue for Bizmo's Brawlpub and grind matches until your rank hits 4. This is a time-gated achievement from the Broken Isles campaign that requires you to complete the previous legplate achievement first.", x = 6 },
        [11564] = { e = 4, s = "g", r = "Grind Brawl'gar Arena to Rank 4.", d = "Queue for Brawl'gar Arena and grind matches until your rank hits 4. Like the other guild achievements, this is time-gated content from the Broken Isles campaign that requires you to complete the previous legplate achievement first.", x = 6 },
        [11565] = { e = 5, s = "g", r = "High RNG grind to Rank 8 in guilds.", d = "Continue queueing for Bizmo's Brawlpub until your rank reaches 8. You must finish the Rank 4 achievement before starting this one, and be aware that the entire Brawler's Guild system is time-gated.", x = 6 },
        [11566] = { e = 5, s = "g", r = "High RNG grind to Rank 8 in arena.", d = "Continue queueing for Brawl'gar Arena until your rank reaches 8. You must finish the Rank 4 achievement before starting this one, and be aware that the entire Brawler's Guild system is time-gated.", x = 6 },
        [11567] = { e = 3, s = "g", r = "Grind Brawler's Gold over time.", d = "Participate in Brawler's Guild matches to earn gold, as this account-wide goal requires collecting 20,000 total. Since the entire guild system is time-gated, you cannot complete this after the Broken Isles campaign ends.", x = 6 },
        [11570] = { e = 4, s = "g", r = "Grind Vested Interest stacks.", d = "Queue for any Brawler's Guild match to earn Vested Interest stacks toward your goal. This account-wide achievement is time-gated, so you must finish it while the Broken Isles campaign is still active.", x = 6 },
        [11572] = { e = 4, s = "c", r = "Requires defeating 10 random bosses in Brawler's Guild.", d = "Queue for random brawl modes in Brawler's Guild to defeat ten different bosses. This account-wide goal is time-gated, meaning you must complete it before the Broken Isles campaign concludes.", x = 6 },
        [11573] = { e = 4, s = "g", r = "Must defeat all 7 specific rumbles sequentially.", d = "Defeat every specific rumble listed in the description by queuing for random matches. This account-wide achievement is time-gated and requires you to finish all rumbles while the Brawler's Guild system is still available.", x = 6 },
        [11607] = { e = 3, s = "s", r = "One-time quest with moderate difficulty and RNG.", d = "Complete the specific Broken Shore quest chain involving the Barrel of Storm Brew without taking damage. This is a precise objective within Legion content that requires careful positioning and timing during the final encounter.", x = 6 },
        [11609] = { e = 2, s = "g", r = "Unlocking one artifact trait tree is quick solo.", d = "Unlock one trait tree for any artifact weapon to complete this goal. You must do this before unlocking all trees, as the next achievement in the chain requires you to finish this one first.", x = 6 },
        [11610] = { e = 3, s = "g", r = "Requires unlocking all artifact trait trees.", d = "Unlock the remaining trait trees on all your other artifact weapons after finishing the previous step. This is a sequential goal where you must complete the single-tree unlock before attempting to finish all of them.", x = 6 },
        [11611] = { e = 2, s = "c", r = "Complete a single challenge quest line for appearance.", d = "Complete an artifact challenge quest line to unlock a new weapon appearance. Ensure you have access to the Legion expansion content, as this goal is tied to specific challenge quests available during that era.", x = 6 },
        [11612] = { e = 3, s = "g", r = "Must unlock all challenging artifact appearances.", d = "Unlock all challenging artifact appearances by earning them across your characters, as this is account-wide and requires completing the specific challenge mode for each appearance. Start with any class you have max level on to begin unlocking these cosmetic rewards without needing to grind multiple levels.", x = 6 },
        [11628] = { e = 4, s = "c", r = "Requires collecting a full Tier 19 set on one class.", d = "Collect a Tier 19 set from the Nighthold raid on at least one character to complete this account-wide collection goal. Focus on farming the raid until you obtain the full set, noting that you do not need every piece if you are collecting any class armor set.", x = 6 },
        [11629] = { e = 4, s = "c", r = "Requires collecting a full Season 16 PvP set.", d = "Gather a Season 16 PvP set from Warlords of Draenor PvP Season 1 to fulfill this account-wide requirement. You can equip these items on any character once collected, so prioritize obtaining the full set for one class first.", x = 6 },
        [11630] = { e = 4, s = "c", r = "Requires collecting a full Legion PvP Season 1-2 set.", d = "Acquire a Season 19 or 20 Legion PvP set on at least one character to complete this collection achievement. Since it is account-wide, ensure you have the full set equipped or in your inventory before moving to other sets.", x = 6 },
        [11631] = { e = 4, s = "c", r = "Requires collecting a full Tier 18 Hellfire Citadel set.", d = "Defeat bosses in Hellfire Citadel to obtain a Tier 18 set for any class to unlock this account-wide appearance. Farm the raid until you secure the full set, as missing pieces will prevent completion.", x = 6 },
        [11652] = { e = 3, s = "g", r = "Grinding reputation to Exalted Paragon reward level.", d = "Earn an exalted Paragon reward from any Legion faction to complete this achievement quickly. Focus on one faction and grind reputation until you reach the exalted tier to claim your reward.", x = 6 },
        [11653] = { e = 1, s = "g", r = "Collecting 10 exalted rewards is fast and account-wide.", d = "Collect ten exalted supply rewards from any Broken Isles factions by reaching exalted reputation with them. This is account-wide, so prioritize factions that offer supply rewards upon reaching exalted status.", x = 6 },
        [11674] = { e = 4, s = "s", r = "Requires specific raid mechanics without dying to a mechanic.", d = "Defeat the Desolate Host in Tomb of Sargeras on Normal or higher while keeping the Diminishing Soul alive throughout the fight. Coordinate with your group to manage the boss mechanics and avoid letting the soul perish.", x = 6 },
        [11675] = { e = 4, s = "c", h = { 58251 }, r = "Capturing all anomalies is RNG-heavy and difficult.", d = "Capture every Titanic Anomaly during the Maiden of Vigilance encounter in Tomb of Sargeras on Normal or higher difficulty. Use ranged abilities or specific mechanics to secure each anomaly before defeating the boss.", x = 6 },
        [11676] = { e = 3, s = "c", r = "Feeding items is moderate but requires raid coordination.", d = "Defeat Mistress Sass'zine in Tomb of Sargeras after feeding Sarukel four specific items: Hydra Essence, Eel Tartare, Ink Sauce, Murloc Fillet, and Player Seasoning. Gather these items beforehand from various sources before starting the encounter.", x = 6 },
        [11681] = { e = 4, s = "s", r = "Requires surviving a specific transformation mechanic in raid.", d = "Reach the final portal of the Dreadex in Broken Shore without losing your Wyrmtongue Transformation during the fight. Manage your transformation cooldowns carefully to maintain it until you reach the portal.", x = 6 },
        [11683] = { e = 4, s = "c", h = { 58298, 58299 }, r = "Avoiding floor breaks requires precise timing and luck.", d = "Defeat the Fallen Avatar in Tomb of Sargeras on Normal or higher while keeping all floor segments intact in specific patterns. Coordinate with your group to avoid breaking columns or rows during the encounter.", x = 6 },
        [11685] = { e = 4, s = "g", r = "Reaching Prestige Level 10 takes significant PvP time.", d = "Focus on PvP activities to gain Prestige points until you hit level 10, as this is a linear progression chain. Do not stop at lower levels since each achievement requires the previous one to unlock the next step in the sequence.", x = 6 },
        [11686] = { e = 4, s = "g", r = "Continuing the prestige grind requires more PvP effort.", d = "Continue accumulating Prestige points through competitive play to reach level 11 immediately after completing the prior requirement. This process is purely time-gated by your activity in PvP arenas or battlegrounds.", x = 6 },
        [11687] = { e = 4, s = "g", r = "Further prestige levels demand sustained competitive play.", d = "Keep grinding Prestige levels without interruption to unlock level 12, ensuring you maintain enough points to progress steadily through the chain. There are no specific mechanics other than consistent participation in ranked content.", x = 6 },
        [11688] = { e = 4, s = "g", r = "Reaching Prestige Level 13 is a long-term goal.", d = "Advance your Prestige rank to 13 by staying active in PvP modes, noting that this step simply continues the linear climb from the previous level. No special conditions or group requirements exist beyond standard Prestige farming.", x = 6 },
        [11689] = { e = 4, s = "g", r = "Prestige progression continues to require dedicated PvP.", d = "Reach Prestige Level 14 by continuing to earn points in any PvP activity, as the only barrier is reaching the specific numerical threshold. Treat this like a checklist where you must simply accumulate enough wins or kills over time.", x = 6 },
        [11690] = { e = 4, s = "g", r = "Reaching Prestige Level 15 is a very long grind.", d = "Push your Prestige level to 15 through regular PvP engagement, remembering that missing this step will prevent access to subsequent achievements in the chain. The game tracks your progress automatically once you start farming points.", x = 6 },
        [11691] = { e = 4, s = "g", r = "Requires extensive PvP grinding to reach Prestige 16.", d = "Aim for Prestige Level 16 by maintaining consistent participation in ranked matches or battlegrounds to ensure steady point accumulation. This achievement is straightforward but requires patience as it depends entirely on your PvP performance.", x = 6 },
        [11692] = { e = 4, s = "g", r = "Continues the long grind for Prestige 17.", d = "Continue climbing the Prestige ladder to reach level 17, keeping in mind that this is a cumulative goal with no shortcuts available. Your only strategy is to play enough PvP content to naturally hit the required threshold.", x = 6 },
        [11693] = { e = 4, s = "g", r = "Continues the long grind for Prestige 18.", d = "Reach Prestige Level 18 by persistently farming points in PvP arenas or battlegrounds, as there are no alternative methods to gain these levels. Treat this as a long-term goal that requires regular engagement with the game's competitive modes.", x = 6 },
        [11694] = { e = 4, s = "g", r = "Continues the long grind for Prestige 19.", d = "Advance to Prestige Level 19 through continued PvP activity, noting that each level up is a prerequisite for the next in the sequence. There are no time limits or rare drops involved, just consistent effort in ranked content.", x = 6 },
        [11696] = { e = 3, s = "s", r = "Single raid encounter with specific Torment requirement.", d = "Gather a full party and enter Tomb of Sargeras on Normal difficulty with all members at maximum Torment to defeat the Demonic Inquisition boss. Ensure everyone is properly geared for high Torment before starting the encounter to avoid unnecessary deaths.", x = 6 },
        [11699] = { e = 4, s = "g", r = "Requires farming rare drop Mrgrglhjorn then raiding.", d = "Summon Elder Murk-Eye using the Mrgrglhjorn item and then coordinate with your group to defeat both him and Harjatan in Tomb of Sargeras on Normal or higher. This is an account-wide achievement, so any character can complete it once the bosses are defeated.", x = 6 },
        [11700] = { e = 2, s = "s", r = "Single dungeon boss kill on Normal difficulty.", d = "Start by defeating Mephistroth in normal difficulty to unlock the next tier. This is a straightforward dungeon kill with no special mechanics or time gates.", x = 6 },
        [11701] = { e = 3, s = "s", r = "Single dungeon boss kill on Heroic difficulty.", d = "Complete the normal version first, then queue for Heroic Cathedral of Eternal Night to defeat Mephistroth again. No additional requirements exist beyond finishing the previous achievement.", x = 6 },
        [11702] = { e = 4, s = "s", r = "Single dungeon boss kill on Mythic difficulty.", d = "You must finish the Heroic version before attempting Mythic difficulty. Once unlocked, defeat Mephistroth on Mythic to claim this point.", x = 6 },
        [11703] = { e = 5, s = "g", r = "Mythic run requiring specific mechanic blocks and luck.", d = "Play Mythic Cathedral of Eternal Night and equip the Aegis of Aggramar to block Shadow Blasts. You need to survive 20 blocks before killing Mephistroth, so be prepared for a longer fight.", x = 6 },
        [11706] = { e = 4, s = "g", r = "Requires collecting full PvP set via ranked play.", d = "Collect any full armor set from PvP Season 1 on at least one character. This is account-wide, so you can share gear across your entire account.", x = 6 },
        [11707] = { e = 4, s = "g", r = "Requires collecting full PvP set via ranked play.", d = "Gather a complete set of armor from PvP Season 2 for any class. Like the previous seasons, this requirement applies to your whole account.", x = 6 },
        [11708] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Obtain a full armor set from PvP Season 3 on any character. Ensure you have all pieces equipped or in your inventory before claiming the achievement.", x = 6 },
        [11709] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Collect a complete set of armor from PvP Season 4. This is account-wide, so you can use gear earned by any character on your account.", x = 6 },
        [11710] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Gather a full armor set from PvP Season 5 for any class. Remember that this requirement tracks across all characters on your account.", x = 6 },
        [11711] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Collect a complete set of armor from PvP Season 6. You can fulfill this by equipping the set on any single character.", x = 6 },
        [11712] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Obtain a full armor set from PvP Season 7. This is account-wide, meaning you can use gear from any character to complete the set.", x = 6 },
        [11713] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Collect a complete set of armor from PvP Season 8. Ensure you have all pieces before claiming the achievement as it is account-wide.", x = 6 },
        [11714] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Equip a Season 9 PvP set on any class to complete this account-wide collection. Since these sets are no longer obtainable in current retail content, you must have previously earned them or use an alternate character that already has the gear.", x = 6 },
        [11715] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Equip a Season 10 PvP set on any class to finish this collection. Like previous seasons, these items are no longer available in current retail content, so you must have earned them previously or use an alternate character.", x = 6 },
        [11716] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Equip a Season 11 PvP set on any class to complete this collection. These sets are no longer obtainable in current retail content, so you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11717] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Equip a Season 12 PvP set on any class to finish this collection. Since these items are no longer available in current retail content, you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11718] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Equip a Season 13 PvP set on any class to complete this collection. These sets are no longer obtainable in current retail content, so you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11719] = { e = 2, s = "g", r = "Buy or earn a PvP set; trivial for active players.", d = "Equip a Season 14 PvP set on any class to finish this collection. Since these items are no longer available in current retail content, you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11720] = { e = 3, s = "g", r = "Grinding PvP sets on one class takes hours.", d = "Equip a Season 15 PvP set on any class to complete this collection. These sets are no longer obtainable in current retail content, so you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11721] = { e = 3, s = "g", r = "Grinding PvP sets on one class takes hours.", d = "Equip a Season 17 PvP set on any class to finish this collection. Since these items are no longer available in current retail content, you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11722] = { e = 3, s = "g", r = "Grinding PvP sets on one class takes hours.", d = "Equip a Season 18 PvP set on any class to complete this collection. These sets are no longer obtainable in current retail content, so you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11723] = { e = 3, s = "g", r = "Grinding PvP sets on one class takes hours.", d = "Equip a Season 21 or 22 PvP set on any class to finish this collection. Since these items are no longer available in current retail content, you must have earned them previously or use an alternate character that already has the gear.", x = 6 },
        [11724] = { e = 4, s = "s", r = "Requires specific raid mechanics and RNG spikes.", d = "Defeat Goroth in Tomb of Sargeras on Normal difficulty after destroying 30 Infernal Spikes with Shattering Stars. This achievement is time-gated as the raid content is no longer accessible in current retail content.", x = 6 },
        [11725] = { e = 4, s = "g", r = "Huge fish counts make this a long grind.", d = "Fish for all Broken Isles masters until you reach Best Friends status with each of them to complete this account-wide collection. Note that fishing quests and mechanics may be unavailable or altered in current retail content.", x = 6 },
        [11731] = { e = 2, s = "g", r = "Quick Mage Tower runs complete the task fast.", d = "Queue for Mage Tower encounters on the Broken Shore until you have five contributions. This is a time-gated achievement that requires active Legion content and cannot be completed after patch 8.0.", x = 6 },
        [11732] = { e = 4, s = "g", r = "50 contributions is a significant time investment.", d = "Complete the previous step, then continue queuing for Mage Tower until you reach fifty contributions. Like the first part, this is account-wide but only available during the Legion expansion era.", x = 6 },
        [11735] = { e = 2, s = "g", r = "Quick Command Center runs complete the task fast.", d = "Queue for Command Center encounters on the Broken Shore to earn five contributions quickly. Ensure you are in a group capable of defeating the commander before attempting this time-gated objective.", x = 6 },
        [11736] = { e = 4, s = "g", r = "50 contributions is a significant time investment.", d = "Finish the prior step and keep contributing to the Command Center until you hit fifty total. This account-wide achievement is missable once Legion content is no longer accessible.", x = 6 },
        [11737] = { e = 2, s = "g", r = "Quick Nether Disruptor runs complete the task fast.", d = "Queue for Nether Disruptor encounters on the Broken Shore to gather five contributions efficiently. You must complete this while the Broken Shore is active, as it is a time-gated achievement.", x = 6 },
        [11738] = { e = 4, s = "g", r = "50 contributions is a significant time investment.", d = "Complete the previous step and continue disrupting the Nether until you reach fifty contributions. This account-wide goal requires persistent participation in Legion Broken Shore events before they are removed.", x = 6 },
        [11740] = { e = 3, s = "g", r = "Requires farming Tier 17 gear on one class.", d = "Collect any Tier 17 armor set from Blackrock Foundry for at least one class to complete this collection. Since sets are account-wide, you can use any character to gather the pieces needed.", x = 6 },
        [11741] = { e = 3, s = "g", r = "Requires farming Molten Core drops on one class.", d = "Gather a Tier 1 armor set from Molten Core for your chosen class to finish this appearance collection. These items are rare drops, so be prepared to run the raid multiple times.", x = 6 },
        [11742] = { e = 3, s = "g", r = "Requires farming Blackwing Lair drops on one class.", d = "Collect any Tier 2 armor set from Blackwing Lair for at least one class to complete this achievement. Focus on obtaining specific pieces rather than needing a full set immediately.", x = 6 },
        [11743] = { e = 3, s = "g", r = "Requires farming AQ40 drops on one class.", d = "Gather a Tier 2.5 armor set from the Temple of Ahn'Qiraj for your selected class. This collection is account-wide, allowing you to use different characters to find missing pieces.", x = 6 },
        [11746] = { e = 3, s = "g", r = "Requires farming multiple raids for Tier 4 gear.", d = "Collect any Tier 4 armor set from Gruul's Lair, Karazhan, or Magtheridon's Lair for one class. You can mix and match drops from these three raids to complete the requirement.", x = 6 },
        [11747] = { e = 3, s = "g", r = "Requires farming Serpentshrine Cavern drops on one class.", d = "Gather a Tier 5 armor set from Serpentshrine Cavern or The Eye of Aman'Thul for your class. Since this is account-wide, utilize any character to acquire the necessary pieces.", x = 6 },
        [11748] = { e = 3, s = "g", r = "Requires farming Black Temple drops on one class.", d = "Start by collecting Black Temple tier pieces for one class, as this set is account-wide and requires no specific group composition beyond standard raid runs. Focus on obtaining the full set rather than individual items to ensure you meet the 'any class armor set' requirement efficiently.", x = 6 },
        [11749] = { e = 3, s = "g", r = "Requires farming Sunwell Plateau drops on one class.", d = "Begin farming Sunwell Plateau immediately after unlocking it, prioritizing the Tier 6.5 set drops which are account-wide and do not require specific group setups. Ensure you complete enough raid runs to guarantee a full set drop for at least one character before moving on.", x = 6 },
        [11750] = { e = 3, s = "g", r = "Requires farming Naxxramas drops on one class.", d = "Enter Naxxramas early in your progression to farm the Tier 7 set, noting that this content is account-wide and drops are random per run. Aim to clear multiple weeks of raids to maximize your chances of collecting a full set for one class without missing any pieces.", x = 6 },
        [11751] = { e = 3, s = "g", r = "Requires farming Ulduar drops on one class.", d = "Focus on Ulduar raids to collect the Tier 8 set, keeping in mind that this achievement is account-wide and requires no specific group coordination beyond standard raid composition. Run enough instances to ensure you receive a complete set drop for at least one character.", x = 6 },
        [11752] = { e = 3, s = "g", r = "Requires farming ToC drops on one class.", d = "Start collecting Trial of the Crusader pieces early since the Tier 9 set is account-wide and drops randomly from weekly raids. Prioritize getting a full set on one class before switching characters to avoid wasting time on incomplete sets.", x = 6 },
        [11753] = { e = 3, s = "g", r = "Requires farming ICC drops on one class.", d = "Farm Icecrown Citadel for the Tier 10 set, remembering that this achievement is account-wide and requires no specific group setup beyond standard raid runs. Clear multiple weeks of raids to ensure you collect a full set for at least one character without missing any pieces.", x = 6 },
        [11754] = { e = 3, s = "g", r = "Requires farming a full raid set on one class.", d = "Begin farming The Bastion of Twilight and Blackwing Descent for the Tier 11 set, noting that this achievement is account-wide and drops are random per run. Focus on completing enough raid runs to guarantee a full set drop for at least one class before moving on.", x = 6 },
        [11755] = { e = 3, s = "g", r = "Requires farming a full raid set on one class.", d = "Start collecting Firelands pieces early since the Tier 12 set is account-wide and requires no specific group composition beyond standard raid runs. Aim to complete multiple weeks of raids to maximize your chances of collecting a full set for one character without missing any pieces.", x = 6 },
        [11756] = { e = 3, s = "g", r = "Requires farming a full raid set on one class.", d = "Enter Dragon Soul raids immediately after unlocking them to farm the Tier 13 set, which is account-wide and drops randomly per run. Prioritize getting a full set on one class before switching characters to avoid wasting time on incomplete sets.", x = 6 },
        [11757] = { e = 3, s = "g", r = "Requires farming a full raid set on one class.", d = "Farm Heart of Fear and Terrace of Endless Spring for the Tier 14 set, keeping in mind that this achievement is account-wide and requires no specific group setup beyond standard raid composition. Run enough instances to ensure you receive a complete set drop for at least one character.", x = 6 },
        [11758] = { e = 3, s = "g", r = "Requires farming a full raid set on one class.", d = "Focus on Throne of Thunder raids to collect the Tier 15 set, noting that this achievement is account-wide and drops are random per run. Clear multiple weeks of raids to ensure you collect a full set for at least one class without missing any pieces.", x = 6 },
        [11759] = { e = 3, s = "g", r = "Requires farming a full raid set on one class.", d = "Start collecting Siege of Orgrimmar pieces early since the Tier 16 set is account-wide and requires no specific group composition beyond standard raid runs. Aim to complete multiple weeks of raids to maximize your chances of collecting a full set for one character without missing any pieces.", x = 6 },
        [11760] = { e = 4, s = "g", r = "T20 requires high-level Mythic+ or raiding.", d = "Equip any Tier 20 set piece from the Tomb of Sargeras on one character. This unlocks the achievement account-wide, so you do not need to collect full sets for every class.", x = 6 },
        [11761] = { e = 5, s = "c", r = "Requires collecting sets from 10 different tiers/seasons.", d = "Unlock a distinct armor set from ten different raid tiers or PvP seasons to earn the Stylist title. Ensure your collection covers various sources like raids and PvP before claiming the reward.", x = 6 },
        [11762] = { e = 3, s = "g", r = "Requires farming a full PvP set on one class.", d = "Collect any class armor set from the Trial of Valor dungeon. Since this is account-wide, one character completing the dungeon with a full set is sufficient for all accounts.", x = 6 },
        [11763] = { e = 5, s = "c", r = "Requires completing multiple specific raid achievements.", d = "Complete specific Tomb of Sargeras raid achievements like Fel Turkey and Bingo! to earn The Tomb Raider title. Focus on these unique objectives rather than just defeating bosses.", x = 6 },
        [11765] = { e = 2, s = "s", r = "Single pet battle challenge with a fixed reward.", d = "Finish the Pet Battle Challenge in Wailing Caverns to receive the Son of Skum pet. Ensure you have a strong team ready before entering the challenge instance.", x = 6 },
        [11767] = { e = 4, s = "s", r = "Requires defeating a specific Mythic raid boss.", d = "Defeat Goroth inside the Tomb of Sargeras raid on Mythic difficulty. This requires a high-level group capable of handling the increased mechanics and damage output.", x = 6 },
        [11768] = { e = 4, s = "c", r = "Mythic dungeon with specific mechanics and RNG.", d = "Kill Agronox in Cathedral of Eternal Night after fulminating four budding flowers on Mythic difficulty. Coordinate your party to manage the flower mechanic before engaging the boss.", x = 6 },
        [11769] = { e = 5, s = "c", r = "Requires reading entire saga before raid boss.", d = "Defeat Thrashbite the Scornful only after every party member has read the Steamy Romance saga on Mythic difficulty. Ensure all members complete the reading requirement first.", x = 6 },
        [11770] = { e = 4, s = "s", r = "Mythic raid fight with strict RNG condition.", d = "Defeat Kil'jaeden in Tomb of Sargeras without any Shadowsouls finishing Destabilized Shadowsoul casts on Normal or higher. This requires careful management of the Shadow Soul mechanic during the fight.", x = 6 },
        [11772] = { e = 3, s = "g", r = "Unlocking all artifact traits is a grind.", d = "Unlock every Artifact Trait for a single weapon by empowering it fully. Note that this achievement is locked behind the Power Realized expansion feature requirement.", x = 6 },
        [11773] = { e = 4, s = "c", r = "Requires specific boss order in Mythic raid.", d = "Defeat a Waxing Twilight Soul before killing the Sisters of the Moon in Tomb of Sargeras on Normal or higher. Ensure you clear the specific encounter order correctly during the raid.", x = 6 },
        [11774] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Defeat Demonic Inquisition within the Tomb of Sargeras raid on Mythic difficulty. Assemble a capable group to handle the challenging mechanics of this specific boss encounter.", x = 6 },
        [11775] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Queue for Mythic Harjatan in Tomb of Sargeras. Ensure your group is prepared for high-level mechanics as this is a raid-only achievement.", x = 6 },
        [11776] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Defeat Mistress Sassz'ine on Mythic difficulty within the Tomb of Sargeras. This requires a coordinated raid group and sufficient gear from prior content.", x = 6 },
        [11777] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Clear the Sisters of the Moon encounter on Mythic difficulty. Coordinate with your raid leader to manage the complex mechanics of this fight.", x = 6 },
        [11778] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Defeat the Desolate Host in the Tomb of Sargeras on Mythic. This boss requires precise timing and coordination from all raid members.", x = 6 },
        [11779] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Kill the Maiden of Vigilance on Mythic difficulty. Be prepared for challenging mechanics that demand high skill and teamwork in a raid setting.", x = 6 },
        [11780] = { e = 5, s = "s", r = "Mythic raid boss on highest difficulty.", d = "Defeat Fallen Avatar in the Tomb of Sargeras on Mythic. Ensure your group has adequate gear to handle this demanding encounter successfully.", x = 6 },
        [11781] = { e = 3, s = "s", r = "Requires a full raid group and specific Mythic difficulty.", d = "Complete the final boss Kil'jaeden on Mythic difficulty to earn the title The Darkener. This is a long-term goal requiring significant progression through Legion content.", x = 6 },
        [11786] = { e = 4, s = "c", h = { 58914, 58915, 58916 }, r = "Grind against rare world bosses with RNG drop rates.", d = "Defeat all four Broken Shore world bosses: Brutallus, Malificus, Si'vash, and Apocron. This achievement is account-wide, so coordinate with friends across realms if needed.", x = 6 },
        [11787] = { e = 3, s = "c", h = { 58921 }, r = "Requires defeating multiple raid bosses including a heavy RNG boss.", d = "Clear the first wing of Tomb of Sargeras by defeating Mistress Sassz'ine, Harjatan, and Goroth. This is a prerequisite for accessing deeper dungeon levels.", x = 6 },
        [11788] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses in sequence.", d = "Defeat bosses in the lower levels including The Desolate Host, Sisters of the Moon, and Demonic Inquisition. Progress sequentially through the dungeon wings to unlock these encounters.", x = 6 },
        [11789] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses in sequence.", d = "Clear the ancient vault by defeating Maiden of Vigilance and Fallen Avatar. Ensure you have completed previous wings before attempting this section of the raid.", x = 6 },
        [11790] = { e = 4, s = "s", r = "Final boss requires full Mythic raid group and RNG.", d = "Defeat Kil'jaeden in the final wing of Tomb of Sargeras. This is the ultimate challenge requiring maximum gear and coordination from your entire raid group.", x = 6 },
        [11796] = { e = 4, s = "g", r = "Requires extensive grinding for reputation with a specific faction.", d = "Grind Broken Shore to Exalted with the Armies of Legionfall faction. This is account-wide and requires reaching Revered first before earning the final points.", x = 6 },
        [11802] = { e = 3, s = "c", r = "Requires visiting and activating beacons in multiple zones.", d = "Use a Sentinax beacon in every listed Broken Shore area. You must visit each zone specifically to trigger the beacon effect for credit.", x = 6 },
        [11841] = { e = 3, s = "c", r = "Requires summoning and defeating multiple specific bosses.", d = "Summon and kill all demonic lieutenants from your Sentinax in Broken Shore. These bosses only appear when you use the beacon in their respective zones.", x = 6 },
        [11846] = { e = 2, s = "s", r = "Single quest completion with a follower reward.", d = "Complete the specific quest Champions of Legionfall to recruit your campaign follower. Ensure you have the prerequisite reputation before starting this quest.", x = 6 },
        [11856] = { e = 3, s = "s", r = "Requires completing a specific pet battle challenge dungeon.", d = "Enter Deadmines and complete the Pet Battle Challenge instance. This is account-wide, so any character on your account can finish it for everyone.", x = 6 },
        [11861] = { e = 3, s = "c", r = "Requires completing multiple storylines in Zuldazar zone.", d = "Finish all major storylines in Zuldazar including Portents and Prophecies. Check the zone achievement tracker to ensure you have completed every required quest line.", x = 7 },
        [11868] = { e = 3, s = "c", r = "Multiple storylines in Nazmir require zone exploration.", d = "Complete the Nazmir storyline quests listed in the info field. These are often tied to specific faction reputures or world events in the zone.", x = 7 },
        [11915] = { e = 4, s = "s", r = "Requires defeating a specific raid boss on Normal+.", d = "Defeat Aggramar on Normal difficulty after killing a Manifestation of Taeshalach in Antorus. This credit is account-wide and requires high-level raid gear.", x = 6 },
        [11918] = { e = 2, s = "s", r = "Participate in one concert event at Darkmoon Faire.", d = "Participate in the Blight Boar concert event at Darkmoon Faire. You must be present during the specific concert window to earn this point.", x = 6 },
        [11919] = { e = 3, s = "c", r = "Requires assigning all band roles after the concert.", d = "Play every band role including Guitarist and Vocals during the Blight Boar concert. Switch roles between songs to unlock all individual credits.", x = 6 },
        [11920] = { e = 4, s = "s", r = "Requires perfect performance RNG during a raid event.", d = "Achieve a perfect score on the Blight Boar concert performance. This requires flawless execution of your assigned band role throughout the entire song.", x = 6 },
        [11921] = { e = 3, s = "s", r = "Requires surviving a concert without ghouls reaching the singer.", d = "Prevent any ghouls from reaching Devlynn Styx during the concert. Focus on crowd control and damage to keep the stage clear for this specific condition.", x = 6 },
        [11928] = { e = 4, s = "s", r = "Requires defeating a specific raid boss after opening a rift.", d = "Defeat Portal Keeper Hasabel in Antorus on Normal or higher after opening a chaotic rift. Ensure you have the rift open before engaging her to avoid missing the requirement.", x = 6 },
        [11929] = { e = 4, s = "s", r = "Requires defeating a specific dungeon boss on Heroic+.", d = "Complete the Return to Karazhan raid on Heroic difficulty or higher to defeat Viz'aduum the Watcher. This is a timed achievement, so plan your dungeon run carefully within the time limit.", x = 6 },
        [11930] = { e = 4, s = "g", r = "Requires decimating 16 worms before the raid boss.", d = "Decimate 16 Blightscale Worms in Antorus on Normal or higher before defeating Garothi Worldbreaker. Farm these worms efficiently during the raid to ensure you meet the count before the boss fight.", x = 6 },
        [11941] = { e = 2, s = "s", r = "Reach max friendship rank with Chromie via quests.", d = "Reach Timelord friendship rank with Chromie for an account-wide title. This requires completing Chromie Time quests and earning reputation across all timelines until you hit the maximum rank.", x = 6 },
        [11948] = { e = 5, s = "s", r = "Requires defeating a raid boss without triggering a specific mechanic.", d = "Defeat Varimathras in Antorus on Normal or higher without triggering Alone in the Darkness. Coordinate with your group to avoid isolation mechanics during the fight to secure this achievement.", x = 6 },
        [11949] = { e = 5, s = "s", r = "Requires triggering every trap on the bridge before the boss.", d = "Trigger every trap on the bridge before defeating Imonar the Soulhunter in Antorus on Normal or higher. Be prepared to interact with specific objects or enemies to activate all traps during the encounter.", x = 6 },
        [11987] = { e = 5, s = "c", h = { 60526 }, r = "Requires full raid group and multiple mythic bosses.", d = "Complete all listed Argus raid achievements to earn the Glory of the Argus Raider mount. This is a collection goal, so ensure you have every sub-achievement unlocked before claiming the reward.", x = 6 },
        [11988] = { e = 5, s = "c", h = { 60532, 60534 }, r = "Requires full raid group and multiple mythic bosses.", d = "Defeat Garothi Worldbreaker, Hounds of Sargeras, and Antoran High Command at Antorus' entrance. These are wing-specific achievements, so clear the first island bosses to unlock this milestone.", x = 6 },
        [11989] = { e = 5, s = "c", h = { 60537 }, r = "Requires full raid group and multiple mythic bosses.", d = "Defeat Portal Keeper Hasabel, Eonar, and Imonar the Soulhunter on the second island of Antorus. Clear the middle section of the raid to complete these specific wing achievements.", x = 6 },
        [11990] = { e = 5, s = "c", h = { 60540, 60541, 60542 }, r = "Requires full raid group and multiple mythic bosses.", d = "Defeat Kin'garoth, Varimathras, and The Coven of Shivarra in the depths of Antorus. These bosses are located in the third wing, so progress through the raid zones to reach them.", x = 6 },
        [11991] = { e = 5, s = "c", h = { 60544, 60545 }, r = "Requires full raid group and multiple mythic bosses.", d = "Defeat Aggramar and Argus the Unmaker in the final wing of Antorus. This requires clearing the deepest part of the raid, ensuring you have completed previous wings first.", x = 6 },
        [11992] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Defeat Garothi Worldbreaker in Antorus on Mythic difficulty. Note that this is a specific difficulty requirement, so ensure your group is prepared for the higher challenge level.", x = 6 },
        [11993] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Defeat Hounds of Sargeras in Antorus on Mythic. Ensure you have the required achievement unlocked first.", x = 6 },
        [11994] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Kill Antoran High Command in Antorus on Mythic. This requires unlocking the War Council achievement beforehand.", x = 6 },
        [11995] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Defeat Portal Keeper Hasabel in Antorus on Mythic. Make sure you have the Keeper achievement ready.", x = 6 },
        [11996] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Successfully defend Eonar in Antorus on Mythic. Unlock the Eonar achievement before attempting this fight.", x = 6 },
        [11997] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Defeat Imonar the Soulhunter in Antorus on Mythic. You must complete the Bounty Hunter achievement first.", x = 6 },
        [11998] = { e = 5, s = "c", r = "Mythic difficulty requires high-level raid group.", d = "Kill Kin'garoth in Antorus on Mythic. Ensure you have the Engineer achievement unlocked prior to starting.", x = 6 },
        [11999] = { e = 4, s = "s", r = "Requires Mythic raid clear; high skill ceiling.", d = "Defeat Varimathras in Antorus on Mythic. Unlock the Varimathras achievement before engaging the final boss.", x = 6 },
        [12000] = { e = 4, s = "s", r = "Requires Mythic raid clear; high skill ceiling.", d = "Defeat The Coven of Shivarra in Antorus on Mythic. Complete the Shivarra achievement first to unlock this.", x = 6 },
        [12001] = { e = 4, s = "s", r = "Requires Mythic raid clear; high skill ceiling.", d = "Kill Aggramar in Antorus on Mythic. You need the Aggramar achievement unlocked before attempting this raid boss.", x = 6 },
        [12002] = { e = 5, s = "s", r = "Needs full raid, specific mechanics, and RNG.", d = "Defeat Argus the Unmaker in Antorus on Mythic for the Titanslayer title. Unlock the World Soul achievement first.", x = 6 },
        [12007] = { e = 4, s = "s", r = "Heroic dungeon clear requires high skill.", d = "Defeat L'ura in Seat of the Triumvirate on Heroic or higher. This is a prerequisite for the Mythic version.", x = 6 },
        [12008] = { e = 5, s = "s", r = "Mythic dungeon requires full raid and mastery.", d = "Defeat L'ura in Seat of the Triumvirate on Mythic. You must complete the Heroic version first to unlock this.", x = 6 },
        [12020] = { e = 4, s = "g", r = "Grinding for T21 sets across multiple classes.", d = "Equip a full Tier 21 set on one character to earn points for all classes. This is account-wide and requires no specific boss kills.", x = 6 },
        [12021] = { e = 3, s = "g", r = "Collecting PvP gear is time-consuming but doable.", d = "Gear up with PvP sets from Legion Seasons 5, 6, or 7 on any class. Since this is account-wide, one character can complete it for everyone.", x = 6 },
        [12026] = { e = 4, s = "c", h = { 61021, 61022, 61023 }, r = "Defeating all generals is a long checklist grind.", d = "Visit each Greater Invasion Point in Legion and defeat the specific General listed there. You must enter the scenario to trigger the encounter.", x = 6 },
        [12028] = { e = 4, s = "c", h = { 61028, 61029, 61030 }, r = "Slaying all commanders is a long checklist grind.", d = "Defeat all demonic commanders controlling Invasion Points by entering their Rifts. These are account-wide, so one character can finish them for your whole account.", x = 6 },
        [12030] = { e = 4, s = "s", r = "Requires specific boss mechanics and RNG.", d = "Kill Kin'garoth in Antorus while maintaining 9 active Diabolic Bombs on Normal or higher. This requires careful management of the bomb mechanic during the fight.", x = 6 },
        [12046] = { e = 5, s = "s", r = "Needs full raid, specific mechanics, and RNG.", d = "Defeat Shivarra Council in Antorus ensuring at least one Torment survives from each faction. Coordinate with your group to avoid killing all Torments prematurely.", x = 6 },
        [12065] = { e = 4, s = "c", h = { 61127 }, r = "Requires raiding and specific debuff mechanics.", d = "Kill Felhounds of Sargeras in Antorus while keeping both on 5 stacks of Fel Imbuement. Apply the debuff consistently before pulling them down.", x = 6 },
        [12066] = { e = 3, s = "c", r = "Campaign quests take a few hours total.", d = "Complete the entire Argus campaign quest chain to unlock this achievement. Ensure you finish all major story quests listed in the requirements.", x = 6 },
        [12067] = { e = 4, s = "g", r = "Requires finding and collecting raid orbs.", d = "Collect all five Orbs of Life from Eonar's sanctuary in Antorus on Normal or higher. Locate each orb carefully as they are placed around the raid room.", x = 6 },
        [12069] = { e = 3, s = "c", r = "Exploration across multiple zones takes time.", d = "Explore every covered area on Krokuun, Eredath, and the Antoran Wastes to reveal the map. Use flying mounts to speed up this account-wide exploration task.", x = 6 },
        [12071] = { e = 1, s = "s", r = "Simple quest completion for artifact power.", d = "Fully upgrade one artifact weapon in the Netherlight Crucible to max power. This legacy achievement tracks your total progress on a single item.", x = 6 },
        [12072] = { e = 1, s = "s", r = "Single quest to unlock the crucible.", d = "Complete the quest 'The Netherlight Crucible' to unlock the system for all characters. Once unlocked, you can use it across any class or specialization.", x = 6 },
        [12073] = { e = 2, s = "c", r = "Collecting cores via quests is straightforward.", d = "Unlock all four Matrix Core powers by completing their specific quests, which are required for the main Legion campaign. This is an account-wide achievement that gates your ability to fully utilize the Vindicaar's abilities.", x = 6 },
        [12074] = { e = 3, s = "g", r = "Finding hidden chests takes exploration time.", d = "Open every hidden chest and cache across Argus while exploring the zone thoroughly. Many of these treasures are missable if you do not interact with them before leaving the area or resetting the instance.", x = 6 },
        [12076] = { e = 4, s = "g", r = "Reaching Exalted requires significant reputation grind.", d = "Grind reputation with the Argussian Reach faction until you reach Exalted status. Focus on daily quests and world events in the zone to speed up this process efficiently.", x = 6 },
        [12077] = { e = 3, s = "c", r = "Killing 25 rare elites takes moderate time.", d = "Kill 25 rare elites scattered throughout Argus, including specific named bosses like Mother Rosula and Gar'zoth. Use a group to handle these tough encounters quickly before they despawn.", x = 6 },
        [12078] = { e = 4, s = "c", r = "Killing all rare elites is a long grind.", d = "Complete all remaining special encounters on Argus after finishing the previous elite kills. This includes defeating Vagath the Betrayed multiple times, so plan your route carefully to avoid missing any targets.", x = 6 },
        [12079] = { e = 3, s = "g", r = "Collecting pets from multiple raids takes time.", d = "Collect all listed battle pets from raids like Firelands and Dragon Soul before patching out their drops. Some pets are rare or have low drop rates, so be patient and persistent.", x = 6 },
        [12081] = { e = 4, s = "c", r = "Requires Exalted reputation grind with Army of the Light.", d = "Earn Exalted reputation with the Army of the Light faction through daily quests and world events. This is account-wide, so coordinate with friends to speed up the grind if possible.", x = 6 },
        [12083] = { e = 5, s = "c", h = { 61540 }, r = "Requires Seat of the Triumvirate raid and other Legion content.", d = "Complete all prerequisite Argus achievements listed in the info field to unlock this meta achievement. Ensure you have finished every sub-achievement before claiming the Lightbringer title reward.", x = 6 },
        [12084] = { e = 3, s = "g", r = "Grinding lightning strikes on Argus takes time but is doable solo.", d = "Stand in lightning strikes on Argus to become Fel Infused, then kill 10 enemies while maintaining that buff. Watch your timer closely and move quickly to avoid losing the infusion effect.", x = 6 },
        [12087] = { e = 2, s = "s", r = "Single event horse show; partial progress irrelevant.", d = "Participate in the Norwington Estate horse show event in Tiragarde Sound and score at least 600 points. This requires engaging with the specific mini-game mechanics introduced in Battle for Azeroth.", x = 7 },
        [12088] = { e = 4, s = "c", h = { 61577 }, r = "Requires defeating many corrupted pets including rare Mar'cuus.", d = "Defeat all corrupted pets on Argus using any team composition. These are often found near rare elites, so check your kill feed to ensure you have defeated every single one listed.", x = 6 },
        [12089] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Aquatic type.", d = "Use only aquatic-type battle pets to defeat the corrupted Argus pets listed in this achievement. Prepare a team of water-based pets beforehand to maximize your chances of success.", x = 6 },
        [12091] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Beast type.", d = "Gather Beast-type pets first to start this chain. Defeat the corrupted Argus pets listed in the info field using only your Beast pets. This is account-wide and requires no group, but ensure you have enough pets before starting.", x = 6 },
        [12092] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Critter type.", d = "Collect Critter-type pets to begin this achievement. Fight the specific corrupted Argus pets using only your Critter pets. It is account-wide and does not require a group, so solo play is fine once you have the right pets.", x = 6 },
        [12093] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Dragonkin type.", d = "Acquire Dragonkin pets to start this task. Defeat the required corrupted Argus pets using only your Dragonkin pets. This is account-wide and can be done solo after gathering the necessary pet types.", x = 6 },
        [12094] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Elemental type.", d = "Get Elemental-type pets ready for this challenge. Battle the listed corrupted Argus pets using exclusively your Elemental pets. It is account-wide and requires no group, making it suitable for solo completion once prepared.", x = 6 },
        [12095] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Flying type.", d = "Gather Flying-type pets to initiate this achievement. Defeat the corrupted Argus pets using only your Flying pets. This is account-wide and does not require a group, so you can complete it alone after collecting the pets.", x = 6 },
        [12096] = { e = 4, s = "c", r = "Requires defeating many corrupted pets with specific Humanoid type.", d = "Collect Humanoid-type pets to start this quest line. Fight the specified corrupted Argus pets using only your Humanoid pets. It is account-wide and requires no group, allowing for solo play once you have the correct pets.", x = 6 },
        [12097] = { e = 3, s = "c", r = "Grind many pets; no single hard criteria.", d = "Acquire Magic-type pets to begin this task. Defeat the required corrupted Argus pets using only your Magic pets. This is account-wide and can be done solo after gathering the necessary pet types.", x = 6 },
        [12098] = { e = 3, s = "c", r = "Grind many pets; no single hard criteria.", d = "Get Mechanical-type pets ready for this challenge. Battle the listed corrupted Argus pets using exclusively your Mechanical pets. It is account-wide and requires no group, making it suitable for solo completion once prepared.", x = 6 },
        [12099] = { e = 3, s = "c", r = "Grind many pets; no single hard criteria.", d = "Collect Undead-type pets to start this achievement. Fight the specified corrupted Argus pets using only your Undead pets. It is account-wide and does not require a group, so you can complete it alone after collecting the pets.", x = 6 },
        [12100] = { e = 4, s = "c", r = "Requires completing three major pet grind achievements.", d = "Complete all nine previous pet type achievements listed in the info field to unlock this one. You must finish each sub-achievement first; there is no time gate or group requirement for the final reward.", x = 6 },
        [12101] = { e = 3, s = "g", r = "Kill 100 demons; steady progress reduces time.", d = "Start by killing Greater Demons in Krokuun, Eredath, and Antoran Wastes until you reach 100. This is account-wide and requires no group, but note that the next achievement in the chain depends on finishing this one first.", x = 6 },
        [12102] = { e = 4, s = "g", r = "Kill 500 demons; requires significant time investment.", d = "First complete the previous demon killing achievement to unlock this one. Continue slaying Greater Demons in the same zones until you reach 500 total. It is account-wide and requires no group, but ensure you finish the prior step.", x = 6 },
        [12103] = { e = 5, s = "g", r = "Kill 2000 demons; long grind with RNG elements.", d = "Farm Greater Demons in Argus zones until you hit the 1000 kill count required to unlock this quest. This is account-wide and time-gated by the expansion, so start immediately upon entering Legion content.", x = 6 },
        [12104] = { e = 5, s = "g", r = "Kill 5000 demons; very long grind or rare drops.", d = "Continue farming Greater Demons on Argus after completing the previous step to reach the 5000 total needed for the title. Since this is account-wide, coordinate with friends if you want to speed up the grind significantly.", x = 6 },
        [12108] = { e = 3, s = "s", r = "Reach Prestige 20; depends on PvP activity.", d = "Grind PvP matches in any rated arena or battleground to gain Prestige points toward Level 20. This achievement is time-gated by the expansion's end and requires active participation in competitive modes.", x = 6 },
        [12109] = { e = 3, s = "s", r = "Reach Prestige 21; depends on PvP activity.", d = "Keep winning rated PvP matches after reaching Prestige Level 20 to unlock Level 21. Be aware that this content expires with the expansion, making it a priority before Legion concludes.", x = 6 },
        [12129] = { e = 4, s = "s", r = "Raid boss fight with specific mechanic constraint.", d = "Defeat Antorus boss mechanics while intentionally placing only three or fewer Felshield Emitters during the fight. Coordinate with your raid group to manage emitter placement carefully to avoid triggering extra adds.", x = 6 },
        [12136] = { e = 4, s = "g", r = "Win 100 arena or 40 rated BGs; steady grind.", d = "Win 100 Arena matches or 40 Rated Battlegrounds specifically in Legion Season 6 to earn the mount reward. This is time-gated by the season, so prioritize it before the season ends.", x = 6 },
        [12137] = { e = 4, s = "g", r = "Winning 100 arena matches is a long grind.", d = "Same as the previous achievement but tracks separately for different game modes; ensure you are playing in Legion Season 6 rated content. Combine efforts with teammates to reach the win count faster before the season expires.", x = 6 },
        [12180] = { e = 5, s = "g", r = "Reaching Prestige 22 requires massive time investment.", d = "Grind more PvP matches after reaching Prestige Level 21 to unlock Level 22. This is part of a chain that expires with the expansion, so maintain consistent participation in rated modes.", x = 6 },
        [12181] = { e = 5, s = "g", r = "Continuing prestige grind is extremely time-consuming.", d = "Continue winning rated PvP matches to progress from Prestige Level 22 to 23. The entire prestige system is time-gated, so do not delay this grind once you start the chain.", x = 6 },
        [12182] = { e = 5, s = "g", r = "Reaching Prestige 24 is a very long grind.", d = "Reach Prestige Level 24 by continuing to win rated PvP matches after unlocking Level 23. This step is part of a sequential chain that must be completed before Legion ends.", x = 6 },
        [12183] = { e = 5, s = "g", r = "Reaching Prestige 25 is an extreme time sink.", d = "Unlock Prestige Level 25 by reaching Level 24 and winning more rated matches. This final prestige milestone is time-gated and requires sustained effort in competitive PvP modes.", x = 6 },
        [12199] = { e = 4, s = "g", r = "Winning 100 arena matches in Season 7 is a grind.", d = "Win 100 Arena or 40 Rated Battlegrounds in Legion Season 7 to earn the mount reward. Like other seasonal achievements, this expires when the season ends, so prioritize it early.", x = 6 },
        [12200] = { e = 4, s = "g", r = "Winning 100 arena matches in Season 7 is a grind.", d = "Focus on winning 100 Arena matches or 40 Rated BGs specifically during Legion Season 7 to unlock the mount. Do not start this now as it is time-gated and will expire once the season ends.", x = 6 },
        [12242] = { e = 3, s = "c", r = "Requires unlocking race and completing heritage quests.", d = "Complete the Void Elf reputation chain first, then finish the Heritage questline to permanently unlock the race for your account.", x = 6 },
        [12243] = { e = 3, s = "c", r = "Requires unlocking race and completing heritage quests.", d = "Finish the Lightforged Draenei reputation and Heritage quests immediately to secure this allied race before any future content changes.", x = 6 },
        [12244] = { e = 3, s = "c", r = "Requires unlocking race and completing heritage quests.", d = "Complete the Nightborne reputation chain followed by their Heritage questline to unlock the race for your entire account.", x = 6 },
        [12245] = { e = 3, s = "c", r = "Requires unlocking race and completing heritage quests.", d = "Earn Highmountain Tauren allegiance and complete their Heritage questline as soon as possible to unlock the race permanently.", x = 6 },
        [12257] = { e = 4, s = "s", r = "Requires specific raid conditions and quick collection.", d = "Run Antorus Normal or higher with a full team, collecting 20 Motes of Titanic Power within 5 seconds before killing Argus.", x = 6 },
        [12270] = { e = 4, s = "c", h = { 62877, 62880, 62881 }, r = "Requires Mythic dungeon clears with specific debuff mechanics.", d = "Clear Atal'Dazar Mythic ensuring at least one party member is affected by Unstable Hex when defeating all four bosses.", x = 7 },
        [12272] = { e = 3, s = "c", r = "Requires defeating a specific boss on Mythic difficulty.", d = "Defeat the Fatal Corruption mechanic on Priestess Alun'za before killing her to complete this specific dungeon achievement.", x = 7 },
        [12273] = { e = 4, s = "c", r = "Requires lighting all sconces and defeating a specific boss.", d = "Light all four Shadowflame Sconces in Atal'Dazar Mythic and then defeat Yazma while they remain lit.", x = 7 },
        [12279] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Queue for PvP pet battles using a full team of level 25 Mechanical pets to win ten matches via Find Battle.", x = 6 },
        [12280] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Use a full team of level 25 Aquatic pets to win ten PvP pet battles through the Find Battle system.", x = 6 },
        [12281] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Field a complete team of level 25 Beast pets and win ten PvP pet battles using the Find Battle mechanic.", x = 6 },
        [12282] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Use the Elemental Brawler pet to queue for PvP battles. Win ten matches while keeping your team at level 25. This is account-wide and requires no specific group.", x = 6 },
        [12283] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Equip the Magic Brawler pet and queue for PvP encounters. Defeat ten opponents using a full team of level 25 Magic pets. Progress carries over across all your characters.", x = 6 },
        [12284] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Select the Critter Brawler pet to start finding battles. Win ten rounds with a complete team of level 25 Critters. No group is needed for this account-wide task.", x = 6 },
        [12285] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Use the Undead Brawler pet to queue for PvP fights. Secure ten victories with a full squad of level 25 Undead pets. This achievement tracks globally on your account.", x = 6 },
        [12286] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Choose the Flying Brawler pet and enter Find Battle mode. Win ten matches using only level 25 Flying pets. Progress is shared across all characters on your account.", x = 6 },
        [12287] = { e = 3, s = "g", r = "Grinding 10 PvP battles with a specific team type.", d = "Equip the Dragonkin Brawler pet to queue for PvP battles. Defeat ten enemies with a full team of level 25 Dragonkin pets. This is an account-wide achievement requiring no group.", x = 6 },
        [12289] = { e = 3, s = "g", r = "Requires finding specific PvP battles and winning 10 times.", d = "Use the Humanoid Brawler pet to find and win PvP battles. You must win ten matches with a full team of level 25 Humanoids. Progress is tracked account-wide without needing a group.", x = 6 },
        [12290] = { e = 4, s = "c", h = { 63658 }, r = "Requires completing all sub-achievements; Humanoid is hardest.", d = "Complete all nine individual Brawler achievements listed in the info field first. Once finished, this Family Brawler achievement unlocks automatically. It rewards a tabard and is account-wide.", x = 6 },
        [12291] = { e = 4, s = "s", r = "Requires creating a new character and leveling to 50.", d = "Create a new Void Elf character and level it to 50. This unlocks the Heritage Armor reward which applies account-wide. Ensure you have access to the Allied Races feature first.", x = 6 },
        [12292] = { e = 3, s = "g", r = "Requires farming reputation with Highmountain Tribe to Exalted.", d = "Travel to Highmountain and complete reputation quests for the Tauren tribe. Reach Exalted status to finish this Legion-era achievement. No group is required for this account-wide goal.", x = 6 },
        [12297] = { e = 4, s = "c", h = { 64355 }, r = "Requires defeating multiple raid bosses; Flame Leviathan is hardest.", d = "Enter Ulduar and defeat all bosses located in the Siege area. This includes Flame Leviathan, Razorscale, Ignis, and XT-002. The achievement is account-wide but requires raiding content.", x = 2 },
        [12302] = { e = 4, s = "c", h = { 64391 }, r = "Requires defeating multiple raid bosses; Kologarn is hardest.", d = "Enter Ulduar and defeat all bosses in the Antechamber area. You must kill Assembly of Iron, Kologarn, and Auriaya. This is an account-wide achievement requiring raid participation.", x = 2 },
        [12309] = { e = 4, s = "c", h = { 64412 }, r = "Requires defeating multiple raid bosses; Mimiron is hardest.", d = "Queue for Ulduar and defeat Hodir, Thorim, Freya, and Mimiron. This is account-wide, so any character can complete it.", x = 2 },
        [12310] = { e = 5, s = "c", h = { 64422 }, r = "Requires defeating multiple raid bosses; Yogg-Saron is hardest.", d = "Defeat General Vezax and Yogg-Saron in the Descent into Madness area. Ensure you clear these specific bosses to earn the points.", x = 2 },
        [12311] = { e = 5, s = "c", r = "Requires defeating every boss including Yogg-Saron.", d = "Complete all other Ulduar achievements first, then defeat every remaining boss including The Siege and Antechamber. This is the final step for full raid completion.", x = 2 },
        [12312] = { e = 3, s = "g", r = "Requires destroying 100 defenders quickly in a specific area.", d = "Stand in the Iron Concourse and destroy 100 Steelforged Defenders within 10 seconds. Use high-damage abilities to clear them quickly before time runs out.", x = 2 },
        [12313] = { e = 4, s = "s", r = "Requires defeating Flame Leviathan on first try without repairs.", d = "Defeat Flame Leviathan on your first attempt without anyone repairing their vehicle. Do not use repair kits or wait for repairs during the fight.", x = 2 },
        [12314] = { e = 5, s = "c", h = { 64458 }, r = "Requires defeating Flame Leviathan with all three vehicles; Demolisher is hardest.", d = "Defeat Flame Leviathan while riding the Chopper, Siege Engine, and Demolisher. You must complete this with each specific vehicle to earn the points.", x = 2 },
        [12315] = { e = 4, s = "s", r = "Requires specific raid mechanics and coordination.", d = "Destroy a Defense Turret during the Flame Leviathan fight. Any turret will suffice, so focus fire on one until it is destroyed.", x = 2 },
        [12316] = { e = 4, s = "s", r = "High difficulty boss fight with strict condition.", d = "Defeat Flame Leviathan without causing a System Shutdown. Avoid triggering the shutdown mechanic by managing adds and mechanics carefully throughout the encounter.", x = 2 },
        [12317] = { e = 4, s = "c", r = "Requires previous achievement; RNG on turret activation.", d = "Defeat Flame Leviathan with at least one Orbital Defense System active. Activate an orbital system before starting the fight to secure this achievement.", x = 2 },
        [12318] = { e = 4, s = "c", r = "Requires previous achievement; RNG on turret activation.", d = "Complete the previous orbital achievement and defeat Flame Leviathan with two systems active. Ensure both systems remain active during the entire encounter.", x = 2 },
        [12319] = { e = 4, s = "c", r = "Requires previous achievement; RNG on turret activation.", d = "Finish the prior step and defeat Flame Leviathan with three orbital systems active. Keep all three systems powered up while fighting the boss.", x = 2 },
        [12320] = { e = 4, s = "c", r = "Requires previous achievement; RNG on turret activation.", d = "Complete the chain by defeating Flame Leviathan with all four orbital systems active. This requires careful coordination to keep every system online during the fight.", x = 2 },
        [12321] = { e = 4, s = "s", r = "Difficult boss fight requiring precise timing.", d = "Pull Razorscale and kill her immediately to prevent her from flying up, which triggers the achievement. Ensure your group focuses damage on her before she can take flight.", x = 2 },
        [12322] = { e = 4, s = "g", r = "Requires killing 25 specific mobs in raid.", d = "This is account-wide and requires you to die to Dark Rune Guardian Dwarves while Razorscale uses Flame Breath. Pull groups of dwarves and let them wipe repeatedly until you reach 25 kills.", x = 2 },
        [12323] = { e = 4, s = "s", r = "Difficult boss fight requiring precise timing.", d = "Defeat Ignis after shattering two Iron Constructs within five seconds by using your class ability or a trinket to break the constructs quickly. Time your damage so Ignis dies right after the second construct breaks.", x = 2 },
        [12324] = { e = 4, s = "s", r = "Requires surviving a specific mechanic in raid.", d = "Survive being thrown into Ignis's Slag Pot during the fight, which usually happens when you fail to dodge his slam attack. Stay alive long enough for the throw to occur and not die upon impact.", x = 2 },
        [12325] = { e = 4, s = "s", r = "Difficult boss fight requiring precise timing.", d = "Defeat Ignis in under four minutes by using high-damage cooldowns early and maintaining consistent pressure on him. Avoid unnecessary pulls or mechanics that waste time during the encounter.", x = 2 },
        [12326] = { e = 4, s = "s", r = "Difficult boss fight requiring precise mechanics.", d = "Keep XT-002 Deconstructor at low health to prevent him from healing via XS-013 Scrapbots. Focus damage on the main boss while ignoring scrapbot spawns until he is near death.", x = 2 },
        [12327] = { e = 4, s = "s", r = "High-skill raid fight requiring precise timing and coordination.", d = "Use XE-321 Boombots to kill 20 XS-013 Scrapbots within twelve seconds while XT-002 Deconstructor is alive. Position boombots near scrapbots and use them as soon as they spawn.", x = 2 },
        [12328] = { e = 4, s = "s", r = "Requires avoiding specific mechanic damage during a hard raid boss.", d = "Defeat XT-002 Deconstructor without any raid member dying from a Gravity Bomb. Spread out during the gravity bomb phase and ensure everyone survives the explosion.", x = 2 },
        [12329] = { e = 4, s = "s", r = "Speed kill on a difficult raid boss requires high skill.", d = "Defeat XT-002 Deconstructor in under 205 seconds by using efficient damage rotation and minimizing downtime between phases. Coordinate with your group to maximize DPS output throughout the fight.", x = 2 },
        [12330] = { e = 4, s = "s", r = "Requires executing specific mechanics correctly during a hard fight.", d = "Destroy XT-002 Deconstructor's heart before defeating him to trigger this achievement. Use a class ability or trinket to break his heart early in the encounter.", x = 2 },
        [12332] = { e = 4, s = "s", r = "Hard raid boss requiring specific tanking and group coordination.", d = "Defeat the Assembly of Iron with Runemaster Molgeim as the last member alive by protecting him from damage and focusing fire on other members. Keep Molgeim healed and avoid unnecessary aggro.", x = 2 },
        [12333] = { e = 4, s = "s", r = "Hard raid boss requiring specific tanking and group coordination.", d = "Defeat the Assembly of Iron with Stormcaller Brundir as the last member alive by keeping her safe while eliminating others. Use defensive cooldowns and healing to ensure she survives until the end.", x = 2 },
        [12334] = { e = 4, s = "s", r = "Hard raid boss requiring specific tanking and group coordination.", d = "Use Steelbreaker as your tank to absorb damage while the rest of the raid focuses on killing the boss. Ensure no other tanks pull aggro away from him until the fight ends.", x = 2 },
        [12335] = { e = 4, s = "s", r = "Hard raid boss requiring specific item usage and mechanics.", d = "Consume an Iron Boot Flask before entering the encounter and maintain its effect throughout the entire fight. Coordinate with your healer to manage any extra damage from the flask's debuff.", x = 2 },
        [12336] = { e = 4, s = "s", r = "Hard raid boss requiring precise control of a dangerous mechanic.", d = "Assign a dedicated player to monitor Stormcaller Brundir and interrupt his casting immediately if he begins Chain Lightning or Lightning Whirl. Position your raid members carefully to avoid standing in his area of effect.", x = 2 },
        [12337] = { e = 4, s = "s", r = "Hard raid boss requiring specific mechanics and high skill.", d = "Focus all damage on Kologarn's body while ignoring his arms entirely until the fight concludes. Use crowd control abilities to prevent players from accidentally hitting the limbs.", x = 2 },
        [12338] = { e = 4, s = "s", r = "Hard raid boss requiring precise timing on complex mechanics.", d = "This achievement requires destroying both arms and then killing Kologarn within 12 seconds, so plan your damage rotation carefully. Ensure your DPS is high enough to finish the boss quickly after breaking his defenses.", x = 2 },
        [12339] = { e = 4, s = "s", r = "Hard raid boss requiring avoidance of specific area-of-effect damage.", d = "Avoid standing in the line of fire when Kologarn uses Focused Eyebeams by spreading out or using movement abilities. Communicate with your raid leader to coordinate positioning during this mechanic.", x = 2 },
        [12340] = { e = 3, s = "g", r = "Requires spawning and killing 25 Rubbles before boss.", d = "Interact with rubble piles around the arena to spawn creatures, aiming for at least 25 before defeating Kologarn. Keep an eye on the counter if possible and prioritize spawning over killing adds.", x = 2 },
        [12341] = { e = 4, s = "c", r = "High skill ceiling to avoid destroying sentries.", d = "Protect Auriaya's Sanctum Sentries by avoiding area-of-effect damage that targets them directly. Use single-target spells and be cautious of mechanics that could accidentally hit these allies.", x = 2 },
        [12342] = { e = 3, s = "s", r = "Requires defeating a specific add before boss.", d = "Defeat the Feral Defender first before engaging Auriaya, as this is a prerequisite for the achievement. Coordinate with your group to ensure both bosses are handled in the correct order.", x = 2 },
        [12343] = { e = 4, s = "c", r = "Strict mechanic requires flawless raid execution.", d = "Monitor Flash Freeze casts and use defensive cooldowns or movement abilities to avoid being hit by them. Communicate with your healer to manage any damage taken from this mechanic.", x = 2 },
        [12344] = { e = 4, s = "c", r = "Requires protecting NPCs from a lethal mechanic.", d = "Protect friendly NPCs during the fight by avoiding area-of-effect damage that could cause them to perish. Use crowd control abilities to prevent players from accidentally hitting these allies.", x = 2 },
        [12345] = { e = 4, s = "c", r = "Strict stacking limit requires precise raid control.", d = "Manage Biting Cold stacks carefully by using defensive cooldowns and movement abilities to avoid gaining more than 2 stacks. Coordinate with your healer to manage any extra damage from this mechanic.", x = 2 },
        [12346] = { e = 3, s = "s", r = "Requires holding three specific buffs simultaneously.", d = "Stack Toasty Fire, Storm Power, and Starlight buffs before engaging Hodir. Ensure all three remain active throughout the entire fight to secure this achievement.", x = 2 },
        [12347] = { e = 3, s = "g", r = "Race against a timer with RNG element.", d = "Defeat Hodir quickly before his Rare Cache shatters. This is a time-gated objective, so focus on damage output immediately upon entering the arena.", x = 2 },
        [12348] = { e = 4, s = "c", r = "Strict mechanic requires flawless raid execution.", d = "Run Ulduar with Thorim in mind and ensure your raid group uses Lightning Charge sparingly or avoids it entirely. Coordinate with healers to prevent any member from being struck by the ability during the fight.", x = 2 },
        [12349] = { e = 3, s = "s", r = "Requires killing specific adds during the fight.", d = "Participate in defeating both the Ancient Rune Giant and the Runic Colossus alongside Thorim in Ulduar. You must deal damage to all three targets to complete this specific raid achievement.", x = 2 },
        [12350] = { e = 3, s = "s", r = "Requires maintaining a specific buff during fight.", d = "Apply Aura of Celerity to your raid leader or self before starting Thorim. Maintain this buff until the boss dies to complete the requirement.", x = 2 },
        [12351] = { e = 4, s = "c", r = "Timing mechanic requires precise boss management.", d = "Force Thorim into the arena while Sif is still present by using specific mechanics. Do not let Sif leave before pulling the boss in.", x = 2 },
        [12352] = { e = 4, s = "c", h = { 64679 }, r = "Requires specific raid mechanics and Sif presence.", d = "Complete the 'Siffed' achievement first to unlock this one. Defeat Thorim with Sif present for a double completion.", x = 2 },
        [12360] = { e = 4, s = "c", r = "Requires precise timing on three separate boss kills.", d = "Kill Elder Brightleaf, Ironbranch, and Stonebark in rapid succession within 15 seconds. Coordinate your group to minimize downtime between kills.", x = 2 },
        [12361] = { e = 4, s = "c", r = "Requires speedrun mechanics within a tight time limit.", d = "Start the Conservatory of Life fight immediately and defeat Freya within 20 minutes. This is a strict time limit starting from the first kill.", x = 2 },
        [12362] = { e = 4, s = "c", r = "Requires killing specific mobs quickly during Freya fight.", d = "Defeat two of each mob type (Ancient Water Spirits, Storm Lashers, Snaplashers) in under 10 seconds. Use high-damage abilities to clear them instantly.", x = 2 },
        [12363] = { e = 4, s = "c", r = "Requires maintaining a specific buff stack on boss.", d = "Apply Attuned to Nature stacks to Freya before killing her. Ensure she has at least 25 stacks active when the fight ends.", x = 2 },
        [12364] = { e = 4, s = "c", r = "Requires precise positioning to leave an Elder alive.", d = "Leave at least one Elder alive while defeating Freya. Manage your damage carefully to avoid wiping out all Elders prematurely.", x = 2 },
        [12365] = { e = 4, s = "c", r = "Requires higher difficulty version of previous achievement.", d = "Start by killing Freya while intentionally letting two Elders survive to trigger the achievement. Ensure you do not kill all three, as this unlocks the next tier requiring all three alive.", x = 2 },
        [12366] = { e = 4, s = "c", r = "Requires highest difficulty version of Elder survival.", d = "After completing the previous tier, focus on keeping all three Elders alive during the fight with Freya. This requires careful positioning and healing to avoid accidental deaths.", x = 2 },
        [12367] = { e = 4, s = "c", h = { 64719, 64723, 64727 }, r = "Requires avoiding three specific raid-wide damage abilities.", d = "Defeat Mimiron without taking damage from Proximity Mines, Rocket Strikes, or Bomb Bots. Coordinate with your raid to avoid these specific mechanics throughout the entire encounter.", x = 2 },
        [12368] = { e = 4, s = "c", r = "Requires manipulating Mimiron's mechanics to kill a bot.", d = "Force Mimiron to use a Rocket Strike on an Assault Bot by positioning correctly during the fight. This mechanic often requires precise timing and awareness of Mimiron's abilities.", x = 2 },
        [12369] = { e = 4, s = "c", r = "Requires activating Self-Destruct and surviving the explosion.", d = "Activate Mimiron's Self-Destruct mechanism before defeating him to earn this achievement. Ensure the raid is ready for the final phase after the bomb is triggered.", x = 2 },
        [12372] = { e = 4, s = "c", r = "Requires avoiding a specific raid-wide ability from Vezax.", d = "Defeat General Vezax without any raid member taking damage from Shadow Crash. Use stealth or positioning strategies to avoid being hit by this specific mechanic.", x = 2 },
        [12373] = { e = 5, s = "c", r = "Requires defeating a raid boss after another specific encounter.", d = "Complete the fight with the Saronite Animus before engaging General Vezax. Ensure the Animus is defeated first, as this is a prerequisite for the main boss encounter.", x = 2 },
        [12384] = { e = 5, s = "s", r = "Requires precise timing and mechanics during a raid fight.", d = "Use the /Kiss Sara command while she is in an angry state to trigger the achievement. Monitor her dialogue or status effects to determine when she is angry.", x = 2 },
        [12385] = { e = 5, s = "c", r = "Harder than standard; requires managing fewer Keepers.", d = "Defeat Yogg-Saron with three or fewer Keepers assisting you. This may require managing Keeper spawns or using specific mechanics to limit their involvement.", x = 2 },
        [12386] = { e = 5, s = "c", r = "Harder than standard; requires managing even fewer Keepers.", d = "After completing the previous tier, defeat Yogg-Saron with two or fewer Keepers. Carefully manage the number of Keepers present during the encounter to meet this requirement.", x = 2 },
        [12387] = { e = 5, s = "c", r = "Harder than standard; requires managing only one Keeper.", d = "Progress from the last tier by defeating Yogg-Saron with one or fewer Keepers. This requires precise control over Keeper spawns and their participation in the fight.", x = 2 },
        [12388] = { e = 5, s = "c", r = "Hardest Yogg-Saron achievement; requires soloing the raid boss.", d = "Complete the final tier by defeating Yogg-Saron without any Keepers assisting. Ensure no Keepers are present during the entire encounter to secure this achievement.", x = 2 },
        [12395] = { e = 5, s = "s", r = "Requires managing a specific debuff mechanic during a raid fight.", d = "Defeat Yogg-Saron without anyone going insane by managing the insanity mechanic carefully. Coordinate with your raid to avoid stacking insanity debuffs on any single player. This is a high-difficulty achievement requiring precise timing and communication.", x = 2 },
        [12396] = { e = 5, s = "s", r = "Requires extreme speed and coordination to defeat the boss quickly.", d = "Focus on speed kills to defeat Yogg-Saron within seven minutes. Prioritize damage output and efficient mechanics to clear the encounter quickly. Do not linger on non-essential phases or unnecessary adds during the fight.", x = 2 },
        [12397] = { e = 5, s = "c", r = "Requires rapid kills of multiple adds within a strict time limit.", d = "Rescue Sara while rushing to kill nine Guardians of Yogg-Saron in twelve seconds. This requires extreme speed and coordination as soon as Sara is freed. Any delay will cause you to miss this time-gated objective permanently.", x = 2 },
        [12398] = { e = 5, s = "c", r = "Requires completing three separate complex raid encounters.", d = "Experience all three visions of Yogg-Saron's mind by completing specific story quests. These are account-wide achievements, so ensure your character has access to the necessary content. Plan your raid runs to include these vision encounters systematically.", x = 2 },
        [12399] = { e = 5, s = "s", r = "Requires defeating a high-level raid boss with specific mechanics.", d = "Defeat Algalon the Observer in Ulduar to earn this achievement and its associated titles. Ensure you have a full group ready for this high-level encounter. This is a standard raid boss fight with no special time gates mentioned.", x = 2 },
        [12400] = { e = 5, s = "c", r = "Requires defeating a raid boss after completing a difficult mechanic.", d = "Close three Black Holes within ten seconds before defeating Algalon the Observer. Coordinate your team to close portals quickly during the fight. Missing this window will prevent you from earning the achievement regardless of the kill.", x = 2 },
        [12401] = { e = 5, s = "c", h = { 64806, 64807, 64808 }, r = "Requires full Ulduar raid clears and rare drops.", d = "Complete all listed Ulduar raid achievements to earn the Glory of the Ulduar Raider title. Start with easier dungeon and raid goals first, then tackle complex boss mechanics. This is a collection-based goal requiring multiple successful runs across different encounters.", x = 6 },
        [12404] = { e = 3, s = "s", r = "Time-sensitive PvP objective requiring quick action.", d = "Land on Seething Shore and collect an Azerite deposit within thirty seconds. Move quickly to the nearest resource node immediately upon spawning. Failure to act fast enough will result in missing this time-sensitive objective.", x = 6 },
        [12405] = { e = 3, s = "s", r = "Time-sensitive PvP kill requirement.", d = "Slay an enemy within thirty seconds of landing on Seething Shore. Engage nearby mobs instantly after arriving at the zone. This is a quick action that should be completed before looting or exploring further.", x = 6 },
        [12406] = { e = 3, s = "g", r = "Requires collecting large amount of Azerite.", d = "Collect twenty-five thousand Azerite in Seething Shore to complete this achievement. Note that the actual requirement may be higher based on current game data. Farm Azerite efficiently by revisiting resource nodes repeatedly until the goal is met.", x = 6 },
        [12407] = { e = 4, s = "s", r = "High-score requirement in competitive PvP match.", d = "Win Seething Shore with a score between fifteen hundred and zero for perfect victory. Focus on capturing resources while minimizing damage taken from enemies. Avoid unnecessary risks that could lower your final score below the required range.", x = 6 },
        [12408] = { e = 3, s = "c", h = { 65182, 65183, 65186 }, r = "Must capture Azerite at multiple specific locations.", d = "Capture Azerite at every location listed in Seething Shore to achieve domination. Visit each zone systematically ensuring you secure resources before moving on. Missing even one location will prevent completion of this comprehensive collection goal.", x = 6 },
        [12409] = { e = 3, s = "s", r = "Standard PvP victory condition.", d = "Queue for Seething Shore and win a match to claim this title. It is a PvP achievement that requires no specific group composition beyond finding a queue.", x = 6 },
        [12410] = { e = 3, s = "g", r = "Requires accumulating 100 PvP victories.", d = "Play hundreds of matches in Seething Shore until you reach 100 victories. This is account-wide and time-gated by the game mode's availability.", x = 6 },
        [12411] = { e = 3, s = "g", r = "Requires killing 50 enemies near Azerite deposits.", d = "Farm Azerite deposits while killing enemies to reach the count of 50. This is account-wide, so progress carries over between characters.", x = 6 },
        [12412] = { e = 5, s = "c", h = { 65199, 65200, 65201 }, r = "Requires completing all other Seething Shore achievements.", d = "Complete every other Seething Shore achievement listed in the info field before claiming this master title. Ensure you have all sub-requirements first.", x = 6 },
        [12413] = { e = 1, s = "s", r = "Automatic upon reaching level 50 on new character.", d = "Create a new Nightborne character and level it to 50 to unlock the heritage armor. This is account-wide once the race is unlocked.", x = 6 },
        [12414] = { e = 1, s = "s", r = "Automatic upon reaching level 50 on new character.", d = "Create a new Lightforged Draenei character and level it to 50 to unlock the heritage armor. This is account-wide once the race is unlocked.", x = 6 },
        [12415] = { e = 3, s = "s", r = "Requires creating a new character and leveling to 50.", d = "Create a new Highmountain Tauren character and level it to 50 to unlock the heritage armor. This is account-wide once the race is unlocked.", x = 6 },
        [12416] = { e = 1, s = "s", r = "Talk to an NPC in Dalaran.", d = "Travel to Dalaran and speak with the Postmaster to complete this Legion questline. Ensure you have access to the Legion expansion content.", x = 6 },
        [12429] = { e = 3, s = "c", h = { 65043 }, r = "Multiple quests; Wardens of the Wetlands is hardest.", d = "Complete all listed Wetlands storylines for Alliance characters. This is account-wide, so finish these on any eligible character.", x = 0 },
        [12430] = { e = 3, s = "c", h = { 65053 }, r = "Multiple quests; Citizens of Darkshire is hardest.", d = "Complete all listed Duskwood storylines for Alliance characters. This is account-wide, so finish these on any eligible character.", x = 0 },
        [12431] = { e = 2, s = "s", r = "Sort mail quickly in a timed mini-game.", d = "Sort 30 letters in the Postmaster's Office within 60 seconds to get the Mailemental pet. Practice speed sorting before attempting this timed challenge.", x = 6 },
        [12439] = { e = 2, s = "s", r = "Sort mail quickly in a timed mini-game.", d = "Sort 30 partially addressed letters in the Mythic difficulty version of the Postmaster's Office within 60 seconds. This is harder and requires faster reaction times.", x = 6 },
        [12457] = { e = 4, s = "s", r = "High Mythic difficulty dungeon with strict mechanics.", d = "Queue Mythic Tol Dagor and focus on dodging Munitions to avoid detonation. This is a high-skill fight requiring precise positioning, so practice in lower difficulties first before attempting the full achievement.", x = 7 },
        [12462] = { e = 4, s = "s", r = "High Mythic difficulty dungeon with strict mechanics.", d = "Coordinate with your group to ensure everyone gets stunned by Heartstopper Venom simultaneously before engaging Overseer Korgus. Communication is key here; use voice chat or emotes to sync stun timers for the required condition.", x = 7 },
        [12473] = { e = 3, s = "c", h = { 66875 }, r = "Multiple quests; Castaways and Cutouts is hardest.", d = "Complete all Tiragarde Sound storylines listed in the info field, as this is an account-wide zone achievement. Start with The Ashvane Trading Company and work through each quest chain systematically without missing any sub-objectives.", x = 7 },
        [12478] = { e = 3, s = "c", h = { 65793 }, r = "Multiple quests; Storming the Spire is hardest.", d = "Finish every Vol'dun storyline mentioned, including Atul'Aman, which serves as the final step for this account-wide zone goal. Ensure you complete all prior quests like Unlikely Allies before tackling the endgame content.", x = 7 },
        [12479] = { e = 3, s = "c", h = { 65809 }, r = "Multiple zone achievements; The Final Seal is hardest.", d = "Unlock Zandalar Forever! by completing The Throne of Zuldazar and other listed achievements first. This is account-wide, so coordinate with friends if needed for rare drops or difficult scenarios like The Dark Heart of Nazmir.", x = 7 },
        [12480] = { e = 3, s = "s", r = "Complete a specific storyline in Zuldazar.", d = "Complete the Blood Gate storyline in Zuldazar to earn Sealed with Blood. Focus on the specific quests tied to this area and ensure no steps are skipped since it feeds into larger zone achievements.", x = 7 },
        [12481] = { e = 3, s = "s", r = "Requires specific scenario completion with high-level gear.", d = "Finish The Final Seal scenario in Zandalar, which is part of the main zone progression. This is account-wide, so make sure your character completes all prerequisite tasks before attempting the final seal event.", x = 7 },
        [12482] = { e = 3, s = "c", h = { 65812, 65817, 65822 }, r = "Collecting rare items from specific drustvar quests.", d = "Gather specific items like Golden Ravasaur Egg and Vilescale Pearl for Jani in Zandalar. These are account-wide tasks, so check your inventory regularly and prioritize rare drops while exploring the zone.", x = 7 },
        [12483] = { e = 3, s = "s", r = "Standard dungeon clear on normal difficulty.", d = "Defeat Gorak Tul in Waycrest Manor on Normal difficulty first to unlock Heroic. This is the base requirement before progressing to higher difficulties, so ensure you clear the dungeon without issues initially.", x = 7 },
        [12484] = { e = 4, s = "s", r = "Heroic dungeon requires better gear and coordination.", d = "Clear Waycrest Manor on Heroic or higher after defeating Gorak Tul normally. This step unlocks Mythic, so verify your group composition and gear level are sufficient for increased enemy health pools.", x = 7 },
        [12488] = { e = 5, s = "s", r = "Mythic difficulty demands high skill and group coordination.", d = "Attempt Mythic Waycrest Manor only after completing the Heroic version. This difficulty features tougher mechanics, so practice dodging key abilities before attempting the achievement to avoid unnecessary wipes.", x = 7 },
        [12489] = { e = 5, s = "c", h = { 65985, 65986, 65987 }, r = "Killing specific enemies on Mythic adds significant difficulty.", d = "Kill all listed enemies in Waycrest Manor and Siege of Boralus on Mythic difficulty for this account-wide hitman achievement. Track each target carefully as missing one will prevent completion until revisited later.", x = 7 },
        [12490] = { e = 5, s = "s", r = "Requires precise execution of a complex mechanic.", d = "First, destroy three Deathtouched Slavers with a single Alchemical Fire to unlock the prerequisite. Then, run Gorak Tul in Waycrest Manor on Mythic difficulty to complete it.", x = 7 },
        [12495] = { e = 5, s = "s", r = "High RNG element makes this very difficult to complete.", d = "Start by defeating the Soulbound Goliath without letting it reach 12 stacks of Soul Harvest. This requires careful management of its mechanics on Mythic Waycrest Manor.", x = 7 },
        [12496] = { e = 3, s = "c", h = { 66030, 66116, 66029 }, r = "Completing multiple storylines in a specific zone.", d = "Complete all listed Stormsong Valley storylines in any order, as this is an account-wide achievement. Ensure you finish every specific quest mentioned in the description.", x = 7 },
        [12497] = { e = 3, s = "c", h = { 66065, 66066, 66067 }, r = "Multiple quests needed to complete the storyline.", d = "Finish all Drustvar storylines listed to earn this account-wide achievement. There are no time gates, so complete them at your own pace.", x = 7 },
        [12498] = { e = 5, s = "s", r = "Requires avoiding taint while defeating a boss on Mythic.", d = "Defeat Elder Leaxa on Mythic Underrot while ensuring no party member takes the Taint of G'huun. Monitor debet effects closely during the fight.", x = 7 },
        [12499] = { e = 5, s = "s", r = "Avoiding rotting spores adds significant difficulty to the fight.", d = "Kill the Unbound Abomination on Mythic Underrot without letting any Rotting Spores die. Protect these adds carefully to avoid losing progress.", x = 7 },
        [12500] = { e = 3, s = "c", r = "Requires unlocking dungeon and defeating boss.", d = "Defeat the Unbound Abomination in Underrot on Normal difficulty first. This unlocks Heroic and is a prerequisite for higher difficulties.", x = 7 },
        [12501] = { e = 4, s = "c", r = "Heroic difficulty adds significant time/coordination.", d = "Complete Normal Underrot first, then run the dungeon on Heroic difficulty or higher. You must defeat the boss again to claim this achievement.", x = 7 },
        [12502] = { e = 5, s = "c", r = "Mythic requires high skill and coordination.", d = "Finish Heroic Underrot before attempting Mythic. Defeat the Unbound Abomination on Mythic difficulty to complete the final step in the chain.", x = 7 },
        [12504] = { e = 3, s = "c", r = "Requires unlocking dungeon and defeating boss.", d = "Restore the Avatar of Sethraliss in Normal Temple of Sethraliss first. This unlocks Heroic and is required before tackling higher difficulties.", x = 7 },
        [12505] = { e = 4, s = "c", r = "Heroic difficulty adds significant time/coordination.", d = "Complete Normal Temple of Sethraliss, then run it on Heroic difficulty or higher. You must restore the avatar again to earn this achievement.", x = 7 },
        [12506] = { e = 5, s = "c", r = "Mythic requires high skill and coordination.", d = "Finish Normal and Heroic Temple of Sethraliss before attempting Mythic. Defeat the boss on Mythic difficulty to complete the final step in the chain.", x = 7 },
        [12509] = { e = 4, s = "c", r = "Requires completing multiple major zone quests.", d = "Complete all Zandalar and Kul Tiras war campaign quests to unlock this account-wide achievement. Ensure you finish the specific foothold and assault objectives listed in the info field before moving on.", x = 7 },
        [12510] = { e = 4, s = "c", r = "Requires completing multiple major zone quests.", d = "Finish every quest in the Kul Tiras and Zandalar campaigns for your faction. This is account-wide, so coordinate with friends if you are playing across different accounts.", x = 7 },
        [12515] = { e = 3, s = "c", r = "Requires reputation grind and unlocking race.", d = "Unlock the Dark Iron Dwarf allied race first, then complete their reputation chain to earn allegiance. Note that this unlocks the next heritage achievement in the sequence.", x = 7 },
        [12518] = { e = 3, s = "c", r = "Requires reputation grind and unlocking race.", d = "Unlock the Mag'har Orc allied race and grind their reputation to gain allegiance. This is a prerequisite for unlocking the subsequent Heritage of the Mag'har content.", x = 7 },
        [12521] = { e = 4, s = "c", r = "Requires clearing multiple raid bosses.", d = "Clear all bosses in Uldir's first section on any difficulty to unlock this wing achievement. You must defeat Taloc, MOTHER, and Zek'voz specifically as listed.", x = 7 },
        [12522] = { e = 4, s = "c", r = "Requires clearing multiple raid bosses.", d = "Defeat the remaining bosses in Uldir's second section, including Vectis, Fetid Devourer, and Zul. Complete these after finishing the first wing requirements.", x = 7 },
        [12523] = { e = 4, s = "c", h = { 66233, 66234 }, r = "Requires defeating multiple Uldir Mythic bosses.", d = "Finish the final Uldir section by defeating Mythrax and G'huun to extinguish the corruption. This completes the standard progression through all three wings of the raid.", x = 7 },
        [12524] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Run Taloc on Mythic difficulty specifically; lower difficulties will not count. Ensure you have access to Mythic Uldir before attempting this boss.", x = 7 },
        [12526] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Defeat MOTHER on Mythic difficulty only. This requires clearing the previous wings and having a group capable of handling Mythic mechanics.", x = 7 },
        [12527] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Clear Zek'voz on Mythic difficulty after unlocking the Mythic Archives achievement. Make sure you have completed the prior wing requirements first.", x = 7 },
        [12529] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Defeat Vectis on Mythic difficulty to unlock this specific boss achievement. You must clear the earlier Uldir wings before attempting this encounter.", x = 7 },
        [12530] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Kill Fetid Devourer on Mythic difficulty after completing the first two wings of Uldir. This is part of the standard Mythic progression path.", x = 7 },
        [12531] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Defeat Zul in Uldir on Mythic difficulty to complete this raid achievement. Ensure you have the prerequisite 'Achievement - Zul' before starting.", x = 7 },
        [12532] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Clear Mythrax the Unraveler in Uldir on Mythic difficulty for this raid title. No special prerequisites are listed beyond entering the raid.", x = 7 },
        [12533] = { e = 4, s = "s", r = "Single boss kill on high difficulty.", d = "Defeat G'huun in Uldir on Mythic difficulty to earn both the achievement and the 'The Purifier' title. This is a core raid boss requirement.", x = 7 },
        [12544] = { e = 1, s = "s", r = "Legacy level requirement is trivial now.", d = "This legacy achievement tracks if you reached level 120 before Shadowlands launched. It cannot be earned now as it requires pre-expansion leveling.", x = 7 },
        [12546] = { e = 3, s = "c", r = "Requires equipping high ilvl gear in all slots.", d = "Equip Superior or better gear (item level 310+) in every slot during Battle for Azeroth. Start by farming dungeons to reach the required item levels.", x = 7 },
        [12547] = { e = 3, s = "c", r = "Requires equipping higher ilvl gear in all slots.", d = "Equip Epic or better gear (item level 340+) in every slot during Battle for Azeroth. You must first complete the Superior (Battle) achievement.", x = 7 },
        [12548] = { e = 3, s = "c", r = "Mythic dungeon with specific boss order.", d = "Defeat Skycap'n Kragg after summoning and defeating Patches in Freehold on Mythic difficulty. This requires completing the specific dungeon sequence correctly.", x = 7 },
        [12549] = { e = 3, s = "c", r = "Mythic dungeon with specific boss order.", d = "Defeat Musashitake, then defeat Sporecaller Zancha in Underrot on Mythic difficulty. Ensure you have the prerequisite achievement for the fungal skeleton.", x = 7 },
        [12550] = { e = 3, s = "c", r = "Requires finding and feeding a NPC in Freehold.", d = "Serve Sharkbait his favorite meal in Freehold on Mythic difficulty to complete this dungeon objective. Follow the specific quest line within the raid instance.", x = 7 },
        [12551] = { e = 4, s = "c", r = "Uldir Normal/Mythic with strict movement restriction.", d = "Defeat G'huun in Uldir after having no player move while holding a Power Matrix on Normal or higher. Coordinate with your group to stand still during the encounter.", x = 7 },
        [12555] = { e = 2, s = "s", r = "Simple intro quest chain in Zandalar.", d = "Complete the introduction quests to Zandalar starting with 'Speaker of the Horde'. This is an account-wide achievement, so any character can finish it.", x = 7 },
        [12556] = { e = 3, s = "g", r = "Requires exploring all points in Tiragarde Sound.", d = "Explore Tiragarde Sound by revealing all covered areas on the world map. This is account-wide, so ensure you visit every location from any character.", x = 7 },
        [12557] = { e = 3, s = "g", r = "Requires exploring all points in Drustvar.", d = "Visit every named location listed in the info field to reveal map fog; this is account-wide so do it on any character. No time gate exists, but ensure you explore all sub-areas like Arom's Stand and Waycrest Manor before leaving the zone.", x = 7 },
        [12558] = { e = 3, s = "g", r = "Requires exploring all points in Stormsong Valley.", d = "Travel to Stormsong Valley and visit each listed location such as Brennadam and Shrine of the Storm to clear map fog. This is account-wide, so one character can complete it for your entire account without time limits.", x = 7 },
        [12559] = { e = 3, s = "g", r = "Requires exploring all points in Zuldazar.", d = "Go to Zuldazar and interact with every named spot like Dazar'alor and Xibala to reveal the map. Since this is account-wide, you only need to visit these locations once on any character in BfA.", x = 7 },
        [12560] = { e = 3, s = "g", r = "Requires exploring all points in Vol'dun.", d = "Explore Vol'dun by visiting all listed areas including Atul'Aman and Tortaka Refuge to clear the map fog. This achievement is account-wide, so complete it on one character and it counts for everyone.", x = 7 },
        [12561] = { e = 3, s = "g", r = "Requires looting 10 bounties while in War Mode.", d = "Visit every named location in Nazmir such as Zalamar and The Frogmarsh to reveal the map. It is account-wide, meaning you can finish this on a single character without worrying about time gates.", x = 7 },
        [12571] = { e = 4, s = "g", r = "Requires killing many players while in War Mode.", d = "Enable War Mode and hunt players who have bounties on them to loot their rewards. Ensure you are in War Mode when looting the bounty item from a slain player's corpse.", x = 7 },
        [12572] = { e = 3, s = "s", r = "Requires War Mode and RNG air drop.", d = "Enable War Mode, fly or ride to an air supply drop zone, and open a War Supply Crate immediately upon arrival. Do not leave the area after opening it, as the crate despawns quickly if you move too far.", x = 7 },
        [12573] = { e = 4, s = "c", h = { 67925 }, r = "Rare elite world quest is the bottleneck.", d = "Form a party of 2-5 players and complete specific PvP tasks like Honorable Kill or Loot War Supply Chest while in War Mode. Ensure your group stays together to avoid losing progress on rare elite world quests.", x = 7 },
        [12574] = { e = 3, s = "g", r = "Grinding honor in Nazmir takes time.", d = "Enable War Mode, travel to Nazmir, and grind honor until you reach 1000 points in that zone. This is account-wide, so any character earning honor there counts toward the total.", x = 7 },
        [12575] = { e = 3, s = "g", r = "Grinding honor in Zuldazar takes time.", d = "Turn on War Mode, go to Zuldazar, and earn 1000 honor by killing enemies or completing objectives. Since it is account-wide, you can do this on one character and share progress with others.", x = 7 },
        [12576] = { e = 3, s = "g", r = "Grinding honor in Vol'dun takes time.", d = "Activate War Mode, visit Vol'dun, and accumulate 1000 honor through combat or world quests. This achievement is account-wide, so finishing it on one character unlocks it for your whole account.", x = 7 },
        [12577] = { e = 3, s = "g", r = "Grinding conquest in Tiragarde takes time.", d = "Enable War Mode, travel to Tiragarde Sound, and earn 1000 honor by engaging in PvP activities. It is account-wide, so you can complete this on any character without time restrictions.", x = 7 },
        [12578] = { e = 3, s = "g", r = "Grinding honor in Stormsong Valley takes time.", d = "Turn on War Mode, go to Stormsong Valley, and gain 1000 honor through battles or quests. This is account-wide, allowing one character to fulfill the requirement for your entire account.", x = 7 },
        [12579] = { e = 3, s = "g", r = "Grinding honor in Drustvar takes time.", d = "Enable War Mode and farm honor in Drustvar by completing quests or PvP activities until you reach 1000 points. This is account-wide, so playing with friends can speed up progress significantly.", x = 7 },
        [12582] = { e = 2, s = "s", r = "Simple intro quest chain completion.", d = "Start the Kul Tiras campaign immediately after unlocking the zone to complete the introduction questline. Finish all required steps quickly as this achievement may become missable if you delay too long.", x = 7 },
        [12587] = { e = 4, s = "c", h = { 66831 }, r = "Warbringer Yenajz is the hardest boss.", d = "Travel to both Kul Tiras and Zandalar to locate and defeat each listed world boss individually. These bosses spawn on a timer, so check their schedules or use addons to track appearances efficiently.", x = 7 },
        [12588] = { e = 3, s = "g", r = "Collecting all edible plants takes time.", d = "Explore Nazmir thoroughly while eating various plants like Saurolisk Tail Nibs and Stonebloom to collect samples for this exploration achievement. Ensure you consume each item at least once before leaving the zone.", x = 7 },
        [12589] = { e = 4, s = "s", r = "Heroic Island Expedition requires group/RNG.", d = "Queue for Island Expeditions targeting Un'gol Ruins on Heroic difficulty or higher to secure victory points. You must first complete the base Un'gol Ruins expedition before attempting harder difficulties.", x = 7 },
        [12590] = { e = 4, s = "g", r = "Requires multiple successful runs with RNG luck.", d = "Complete any difficulty of the Un'gol Ruins expedition to earn this achievement, serving as a prerequisite for Heroic runs. Simply win one match on Normal or higher to finish it.", x = 7 },
        [12591] = { e = 5, s = "g", r = "Mythic difficulty adds significant time and skill requirements.", d = "Unlock this by first completing the Heroic version of Un'gol Ruins, then queue specifically for Mythic difficulty matches. Victory on Mythic will grant the final tier of this achievement chain.", x = 7 },
        [12592] = { e = 4, s = "g", r = "PvP victory depends on matchmaking and team performance.", d = "Participate in PvP Island Expeditions at Un'gol Ruins to win matches and claim victory points. This requires engaging enemy fleets directly rather than just completing objectives alone.", x = 7 },
        [12593] = { e = 3, s = "c", h = { 66892 }, r = "Quests are moderate but one involves heavy RNG drops.", d = "Complete the specific Kul Tiras quests listed in the achievement details, such as A Sound Plan and Drust Do It. Track your progress carefully since these are individual quest requirements within the Loremaster series.", x = 7 },
        [12594] = { e = 4, s = "g", r = "Winning 20 expeditions requires consistent success and luck.", d = "Win 20 Island Expeditions on Heroic difficulty or higher to advance through this tier of the Captain achievements. Ensure you meet the Normal+ requirement first if you haven't already unlocked previous steps.", x = 7 },
        [12595] = { e = 5, s = "g", r = "Mythic wins are rare and require high skill/team coordination.", d = "After earning Competent Captain, focus exclusively on Mythic difficulty expeditions until you secure 50 victories. This is a long-term goal requiring consistent high-level play and coordination with your crew.", x = 7 },
        [12596] = { e = 3, s = "g", r = "Winning 10 expeditions is moderate but requires RNG luck.", d = "Begin by winning 10 Island Expeditions on Normal difficulty or higher to unlock the next tier in the Captain progression chain. Treat this as an early milestone before moving to Heroic challenges.", x = 7 },
        [12597] = { e = 4, s = "g", r = "PvP wins depend on finding a winning team and luck.", d = "Win ten Island Expeditions in PvP mode, ensuring you select the correct game type before starting each run. This is account-wide and requires level 80+ characters to access the necessary zones.", x = 7 },
        [12600] = { e = 3, s = "s", r = "Specific mechanic check within a single Mythic run.", d = "Light all ceremonial fires within the Shrine of the Storm temple on Mythic difficulty using the Shrine's Breath ability. Coordinate with your group to ensure every fire is lit before defeating the final boss.", x = 7 },
        [12601] = { e = 4, s = "s", r = "Requires perfect avoidance mechanics in a high-difficulty raid.", d = "Defeat Lord Stormsong in Shrine of the Storm on Mythic without touching any Awoken Void orbs. Stay vigilant and avoid ground effects that spawn these dangerous void pools during the fight.", x = 7 },
        [12602] = { e = 5, s = "s", r = "Highly specific condition requiring precise execution and luck.", d = "Defeat Vol'zith the Whisperer while every party member has the Maddening Dreams debuff active throughout the entire encounter. Maintain group buffs and ensure no one loses the effect before the kill.", x = 7 },
        [12604] = { e = 3, s = "c", h = { 67926 }, r = "List of achievements; Nazmir tour is the most demanding.", d = "Complete all listed World PvP achievements, including Tour of Duty quests across multiple zones like Nazmir and Zuldazar. This is account-wide, so coordinate with friends to cover different regions efficiently.", x = 7 },
        [12605] = { e = 4, s = "c", h = { 67933, 67934, 67935 }, r = "Requires completing multiple complex World PvP achievements.", d = "Finish the same set of World PvP tasks as the previous achievement, noting that this version lists slightly different Tour of Duty IDs. Ensure you complete every sub-achievement to unlock the Conqueror of Azeroth title.", x = 7 },
        [12614] = { e = 2, s = "c", r = "Simple buffs obtained by talking to NPCs in Zandalar.", d = "Visit each Loa in Zandalar to receive their specific boon buff while standing near their altar. You must collect all seven buffs listed, which may require visiting different zones or waiting for cooldowns if grouped.", x = 7 },
        [12719] = { e = 3, s = "c", r = "Requires completing specific storylines within the Zandalar zone.", d = "Complete the storylines The Fallen Chieftain and Justice For The Fallen within Zandalar. These are account-wide achievements, so ensure your group finishes both quests to progress.", x = 7 },
        [12721] = { e = 5, s = "s", r = "Highly specific mechanics on Mythic difficulty Kings' Rest.", d = "Defeat Mchimba the Embalmer in Kings' Rest on Mythic without letting him finish an Open Coffin cast and limit Struggle usage to once per Entomb cycle. Communicate clearly with your team to manage mechanics tightly.", x = 7 },
        [12722] = { e = 4, s = "g", r = "Requires finding four rare trinkets in a dungeon run.", d = "Locate and collect four ancient trinkets hidden within Kings' Rest on Mythic difficulty. Explore thoroughly after each boss phase, as these items are rare drops that may not appear in every run.", x = 7 },
        [12723] = { e = 5, s = "s", r = "Specific boss mechanic required on Mythic difficulty Kings' Rest.", d = "Free Miimii the Mummy by completing the specific boss achievement in Kings' Rest on Mythic. This unlocks a pet reward and requires precise timing to avoid triggering failure conditions during the encounter.", x = 7 },
        [12726] = { e = 4, s = "g", r = "Requires killing many specific mobs before the Siege of Boralus boss.", d = "Kick fifteen Gasping Flounders back into water before defeating Viq'Goth in Siege of Boralus on Mythic. Use area-of-effect abilities or ranged attacks to clear fish quickly without engaging the boss prematurely.", x = 7 },
        [12727] = { e = 5, s = "s", r = "Strict mechanic against a specific boss on Mythic difficulty.", d = "This is a Mythic Siege of Boralus achievement requiring you to hold Dread Captain Lockwood's evasive aura until her death. Coordinate with your group to focus fire on her while maintaining the aura; do not let her leap away or the timer will reset.", x = 7 },
        [12731] = { e = 3, s = "g", r = "Requires gaining 150 skill points in one Kul Tiran profession.", d = "Pick one primary profession and grind recipes in Kul Tiras zones until you reach 150 skill points. This is account-wide, so any character can contribute to the progress once unlocked.", x = 7 },
        [12733] = { e = 3, s = "g", r = "Requires gaining 150 skill points in one Zandalari profession.", d = "Select a primary profession and focus on Zandalari recipes found in Zandalar zones to reach 150 skill points. Ensure you are in the correct faction zone for these specific recipe categories to count.", x = 7 },
        [12734] = { e = 4, s = "c", r = "Requires reaching the goal in two different Kul Tiran professions.", d = "You must complete the previous Kul Tiran single-profession achievement first, then grind two different primary professions to 150 Kul Tiran skill points each. This is account-wide and requires significant profession grinding across multiple characters or long sessions.", x = 7 },
        [12735] = { e = 4, s = "c", r = "Requires reaching the goal in two different Zandalari professions.", d = "Unlock the prior Zandalari single-profession requirement, then raise two distinct primary professions to 150 skill points in Zandalari recipes. Like the Kul Tiran version, this is account-wide and requires dedicated grinding time.", x = 7 },
        [12736] = { e = 4, s = "c", r = "Grinding 15 skill points in all Kul Tiran professions.", d = "Complete all individual Kul Tiran profession achievements first, then grind every remaining primary profession to 150 Kul Tiran skill points. This is a massive account-wide goal requiring extensive crafting across all characters.", x = 7 },
        [12737] = { e = 4, s = "c", r = "Grinding 15 skill points in all Zandalari professions.", d = "Finish the Zandalari single-profession prerequisites before grinding all primary professions to 150 Zandalari skill points. Expect this to take considerable time as it involves every profession on your entire account.", x = 7 },
        [12738] = { e = 3, s = "g", r = "Scrap 100 items; effort shrinks steadily as count rises.", d = "Acquire the Scrap-O-Matic 1000 from a vendor and start scrapping unwanted items immediately. You need to scrap exactly 100 items; using the Shred-Master Mk1 also works if you have it equipped.", x = 7 },
        [12739] = { e = 3, s = "g", r = "Scrap 250 items; effort shrinks steadily as count rises.", d = "Continue using the Scrap-O-Matic 1000 or Shred-Master Mk1 to reach a total of 250 scrapped items. This is account-wide, so scrap on any character once you have learned the ability.", x = 7 },
        [12740] = { e = 3, s = "g", r = "Scrap 500 items; effort shrinks steadily as count rises.", d = "Keep scrapping items with your chosen machine until you hit 500 total scraps. Since this is account-wide, you can rapidly progress by having multiple characters scrap simultaneously.", x = 7 },
        [12741] = { e = 1, s = "s", r = "Complete one quest to learn the Scrap-O-Matic.", d = "Find and complete the quest 'A Load of Scrap' to learn how to use the Scrap-O-Matic 1000. Once learned, this ability persists across all your characters for the subsequent achievements.", x = 7 },
        [12742] = { e = 3, s = "g", r = "Grinding fishing skill points in Kul Tiran zones.", d = "Grind cooking recipes specifically located in Kul Tiras zones until you reach 150 skill points in that category. This is account-wide, so any character can help progress toward the goal.", x = 7 },
        [12743] = { e = 3, s = "g", r = "Grinding cooking skill points in Zandalari zones.", d = "Focus on cooking Zandalari recipes to gain the required 150 skill points efficiently while exploring Zuldazar. Ensure you have access to all necessary ingredients before starting this long-term grind.", x = 7 },
        [12744] = { e = 3, s = "c", r = "Cook 10 specific recipes; effort depends on which are left.", d = "Cook the ten specific Kul Tiran recipes listed in the info field, which are available after completing the Kul Tiras storyline. This is account-wide, so any character can contribute by cooking these dishes.", x = 7 },
        [12746] = { e = 3, s = "c", r = "Cook 10 specific recipes; effort depends on which are left.", d = "Prepare the ten Zandalari recipes listed to complete this achievement, earning a decorative griddle as a reward. Visit Zuldazar and use your cooking skill to craft these items.", x = 7 },
        [12747] = { e = 3, s = "g", r = "Cook 50 specific meals; effort shrinks steadily as count rises.", d = "Cook fifty of the specified buff foods like Galley Banquets or Bountiful Captain's Feasts to reach 25 points. These recipes often drop from world bosses or can be crafted once unlocked.", x = 7 },
        [12753] = { e = 3, s = "g", r = "Grinding fishing skill points in Kul Tiran zones.", d = "Fish in Kul Tiran waters until you accumulate 150 skill points, which may take significant time depending on your fishing rate. Use bait and explore various zones to maximize catch efficiency.", x = 7 },
        [12754] = { e = 3, s = "g", r = "Grinding 150 skill points takes several hours.", d = "Gain 150 skill points by fishing exclusively within Zandalar territories like Dazar'alor or Nazmir. This requires dedicated sessions in those regions.", x = 7 },
        [12755] = { e = 3, s = "g", r = "Converting 100 fish requires significant time.", d = "Convert one hundred fish from Kul Tiras and Zandalar into Aromatic Fish Oil using the appropriate profession skill. Gather fish from both zones to meet the requirement.", x = 7 },
        [12756] = { e = 4, s = "g", r = "Midnight Salmon are rare; grinding 50 takes days.", d = "Fish for Midnight Salmon, which are rare spawns often found in specific coastal areas or during certain events. Be patient as these fish do not appear frequently.", x = 7 },
        [12757] = { e = 2, s = "g", r = "Normal fish are common; 100 is quick work.", d = "Catch one hundred normal fish in either Kul Tiras or Zandalar by exploring their waters regularly. Avoid catching legendary fish to ensure you count toward the total.", x = 7 },
        [12758] = { e = 4, s = "s", r = "U'taka is a rare spawn requiring luck/time.", d = "Fish for an U'taka specifically within Dazar'alor, as this rare catch is location-dependent and may require luck. Check local fishing spots in Zuldazar for appearances.", x = 7 },
        [12759] = { e = 4, s = "s", r = "Rasboralus is a rare spawn requiring luck/time.", d = "Fish for a Rasboralus inside Proudmoore Keep in Tiragarde Sound, which is a specific dungeon environment. Enter the keep and fish carefully to secure this unique catch.", x = 7 },
        [12760] = { e = 3, s = "g", r = "Grinding 950 archaeology skill points takes hours.", d = "Reach 950 archaeology skill points by excavating artifacts across Azeroth, but note you must already be an Archaeologist from Legion. Continue digging in any zone to progress.", x = 7 },
        [12761] = { e = 3, s = "g", r = "Grinding 950 archaeology skill points takes hours.", d = "Start by leveling Archaeology to max skill in Kul Tiras or Zandalar. Focus on high-level digsites to gain points quickly, as this is a grind that benefits from completing other content first.", x = 7 },
        [12762] = { e = 4, s = "c", r = "Most artifacts are easy; Blowgun of the Sethra is hardest.", d = "This account-wide achievement requires restoring every artifact listed in the info field. Prioritize finding rare pristine versions of items like the Blowgun of the Sethrak, which drop infrequently from specific digsites or world bosses.", x = 7 },
        [12764] = { e = 4, s = "c", r = "Most artifacts are easy; Blowgun of the Sethra is hardest.", d = "Similar to the previous achievement, you must restore all artifacts. Ensure you have completed the prerequisite Zandalari Curator if applicable, and focus on obtaining pristine versions of common drops alongside rare ones.", x = 7 },
        [12765] = { e = 4, s = "c", h = { 67632 }, r = "Most artifacts are easy; Blowgun of the Sethra is hardest.", d = "Restore one copy of each common artifact listed. This is often easier than the pristine versions, but still requires extensive digging across both zones to find every unique item type.", x = 7 },
        [12769] = { e = 3, s = "g", r = "Completing 50 digsites takes a few hours.", d = "Complete fifty digsites in either zone. You can track progress via the achievement tracker, and this goal is best achieved by consistently running high-level sites rather than just any site.", x = 7 },
        [12770] = { e = 3, s = "g", r = "Requires finding and completing 100 specific digsites.", d = "Reach one hundred total digsite completions. This builds directly on the previous achievement, so continue your archaeology grind without stopping once you hit fifty to save time.", x = 7 },
        [12771] = { e = 4, s = "c", h = { 67652 }, r = "Most items are easy, but one requires a specific rare drop.", d = "Explore Nazmir thoroughly to find unique treasures like Lucky Horace's Chest or Venomous Seal. These often require specific quest lines or defeating particular world bosses within the zone.", x = 7 },
        [12772] = { e = 4, s = "s", r = "Requires specific raid mechanics and boss defeat.", d = "Defeat Vectis in Uldir after infecting Warmother Rakkali with a Plague Bomb. Ensure you are on Normal difficulty or higher, and coordinate with your raid group to handle the mechanics correctly.", x = 7 },
        [12806] = { e = 5, s = "c", r = "Requires completing multiple raids/dungeons including high-level content.", d = "Complete all listed Uldir raid achievements. This is a collection goal requiring multiple raids runs; prioritize difficult objectives like Double Dribble or Elevator Music which may need specific strategies.", x = 7 },
        [12807] = { e = 5, s = "c", h = { 67869 }, r = "Requires completing multiple heroic dungeons including difficult ones.", d = "Finish Heroic versions of all Battle for Azeroth dungeons listed. Run these with a group to ensure success, as some dungeons have mechanics that are very punishing on Heroic difficulty.", x = 7 },
        [12812] = { e = 5, s = "c", h = { 68607 }, r = "Requires completing multiple mythic dungeons including very difficult ones.", d = "Complete Mythic dungeon achievements listed. This requires high-level gear and coordination; start with easier dungeons like The Temple of Sethraliss before tackling harder ones like Atal'Dazar.", x = 7 },
        [12823] = { e = 4, s = "s", r = "Requires specific raid mechanics and boss defeat.", d = "Defeat the Fetid Devourer in Uldir while ensuring every player gets hit by Terrible Thrash. Coordinate with your raid to maximize damage output and ensure no one misses the debuff application.", x = 7 },
        [12824] = { e = 3, s = "s", r = "Requires defeating a dungeon boss on normal difficulty.", d = "Start on Normal difficulty to defeat Yazma in Atal'Dazar. Complete this before moving to Heroic or Mythic versions of the dungeon.", x = 7 },
        [12825] = { e = 4, s = "s", r = "Requires defeating a dungeon boss on heroic difficulty.", d = "You must finish the Normal version first, then run Heroic Atal'Dazar to defeat Yazma again. Do not attempt Mythic until you have the Heroic completion.", x = 7 },
        [12826] = { e = 5, s = "s", r = "Requires defeating a dungeon boss on mythic difficulty.", d = "This requires completing both Normal and Heroic versions of Atal'Dazar beforehand. Run the dungeon on Mythic difficulty to defeat Yazma for the final point.", x = 7 },
        [12828] = { e = 4, s = "s", r = "Requires specific raid mechanics and boss defeat.", d = "Defeat Zek'voz in Uldir after exposing Yogg-Saron's Puzzle Box on Normal or higher. Ensure you are on the correct raid difficulty before starting the fight.", x = 7 },
        [12830] = { e = 4, s = "s", r = "Requires specific raid mechanics and boss defeat.", d = "Run Uldir on Normal or higher and avoid stepping onto the inner ring of the Oblivion Door during Zul's fight. Coordinate with your group to keep everyone off the platform.", x = 7 },
        [12831] = { e = 2, s = "s", r = "First clear of a standard dungeon boss.", d = "Begin by defeating Harlan Sweete in Freehold on Normal difficulty. Once completed, you can progress to Heroic and Mythic versions of the dungeon.", x = 7 },
        [12832] = { e = 4, s = "s", r = "Requires Heroic difficulty clear first.", d = "Finish the Normal version first, then run Freehold on Heroic difficulty to defeat Harlan Sweete again. You cannot start this until you have cleared the base dungeon.", x = 7 },
        [12833] = { e = 5, s = "s", r = "Requires Mythic difficulty; high RNG/coordination.", d = "Complete both Normal and Heroic versions of Freehold before attempting Mythic. Defeat Harlan Sweete on Mythic difficulty to earn the final point.", x = 7 },
        [12835] = { e = 2, s = "s", r = "First clear of a standard dungeon boss.", d = "Defeat Vol'zith the Whisperer in Shrine of the Storm on Normal difficulty first. This unlocks the ability to attempt Heroic and Mythic versions later.", x = 7 },
        [12836] = { e = 5, s = "s", r = "Requires specific mechanic execution in raid.", d = "Run Uldir on Normal or higher while ensuring no player touches an Existence Fragment spawned by teammates. Coordinate carefully during Mythrax's fight to avoid contact.", x = 7 },
        [12837] = { e = 4, s = "s", r = "Requires Heroic difficulty clear first.", d = "You must clear the Normal version of Shrine of the Storm before attempting Heroic. Defeat Vol'zith the Whisperer on Heroic difficulty to earn this achievement.", x = 7 },
        [12838] = { e = 5, s = "s", r = "Requires Mythic difficulty; high RNG/coordination.", d = "Complete both Normal and Heroic versions of Shrine of the Storm first. Then run the dungeon on Mythic difficulty to defeat Vol'zith the Whisperer for the final point.", x = 7 },
        [12840] = { e = 2, s = "s", r = "First clear of a standard dungeon boss.", d = "Complete the normal Tol Dagor dungeon first to unlock higher difficulties. This achievement is time-gated if you do not clear the base version before progressing.", x = 7 },
        [12841] = { e = 4, s = "s", r = "Requires Heroic difficulty clear first.", d = "Run Heroic Tol Dagor immediately after clearing normal mode. Ensure your group is ready for increased difficulty as this unlocks the final Mythic tier.", x = 7 },
        [12842] = { e = 5, s = "s", r = "Requires Mythic difficulty; high RNG/coordination.", d = "Defeat Overseer Korgus on Mythic difficulty to finish the Tol Dagor chain. This requires completing both normal and Heroic versions first.", x = 7 },
        [12844] = { e = 2, s = "s", r = "First clear of a standard dungeon boss.", d = "Clear The MOTHERLODE!! dungeon normally before attempting harder modes. Mogul Razdunk drops loot that is essential for subsequent achievements.", x = 7 },
        [12845] = { e = 4, s = "s", r = "Requires Heroic difficulty clear first.", d = "Progress to Heroic difficulty in The MOTHERLODE!! after clearing normal mode. This step is mandatory before you can attempt Mythic.", x = 7 },
        [12846] = { e = 4, s = "s", r = "Requires clearing Mythic dungeon; high difficulty.", d = "Complete the full chain by defeating Mogul Razdunk on Mythic difficulty. You must have cleared both normal and Heroic versions first.", x = 7 },
        [12847] = { e = 4, s = "s", r = "Requires clearing Mythic dungeon; high difficulty.", d = "Clear Siege of Boralus on Mythic difficulty to earn these points. This is a single-step achievement requiring the highest dungeon tier.", x = 7 },
        [12848] = { e = 4, s = "s", r = "Requires clearing Mythic dungeon; high difficulty.", d = "Defeat Dazar in Kings' Rest on Mythic difficulty for this reward. Ensure you have access to the Mythic version of this dungeon.", x = 7 },
        [12849] = { e = 3, s = "g", r = "Collecting many unique treasures across zones.", d = "Explore Vol'dun thoroughly to find all unique treasure chests listed in the info. This is account-wide and requires visiting specific locations.", x = 7 },
        [12851] = { e = 3, s = "g", r = "Collecting many unique treasures across zones.", d = "Search Zuldazar for every unique treasure item mentioned in the requirements. These drops are account-wide and may take time to collect.", x = 7 },
        [12852] = { e = 3, s = "g", r = "Collecting many unique treasures across zones.", d = "Visit Tiragarde Sound and locate all hidden treasure chests listed. This achievement is account-wide and depends on finding specific items.", x = 7 },
        [12853] = { e = 3, s = "g", r = "Collecting many unique treasures across zones.", d = "Explore Stormsong Valley to discover all unique treasures required. Be patient as some chests may be rare or located in hard-to-reach spots.", x = 7 },
        [12854] = { e = 4, s = "s", r = "Requires perfect Mythic run; high difficulty.", d = "Defeat Mogul Razdunk on Mythic without taking specific heavy-hitting abilities. Focus on dodging rockets and missiles while waiting for the boss to reset between phases.", x = 7 },
        [12855] = { e = 4, s = "s", r = "Specific boss fight on Mythic; high difficulty.", d = "Complete the Pitch Invasion dungeon first, then defeat Ledley the Bold before engaging the Coin-Operated Crowd Pummeler immediately after.", x = 7 },
        [12856] = { e = 1, s = "s", r = "Simple participation in a duel event.", d = "Enter the Dueler's Guild and accept any duel quest to start this chain; no specific win condition is required yet.", x = 7 },
        [12857] = { e = 2, s = "g", r = "Requires winning one duel; low difficulty.", d = "You must win at least one duel before unlocking further goals, so find a friendly opponent or use a trainer if needed.", x = 7 },
        [12858] = { e = 3, s = "g", r = "Requires winning five duels; moderate effort.", d = "Win five total duels in the guild; this tracks account-wide and does not require consecutive wins or staying in the instance.", x = 7 },
        [12859] = { e = 3, s = "c", r = "Requires winning 3 duels; moderate grind.", d = "Enter the Dueler's Guild and win three consecutive duels without leaving the instance or losing your champion status. Keep track of your duel streak to avoid resetting progress.", x = 7 },
        [12860] = { e = 4, s = "g", r = "Winning 25 duels is a long solo grind.", d = "Accumulate twenty-five duel victories to unlock the next tier, ensuring you track your count across all characters since it is account-wide.", x = 7 },
        [12861] = { e = 4, s = "c", r = "Requires completing other hard dueling achievements.", d = "Finish all listed sub-achievements including Thirty Six and Two and Prize Fighter before claiming the Master of Duels title.", x = 7 },
        [12862] = { e = 3, s = "c", r = "Defeating each class is a moderate checklist grind.", d = "Queue for duels against every class type, noting that some classes may require specific tactics or gear to defeat consistently.", x = 7 },
        [12863] = { e = 4, s = "g", r = "Winning 50 duels is a significant solo grind.", d = "Reach fifty total wins to earn the Dueler's Tabard; remember this counter resets if you leave the guild instance during a match.", x = 7 },
        [12864] = { e = 4, s = "g", r = "Raising 80 reputations to Exalted is a long grind.", d = "Grind faction reputations efficiently by focusing on high-yield activities like world quests or dungeons until you hit eighty exalted titles.", x = 7 },
        [12865] = { e = 4, s = "g", r = "Raising 90 reputations to Exalted is a long grind.", d = "Continue grinding after reaching eighty to gain the final ten; this step has no additional requirements beyond raising more factions to exalted.", x = 7 },
        [12866] = { e = 4, s = "g", r = "Raising 100 reputations to Exalted is a very long grind.", d = "Grind daily reputation vendors and world quests across all zones until you hit Exalted. This is account-wide but requires significant time investment as you must raise 100 distinct factions.", x = 7 },
        [12867] = { e = 3, s = "c", r = "Completing 6 missions is a moderate checklist task.", d = "Complete any six of the listed Barrens missions for the Horde war effort. These are typically daily-style objectives found in specific zones like Durotar or Theramore.", x = 7 },
        [12869] = { e = 3, s = "c", r = "Completing 6 Lordaeron missions is a moderate checklist.", d = "Finish six missions related to Lordaeron for the Horde campaign. Focus on zones like Gilneas or Alterac Valley where these specific story events occur.", x = 7 },
        [12870] = { e = 3, s = "c", r = "Completing 6 Kalimdor missions is a moderate checklist.", d = "Complete six Kalimdor-specific war missions. Visit zones like Ashenvale or Teldrassil to find the required objectives for this expansion feature.", x = 7 },
        [12872] = { e = 4, s = "g", r = "Raising all champions to epic level is a long grind.", d = "Raise all War Campaign champions to Epic level by completing their specific daily or weekly challenges. This requires consistent engagement with the war campaign interface.", x = 7 },
        [12873] = { e = 4, s = "c", r = "Requires completing a full Warfront campaign.", d = "Fully complete the Battle for Stromgarde warfront as the Horde faction. Ensure you capture all points and defeat commanders to unlock this milestone.", x = 7 },
        [12874] = { e = 4, s = "g", r = "Must complete 6 random events within the warfront.", d = "Participate in six random events within the Battle for Stromgarde warfront. These pop up during the battle, so stay active throughout the entire encounter.", x = 7 },
        [12876] = { e = 4, s = "c", r = "Requires capturing every location in the warfront.", d = "Capture every single location on the map during the Battle for Stromgarde. You must hold or visit each point to satisfy this requirement.", x = 7 },
        [12877] = { e = 3, s = "g", r = "Requires capturing at least one location.", d = "Capture at least one location in the Battle for Stromgarde to start the chain. This is often an early objective available once the warfront begins.", x = 7 },
        [12878] = { e = 4, s = "c", r = "Must recruit every unique troop type available.", d = "Recruit one unit of each troop type available in the Battle for Stromgarde. Check your recruitment menu to ensure you have at least one of every kind.", x = 7 },
        [12879] = { e = 5, s = "c", h = { 68123 }, r = "Requires defeating specific commanders; Danath is rare.", d = "Defeat every enemy commander listed in the Battle for Stromgarde. These are usually elite targets that appear during specific phases of the warfront.", x = 7 },
        [12881] = { e = 4, s = "c", r = "Requires completing a full Warfront campaign.", d = "Fully complete the Battle for Stromgarde warfront as the Alliance faction. Follow the same steps as the Horde version but ensure you are playing on the Alliance side.", x = 7 },
        [12884] = { e = 4, s = "c", r = "Must recruit every unique troop type available.", d = "Recruit every troop type in Battle for Stromgarde by completing warfronts until all units appear. This is account-wide and requires no specific order, but ensure you finish the campaign fully to unlock all recruits.", x = 7 },
        [12886] = { e = 3, s = "g", r = "Requires capturing at least one location.", d = "Defeat Eitrigg, Lady Liadrin, and Rokhan as commanders in Battle for Stromgarde. Complete full warfronts with each leader present; do not skip any commander encounters to avoid missing this requirement.", x = 7 },
        [12888] = { e = 3, s = "g", r = "Requires capturing multiple locations across a warfront.", d = "Join a Warfront group for Battle for Stromgarde and help capture any location on the map. This is an account-wide achievement, so you can contribute from any faction.", x = 7 },
        [12889] = { e = 4, s = "c", r = "Requires capturing every location in the warfront.", d = "Capture all seven locations in Battle for Stromgarde before the warfront ends. This achievement requires completing 'Strike Hard' first, so prioritize capturing every zone during your final push.", x = 7 },
        [12891] = { e = 3, s = "c", r = "Requires completing multiple Kul Tiras meta achievements.", d = "Complete the Kul Tiras meta achievement by finishing Loremaster of Kul Tiras, The Pride of Kul Tiras, and A Nation United. Start with quest hubs in Boralus to unlock all necessary sub-quests efficiently.", x = 7 },
        [12893] = { e = 2, s = "g", r = "Grinding PvP for ~5 hours to reach level 5.", d = "Reach Honor Level 5 by earning honor through PvP activities like arenas or battlegrounds. This is account-wide, so any character's progress counts toward the shared goal.", x = 7 },
        [12894] = { e = 2, s = "g", r = "Additional PvP grind takes another few hours.", d = "Advance to Honor Level 10 after reaching level 5 by continuing PvP participation. No special tactics are needed beyond consistent engagement in rated or unrated PvP content.", x = 7 },
