        [12931] = { e = 4, s = "g", r = "Collecting all Zandalar/Kul Tiras pets is a lengthy grind.", d = "Gather 400 mounts by completing previous collection milestones and hunting rare spawns. This is account-wide, so coordinate with friends if needed for rare drops.", x = 7 },
