        [12938] = { e = 4, s = "s", r = "Defeating MOTHER requires a raid group and secret passcode.", d = "Enter MOTHER's secret passcode before fighting her in Uldir on Normal or higher. The code is obtained from specific NPCs; do not skip this step or the achievement will be missable.", x = 7 },
