        [12957] = { e = 1, s = "s", r = "Unlock Honorbound achievement first.", d = "Finish the main Honorbound achievement before earning Exalted status with them. Ensure you have completed all necessary steps for the prerequisite to unlock the final title.", x = 7 },
        [12958] = { e = 4, s = "g", r = "Grind for 1000 pets; RNG dominates.", d = "Use the Pet Emporium to collect your 1000th unique pet, as this is required for the Master of Minions achievement. Review your collection frequently to identify missing pets efficiently.", x = 7 },
        [12988] = { e = 3, s = "c", r = "Explore multiple zones and regions.", d = "Explore every zone in Kul Tiras and Zandalar by visiting all major points of interest and completing exploration quests. Ensure you have visited every location to unlock the full Battle for Azeroth Explorer achievement.", x = 7 },
        [12989] = { e = 2, s = "s", r = "Fish one specific rare fish.", d = "Complete the Battle for Azeroth Explorer achievement first, along with other listed prerequisites like the War Campaign. Finish all zone questlines and diplomatic achievements to unlock the Pathfinder title.", x = 7 },
        [12990] = { e = 3, s = "c", r = "Complete multiple zone questlines.", d = "Fish in the oceans around Kul Tiras or Zandalar until you catch a Great Sea Ray. This rare fish is needed for the Catchin' Some Rays achievement and may require patience.", x = 7 },
        [12991] = { e = 4, s = "s", r = "Grind Uldir for full set.", d = "Collect any single piece of Tier 22 armor from Uldir to complete this appearance set achievement. You do not need a full set, just one item from the tier.", x = 7 },
        [12992] = { e = 4, s = "g", r = "Grind for 800 pets; RNG dominates.", d = "This is a massive, account-wide collection goal requiring 800 unique pets. Start by catching common wild pets and completing daily quests to earn rare ones over time. Be patient as this will take hundreds of hours across many expansions.", x = 7 },
        [12993] = { e = 3, s = "s", r = "Collect PvP gear from one source.", d = "Equip any full armor set from the Arathi Warfront or PvP Season 1 to claim this. If you already own gear from those sources, simply equip them and turn in the achievement immediately.", x = 7 },
        [12995] = { e = 4, s = "c", r = "Find many hidden chests in zone.", d = "Explore Drustvar thoroughly to find hidden chests scattered throughout the zone. Use your mount to speed up travel between locations and ensure you check every corner for lootable containers.", x = 7 },
        [12996] = { e = 4, s = "g", r = "Grind for 400 toys; RNG dominates.", d = "Gather toys from daily quests, world bosses, and rare drops until you reach 400. This is account-wide so share progress with friends if needed to speed up completion.", x = 7 },
        [12997] = { e = 3, s = "s", r = "Requires prior storyline completion.", d = "Complete the entire Jaina Proudmoore storyline in Kul Tiras to finish this quest chain. Ensure you finish all sub-objectives before turning in the final reward.", x = 7 },
        [12998] = { e = 4, s = "g", r = "Mythic dungeon with specific chest destruction.", d = "Enter Freehold on Mythic difficulty and destroy three Chests o' Booty before defeating Harlan Sweete. This requires a full group and specific dungeon runs on the highest difficulty setting.", x = 7 },
        [13009] = { e = 3, s = "g", r = "Collecting multiple rare scales from fishing.", d = "Go to Vol'dun and collect all five colored Sandworm Scales from sandfishing activities. Fish in various locations within the zone until you have at least one of each scale color.", x = 7 },
        [13011] = { e = 2, s = "g", r = "Kill count with a companion NPC.", d = "Travel to Port of Zem'lan in Vol'dun with Ol' Bonebite equipped or summoned. Kill 20 pirates while he is present to complete this objective quickly.", x = 7 },
        [13014] = { e = 3, s = "g", r = "Requires specific weapons and kill counts.", d = "Acquire Vorrik's Bulwark, Rakjan the Unbroken, or a Battle Krolusk before fighting Faithless in Vol'dun. Use your chosen weapon against him 100-300 times depending on which item you select.", x = 7 },
        [13016] = { e = 2, s = "g", r = "Collecting scattered junk items in zone.", d = "Scour Vol'dun for lost junk items dropped by NPCs and enemies. Check every corpse and interaction point to ensure you collect all listed personal belongings before leaving the zone.", x = 7 },
        [13017] = { e = 2, s = "g", r = "Rescue count with companion NPC.", d = "Rescue 50 vulpera scattered throughout Vol'dun by interacting with their distress signals. Run the entire zone systematically to locate and save each trapped vulpera citizen.", x = 7 },
        [13018] = { e = 2, s = "s", r = "Riding specific planks in zone.", d = "Ride across all five rickety planks in Vol'dun using your mount. Locate these specific wooden bridges and ride over them to trigger the achievement counter.", x = 7 },
        [13020] = { e = 2, s = "s", r = "Single timed world quest solo.", d = "Bowl to each Loa in Zandalar individually, as they are account-wide and require no group. Start with Bwonsamdi or Krag'wa near the Loa Sanctum, then visit the others like Rezan and Sethraliss. No time limit exists, but ensure you have completed the initial questline to access them.", x = 7 },
        [13021] = { e = 2, s = "s", r = "Single timed world quest solo.", d = "Board the A.F.M.O.D alone in Nazmir and rush through the 'Cancel the Blood Troll Apocalypse' world quest within 30 seconds. Do not engage enemies or use abilities that delay your progress, as solo play is mandatory. This can be missable if you wait for a group or fail the timer.", x = 7 },
        [13022] = { e = 2, s = "s", r = "Single timed world quest solo.", d = "Ride Krag'wa alone and complete the 'Revenge of Krag'wa' world quest in under 45 seconds without stopping. Avoid unnecessary combat to maintain speed, as being in a group will prevent completion. Practice the route beforehand to ensure you beat the timer on your first attempt.", x = 7 },
        [13023] = { e = 2, s = "s", r = "Single timed world quest solo.", d = "Become the Hand of Fate solo and finish the 'Getting out of hand' world quest within 20 seconds. This requires quick movement and avoiding any actions that break the buff or delay you. It is a high-pressure solo task where mistakes will cause failure.", x = 7 },
        [13024] = { e = 3, s = "g", r = "Collecting scattered items across Nazmir takes a few hours.", d = "Locate all Nazmani pictographs in Nazmir, including four Fractured Tablets scattered across the zone. These are account-wide and do not require specific quests, so explore thoroughly while avoiding time gates. Check caves and ruins for the Cracked and Weathered tablets to ensure none are missed.", x = 7 },
        [13025] = { e = 4, s = "s", r = "Solo world quest with strict time limit and RNG spawns.", d = "Complete the 'Don't Stalk Me, Troll' world quest alone by slaying invaders within 60 seconds. Do not join a group or use slow travel methods, as the timer starts immediately upon acceptance. Focus on efficient combat to clear enemies before time runs out.", x = 7 },
        [13026] = { e = 4, s = "s", r = "Solo world quest with strict time limit and RNG spawns.", d = "This achievement mirrors id=13025; complete the 'Don't Stalk Me, Troll' world quest solo in 60 seconds without grouping. Ensure you are not in a party when starting the quest, as group status will invalidate the requirement. Speed is key to clearing all invaders before the timer expires.", x = 7 },
        [13027] = { e = 3, s = "g", r = "Killing specific mobs in Zandalar takes a few hours.", d = "Kill all four fungarian villains (Skullcap, Bane of the Woods, Portakillo, Toadcruel) in Zandalar for this account-wide achievement. They spawn randomly, so explore different areas of Zuldazar and Vol'dun to find them. No time limit applies, but patience is needed as they may take days to appear.", x = 7 },
        [13028] = { e = 3, s = "g", r = "Shooing 10 specific mobs in Nazmir takes a few hours.", d = "Shoo ten Lost Spawn of Krag'wa back to their home in Nazmir without killing them. Use the shoo command or appropriate abilities to guide them safely; killing them will not count. This is account-wide and requires finding the spawns, which may take time depending on spawn rates.", x = 7 },
        [13029] = { e = 3, s = "g", r = "Feeding multiple brutoosaurs across zones takes a few hours.", d = "Feed brutosaurs in Nazmir, Vol'dun, and Zuldazar using their favorite food items. These are account-wide, so you can feed them from any server once unlocked. Locate brutoasurs in their respective zones and use the correct food to complete the criteria without missing any.", x = 7 },
        [13030] = { e = 4, s = "s", r = "World quest requires maintaining buffs without dropping them.", d = "Complete the four specific quests at Warbeast Kraal to raise your pterrordax from hatchling to mount. Follow the quest chain sequentially, ensuring you do not miss any steps as they are account-wide. This process takes time and requires caring for your pet through various growth stages.", x = 7 },
        [13035] = { e = 4, s = "s", r = "World quest requires maintaining four totem buffs simultaneously.", d = "Complete the 'Hundred Troll Holdout' world quest in Zuldazar while keeping all four totem buffs active. Do not drop any buffs during the entire duration, as this will fail the achievement. Coordinate with allies if needed, but ensure no one breaks the buff stack prematurely.", x = 7 },
        [13036] = { e = 2, s = "g", r = "Reading scattered books in Zandalar takes under an hour.", d = "Read all Tales of de Loa volumes scattered across Zandalar while leveling to 8.0, as this is account-wide and missable if you skip zones. Start by checking major Loa shrines for the books before completing main story quests.", x = 7 },
        [13038] = { e = 4, s = "s", r = "Maintaining mount speed for 3 minutes is difficult RNG.", d = "Mount Gonk in Zuldazar and hold speed up for three minutes without stopping; do not engage combat or slow down during the timer. This is account-wide, so ensure you are on a character that can access Zuldazar.", x = 7 },
        [13039] = { e = 4, s = "s", r = "Traveling Zuldazar with 6 different totems in 1 minute is hard.", d = "Use six different Totems of Pa'ku within one minute in Zuldazar by running between shrines quickly. Coordinate with a group if needed to trigger totems faster, but avoid delays from combat or travel.", x = 7 },
        [13041] = { e = 4, s = "s", r = "Feeding a voracious pet in under 45 seconds is RNG heavy.", d = "Feed your Voracious Ranishu in Vol'dun as fast as possible under 45 seconds; prepare food beforehand and have the pet ready immediately upon spawning. This is account-wide, so complete it early before leaving the zone.", x = 7 },
        [13042] = { e = 1, s = "s", r = "Instant trigger upon meeting simple status effects.", d = "Stack all three negative Strain effects simultaneously in Stormsong Valley by consuming specific foods or items at once. Check your status bar to confirm all effects are active before moving on.", x = 7 },
        [13045] = { e = 1, s = "s", r = "Instant trigger upon collecting consumable items.", d = "Collect and activate all four Stormsong Valley truffle effects at the same time by visiting each unique location. Ensure you have the correct consumables ready before starting to avoid missing any effect.", x = 7 },
        [13046] = { e = 1, s = "s", r = "Visit a specific location and interact with an NPC.", d = "Find the special luncheon spot in Stormsong Valley and enjoy an Unforgettable Luncheon there without interruption. This is often tied to a specific NPC or event, so check local quest markers for guidance.", x = 7 },
        [13047] = { e = 2, s = "s", r = "Find one mob and use a consumable item on it.", d = "Use a Sporonite Bomb on the Lichen King boss in Stormsong Valley during its encounter. Bring extra bombs and coordinate with your group to ensure the bomb lands correctly before the fight ends.", x = 7 },
        [13048] = { e = 4, s = "g", r = "Kill 8 specific rare dinosaurs across zones.", d = "Hunt and kill one fearsome dinosaur of each species listed in Zuldazar and Nazmir, as this is account-wide. Prioritize rare spawns and check world maps for their locations early in the expansion.", x = 7 },
        [13049] = { e = 3, s = "c", r = "Complete a multi-step quest chain in one zone.", d = "Complete Roko the Wandering Merchant's entire storyline in Tiragarde Sound by following his quests sequentially. This is account-wide, so finish it before leaving Kul Tiras to avoid missing rewards.", x = 7 },
        [13050] = { e = 2, s = "s", r = "Participate in one specific event and hit targets.", d = "During Swab This! in Outlaw Town, hit all four specified targets with Vile Bombardment quickly. Coordinate with your group to ensure all targets are destroyed within the event's duration.", x = 7 },
        [13051] = { e = 2, s = "g", r = "Find and collect multiple scattered lore objects.", d = "Discover each of the eight lore objects related to the Tidesages in Stormsong Valley by exploring hidden areas and completing related quests. This is account-wide, so make sure to check every corner of the zone for collectibles.", x = 7 },
        [13053] = { e = 1, s = "s", r = "Talk to three NPCs at a single fishing village.", d = "Head to Thresher's Wharf in Stormsong Valley and listen to the three specific NPCs mentioned in the description. This is account-wide, so one character can complete it for everyone, but ensure you are at level 80 first.", x = 7 },
        [13054] = { e = 2, s = "g", r = "Kill five specific mobs that spawn in the zone.", d = "Locate and kill all five Sabertron variants (Red, Yellow, Orange, Green, Copper) within Stormsong Valley. These mobs may be rare or time-gated, so check their spawn times if they do not appear immediately.", x = 7 },
        [13056] = { e = 1, s = "s", r = "Complete one specific profession quest.", d = "Complete the quest 'A Load of Scrap' to learn how to use the Shred-Master Mk1. This is a profession achievement, so ensure you have the required crafting skill before starting.", x = 7 },
        [13057] = { e = 2, s = "g", r = "Find seven hidden shanties scattered across the zone.", d = "Explore Tiragarde Sound to find and interact with all seven Forbidden Sea Shanties listed in the info field. Since this is account-wide, one character can unlock it for your entire group.", x = 7 },
        [13058] = { e = 1, s = "s", r = "Talk to NPC and dance once.", d = "Find the dance floor at Norwington Estate in Tiragarde Sound and use the /dance command with another player. This requires two people present simultaneously to register the action.", x = 7 },
        [13059] = { e = 2, s = "g", r = "Drag 5 troggs; simple repeat action.", d = "Use the Bolas item to drag five invading troggs behind Cooper at Norwington Estate all at once. Coordinate with a group to pull the mobs together for this specific mechanic.", x = 7 },
        [13060] = { e = 4, s = "c", h = { 69091, 69092, 69093 }, r = "Complete multiple world quests across zones.", d = "Complete all three Pengling sledding world quests on Kul Tiras: Sliding with Style, Frozen Freestyle, and Slippery Slopes. These are account-wide, so one character can finish them for everyone.", x = 7 },
        [13061] = { e = 4, s = "g", r = "Collect many specific drinks from vendors.", d = "Collect every listed Kul Tiran drink from vendors or world drops across the zone. This is account-wide, so gather drinks on one character to unlock the achievement for your whole account.", x = 7 },
        [13062] = { e = 2, s = "g", r = "Feed formula to pet; simple repeat action.", d = "Feed seven Bumbles in Stormsong Valley using the Mildenhall Growth Formula to earn the pet reward. Ensure you have enough formula items and locate the specific bee NPCs before starting.", x = 7 },
        [13064] = { e = 3, s = "c", h = { 68689, 68690, 68691 }, r = "Find scattered steles in one zone.", d = "Travel to Drustvar and read all nine Drust Steles scattered throughout the zone. This is account-wide, so one character can complete it for your entire group once found.", x = 7 },
        [13075] = { e = 4, s = "c", h = { 68771, 68772, 68773 }, r = "Run all BfA dungeons on Mythic Keystone.", d = "Run all ten Battle for Azeroth dungeons using a Mythic Keystone to unlock this legacy achievement. You must clear each dungeon at least once in Mythic+ difficulty to count toward the total.", x = 7 },
        [13076] = { e = 4, s = "s", r = "Create and level new allied race character.", d = "Create a new Dark Iron Dwarf character and reach level 50 to earn the heritage armor. This is account-wide, so one character can unlock the reward for your entire account.", x = 7 },
        [13077] = { e = 4, s = "s", r = "Create and level new allied race character.", d = "Create a Mag'har Orc character and level to 50. You must unlock the Heritage Armor first before starting this questline.", x = 7 },
        [13082] = { e = 3, s = "c", h = { 68938, 68939, 68940 }, r = "Find scattered relics in one zone.", d = "Travel to Drustvar in Battle for Azeroth to locate specific Order of Embers relics. Return each item to its designated spot within the zone.", x = 7 },
        [13083] = { e = 2, s = "s", r = "Consume specific potions and newt.", d = "Consume all Witch's Boon potions and apply the Newt curse simultaneously in Drustvar. Ensure you have access to every potion type available in the area.", x = 7 },
        [13087] = { e = 3, s = "g", r = "Eat multiple sausages from vendors.", d = "Purchase or find various sausages sold by vendors in Drustvar. Eat each unique sausage listed in the achievement requirements.", x = 7 },
        [13094] = { e = 2, s = "c", r = "Kill 13 unique beasts in Drustvar; easy solo grind.", d = "Locate and kill every type of cursed animal roaming Drustvar. These creatures are often found in specific zones or near quest markers.", x = 7 },
        [13095] = { e = 3, s = "s", r = "Win one expedition on any difficulty; moderate effort.", d = "Queue for an Island Expedition at Dread Chain on any difficulty setting. Victory is required to complete this step of the chain.", x = 7 },
        [13096] = { e = 4, s = "s", r = "Win Heroic Dread Chain; requires better gear/team.", d = "Complete the previous achievement then queue for Dread Chain on Heroic difficulty or higher. This requires a stronger team composition than normal runs.", x = 7 },
        [13097] = { e = 5, s = "s", r = "Win Mythic Dread Chain; high RNG and skill needed.", d = "Unlock Heroic Dread Chain first, then attempt Mythic difficulty. You must win the expedition to earn this final tier of the chain.", x = 7 },
        [13098] = { e = 4, s = "s", r = "Win PvP expedition; requires group coordination.", d = "Queue for a PvP Island Expedition at Dread Chain. Ensure you are in a competitive environment rather than a standard PvE run.", x = 7 },
        [13099] = { e = 3, s = "s", r = "Win one Molten Cay expedition; moderate effort.", d = "Start the Molten Cay chain by winning an expedition on any difficulty. This unlocks access to higher difficulties for this specific island.", x = 7 },
        [13100] = { e = 4, s = "s", r = "Win Heroic Molten Cay; requires better gear/team.", d = "Complete the standard Molten Cay run before attempting Heroic difficulty. Coordinate with your group to handle the increased challenge level.", x = 7 },
        [13101] = { e = 5, s = "s", r = "Win Mythic Molten Cay; high RNG and skill needed.", d = "Finish Heroic Molten Cay first, then attempt Mythic difficulty. This is the final step in the Molten Cay expedition progression chain.", x = 7 },
        [13102] = { e = 4, s = "s", r = "Win PvP Molten Cay; requires group coordination.", d = "Queue for Molten Cay in PvP mode immediately after unlocking the expansion. Ensure your team has enough damage output to secure a quick victory before the timer runs out.", x = 7 },
        [13103] = { e = 3, s = "s", r = "Win one Rotting Mire expedition; moderate effort.", d = "Start with Normal difficulty on Rotting Mire to learn enemy patterns and mechanics. Once comfortable, progress through Heroic and Mythic tiers sequentially for maximum efficiency.", x = 7 },
        [13104] = { e = 4, s = "s", r = "Win Heroic Rotting Mire; requires better gear/team.", d = "You must complete the Normal Rotting Mire achievement first before attempting Heroic. Focus on coordinated team play to handle the increased difficulty and secure the win.", x = 7 },
        [13105] = { e = 5, s = "s", r = "Win Mythic Rotting Mire; high RNG and skill needed.", d = "Unlock Mythic Rotting Mire only after finishing the Heroic tier. This is the hardest version, so ensure your group composition is optimized for survival against elite mechanics.", x = 7 },
        [13106] = { e = 4, s = "c", r = "Requires coordinated group and RNG.", d = "Queue specifically for PvP mode on Rotting Mire once you have cleared the standard versions. Coordinate with your team to defend objectives and eliminate enemy players quickly.", x = 7 },
        [13107] = { e = 4, s = "c", r = "Requires coordinated group and RNG.", d = "Begin with Normal difficulty on Skittering Hollow to understand the island's layout and threats. Progress steadily through difficulties as your group gains experience with the mechanics.", x = 7 },
        [13108] = { e = 5, s = "c", r = "Heroic difficulty adds significant challenge.", d = "Complete the Normal Skittering Hollow achievement before attempting Heroic. Pay close attention to enemy positioning and use crowd control abilities effectively during engagements.", x = 7 },
        [13109] = { e = 5, s = "c", r = "Mythic difficulty is the hardest.", d = "Unlock Mythic Skittering Hollow only after clearing the Heroic tier. This version demands precise timing and strong defensive capabilities from your entire team to succeed.", x = 7 },
        [13110] = { e = 4, s = "c", r = "PvP victory requires coordination.", d = "Queue for PvP mode on Skittering Hollow after finishing standard difficulties. Focus on controlling key areas and managing resources while engaging enemy players strategically.", x = 7 },
        [13111] = { e = 4, s = "c", r = "Requires coordinated group and RNG.", d = "Start with Normal difficulty on Verdant Wilds to master the island's unique mechanics. Build your team's coordination before moving up to higher difficulties for faster completion.", x = 7 },
        [13112] = { e = 5, s = "c", r = "Heroic difficulty adds significant challenge.", d = "Complete the Normal Verdant Wilds achievement before attempting Heroic. Maintain high mobility and damage output to overcome the tougher enemies found on this island.", x = 7 },
        [13113] = { e = 5, s = "c", r = "Mythic difficulty is the hardest.", d = "Unlock Mythic Verdant Wilds only after finishing the Heroic tier. Prepare your group with strong healing and crowd control to handle the intense pressure of this final challenge.", x = 7 },
        [13114] = { e = 4, s = "c", r = "PvP victory requires coordination.", d = "Queue for Verdant Wilds expeditions and secure a victory to claim this point. Ensure you have completed the base island content first.", x = 7 },
        [13115] = { e = 4, s = "c", r = "PvP victory requires coordination.", d = "Queue for Whispering Reef expeditions and secure a victory to claim this point. Ensure you have completed the base island content first.", x = 7 },
        [13116] = { e = 5, s = "c", r = "Mythic difficulty is the hardest.", d = "First unlock Heroic difficulty on Whispering Reef, then queue specifically for Mythic runs to win and complete this achievement.", x = 7 },
        [13118] = { e = 5, s = "c", r = "Heroic/Mythic requires high skill/RNG.", d = "Queue for Whispering Reef expeditions on Heroic or higher difficulty until you secure a victory. This unlocks the next tier.", x = 7 },
        [13119] = { e = 2, s = "s", r = "First expedition victory is quick and solo-friendly.", d = "Simply queue for any Whispering Reef expedition and win to complete this base requirement before tackling harder difficulties.", x = 7 },
        [13120] = { e = 4, s = "g", r = "Requires winning 20 PvP expeditions; steady grind.", d = "Win twenty total PvP Island Expeditions across all maps. This is account-wide, so coordinate with friends if needed.", x = 7 },
        [13121] = { e = 5, s = "g", r = "Winning 50 PvP runs is a long, account-wide grind.", d = "Continue winning PvP Island Expeditions until you reach fifty total victories. Remember this progress carries over your entire account.", x = 7 },
        [13122] = { e = 5, s = "c", h = { 69312 }, r = "Requires completing all other Mythic Island Expedition achievements.", d = "Complete every single Mythic Island Expedition achievement listed in the description before claiming this final title.", x = 7 },
        [13123] = { e = 2, s = "g", r = "Looting 10 dubloons is fast on the first island.", d = "Loot Seafarer's Dubloons from chests or enemies during expeditions until you have collected ten total.", x = 7 },
        [13124] = { e = 3, s = "g", r = "Looting 100 dubloons takes a few hours of grinding.", d = "Keep looting Seafarer's Dubloons from expeditions until you reach one hundred. This builds on your previous collection.", x = 7 },
        [13125] = { e = 4, s = "g", r = "Collecting 1 million Azerite is a massive account-wide grind.", d = "Collect Azerite resources during Island Expeditions to reach the one million threshold. Progress is shared across your account.", x = 7 },
        [13126] = { e = 3, s = "g", r = "Collecting 30 energy globes takes moderate time.", d = "Gather Azerite Energy globes dropped in expeditions until you have thirty. This progress is tracked on your account.", x = 7 },
        [13127] = { e = 3, s = "c", h = { 69336 }, r = "Completing 10 quests; one item requires heavy grinding.", d = "Join Island Expeditions regularly to collect quest items like pamphlets and scales. These drop from enemies or chests during the match, so aim for high-level expeditions to speed up progress.", x = 7 },
        [13128] = { e = 4, s = "c", h = { 69357 }, r = "Getting 15 pets; one pet requires significant RNG/grind.", d = "Participate in Island Expeditions to catch unique battle pets that appear as loot. Check your collection after each run and use the pet vendor if you miss a specific one.", x = 7 },
        [13129] = { e = 2, s = "s", r = "Killing a starfished player happens naturally in PvP.", d = "Play PvP Island Expeditions and wait for opponents to get starfished by teammates. Quickly kill the affected player before they can escape or heal up.", x = 7 },
        [13132] = { e = 4, s = "c", h = { 69396 }, r = "Rescuing 15 explorers; one requires heavy RNG/grind.", d = "Rescue stranded explorers scattered across the island during expeditions. They often appear in dangerous areas, so keep an eye on your surroundings while fighting.", x = 7 },
        [13133] = { e = 4, s = "g", r = "Requires killing 15 specific champions in high-level PvP expeditions.", d = "Focus on killing Horde champions like Gazlowe or Lady Sena during Island Expeditions. These targets are usually marked and offer significant rewards for your efforts.", x = 7 },
        [13134] = { e = 5, s = "c", h = { 69454, 69455, 69456 }, r = "Needs completing all other difficult Island Expedition achievements first.", d = "Complete all other Island Expedition achievements first to unlock this final title. It requires finishing every listed sub-achievement, so track your progress carefully.", x = 7 },
        [13135] = { e = 4, s = "g", r = "Requires killing 15 specific champions in high-level PvP expeditions.", d = "Target Alliance champions such as Briona or Varigg during expeditions. They spawn in specific zones, so explore thoroughly to find and defeat them.", x = 7 },
        [13141] = { e = 5, s = "c", h = { 69649, 69650, 69651 }, r = "Requires completing all other difficult Island Expedition achievements first.", d = "Finish all PvP-specific Island Expedition achievements listed under this category. This includes completing various island conquests and defeating key champions on enemy territory.", x = 7 },
        [13142] = { e = 3, s = "g", r = "Requires finding and winning on five different random islands.", d = "Visit and complete expeditions on five different islands to earn this achievement. Each island has unique mechanics, so try them all for variety and completion.", x = 7 },
        [13144] = { e = 4, s = "g", r = "Requires collecting 100 unique world quests across two zones.", d = "Accept and complete world quests in Kul Tiras and Zandalar until you reach 100 different ones. Some may be time-gated or require specific conditions to trigger.", x = 7 },
        [13161] = { e = 2, s = "s", r = "Involves completing a reputation chain to unlock an allied race.", d = "Earn enough reputation with the Zandalari Troll faction to unlock their allied race. Follow the main questline and complete daily activities to reach the required standing.", x = 7 },
        [13163] = { e = 2, s = "s", r = "Involves completing a reputation chain to unlock an allied race.", d = "Gain sufficient reputation with the Kul Tiran faction to unlock their allied race. Engage in world quests and faction-specific content to accelerate your progress.", x = 7 },
        [13186] = { e = 4, s = "g", r = "Requires winning brawls in a guild hall with specific rules.", d = "This achievement requires winning a Brawler's Guild brawl during Season 3. Since the guild is no longer active in retail, this legacy title cannot be earned now and is already owned by all current players.", x = 7 },
        [13188] = { e = 4, s = "g", r = "Requires winning brawls in a guild hall with specific rules.", d = "Like the previous entry, this requires winning a brawl during Season 3. As the Brawler's Guild has been removed from the game, this achievement is unobtainable in the current retail version of World of Warcraft.", x = 7 },
        [13189] = { e = 4, s = "g", r = "Requires reaching rank 4 in Brawlpub through repeated wins.", d = "You must reach Rank 4 with Bizmo's Brawlpub to complete this. Since the Brawler's Guild content is no longer available, you cannot earn these ranks or unlock the associated rewards in retail.", x = 7 },
        [13190] = { e = 4, s = "g", r = "Requires reaching rank 4 in Brawl'gar Arena through repeated wins.", d = "This requires reaching Rank 4 with Brawl'gar Arena, which is part of the defunct Brawler's Guild. You cannot complete this achievement now as the necessary game content has been removed from retail.", x = 7 },
        [13191] = { e = 2, s = "g", r = "Grinding Brawlpub to Rank 8 takes an hour or two.", d = "Reaching Rank 8 with Bizmo's Brawlpub grants the title 'Brawler', but this is impossible in retail. The entire Brawler's Guild system was shut down years ago, making these legacy achievements unobtainable.", x = 7 },
        [13192] = { e = 2, s = "g", r = "Grinding Brawl'gar Arena to Rank 8 takes an hour or two.", d = "Similar to the others, reaching Rank 8 with Brawl'gar Arena is required but impossible. The Brawler's Guild no longer exists in retail World of Warcraft, so you cannot earn this achievement or its rewards.", x = 7 },
        [13194] = { e = 3, s = "c", r = "Requires random brawl modes; RNG makes it moderate to hard.", d = "This account-wide achievement requires defeating bosses in random brawl mode using Thrall's legplates. Since the Brawler's Guild is gone, you cannot complete this challenge or obtain the associated legacy title.", x = 7 },
        [13206] = { e = 3, s = "g", r = "Gaining Vulpera allegiance requires significant reputation grinding.", d = "Unlock the Vulpera allied race first to start this chain. You must earn allegiance from Vol'dun vulpera and welcome them into the Horde to unlock the race for your account.", x = 7 },
        [13250] = { e = 4, s = "c", h = { 79818, 71466, 81488 }, r = "Requires completing multiple major Pathfinder and exploration achievements.", d = "Complete all listed Battle for Azeroth exploration achievements first, including exploring Nazjatar and Mechagon. Once those are done, finish the Kul Tiras and Zandalar requirements to unlock the Wonderwing 2.0 mount.", x = 7 },
        [13251] = { e = 3, s = "s", r = "Completing a specific storyline quest chain takes a few hours.", d = "Start the Tyrande's Ascension storyline in Teldrassil immediately after unlocking Night Warrior customization options. Follow the quest chain carefully to complete the storyline and earn your custom appearance.", x = 7 },
        [13263] = { e = 3, s = "s", r = "Completing a specific quest chain requires some time and effort.", d = "This achievement requires aiding Vol'jin in his search for answers, likely involving specific quests or world events. Check current zone content in Dazar'alor or Zandalar for relevant objectives related to the Shadow Hunter questline.", x = 7 },
        [13269] = { e = 2, s = "s", r = "Completing a pet battle challenge is straightforward but takes time.", d = "Complete the Pet Battle Challenge located in Gnomeregan to earn the Mini Spider Tank pet. Ensure you have a competitive team ready before entering the challenge arena to secure the reward.", x = 7 },
        [13270] = { e = 4, s = "g", r = "Grinding 15 Master Tamers with specific pets is a long task.", d = "Gather a full team of level 25 Beast pets before heading to Kul Tiras or Zandalar. Defeat the Master Tamers there, but note that Sizzik requires fifteen defeats and may be missable if you do not clear him quickly enough.", x = 7 },
        [13271] = { e = 4, s = "g", r = "Grinding 15 Master Tamers with specific pets is a long task.", d = "Assemble a team of level 25 Critter pets and travel to Kul Tiras or Zandalar. You must defeat the Master Tamers there; ensure you have at least one Critter pet that can survive Sizzik's fifteen encounters.", x = 7 },
        [13272] = { e = 4, s = "g", r = "Grinding 15 Master Tamers with specific pets is a long task.", d = "Build a team of level 25 Dragonkin pets and head to Kul Tiras or Zandalar. Defeat the Master Tamers in these zones, keeping in mind that Sizzik counts toward your total and must be defeated fifteen times.", x = 7 },
        [13273] = { e = 4, s = "g", r = "Grinding 15 Master Tamers with specific pets is a long task.", d = "Collect a team of level 25 Elemental pets and travel to Kul Tiras or Zandalar. Defeat the Master Tamers there, ensuring you have enough Elemental pets to handle Sizzik's fifteen encounters without failing.", x = 7 },
        [13274] = { e = 3, s = "g", r = "Grinding 15 specific tamer battles with Flying pets.", d = "Gather a team of level 25 Flying pets and go to Kul Tiras or Zandalar. Defeat the Master Tamers in these zones, but be prepared for Sizzik which requires fifteen defeats and can be missable if not cleared promptly.", x = 7 },
        [13275] = { e = 3, s = "g", r = "Grinding 15 specific tamer battles with Magic pets.", d = "Assemble a team of level 25 Magic pets and travel to Kul Tiras or Zandalar. Defeat the Master Tamers there, noting that Sizzik requires fifteen defeats and may be missable if you do not clear him quickly.", x = 7 },
        [13277] = { e = 3, s = "g", r = "Grinding 15 specific tamer battles with Mechanical pets.", d = "Build a team of level 25 Mechanical pets and head to Kul Tiras or Zandalar. Defeat the Master Tamers in these zones, ensuring you have enough Mechanical pets to handle Sizzik's fifteen encounters without failing.", x = 7 },
        [13278] = { e = 3, s = "g", r = "Grinding 15 specific tamer battles with Undead pets.", d = "Collect a team of level 25 Undead pets and travel to Kul Tiras or Zandalar. Defeat the Master Tamers there, keeping in mind that Sizzik counts toward your total and must be defeated fifteen times.", x = 7 },
        [13279] = { e = 4, s = "c", h = { 71785, 71787, 71788 }, r = "Requires completing multiple difficult pet battle grinds.", d = "Complete all other pet battle achievements listed here to unlock this one. This is a collection achievement requiring you to finish every specific pet type challenge first before claiming the reward.", x = 7 },
        [13280] = { e = 3, s = "g", r = "Grinding 15 specific tamer battles with Aquatic pets.", d = "Gather a full team of level 25 Aquatic pets before heading to Kul Tiras or Zandalar. Defeat the Master Tamers there, but note that Sizzik requires fifteen defeats and may be missable if you do not clear him quickly enough.", x = 7 },
        [13281] = { e = 3, s = "g", r = "Grinding 15 specific tamer battles with Humanoid pets.", d = "Assemble a team of level 25 Humanoid pets and travel to Kul Tiras or Zandalar. You must defeat the Master Tamers there; ensure you have at least one Humanoid pet that can survive Sizzik's fifteen encounters.", x = 7 },
        [13283] = { e = 4, s = "c", h = { 71853, 71856 }, r = "Requires completing six distinct Assault quests.", d = "Complete all six Alliance Assault quests to earn this achievement. These are time-gated content from Battle for Azeroth, so you must finish them while the Assaults are active and available in your region.", x = 7 },
        [13284] = { e = 4, s = "c", h = { 71859, 71860 }, r = "Requires completing six distinct Assault quests.", d = "Complete all six Horde Assaults in Zandalar to earn this title; ensure you finish every assault event before the expansion's content rotates or becomes unavailable. This is account-wide, so any character can contribute progress.", x = 7 },
        [13285] = { e = 3, s = "c", r = "Recruiting three specific citizens during one quest.", d = "Recruit three extra citizens during the specific 'Not Too Sober Citizens Brigade' quest by interacting with NPCs like Russel and Flynn. Do not miss this window as it is tied to a single quest instance and may reset or expire.", x = 7 },
        [13286] = { e = 4, s = "c", h = { 72115, 72116 }, r = "Requires defeating multiple raid bosses in a wing.", d = "Defeat all listed bosses in the Alliance wing of the Battle of Dazar'alor raid; start with lower difficulties if needed before attempting higher tiers. Progress carries over across characters on the same account.", x = 7 },
        [13287] = { e = 4, s = "c", h = { 72119, 72120 }, r = "Requires defeating multiple raid bosses in a wing.", d = "Clear the remaining bosses in the Alliance wing, including King Rastakhan, to complete this set. Ensure your group is prepared for the final encounter as it often requires specific mechanics.", x = 7 },
        [13288] = { e = 4, s = "c", h = { 72123, 72124, 72125 }, r = "Requires full raid wing completion; high RNG and difficulty.", d = "Witness the cinematic retellings of your allies' efforts by defeating all required bosses in the third wing of the raid. These achievements unlock after completing the previous wings.", x = 7 },
        [13289] = { e = 4, s = "c", h = { 72127, 72128, 72129 }, r = "Requires full raid wing completion; high RNG and difficulty.", d = "Defeat the Horde-specific bosses in the first wing of the Battle of Dazar'alor; these are distinct from the Alliance counterparts. Coordinate with your group to handle unique mechanics efficiently.", x = 7 },
        [13290] = { e = 4, s = "c", h = { 72131, 72132, 72133 }, r = "Requires full raid wing completion; high RNG and difficulty.", d = "Complete the second wing of the Horde raid by defeating Opulence and King Rastakhan among others. Be aware that some bosses may have different mechanics than their Alliance equivalents.", x = 7 },
        [13291] = { e = 4, s = "c", h = { 72135, 72136, 72137 }, r = "Requires full raid wing completion; high RNG and difficulty.", d = "Finish the third wing of the Horde raid by defeating Lady Jaina Proudmoore and Mekkatorque. This final set unlocks after clearing the previous wings in the same expansion.", x = 7 },
        [13292] = { e = 4, s = "s", r = "Mythic+ specific boss kill; requires high-level group play.", d = "Defeat Champion of the Light on Mythic difficulty to unlock this specific achievement; ensure your group is well-gearred for high-level content. Progress is account-wide but requires a single character to complete.", x = 7 },
        [13293] = { e = 4, s = "s", r = "Mythic+ specific boss kill; requires high-level group play.", d = "Take down Grong on Mythic difficulty, which demands precise execution and coordination from your entire raid group. Start with lower difficulties if you are new to this encounter.", x = 7 },
        [13294] = { e = 4, s = "c", h = { 72146, 72147, 72148 }, r = "Requires completing multiple major zone achievements.", d = "Complete all Loremaster achievements in Zandalar by finishing the associated continent-wide quests. This includes clearing major storylines across Boralus, Nazmir, and Zuldazar before moving forward.", x = 7 },
        [13295] = { e = 4, s = "s", r = "Mythic+ specific duo boss kill; requires high-level group play.", d = "Defeat Mestrah and Manceroy Flamefist on Mythic difficulty as a duo; this requires two players working together in the raid instance. Ensure both characters are ready for high-level combat challenges.", x = 7 },
        [13296] = { e = 4, s = "s", r = "Requires completing a full Warfront campaign.", d = "Queue for the Horde Warfront in Battle for Darkshore and complete the main scenario. Ensure you finish the entire warfront chain to unlock this specific completion achievement.", x = 7 },
        [13297] = { e = 4, s = "s", r = "Requires completing a full Warfront campaign.", d = "Queue for the Alliance Warfront in Battle for Darkshore and complete the main scenario. Finish the full warfront sequence to claim this completion title.", x = 7 },
        [13298] = { e = 4, s = "s", r = "Mythic+ specific duo boss kill; requires high-level group play.", d = "Form a Mythic duo group with an eligible friend to defeat Ma'ra Grimfang and Anathos Firecaller in Battle of Dazar'alor. This requires the Alliance Mythic Duo prerequisite achievement.", x = 7 },
        [13299] = { e = 4, s = "s", r = "Mythic+ specific boss kill; requires high-level group play.", d = "Gather a Mythic group to defeat Opulence in Battle of Dazar'alor as a Treasure Guardian. You must first complete the Mythic Treasure Guardian prerequisite achievement.", x = 7 },
        [13300] = { e = 4, s = "c", r = "Requires prior Mythic raid completion and group coordination.", d = "Assemble a Mythic party to defeat Conclave of the Chosen in Battle of Dazar'alor. Ensure you have the Mythic Loa Council prerequisite before starting.", x = 7 },
        [13301] = { e = 2, s = "g", r = "Capture any location; shrinks steadily as count rises.", d = "Queue for the Horde Warfront and capture any single location listed in the info to progress. This unlocks the next stage of the Darkshore warfront chain.", x = 7 },
        [13302] = { e = 2, s = "g", r = "Capture any location; shrinks steadily as count rises.", d = "Queue for the Alliance Warfront and capture any single location listed in the info to progress. Capturing one spot advances you toward the full capture goal.", x = 7 },
        [13305] = { e = 4, s = "c", h = { 72181 }, r = "Requires capturing all locations; hardest is Bashal'Aran.", d = "Capture every specific location listed for your faction while holding the Under Cover of Darkness prerequisite. Note this is account-wide and requires completing all previous steps.", x = 7 },
        [13306] = { e = 4, s = "c", h = { 72189 }, r = "Requires capturing all locations; hardest is Bashal'Aran.", d = "Capture every specific location listed for your faction while holding the Under Cover of Darkness prerequisite. This account-wide achievement requires full completion of prior warfront goals.", x = 7 },
        [13307] = { e = 4, s = "c", h = { 72197 }, r = "Requires recruiting all troops; hardest is Forsaken Alchemist.", d = "Recruit one unit of each troop type listed in the info during the Horde Warfront. Remember this is account-wide and tracks all unique recruitments.", x = 7 },
        [13308] = { e = 4, s = "c", h = { 72203 }, r = "Requires recruiting all troops; hardest is Kaldorei Archer.", d = "Recruit one unit of each troop type listed in the info during the Alliance Warfront. Track every unique recruit as this achievement is account-wide.", x = 7 },
        [13309] = { e = 4, s = "c", h = { 72209 }, r = "Requires embodying all heroes; hardest is Banshee.", d = "Embody every specific hero listed in the info while playing the Horde Warfront. This account-wide goal requires you to transform into each unique hero unit.", x = 7 },
        [13310] = { e = 4, s = "c", h = { 72213 }, r = "Requires embodying all heroes; hardest is Dryad.", d = "Queue for the Darkshore Warfront repeatedly until you defeat every Alliance hero listed in the info field. This is account-wide, so ensure your main character completes it first before alts can progress.", x = 7 },
        [13311] = { e = 4, s = "s", r = "Defeat boss on Mythic; requires prior raid completion.", d = "You must complete the base raid achievements and obtain the specific Mythic Rastakhan achievement prerequisite listed in the info. Once unlocked, run the boss on Mythic difficulty to claim the points.", x = 7 },
        [13312] = { e = 4, s = "s", r = "Defeat boss on Mythic; requires prior raid completion.", d = "First secure the Mythic Mekkatorque achievement requirement from the info field, then defeat Gelbin on Mythic difficulty. This is a standard raid progression task with no special time gates.", x = 7 },
        [13313] = { e = 4, s = "s", r = "Defeat boss on Mythic; requires prior raid completion.", d = "Defeat Stormwall Blockade on Mythic after obtaining the required Mythic Sea Priest Blockade achievement from the info. Treat this as a standard boss kill within the Battle of Dazar'alor raid.", x = 7 },
        [13314] = { e = 5, s = "s", r = "Requires Mythic raid clear and specific loot.", d = "Queue for Lady Jaina Proudmoore on Mythic difficulty once you have the prerequisite Mythic Jaina achievement from the info. Completing this grants the Hero of Dazar'alor title automatically.", x = 7 },
        [13315] = { e = 5, s = "c", h = { 72261, 72310, 72334 }, r = "Needs full raid clears plus rare mechanics/events.", d = "Complete all nine specific sub-achievements listed in the info field to unlock this 25-point summary achievement. Ensure your account has earned every single prerequisite before claiming the mount reward.", x = 7 },
        [13316] = { e = 4, s = "g", r = "Requires stealing shinies from multiple bosses.", d = "Steal three shinies from each Crusader, Disciple, and Champion of the Light on Normal or higher difficulty first. Only after meeting these theft counts can you defeat the final champion to earn points.", x = 7 },
        [13317] = { e = 2, s = "c", h = { 72231 }, r = "Simple world event drops in active zones.", d = "Enable War Mode and loot secret supply chests in all six zones listed in the info field during active Assaults. This is account-wide, so coordinate with friends to cover different zones efficiently.", x = 7 },
        [13325] = { e = 4, s = "s", r = "Requires specific raid mechanics on Mythic/Normal.", d = "Run the Conclave of the Chosen on Normal or higher difficulty without killing the initial raptors summoned by Gonk's Wrath. Watch your damage output carefully during the first phase to avoid triggering the kill condition.", x = 7 },
        [13340] = { e = 2, s = "g", r = "Simple world event interaction in Zandalar.", d = "Travel to Zandalar zones listed in the info and interact with the flame mechanics to honor them. This is account-wide, so one player can complete it for everyone on the account.", x = 7 },
        [13341] = { e = 2, s = "g", r = "Simple world event interaction in Kul Tiras.", d = "Visit Kul Tiras zones listed in the info and honor the flames there. Since this is account-wide, you only need to visit these locations once with War Mode active.", x = 7 },
        [13342] = { e = 2, s = "g", r = "Simple world event interaction in Kul Tiras.", d = "Travel to Kul Tiras zones listed in the info and desecrate the Alliance bonfires. This is account-wide, so ensure you are in War Mode before interacting with any of the listed locations.", x = 7 },
        [13343] = { e = 2, s = "g", r = "Simple world event interaction in Zandalar.", d = "Travel to Zuldazar, Nazmir, and Vol'dun to desecrate all Horde bonfires. This is account-wide, so coordinate with friends if you lack a full group. Ensure no bonfires remain active before finishing.", x = 7 },
        [13345] = { e = 4, s = "s", r = "Requires specific raid mechanics and buffs.", d = "Start the raid on Normal or higher difficulty and locate the Singing Sunflower mechanic. Defeat the Opulence boss immediately after praising the flower while under Brilliant Aura.", x = 7 },
        [13383] = { e = 4, s = "g", r = "Requires destroying barrels before defeating boss.", d = "Enter the Battle of Dazar'alor raid and destroy six barrels before engaging Grong. Do not start the fight until you have cleared all barrels to trigger the achievement.", x = 7 },
        [13384] = { e = 2, s = "s", r = "Simple quest completion in War Campaign.", d = "Join the Alliance War Campaign in Kul Tiras and complete the specific quest Express Delivery. This is a timed event, so check current campaign availability before starting.", x = 7 },
        [13385] = { e = 4, s = "c", r = "Requires collecting a full set on one class; moderate RNG.", d = "Defeat all raid bosses in Battle of Dazar'alor to unlock Tier 23 armor pieces. Equip the full set on at least one character to claim the appearance achievement.", x = 7 },
        [13387] = { e = 4, s = "c", h = { 72405, 72406, 72407 }, r = "Requires completing all six Alliance Assaults in War Mode.", d = "Enable War Mode and complete every single Alliance Assault objective listed in your info. You must finish all six assaults before the event ends or you miss out.", x = 7 },
        [13388] = { e = 4, s = "c", h = { 72412, 72413, 72414 }, r = "Requires completing all six Horde Assaults in War Mode.", d = "Enable War Mode and complete every single Horde Assault objective listed in your info. Coordinate with friends to cover all required objectives efficiently.", x = 7 },
        [13389] = { e = 3, s = "g", r = "Requires winning an expedition; moderate difficulty and RNG.", d = "Queue for Island Expeditions targeting Jorundall until you secure a victory on any difficulty. This unlocks the next tier of the achievement chain.", x = 7 },
        [13394] = { e = 5, s = "g", r = "Heroic/Mythic Island Expeditions require high skill and RNG.", d = "First complete the normal version of Jorundall, then queue specifically for Heroic difficulty to win. You cannot attempt this without clearing the previous tier first.", x = 7 },
        [13395] = { e = 5, s = "g", r = "Mythic difficulty requires top-tier gear and coordination.", d = "Clear both Normal and Heroic versions of Jorundall before attempting Mythic difficulty. Winning on Mythic will grant the final point in this chain.", x = 7 },
        [13396] = { e = 3, s = "g", r = "Requires winning an expedition; moderate difficulty and RNG.", d = "Queue for Island Expeditions targeting Havenswood until you achieve a victory on any difficulty. This is required to unlock the Heroic version of the island.", x = 7 },
        [13397] = { e = 5, s = "g", r = "Heroic/Mythic Island Expeditions require high skill and RNG.", d = "Complete Normal and Heroic Havenswood expeditions before attempting Mythic difficulty. Ensure you have cleared all prior tiers to access this final challenge.", x = 7 },
        [13398] = { e = 5, s = "g", r = "Mythic difficulty requires top-tier gear and coordination.", d = "Complete the Havenswood Mythic expedition by defeating all enemies and securing victory. Ensure you have unlocked the required island content first, as this is a time-gated achievement that cannot be earned before unlocking the zone.", x = 7 },
        [13399] = { e = 4, s = "g", r = "PvP victory requires finding a team and winning matches.", d = "Participate in Jorundall PvP expeditions and win matches to earn points. This requires completing the base island content first; note that you must actively engage in PvP battles rather than just surviving.", x = 7 },
        [13400] = { e = 4, s = "g", r = "PvP victory requires finding a team and winning matches.", d = "Win Havenswood expeditions specifically in a PvP environment. Unlike the Mythic version, this requires engaging enemy players directly, so coordinate with your group to focus fire on opposing teams.", x = 7 },
        [13401] = { e = 5, s = "s", r = "Requires defeating raid boss after another on Normal+.", d = "Defeat High Tinker Mekkatorque after killing Blingtron MK2 on Normal or higher difficulty. This is a sequential requirement within the Battle of Dazar'alor raid, so ensure you clear the prerequisite boss before attempting the final encounter.", x = 7 },
        [13402] = { e = 4, s = "g", r = "Grinding 50 PvP kills during specific assaults is time-consuming.", d = "Kill 50 Horde players during Assault on Kul Tiras or Zandalar. This is account-wide and requires participating in specific World Quests where PvP combat is enabled against opposing faction players.", x = 7 },
        [13403] = { e = 4, s = "g", r = "Grinding 50 PvP kills during specific assaults is time-consuming.", d = "Kill 50 Alliance players during Assault on Kul Tiras or Zandalar. Like the Horde version, this tracks account-wide kills during designated World Quests where PvP is active against the opposing faction.", x = 7 },
        [13410] = { e = 2, s = "s", r = "Requires one specific mechanic during a raid fight.", d = "Build a Frosty Snowmon and destroy it before defeating Lady Jaina Proudmoore on Normal or higher. This requires precise timing during the raid encounter to eliminate your own pet before the boss is defeated.", x = 7 },
        [13414] = { e = 3, s = "c", h = { 72461, 72462 }, r = "Requires defeating two specific raid bosses.", d = "Defeat both The Restless Cabal and Uu'nat, Harbinger of the Void in Crucible of Storms. This achievement tracks account-wide progress, so coordinate with your group to clear these specific shrine raid bosses.", x = 7 },
        [13416] = { e = 5, s = "s", r = "Mythic difficulty adds significant complexity and coordination.", d = "Defeat The Restless Cabal on Mythic difficulty within Crucible of Storms. Ensure you have unlocked the Mythic version of this shrine raid and are prepared for the increased challenge compared to Normal or Heroic.", x = 7 },
        [13417] = { e = 5, s = "s", r = "Mythic difficulty adds significant complexity and coordination.", d = "Defeat Uu'nat, Harbinger of the Void on Mythic difficulty in Crucible of Storms. This requires unlocking the Mythic shrine raid content and successfully clearing the boss under higher difficulty settings.", x = 7 },
        [13425] = { e = 4, s = "s", r = "Requires precise execution to keep all Phantoms alive.", d = "Defeat King Rastakhan while keeping all three Phantoms alive on Normal or higher. Manage your group's focus to avoid killing the summoned Phantoms of Rage, Retribution, and Slaughter during the fight.", x = 7 },
        [13426] = { e = 2, s = "g", r = "Killing 20 targets with a single ability is quick but requires setup.", d = "Kill 20 sin'dorei with a single Rising Tide cast during the Nazmir Assault World Quest. Use the water elemental vehicle to maximize damage output in one ability cast against the specific enemy type.", x = 7 },
        [13429] = { e = 3, s = "c", h = { 72518 }, r = "Requires killing 5 players while debuffed; RNG on flare duration.", d = "Find an Unstable Azerite Flare effect and engage PvP immediately to kill five opponents. This is time-gated as the flare effect expires quickly, so do not delay once active.", x = 7 },
        [13430] = { e = 3, s = "s", r = "Requires fishing up a specific mount before defeating the boss.", d = "Fish up De Lurker Be'loa before entering Stormwall Blockade on Normal or higher difficulty. Ensure the pet stays alive during the fight to avoid missing the achievement.", x = 7 },
        [13431] = { e = 2, s = "s", r = "Hatching an egg during a fight is a single mechanic check.", d = "Hatch the cloud serpent egg during Jadefire Masters in Battle of Dazar'alor on Normal difficulty or higher. This requires specific encounter timing and cannot be done on lower difficulties.", x = 7 },
        [13433] = { e = 2, s = "s", r = "Collecting armor sets from existing content is straightforward.", d = "Collect any full armor set from PvP Season 27 or the Darkshore Warfront to complete this collection. Check your inventory for missing pieces from these specific sources.", x = 7 },
        [13435] = { e = 2, s = "s", r = "Single world quest completion with specific enemy.", d = "Complete the Drustvar Assault world quest Lights Out using a single Doomsoul unit. Ensure you do not spawn additional units during the encounter.", x = 7 },
        [13437] = { e = 2, s = "s", r = "Single world quest with costume requirement.", d = "Equip Vulpera appearance gear and complete the Vol'dun Assault world quest Vulpera for a Day. Finish the digsite while maintaining the disguise throughout.", x = 7 },
        [13438] = { e = 3, s = "g", r = "Requires War Mode and specific PvP encounter.", d = "Start Zuldazar Assault Crate n' Barrel in War Mode and kill Burly Deckhands without losing your Extra Buff Peon. Protect your peon from enemy attacks during the fight.", x = 7 },
        [13439] = { e = 3, s = "g", r = "Requires War Mode and specific PvP encounter.", d = "Begin Zuldazar Assault Crate n' Barrel in War Mode and kill Extra Buff Peons while keeping your Burly Deckhand alive. Focus on defending your deckhand from incoming damage.", x = 7 },
        [13440] = { e = 2, s = "g", r = "Kill 6 enemies during a single world quest.", d = "Complete Stack on the Tank assault world quest by killing six enemies before the timer runs out. Coordinate with your group to maximize kill speed.", x = 7 },
        [13441] = { e = 2, s = "g", r = "Kill 6 enemies during a single world quest.", d = "Finish Get On The Payload assault world quest by slaying six enemies within the time limit. Prioritize high-value targets to quickly meet the kill count.", x = 7 },
        [13466] = { e = 4, s = "c", h = { 78416, 79561 }, r = "Campaign requires multiple steps and rare drops.", d = "Complete all Tides of Vengeance war campaign quests listed in the info field to earn this achievement. Progress through the campaign sequentially to unlock each required objective.", x = 7 },
        [13467] = { e = 4, s = "c", h = { 78421, 78424 }, r = "Campaign requires multiple steps and rare drops.", d = "Finish the remaining Tides of Vengeance war campaign quests shown in the info field for full completion. Ensure you have completed all prior campaign steps before starting these final objectives.", x = 7 },
        [13469] = { e = 5, s = "g", r = "Collecting many pets from raids is a long grind.", d = "Farm pets from Mogu'shan Vaults through Heart of Fear; this is a time-gated achievement requiring the full Mists of Pandaria raid content. Ensure you have all necessary mounts and flight paths before starting to avoid missing any rare drops.", x = 7 },
        [13470] = { e = 5, s = "c", h = { 79764, 79765 }, r = "Killing all rares and bosses in Mechagon is hard.", d = "Complete special encounters in Mechagon by killing specific rares; this is a time-gated achievement requiring the Battle for Azeroth expansion. Use group play to efficiently clear all listed targets before the zone becomes inaccessible.", x = 7 },
        [13472] = { e = 4, s = "g", r = "Contribute 250 times to construction projects.", d = "Contribute 1,000 times to Mechagon construction projects; this is a time-gated achievement requiring the Battle for Azeroth expansion. Simply donate gold or materials frequently while exploring the zone to reach the count quickly.", x = 7 },
        [13473] = { e = 3, s = "c", h = { 78508 }, r = "Building specific turrets requires rare drops.", d = "Complete specific construction projects in Mechagon after unlocking the Junkyard Machinist title; this is a time-gated achievement requiring the Battle for Azeroth expansion. Focus on building the listed structures like the Flame Turret and Drill Rig.", x = 7 },
        [13474] = { e = 4, s = "g", r = "Grinding 100 construction projects takes days.", d = "Complete 100 construction projects in Mechagon; this is a time-gated achievement requiring the Battle for Azeroth expansion. Contribute to any available construction projects repeatedly until you reach the required count.", x = 7 },
        [13475] = { e = 3, s = "g", r = "Crafting 50 items is a moderate grind.", d = "Craft 250 Junkyard Tinkering items excluding crates; this is a time-gated achievement requiring the Battle for Azeroth expansion. Start by unlocking the Junkyard Scavenger title and focus on crafting non-crate items.", x = 7 },
        [13476] = { e = 4, s = "g", r = "Crafting 1000 items requires significant time.", d = "Craft 1,000 Junkyard Tinkering items excluding crates after reaching Junkyard Apprentice; this is a time-gated achievement requiring the Battle for Azeroth expansion. Continue crafting high-volume items like scrap grenades or traps to meet the goal.", x = 7 },
        [13477] = { e = 3, s = "g", r = "Crafting 250 items is a moderate grind.", d = "Craft 50 Junkyard Tinkering items excluding crates; this is a time-gated achievement requiring the Battle for Azeroth expansion. Unlock the Junkyard Scavenger title first and craft simple items to reach the count.", x = 7 },
        [13478] = { e = 3, s = "c", r = "Unlocking 20 blueprints involves RNG and crafting.", d = "Unlock 20 specific Junkyard Tinkering blueprints in Mechagon; this is a time-gated achievement requiring the Battle for Azeroth expansion. Explore the junkyard thoroughly and purchase or unlock blueprints from vendors to complete the list.", x = 7 },
        [13479] = { e = 3, s = "c", r = "Unlocking 30 blueprints involves RNG and crafting.", d = "Unlock 30 specific Junkyard Tinkering blueprints after reaching Junkyard Collector; this is a time-gated achievement requiring the Battle for Azeroth expansion. Continue exploring and purchasing remaining blueprints to finish the collection.", x = 7 },
        [13482] = { e = 4, s = "g", r = "Contributing 10,000 times is a long grind.", d = "Contribute 10,000 times to Mechagon construction projects after reaching Head Financier of Mechagon; this is a time-gated achievement requiring the Battle for Azeroth expansion. Donate gold or materials frequently while exploring the zone to reach the massive count.", x = 7 },
        [13489] = { e = 2, s = "c", r = "Catching 11 specific fish is an easy checklist.", d = "Catch and deliver each Secret Fish of Mechagon to Angler Danielle; this is a time-gated achievement requiring the Battle for Azeroth expansion. Fish in specific locations within Mechagon and ensure you have enough space in your bag or use a pet bag.", x = 7 },
        [13501] = { e = 4, s = "s", r = "Requires high-level raid content and RNG.", d = "Defeat the Restless Cabal in Crucible of Storms Normal+ while keeping at least 10 Void Crashes active simultaneously. Coordinate with your group to maintain the crash count throughout the entire encounter, as dropping below ten will reset progress.", x = 7 },
        [13502] = { e = 3, s = "c", r = "Catching all secret fish is a moderate grind.", d = "Equip Secret Fish Goggles and fish in all zones to collect every secret fish listed in the achievement info. This is account-wide, so one character can complete it for everyone, but be patient as some fish are rare drops or require specific locations.", x = 7 },
        [13503] = { e = 2, s = "s", r = "Leveling a new character to 50 is easy.", d = "Create a new Zandalari Troll character and level them to 50 to unlock the heritage armor. Ensure you have already unlocked the allied race prerequisite before starting this process on your account.", x = 7 },
        [13504] = { e = 2, s = "s", r = "Leveling a new character to 50 is easy.", d = "Create a new Kul Tiran character and level them to 50 to claim the heritage armor. Like other heritage armors, this is account-wide once the level requirement is met on any character of that race.", x = 7 },
        [13506] = { e = 4, s = "s", r = "High-skill raid boss fight with strict stealth mechanics.", d = "Defeat Uu'nat in Crucible of Storms Normal+ without letting N'Zoth see your movement. Avoid standing in his line of sight during the fight, as being seen will cause the achievement to fail immediately.", x = 7 },
        [13512] = { e = 2, s = "c", r = "Short world quest repeated three times with low RNG.", d = "Complete the world quest Calligraphy multiple times until you master all three shapes: circle, square, and triangle. Never deviate from the lines during any attempt, as a single mistake resets your progress for that shape.", x = 7 },
        [13513] = { e = 4, s = "g", r = "Requires collecting all eight colors via random drops.", d = "Collect all eight paint colors for the X-995 Mechanocat mount by completing various activities across Azeroth. This is account-wide, so gather colors on one character to unlock them for everyone in your group.", x = 7 },
        [13516] = { e = 2, s = "s", r = "Craft one item from any of the eight professions.", d = "Craft a Tool of the Trade item from any primary profession like Alchemy or Engineering. You do not need to max out the item; simply crafting one instance of the specific tool listed for your chosen profession is sufficient.", x = 7 },
        [13517] = { e = 4, s = "c", h = { 79433 }, r = "Requires completing major faction storylines across continents.", d = "Complete the four specified achievements on Zandalar and Kul Tiras to earn both mounts. These are likely time-gated by content availability, so ensure you have access to the relevant zones before starting.", x = 7 },
        [13541] = { e = 4, s = "s", r = "High-difficulty dungeon with strict avoidance mechanics.", d = "Finish all listed Mechagon achievements, including exploration and crafting tasks. Many of these require specific items or locations within Mechagon Bay, so explore thoroughly and check your inventory for missing collectibles.", x = 7 },
        [13542] = { e = 2, s = "c", r = "Complete a series of short training quests in Zuldazar.", d = "Complete the direhorn training quests in Zuldazar to raise it from hatchling to mount. Follow the quest chain sequentially at Warbeast Kraal, ensuring you complete each step like feeding and sleeping before advancing.", x = 7 },
        [13545] = { e = 4, s = "s", r = "Mythic dungeon with strict avoidance of multiple hazards.", d = "Defeat Machinist's Garden in Operation: Mechagon Mythic without taking damage from specific mechanics like Hidden Flame Cannon or Roaring Flame. This requires precise positioning and timing to avoid the listed hazards during the entire encounter.", x = 7 },
        [13549] = { e = 2, s = "g", r = "Locate and open chests/trunks scattered across Nazjatar.", d = "Start by clearing Nazjatar zones to unlock chests, then use Arcane Chests and Glowing Arcane Trunks in specific areas. Check your map for glowing markers as they appear after defeating local bosses or completing quests.", x = 7 },
        [13553] = { e = 3, s = "c", r = "Complete the main Mechagon storyline with several steps.", d = "Begin the Mechagon storyline immediately upon entering the zone to avoid missing early quest chains. Complete all main story quests sequentially, ensuring you finish 'The Legend of Mechagon' first to unlock subsequent steps.", x = 7 },
        [13555] = { e = 4, s = "c", h = { 80061 }, r = "Requires completing multiple visitor quests and a raid boss.", d = "Finish the main Mechagon storyline before tackling visitor quests or side content for this achievement. Ensure you have completed all required sub-achievements like 'Junkyard Tinkerer' and 'Head Financier of Mechagon'.", x = 7 },
        [13556] = { e = 3, s = "g", r = "Complete 15 specific visitor quests in Mechagon.", d = "Talk to visitor NPCs in Mechagon to accept their quests, then complete them in any order once the main story is done. Aim for 15 total quests from these visitors, including repeatable ones if needed.", x = 7 },
        [13557] = { e = 4, s = "g", r = "Requires Exalted reputation grind.", d = "Earn Exalted with the Rustbolt Resistance by completing faction quests and defeating enemies in Nazjatar. Focus on high-level content to gain reputation quickly while exploring the zone.", x = 7 },
        [13558] = { e = 4, s = "g", r = "Requires Exalted reputation grind.", d = "Complete Ankoan quests in Nazjatar to reach Exalted status with the Waveblade Ankoan. Defeat key NPCs and complete daily objectives for efficient reputation gains.", x = 7 },
        [13559] = { e = 4, s = "g", r = "Requires Exalted reputation grind.", d = "Finish Unshackled quests in Nazjatar to earn Exalted status. Prioritize main story quests and faction-specific tasks to maximize reputation progress efficiently.", x = 7 },
        [13568] = { e = 3, s = "s", r = "Win a single PvP battle.", d = "Coordinate with your raid group to win the Battle for Nazjatar event, which requires defeating all bosses within a time limit. Ensure everyone is ready and positioned correctly before starting the event.", x = 7 },
        [13569] = { e = 4, s = "g", r = "Grind honor in War Mode.", d = "Enable War Mode and spend time in Nazjatar PvP zones to earn honor. Engage in world PvP activities or join group battles to accumulate 1000 honor quickly.", x = 7 },
        [13570] = { e = 4, s = "g", r = "Grind honor in War Mode.", d = "Activate War Mode and explore Mechagon while engaging in PvP encounters to gain honor. Participate in arena matches or open-world combat to reach the 1000 honor goal.", x = 7 },
        [13571] = { e = 4, s = "s", r = "Requires raiding Tier 24 content.", d = "Collect a full Tier 24 armor set from The Eternal Palace on at least one character. Defeat bosses in the raid to obtain pieces and complete the set for this achievement.", x = 7 },
        [13572] = { e = 2, s = "s", r = "Simple unlock after repairs.", d = "Repair the Chamber of Heart by completing related quests, then unlock the Heart Forge inside. Follow quest markers carefully to ensure all prerequisites are met before accessing the forge.", x = 7 },
        [13573] = { e = 2, s = "s", r = "Complete a specific quest chain.", d = "Start by visiting Kua'fon in Zuldazar to begin the Pterrordax training quest chain immediately, as this content is time-gated to the Battle for Azeroth expansion era. Ensure you have access to the required zones before attempting to help him earn his wings.", x = 7 },
        [13577] = { e = 4, s = "g", r = "Grind Island Expeditions victory.", d = "Queue for Island Expeditions targeting Crestfall on Normal difficulty first to unlock the base achievement and progress toward harder versions. Be prepared for random group composition since these are account-wide activities that require a full team.", x = 7 },
        [13578] = { e = 4, s = "g", r = "Grind Heroic difficulty expeditions.", d = "Unlock this by completing the standard Crestfall victory, then queue specifically for Heroic difficulty where enemy health pools and mechanics increase significantly. This step is mandatory before attempting the Mythic version or PvP variant.", x = 7 },
        [13579] = { e = 5, s = "g", r = "Grind Mythic difficulty expeditions.", d = "Achieve a win on Heroic Crestfall first to unlock access to Mythic difficulty, which features tougher enemies and higher rewards. Coordinate with your group carefully as failure resets progress for the entire team.", x = 7 },
        [13580] = { e = 2, s = "s", r = "Single expedition victory; requires group coordination.", d = "Join an Island Expedition queue set to PvP mode specifically for Crestfall to earn this victory-based achievement. Note that standard PvE wins do not count toward this specific PvP requirement.", x = 7 },
        [13581] = { e = 2, s = "s", r = "Single expedition victory; requires group coordination.", d = "Begin with Snowblossom Village on Normal difficulty to unlock the location and progress through its difficulty tiers. This island offers unique mechanics distinct from other expedition locations like Crestfall.", x = 7 },
        [13582] = { e = 4, s = "s", r = "Heroic difficulty requires skilled group and RNG.", d = "Complete the base Snowblossom Village victory before attempting Heroic difficulty, which introduces stronger enemies and more complex objectives. Plan your team composition carefully as higher difficulties demand better gear and coordination.", x = 7 },
        [13583] = { e = 5, s = "s", r = "Mythic difficulty is extremely hard for a new player.", d = "Unlock Mythic Snowblossom Village only after defeating the Heroic version, ensuring your group is prepared for maximum difficulty challenges. This final tier requires optimal strategy and communication to secure victory against elite foes.", x = 7 },
        [13584] = { e = 2, s = "s", r = "Single PvP expedition victory; requires group coordination.", d = "Queue specifically for PvP mode in Snowblossom Village rather than standard PvE expeditions to earn this achievement. Standard victories on any difficulty will not fulfill the specific PvP requirement listed here.", x = 7 },
        [13585] = { e = 4, s = "g", r = "Grinding for a full set of PvP armor is time-consuming.", d = "Collect all armor pieces from Battle for Azeroth PvP Season 3 sets, which are account-wide and include both Alliance and Horde gear. Focus on acquiring these items through PvP activities or seasonal rewards during that specific expansion period.", x = 7 },
        [13623] = { e = 4, s = "c", h = { 80952 }, r = "Killing 50 players in Mechagon is the hardest checklist item.", d = "Complete multiple World PvP activities including killing players in Nazjatar and Mechagon while earning Battle Commendations. This achievement is account-wide, so coordinate with friends across factions to maximize progress efficiently.", x = 7 },
        [13624] = { e = 5, s = "s", r = "Mythic raid content requires high skill and coordination.", d = "Prevent all destruction of non-robotic life during Operation: Mechagon on Mythic difficulty by managing adds and protecting civilians throughout the dungeon run. Coordinate with your group to prioritize defense objectives over damage dealing when necessary.", x = 7 },
        [13625] = { e = 4, s = "c", h = { 80465 }, r = "Defeating specific legendary pets is a long grind.", d = "Defeat all listed mechanized minions on Mechagon Island, ensuring you have the required legendary pets if needed. This is account-wide and requires no specific group composition beyond standard pet battle rules.", x = 7 },
        [13626] = { e = 4, s = "s", r = "Pet battle challenge requires high skill and luck.", d = "Clear Nazjatar to defeat the deep sea terrors listed in the achievement info. Ensure you have the necessary Nazjatar legendary pets before attempting these battles.", x = 7 },
        [13627] = { e = 4, s = "s", r = "Pet battle challenge requires high skill and luck.", d = "Complete the Stratholme Pet Battle Challenge solo or with a group, as it awards the Evil Wizard Hat pet upon success.", x = 7 },
        [13628] = { e = 4, s = "g", r = "Collecting 50 samples is a grind; final boss is hard.", d = "Collect 50 sea life samples in Darkest Depths on Normal difficulty before defeating Blackwater Behemoth in The Eternal Palace. This is a time-gated collection process.", x = 7 },
        [13629] = { e = 4, s = "s", r = "Requires specific raid mechanics and high-level gear.", d = "Defeat Lady Ashvane in The Eternal Palace while ensuring Arcing Azerite passes through her multiple times on Normal or higher difficulty.", x = 7 },
        [13633] = { e = 4, s = "c", r = "Needs rare emote drops and a full raid clear.", d = "Perform required emotes to earn Queen Azshara's Favor before defeating The Queen's Court on Normal difficulty or higher in The Eternal Palace.", x = 7 },
        [13635] = { e = 4, s = "c", r = "Many Nazjatar objectives including world bosses and allies.", d = "Complete various Nazjatar objectives including emissaries, world bosses, and ally leveling. This achievement is account-wide and requires diverse exploration activities.", x = 7 },
        [13638] = { e = 4, s = "c", r = "Requires completing numerous other Nazjatar achievements.", d = "Finish all listed Nazjatar achievements to unlock the Of The Deeps title and Snapback Scuttler mount. This includes completing questlines and exploring the zone thoroughly.", x = 7 },
        [13645] = { e = 3, s = "g", r = "Grinding XP with Unshackled allies takes time.", d = "Gain 4800 experience with Unshackled allies by engaging in combat or completing activities that grant XP to your team.", x = 7 },
        [13684] = { e = 4, s = "s", r = "Difficult raid boss fight requiring specific conditions.", d = "Defeat Abyssal Commander Sivara in The Eternal Palace while keeping all three lieutenants alive and engaged during the fight on Normal difficulty or higher.", x = 7 },
        [13686] = { e = 2, s = "c", r = "Collecting tracks is easy once the gramophone is unlocked.", d = "Unlock the Rustbolt Gramophone and its tracks by completing specific Mechagon achievements like Ode to Tinkertown and Gnomeregan Forever.", x = 7 },
        [13687] = { e = 4, s = "c", r = "Requires completing all Eternal Palace raid achievements.", d = "Complete all Eternal Palace raid achievements listed, including defeating bosses under specific conditions. This unlocks the Azshari Bloatray mount upon completion.", x = 7 },
        [13690] = { e = 4, s = "c", r = "Defeating many Nazjatar world boss champions.", d = "Start by completing the Nazjatar world quests listed in the info field to unlock each champion encounter. Focus on one quest at a time since they are separate objectives, and ensure you have enough gear for the higher-level bosses like Azshara's champions.", x = 7 },
        [13691] = { e = 4, s = "g", r = "Slaying dozens of rare creatures across the zone.", d = "Travel to Nazjatar and systematically hunt rare creatures by checking world maps or using scanning tools if available. These mobs often spawn in specific zones, so explore thoroughly rather than rushing through main story content first.", x = 7 },
        [13692] = { e = 4, s = "g", r = "Collecting many rare drops from Nazjatar mobs.", d = "Farm the rare drops from the same creatures you are slaying for the previous achievement, as many items drop directly upon killing them. Keep an eye on your loot window and ensure you do not accidentally sell or discard these specific items before collecting all of them.", x = 7 },
        [13693] = { e = 3, s = "g", r = "Catching all pets on Mechagon requires time and luck.", d = "Visit Mechagon Island and explore every zone to find wild pets that can be caught using a Battle Pet Trainer. Some pets may require specific locations or events, so check the map for hidden areas or quest markers related to pet catching.", x = 7 },
        [13694] = { e = 3, s = "g", r = "Collecting 12 specific pets in Nazjatar requires exploration and RNG.", d = "Head to Nazjatar and locate the rare aquatic creatures listed in the info field to catch them as battle pets. Use a high-level Battle Pet Trainer and be patient, as some may only appear during certain times or after completing specific world quests.", x = 7 },
        [13695] = { e = 3, s = "c", h = { 80740 }, r = "Requires completing other pet achievements; Nautical Nuisances is the hardest.", d = "Complete both the Nazjatar and Mechagon pet battle achievements first, as this one depends on finishing those earlier tasks. Once you have caught all pets and completed their respective achievements, claim the reward to finish this set.", x = 7 },
        [13696] = { e = 2, s = "s", r = "Simple interaction with Scrappy in Rustbolt after unlocking Mechagon.", d = "Go to Rustbolt in Mechagon Island to find Scrappy and revive him if needed, then feed him a Mechano-Treat. Make sure you have the treat item in your inventory before approaching Scrappy to avoid missing the interaction.", x = 7 },
        [13698] = { e = 4, s = "g", r = "Requires Mythic dungeon runs and finding/helping critters repeatedly.", d = "Run Operation: Mechagon on Mythic Difficulty and focus on rescuing five Helpless Critters before defeating Gunker. This requires careful planning during the dungeon run, as saving critters is a key objective separate from just killing the boss.", x = 7 },
        [13699] = { e = 4, s = "g", r = "Defeating multiple unique bosses in Nazjatar requires repeated dungeon runs.", d = "Locate Mardivas's Laboratory in Nazjatar and defeat all listed creations, including bosses like Salgos the Eternal. These enemies are often found in specific rooms or events within the lab area, so explore thoroughly to find each target.", x = 7 },
        [13700] = { e = 3, s = "c", h = { 80884 }, r = "Requires completing the full Mechagon storyline; Prospectus Bay is hardest.", d = "Complete the full Mechagon storyline by following the main quest chain from start to finish. Ensure you accept and complete every major quest listed in the info field, as missing one will prevent you from earning this achievement.", x = 7 },
        [13701] = { e = 2, s = "g", r = "Earning honor is steady progress across various PvP activities.", d = "Participate in PvP activities like Island Expeditions, Brawls, Battlegrounds, and Epic Battlegrounds to earn honor points. Accumulate 10,000 honor total across these modes, keeping track of your progress via the character panel or achievement tracker.", x = 7 },
        [13702] = { e = 2, s = "g", r = "Continues the grind for honor; slightly more time than previous tier.", d = "Continue earning honor from PvP activities until you reach 30,000 total points. This is essentially an extended version of the previous achievement, so focus on high-honor events like Island Expeditions to speed up progress.", x = 7 },
        [13703] = { e = 2, s = "g", r = "Continues the grind for honor; requires significant but manageable time.", d = "Farm honor in any PvP activity until you hit the cap, noting that this is account-wide so group up for faster progress. Avoid relying solely on Island Expeditions as they are time-gated and require specific conditions to run.", x = 7 },
        [13704] = { e = 3, s = "g", r = "Gaining XP with allies requires repeated activities in Nazjatar.", d = "Complete the initial Waveblade Ankoan storyline first to unlock the experience gain mechanic with your allies. This achievement chains directly into the next one, so ensure you finish prerequisites before moving forward.", x = 7 },
        [13706] = { e = 4, s = "s", r = "Requires specific Mythic dungeon run with a charged Sacred Gear.", d = "Run Operation: Mechagon in Mythic difficulty and keep the Sacred Gear charged throughout the entire dungeon run. Do not let the charge drop below full or the boss will not count toward your progress.", x = 7 },
        [13707] = { e = 2, s = "g", r = "Obtaining the Crimson Tidestallion requires hunting in Nazjatar waters.", d = "Locate and defeat the Crimson Tidestallion mob to obtain the required item for this collection entry. This is account-wide, so coordinate with friends if you cannot find it alone.", x = 7 },
        [13708] = { e = 5, s = "g", r = "Grinding for all mini figures is a long RNG-heavy process.", d = "Collect all figures from the Azeroth Mini: Mechagon set by completing related quests or purchasing them from vendors. Check your toy box inventory regularly to ensure no mini is missed before claiming the achievement.", x = 7 },
        [13709] = { e = 2, s = "c", r = "Straightforward story quests with no difficult mechanics.", d = "Finish the Nazjatar storylines for your faction by following the main quest chain and completing all associated objectives. This is account-wide, so playing with a group can speed up storyline completion significantly.", x = 7 },
        [13710] = { e = 2, s = "c", r = "Straightforward story quests with no difficult mechanics.", d = "Complete the Nazjatar storylines for your faction just like the previous achievement, ensuring all key quests are finished. Since this is account-wide, you can share progress with friends if needed.", x = 7 },
        [13711] = { e = 4, s = "g", r = "Collecting 1000 rare pearls is a lengthy grinding task.", d = "Gather Prismatic Manapearls by completing various activities in Nazjatar or trading with other players. Aim to collect 1,000 of these items as they are essential for this exploration achievement.", x = 7 },
        [13712] = { e = 3, s = "c", r = "Exploring zones takes time but involves standard traversal.", d = "Explore all zones in Nazjatar by revealing covered areas on the world map through travel and quest completion. Use a flying mount or boat to efficiently cover different regions and ensure no zone is missed.", x = 7 },
        [13713] = { e = 4, s = "g", r = "Finding 100 treasures is a repetitive and lengthy grind.", d = "Use a Scrying Stone to locate and collect 100 treasures scattered across Nazjatar. Be patient as some treasures may require specific conditions or locations to unlock.", x = 7 },
        [13715] = { e = 2, s = "s", r = "Obtaining one specific pet is usually a quick drop or quest.", d = "Obtain the slimy companion pet in Nazjatar by completing related quests or defeating specific enemies. This pet is account-wide, so you can share progress with friends if needed.", x = 7 },
        [13716] = { e = 4, s = "c", h = { 81018 }, r = "Killing 10 specific mobs before the raid boss is a grind.", d = "Defeat Za'qul in the Eternal Palace after killing ten Twinklehoof Bovine on Normal difficulty or higher. Ensure you complete the prerequisite kills before attempting to defeat the final boss for credit.", x = 7 },
        [13718] = { e = 5, s = "c", h = { 81014, 81015, 81016 }, r = "Raids require high skill, coordination, and significant time.", d = "Start this after clearing Wing 1 of The Eternal Palace to unlock the other bosses. Defeat Sivara, Behemoth, and Radiance in any difficulty since no Mythic requirement is listed.", x = 7 },
        [13719] = { e = 5, s = "c", h = { 81027, 81028, 81029 }, r = "Raids require high skill, coordination, and significant time.", d = "Complete these only after finishing Wing 2 content. You must defeat Ashvane, Orgozoa, and The Queen's Court; ensure you have the prerequisite achievements unlocked first.", x = 7 },
        [13720] = { e = 4, s = "g", r = "Looting 25 chests while active is a repetitive grind.", d = "Equip the Assassin set and run Nazjatar zones to find War Supply Chests. This is account-wide, so coordinate with friends or solo grind until you hit 25 chests.", x = 7 },
        [13722] = { e = 3, s = "g", r = "Shooing 100 tadpoles takes time but is mechanically simple.", d = "Find Bloodfin Tadpoles in Nazjatar water areas and use the shoo ability on them repeatedly. Aim for 100 total as this is a simple exploration task.", x = 7 },
        [13723] = { e = 4, s = "c", r = "Requires specific Mythic dungeon completion and precise mechanic timing.", d = "Finish Operation: Mechagon first, then hit Deuce Mecha-Buffer with a Piston Smasher on Mythic. Finally, defeat Tussle Tonks to claim the Gnomish T.O.O.L.B.O.X.", x = 7 },
        [13724] = { e = 3, s = "g", r = "Needs incubating a pet then defeating a raid boss on Normal.", d = "Incubate a baby Zoatroid in The Eternal Palace Hatchery before fighting Orgozoa. You can do this on Normal or higher difficulty to unlock the achievement.", x = 7 },
        [13725] = { e = 4, s = "c", h = { 81031, 81032 }, r = "Requires defeating multiple specific raid bosses on Mythic.", d = "Unlock Wing 3 of The Eternal Palace first, then defeat Za'qul and Queen Azshara. This is account-wide, so you can help friends complete it faster.", x = 7 },
        [13726] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "You must have the Mythic Naga Centaur achievement before attempting this. Defeat Abyssal Commander Sivara specifically on Mythic difficulty in The Eternal Palace.", x = 7 },
        [13727] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Prerequisite Mythic Rage of Azshara is required first. Then defeat Radiance of Azshara on Mythic difficulty to earn these points.", x = 7 },
        [13728] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Unlock the Mythic Blackwater Behemoth achievement before starting this one. Defeat Blackwater Behemoth on Mythic difficulty within The Eternal Palace raid.", x = 7 },
        [13729] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Get the Mythic Lady Ashvane achievement first as a prerequisite. Then defeat Lady Ashvane on Mythic difficulty in The Eternal Palace.", x = 7 },
        [13730] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Complete the Mythic Orgozoa achievement before attempting this one. Defeat Orgozoa on Mythic difficulty in The Eternal Palace to finish the set.", x = 7 },
        [13731] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Queue for The Eternal Palace on Mythic difficulty and defeat The Queen's Court boss. Ensure your group has completed the prerequisite Mythic Naga Council achievement before attempting this raid.", x = 7 },
        [13732] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Defeat Za'qul in The Eternal Palace on Mythic difficulty after unlocking the required Mythic Herald achievement. Coordinate with your group to handle the mechanics specific to this boss encounter.", x = 7 },
        [13733] = { e = 5, s = "s", r = "Mythic difficulty raid boss requires high-end gear and coordination.", d = "Complete the Eternal Palace raid on Mythic difficulty by defeating Queen Azshara while holding the Mythic Azshara prerequisite. This will grant you the title The Eternal upon completion.", x = 7 },
        [13735] = { e = 4, s = "s", r = "Heroic Warfront completion is a long, complex group endeavor.", d = "Form a group to run Battle for Stromgarde on Heroic difficulty and complete all objectives. Ensure your faction is Horde since this specific achievement is listed under that requirement.", x = 7 },
        [13737] = { e = 4, s = "c", r = "Requires completing a full Warfront on Heroic.", d = "Complete the Battle for Stromgarde Warfront on Heroic difficulty to earn this title. Ensure you have unlocked and finished the base Warfront achievement first, as this is a prerequisite.", x = 7 },
        [13738] = { e = 4, s = "c", r = "Requires defeating all commanders on Heroic Warfronts.", d = "Defeat every Horde commander in Battle for Stromgarde on Heroic difficulty. You must complete the warfront with each specific enemy leader to count toward this account-wide achievement.", x = 7 },
        [13739] = { e = 4, s = "c", r = "Requires completing full Warfronts with every commander.", d = "Defeat every Alliance commander in Battle for Stromgarde on Heroic difficulty. Finish the warfront with each specific enemy leader listed to ensure progress counts for this account-wide goal.", x = 7 },
        [13743] = { e = 2, s = "g", r = "Grinding a companion to Rank 10 takes under an hour.", d = "Adventure with Hunter Akana until reaching Rank 10 by completing daily contracts. This is a time-gated achievement that requires you to unlock the next tier before moving on.", x = 7 },
        [13744] = { e = 2, s = "g", r = "Grinding a companion to Rank 10 takes under an hour.", d = "Complete daily contracts for Bladesman Inowari until he reaches Rank 10. Treat this as part of a chain where you must finish the previous rank before advancing.", x = 7 },
        [13745] = { e = 2, s = "g", r = "Grinding a companion to Rank 10 takes under an hour.", d = "Adventure with Farseer Ori by completing daily contracts until she reaches Rank 10. Do not skip steps in the progression chain as later ranks require prior completion.", x = 7 },
        [13746] = { e = 2, s = "g", r = "Grinding a companion to Rank 10 takes under an hour.", d = "Complete daily contracts for Neri Sharpfin until she reaches Rank 10. This is a sequential achievement where you must finish the current rank before unlocking the next tier.", x = 7 },
        [13747] = { e = 2, s = "g", r = "Grinding a companion to Rank 10 takes under an hour.", d = "Adventure with Poen Gillbrack by completing daily contracts until he reaches Rank 10. Ensure you have unlocked the previous rank in his progression chain first.", x = 7 },
        [13748] = { e = 2, s = "g", r = "Grinding a companion to Rank 10 takes under an hour.", d = "Complete daily contracts for Vim Brineheart until he reaches Rank 10. This achievement is part of a tiered system requiring sequential completion of ranks.", x = 7 },
        [13749] = { e = 3, s = "g", r = "Requires grinding a companion from Rank 10 to 20.", d = "Advance Neri Sharpfin from Rank 10 to Rank 20 by completing daily contracts. You must first complete the Seasoned rank before this Veteran rank becomes available.", x = 7 },
        [13750] = { e = 4, s = "g", r = "Requires grinding a companion from Rank 20 to 30.", d = "Push Neri Sharpfin from Rank 20 to Rank 30 to finish her progression chain. This final tier requires you to have already completed the Veteran rank first.", x = 7 },
        [13751] = { e = 3, s = "g", r = "Requires grinding a companion from Rank 10 to 20.", d = "Advance Poen Gillbrack from Rank 10 to Rank 20 by completing daily contracts. Ensure you finish the Seasoned rank before attempting this Veteran tier.", x = 7 },
        [13752] = { e = 3, s = "g", r = "Grinding a companion to rank 20 takes several hours.", d = "Start by completing the previous Vim Brineheart achievement to unlock this one. Focus on daily quests with him until he reaches Rank 20, then continue to Rank 30 for the next tier.", x = 7 },
        [13753] = { e = 3, s = "g", r = "Grinding a companion to rank 20 takes several hours.", d = "Unlock this by finishing Hunter Akana's prior achievement. Complete her daily quests consistently to reach Rank 20 before moving on to the Battle-Scarred tier.", x = 7 },
        [13754] = { e = 3, s = "g", r = "Grinding a companion to rank 20 takes several hours.", d = "Begin after unlocking Bladesman Inowari's previous rank. Grind his daily quests until he hits Rank 20, ensuring you do not miss any weekly opportunities.", x = 7 },
        [13755] = { e = 3, s = "g", r = "Grinding a companion to rank 20 takes several hours.", d = "Unlock this by completing Farseer Ori's prior achievement. Work with her on daily quests to reach Rank 20, then proceed immediately to the next rank goal.", x = 7 },
        [13756] = { e = 3, s = "g", r = "Grinding a companion to rank 30 takes several hours.", d = "This requires unlocking Poen Gillbrack's Veteran tier first. Complete his daily quests until he reaches Rank 30, as this is a sequential chain with no shortcuts.", x = 7 },
        [13757] = { e = 3, s = "g", r = "Grinding a companion to rank 30 takes several hours.", d = "Unlock after finishing Vim Brineheart's Veteran achievement. Continue his daily quests to reach Rank 30, noting that this extends the grind significantly from the previous tier.", x = 7 },
        [13758] = { e = 3, s = "g", r = "Grinding a companion to rank 30 takes several hours.", d = "Start by completing Hunter Akana's Veteran achievement. Grind her daily quests until she reaches Rank 30, ensuring you maintain a steady pace to avoid long delays.", x = 7 },
        [13759] = { e = 3, s = "g", r = "Grinding a companion to rank 30 takes several hours.", d = "Unlock after finishing Bladesman Inowari's Veteran tier. Complete his daily quests to reach Rank 30, watching for any changes in quest availability or difficulty.", x = 7 },
        [13760] = { e = 3, s = "g", r = "Grinding a companion to rank 30 takes several hours.", d = "Begin by completing Farseer Ori's Veteran achievement. Work with her on daily quests until she reaches Rank 30, as this is the final step in her progression chain.", x = 7 },
        [13761] = { e = 4, s = "c", h = { 81129 }, r = "Requires leveling multiple companions; Vim is the hardest.", d = "This account-wide achievement requires leveling all Horde Nazjatar allies to Rank 30. Start with Poen Gillbrack and Vim Brineheart first, as they are often easier to access than Neri Sharpfin.", x = 7 },
        [13762] = { e = 4, s = "c", h = { 81133 }, r = "Requires leveling multiple companions; Akana is the hardest.", d = "Unlock this by leveling all Alliance Nazjatar allies to Rank 30. Prioritize Bladesman Inowari and Farseer Ori, as they share similar daily quest structures with Hunter Akana.", x = 7 },
        [13763] = { e = 2, s = "g", r = "Running a short scenario ten times takes under an hour.", d = "Complete the Summons from the Depths scenario ten times to earn this achievement. This is account-wide, so coordinate with friends or solo grind depending on your schedule.", x = 7 },
        [13764] = { e = 2, s = "c", r = "Solve puzzles with chests; moderate time.", d = "Start by completing the Easy Leylocked Chest, then progress through Medium and Hard chests in order. Ensure you have all required keys before attempting the Hard Runelocked Chests to avoid missing drops.", x = 7 },
        [13765] = { e = 3, s = "g", r = "Grind 30 daily quests in Nazjatar.", d = "Queue for Requisition or Bounty dailies in Nazjatar immediately upon arrival. You must complete exactly 30 of these quests, so track your progress carefully as this is account-wide and cannot be rushed.", x = 7 },
        [13766] = { e = 2, s = "s", r = "Single pet battle; trivial once found.", d = "Travel to the Postmaster Malown encounter location and initiate a Pet Battle against her directly. This is a straightforward fight with no special mechanics, making it quick to complete for the Burnout pet reward.", x = 7 },
        [13767] = { e = 4, s = "s", r = "Strict lap requirement; high RNG risk.", d = "Run The Eternal Palace laps on Normal or higher difficulty while avoiding the water hazard. You must complete six full laps without falling in before defeating Radiance of Azshara to secure this achievement.", x = 7 },
        [13768] = { e = 4, s = "s", r = "Specific debuff condition on boss kill.", d = "Coordinate with your group to ensure one player remains alive while affected by Essence of Azeroth during Queen Azshara's fight. Communicate clearly about the debuff status and timing to guarantee success on Normal or higher.", x = 7 },
        [13769] = { e = 2, s = "s", r = "Simple infusion step; trivial once unlocked.", d = "Infuse your Heart of Azeroth with any essence at rank 2 or higher to unlock this milestone. This is part of a chain, so ensure you have learned essences above rank 1 first before attempting the infusion.", x = 7 },
        [13770] = { e = 2, s = "s", r = "Simple infusion step; trivial once unlocked.", d = "Progress by infusing your Heart of Azeroth with an essence at rank 3 or higher. You must complete the previous Power Up achievement and have learned essences above rank 2 before starting this step.", x = 7 },
        [13771] = { e = 2, s = "s", r = "Simple infusion step; trivial once unlocked.", d = "Infuse your Heart of Azeroth with any essence at exactly rank 4 to finish this tier. Ensure you have completed the prior Power Creep requirement and learned all necessary essences above rank 3 first.", x = 7 },
        [13772] = { e = 3, s = "c", r = "Unlock all essences; moderate collection time.", d = "Unlock all available essences from the Rise of Azshara update for your role, then infuse them at rank 1. This includes both generic and role-specific essences, so check your collection before starting the infusion process.", x = 7 },
        [13773] = { e = 3, s = "c", r = "Grind essences to rank 2; moderate effort.", d = "Infuse all learned essences at rank 2 or higher after completing Essence Essentials. Track your progress across all roles to ensure you meet the requirement for every available essence before moving forward.", x = 7 },
        [13775] = { e = 3, s = "c", r = "Grind essences to rank 3; moderate effort.", d = "Infuse all essences at rank 3 or higher once you have completed Essence Gains. Verify that you have learned all rank 3 essences for your roles, as this is a strict prerequisite for the next step in the chain.", x = 7 },
        [13776] = { e = 2, s = "s", r = "Explore zone map; easy solo task.", d = "Explore Mechagon Island thoroughly to reveal all covered areas on the world map. Visit key locations like Rustbolt and Sparkweaver Point, ensuring you mark each zone as explored to avoid missing any critical spots.", x = 7 },
        [13777] = { e = 4, s = "g", r = "Grinding for high-rank essences takes time.", d = "Gather rank 3+ Heart of Azeroth Essences for every slot before applying them. This is a straightforward collection task with no time gate, but ensure you have the correct essence types for your chosen role.", x = 7 },
        [13790] = { e = 2, s = "c", r = "Crafting weapons is quick with recipes.", d = "Complete the Rocket-Chief Fuselage quest chain to craft all listed weapons. Since this is account-wide, one player can finish it for everyone in your group or guild.", x = 7 },
        [13791] = { e = 4, s = "c", h = { 81362 }, r = "Quest chain requires specific bot parts.", d = "Finish the entire Mechaspider storyline quests sequentially. This achievement is account-wide, so coordinate with friends if you need help completing specific steps.", x = 7 },
        [13836] = { e = 3, s = "g", r = "Finding scattered figurines takes exploration time.", d = "Search Nazjatar for all ten crystalline cat figurines scattered in various zones. These are rare drops or hidden items, so be thorough and check every corner of the zone.", x = 7 },
        [13878] = { e = 4, s = "c", h = { 81921 }, r = "Revendreth storylines require zone completion.", d = "Complete all Revendreth storyline quests listed in the achievement description. This is account-wide, meaning one player can complete it for your entire group.", x = 8 },
        [13924] = { e = 3, s = "c", r = "Campaign quests are straightforward but long.", d = "Finish the entire War Campaign in Battle for Azeroth to unlock the title. Ensure you complete all campaign chapters and side objectives before moving on.", x = 7 },
        [13925] = { e = 3, s = "c", r = "Same campaign as previous achievement.", d = "Complete the War Campaign similar to the previous entry, as this appears to be a duplicate or alternative version. Focus on finishing all campaign content regardless of minor quest name differences.", x = 7 },
        [13928] = { e = 4, s = "g", r = "Earning badges requires many AV runs.", d = "Earn 200 Timewarped Badges by doing Alterac Valley Classic quests and participating in matches. This is account-wide, so one player can collect badges for everyone.", x = 7 },
        [13930] = { e = 4, s = "g", r = "Same badge grind as previous achievement.", d = "Collect 200 Timewarped Badges from Alterac Valley Classic activities. This is essentially the same as the previous achievement, so focus on completing both if needed.", x = 7 },
        [13990] = { e = 5, s = "s", r = "Requires raiding and specific pet mechanic.", d = "Defeat Shad'har the Insatiable in Ny'alotha after petting him on Normal or higher difficulty. Ensure your entire raid has pets active before engaging the boss.", x = 7 },
        [13994] = { e = 5, s = "c", h = { 82811 }, r = "Horrific Visions are rare RNG events.", d = "Complete all Horrific Vision achievements listed to unlock the Black Serpent of N'Zoth mount. This requires finishing specific vision scenarios and is account-wide.", x = 7 },
        [13998] = { e = 4, s = "g", r = "Collecting all essences takes significant time.", d = "Infuse your Heart of Azeroth with all Visions of N'Zoth Essences available for your role. Gather all essences first, then apply them to reach the achievement.", x = 7 },
        [13999] = { e = 4, s = "g", r = "Requires defeating a raid boss after destroying two obelisks.", d = "Defeat Ra-den after destroying two obelisks with Unstable Void on Normal or higher; ensure you have the prerequisite achievement first.", x = 7 },
        [14002] = { e = 3, s = "s", r = "Create a new character and level to 50.", d = "Create a new Vulpera character and level them to 50 to unlock the heritage armor; this is account-wide.", x = 7 },
        [14008] = { e = 4, s = "g", r = "Requires defeating a raid boss after killing a manifestation.", d = "Defeat Maut in Ny'alotha after beating a Forbidden Manifestation on Normal or higher; no specific prerequisite listed but raid progression helps.", x = 7 },
        [14013] = { e = 3, s = "s", r = "Complete reputation grinds and unlock the race.", d = "Complete the Mechagnome reputation chain to unlock the race, then level a new character to 50 for the heritage armor.", x = 7 },
        [14014] = { e = 3, s = "s", r = "Create a new character and level to 50.", d = "Create a new Mechagnome character and level them to 50; ensure you have unlocked the base race first.", x = 7 },
        [14019] = { e = 4, s = "g", r = "Requires defeating a raid boss after killing ten shards quickly.", d = "Defeat Wrathion after killing ten Crackling Shards within three seconds on Normal or higher; practice timing your kills.", x = 7 },
        [14020] = { e = 3, s = "s", r = "Complete the pet battle challenge in Blackrock Depths.", d = "Complete the Pet Battle Challenge in Blackrock Depths to earn the Shadowy Disguise toy; this is account-wide.", x = 7 },
        [14021] = { e = 4, s = "c", h = { 82880, 82881, 82882 }, r = "Requires completing multiple pet battle challenges.", d = "Finish all listed Pet Battle Challenges including Wailing Caverns, Deadmines, Gnomeregan, Stratholme, and Blackrock Depths.", x = 7 },
        [14023] = { e = 4, s = "g", r = "Requires defeating a raid boss after killing three specimens.", d = "Defeat the Hivemind after killing three Evolved Specimens on Normal or higher; ensure you have the Bug Duo achievement.", x = 7 },
        [14024] = { e = 4, s = "g", r = "Requires defeating a raid boss with specific orb timing.", d = "Defeat Dark Inquisitor Xanesh by eliminating Void Orbs with under three seconds remaining on Voidwoken three times.", x = 7 },
        [14026] = { e = 4, s = "g", r = "Requires defeating a raid boss after triggering mechanics twice.", d = "Trigger Throes of Agony twice within sixty seconds on Drest'agath to complete this Ny'alotha achievement.", x = 7 },
        [14037] = { e = 4, s = "g", r = "Requires defeating a raid boss after killing three disciples.", d = "Defeat Prophet Skitra after killing three Disciples of the Prophet on Normal or higher; ensure Phase 3 is active.", x = 7 },
        [14038] = { e = 5, s = "c", r = "Requires specific speedrun mechanics and high-level gear.", d = "Defeat Il'gynoth on Normal or higher after killing ten Bloods of Ny'alotha. Ensure your group can clear the Bloods quickly to meet the three-second timer for the final boss.", x = 7 },
        [14041] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Queue for Wrathion, the Black Emperor on Mythic difficulty in Ny'alotha. This is a timed event that requires a full group and cannot be missed once the window closes.", x = 7 },
        [14043] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Defeat Maut on Mythic difficulty within the limited time window available for Ny'alotha content. Coordinate with your raid leader to ensure everyone is ready before the event starts.", x = 7 },
        [14044] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Kill the Prophet Skitra on Mythic difficulty during the specific event period. This encounter requires a full group and must be completed before the event timer expires.", x = 7 },
        [14045] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Defeat Dark Inquisitor Xanesh on Mythic difficulty while the event is active. Bring a complete raid group to handle this encounter efficiently within the time limit.", x = 7 },
        [14046] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Kill the Hivemind on Mythic difficulty during its available event window. Ensure your group composition is optimized for this specific boss before queuing up.", x = 7 },
        [14048] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Defeat Shad'har the Insatiable on Mythic difficulty before the event ends. This requires a full group and careful coordination to complete within the allotted time.", x = 7 },
        [14049] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Kill Drest'agath on Mythic difficulty during the limited event period. Gather your raid group early to avoid missing this opportunity once the timer runs out.", x = 7 },
        [14050] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Defeat Vexiona on Mythic difficulty while the event is active. This encounter requires a full group and must be completed before the event window closes.", x = 7 },
        [14051] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Kill Ra-den the Despoiled on Mythic difficulty during its specific event window. Ensure your raid is ready to tackle this boss quickly before time expires.", x = 7 },
        [14052] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Defeat Il'gynoth, Corruption Reborn on Mythic difficulty within the event timeframe. This requires a full group and efficient execution to complete before the timer ends.", x = 7 },
        [14054] = { e = 5, s = "s", r = "Mythic difficulty requires raid group and high skill.", d = "Kill Carapace of N'Zoth on Mythic difficulty during its available event period. Coordinate with your group to ensure you can defeat this boss before the window closes.", x = 7 },
        [14055] = { e = 4, s = "s", r = "Requires Mythic raid clear; significant time and coordination.", d = "Defeat N'Zoth the Corruptor on Mythic difficulty to earn your title. This is a time-gated achievement requiring you to complete the raid after unlocking the specific Mythic version.", x = 7 },
        [14058] = { e = 3, s = "g", r = "Grinding for Tier 25 set pieces across multiple classes.", d = "Collect any Tier 25 armor set from Ny'alotha on at least one class. Since this is account-wide, gear earned by other characters counts toward your completion.", x = 7 },
        [14059] = { e = 2, s = "g", r = "Collecting PvP gear from a past season; account-wide.", d = "Gather the full PvP Season 4 armor set to complete this collection goal. Ensure you acquire all pieces from the specific season's rewards or drops.", x = 7 },
        [14060] = { e = 3, s = "g", r = "Requires repeated dungeon runs to upgrade weapon rank.", d = "Upgrade Ashjra'kamas, Shroud of Resolve to rank 15 using materials gathered during the expansion. This requires collecting specific resources and crafting upgrades.", x = 7 },
        [14061] = { e = 2, s = "g", r = "Purchasing research items; mostly gold and time.", d = "Purchase every research item available in the Titanic Research Archive. You must have sufficient gold and complete any prerequisite quests to unlock these items.", x = 7 },
        [14062] = { e = 3, s = "s", r = "Defeating a specific NPC in a timed event instance.", d = "Defeat Alleria in the Horrific Vision of Stormwind as a solo or group activity. This is often time-gated if you do not progress through the specific vision content quickly enough.", x = 7 },
        [14063] = { e = 3, s = "s", r = "Defeating a specific NPC in a timed event instance.", d = "Defeat Thrall in the Horrific Vision of Orgrimmar to claim these points. Like other visions, this may be time-gated depending on your progression speed.", x = 7 },
        [14064] = { e = 3, s = "s", r = "Completing objectives in a single run; requires prior unlock.", d = "Complete all objectives in the Horrific Vision of Stormwind during a single visit. Do not leave the instance until you have finished every required task to avoid missing out.", x = 7 },
        [14065] = { e = 3, s = "s", r = "Completing objectives in a single run; requires prior unlock.", d = "Finish all objectives in the Horrific Vision of Orgrimmar without leaving the instance. Ensure you check off every single objective before exiting the vision area.", x = 7 },
        [14066] = { e = 4, s = "s", r = "Requires specific masks and perfect completion; high difficulty.", d = "Complete the Stormwind vision with all five Faceless Masks active in one visit. You must equip these specific masks and finish all objectives without interruption.", x = 7 },
        [14067] = { e = 4, s = "s", r = "Requires specific masks and perfect completion; high difficulty.", d = "Complete the Orgrimmar vision while wearing all five Faceless Masks simultaneously. This requires equipping the masks before entering and finishing all tasks in a single run.", x = 7 },
        [14139] = { e = 5, s = "g", r = "Requires extreme RNG luck with Annihilation mechanic on Mythic.", d = "Allow every player to be hit by Annihilation at least 30 times on Normal or higher difficulty. Coordinate with your group to ensure no one misses the mechanic count before defeating Vexiona.", x = 7 },
        [14143] = { e = 5, s = "c", h = { 83442, 83443 }, r = "Requires completing multiple Horrific Visions instances.", d = "Complete both Horrific Visions of N'Zoth first to unlock the Even More variants. This is a solo-friendly chain that rewards a pet, so prioritize it early in your progression.", x = 7 },
        [14146] = { e = 5, s = "c", h = { 83522, 83528 }, r = "Needs full raid clears and specific boss mechanics.", d = "Finish all Ny'alotha raid achievements before attempting this one, as it requires specific boss kills and mechanics. It is account-wide, so coordinate with friends or use a guild to secure the mount reward.", x = 7 },
        [14147] = { e = 5, s = "s", r = "Requires precise timing on a high-difficulty raid boss.", d = "Run Normal difficulty raids and focus on defeating Synthesis Growths quickly before engaging the Carapace of N'Zoth. Timing is critical here; practice the wipe mechanic to ensure you meet the ten-second window.", x = 7 },
        [14148] = { e = 5, s = "s", r = "Requires full raid coordination and specific mechanic.", d = "Ensure every player in your group accepts the Gift of N'Zoth before killing the final boss on Normal or higher. This is a strict group requirement that cannot be completed solo.", x = 7 },
        [14149] = { e = 3, s = "g", r = "Heroic warfront requires multiple runs to complete.", d = "Queue for the Battle for Darkshore Warfront and select Heroic difficulty to earn this achievement. Note that you must complete it on your faction's server as an account-wide goal.", x = 7 },
        [14150] = { e = 3, s = "g", r = "Heroic warfront requires multiple runs to complete.", d = "Complete the Battle for Darkshore Warfront on Heroic difficulty for your specific faction. Since this is account-wide, ensure your faction completes the objective to unlock the achievement.", x = 7 },
        [14153] = { e = 3, s = "g", r = "Requires completing three separate assault events.", d = "Participate in all three Uldum Assaults during the Black Empire event to protect denizens and earn points. These are time-gated events, so check your calendar for availability.", x = 7 },
        [14154] = { e = 3, s = "g", r = "Requires completing three separate assault events.", d = "Defend the Vale of Eternal Blossoms against all three specific assault waves during the Black Empire event. This is account-wide, so coordinate with friends to cover different zones if needed.", x = 7 },
        [14155] = { e = 2, s = "g", r = "Reputation grind is moderate but achievable solo.", d = "Grind reputation with the Uldum Accord faction until you reach Exalted status. This often requires completing daily quests and world events in Uldum during the relevant expansion content.", x = 7 },
        [14156] = { e = 2, s = "g", r = "Reputation grind is moderate but achievable solo.", d = "Earn Exalted reputation with the Rajani faction by completing their specific questlines and world events. Focus on activities that grant large chunks of reputation to speed up this process.", x = 7 },
        [14157] = { e = 3, s = "s", r = "Campaign storyline requires multiple steps to finish.", d = "Complete the entire Black Empire Campaign storyline within Ny'alotha, the Waking City. This is a major quest chain that unlocks after finishing the raid and related assaults.", x = 7 },
        [14158] = { e = 2, s = "g", r = "Collecting tumors during assaults is moderately easy.", d = "Destroy one hundred Corruption Tumors during Uldum or Vale Assaults in the Black Empire event. These tumors spawn frequently, so stay active in combat zones to reach the count quickly.", x = 7 },
        [14159] = { e = 3, s = "c", r = "Kill 10 corrupted rares; RNG dependent.", d = "Start by farming corrupted rares in Uldum or Vale of Eternal Blossoms during Black Empire Assaults, as these events are time-gated and missable if you do not participate. Focus on killing the specific corrupted rare types listed in the info field to reach the 10-type requirement efficiently. Remember this is account-wide, so coordinate with friends to cover different zones or event times.", x = 7 },
        [14160] = { e = 4, s = "g", r = "Grind 250 rares; RNG dependent.", d = "Prioritize farming rare creatures specifically during Black Empire Assaults in Uldum or Vale of Eternal Blossoms, as these are the only valid sources for this achievement. Since you need 250 kills, plan multiple assault runs to ensure you hit the count before the event timer expires. This is account-wide, so group up with others to maximize your kill count per session.", x = 7 },
        [14161] = { e = 3, s = "c", r = "Complete all consuming maw objectives.", d = "Complete every unique Consuming Maw objective in both Uldum and Vale of Eternal Blossoms during Black Empire Assaults, as these events are time-limited. Track the specific objectives listed in the info field to ensure you do not miss any cleansable targets. Coordinate with a group to handle all objectives quickly before the assault ends.", x = 7 },
        [14162] = { e = 3, s = "c", r = "Obtain 5 masks; RNG dependent.", d = "Obtain all five Faceless Masks by completing Horrific Visions runs, as each mask drops from a specific vision encounter. You must complete these masks in any order, but ensure you have the necessary gear and resources for higher-difficulty visions. This is account-wide, so share progress with friends if needed.", x = 7 },
        [14164] = { e = 3, s = "s", r = "Complete Ardenweald storylines.", d = "Complete the Ardenweald storylines by following the main questline and leveling up through the zone's specific objectives. Start with the Welcome to Ardenweald quest and work through each listed objective in order to unlock the next stage. This is account-wide, so ensure your character meets the level requirement before beginning.", x = 8 },
        [14165] = { e = 2, s = "c", r = "Full run with 1 mask; RNG dependent.", d = "Complete all objectives in any Horrific Vision with at least one Faceless Mask active to earn this achievement. Ensure you have obtained at least one mask first, as this is a prerequisite for subsequent mask achievements. You can use any vision type, so choose one that suits your group's capabilities.", x = 7 },
        [14166] = { e = 2, s = "c", r = "Full run with 2 masks; RNG dependent.", d = "Complete all objectives in any Horrific Vision with exactly two Faceless Masks active, building on the previous achievement. Ensure you have both masks equipped before starting a new vision run to avoid wasting time. This is account-wide, so coordinate with friends to handle different mask combinations.", x = 7 },
        [14167] = { e = 2, s = "c", r = "Full run with 3 masks; RNG dependent.", d = "Complete all objectives in any Horrific Vision with exactly three Faceless Masks active, following the sequential requirements from previous achievements. Equip three masks before starting a vision run to ensure you meet the criteria without interruption. This is account-wide, so plan your mask collection carefully to avoid delays.", x = 7 },
        [14168] = { e = 2, s = "c", r = "Full run with 4 masks; RNG dependent.", d = "Complete all objectives in any Horrific Vision with exactly four Faceless Masks active, continuing the progression from earlier achievements. Equip four masks before starting a vision run to ensure you meet the criteria without interruption. This is account-wide, so plan your mask collection carefully to avoid delays.", x = 7 },
        [14169] = { e = 3, s = "c", r = "Full run with 5 masks; RNG dependent.", d = "Complete all objectives in any Horrific Vision with all five Faceless Masks active to finish the mask progression chain. Equip all five masks before starting a vision run to ensure you meet the criteria without interruption. This is account-wide, so plan your mask collection carefully to avoid delays.", x = 7 },
        [14170] = { e = 2, s = "g", r = "Grind 1000 mementos; RNG dependent.", d = "Obtain 1000 Corrupted Mementos by completing Horrific Visions and other related activities in the Shadowlands expansion. Track your progress closely, as this is a large number that may take significant time to accumulate. This is account-wide, so share loot with friends if possible to speed up collection.", x = 7 },
        [14171] = { e = 3, s = "g", r = "Grind 10000 mementos; RNG dependent.", d = "Obtain 10000 Corrupted Mementos by continuing to complete Horrific Visions and other related activities after reaching the previous milestone. This requires substantial time investment, so plan multiple sessions to accumulate the necessary amount efficiently. This is account-wide, so share loot with friends if possible to speed up collection.", x = 7 },
        [14172] = { e = 4, s = "g", r = "Grinding 50k items is a long, repetitive task.", d = "Farm Corrupted Mementos from any source until you hit the count. This is account-wide and requires no specific group, so play solo or with friends at your leisure.", x = 7 },
        [14173] = { e = 4, s = "g", r = "Grinding 100k items is a very long task.", d = "Continue farming mementos after finishing the previous one. Since this is a cumulative total, you do not need to restart; just keep collecting until you reach 100,000.", x = 7 },
        [14175] = { e = 3, s = "c", h = { 83676, 83677 }, r = "Requires multiple PVP achievements; victory and veteran are hardest.", d = "Complete all listed Deepwind Gorge PvP achievements first, as they are prerequisites for this title. Ensure you finish the victory and veteran milestones before attempting perfection or drinking brews.", x = 4 },
        [14186] = { e = 3, s = "g", r = "Winning 25 matches is a moderate but lengthy grind.", d = "Focus on controlling the Market base during every match in Deepwind Gorge. You need 25 specific victories where your team holds this objective to claim the points.", x = 4 },
        [14187] = { e = 3, s = "c", h = { 83818 }, r = "Requires specific buff + kills; honorable kills dominate effort.", d = "Consume Stormstout Brew before entering a battle and secure 150 honorable kills while its effects are active. Note that you must be under the buff for every kill counted.", x = 4 },
        [14188] = { e = 2, s = "g", r = "Eating food before matches is easy and quick.", d = "Eat cooked food or feasts to become Well Fed before starting each of your 50 Deepwind Gorge matches. Do not wait until mid-battle; ensure the status is active at the start.", x = 4 },
        [14193] = { e = 5, s = "c", h = { 84589, 84590, 84591 }, r = "Requires defeating specific raid bosses; raid content is hard.", d = "Clear Wing 1 of Ny'alotha by defeating Wrathion, Maut, and The Prophet Skitra. This achievement unlocks after you have completed the initial raid wing requirements.", x = 7 },
        [14194] = { e = 5, s = "c", h = { 84593, 84594, 84595 }, r = "Requires defeating specific raid bosses; raid content is hard.", d = "Progress to Wing 2 of Ny'alotha and defeat Dark Inquisitor Xanesh, Vexiona, The Hivemind, and Ra-Den. Ensure you have access to the raid before attempting these specific bosses.", x = 7 },
        [14195] = { e = 5, s = "c", h = { 84598, 84599, 84600 }, r = "Requires defeating specific raid bosses; raid content is hard.", d = "Advance through Wing 3 of Ny'alotha by killing Shad'har, Drest'agath, and Il'gynoth. This segment is part of the main raid progression path in the Waking City.", x = 7 },
        [14196] = { e = 5, s = "c", h = { 84602, 84603 }, r = "Requires defeating specific raid bosses; raid content is hard.", d = "Finish the final Wing 4 by defeating Carapace of N'Zoth and then N'Zoth the Corruptor. This is the culmination of the raid content and requires full group coordination.", x = 7 },
        [14197] = { e = 3, s = "s", r = "Defeating one boss is moderate difficulty for a group.", d = "Enter Sanguine Depths dungeon and defeat General Kaal on Normal difficulty. This is a straightforward solo or group run with no special mechanics to worry about initially.", x = 8 },
        [14198] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and coordination.", d = "Return to Sanguine Depths and kill General Kaal on Heroic difficulty or higher. You must have completed the Normal version first to unlock this specific achievement tier.", x = 8 },
        [14199] = { e = 3, s = "s", r = "Requires Mythic+ dungeon run with specific boss.", d = "Queue for Mythic Sanguine Depths and defeat General Kaal to earn this dungeon achievement. Ensure you are on the correct difficulty setting before entering the raid instance.", x = 8 },
        [14206] = { e = 3, s = "c", r = "Multiple zone storylines; moderate time investment.", d = "Complete all main storylines in Maldraxxus by finishing the specific quest chains listed in the achievement description. This is account-wide and requires progressing through the zone's primary narrative.", x = 8 },
        [14222] = { e = 3, s = "s", r = "Single event escape; requires group or solo run.", d = "Finish the Exile's Reach introductory content to escape the isle and unlock this quest achievement. Ensure you complete all necessary steps before leaving the area.", x = 8 },
        [14233] = { e = 3, s = "c", r = "Four specific quests to complete in sequence.", d = "Speak with Theotar at the tea party location and complete all four associated weekly quests to hear every side of the story. This is account-wide and requires visiting the specific NPC multiple times.", x = 8 },
        [14272] = { e = 3, s = "s", r = "Single NPC interaction; trivial once found.", d = "Interact with Stonehead in Revendreth to earn his friendship points until you reach the required level for this achievement. Focus on completing daily activities that grant reputation or affection.", x = 8 },
        [14273] = { e = 3, s = "g", r = "Collecting 50 crypts; steady progress required.", d = "Locate and open fifty Atonement Crypts scattered throughout Revendreth to complete this exploration goal. These crypts often appear in specific zones within the zone.", x = 8 },
        [14274] = { e = 3, s = "g", r = "Helping 100 souls; repetitive but straightforward.", d = "Help one hundred fugitive souls complete their rituals of absolution by interacting with them in Revendreth. This is account-wide and requires frequent visits to the zone.", x = 8 },
        [14276] = { e = 3, s = "c", r = "Defeat multiple inquisitors; moderate time needed.", d = "Defeat all listed Inquisitors and Grand Inquisitors found throughout Revendreth to complete this combat achievement. These enemies are often found in specific areas or as world bosses.", x = 8 },
        [14277] = { e = 3, s = "c", r = "Requires completing other Revendreth achievements.", d = "Complete the other Revendreth achievements listed, including Crypt Kicker and Absolution for All, to unlock this title-granting achievement. This is account-wide and requires finishing multiple sub-goals.", x = 8 },
        [14280] = { e = 3, s = "c", r = "Combines zone storylines; moderate overall effort.", d = "Finish all major Shadowlands questlines across Bastion, Maldraxxus, Ardenweald, and Revendreth to complete this Loremaster achievement. This is account-wide and requires visiting every zone.", x = 8 },
        [14281] = { e = 3, s = "c", r = "Multiple Bastion storyline quests to finish.", d = "Complete the entire Bastion storylines by finishing the specific quests listed in the achievement description. This is account-wide and requires progressing through the zone's main narrative.", x = 8 },
        [14284] = { e = 3, s = "g", r = "Shatter 18 Stonefiends; requires Mythic difficulty.", d = "Enter Halls of Atonement on Mythic difficulty and shatter eighteen Undying Stonefiends at once before defeating Echelon. This is a single-run achievement that requires careful planning.", x = 8 },
        [14285] = { e = 3, s = "s", r = "Mythic dungeon mechanics require specific avoidance.", d = "Run Mythic Necrotic Wake with a healer who can manage Comet Storm and Blizzard. Avoid standing in Frozen Binds by moving quickly when the boss casts it.", x = 8 },
        [14286] = { e = 3, s = "g", r = "Requires killing 8 specific mobs before the boss.", d = "Start by killing Forlorn Captives to gain Residue stacks before engaging Executor Tarvold. Ensure you have enough stacks before the fight begins.", x = 8 },
        [14289] = { e = 3, s = "s", r = "Mythic dungeon mechanics require specific debuff.", d = "Defeat General Kaal while under the Slammed! debuff. Coordinate with your group to maintain this effect throughout the entire encounter.", x = 8 },
        [14290] = { e = 3, s = "s", r = "Mythic dungeon boss fight with no partial progress.", d = "Simply defeat Duraka the Unbreakable on Mythic difficulty in Sanguine Depths. No special mechanics or conditions need to be met.", x = 8 },
        [14291] = { e = 3, s = "g", r = "Requires finding 6 specific toys in a zone.", d = "This account-wide achievement requires finding six specific toys in Mists of Tirna Scithe. Run Mythic difficulty and thoroughly explore every zone.", x = 8 },
        [14292] = { e = 3, s = "s", r = "Mythic dungeon run requires specific debuff state.", d = "Defeat all Plaguefall bosses while affected by the Plaguefallen buff within one run. Coordinate with your group to maintain the buff continuously.", x = 8 },
        [14293] = { e = 3, s = "g", r = "Requires killing 6 specific mobs before the boss.", d = "Kill six Sneaky Servitors before defeating Shriekwing in Castle Nathria on Normal or higher difficulty. Ensure the servitors are dead before engaging the boss.", x = 8 },
        [14294] = { e = 3, s = "s", r = "Mythic dungeon mechanics require specific pillar order.", d = "Defeat Sludgefist after he collides with pillars in his preferred order. Watch for his movement patterns to time the collision correctly.", x = 8 },
        [14295] = { e = 3, s = "s", r = "Mythic dungeon mechanics require specific boss state.", d = "Use Final Harvest to consume a Grisly Colossus corpse before defeating Amarth the Harvester. Coordinate with your group to manage the mechanic.", x = 8 },
        [14296] = { e = 3, s = "g", r = "Requires destroying 2 bombs before the boss fight.", d = "Destroy two Volatile Plague Bombs before defeating Doctor Ickus in Plaguefall on Mythic difficulty. Locate and destroy the bombs quickly.", x = 8 },
        [14297] = { e = 3, s = "c", h = { 85713, 85714, 85715 }, r = "Requires defeating specific combatants last multiple times.", d = "Defeat each combatant of Affront of Challengers last across multiple runs. This account-wide achievement requires careful planning and coordination.", x = 8 },
        [14303] = { e = 3, s = "g", r = "Requires exploring all covered areas of a zone.", d = "Explore all covered areas in Bastion to reveal the world map. Visit every zone and complete any necessary quests or objectives.", x = 8 },
        [14304] = { e = 3, s = "c", r = "Requires exploring multiple zones; moderate time investment.", d = "Complete the main Ardenweald questline to unlock all zones. Then run daily vignettes or use the map to reveal hidden areas like Dusty Burrows and Gormhive.", x = 8 },
        [14305] = { e = 3, s = "c", r = "Requires exploring multiple zones; moderate time investment.", d = "Finish Maldraxxus story quests first, then explore districts like Theater of Pain. Use daily vignettes to quickly reveal remaining covered map areas.", x = 8 },
        [14306] = { e = 3, s = "c", r = "Requires completing 15 encounters; grindable solo.", d = "Unlock Bastion zones via the main questline, then hunt special encounters like Herculon or Unstable Memory. Note that some encounters require specific daily vignette unlocks.", x = 8 },
        [14307] = { e = 3, s = "c", r = "Requires completing 15 encounters; grindable solo.", d = "Complete Maldraxxus story quests to unlock zones, then defeat bosses like Corpsecutter Moroc. Remember that Devour'us requires fifteen kills and may need multiple attempts.", x = 8 },
        [14308] = { e = 3, s = "c", r = "Requires completing 15 encounters; grindable solo.", d = "Finish Ardenweald story quests first, then hunt encounters like Deathbinder Hroth. The Slumbering Emperor needs fifteen kills, so plan your daily runs accordingly.", x = 8 },
        [14309] = { e = 3, s = "c", r = "Requires completing 15 encounters; grindable solo.", d = "Unlock Revendreth zones via the main questline, then defeat bosses like Soulstalker Doina. Famu the Infinite requires fifteen kills and can be done in one session.", x = 8 },
        [14310] = { e = 3, s = "c", r = "Requires completing 15 encounters; grindable solo.", d = "Explore Bastion by finding hidden treasures like Scroll of Aeons or Gift of Agthia. Check daily vignettes for new treasure locations each week.", x = 8 },
        [14311] = { e = 3, s = "c", r = "Collecting scattered items across zones; moderate effort.", d = "Discover Maldraxxus treasures such as Ornate Bone Shield or Forgotten Mementos by exploring hidden corners. Some items like Chest of Eyes are rare drops from vignettes.", x = 8 },
        [14312] = { e = 3, s = "c", r = "Collecting scattered items across zones; moderate effort.", d = "Find Ardenweald treasures like Aerto's Body or Dreamsong Heart by checking vignette rewards and map secrets. Use daily quests to locate elusive caches.", x = 8 },
        [14313] = { e = 3, s = "c", r = "Collecting scattered items across zones; moderate effort.", d = "Locate Revendreth treasures such as Lost Quill or Gilded Plum Chest through vignettes and hidden map areas. Some items like Smuggled Cache are rare drops.", x = 8 },
        [14314] = { e = 3, s = "c", r = "Collecting scattered items across zones; moderate effort.", d = "Earn Revered reputation with The Ascended, The Undying Army, Court of Harvesters, and The Wild Hunt. Focus on daily quests and world events for efficient gains.", x = 8 },
        [14315] = { e = 4, s = "c", h = { 85984, 85985, 85986 }, r = "Reaching Revered with all factions requires significant grinding.", x = 8 },
        [14320] = { e = 3, s = "c", r = "Requires Mythic dungeon run and barrel destruction.", d = "Run Necrotic Wake Mythic and focus on destroying two spare part barrels before killing Surgeon Stitchflesh. Ensure you have enough damage output to clear the arena quickly, as this is a timed objective tied to the boss fight.", x = 8 },
        [14322] = { e = 5, s = "c", h = { 85850, 85851, 85859 }, r = "Depends on completing many other Mythic dungeon achievements.", d = "Complete all listed Shadowlands Mythic dungeon achievements first, as they unlock the mount reward. This requires finishing specific bosses and objectives across multiple dungeons like Necrotic Wake and Spires of Ascension on Mythic difficulty.", x = 8 },
        [14323] = { e = 3, s = "c", r = "Requires specific item drop and boss kill on Mythic.", d = "In Spires of Ascension Mythic, hit Devos with five Spears of Duty before defeating her to claim this achievement. Coordinate with your group to ensure the spears are used effectively during the encounter.", x = 8 },
        [14324] = { e = 3, s = "s", r = "Standard Heroic dungeon clear with specific boss.", d = "Defeat Devos in Spires of Ascension on Heroic or higher difficulty. Start with Heroic if you are new to the dungeon, then progress to Mythic for subsequent achievements in the chain.", x = 8 },
        [14325] = { e = 4, s = "s", r = "Requires Mythic dungeon clear after Heroic.", d = "Complete the Heroic version first, then run Spires of Ascension on Mythic to defeat Devos and unlock this achievement. This is part of a progression chain that must be followed in order.", x = 8 },
        [14326] = { e = 3, s = "s", r = "Standard dungeon clear with specific boss.", d = "Simply defeat Devos in Spires of Ascension on any difficulty to start the progression chain. Ensure your group is prepared for the mechanics of this boss before attempting the run.", x = 8 },
        [14327] = { e = 4, s = "c", h = { 85885 }, r = "Requires Mythic clear and fast orb collection.", d = "After defeating Devos in Spires of Ascension Mythic, collect all five orbs within 60 seconds. This requires quick coordination with your group to grab the orbs before they despawn or move out of range.", x = 8 },
        [14328] = { e = 3, s = "g", r = "Grinding profession skill points in Shadowlands.", d = "Pick one primary profession and level it to maximum skill points in the Shadowlands category. Focus on gathering materials and crafting items relevant to that profession's specific content during the expansion.", x = 8 },
        [14329] = { e = 4, s = "c", r = "Requires maxing two professions first.", d = "Complete the Professional Shadowlands Master achievement first, then choose a second primary profession to max out its Shadowlands skills. This is account-wide, so ensure both characters contribute to leveling these professions.", x = 8 },
        [14330] = { e = 4, s = "c", r = "Requires Mythic clear and destroying three specific objects.", d = "Max out all primary professions in their Shadowlands categories before attempting this achievement. It requires significant time investment across multiple characters or alts to gather the necessary skill points for each profession.", x = 8 },
        [14331] = { e = 4, s = "c", h = { 85923, 87243, 87244 }, r = "Requires Mythic clear and destroying three specific objects.", d = "In Spires of Ascension Mythic, activate and destroy all three Shattered Devastators before defeating Oryphrion. Coordinate with your group to handle the mechanics of destroying these objects efficiently during the boss fight.", x = 8 },
        [14332] = { e = 2, s = "g", r = "Grinding cooking skill points in Shadowlands.", d = "Level cooking to 75 skill points in the Shadowlands category by gathering herbs and cooking recipes available in that expansion. Focus on completing cooking quests and using cooking materials dropped from Shadowlands content.", x = 8 },
        [14333] = { e = 2, s = "g", r = "Grinding fishing skill points is moderate but tedious.", d = "Fish in any Shadowlands zone until your skill reaches 200. This is purely a grind so just fish consistently.", x = 8 },
        [14334] = { e = 1, s = "s", r = "Introduction quest is trivial and account-wide.", d = "Start the introductory questline immediately upon entering Bastion to unlock this account-wide achievement.", x = 8 },
        [14335] = { e = 4, s = "g", r = "Exalted reputation requires significant grinding time.", d = "Grind reputation with Ascended in Bastion until you reach Exalted status for this account-wide reward.", x = 8 },
        [14336] = { e = 4, s = "g", r = "Exalted reputation requires significant grinding time.", d = "Earn Exalted with the Undying Army by completing their specific quest chain or grinding reputation.", x = 8 },
        [14337] = { e = 4, s = "g", r = "Exalted reputation requires significant grinding time.", d = "Complete the Wild Hunt questline in Bastion to reach Exalted status and claim this achievement.", x = 8 },
        [14338] = { e = 4, s = "g", r = "Exalted reputation requires significant grinding time.", d = "Finish the Court of Harvesters questline in Bastion to gain Exalted reputation for this account-wide goal.", x = 8 },
        [14339] = { e = 2, s = "g", r = "Collecting shards is easy but requires some travel.", d = "Collect all lost anima crystal shards scattered throughout Bastion by exploring every corner of the zone.", x = 8 },
        [14347] = { e = 5, s = "c", h = { 86269, 86270, 86271 }, r = "Mythic dungeon with complex checklist mechanics and RNG.", d = "Run Plaguefall on Mythic difficulty and feed Globgrog three specific items before defeating him.", x = 8 },
        [14352] = { e = 5, s = "c", h = { 86414 }, r = "Mythic dungeon requiring precise setup and boss kill.", d = "Place three Sinstone Statues in the room corners before fighting Lord Chamberlain in Halls of Atonement on Mythic.", x = 8 },
        [14353] = { e = 3, s = "c", r = "Watching plays is moderate effort with multiple steps.", d = "Watch all available plays at the Star Lake Amphitheater in Ardenweald to complete this exploration task.", x = 8 },
        [14354] = { e = 5, s = "g", r = "Mythic dungeon requiring specific debuff management.", d = "Defeat De Other Side bosses on Mythic while a party member has Corrupted Blood active for this entire run.", x = 8 },
        [14355] = { e = 5, s = "c", h = { 87892, 87898, 87893 }, r = "Castle Nathria raid requires high-level group play.", d = "Complete every individual achievement listed under Castle Nathria to unlock the main raid title and mount.", x = 8 },
        [14356] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Queue for Castle Nathria on Mythic difficulty and defeat Shriekwing. This is a time-gated achievement requiring the raid to be available in Shadowlands.", x = 8 },
        [14357] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Defeat Huntsman Altimor in Castle Nathria on Mythic difficulty. Ensure you are in a Mythic+ or Mythic raid group before starting.", x = 8 },
        [14358] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Clear the Hungering Destroyer encounter in Castle Nathria on Mythic difficulty. This boss requires specific mechanics and high gear levels.", x = 8 },
        [14359] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Defeat Artificer Xy'mox in Castle Nathria on Mythic difficulty. Coordinate with your group to handle the complex mechanics of this fight.", x = 8 },
        [14360] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Complete the Sun King's Salvation encounter in Castle Nathria on Mythic difficulty. This boss is part of the main raid progression.", x = 8 },
        [14361] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Defeat Lady Inerva Darkvein in Castle Nathria on Mythic difficulty. Be prepared for challenging mechanics that require precise execution.", x = 8 },
        [14362] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Clear The Council of Blood in Castle Nathria on Mythic difficulty. This encounter is a key part of the Shadowlands raid content.", x = 8 },
        [14363] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Defeat Sludgefist in Castle Nathria on Mythic difficulty. Ensure your group is ready for the specific mechanics of this boss fight.", x = 8 },
        [14364] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Clear the Stone Legion Generals encounter in Castle Nathria on Mythic difficulty. This is a multi-phase boss requiring coordinated effort.", x = 8 },
        [14365] = { e = 4, s = "s", r = "Requires full raid group and high skill.", d = "Defeat Sire Denathrius in Castle Nathria on Mythic difficulty to earn the Sinbreaker title. This is the final raid boss of Shadowlands.", x = 8 },
        [14366] = { e = 4, s = "s", r = "Requires Heroic+ dungeon group and luck.", d = "Defeat Nalthor the Rimebinder in The Necrotic Wake dungeon. Start with Normal or Heroic difficulty before attempting higher tiers.", x = 8 },
        [14367] = { e = 4, s = "s", r = "Requires Mythic+ dungeon group and luck.", d = "Complete The Necrotic Wake on Heroic difficulty or higher. This achievement requires defeating the boss after unlocking the Heroic tier.", x = 8 },
        [14368] = { e = 4, s = "s", r = "Mythic dungeon boss requires group coordination and gear.", d = "Complete Heroic The Necrotic Wake first to unlock the boss. Then run Mythic or Mythic+ versions of the dungeon until you defeat Nalthor the Rimebinder.", x = 8 },
        [14369] = { e = 4, s = "s", r = "Heroic dungeon boss requires group coordination and gear.", d = "Finish Heroic Plaguefall before attempting this achievement. Simply defeat Margrave Stradama in the dungeon on any difficulty equal to or higher than Heroic.", x = 8 },
        [14370] = { e = 4, s = "s", r = "Heroic dungeon boss requires group coordination and gear.", d = "Unlock Halls of Atonement by completing the base version first. Defeat Lord Chamberlain on Heroic or higher difficulty to claim the points.", x = 8 },
        [14371] = { e = 4, s = "s", r = "Mythic dungeon boss requires group coordination and gear.", d = "Start with the base Mists of Tirna Scithe dungeon. You must defeat Tred'ova on Heroic or higher difficulty to complete this task.", x = 8 },
        [14372] = { e = 4, s = "s", r = "Heroic raid boss fight requires full group effort.", d = "Unlock Theater of Pain by finishing the base dungeon first. Defeat Mordretha, the Endless Empress on Heroic or higher difficulty for the achievement.", x = 8 },
        [14373] = { e = 4, s = "s", r = "Mythic dungeon boss requires group coordination and gear.", d = "Complete the base De Other Side dungeon to unlock it. Then defeat Mueh'zala on Heroic or higher difficulty to finish this requirement.", x = 8 },
        [14374] = { e = 5, s = "c", r = "Requires specific mechanics on Mythic; high RNG/coordination.", d = "Run Mythic De Other Side and ensure both bosses hit each other with their specific abilities. You must also kill the Manastorms during this run.", x = 8 },
        [14375] = { e = 5, s = "c", r = "Requires killing a rare spawn before the boss.", d = "Run Mythic Mists of Tirna Scithe and defeat an Enlightened Spinemaw Gorger first. Immediately after, kill Tred'ova to complete the Hunger for Knowledge criteria.", x = 8 },
        [14376] = { e = 5, s = "c", r = "Requires draining all canisters; heavy RNG/coordination.", d = "Unlock Castle Nathria by completing the base raid instance first. Drain all large anima canisters using Volatile Ejection before defeating the Hungering Destroyer on Normal or higher.", x = 8 },
        [14408] = { e = 4, s = "s", r = "Heroic dungeon boss requires group coordination and gear.", d = "Finish the base De Other Side dungeon to unlock Heroic mode. Defeat Mueh'zala on Heroic difficulty or higher to earn these points.", x = 8 },
        [14409] = { e = 5, s = "s", r = "Mythic dungeon boss requires high-level group coordination.", d = "Complete Heroic De Other Side first as a prerequisite. Then run Mythic or Mythic+ De Other Side and defeat Mueh'zala to finish this achievement.", x = 8 },
        [14410] = { e = 4, s = "s", r = "Heroic dungeon boss requires group coordination and gear.", d = "Unlock Halls of Atonement by finishing the base dungeon first. Defeat Lord Chamberlain on Heroic difficulty or higher to claim the points before moving to Mythic.", x = 8 },
        [14411] = { e = 3, s = "s", r = "Requires Mythic+ dungeon run; moderate difficulty.", d = "Complete Heroic Halls of Atonement first to unlock the Mythic version. Defeat Lord Chamberlain on Mythic difficulty for this achievement; ensure your group is prepared for high-level mechanics.", x = 8 },
        [14412] = { e = 3, s = "s", r = "Heroic dungeon boss kill; moderate difficulty.", d = "Defeat Tred'ova in Mists of Tirna Scithe on Heroic or higher. This unlocks the Mythic version next, so clear Heroic before attempting the harder difficulty.", x = 8 },
        [14413] = { e = 4, s = "s", r = "Mythic+ dungeon run; high RNG and skill.", d = "You must have completed Heroic Mists of Tirna Scithe first. Then defeat Tred'ova on Mythic or Mythic Keystone difficulty to claim this achievement.", x = 8 },
        [14414] = { e = 3, s = "s", r = "Heroic dungeon boss kill; moderate difficulty.", d = "Clear Plaguefall on Heroic difficulty before attempting the Mythic version. Defeat Margrave Stradama on Heroic or higher to earn these points.", x = 8 },
        [14415] = { e = 4, s = "s", r = "Mythic+ dungeon run; high RNG and skill.", d = "Finish Heroic Plaguefall first as a prerequisite. Then defeat Margrave Stradama on Mythic difficulty to complete this specific dungeon achievement.", x = 8 },
        [14416] = { e = 3, s = "s", r = "Heroic dungeon boss kill; moderate difficulty.", d = "Complete Theater of Pain on Heroic difficulty or higher to start the chain. Defeat Mordretha, the Endless Empress on Heroic to unlock the Mythic version.", x = 8 },
        [14417] = { e = 4, s = "s", r = "Mythic+ dungeon run; high RNG and skill.", d = "You need Heroic Theater of Pain completed first. Then defeat Mordretha, the Endless Empress on Mythic difficulty for this achievement.", x = 8 },
        [14418] = { e = 3, s = "c", h = { 86920 }, r = "Requires 8 Heroic dungeons; one is very hard.", d = "This account-wide achievement requires all eight Shadowlands Heroic dungeon bosses to be defeated. Clear every Heroic dungeon listed in the info field before claiming the reward.", x = 8 },
        [14463] = { e = 3, s = "s", r = "Torghast Layer 1; moderate RNG and skill.", d = "Enter Torghast and successfully complete the first Layer of Skoldus Hall. This is a self-contained objective within the tower instance.", x = 8 },
        [14468] = { e = 2, s = "g", r = "Torghast Layer 1; steady progress with time.", d = "Complete Layer 1 of Twisting Corridors in Torghast to unlock Layer 2. This is an account-wide achievement that progresses sequentially through the tower.", x = 8 },
        [14469] = { e = 3, s = "g", r = "Torghast Layer 2; requires previous layer.", d = "Finish Layer 2 of Twisting Corridors before attempting Layer 3. Completing this layer grants the Death Seeker pet as a reward.", x = 8 },
        [14470] = { e = 3, s = "g", r = "Torghast Layer 3; requires previous layers.", d = "You must complete Layer 3 of Twisting Corridors first to unlock Layer 4. Progress through these layers sequentially in Torghast.", x = 8 },
        [14471] = { e = 3, s = "g", r = "Requires completing previous layer first.", d = "Complete Layer 3 first to unlock this layer. Run it solo or in a group until you reach the top, then return to repeat if needed for account-wide progress.", x = 8 },
        [14472] = { e = 3, s = "g", r = "Requires completing previous layer first.", d = "Finish Layer 4 before attempting this one. Clear the entire tower once, as rewards are account-wide and no further repeats are necessary after completion.", x = 8 },
        [14473] = { e = 3, s = "s", r = "Single run of a specific Torghast mode.", d = "Start Fracture Chambers immediately after unlocking Torghast. This instance is soloable and requires no specific gear beyond what you have from previous layers.", x = 8 },
        [14478] = { e = 3, s = "s", r = "Single run of a specific Torghast mode.", d = "Enter The Soulforges once unlocked. It is a solo-friendly dungeon where you simply need to reach the top without dying or failing the encounter.", x = 8 },
        [14483] = { e = 3, s = "s", r = "Single run of a specific Torghast mode.", d = "Clear Coldheart Interstitia as soon as it becomes available. This layer functions like a standard Torghast run and can be completed entirely alone.", x = 8 },
        [14488] = { e = 3, s = "s", r = "Single run of a specific Torghast mode.", d = "Complete Mort'regar after unlocking the instance. Focus on surviving the mechanics at the top; no group is required for this specific achievement.", x = 8 },
        [14493] = { e = 3, s = "s", r = "Single run of a specific Torghast mode.", d = "Finish The Upper Reaches once accessible. Treat it as a standard Torghast ascent and ensure you reach the summit to claim your account-wide credit.", x = 8 },
        [14498] = { e = 3, s = "g", r = "Requires defeating many bosses across modes.", d = "Defeat all listed bosses in any order within Torghast. You can do this solo or with friends, but ensure every boss name appears on your tracker before finishing.", x = 8 },
        [14499] = { e = 3, s = "g", r = "Grinding Phantasma drops from Torghast runs.", d = "Farm Phantasma by running Torghast layers repeatedly. Once you hit 2500, the next tier unlocks automatically without needing to restart the collection process.", x = 8 },
        [14500] = { e = 3, s = "g", r = "Continues grinding Phantasma after previous goal.", d = "Continue farming Phantasma after reaching 2500. The counter stacks globally, so keep running Torghast until you hit the 25,000 threshold for the next achievement.", x = 8 },
        [14501] = { e = 3, s = "g", r = "Continues grinding Phantasma after previous goal.", d = "Keep farming Phantasma after hitting 25,000. This is a long-term goal requiring many Torghast runs, but no new mechanics or groups are needed.", x = 8 },
        [14502] = { e = 3, s = "c", h = { 87091 }, r = "Requires defeating multiple covenant trial bosses.", d = "Complete the first eight Trials of Loyalty in your Covenant Sanctum. These are soloable encounters that unlock sequentially as you progress through the trials.", x = 8 },
        [14503] = { e = 4, s = "c", r = "Requires specific dungeon run with rare spawn kill.", d = "Start by defeating the Overgrown Hydra in Tirna Scithe on Mythic difficulty. Immediately proceed to fight Ingra Maloch without leaving the instance to avoid resetting progress.", x = 8 },
        [14511] = { e = 3, s = "g", r = "Grinding honor in a zone takes a few hours.", d = "Enable War Mode and queue for Ardenweald PvP or run world quests there. Farm honor until you hit 1000, then turn it in.", x = 8 },
        [14512] = { e = 3, s = "g", r = "Grinding honor in a zone takes a few hours.", d = "Enable War Mode and farm Revendreth PvP or world quests to earn 1000 honor. This is account-wide, so one character can complete it for everyone.", x = 8 },
        [14513] = { e = 3, s = "g", r = "Grinding honor in a zone takes a few hours.", d = "Enable War Mode and grind Maldraxxus PvP or world quests until you have 1000 honor. Note that this progress carries over across all characters on your account.", x = 8 },
        [14514] = { e = 3, s = "g", r = "Grinding honor in a zone takes a few hours.", d = "Enable War Mode and earn 1000 honor in Bastion through PvP or world quests. Ensure you stay in the zone to count toward the total.", x = 8 },
        [14515] = { e = 2, s = "c", r = "Simple world quests with no complex requirements.", d = "Complete all listed Shadowlands World PvP quests once. These are account-wide, so finish them on any character while War Mode is active.", x = 8 },
        [14516] = { e = 3, s = "g", r = "Repeating simple world quests is a moderate grind.", d = "Repeat each specific World PvP quest in Shadowlands twenty times. Keep track of your counts as these do not stack automatically with other runs.", x = 8 },
        [14519] = { e = 2, s = "c", r = "Killing PvP players is fast and easy to do.", d = "Kill twenty enemy players for each Covenant listed. You must target specific factions, so check the kill counter after every combat encounter.", x = 8 },
        [14523] = { e = 4, s = "c", r = "Requires specific raid mechanics and multiple steps.", d = "On Normal or higher difficulty, walk Margore, Bargast, and Hecutis to their respective corners in Castle Nathria before killing Huntsman Altimor.", x = 8 },
        [14524] = { e = 3, s = "c", r = "Standard raid fight with a pre-fight condition.", d = "Defeat the Dark Animus first on Normal or higher difficulty, then proceed to kill Lady Inerva Darkvein immediately afterward.", x = 8 },
        [14525] = { e = 3, s = "c", r = "Requires crafting item and specific boss encounter.", d = "Acquire Bouquets of Blooming Sanguine Roses before entering Castle Nathria. Ensure every player in your group holds a bouquet when fighting the Stone Legion Generals.", x = 8 },
        [14533] = { e = 4, s = "c", r = "Mythic dungeon with rare spawn mechanics involved.", d = "Use /challenge to summon Mordretha on Mythic difficulty, defeat two Ghostly Contenders first, then kill the Endless Empress without leaving the Theater of Pain.", x = 8 },
        [14567] = { e = 3, s = "s", r = "Requires Mythic dungeon run and specific boss mechanic.", d = "Defeat Halkias on Mythic difficulty after he reabsorbs all three Shards of Halkias in the Halls of Atonement. Ensure you wait for the final phase where he absorbs the shards before killing him to trigger the achievement.", x = 8 },
        [14568] = { e = 2, s = "g", r = "Torghast Layer 6 is a short climb for prepared players.", d = "Complete Layer 6 of Twisting Corridors in Torghast, which requires finishing Layer 5 first. This is account-wide and unlocks the Spirestalker title upon completion.", x = 8 },
        [14569] = { e = 3, s = "g", r = "Layer 7 requires clearing previous layers and higher difficulty.", d = "Finish Layer 7 of Twisting Corridors immediately after clearing Layer 6, as these layers are sequential. Progress through the twisting corridors until you reach this specific layer to earn the points.", x = 8 },
        [14570] = { e = 3, s = "g", r = "Layer 8 is the final Torghast layer, requiring high skill.", d = "Clear Layer 8 of Torghast after completing Layer 7 to receive the Corridor Creeper mount. This is account-wide and part of the main progression chain for the tower.", x = 8 },
        [14606] = { e = 3, s = "s", r = "Requires Mythic dungeon run and collecting orbs before boss.", d = "Defeat Dealer Xy'exa on Mythic difficulty in De Other Side only after collecting all five floating orbs above her. Do not kill her until every orb has been gathered to avoid missing the achievement.", x = 8 },
        [14607] = { e = 2, s = "g", r = "Meat tenderizing is a quick mechanic inside the Theater of Pain.", d = "Use the Tenderizing Smash ability on Gorechop in the Theater of Pain until two hunks of meat are tenderized. Then defeat him on Mythic difficulty while the meat is still prepared.", x = 8 },
        [14608] = { e = 3, s = "s", r = "Requires raiding Castle Nathria and lighting braziers.", d = "Light all four braziers in Castle Nathria before redeeming Kael'thas to complete this raid achievement. You can do this on Normal difficulty or higher, so ensure every brazier is lit first.", x = 8 },
        [14610] = { e = 3, s = "s", r = "Requires specific raid mechanics on Sire Denathrius.", d = "Remove the Burden of Sin from every player before March of the Penitent casts its effect during Sire Denathrius. Coordinate with your group to clear all burdens quickly to avoid failure.", x = 8 },
        [14614] = { e = 2, s = "g", r = "Collecting a T26 set is easy once the raid is cleared.", d = "Collect any armor set from Castle Nathria on at least one class to earn this account-wide appearance achievement. Focus on obtaining a full tier set rather than individual pieces for this specific goal.", x = 8 },
        [14617] = { e = 3, s = "s", r = "Requires specific Anima drops and returning them in Castle Nathria.", d = "Return loose Anima from Maldraxxus, Ardenweald, and the Maw to their display cases before defeating Artificer Xy'mox. Ensure all three types of anima are returned on Normal difficulty or higher.", x = 8 },
        [14619] = { e = 2, s = "s", r = "Throwing wine bottles is a simple interaction during the fight.", d = "Throw four bottles of wine at the Council of Blood in Castle Nathria before defeating them. Make sure you have the bottles and throw all four to trigger the achievement condition.", x = 8 },
        [14625] = { e = 3, s = "g", r = "Requires completing 14 specific pet battle world quests.", d = "Complete fourteen specific Pet Battle World Quests across Shadowlands zones using a full team of level 25 pets. Track each unique quest name listed in the info field to ensure you complete all required battles.", x = 8 },
        [14626] = { e = 3, s = "s", r = "Requires specific dungeon run and rare drop.", d = "Defeat the boss in Theater of Pain to drop Sorrowbane, then turn it in immediately as this item is missable upon zone reset. Ensure you have access to the raid instance before attempting this specific collection goal.", x = 8 },
        [14627] = { e = 2, s = "c", r = "Simple quest selection at character creation.", d = "Complete your initial Covenant choice questline early in Shadowlands to unlock Sanctum features and begin earning Renown points efficiently. Do not delay this step, as it gates progression into all subsequent covenant-specific achievements.", x = 8 },
        [14628] = { e = 3, s = "g", r = "Requires grinding renown through various activities.", d = "Grind Renown through daily activities and world quests until you hit level 10, which unlocks the next tier of rewards. This is a linear progression that requires consistent engagement with your chosen Covenant's reputation sources.", x = 8 },
        [14629] = { e = 3, s = "g", r = "Continues renown grind to next level.", d = "Continue farming Renown to reach level 20, unlocking new abilities and gear options within your Sanctum. Maintain steady progress by completing weekly contracts and daily quests to avoid falling behind the recommended pace.", x = 8 },
        [14630] = { e = 3, s = "g", r = "Continues renown grind to next level.", d = "Push your Renown to level 30 by focusing on high-yield activities like world bosses and dungeon runs. This milestone grants significant power boosts, so prioritize it alongside other endgame content.", x = 8 },
        [14631] = { e = 3, s = "g", r = "Continues renown grind to max level.", d = "Reach Renown level 40 through dedicated farming sessions, ensuring you maximize efficiency with your current Covenant's bonuses. Be prepared for increased competition for reputation sources as you approach this cap.", x = 8 },
        [14632] = { e = 3, s = "s", r = "Requires unlocking specific sanctum feature.", d = "Unlock Rank III of your Anima Conductor by completing specific Sanctum upgrades and collecting necessary resources. This achievement is tied to your Sanctum's development, so focus on upgrading other features first if needed.", x = 8 },
        [14633] = { e = 3, s = "s", r = "Requires unlocking specific sanctum feature.", d = "Expand your Travel Network to Rank III by exploring all regions connected to your Sanctum. Use the map interface to identify missing nodes and visit them systematically to complete this requirement.", x = 8 },
        [14634] = { e = 4, s = "c", h = { 87527, 87528, 87529 }, r = "Finding all kittens involves heavy RNG and travel.", d = "Visit Maldraxxus frequently to find and pet all nine kittens, as they appear randomly in specific locations. This achievement is account-wide but requires physical presence in the zone, so plan your rotations accordingly.", x = 8 },
        [14636] = { e = 3, s = "s", r = "Requires unlocking specific sanctum feature.", d = "Unlock Rank III of your Adventures Command Table by completing various adventure quests and earning sufficient experience points. Focus on high-level adventures that offer better rewards to speed up this process.", x = 8 },
        [14637] = { e = 3, s = "s", r = "Requires unlocking specific sanctum feature.", d = "Maximize your Special Feature to Rank V by engaging with all available special events and challenges within your Sanctum. This may involve collecting rare items or completing time-limited objectives, so stay vigilant for new opportunities.", x = 8 },
        [14638] = { e = 3, s = "s", r = "Requires unlocking all anima locations.", d = "Connect all Anima Conductor locations by unlocking every node in your network. This requires visiting specific zones and completing associated tasks, so ensure you have explored the entire map of your Covenant's territory.", x = 8 },
        [14639] = { e = 2, s = "g", r = "50 uses is a short grind for any active player.", d = "Join any Covenant Sanctum and use your Anima Conductor repeatedly to gather resources for crafting or upgrades. This is account-wide, so one player can complete it for everyone in the group.", x = 8 },
        [14656] = { e = 3, s = "c", r = "Requires grinding reputation to Appreciated level.", d = "Travel to The Maw and grind against enemies to earn Ve'nari reputation until you reach the Appreciated tier. Focus on high-reputation zones within the zone to speed up progress efficiently.", x = 8 },
        [14658] = { e = 2, s = "g", r = "Rescuing souls is a quick repeatable action.", d = "Rescue souls by completing world quests or defeating specific targets in The Maw that drop soul fragments. You can do this solo, but group up for faster completion of difficult encounters.", x = 8 },
        [14659] = { e = 3, s = "c", r = "Defeating 5 specific bosses takes some time but is doable solo.", d = "Defeat the five special encounter bosses listed in the info field within The Maw. These are optional objectives, so prioritize them after main story content to avoid missing them later.", x = 8 },
        [14660] = { e = 4, s = "c", h = { 87640 }, r = "Valis the Cruel RNG makes this checklist significantly harder.", d = "Complete all remaining special encounters in The Maw, including the additional ones beyond the first five. Ensure you have cleared previous achievements like Handling His Henchmen before attempting this one.", x = 8 },
        [14663] = { e = 2, s = "g", r = "Exploring zones is fast once areas are unlocked.", d = "Explore every zone and subzone in The Maw to reveal hidden areas on your map. Use flying mounts if available and check caves or inaccessible regions for completion.", x = 8 },
        [14670] = { e = 2, s = "c", r = "Incubating spirits is a quick repeatable task.", d = "Visit the Queen's Conservatory in your Covenant Sanctum and incubate one spirit from each of the four covenant types. You can use any level spirit, so start with basic ones first.", x = 8 },
        [14671] = { e = 3, s = "s", r = "Requires specific timing and luck on one quest.", d = "Start the Tough Crowd world quest in Ardenweald and expose eight boggarts consecutively without guessing wrong within 20 minutes. Practice timing your accusations carefully to avoid resetting the counter.", x = 8 },
        [14672] = { e = 2, s = "c", r = "Collecting gifts from a world quest is straightforward.", d = "Complete the We'll Workshop It world quest in Ardenweald and try all available artisan buffs to collect every gift item. Save this for when you have access to all necessary reagents or buffs.", x = 8 },
        [14675] = { e = 3, s = "c", r = "Greater spirits require more incubation time than basic ones.", d = "Incubate one greater spirit from each covenant type in the Queen's Conservatory after unlocking the ability to use them. Greater spirits require higher Anima levels, so progress through lower tiers first.", x = 8 },
        [14676] = { e = 4, s = "c", r = "Divine spirits are rare drops requiring significant RNG luck.", d = "Use divine garden spirits to incubate one of each divine spirit type in the Queen's Conservatory. Divine spirits are rare, so ensure you have enough Anima and time for this final tier.", x = 8 },
        [14677] = { e = 2, s = "s", r = "Completing observation quests is a simple multi-step task.", d = "Complete all observation quests given by Falir in the Queen's Conservatory to unlock spiritual insights. These quests may appear periodically, so check back regularly after unlocking the area.", x = 8 },
        [14678] = { e = 3, s = "g", r = "Collecting 10 random items from various zones.", d = "Unlock all Covenant Arsenal items first, as they are required for other achievements. Farm Anima-Infused Water and specific quest rewards like the Crown of Honor to progress. This is account-wide but requires visiting each Sanctum zone.", x = 8 },
        [14679] = { e = 3, s = "g", r = "Gathering upgrades and staff from multiple sources.", d = "Purchase buildings and staff from the Dredger Academy trainer after unlocking Court Favors. Prioritize hiring ambassadors for all zones to complete the guest list upgrades quickly. Ensure you have enough gold before buying expensive furniture sets.", x = 8 },
        [14680] = { e = 3, s = "g", r = "Completing various quests and collecting items.", d = "Complete various zone-specific quests and collect items like Traditional Decorations and Divine Desserts. Some amenities require specific NPC interactions or rare drops from world events. Check your quest log regularly for hidden objectives related to these upgrades.", x = 8 },
        [14681] = { e = 2, s = "g", r = "Training dredger skills via simple zone visits.", d = "Travel to each Covenant zone to complete the Etiquette quests and learn riding abilities. Train your dredger in Maldraxxus first, then move on to other zones for variety. These are account-wide achievements so progress carries over across characters.", x = 8 },
        [14682] = { e = 3, s = "c", r = "Requires completing other Covenant achievements first.", d = "Complete all previous Ember Court achievements listed in this meta-achievement before starting new ones. The title rewards come after finishing everything else, so plan your order carefully. Some sub-objectives may be missable if you do not check the Dredger Academy.", x = 8 },
        [14683] = { e = 2, s = "g", r = "Unlocking cosmetic options via simple interactions.", d = "Unlock cosmetic dye options and hair cuts by completing specific quests or purchasing from vendors. These items are account-wide, so start with basic dyes before moving to complex styles. Ensure your dredger has enough reputation to buy all available outfits.", x = 8 },
        [14684] = { e = 3, s = "g", r = "Completing a series of Abominable Stitching quests.", d = "Start the Abominable Stitching questline in Maldraxxus and complete all associated world quests. Some objectives involve finding specific corpses or completing training programs that may have timers. Finish these before leaving the zone to avoid missing rare drop opportunities.", x = 8 },
        [14715] = { e = 4, s = "c", h = { 87901, 87902, 87903 }, r = "Defeating all Castle Nathria bosses on any difficulty.", d = "Defeat all bosses in Castle Nathria on Normal difficulty first, then unlock Heroic and Mythic versions. Use a group with high DPS for faster clears, especially against Sire Denathrius. This achievement is account-wide, so coordinate with friends or guild members.", x = 8 },
        [14717] = { e = 5, s = "c", h = { 87912, 87913, 87914 }, r = "Defeating all Castle Nathria bosses on Heroic.", d = "Clear all bosses on Heroic difficulty after completing Normal mode to unlock further challenges. Some encounters require specific strategies or gear upgrades before attempting them. Coordinate with your group to ensure everyone contributes effectively during fights.", x = 8 },
        [14718] = { e = 5, s = "c", h = { 87923, 87924, 87925 }, r = "Defeating all Castle Nathria bosses on Mythic.", d = "Complete Mythic Castle Nathria by defeating all bosses in order, starting from Shriekwing. This difficulty requires optimal gear and coordination, so prepare thoroughly before beginning. The achievement is account-wide, making it easier to share progress with others.", x = 8 },
        [14721] = { e = 3, s = "g", r = "Defeating seven specific creations from the pool.", d = "Defeat all seven creations from the Pool of Mixed Monstrosities in Revendreth for a rare toy reward. These creatures appear randomly, so check the mixing pool frequently during your visits. The achievement is account-wide, allowing you to farm these efficiently with friends.", x = 8 },
        [14723] = { e = 3, s = "g", r = "Hosting various guests at your Ember Court.", d = "Host guests at your Ember Court by completing specific quests and collecting unique items. Some guests require rare drops or special events, so keep an eye on world news. This achievement is account-wide, so progress will carry over across all characters.", x = 8 },
        [14724] = { e = 3, s = "c", r = "Talk to 15 guests; requires specific items and time.", d = "Gather all required guests in Revendreth's Ember Court to reach Elated mood. Complete this early as it is account-wide and time-gated by the expansion.", x = 8 },
        [14725] = { e = 3, s = "c", r = "Host court with 4 happy guests; requires item prep.", d = "Host a single Ember Court with four Elated guests simultaneously. This requires managing guest moods efficiently during one session.", x = 8 },
        [14726] = { e = 3, s = "c", r = "Achieve 9 attributes via items/events; moderate grind.", d = "Cycle through all Ember Court attributes like Messy or Formal to reach high levels. Do this early since the court resets daily.", x = 8 },
        [14727] = { e = 3, s = "g", r = "Complete 10 events in one session; steady progress.", d = "Complete ten events within one Ember Court session by inviting diverse guests. Plan your invites carefully to maximize event variety.", x = 8 },
        [14728] = { e = 3, s = "g", r = "Pet 15 critters in Draenor; requires travel and time.", d = "Use the /love command on every rare critter in Draenor. This is account-wide and can be done at any level after unlocking the zone.", x = 5 },
        [14729] = { e = 3, s = "g", r = "Pet 15 critters on Broken Shore; requires travel.", d = "Love all rare critters found on the Broken Shore in Legion. Ensure you visit this zone specifically to avoid missing any targets.", x = 6 },
        [14730] = { e = 3, s = "g", r = "Pet 15 critters in Kul Tiras/Zandalar; requires travel.", d = "Travel to Kul Tiras and Zandalar to love their respective rare critters. This is account-wide but requires visiting both zones.", x = 7 },
        [14731] = { e = 3, s = "g", r = "Pet 15 critters in Shadowlands; requires travel.", d = "Love all rare critters in the Shadowlands regions. Check each zone thoroughly as these are account-wide and missable if not done properly.", x = 8 },
        [14733] = { e = 3, s = "s", r = "Survive Sundancer once; moderate difficulty fight.", d = "Survive Sundancer's wrath in Bastion to unlock the trial by combat. This is a rare drop or specific encounter requiring preparation.", x = 8 },
        [14734] = { e = 2, s = "c", r = "Ring 5 bells in Bastion; simple location check.", d = "Ring all five temple vespers in Bastion to summon the Ascended Council. Locate each bell and ring them in one visit.", x = 8 },
        [14735] = { e = 3, s = "c", r = "Complete 3 specific world quests; moderate time.", d = "Complete every Flight School World Quest in Bastion. These quests appear randomly, so check daily for new opportunities.", x = 8 },
        [14737] = { e = 3, s = "c", r = "Read 8 tales from world quests; requires travel.", d = "Read the Tales of Things Remembered from each listed character in Bastion. Visit each NPC to trigger their specific world quest.", x = 8 },
        [14738] = { e = 2, s = "c", r = "Four distinct hunts in The Maw; straightforward completion.", d = "Complete all four specific hunts in The Maw to earn this achievement. Start by checking the quest tracker for available hunt types and finish them sequentially, as you cannot unlock new ones until previous objectives are done.", x = 8 },
        [14741] = { e = 3, s = "s", r = "Specific world quest chain with hard mode requirement.", d = "This requires finishing the 'Flight School: Flapping Frenzy' world quest on Hard Mode in Bastion first. Once unlocked, complete the Paragon's Challenge during that specific event to claim your points.", x = 8 },
        [14742] = { e = 2, s = "g", r = "Kill 100 Assassins; steady progress reduces remaining time.", d = "You must kill 100 assassins sent via the Eye of the Jailer while in The Maw. These enemies spawn randomly, so keep exploring different zones and be ready to engage them immediately when they appear.", x = 8 },
        [14743] = { e = 2, s = "c", r = "Kill 5 specific rares; low count makes it easy.", d = "Kill five rare or rare elite bosses found throughout The Maw. Start with easier encounters like Adjutant Dekaris or Conjured Death, and ensure you are in the correct zone before attempting each specific boss.", x = 8 },
        [14744] = { e = 3, s = "c", r = "Kill all rares in The Maw; checklist but manageable.", d = "This is a follow-up to Deadly Serious requiring you to kill all remaining rare elites in The Maw. After finishing the previous tier, simply continue hunting bosses until every single one listed in the achievement is defeated.", x = 8 },
        [14745] = { e = 2, s = "g", r = "Steal 50 items from specific mobs; steady grind.", d = "Steal 50 Shadehounds from Mawsworn Outriders by using your class ability or a pet to interrupt them. Farm this efficiently by focusing on areas where Outriders frequently spawn and stealing quickly before they escape.", x = 8 },
        [14746] = { e = 1, s = "s", r = "Gain access via simple quest or zone visit.", d = "Gain access to Perdition Hold by progressing through The Maw's story quests until you unlock the new zone. This is time-gated by completing prior content, so ensure you have finished earlier chapters first.", x = 8 },
        [14747] = { e = 1, s = "s", r = "Gain access via simple quest or zone visit.", d = "Unlock The Beastwarrens by advancing further in The Maw storyline. Like other zones, this requires finishing previous narrative steps before you can enter and explore the new area for rewards.", x = 8 },
        [14748] = { e = 3, s = "c", h = { 89167 }, r = "Craft 25 items; RNG drop (Hitchhiker) dominates effort.", d = "Create 25 fashion accessories using Abominable Stitching in Maldraxxus. You can craft any of the listed hats or items, so mix them up to reach the count without waiting for specific drops.", x = 8 },
        [14749] = { e = 3, s = "c", r = "Find specific hats in Revendreth; moderate search time.", d = "Help Rendle find four specific hats in Revendreth's Ember Court event. Participate in the Ember Court festivities and collect these unique items as they appear during the celebration.", x = 8 },
        [14751] = { e = 4, s = "c", h = { 88209 }, r = "Build many constructs; Guillotine requires heavy RNG grind.", d = "Build all listed constructs using Abominable Stitching in Maldraxxus. Craft each construct individually, starting with simpler ones like Chordy or Flytrap, until you have created every single model on the list.", x = 8 },
        [14752] = { e = 4, s = "c", h = { 88179 }, r = "Meta achievement requiring all sub-tasks; RNG lives dominate.", d = "Complete this meta-achievement by finishing all other Abominable Stitching tasks first. Once Wardrobe Makeover, The Gang's All Here, and others are done, claim your title and mount as the final reward for completing the entire crafting line.", x = 8 },
        [14753] = { e = 2, s = "g", r = "Grinding Anima Wraps is easy but takes time.", d = "Farm Anima-Bound Wraps from Maldraxxus dungeons or world quests until you have 100, then turn them in to Summoner Gerard. This is account-wide and requires no specific group composition beyond having enough wraps.", x = 8 },
        [14754] = { e = 3, s = "s", r = "Requires finding a specific Torghast floor and boss.", d = "Visit the Runecarver in Torghast and complete the dialogue option to free him from his bonds. You can do this alone without any special items or prior progression.", x = 8 },
        [14755] = { e = 4, s = "c", h = { 88188 }, r = "Crafting a legendary requires high-level gear and RNG.", d = "Craft a legendary item using the Runecarver's services in Torghast, which requires you to have access to the crafting system first. Ensure you have the necessary materials before attempting this task.", x = 8 },
        [14758] = { e = 3, s = "g", r = "Completing 100 unique world quests takes several hours.", d = "Complete 100 unique world quests across all zones of Shadowlands, including Bastion, Maldraxxus, Revendreth, and the Maw. Track your progress carefully as duplicates do not count toward the total.", x = 8 },
        [14759] = { e = 2, s = "s", r = "Returning a memory is a quick Torghast task.", d = "Return memories to the Runecarver in Torghast by completing specific objectives within the tower. This is part of a chain leading to further achievements, so prioritize it early.", x = 8 },
        [14760] = { e = 3, s = "g", r = "Returning 10 memories requires repeated Torghast runs.", d = "Collect and return 10 different memories to the Runecarver after unlocking the previous memory achievement. These are found throughout Torghast floors and require exploration.", x = 8 },
        [14761] = { e = 4, s = "c", h = { 88217 }, r = "Collecting all Maw Lore items involves rare drops.", d = "Gather all Maw Lore items scattered across The Maw zone, including cryptograms, maps, and grimoires. Some items may be rare drops or require specific world quests to unlock.", x = 8 },
        [14762] = { e = 3, s = "s", r = "Completing a specific hard-mode world quest once.", d = "Complete the Paragon's Challenge during the Bastion world quest Flight School: Up and Away! in hard mode. This is a timed event, so coordinate with your group for success.", x = 8 },
        [14763] = { e = 2, s = "c", r = "Collecting customization items is mostly solo and easy.", d = "Collect every customization item for the Necrotic Acolyte disguise in Maldraxxus from various sources like dungeons and world quests. These items are account-wide and can be turned in once collected.", x = 8 },
        [14764] = { e = 3, s = "s", r = "Finding the Great Luckydo requires exploration/RNG.", d = "Work with Chordy to discover the Great Luckydo, which involves completing specific tasks or events within the Covenant Sanctum. This may require exploring different areas of Maldraxxus.", x = 8 },
        [14765] = { e = 2, s = "g", r = "Winning races is easy but needs repetition.", d = "Win the It's Race Day in the Ramparts world quest 10 times by participating in races across Revendreth. These are solo-friendly but can be done faster with a group.", x = 8 },
        [14766] = { e = 2, s = "g", r = "Completing the parasol quest 10 times is straightforward.", d = "Master Parasoling by completing the Parasol Peril world quest 10 times in Revendreth. This involves navigating the skies and collecting items, which can be challenging without preparation.", x = 8 },
        [14767] = { e = 2, s = "c", r = "Collectible buffs in one zone; low RNG.", d = "Complete the Bastion questline to unlock all Purified Blessings. Visit each blessing location in the zone while standing near its source to receive the buff, then return to the NPC to claim it.", x = 8 },
        [14768] = { e = 2, s = "c", r = "Area buffs in temples; no RNG involved.", d = "Travel to every temple in Bastion and stand within range of each Hymn statue. Ensure you are affected by the aura before leaving the area or logging out to secure progress.", x = 8 },
        [14769] = { e = 3, s = "g", r = "Requires collecting rubies and finding statues.", d = "Gather infused rubies from Dredbat corpses in Revendreth. Use them at each statue to animate it; this is account-wide so help friends if needed.", x = 8 },
        [14770] = { e = 2, s = "c", r = "Rentable rides to fixed locations; no RNG.", d = "Rent Castle Sinrunners from the NPC in Revendreth and ride to each listed location. You must visit every specific gate or area listed in the achievement description.", x = 8 },
        [14771] = { e = 2, s = "c", r = "Ride specific carriages; mostly linear progress.", d = "Locate and ride each carriage found throughout Revendreth. Some may be hidden or require specific triggers, so explore thoroughly before assuming a carriage is unobtainable.", x = 8 },
        [14772] = { e = 3, s = "s", r = "Single world quest with a difficulty constraint.", d = "Start the world quest Secret Service and maintain your disguise until completion. Do not engage enemies or use abilities that reveal your identity during the entire sequence.", x = 8 },
        [14773] = { e = 3, s = "g", r = "Requires specific power and killing many mobs.", d = "Unlock the Bloating Fodder Anima Power in Torghast. Use it to explode Mawrats inside cells; aim for high-density areas to reach the count efficiently.", x = 8 },
        [14774] = { e = 2, s = "c", r = "Rentable rides to fixed locations; no RNG.", d = "Enter Torghast and complete any cell block while keeping your Phantasma spend at zero. Monitor your currency usage carefully as you progress through each floor.", x = 8 },
        [14775] = { e = 3, s = "g", r = "Requires completing daily mushroom quests for exalted.", d = "Visit Marasmius in Ardenweald daily to earn reputation. Continue until you reach Exalted status, which grants the Fun Guy/Fun Gal title upon completion.", x = 8 },
        [14776] = { e = 2, s = "s", r = "Single Torghast run with a resource condition.", d = "Upgrade your Covenant Sanctum features first if possible. Then run Torghast cells without spending any Phantasma on Anima Powers or other upgrades to meet the requirement.", x = 8 },
        [14777] = { e = 3, s = "g", r = "Requires upgrading multiple sanctum features over time.", d = "Fully upgrade every feature in your Covenant Sanctum before claiming this achievement. Check the quest tracker for specific items needed to complete each upgrade path.", x = 8 },
        [14778] = { e = 3, s = "c", r = "Collect specific powers from a single Torghast run.", d = "Use Ravenous Anima Cells to unlock all listed Anima Powers. Prioritize unlocking rare powers like the Maw Seeker Mount early as they may have limited availability.", x = 8 },
        [14779] = { e = 2, s = "g", r = "Kill 10 common beasts in Ardenweald.", d = "Farm beasts in Ardenweald like the Nightsong Wader or Decayfly. This is account-wide and requires no specific group, but be patient as some spawn rarely.", x = 8 },
        [14780] = { e = 3, s = "c", r = "Complete all meditation quests; effort varies by player.", d = "Visit Ohm in the Queen's Conservatory to complete his meditation quests. Finish all available steps to unlock this account-wide title.", x = 8 },
        [14782] = { e = 1, s = "s", r = "Reach level 50 is trivial with XP gear.", d = "Grind experience until you hit level 50. This is a standard progression step and unlocks the next tier immediately.", x = 8 },
        [14783] = { e = 2, s = "s", r = "Reach level 60 takes under an hour.", d = "Continue leveling up from 50 to reach 60. No special mechanics are needed beyond gaining enough experience points.", x = 8 },
        [14788] = { e = 3, s = "c", r = "Find and return 5 specific books in Ardenweald.", d = "Find the lost books like A Meandering Story in Ardenweald and return them. These items often drop from specific mobs or chests.", x = 8 },
        [14789] = { e = 3, s = "c", r = "Complete Lia's storyline; effort depends on quest steps.", d = "Talk to Lia in the Queen's Conservatory to start restoring animal spirits. Complete her entire storyline sequence for this achievement.", x = 8 },
        [14790] = { e = 3, s = "c", r = "Complete Covenant campaign; effort varies by class.", d = "Finish your Covenant campaign quests first. This unlocks the next chain and is required before moving on to other content.", x = 8 },
        [14791] = { e = 2, s = "s", r = "Toss seed during/after fight with specific mob.", d = "Kill the mire boggart near Gwynceirw, The Winter Wolf, then toss a Faintly Glowing Seed. This specific interaction is account-wide.", x = 8 },
        [14795] = { e = 3, s = "g", r = "Return 15 memories from Torghast runs.", d = "Defeat enemies in Torghast to gain memories and return them to the Runecarver. You need 15 total for this account-wide goal.", x = 8 },
        [14796] = { e = 4, s = "c", r = "Equip high ilvl gear in every slot; requires farming.", d = "Equip a Superior item (item level 158+) in every gear slot. Ensure you have access to high-level loot before attempting this.", x = 8 },
        [14797] = { e = 4, s = "c", r = "Equip higher ilvl gear in every slot; requires farming.", d = "Upgrade your gear to Epic quality (item level 183+) in all slots. This requires completing the previous Superior tier first.", x = 8 },
        [14798] = { e = 3, s = "c", r = "Complete optional Revendreth storylines; effort varies.", d = "Complete optional Revendreth storylines like The Duelist's Debt or Tithes of Darkhaven. These are account-wide and can be done in any order.", x = 8 },
        [14799] = { e = 3, s = "c", r = "Requires completing multiple optional storylines across Maldraxxus.", d = "Complete the four optional Maldraxxus storylines in any order, as they are account-wide and require level 9.0+.", x = 8 },
        [14800] = { e = 3, s = "c", r = "Requires completing multiple optional storylines across Ardenweald.", d = "Finish all seven optional Ardenweald quests to earn this achievement; ensure you have access to the zone at level 9.0.", x = 8 },
        [14801] = { e = 3, s = "c", r = "Requires completing multiple optional storylines across Bastion.", d = "Do the four Bastion side storylines available after reaching level 9.0, noting that these are account-wide achievements.", x = 8 },
        [14802] = { e = 3, s = "g", r = "Grinding seven specific champions in Theater of Pain.", d = "Defeat all seven Theater of Pain champions in Maldraxxus; this is a straightforward kill list with no time gate.", x = 8 },
        [14808] = { e = 3, s = "c", r = "Requires completing the first layer of each Torghast wing.", d = "Start by completing the first layer of every Torghast wing, as you must finish Touring Torghast before advancing.", x = 8 },
        [14809] = { e = 3, s = "c", r = "Requires reaching Layer 4 in each Torghast wing.", d = "Progress to Layer 4 in each Torghast wing immediately after finishing Touring Torghast; this unlocks the next tier.", x = 8 },
        [14810] = { e = 3, s = "c", r = "Requires reaching Layer 8 in each Torghast wing.", d = "Reach Layer 8 in all Torghast wings, which requires completing the previous tiers first and may take significant time.", x = 8 },
        [14815] = { e = 4, s = "s", r = "Killing a high-level PvP target requires specific conditions.", d = "Find and kill High Exarch Turalyon in PvP content; this is a specific target that can be missed if you do not engage properly.", x = 8 },
        [14817] = { e = 4, s = "s", r = "Killing a high-level PvP target requires specific conditions.", d = "Locate and defeat Rokhan in PvP scenarios; ensure you are in the correct zone or instance to find him.", x = 0 },
        [14825] = { e = 3, s = "c", r = "Combines exploration and treasure collection across all zones.", d = "Unlock all four zones, collect treasures, and complete adventurer achievements first, as this umbrella achievement depends on them.", x = 8 },
        [14831] = { e = 2, s = "g", r = "Collecting a PvP set is straightforward with enough time.", d = "Gather any full armor set from Shadowlands PvP Season 1; check your wardrobe to see what you already have.", x = 8 },
        [14833] = { e = 2, s = "c", r = "Crafting many cosmetic items is easy once unlocked.", d = "Craft every Fashion Accessory using Abominable Stitching in Maldraxxus; remember this requires the Wardrobe Makeover first.", x = 8 },
        [14834] = { e = 2, s = "s", r = "Unlock first soulbind requires basic covenant setup.", d = "Unlock your covenant by completing the initial soulbind questline to earn this first point. Ensure you have access to your chosen covenant's sanctum before starting.", x = 8 },
        [14835] = { e = 3, s = "c", h = { 94303 }, r = "Requires gathering specific currency from Ardenweald.", d = "Complete the second soulbind questline and gather the required Maldraxxus, Ardenweald, or Unnamed Branch credits as specified in the info field. Visit your covenant representative to unlock the ability.", x = 8 },
        [14836] = { e = 2, s = "s", r = "Unlock second soulbind is a simple step.", d = "Finish the third soulbind requirements, which may involve gathering specific Ardenweald resources if you are an alternate character. Check your progress tracker to ensure all conditions are met.", x = 8 },
        [14837] = { e = 3, s = "c", r = "Requires reaching Renown 34 and unlocking third soulbind.", d = "Reach Renown Level 34 on your account and unlock every row in all three soulbinds for your covenant. This is account-wide, so coordinate with other players if needed.", x = 8 },
        [14839] = { e = 2, s = "c", r = "Grind involves leveling three adventurers to max.", d = "Raise three separate adventurers to level 60 using the Adventures system to complete this requirement. You must create or use multiple characters to fulfill the count.", x = 8 },
        [14840] = { e = 2, s = "g", r = "Leveling one adventurer to level 20 is quick.", d = "Level any single adventurer from zero to level 20 in the Adventures mode to claim this point. Start with a new character if you do not have one ready.", x = 8 },
        [14841] = { e = 2, s = "g", r = "Leveling an adventurer from 20 to 40 takes time.", d = "Continue leveling your chosen adventurer from level 20 to 40, ensuring you complete the previous step first. This is part of a chain that must be followed in order.", x = 8 },
        [14842] = { e = 2, s = "g", r = "Leveling an adventurer from 40 to 60 is moderate.", d = "Finish leveling your adventurer to level 60 after reaching level 40. Once this character hits max level, you can unlock the next achievement in the sequence.", x = 8 },
        [14843] = { e = 3, s = "c", h = { 89784 }, r = "Collecting all 12 adventurers requires significant time.", d = "Collect all twelve unique adventurers from your covenant by completing their respective adventure lines. This is account-wide, so plan to run adventures across multiple characters.", x = 8 },
        [14844] = { e = 3, s = "c", h = { 90621 }, r = "Completing Maw adventures involves multiple complex tasks.", d = "Complete every listed Maw adventure quest, including Breach the Planes and Ghelak's Revenge. These are account-wide tasks that require finishing specific storylines in the Maw.", x = 8 },
        [14845] = { e = 2, s = "s", r = "Completing a single adventure is straightforward.", d = "Finish any single adventure quest to unlock this point. It serves as the first step in a chain leading to completing ten adventures total.", x = 8 },
        [14846] = { e = 3, s = "g", r = "Completing 10 adventures requires repeated effort.", d = "Complete ten distinct adventures after finishing your first one, tracking your progress carefully. This leads into the Protector of the Shadowlands achievement chain.", x = 8 },
        [14847] = { e = 2, s = "g", r = "Grinding 100 adventures is easy solo but takes time.", d = "Complete 100 Adventures by finishing the 'Leaves in the Forest' questline, which is account-wide and requires no group. Focus on daily activities to reach the count quickly without worrying about specific bosses or drops.", x = 8 },
        [14851] = { e = 3, s = "c", h = { 90072 }, r = "Requires specific gear and defeating two bosses.", d = "Equip the Spiritforged Aegis before entering the Sanctum of Domination to defeat Kalisthene and Craven Corinth. This item is a rare drop, so you may need to run multiple trials or wait for other players to obtain it first.", x = 8 },
        [14852] = { e = 3, s = "c", h = { 90076 }, r = "Trial of Loyalty is harder; Splinterbark Nightmare is the main hurdle.", d = "Join a group to complete the Trial of Loyalty as Mikanikos, ensuring you defeat Alderyn, Myn'ir, and Splinterbark Nightmare. This achievement is account-wide, so coordinate with friends or find a party willing to run the specific covenant trial.", x = 8 },
        [14853] = { e = 2, s = "s", r = "Single fight with debuffs; trivial once conditions met.", d = "Defeat Mad Mortimer while simultaneously afflicted by Fiery Veins, Frozen, and Uncontrolled Vomiting debuffs. These conditions often require specific encounters or consumables, so plan your approach carefully before engaging the boss.", x = 8 },
        [14854] = { e = 3, s = "c", h = { 90079 }, r = "Requires six different gear pieces; one is a rare drop.", d = "Run Trials of Loyalty separately for each soulbind equipment piece listed in the info field. Since this is account-wide, ensure you have access to all gear types and complete them efficiently to avoid missing any pieces.", x = 8 },
        [14856] = { e = 2, s = "g", r = "Grinding five charms is easy with good RNG.", d = "Equip five different Charms before attempting a Trial of Wisdom to unlock this achievement. Make sure you collect enough charms first, as equipping them simultaneously is the key requirement for success.", x = 8 },
        [14857] = { e = 3, s = "c", r = "Requires killing 20 crawlers then defeating Echthra.", d = "Kill 20 Crawlers in the Sanctum of Domination before engaging Echthra in a Trial of Wisdom. This requires patience and careful tracking of kills, so consider using area-of-effect abilities to speed up the process.", x = 8 },
        [14858] = { e = 3, s = "c", r = "Requires consuming orbs first; Splinterbark Nightmare is the hardest part.", d = "Defeat Craven Corinth in a Trial of Wisdom only after he has consumed two anima orbs. Monitor his health bar closely during the fight, as timing your damage output with his orb consumption is critical.", x = 8 },
        [14859] = { e = 3, s = "c", r = "Requires surviving swings; Splinterbark Nightmare is the hardest part.", d = "Survive five Power Swings from Athanos before defeating him in a Trial of Wisdom. Stay mobile and use defensive abilities to endure these attacks while dealing consistent damage to complete the objective.", x = 8 },
        [14860] = { e = 2, s = "s", r = "Single fight without gear; trivial once conditions met.", d = "Overcome a Trial of Wisdom without equipping any soulbind equipment to earn this achievement. Ensure you have no gear equipped from soulbinds before starting the trial, as even one piece will disqualify your progress.", x = 8 },
        [14861] = { e = 3, s = "c", h = { 90097 }, r = "Requires three specific covenants; Pelagos is the hardest to get.", d = "Defeat both Kalisthene and Athanos in the Trial of Wisdom using Pelagos, Kleia, and Mikanikos. This requires switching between covenants or using specific abilities, so plan your strategy around each character's unique skills.", x = 8 },
        [14862] = { e = 3, s = "c", h = { 90085 }, r = "Requires six different gear pieces; one is a rare drop.", d = "Complete Trials of Humility separately for each soulbind equipment piece listed in the info field. Since this is account-wide, coordinate with others to ensure all gear types are tested and completed efficiently.", x = 8 },
        [14863] = { e = 4, s = "s", r = "High-difficulty trial requiring precise execution.", d = "Defeat Thran'tiok in Trial of Wisdom by destroying all phylacteries before taking damage, as this is a missable condition. Start with high mobility to dodge her attacks while focusing on the phylactery targets. Pitfall: Do not engage her directly until the phylacteries are gone or you will fail.", x = 8 },
        [14864] = { e = 4, s = "s", r = "High-difficulty trial requiring specific class playstyle.", d = "Complete the Pelagos trial against Azaruux by avoiding all memory encounters during the fight. This requires careful navigation of the arena to skip specific triggers without triggering them. Pitfall: Missing a memory encounter resets progress, so plan your path carefully from the start.", x = 8 },
        [14865] = { e = 3, s = "c", h = { 90106, 90107, 90108 }, r = "Requires defeating ten trials with specific characters.", d = "Defeat every Trial of Humility boss using Pelagos, Kleia, and Mikanikos in any combination. You can mix and match these characters across different trials to complete the set. Pitfall: Ensure you have access to all three covenants or use appropriate gear if restricted.", x = 8 },
        [14866] = { e = 4, s = "c", h = { 90137, 90138, 90139 }, r = "Hard mode requires perfect execution across ten trials.", d = "Clear all Trials of Humility without using charms or active braziers for a true test of skill. This means relying solely on your character's abilities and positioning. Pitfall: Avoid picking up any buffs that might count as charms, as this will invalidate the achievement.", x = 8 },
        [14867] = { e = 3, s = "g", r = "Collecting many pets via battles is a moderate grind.", d = "Catch every Shadowlands battle pet by exploring relevant zones and completing associated quests or events. Some pets may require specific conditions like defeating certain mobs or solving puzzles. Pitfall: Certain rare pets have low drop rates, so be patient and thorough in your hunting.", x = 8 },
        [14868] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Defeat nine Master Tamers using only level 25 Aquatic pets for this challenge. Build a balanced team of water-based creatures to handle various enemy types effectively. Pitfall: Ensure all pets are exactly level 25, as higher or lower levels will not count toward the achievement.", x = 8 },
        [14869] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Assemble a team of level 25 Beast pets to defeat nine Master Tamers in Shadowlands. Focus on gathering diverse beast-type creatures for your roster. Pitfall: Some tamers may resist specific pet types, so adapt your lineup accordingly while maintaining the level requirement.", x = 8 },
        [14870] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Use a team of level 25 Critter pets to conquer nine Master Tamers in Shadowlands. Collect small animals like insects and rodents for your squad. Pitfall: Ensure your critters are fully leveled and equipped, as weak teams may struggle against tougher tamers.", x = 8 },
        [14871] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Defeat nine Master Tamers with a team of level 25 Dragonkin pets in Shadowlands. Gather dragon-type creatures to form your specialized squad. Pitfall: Dragonkin pets often have unique mechanics; familiarize yourself with their abilities before tackling difficult tamers.", x = 8 },
        [14872] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Complete the challenge by defeating nine Master Tamers using level 25 Elemental pets in Shadowlands. Collect fire, earth, air, and water elementals for your team. Pitfall: Elemental pets may have elemental weaknesses; match them against appropriate tamers to maximize efficiency.", x = 8 },
        [14873] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Defeat nine Master Tamers with a team of level 25 Flying pets in Shadowlands. Gather aerial creatures like birds and dragons for your squad. Pitfall: Flying pets excel at evasion but may lack raw damage; balance your team composition accordingly.", x = 8 },
        [14874] = { e = 4, s = "c", r = "Requires specific team and defeating multiple tamers.", d = "Assemble a team of level 25 Humanoid pets to defeat nine Master Tamers in Shadowlands. Collect humanoid creatures such as goblins and dwarves for your roster. Pitfall: Ensure your humanoids are well-equipped, as they may face tough opponents requiring strategic play.", x = 8 },
        [14875] = { e = 3, s = "c", r = "Grind 9 specific bosses with a specific pet team.", d = "Gather nine level 25 Magic pets and defeat the Master Tamers in Shadowlands, noting that Faryl requires nine separate victories. This is account-wide so coordinate with friends if you lack specific pets.", x = 8 },
        [14876] = { e = 3, s = "c", r = "Grind 9 specific bosses with a specific pet team.", d = "Collect nine level 25 Mechanical pets to challenge the same Master Tamers in Shadowlands. Ensure your team meets the exact level requirement before engaging each boss.", x = 8 },
        [14877] = { e = 3, s = "c", r = "Grind 9 specific bosses with a specific pet team.", d = "Assemble a team of nine level 25 Undead pets and defeat the Master Tamers in Shadowlands. Verify pet levels immediately after unlocking new ones to avoid time-gating issues.", x = 8 },
        [14879] = { e = 3, s = "c", r = "Requires completing other checklist achievements first.", d = "Complete all sub-achievements listed, including the three elemental type challenges you just started. This is a collection goal with no specific order required.", x = 8 },
        [14881] = { e = 4, s = "c", h = { 90032, 90037 }, r = "Grind rare Shadowlands legendary pets including RNG drops.", d = "Defeat the Shadowlands Legendary Pets listed in the info field to unlock this achievement. These are rare drops or specific encounters that may require multiple attempts.", x = 8 },
        [14887] = { e = 1, s = "s", r = "Simple interaction with NPC Athanos after expansion launch.", d = "Travel to the Covenant Sanctum and speak with Athanos until he waves goodbye. This is a simple interaction quest with no combat requirements.", x = 8 },
        [14894] = { e = 3, s = "c", r = "Grind Ve'nari upgrades; some require specific conditions.", d = "Unlock any two permanent upgrades from Ve'nari in the Maw to complete this step. You can choose any available upgrades without needing specific ones first.", x = 8 },
        [14895] = { e = 3, s = "c", r = "Grind Ve'nari upgrades; requires completing previous tier.", d = "Unlock five permanent upgrades from Ve'nari, which requires completing the previous 'Two Curios' achievement first. Select upgrades strategically as some may be missable if not claimed promptly.", x = 8 },
        [14943] = { e = 3, s = "s", r = "Specific encounter condition in Maw; manageable with group.", d = "Defeat Ylva while maintaining five stacks of Blood of the Pack buff in the Maw. This requires careful management of your pet abilities during the encounter.", x = 8 },
        [14961] = { e = 3, s = "c", r = "Complete multiple campaign storylines across zones.", d = "Complete all listed Shadowlands campaign quests to finish this storyline achievement. Follow the main quest chain in Ardenweald and the Maw to unlock each step.", x = 8 },
        [14998] = { e = 4, s = "s", r = "Specific quest chain ending in a difficult raid boss fight.", d = "Reunite Moriaz with Buttons in the Sanctum of Domination before defeating The Tarragrue on Normal or higher difficulty. This is a specific sequence that must be completed in order.", x = 8 },
        [15000] = { e = 3, s = "c", r = "Complete four distinct Maw Assault objectives.", d = "Complete all four covenant assaults in the Maw, which involves defeating specific bosses for each covenant. These are account-wide and require coordinating with friends if needed.", x = 8 },
        [15001] = { e = 4, s = "g", r = "Requires opening 10 caches during a specific assault event.", d = "Open Rift Hidden Caches during the Night Fae assault on the Crucible of the Damned until you have ten. This is part of a larger assault achievement, so ensure you are in the correct zone and faction event. Do not miss this window as it is time-gated to the specific assault duration.", x = 8 },
        [15003] = { e = 5, s = "c", r = "Requires forming a Shard of Destiny and defeating The Nine.", d = "Form a Shard of Destiny from nine or more Fragments during Sanctum of Domination on Normal difficulty or higher. Defeat The Nine immediately after forming the shard to claim the achievement. This requires coordinating with other players to collect enough fragments before the encounter resets.", x = 8 },
        [15004] = { e = 4, s = "g", r = "Requires rescuing 'Sly' three times; relies on RNG and patience.", d = "Rescue the pet Sly three times by finding him and letting him run away each time. This is a repeatable objective, so keep an eye out for his appearance in various zones. There is no strict time limit, but be patient as he may take time to spawn.", x = 8 },
        [15023] = { e = 4, s = "c", r = "Requires unlocking Rank I of all four Covenant Upgrades.", d = "Unlock Rank I of all four Covenant Upgrades by completing the necessary quests and earning Anima. Start with your chosen covenant and work through the upgrade tree systematically. This achievement unlocks increased Anima rewards for future progress.", x = 8 },
        [15024] = { e = 4, s = "c", r = "Requires unlocking Rank II of all four Covenant Upgrades.", d = "Unlock Rank II of all four Covenant Upgrades after completing Rank I for each. Continue progressing through your covenant's questline to earn the required Anima. This is a sequential requirement, so do not skip ranks or you will need to restart.", x = 8 },
        [15025] = { e = 4, s = "c", r = "Requires unlocking Rank III of all four Covenant Upgrades.", d = "Unlock Rank III of all four Covenant Upgrades by reaching the final tier in each covenant. Ensure you have completed Ranks I and II first as they are prerequisites. This step grants further Anima bonuses and is essential for maxing out your covenant power.", x = 8 },
        [15032] = { e = 4, s = "c", r = "Requires completing 10 specific quests during the Necrolord assault.", d = "Complete all listed quests during the Necrolord assault on Perdition Hold to earn this achievement. These quests are account-wide, so any character can contribute by completing them while the assault is active. Make sure to track quest progress carefully as the assault event has a limited duration.", x = 8 },
        [15033] = { e = 4, s = "c", r = "Requires completing 9 specific quests during the Venthyr assault.", d = "Finish all required quests during the Venthyr assault on the Tremaculum for this achievement. Like other assaults, this is time-gated and account-wide, so coordinate with friends if needed. Keep an eye on quest completion status to avoid missing any objectives before the event ends.", x = 8 },
        [15034] = { e = 4, s = "c", r = "Requires completing 11 specific quests during the Kyrian assault.", d = "Complete all specified quests during the Kyrian assault on Zovaal's Cauldron to unlock this achievement. Ensure you are in the correct zone and faction event when starting these quests. The assault duration is limited, so prioritize completing these tasks early in the event window.", x = 8 },
        [15035] = { e = 4, s = "c", r = "Requires completing four of the listed covenant assault achievements.", d = "Complete four of the listed covenant assault achievements by participating in their respective events. These include assault-specific objectives like opening caches or defeating bosses. Choose any four to complete as they are not tied to a specific order, but all must be done within their event windows.", x = 8 },
        [15036] = { e = 4, s = "c", r = "Requires completing 9 specific quests during the Night Fae assault.", d = "Finish all quests during the Night Fae assault on the Crucible of the Damned for this achievement. These quests are account-wide and time-gated to the assault duration. Track your progress closely to ensure no quest is left incomplete before the event ends.", x = 8 },
        [15037] = { e = 4, s = "c", r = "Requires completing 'You and What Army' with each unique champion.", d = "Complete the quest You and What Army once with each unique champion listed to earn this achievement. This requires engaging in specific encounters with each champion individually. Be prepared for varying difficulty levels and ensure you have the right gear and group composition for each fight.", x = 8 },
        [15039] = { e = 2, s = "g", r = "Open 10 caches during a short assault; takes under an hour.", d = "Open Mawsworn Caches during Necrolord assaults on Perdition Hold until you have ten. This requires active participation in the assault, so plan to queue for this faction specifically.", x = 8 },
        [15040] = { e = 4, s = "s", r = "High-skill raid fight with strict mechanics and RNG elements.", d = "Defeat Fatescribe Roh-Kalo without taking damage from specific mechanics like Fate Fragments or explosions. Ensure your group coordinates perfectly and uses defensive cooldowns proactively on Normal difficulty or higher.", x = 8 },
        [15041] = { e = 2, s = "g", r = "Dance near 5 forges; takes a few minutes to an hour.", d = "Equip the Mawproof Parasol and dance near five different forges in Zovaal's Cauldron. You can do this solo, but ensure you visit all forge locations within the zone.", x = 8 },
        [15042] = { e = 2, s = "c", h = { 91638 }, r = "Serve tea to NPCs during a short assault; mostly trivial.", d = "Serve tea to specific NPCs during the Venthyr assault on Tremaculum. Check your quest log for the exact list of characters to interact with before engaging combat.", x = 8 },
        [15043] = { e = 2, s = "g", r = "Collect 10 items from Torghast portal; takes under an hour.", d = "Collect ten items that Fangcrack pulls from the Portal in Torghast. This is account-wide, so any character can contribute by running Torghast and accepting his offers.", x = 8 },
        [15044] = { e = 2, s = "c", r = "Aid NPCs during a short assault; mostly trivial checklist.", d = "Aid specific characters during the Night Fae assault quest 'Just Don't Ask Me to Spell It'. Coordinate with your group to ensure every listed NPC receives assistance.", x = 8 },
        [15053] = { e = 2, s = "c", r = "Explore zones and points; takes a few hours total.", d = "Explore Korthia by revealing all covered areas on the world map. Focus on unexplored zones and landmarks, as this is account-wide and requires thorough traversal of the zone.", x = 8 },
        [15054] = { e = 4, s = "g", r = "Defeat all Tormentors; requires multiple runs and RNG.", d = "Defeat all Tormentors of Torghast special encounters in The Maw. This includes unique bosses like Versya the Damned and others, requiring you to run specific Torghast modes.", x = 8 },
        [15055] = { e = 2, s = "g", r = "Complete daily quest 3 times with Ooz; takes under an hour.", d = "Complete the 'Oozing with Character' daily quest three times with Ooz. Train him first if needed, then queue for the daily to track your progress.", x = 8 },
        [15056] = { e = 2, s = "g", r = "Complete daily quest 3 times with Bloop; takes under an hour.", d = "Complete the 'Oozing with Character' daily quest three times with Bloop. Similar to other pets, ensure you have trained him and completed the required dailies.", x = 8 },
        [15057] = { e = 2, s = "g", r = "Complete daily quest 3 times with Plaguey; takes under an hour.", d = "Complete the 'Oozing with Character' daily quest three times with Plaguey. Train the pet and run the daily repeatedly until the counter reaches three.", x = 8 },
        [15058] = { e = 4, s = "s", r = "Score goals then defeat boss; high-skill raid encounter.", d = "Score three goals in Sanctum of Domination before defeating the Remnant of Ner'zhul on Normal or higher. Coordinate with your team to focus on scoring objectives first.", x = 8 },
        [15059] = { e = 2, s = "g", r = "Grinding reputation to Exalted takes several hours.", d = "Earn Exalted with Death's Advance by completing their reputation quests and turning in items to the faction. This is account-wide, so any character can finish it for everyone. No specific time gate exists, but you must reach Exalted before unlocking related content.", x = 8 },
        [15064] = { e = 4, s = "c", h = { 91731 }, r = "Chains of Domination is the hardest checklist item.", d = "Complete all listed sub-achievements including Chains of Domination and Conquering Korthia to unlock this meta achievement. Start by finishing the main Korthia campaign and collecting relics first. This is account-wide, so one character can finish it for your entire account.", x = 8 },
        [15065] = { e = 4, s = "s", r = "Requires a specific raid encounter photo opportunity.", d = "Defeat the Eye of the Jailer on Normal or higher difficulty after taking a group photo with everyone having Photoflash! Ensure all raid members have the camera buff before engaging the boss. This is missable if you do not coordinate the photo during the fight.", x = 8 },
        [15066] = { e = 3, s = "g", r = "Collecting relics in Korthia takes moderate time.", d = "Collect every Archivist relic in Korthia by exploring the zone and completing specific collection quests. Focus on gathering items like the Talisman of the Eternal Scholar and Book of Binding first. This is account-wide, so one character can complete it for everyone.", x = 8 },
        [15067] = { e = 4, s = "s", r = "Adamant Vaults require significant Torghast progression.", d = "Complete Adamant Vaults on any layer in Torghast to earn this achievement. You do not need a specific layer or difficulty, just a successful run. This is account-wide, so finish it once with any character.", x = 8 },
        [15069] = { e = 2, s = "s", r = "Unlocking Tier 6 research is a quick step.", d = "Unlock Tier 6 Research with The Archivists' Codex by completing the associated research quests in Korthia. Ensure you have access to the Codex and complete all required steps. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15075] = { e = 4, s = "c", h = { 91792 }, r = "Killing all rare Torghast encounters is a grind.", d = "Defeat each rare encounter in Torghast including Karthazel, Sath'zuul, and Vil'thras to unlock this achievement. These are random spawns, so be prepared to wait or run multiple layers. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15076] = { e = 3, s = "s", r = "Obtaining the box depends on Torghast completion.", d = "Obtain the Box of Many Things by completing specific Torghast-related quests or events. Check your quest log for the required items or objectives. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15079] = { e = 4, s = "g", r = "Researching every talent requires extensive Torghast runs.", d = "Research every talent in the Box of Many Things by interacting with the box and selecting each option. Some talents may require specific conditions or items to unlock. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15080] = { e = 3, s = "s", r = "Ranking up a specific talent is moderate effort.", d = "Research rank 3 of Blessing of the Ancients in the Box of Many Things by selecting the talent multiple times. Ensure you have enough resources or currency to upgrade the talent fully. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15081] = { e = 4, s = "s", r = "Flawless run on Layer 12 is difficult and RNG-heavy.", d = "Achieve a Flawless run on layer 12 in Skoldus Hall by defeating all bosses without dying or failing encounters. Prepare your gear and group composition carefully to handle the high difficulty. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15082] = { e = 4, s = "s", r = "Flawless run on Fracture Chambers Layer 12 is hard.", d = "Achieve a Flawless run on layer 12 in Fracture Chambers by defeating all bosses without dying or failing encounters. Prepare your gear and group composition carefully to handle the high difficulty. This is account-wide, so one character can finish it for everyone.", x = 8 },
        [15083] = { e = 4, s = "s", r = "Flawless Layer 12 requires high skill and RNG luck.", d = "Farm Coldheart Interstitia until you can clear Layer 12 without dying. Focus on dodging mechanics and managing cooldowns to achieve the flawless run required for this achievement.", x = 8 },
        [15084] = { e = 4, s = "s", r = "Flawless Layer 12 requires high skill and RNG luck.", d = "Grind The Soulforges wings repeatedly to master their specific boss patterns. Aim for Layer 12 by optimizing your rotation and ensuring zero deaths during the attempt.", x = 8 },
        [15087] = { e = 4, s = "s", r = "Flawless Layer 12 requires high skill and RNG luck.", d = "Practice Mort'regar runs until you can clear Layer 12 without taking fatal damage. Pay close attention to boss abilities that cause instant death or heavy damage.", x = 8 },
        [15088] = { e = 4, s = "s", r = "Flawless Layer 12 requires high skill and RNG luck.", d = "Clear The Upper Reaches wings repeatedly to reach the flawless requirement at Layer 12. Ensure your group composition is strong enough to handle the increased difficulty.", x = 8 },
        [15089] = { e = 4, s = "c", h = { 91834, 91835, 91836 }, r = "Requires flawless runs across all six Torghast wings.", d = "Complete all four wing-specific flawless runs on Layer 12 before claiming this master achievement. This requires significant Torghast experience and consistent high-level performance across different wings.", x = 8 },
        [15091] = { e = 3, s = "s", r = "Any Flawless run is hard but easier than Layer 12.", d = "Start with any single wing to unlock the base flawless run requirement. Once you have one flawless run, you can progress through other layers or wings as desired.", x = 8 },
        [15092] = { e = 4, s = "c", h = { 91853, 91854, 91855 }, r = "Requires completing four specific high-difficulty Torghast tasks.", d = "Unlock all four sub-achievements listed in the info field first. These specific Torment achievements must be completed before the main Master of Torment title becomes available.", x = 8 },
        [15093] = { e = 3, s = "s", r = "Requires building Vengeance stacks against an elite enemy.", d = "Engage elite enemies while actively stacking Vengeance to reach ten stacks before they die. This often requires pulling adds or using specific abilities to maintain the buff duration.", x = 8 },
        [15094] = { e = 3, s = "s", r = "Requires maintaining Rampage stacks for 30 seconds.", d = "Maintain maximum Rampage stacks for thirty consecutive seconds during a single run. Avoid taking damage that breaks the stack count and keep your offensive pressure high.", x = 8 },
        [15095] = { e = 4, s = "s", r = "Requires perfect play to avoid killing Doubtcaller spells.", d = "Defeat a boss while protecting the Doubtcaller from being killed or interrupted. Coordinate with your group to handle adds without focusing fire on the NPC during the encounter.", x = 8 },
        [15096] = { e = 3, s = "s", r = "Requires surviving Claustrophobia for 30 seconds.", d = "Stay under the Claustrophobia effect for thirty seconds continuously while the Torment is active. Avoid taking damage or dying, as this will reset your progress toward the time goal.", x = 8 },
        [15099] = { e = 4, s = "g", r = "Requires finding many unique hidden treasures across zones.", d = "Explore Korthia and Desmotaeron thoroughly to find all unique treasure items listed in the info field. Check hidden areas and complete related quests to ensure you have collected every item.", x = 8 },
        [15102] = { e = 1, s = "s", r = "Collect a set from PvP Season 31; trivial account-wide.", d = "Gather PvP gear from Season 31 sets, which are account-wide and require no specific class. Focus on acquiring the full set for any character to complete this collection quickly.", x = 8 },
        [15105] = { e = 4, s = "c", h = { 91908 }, r = "Requires specific mechanics and avoiding Torment impacts.", d = "Start by taunting Garrosh Hellscream before combat begins in Sanctum of Domination Normal or higher. Avoid all Torment impacts while afflicted with Hellscream's Burden, as missing these conditions makes the achievement missable.", x = 8 },
        [15106] = { e = 4, s = "c", h = { 91927 }, r = "Mythic dungeon with strict delivery mechanics required.", d = "Run Tazavesh Mythic and ensure every Unstable Goods item is delivered to another player before the P.O.S.T. Master fight. Failure to pass items correctly will prevent defeating the boss for credit.", x = 8 },
        [15107] = { e = 3, s = "c", r = "Multiple encounters in Korthia; grind depends on completion count.", d = "Complete all listed special encounters in Korthia and the Maw, noting that this is an account-wide achievement requiring group play for many bosses. Prioritize rare spawns like Malbog and Deomen the Vortex to avoid missing content.", x = 8 },
        [15108] = { e = 4, s = "s", r = "Defeat Kel'Thuzad after thawing heart; single raid step.", d = "Defeat Kel'Thuzad in Sanctum of Domination Normal or higher after thawing the Remnant's heart. This raid encounter is time-gated if you do not complete the heart mechanic before engaging the final boss.", x = 8 },
        [15109] = { e = 4, s = "c", h = { 91946 }, r = "Mythic dungeon requiring all players to be blended.", d = "Enter Tazavesh Mythic with all party members covered in four different blended substances before fighting Zo'phex the Sentinel. Coordinate blending items early to ensure everyone meets the requirement before the encounter starts.", x = 8 },
        [15110] = { e = 2, s = "s", r = "Collect a Tier 27 set; trivial account-wide collection.", d = "Collect a full Tier 27 armor set from Sanctum of Domination for at least one class. This is account-wide, so any character can contribute to gathering the necessary pieces.", x = 8 },
        [15112] = { e = 4, s = "s", r = "Defeat The Tarragrue on Mythic; single raid boss kill.", d = "Defeat The Tarragrue specifically on Mythic difficulty in Sanctum of Domination. Normal or lower difficulties will not count toward this achievement, so ensure you are queued for Mythic runs.", x = 8 },
        [15113] = { e = 4, s = "s", r = "Defeat The Eye of the Jailer on Mythic; single raid boss kill.", d = "Queue for Mythic difficulty to defeat The Eye of the Jailer in Sanctum of Domination. This boss does not appear on lower difficulties, making it essential to run Mythic specifically.", x = 8 },
        [15114] = { e = 4, s = "s", r = "Defeat The Nine on Mythic; single raid boss kill.", d = "Defeat The Nine only on Mythic difficulty within Sanctum of Domination. Attempting this on Normal or Heroic will fail to register the achievement progress.", x = 8 },
        [15115] = { e = 4, s = "s", r = "Defeat Remnant of Ner'zhul on Mythic; single raid boss kill.", d = "Run Sanctum of Domination on Mythic difficulty to defeat Remnant of Ner'zhul. Lower difficulties will not grant credit, so verify your queue settings before starting the raid.", x = 8 },
        [15116] = { e = 4, s = "s", r = "Defeat Soulrender Dormazain on Mythic; single raid boss kill.", d = "Defeat Soulrender Dormazain exclusively on Mythic difficulty in Sanctum of Domination. Normal or Heroic runs will not count, requiring a dedicated Mythic attempt for this achievement.", x = 8 },
        [15117] = { e = 4, s = "c", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Painsmith Raznal on Mythic difficulty in the Sanctum of Domination. This is a time-gated achievement requiring you to complete the entire raid wing first.", x = 8 },
        [15118] = { e = 4, s = "c", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Guardian of the First Ones on Mythic difficulty in the Sanctum of Domination. Ensure you clear all lower wings before attempting this upper-tier boss.", x = 8 },
        [15119] = { e = 4, s = "c", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Fatescribe Roh-Kalo on Mythic difficulty in the Sanctum of Domination. This boss is located in the third wing and requires prior completion of earlier tiers.", x = 8 },
        [15120] = { e = 4, s = "c", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Kel'Thuzad on Mythic difficulty in the Sanctum of Domination. You must clear the previous wings before accessing this boss encounter.", x = 8 },
        [15121] = { e = 4, s = "c", r = "Mythic raid boss requires group coordination and gear.", d = "Defeat Sylvanas Windrunner on Mythic difficulty to earn the Breaker of Chains title. This is the final boss and requires completing all prior Sanctum wings first.", x = 8 },
        [15122] = { e = 4, s = "c", r = "Requires clearing multiple Mythic bosses in sequence.", d = "Clear all bosses in the lower floors of the Sanctum of Domination on any difficulty. This account-wide achievement unlocks access to the next wing of the raid.", x = 8 },
        [15123] = { e = 4, s = "c", r = "Requires clearing multiple Mythic bosses in sequence.", d = "Defeat all bosses in the middle wings of the Sanctum of Domination on any difficulty. Complete this after clearing the lower floors to progress further.", x = 8 },
        [15124] = { e = 4, s = "c", r = "Requires clearing multiple Mythic bosses in sequence.", d = "Clear all bosses in the upper tiers of the Sanctum of Domination on any difficulty. This unlocks access to the final boss encounter with Sylvanas.", x = 8 },
        [15125] = { e = 4, s = "c", r = "Final Mythic boss requires full raid progression.", d = "Defeat Sylvanas Windrunner on any difficulty to complete the main raid progression. Ensure you have cleared all previous wings before facing her.", x = 8 },
        [15126] = { e = 3, s = "c", r = "Heroic difficulty is easier than Mythic but still a grind.", d = "Defeat every boss in the Sanctum of Domination on Normal or higher difficulty. This serves as a prerequisite for unlocking Heroic and Mythic difficulties.", x = 8 },
        [15127] = { e = 4, s = "c", r = "Mythic difficulty requires significant time and coordination.", d = "Clear all bosses on Heroic difficulty after completing the base raid. This unlocks Mythic difficulty and is required before attempting any Mythic achievements.", x = 8 },
        [15128] = { e = 4, s = "c", r = "Full Mythic raid clear is a major time commitment.", d = "Defeat every boss on Mythic difficulty to complete the full raid progression chain. Start this only after finishing all Heroic encounters successfully.", x = 8 },
        [15130] = { e = 4, s = "c", h = { 92078, 92079, 92080 }, r = "Raid achievements require high-level gear and group coordination.", d = "Start by clearing the Sanctum of Domination raid on Normal or higher to unlock sub-achievements. Complete all listed boss kills and mechanics, as this is account-wide and requires a full group.", x = 8 },
        [15131] = { e = 4, s = "s", r = "Requires specific raid boss kill on Normal or higher.", d = "Defeat Painsmith Raznal in Torghast after activating the Burning Gibbets on Normal difficulty or higher. Ensure you have the raid key active before attempting this specific kill condition.", x = 8 },
        [15132] = { e = 4, s = "s", r = "Requires defeating a specific raid boss under conditions.", d = "First enlighten and defeat Vazzaren the Seeker in Sanctum of Domination on Normal or higher. Then proceed to defeat the Guardian of the First Ones to complete the objective.", x = 8 },
        [15133] = { e = 4, s = "s", r = "Requires defeating Sylvanas in Torghast on Normal or higher.", d = "Activate the Focusing Prism in Sanctum of Domination and then defeat Sylvanas Windrunner on Normal difficulty or higher. This is part of the main raid progression requirements.", x = 8 },
        [15177] = { e = 4, s = "s", r = "Mythic dungeon boss kill requires high-level group play.", d = "Run Tazavesh, the Veiled Market dungeon on Mythic difficulty to defeat So'leah. You must be in a full group and ensure the dungeon is set to Mythic before starting.", x = 8 },
        [15178] = { e = 4, s = "s", r = "Requires specific Mythic Hard Mode run with forged credentials.", d = "Complete Tazavesh on Mythic with Hard Mode enabled to get caught using forged credentials against So'leah. This requires specific interaction timing during the boss fight.", x = 8 },
        [15179] = { e = 4, s = "s", r = "Requires specific Mythic dungeon conditions and boss kill.", d = "In Tazavesh Mythic, insert Bypass Codes while afflicted by the Sanitizing Field debuff to defeat Hylbrande. Watch for the field effect and time your code insertion correctly.", x = 8 },
        [15181] = { e = 2, s = "g", r = "Simple action while driving a vehicle for some time.", d = "Drive your Rockin' Rollin' Racer while listening to Rockin' Tunes music, then use Lightning Nitro to complete this Winter Veil event. Ensure the music is playing before activating the nitro.", x = 8 },
        [15190] = { e = 4, s = "c", h = { 92281, 92282, 92283 }, r = "Requires finding and interacting with specific rare rats in Mythic.", d = "Tickle all listed broker rats in Tazavesh on Mythic difficulty for account-wide credit. Use a ranged pet or ability to safely tickle them without aggroing other mobs.", x = 8 },
        [15211] = { e = 4, s = "g", r = "Requires collecting data from many different creatures using a trap.", d = "Use the Containment Trap toy on various creatures in Shadowlands to retrieve research data. This is account-wide and requires finding specific targets across different zones.", x = 8 },
        [15212] = { e = 2, s = "s", r = "Simple mini-game interaction at the Darkmoon Faire.", d = "Participate in the Darkmoon Faire Dance game once to start this chain. Return to the faire regularly as you progress toward the next tier of this achievement.", x = 8 },
        [15213] = { e = 4, s = "g", r = "Requires completing the dance game 30 times in a row.", d = "Complete the First Dance achievement first, then play the Darkmoon Faire Dance game 30 times total. This is account-wide and requires visiting the faire multiple times.", x = 8 },
        [15214] = { e = 1, s = "s", r = "One dance game attempt on medium difficulty.", d = "Start with the easiest dance difficulty to unlock the medium challenge. Practice your timing on the first attempt, as a perfect score is required immediately.", x = 8 },
        [15215] = { e = 3, s = "g", r = "Requires repeating the previous achievement 10 times.", d = "Unlock the previous achievement first, then grind the medium difficulty repeatedly until you hit ten perfect scores. This is account-wide, so any character can contribute.", x = 8 },
        [15216] = { e = 2, s = "s", r = "One dance game attempt on hardest difficulty.", d = "Begin with the medium difficulty to unlock the hardest setting. Master the complex patterns here, as one mistake resets your score.", x = 8 },
        [15217] = { e = 3, s = "g", r = "Requires repeating the previous achievement 10 times.", d = "Unlock the previous achievement first, then grind the hardest difficulty repeatedly until you hit ten perfect scores. This is account-wide, so any character can contribute.", x = 8 },
        [15220] = { e = 4, s = "g", r = "Requires grinding reputation to Exalted level.", d = "Grind reputation with Enlightened Brokers in Shadowlands until you reach Exalted status. This is account-wide, allowing all your characters to share the progress.", x = 8 },
        [15221] = { e = 3, s = "c", h = { 92472, 92466, 92467 }, r = "Requires completing four specific dance achievements.", d = "Complete all listed dance achievements first, as this one acts as a summary requirement for the full set. Ensure every prerequisite is finished before claiming the reward.", x = 8 },
        [15222] = { e = 1, s = "s", r = "One dance game attempt on easiest difficulty.", d = "Start with the easiest dance difficulty to unlock the next tier. Practice your timing on the first attempt, as a perfect score is required immediately.", x = 8 },
        [15223] = { e = 3, s = "g", r = "Requires repeating the previous achievement 10 times.", d = "Unlock the previous achievement first, then grind the easiest difficulty repeatedly until you hit ten perfect scores. This is account-wide, so any character can contribute.", x = 8 },
        [15224] = { e = 4, s = "c", h = { 94252, 94253, 94254 }, r = "Requires exploring many specific zones and points.", d = "Explore Zereth Mortis thoroughly to reveal all covered map areas and complete sub-achievements like Path of Inception. Use Firim's Forge-Tap on Progenitor Forges for rare materials.", x = 8 },
        [15229] = { e = 4, s = "g", r = "Requires farming rare proto-materials from forges.", d = "Use Firim's Forge-Tap on Progenitor Forges throughout Zereth Mortis to collect the listed rare proto-materials. This is account-wide, so any character can contribute to the total count.", x = 8 },
        [15241] = { e = 3, s = "c", r = "Requires completing multiple renown and covenant steps.", d = "Reach Renown level 80 by completing Covenant Sanctum quests and activities. Unlock this via Champion of the Covenant first, then grind reputation until maxed.", x = 8 },
        [15251] = { e = 2, s = "s", r = "One run of Torghast Layer 1.", d = "Complete Layer 1 of The Jailer's Gauntlet in Torghast to unlock the next layer. This is account-wide, so any character can contribute to the progress.", x = 8 },
        [15252] = { e = 3, s = "g", r = "Requires completing previous layer; moderate difficulty per run.", d = "Complete Layer 1 first to unlock this layer, then run Torghast until you reach the second floor. Be prepared for increased difficulty as mechanics become more complex.", x = 8 },
        [15253] = { e = 3, s = "g", r = "Requires completing previous layer; moderate difficulty per run.", d = "Finish Layer 2 before attempting this one, as it is strictly sequential. Expect tougher enemies and new mechanics that require careful positioning.", x = 8 },
        [15254] = { e = 4, s = "g", r = "Higher layers are significantly harder and require more skill.", d = "Unlock this by completing Layer 3 first; the rewards include a rare mount. Ensure your gear is sufficient for the escalating challenge levels.", x = 8 },
        [15255] = { e = 4, s = "g", r = "Higher layers are significantly harder and require more skill.", d = "Progress through Layer 4 to access this tier, noting that failure resets your run. Save consumables for the final boss encounter in this layer.", x = 8 },
        [15256] = { e = 4, s = "g", r = "Higher layers are significantly harder and require more skill.", d = "Complete Layer 5 as a prerequisite; this layer introduces significant mechanical shifts. Coordinate with your group to handle new adds efficiently.", x = 8 },
        [15257] = { e = 4, s = "g", r = "Higher layers are significantly harder and require more skill.", d = "Finish Layer 6 before starting here, as the difficulty curve steepens noticeably. Watch for environmental hazards that can interrupt your progress.", x = 8 },
        [15258] = { e = 4, s = "g", r = "Higher layers are significantly harder and require more skill.", d = "Unlock this by clearing Layer 7; expect high-level mechanics demanding precise timing. Keep an eye on cooldowns to manage the final boss effectively.", x = 8 },
        [15259] = { e = 3, s = "c", h = { 93887 }, r = "Most quests are easy; Crown of Wills is the hardest.", d = "Start with the 9.2 campaign quests listed in the info field to unlock all storylines. Complete each quest chain sequentially to earn the points.", x = 8 },
        [15309] = { e = 2, s = "s", r = "Any challenge works; Timewalking makes bosses easier.", d = "Wait for Legion Timewalking events to activate the Mage Tower. Choose any specialization challenge and complete it once to claim the achievement.", x = 8 },
        [15310] = { e = 3, s = "c", r = "Most challenges are easy; Closing the Eye is hardest.", d = "During Legion Timewalking, attempt every unique Mage Tower challenge available. This requires multiple runs as some challenges are missable or time-gated.", x = 8 },
        [15314] = { e = 5, s = "g", r = "Flawless runs require perfect play and high skill.", d = "First achieve a Flawless run on Layer 12 to unlock this specific layer. Focus on perfect execution to avoid any damage taken during the run.", x = 8 },
        [15315] = { e = 4, s = "s", r = "Requires specific raid mechanics and a rare task.", d = "Enter the Sepulcher of the First Ones on Normal or higher difficulty and complete the Infiltration of Dread. Defeat the Lords of Dread after finishing one simple task to succeed.", x = 8 },
        [15316] = { e = 4, s = "s", r = "Requires flawless run on high Torghast layer.", d = "Unlock Layer 12 first, then farm Layer 16 repeatedly until you achieve a Flawless run with zero deaths. Focus on perfect dodging and cooldown management to avoid any damage taken.", x = 8 },
        [15317] = { e = 4, s = "s", r = "Requires flawless run on high Torghast layer.", d = "Complete the prerequisite Layer 12 achievement before attempting Layer 16 in The Soulforges. Practice your movement skills to ensure you can survive without taking damage or dying.", x = 8 },
        [15318] = { e = 4, s = "s", r = "Requires flawless run on high Torghast layer.", d = "Finish the Layer 12 requirement for Coldheart Interstitia first, then grind Layer 16 until you secure a Flawless run. Be prepared to restart frequently if you take any damage.", x = 8 },
        [15319] = { e = 4, s = "s", r = "Requires flawless run on high Torghast layer.", d = "Unlock the Layer 12 prerequisite for Mort'regar before attempting the Layer 16 challenge. Maintain strict zero-damage gameplay and avoid unnecessary aggro from enemies.", x = 8 },
        [15320] = { e = 4, s = "s", r = "Requires flawless run on high Torghast layer.", d = "Achieve a Flawless run on Layer 12 in The Upper Reaches first, then progress to Layer 16. Coordinate with your group to minimize damage intake during the ascent.", x = 8 },
        [15322] = { e = 4, s = "c", h = { 94239, 94240, 94241 }, r = "Requires flawless runs on all five Torghast wings.", d = "Complete all individual Layer 16 Flawless achievements for every wing before claiming this master title. This requires extensive grinding and perfect execution in each zone.", x = 8 },
        [15324] = { e = 4, s = "c", h = { 94269, 94270, 94271 }, r = "Requires multiple high-difficulty Torghast and raid runs.", d = "Finish the Tower Ranger meta-achievement by completing all listed sub-goals, including Adamant Vaults and Twisting Corridors. Ensure you have unlocked every necessary prerequisite first.", x = 8 },
        [15325] = { e = 3, s = "c", r = "Requires completing several Forbidden Reach storylines.", d = "Progress through all Forbidden Reach storylines sequentially to unlock the Dracthyr, Awaken achievement. Complete each specific storyline quest before moving to the next one.", x = 9 },
        [15331] = { e = 4, s = "g", r = "Requires finding many hidden treasures in Zereth Mortis.", d = "Explore Zereth Mortis thoroughly to find all hidden treasures listed in the requirements. Check chests and interact with objects carefully to avoid missing any collectibles.", x = 8 },
        [15336] = { e = 4, s = "c", h = { 94542, 94328, 94541 }, r = "Requires completing all major Zereth Mortis achievements.", d = "Complete every Zereth Mortis sub-achievement, including Secrets of the First Ones and Dune Dominance, before earning the main title. Ensure all exploration goals are met first.", x = 8 },
        [15381] = { e = 3, s = "s", r = "Requires defeating specific raid mechanics once.", d = "Defeat the Depleted Automa in the Sepulcher of the First Ones on Normal or higher difficulty to unlock the next phase. Then defeat the Vigilant Guardian immediately after.", x = 8 },
        [15386] = { e = 4, s = "g", r = "Requires collecting six rare artifacts and defeating constructs.", d = "Collect six strange artifacts and defeat their constructs before facing Halondrus the Reclaimer in the Sepulcher of the First Ones. Ensure you are on Normal difficulty or higher.", x = 8 },
        [15388] = { e = 2, s = "c", r = "Requires visiting four zones; trivial once in Shadowlands.", d = "Explore Revendreth, Maldraxxus, Ardenweald, and Bastion in any order to unlock this account-wide title. There are no time gates or rare drops; simply travel to each zone and complete the main exploration quests.", x = 8 },
        [15391] = { e = 4, s = "g", r = "Grinding many encounters in Zereth Mortis takes time.", d = "Complete all special encounters in Zereth Mortis, including Gluttonous Overgrowth and General Zarathura. These are not rare drops but specific boss fights you must defeat at least once while in the zone.", x = 8 },
        [15392] = { e = 4, s = "g", r = "Rare spawns require significant grinding and luck.", d = "Defeat the three rare encounters Iska, High Reaver Damaris, and Reanimatrox Marzan in Zereth Mortis. Unlike normal bosses, these require finding them as rare spawns rather than queuing for a standard raid.", x = 8 },
        [15394] = { e = 2, s = "c", r = "Completing five storylines in Ohn'ahran Plains is easy.", d = "Reach level 10 on the Ohn'ahran Plains and complete the main storyline quests listed in the info field. This is account-wide, so any character can finish the required storylines to unlock it.", x = 9 },
        [15396] = { e = 4, s = "s", r = "Specific raid condition makes this hard to get.", d = "Defeat Rygelon in the Sepulcher of the First Ones while every player has the Herald of the Cosmos buff active. Ensure your group maintains this debuff throughout the entire fight on Normal or higher difficulty.", x = 8 },
        [15397] = { e = 4, s = "s", r = "Requires specific item drop and raid boss kill.", d = "Kill Dausegne, the Fallen Oracle while at least one player carries the Afterlife Core during the encounter. Coordinate with your raid to ensure someone holds the core until the boss dies.", x = 8 },
        [15398] = { e = 4, s = "s", r = "Needs pilfered artifacts buff during a raid fight.", d = "Defeat Xy'mox in the Sepulcher of the First Ones with all players affected by Pilfered Relics. You must acquire these artifacts before starting the fight and keep them active during the entire encounter.", x = 8 },
        [15399] = { e = 4, s = "s", r = "Requires defeating specific encounter before final boss.", d = "First defeat Anduin's Grief, then continue to kill Anduin Wrynn in the same run on Normal or higher difficulty. This is a sequential requirement within the Sepulcher of the First Ones raid.", x = 8 },
        [15400] = { e = 4, s = "g", r = "Petting 20 corgis requires long raid time.", d = "Pet five Corgis for each player during Wild Stampede before defeating the Prototype Pantheon. Coordinate with your group to ensure everyone pets enough corgis before pulling the final boss.", x = 8 },
        [15401] = { e = 4, s = "s", r = "Specific mechanic required during a difficult raid boss.", d = "Defeat Skolex, the Insatiable Ravener after it burrows and destroys all four Memorial Pylons. This requires patience during the fight to wait for the pylons to break before killing the boss.", x = 8 },
        [15402] = { e = 3, s = "c", r = "Finding and completing four cypher sets takes time.", d = "Complete every Metrial, Aealic, Dealic, and Trebalim Cypher listed in the info field. These are specific objectives within Zereth Mortis that must be finished individually to unlock this achievement.", x = 8 },
        [15404] = { e = 2, s = "s", r = "Simple action using a specific item once found.", d = "Use a Cypher of the First Ones to cleanse one of Antros' Destruction Cores in Zereth Mortis. This is a simple interaction quest with no time gate or rare drop mechanics involved.", x = 8 },
        [15406] = { e = 2, s = "g", r = "Craft one item; trivial for new players.", d = "Head to Zereth Mortis and craft any protoform creature at a forge. This is the first step in the crafting chain, so just start experimenting with available recipes immediately.", x = 8 },
        [15407] = { e = 3, s = "g", r = "Craft five items; requires some time.", d = "Continue crafting different protoform creatures until you have five unique ones. Ensure you track your progress carefully to avoid repeating designs before unlocking the next tier.", x = 8 },
        [15408] = { e = 2, s = "c", r = "Buy or earn PvP gear; very easy.", d = "Collect a full armor set from Shadowlands PvP Season 3 or 4. You can obtain these through PvP rewards or specific world drops, so check your collection tab regularly.", x = 8 },
        [15409] = { e = 3, s = "c", r = "Craft a tier set; moderate crafting time.", d = "Gather an armor set from the Sepulcher of the First Ones raid. This requires defeating bosses in that specific raid instance, so prioritize clearing content on any difficulty.", x = 8 },
        [15410] = { e = 4, s = "g", r = "Craft twenty-five items; significant grind.", d = "Expand your crafting efforts to reach twenty-five different protoform creatures. Keep a list of crafted items to ensure you are hitting the diversity requirement efficiently.", x = 8 },
        [15411] = { e = 5, s = "g", r = "Craft fifty items; massive time investment.", d = "Aim for fifty distinct protoform creatures at Zereth Mortis. This is a long-term goal requiring extensive crafting sessions, so plan your time around new recipe unlocks.", x = 8 },
        [15416] = { e = 3, s = "c", r = "Defeat specific bosses; standard raid content.", d = "Defeat specific bosses in the Sepulcher of the First Ones to unlock this part of the raid achievement. Focus on clearing the designated wing content first.", x = 8 },
        [15417] = { e = 3, s = "c", r = "Clear the raid on any difficulty.", d = "Clear all bosses in the Sepulcher of the First Ones on any difficulty. Start with Normal mode if you are new to the raid to learn mechanics before attempting harder versions.", x = 8 },
        [15418] = { e = 2, s = "s", r = "Defeat final boss; single step event.", d = "Progress through the raid until you reach and defeat The Jailer. This achievement unlocks after completing the previous raid parts, so ensure all prior bosses are cleared.", x = 8 },
        [15419] = { e = 3, s = "c", r = "Specific raid condition; moderate difficulty.", d = "Defeat Lihuvim only after synthesizing and defeating Reaving Automa: Neo on Normal or higher. Follow the specific quest chain order to unlock this boss encounter properly.", x = 8 },
        [15478] = { e = 4, s = "c", r = "Heroic raid bosses; requires skill/group.", d = "Clear all Sepulcher of the First Ones bosses on Heroic difficulty. This is a significant step up in gear and skill, so ensure your group is well-prepared before starting.", x = 8 },
        [15479] = { e = 5, s = "c", r = "Mythic Vigilant Guardian; high RNG/skill.", d = "Defeat Vigilant Guardian specifically on Mythic difficulty. This requires high-level gear and coordination, so join a skilled group familiar with the raid's mechanics.", x = 8 },
        [15480] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Queue for Mythic difficulty in the Sepulcher of the First Ones and focus on defeating Skolex. Ensure your group is well-geared as this boss requires high damage output and coordination.", x = 8 },
        [15481] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Defeat Artificer Xy'mox in Mythic mode by managing her mechanics carefully. This fight can be challenging, so practice with a dedicated group to avoid wipes.", x = 8 },
        [15482] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Target Dausegne in the Sepulcher of the First Ones on Mythic difficulty. Coordinate your team's abilities to handle her specific mechanics effectively.", x = 8 },
        [15483] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Defeat Prototype Pantheon in Mythic mode within the Sepulcher of the First Ones. This encounter requires precise timing and group synchronization to succeed.", x = 8 },
        [15484] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Challenge Lihuvim in the Sepulcher of the First Ones on Mythic difficulty. Prepare your group for complex mechanics that demand high skill levels.", x = 8 },
        [15485] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Defeat Halondrus in the Sepulcher of the First Ones on Mythic difficulty. Focus on maintaining consistent damage and managing adds during the fight.", x = 8 },
        [15486] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Face Anduin Wrynn in the Sepulcher of the First Ones on Mythic difficulty. Ensure your group is prepared for his unique mechanics and high burst damage.", x = 8 },
        [15487] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Defeat the Lords of Dread in the Sepulcher of the First Ones on Mythic difficulty. Coordinate with your team to handle multiple enemies simultaneously.", x = 8 },
        [15488] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Challenge Rygelon in the Sepulcher of the First Ones on Mythic difficulty. Practice his mechanics thoroughly to avoid unnecessary deaths during the encounter.", x = 8 },
        [15489] = { e = 5, s = "s", r = "Requires Mythic raid group and specific boss kill.", d = "Defeat The Jailer in the Sepulcher of the First Ones on Mythic difficulty to earn the Guardian of the Pattern title. This is the final boss and requires full group coordination.", x = 8 },
        [15490] = { e = 5, s = "c", h = { 95108, 95107, 95106 }, r = "Requires clearing entire Mythic raid; hardest bosses dominate.", d = "Complete all listed Sepulcher of the First Ones Mythic boss achievements to unlock the main raid achievement. Ensure you have cleared Heroic difficulty first as a prerequisite.", x = 8 },
        [15491] = { e = 5, s = "c", h = { 95133, 95120, 95119 }, r = "Requires clearing entire Mythic raid; hardest bosses dominate.", d = "Finish all specific Sepulcher of the First Ones achievements listed to earn the Glory of the Sepulcher Raider title and mount. This is account-wide and requires completing various sub-achievements.", x = 8 },
        [15492] = { e = 3, s = "c", r = "Defeat 3 raid bosses on Normal or higher.", d = "Defeat all Sepulcher bosses on Normal or higher, as the Jailer fight requires collecting six Progenitor Orbs first. This is account-wide and needs no specific group composition beyond clearing the raid wings.", x = 8 },
        [15493] = { e = 3, s = "c", r = "Defeat 4 raid bosses on Normal or higher.", d = "Clear every boss in the Ephemeral Plains wing of the Sepulcher on Normal difficulty or higher to unlock this title. Treat it as a standard raid clear with no special drop mechanics mentioned.", x = 8 },
        [15494] = { e = 4, s = "g", r = "Grind for 6 orbs then defeat Jailer boss.", d = "You must collect six Progenitor Orbs before defeating the Jailer on Normal or higher difficulty to earn this achievement. Ensure you have enough time to gather orbs if you plan to run the final boss immediately.", x = 8 },
        [15502] = { e = 3, s = "g", r = "Collect 8 sand piles scattered across zone.", d = "Dig up all sand piles scattered across Zereth Mortis, including rare variants like the Ticking Sand Pile. This is account-wide and requires no group, just thorough exploration of the zone.", x = 8 },
        [15508] = { e = 4, s = "c", r = "Find and collect all 9 unique costumes.", d = "Collect every Pocopoc costume variant by interacting with NPCs or completing related activities in Zereth Mortis. Do not miss any costumes as this achievement tracks total collection count.", x = 8 },
        [15509] = { e = 3, s = "g", r = "Read 7 book volumes scattered in zone.", d = "Read all seven volumes of Firim in Exile found throughout Zereth Mortis to complete this reading list. These books are scattered across the zone and must be physically picked up.", x = 8 },
        [15511] = { e = 4, s = "g", r = "Complete 50 rounds of Solo Shuffle arena.", d = "Complete fifty rounds of Solo Shuffle in PvP Arena mode, which requires the Solo Aspirations feature enabled. This is account-wide and does not require a group for each round.", x = 8 },
        [15512] = { e = 3, s = "c", r = "Defeat 10 special encounters in Zereth Mortis.", d = "Finish ten special encounters in Zereth Mortis such as Gluttonous Overgrowth or General Zarathura. Some bosses may drop multiple times, so track your progress carefully to avoid missing required kills.", x = 8 },
        [15513] = { e = 3, s = "g", r = "Discover 5 hidden treasure chests/locations.", d = "Find five hidden treasure chests or caches like the Library Vault or Stolen Relic by exploring Zereth Mortis thoroughly. These are often missable if not checked during initial zone runs.", x = 8 },
        [15514] = { e = 3, s = "c", r = "Complete several other Zereth Mortis tasks.", d = "Complete all listed Zereth Mortis achievements including exploration, reading, and special encounters to unlock flying in the zone. Start with easy tasks like reading books before tackling raid content.", x = 8 },
        [15515] = { e = 2, s = "c", r = "Complete 3 short quest storylines.", d = "Finish the three questlines Small Pet Problems, Not All Are Lost, and A Return to Grace to complete this storyline achievement. These quests are tied to specific NPCs or events in Zereth Mortis.", x = 8 },
        [15518] = { e = 2, s = "s", r = "Complete one specific quest storyline.", d = "Complete the single storyline quest A Means to an End to finish this achievement. It is likely part of a larger narrative chain in Zereth Mortis, so follow quest markers closely.", x = 8 },
        [15539] = { e = 2, s = "g", r = "Grind 15 rounds; easy solo queue.", d = "Queue for Solo Shuffle and play until you hit 15 rounds, ignoring wins or losses. This is purely time-gated by queue availability, so be patient if the arena is full.", x = 8 },
        [15540] = { e = 3, s = "g", r = "Grind 150 rounds; moderate time investment.", d = "After unlocking the previous tier, continue queuing for Solo Shuffle to reach 150 total rounds played. No specific strategy is needed beyond consistent participation over time.", x = 8 },
        [15541] = { e = 2, s = "g", r = "Win 15 rounds; RNG adds slight variance.", d = "Focus on winning your Solo Shuffle matches rather than just playing them; you need 15 victories specifically. Avoid risky fights early on until you master the solo mechanics.", x = 8 },
        [15542] = { e = 3, s = "g", r = "Grind wildlife automa; moderate time.", d = "Travel to Zereth Mortis and equip Pocopoc to automate wildlife takedowns, aiming for 100 completions. This is account-wide, so coordinate with friends if you want faster progress.", x = 8 },
        [15543] = { e = 3, s = "g", r = "Win 50 rounds; RNG makes it harder.", d = "Once you have won 15 Solo Shuffle rounds, keep playing to reach the 50-win threshold required for this title. Consistent performance in the arena will eventually unlock it.", x = 8 },
        [15544] = { e = 4, s = "g", r = "Win 150 rounds; significant grind time.", d = "Continue winning Solo Shuffle matches until you reach 150 total victories to earn both the achievement and the Soloist title. This is a long-term goal requiring many hours of play.", x = 8 },
        [15579] = { e = 2, s = "s", r = "Complete storyline; straightforward quest chain.", d = "Complete the Return to Lordaeron storyline in Shadowlands to unlock the Dark Ranger customization and title. Ensure you have access to the relevant zones before starting this quest chain.", x = 8 },
        [15638] = { e = 3, s = "c", r = "Multiple storylines; checklist effort dominates.", d = "Finish all listed storylines in the Forbidden Reach for Dracthyr, including The War Creche and others. This is essential for unlocking your Dracthyr character's full potential.", x = 9 },
        [15641] = { e = 4, s = "g", r = "Grind 1200 pets; heavy RNG and time.", d = "Collect 1200 unique pets by exploring all zones and completing pet-related quests. Start early as this is a massive grind that spans multiple expansions and requires patience.", x = 9 },
        [15642] = { e = 4, s = "g", r = "Grind 1400 pets; heavy RNG and time.", d = "After reaching 1200 pets, continue collecting to hit 1400 for the next tier. Use daily dailies and world events to efficiently gather new companions without missing out on rare drops.", x = 9 },
        [15643] = { e = 4, s = "g", r = "Grind 1600 pets; heavy RNG and time.", d = "Keep expanding your pet collection beyond 1400 to reach 1600 unique pets. This stage of the achievement chain demands thorough exploration across all available content areas.", x = 9 },
        [15644] = { e = 4, s = "g", r = "Grind 1800 pets; heavy RNG and time.", d = "Push your pet count past 1600 to achieve 1800 unique companions. Be prepared for a lengthy process involving rare drops and extensive world exploration across multiple expansions.", x = 10 },
        [15646] = { e = 4, s = "g", r = "Requires reaching max renown with all four covenants.", d = "Renown caps at 80, so grind all four covenants to max before any cap changes or expansions. Complete their campaigns first for bonuses, then finish renown via daily activities and world quests.", x = 8 },
        [15647] = { e = 3, s = "c", r = "Complete four distinct campaign quests.", d = "Start each covenant campaign immediately after reaching Renown 20 with that faction to avoid missing early steps. Finish all four campaigns as they are account-wide and cannot be retraced later.", x = 8 },
        [15648] = { e = 4, s = "c", r = "Requires completing multiple Maw-specific achievements.", d = "Enter the Maw, complete its exploration achievements, and defeat Ghast Five for the title. This content is time-gated by expansion progression and requires full Maw access.", x = 8 },
        [15649] = { e = 3, s = "c", r = "Complete four specific covenant special feature tasks.", d = "Complete each covenant special feature achievement by engaging their unique mechanics like loyalty quests or guest events. These are account-wide but require specific covenant activities to unlock.", x = 8 },
        [15650] = { e = 4, s = "s", r = "Requires defeating a specific dungeon boss on Mythic+.", d = "Run Streets of Wonder on Mythic+ difficulty and defeat So'azmi to claim the achievement. Ensure you have a group capable of handling Mythic-level content for this dungeon.", x = 8 },
        [15651] = { e = 5, s = "c", h = { 134093, 134094, 134095 }, r = "Grinding all eight dungeons on Mythic+ is very hard.", d = "Queue or group up for each Shadowlands dungeon on Mythic+ difficulty, starting with The Necrotic Wake. This is account-wide, so coordinate with friends if possible to clear all dungeons efficiently.", x = 8 },
        [15652] = { e = 4, s = "s", r = "Requires defeating a specific dungeon boss on Mythic+.", d = "Defeat So'leah in So'leah's Gambit on Mythic+ by running the dungeon repeatedly until the boss is defeated. This requires a capable group and may take time due to the dungeon's mechanics.", x = 8 },
        [15781] = { e = 3, s = "g", r = "Collecting 500 toys is a steady grind.", d = "Collect 500 toys by engaging with various game activities like world events, dungeons, and raids. Use toy vendors or daily rewards to speed up collection if available.", x = 9 },
        [15794] = { e = 2, s = "s", r = "Unlocking one specific drake is easy.", d = "Unlock the Renewed Proto-Drake by completing Dragonriding quests in Dragonflight. This is account-wide, so ensure you have the necessary reputation or quest progress before starting.", x = 9 },
        [15795] = { e = 2, s = "s", r = "Unlocking one specific drake is easy.", d = "Unlock the Windborne Velocidrake by progressing through Dragonflight's dragonriding content and completing related quests. Coordinate with friends if needed for group activities to speed up unlocks.", x = 9 },
        [15796] = { e = 2, s = "s", r = "Unlocking one specific drake is easy.", d = "Unlock the Cliffside Wylderdrake by advancing in Dragonflight's dragonriding storyline and completing specific objectives. This is account-wide, so focus on main story progression first.", x = 9 },
        [15797] = { e = 2, s = "s", r = "Unlocking one specific drake is easy.", d = "Unlock the Highland Drake by finishing Dragonflight's dragonriding quests and reaching required reputation levels. Prioritize main story content to unlock this drake efficiently.", x = 9 },
        [15805] = { e = 2, s = "s", r = "Grind to level 70 takes a few hours.", d = "Grind any content until you hit level 70. This is a simple progression goal with no specific strategy needed.", x = 9 },
        [15833] = { e = 4, s = "g", r = "Collecting 500 mounts is a long grind.", d = "This account-wide mount collection requires obtaining 500 unique mounts. Focus on daily dailies and world bosses to gather them efficiently over time.", x = 9 },
        [15834] = { e = 4, s = "g", r = "Collecting 500 mounts is a long grind.", d = "Same as the previous entry, this is an account-wide goal requiring 500 mounts. Prioritize rare drops and event mounts to speed up progress.", x = 9 },
        [15889] = { e = 2, s = "s", r = "Catch 40 fish in one session is easy.", d = "Complete Ruriq's River Rapids Ride in one session without stopping. You must catch exactly 40 fish during this single ride attempt.", x = 9 },
        [15890] = { e = 3, s = "g", r = "Flagging 10 peaks takes a few hours.", d = "Use the Dragonscale Expedition tool to locate the tallest peaks. Place flags on ten of these specific high points across the Dragon Isles.", x = 9 },
        [15915] = { e = 3, s = "c", h = { 136655, 136656, 136657 }, r = "Completing all bronze races is moderate.", d = "Unlock Skyriding in Waking Shores and complete every race at Bronze difficulty. Do not skip any track to ensure you meet the full requirement.", x = 9 },
        [15916] = { e = 3, s = "c", h = { 136664, 136665, 136666 }, r = "Getting silver in all races is moderate.", d = "After finishing all Bronze races in Waking Shores, upgrade each track to Silver. This unlocks a new reward and progresses the achievement chain.", x = 9 },
        [15917] = { e = 3, s = "c", h = { 136673, 136674, 136675 }, r = "Getting gold in all races is moderate.", d = "Repeat the process by upgrading all your Waking Shores tracks from Silver to Gold. Ensure every single race is completed at this tier.", x = 9 },
        [15918] = { e = 3, s = "c", h = { 136709, 136710, 136711 }, r = "Completing all bronze races is moderate.", d = "Unlock Skyriding in Ohn'ahran Plains and finish all races at Bronze difficulty. Treat each track as a separate task within the zone.", x = 9 },
        [15919] = { e = 3, s = "c", h = { 136716, 136717, 136718 }, r = "Getting silver in all races is moderate.", d = "Upgrade every Ohn'ahran Plains race from Bronze to Silver. This step is required before you can attempt the Gold tier achievements.", x = 9 },
        [15920] = { e = 3, s = "c", h = { 136723, 136724, 136725 }, r = "Getting gold in all races is moderate.", d = "Complete all Ohn'ahran Plains races at Gold difficulty. You must have already finished both Bronze and Silver tiers for this to unlock.", x = 9 },
        [15921] = { e = 3, s = "c", h = { 136745, 136746, 136747 }, r = "Completing all bronze races is moderate.", d = "Unlock Skyriding in Azure Span and complete all initial races at Bronze difficulty. Start with the basic sprint and slalom tracks first.", x = 9 },
        [15922] = { e = 3, s = "c", r = "Requires completing multiple distinct races across all normal zones.", d = "Unlock the Bronze tier first to gain access to all required races. Complete each race on every normal character race before moving up tiers, as this achievement is account-wide but requires specific characters.", x = 9 },
        [15923] = { e = 3, s = "c", r = "Requires completing multiple distinct races across all normal zones with higher difficulty.", d = "You must finish the Silver tier achievements before attempting Gold. Ensure you have completed all races on your current set of characters to unlock the next tier's requirements without delay.", x = 9 },
        [15924] = { e = 3, s = "c", r = "Requires completing multiple distinct races across Thaldraszus zone.", d = "Start with Bronze races in Thaldraszus, completing them on all normal character races. Do not rush to Silver until every Bronze race is finished across your entire account roster.", x = 9 },
        [15925] = { e = 3, s = "c", r = "Requires completing multiple distinct races across Thaldraszus with higher difficulty.", d = "Complete the Silver tier after securing all Bronze achievements. This step grants a drake customization reward and unlocks the path to Gold, so prioritize finishing all races first.", x = 9 },
        [15926] = { e = 3, s = "c", r = "Requires completing multiple distinct races across Thaldraszus with highest difficulty.", d = "Finish the Silver tier completely before attempting Gold races. Since this is account-wide, ensure you have a full roster of characters ready to tackle the final tier efficiently.", x = 9 },
        [15927] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Waking Shores zone.", d = "Begin with Bronze advanced races in Waking Shores on all your characters. You must complete every single race before unlocking Silver, so plan your character rotation carefully to avoid bottlenecks.", x = 9 },
        [15928] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Waking Shores with higher difficulty.", d = "Unlock the Silver tier only after finishing all Bronze races. This achievement grants a drake customization, so ensure you have completed every race on all characters before progressing.", x = 9 },
        [15929] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Waking Shores with highest difficulty.", d = "Complete the Silver advanced races to unlock Gold. Remember that this is account-wide, so you need to cycle through your entire character roster to finish the prerequisite tier first.", x = 9 },
        [15930] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Ohn'ahran Plains zone.", d = "Start with Bronze advanced races in Ohn'ahran Plains on all characters. You cannot access Silver until every Bronze race is completed across your account, so manage your character queue effectively.", x = 9 },
        [15931] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Ohn'ahran Plains with higher difficulty.", d = "Finish the Silver tier after securing all Bronze achievements. This step rewards a drake customization and unlocks Gold, requiring you to clear every race on your current characters first.", x = 9 },
        [15932] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Ohn'ahran Plains with highest difficulty.", d = "Complete the Silver advanced races before attempting Gold. Since this is account-wide, ensure you have finished all prerequisite races on every character to avoid getting stuck at the next tier.", x = 9 },
        [15933] = { e = 3, s = "c", r = "Requires completing multiple advanced races in Azure Span zone.", d = "Begin with Bronze advanced races in the Azure Span on all characters. You must finish every race before unlocking Silver, so plan your character usage to complete the entire set efficiently.", x = 9 },
        [15934] = { e = 2, s = "c", r = "Requires unlocking and running several short races.", d = "Unlock the Bronze tier first to access all races. Complete each race once for Silver, then repeat with higher settings for Gold. This is account-wide and requires no specific group composition.", x = 9 },
        [15935] = { e = 2, s = "c", r = "Requires unlocking and running several slightly harder races.", d = "You must already have the Silver achievement unlocked. Focus on mastering the harder course settings for each race to earn Gold points efficiently without needing a new group.", x = 9 },
        [15936] = { e = 2, s = "c", r = "Requires completing multiple short races across zones.", d = "Start by completing all Bronze races in every zone. Once done, unlock and complete the Silver tier before moving on to Gold. This unlocks the next tier automatically upon completion.", x = 9 },
        [15937] = { e = 2, s = "c", r = "Requires unlocking and running several slightly harder races.", d = "Finish the Bronze tier first, then grind each race again for Silver points. Do not skip this step, as it is a hard requirement before you can attempt the Gold tier.", x = 9 },
        [15938] = { e = 2, s = "c", r = "Requires completing multiple short races across zones.", d = "Complete all races in every zone at any difficulty to unlock Bronze. Then progress through Silver and Gold tiers sequentially. This is account-wide and tracks total race completions.", x = 9 },
        [15939] = { e = 2, s = "c", r = "Requires completing multiple short races across zones.", d = "Unlock the Silver tier by finishing all races again with higher settings. You can mix standard and advanced races to meet the criteria for this specific achievement.", x = 9 },
        [15940] = { e = 2, s = "c", r = "Requires unlocking and running several slightly harder races.", d = "Complete all races one final time at the highest difficulty settings to earn Gold. This is the last step in the main racing chain and grants a title.", x = 9 },
        [15941] = { e = 2, s = "c", r = "Requires unlocking and running several much harder races.", x = 9 },
        [16110] = { e = 3, s = "s", r = "Single visit but requires specific Mythic dungeon access.", d = "Enter Brackenhide Hollow on Mythic difficulty with a group. Talk to Gwybod immediately and listen to five distinct hyena facts during that single visit to complete it.", x = 9 },
        [16255] = { e = 3, s = "s", r = "Single boss kill in a standard dungeon.", d = "Defeat the boss Decatriarch Wratheye in normal mode first. This unlocks the Heroic tier, so ensure you have the basic dungeon unlocked before attempting harder difficulties.", x = 9 },
        [16256] = { e = 4, s = "s", r = "Requires Heroic+ dungeon key and specific boss kill.", d = "You must clear the normal version first to unlock Heroic. Once unlocked, defeat the boss on Heroic difficulty or higher to claim this achievement.", x = 9 },
        [16257] = { e = 4, s = "s", r = "Requires Mythic+ dungeon key and specific boss kill.", d = "Clear the Heroic tier before attempting Mythic. Defeat the boss on Mythic or Mythic Keystone difficulty to finish the chain for this dungeon.", x = 9 },
        [16260] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Queue for Halls of Infusion and defeat the Primal Tsunami boss to earn this. Complete the Normal version first before attempting Heroic or Mythic difficulties.", x = 9 },
        [16261] = { e = 5, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "You must finish Normal Halls of Infusion first, then queue for Heroic difficulty and defeat the Primal Tsunami boss again. Do not skip the Normal version as it is a hard requirement.", x = 9 },
        [16262] = { e = 5, s = "s", r = "Mythic raid boss requires high-level group performance.", d = "Complete both Normal and Heroic versions of Halls of Infusion before attempting Mythic difficulty. Defeat the Primal Tsunami on Mythic or Mythic Keystone to finish.", x = 9 },
        [16263] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Queue for Neltharus and defeat Warlord Sargha boss in Normal difficulty to claim this achievement. Ensure you are in a group capable of clearing the dungeon first.", x = 9 },
        [16264] = { e = 5, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Finish Normal Neltharus before attempting Heroic difficulty where you must defeat Warlord Sargha again. This progression is mandatory to unlock the next tier.", x = 9 },
        [16265] = { e = 5, s = "s", r = "Mythic raid boss requires high-level group performance.", d = "Clear both Normal and Heroic Neltharus instances before tackling Mythic difficulty. Defeat Warlord Sargha on Mythic or Mythic Keystone to complete the set.", x = 9 },
        [16266] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Queue for Ruby Life Pools and defeat both Kyrakka and Erkhart Stormvein bosses in Normal difficulty. Make sure you kill all required bosses before leaving the instance.", x = 9 },
        [16267] = { e = 5, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Complete Normal Ruby Life Pools first, then queue for Heroic difficulty to defeat Kyrakka and Erkhart Stormvein again. Skipping Normal will prevent you from starting this tier.", x = 9 },
        [16268] = { e = 5, s = "s", r = "Mythic raid boss requires high-level group performance.", d = "Finish both Normal and Heroic Ruby Life Pools before attempting Mythic difficulty. Defeat the required bosses on Mythic or Mythic Keystone to earn the points.", x = 9 },
        [16269] = { e = 4, s = "s", r = "Requires defeating a raid boss on normal difficulty.", d = "Queue for Algeth'ar Academy and defeat the Echo of Doragosa boss in Normal difficulty. Ensure your group is ready for the mechanics before engaging the boss.", x = 9 },
        [16270] = { e = 5, s = "s", r = "Heroic raid boss requires group coordination and skill.", d = "Complete Normal Algeth'ar Academy first, then queue for Heroic difficulty to defeat the Echo of Doragosa again. You cannot start Heroic without finishing Normal.", x = 9 },
        [16271] = { e = 5, s = "s", r = "Mythic raid boss requires high-level group performance.", d = "Clear both Normal and Heroic Algeth'ar Academy instances before attempting Mythic difficulty. Defeat the Echo of Doragosa on Mythic or Mythic Keystone to finish.", x = 9 },
        [16272] = { e = 3, s = "s", r = "Standard dungeon boss kill on Normal difficulty.", d = "Complete The Azure Vault dungeon on Normal difficulty to defeat Umbrelskul. This is the first step in a chain requiring Heroic and Mythic clears afterward.", x = 9 },
        [16273] = { e = 4, s = "s", r = "Heroic dungeon requires better gear and coordination.", d = "Clear The Azure Vault on Heroic or higher to earn this achievement. You must finish the Normal version first before unlocking Heroic.", x = 9 },
        [16274] = { e = 5, s = "s", r = "Mythic+ requires high-level keystone and skilled group.", d = "Defeat Umbrelskul on Mythic difficulty after completing the Heroic version. Ensure you have a group capable of handling high-level mechanics.", x = 9 },
        [16275] = { e = 3, s = "s", r = "Standard dungeon boss kill on Normal difficulty.", d = "Finish The Nokhud Offensive dungeon on Normal to defeat Balakar Khan. This unlocks the ability to attempt Heroic and Mythic versions next.", x = 9 },
        [16276] = { e = 4, s = "s", r = "Heroic dungeon requires better gear and coordination.", d = "Clear The Nokhud Offensive on Heroic or higher after beating the Normal version. Coordinate with your group for increased difficulty mechanics.", x = 9 },
        [16277] = { e = 5, s = "s", r = "Mythic+ requires high-level keystone and skilled group.", d = "Defeat Balakar Khan on Mythic difficulty following a successful Heroic run. This requires a well-coordinated team familiar with raid-level challenges.", x = 9 },
        [16278] = { e = 3, s = "s", r = "Standard dungeon boss kill on Normal difficulty.", d = "Complete Uldaman: Legacy of Tyr on Normal to defeat Chrono-Lord Deios. Start here before progressing to Heroic or Mythic difficulties.", x = 9 },
        [16279] = { e = 4, s = "s", r = "Heroic dungeon requires better gear and coordination.", d = "Clear Uldaman: Legacy of Tyr on Heroic or higher after finishing the Normal version. Prepare for tougher mechanics and better loot tables.", x = 9 },
        [16280] = { e = 5, s = "s", r = "Mythic+ requires high-level keystone and skilled group.", d = "Defeat Chrono-Lord Deios on Mythic difficulty after completing the Heroic run. This is the final step in the Uldaman achievement chain.", x = 9 },
        [16281] = { e = 4, s = "g", r = "Requires catching 20 orbs before boss fight RNG.", d = "Play Uldaman: Legacy of Tyr on Mythic and catch 20 falling Eternity Orbs before defeating Chrono-Lord Deios. Timing is critical as orbs disappear quickly.", x = 9 },
        [16282] = { e = 5, s = "s", r = "Complex mechanic requiring precise timing and luck.", d = "On Mythic Uldaman: Legacy of Tyr, stun Sentinel Talondras and all party members simultaneously before defeating the boss. Practice coordination with your group.", x = 9 },
        [16291] = { e = 2, s = "s", r = "Account-wide unlock via simple travel network usage.", d = "Unlock the Ancient Waygate travel network by completing specific quests across the Dragon Isles. This is account-wide and requires exploring various zones.", x = 9 },
        [16292] = { e = 2, s = "c", r = "Visit 8 locations; requires travel but no combat.", d = "Unlock all Ancient Waygate locations by visiting each zone in the Dragon Isles to complete their respective quests. This is account-wide and requires no specific group, but ensure you have access to all zones first.", x = 9 },
        [16294] = { e = 3, s = "c", r = "Run 8 heroic dungeons; grind depends on queue times.", d = "Queue for Heroic dungeons across all Dragonflight instances until every listed achievement pops up. Since this is account-wide, any character can contribute progress toward the total points.", x = 9 },
        [16295] = { e = 4, s = "c", h = { 137497, 137499 }, r = "Run 15 mythic dungeons; RNG-heavy quests dominate.", d = "Complete Mythic dungeon achievements by running each instance; note that some require specific quest lines or rare drops like 'See Me After Class'. This is account-wide and rewards a mount upon completion.", x = 9 },
        [16296] = { e = 3, s = "s", r = "One specific dungeon run with a mechanic to master.", d = "In Brackenhide Hollow on Mythic, free Chief Softpaw, equip her with a spear and shield, then protect her while defeating Hackclaw's War-Band. Do not let her die during the encounter.", x = 9 },
        [16297] = { e = 3, s = "g", r = "Find scattered items; effort shrinks as count rises.", d = "Explore The Waking Shores thoroughly to find hidden treasures like gems and unique items scattered in caves or behind rocks. Use your map markers to track progress if needed.", x = 9 },
        [16298] = { e = 3, s = "c", r = "Complete four sub-achievements; total time is moderate.", d = "Finish all regional treasure collections starting with The Waking Shores, then move through Ohn'ahran Plains, Azure Span, and Thaldraszus. Each region has its own set of hidden items to discover.", x = 9 },
        [16299] = { e = 3, s = "g", r = "Find scattered items in one zone; steady progress.", d = "Search Ohn'ahran Plains for unique treasures such as the Nokhud Warspear and Yennu's Boat. These are often found in hard-to-reach areas or require specific interactions.", x = 9 },
        [16300] = { e = 3, s = "g", r = "Find scattered items in one zone; steady progress.", d = "Explore The Azure Span to locate hidden treasures like the Forgotten Jewel Box and Rubber Fish. Some items may be behind walls or require climbing to reach.", x = 9 },
        [16301] = { e = 3, s = "g", r = "Find scattered items in one zone; steady progress.", d = "Visit Thaldraszus to collect unique treasures including the Cracked Hourglass and Elegant Canvas Brush. Check both ground level and higher elevations for hidden spots.", x = 9 },
        [16317] = { e = 2, s = "c", r = "Visit 3 fishing spots; requires unlocking first.", d = "Unlock all secret fishing pools by completing reputation tasks or finding special keys in each zone. Once unlocked, you can fish at Highlands, Ice, and Lava locations.", x = 9 },
        [16320] = { e = 4, s = "s", r = "Requires specific mechanic and RNG drop in one dungeon.", d = "In Ruby Life Pools on Mythic, use Molten Boulder to heat four life pools before defeating Kokia Blazehoof. Timing is key—do not skip heating the pools.", x = 9 },
        [16321] = { e = 2, s = "c", r = "Fish for two items; requires unlocking fishing spots first.", d = "Obtain the Iskaaran Harpoon and Fishing Net by completing related quests or trading with NPCs in relevant zones. These items are account-wide once obtained.", x = 9 },
        [16322] = { e = 2, s = "g", r = "Crafting upgrades; requires gathering materials.", d = "Fully upgrade your Iskaaran fishing gear by collecting all required components like harpoon handles and net weights. This is account-wide, so ensure you have access to the necessary materials before starting.", x = 9 },
        [16323] = { e = 4, s = "g", r = "Collecting scattered rare world drops across zones.", d = "Search the Dragon Isles for loose statuary fragments such as dislodged dragoneye eyes and broken banding. These items are scattered across zones, so explore thoroughly or use a group to cover more ground quickly.", x = 9 },
        [16329] = { e = 5, s = "c", h = { 138879 }, r = "Requires Mythic dungeon group and specific item on all.", d = "Gather Well-Fed Ducklings for every party member before entering Algeth'ar Academy on Mythic difficulty. Keep them equipped during the entire fight against the Overgrown Ancient without letting anyone lose their duckling.", x = 9 },
        [16330] = { e = 5, s = "c", h = { 138060 }, r = "Requires Mythic dungeon group and perfect trap avoidance.", d = "Run The Azure Vault on Mythic and avoid both polymorph traps and Shriek casts from Umbrelskul. This requires precise dodging and awareness of trap locations throughout the encounter.", x = 9 },
        [16331] = { e = 5, s = "c", h = { 138063 }, r = "Requires Mythic dungeon group and specific mechanic.", d = "Smash Shimmering Geodes with Dragon Strike to destroy nine chunks before defeating Umbrelskul in The Azure Vault on Mythic. Ensure your character has the Dragon Strike ability ready for efficient geode destruction.", x = 9 },
        [16334] = { e = 2, s = "c", r = "Completing story quests in one zone.", d = "Complete all listed storylines in the Waking Shores, including quests like Dragons in Distress and A Purpose Restored. Finish these main story arcs to unlock the achievement points.", x = 9 },
        [16335] = { e = 4, s = "c", h = { 138068 }, r = "Requires raid group and specific boss kill condition.", d = "Defeat a Burning Behemoth and locate a Frozen Portal Stone before killing Eranog in Vault of the Incades on Normal or higher. Coordinate with your raid group to handle both objectives efficiently.", x = 9 },
        [16336] = { e = 2, s = "c", r = "Completing story quests in one zone.", d = "Finish all storylines in the Azure Span, such as Into the Archives and Vakthros. These quests are account-wide, so ensure everyone contributes if needed for completion.", x = 9 },
        [16337] = { e = 5, s = "c", h = { 138090 }, r = "Requires Mythic dungeon group and mob management.", d = "Bring at least ten Stonevault Troggs alive into Uldaman: Legacy of Tyr on Mythic to defeat Bromach. Avoid killing troggs unnecessarily during the run to maintain the required count.", x = 9 },
        [16338] = { e = 2, s = "s", r = "Single game of mini-game; trivial once found.", d = "Play a single game of Fang Flap Fire and score ten points to earn this achievement. Focus on catching fish quickly while managing your team's actions effectively.", x = 9 },
        [16339] = { e = 5, s = "c", r = "Requires running all dungeons on Mythic difficulty.", d = "Complete each Dragonflight dungeon on Mythic or Mythic Keystone difficulty, including Algeth'ar Academy and The Nokhud Offensive. Prioritize running these dungeons efficiently with a skilled group.", x = 9 },
        [16343] = { e = 5, s = "c", r = "Requires defeating all raid bosses on any difficulty.", d = "Defeat all Vault of the Incarnates bosses on any difficulty, starting from Eranog through to Raszageth the Storm-Eater. This may require multiple runs if some bosses are missed or need retrying.", x = 9 },
        [16345] = { e = 4, s = "c", h = { 138142, 138143, 138144 }, r = "Requires defeating all 8 bosses on Heroic difficulty.", d = "Complete Heroic Vault of the Incarnates to unlock this account-wide set. Use a healer and tank you trust for all bosses, as mechanics vary wildly.", x = 9 },
        [16346] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Queue Mythic Eranog after clearing Heroic. Watch for his phase transitions carefully; he is not overly difficult but requires focus.", x = 9 },
        [16347] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Defeat Terros on Mythic next. His mechanics are straightforward compared to later bosses, making him a good warm-up.", x = 9 },
        [16348] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "The Primal Council is the first boss; coordinate with your group for his elemental phases. This is often the hardest of the early set.", x = 9 },
        [16349] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Sennarth requires precise positioning during her breath attacks. Ensure your healer can handle the damage spikes from her cold breath phase.", x = 9 },
        [16350] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Dathea is a single-target boss with heavy cleave mechanics. Keep your group spread out to avoid unnecessary damage during her phases.", x = 9 },
        [16351] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Kurog Grimtotem involves complex adds and movement. Communicate clearly with your team to manage the adds efficiently.", x = 9 },
        [16352] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Broodkeeper Diurna has a long fight with multiple phases. Stay alert for her spawn mechanics and avoid standing in her pools.", x = 9 },
        [16353] = { e = 5, s = "s", r = "Mythic raid boss requires high skill and RNG.", d = "Raszageth is the final boss; prepare for high damage and complex mechanics. This drop grants you the title The Storm-Eater.", x = 9 },
        [16354] = { e = 5, s = "c", h = { 138167, 138168, 138169 }, r = "Requires defeating all 9 bosses on Mythic difficulty.", d = "Unlock Mythic Vault of the Incarnates after beating all Heroic bosses. You must clear every Mythic boss listed to complete this set.", x = 9 },
        [16355] = { e = 4, s = "c", h = { 138246, 139046, 139047 }, r = "Requires completing multiple specific raid encounters.", d = "This account-wide achievement requires completing specific raid milestones. Focus on the listed sub-achievements like What Frozen Things Do and Little Friends first.", x = 9 },
        [16363] = { e = 2, s = "c", r = "Quests and storylines are straightforward to finish.", d = "Complete Thaldraszus storylines including Valdrakken and Time Management. These are quest-based achievements that unlock as you progress through the zone.", x = 9 },
        [16364] = { e = 4, s = "c", r = "Requires raiding and specific fishing RNG.", d = "Fish for the Lurking Lunker in lava near Vault of the Incarnates, then pull it out to fight the Primal Council on Normal or higher. Do this early as the fishable mob despawns if you wait too long.", x = 9 },
        [16365] = { e = 4, s = "c", r = "Requires raiding and finding rare nodes.", d = "Hit Dormant Earth nodes with Awakened Earth in Terros's chamber to spawn Energized Earth creatures, then defeat them before killing the boss. This requires specific mechanics and may need a group for efficiency.", x = 9 },
        [16395] = { e = 4, s = "g", r = "Grinding a full set on one class.", d = "Collect any Tier 29 armor piece from Vault of the Incarnates drops on at least one character. Farm raid loot consistently since this is account-wide but needs one class to wear the set.", x = 9 },
        [16398] = { e = 2, s = "c", r = "Optional side quests are short and easy.", d = "Complete all listed Thaldraszus side questlines by talking to NPCs and finishing their chains. Check your quest log regularly as these are optional but time-gated if you skip them.", x = 9 },
        [16399] = { e = 1, s = "s", r = "Simple pet training questline.", d = "Finish the Pet Training Questline with Lubbins to unlock this achievement. Ensure you complete every step of his story before moving on to other pet content.", x = 9 },
        [16400] = { e = 2, s = "g", r = "Exploring a zone is straightforward.", d = "Explore all covered areas in Waking Shores by interacting with points of interest and completing exploration quests. Use a flying mount and check the map for hidden zones regularly.", x = 9 },
        [16401] = { e = 2, s = "c", r = "Optional side quests are short and easy.", d = "Finish all optional Waking Shores storylines listed in the achievement description. These are scattered across the zone so follow quest markers carefully to avoid missing any.", x = 9 },
        [16402] = { e = 3, s = "g", r = "Grinding whelps in a Mythic dungeon.", d = "Defeat 40 Infused Whelps in Melidrussa's chamber on Mythic difficulty before killing her for Dragon Kill Points. This is tedious and requires patience or a group to speed up the kill count.", x = 9 },
        [16404] = { e = 2, s = "c", r = "Simple dungeon mechanics with mushrooms.", d = "Find and destroy three Resilient Mushrooms with Decaystrike near Decatriarch Wratheye in Brackenhide Hollow on Mythic. Use a class that can apply Decaystrike efficiently to save time.", x = 9 },
        [16405] = { e = 2, s = "c", r = "Optional side quests are short and easy.", d = "Complete all Ohn'ahran Plains side questlines by engaging with local NPCs and finishing their chains. These are optional but should be done while exploring the zone to avoid missing content.", x = 9 },
        [16406] = { e = 2, s = "g", r = "Talking to NPCs is quick and easy.", d = "Talk to all listed storytellers in Waking Shores to hear their stories. Visit each location marked on your map or follow quest markers to ensure you don't miss any interactions.", x = 9 },
        [16409] = { e = 1, s = "g", r = "Rescuing ducks is very fast.", d = "Rescue all five Bubbled Ducklings in Restless Wetlands by finding them and completing the rescue steps. They may be hidden or require specific actions so check thoroughly.", x = 9 },
        [16410] = { e = 1, s = "g", r = "Simple item drop collection during a scenario.", d = "Start the Siege on Dragonbane Keep scenario and focus entirely on feeding Beef snacks during stage one. Ensure you have enough snacks prepared beforehand, as this objective is time-gated to the first phase of the fight.", x = 9 },
        [16411] = { e = 2, s = "s", r = "Complete one standard dungeon scenario.", d = "Simply complete the full Siege on Dragonbane Keep scenario to earn this achievement. There are no special requirements beyond finishing the main story content for the keep.", x = 9 },
        [16412] = { e = 3, s = "c", h = { 138396 }, r = "Collecting scattered items; one is a rare drop.", d = "Explore every corner of Dragonbane Keep to locate and collect all djaradin tablets scattered throughout the environment. This is a collection task, so ensure you check hidden areas and interact with every object before leaving.", x = 9 },
        [16419] = { e = 4, s = "g", r = "Requires specific mechanics and RNG on a raid boss.", d = "Run Vault of the Incarnates on Normal or higher difficulty and use Caustic Eruption to free five captives before they die during Sennarth's fight. You must witness their deaths after freeing them, so coordinate with your group to manage the mechanics carefully.", x = 9 },
        [16423] = { e = 3, s = "c", h = { 138450 }, r = "Visit multiple locations; one requires a rare spawn.", d = "Travel to Ohn'ahran Plains while under the effect of Essence of Awakening and present offerings to all listed ancestor spirits. Make sure you maintain the buff active throughout the entire process, as it is required for each offering.", x = 9 },
        [16424] = { e = 3, s = "c", h = { 138509 }, r = "Pet many animals; one is a rare spawn.", d = "Pet every bakar in Ohn'ahran Plains by interacting with them individually until the counter fills. This is a straightforward exploration task, but ensure you do not miss any hidden or hard-to-reach locations in the zone.", x = 9 },
        [16426] = { e = 3, s = "g", r = "Collect items and defeat boss on Mythic.", d = "Enter Halls of Infusion on Mythic difficulty and force the Gulping Goliath to become Hangry by feeding it Curious Swoglets. You must feed it exactly ten swoglets before defeating it, so manage your resources and timing carefully.", x = 9 },
        [16427] = { e = 3, s = "g", r = "Kill specific adds before defeating the boss.", d = "Defeat three Flow Control Units before engaging the Primal Tsunami boss in Halls of Infusion on Mythic difficulty. Clear these adds first to unlock the boss encounter and secure the achievement.", x = 9 },
        [16428] = { e = 3, s = "c", h = { 138495 }, r = "Complete many side quests; one is a rare spawn.", d = "Complete all optional Azure Span storylines listed in the achievement description by following each quest chain thoroughly. These are side content tasks, so ensure you finish every single storyline before moving on to other activities.", x = 9 },
        [16430] = { e = 2, s = "s", r = "Group mechanic requiring everyone to be hit once.", d = "In Brackenhide Hollow on Mythic difficulty, allow every player in your group to be consumed at least once by Treemouth before defeating the boss. Coordinate with your team to ensure no one is left out of the consumption mechanic.", x = 9 },
        [16432] = { e = 4, s = "s", r = "Strict avoidance mechanics on a raid boss.", d = "Defeat Forgemaster Gorek in Neltharus on Mythic difficulty while avoiding all listed damage effects including Forgestorm, Forgefire, and Blazing Eruptions. This requires precise positioning and awareness of raid-wide mechanics throughout the entire fight.", x = 9 },
        [16434] = { e = 4, s = "s", r = "Strict avoidance mechanics on a raid boss.", d = "Run Algeth'ar Academy on Mythic difficulty and defeat Vexamus without any players absorbing Arcane Orbs. Avoid orb collection mechanics entirely during the encounter, as even one absorption will fail the achievement.", x = 9 },
        [16438] = { e = 4, s = "c", r = "Requires precise resource management during a high-difficulty raid boss fight.", d = "Run Neltharus Mythic with a healer who can monitor the book count. Prioritize killing Chargath quickly to minimize fire damage, as exceeding 15 books will fail the achievement permanently.", x = 9 },
        [16440] = { e = 4, s = "c", r = "Complex multi-step mechanic requiring perfect timing and survival.", d = "Start by chilling and searing the egg early in Ruby Life Pools. Keep it alive while tempering and sifting through mechanics, then defeat Kyrakka and Erkhart Stormvein before time runs out.", x = 9 },
        [16441] = { e = 3, s = "c", r = "Requires coordination to activate two specific mechanics simultaneously.", d = "Enter Algeth'ar Academy Mythic and locate both goal locations immediately. Activate them simultaneously before engaging Crawth to ensure the condition is met during the fight.", x = 9 },
        [16442] = { e = 5, s = "c", h = { 138539 }, r = "Extremely tight timing window makes this a high-skill raid encounter.", d = "Hatch all three Primal eggs and defeat their lieutenants within a strict 10-second window. Coordinate with your group to clear enemies instantly after hatching each egg in Vault of the Incarnates.", x = 9 },
        [16443] = { e = 3, s = "g", r = "Requires completing 100 specific cooking tasks in the same zone.", d = "Visit Iskaara's Community Feast and complete cooking tasks repeatedly until you hit 100. This is account-wide, so ensure all characters contribute or use a dedicated cook to speed up progress.", x = 9 },
        [16444] = { e = 2, s = "c", r = "Simple sequence of cooking a legendary item and killing an NPC.", d = "Cook legendary soup at the feast first, then immediately engage Bisquius. Do not leave the area between cooking and fighting, as the quest state may reset if you disconnect.", x = 9 },
        [16445] = { e = 3, s = "g", r = "Requires using a specific ability 12 times on a crystal before the fight.", d = "Use Icy Devastator on crystals in The Azure Vault Mythic until a Very Icy Crystal forms. Defeat Telash Greywing immediately after creation, as the crystal effect is temporary.", x = 9 },
        [16446] = { e = 3, s = "c", r = "Requires finding and photographing many different bird species across zones.", d = "Travel across all Dragon Isles zones to photograph every listed bird species. Use the S.E.L.F.I.E. camera on each target and verify completion in your achievement tracker before moving on.", x = 9 },
        [16447] = { e = 5, s = "c", h = { 138571 }, r = "High RNG element combined with a specific high-difficulty dungeon mechanic.", d = "In The Nokhud Offensive Mythic, strike a single player with five lightning bolts simultaneously. Defeat the Storm Elemental right after this occurs to secure the Raging Tempest kill credit.", x = 9 },
        [16450] = { e = 2, s = "s", r = "Standard raid boss fight with one optional objective to destroy an add.", d = "Destroy the Primal Avatar in Vault of the Incarnates Normal or higher before fighting Kurog Grimtotem. Ensure the avatar is fully destroyed during the encounter to claim the achievement.", x = 9 },
        [16451] = { e = 3, s = "c", h = { 139676 }, r = "Requires gathering rare drops and defeating a specific encounter in a raid.", d = "Gather two Concentrated Storm Essences and defeat the Concentrated Storm before engaging Raszageth. This requires careful timing in Vault of the Incarnates on Normal or higher difficulty.", x = 9 },
        [16453] = { e = 2, s = "s", r = "Simple interaction to mutate a boss before engaging it in a dungeon.", d = "Apply Draconic Tincture to Magmatusk before entering combat in Neltharus Mythic. Mutating him first is essential, as applying it after damage will not count toward the achievement.", x = 9 },
        [16456] = { e = 4, s = "c", h = { 138926 }, r = "Requires specific Mythic dungeon run with three rare weapons.", d = "Defeat Teera and Maruuk on Mythic Nokhud Offensive while holding all three tainted weapons simultaneously. Start by obtaining the weapons from previous dungeon runs before attempting this specific encounter, as missing the hold condition makes it impossible to complete.", x = 9 },
        [16457] = { e = 3, s = "c", r = "Exploration checklist; some points are tedious but doable solo.", d = "Fly across Ohn'ahran Plains to reveal every zone marker and interact with world quests to unlock all locations. This is account-wide and requires full map exploration, so ensure you visit remote areas like Mirewood Fen and Rusza'thar Reach before flying off the continent.", x = 9 },
        [16458] = { e = 3, s = "g", r = "Grind for 8 gales in a raid; manageable with patience.", d = "Collect eight Condensed Gales from Dathea Ascended in Vault of the Incades on Normal or higher difficulty. Use a healer to manage adds while gathering gales, then defeat the boss immediately after collecting all items to secure the achievement.", x = 9 },
        [16460] = { e = 3, s = "c", r = "Exploration checklist; requires flying and finding hidden points.", d = "Explore Azure Span by flying to every unexplored zone marker and completing local world quests. This account-wide achievement requires visiting specific camps like Camp Antonidas and Iskaara, so use a mount with high speed to cover the large area efficiently.", x = 9 },
        [16461] = { e = 4, s = "c", h = { 138649 }, r = "Most bosses are easy, but one requires heavy RNG or luck.", d = "Wait for storm events in Dragon Isles and defeat eight special storm bosses like Infernum or Gaelzion. These spawns are time-gated and account-wide, so check local chat or guides for storm timers before heading out.", x = 9 },
        [16462] = { e = 3, s = "c", r = "Defend camps in a specific order; moderate time investment.", d = "Defend Clan Aylaag by completing three specific escort quests between their camp locations. Follow the quest markers carefully as this account-wide achievement requires defending them from waves of enemies at each stage.", x = 9 },
        [16463] = { e = 2, s = "g", r = "Kill count during storms; very fast once events start.", d = "During storm events in The Waking Shores, defeat air-imbued creatures to earn points toward Thunderstorms. These spawns are temporary and account-wide, so prioritize killing them quickly before the storm ends.", x = 9 },
        [16464] = { e = 3, s = "c", r = "Complete 8 specific pet battle world quests; moderate effort.", d = "Complete eight Pet Battle World Quests on Dragon Isles using a full team of level 25 pets. Accept quests from world NPCs or quest givers, ensuring your pet team is ready before starting each battle to avoid delays.", x = 9 },
        [16465] = { e = 2, s = "g", r = "Kill count during storms; very fast once events start.", d = "During storm events in The Waking Shores, defeat earth-imbued creatures for Sandstorms points. These spawns are time-limited and account-wide, so focus on killing them immediately when the storm appears.", x = 9 },
        [16466] = { e = 2, s = "g", r = "Kill count during storms; very fast once events start.", d = "During storm events in The Waking Shores, defeat fire-imbued creatures to progress Firestorms. These spawns are temporary and account-wide, so prioritize killing them before the storm dissipates.", x = 9 },
        [16467] = { e = 2, s = "g", r = "Kill count during storms; very fast once events start.", d = "During storm events in The Waking Shores, defeat water-imbued creatures for Snowstorms points. These spawns are time-gated and account-wide, so check local timers and kill targets quickly to avoid missing the window.", x = 9 },
        [16468] = { e = 3, s = "c", r = "Simple checklist of other achievements; minimal extra effort.", d = "Complete all four sub-achievements (Thunderstorms, Sandstorms, Firestorms, Snowstorms) in The Waking Shores to unlock Chasing Storms. This is a parent achievement requiring you to finish each elemental storm task first.", x = 9 },
        [16474] = { e = 3, s = "s", r = "Requires specific toy and quest; moderate setup time.", d = "Start the 'World as Toy' quest to unlock snowman building in Azure Span, then craft one immediately before leaving the zone. This is a single-player task that requires specific crafting materials and cannot be completed on other servers.", x = 9 },
        [16475] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in one zone.", d = "Wait for storm events in Ohn'ahran Plains, then hunt creatures marked with elemental air buffs to earn points. Since this is account-wide, any character can contribute, but you must be present during the limited-time weather event.", x = 9 },
        [16476] = { e = 4, s = "c", h = { 138693, 138694, 138695 }, r = "Requires completing four separate storm event grinds.", d = "Complete all four individual storm achievements in Ohn'ahran Plains first, as they are prerequisites for this summary quest. Ensure you defeat the correct elemental creatures during each specific storm type before the event ends.", x = 9 },
        [16477] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in one zone.", d = "During earth-themed storms in Ohn'ahran Plains, focus your attacks on mobs with elemental earth buffs to progress. This achievement is account-wide, so coordinate with friends if you are playing multiple characters.", x = 9 },
        [16478] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in one zone.", d = "Hunt fire-empowered creatures during active firestorm events in Ohn'ahran Plains to complete this objective. Do not miss the event window, as these storms only occur at specific times and locations.", x = 9 },
        [16479] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in one zone.", d = "Defeat water-imbued enemies while a snowstorm is active in Ohn'ahran Plains to earn these points. Remember that this is account-wide, so you can switch characters freely during the event.", x = 9 },
        [16480] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in Azure Span.", d = "Wait for air storms in The Azure Span and defeat the corresponding elemental creatures. This task is account-wide, allowing any character on your account to contribute to the progress.", x = 9 },
        [16481] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in Azure Span.", d = "During earth storms in The Azure Span, target creatures with elemental earth buffs to complete this achievement. Ensure you are in the correct zone when the storm event begins.", x = 9 },
        [16482] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in Azure Span.", d = "Hunt fire-empowered mobs during firestorm events in The Azure Span to make progress on this goal. These events are time-limited, so plan your gameplay around their scheduled appearances.", x = 9 },
        [16483] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in Azure Span.", d = "Defeat water-imbued creatures while a snowstorm is occurring in The Azure Span. This achievement is account-wide, so you can use any character to finish it quickly.", x = 9 },
        [16484] = { e = 4, s = "c", h = { 138706, 138707, 138708 }, r = "Requires completing four separate storm event grinds.", d = "Complete all four individual storm achievements in The Azure Span before turning them in for this summary quest. Each sub-achievement requires defeating specific elemental creatures during their respective storms.", x = 9 },
        [16485] = { e = 3, s = "g", r = "Grinding elemental mobs during storms in Thaldraszus.", d = "Wait for air storms in Thaldraszus and defeat the empowered creatures to earn points. As an account-wide achievement, you can switch characters freely, but timing is critical since storms are limited events.", x = 9 },
        [16486] = { e = 2, s = "g", r = "Grinding elemental mobs during a timed storm event.", d = "Wait for the Sandstorm event in Thaldraszus to spawn earth-empowered creatures. Focus on defeating these specific mobs while the storm is active, as this cannot be done during normal weather.", x = 9 },
        [16487] = { e = 2, s = "g", r = "Grinding elemental mobs during a timed storm event.", d = "Wait for the Firestorm event in Thaldraszus to spawn fire-empowered creatures. Defeat these specific mobs while the storm is active, ensuring you do not miss the limited window.", x = 9 },
        [16488] = { e = 2, s = "g", r = "Grinding elemental mobs during a timed storm event.", d = "Wait for the Snowstorm event in Thaldraszus to spawn water-empowered creatures. Defeat these specific mobs while the storm is active, as this requires the correct elemental condition.", x = 9 },
        [16489] = { e = 3, s = "c", r = "Requires completing four separate storm zone achievements.", d = "Complete the individual Sandstorm, Firestorm, and Snowstorm achievements first to unlock this one. You must also complete Thunderstorms in Thaldraszus before earning points for Chasing Storms.", x = 9 },
        [16490] = { e = 3, s = "c", r = "Requires completing five separate storm zone achievements.", d = "Finish all regional storm achievements in The Waking Shores, Ohn'ahran Plains, and The Azure Span first. Then complete the Thaldraszus storms to unlock this final Chasing Storms achievement.", x = 9 },
        [16492] = { e = 4, s = "c", h = { 138729 }, r = "Depends on completing the difficult Storm Chaser achievement.", d = "Complete all previous storm achievements including Elemental Overload and Storming the Runway first. This is a high-level requirement that depends on finishing the entire storm quest line across all zones.", x = 9 },
        [16493] = { e = 2, s = "c", r = "Requires taming and riding specific tameable mobs.", d = "Tame baby mammoths in The Waking Shores, Ohn'ahran Plains, and The Azure Span first. Ride them to Mammoth-Tamer Tavok in the Emberflow zone to complete this exploration task.", x = 9 },
        [16494] = { e = 3, s = "g", r = "Grinding reputation with a specific NPC to max level.", d = "Travel to the Obsidian Throne and interact with Wrathion repeatedly until you reach maximum friendship. This reputation grind requires consistent interaction and may take significant time depending on your current standing.", x = 9 },
        [16495] = { e = 2, s = "g", r = "Collecting and turning in a set number of keys.", d = "Collect Obsidian Keys from various sources around the Obsidian Citadel and turn in a total of 30 to designated NPCs. Ensure you have enough keys before starting, as they are required for other achievements.", x = 9 },
        [16496] = { e = 3, s = "c", r = "Requires completing four specific encounters at the Citadel.", d = "Locate and complete the four special encounters at the Obsidian Citadel and adjacent lava fields. These are distinct boss fights that must be finished individually to earn this achievement.", x = 9 },
        [16497] = { e = 2, s = "c", r = "Requires turning in keys to all specific NPCs.", d = "Turn in Obsidian Keys to Sabellian, Wrathion, Igys the Believer, and Forgemaster Bazentus to ensure you get credit for all of them. Do not turn keys to only one person if you want to complete this specific task.", x = 9 },
        [16498] = { e = 3, s = "g", r = "Collecting a large quantity of a specific resource.", d = "Gather Elemental Overflow from various sources until you have collected a total of 1000 units. This is a collection goal that requires farming the resource efficiently across the Dragon Isles.", x = 9 },
        [16499] = { e = 2, s = "g", r = "Collecting items is a steady grind.", d = "Farm the Elemental Overflow item from world bosses or vendors until you hit 2500, as this is a cumulative account-wide total. Ensure you do not reset your progress by leaving the game unnecessarily if tracking manually.", x = 9 },
        [16500] = { e = 3, s = "g", r = "Requires more collection time than previous.", d = "This achievement requires collecting 5000 Elemental Overflow items, so continue farming after completing the previous step. It is account-wide and simply extends the collection goal from the prior achievement.", x = 9 },
        [16501] = { e = 4, s = "c", h = { 138771, 138776, 138774 }, r = "Requires specific team and defeating multiple elites.", d = "Gather a team of ten level 25 Aquatic pets to defeat all listed elite trainers in the Dragon Isles. You must complete this specific set before moving on to other pet types.", x = 9 },
        [16502] = { e = 3, s = "g", r = "Collecting a full set takes time.", d = "Equip and collect every armor piece from the Primal Storms set, which drops from world bosses or vendors in the Dragon Isles. This is an account-wide collection that does not require defeating any specific elites.", x = 9 },
        [16503] = { e = 4, s = "c", h = { 138779, 138780, 138781 }, r = "Requires specific team and defeating multiple elites.", d = "Assemble a squad of ten level 25 Beast pets to clear all required elite trainers across the Dragon Isles. Ensure your team composition matches the Beast category exactly for each encounter.", x = 9 },
        [16504] = { e = 4, s = "c", h = { 138797, 138798, 138799 }, r = "Requires specific team and defeating multiple elites.", d = "Use a full team of level 25 Critter pets to defeat every elite trainer listed in the achievement description. This is account-wide and requires visiting multiple locations in the Dragon Isles.", x = 9 },
        [16505] = { e = 4, s = "c", h = { 138806, 138807, 138808 }, r = "Requires specific team and defeating multiple elites.", d = "Build a roster of ten level 25 Dragonkin pets to tackle the specific elite trainers mentioned in the info field. Complete all encounters before switching your team composition for other categories.", x = 9 },
        [16506] = { e = 4, s = "c", h = { 138817, 138818, 138819 }, r = "Requires specific team and defeating multiple elites.", d = "Collect a team of ten level 25 Elemental pets to defeat the designated elite trainers in the Dragon Isles. This is part of the larger pet battling collection and is account-wide.", x = 9 },
        [16507] = { e = 4, s = "c", h = { 138826, 138827, 138828 }, r = "Requires specific team and defeating multiple elites.", d = "Gather ten level 25 Flying pets to clear all required elite trainers in the Dragon Isles. Ensure your team consists entirely of Flying type pets as specified by the achievement requirements.", x = 9 },
        [16508] = { e = 4, s = "c", h = { 138835, 138836, 138837 }, r = "Requires specific team and defeating multiple elites.", d = "Assemble a team of ten level 25 Humanoid pets to defeat every elite trainer listed for this specific category. This is account-wide and requires visiting all relevant trainers in the Dragon Isles.", x = 9 },
        [16509] = { e = 4, s = "c", h = { 138844, 138845, 138846 }, r = "Requires specific team and defeating multiple elites.", d = "Use a full team of ten level 25 Magic pets to defeat all required elite trainers in the Dragon Isles. This achievement is account-wide and follows the same pattern as other pet battling collections.", x = 9 },
        [16510] = { e = 4, s = "c", h = { 138853, 138854, 138855 }, r = "Requires specific team and defeating multiple elites.", d = "Collect a squad of ten level 25 Mechanical pets to clear all listed elite trainers in the Dragon Isles. Ensure your team composition matches the Mechanical category exactly for each encounter.", x = 9 },
        [16511] = { e = 2, s = "c", r = "Defeat 10 elite pets; manageable solo grind.", d = "Defeat the listed elite trainers in Dragon Isles using a team of level 25 Undead pets. Ensure your team is ready before engaging each trainer to avoid wasting attempts.", x = 9 },
        [16512] = { e = 3, s = "c", r = "Requires completing 11 other battler achievements first.", d = "Complete all other 'Battler' achievements first, as this one requires them. This unlocks the Lady Feathersworth pet upon completion.", x = 9 },
        [16517] = { e = 4, s = "s", r = "Mythic dungeon boss requires specific conditions and gear.", d = "Clear Halls of Infusion on Mythic difficulty and defeat Toxic Swogmother after purging water intakes. This is a timed raid achievement that may be missable if not done during the event window.", x = 9 },
        [16518] = { e = 3, s = "g", r = "Exploring covered map areas takes time but is steady.", d = "Travel to every zone in Thaldraszus and explore all covered map areas to reveal them. Fly or run through each region until the map fully lights up.", x = 9 },
        [16519] = { e = 4, s = "g", r = "Catching many rare pets involves RNG and travel.", d = "Catch every listed pet in the Dragon Isles using your Battle Pet trainer. Some pets may be rare drops, so be patient and thorough in each zone.", x = 9 },
        [16531] = { e = 2, s = "g", r = "Fishing for 25 items is repetitive but fast.", d = "Fish with an Iskaaran Harpoon to find Lunkers until you have 25. This is a grind that requires patience as Lunkers are not guaranteed on every catch.", x = 9 },
        [16532] = { e = 1, s = "s", r = "Reputation grinds are trivial once started.", d = "Complete the Sabellian reputation chain by doing daily quests and world events in Thaldraszus. Reach True Friend status to finish this achievement.", x = 9 },
        [16533] = { e = 1, s = "g", r = "Fishing for 10 items is very quick.", d = "Fish with an Iskaaran Harpoon to collect 10 Lunkers before moving to the next tier. This is a straightforward grind requiring only fishing time.", x = 9 },
        [16536] = { e = 1, s = "s", r = "Reputation grinds are trivial once started.", d = "Complete the Wrathion reputation chain by doing daily quests and world events in Thaldraszus. Reach True Friend status to finish this achievement.", x = 9 },
        [16537] = { e = 1, s = "s", r = "Reputation grinds are trivial once started.", d = "Complete the Cobalt Assembly reputation chain by doing daily quests and world events in Thaldraszus. Reach Maximum Power status to finish this achievement.", x = 9 },
        [16539] = { e = 2, s = "s", r = "Reaching Esteemed rank is a short grind.", d = "Complete the Artisan's Consortium reputation chain by doing daily quests and world events in Thaldraszus. Reach Esteemed status to finish this achievement.", x = 9 },
        [16540] = { e = 3, s = "c", r = "Completing 15 hunts involves travel and combat.", d = "Participate in every Grand Hunt event across all Dragon Isles zones. These are time-gated events, so check the calendar regularly to ensure you don't miss any.", x = 9 },
        [16541] = { e = 2, s = "g", r = "Simple repeatable action; very fast per step.", d = "Start any Grand Hunt immediately to progress hunt steps, as this is the primary way to earn points. Complete hunts in any order since there are no time gates or specific locations required.", x = 9 },
        [16542] = { e = 3, s = "c", h = { 139044 }, r = "Requires visiting all zones; one is rare spawn.", d = "Visit every Grand Hunt location and wait for the disgruntled hunter NPC to spawn after completing the main quest. You must find them at all 11 distinct hunt sites, so ensure you clear each zone's current event before moving on.", x = 9 },
        [16543] = { e = 2, s = "c", r = "Collect colors from common spawns in zones.", d = "Collect companion colors by completing specific hunts that reward color items for Bakar and Ohuna. Check your inventory after each hunt to see if a new color was awarded, as some may be rare drops tied to specific events.", x = 9 },
        [16544] = { e = 2, s = "s", r = "One-time event; trivial once started.", d = "Simply complete one full Grand Hunt from start to finish, ensuring you finish the final objective to claim the achievement. There are no special requirements beyond finishing the event's main quest line.", x = 9 },
        [16545] = { e = 3, s = "g", r = "Kill count is high but bosses are common.", d = "Participate in Grand Hunts and defeat bosses to count toward your total of 30 kills. This is account-wide, so playing with friends can speed up progress significantly.", x = 9 },
        [16546] = { e = 2, s = "c", r = "Find two specific fish at a known spot.", d = "Use Ominous Conchs at Large Fish Sighting locations to find Massive Lunkers, which are required for this achievement. Ensure you have the conch item before attempting to fish at these specific spots.", x = 9 },
        [16547] = { e = 2, s = "g", r = "Fishing event; high count but very fast.", d = "Harpoon fish in open water areas and take damage from large creatures to get knocked down repeatedly. You need 50 knockdowns, so stay near dangerous marine life while fishing.", x = 9 },
        [16548] = { e = 1, s = "s", r = "Catch fish with a friend; instant completion.", d = "Invite a friend to your party and catch a fish together to complete this simple social requirement. Any type of fish works, so just ensure you are grouped with another player during the catch.", x = 9 },
        [16550] = { e = 2, s = "g", r = "Restock 100 fish; fast and repetitive.", d = "Restock 100 fish in Tuskarr Fishing Holes by using fishing rods at designated spots. This is a grind that requires patience, but you can speed it up by visiting multiple holes in one session.", x = 9 },
        [16551] = { e = 2, s = "g", r = "Restock 1000 fish; slightly longer but easy.", d = "Continue restocking fish after completing the previous tier to reach 1000 total. Since this builds on the prior achievement, make sure you have already finished the 100-fish goal before starting here.", x = 9 },
        [16552] = { e = 3, s = "g", r = "Restock 5000 fish; takes time but no RNG.", d = "Restock an additional 4000 fish beyond the 1000 mark to reach 5000 total. This is a long-term grind that benefits from daily play, as you will need many sessions to accumulate enough restocks.", x = 9 },
        [16553] = { e = 2, s = "c", r = "Unlock 5 nets; requires visiting specific holes.", d = "Unlock fishing nets at five different Tuskarr Fishing Hole locations by completing their respective quests or challenges. Visit each hole and interact with the NPC to unlock the net, ensuring you do not miss any of the five required spots.", x = 9 },
        [16556] = { e = 2, s = "g", r = "Collecting many food items from vendors or cooking.", d = "Head to Valdrakken and order every dish at The Ruby Feast, including the extra items listed in the info field. Since this is account-wide, ensure your main character orders them all if others cannot join. No time gates exist, but you must finish the feast before leaving the city.", x = 9 },
        [16560] = { e = 3, s = "c", r = "Completing one world quest in each of the four zones.", d = "Travel to each of the four Dragonflight zones and complete one cataloging world quest in every area. Start with The Waking Shores as it is often easiest to access early on. This tracks account-wide so any character can contribute, but you must visit all zones personally.", x = 9 },
        [16561] = { e = 4, s = "g", r = "Finding 100 rare fish requires significant fishing time.", d = "Equip an Iskaari Harpoon and fish for Lunkers until you find 100 of them. Use the Ominous Conch ability to attract them if they are hard to catch. This is account-wide, so coordinate with friends if you need help finding enough spots.", x = 9 },
        [16562] = { e = 4, s = "c", h = { 139228 }, r = "Requires finding massive lunkers and using conchs.", d = "Find Large Fish Sighting locations and use Ominous Conchs to summon Massive Lunkers until you have 10. These sightings appear randomly, so be patient or check community maps for common spawn points. This unlocks the next harpoon upgrade questline.", x = 9 },
        [16563] = { e = 4, s = "c", h = { 139230 }, r = "Requires finding more massive lunkers and using conchs.", d = "Continue fishing at Large Fish Sighting locations to find 25 more Massive Lunkers using Ominous Conchs. The process is identical to the previous achievement, just requiring more time or group effort. Ensure you are in a zone with active fish sightings before starting.", x = 9 },
        [16564] = { e = 2, s = "s", r = "Catch a fish with friends; trivial once grouped.", d = "Gather five friends and catch a single fish together while they stand near you. This requires coordination but no specific location, so organize a quick party in any open area. The achievement tracks account-wide, so anyone in the group counts toward the total.", x = 9 },
        [16565] = { e = 3, s = "s", r = "Catch a fish with many friends; needs coordination.", d = "Expand your previous group to ten players and catch one fish with everyone present. Finding enough people may take time, so consider using Discord or guild channels to assemble a large party. Once caught, the achievement completes instantly for all accounts involved.", x = 9 },
        [16566] = { e = 2, s = "g", r = "Taking one great shot is easy during cataloging.", d = "While cataloging wildlife, aim at creatures to trigger \"Great Shot\" animations until you get one success. This is part of a chain, so do not skip it as it unlocks higher-tier shot achievements. Use ranged abilities or spells that count as attacks for this purpose.", x = 9 },
        [16567] = { e = 3, s = "g", r = "Requires taking many great shots while cataloging.", d = "Repeat the Great Shot mechanic 24 more times to reach 25 total shots while cataloging. This is account-wide, so you can farm quickly with any character in any zone. Avoid interrupting your cataloging session to maintain progress toward the next tier.", x = 9 },
        [16568] = { e = 4, s = "g", r = "Requires taking a large number of great shots.", d = "Take 75 additional Great Shots to reach 100 total, completing this final tier of the chain. Farming is easiest in high-density wildlife zones like Ohn'ahran Plains. Since it is account-wide, you can switch characters if one runs out of targets.", x = 9 },
        [16569] = { e = 2, s = "s", r = "Activating powers is trivial; just need enough active.", d = "Enter the Cobalt Assembly and activate five or more Wild Arcana powers simultaneously to trigger the achievement. This requires specific conditions inside the instance, so ensure all auras are active before engaging content. It is account-wide, so coordinate with friends if needed.", x = 9 },
        [16570] = { e = 3, s = "c", h = { 139268 }, r = "Photographing specific legendary characters is the main task.", d = "Take photographs of legendary characters listed in the info field while cataloging wildlife. These NPCs appear at specific locations or events, so check community guides for their spawn times. The achievement is account-wide, but you must personally photograph each target.", x = 9 },
        [16571] = { e = 2, s = "c", r = "Unlocking all talents is moderate but straightforward.", d = "Unlock every talent in the Expedition Supplies tree to earn this account-wide reputation point. Focus on completing all available talents first, as missing any will prevent completion.", x = 9 },
        [16572] = { e = 3, s = "c", r = "Requires specific NPC interaction and cataloging time.", d = "Take a photograph of one legendary character while cataloging wildlife, starting with Abu'Gar or Chen Stormstout. Ensure you are in the correct zone and have the cataloging ability active before attempting to take the picture.", x = 9 },
        [16573] = { e = 4, s = "c", r = "Needs multiple photos of rare NPCs including Wrathion.", d = "After completing the first legendary photograph, return to take photos of the remaining seven characters for a total of four. This is account-wide, so coordinate with friends if needed to find specific NPCs quickly.", x = 9 },
        [16574] = { e = 2, s = "c", r = "Simple interaction with nearby Dreamguard NPCs.", d = "Target and use the /sleep command next to each of the seven Dreamguards in Ohn'ahran Plains. Do not attack them or move away before sleeping, as this will reset progress on that specific NPC.", x = 9 },
        [16575] = { e = 3, s = "c", r = "Finding scattered glyphs across the Waking Shores zone.", d = "Fly to each listed location in the Waking Shores to find and collect the dragon glyphs. Use your mount or flying ability to reach high points like Skytop Observatory Tower for easier access.", x = 9 },
        [16576] = { e = 3, s = "c", r = "Finding scattered glyphs across Ohn'ahran Plains zone.", d = "Explore Ohn'ahran Plains to locate all dragon glyphs at sites like Nokhudon Hold and Emerald Gardens. Some glyphs may be hidden in hard-to-reach areas, so use your mount's abilities to navigate terrain effectively.", x = 9 },
        [16577] = { e = 3, s = "c", r = "Finding scattered glyphs across the Azure Span zone.", d = "Travel through the Azure Span region to find glyphs at locations such as Cobalt Assembly and Ruins of Karnthar. Be prepared for challenging terrain and potential enemies that may block your path while searching.", x = 9 },
        [16578] = { e = 3, s = "c", r = "Finding scattered glyphs across Thaldraszus zone.", d = "Visit Thaldraszus to collect glyphs from places like Temporal Conflux and Stormshroud Peak. This zone has unique mechanics, so ensure you have the necessary gear and abilities to handle any obstacles.", x = 9 },
        [16580] = { e = 3, s = "c", r = "Completing a mix of optional quests and activities.", d = "Complete all optional quests listed from Camp Antonidas, Iskaara, and Three Falls Lookout. These include fishing tasks and combat objectives, so be ready for various activities depending on the quest giver.", x = 9 },
        [16581] = { e = 2, s = "s", r = "One specific flight path without landing.", d = "Fly directly from the top of Azure Archives to Cobalt Assembly without landing anywhere in between. Plan your route carefully to avoid obstacles or terrain that could force you to land mid-flight.", x = 9 },
        [16583] = { e = 2, s = "s", r = "Complete a training course while disguised.", d = "Disguise yourself as a Nokhud Martial and complete the training course in Nokhudon Hold. Ensure you have the correct disguise active before starting, as failing to maintain it will reset progress.", x = 9 },
        [16584] = { e = 2, s = "c", r = "Fly to specific locations and release kites.", d = "Release ten Hope Kites tethered by locals in the Waking Shores, such as those near Wingrest Embassy and Skytop Observatory. These are scattered across the area, so explore thoroughly to find all locations.", x = 9 },
        [16585] = { e = 2, s = "c", r = "Requires reading and completing ~8 simple zone quests.", d = "Start by completing the specific zone achievements listed in the info field, as this is a prerequisite for the main Loremaster title. Focus on finishing all required quests across Waking Shores, Ohn'ahran Plains, Azure Span, and Thaldraszus before moving on to other content. This achievement is account-wide but requires you to physically visit each zone to unlock its sub-requirements.", x = 9 },
        [16587] = { e = 3, s = "g", r = "Grind for 10 specific climbing world quests.", d = "Locate climbing World Quests in any Dragon Isle zone and complete ten of them to earn this title. These quests often appear randomly, so check your quest log frequently or use a guide to find active climbing locations. There is no time gate, but you must be in the correct zones when these specific world quests spawn.", x = 9 },
        [16588] = { e = 2, s = "g", r = "Collecting supplies during existing quest runs is easy.", d = "While doing climbing World Quests for the Lead Climber achievement, ensure you collect all hidden supplies dropped during those runs. These items are automatically tracked by the game, so simply finishing the climb objectives usually satisfies this requirement. No special actions are needed beyond completing the base climbing quest.", x = 9 },
        [16589] = { e = 3, s = "c", r = "Complete 4 specific PvP world quests in War Mode.", d = "Enable War Mode and complete each of the four listed PvP World Quests once to unlock Malicia's Challenge. These quests only appear while you are in War Mode, so ensure you have activated it before accepting them. The achievement is account-wide, meaning any character on your account can contribute to progress.", x = 9 },
        [16590] = { e = 4, s = "g", r = "Grinding 4 different quests to 20 completions each.", d = "Repeat the same four PvP World Quests twenty times each while in War Mode to finish this lengthy objective. Since these are random world quests, you may need to travel between zones or wait for them to spawn repeatedly. Plan your route efficiently to minimize downtime between completions.", x = 9 },
        [16591] = { e = 3, s = "g", r = "Requires 30 uses of a specific NPC during quests.", d = "Use Rupert the Gentleman Elemental during climbing World Quests thirty times to complete this reputation task. You can summon him directly from his quest giver NPC in each zone without needing to climb manually every time. Keep an eye on your progress tracker if available, or simply estimate based on completed climbs.", x = 9 },
        [16592] = { e = 2, s = "s", r = "Earn honor in one zone is trivial once started.", d = "Enter War Mode and kill enemies in The Waking Shores until you earn 1000 honor points for this specific achievement. Honor gains vary by activity, so engaging in PvP or high-level combat will speed up progress significantly. This is zone-specific, so stay within The Waking Shores boundaries while War Mode is active.", x = 9 },
        [16593] = { e = 2, s = "s", r = "Earn honor in one zone is trivial once started.", d = "Repeat the process from the previous achievement but focus entirely on Thaldraszus to earn 1000 honor there. Ensure you remain in this zone and keep War Mode enabled throughout your grinding session. Like other Tour of Duty achievements, this does not carry over if you leave the zone.", x = 9 },
        [16594] = { e = 2, s = "s", r = "Earn honor in one zone is trivial once started.", d = "Gather 1000 honor specifically within The Azure Span while War Mode is active to unlock this title. Avoid crossing into other zones accidentally, as progress resets or stops outside the target area. Use high-yield activities like PvP arenas or elite kills to maximize honor gain per minute.", x = 9 },
        [16595] = { e = 2, s = "s", r = "Earn honor in one zone is trivial once started.", d = "Kill each of the four listed elites in Ohn'ahran Plains while War Mode is enabled to complete this challenge. These elites may be rare spawns, so check local guides or explore thoroughly if you cannot find them quickly. Once all are defeated, the achievement will pop automatically.", x = 9 },
        [16599] = { e = 3, s = "c", r = "Kill 4 specific elites; moderate RNG or location search.", d = "Find and defeat each of the four named elites across any Dragon Isle zone while War Mode is active. These targets are fixed locations or rare spawns, so consult a map guide if they do not appear immediately. Ensure you stay in War Mode before engaging them to avoid missing out on progress.", x = 9 },
        [16600] = { e = 2, s = "c", r = "One climb per zone is very easy to find.", d = "Complete at least one climbing World Quest in each of the four Dragon Isle zones to earn the Isles Ascender title. You can do this in any order, but make sure to finish a climb objective in every single zone. This is often done early in your Dragonflight journey as part of general exploration.", x = 9 },
        [16601] = { e = 4, s = "c", h = { 139578 }, r = "Requires completing multiple difficult World PvP achievements.", d = "Complete the listed World PvP achievements first, as this parent achievement requires them all. Ensure you finish each sub-achievement before claiming the title reward.", x = 9 },
        [16602] = { e = 4, s = "s", r = "Needs specific Mythic dungeon run with precise healing mechanic.", d = "Run The Nokhud Offensive on Mythic and focus on healing Ohn'ahra to full health before defeating Balakar Khan. This is a single-run requirement that cannot be completed later if missed.", x = 9 },
        [16603] = { e = 3, s = "g", r = "Grinding bounties across all Dragon Isles zones in War Mode.", d = "Enable War Mode and travel to each Dragon Isles zone to loot bounties from slain players. You must visit every zone individually to complete the collection.", x = 9 },
        [16611] = { e = 2, s = "g", r = "Opening crates is quick once in the correct zones.", d = "Open a War Supply Crate in every Dragon Isles zone while in War Mode. Carry extra crates or find them in world drops across all regions.", x = 9 },
        [16612] = { e = 3, s = "g", r = "Requires killing and looting bounties across multiple zones.", d = "Enable War Mode and kill players to loot bounties until you reach ten total. This requires active PvP participation across the entire Dragon Isles.", x = 9 },
        [16613] = { e = 2, s = "g", r = "Opening crates is fast; only needs to be done 10 times.", d = "Open ten War Supply Crates in any Dragon Isles zone while in War Mode. You can open them in one session or spread them out over time.", x = 9 },
        [16614] = { e = 3, s = "g", r = "Collecting 750 tokens requires time and participation in PvP.", d = "Collect Bloody Tokens from PvP activities until you reach 750. This is a cumulative counter that persists across sessions but requires ongoing participation.", x = 9 },
        [16615] = { e = 4, s = "g", r = "Requires unlocking previous achievements first then grinding more tokens.", d = "Gather 3000 Bloody Tokens after completing the previous tier. Continue engaging in PvP to accumulate tokens efficiently without resetting progress.", x = 9 },
        [16616] = { e = 2, s = "g", r = "Collecting 1500 tokens is easy if previous achievements are done.", d = "Collect 1500 Bloody Tokens as part of a chain starting with Bloodstained Bounty. Finish this before attempting the next tier in the sequence.", x = 9 },
        [16620] = { e = 4, s = "s", r = "Requires specific Mythic dungeon run with precise egg delivery timing.", d = "Deliver eight warm ohuna eggs to Ohuna Keeper Taruk in one continuous run of The Nokhud Offensive on Mythic. Do not leave the instance until all eggs are delivered.", x = 9 },
        [16621] = { e = 3, s = "c", r = "Trying various foods across Thaldraszus eateries takes some time.", d = "Visit various eateries in Thaldraszus to sample their specialty food and drinks. Check each vendor's menu to ensure you try every unique item listed.", x = 9 },
        [16622] = { e = 4, s = "s", r = "Requires precise timing and coordination to deliver bait quickly.", d = "Deliver bait to Patient Vaargo within three minutes for a speed challenge. Practice your route beforehand to minimize travel time and maximize efficiency.", x = 9 },
        [16623] = { e = 3, s = "g", r = "Grinding 50 hazards takes a few hours.", d = "Unlock climbing World Quests first, then equip Spiked Cleats to avoid hazards while completing them. This is account-wide and requires patience as you grind through multiple quests.", x = 9 },
        [16624] = { e = 2, s = "s", r = "Unlocking quests is a one-time step.", d = "Complete the introductory Dragonflight story content to unlock the Dragonscale Expedition climbing quests immediately. No special items are needed beyond progressing the main narrative.", x = 9 },
        [16625] = { e = 3, s = "g", r = "Using the buddy system 10 times takes time.", d = "Use the Buddy System feature during any climbing World Quest you complete after unlocking them. Aim for ten uses by queuing up frequently or playing with friends.", x = 9 },
        [16626] = { e = 4, s = "g", r = "Grinding two professions to max is long.", d = "Max out one primary profession in a Dragon Isles category before starting the second to unlock this follow-up achievement. Focus on gathering nodes and crafting recipes specific to the new zones.", x = 9 },
        [16627] = { e = 3, s = "g", r = "Grinding one profession to max takes hours.", d = "Grind a single primary profession to its maximum skill points in a Dragon Isles category. This unlocks the next tier of profession achievements.", x = 9 },
        [16630] = { e = 4, s = "c", h = { 139550, 139551, 139552 }, r = "RNG-heavy drops dominate the effort.", d = "Take photos at every listed vista in Thaldraszus using your S.E.L.F.I.E. camera. Ensure you visit all locations including Tyrhold and Valdrakken's Portal Room.", x = 9 },
        [16631] = { e = 4, s = "g", r = "Grinding cooking skill points takes time.", d = "Cook recipes found in the Dragon Isles zone until you reach 100 skill points. Focus on local ingredients to maximize efficiency.", x = 9 },
        [16632] = { e = 4, s = "g", r = "Grinding fishing skill points takes time.", d = "Fish in the waters of the Dragon Isles until you gain 100 skill points. Visit various zones like Ohn'ahran Plains for diverse fish options.", x = 9 },
        [16634] = { e = 3, s = "c", r = "Taking photos at all vistas is moderate.", d = "Travel to every vista listed in Thaldraszus and take a picture with your camera. Some vistas may require specific viewpoints or lighting conditions.", x = 9 },
        [16638] = { e = 2, s = "s", r = "Realigning ley lines is a quick task.", d = "Interact with each location in the Azure Span to realign its ley lines. This involves visiting specific landmarks like Azure Archives and Rustpine Den.", x = 9 },
        [16676] = { e = 4, s = "c", h = { 139711, 139712, 139713 }, r = "Rare spawns and RNG drops dominate.", d = "Complete ten special encounters in The Waking Shores, such as defeating Gushgut the Beaksinker or collecting Azra's Prized Peony. These often appear as world events.", x = 9 },
        [16677] = { e = 4, s = "c", h = { 139741, 139742, 139743 }, r = "Rare spawns and RNG drops dominate.", d = "Finish ten special encounters in Ohn'ahran Plains by defeating bosses like Sparkspitter Vrak or gathering items from Researcher Sneakwing. Check daily quests for these targets.", x = 9 },
        [16678] = { e = 3, s = "g", r = "Requires finding and defeating 10 specific wild encounters.", d = "Start the 'Adventurer's Journey: The Azure Span' questline and hunt the listed special encounters in that zone. These are often rare spawns or specific events, so check daily objectives for guaranteed chances. Do not miss this content as it may be time-gated by the expansion timeline.", x = 9 },
        [16679] = { e = 3, s = "g", r = "Requires finding and defeating 10 specific wild encounters.", d = "Begin 'Adventurer's Journey: Thaldraszus' and track down the required special encounters across the zone. Many targets are rare spawns or tied to specific world events, requiring patience and frequent checking. Ensure you complete these before the zone becomes obsolete due to time-gating.", x = 9 },
        [16683] = { e = 4, s = "c", h = { 139851, 139853, 139855 }, r = "Profession quests are time-consuming; first three challenges are hardest.", d = "Complete the 'In Tyr's Footsteps' questline by finishing all listed profession challenges in order. These quests often require specific crafted items or high-level profession skills, so level your tradeskills first. This is account-wide, so coordinate with friends if you need help crafting rare components.", x = 9 },
        [16696] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Equip the Renewed Proto-Drake and collect all listed cosmetic armor pieces from vendors or rewards. These unlocks are typically obtained through specific quests or world events in the Dragon Isles. Check your character's appearance menu to verify collection progress before purchasing duplicates.", x = 9 },
        [16697] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Gather the required head feature cosmetics for the Renewed Proto-Drake via quests or vendors. Some pieces may be rare drops or tied to specific achievements, so prioritize high-value targets first. Verify each item is unlocked in your character's appearance menu before moving on.", x = 9 },
        [16698] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Collect tail feature cosmetics for the Renewed Proto-Drake by completing associated quests or purchasing from vendors. These items are often account-wide unlocks available after reaching certain progression milestones. Check your inventory and appearance settings to confirm which pieces you still need.", x = 9 },
        [16699] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Acquire scale and pattern cosmetics for the Renewed Proto-Drake through quests, vendors, or rare drops. Some patterns may require specific achievements or world events, so track these carefully. Ensure you have the base skin equipped before collecting individual cosmetic pieces.", x = 9 },
        [16700] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Gather horn and hair cosmetics for the Renewed Proto-Drake via quests or vendor purchases. These items are often tied to specific achievement milestones or rare drops, so prioritize high-value targets first. Verify your collection progress in the appearance menu before buying duplicates.", x = 9 },
        [16701] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Collect scale and pattern cosmetics for the Windborne Velocidrake through quests or vendors. Some pieces may be rare drops or tied to specific achievements, requiring patience and frequent checking. Ensure you have the base skin equipped before collecting individual cosmetic pieces.", x = 9 },
        [16702] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Gather armor cosmetics for the Windborne Velocidrake via quests or vendor purchases. These items are often account-wide unlocks available after reaching certain progression milestones. Check your inventory and appearance settings to confirm which pieces you still need.", x = 9 },
        [16704] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Collect horn and fur cosmetics for the Windborne Velocidrake through quests or vendors. Some pieces may be rare drops or tied to specific achievements, so prioritize high-value targets first. Verify your collection progress in the appearance menu before buying duplicates.", x = 9 },
        [16705] = { e = 4, s = "g", r = "Requires collecting many rare cosmetic items from drakes.", d = "Gather head feature cosmetics for the Windborne Velocidrake via quests or vendor purchases. These items are often account-wide unlocks available after reaching certain progression milestones. Check your inventory and appearance settings to confirm which pieces you still need.", x = 9 },
        [16706] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Acquire the Windborne Velocidrake mount first, then purchase all listed cosmetic parts from the vendor. Since this is account-wide, ensure you have enough gold and check your inventory before buying to avoid duplicates.", x = 9 },
        [16707] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Obtain the Highland Drake mount and buy every scale and pattern option from the vendor. These items are account-wide, so coordinate with friends if you need specific colors they already own.", x = 9 },
        [16708] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Get the Highland Drake mount and purchase all armor variants available at the vendor. This collection is account-wide, making it easy to complete by trading excess mounts or buying everything yourself.", x = 9 },
        [16710] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Acquire the Highland Drake mount and buy all horn and hair options from the vendor. As an account-wide collection, you can share progress with friends who own the base mount.", x = 9 },
        [16711] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Purchase the Highland Drake mount and collect every back and tail cosmetic from the vendor. Ensure you have sufficient gold, as these are account-wide unlocks that stack across characters.", x = 9 },
        [16712] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Get the Highland Drake mount and buy all head feature options from the vendor. This is an account-wide collection, so focus on acquiring the mount first before spending gold on parts.", x = 9 },
        [16723] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Acquire the Cliffside Wylderdrake mount and purchase all scale and pattern cosmetics from the vendor. Since this is account-wide, you can buy everything at once if you have enough gold.", x = 9 },
        [16724] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Obtain the Cliffside Wylderdrake mount and collect every armor variant from the vendor. This collection is account-wide, allowing you to complete it quickly by purchasing all options immediately.", x = 9 },
        [16725] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Get the Cliffside Wylderdrake mount and buy all horn and mane options from the vendor. As an account-wide achievement, ensure you have enough gold before purchasing all variants.", x = 9 },
        [16726] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Acquire the Cliffside Wylderdrake mount and purchase every back and tail cosmetic available. This is account-wide, so you can complete it efficiently by buying all parts from the vendor.", x = 9 },
        [16727] = { e = 4, s = "c", r = "Requires collecting many specific cosmetic items.", d = "Obtain the Cliffside Wylderdrake mount and collect all head feature options from the vendor. Since this is account-wide, prioritize getting the mount before spending gold on cosmetics.", x = 9 },
        [16729] = { e = 3, s = "g", r = "Grinding critters is tedious but straightforward.", d = "Interact with every critter listed in the info field to show them love. This exploration achievement is account-wide, so you can complete it by visiting all zones and finding each specific creature.", x = 9 },
        [16731] = { e = 3, s = "c", r = "Collecting many pets requires hunting or buying.", d = "Start by collecting pets from Lord Basilton and Lady Feathersworth in the Waking Shores, as they are often missed early on. Ensure you have completed the prerequisite 'Lots of Dragonflight Pet Stuff' achievement before attempting this collection.", x = 10 },
        [16736] = { e = 2, s = "s", r = "One-time mount liberation event.", d = "Head to Brackenhide Hollow and use a Magmamooth mount to liberate the Qalashi magmammoth in one visit. This is account-wide, so coordinate with friends if you need help locating the specific spawn point.", x = 9 },
        [16758] = { e = 2, s = "s", r = "Simple NPC interaction to unlock feature.", d = "Unlock cataloging World Quests by completing the initial Dragonscale Expedition quests in any Dragon Isle zone. Once unlocked, this status persists across all characters on your account.", x = 9 },
        [16760] = { e = 3, s = "g", r = "Requires repeated visits to raise friendship.", d = "Travel to the Obsidian Throne and repeatedly complete Sabellian's friendship quests until you reach maximum standing. Be patient as reputation gains can be slow compared to other activities.", x = 9 },
        [16761] = { e = 2, s = "c", r = "Exploring four zones is moderate work.", d = "Prioritize exploring the Waking Shores first, then move through Ohn'ahran Plains, Azure Span, and finally Thaldraszus. Use the map markers in your Adventure Guide to ensure no region is missed.", x = 9 },
        [16762] = { e = 2, s = "s", r = "Single dungeon run with specific targets.", d = "Visit Brackenhide Hollow once and locate every Captive Tuskarr trapped in a Meat Storage container. Free them all during this single run to avoid resetting the progress.", x = 9 },
        [16764] = { e = 3, s = "c", r = "Collecting PvP gear sets takes time.", d = "Equip any full armor set from Dragonflight PvP Season 1, which includes items from Season 34. You do not need to complete the entire season, just collect one matching set.", x = 9 },
        [16789] = { e = 2, s = "s", r = "Finding hidden money is easy exploration.", d = "Search your Adventure Guide for hidden money drops scattered across the Dragon Isles. These are often found in hard-to-reach areas or require specific exploration actions.", x = 9 },
        [16790] = { e = 2, s = "s", r = "Unlocking secret requires prior step.", d = "This achievement unlocks only after finding the Lucky Penny, so ensure you have discovered that secret first. Look for interactive objects or hidden paths in your Adventure Guide.", x = 9 },
        [16791] = { e = 4, s = "g", r = "Fulfilling 1000 orders is a long grind.", d = "Fulfill crafting orders by accepting jobs from vendors and completing them efficiently. This is account-wide, so use multiple characters to speed up reaching 1000 completions.", x = 9 },
        [16799] = { e = 3, s = "g", r = "Fulfilling 500 orders takes several hours.", d = "Accept personal crafting orders from friends or guild members who need specific items. Focus on high-demand materials to quickly reach the 500 order goal.", x = 9 },
        [16808] = { e = 3, s = "c", r = "Completing multiple renown campaigns.", d = "Complete all listed renown campaigns by reaching level 10 in each respective faction within the Dragon Isles. Check your reputation tab to track which campaigns remain incomplete.", x = 9 },
        [17110] = { e = 4, s = "c", h = { 141925, 141926, 141927 }, r = "Requires defeating three specific raid bosses.", d = "Queue for Vault of the Incarnates and defeat Eranog, The Primal Council, and Dathea. This is account-wide, so any character can contribute to progress.", x = 9 },
        [17111] = { e = 4, s = "c", h = { 141929, 141930, 141931 }, r = "Requires defeating three specific raid bosses.", d = "Defeat Terros, Sennarth, and Kurog Grimtotem in the Vault of the Incarnates caverns. Ensure you are on a Mythic+ or Raid group to access these bosses.", x = 9 },
        [17112] = { e = 4, s = "c", h = { 141933, 141934 }, r = "Requires defeating two specific raid bosses.", d = "Kill Broodkeeper Diurna and Raszageth the Storm-Eater in the deepest Vault of the Incarnates reaches. This requires high-level gear and a coordinated raid group.", x = 9 },
        [17119] = { e = 5, s = "c", h = { 141946 }, r = "Requires Mythic+ Raszageth or heavy RNG feats.", d = "Complete one listed feat, such as Mythic Raszageth or Dragonflight Keystone Hero Season One. Choose the easiest available option to unlock this appearance reward quickly.", x = 9 },
        [17195] = { e = 3, s = "g", r = "Multiple reverse races to complete in one zone.", d = "Finish all reverse races in Waking Shores for Bronze first. You must complete these before attempting Silver or Gold tiers in the same zone.", x = 9 },
        [17196] = { e = 4, s = "g", r = "Requires silver times on all previous races.", d = "Achieve Silver times on all Waking Shores reverse races after finishing Bronze. Practice your routes to shave off seconds for consistent silver placements.", x = 9 },
        [17197] = { e = 5, s = "g", r = "Requires gold times; high skill ceiling.", d = "Reach Gold status on every Waking Shores reverse race. This requires perfect execution and familiarity with the track layouts to beat the time gates.", x = 9 },
        [17198] = { e = 3, s = "g", r = "Multiple reverse races to complete in one zone.", d = "Complete all reverse races in Ohn'ahran Plains starting with Bronze. Follow the chain progression strictly as you cannot unlock higher tiers without finishing the lower ones.", x = 9 },
        [17199] = { e = 4, s = "g", r = "Requires silver times on all previous races.", d = "Obtain Silver times on all Ohn'ahran Plains reverse races after clearing Bronze. Focus on optimizing your speed to meet the stricter time requirements for silver.", x = 9 },
        [17200] = { e = 5, s = "g", r = "Requires gold times; high skill ceiling.", d = "Secure Gold times on every Ohn'ahran Plains reverse race. This is the final tier for this zone and demands precise route knowledge and high skill.", x = 9 },
        [17201] = { e = 3, s = "g", r = "Multiple reverse races to complete in one zone.", d = "Finish all reverse races in Azure Span to unlock Bronze. Start with the simpler tracks like The Azure Span Sprint before moving to complex slaloms.", x = 9 },
        [17202] = { e = 4, s = "g", r = "Requires silver times on all previous races.", d = "Achieve Silver times on all Azure Span reverse races after Bronze completion. Practice your lines repeatedly to ensure you consistently meet the silver time thresholds.", x = 9 },
        [17203] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Unlock the base Azure Span Reverse: Silver first, then grind each track to Gold. This is account-wide so progress carries across characters, but you must finish every single reverse race listed in the info field.", x = 9 },
        [17204] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Start with Bronze on all Thaldraszus tracks before moving to Silver and Gold tiers. Since this is account-wide, one character can unlock the entire set by completing every race in the region.", x = 9 },
        [17205] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "You must have completed the Bronze tier first; then run each track again for Silver medals. There are no time gates here, just repeat the same courses with higher difficulty requirements.", x = 9 },
        [17206] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "After earning Silver on all Thaldraszus tracks, grind them again to achieve Gold times. This is account-wide, so ensure you have a fast flying mount and good control before starting.", x = 9 },
        [17207] = { e = 4, s = "g", r = "Grinding 100 fish with a specific bobber.", d = "Equip the Oversized Bobber from your profession trainer and catch 100 fish of any type. The achievement rewards the bobber itself, so keep fishing until the counter hits 100.", x = 9 },
        [17279] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Begin with Bronze on all Forbidden Reach tracks, then progress to Silver and Gold. These are normal races, meaning you must complete every track listed in the info field without using advanced mechanics.", x = 9 },
        [17280] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Unlock Bronze first, then repeat each race for Silver times. This is account-wide, so one character can finish all three tiers by simply running the tracks multiple times.", x = 9 },
        [17281] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "After earning Silver on all Forbidden Reach normal races, grind them again for Gold. Ensure you have mastered the course layout and timing before attempting the final tier.", x = 9 },
        [17284] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Start with Bronze on all advanced races in the Forbidden Reach. These tracks require specific maneuvers or shortcuts not needed for normal races, so study the course carefully first.", x = 9 },
        [17286] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Complete Bronze advanced races first, then repeat each track for Silver times. This is account-wide, so progress made on one character unlocks the next tier for everyone.", x = 9 },
        [17287] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "After earning Silver on all advanced races, grind them again to achieve Gold times. These are the hardest tracks in the region, so practice your lines before attempting the final tier.", x = 9 },
        [17288] = { e = 3, s = "c", r = "Requires completing multiple timed skyriding races.", d = "Begin with Bronze on all reverse races in the Forbidden Reach. Reverse races often require different strategies than normal ones, so learn the optimal path before rushing for time.", x = 9 },
        [17289] = { e = 3, s = "c", r = "Requires completing multiple specific reverse races.", d = "Unlock the Forbidden Reach Reverse Bronze first, then grind each of the six specific circuits to Silver. Focus on mastering tight turns and avoiding obstacles to secure consistent top-three finishes.", x = 9 },
        [17290] = { e = 3, s = "c", r = "Requires completing multiple specific reverse races.", d = "Once you have all Silver ranks, repeat the same circuits with higher speed requirements for Gold. Practice your lines repeatedly as the time gates are strict and missing a race resets progress.", x = 9 },
        [17294] = { e = 3, s = "c", r = "Requires completing all bronze races in the zone.", d = "Complete every standard race in the Forbidden Reach before attempting any reverse or bronze tiers. This unlocks the necessary prerequisites for the full completionist chain.", x = 9 },
        [17296] = { e = 3, s = "c", r = "Requires completing multiple specific silver races.", d = "After finishing all standard races at Bronze, grind each track to Silver status. Ensure you have unlocked the base Forbidden Reach Racing Completionist before starting this tier.", x = 9 },
        [17298] = { e = 3, s = "c", r = "Requires completing multiple specific gold races.", d = "Finish all tracks at Gold rank to earn the title and complete the main chain. This is the final step after securing Silver across every race type in the zone.", x = 9 },
        [17315] = { e = 3, s = "c", r = "Requires collecting and delivering various quest items.", d = "Collect specific journal entries and stones from various NPCs throughout the Dragon Isles. Deliver these items to Scalecommanders in the Forbidden Reach as they appear in your log.", x = 9 },
        [17321] = { e = 2, s = "c", r = "Requires visiting and honoring multiple NPC elders.", d = "Travel to each of the four Dragon Isle zones to locate and honor the specific Elder NPCs listed. This is account-wide, so ensure you visit all regions including Thaldraszus.", x = 9 },
        [17330] = { e = 3, s = "c", r = "Requires completing all reverse races across four zones.", d = "Start by completing one reverse race in each of the four main Dragon Isles zones to unlock Bronze. You must finish every single zone before moving to Silver.", x = 9 },
        [17331] = { e = 3, s = "c", r = "Requires completing multiple specific silver reverse races.", d = "Grind all four zone reverse races again to achieve Silver status. This requires unlocking the Bronze tier first and maintaining high speeds across varied terrain.", x = 9 },
        [17332] = { e = 3, s = "c", r = "Requires completing multiple specific gold reverse races.", d = "Complete the final Gold tier by finishing every reverse race in all four zones. This grants the Reverse Racer title and concludes the account-wide skyriding chain.", x = 9 },
        [17334] = { e = 2, s = "g", r = "Requires earning the monthly reward twelve times.", d = "Visit the Trading Post each month to claim your special reward until you have done this twelve times total. Be patient as this achievement is time-gated by calendar months.", x = 9 },
        [17335] = { e = 2, s = "s", r = "Requires performing a specific PvP action once.", d = "Enable War Mode and use the Whirling Surge ability to dismount enemy players in PvP zones. You only need one successful takedown to complete this small achievement.", x = 9 },
        [17336] = { e = 2, s = "g", r = "Grinding dismounts in War Mode is easy but requires time.", d = "Enable War Mode and use Whirling Surge to dismount enemies, but note this is a 50-count achievement split into two parts. Start by farming PvP zones like Stormsong Valley or Valdrakken Summit where enemy players are common. Be patient as you need to hit the first milestone before unlocking the larger goal.", x = 9 },
        [17342] = { e = 2, s = "c", h = { 142769, 142770, 166847 }, r = "Kill all Primalist monsters; checklist of specific event spawns.", d = "Join the Primalist Future event in Dragonflight and kill all three specific Primalist monsters listed in the info field. This is account-wide, so coordinate with friends or wait for a group to ensure you can defeat every variant. Check your achievement tracker frequently as missing one monster type will delay completion.", x = 9 },
        [17343] = { e = 2, s = "g", r = "Grinding kills with a buff is easy but requires time.", d = "Participate in the Storm's Fury event and build up Warmth stacks before engaging any Primalist monsters. Aim to reach at least 15 stacks by using specific abilities or items mentioned in the game mechanics. Kill any available Primalist monster while maintaining this stack count to secure the achievement quickly.", x = 9 },
        [17344] = { e = 2, s = "c", h = { 142781, 142782, 142783 }, r = "Collect all seven toys; checklist of specific toy drops.", d = "Purchase all seven Warcraft Rumble Minis from the Toy Box vendor, as they are required for this collection. Ensure you have enough gold and check each toy slot individually since missing even one will prevent completion. This is account-wide, so buy them on any character once you have gathered the necessary currency.", x = 9 },
        [17345] = { e = 3, s = "g", r = "Grinding dismounts to 50 is moderate due to higher count.", d = "Complete the first part of Airborne Tumbler by dismounting 50 enemies in War Mode using Whirling Surge. Once this threshold is reached, the achievement will automatically progress toward the next stage. Focus on high-traffic PvP areas to maximize your dismount count efficiently.", x = 9 },
        [17346] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Locate the Maiev toy in the Toy Box and spend resources to upgrade her appearance once. This simple upgrade unlocks the achievement instantly, so ensure you have the required materials or currency ready before attempting it. It is account-wide, so complete it on any character with access to the toy.", x = 9 },
        [17347] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Find the Sneed toy in the Toy Box and perform a single upgrade to fulfill this collection goal. The process is straightforward, but make sure you do not accidentally sell or remove the toy before upgrading. Complete this quickly as it contributes to your overall Warcraft Rumble Minis progress.", x = 9 },
        [17348] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Upgrade The Night Elf Huntress toy once using resources from the Toy Box vendor. This task is similar to other toy upgrades, so prioritize gathering any needed materials beforehand. Once upgraded, the achievement will register immediately, helping you advance through the full collection set.", x = 9 },
        [17349] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Head to the Toy Box and upgrade the Stonehoof Tauren toy a single time to claim this achievement. Ensure you have sufficient gold or resources available before starting the upgrade process. This is account-wide, so finish it early if you plan to collect all other toys later.", x = 9 },
        [17350] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Locate the Undead Ghoul toy in the Toy Box and complete one upgrade to satisfy this requirement. The upgrade mechanism is consistent across all toys, so follow the same steps used for previous upgrades. Check your achievement list after upgrading to confirm completion before moving on.", x = 9 },
        [17351] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Upgrade the Murloc toy once using materials from the Toy Box vendor to unlock this achievement. This task is quick and does not require complex strategies, making it ideal for filling gaps in your collection. Remember that this is account-wide, so complete it regardless of which character you are playing.", x = 9 },
        [17352] = { e = 2, s = "s", r = "Single upgrade step; partial progress does not matter.", d = "Find the Whelp Egg toy in the Toy Box and perform a single upgrade to finish this collection goal. The process mirrors other toy upgrades, so no special preparation is needed beyond having resources ready. Once upgraded, the achievement will pop automatically, completing your Warcraft Rumble Minis set.", x = 9 },
        [17353] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Obtain the Gold Maiev Toy from Warcraft Rumble to upgrade her twice. This is account-wide and requires no group.", x = 9 },
        [17354] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Get the Gold Sneed Toy from Warcraft Rumble and upgrade him twice. It is account-wide and time-gated by the toy source.", x = 9 },
        [17355] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Acquire the Gold Huntress Toy via Warcraft Rumble to complete two upgrades. This achievement is account-wide.", x = 9 },
        [17356] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Purchase or earn the Gold Tauren Toy from Warcraft Rumble for two upgrades. No group is needed as it is account-wide.", x = 9 },
        [17357] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Obtain the Gold Ghoul Toy from Warcraft Rumble and upgrade the figure twice. This is an account-wide collection task.", x = 9 },
        [17358] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Get the Gold Murloc Toy from Warcraft Rumble to upgrade the model twice. It is account-wide and depends on external toy drops.", x = 9 },
        [17359] = { e = 2, s = "g", r = "Grind for a specific toy; trivial once obtained.", d = "Earn the Gold Whelp Egg Toy from Warcraft Rumble for two upgrades. This is account-wide and requires the specific toy.", x = 9 },
        [17360] = { e = 3, s = "c", r = "Collect 7 items; moderate grind but no single hard criteria.", d = "Collect all seven Silver Warcraft Rumble toys to upgrade each mini once. You must gather these from the external game first.", x = 9 },
        [17361] = { e = 4, s = "c", r = "Collect 7 rare gold toys; long grind with RNG.", d = "Gather all seven Gold Warcraft Rumble toys to upgrade every mini twice. This is account-wide and requires completing the silver tier first.", x = 9 },
        [17366] = { e = 2, s = "s", r = "Complete one specific quest chain; trivial once started.", d = "Complete the Zul'Gurub Restoration quest in Professions to deliver a Hakkari Bijou. This unlocks ancient secrets within Zul'Gurub.", x = 0 },
        [17367] = { e = 4, s = "g", r = "Fish rare drop in Zul'Gurub; long grind with RNG.", d = "Fish for a Gurubashi Cache while inside Zul'Gurub dungeon content. You must be in the zone to catch this specific item.", x = 9 },
        [17397] = { e = 2, s = "g", r = "Unlock doors with keys; trivial once keys are obtained.", d = "Unlock fifty doors in the Zskera Vaults using keys dropped from bosses. This is account-wide and leads to the Door Buster achievement.", x = 9 },
        [17406] = { e = 3, s = "c", h = { 143169, 143172, 143173 }, r = "Requires specific rare RNG drops and multiple world quests.", d = "Start by completing the initial Dragon Isles Pet Battle World Quest to unlock the rest. Gather a full team of level 25 pets before attempting any quest, as this is a hard requirement. This achievement is account-wide and requires finishing eight specific world quests.", x = 9 },
        [17410] = { e = 5, s = "s", r = "Legacy achievement; no longer obtainable by new players.", d = "This legacy achievement tracks crafting contributions made before the Cataclysm expansion. You cannot earn points now; it is purely for historical record on your character sheet. No action is needed to progress or complete this item.", x = 9 },
        [17411] = { e = 3, s = "c", h = { 143220, 143225, 143227 }, r = "Requires finding scattered glyphs; some are rare spawns.", d = "Fly to the Forbidden Reach and locate each of the eight listed dragon glyphs scattered across the zone. Use Dragonriding to efficiently travel between drop points, as some are in hard-to-reach areas. Once all glyphs are collected, the achievement will automatically complete.", x = 9 },
        [17412] = { e = 5, s = "s", r = "Legacy achievement; no longer obtainable by new players.", d = "Like the Zandalar achievement, this tracks pre-Cataclysm crafting efforts against Naxxramas. It is a legacy item that cannot be earned in the current game state. Simply view your character sheet to see it listed as completed historically.", x = 9 },
        [17413] = { e = 3, s = "g", r = "Requires unlocking 150 doors via keys; steady grind.", d = "Travel to the Zskera Vaults and use keys to unlock doors, aiming for the 150 required count. This can be done solo or with a group, but ensure you have enough keys to maximize efficiency. The achievement is account-wide and grants the Key Master title upon completion.", x = 9 },
        [17427] = { e = 3, s = "g", r = "Requires learning language through repeated interaction.", d = "Read any Winterpelt language text in-game until your skill reaches 100 to unlock chatting in that tongue. This is an account-wide achievement, so progress on one character benefits all others. Focus on finding Furbolg NPCs or quest items that provide language experience.", x = 9 },
        [17483] = { e = 2, s = "c", h = { 143516, 143519, 143518 }, r = "Most races are easy; some advanced or specific routes add difficulty.", d = "Complete every race in Zaralek Cavern at the Bronze difficulty level first, as higher tiers require finishing lower ones. Some races involve specific mechanics like avoiding hazards or collecting crystals, so study each track carefully. This is account-wide and serves as a prerequisite for Silver.", x = 9 },
        [17484] = { e = 2, s = "c", h = { 143523, 143526, 143525 }, r = "Most races are easy; some require specific conditions or RNG.", d = "After unlocking Bronze, repeat all Zaralek Cavern races to earn Silver medals instead of Bronze. You must complete the normal versions of each race without errors to qualify for the higher tier. This step is required before attempting Gold or Advanced tracks.", x = 9 },
        [17485] = { e = 2, s = "c", h = { 143529, 143533, 143530 }, r = "Most races are easy; some require specific conditions or RNG.", d = "Push your skills further by completing all Zaralek Cavern races at the Gold difficulty level. This requires precise execution and often multiple attempts per track due to stricter time limits or obstacle avoidance. Ensure you have unlocked Silver first, as it is a strict prerequisite for Gold.", x = 9 },
        [17486] = { e = 2, s = "c", h = { 143537, 143540, 143539 }, r = "Most races are easy; some require specific conditions or RNG.", d = "Begin tackling the Advanced races in Zaralek Cavern at Bronze difficulty, which feature more complex paths and mechanics. These tracks are harder than normal ones, so practice each route thoroughly before aiming for higher medals. This tier must be completed before moving to Silver or Gold.", x = 9 },
        [17487] = { e = 2, s = "c", h = { 143544, 143547, 143546 }, r = "Most races are easy; some require specific conditions or RNG.", d = "Once Bronze Advanced is done, repeat all advanced races to earn Silver medals on the difficult tracks. Pay close attention to new obstacles and timing requirements that make these races challenging. Completing this tier unlocks the path to Gold and rewards a special drake customization.", x = 9 },
        [17488] = { e = 2, s = "c", h = { 143550, 143554, 143553 }, r = "Most races are easy; some require specific conditions or RNG.", d = "Finally, master all Advanced races in Zaralek Cavern by earning Gold medals on each track. This is the highest difficulty tier, demanding perfect runs with no mistakes or time penalties. Finish Silver first as it is required, then focus on flawless execution to complete this final challenge.", x = 9 },
        [17489] = { e = 3, s = "c", r = "Requires completing 7 separate reverse races.", d = "Complete all seven reverse races in Zaralek Cavern to earn Bronze. This is a prerequisite for the Silver and Gold tiers, so start immediately after unlocking the zone.", x = 9 },
        [17490] = { e = 3, s = "c", r = "Requires completing 7 separate silver races.", d = "Repeat the same seven reverse races but aim for faster times to unlock Silver. You must have completed the Bronze tier first before attempting this.", x = 9 },
        [17491] = { e = 3, s = "c", r = "Requires completing 7 separate gold races.", d = "Push your speed limits further on all seven reverse tracks to achieve Gold status. This requires completing the Silver tier beforehand and is account-wide.", x = 9 },
        [17492] = { e = 3, s = "c", r = "Requires completing all standard and advanced races.", d = "Finish every standard race, advanced variant, and all reverse races in Zaralek Cavern. Start with the basic races first, then tackle the harder variants for Bronze completion.", x = 9 },
        [17493] = { e = 3, s = "c", r = "Requires completing all silver standard/advanced races.", d = "Repeat all races from the previous tier to earn Silver status. Ensure you have unlocked the Bronze completionist achievement before starting this step.", x = 9 },
        [17494] = { e = 3, s = "c", r = "Requires completing all gold standard/advanced races.", d = "Master every race in Zaralek Cavern including reverse tracks to reach Gold and claim your title. This is the final tier requiring prior Silver completion.", x = 9 },
        [17496] = { e = 5, s = "s", r = "Legacy achievement; likely no longer obtainable.", d = "This legacy achievement is already complete for all current players as it refers to pre-Cataclysm content you cannot access now.", x = 9 },
        [17497] = { e = 5, s = "s", r = "Legacy achievement; likely no longer obtainable.", d = "Like other legacy profession titles, this is automatically granted to existing accounts and requires no action from you today.", x = 9 },
        [17498] = { e = 5, s = "s", r = "Legacy achievement; likely no longer obtainable.", d = "This legacy achievement is already completed for all current players as it refers to pre-Cataclysm content you cannot access now.", x = 9 },
        [17499] = { e = 5, s = "s", r = "Legacy achievement; likely no longer obtainable.", d = "This legacy achievement is already completed for all current players as it refers to pre-Cataclysm content you cannot access now.", x = 9 },
        [17506] = { e = 3, s = "s", r = "Requires dying to a specific boss once.", d = "Find Fyrakk in Zaralek Cavern and intentionally let him kill you. This is a simple interaction with no specific location or timing restrictions.", x = 9 },
        [17509] = { e = 4, s = "c", r = "Time-limited vault exploration with multiple doors.", d = "Pick one Zskera Vault and unlock every door inside it within seven days. Start immediately upon entering the vault to avoid missing the time limit.", x = 9 },
        [17524] = { e = 3, s = "c", r = "Requires finding and defeating 10 random bosses.", d = "Start by completing the Adventurer's Journey questline to unlock special encounters. Focus on defeating bosses like Vraken and Gahz'raxes, noting that Pyrachniss requires ten kills. This account-wide achievement is time-gated until you finish the initial storm events.", x = 9 },
        [17525] = { e = 4, s = "c", r = "Requires completing all remaining bosses after the first.", d = "Unlock this after finishing the previous tier by completing all remaining special encounters. Ensure you have access to every boss listed in the info field, including the extra Pyrachniss spawns. No group is strictly required if you can solo these fights.", x = 9 },
        [17526] = { e = 3, s = "g", r = "Requires finding and opening multiple hidden chests.", d = "Locate and interact with unique treasure containers scattered across the post-storm zone. Check major landmarks and quest hubs for hidden coffers and stashes. This is account-wide, so coordinate with friends to cover different areas quickly.", x = 9 },
        [17527] = { e = 3, s = "g", r = "Requires opening 20 small treasure chests.", d = "Open small treasures found in chests or on the ground throughout the region. Aim for twenty opens first, then continue grinding toward one hundred for the next tier. These drops are common but require active exploration of every corner.", x = 9 },
        [17528] = { e = 4, s = "g", r = "Requires opening 100 small treasure chests total.", d = "Continue opening small treasures until you reach the one hundred count required. Since this builds on the previous achievement, ensure you have already unlocked the Scavenger title. Keep an eye on your total count as it is account-wide.", x = 9 },
        [17529] = { e = 3, s = "g", r = "Requires finding and opening 10 large guarded chests.", d = "Seek out ten Forbidden Hoards, which are larger and more guarded than small treasures. These often require defeating nearby enemies or solving a minor puzzle to access. The reward includes a decorative chest for your collection.", x = 9 },
        [17530] = { e = 3, s = "g", r = "Requires collecting 10 specific lore books.", d = "Gather all listed lore books by checking quest givers, reading world text, and exploring dungeons. Some books may be rare drops or found in specific locations like the War Creche. Read carefully as some titles have unique descriptions.", x = 9 },
        [17531] = { e = 3, s = "g", r = "Requires solving 10 Sealed Scroll puzzles.", d = "Use Sealed Scroll maps to locate hidden treasures within the Forbidden Reach. Complete ten scrolls first before progressing to the next tier. These maps can be obtained from vendors or quest rewards and are account-wide.", x = 9 },
        [17532] = { e = 4, s = "g", r = "Requires solving 50 Sealed Scroll puzzles total.", d = "Finish the remaining forty-five Sealed Scroll maps after completing the initial ten. Treat this as a long-term goal requiring thorough map exploration. Ensure you check every scroll location to avoid missing any rare treasures.", x = 9 },
        [17534] = { e = 3, s = "c", r = "Requires visiting and revealing 6 specific zones.", d = "Explore all major zones in the post-storm Forbidden Reach to reveal covered areas on the world map. Visit key locations like Stormsunder Crater and Dragonskull Island systematically. This achievement unlocks once every region is fully explored.", x = 9 },
        [17540] = { e = 2, s = "s", r = "Requires defeating one boss per element once.", d = "Defeat a Primal Storm of each element (Air, Earth, Fire, Water) inside Froststone Vault. These events are time-gated and may require specific weather conditions or boss phases. Coordinate with your group to handle the elemental mechanics efficiently.", x = 9 },
        [17541] = { e = 2, s = "s", r = "Requires completing four specific pet battle quests.", d = "Complete the Vortex, Tremblor, Wildfire, and Flow quests in Pet Battles to unlock this title. Each quest involves defeating a specific elemental boss using pet battles. Ensure your pets are ready for these unique encounters before starting.", x = 9 },
        [17543] = { e = 4, s = "c", h = { 143909, 143910, 143911 }, r = "Requires completing many Forbidden Reach sub-achievements.", d = "Start by completing the main Forbidden Reach storyline to unlock all sub-achievements, as some require specific zones or bosses. Do not rush; ensure you collect every item and complete every quest before moving on, since missing content is permanent.", x = 9 },
        [17546] = { e = 2, s = "s", r = "Straightforward storyline completion in one zone.", d = "Begin the Old Hatreds questline in Ohn'ahran Plains immediately after unlocking the zone, as it follows a strict narrative sequence. Finish all related quests without interruption to avoid missing story beats that are required for completion.", x = 9 },
        [17560] = { e = 3, s = "c", h = { 144203, 144204, 144205 }, r = "Needs finding stones across all four Dragon Isles.", d = "Visit each of the four Dragon Isles and complete their respective Ancient Stones achievements first, as they often unlock other content. Ensure you explore every corner of each zone thoroughly, since some stones require specific interactions or rare spawns.", x = 9 },
        [17561] = { e = 2, s = "c", h = { 144208, 144209, 144210 }, r = "Requires finding stones in Waking Shores zone.", d = "Focus on Waking Shores by completing its unique sub-achievements like 'So Close, So Far' which may involve precise positioning or rare events. Check the achievement tracker regularly to ensure no small tasks are overlooked during your exploration.", x = 9 },
        [17562] = { e = 2, s = "c", h = { 144214, 144215, 144216 }, r = "Requires finding stones in Ohn'ahran Plains zone.", d = "In Ohn'ahran Plains, prioritize quests and activities that unlock the Ancient Stones sub-achievements like 'The Gnoll Wars.' Be patient with world events, as some stones only appear after specific conditions are met.", x = 9 },
        [17563] = { e = 2, s = "c", h = { 144220, 144221, 144222 }, r = "Requires finding stones in Azure Span zone.", d = "Azure Span requires completing its unique set of achievements such as 'Im'bunata's Blessing' which may involve rare drops or timed events. Explore the zone thoroughly and keep an eye on dynamic world events to unlock all necessary components.", x = 9 },
        [17564] = { e = 2, s = "c", h = { 144226, 144227, 144228 }, r = "Requires finding stones in Thaldraszus zone.", d = "Thaldraszus involves completing achievements like 'Mighty Ducks' which often require specific mounts or interactions with NPCs. Ensure you visit every district and complete all related quests before moving to the next zone.", x = 9 },
        [17567] = { e = 2, s = "c", h = { 144234, 144235, 144236 }, r = "Requires finding stones in Zaralek Cavern zone.", d = "Zaralek Cavern's Ancient Stones are tied to its unique world events and boss encounters, so engage with them actively. Some achievements may require rare drops or specific actions during raids, so be prepared for these challenges.", x = 9 },
        [17712] = { e = 3, s = "c", h = { 144355, 144356, 144357 }, r = "Requires skyriding all Kalimdor zones to Bronze.", d = "Start the Kalimdor Bronze skyriding achievement by flying over all zones in order, as some routes unlock progressively. Use a fast mount and plan your route efficiently to minimize time spent on each zone.", x = 9 },
        [17713] = { e = 3, s = "c", h = { 144377, 144378, 144379 }, r = "Requires skyriding all Kalimdor zones to Silver.", d = "After completing Kalimdor Bronze, focus on obtaining silver ratings by optimizing your flight paths and avoiding unnecessary detours. Some zones may require specific maneuvers or timing to achieve the higher rating.", x = 9 },
        [17714] = { e = 3, s = "c", h = { 144394, 144395, 144396 }, r = "Requires skyriding all Kalimdor zones to Gold.", d = "Gold in Kalimdor demands precise flying skills and route optimization, as you must maintain high speed throughout each zone. Practice your routes beforehand to ensure you can consistently meet the gold requirements.", x = 9 },
        [17715] = { e = 4, s = "c", h = { 144411, 144412, 144413 }, r = "Advanced races are harder and require specific conditions.", d = "Advanced skyriding achievements require mastering complex flight paths and maneuvers across all zones. These are more challenging and may need repeated attempts, so be patient and persistent in your efforts.", x = 9 },
        [17716] = { e = 3, s = "c", r = "Requires flying through many zones to get silver.", d = "Start with Felwood Flyover and work through each zone's advanced race to unlock silver. Ensure you have a mount capable of high-speed traversal in every region listed. No time gates exist, but completing all zones takes significant real-world time.", x = 9 },
        [17717] = { e = 4, s = "c", r = "Gold tier requires completing all bronze/silver first.", d = "Unlock the silver tier first, then repeat every advanced race focusing on speed and efficiency for gold. Use the same route optimization strategies as the previous tier to maximize your score. This is purely a grind requiring patience across all Kalimdor zones.", x = 9 },
        [17718] = { e = 3, s = "c", r = "Reverse races require specific paths in many zones.", d = "Begin with Felwood Flyover Reverse and complete every reverse race in order to unlock bronze. These races often require different pathing than standard runs, so study the optimal routes beforehand. There are no time gates, but missing a zone early makes it harder to track progress.", x = 9 },
        [17719] = { e = 4, s = "c", r = "Silver tier requires completing all bronze reverse first.", d = "Finish all reverse races at bronze speed first, then optimize your paths for silver medals. The difficulty increases slightly with each tier, so practice your timing in easier zones before tackling the hardest ones. No content is missable if you complete the prerequisite tiers correctly.", x = 9 },
        [17720] = { e = 5, s = "c", r = "Gold tier is the final step of a massive chain.", d = "Complete the silver tier entirely before attempting gold, as it is a strict requirement. Focus on perfect runs in every zone to secure the necessary points for the final tier. This achievement demands extensive grinding and precise route knowledge across all of Kalimdor.", x = 9 },
        [17721] = { e = 5, s = "c", r = "Completionist requires finishing all bronze tiers first.", d = "Finish the bronze tiers for Advanced, Reverse, and standard races before moving to silver. You must complete every single race type in every zone listed in the info field. There are no time gates, but the sheer volume of content makes this a long-term goal.", x = 9 },
        [17722] = { e = 4, s = "c", r = "Silver tier requires completing all bronze races first.", d = "Unlock the silver completionist tier by finishing all bronze races first. Once silver is done, repeat the process to aim for gold, which grants you the Kalimdor Racer title. This achievement requires account-wide progress and cannot be rushed without grinding every zone multiple times.", x = 9 },
        [17723] = { e = 5, s = "c", r = "Gold tier is the final step of the entire chain.", d = "Complete the silver completionist tier as a prerequisite before attempting gold. Gold requires flawless runs across all zones, so master your routes in bronze and silver first. Successfully finishing this grants you the exclusive Kalimdor Racer title permanently.", x = 9 },
        [17734] = { e = 2, s = "s", r = "Requires completing a specific quest storyline.", d = "Finish the Reconcilable Dissidents questline to unlock this achievement and earn The Reconciler title. This involves completing specific Rebel Dragonkin storyline quests, so check your quest log for any remaining steps. No time gates apply, but ensure you have access to Dragonflight zones.", x = 9 },
        [17735] = { e = 3, s = "g", r = "Grinding to douse 100 fires takes time.", d = "Travel to Suffusion Camps in the Dragon Isles and extinguish 100 fires using appropriate abilities or items. This is a straightforward grind with no time gates, but it requires visiting multiple locations across different zones. Keep track of your count to avoid wasting time on already doused fires.", x = 9 },
        [17736] = { e = 2, s = "g", r = "Feeding 50 rats is a moderate collection task.", d = "Cook Recipe Rat's greatest recipe and feed 50 rats scattered across Azeroth to earn the Roland pet. Visit major cities and outdoor areas where rats spawn, as they are not always in one location. This is a simple grind with no time gates, but ensure you have the correct recipe unlocked first.", x = 9 },
        [17737] = { e = 2, s = "c", r = "Requires visiting specific zones during an event.", d = "Visit each of the six Dragon Isles zones listed in the info field to honor their flames. Complete the specific objective in The Waking Shores, Ohn'ahran Plains, and other zones to finish this world event achievement. No time gates exist, but you must physically travel to each zone to complete the task.", x = 9 },
        [17738] = { e = 2, s = "c", r = "Visit all six zones and interact with the flame mechanic.", d = "Visit all Dragon Isles zones to honor the flames, as this is account-wide and requires no specific quest chain. Ensure you have completed zone-specific storylines first, since some flame honors are gated behind plot progression.", x = 9 },
        [17739] = { e = 4, s = "c", h = { 144649 }, r = "Mostly story quests; Inherited Sin requires repeated dungeon runs.", d = "Start with the 'Embers of Neltharion' campaign credit in Zaralek Cavern, then complete the listed quests in order. This is a major account-wide achievement, so coordinate with friends if any quests require group play or specific class abilities.", x = 9 },
        [17741] = { e = 3, s = "c", r = "Feed four snails until one wins the race.", d = "Go to Glimmerogg in Zaralek Cavern and toss treats to each snail until they win their race. This is account-wide, so one player can complete it for everyone, but be patient as snails may take time to finish.", x = 9 },
        [17765] = { e = 4, s = "s", r = "Craft or buy a full set of Tier 30 armor.", d = "Equip a Tier 30 armor set from Aberrus on at least one character to unlock this appearance achievement. Since it is account-wide, any class can wear the set once you have access to the raid content.", x = 9 },
        [17766] = { e = 3, s = "g", r = "Travel and interact with points of interest across the zone.", d = "Travel to Zaralek Cavern and explore every zone by interacting with world objects and completing discovery quests. This is account-wide, so one player can finish it for the entire account if they visit all areas.", x = 9 },
        [17773] = { e = 2, s = "s", r = "Complete a specific quest chain to restore bonds.", d = "Help Kalecgos restore Blue Dragonflight bonds by completing the 'Blue Dawn' questline. This is account-wide, so focus on the main story quests that involve the Blue Dragons in Zaralek Cavern.", x = 9 },
        [17779] = { e = 3, s = "s", r = "Unlock the mount via a specific campaign milestone.", d = "Unlock the Winding Slitherdrake by completing the associated campaign credit and any prerequisite quests. This is account-wide, so ensure you have access to the relevant content before attempting to unlock it.", x = 9 },
        [17781] = { e = 2, s = "g", r = "Collect coins from public objectives in the zone.", d = "Earn 200 Unearthed Fragrant Coins by completing public objectives in Zaralek Cavern. These coins drop from world events and can be collected by any player, making this account-wide and flexible.", x = 9 },
        [17782] = { e = 3, s = "c", r = "Participate in five separate daycare races.", d = "Participate in every Little Scales Daycare Whelp Race to unlock the 'Daycare Derby' achievement. This is account-wide, so one player can complete all races for everyone once they are available.", x = 9 },
        [17783] = { e = 4, s = "g", r = "Complete ten special encounters; Magtembo is the hardest.", d = "Complete 10 special encounters in Zaralek Cavern, such as defeating bosses or solving puzzles. This is account-wide, so focus on the most accessible encounters first to build progress quickly.", x = 9 },
        [17785] = { e = 5, s = "c", h = { 144888 }, r = "Requires completing all sub-achievements including hard grinds.", d = "Complete all Zaralek Cavern achievements listed, including exploration and quest milestones. This is a major account-wide achievement, so prioritize finishing smaller sub-achievements like 'Explore Zaralek Cavern' first.", x = 9 },
        [17786] = { e = 3, s = "g", r = "Find ten hidden chests scattered throughout the zone.", d = "Discover hidden treasures in Zaralek Cavern by exploring caves, chests, and secret areas. This is account-wide, so one player can find all treasures for the entire account if they thoroughly explore the zone.", x = 9 },
        [17830] = { e = 2, s = "g", r = "Grinding flightstones takes time but is straightforward.", d = "Grind Flightstones daily via World Quests or dungeons until you hit 2000. Note that this is a cumulative total, so do not reset your progress by clearing the same content repeatedly without checking your current count.", x = 9 },
        [17832] = { e = 2, s = "g", r = "Sniffing five items is quick exploration with a companion.", d = "Start by finding any cave with a niffen companion and sniffing out five special items immediately. You can complete this solo, but be patient as specific items may only appear in certain caves or at specific times.", x = 9 },
        [17833] = { e = 3, s = "g", r = "Finding all nine items requires more extensive cave exploration.", d = "Unlock the previous achievement first, then systematically visit every cave to sniff out all nine possible special items. This is account-wide and requires no group, but ensure you have a niffen companion active before starting.", x = 9 },
        [17841] = { e = 2, s = "s", r = "Buying boulders and getting a hat is a short quest chain.", d = "Travel to Zaralek Cavern and locate Ponzo to bring Barter Boulders for his hat. Complete the barter quest chain quickly as it involves specific NPC interactions that may not persist if you leave the area too long.", x = 9 },
        [17851] = { e = 3, s = "g", r = "Earning 1000 honor involves running dungeons or world quests.", d = "Enable War Mode and farm honor in Zaralek Cavern through World Quests or dungeons. Since this is account-wide, coordinate with friends to maximize efficiency while ensuring your character remains active in combat.", x = 9 },
        [17852] = { e = 4, s = "c", r = "Killing players with six specific elements requires RNG and PvP.", d = "Equip Elemental Infused Rock Snails and kill players while infused with each of the six elements. This requires PvP engagement, so be cautious not to die prematurely or fail to trigger the necessary elemental effects.", x = 9 },
        [17877] = { e = 4, s = "c", r = "Raid mechanics with a specific item requirement add complexity.", d = "Defeat Scalecommander Sarkareth on Normal difficulty or higher after cultivating a Mysterious Lump of Flesh. Throw the lump into the Emptiness Between Stars during the fight to complete the achievement.", x = 9 },
        [17878] = { e = 2, s = "s", r = "Eating one fish and surviving is a simple interaction.", d = "Find and consume a Forbidden Flounder in Zaralek Cavern while ensuring you survive the encounter. This is a solo task, so avoid taking unnecessary damage or being interrupted by other players.", x = 9 },
        [17879] = { e = 3, s = "g", r = "Catching nine specific pets involves hunting in one zone.", d = "Catch all nine Zaralek Cavern battle pets by exploring caves and completing World Quests. Some pets may require specific conditions or locations, so check your collection regularly to ensure you have not missed any.", x = 9 },
        [17880] = { e = 3, s = "c", r = "Completing four specific pet battle world quests takes time.", d = "Complete four Pet Battle World Quests in Zaralek Cavern using a full team of level 25 pets. Ensure your pets are fully leveled and equipped before starting, as lower-level teams will fail the requirement.", x = 9 },
        [17881] = { e = 3, s = "c", r = "Defeating trainers with specific aquatic pets requires farming.", d = "Defeat pet trainers in Zaralek Cavern using only aquatic pets at level 25. This requires careful preparation, as you must switch to an aquatic team specifically for this achievement.", x = 9 },
        [17882] = { e = 3, s = "c", r = "Defeating trainers with specific beast pets requires farming.", d = "Repeat the process with a team of beast-type pets at level 25 to defeat the same trainers. Ensure your pet roster includes enough beasts to complete the requirement without mixing other types.", x = 9 },
        [17883] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Gather five level 25 Critter pets and defeat the four Zaralek Cavern trainers. This is account-wide but requires you to complete all other pet type achievements first.", x = 9 },
        [17890] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Use a team of five level 25 Dragonkin pets to challenge the Zaralek Cavern trainers. Ensure your collection includes these specific types before starting.", x = 9 },
        [17904] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Defeat all Zaralek Cavern trainers using a lineup of five level 25 Elemental pets. You must have the required pet types collected beforehand.", x = 9 },
        [17905] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Challenge the Zaralek Cavern trainers with a team of five level 25 Flying pets. This achievement is account-wide and requires specific pet collection.", x = 9 },
        [17915] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Use five level 25 Humanoid pets to defeat the Zaralek Cavern trainers. Verify your pet collection meets the type requirement before entering combat.", x = 9 },
        [17916] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Defeat the Zaralek Cavern trainers with a team of five level 25 Magic pets. This is account-wide and depends on having the correct pets.", x = 9 },
        [17917] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Challenge the Zaralek Cavern trainers using a lineup of five level 25 Mechanical pets. Ensure you have collected these specific pet types first.", x = 9 },
        [17918] = { e = 2, s = "g", r = "Requires specific pet types; grind is moderate.", d = "Use a team of five level 25 Undead pets to defeat the Zaralek Cavern trainers. This achievement is account-wide and requires specific pets.", x = 9 },
        [17934] = { e = 3, s = "c", r = "Depends on completing other pet battle grinds.", d = "Complete all individual pet type achievements listed in the info field to unlock this bonus point achievement. It rewards the Gerald pet upon completion.", x = 9 },
        [17977] = { e = 2, s = "g", r = "Grinding currency is easy with daily quests.", d = "Earn 5000 Flightstones by completing daily quests and other activities that grant currency. This is a prerequisite for the next tier in the chain.", x = 9 },
        [17978] = { e = 3, s = "g", r = "Requires more currency; takes a few days.", d = "Accumulate 20000 Flightstones total to complete this legacy achievement. You must finish the previous tier first as it is part of a sequence.", x = 9 },
        [18100] = { e = 4, s = "c", h = { 145322 }, r = "Many encounters; one boss requires heavy RNG.", d = "Equip the Clacking Claw and defeat every special encounter listed in the info field within Zaralek Cavern. This includes multiple bosses and requires the toy to be equipped.", x = 9 },
        [18149] = { e = 4, s = "c", r = "Requires specific mechanics and high-level raid gear.", d = "Defeat Neltharion on Normal or higher while smashing all four specific objects during the fight. Ensure your group carries the Expired Experiment, Stack of Scrolls, Ebon Candle, and Ebon Anvil to trigger the shatter event.", x = 9 },
        [18150] = { e = 3, s = "g", r = "Collecting multiple glyphs across the zone takes time.", d = "Fly Zaralek Cavern to locate and collect all eight required dragon glyphs scattered across the zone. This is account-wide, so coordinate with friends if you cannot find them alone.", x = 9 },
        [18151] = { e = 4, s = "c", r = "Mythic difficulty adds significant complexity and gear requirements.", d = "Queue for Kazzara on Mythic difficulty and defeat her to claim the points. No special mechanics are needed beyond standard Mythic requirements.", x = 9 },
        [18152] = { e = 4, s = "c", r = "Mythic difficulty requires high-level raid preparation.", d = "Run The Amalgamation Chamber on Mythic difficulty until you see the boss die. This is a straightforward kill requirement with no hidden steps.", x = 9 },
        [18153] = { e = 4, s = "c", r = "Mythic difficulty demands top-tier gear and coordination.", d = "Defeat The Forgotten Experiments on Mythic difficulty. Focus on the mechanics specific to this encounter to ensure a clean wipe count.", x = 9 },
        [18154] = { e = 4, s = "c", r = "Mythic difficulty requires extensive raid preparation.", d = "Clear Assault of the Zaqali on Mythic difficulty. Coordinate with your group to handle the adds and mechanics efficiently for the kill credit.", x = 9 },
        [18155] = { e = 4, s = "c", r = "Mythic difficulty necessitates high-level gear and skill.", d = "Defeat Rashok the Elder on Mythic difficulty. Ensure you survive his phases to secure the boss kill required for this achievement.", x = 9 },
        [18156] = { e = 4, s = "c", r = "Mythic difficulty requires substantial raid preparation.", d = "Kill The Vigilant Steward Zskarn on Mythic difficulty. Watch for his specific mechanics and maintain group coordination throughout the encounter.", x = 9 },
        [18157] = { e = 4, s = "c", r = "Mythic difficulty demands advanced gear and tactics.", d = "Defeat Magmorax on Mythic difficulty. Manage the magma mechanics carefully to avoid wipes while securing the kill.", x = 9 },
        [18158] = { e = 4, s = "c", r = "Mythic difficulty requires high-level raid readiness.", d = "Run Echo of Neltharion on Mythic difficulty. This is the final boss of the raid, so ensure you have completed previous bosses first.", x = 9 },
        [18159] = { e = 4, s = "c", r = "Mythic difficulty plus title reward increases overall effort.", d = "Defeat Scalecommander Sarkareth on Mythic difficulty to earn both points and the Heir to the Void title. This is the last boss of the raid.", x = 9 },
        [18160] = { e = 3, s = "c", r = "Any difficulty lowers the bar compared to Mythic versions.", d = "Defeat every boss in Aberrus on any difficulty to unlock this main raid achievement. Start with Normal mode bosses before attempting Mythic ones for other achievements.", x = 9 },
        [18161] = { e = 4, s = "c", h = { 145520 }, r = "Heroic raid bosses require a full group and significant time.", d = "Start this account-wide achievement by clearing all bosses on Heroic difficulty in Aberrus. Ensure you have access to the raid before attempting any Mythic content later.", x = 9 },
        [18162] = { e = 5, s = "c", h = { 145530 }, r = "Mythic raid bosses are the hardest content in the game.", d = "Complete the Heroic version first as a strict requirement before unlocking Mythic runs. This account-wide goal demands high-level coordination and gear from your group.", x = 9 },
        [18163] = { e = 4, s = "c", h = { 145534 }, r = "Requires Heroic completion first; specific bosses are tough.", d = "Focus on the experimental laboratories wing to defeat Kazzara, The Amalgamation Chamber, and The Forgotten Experiments. These are specific sub-goals within the main raid progression.", x = 9 },
        [18164] = { e = 4, s = "c", h = { 145539 }, r = "Requires Heroic completion first; specific bosses are tough.", d = "Clear the wing containing Assault of the Zaqali, Rashok, and Zskarn to complete this section. Treat this as a prerequisite for reaching deeper raid zones.", x = 9 },
        [18165] = { e = 4, s = "c", h = { 145542 }, r = "Requires Heroic completion first; specific bosses are tough.", d = "Proceed to the depths to defeat Magmorax and Echo of Neltharion. This segment follows naturally after clearing the upper wings of Aberrus.", x = 9 },
        [18167] = { e = 4, s = "c", h = { 145545 }, r = "Requires Heroic completion first; specific boss is tough.", d = "Descend to the final zone to confront Scalecommander Sarkareth. This is the ultimate raid boss and requires completing all previous wing achievements first.", x = 9 },
        [18168] = { e = 3, s = "g", r = "Mechanic-based achievement requiring a full raid group.", d = "Use Umbral Detonation, Fiery Meteor, and Blistering Twilight on a Forgotten Specimen Tank to create a Shadowflame Remnant. Defeat this remnant on Normal or higher difficulty.", x = 9 },
        [18172] = { e = 4, s = "g", r = "Requires feeding 20 items to a raid boss.", d = "Feed Magmorax twenty Spicy Lava Snails during the fight before defeating him. This is a missable mechanic if you do not manage the snail count correctly.", x = 9 },
        [18173] = { e = 3, s = "c", r = "Mechanic-based achievement requiring specific abilities used.", d = "Defeat The Forgotten Experiments while hitting Nutraal three times with Rending Charge, Volatile Spew, and Deep Breath. Coordinate your damage abilities carefully during the encounter.", x = 9 },
        [18174] = { e = 3, s = "s", r = "Single event defeat is moderate effort.", d = "Participate in the Researchers Under Fire: Titan Lockdown event to defeat the Animated Contaminant. This is an exploration achievement tied to a specific world event.", x = 9 },
        [18193] = { e = 4, s = "c", h = { 146255 }, r = "Requires a raid member to carry an item during the fight.", d = "Defeat Zskarn while a raid member carries the Delicate Experimental Egg. Ensure someone picks up the egg early in the fight to secure this account-wide goal.", x = 9 },
        [18199] = { e = 3, s = "c", r = "Event-based achievement requiring specific event completion.", d = "Join the Researchers Under Fire: Zaqali Ruin Investigation event to defeat Ritualmaster Skarna and the Elder Magma Worm. This is a timed world event in the Dragon Isles.", x = 9 },
        [18200] = { e = 4, s = "c", h = { 145734, 145735 }, r = "Requires completing multiple event-specific sub-achievements.", d = "Start the Researchers Under Fire event in Zaralek Cavern and complete all sub-achievements to earn the Field Researcher title. Ensure you do this during the active event window as it is time-gated content.", x = 9 },
        [18201] = { e = 4, s = "s", r = "Defeating a specific boss during a timed event.", d = "Locate and defeat the Contaminated Titan Watcher during the Titan Lockdown event portion of Researchers Under Fire. This boss fight is part of the larger event and requires you to be present when it spawns.", x = 9 },
        [18202] = { e = 3, s = "g", r = "Destroying 100 boulders is a moderate collection task.", d = "Destroy boulders scattered throughout Zaralek Cavern during the Titan Lockdown event; aim for 100 total. These are often found near the main event zones and can be destroyed quickly with melee attacks.", x = 9 },
        [18203] = { e = 3, s = "g", r = "Gathering 50 ore samples is a standard collection.", d = "Gather Curious Ore Samples from the ground during the Titan Lockdown event and deliver them to the quest giver. Check your inventory frequently as these samples are a key objective for this specific timeframe.", x = 9 },
        [18204] = { e = 4, s = "s", r = "Defeating a specific boss during an event.", d = "Defeat the Monstrous Magmaclaw Snapper during the Zaqali Ruin Investigation event in Zaralek Cavern. This boss appears specifically for this achievement and is only available while the event is active.", x = 9 },
        [18205] = { e = 3, s = "g", r = "Collecting 25 shards is a moderate collection task.", d = "Collect Djaradin Pillar Shards from ruins during the Zaqali Ruin Investigation event and return them to the NPC. You need to gather at least 25 shards, so explore thoroughly before the event ends.", x = 9 },
        [18206] = { e = 3, s = "g", r = "Delivering 25 stones is a moderate collection task.", d = "Find Resilient Stones near the Zaqali altar during the Ruin Investigation event and restore them to complete the puzzle. These stones are scattered around the main ruin area and must be placed correctly.", x = 9 },
        [18207] = { e = 4, s = "g", r = "Killing 500 enemies during events is a long grind.", d = "Kill any hostile creature in Zaralek Cavern during either Researchers Under Fire event to reach 500 kills. Since this is account-wide and cumulative, you can grind these mobs efficiently with a group.", x = 9 },
        [18208] = { e = 3, s = "g", r = "Stomping 100 specific mobs is a moderate collection.", d = "Stomp on Magmaclaw Snappers specifically during the Zaqali Ruin Investigation event; do not count kills from other events. These snappers spawn in specific zones within the ruin area.", x = 9 },
        [18209] = { e = 4, s = "s", r = "Defeating a specific boss during an event.", d = "Defeat Captain Reykal, the Sundered Flame leader, during either Researchers Under Fire event. This boss spawns in designated areas and is a high-priority target for this achievement.", x = 9 },
        [18228] = { e = 3, s = "c", h = { 146097, 146098, 146099 }, r = "Requires hitting specific rare mobs in a raid.", d = "Use Cave Pebbles to hit specific creatures like Ember Mouse or Siege Mammoth in Aberrus on Normal or higher. You must complete this before leaving the raid instance as it tracks your interactions within the dungeon.", x = 9 },
        [18229] = { e = 5, s = "s", r = "Requires shattering plating before defeating a raid boss.", d = "Shatter your own Hellsteel Plating before defeating Kazzara, the Hellforged in Aberrus on Normal or higher. Ensure you have broken your plating early in the raid to avoid missing this unique condition.", x = 9 },
        [18230] = { e = 4, s = "c", h = { 146177 }, r = "Requires specific raid mechanics and RNG on Normal+.", d = "Defeat Rashok on Normal or higher after hitting the Lost Lunker with Searing Slam five times. Ensure you have the new criteria tree unlocked first, as this is a specific mechanic requirement.", x = 9 },
        [18249] = { e = 3, s = "c", r = "Collecting a PvP set takes time but is straightforward.", d = "Collect any full armor set from Dragonflight PvP Season 2 to earn this appearance achievement. This is account-wide, so progress made on any character counts toward the total.", x = 9 },
        [18251] = { e = 4, s = "c", h = { 145906 }, r = "Includes the difficult 'Whac-A-Swog' raid mechanic.", d = "Complete all listed sub-achievements in Aberrus to unlock Glory of the Aberrus Raider. Start with easier tasks like Cosplate and work up to the raid boss mechanics for Whac-A-Swog.", x = 9 },
        [18255] = { e = 3, s = "c", r = "Many small objectives in one zone; grind but doable.", d = "Complete every Sniffenseek dig achievement alongside a niffen companion before moving on. This is a prerequisite for Can You Dig It?, so finish all listed sub-tasks first.", x = 9 },
        [18257] = { e = 3, s = "g", r = "Grinding 50 digs is steady work with a companion.", d = "Finish 50 total digs with a niffen companion, but only after completing Proof of Myrrit. Check your progress frequently as this chains directly into the next meta achievement.", x = 9 },
        [18271] = { e = 4, s = "c", h = { 145979 }, r = "Ouroboros ritual involves complex mechanics and RNG.", d = "Acquire Salverun by finishing the Ouroboros Tablet ritual. This is a specific quest line in Zaralek Cavern, so ensure you have completed all prior steps for the tablet.", x = 9 },
        [18284] = { e = 3, s = "c", r = "Meta achievement requiring completion of other medium tasks.", d = "Unlock A Niffen's Best Buddy by completing Sniffen Sage, Can You Dig It?, and He'sSss All Mine. These are meta achievements that require their respective sub-goals to be finished first.", x = 9 },
        [18360] = { e = 2, s = "g", r = "Visiting many locations is easy but repetitive.", d = "Visit every Candy Bucket location across the Dragon Isles during Hallow's End. This is time-gated to the event window, so prioritize these zones while the buckets are active.", x = 9 },
        [18361] = { e = 4, s = "c", r = "Requires finding and interacting with rare critters.", d = "Use /love on critters in Zaralek Cavern to complete To All the Squirrels Burrowed Beneath. Avoid sunlight when interacting with them, as they hide from light sources.", x = 9 },
        [18368] = { e = 2, s = "s", r = "Simple ritual once the feature is unlocked.", d = "Perform a ritual with Eva's Journal to unlock Memory of Scholomance. Ensure you have the Naxxramas Restoration profession unlocked first, as this is a prerequisite.", x = 0 },
        [18372] = { e = 2, s = "s", r = "Straightforward unlock for Naxxramas features.", d = "Empower your Argent Dawn Commission to unlock Wards of the Dread Citadel. This requires unlocking the Naxxramas feature in the game world before attempting the empowerment.", x = 0 },
        [18383] = { e = 2, s = "c", r = "Feeding five pets is quick and easy.", d = "Care for five newly hatched whelplings at Little Scales Daycare to earn Hey Nanny Nanny. Focus on feeding and tending to them until they are fully grown and cared for.", x = 9 },
        [18384] = { e = 2, s = "c", r = "Quest chain with minor grinding.", d = "Complete all listed daycare quests sequentially to care for whelplings and earn the Axel pet. This is account-wide, so finish it early before changing characters or expanding your collection.", x = 9 },
        [18471] = { e = 5, s = "g", r = "Massive grind to Exalted on all factions.", d = "Grind daily reputation sources across all factions until you hit 110 Exalted totals. Since this is account-wide, maximize efficiency by focusing on high-yield activities first.", x = 9 },
        [18539] = { e = 5, s = "c", h = { 147086 }, r = "Mythic raid boss after heavy rift grinding.", d = "Run Mythic Dawn of the Infinite to close 18 Time Rifts before defeating Tyr, the Infinite Keeper. Note that this content may be time-gated or require specific group coordination.", x = 9 },
        [18554] = { e = 4, s = "g", r = "Requires completing many Time Rift flavor quests.", d = "Collect every flavor item dropped during Time Rift runs in Dawn of the Infinite on Mythic. This achievement is account-wide and rewards a toy upon completion.", x = 9 },
        [18556] = { e = 4, s = "c", h = { 147167 }, r = "Mythic boss fight after portal activation.", d = "Activate three Chaotic Time portals in Dawn of the Infinite on Mythic before defeating Manifested Timeways. Ensure you have a capable group for this high-difficulty encounter.", x = 9 },
        [18557] = { e = 3, s = "s", r = "Crafting set by players is straightforward.", d = "Craft or acquire any Sapphiron's Bane crafted set piece for one armor type to unlock the appearance. This is account-wide, so coordinate with crafters if needed.", x = 9 },
        [18558] = { e = 2, s = "c", r = "Classic dungeon bosses are easy to kill.", d = "Defeat Darkmaster Gandling and Kirtonos the Herald in Scholomance Classic mode. Complete this quickly as Classic content may become inaccessible over time.", x = 0 },
        [18559] = { e = 3, s = "g", r = "Opening 50 boxes takes some time.", d = "Open fifty Box of Rocks items to release elementals and claim the Tiny Box of Tiny Rocks toy. This is account-wide, so open boxes across all characters if necessary.", x = 9 },
        [18566] = { e = 4, s = "c", r = "Completing all Bronze races is a long task.", d = "Complete all Bronze Skyriding races in Eastern Kingdoms before progressing to Silver. These are account-wide, so finish them early while you have a suitable mount.", x = 9 },
        [18567] = { e = 4, s = "g", r = "Silver races require significant flying skill.", d = "Earn Silver medals on all normal Eastern Kingdoms Skyriding races after unlocking Bronze. This requires completing the previous tier first and is account-wide.", x = 9 },
        [18568] = { e = 4, s = "g", r = "Gold races are harder than Silver.", d = "Achieve Gold status on every normal Eastern Kingdoms Skyriding race after securing Silver. Plan your runs carefully as this tier demands consistent high performance.", x = 9 },
        [18569] = { e = 4, s = "c", r = "Advanced Bronze races require high skill.", d = "Finish all Advanced Bronze Skyriding races in Eastern Kingdoms to progress further. These advanced routes are more challenging and require precise execution.", x = 9 },
        [18570] = { e = 3, s = "c", r = "Grind many races; requires unlocking first.", d = "Start by unlocking the Eastern Kingdoms Advanced race category. Complete each individual track to earn silver before moving to gold, as you must finish all tracks in one tier before advancing.", x = 9 },
        [18571] = { e = 4, s = "c", r = "Grind harder races after silver completion.", d = "You cannot start this until you have earned silver on every single advanced track. Once unlocked, complete the remaining tracks for gold; note that progress carries across characters but requires finishing all locations first.", x = 9 },
        [18572] = { e = 3, s = "c", r = "Grind reverse races; unlockable via chain.", d = "Begin by completing every reverse race in Bronze to unlock Silver. These races often have different mechanics or paths than standard ones, so study the course layout before attempting higher tiers.", x = 9 },
        [18573] = { e = 4, s = "c", r = "Grind harder reverse races after bronze.", d = "Finish all reverse races in Bronze first, then progress through Silver and finally Gold. Ensure you do not skip any tracks, as missing one will prevent you from unlocking the next tier for that specific race type.", x = 9 },
        [18574] = { e = 4, s = "c", r = "Grind hardest reverse races; account-wide.", d = "This requires completing all reverse races in Bronze and Silver first. Once unlocked, finish every remaining track for Gold; remember this is account-wide so one character can unlock it for the whole realm.", x = 9 },
        [18579] = { e = 3, s = "g", r = "Donate to taverns across Dragon Isles.", d = "Visit any tavern on the Dragon Isles during Brewfest to donate to Bar Tab Barrels. This achievement is account-wide, so ensure you are in a festival zone and have enough time before the event ends.", x = 9 },
        [18589] = { e = 4, s = "s", r = "Specific Mythic dungeon mechanic required.", d = "Defeat Chronikar on Mythic difficulty in Dawn of the Infinite after she shatters an Infused Hourglass. You must wait for her to use Eon Shatter and destroy the hourglass before engaging her for credit.", x = 9 },
        [18612] = { e = 4, s = "s", r = "Specific Mythic dungeon mechanic required.", d = "Allow a lost slime to hop onto your back in Dawn of the Infinite on Mythic difficulty. Then get hit by Blight Reclamation from Blight of Galakrond to reunite the slime and earn credit.", x = 9 },
        [18615] = { e = 3, s = "g", r = "Grind friendship rank with Soridormi.", d = "Interact with Soridormi frequently during Time Rifts on the Dragon Isles to increase your friendship rank. You must reach the maximum \"Legend of the Multiverse\" rank, which is tracked account-wide.", x = 9 },
        [18616] = { e = 4, s = "c", r = "Collect many pages from Naxxramas.", d = "Run Naxxramas and collect all pages of Omarion's Notes found inside. Return them to Omarion in your profession window; this is account-wide so one character can complete it for everyone.", x = 9 },
        [18635] = { e = 3, s = "g", r = "Complete a Time Rift; repeatable.", d = "Enter any active Time Rift on the Dragon Isles and complete the associated tasks. Once finished, you will unlock this achievement regardless of which rift or zone you used.", x = 9 },
        [18636] = { e = 4, s = "g", r = "Grind 100 tasks within Time Rifts.", d = "Complete Time Rifts while doing their specific tasks for Soridormi. You need to finish exactly 100 tasks across all rifts; track your count carefully as this is account-wide and time-gated by the rift events.", x = 9 },
        [18637] = { e = 4, s = "g", r = "Requires defeating 7 bosses in a timed event with RNG.", d = "Start by running Time Rifts repeatedly to defeat every Fractured Causality boss listed in the info field. Ensure you clear all specific reality variants like Azmerloth and The Warlands, as missing one prevents completion. This is account-wide so coordinate with friends if needed for difficult encounters.", x = 9 },
        [18638] = { e = 4, s = "g", r = "Requires collecting specific pets from Time Rifts bosses.", d = "Run Time Rifts until you collect every pet mentioned in the info list, such as Gill'dan and Killbot 9000. Keep an eye on your collection after each run since alternate timeway pets are rare drops. Complete this account-wide goal by grinding different realities to maximize drop chances.", x = 9 },
        [18639] = { e = 5, s = "g", r = "Requires earning massive amount of essence in one run.", d = "Focus on earning Temporal Essence in a single Time Rift run without stopping or changing zones. You need exactly 7500 essence, so prioritize high-yield activities within the rift event. This account-wide achievement requires careful resource management during one continuous session.", x = 9 },
        [18640] = { e = 3, s = "g", r = "Requires finding and using multiple specific weapons.", d = "Equip and fire each weapon listed in the info field during Time Rift encounters to register hits. Test every gun type like the Bomb Lobber and Railgun by engaging enemies with them. Ensure you use these specific weapons found in rifts rather than standard gear.", x = 9 },
        [18641] = { e = 2, s = "s", r = "Simple interaction with NPC after obtaining pet.", d = "Complete Time Rift content to obtain Soridormi's fluffy fur pet mentioned in the info field. Once acquired, interact with Soridormi to fulfill her request and claim the achievement. This account-wide goal depends on securing the specific pet reward from rift activities.", x = 9 },
        [18642] = { e = 3, s = "c", h = { 147653 }, r = "Requires finding specific daily secret items.", d = "Participate in the Secrets of Azeroth event and solve all Day 1 secrets listed in the info field. Return the Ceremonial Spear to complete the first day's objectives quickly. This account-wide achievement unlocks a title, so prioritize early event completion.", x = 9 },
        [18643] = { e = 3, s = "g", r = "Requires locating multiple hidden satchels via rumors.", d = "Search for Buried Satchels using community rumors until you find five as specified in the info field. Solve each rumor clue carefully since missing one might require restarting the search chain. This account-wide step leads directly into the next achievement in the sequence.", x = 9 },
        [18644] = { e = 3, s = "g", r = "Requires locating more hidden satchels than previous.", d = "Continue solving community rumors to locate ten Buried Satchels total, building on your previous progress. The info field confirms you need exactly ten satchels for this specific milestone. Claim the Tobias pet reward once the count reaches the required number.", x = 9 },
        [18645] = { e = 2, s = "s", r = "Simple interaction to unlock secret finding toys.", d = "Unlock all secret finding toys listed in the info field, including the Tricked-Out Thinking Cap and Torch of Pyrreth. Explore various locations to discover these hidden items before they become unavailable. This account-wide achievement grants a new appearance upon completion.", x = 9 },
        [18646] = { e = 4, s = "c", h = { 147663 }, r = "Requires solving complex meta-secrets and puzzles.", d = "Solve every secret listed in the Secrets of Azeroth Full Meta info field, such as A Preservationist and Shifting Sands. Review each clue carefully since missing one secret prevents unlocking the final reward. This extensive goal requires thorough exploration across multiple event areas.", x = 9 },
        [18703] = { e = 2, s = "s", r = "Standard dungeon boss defeat with no special conditions.", d = "Defeat Iridikron boss in Dawn of the Infinite dungeon as specified in the info field. Prepare your group for this encounter since it requires coordinated effort to secure the kill. This account-wide achievement marks the completion of Galakrond's Fall storyline.", x = 9 },
        [18704] = { e = 2, s = "s", r = "Standard dungeon boss defeat with no special conditions.", d = "Focus on defeating Chrono-Lord Deios boss in Dawn of the Infinite dungeon per the info requirements. Coordinate with your raid group to handle this challenging encounter effectively. Completing this goal unlocks the Murozond's Rise achievement for your account.", x = 9 },
        [18706] = { e = 5, s = "s", r = "Mythic dungeon run with no deaths and specific artifact restoration.", d = "Start this Mythic+ run with a high-level group to clear Dawn of the Infinite quickly. Focus on restoring all four artifacts without letting anyone die, as any death resets progress. This is time-gated and requires perfect execution from start to finish.", x = 9 },
        [18719] = { e = 4, s = "g", r = "Grinding 75 skill points across 12 professions in Cataclysm.", d = "Grind professions in the Cataclysm category until each reaches exactly 75 skill points. Since this is account-wide, coordinate with friends or use a macro to track progress across characters. Avoid over-leveling beyond 75 for these specific achievements.", x = 9 },
        [18720] = { e = 4, s = "g", r = "Grinding 300 skill points across 12 professions in Classic content.", d = "Grind professions in the Classic category until each reaches exactly 300 skill points. This is account-wide and requires significant time investment across multiple characters. Do not stop at lower levels; you must hit the specific 300 threshold for every primary profession.", x = 9 },
        [18721] = { e = 4, s = "g", r = "Grinding 75 skill points across 12 professions in Outland content.", d = "Grind professions in the Outland category until each reaches exactly 75 skill points. This is account-wide and requires visiting zones like Hellfire Peninsula or The Burning Crusade dungeons. Ensure you do not exceed 75 points for these specific achievements.", x = 9 },
        [18722] = { e = 4, s = "g", r = "Grinding 75 skill points across 12 professions in Northrend content.", d = "Grind professions in the Northrend category until each reaches exactly 75 skill points. Visit zones like Borean Tundra or Grizzly Hills to gather materials. This is account-wide and requires reaching the specific 75 point threshold for every primary profession.", x = 9 },
        [18723] = { e = 4, s = "g", r = "Requires extensive crafting to master three specific alchemy specializations.", d = "Specialize in Alchemy by mastering Elixir, Potion, or Transmutation skills. Use the appropriate specialization talent to gain credit. This is account-wide and requires reaching the maximum skill level for your chosen mastery type.", x = 9 },
        [18724] = { e = 3, s = "g", r = "Crafting and using Vantus Runes five times in the raid.", d = "Participate in Vantus Rune encounters five times to empower yourself with the rune. You must be present during the encounter to gain credit. This is account-wide and requires finding groups willing to run these specific Mythic+ dungeons.", x = 9 },
        [18725] = { e = 4, s = "g", r = "Requires crafting four specific books via a complex ritual system.", d = "Read all four books in the Rituals of the New Moon series crafted by scribes. These are rare drops from specific encounters or vendors. This is account-wide and requires collecting each unique book to complete the set.", x = 9 },
        [18726] = { e = 3, s = "g", r = "Crafting 100 potions is a steady but lengthy profession grind.", d = "Craft potions using Alchemy until you have created exactly 100 of them. Track your count carefully as this is a cumulative total. This is account-wide and requires consistent grinding in zones with high potion material availability.", x = 9 },
        [18727] = { e = 4, s = "s", r = "Requires cycling through all prism colors in a full raid run.", d = "Use the Convergent Prism toy to cycle through all its color variations within a single raid instance. Ensure you change colors before leaving the raid to count for this achievement. This is account-wide and requires finding a group willing to run a full raid with the toy equipped.", x = 9 },
        [18728] = { e = 3, s = "g", r = "Grinding two professions to 300 Classic skill points is lengthy.", d = "Obtain 300 skill points in two different Classic category professions. This requires reaching the high-level threshold for multiple specializations. This is account-wide and often needs coordination to grind efficiently across characters.", x = 9 },
        [18729] = { e = 3, s = "g", r = "Grinding two professions to 75 Outland skill points is lengthy.", d = "Obtain 75 skill points in two different Outland category professions. Visit zones like Hellfire Peninsula or Zangarmarsh for materials. This is account-wide and requires reaching the specific 75 point threshold for each chosen profession.", x = 9 },
        [18730] = { e = 2, s = "s", r = "Specialize in one engineering specialization.", d = "Choose one engineering specialization early and focus on crafting that specific type of gear. This achievement is account-wide, so pick the faction you prefer and stick with it.", x = 9 },
        [18731] = { e = 4, s = "g", r = "Grind 500 potions; requires prior achievement.", d = "Start this chain immediately after unlocking Alchemy to avoid missing the prerequisite. Craft any potion repeatedly until you hit the count, as this is account-wide and time-gated by the previous achievement.", x = 9 },
        [18732] = { e = 4, s = "g", r = "Grind 1000 potions; requires prior achievement.", d = "Continue crafting potions after completing the previous tier. This is a straightforward volume goal that requires no specific location or group, just consistent profession usage.", x = 9 },
        [18733] = { e = 4, s = "g", r = "Grind 2000 potions; requires prior achievement.", d = "Keep crafting potions until you reach the higher count required for this tier. Ensure you have completed the previous achievement first, as it is a strict prerequisite.", x = 9 },
        [18734] = { e = 3, s = "g", r = "Grind 50 flasks/elixirs/phials.", d = "Begin crafting flasks, elixirs, or phials once you unlock Alchemy recipes for them. This goal is account-wide and serves as the foundation for the subsequent powerful concoctions tiers.", x = 9 },
        [18735] = { e = 4, s = "g", r = "Grind 250 flasks; requires prior achievement.", d = "Progress to this tier only after finishing the previous one by crafting more flasks and elixirs. The volume required increases significantly, so plan your profession time accordingly.", x = 9 },
        [18736] = { e = 4, s = "g", r = "Grind 750 flasks; requires prior achievement.", d = "Continue increasing your flask and elixir counts to reach this higher tier. This is a linear progression that depends entirely on your previous completion status.", x = 9 },
        [18737] = { e = 4, s = "g", r = "Grind 1500 flasks; requires prior achievement.", d = "Finish the final tier of this chain by crafting a large number of flasks and elixirs. There are no time gates here other than completing the prior achievement in the sequence.", x = 9 },
        [18738] = { e = 4, s = "c", h = { 148094 }, r = "Release origami in multiple zones; Deepholm is hardest.", d = "Release origami creatures in their specific zones as listed in the info field. This is account-wide but requires visiting multiple expansion zones and releasing the correct creature types.", x = 9 },
        [18748] = { e = 5, s = "c", h = { 148136 }, r = "Complete all bronze skyriding challenges; reverse Apex Canopy is hardest.", d = "Complete all bronze challenge races in Waking Shores first, then move to silver. These are time-gated by your current rank, so do not skip ahead before unlocking the next tier.", x = 9 },
        [18749] = { e = 5, s = "c", h = { 148148 }, r = "Get silver in all challenges; reverse Apex Canopy is hardest.", d = "Advance from bronze to silver by improving your times in each challenge race. This is a direct progression where you must finish all zones at the lower rank first.", x = 9 },
        [18750] = { e = 5, s = "c", h = { 148158 }, r = "Get gold in all challenges; reverse Apex Canopy is hardest.", d = "Reach gold status in all Waking Shores challenges after mastering silver times. Be aware that these are time-gated achievements, meaning you cannot unlock gold until you have completed the silver tier for every race.", x = 9 },
        [18754] = { e = 3, s = "g", r = "Requires completing multiple bronze races across zones.", d = "Complete all Bronze races in Ohn'ahran Plains first. Use a flying mount and practice the specific course paths to avoid missing checkpoints.", x = 9 },
        [18755] = { e = 4, s = "g", r = "Silver tier requires significantly more skill and time than Bronze.", d = "Return to Ohn'ahran Plains after finishing Silver races elsewhere if needed. Focus on speed runs to secure silver medals for every track.", x = 9 },
        [18756] = { e = 4, s = "g", r = "Gold tier is the hardest difficulty of the race challenges.", d = "Master the fastest routes in Ohn'ahran Plains to earn gold medals. This is account-wide, so ensure all characters contribute if possible.", x = 9 },
        [18757] = { e = 3, s = "g", r = "Requires completing multiple bronze races in Azure Span.", d = "Start with Bronze races in Azure Span using a flying mount. Practice the reverse courses carefully as they often have different optimal paths.", x = 9 },
        [18758] = { e = 4, s = "g", r = "Silver tier requires significantly more skill and time than Bronze.", d = "Upgrade to Silver medals in Azure Span by optimizing your speed and route selection. Ensure you complete every single race type including reverses.", x = 9 },
        [18759] = { e = 4, s = "g", r = "Gold tier is the hardest difficulty of the race challenges.", d = "Achieve Gold status in Azure Span through repeated practice runs. This is account-wide, so coordinate with friends or solo grind efficiently.", x = 9 },
        [18760] = { e = 3, s = "g", r = "Requires completing multiple bronze races in Thaldraszus.", d = "Begin Thaldraszus Bronze challenges immediately upon arrival. Use a flying mount and memorize the specific flight paths for each circuit.", x = 9 },
        [18761] = { e = 4, s = "g", r = "Silver tier requires significantly more skill and time than Bronze.", d = "Progress to Silver medals in Thaldraszus by refining your speed runs. Pay close attention to reverse courses which require different strategies.", x = 9 },
        [18762] = { e = 4, s = "g", r = "Gold tier is the hardest difficulty of the race challenges.", d = "Secure Gold medals in Thaldraszus through high-speed completion of all tracks. This is account-wide, so grind efficiently across characters.", x = 9 },
        [18763] = { e = 2, s = "g", r = "Crafting 50 items is easy with profession knowledge.", d = "Equip the Spectral Visage toy and craft ten Scepters of each element. Use them while the toy is active to complete the achievement.", x = 9 },
        [18764] = { e = 3, s = "s", r = "Requires maintaining a specific buff for one hour.", d = "Craft or obtain Elemental Shatter items and maintain their effects for one continuous hour. Coordinate with friends if you need multiple sources.", x = 9 },
        [18765] = { e = 2, s = "s", r = "Crafting a single legendary item takes moderate time.", d = "Gather the required materials to craft the Sulfuron Hammer. Ensure your profession skill is high enough before attempting this legendary item.", x = 9 },
        [18766] = { e = 2, s = "g", r = "Disenchanting 50 items is quick solo work.", d = "Start disenchanting junk items immediately after learning the profession. This is account-wide and chains into higher tiers, so do not stop until you reach the next requirement.", x = 9 },
        [18767] = { e = 3, s = "g", r = "Disenchanting 250 items takes a few hours.", d = "Continue disenchanting once you unlock Disenchantment I. The volume increases significantly, so plan to grind high-yield zones or use a group for efficiency.", x = 9 },
        [18768] = { e = 4, s = "g", r = "Disenchanting 750 items is a long grind.", d = "Keep disenchanting after completing the previous tier. This stage requires substantial grinding; consider using a disenchanting addon to track progress easily.", x = 9 },
        [18769] = { e = 4, s = "g", r = "Disenchanting 1500 items requires significant time.", d = "Finish the final disenchantment tier by processing large quantities of items. Ensure you have enough gold and inventory space for this long-term goal.", x = 9 },
        [18770] = { e = 2, s = "s", r = "Crafting the tool is a single step.", d = "Craft Silas' Sphere of Transmutation as soon as you learn Alchemy. This is a one-time craft that unlocks your profession's full potential.", x = 9 },
        [18771] = { e = 2, s = "s", r = "Crafting the hammer is a single step.", d = "Craft the Khaz'gorian Smithing Hammer immediately upon learning Blacksmithing. It is a single-item requirement with no time gate or group needed.", x = 9 },
        [18772] = { e = 2, s = "s", r = "Crafting the quill is a single step.", d = "Craft the Sanguine Feather Quill of Lana'thel right after starting Inscription. This tool achievement is account-wide and requires only one specific item.", x = 9 },
        [18773] = { e = 2, s = "s", r = "Crafting the focus is a single step.", d = "Craft Jewelhammer's Focus once you unlock Jewelcrafting. It is a straightforward single-item craft that serves as your profession's key tool.", x = 9 },
        [18774] = { e = 2, s = "s", r = "Crafting the thread is a single step.", d = "Craft the Synchronous Thread immediately after learning Tailoring. This is a simple one-time craft with no complex prerequisites or time limits.", x = 9 },
        [18775] = { e = 2, s = "s", r = "Crafting the rod is a single step.", d = "Craft Iwen's Enchanting Rod as soon as you learn Enchanting. Ensure you have the necessary materials ready before attempting this single-item craft.", x = 9 },
        [18776] = { e = 2, s = "s", r = "Crafting the spanner is a single step.", d = "Craft The Ub3r-Spanner immediately after learning Engineering. This is a standard tool achievement that requires only one specific crafted item.", x = 9 },
        [18777] = { e = 2, s = "s", r = "Crafting the mallet is a single step.", d = "Craft the Mallet of Thunderous Skins right after learning Leatherworking. Gather the required materials beforehand to complete this single-item craft quickly.", x = 9 },
        [18778] = { e = 2, s = "c", r = "Crafting items takes a few hours total.", d = "Craft the Tools of the Trade from each primary profession to unlock this account-wide achievement. Prioritize gathering materials and learning recipes before attempting the final craft. No time gates exist, but ensure you have access to all crafting zones.", x = 9 },
        [18779] = { e = 3, s = "g", r = "Completing multiple timed races is moderate work.", d = "Complete every Forbidden Reach Challenge race in Bronze difficulty first. These races are repeatable and require no specific group composition. Finish the reverse versions of each route before moving to Silver or higher difficulties.", x = 9 },
        [18780] = { e = 4, s = "g", r = "Silver requires faster runs and more attempts.", d = "Once you have finished all Forbidden Reach Bronze challenges, immediately attempt them again for Silver medals. Practice your routes to improve speed and consistency. This step is mandatory before unlocking Gold challenges in the same zone.", x = 9 },
        [18781] = { e = 5, s = "g", r = "Gold is rare RNG dependent on perfect runs.", d = "Achieve Gold status on all Forbidden Reach Challenge races after completing the Silver tier. Focus on optimizing your pathing and reaction times for maximum speed. This is an account-wide requirement, so ensure every character contributes to the progress.", x = 9 },
        [18785] = { e = 2, s = "c", r = "Shatter recipes are quick to craft once known.", d = "Perform each listed shatter recipe as an Enchanter to complete this account-wide task. You can do these individually without needing specific items or groups. There are no time gates, so craft them whenever you have excess reagents.", x = 9 },
        [18786] = { e = 3, s = "g", r = "Zaralek Bronze races take a few hours total.", d = "Finish all Zaralek Cavern Challenge races in Bronze difficulty before advancing. These races are repeatable and cover various zones within the cavern. Complete both forward and reverse versions of each route to unlock the next tier.", x = 9 },
        [18787] = { e = 4, s = "g", r = "Silver requires faster completion times.", d = "Repeat all Zaralek Cavern Bronze challenges to earn Silver medals. Improve your speed by memorizing shortcuts and avoiding unnecessary obstacles. You must complete this entire set before attempting Gold difficulties in the same area.", x = 9 },
        [18788] = { e = 5, s = "g", r = "Gold is very hard due to RNG and speed.", d = "Achieve Gold status on all Zaralek Cavern Challenge races after finishing Silver. Focus on perfect runs to maximize your time and secure the gold medal. This step is required before moving on to Dragon Isles challenges.", x = 9 },
        [18789] = { e = 2, s = "c", r = "Crafting reagents is fast and easy.", d = "Craft twenty of each specified enchanted crafting reagent as an Enchanter. These items are account-wide, so any character can contribute. No time gates exist, but ensure you have the necessary base materials and enchanting recipes.", x = 9 },
        [18790] = { e = 4, s = "g", r = "Dragon Isles Bronze requires many zone visits.", d = "Complete all Dragon Isles Challenge races in Bronze difficulty to unlock this tier. This includes zones like Waking Shores and Ohn'ahran Plains. Finish both forward and reverse routes before progressing to Silver or higher difficulties.", x = 9 },
        [18791] = { e = 5, s = "g", r = "Silver is hard due to RNG and speed needs.", d = "Achieve Silver status on all Dragon Isles Challenge races after completing Bronze. Practice your routes to improve speed and consistency across different zones. This step is mandatory before unlocking Gold challenges in the same area.", x = 9 },
        [18792] = { e = 5, s = "g", r = "Gold is very hard with strict RNG and speed.", d = "Obtain Gold medals for all Dragon Isles Challenge races after finishing Silver. Focus on optimizing your pathing and reaction times for maximum speed. Completing this tier grants you the Isles Ace title and a toy reward.", x = 9 },
        [18793] = { e = 4, s = "c", r = "Requires specific cooking buff and multiple rare spawns/tasks.", d = "Start by camping in a safe zone to activate Cooking Fire, then complete tasks like fishing or crafting while the buff lasts. Finish quickly as the effect wears off, and note this is account-wide so friends can help.", x = 9 },
        [18804] = { e = 5, s = "c", h = { 148523, 148524, 149677 }, r = "End-game raid content with heavy RNG and complex mechanics.", d = "Begin with Que Zara(lek) and work through each Embers of Neltharion achievement listed in the info field sequentially. Ensure you finish all sub-quests before moving on, as missing content here will permanently block progress.", x = 9 },
        [18805] = { e = 3, s = "c", r = "Requires learning many recipes after a specific profession upgrade.", d = "First craft a Draconic Phial Cauldron to unlock these recipes, then learn every phial variant listed in the requirements. This is account-wide, so coordinate with friends if you need specific reagents or testing environments.", x = 9 },
        [18815] = { e = 3, s = "c", r = "Crafting multiple items within a strict time limit.", d = "Craft Dream of Destruction immediately before starting this set, as you must make each Dreamcloth recipe within five minutes. Rush through crafting quickly to avoid the timer expiring on any single item.", x = 9 },
        [18816] = { e = 4, s = "g", r = "Requires learning 300 recipes, taking significant time to complete.", d = "Focus on cooking rare recipes and completing daily food quests to reach 300 learned items efficiently. This is a chain requirement, so do not stop until you hit the count before moving to the next tier.", x = 9 },
        [18817] = { e = 4, s = "g", r = "Requires learning 400 recipes, a substantial grind for alchemists.", d = "Continue learning new cooking recipes immediately after finishing the previous tier to reach 400 total. Prioritize rare drops and daily quests to speed up progress on this account-wide goal.", x = 9 },
        [18818] = { e = 3, s = "g", r = "Requires finding and documenting every variant of Serevite ore.", d = "Travel across all Dragon Isles zones mining every Serevite node you encounter to document each variant. Check your ledger frequently to ensure no ore type is missed before moving to new areas.", x = 9 },
        [18819] = { e = 3, s = "g", r = "Requires finding and documenting every variant of Draconium ore.", d = "Mine Draconium deposits in every zone of the Dragon Isles, ensuring you interact with each unique vein type. Keep an eye on your discovery log to confirm all variants are recorded before leaving a region.", x = 9 },
        [18820] = { e = 4, s = "c", r = "Combines multiple mining ledger achievements into one large task.", d = "Complete the three elemental ore ledgers and find the two special stone discoveries listed in the info field. This is account-wide, so gather friends to help locate rare mining nodes quickly.", x = 9 },
        [18821] = { e = 3, s = "g", r = "Requires overloading every element empowered ore vein across zones.", d = "Use overload mechanics on every empowered ore vein across the Dragon Isles to discover their effects. Test each node type thoroughly to ensure you have documented all overloads before finishing.", x = 9 },
        [18822] = { e = 3, s = "g", r = "Requires finding and documenting every variant of Hochenblume herb.", d = "Gather Hochenblume herbs in every zone of the Dragon Isles, checking your log after each harvest to confirm variants are discovered. This is account-wide, so coordinate with friends if specific zones are hard to access.", x = 9 },
        [18823] = { e = 3, s = "g", r = "Requires finding and documenting every variant of Saxifrage herb.", d = "Collect Saxifrage samples from all locations on the Dragon Isles and verify each variant in your botanist log. Ensure you visit remote areas where rare herb patches might be hidden to avoid missing discoveries.", x = 9 },
        [18824] = { e = 3, s = "g", r = "Grinding for specific herb variants across zones.", d = "Gather every Bubble Poppy variant in the Dragon Isles while leveling Herbalism. This is account-wide and requires no group, but ensure you visit all zones to find rare spawns.", x = 9 },
        [18825] = { e = 3, s = "g", r = "Grinding for specific herb variants across zones.", d = "Locate and gather all Writhebark variants across the Dragon Isles. Since this is account-wide, any character can contribute progress toward completion.", x = 9 },
        [18828] = { e = 4, s = "c", h = { 148827, 148826, 148830 }, r = "Requires finding rare herbs and specific pollen.", d = "Complete all other herbalism achievements first, then overload nodes to finish this one. It requires specific items like Infused Pollen and Dreambloom found during normal gathering.", x = 9 },
        [18829] = { e = 3, s = "g", r = "Grinding for overloaded herb variants across zones.", d = "Use the Overload ability on every empowered herb node in the Dragon Isles. This is account-wide, so gather with any character once you have the skill unlocked.", x = 9 },
        [18831] = { e = 4, s = "c", r = "Combines multiple rare herb and pollen requirements.", d = "This achievement unlocks after completing all other herbalism logs and recovering specific items. Focus on gathering diverse herbs across all Dragon Isles zones to trigger the final requirement.", x = 9 },
        [18832] = { e = 3, s = "g", r = "Grinding for special elusive beasts as a skinner.", d = "Kill any special elusive beast as a Skinner to start this chain. These targets are rare spawns, so be patient and check multiple zones for appearances.", x = 9 },
        [18833] = { e = 4, s = "c", h = { 148888, 148892, 148897 }, r = "Requires slaying all special elusive beasts including rares.", d = "After completing the previous achievement, kill all remaining special elusive beasts. This is account-wide, so coordinate with friends or solo farm different zones until all are done.", x = 9 },
        [18834] = { e = 2, s = "c", r = "Mastering existing techniques from previous expansions.", d = "Master every Broken Isles Skinning Technique by skinning appropriate creatures in Legion zones. These techniques unlock automatically upon meeting the specific creature requirements.", x = 9 },
        [18835] = { e = 2, s = "c", r = "Mastering existing techniques from previous expansions.", d = "Learn all Zandalari and Kul'Tiran Skinning Techniques from Battle for Azeroth content. Farm relevant mobs in Stormsong Valley or Nazjatar to unlock these techniques.", x = 9 },
        [18837] = { e = 2, s = "c", r = "Mastering existing gathering techniques from previous expansions.", d = "Gather specific herbs like Aethril and Felwort in Legion zones to master Broken Isles Herbalism Techniques. Visit all major zones to ensure you encounter every required plant.", x = 9 },
        [18838] = { e = 2, s = "c", r = "Mastering existing gathering techniques from previous expansions.", d = "Collect herbs from Zandalari and Kul'Tiran regions to master Fourth War Herbalism Techniques. Focus on Stormsong Valley and Nazjatar for the necessary rare plants.", x = 9 },
        [18839] = { e = 2, s = "c", r = "Mastering existing mining techniques from previous expansions.", d = "Mine specific ores in Legion zones to master Broken Isles Mining Techniques. Visit all major zones like Suramar or Tazavesh to find every required deposit or seam.", x = 9 },
        [18840] = { e = 3, s = "g", r = "Requires finding and mining multiple rare deposits across zones.", d = "Master all Battle for Azeroth mining techniques first, then gather the specific deposits and seams listed in the info field. This is account-wide so play multiple characters if needed, but be aware that rare ore nodes may take time to find.", x = 9 },
        [18841] = { e = 2, s = "g", r = "Smelt a specific bar five times; materials are craftable.", d = "Smelt Enchanted Elementium Bars five times total across your account by crafting them on any character with sufficient profession skill. Ensure you have the recipe unlocked before attempting this, as it is a simple repeat task without complex prerequisites.", x = 9 },
        [18851] = { e = 4, s = "c", h = { 148986, 148990, 148992 }, r = "Crafting rare skeleton keys requires specific recipes and materials.", d = "Craft each of the twelve Skeleton Keys listed in the info field using Blacksmithing recipes available after unlocking Reborn weapons. Since these are account-wide, one character can complete them all once you have learned the necessary crafting methods.", x = 9 },
        [18852] = { e = 3, s = "c", h = { 148996, 148997, 148998 }, r = "Learning to craft several legendary weapons requires finding recipes.", d = "Learn to craft each of the seven Reborn weapons by finding their specific recipes and gathering required materials. These items are historical significance pieces, so check your profession trainer or recipe books for access after unlocking the Reborn line.", x = 9 },
        [18853] = { e = 2, s = "s", r = "Craft one specific item once; recipe must be learned first.", d = "Craft the Warblades of the Hakkari, Reborn directly using Blacksmithing once you have access to the recipe and necessary components. This is a single-item achievement, so focus solely on obtaining the materials and crafting it exactly as specified.", x = 9 },
        [18854] = { e = 1, s = "s", r = "Complete a single quest chain to witness the event.", d = "Complete the quest Proof and Promise to witness Velen's prophecy unfold and unlock the custom appearance reward for Draenei characters. Ensure you are playing a Draenei character or have an account-wide completion if the reward is tied to your specific faction.", x = 9 },
        [18855] = { e = 3, s = "g", r = "Collect multiple wormhole devices from various zones and events.", d = "Use the Zapthrottle Mote Extractor on 50 gas clouds found in various zones to complete this engineering achievement. Gas clouds spawn randomly, so be patient and explore diverse areas to maximize your extraction opportunities.", x = 9 },
        [18856] = { e = 2, s = "g", r = "Extract elements from gas clouds; materials are common in zones.", d = "Catch two of each elemental soul using the Zapthrottle Soul Inhaler by interacting with specific environmental events or creatures. Air, Earth, Fire, and Frost souls must each be captured twice for a total of eight captures.", x = 9 },
        [18857] = { e = 3, s = "g", r = "Catch elemental souls with a specific tool; requires some luck.", d = "Deliver forged documents to the six listed Horde individuals in the info field to complete this inscription achievement. Visit the specified NPCs in their respective zones and ensure you have the correct forged document before handing it over.", x = 9 },
        [18858] = { e = 2, s = "c", h = { 149057, 149058, 149059 }, r = "Deliver forged documents to NPCs; some may be rare spawns.", x = 9 },
        [18859] = { e = 2, s = "c", h = { 149063, 149065, 149067 }, r = "Deliver forged documents to NPCs; some may be rare spawns.", d = "Deliver forged documents to the six listed Alliance individuals in the info field to complete this inscription achievement. Visit the specified NPCs in their respective zones and ensure you have the correct forged document before handing it over.", x = 9 },
        [18862] = { e = 2, s = "g", r = "Craft 100 items with the profession; materials are craftable.", d = "Craft any Blacksmithing item 100 times total across your account by repeatedly using the profession on various characters. This is a grind-heavy task, so consider crafting high-demand items to sell or use for other achievements while meeting the count.", x = 9 },
        [18864] = { e = 3, s = "g", r = "Grinding 500 items takes several hours of profession time.", d = "Start crafting basic items immediately after unlocking Blacksmithing to begin the chain. Since these are account-wide, craft on any character once you reach level 350 or higher for faster progress.", x = 9 },
        [18865] = { e = 4, s = "g", r = "Crafting 1000 items is a long grind requiring many hours.", d = "Continue crafting consistently; no specific quest is needed beyond completing the previous tier. Focus on high-volume recipes like boots or belts to meet the 1000 item count efficiently.", x = 9 },
        [18866] = { e = 5, s = "g", r = "2000 items is a massive grind taking days of playtime.", d = "This tier requires double the effort of the first two, so plan your daily crafting around gathering nodes near your main hub. Ensure you have enough reagents stocked before starting long sessions.", x = 9 },
        [18867] = { e = 2, s = "s", r = "Completing one specific quest is easy and quick.", d = "Complete the 'Suffusion Camp' quest in Dragonflight as soon as it becomes available to secure these points. Do not delay this if you plan to do other Dragonflight content later.", x = 9 },
        [18868] = { e = 3, s = "g", r = "Grinding 100 enchantments takes a few hours of profession time.", d = "Begin enchanting or crafting items immediately after learning Enchanting; even low-level gear counts toward the total. Use any character on your account to speed up reaching 100 items.", x = 9 },
        [18869] = { e = 4, s = "g", r = "Crafting 500 items is a long grind requiring significant time.", d = "Progress steadily by focusing on popular enchant slots like weapon speed or armor stats. Avoid stopping mid-chain since each tier builds directly on the previous one.", x = 9 },
        [18870] = { e = 5, s = "g", r = "2000 items requires days of grinding the profession.", d = "At this stage, consider automating your crafting routine with addons that track profession progress. Stick to recipes that yield multiple items per session for maximum efficiency.", x = 9 },
        [18871] = { e = 5, s = "g", r = "Crafting 2000 items is a very long grind taking days.", d = "Reach the final enchanting tier by maintaining a steady pace; there are no time gates but material costs increase significantly at higher levels.", x = 9 },
        [18872] = { e = 3, s = "g", r = "Grinding 100 engineering items takes several hours of time.", d = "Start engineering right away and craft simple gadgets like grenades or traps. These early items count toward the total, so do not skip them for advanced recipes.", x = 9 },
        [18873] = { e = 4, s = "g", r = "Crafting 500 items is a long grind requiring many hours.", d = "Keep crafting engineering items daily; the jump to 500 items is manageable but requires consistent effort over several weeks if playing casually.", x = 9 },
        [18874] = { e = 5, s = "g", r = "2000 items requires days of grinding the profession.", d = "Focus on high-yield engineering projects like explosives or utility devices. Remember that account-wide progress means you can switch characters freely without losing progress.", x = 9 },
        [18875] = { e = 5, s = "g", r = "Crafting 2000 items is a very long grind taking days.", d = "Complete the final engineering tier by crafting 2000 items; prioritize recipes with low material costs and high drop rates to finish faster.", x = 9 },
        [18876] = { e = 2, s = "g", r = "Solo crafting grind; trivial once profession is learned.", d = "Start crafting any Inscription item immediately to begin the chain. Focus on high-yield recipes like scrolls or flasks for efficiency, as you need 50 total items.", x = 9 },
        [18877] = { e = 3, s = "g", r = "Larger crafting count requires significant time investment.", d = "Unlock this after finishing the first tier by continuing to craft Inscription items. Maintain a steady production rate since the requirement jumps to 250 items.", x = 9 },
        [18878] = { e = 4, s = "g", r = "High volume crafting becomes a long-term daily grind.", d = "Complete the previous tier before unlocking this one, which requires crafting 750 items. Use daily vendors or world drops to speed up material gathering for large batches.", x = 9 },
        [18879] = { e = 5, s = "g", r = "Extreme crafting count makes this a very hard multi-week grind.", d = "Finish the prior tier first, then craft 1500 Inscription items. This is a long-term goal, so consider alts or group crafting if you want to finish faster.", x = 9 },
        [18880] = { e = 2, s = "g", r = "Solo crafting grind; trivial once profession is learned.", d = "Begin by crafting any Jewelcrafting item like gems or jewelry. Aim for consistent daily output since you need 100 items before unlocking the next tier.", x = 9 },
        [18881] = { e = 2, s = "g", r = "Solo crafting grind; trivial once profession is learned.", d = "Start crafting Leatherworking items immediately, focusing on bags or bracers. You only need 100 items to unlock the next stage of this achievement chain.", x = 9 },
        [18882] = { e = 3, s = "g", r = "Larger crafting count requires significant time investment.", d = "Unlock after completing the first tier by crafting 500 Leatherworking items. Prioritize recipes with high drop rates from world bosses or daily quests.", x = 9 },
        [18883] = { e = 4, s = "g", r = "High volume crafting becomes a long-term daily grind.", d = "Complete the previous tier before starting this one, which requires 1000 crafted items. Plan your material gathering carefully to avoid running out of resources mid-chain.", x = 9 },
        [18884] = { e = 5, s = "g", r = "Extreme crafting count makes this a very hard multi-week grind.", d = "Finish the prior tier first, then craft 2000 Leatherworking items. This is a massive volume goal, so consider using multiple characters or focusing on high-yield recipes.", x = 9 },
        [18885] = { e = 2, s = "g", r = "Solo crafting grind; trivial once profession is learned.", d = "Start crafting Tailoring items like cloaks or bracers immediately. You need 100 items to unlock the next tier, so pick efficient recipes early.", x = 9 },
        [18886] = { e = 3, s = "g", r = "Larger crafting count requires significant time investment.", d = "Unlock after finishing the first tier by crafting 500 Tailoring items. Focus on high-demand items like armor pieces to maximize your crafting efficiency.", x = 9 },
        [18887] = { e = 4, s = "g", r = "High volume crafting becomes a long-term daily grind.", d = "Complete the previous tier before unlocking this one, which requires 1000 crafted items. Use daily vendors and world drops to gather materials quickly for large batches.", x = 9 },
        [18888] = { e = 3, s = "g", r = "Crafting 2000 items is a long solo grind.", d = "Start this after completing Quite the Quilt III, then focus on crafting any tailoring item 2000 times total. Since it is account-wide, you can craft items across all characters to reach the goal faster.", x = 9 },
        [18889] = { e = 3, s = "g", r = "Crafting 500 items is a moderate solo grind.", d = "Begin by crafting jewelcrafting items until you hit 500 total counts; this unlocks the next tier in the chain. Remember that progress carries over across your entire account, so use multiple characters if needed.", x = 9 },
        [18890] = { e = 3, s = "g", r = "Crafting 1000 items is a long solo grind.", d = "Once Generations of Gemstones II is complete, continue crafting jewelcrafting items to reach the 1000 count requirement. This step is part of a longer progression chain, so ensure you have completed the previous tier first.", x = 9 },
        [18891] = { e = 3, s = "g", r = "Crafting 2000 items is a very long solo grind.", d = "After finishing Generations of Gemstones III, craft jewelcrafting items until you reach 2000 total. As an account-wide achievement, you can grind this efficiently by using multiple characters to boost your count quickly.", x = 9 },
        [18892] = { e = 3, s = "g", r = "Milling 2000 herbs is a long solo grind.", d = "Use the Inscription profession to mill herbs repeatedly; aim for 2000 milling operations total. This is account-wide, so you can split the work across different characters to speed up completion.", x = 9 },
        [18893] = { e = 3, s = "g", r = "Prospecting/Crushing 2000 items is a long solo grind.", d = "Perform prospecting or crushing actions on ores and gems until you reach 2000 total operations. Since this tracks account-wide, utilize multiple characters to maximize your progress without wasting time.", x = 9 },
        [18894] = { e = 3, s = "c", r = "Crafting four specific hats takes several hours.", d = "Craft each of the four listed stylin' hats using Leatherworking to complete this achievement. Ensure you have access to the required patterns and materials before starting, as missing any hat will delay completion.", x = 9 },
        [18895] = { e = 2, s = "s", r = "Single event achievement with no partial progress.", d = "This engineering achievement requires completing a specific quest titled Get What You Deserve. Check your engineering daily quests or reputation rewards for the necessary task, as it may be time-gated or rare drop dependent.", x = 9 },
        [18896] = { e = 2, s = "s", r = "Requires specific buffs but is a single step.", d = "Equip all three Battle Flags (Phalanx Defense, Rallying Swiftness, and Spirit of Freedom) simultaneously while wearing tailoring gear. This is account-wide, so coordinate with friends or use multiple characters to gather the flags quickly.", x = 9 },
        [18897] = { e = 3, s = "c", r = "Completing many daily quests takes several hours.", d = "Complete every listed Jewelcrafting daily quest, including unique ones like Nibbler! No! and The Latest Fashion!. Track your progress carefully since missing a single quest will prevent you from earning the full points.", x = 9 },
        [18898] = { e = 4, s = "c", h = { 149177 }, r = "Killing Nefarian is hard; second kill is easier.", d = "Defeat Nefarian in Blackwing Lair with the Onyxia Scale Cloak equipped, then repeat the feat in Blackwing Descent. This is account-wide, so coordinate with a group to ensure both bosses are defeated under the correct conditions.", x = 9 },
        [18899] = { e = 3, s = "c", r = "Crafting and wearing item during boss fight.", d = "While fighting Captain Kromcrush in Dire Maul, craft and equip a Gordok Ogre Suit using Leatherworking. Timing is critical here, as you must craft and wear the suit during combat to trigger the achievement.", x = 9 },
        [18900] = { e = 2, s = "g", r = "Crafting ~13 drums takes a few hours.", d = "Craft every drum recipe listed, starting with the basic ones first to save resources. This is account-wide and requires no group, but ensure you have enough leather before crafting high-end drums.", x = 9 },
        [18901] = { e = 2, s = "g", r = "Crafting many goggles takes a few hours.", d = "Queue up engineering recipes for all holo-goggs variants in your profession window. Since this is account-wide, craft them on any character once you unlock the necessary engineering skill levels.", x = 9 },
        [18902] = { e = 4, s = "g", r = "Grinding 500 bandages is time-consuming.", d = "Grind Wildercloth Bandages by crafting them repeatedly; this is purely a volume-based task with no time gate. Use a high-level alchemy or tailoring character to speed up material gathering if needed.", x = 9 },
        [18903] = { e = 2, s = "g", r = "Crafting many shirts takes a few hours.", d = "Craft each shirt and the tuxedo pants recipe one by one, checking your profession window for available patterns. This achievement is account-wide, so complete it on any character with maxed tailoring skills.", x = 9 },
        [18904] = { e = 2, s = "g", r = "Crafting ~23 stones takes a few hours.", d = "Research or craft every Philosopher's Stone variant listed, starting from the basic stone to the rarest versions. This is account-wide and may require specific reagents found in dungeons or crafted via alchemy research.", x = 9 },
        [18905] = { e = 2, s = "g", r = "Crafting 7 goggles takes under an hour.", d = "Craft all Pandaria goggles recipes sequentially, ensuring you have the required engineering skill and materials. This achievement is account-wide, so finish it on any character with unlocked engineering patterns.", x = 9 },
        [18906] = { e = 2, s = "g", r = "Crafting 10 headguns takes a few hours.", d = "Craft each cranial cannon recipe in order, using your engineering profession to unlock higher-tier variants. This is account-wide and requires no group, but watch for rare material drops that may take time.", x = 9 },
        [18907] = { e = 2, s = "g", r = "Crafting 4 specs takes under an hour.", d = "Queue up ectoplasmic specs recipes and craft them as you gather the necessary reagents. This achievement is account-wide, so complete it on any character with unlocked engineering patterns.", x = 9 },
        [18908] = { e = 2, s = "g", r = "Crafting 7 goggles takes under an hour.", d = "Craft every bio-optic killshade variant listed, starting from the basic version to the specialized ones. This is account-wide and requires no group, but ensure you have enough engineering skill for higher-tier recipes.", x = 9 },
        [18909] = { e = 2, s = "g", r = "Crafting ~20 figurines takes a few hours.", d = "Craft or repair each figurine recipe in your jewelcrafting window, starting with the simplest designs. This is account-wide and may require rare materials found in dungeons or crafted via specific quests.", x = 9 },
        [18934] = { e = 3, s = "g", r = "Experimenting 100 times takes several hours.", d = "Perform alchemical experiments repeatedly by using reagents in your alchemy profession until you reach 100 experiments. This is account-wide and can be done quickly with a high-level character and ample resources.", x = 9 },
        [18939] = { e = 2, s = "c", h = { 149486 }, r = "Racing all tracks is a moderate checklist.", d = "Complete all dragon racing events in the Eastern Kingdoms, including bronze, advanced, and reverse races. This is account-wide and requires skyriding ability; start with basic races before attempting harder variants.", x = 9 },
        [18940] = { e = 2, s = "g", r = "Grind races across Eastern Kingdoms zones.", d = "Race all three dragon mounts in Eastern Kingdoms to earn silver medals. You must first complete the base racing achievement before unlocking this one.", x = 9 },
        [18941] = { e = 3, s = "c", r = "Craft multiple specific jeweled pets.", d = "Craft every Jeweled Whelpling using your Jewelcrafting skill. This is account-wide, so any character can contribute to the progress.", x = 9 },
        [18942] = { e = 3, s = "g", r = "Grind harder races after silver completion.", d = "Repeat the racing process from the previous achievement but aim for gold medals on every track. Ensure you have unlocked the silver version first.", x = 9 },
        [18958] = { e = 2, s = "s", r = "Complete a specific storyline quest.", d = "Complete Tyr's storyline in Dragonflight by finishing the quest Time to Process. This unlocks the title of the Tyr's Guard.", x = 9 },
        [18959] = { e = 3, s = "s", r = "Kill event boss during Hallow's End.", d = "Defeat any version of the Headless Horseman during Hallow's End events. Simply killing him once counts toward this achievement.", x = 9 },
        [18960] = { e = 4, s = "c", r = "Requires specific curse conditions on boss.", d = "Wait for all four wicker men to curse you before defeating the Headless Horseman. This specific condition is required for full credit.", x = 9 },
        [18962] = { e = 3, s = "s", r = "Kill event boss during Hallow's End.", d = "Defeat the Headless Horseman again during Hallow's End. Note that this may be a separate instance or simply another kill count depending on game mechanics.", x = 9 },
        [18963] = { e = 4, s = "c", r = "Requires complex simultaneous buff stacking.", d = "Stack all five burst effects simultaneously and drink a Potion of Bursting Blood instantly. Timing is critical as the effects wear off quickly.", x = 9 },
        [18976] = { e = 2, s = "s", r = "Equip gear meeting item level threshold.", d = "Equip gear with at least item level 346 in every slot to start this legacy chain. You must fill all equipment slots before moving up.", x = 9 },
        [18977] = { e = 2, s = "s", r = "Equip higher item level gear.", d = "Upgrade your entire set to item level 372 or higher after completing the previous step. This requires farming better gear from raids or dungeons.", x = 9 },
        [19008] = { e = 2, s = "s", r = "Complete a specific quest in Dragonflight.", d = "Complete the specific quest Shaping the Dreamsurge in Dragonflight. Ensure you have finished any prerequisite quests listed in the achievement info.", x = 9 },
        [19013] = { e = 4, s = "g", r = "Grind seeds at many scattered locations.", d = "Gather and plant seeds at every Emerald Bounty location across the Dragon Isles. This is account-wide, so coordinate with friends if needed.", x = 9 },
        [19026] = { e = 3, s = "c", r = "Complete 7 storylines; moderate time.", d = "Start the Emerald Dream campaign immediately upon entering the zone. Complete all listed storylines in any order, but ensure you finish them before leaving the area to avoid missing content.", x = 9 },
        [19089] = { e = 4, s = "s", r = "Specific raid condition with pet mechanic.", d = "Defeat Larodar on Normal or higher difficulty while keeping Ivy extinguished and alive. This is a raid achievement requiring specific boss mechanics and cannot be completed in Mythic+ without the correct raid setup.", x = 9 },
        [19092] = { e = 3, s = "g", r = "Grind bronze races across multiple zones.", d = "Complete every normal race in Outland to earn bronze medals. You must finish all tracks before unlocking silver; this is account-wide so coordinate with friends if needed for difficult courses.", x = 9 },
        [19097] = { e = 3, s = "g", r = "Grind silver races; requires previous step.", d = "Unlock the silver tier by completing all normal races again after finishing bronze. Do not skip any track, as missing one will prevent you from earning the full achievement points for this tier.", x = 9 },
        [19098] = { e = 3, s = "g", r = "Grind gold races; requires previous step.", d = "Achieve gold status on all normal Outland races by completing them faster than the silver time limit. This requires practice and knowledge of optimal routes to shave off seconds from your previous runs.", x = 9 },
        [19099] = { e = 3, s = "g", r = "Grind advanced bronze races across zones.", d = "Begin advanced races in Outland immediately after unlocking bronze normal races. These tracks are harder and require precise timing; complete all of them to progress toward the silver tier without delay.", x = 9 },
        [19100] = { e = 3, s = "g", r = "Grind advanced silver races; requires previous step.", d = "Earn silver medals on all advanced races by beating their specific time gates. Since these are timed events, practice each course multiple times to ensure you meet the requirements before moving to gold.", x = 9 },
        [19101] = { e = 3, s = "g", r = "Grind advanced gold races; requires previous step.", d = "Complete advanced races in Outland with gold medals by finishing well under the silver time limit. This tier demands high skill and familiarity with every track layout to consistently beat the clock.", x = 9 },
        [19102] = { e = 3, s = "g", r = "Grind reverse bronze races across zones.", d = "Start reverse races in Outland after completing all normal bronze races. These tracks run backward and often have different obstacles; treat them as entirely new courses requiring fresh strategies for success.", x = 9 },
        [19103] = { e = 3, s = "g", r = "Grind reverse silver races; requires previous step.", d = "Unlock silver status on all reverse races by beating their respective time limits. Like normal advanced races, these require multiple attempts to master the reversed layouts and ensure you do not miss any gates.", x = 9 },
        [19104] = { e = 3, s = "g", r = "Grind reverse gold races; requires previous step.", d = "Achieve gold medals on every reverse race in Outland by significantly outperforming the silver time. These are among the most challenging tracks, so dedicate time to perfecting your speed and accuracy before attempting gold.", x = 9 },
        [19105] = { e = 2, s = "c", r = "Unlocks after completing all Outland races.", d = "Finish all Outland races including normal, advanced, and reverse tiers to claim this completionist title. This is an account-wide achievement, so plan your schedule carefully to tackle the hardest tracks when you are most prepared.", x = 9 },
        [19106] = { e = 2, s = "c", r = "Grinding multiple races is moderate effort.", d = "Start by unlocking the Outland Dragon Racing event and complete all three silver races. This achievement is account-wide, so you can race on any character once unlocked.", x = 9 },
        [19107] = { e = 3, s = "c", r = "Higher difficulty races increase grind time.", d = "After earning silver, repeat the process to obtain gold in each Outland race. You will receive a title and tabard upon finishing all gold races.", x = 9 },
        [19109] = { e = 2, s = "c", r = "Standard races are easy to complete solo.", d = "Unlock the Emerald Dream event first, then complete every bronze race available there. This is account-wide, allowing you to switch characters easily between runs.", x = 9 },
        [19110] = { e = 3, s = "c", r = "Silver tier adds some difficulty to races.", d = "Progress from bronze to silver by completing all normal races in the Emerald Dream again. Ensure you have unlocked the previous tier before attempting this one.", x = 9 },
        [19111] = { e = 4, s = "c", r = "Gold tier requires significant grinding time.", d = "Finish the gold tier after securing silver in all normal Emerald Dream races. This completes the standard difficulty set for the zone.", x = 9 },
        [19112] = { e = 3, s = "c", r = "Advanced races are moderately difficult.", d = "Unlock the advanced race category and complete every bronze version of these harder tracks. These races are distinct from the normal ones listed in previous achievements.", x = 9 },
        [19113] = { e = 4, s = "c", r = "Silver advanced races require more time.", d = "Advance to silver by completing all advanced races in the Emerald Dream. You must finish the bronze tier first as a prerequisite.", x = 9 },
        [19114] = { e = 5, s = "c", r = "Gold advanced races are a long grind.", d = "Complete the gold tier of advanced races after earning silver. This finishes the standard difficulty progression for the advanced track set.", x = 9 },
        [19115] = { e = 2, s = "c", r = "Reverse races are similar to standard ones.", d = "Start with the reverse race category and finish all bronze versions in the Emerald Dream. These races run opposite to the normal direction.", x = 9 },
        [19116] = { e = 3, s = "c", r = "Silver reverse races add moderate difficulty.", d = "Move on to silver after completing all reverse bronze races. The achievement tracks your progress through the reverse difficulty tiers specifically.", x = 9 },
        [19117] = { e = 4, s = "c", r = "Gold reverse races are a long grind.", d = "Finish the gold tier of reverse races once you have secured silver. This completes the full reverse difficulty set for the zone.", x = 9 },
        [19118] = { e = 3, s = "c", r = "Combining all race types is moderate effort.", d = "Unlock this completionist title by finishing all bronze achievements in the Emerald Dream first. It requires completing normal, advanced, and reverse categories at the bronze level.", x = 9 },
        [19119] = { e = 2, s = "c", r = "Requires completing multiple silver races.", d = "Start by unlocking the Emerald Dream zone and completing the basic Silver race tracks. Focus on mastering each track's layout before attempting Gold tiers to avoid wasting time.", x = 9 },
        [19120] = { e = 3, s = "c", r = "Requires completing multiple gold races.", d = "Once you have all Silver medals, immediately switch to Gold races on every track. Note that this tier grants the Dream Racer title upon completion.", x = 9 },
        [19121] = { e = 2, s = "c", r = "Requires completing multiple bronze challenge races.", d = "Begin with the Bronze challenge races in any order, as they do not require specific prerequisites. Complete all eight tracks to unlock the Silver tier.", x = 9 },
        [19122] = { e = 3, s = "c", r = "Requires completing multiple silver challenge races.", d = "After finishing all Bronze challenges, repeat the process for Silver medals on every track. This step is required before you can attempt Gold challenges.", x = 9 },
        [19123] = { e = 4, s = "c", r = "Requires completing multiple gold challenge races.", d = "Complete all challenge races to earn the base Completionist title. You must finish both standard and reverse tracks in each tier to progress.", x = 9 },
        [19124] = { e = 2, s = "c", r = "Requires completing multiple bronze reverse races.", d = "Start the Reverse Challenge series with Bronze medals on all tracks. These races run backward compared to standard courses but share the same mechanics.", x = 9 },
        [19125] = { e = 3, s = "c", r = "Requires completing multiple silver reverse races.", d = "Progress through Silver medals for all reverse challenge tracks once you have cleared the Bronze tier. Ensure you do not miss any track in this sequence.", x = 9 },
        [19126] = { e = 4, s = "c", r = "Requires completing multiple gold reverse races.", d = "Finish the Gold tier for all reverse challenge races to complete this specific set. This requires having already earned Silver medals on every reverse track.", x = 9 },
        [19127] = { e = 3, s = "c", r = "Requires completing all challenge and reverse races.", d = "Unlock the base Challenge Racing Completionist by earning Bronze medals in both standard and reverse challenges across all tracks. This is the foundation for higher tiers.", x = 9 },
        [19128] = { e = 4, s = "c", r = "Requires completing silver versions of all challenges.", d = "Advance to Silver medals for all challenge racing tracks after securing the base completionist status. You must complete every track in this tier before moving on.", x = 9 },
        [19129] = { e = 5, s = "c", r = "Requires gold versions of all challenges.", d = "Complete Gold medals for all challenge racing tracks to earn the Emerald Ace title. This is the final step for the main Challenge Racing Completionist chain.", x = 9 },
        [19193] = { e = 4, s = "s", r = "Requires defeating raid boss with specific NPC.", d = "Recruit Sergeant Quackers in Amirdrassil and then defeat the Council of Dreams on Normal difficulty or higher. Ensure you have the recruitment quest active before entering the raid.", x = 9 },
        [19194] = { e = 2, s = "g", r = "Collecting 10 seeds is quick solo farming.", d = "Start by farming seeds from any Dragonflight zone and turn them in to the Emerald Bounty vendor. This is a simple grind with no time gate, but you must reach 50 seeds first before unlocking the next tier.", x = 9 },
        [19196] = { e = 3, s = "g", r = "50 seeds takes a few hours of farming.", d = "Once you have 50 seeds, continue farming until you hit 100 to unlock the final title reward. There are no group requirements, so solo play is perfectly fine for this chain.", x = 9 },
        [19198] = { e = 4, s = "g", r = "100 seeds requires significant time grinding.", d = "Finish the seed chain by contributing your last 100 seeds to claim the Blossom Bringer title. Ensure you have completed the previous two tiers as they are strictly sequential.", x = 9 },
        [19276] = { e = 3, s = "c", r = "PvP sets are easy to get in a few hours.", d = "Equip any armor set from PvP Season 3 or 4 to complete this collection achievement. You do not need to win matches, just wear the gear while in War Mode if required by other criteria.", x = 9 },
        [19293] = { e = 2, s = "c", r = "Rescuing hatchlings is a short quest chain.", d = "Join the Claws For Concern quest chain in Whorlwing Basin and rescue all listed moonkin hatchlings. This is a solo-friendly quest line with no time limit, so take your time to find every pet.", x = 9 },
        [19294] = { e = 3, s = "g", r = "Earning 1000 honor takes an hour or two.", d = "Enable War Mode and queue for Emerald Dream PvP matches to earn honor quickly. You need 1000 total honor, which can be done relatively fast in ranked or arena modes.", x = 9 },
        [19306] = { e = 4, s = "c", h = { 151073 }, r = "Amirdrassil glyph is the hardest to find.", d = "Fly around the Emerald Dream zones using Dragonriding to locate and collect all listed dragon glyphs. These are scattered across the map and require exploration rather than combat.", x = 9 },
        [19307] = { e = 4, s = "c", h = { 151236 }, r = "Exploring Zaralek Caverns is the main grind.", d = "Complete all sub-achievements listed under this title, including exploring Zaralek Caverns and the Emerald Dream. Start with the easier exploration tasks first to build up your progress efficiently.", x = 9 },
        [19309] = { e = 4, s = "c", r = "Full map exploration takes several hours.", d = "Fly over every zone in the Emerald Dream to reveal hidden map areas like Ancient Bough and Amirdrassil. This is purely an exploration task with no combat or time gates involved.", x = 9 },
        [19310] = { e = 4, s = "c", r = "Activating all powers requires extensive travel.", d = "Use Superbloom Dreamfruit powers during bloom events to trigger each unique effect listed. You must activate every power at least once, so keep an eye on your active abilities during blooms.", x = 9 },
        [19312] = { e = 3, s = "s", r = "One specific superbloom event takes a few hours.", d = "Participate in a tier 3 superbloom event and complete the associated tracking quest for epic quality. This is time-gated to specific bloom events, so check the calendar for upcoming opportunities.", x = 9 },
        [19313] = { e = 4, s = "g", r = "Summoning the boss 10 times is a long grind.", d = "During a superbloom, use the Feral Overflow power repeatedly to summon Feral Umbraclaws until you reach 10 kills. Coordinate with other players if possible to maximize your summon count quickly.", x = 9 },
        [19315] = { e = 2, s = "g", r = "Gathering 100 items is a short solo grind.", d = "Farm Errant Dreams during the Superbloom event in the Emerald Dream; this is time-gated and account-wide. Focus on high-density spawn areas to reach the 100 count quickly before the event ends.", x = 9 },
        [19316] = { e = 4, s = "c", h = { 151273 }, r = "Most are easy, but Isaqa requires heavy RNG.", d = "Complete all listed special encounters in the Emerald Dream, including the x10 requirement for Keen-Eyed Cian. These are often grouped together, so run them efficiently as a group or solo depending on difficulty.", x = 9 },
        [19317] = { e = 4, s = "c", h = { 151286 }, r = "Most are easy, but Triflesnatch requires RNG.", d = "Locate and collect unique treasures like Reliquaries and caches scattered throughout the Emerald Dream zones. This is account-wide and requires thorough exploration of every sub-zone during the Superbloom.", x = 9 },
        [19318] = { e = 4, s = "c", h = { 151297 }, r = "Depends on other achievements; Defenders is hardest.", d = "Unlock this title by completing all prerequisite achievements listed in its info field. Start with the smaller gathering and encounter goals before tackling the main questline to ensure progress flows smoothly.", x = 9 },
        [19319] = { e = 4, s = "s", r = "Requires full raid clear with specific mechanics.", d = "Defeat Smolderon on Normal or higher only after dousing all six Runes of the Firelord. This is a specific raid condition; do not attempt the fight until every rune is extinguished.", x = 9 },
        [19320] = { e = 4, s = "s", r = "Requires full raid clear with specific mechanics.", d = "Free all caged critters before fighting Igira on Normal or higher difficulty. Ensure you complete the freeing objective first, as the boss will not spawn or be defeatable otherwise.", x = 9 },
        [19321] = { e = 4, s = "g", r = "Grinding food for a boss is moderate to hard.", d = "Feed Volcoross at least 30 Sizzling Swoggers before engaging him on Normal or higher. Bring extra food items and monitor your count to avoid wasting time after the fight starts.", x = 9 },
        [19322] = { e = 4, s = "s", r = "Requires full raid clear with specific mechanics.", d = "Ignite eight Harmless Blossoms prior to defeating Gnarlroot on Normal or higher. These blossoms are scattered around the raid; clear them all before pulling the boss for credit.", x = 9 },
        [19331] = { e = 5, s = "c", r = "Raid bosses are hard; Tindral is the hardest.", d = "Defeat every boss in Amirdrassil on any difficulty to unlock this main raid achievement. Start with Normal mode if you are new to the raid, then progress to Heroic and Mythic as your group improves.", x = 9 },
        [19333] = { e = 5, s = "c", h = { 151447 }, r = "Heroic raid bosses are very hard; Tindral is hardest.", d = "Unlock Heroic Amirdrassil only after completing the Normal version. Defeat all bosses on Heroic difficulty; this is a strict requirement before you can access Mythic+ or Mythic raid content.", x = 9 },
        [19334] = { e = 5, s = "c", h = { 151490 }, r = "Mythic raid bosses are very hard; Tindral is hardest.", d = "Complete Heroic Amirdrassil first, then queue for Mythic runs to unlock this achievement. Note that Mythic requires specific group coordination and may need multiple attempts per boss depending on your team's skill level.", x = 9 },
        [19335] = { e = 5, s = "s", r = "Requires full Mythic raid clear of a specific boss.", d = "Defeat Gnarlroot specifically on Mythic difficulty within Amirdrassil. This is part of the larger Mythic raid achievement chain, so ensure you have cleared other bosses if required by your specific goal.", x = 9 },
        [19336] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Queue for Mythic Igira in Amirdrassil after unlocking the raid. This is a standard boss kill with no special missable mechanics beyond normal difficulty requirements.", x = 9 },
        [19337] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Defeat Volcoross on Mythic difficulty within Amirdrassil. Ensure you have access to the raid instance before attempting this specific boss encounter.", x = 9 },
        [19338] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Clear Council of Dreams on Mythic in Amirdrassil. This is a straightforward progression step requiring no special group composition beyond standard raid requirements.", x = 9 },
        [19339] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Kill Larodar, Keeper of the Flame on Mythic difficulty. Focus on managing his mechanics as you progress through the Amirdrassil raid content.", x = 9 },
        [19340] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Defeat Nymue, Weaver of the Cycle in Mythic Amirdrassil. This boss requires standard raid coordination and no unique time-gated conditions.", x = 9 },
        [19341] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Slay Smolderon on Mythic difficulty within Amirdrassil. Treat this as a standard progression boss with typical raid mechanics to watch for.", x = 9 },
        [19342] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Complete the Tindral Sageswift encounter on Mythic in Amirdrassil. Ensure your group is ready for the specific mechanics of this final boss fight.", x = 9 },
        [19343] = { e = 4, s = "s", r = "Mythic raid boss requires group and skill.", d = "Defeat Fyrakk the Blazing on Mythic to earn the title The Blazing. This is the last major boss in the raid progression chain.", x = 9 },
        [19344] = { e = 4, s = "c", h = { 151493, 151494 }, r = "Requires defeating specific Mythic raid bosses.", d = "This account-wide achievement requires defeating Gnarlroot, Igira, and Smolderon. You must clear these specific bosses on Mythic to unlock this bonus objective.", x = 9 },
        [19345] = { e = 4, s = "c", h = { 151497, 151498 }, r = "Requires defeating specific Mythic raid bosses.", d = "Unlock Molten Incursion by killing Volcoross and Larodar on Mythic. This is an account-wide bonus that tracks your progress against these specific raid bosses.", x = 9 },
        [19346] = { e = 4, s = "c", h = { 151500, 151501 }, r = "Requires defeating specific Mythic raid bosses.", d = "Achieve The Viridian Weave by defeating Council of Dreams and Nymue on Mythic. Ensure both encounters are completed to satisfy this account-wide requirement.", x = 9 },
        [19347] = { e = 4, s = "c", h = { 151503, 151504 }, r = "Requires defeating specific Mythic raid bosses.", d = "Complete Fate of Amirdrassil by killing Tindral Sageswift and Fyrakk on Mythic. These are the final bosses needed to finish this specific raid achievement set.", x = 9 },
        [19349] = { e = 5, s = "c", h = { 151523, 151524, 151525 }, r = "Raid content with multiple rare drops and specific mechanics.", d = "Complete all listed sub-achievements for Amirdrassil on Normal or higher difficulty. This is a long-term goal requiring full raid clears and specific mechanics like collecting memories or defeating Fyrakk.", x = 9 },
        [19390] = { e = 4, s = "g", r = "Requires collecting six items then defeating a raid boss.", d = "Defeat Fyrakk the Blazing after gathering six Memories of Teldrassil. Ensure you return their spirits to the Heart of Amirdrassil before engaging the boss on Normal or higher.", x = 9 },
        [19393] = { e = 4, s = "g", r = "Requires rescuing six whelps before defeating the boss.", d = "Rescue six Lost Whelps from Nymue's encounter and then defeat Tindral Sageswift. This requires careful attention during the raid mechanics to secure the whelps before the fight ends.", x = 9 },
        [19394] = { e = 5, s = "c", h = { 151639 }, r = "Requires collecting projections while asleep and defeating a boss.", d = "Collect five Dream Projections while asleep in Nymue's encounter and defeat the Manifested Monarch. Coordinate with your group to ensure no projections are missed during the sleep phase.", x = 9 },
        [19400] = { e = 2, s = "g", r = "Donating gold is easy but requires significant accumulation.", d = "Donate 50,000 gold to the Artisan's Consortium for the Gala of Gifts event. This is account-wide and can be done by any character in your group or via mail.", x = 9 },
        [19401] = { e = 3, s = "g", r = "Catching multiple pets in the Emerald Dream takes time.", d = "Catch all listed battle pets in the Emerald Dream zone. Use a Battle Pet Trainer to catch them efficiently, as they are rare spawns found only in that specific area.", x = 9 },
        [19408] = { e = 2, s = "g", r = "Grinding one profession to max skill points is straightforward.", d = "Maximize skill points in one primary profession within the Khaz Algar category. Focus on gathering resources or crafting items until you hit the cap for that specific region's profession tier.", x = 10 },
        [19409] = { e = 3, s = "g", r = "Requires grinding two professions to max skill points.", d = "Reach maximum skill points in two different primary professions in the Khaz Algar category. Complete this after finishing the first profession to unlock the next tier of achievements.", x = 10 },
        [19410] = { e = 5, s = "g", r = "Grinding all primary professions is a massive time investment.", d = "Maximize all primary professions in the Khaz Algar category for a massive point reward. This is a long-term grind requiring significant time investment across multiple characters or alts.", x = 10 },
        [19411] = { e = 2, s = "g", r = "Completing ten BG Blitz victories is relatively quick.", d = "Win ten matches in Battleground Blitz to start this chain. Play rated battlegrounds and focus on winning quickly to progress through the novice tier efficiently.", x = 9 },
        [19412] = { e = 3, s = "g", r = "Requires twenty-five BG Blitz victories, taking moderate time.", d = "Accumulate twenty-five total victories in Battleground Blitz after unlocking the previous tier. Continue playing rated battlegrounds consistently to reach this milestone faster.", x = 9 },
        [19413] = { e = 4, s = "g", r = "Fifty BG Blitz victories is a long grind requiring consistency.", d = "Complete fifty total victories in Battleground Blitz to finish the chain. Maintain a high win rate by learning optimal strategies for each battleground mode.", x = 9 },
        [19414] = { e = 2, s = "g", r = "Grinding profession skill points is easy solo.", d = "Cook rare Khaz Algar recipes repeatedly until you hit 100 skill points in that category. Do this early as cooking skill caps are low and you will outgrow the zone quickly.", x = 10 },
        [19415] = { e = 2, s = "g", r = "Fishing for skill points is quick and solo.", d = "Fish in Khaz Algar zones to gain skill points, aiming for 300 total in that specific category. This is time-gated by zone progression, so fish there before moving to higher levels.", x = 10 },
        [19416] = { e = 3, s = "g", r = "Requires queueing for 25 BG matches.", d = "Queue for Battleground Blitz matches until you complete 25 games to unlock the next tier. This is account-wide and requires no specific class or gear.", x = 9 },
        [19417] = { e = 3, s = "g", r = "Requires queueing for 50 BG matches.", d = "Continue playing Battleground Blitz to reach 50 matches, unlocking the next achievement in the chain. Ensure your account has already completed the previous requirement before starting.", x = 9 },
        [19418] = { e = 3, s = "g", r = "Requires queueing for 100 BG matches.", d = "Play Battleground Blitz until you hit 100 matches total, which unlocks the next stage of the series. This is purely a grind dependent on match completion counts.", x = 9 },
        [19442] = { e = 4, s = "c", r = "Requires raiding Amirdrassil for tier set.", d = "Equip any Tier 31 armor set from Amirdrassil on at least one character to claim this account-wide appearance achievement. You do not need to wear it in combat, just have it equipped once.", x = 9 },
        [19458] = { e = 4, s = "c", h = { 153273, 153274, 153275 }, r = "Requires completing multiple endgame raids.", d = "Complete all listed Dragonflight content achievements before the next expansion launches to earn the Taivan mount. Missing any single requirement will prevent you from getting this reward permanently.", x = 9 },
        [19459] = { e = 2, s = "s", r = "Leveling to 80 is a single milestone.", d = "Level a character to 80 using The War Within leveling experience or legacy methods if available. This is a basic progression goal with no hidden mechanics.", x = 10 },
        [19460] = { e = 3, s = "c", r = "Requires leveling two characters to 80.", d = "Reach level 80 on two separate characters to unlock the bonus XP reward. Start this early as it requires significant time investment across multiple alts.", x = 10 },
        [19461] = { e = 2, s = "s", r = "Obtaining a blessing is a single event.", d = "Travel to Ohn'ahra's zone and interact with her to receive the transformative blessing. This is a one-time interaction that grants the achievement instantly upon completion.", x = 9 },
        [19463] = { e = 3, s = "c", r = "Requires completing multiple specific quests.", d = "Complete every listed Dragonflight quest achievement, which includes major storylines and side quests. Track your progress carefully as missing even one quest will block the main collection.", x = 9 },
        [19466] = { e = 3, s = "c", r = "Requires reaching multiple reputation levels.", d = "Earn all required reputation with factions across the Dragon Isles to finish this large collection. Prioritize high-reputation zones first since some rewards are time-gated by expansion transitions.", x = 9 },
        [19470] = { e = 2, s = "g", r = "Grinding XP to level 80 on one character.", d = "Start leveling one character to 80 immediately to unlock the first mentor bonus. This is account-wide and essential for faster progression on your other characters.", x = 10 },
        [19475] = { e = 3, s = "g", r = "Requires leveling three characters to 80.", d = "Complete the previous mentor achievement, then level three distinct characters to 80 total. You must finish the prior tier before starting this one.", x = 10 },
        [19476] = { e = 3, s = "g", r = "Requires leveling four characters to 80.", d = "Finish the three-character milestone, then level four unique characters to 80. Ensure you do not reuse characters from earlier tiers if the game logic requires distinct ones.", x = 10 },
        [19477] = { e = 3, s = "g", r = "Requires leveling five characters to 80.", d = "Complete the four-character goal by leveling five different characters to 80. This grants the highest experience bonus available in this chain.", x = 10 },
        [19478] = { e = 3, s = "c", h = { 153390, 153391 }, r = "Multiple zone-specific racing achievements required.", d = "Unlock Dragonriding first, then complete every listed racing and glyph achievement across all zones. Some races may be time-gated or require specific mounts.", x = 9 },
        [19479] = { e = 3, s = "c", h = { 153406, 153408 }, r = "Requires completing multiple expedition sub-achievements.", d = "Focus on Dragonscale Expedition tasks like photo quests and climbing peaks in Waking Shores. These are often daily-locked or have long cooldowns.", x = 9 },
        [19481] = { e = 3, s = "c", h = { 153417, 153418 }, r = "Requires completing multiple centaur sub-achievements.", d = "Complete Maruuk Centaur achievements such as hunting specific beasts and gathering resources in Ohn'ahran Plains. Some hunts may require rare spawns.", x = 9 },
        [19482] = { e = 3, s = "c", h = { 153426, 153427 }, r = "Requires completing multiple tuskarr sub-achievements.", d = "Finish Iskaara Tuskarr goals including secret fishing spots and soup-related quests in Azure Span. Fishing locations can be tricky to find.", x = 9 },
        [19483] = { e = 3, s = "c", h = { 153438, 153439 }, r = "Requires completing multiple accord sub-achievements.", d = "Complete Valdrakken Accord tasks like siege events and daycare races in Thaldraszus. Some achievements may require coordinating with other players.", x = 9 },
        [19485] = { e = 3, s = "c", h = { 153449, 153450 }, r = "Requires completing multiple timewalker sub-achievements.", d = "Finish Timewalker achievements involving time-travel mechanics and reality shifts in Emerald Dream. Be cautious of content that resets or has strict timers.", x = 9 },
        [19486] = { e = 4, s = "c", h = { 153457, 153458 }, r = "Combines all other isle achievements plus two more.", d = "Complete all faction-specific achievements listed to unlock the final Dragon Isles mount. This is a massive undertaking requiring full exploration of every zone.", x = 9 },
        [19507] = { e = 2, s = "g", r = "Complete 8 of many available daily quests.", d = "Do daily quests in Eon's Fringe until you complete eight different ones. Some quests may reset on server restarts or have limited availability.", x = 9 },
        [19508] = { e = 2, s = "c", r = "Collecting 10 gifts is a short quest chain.", d = "Farm gifts at Steam Pools Resort by completing daily quests or buying from vendors. Deliver all ten specific gift types to Lovely Guests before the event ends, as this is account-wide and time-gated.", x = 9 },
        [19515] = { e = 4, s = "g", r = "Grinding 5 professions to max skill takes hours.", d = "Grind five primary professions in Khaz Algar to max skill points while working underground. This is a long-term goal requiring significant profession gathering; finish before unlocking the next tier achievement.", x = 10 },
        [19559] = { e = 3, s = "c", r = "Completing 4 storylines in Azj-Kahet takes a few hours.", d = "Complete the Azj-Kahet storyline quests listed in the info field after leveling up that zone. Ensure you have access to the War Within content and follow the main story path.", x = 10 },
        [19560] = { e = 3, s = "c", r = "Completing 3 storylines in The Ringing Deeps takes a few hours.", d = "Finish all chapters of The Ringing Deeps storyline after unlocking the zone. These are sequential quests, so progress through them in order without skipping any required steps.", x = 10 },
        [19674] = { e = 2, s = "g", r = "Bronze races are short and repeatable quickly.", d = "Complete every normal skyriding race in Northrend to earn bronze medals. This requires flying across the entire region; use a fast mount and plan your route efficiently.", x = 9 },
        [19675] = { e = 3, s = "g", r = "Silver races require more time than Bronze.", d = "Repeat all Northrend normal races with silver medals after unlocking bronze. You must complete each race again with higher difficulty or faster times to progress the chain.", x = 9 },
        [19676] = { e = 4, s = "g", r = "Gold races are longer and harder than Silver.", d = "Finish all remaining Northrend normal races with gold medals after earning silver. This is the final tier for standard races; ensure you meet the strictest time requirements.", x = 9 },
        [19677] = { e = 2, s = "g", r = "Advanced Bronze races are short and repeatable.", d = "Complete all advanced skyriding races in Northrend to earn bronze medals. These are harder versions of normal races requiring precise navigation and speed.", x = 9 },
        [19679] = { e = 3, s = "g", r = "Advanced Silver races take moderate time.", d = "Repeat all Northrend advanced races with silver medals after unlocking bronze. Treat these like normal races but aim for higher performance metrics.", x = 9 },
        [19681] = { e = 4, s = "g", r = "Advanced Gold races are long and difficult.", d = "Finish all remaining Northrend advanced races with gold medals after earning silver. This is the hardest tier; practice your routes to meet the strictest time limits.", x = 9 },
        [19682] = { e = 2, s = "g", r = "Reverse Bronze races are short and repeatable.", d = "Complete all reverse skyriding races in Northrend to earn bronze medals. Reverse races often involve different paths or objectives; study the map carefully.", x = 9 },
        [19683] = { e = 3, s = "g", r = "Reverse Silver races take moderate time.", d = "Repeat all Northrend reverse races with silver medals after unlocking bronze. Maintain high performance while navigating the unique reverse race challenges.", x = 9 },
        [19684] = { e = 3, s = "c", r = "Requires completing multiple reverse races across Northrend zones.", d = "First unlock Northrend Reverse: Silver to access the Gold track. Then race every reverse event in all zones until you hit Gold on each one.", x = 9 },
        [19685] = { e = 2, s = "s", r = "Single reputation milestone achievable via routine activities.", d = "Travel to the Dragon Isles and complete the Azerothian Archives reputation grinds until you reach Tenured Archivist status.", x = 9 },
        [19704] = { e = 3, s = "c", r = "Requires learning multiple specific alchemy recipes.", d = "Learn the Algari Flask Cauldron recipe first, then craft every listed flask variant to unlock the achievement.", x = 10 },
        [19716] = { e = 3, s = "c", r = "Requires learning multiple specific alchemy recipes.", d = "Unlock the Algari Potion Cauldron and learn all required potion recipes by crafting them once for each entry.", x = 10 },
        [19719] = { e = 2, s = "s", r = "Single storyline quest chain with defined start and end.", d = "Start the Reclamation of Gilneas quest line immediately upon reaching level 60 or via the appropriate zone unlock.", x = 9 },
        [19721] = { e = 3, s = "c", r = "Requires completing all races in Northrend zones.", d = "Begin with Bronze races in Northrend, then progress through Silver and Gold tiers to complete the full chain.", x = 9 },
        [19722] = { e = 3, s = "c", r = "Requires achieving silver rank in all Northrend races.", d = "You must finish the Bronze tier first; then race every event again to earn Silver medals across all locations.", x = 9 },
        [19723] = { e = 3, s = "c", r = "Requires achieving gold rank in all Northrend races.", d = "Complete the Silver tier before attempting Gold races, ensuring you win every Northrend racing event for the title.", x = 9 },
        [19724] = { e = 4, s = "c", h = { 154674 }, r = "Mostly easy cards, but Hogger requires significant RNG luck.", d = "Purchase or earn all listed Hearthstone cards from the shop or events, noting that Hogger requires twelve copies.", x = 9 },
        [19786] = { e = 2, s = "g", r = "Simple collection task with steady progress per rock.", d = "Join Roska for Excavating around the Dragon Isles and gather ten rocks in a single session to finish this task.", x = 9 },
        [19787] = { e = 2, s = "g", r = "Simple collection task with steady progress per clue.", d = "Work with Nirobin during Research activities to discover twenty Information-Stuffed Clues scattered across the Dragon Isles.", x = 9 },
        [19788] = { e = 3, s = "c", r = "Requires collecting multiple specific tomes from activities.", d = "Participate in The Big Dig events and collect all listed dusty and preserved tomes to complete your collection.", x = 9 },
        [19789] = { e = 3, s = "g", r = "Collecting multiple relics from a specific dungeon event.", d = "Participate in The Big Dig to recover all nine relic types like jars and tablets. This is account-wide, so ensure your group completes the dig fully before logging off to avoid missing any specific items.", x = 9 },
        [19790] = { e = 4, s = "c", h = { 154861, 154862, 154859 }, r = "Requires completing several distinct archive sub-achievements.", d = "Complete every sub-achievement listed under Azerothian Archives to unlock the Isles Archivist title. Start with Relic Rescuer and Tome Comber as they form the core requirements for this collection.", x = 9 },
        [19791] = { e = 3, s = "c", h = { 154864, 154865, 154866 }, r = "Dancing with a specific NPC while doing dungeon content.", d = "Equip Technoscryers gear, use /dance on Zenata while active in The Big Dig, then kill her at any of the three locations to finish. Do not forget to dance before engaging her or you will miss the interaction.", x = 9 },
        [19792] = { e = 3, s = "c", h = { 154870, 154871, 154872 }, r = "Completing entries across multiple research sites.", d = "Finish one full entry for each site in the Tome of Archived Isles Research by Nirobin. You can do these individually, but ensure you visit all six isle sites to claim your pet Reese.", x = 9 },
        [19793] = { e = 3, s = "g", r = "Gathering a large quantity of story fragments.", d = "Collect exactly 100 entries from The Story of Traitor's Rest during The Big Dig events. This count is strict, so track your progress carefully as the achievement unlocks a specific pet upon completion.", x = 9 },
        [19871] = { e = 2, s = "s", r = "Equipping a specific cloak during a timed event.", d = "Equip the Cloak of the Infinite during the Pandaria Timewalking season to complete this step. It is account-wide and serves as the prerequisite for the next tier in the Infinite Power chain.", x = 4 },
        [19872] = { e = 3, s = "c", h = { 154912, 163957, 154911 }, r = "Completing two of several campaign or tour tasks.", d = "Use a Timerunner to complete two achievements related to The Jade Forest campaign or group content. Focus on finishing the main campaign and touring the zone to secure your reward toy quickly.", x = 4 },
        [19873] = { e = 3, s = "c", h = { 155074, 155075, 155076 }, r = "Completing two of several campaign or tour tasks.", d = "Complete two Valley of the Four Winds objectives with a Timerunner, such as finishing the campaign or doing group content twice. Prioritize the group content requirement since it often requires finding specific dungeons or events.", x = 4 },
        [19874] = { e = 3, s = "c", h = { 155696, 157220, 155697 }, r = "Completing one of several campaign or tour tasks.", d = "Finish one Krasarang Wilds achievement with a Timerunner, ideally the tour or campaign completion. This zone is smaller, so you can clear it quickly before moving to other zones in the Timewalking event.", x = 4 },
        [19875] = { e = 3, s = "c", h = { 155698, 163959, 155699 }, r = "Completing two of several campaign or tour tasks.", d = "Complete two Kun-Lai Summit achievements using a Timerunner, focusing on group content or looking for group instances. Ensure you finish at least two separate group runs to meet the requirement efficiently.", x = 4 },
        [19876] = { e = 3, s = "c", h = { 155702, 155703, 155708 }, r = "Completing two of several campaign or tour tasks.", d = "Finish two Vale of Eternal Blossoms goals with a Timerunner, including defeating Elusive Foes twice or completing Golden Lotus quests. Group up early to handle the elusive foes requirement without wasting time.", x = 4 },
        [19877] = { e = 3, s = "c", h = { 155704, 155705, 155706 }, r = "Completing two of several campaign or tour tasks.", d = "Complete two Townlong Steppes achievements with a Timerunner, such as touring the zone or defeating Shado-Pan targets twice. Coordinate with your group to clear the campaign and tour objectives in one session.", x = 4 },
        [19878] = { e = 4, s = "c", r = "Requires Timewalking event and multiple specific achievements.", d = "Queue the Dread Wastes Timewalking event with a Timerunner to complete two objectives. Focus on the campaign and tour quests first as they are straightforward. Note that this requires specific Timewalking Season access and is account-wide.", x = 4 },
        [19879] = { e = 4, s = "c", r = "Requires Timewalking event and multiple specific achievements.", d = "Start the Landfall Timewalking event with a Timerunner to earn two achievements. Prioritize Operation: Shieldwall or Dominance Offensive if you need multiple completions quickly. Remember this is account-wide and requires the correct Timewalking Season.", x = 4 },
        [19880] = { e = 3, s = "c", r = "Requires Timewalking event and one of several options.", d = "Join the Isle of Thunder Timewalking event with a Timerunner for one achievement. Complete the campaign or Looking For Group quest first as they are easier to finish solo or in small groups. Ensure you have access to the Pandaria Timewalking Season.", x = 4 },
        [19881] = { e = 4, s = "c", r = "Requires Timewalking event and three specific achievements.", d = "Queue the Escalation Timewalking event with a Timerunner to complete three achievements. Raid Finder: Siege of Orgrimmar is available but requires a full group; try Battle on the High Seas or Theramore's Fall first. This is account-wide and needs the Pandaria Timewalking Season.", x = 4 },
        [19882] = { e = 3, s = "c", r = "Requires completing multiple storylines in a Timewalking event.", d = "Complete The Jade Forest campaign with a Timerunner by doing all listed storylines in order. Start with Nectarbreeze Orchard or Tian Monastery as they unlock subsequent quests. This is account-wide and requires the Pandaria Timewalking Season.", x = 4 },
        [19883] = { e = 3, s = "c", r = "Requires completing multiple storylines in a Timewalking event.", d = "Finish The Jade Forest campaign with a Timerunner by completing all listed storylines. Begin with Dawn's Blossom or Tian Monastery to progress naturally through the zone. Remember this is account-wide and needs the Pandaria Timewalking Season.", x = 4 },
        [19884] = { e = 2, s = "c", r = "Requires completing several storylines in a Timewalking event.", d = "Complete the Valley of the Four Winds campaign with a Timerunner by doing all listed quests. Start at Thunderfoot Fields to unlock the rest of the storyline. This is account-wide and requires the Pandaria Timewalking Season.", x = 4 },
        [19885] = { e = 2, s = "c", r = "Requires completing several storylines in a Timewalking event.", d = "Finish the Krasarang Wilds campaign with a Timerunner by completing all listed storylines. Begin at Zhu's Watch or The Incursion to progress through the zone. This is account-wide and needs the Pandaria Timewalking Season.", x = 4 },
        [19886] = { e = 2, s = "c", r = "Requires completing several storylines in a Timewalking event.", d = "Complete the Krasarang Wilds campaign with a Timerunner by doing all listed quests. Start at Thunder Cleft or Dawnchaser Retreat to unlock subsequent objectives. Remember this is account-wide and requires the Pandaria Timewalking Season.", x = 4 },
        [19887] = { e = 3, s = "c", r = "Requires completing multiple storylines in a Timewalking event.", d = "Finish the Kun-Lai Summit campaign with a Timerunner by completing all listed storylines. Start with The Shado-Pan or Inkgill Mere to progress naturally through the zone. This is account-wide and needs the Pandaria Timewalking Season.", x = 4 },
        [19888] = { e = 3, s = "c", r = "Requires completing multiple storylines in a Timewalking event.", d = "Complete the Kun-Lai Summit campaign with a Timerunner by doing all listed quests. Begin at The Yak Wash or The Thunder King to unlock subsequent objectives. Remember this is account-wide and requires the Pandaria Timewalking Season.", x = 4 },
        [19889] = { e = 2, s = "c", r = "Requires completing several storylines in a Timewalking event.", d = "Finish the Townlong Steppes campaign with a Timerunner by completing all listed storylines. Start with The Sha of Hatred or Fire Camp Osul to progress through the zone. This is account-wide and needs the Pandaria Timewalking Season.", x = 4 },
        [19890] = { e = 3, s = "c", r = "Requires Timewalking event and completing multiple campaign quests.", d = "Wait for the Timewalking event to activate Dread Wastes content. Complete all listed storylines with a Timerunner before the event ends, as this is time-gated and cannot be done normally.", x = 4 },
        [19891] = { e = 3, s = "s", r = "Single campaign completion during a specific Timewalking event.", d = "Participate in the Landfall Timewalking campaign when available. Ensure you finish the entire storyline with a Timerunner before the event concludes, as this content is strictly time-limited.", x = 4 },
        [19892] = { e = 3, s = "c", r = "Requires Timewalking event and completing multiple campaign quests.", d = "Join the Isle of Thunder Timewalking event to complete all required storylines. Use a Timerunner for every objective listed, as you must finish them before the seasonal window closes.", x = 4 },
        [19893] = { e = 3, s = "s", r = "Single scenario completion during a specific Timewalking event.", d = "Complete the A Brewing Storm scenario with a Timerunner during its Timewalking week. Note that finishing this unlocks the Heroic version later in the same event chain.", x = 4 },
        [19894] = { e = 3, s = "s", r = "Single dungeon run on Normal difficulty with Timewalker.", d = "Run the Normal Temple of the Jade Serpent dungeon with a Timerunner while the Timewalking event is active. This step is required before you can attempt the Heroic version later in the event.", x = 4 },
        [19895] = { e = 3, s = "s", r = "Single dungeon run on Heroic difficulty with Timewalker.", d = "After completing the Normal run, immediately queue for Heroic Temple of the Jade Serpent with a Timerunner. Do not skip this step, as it is part of the required progression chain for the event.", x = 4 },
        [19896] = { e = 3, s = "s", r = "Single dungeon run on Normal difficulty with Timewalker.", d = "Complete Stormstout Brewery on Normal difficulty using a Timerunner during the Timewalking season. This unlocks the ability to attempt the Heroic version in the subsequent phase of the event.", x = 4 },
        [19897] = { e = 3, s = "s", r = "Single dungeon run on Heroic difficulty with Timewalker.", d = "Once you have finished the Normal run, switch to Heroic Stormstout Brewery with a Timerunner. Ensure you complete this before the Timewalking event ends to secure your reward.", x = 4 },
        [19898] = { e = 3, s = "s", r = "Single dungeon run on Normal difficulty with Timewalker.", d = "Finish Shado-Pan Monastery on Normal difficulty with a Timerunner while the event is running. This completion is mandatory to unlock and complete the Heroic version later in the chain.", x = 4 },
        [19899] = { e = 3, s = "s", r = "Single dungeon run on Heroic difficulty with Timewalker.", d = "After clearing the Normal dungeon, run Shado-Pan Monastery on Heroic with a Timerunner. Make sure to do this before the Timewalking season expires to avoid missing the achievement.", x = 4 },
        [19900] = { e = 3, s = "s", r = "Single dungeon run on Normal difficulty with Timewalker.", d = "Complete Siege of Niuzao Temple on Normal difficulty using a Timerunner during its Timewalking window. This is the prerequisite step needed to access the Heroic version later in the event.", x = 4 },
        [19901] = { e = 3, s = "s", r = "Single dungeon run on Heroic difficulty with Timewalker.", d = "Finish the Normal run first, then immediately tackle Heroic Siege of Niuzao Temple with a Timerunner. Complete both parts before the Timewalking event ends to claim your rewards.", x = 4 },
        [19902] = { e = 3, s = "c", r = "Normal dungeon with a timer; requires group.", d = "Queue for Gate of the Setting Sun during Timewalking; you must complete it with a Timerunner group. Finish the normal version first to unlock the Heroic requirement.", x = 4 },
        [19903] = { e = 4, s = "c", r = "Heroic dungeon with timer; harder RNG and mechanics.", d = "After completing Normal, queue for Heroic difficulty while still in a Timerunner group. Ensure your party composition is ready for higher difficulty mechanics.", x = 4 },
        [19904] = { e = 3, s = "c", r = "Normal dungeon with a timer; requires group.", d = "Start with Mogu'shan Palace Normal mode during the Timewalking event using a Timerunner. This unlocks the Heroic version which follows immediately after.", x = 4 },
        [19905] = { e = 4, s = "c", r = "Heroic dungeon with timer; harder RNG and mechanics.", d = "Once you finish Normal Mogu'shan Palace, switch to Heroic difficulty with a Timerunner group. Be prepared for more challenging mechanics than the normal run.", x = 4 },
        [19906] = { e = 3, s = "c", r = "Normal dungeon with a timer; requires group.", d = "Complete Scarlet Halls on Normal difficulty first while participating in Timewalking with a Timerunner. This is required before attempting the Heroic version.", x = 4 },
        [19907] = { e = 4, s = "c", r = "Heroic dungeon with timer; harder RNG and mechanics.", d = "After clearing Normal Scarlet Halls, queue for the Heroic version with a Timerunner group. Watch out for specific mechanics that differ from normal mode.", x = 4 },
        [19908] = { e = 3, s = "c", r = "Normal dungeon with a timer; requires group.", d = "Begin with Scarlet Monastery Normal during Timewalking events, ensuring you have a Timerunner in your party. Complete this before moving to Heroic difficulty.", x = 4 },
        [19909] = { e = 4, s = "c", r = "Heroic dungeon with timer; harder RNG and mechanics.", d = "Once Normal Scarlet Monastery is done, attempt the Heroic version with a Timerunner group. This dungeon has unique mechanics that require careful coordination.", x = 4 },
        [19910] = { e = 3, s = "c", r = "Normal dungeon with a timer; requires group.", d = "Start Scholomance on Normal difficulty during Timewalking with a Timerunner group to unlock the next step. Finish this before attempting Heroic mode.", x = 4 },
        [19911] = { e = 4, s = "c", r = "Heroic dungeon with timer; harder RNG and mechanics.", d = "After clearing Normal Scholomance, queue for Heroic difficulty while maintaining your Timerunner status. Be ready for tougher encounters than the normal version.", x = 4 },
        [19912] = { e = 3, s = "g", r = "Reputation grind; steady progress reduces time.", d = "Earn Exalted reputation with Order of the Cloud Serpent during Timewalking events using a Timerunner group. Focus on daily quests or world drops to gain reputation quickly.", x = 4 },
        [19913] = { e = 3, s = "g", r = "Reputation grind; steady progress reduces time.", d = "Gain Exalted status with The August Celestials while in a Timerunner group during Timewalking. Complete relevant quests or activities to reach the required reputation level.", x = 4 },
        [19914] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Join a Timewalking group in Pandaria and grind reputation with the Shado-Pan until you reach Exalted. This is time-gated to the current season, so coordinate with friends or find a guild queue to avoid missing out.", x = 4 },
        [19915] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Grind Klaxxi reputation in Pandaria Timewalking until you hit Exalted status. Ensure you are in a group during the season window, as this content is no longer accessible outside of Timewalking events.", x = 4 },
        [19916] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Earn Exalted with the Golden Lotus faction while participating in Pandaria Timewalking. Focus on daily quests and world drops to speed up reputation gains before the season ends.", x = 4 },
        [19917] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Complete Operation: Shieldwall reputation grinds in Pandaria Timewalking to reach Exalted. This faction requires specific quest chains, so check your daily objectives carefully to maximize progress.", x = 4 },
        [19918] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Grind Dominance Offensive reputation during the Pandaria Timewalking season until you achieve Exalted. Be prepared for high-level combat encounters and ensure your group composition is optimized for these raids.", x = 4 },
        [19919] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Reach Exalted with Kirin Tor Offensive by completing their reputation quests in Pandaria Timewalking. This faction often involves unique daily tasks, so prioritize them to avoid falling behind on progress.", x = 4 },
        [19920] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Earn Exalted status with Sunreaver Onslaught during the active Timewalking season. Focus on their specific reputation sources and ensure you are in a group for efficient grinding.", x = 4 },
        [19921] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Grind Shado-Pan Assault reputation to Exalted while in Pandaria Timewalking. This faction has distinct daily quests, so plan your route carefully to complete them without wasting time.", x = 4 },
        [19922] = { e = 2, s = "c", r = "Requires Exalted rep grind with a specific faction.", d = "Complete Emperor Shaohao reputation goals in Pandaria Timewalking until you reach Exalted. Coordinate with a group for the necessary scenarios and ensure you do not miss any seasonal windows.", x = 4 },
        [19923] = { e = 2, s = "c", r = "Single kill objective within a scenario instance.", d = "Join a Timewalking group to complete the Greenstone Village scenario and kill Vengeful Hui. This is time-gated content, so find a party quickly before the season concludes.", x = 4 },
        [19924] = { e = 3, s = "c", r = "Heroic difficulty adds complexity to the scenario run.", d = "Complete A Brewing Storm on Heroic difficulty with a Timewalking group to earn this achievement. Ensure your team is prepared for high-level mechanics and coordinate kills efficiently.", x = 4 },
        [19925] = { e = 2, s = "c", r = "Single kill objective within a scenario instance.", d = "Grind Unga Ingoo reputation in Pandaria Timewalking until you reach Exalted. Focus on their daily quests and world events to maximize your progress before the season ends.", x = 4 },
        [19926] = { e = 3, s = "s", r = "Timewalking scenario with a specific boss kill.", d = "Wait for the Brewmoon Festival Timewalking event to start. Complete the scenario with a Timerunner and kill Warbringer Qobi to finish.", x = 4 },
        [19927] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Participate in the Arena of Annihilation Timewalking event when available. Ensure you have a Timerunner active before entering the scenario.", x = 4 },
        [19928] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Complete the Crypt of Forgotten Kings scenario with a Timerunner during its Timewalking window. Defeat Abomination of Anger to claim your reward.", x = 4 },
        [19929] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and skill.", d = "First finish the normal Crypt of Forgotten Kings scenario, then queue for Heroic difficulty with a Timerunner. This unlocks the Lesser Bronze Cache reward.", x = 4 },
        [19930] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Wait for the Assault on Zan'vess Timewalking event to launch. Complete the scenario with a Timerunner and defeat Commander Tel'vrak.", x = 4 },
        [19931] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Complete the A Little Patience scenario with a Timerunner during its specific Timewalking season. No special requirements beyond the event window.", x = 4 },
        [19932] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Participate in the Domination Point Timewalking event when it becomes available. Complete the scenario with a Timerunner to earn your reward.", x = 4 },
        [19933] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Wait for the Dagger in the Dark Timewalking event to start. Complete the scenario with a Timerunner and finish the objective.", x = 4 },
        [19934] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Complete the Battle on the High Seas scenario as an Alliance player with a Timerunner. Defeat Admiral Hagman to progress in the chain.", x = 4 },
        [19935] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and skill.", d = "Finish the normal Battle on the High Seas first, then queue for Heroic difficulty with a Timerunner. This requires completing the normal version first.", x = 4 },
        [19936] = { e = 3, s = "s", r = "Timewalking scenario completion.", d = "Complete the Battle on the High Seas scenario as a Horde player with a Timerunner. Defeat Admiral Hodgson to advance in the achievement chain.", x = 4 },
        [19937] = { e = 4, s = "s", r = "Heroic difficulty adds significant time and skill.", d = "Finish the normal Battle on the High Seas first, then queue for Heroic difficulty with a Timerunner. This unlocks the Lesser Bronze Cache reward.", x = 4 },
        [19938] = { e = 2, s = "s", r = "Timewalking scenario with a timerunner.", d = "Queue for the Theramore's Fall Timewalking scenario during the Pandaria season. Complete it with a Timerunner to earn the achievement and cache.", x = 4 },
        [19939] = { e = 2, s = "s", r = "Timewalking scenario with a timerunner.", d = "Queue for the Theramore's Fall Timewalking scenario during the Pandaria season. Complete it with a Timerunner to earn the achievement and cache.", x = 4 },
        [19940] = { e = 2, s = "s", r = "Timewalking scenario with a timerunner.", d = "Start by completing the Blood in the Snow Timewalking scenario with a Timerunner. This unlocks the next step in the chain.", x = 4 },
        [19941] = { e = 3, s = "s", r = "Heroic Timewalking scenario requires skill.", d = "After finishing Normal Blood in the Snow, queue for the Heroic version with a Timerunner. Ensure you have completed the Normal run first.", x = 4 },
        [19942] = { e = 2, s = "s", r = "Timewalking scenario with a timerunner.", d = "Queue for the Dark Heart of Pandaria Timewalking scenario with a Timerunner. Finish it to unlock the Heroic difficulty requirement.", x = 4 },
        [19943] = { e = 3, s = "s", r = "Heroic Timewalking scenario requires skill.", d = "Complete the Normal Dark Heart of Pandaria first, then queue for the Heroic version with a Timerunner. Do not skip the Normal run.", x = 4 },
        [19944] = { e = 2, s = "s", r = "Timewalking scenario with a timerunner.", d = "Queue for the Secrets of Ragefire Timewalking scenario with a Timerunner. Finish it to unlock the Heroic difficulty requirement.", x = 4 },
        [19945] = { e = 3, s = "s", r = "Heroic Timewalking scenario requires skill.", d = "After finishing Normal Secrets of Ragefire, queue for the Heroic version with a Timerunner. Ensure you have completed the Normal run first.", x = 4 },
        [19946] = { e = 3, s = "g", r = "Kill all bosses in LFR Mogu'shan Vaults.", d = "Queue for Mogu'shan Vaults Raid Finder during the Timewalking event and defeat all listed bosses on any difficulty. This is time-gated to the specific season.", x = 4 },
        [19947] = { e = 4, s = "g", r = "Grind Normal difficulty raid bosses.", d = "Queue for Mogu'shan Vaults Normal difficulty during the Timewalking event and defeat all listed bosses. You must clear LFR first if required by progression.", x = 4 },
        [19948] = { e = 5, s = "g", r = "Heroic raid requires group and skill.", d = "Queue for Mogu'shan Vaults Heroic difficulty during the Timewalking event and defeat all listed bosses. Ensure you have cleared Normal first.", x = 4 },
        [19949] = { e = 3, s = "g", r = "Kill all bosses in LFR Heart of Fear.", d = "Queue for Heart of Fear Raid Finder during the Timewalking event and defeat all listed bosses on any difficulty. This content is time-gated to the season.", x = 4 },
        [19950] = { e = 4, s = "g", r = "Raid boss kills on Normal/Heroic require group time.", d = "Queue for Heart of Fear Timewalking on Normal or higher to defeat all listed bosses. Ensure you complete the entire raid instance as missing any boss will prevent completion.", x = 4 },
        [19951] = { e = 4, s = "g", r = "Heroic raid kills require skilled group and time.", d = "Run Heart of Fear Timewalking specifically on Heroic difficulty to clear every boss nameplate. This requires a full group and cannot be done solo or in LFR.", x = 4 },
        [19952] = { e = 3, s = "g", r = "LFR kills are easy but require multiple runs.", d = "Join any difficulty of Terrace of Endless Spring Timewalking to defeat all bosses including the final encounter. You do not need Normal or Heroic for this specific achievement.", x = 4 },
        [19953] = { e = 3, s = "g", r = "Normal raid kills take several hours of running.", d = "Queue for Terrace of Endless Spring on Normal difficulty or higher to clear all boss names. Avoid LFR if you want to ensure the difficulty requirement is met.", x = 4 },
        [19954] = { e = 4, s = "g", r = "Heroic ToES requires skilled group and multiple runs.", d = "Run Terrace of Endless Spring Timewalking on Heroic difficulty to defeat every boss listed. This is a group-only achievement requiring specific raid settings.", x = 4 },
        [19955] = { e = 3, s = "g", r = "LFR kills are straightforward but require many runs.", d = "Complete Throne of Thunder Timewalking on any difficulty setting to defeat all bosses from Jin'rokh to Lei Shen. No specific difficulty tier is required for this entry.", x = 4 },
        [19956] = { e = 3, s = "g", r = "Normal ToT requires multiple raid runs to complete.", d = "Run Throne of Thunder Timewalking on Normal or Heroic to clear all boss names. LFR will not count toward this specific achievement requirement.", x = 4 },
        [19957] = { e = 4, s = "g", r = "Heroic ToT is difficult and requires skilled group.", d = "Queue for Throne of Thunder Timewalking on Heroic difficulty to defeat every boss in the instance. Ensure your group is prepared for the higher difficulty mechanics.", x = 4 },
        [19958] = { e = 3, s = "g", r = "LFR SoO kills are easy but require many runs.", d = "Run Siege of Orgrimmar Timewalking on any difficulty to clear all bosses including Garrosh Hellscream. You can complete this in LFR without issue.", x = 4 },
        [19959] = { e = 3, s = "g", r = "Normal SoO requires multiple raid runs to complete.", d = "Complete Siege of Orgrimmar Timewalking on Normal or Heroic to defeat all listed enemies. Avoid LFR as it does not satisfy the difficulty requirement for this achievement.", x = 4 },
        [19960] = { e = 4, s = "g", r = "Heroic SoO is difficult and requires skilled group.", d = "Run Siege of Orgrimmar Timewalking on Heroic difficulty to clear every boss nameplate. This requires a coordinated group capable of handling Heroic mechanics.", x = 4 },
        [19962] = { e = 3, s = "g", r = "Exploring Jade Forest takes several hours of running.", d = "Explore the Jade Forest by defeating rare mobs, recovering treasures, and using a Timerunner to reveal hidden areas. Complete all three sub-objectives within the timed event window.", x = 4 },
        [19963] = { e = 2, s = "c", r = "Zone tour with rare kills and looting.", d = "Complete the Timewalking Season quest to unlock Valley of the Four Winds. Explore the zone, kill rare enemies, and collect all treasures while using a Timerunner to reveal hidden areas.", x = 4 },
        [19964] = { e = 2, s = "c", r = "Zone tour with rare kills and looting.", d = "Start with the Timewalking Season quest for Krasarang Wilds. Run through the zone to explore, defeat rares, and recover every treasure before the event ends.", x = 4 },
        [19965] = { e = 2, s = "c", r = "Zone tour with rare kills and looting.", d = "Begin Kun-Lai Summit via the Timewalking Season quest. You must explore the area, kill rare mobs, and gather all treasures to finish this tour achievement.", x = 4 },
        [19966] = { e = 2, s = "c", r = "Zone tour with rare kills and looting.", d = "Unlock Townlong Steppes through the Timewalking Season quest. Explore the zone, defeat rare enemies, and collect all available treasures to complete the tour.", x = 4 },
        [19967] = { e = 2, s = "c", r = "Zone tour with rare kills and looting.", d = "Start Dread Wastes with the Timewalking Season quest. Focus on exploring the area and defeating rare enemies, as collecting treasures is not required for this specific tour.", x = 4 },
        [19970] = { e = 2, s = "c", r = "Isle tour with rare kills and looting.", d = "Access the Timeless Isle via the Timewalking Season quest. Explore the island to defeat rare enemies and recover all hidden treasures to finish the tour.", x = 4 },
        [19977] = { e = 2, s = "c", r = "Find two specific items in zone.", d = "Find two specific lost treasures in the Jade Forest during Timewalking. Check common drop locations or interact with objects to locate items like the Ship's Storage or Ancient Pandaren Tea Pot.", x = 4 },
        [19978] = { e = 2, s = "c", r = "Find one specific item in zones.", d = "Locate either the Virmen Treasure Cache or The Hammer of Folly in Valley of the Four Winds. These items drop from rares or appear as world objects during Timewalking.", x = 4 },
        [19979] = { e = 2, s = "c", r = "Find one specific rare mob spawn.", d = "Search Krasarang Wilds for the Saurok Stone Tablet. This item drops from rare enemies in the zone and requires you to kill enough rares to get one copy.", x = 4 },
        [19980] = { e = 2, s = "c", r = "Find three specific items in zone.", d = "Collect three specific treasures in Kun-Lai Summit like the Hozen Treasure Cache or Statue of Xuen. Explore thoroughly and kill rares to find these items during Timewalking.", x = 4 },
        [19981] = { e = 2, s = "c", r = "Find two specific items in zone.", d = "Find two lost treasures in Townlong Steppes such as the Fragment of Dread or Hardened Sap of Kri'vess. Kill rare enemies and explore caves to locate these drops.", x = 4 },
        [19982] = { e = 2, s = "c", r = "Find four specific items on Isle.", d = "Gather four specific treasures on the Timeless Isle including the Flameheart Shawl or Gleaming Treasure Chest. Explore the island fully and defeat rares to collect all required items.", x = 4 },
        [19993] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Queue for the Pandaria Timewalking event and head to The Jade Forest. Hunt any three rare mobs listed in the info field, noting that some may require specific spawn conditions or group assistance.", x = 4 },
        [19994] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Participate in the Pandaria Timewalking event and travel to Valley of the Four Winds. Defeat three rare enemies from the provided list, keeping in mind that some targets might be elusive or require a group.", x = 4 },
        [19995] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Join the Pandaria Timewalking event and explore Krasarang Wilds. Kill three rare mobs from the info list, being aware that certain rares may only appear during specific quest chains or events.", x = 4 },
        [19996] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Enter the Pandaria Timewalking event and venture into Kun-Lai Summit. Defeat three rare enemies from the given list, watching for spawn timers or area-specific mechanics that might delay progress.", x = 4 },
        [19997] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Queue for the Pandaria Timewalking event and head to Townlong Steppes. Eliminate three rare mobs from the info list, as some may be located in hard-to-reach areas or require a group to defeat.", x = 4 },
        [19998] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Participate in the Pandaria Timewalking event and travel to the Dread Wastes. Defeat three rare enemies from the provided list, noting that some may be tied to specific world events or spawn cycles.", x = 4 },
        [19999] = { e = 2, s = "g", r = "Kill 3 faction champions; easy solo grind.", d = "Join the Pandaria Timewalking event and go to Krasarang Wilds for the Landfall achievement. You must defeat three champions from the opposing faction listed in the info field, which may require group coordination.", x = 4 },
        [20000] = { e = 2, s = "g", r = "Kill 3 rares; easy solo in Timewalking.", d = "Enter the Pandaria Timewalking event and travel to the Isle of Thunder. Defeat three rare enemies from the info list, being mindful that some are elite or have unique mechanics requiring a group.", x = 4 },
        [20001] = { e = 2, s = "c", r = "Do one of three simple tasks; low effort.", d = "Queue for the Pandaria Timewalking event and visit the Timeless Isle. Hunt three rare mobs from the provided list, as they may be scattered across different zones or require specific quest triggers to appear.", x = 4 },
        [20002] = { e = 2, s = "g", r = "Kill 3 elite rares; slightly harder but easy.", d = "Participate in the Pandaria Timewalking event on the Timeless Isle and defeat three rare elite enemies from the info list. These targets are often high-level or require a group due to their enhanced stats.", x = 4 },
        [20003] = { e = 1, s = "c", r = "Any of three simple tasks; very trivial.", d = "Complete one of the listed achievements with Timerunner during the Pandaria Timewalking event on the Timeless Isle. This is account-wide, so coordinate with friends or use a group finder to complete it efficiently.", x = 4 },
        [20004] = { e = 3, s = "c", r = "Complete 6 heroic scenarios; moderate time.", d = "Queue for the Pandaria Timewalking event and run all listed scenarios on Heroic difficulty. Some scenarios may require specific class compositions or group coordination, so plan your team accordingly before starting.", x = 4 },
        [20005] = { e = 4, s = "c", r = "Grinding 10 heroic dungeons is a multi-hour group effort.", d = "Queue for Timewalking Heroic Pandaria dungeons once the season is active. Complete all ten instances in any order, noting that some require specific dungeon finder queues or group coordination.", x = 4 },
        [20006] = { e = 3, s = "c", r = "Completing 5 normal raids takes several hours of group time.", d = "Start with Siege of Orgrimmar and Throne of Thunder during Timewalking Normal raids. Ensure you have a full group for each instance as these cannot be soloed.", x = 4 },
        [20007] = { e = 4, s = "c", r = "Grinding 5 heroic raids is a significant multi-day group grind.", d = "Queue for Timewalking Heroic Pandaria raids immediately after finishing the Normal versions. This title is account-wide, so coordinate with friends to clear all five raids efficiently.", x = 4 },
        [20008] = { e = 3, s = "c", r = "Grouping for 3 specific activities in one zone takes hours.", d = "Join a group to complete Jade Forest activities like Greenstone Village and Temple of the Jade Serpent during Timewalking. These are group-only quests that may time out if not finished quickly.", x = 4 },
        [20009] = { e = 3, s = "c", r = "Grouping for 2 specific activities in one zone takes hours.", d = "Gather a party for Valley of the Four Winds activities including Stormstout Brewery and Salyis's Warband. Be prepared to run multiple instances back-to-back as they are group-dependent.", x = 4 },
        [20011] = { e = 4, s = "c", r = "Grinding 6 varied group activities across zones is time-consuming.", d = "Complete Kun-Lai Summit group activities like Brewmoon Festival and Raid Finder: Mogu'shan Vaults during Timewalking. Note that the Sha of Anger boss fight is part of this chain.", x = 4 },
        [20012] = { e = 3, s = "c", r = "Grouping for 2 specific activities in one zone takes hours.", d = "Form a group for Townlong Steppes tasks such as Assault on Zan'vess and Siege of Niuzao Temple. These activities often require specific dungeon finder queues or organized groups.", x = 4 },
        [20014] = { e = 4, s = "c", r = "Grinding 6 varied group activities across zones is time-consuming.", d = "Queue for Vale of Eternal Blossoms group content including Scarlet Monastery and Raid Finder: Terrace of Endless Spring. Ensure you have a full party before starting these timed events.", x = 4 },
        [20015] = { e = 3, s = "c", r = "Grouping for 3 specific activities in one zone takes hours.", d = "Complete Isle of Thunder activities like Oondasta and Nalak during Timewalking. This includes the Raid Finder: Throne of Thunder which requires a coordinated group effort.", x = 4 },
        [20016] = { e = 4, s = "c", r = "Grinding 5 varied group activities on the Timeless Isle is long.", d = "Gather a party for Timeless Isle boss fights including Chi-ji, Yu'lon, and Xuen during Timewalking. These are rare encounters that may require specific quest prerequisites or group coordination.", x = 4 },
        [20017] = { e = 3, s = "s", r = "Defeating a world boss takes one session of group time.", d = "Defeat Salyis's Warband in Valley of the Four Winds as a world boss during Timewalking. Coordinate with other players to ensure you are present when the event spawns.", x = 4 },
        [20018] = { e = 3, s = "s", r = "Defeating a world boss takes one session of group time.", d = "Queue for Sha of Anger in Kun-Lai Summit during Timewalking. This is a rare world boss that requires a full group and may have limited spawn windows.", x = 4 },
        [20019] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Wait for the Timewalking Season to activate Nalak. Join a group and kill him on the Isle of Thunder; do not wait for a rare drop as he is a guaranteed world boss.", x = 4 },
        [20020] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Defeat Oondasta on the Isle of Giants during the Timewalking Season. This is a scheduled world boss event, so coordinate with friends or find a group to handle his mechanics efficiently.", x = 4 },
        [20021] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Travel to the Timeless Isle and wait for Chi-ji's spawn during the Timewalking Season. He is a world boss, so ensure you have a full party ready before he appears.", x = 4 },
        [20022] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Find Yu'lon on the Timeless Isle when the Timewalking Season is active. As a world boss, he requires a group to defeat quickly before the event timer expires.", x = 4 },
        [20023] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Locate Niuzao on the Timeless Isle during the Timewalking Season. He is a scheduled world boss, so gather your party and prepare for his specific mechanics upon spawn.", x = 4 },
        [20024] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Defeat Xuen on the Timeless Isle while the Timewalking Season is running. This world boss requires a full group to handle his phases effectively within the event window.", x = 4 },
        [20025] = { e = 3, s = "s", r = "Timewalking world boss; requires group and RNG.", d = "Kill Ordos on the Timeless Isle during the Timewalking Season. He is a world boss that spawns on a timer, so be ready with your group to avoid missing the kill.", x = 4 },
        [20026] = { e = 4, s = "c", h = { 155757 }, r = "Many points to find; one specific point is hardest.", d = "Use the Timerunner tool in Jade Forest to reveal all marked locations on the map. Ensure you visit every listed point, as some may be hidden until explored.", x = 4 },
        [20027] = { e = 4, s = "c", h = { 155832 }, r = "Many points to find; one specific point is hardest.", d = "Explore Valley of the Four Winds by visiting every location listed in the achievement info. Use the Timerunner to reveal hidden areas and ensure no points are missed.", x = 4 },
        [20028] = { e = 4, s = "c", h = { 155815 }, r = "Many points to find; one specific point is hardest.", d = "Visit all marked locations in Krasarang Wilds using the Timerunner. Some spots may be hard to reach, so check your map carefully after revealing each area.", x = 4 },
        [20029] = { e = 4, s = "c", h = { 155800 }, r = "Many points to find; one specific point is hardest.", d = "Explore Kun-Lai Summit by visiting every listed location with the Timerunner. High-level content here requires a strong group, but the achievement only needs exploration completion.", x = 4 },
        [20030] = { e = 4, s = "c", h = { 155788 }, r = "Many points to find; one specific point is hardest.", d = "Travel to Townlong Steppes and visit all marked locations using the Timerunner. This zone is high-level, so ensure your gear is sufficient before starting the exploration.", x = 4 },
        [20031] = { e = 4, s = "c", h = { 155786, 155783, 155784 }, r = "Grinding rare spawns in a timed scenario.", d = "Start this during the Pandaria Timewalking event to access Dread Wastes content. Use a Timerunner character to reveal hidden map areas efficiently. Note that specific rare enemies and scenarios must be completed within the event window.", x = 4 },
        [20033] = { e = 1, s = "g", r = "Collecting cards is quick and easy.", d = "Purchase or earn Hearthstone cards from any vendor or event to reach the 10-card goal. This is account-wide, so one character can unlock it for your entire account. Avoid missing out on limited-time card packs if you want faster progress.", x = 9 },
        [20069] = { e = 4, s = "c", h = { 156087, 156093, 156090 }, r = "Rare spawns require patience and luck.", d = "Defeat three rare enemies in the Vale of Eternal Blossoms during the Pandaria Timewalking event. These targets are often missed if not actively hunted while the zone is active. Check the achievement tracker to ensure you have killed the required specific rares.", x = 4 },
        [20118] = { e = 3, s = "c", r = "Completing storylines takes a few hours.", d = "Complete all three storylines in the Isle of Dorn expansion content. Start with Breaking Point and follow the quest chain to unlock Earthen Fissures and The First Blow. Ensure you finish these before leaving the zone or resetting your character.", x = 10 },
        [20206] = { e = 1, s = "s", r = "One specific quest to complete.", d = "Find and complete the specific quest Fair Skies and Strong Winds in Dragonflight. This grants the Champion of the Dragonflights title immediately upon completion. Verify you are on the correct faction side if the quest requires a choice.", x = 9 },
        [20209] = { e = 2, s = "g", r = "Killing a rare mob is straightforward.", d = "Locate Daetan Swiftplume during the Noblegarden event to defeat him for points. This target only appears during the specific holiday event window. Do not attempt this outside of Noblegarden as the boss will not spawn.", x = 9 },
        [20500] = { e = 4, s = "c", r = "Timed scenario with multiple rare spawns.", d = "Run the Lion's Landing scenario with a Timerunner character during the Pandaria Timewalking event. Focus on completing the scenario quickly to reveal the hidden map area. Ensure you have the necessary keys or items required for the scenario entrance.", x = 4 },
        [20501] = { e = 4, s = "c", h = { 157239, 157236, 157238 }, r = "Requires completing multiple expansion achievements.", d = "Complete all listed Shadowlands dungeon achievements before leaving that expansion content. This includes Castle Nathria and Sanctum of Domination runs. You must finish these while still in the Shadowlands era to earn the mount.", x = 9 },
        [20511] = { e = 2, s = "g", r = "Punting creatures is repetitive but fast.", d = "Use the Box of Puntables toy during Winter Veil to spawn creatures and punt them 30 times total. This is account-wide, so coordinate with friends or play solo for extended periods. The toy must be active in your inventory to spawn targets.", x = 10 },
        [20527] = { e = 4, s = "g", r = "Gathering threads requires significant time.", d = "Gather 40 Threads by completing Timewalking runs in Pandaria while using a Timerunner character. These threads carry over to future characters, so start early in the event. Do not wait until the end of the season as progress resets for new timers.", x = 4 },
        [20528] = { e = 4, s = "g", r = "Gathering more threads takes longer.", d = "Continue gathering Threads by completing more Timewalking runs after finishing Infinite Power I. Aim for 100 total threads to unlock the next tier. Progress is saved on your account, so you can switch characters if needed.", x = 4 },
        [20529] = { e = 4, s = "g", r = "Gathering even more threads is time-consuming.", d = "Gather an additional 150 Threads by running more Timewalking scenarios in Pandaria. This requires completing Infinite Power II first and is part of a chain. Ensure you are using a Timerunner to maximize thread collection efficiency.", x = 4 },
        [20530] = { e = 2, s = "g", r = "Gathering threads is a short grind.", d = "Start gathering threads after completing Infinite Power III. Farm any source that drops threads and check your total before moving to the next tier. Note that rewards apply only to future characters on your account.", x = 4 },
        [20531] = { e = 2, s = "g", r = "Slightly more gathering needed.", d = "Continue farming threads until you reach 250 for this tier. Ensure you have unlocked Infinite Power IV first. Remember these bonuses are account-wide for new characters.", x = 4 },
        [20532] = { e = 2, s = "g", r = "Continues the thread gathering grind.", d = "Gather another 50 threads to reach the 300 total required here. Complete the previous step before attempting this one. No group is needed, just consistent farming.", x = 4 },
        [20533] = { e = 2, s = "g", r = "More threads to gather still easy.", d = "Farm threads until you hit 400 total. You must finish Infinite Power VI first. This chain rewards future characters with extra thread drops automatically.", x = 4 },
        [20534] = { e = 2, s = "g", r = "Gathering continues with slight increase.", d = "Reach 500 threads by farming various sources after unlocking the prior tier. No special group is required. Keep an eye on your collection count frequently.", x = 4 },
        [20535] = { e = 2, s = "g", r = "Thread gathering remains straightforward.", d = "Gather 600 threads total after completing Infinite Power VIII. Farm efficiently as you approach this milestone. Rewards are reserved for characters created later.", x = 4 },
        [20536] = { e = 2, s = "g", r = "Another step in the thread grind.", d = "Collect 700 threads once the previous tier is done. Use any thread-dropping activity to speed up progress. Account-wide bonuses will apply to new alts.", x = 4 },
        [20537] = { e = 3, s = "g", r = "Jump in count makes it longer.", d = "This step requires a massive jump to 2200 threads. Farm intensively or use multiple characters to gather the bulk needed quickly. Ensure you have Infinite Power X completed first.", x = 4 },
        [20538] = { e = 4, s = "g", r = "Large thread count requires time.", d = "Gather the final 4200 threads for this chain after finishing the prior tier. This unlocks a specific toy reward. No group is necessary, just persistence.", x = 4 },
        [20593] = { e = 1, s = "s", r = "Quick level up with timerunner.", d = "Reach level 20 with a Timerunner during the active Timewalking season. Do not delay as the event window closes. The mount reward applies to your account.", x = 4 },
        [20594] = { e = 3, s = "g", r = "Daily task over two weeks.", d = "Visit Kaleb Flamegard in Mereldar daily for 20 days to help him. Track your progress carefully since the counter resets if you miss days. No group is needed.", x = 10 },
        [20595] = { e = 3, s = "c", h = { 161677 }, r = "Most quests are short; one is long.", d = "Complete all listed optional Isle of Dorn storylines sequentially. Check each quest description to ensure you have finished every required storyline before claiming the recliner reward.", x = 10 },
        [20596] = { e = 3, s = "c", r = "Requires completing multiple zone-specific quest chains.", d = "Start by completing the four main zone achievements first, as they unlock the Sojourner titles needed for the rest. Finish all listed quests in order to earn the Crimson Cartographer's Orientation appearance.", x = 10 },
        [20597] = { e = 3, s = "s", r = "Main storyline completion is a single major event.", d = "Begin the campaign on Isle of Dorn and progress through each major story quest sequentially. Ensure you finish the final zone content before moving on to avoid missing any storyline rewards.", x = 10 },
        [20598] = { e = 3, s = "c", r = "Requires completing multiple storylines within one zone.", d = "Complete the three specific Hallowfall quests listed in the info field to finish this storyline section. These are likely tied to local NPCs or events within that zone.", x = 10 },
        [40082] = { e = 4, s = "g", r = "Grinding specific mobs with a specific NPC nearby.", d = "Travel to the Hungering Pool in Hallowfall and kill Kobyss while standing next to Alyza Bowblaze. This is account-wide, so coordinate with a friend if you do not have Alyza available.", x = 10 },
        [40083] = { e = 2, s = "g", r = "Earning honor is fast in War Mode zones.", d = "Enable War Mode and farm honor specifically in Isle of Dorn until you reach 1000 points. Do this early as the achievement may become unavailable later.", x = 10 },
        [40084] = { e = 2, s = "g", r = "Earning honor is fast in War Mode zones.", d = "Activate War Mode and grind honor in The Ringing Deeps to hit the 1000 point threshold. This is account-wide, so any character can contribute to the progress.", x = 10 },
        [40085] = { e = 2, s = "g", r = "Earning honor is fast in War Mode zones.", d = "Turn on War Mode and earn 1000 honor points within Hallowfall. Complete this before leaving the zone or turning off War Mode to ensure it counts.", x = 10 },
        [40086] = { e = 2, s = "g", r = "Earning honor is fast in War Mode zones.", d = "Enable War Mode and accumulate 1000 honor in Azj-Kahet, which is account-wide. Farm this efficiently as part of your general level 70+ content rotation.", x = 10 },
        [40087] = { e = 3, s = "c", r = "Requires finding and completing several distinct world quests.", d = "Locate and complete each of the eight listed World PvP world quests at least once. Check your quest log regularly to ensure you have finished every unique objective.", x = 10 },
        [40088] = { e = 4, s = "g", r = "Repeating world quests five times requires significant time.", d = "Repeat each of the eight specific World PvP world quests five times total for account-wide progress. This will take significant time, so plan to do them during dedicated farming sessions.", x = 10 },
        [40089] = { e = 3, s = "c", r = "Requires capturing multiple rare/unbound items.", d = "Find and capture an Unbound Spoils item to complete this first step in the chain. You can usually find these as rare drops from world bosses or specific events.", x = 10 },
        [40090] = { e = 4, s = "g", r = "Capturing the item ten times is a long grind.", d = "Capture ten Unbound Spoils items total, building on your progress from the previous achievement. Keep an eye on rare drop notifications to maximize efficiency.", x = 10 },
        [40091] = { e = 3, s = "c", r = "Requires opening one item in each of the four zones.", d = "Open Unbound Spoils in Isle of Dorn, The Ringing Deeps, Hallowfall, and Azj-kahet to complete this account-wide task. Ensure you visit each zone as the specific items may not drop or open if missed during initial exploration.", x = 10 },
        [40097] = { e = 4, s = "c", r = "Must complete multiple distinct World PvP achievements first.", d = "Finish all listed World PvP achievements like Unbound Battle and the various Tour of Duty quests in the Dragon Isles. This is a group-heavy requirement, so coordinate with friends or guild members to tackle these high-level objectives efficiently.", x = 10 },
        [40138] = { e = 5, s = "c", r = "Requires running all dungeons as Tank, Healer, and DPS.", d = "Run every Khaz Algar dungeon on Mythic or Mythic+ difficulty while playing as a Tank, Healer, and DPS separately. You must complete the full set for each role, which may require multiple characters or extensive solo playtesting if you lack a group.", x = 10 },
        [40139] = { e = 4, s = "c", r = "Must defeat every War Within dungeon as a Damage Dealer.", d = "Defeat all War Within dungeons at Mythic or M+ difficulty specifically as a Damage Dealer to earn this title. Start by queuing with a group or finding a party finder group that accepts your class and spec.", x = 10 },
        [40140] = { e = 4, s = "c", r = "Must defeat every War Within dungeon as a Healer.", d = "Complete every Khaz Algar dungeon on Mythic or M+ while playing as a Healer to fulfill this requirement. Coordinate with healers in your guild or use the party finder to ensure you can run all listed dungeons in this role.", x = 10 },
        [40141] = { e = 4, s = "c", r = "Must defeat every War Within dungeon as a Tank.", d = "Run all War Within dungeons on Mythic or M+ difficulty specifically as a Tank to achieve this goal. You will need to queue for groups that require tanking, so be prepared to adapt your gear and playstyle accordingly.", x = 10 },
        [40142] = { e = 1, s = "g", r = "Buy one tab; trivial if gold is available.", d = "Purchase your first tab in the Warband Bank to start this character-specific chain. This is an account-wide achievement, so ensure you have enough gold or resources available before attempting to buy the initial tab.", x = 10 },
        [40145] = { e = 2, s = "g", r = "Buy five tabs; easy grind with sufficient gold.", d = "Buy five tabs in the Warband Bank after completing the previous step to finish this milestone. Plan your spending carefully as this requires significant resources and may take time depending on your current economy status.", x = 10 },
        [40146] = { e = 2, s = "s", r = "Equipping gear is easy if items are available.", d = "Equip a Superior or better item with at least 564 item level in every gear slot to unlock this legacy achievement. Check your inventory for any missing slots and prioritize upgrading those areas first.", x = 10 },
        [40147] = { e = 2, s = "s", r = "Equipping gear is easy if items are available.", d = "Equip an Epic or better item with at least 584 item level in every slot to complete this legacy goal. Focus on acquiring higher-tier gear through dungeons, raids, or world drops to meet the item level threshold.", x = 10 },
        [40150] = { e = 3, s = "c", r = "Play eight specific games with orphans in Mereldar.", d = "Play every game listed with the orphans of Mereldar, including variations like Tag and Hide and Seek. Visit the orphanage regularly to interact with NPCs and trigger these mini-games as they become available.", x = 10 },
        [40151] = { e = 2, s = "c", r = "Interact with several objects to set a bad example.", d = "Interact with specific locations like the Orphanage Window and Food Stall to set a bad example for this exploration achievement. Make sure to visit all listed points of interest in Mereldar to avoid missing any interactions.", x = 10 },
        [40153] = { e = 3, s = "c", h = { 161728 }, r = "Requires collecting 8 specific pets first.", d = "Start by completing the initial World Quest to unlock the quest line, then gather your full team of level 25 pets before tackling the remaining eight quests. Ensure you have all required NPCs like Awakened Custodian and Ziriak available, as this is account-wide and cannot be missed once started.", x = 10 },
        [40154] = { e = 3, s = "c", h = { 161733 }, r = "Needs specific aquatic pets and defeating trainers.", d = "Focus exclusively on recruiting or evolving Aquatic pets to level 25 before engaging any trainers in Khaz Algar. Defeat each trainer sequentially while maintaining your all-Aquatic team composition to avoid failing the requirement.", x = 10 },
        [40155] = { e = 3, s = "c", h = { 161738 }, r = "Needs specific beast pets and defeating trainers.", d = "Prioritize leveling Beast-type pets to level 25 and verify your roster contains only Beasts before attempting the trainer battles. Do not mix species, or you will fail the achievement despite winning the fights.", x = 10 },
        [40156] = { e = 3, s = "c", h = { 161743 }, r = "Needs specific critter pets and defeating trainers.", d = "Gather Critter pets and bring them all to level 25 before starting the trainer challenges in Khaz Algar. Keep your team pure to Critters throughout the entire sequence to satisfy the specific category requirement.", x = 10 },
        [40157] = { e = 3, s = "c", h = { 161748 }, r = "Needs specific dragonkin pets and defeating trainers.", d = "Collect Dragonkin pets and evolve or level them to 25 before confronting the trainers. Maintain a strict Dragonkin-only team during battles, as mixing types will void the achievement progress.", x = 10 },
        [40158] = { e = 3, s = "c", h = { 161753 }, r = "Needs specific elemental pets and defeating trainers.", d = "Assemble a full team of Elemental pets at level 25 and defeat each trainer in Khaz Algar without switching categories. This is account-wide, so ensure your main character's collection supports the requirement.", x = 10 },
        [40161] = { e = 3, s = "c", h = { 161758 }, r = "Needs specific flying pets and defeating trainers.", d = "Recruit Flying pets and bring them all to level 25 before engaging trainers. Keep your team strictly Flying throughout the battles, as using ground-based pets will fail the achievement.", x = 10 },
        [40162] = { e = 3, s = "c", h = { 161763 }, r = "Needs specific humanoid pets and defeating trainers.", d = "Level Humanoid pets to 25 and ensure your battle team consists solely of Humanoids before starting the trainer fights. Avoid including any other species in your active lineup during these encounters.", x = 10 },
        [40163] = { e = 3, s = "c", h = { 161768 }, r = "Needs specific magic pets and defeating trainers.", d = "Gather Magic pets and evolve them to level 25 prior to facing the trainers. Maintain a pure Magic team composition during all battles to successfully complete this specific category achievement.", x = 10 },
        [40164] = { e = 3, s = "c", h = { 161773 }, r = "Needs specific mechanical pets and defeating trainers.", d = "Collect Mechanical pets and bring them all to level 25 before attempting the trainer battles in Khaz Algar. Ensure your active team contains only Mechanical types to avoid failing the requirement.", x = 10 },
        [40165] = { e = 3, s = "c", h = { 161778 }, r = "Needs specific undead pets and defeating trainers.", d = "Assemble a full team of Undead pets at level 25 and defeat each trainer without mixing species. This is account-wide, so coordinate with friends if you lack enough Undead pets in your collection.", x = 10 },
        [40166] = { e = 2, s = "c", r = "Discovering glyphs is moderate but not hard.", d = "Discover all ten specified Skyriding Glyphs in Isle of Dorn by exploring the zone thoroughly. Use a flying mount to access high areas and check each glyph location carefully, as missing one will require revisiting the zone later.", x = 10 },
        [40194] = { e = 3, s = "g", r = "Collecting many pets requires time and RNG.", d = "Farm pets in Khaz Algar zones like the Greenlands and Arathi Highlands. Use a high-level pet battle team to catch rare spawns quickly, as some are time-gated or missable if you leave the area.", x = 10 },
        [40210] = { e = 2, s = "s", r = "Single win is easy for skilled players.", d = "Queue for Deephaul Ravine in PvP and focus on securing objectives fast. Do not let the enemy capture any mine carts to progress toward the shutout achievement later.", x = 10 },
        [40211] = { e = 3, s = "g", r = "Grinding to 100 wins takes time.", d = "Play Deephaul Ravine repeatedly until you hit 100 wins. This is purely a grind requiring consistent queue time and good team coordination to maintain victory momentum.", x = 10 },
        [40215] = { e = 3, s = "s", r = "Perfect play is hard but single event.", d = "Prioritize defending your mine carts above all else during Deephaul Ravine matches. If you lose control of any cart, reset the match immediately to try again for this specific goal.", x = 10 },
        [40216] = { e = 3, s = "s", r = "Speed run requires skill and luck.", d = "Play Deephaul Ravine with a high-level team capable of quick kills. Aim to clear objectives and win before the seven-minute timer expires to secure this speed-based point.", x = 10 },
        [40217] = { e = 3, s = "s", r = "Fast BG win is hard but single event.", d = "Queue for Battleground Blitz matches and rush objectives immediately. You must win within six minutes, so avoid prolonged fights or unnecessary exploration that wastes time.", x = 10 },
        [40219] = { e = 4, s = "c", h = { 162097, 162103 }, r = "Maps vary; some are harder than others.", d = "Unlock all Battleground Blitz maps first, then practice winning each one under seven minutes. This requires mastering map-specific strategies and maintaining high team performance across every location.", x = 10 },
        [40220] = { e = 3, s = "g", r = "Grinding matches takes significant time.", d = "Participate in Battleground Blitz matches consistently to reach the three-hundred-match milestone. Treat this as a long-term commitment requiring regular queue sessions over many weeks or months.", x = 10 },
        [40221] = { e = 3, s = "g", r = "Grinding to 150 wins takes time.", d = "Focus on winning fifteen Battleground Blitz matches total. Coordinate with teammates to secure quick victories and track your win count carefully to avoid missing the target.", x = 10 },
        [40222] = { e = 4, s = "c", h = { 162223 }, r = "Rare spawns and RNG make this hard.", d = "Complete Worldsoul Memory events in Khaz Algar on Radiant Discord difficulty. Defeat twenty specific rare creatures that spawn during these timed events, as they are missable if you fail to kill them quickly.", x = 10 },
        [40223] = { e = 5, s = "s", r = "Timewalking requires specific season access.", d = "Play Timewalking events in Pandaria and level your character to seventy. Ensure you complete the required journey steps while leveling up to claim the title and item rewards.", x = 4 },
        [40231] = { e = 3, s = "c", h = { 167679 }, r = "Exploring zones is moderate effort.", d = "Explore all major zones of Khaz Algar including the Isle of Dorn and Azj-Kahet. Complete sub-achievements for each zone first to unlock this overarching exploration goal efficiently.", x = 10 },
        [40232] = { e = 5, s = "c", h = { 162373, 162374, 162375 }, r = "Raid achievements require high-level gear and group coordination.", d = "Complete all listed achievements in the Nerub-ar Palace raid to earn this title. Since it is account-wide, ensure your entire group finishes every boss on any difficulty before moving on.", x = 10 },
        [40236] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Defeat Ulgrax the Devourer specifically on Mythic difficulty. This requires completing the Heroic version first and is part of the main raid progression chain.", x = 10 },
        [40237] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Kill The Bloodbound Horror on Mythic difficulty after clearing Heroic. Treat this as a standard boss kill within the larger Nerub-ar Palace progression sequence.", x = 10 },
        [40238] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Defeat Sikran, Captain of the Sureki on Mythic difficulty. Ensure you have cleared the Heroic version first to unlock this specific achievement requirement.", x = 10 },
        [40239] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Kill Rasha'nan on Mythic difficulty as part of the raid's progression. This is a standard boss kill that unlocks after completing the Heroic tier.", x = 10 },
        [40240] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Defeat Broodtwister Ovi'nax on Mythic difficulty. Note that this replaces the Eggtender Ovi'nax achievement from earlier expansions, so focus solely on the new boss.", x = 10 },
        [40241] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Kill Nexus-Princess Ky'veza on Mythic difficulty. This is a standard raid boss kill that requires you to have completed the Heroic tier first.", x = 10 },
        [40242] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Defeat The Silken Court on Mythic difficulty. Treat this as a multi-boss encounter or specific raid phase requiring full group coordination on Mythic settings.", x = 10 },
        [40243] = { e = 5, s = "s", r = "Mythic raid boss requires a full group and high skill.", d = "Kill Queen Ansurek on Mythic difficulty to earn the Queenslayer title. This is the final boss of the raid and requires prior completion of Heroic difficulties.", x = 10 },
        [40244] = { e = 5, s = "c", h = { 162292, 162293, 162294 }, r = "Requires defeating all bosses on any difficulty first.", d = "Defeat all bosses in Nerub-ar Palace on any difficulty to unlock this base achievement. Start with Normal or Heroic before attempting Mythic for subsequent rewards.", x = 10 },
        [40245] = { e = 5, s = "c", h = { 162301, 162302, 162303 }, r = "Requires defeating all bosses on Heroic difficulty first.", d = "Clear all bosses on Heroic difficulty before moving to Mythic. This is a mandatory step in the progression chain and unlocks the next tier of achievements.", x = 10 },
        [40246] = { e = 5, s = "c", h = { 162310, 162311, 162312 }, r = "Requires defeating all bosses on Mythic difficulty first.", d = "Defeat all bosses on Mythic difficulty after clearing Heroic. This is the final tier of the Nerub-ar Palace raid and requires a full group capable of high-level mechanics.", x = 10 },
        [40247] = { e = 3, s = "c", r = "Kill 3 raid bosses; requires group and dungeon key.", d = "This is a standard Wing 1 completion achievement requiring you to defeat Ulgrax the Devourer, The Bloodbound Horror, and Sikran. Ensure you clear all three bosses in Nerub-ar Palace on Normal or higher difficulty to earn these points.", x = 10 },
        [40248] = { e = 3, s = "c", r = "Kill 3 raid bosses; requires group and dungeon key.", d = "Complete this by defeating Rasha'nan, Broodtwister Ovi'nax, and Nexus-Princess Ky'veza within Wing 2 of the raid. These are standard encounters, so focus on clearing the wing without missing any boss kills.", x = 10 },
        [40249] = { e = 3, s = "c", r = "Kill 2 raid bosses; requires group and dungeon key.", d = "Finish this achievement by defeating The Silken Court and Queen Ansurek in Wing 3. This is a straightforward progression step after completing previous wings of Nerub-ar Palace.", x = 10 },
        [40250] = { e = 1, s = "s", r = "Complete one event; trivial once zone is accessible.", d = "Start by locating any Radiant Echo event in Khaz Algar and complete it once to unlock the next tier. These events are account-wide, so you can help friends if needed.", x = 10 },
        [40251] = { e = 3, s = "g", r = "Grind 25 events; effort shrinks steadily with progress.", d = "After unlocking the previous achievement, you must complete a total of 25 Worldsoul Memory events in Khaz Algar. Keep track of your count as these do not stack with other echoes.", x = 10 },
        [40252] = { e = 1, s = "c", r = "Complete 8 specific events; trivial once zone is accessible.", d = "You must complete every single listed Radiant Echo event in Khaz Algar to finish this collection. Check the map for all available locations and ensure you visit each one at least once.", x = 10 },
        [40255] = { e = 3, s = "s", r = "Specific mechanic on one boss; requires group and key.", d = "Defeat Sikran on Normal or higher while ensuring every player is affected by Riposte before killing her. This requires coordination during the fight to maintain the debuff on the entire group.", x = 10 },
        [40260] = { e = 3, s = "s", r = "Specific mechanic on two bosses; requires group and key.", d = "For this achievement, get all players Slimed and then defeat a Volatile Ooze before killing The Bloodbound Horror. Coordinate with your raid to apply the slime debuff consistently throughout the encounter.", x = 10 },
        [40261] = { e = 3, s = "s", r = "Specific mechanic on one boss; requires group and key.", d = "Keep the Spider Silk Grub alive while defeating Ulgrax the Devourer on Normal or higher. Avoid damaging the grub during the fight and ensure it survives until the boss is defeated.", x = 10 },
        [40262] = { e = 3, s = "s", r = "Specific mechanic on one boss; requires group and key.", d = "Ride a single wave for every cast of Rolling Acid with all players present when defeating Rasha'nan. This requires careful positioning and timing to surf each acid wave as it spawns.", x = 10 },
        [40263] = { e = 3, s = "s", r = "Specific mechanic on one boss; requires group and key.", d = "Interact with a Disheartened Worm using the /love command from everyone in your raid before defeating Broodtwister Ovi'nax. Make sure all players complete this interaction during the fight.", x = 10 },
        [40264] = { e = 3, s = "s", r = "Specific mechanic on one boss; requires group and key.", d = "Maintain Nexus-Princess Ky'veza's Kill Streak buff while defeating her on Normal or higher. Avoid taking damage or dying to prevent breaking the streak before the boss is killed.", x = 10 },
        [40266] = { e = 5, s = "s", r = "Raid boss fight with specific mechanic timing.", d = "Defeat Queen Ansurek on Normal or higher difficulty, ensuring your entire group uses Abyssal Conduits to travel underneath her during the Frothing Gluttony phase. This is a raid-specific mechanic that requires coordination and cannot be completed solo or with insufficient dungeon gear.", x = 10 },
        [40307] = { e = 4, s = "c", h = { 162486 }, r = "Main campaign storylines are long and mandatory.", d = "Complete all listed War Within storylines including Mourning Rise, Broken Tools, and Merrix and Steelvein to unlock the Earthen race. These quests are account-wide and must be finished before you can create a new Earthen character for the next achievement.", x = 10 },
        [40308] = { e = 4, s = "g", r = "Requires collecting many Radiant Remnants from zones.", d = "Gather Radiant Remnants from various sources to light lesser keyflames and finish the associated quests like Web of Manipulation and Harvest Havoc. This is an account-wide objective that progresses as you explore zones and complete daily activities.", x = 10 },
        [40309] = { e = 2, s = "s", r = "Create and level a new character to 50.", d = "Create a new Earthen character and level it to 50 to earn the Heritage Armor. You must first unlock the Earthen race by completing the previous storyline achievements, so plan your leveling path accordingly.", x = 10 },
        [40311] = { e = 3, s = "c", h = { 168069 }, r = "Multiple zone events; one is rare spawn based.", d = "Visit larger activated Keyflames in each zone to complete bonus events such as Bleak Sand and Waters of War. These are account-wide tasks that require you to interact with specific world events rather than just finishing quests.", x = 10 },
        [40312] = { e = 3, s = "g", r = "Collect 10 items via various zone activities.", d = "Collect 10 Radiant Remnants and contribute them to any keyflame to start the chain. This is a simple gathering task that can be done while exploring zones or completing other objectives in the War Within campaign.", x = 10 },
        [40313] = { e = 4, s = "g", r = "Requires significantly more items than previous step.", d = "Accumulate 100 Radiant Remnants total across all keyflames to progress further. Since this builds on the previous achievement, ensure you have already contributed the initial 10 remnants before attempting this milestone.", x = 10 },
        [40314] = { e = 3, s = "c", r = "Find one fragment in each of the four zones.", d = "Loot and shatter Echoing Fragments found in Worldsoul Memory events within each zone like Hallowfall and Azj-Kahet. These fragments are account-wide rewards that grant a toy once all zones are completed.", x = 10 },
        [40316] = { e = 2, s = "g", r = "Complete standard skyriding routes multiple times.", d = "Complete all normal skyriding races in Isle of Dorn to earn Bronze status, starting with routes like Dornogal Drift and Storm's Watch Survey. This is the first tier of the achievement chain and must be finished before moving to Silver.", x = 10 },
        [40317] = { e = 2, s = "g", r = "Repeat bronze routes with higher speed requirement.", d = "Achieve Silver rank on all normal Isle of Dorn skyriding races by improving your times from Bronze. You cannot start this until you have fully completed the Bronze tier, so focus on optimizing your routes first.", x = 10 },
        [40318] = { e = 2, s = "g", r = "Repeat silver routes with even higher speed.", d = "Reach Gold status across all normal Isle of Dorn skyriding races after unlocking Silver. This requires mastering every route efficiently, as Gold demands significantly faster completion times than lower tiers.", x = 10 },
        [40319] = { e = 2, s = "g", r = "Complete advanced skyriding routes efficiently.", d = "Finish all advanced skyriding races in Isle of Dorn to earn Bronze for the advanced tier. These routes are separate from normal ones and require completing specific challenges before progressing further.", x = 10 },
        [40320] = { e = 3, s = "c", r = "Grind multiple races; moderate time.", d = "Start this after unlocking Isle of Dorn Advanced Bronze. Complete every advanced race on the map to earn silver points. This is account-wide and requires no group, but you must finish all tracks before moving to Gold.", x = 10 },
        [40321] = { e = 3, s = "c", r = "Grind multiple races; moderate time.", d = "Unlock this only after finishing Isle of Dorn Advanced Silver. Repeat the same advanced races to earn gold points for each track. No group is needed, but ensure you have completed all previous tiers first.", x = 10 },
        [40322] = { e = 3, s = "c", r = "Grind multiple reverse races.", d = "Begin reverse races in Isle of Dorn once you have unlocked the Bronze tier. Fly every reverse route to complete the set. This is account-wide and does not require a group or specific drop rates.", x = 10 },
        [40323] = { e = 3, s = "c", r = "Grind multiple reverse races.", d = "Progress from Reverse Bronze to Silver by completing all reverse races in Isle of Dorn again. No group is required, but you must finish the entire set before advancing to Gold.", x = 10 },
        [40324] = { e = 3, s = "c", r = "Grind multiple reverse races.", d = "Unlock this after finishing Isle of Dorn Reverse Silver. Complete every reverse race to earn gold points. This is account-wide and requires no group, but time gating applies between tiers.", x = 10 },
        [40325] = { e = 3, s = "c", r = "Grind multiple normal races.", d = "Start normal races in The Ringing Deeps after unlocking the Bronze tier. Fly all listed routes to complete the set. This is account-wide and does not require a group or rare drops.", x = 10 },
        [40326] = { e = 3, s = "c", r = "Grind multiple normal races.", d = "Advance from The Ringing Deeps Bronze to Silver by completing all normal races again. No group is needed, but you must finish the entire set before moving to Gold.", x = 10 },
        [40327] = { e = 3, s = "c", r = "Grind multiple normal races.", d = "Unlock this after finishing The Ringing Deeps Silver. Repeat all normal races to earn gold points. This is account-wide and requires no group, but ensure you have completed all previous tiers first.", x = 10 },
        [40328] = { e = 3, s = "c", r = "Grind multiple advanced races.", d = "Begin advanced races in The Ringing Deeps once the Bronze tier is unlocked. Complete every advanced route to earn points. This is account-wide and does not require a group or specific drop rates.", x = 10 },
        [40329] = { e = 3, s = "c", r = "Grind multiple advanced races.", d = "Progress from Advanced Bronze to Silver by completing all advanced races in The Ringing Deeps again. No group is required, but you must finish the entire set before advancing to Gold.", x = 10 },
        [40330] = { e = 3, s = "c", r = "Grind multiple advanced races.", d = "Unlock this after finishing The Ringing Deeps Advanced Silver. Complete every advanced race to earn gold points. This is account-wide and requires no group, but time gating applies between tiers.", x = 10 },
        [40331] = { e = 3, s = "c", r = "Grind multiple reverse races.", d = "Start reverse races in The Ringing Deeps after unlocking the Bronze tier. Fly all reverse routes to complete the set. This is account-wide and does not require a group or rare drops.", x = 10 },
        [40332] = { e = 3, s = "g", r = "Requires completing multiple timed races with RNG elements.", d = "Start with the bronze race to unlock silver and gold tiers. Complete all seven individual reverse races in The Ringing Deeps before moving up.", x = 10 },
        [40333] = { e = 3, s = "g", r = "Requires completing multiple timed races with RNG elements.", d = "You must finish the silver tier first. Run every reverse race again to earn the gold medals for this zone.", x = 10 },
        [40334] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Begin with normal races in Hallowfall to unlock higher tiers. Ensure you complete all seven standard tracks before attempting silver.", x = 10 },
        [40335] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Finish the bronze tier first, then repeat all normal races for silver. This unlocks the path to gold medals later.", x = 10 },
        [40336] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Complete the silver tier before attempting gold. Run every normal race in Hallowfall again to secure the gold achievement.", x = 10 },
        [40337] = { e = 3, s = "g", r = "Advanced courses require more skill and time than normal ones.", d = "Start advanced races immediately after unlocking them. Finish all seven advanced tracks to progress from bronze to silver.", x = 10 },
        [40338] = { e = 3, s = "g", r = "Advanced courses require more skill and time than normal ones.", d = "You must finish the bronze tier first. Repeat every advanced race in Hallowfall to earn the required silver medals.", x = 10 },
        [40339] = { e = 3, s = "g", r = "Advanced courses require more skill and time than normal ones.", d = "Complete the silver tier before attempting gold. Run all advanced races again to secure the final gold achievement for this zone.", x = 10 },
        [40340] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Start reverse races in Hallowfall after unlocking them. Finish all seven reverse tracks to progress from bronze to silver.", x = 10 },
        [40341] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Finish the bronze tier first, then repeat every reverse race for silver. This unlocks the path to gold medals later.", x = 10 },
        [40342] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Complete the silver tier before attempting gold. Run all reverse races again to secure the final gold achievement for this zone.", x = 10 },
        [40343] = { e = 2, s = "g", r = "Multiple standard races are generally quick to complete.", d = "Start with normal races in Azj-Kahet to unlock higher tiers. Ensure you complete all seven standard tracks before attempting silver.", x = 10 },
        [40344] = { e = 2, s = "c", r = "Requires unlocking and completing several simple skyriding races.", d = "Unlock Azj-Kahet: Bronze first, then grind normal races on every race to earn silver. This is account-wide but requires completing specific twist and plunge challenges repeatedly.", x = 10 },
        [40345] = { e = 2, s = "c", r = "Requires unlocking and completing several slightly harder skyriding races.", d = "After earning silver, repeat the same normal races again to obtain gold status for all characters. Ensure you have unlocked the prerequisite silver tier before attempting this.", x = 10 },
        [40346] = { e = 2, s = "c", r = "Requires unlocking and completing several advanced skyriding races.", d = "Complete every advanced race in Azj-Kahet on each character to unlock bronze. These are harder versions of standard tracks and must be done individually per account.", x = 10 },
        [40347] = { e = 2, s = "c", r = "Requires unlocking and completing several harder advanced skyriding races.", d = "Grind all advanced races again to reach silver status, following the bronze completion requirement. Focus on mastering the more difficult course layouts for efficiency.", x = 10 },
        [40348] = { e = 2, s = "c", r = "Requires unlocking and completing the hardest advanced skyriding races.", d = "Finish the final tier of advanced races to earn gold and unlock the title. This completes the full advanced progression chain across all characters.", x = 10 },
        [40349] = { e = 2, s = "c", r = "Requires unlocking and completing several reverse skyriding races.", d = "Start by completing every reverse race in Azj-Kahet on each character for bronze. Reverse tracks often require different strategies than standard forward routes.", x = 10 },
        [40350] = { e = 2, s = "c", r = "Requires unlocking and completing several harder reverse skyriding races.", d = "Repeat the reverse races to earn silver, ensuring you have the bronze prerequisite unlocked first. Consistent practice is key due to the unique reverse mechanics.", x = 10 },
        [40351] = { e = 2, s = "c", r = "Requires unlocking and completing the hardest reverse skyriding races.", d = "Complete all reverse races one last time to achieve gold status and finish the reverse tier. This finalizes your mastery of Azj-Kahet's alternate course directions.", x = 10 },
        [40352] = { e = 2, s = "c", r = "Requires completing all Khaz Algar and Azj-Kahet skyriding chains.", d = "Finish every race type in Khaz Algar including normal, advanced, and reverse on all characters for bronze. This massive achievement requires extensive grinding across multiple zones.", x = 10 },
        [40353] = { e = 2, s = "c", r = "Requires unlocking silver versions of all Khaz Algar and Azj-Kahet chains.", d = "Grind through all Khaz Algar races again to earn silver after unlocking bronze. Be prepared for significant time investment as this covers every track variant in the region.", x = 10 },
        [40354] = { e = 2, s = "c", r = "Requires unlocking gold versions of all Khaz Algar and Azj-Kahet chains.", d = "Complete the final set of Khaz Algar races to earn gold and unlock the title. This is a long-term goal requiring completion of all previous tiers first.", x = 10 },
        [40360] = { e = 2, s = "c", r = "Requires completing a series of simple farm-themed quests.", d = "Start with Seeds of Evil and follow Miral's questline to complete farm-related objectives. These quests are tied to specific NPCs and locations within the Hillhelm Stead area.", x = 10 },
        [40361] = { e = 2, s = "s", r = "Single boss kill on normal difficulty.", d = "Start by defeating Goldie Baronbottom on Normal difficulty to unlock the next tier. This is a straightforward dungeon clear with no special mechanics to worry about initially.", x = 10 },
        [40363] = { e = 3, s = "s", r = "Requires Heroic dungeon completion first.", d = "Return to Cinderbrew Meadery and queue for Heroic mode to defeat Goldie Baronbottom again. Ensure your group is prepared for increased damage and mechanics before attempting this step.", x = 10 },
        [40366] = { e = 4, s = "s", r = "Requires Mythic dungeon completion first.", d = "You must first complete the Heroic version of Cinderbrew Meadery before unlocking Mythic. Defeat Goldie Baronbottom on Mythic difficulty once that prerequisite is met.", x = 10 },
        [40370] = { e = 2, s = "s", r = "Single boss kill on normal difficulty.", d = "Begin your progress by defeating Ki'katal the Harvester in Ara-Kara, City of Echoes on Normal difficulty. This clears the first requirement for the subsequent Heroic achievement.", x = 10 },
        [40374] = { e = 3, s = "s", r = "Requires Heroic dungeon completion first.", d = "After clearing Normal mode, defeat Ki'katal the Harvester on Heroic difficulty to unlock Mythic. Make sure your group composition can handle the higher difficulty scaling.", x = 10 },
        [40375] = { e = 4, s = "s", r = "Requires Mythic dungeon completion first.", d = "Complete the Heroic version of Ara-Kara first, then defeat Ki'katal the Harvester on Mythic or Mythic Keystone. This final step requires a well-coordinated group for maximum difficulty.", x = 10 },
        [40376] = { e = 2, s = "s", r = "Single boss kill on normal difficulty.", d = "Defeat Izo, the Grand Splicer in City of Threads on Normal difficulty to start the chain. There are no specific prerequisites other than accessing the dungeon.", x = 10 },
        [40377] = { e = 3, s = "s", r = "Requires Heroic dungeon completion first.", d = "Queue for Heroic mode in City of Threads and defeat Izo, the Grand Splicer again. Ensure your team is ready for the increased challenge before attempting this run.", x = 10 },
        [40379] = { e = 4, s = "s", r = "Requires Mythic dungeon completion first.", d = "Unlock Mythic difficulty by first completing the Heroic version of City of Threads. Defeat Izo, the Grand Splicer on Mythic once that requirement is satisfied.", x = 10 },
        [40382] = { e = 1, s = "s", r = "Short quest storyline with no grind.", d = "Complete the entire Hunt the Harbinger storyline to earn this achievement. Follow the quest chain carefully as missing steps will prevent you from finishing the objective.", x = 9 },
        [40427] = { e = 2, s = "s", r = "Single boss kill on normal difficulty.", d = "Defeat The Darkness in Darkflame Cleft on Normal difficulty to unlock the next tier. This is a standard dungeon clear with no hidden prerequisites mentioned.", x = 10 },
        [40428] = { e = 3, s = "s", r = "Requires Heroic dungeon completion first.", d = "Return to Darkflame Cleft and defeat The Darkness on Heroic difficulty or higher. Ensure your group has the necessary gear and skill level for this increased challenge.", x = 10 },
        [40429] = { e = 3, s = "s", r = "Requires Mythic difficulty boss kill; moderate effort.", d = "You must defeat The Darkness boss on Mythic difficulty after unlocking Heroic. This is a time-gated achievement requiring the expansion's release and sufficient gear progression.", x = 10 },
        [40430] = { e = 2, s = "g", r = "Visit flight masters; easy solo exploration grind.", d = "Travel to all listed flight masters in Khaz Algar to unlock their points. Visit each location sequentially to ensure you do not miss any hidden or hard-to-reach paths.", x = 10 },
        [40434] = { e = 2, s = "g", r = "Collect unique treasures; easy solo exploration grind.", d = "Explore the Isle of Dorn thoroughly to find unique treasures like chests and orbs. This is account-wide, so coordinate with friends if some items are rare drops.", x = 10 },
        [40435] = { e = 3, s = "g", r = "Complete 10 special encounters; moderate solo grind.", d = "Locate and complete ten special encounters across the Isle of Dorn. These often require specific quest triggers or defeating elite mobs in designated zones.", x = 10 },
        [40436] = { e = 2, s = "s", r = "Complete one delve; easy solo activity.", d = "Simply complete any single delve to earn this achievement. Start with lower-tier delves if you are new to the mechanic to learn the flow.", x = 10 },
        [40437] = { e = 3, s = "g", r = "Complete multiple delves; moderate solo grind.", d = "Finish all listed War Within delves on any difficulty. You can mix and match difficulties across different delves as long as you complete every single one.", x = 10 },
        [40438] = { e = 4, s = "c", h = { 166621 }, r = "Requires Loremaster title and multiple delves; hard.", d = "Complete various delve achievements including finding treasures and defeating seasonal bosses. Note that some rewards like mounts require finishing the entire list first.", x = 10 },
        [40445] = { e = 3, s = "g", r = "Complete Fungarian delve without spores; moderate grind.", d = "Run a Fungarian delve on Tier 8 or higher without taking explosive spore damage. Use defensive cooldowns and avoid standing in green areas during the encounter.", x = 10 },
        [40447] = { e = 3, s = "g", r = "Complete delves on Tier 4+ with lives; moderate grind.", d = "Complete all listed delves on Tier 4 or higher while keeping at least one life remaining. This requires careful resource management and avoiding unnecessary deaths.", x = 10 },
        [40448] = { e = 4, s = "g", r = "Complete delves on Tier 8+ with lives; hard grind.", d = "Finish the same delve list as the previous tier but on Tier 8 or higher with lives left. Ensure your group composition can handle the increased difficulty safely.", x = 10 },
        [40449] = { e = 5, s = "g", r = "Complete delves on Tier 11 with lives; very hard.", d = "Complete all delves on the maximum Tier 11 difficulty while maintaining at least one life. This is a significant challenge requiring optimized builds and coordination.", x = 10 },
        [40450] = { e = 2, s = "g", r = "Raise companion to level 20; easy solo grind.", d = "Raise your companion to level 20 by completing its daily quests and gaining experience. Monitor the companion's progress closely as it may take time to reach this cap.", x = 10 },
        [40451] = { e = 2, s = "g", r = "Grinding companion XP is easy but takes time.", d = "Complete Buddy System II first, then grind companion XP until level 30. This is account-wide and chains directly to the next tier.", x = 10 },
        [40453] = { e = 3, s = "s", r = "Requires specific tier and avoiding mechanics once.", d = "Run a Tier 8+ Nerubian delve while avoiding webs and eggs to prevent ambushers or damage. Clear the web spawns quickly before they trigger enemies.", x = 10 },
        [40454] = { e = 3, s = "s", r = "Requires specific tier and avoiding mechanics once.", d = "Finish an Order of Night delve on Tier 8+ without taking artillery fire. Stay mobile and avoid standing in open areas where cannons target you.", x = 10 },
        [40455] = { e = 2, s = "g", r = "Grinding companion XP is easy but takes time.", d = "Start by leveling your companion to level 10 as the first step in the Buddy System chain. This unlocks higher-level companion achievements.", x = 10 },
        [40456] = { e = 3, s = "g", r = "Higher level grinding takes more time than low levels.", d = "After reaching level 30, continue grinding XP to hit level 40 for this next tier. Ensure you have completed Buddy System III first.", x = 10 },
        [40457] = { e = 3, s = "g", r = "Higher level grinding takes more time than low levels.", d = "Push your companion from level 40 to 50 to unlock the final tier of the standard chain. Keep using companions in delves for efficient XP.", x = 10 },
        [40458] = { e = 2, s = "g", r = "Defeating disturbances is a short, repeatable task.", d = "Defeat strange disturbances ten times across any delve type. These appear randomly, so run multiple delves and clear them quickly when they spawn.", x = 10 },
        [40459] = { e = 3, s = "s", r = "Requires obtaining a specific item from a quest chain.", d = "Obtain the Delver's Dirigible by completing specific unlock conditions within the game. This item is required before you can progress to Flying in Style.", x = 10 },
        [40460] = { e = 2, s = "g", r = "Completing 10 delves is a short, repeatable task.", d = "Complete ten total delves to finish this milestone. You must have unlocked the initial delve ability before starting this counter.", x = 10 },
        [40461] = { e = 3, s = "g", r = "Higher level grinding takes more time than low levels.", d = "Level your companion from 50 to 60 after finishing Buddy System V. This is account-wide and leads directly into the Valeera companion tier.", x = 10 },
        [40462] = { e = 3, s = "g", r = "Completing 50 delves is a moderate grind.", d = "Grind delves until you reach fifty total completions. Track your count carefully as this requirement stacks with previous delve achievements.", x = 10 },
        [40463] = { e = 4, s = "g", r = "Completing 100 delves is a long grind.", d = "Continue running delves to hit one hundred total completions. This is a long-term goal that requires consistent daily delve runs over time.", x = 10 },
        [40464] = { e = 3, s = "g", r = "Requires killing 50 players in War Mode; RNG and PvP skill dependent.", d = "Enable War Mode and hunt players in high-traffic areas to quickly loot bounties, as this is a grind that requires many kills.", x = 10 },
        [40465] = { e = 3, s = "c", h = { 163777 }, r = "Requires bounties in all zones; Isle of Dorn is the hardest zone.", d = "Visit every zone listed in The War Within while in War Mode to find bounty hunters, ensuring you do not miss any region.", x = 10 },
        [40466] = { e = 2, s = "g", r = "Open 10 crates; easy to get with Warband sharing loot.", d = "Open War Supply Crates by defeating enemies or completing objectives; this is a simple count that does not require specific gear.", x = 10 },
        [40467] = { e = 3, s = "g", r = "Open 25 crates; requires more time than the previous tier.", d = "Continue opening crates until you reach 25 total, building on the previous crate achievement for faster completion.", x = 10 },
        [40468] = { e = 1, s = "g", r = "Open 5 crates; trivial if you have Warband sharing enabled.", d = "Start by opening five War Supply Crates while in War Mode to unlock the next tier of this crate chain.", x = 10 },
        [40469] = { e = 3, s = "s", r = "Collect a full set from Nerub-ar Palace; requires dungeon runs.", d = "Farm Nerub-ar Palace content to collect a full Tier 32 armor set on at least one character to complete this collection.", x = 10 },
        [40473] = { e = 2, s = "c", h = { 163877 }, r = "Repair 6 consoles; Abyssal Console is the hardest to find.", d = "Locate and repair all six busted earthen consoles in The Ringing Deeps, checking each zone for the specific console locations.", x = 10 },
        [40475] = { e = 2, s = "c", h = { 164089 }, r = "Love critters; Cavern Mote is the hardest to find in Ringing Deeps.", d = "Use the /love command on every critter in The Ringing Deeps, including rare ones, to complete this exploration task.", x = 10 },
        [40476] = { e = 2, s = "g", r = "Use 10 Seekerthreads; easy with Warband sharing and fishing.", d = "Gather Algari Seekerthread and use it at the fishing station to unlock the next stage of your Algari Weaverline power.", x = 10 },
        [40480] = { e = 3, s = "g", r = "Use 20 Seekerthreads; requires more time than the previous tier.", d = "Collect more Seekerthread and spin twenty units into your line, continuing the progression chain for increased fishing efficiency.", x = 10 },
        [40484] = { e = 3, s = "g", r = "Use 30 Seekerthreads; requires more time than the previous tier.", d = "Accumulate thirty Seekerthreads and apply them to your line, advancing further in the Algari Weaverline upgrade sequence.", x = 10 },
        [40485] = { e = 3, s = "g", r = "Use 40 Seekerthreads; requires more time than the previous tier.", d = "Finish by using forty Seekerthreads on your line, completing the full progression of this fishing profession achievement chain.", x = 10 },
        [40487] = { e = 3, s = "g", r = "Grinding 50 items is moderate effort.", d = "Fish for Algari Seekerthread until you have 50, then use them at the Algari Weaverline. This is account-wide and chains directly to the next tier, so do not stop early.", x = 10 },
        [40488] = { e = 3, s = "g", r = "Grinding 60 items is moderate effort.", d = "Gather another 10 Seekerthread on top of your previous total to reach 60 for this upgrade. Continue fishing until you hit the next threshold.", x = 10 },
        [40489] = { e = 3, s = "g", r = "Grinding 70 items is moderate effort.", d = "Spin 70 Algari Seekerthreads at the Weaverline after completing the 60 tier. Keep fishing to unlock the subsequent reward in this chain.", x = 10 },
        [40490] = { e = 3, s = "g", r = "Grinding 80 items is moderate effort.", d = "Use 80 Seekerthreads to upgrade your line again. This step requires you to fish out ten more threads before spinning at the interface.", x = 10 },
        [40491] = { e = 3, s = "g", r = "Grinding 90 items is moderate effort.", d = "Collect 90 Algari Seekerthread total and spin them in. You must complete the previous tier first to unlock this specific achievement.", x = 10 },
        [40492] = { e = 3, s = "g", r = "Grinding 100 items is moderate effort.", d = "Fish until you possess 100 Algari Seekerthread, then use them all at once. This final step in the Seekerthread chain grants a permanent power boost.", x = 10 },
        [40494] = { e = 3, s = "g", r = "Grinding 10 items is moderate effort.", d = "Start by gathering 10 Algari Anglerthread and spinning them immediately. Do not confuse these with Seekerthreads, as they are separate materials for the same line.", x = 10 },
        [40495] = { e = 3, s = "g", r = "Grinding 20 items is moderate effort.", d = "After completing the 10 tier, fish for another 10 Anglerthread to reach 20. The interface will only accept this amount once the previous tier is done.", x = 10 },
        [40496] = { e = 3, s = "g", r = "Grinding 60 items is moderate effort.", d = "Spin 60 Anglerthreads after finishing the 50 tier. Ensure you have collected enough threads from fishing zones before attempting to spin this large batch.", x = 10 },
        [40497] = { e = 3, s = "g", r = "Grinding 30 items is moderate effort.", d = "Use 30 Anglerthreads once you have completed the 20 tier. This intermediate step is part of a long progression chain for your fishing gear.", x = 10 },
        [40498] = { e = 3, s = "g", r = "Grinding 70 items is moderate effort.", d = "Gather 70 Anglerthread total and spin them at the Weaverline. You must finish the 60 tier first to make this achievement available.", x = 10 },
        [40499] = { e = 3, s = "g", r = "Grinding 40 items is moderate effort.", d = "Spin 40 Anglerthreads after reaching the 30 tier. Treat this as a standard progression step where you simply need to fish for more material.", x = 10 },
        [40500] = { e = 3, s = "g", r = "Grinding 80 specific threads takes several hours.", d = "Fish Algari Anglerthread and use it at the Algari Weaverline to unlock this tier. Since rewards share across your Warband, coordinate with friends to speed up collection.", x = 10 },
        [40501] = { e = 3, s = "g", r = "Grinding 100 specific threads takes several hours.", d = "Continue fishing for Algari Anglerthread until you have enough to spin 100 units at the Algari Weaverline. This is a straightforward grind that benefits from group coordination.", x = 10 },
        [40502] = { e = 3, s = "g", r = "Grinding 50 specific threads takes a few hours.", d = "Start by collecting and spinning 50 Algari Anglerthreads at the Algari Weaverline to unlock this tier. It is an early step in the progression chain for your fishing gear.", x = 10 },
        [40503] = { e = 3, s = "g", r = "Grinding 90 specific threads takes several hours.", d = "Fish up 90 Algari Anglerthreads and spin them into your Algari Weaverline to complete this achievement. Ensure you have enough materials before attempting the next tier in the chain.", x = 10 },
        [40504] = { e = 3, s = "c", r = "Reading plaques on scattered inert earthen takes moderate time.", d = "Travel to the inert earthen locations listed in the info field and read their plaques to unlock Rocked to Sleep. This is a static collection task with no time limit.", x = 10 },
        [40506] = { e = 4, s = "g", r = "Finding chests in all delves requires significant grinding.", d = "Run through all War Within delves and open every Sturdy Chest you find to earn the Seeker of Loot title. Be thorough as missing a chest in any delve will prevent completion.", x = 10 },
        [40507] = { e = 3, s = "s", r = "Completing one specific world quest instance takes moderate time.", d = "Complete the Ringing Deeps world quest Reaching for Resources while leaping to 25 handholds or fewer. Monitor your leap count carefully during the quest to meet this specific condition.", x = 10 },
        [40512] = { e = 3, s = "s", r = "Completing one Tier 2 delve instance takes a few hours.", d = "Unlock Tier 1 delves first, then complete a Tier 2 delve to earn these points and unlock Tier 3 content. This is a linear progression requirement for the delve system.", x = 10 },
        [40514] = { e = 3, s = "s", r = "Completing one Tier 3 delve instance takes a few hours.", d = "Finish all Tier 2 delves before attempting Tier 3, as this achievement requires prior completion of the lower tier. Once unlocked, simply complete any available Tier 3 delve.", x = 10 },
        [40523] = { e = 3, s = "c", r = "Collecting various curios takes moderate time across zones.", d = "Purchase or obtain every curio available for Brann Bronzebeard from the appropriate vendors to unlock On Brand. Check all relevant vendors in your capital cities for missing items.", x = 10 },
        [40524] = { e = 3, s = "g", r = "Completing 5 specific quests takes a few hours total.", d = "Accept and complete five Delver's Call quests found throughout The War Within zones. These quests appear periodically, so check your quest log regularly for new opportunities.", x = 10 },
        [40525] = { e = 3, s = "c", r = "Completing multiple story variants in one delve takes moderate time.", d = "Run through Fungal Folly multiple times to experience each unique story variant listed in the info field. You must complete every specific scenario to finish this achievement.", x = 10 },
        [40526] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Run Kriegval's Rest multiple times to unlock every story variant. Ensure you finish all four specific objectives in each run before exiting.", x = 10 },
        [40527] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Complete Earthcrawl Mines repeatedly until you have finished all five story variants. Check your tracker after each run to see what is missing.", x = 10 },
        [40528] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Finish The Waterworks delve several times to unlock its four story variants. Make sure to complete every objective within a single run.", x = 10 },
        [40529] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Run The Dread Pit until you have completed all four story variants. Do not restart the delve until you have finished the current set of objectives.", x = 10 },
        [40530] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Complete Nightfall Sanctum multiple times to unlock its four story variants. Finish every objective in one run before leaving the instance.", x = 10 },
        [40531] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Run Mycomancer Cavern repeatedly to finish all three story variants. Ensure you complete every task before exiting the delve.", x = 10 },
        [40532] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Finish The Sinkhole delve several times to unlock its four story variants. Complete all objectives in a single run without restarting.", x = 10 },
        [40533] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Run Skittering Breach multiple times to complete all four story variants. Make sure to finish every objective before leaving the instance.", x = 10 },
        [40534] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Complete The Underkeep delve repeatedly until you have finished all four story variants. Finish all tasks in one run to unlock them.", x = 10 },
        [40535] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Run Tak-Rethan Abyss several times to unlock its four story variants. Ensure you complete every objective before exiting the delve.", x = 10 },
        [40536] = { e = 2, s = "c", r = "Complete several story variants in a single delve.", d = "Finish The Spiral Weave multiple times to complete all four story variants. Do not restart until you have finished the current set of objectives.", x = 10 },
        [40537] = { e = 3, s = "c", r = "Requires completing all previous individual story achievements.", d = "Unlock every other delve achievement first, then run each specific delve repeatedly to finish all its story variants. Finally, complete the remaining unique delves listed in the info field.", x = 10 },
        [40538] = { e = 1, s = "s", r = "Level a single NPC to 25 via simple quests.", d = "Complete Brann Development by raising Brann Bronzebeard to level 25 using any available leveling methods. This achievement is account-wide and does not require specific group composition or rare drops.", x = 10 },
        [40539] = { e = 3, s = "g", r = "Catch many specific fish within a time limit.", d = "Start The Derby Dash immediately after unlocking the Mereldar Fishing Derby profession node to catch all listed fish within the time limit. Note that this is account-wide and requires catching specific rare fish like the Kaheti Slum Shark.", x = 10 },
        [40542] = { e = 3, s = "c", h = { 165880 }, r = "Read many books; one part requires specific quest.", d = "Read all required Azj-Kahet books while under the effects of Polymorphic Translation to complete Smelling History. Ensure you have access to the translation buff before attempting to read any of the listed texts.", x = 10 },
        [40585] = { e = 2, s = "g", r = "Collect a common item from world drops.", d = "Obtain 100 Odd Glob of Wax by farming them from relevant sources in Khaz Algar. This achievement is account-wide and requires no specific group or time limit.", x = 10 },
        [40590] = { e = 3, s = "s", r = "Defeat a dungeon boss on normal difficulty.", d = "Defeat Prioress Murrpray in the normal difficulty of Priory of the Sacred Flame to start the dungeon chain. Complete this before moving on to Heroic or Mythic versions.", x = 10 },
        [40592] = { e = 3, s = "s", r = "Defeat the same boss on Heroic difficulty.", d = "Progress to Heroic: Priory of the Sacred Flame after completing the normal version by defeating Prioress Murrpray again. You must finish the normal difficulty first before unlocking this tier.", x = 10 },
        [40596] = { e = 4, s = "s", r = "Requires Mythic dungeon completion and skill.", d = "Complete Mythic: Priory of the Sacred Flame only after finishing Heroic, as it requires the previous tier to be unlocked. Defeat Prioress Murrpray on Mythic or Mythic Keystone difficulty.", x = 10 },
        [40599] = { e = 3, s = "s", r = "Defeat a new dungeon boss on normal difficulty.", d = "Defeat Rasha'nan in The Dawnbreaker normal difficulty to begin the dungeon progression chain. This is the first step before attempting Heroic or Mythic versions of the dungeon.", x = 10 },
        [40601] = { e = 3, s = "s", r = "Defeat the same boss on Heroic difficulty.", d = "Unlock and complete Heroic: The Dawnbreaker after finishing the normal version by defeating Rasha'nan again. Ensure you have completed the base difficulty before attempting this tier.", x = 10 },
        [40604] = { e = 4, s = "s", r = "Requires Mythic dungeon completion and skill.", d = "Finish Mythic: The Dawnbreaker only after completing Heroic, as it is locked behind the previous tier. Defeat Rasha'nan on Mythic or Mythic Keystone difficulty to earn the points.", x = 10 },
        [40606] = { e = 1, s = "s", r = "Die to a specific environmental hazard once.", d = "Become a victim of a workplace accident in the Forgegrounds of Dornogal by dying to the Forgegrounds Press. This is an exploration achievement that requires being killed by the specific environmental hazard.", x = 10 },
        [40607] = { e = 2, s = "g", r = "Capture rare crystals in an open world zone.", d = "Capture a Deephaul Crystal on Deephaul Ravine to start the Wandering in the Ravine chain. This is the first step in a series of achievements for this zone.", x = 10 },
        [40608] = { e = 3, s = "g", r = "Grinding crystals 10 times in a PvP zone.", d = "Start by capturing the flag in Deephaul Ravine. This is a PVP zone requiring you to grab the crystal ten times, so expect other players to try stopping you.", x = 10 },
        [40612] = { e = 3, s = "g", r = "Grinding crystals 50 times in a PvP zone.", d = "Continue playing Deephaul Ravine until you have captured the flag fifty times total. You will receive a Decord reward upon completion, but be prepared for intense PVP combat throughout.", x = 10 },
        [40613] = { e = 4, s = "c", r = "Requires surviving while carrying the flag 3 times.", d = "Play a single match in Deephaul Ravine where you capture the flag three times without dying. This requires careful positioning and avoiding enemy damage while carrying the crystal.", x = 10 },
        [40614] = { e = 2, s = "s", r = "Simple interaction with an NPC and mob.", d = "Find Ethereal Glimmerlings in Hallowfall and bring them to Glublurp. These creatures are rare spawns, so you may need to explore thoroughly or wait for specific conditions.", x = 10 },
        [40615] = { e = 3, s = "g", r = "Grinding kills against players exiting carts.", d = "Kill players who have just exited an Earthen Mine Cart in Deephaul Ravine. Wait near cart exit points to catch opponents with the exhaustion debuff easily.", x = 10 },
        [40616] = { e = 3, s = "g", r = "Grinding kills against players exiting carts (x20).", d = "Repeat the previous task twenty times to complete this chain. It is account-wide, so coordinate with friends or play solo until you reach the kill count.", x = 10 },
        [40617] = { e = 5, s = "c", r = "Requires completing multiple difficult Deephaul achievements.", d = "Complete all listed Deephaul Ravine achievements first, including the Veteran and Perfection titles. This unlocks the Deephauler title once every prerequisite is met.", x = 10 },
        [40618] = { e = 2, s = "s", r = "Simple quest to return items to an NPC.", d = "Return any lost Hallowfall memento items to Maera Ashyld immediately after finding them. Do not lose track of these items as they are required for this specific quest line.", x = 10 },
        [40620] = { e = 3, s = "g", r = "Grinding rescues of prisoners in a zone.", d = "Rescue fifty Arathi prisoners located in Arathi's End. Search the area thoroughly and prioritize freeing captives to reach the total count efficiently.", x = 10 },
        [40621] = { e = 3, s = "s", r = "Defeating a specific boss in a dungeon.", d = "Defeat Voidstone Monstrosity inside The Rookery dungeon. This is a standard dungeon boss fight, so ensure your group composition is ready for normal difficulty first.", x = 10 },
        [40622] = { e = 3, s = "c", r = "Finding multiple lore books across the zone.", d = "Locate every lore book scattered across Hallowfall. Check hidden corners and interact with NPCs to find these items, as missing one will prevent completion.", x = 10 },
        [40623] = { e = 2, s = "s", r = "Completing a specific world quest objective.", d = "Gather all ten ore types for the Courier Mission world quest in Taelloch. Deposit them all at once to complete the achievement without needing multiple trips.", x = 10 },
        [40624] = { e = 1, s = "c", r = "Wave to nearby rats; trivial and quick.", d = "Wave to all listed weave-rats in the War Within zone. This is account-wide and requires no group, but ensure you interact with every named rat to avoid missing any.", x = 10 },
        [40625] = { e = 1, s = "c", r = "Pet cats in one zone; very easy.", d = "Pet every warcat NPC listed around Hallowfall. Since this is account-wide, coordinate with friends if some cats are missed on your character.", x = 10 },
        [40628] = { e = 1, s = "c", r = "Read notes in one area; trivial.", d = "Read all six fragments of Notes On Machine Speakers in The Ringing Deeps. These notes may be scattered, so thoroughly search the area.", x = 10 },
        [40629] = { e = 2, s = "c", r = "Read books while polymorphed; easy solo.", d = "Consume Polymorphic Translation buffs and read the three Entomological Essay books on Grubs. Do not finish reading before applying the buff or the achievement will fail.", x = 10 },
        [40630] = { e = 3, s = "g", r = "Grind ore for contraptions; moderate effort.", d = "Participate in the Courier Mission: Ore Recovery world quest ten times to contribute 100 ore each time. This is account-wide, so help friends reach their goals faster.", x = 10 },
        [40631] = { e = 2, s = "s", r = "Complete one delve; easy solo.", d = "Complete any Tier 1 delve to unlock Tier 2 content. You can do this solo or in a group; just ensure the delve finishes successfully.", x = 10 },
        [40632] = { e = 2, s = "c", r = "Follow spiders and return copies; easy.", d = "Follow the spiders in Pillar-nest Xesh and return evil copies of yourself to their books. This is account-wide, so check your other characters for progress.", x = 10 },
        [40633] = { e = 3, s = "g", r = "Grind stacks in two zones; moderate.", d = "Farm Unseeming Shift stacks in either the Maddening Deep or Writhing Fields until you have 100. These areas are likely instanced, so run them repeatedly.", x = 10 },
        [40634] = { e = 2, s = "s", r = "Get kicked out once; easy.", d = "Trigger the event where guards expel you from the City of Threads. This is account-wide, so ensure your character gets kicked out to complete it.", x = 10 },
        [40635] = { e = 3, s = "c", r = "Collect curios for Brann; moderate grind.", d = "Rank up Brann Bronzebeard and collect all available curios at rank 4. This requires being on Brand, so check if that zone is accessible.", x = 10 },
        [40636] = { e = 3, s = "c", r = "Complete multiple optional storylines; moderate.", d = "Complete every optional Azj-Kahet storyline listed in the achievement info. These are likely quest chains, so follow them sequentially to avoid missing steps.", x = 10 },
        [40637] = { e = 4, s = "s", r = "Defeat raid boss on Heroic; hard.", d = "Defeat Voidstone Monstrosity in The Rookery on Heroic difficulty or higher. This is account-wide, so coordinate with a group to handle the boss efficiently.", x = 10 },
        [40642] = { e = 4, s = "s", r = "Requires Mythic+ dungeon completion; significant time investment.", d = "Complete Heroic The Rookery first to unlock the boss. Then run Mythic with a group to defeat Voidstone Monstrosity for this achievement.", x = 10 },
        [40643] = { e = 2, s = "s", r = "Heroic dungeon boss kill; straightforward but requires gear.", d = "This is a standard dungeon kill; ensure you have unlocked Heroic The Rookery first if required by the chain. Run it normally to finish.", x = 10 },
        [40644] = { e = 3, s = "s", r = "Heroic+ difficulty adds some challenge to a standard dungeon.", d = "You must clear The Stonevault on Heroic difficulty before attempting this. Use a group to defeat Void Speaker Eirich on Heroic or higher.", x = 10 },
        [40648] = { e = 5, s = "s", r = "Mythic difficulty requires high skill and coordination.", d = "Clear Heroic The Stonevault first as a prerequisite. Then run Mythic difficulty with a full group to defeat the boss for this title.", x = 10 },
        [40661] = { e = 2, s = "s", r = "Simple event interaction; time depends on luck/timing.", d = "Use a pet disguise and hold a stationary pose or move slowly to stay zoomed for over 20 seconds. This tracks account-wide so play with friends.", x = 10 },
        [40662] = { e = 3, s = "s", r = "Specific world boss encounter; requires group coordination.", d = "Locate and defeat the Awakened Phalanx within the Awakening The Machine dungeon instance. This is a single-player friendly objective once inside.", x = 10 },
        [40702] = { e = 5, s = "c", h = { 166395 }, r = "Multiple zones required; one zone likely has difficult mechanics.", d = "Unlock all four regional Glyph Hunter achievements in Khaz Algar first. Then discover glyphs across Isle of Dorn, The Ringing Deeps, Hallowfall, and Azj-Kahet.", x = 10 },
        [40703] = { e = 3, s = "g", r = "Requires finding specific glyphs across multiple locations.", d = "Fly over every named location listed in The Ringing Deeps to find hidden skyriding glyphs. Use the map or exploration tools to locate each spot.", x = 10 },
        [40704] = { e = 3, s = "g", r = "Requires finding specific glyphs across multiple locations.", d = "Explore Hallowfall thoroughly and fly near every listed zone name to discover the required skyriding glyphs. Ensure you visit all specific locations listed.", x = 10 },
        [40705] = { e = 3, s = "g", r = "Requires finding specific glyphs across multiple locations.", d = "Travel to Azj-Kahet and hover over each named area like Arathi's End or Rak-Ush to find the hidden glyphs. Check your map for completion.", x = 10 },
        [40723] = { e = 5, s = "s", r = "Requires completing a Mythic raid boss; high difficulty.", d = "Unlock Mythic VFX first, then complete one listed feat like Queen Ansurek or a Season Keystone run. This rewards a catalyst stone and is account-wide.", x = 10 },
        [40724] = { e = 3, s = "g", r = "Requires finding multiple hidden items across the zone.", d = "Explore The Ringing Deeps thoroughly to find hidden chests and treasures. Use flying mounts to check hard-to-reach spots for the unique items listed.", x = 10 },
        [40725] = { e = 2, s = "s", r = "Complete main story campaign; requires level 80.", d = "Reach level 80 and finish the Khaz Algar main story campaign on your Warband to unlock Tier 4 delves. This is account-wide, so ensure you are in a group that can complete the final campaign segment together.", x = 10 },
        [40727] = { e = 1, s = "s", r = "Ride NPC once; trivial and instant.", d = "Ride the High Hollows Skittershaw once for a full lap around the district. There are no specific pitfalls, but ensure you mount the creature and let it complete one full circuit without dismounting.", x = 10 },
        [40728] = { e = 3, s = "c", r = "Collect full PvP set; RNG dependent.", d = "Collect any armor set from The War Within PvP Season 1 to earn these points. Since this is account-wide, coordinate with friends who have access to the PvP season rewards if needed.", x = 10 },
        [40729] = { e = 3, s = "s", r = "Win one Hard mode game; moderate skill.", d = "Win a single game of Light's Gambit on Hard Difficulty to complete this achievement. No specific strategy is required beyond winning the match, so practice your mechanics beforehand.", x = 10 },
        [40730] = { e = 4, s = "c", r = "Defeat boss after specific quest chain.", d = "Defeat Silken Court in Nerub-ar Palace after bonding Anub'arash and Takazj on Normal difficulty or higher. Ensure both pets are bonded before attempting the final boss encounter.", x = 10 },
        [40731] = { e = 2, s = "g", r = "Land 10 hits; fast grind in zone.", d = "Land 10 hits with Frying Pans dropped by Overworked Cooks in Deepforge Golemworks. This is account-wide, so group up to farm these mobs efficiently without missing drops.", x = 10 },
        [40732] = { e = 2, s = "s", r = "Get killed once by specific enemy.", d = "Get killed by a Delve Nemesis to complete this objective. Be cautious not to die from other sources, as only deaths inflicted by the specific Nemesis boss count toward the achievement.", x = 10 },
        [40762] = { e = 3, s = "c", r = "Find many scattered lore objects.", d = "Discover all listed lore objects across Khaz Algar regions like Hallowfall and Azj-Kahet. Use exploration tools or guides to locate hidden items, as missing any object will prevent completion.", x = 10 },
        [40763] = { e = 2, s = "g", r = "Loot 25 curiosities; steady progress.", d = "Loot 25 mislaid curiosities within delves by thoroughly searching chests and containers. This is account-wide, so ensure you are in a delve where these items can drop consistently.", x = 10 },
        [40788] = { e = 3, s = "g", r = "Open 50 coffers; requires keys/grind.", d = "Open 50 Bountiful Coffers using Restored Coffer Keys obtained from delves. Prioritize completing delves that yield keys to avoid running out of resources before reaching the goal.", x = 10 },
        [40789] = { e = 2, s = "c", r = "Collect multiple cosmetic parts.", d = "Collect all cosmetic unlocks for the Delver's Dirigible, including parts like exhausts and paint jobs. These items are often tied to specific delve rewards or events, so check your inventory regularly.", x = 10 },
        [40790] = { e = 3, s = "c", r = "Explore four distinct regions.", d = "Explore all four regions of Khaz Algar: Isle of Dorn, Ringing Deeps, Hallowfall, and Azj-Kahet. Use the map interface to track progress and ensure no region is left unexplored before finishing.", x = 10 },
        [40791] = { e = 3, s = "c", r = "Requires completing multiple campaign storylines.", d = "Complete the Fate of the Kirin Tor campaign quests Arcane Desolation and Strength Amidst Ruins to earn this title. Ensure you finish all required storylines as this cannot be done retroactively.", x = 10 },
        [40799] = { e = 3, s = "c", r = "Requires completing many optional side quests.", d = "Finish every optional Ringing Deeps side quest listed in the achievement info while on Z2 content. This is account-wide and missable if you do not complete the specific side quests before moving on.", x = 10 },
        [40803] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Open all five Sturdy Chests hidden within the Fungal Folly delve to claim these points. Check each chest location carefully as missing one will prevent completion.", x = 10 },
        [40806] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Locate and open every Sturdy Chest in Earthcrawl Mines for this discovery achievement. These chests are account-wide so ensure your character or an alt opens them all.", x = 10 },
        [40807] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Find the four Sturdy Chests hidden inside Kriegval's Rest delve to complete this objective. Explore thoroughly as these chests often require specific triggers to open.", x = 10 },
        [40808] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Open all Sturdy Chests found in Mycomancer Cavern to earn these points. Be prepared for potential time gating if the delve content is not yet available.", x = 10 },
        [40809] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Search Nightfall Sanctum for its four hidden Sturdy Chests and open them to finish this achievement. Do not skip any area within the delve as chests may be scattered.", x = 10 },
        [40810] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Complete Skittering Breach by opening all four Sturdy Chests located throughout the instance. Ensure you have cleared all enemies before attempting to open these locked containers.", x = 10 },
        [40811] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Open the four Sturdy Chests hidden in Tak-Rethan Abyss to claim this discovery. This delve may require specific conditions to access its deepest areas where chests reside.", x = 10 },
        [40812] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Find and open all four Sturdy Chests inside The Dread Pit delve. Some chests might be behind destructible walls or require defeating a boss first.", x = 10 },
        [40813] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Locate the four Sturdy Chests in The Sinkhole delve and open them to complete this objective. Pay attention to environmental hazards that could block your path.", x = 10 },
        [40814] = { e = 2, s = "g", r = "Grinding for chests in a single delve.", d = "Open all four Sturdy Chests hidden within The Spiral Weave delve for this achievement. These chests are account-wide so coordinate with friends if needed.", x = 10 },
        [40815] = { e = 2, s = "c", r = "Find and open 4 chests in a single delve.", d = "Complete all four Sturdy Chests in The Underkeep delve. This is account-wide and requires finding specific hidden chests within the instance.", x = 10 },
        [40816] = { e = 2, s = "c", r = "Find and open 4 chests in a single delve.", d = "Find and open the four Sturdy Chests located inside The Waterworks delve. Ensure you clear the entire area to locate these hidden containers.", x = 10 },
        [40817] = { e = 3, s = "g", r = "Grind for 10 Hidden Troves via Delver's Bounties.", d = "Use Delver's Bounties to find and open ten Hidden Troves. These are account-wide, so coordinate with other characters if needed.", x = 10 },
        [40819] = { e = 2, s = "s", r = "Open one specific coffer with a key.", d = "Open a Bountiful Coffer using a Restored Coffer Key. This is the first step in a chain leading to the next key-related achievement.", x = 10 },
        [40820] = { e = 3, s = "s", r = "Revive Brann after he falls unconscious.", d = "Revive Brann Bronzebeard after he falls unconscious during gameplay. Watch for his health dropping to zero and use a revive ability immediately.", x = 10 },
        [40822] = { e = 3, s = "c", r = "Explore 11 distinct sub-areas of Azj-Kahet.", d = "Explore every zone in Azj-Kahet by revealing the world map. This includes specific sub-zones like Ruptured Lake and The Weaver's Lair.", x = 10 },
        [40825] = { e = 3, s = "c", r = "Explore 11 distinct sub-areas of The Ringing Deeps.", d = "Fully explore the Ringing Deeps region to reveal all map areas. Visit locations such as Lost Mines and The Waterworks to complete this.", x = 10 },
        [40826] = { e = 3, s = "c", r = "Explore 9 distinct sub-areas of Hallowfall.", d = "Explore Hallowfall by visiting every sub-zone listed in the requirements. This includes Dunelle's Kindness and Light's Redoubt among others.", x = 10 },
        [40828] = { e = 3, s = "c", r = "Discover 12 unique hidden treasures across Azj-Kahet.", d = "Discover all unique hidden treasures across Azj-Kahet. Look for specific items like Concealed Contraband and Memory Cache scattered throughout the zone.", x = 10 },
        [40831] = { e = 3, s = "c", r = "Explore 9 distinct sub-areas of the Isle of Dorn.", d = "Explore the entire Isle of Dorn to reveal the world map. Check areas like Thunderhead Peak and The Three Shields for completion.", x = 10 },
        [40832] = { e = 2, s = "s", r = "Complete one specific quest chain in Azj-Kahet.", d = "Complete the quest The Weaver's Legacy in Azj-Kahet. Ensure you have the necessary quest items before turning it in.", x = 10 },
        [40833] = { e = 2, s = "s", r = "Complete one specific quest chain in Azj-Kahet.", d = "Finish the quest The General's Resolve in Azj-Kahet. Follow the quest chain carefully to avoid missing any objectives.", x = 10 },
        [40835] = { e = 1, s = "s", r = "Single quest completion.", d = "Complete the quest The Vizier's Resolve in Azj-Kahet to earn this achievement. Ensure you have the Mask of the Vizier equipped as it is a hard requirement for this content.", x = 10 },
        [40837] = { e = 3, s = "g", r = "Grind for 10 of 15 encounters.", d = "Unlock the Adventurer's Journey: The Ringing Deeps first, then hunt down any of the listed special encounters like Candleflyer Captain or King Splash. This is account-wide so progress carries across characters.", x = 10 },
        [40840] = { e = 3, s = "g", r = "Grind for 10 of 20 encounters.", d = "Start by unlocking the Adventurer of Azj-Kahet achievement requirement and then defeat ten different bosses such as Abyssal Devourer or Rhak'ik & Khak'ik. Some encounters may be rare, so explore thoroughly.", x = 10 },
        [40843] = { e = 3, s = "g", r = "Grind to destroy 500 mines.", d = "Equip a mining profession or use an appropriate tool to destroy Nerubian mines scattered throughout Azj-Kahet until you reach the count of 500. This progress is shared across your entire account.", x = 10 },
        [40844] = { e = 3, s = "c", h = { 167739 }, r = "Optional storylines; Striking Steel dominates.", d = "Begin the optional Hallowfall storylines by accepting quests like Light to Velhan's Claim and follow them through to completion. These are account-wide, so finish them on one character to unlock for all.", x = 10 },
        [40848] = { e = 2, s = "c", r = "Discover hidden treasures across zone.", d = "Explore every corner of Hallowfall to find hidden treasures like Caesper or the Smuggler's Treasure. Use your map markers to track which items you have already discovered.", x = 10 },
        [40851] = { e = 3, s = "g", r = "Grind for 10 of 20 encounters.", d = "Unlock the Adventurer of Hallowfall requirement and then defeat ten special encounters such as Deepfiend Azellix or Ixlorb the Spinner. Be patient as some bosses like Deathtide may be rare spawns.", x = 10 },
        [40859] = { e = 2, s = "c", r = "Watch or participate in plays.", d = "Watch and participate in all five Theater Troupe plays listed, starting with The Rivals to unlock the rest. This is account-wide, so view them on any character you prefer.", x = 10 },
        [40860] = { e = 2, s = "c", r = "Unlock actor perks via quests.", d = "After completing the plays, accept the Actor Renown Quests to unlock perks like Quickchange Artist and Attention-Getter. Ensure you have finished all play requirements first.", x = 10 },
        [40862] = { e = 1, s = "c", r = "Visit candy buckets in zones.", d = "Visit every Candy Bucket location listed across Khaz Algar zones during Hallow's End event. This is time-gated to the event window, so prioritize it while active.", x = 10 },
        [40863] = { e = 2, s = "s", r = "Complete one puzzle instance.", d = "Enter any delve instance and solve the first puzzle you encounter to complete this step. Progress carries over if you switch characters before finishing the next tier.", x = 10 },
        [40864] = { e = 3, s = "g", r = "Grind to complete 25 puzzles.", d = "Continue solving puzzles in delves until you reach 25 total completions. Since this builds on the previous achievement, ensure you have already solved at least one puzzle first.", x = 10 },
        [40869] = { e = 2, s = "c", r = "Three short quests in a new zone.", d = "Start by accepting the three listed quests in Rak-Ush and the Wormlands to unlock Lil' Bonechewer. Ensure you complete all parts of this chain before leaving the zone, as it is account-wide but tied to specific quest flags.", x = 10 },
        [40870] = { e = 3, s = "c", h = { 168933 }, r = "Requires one of several event-based achievements.", d = "Begin with 'Azeroth's Greatest Detective' since it unlocks the other anniversary achievements. You only need two sub-achievements from the list, so prioritize the ones that do not require rare drops or complex setups.", x = 10 },
        [40871] = { e = 4, s = "c", h = { 168898 }, r = "Many hidden stories; some are rare spawns.", d = "Locate and complete every hidden Guest Relations local story listed in the info field. Be patient with 'The Case of Staged Disaster' as it may require multiple attempts to trigger all nine instances.", x = 10 },
        [40872] = { e = 3, s = "c", r = "Linear storyline with four chapters.", d = "Follow the four chapters of the main Guest Relations storyline sequentially. This is a straightforward narrative quest chain that unlocks rewards and progresses you toward other anniversary goals.", x = 10 },
        [40873] = { e = 2, s = "g", r = "Find and return six crates easily.", d = "Search for Celebration Crates across Azeroth and return them to the appropriate NPC until you have six. Once collected, this achievement automatically advances you to the next crate-related goal.", x = 10 },
        [40874] = { e = 3, s = "g", r = "Grind reputation to max with Weaver.", d = "Grind reputation with the Weaver in Azj'Kahet by completing daily activities and world quests in that zone. Reach maximum friendship to earn the Silksinger title without needing any special items.", x = 10 },
        [40875] = { e = 3, s = "g", r = "Grind reputation to max with General.", d = "Focus your efforts on earning maximum reputation with the General in Azj'Kahet through local quests and events. This straightforward grind will grant you the Anub title once completed.", x = 10 },
        [40876] = { e = 3, s = "g", r = "Grind reputation to max with Vizier.", d = "Complete all available content for the Vizier in Azj'Kahet to reach maximum friendship. There are no time gates, so simply finish every quest and event associated with this faction.", x = 10 },
        [40882] = { e = 4, s = "g", r = "Open 250 coffers; requires key farming.", d = "Farm Bountiful Coffers using Restored Coffer Keys until you open 250 of them. This is a volume-based grind that requires obtaining the prerequisite key achievement first.", x = 10 },
        [40885] = { e = 4, s = "g", r = "Open 500 coffers; builds on previous.", d = "Continue farming coffers to reach the 500 total required for this next tier. Since it builds on the previous achievement, ensure you keep your keys and coffers active without interruption.", x = 10 },
        [40894] = { e = 3, s = "c", h = { 206050 }, r = "Eleven optional quests; wedding is RNG.", d = "Accept and complete all optional Undermine storylines listed in the info field. These are scattered across the zone, so check your quest log regularly to avoid missing any side objectives.", x = 10 },
        [40900] = { e = 1, s = "s", r = "Complete main Undermine campaign story.", d = "Finish the entire Undermine campaign storyline to unlock this achievement. Ensure you have max-level characters or appropriate gear if the content is scaled for higher levels, as it may be missable on lower levels.", x = 10 },
        [40936] = { e = 2, s = "c", r = "Grind races in Undermine; Silver requires Bronze first.", d = "Start by completing all Bronze races in Undermine using the Skyrocketing ability. You must finish every single race variant to unlock the Silver tier next.", x = 10 },
        [40937] = { e = 3, s = "c", r = "Grind harder races; Silver is prerequisite for Gold.", d = "Once you have Bronze, immediately attempt the Silver races. This tier requires significantly better gear and skill than Bronze.", x = 10 },
        [40938] = { e = 4, s = "c", r = "Gold races are very hard; requires Silver first.", d = "Complete all Gold races to earn the Skyrocketer title. Ensure you have mastered the mechanics before attempting this highest difficulty.", x = 10 },
        [40948] = { e = 2, s = "g", r = "Collect 5 specific items in Undermine zones.", d = "Unlock Muff's Auto-Lockers by finding and opening five specific complex treasures scattered throughout Undermine. These locations are fixed and do not respawn.", x = 10 },
        [40953] = { e = 5, s = "c", h = { 168590, 168591, 168592 }, r = "Requires completing multiple old raids and dungeons.", d = "This is a massive account-wide goal requiring you to clear all major raids and dungeons from the Battle for Azeroth expansion. Start with Uldir or The Eternal Palace as they are often easier entry points.", x = 10 },
        [40955] = { e = 3, s = "c", r = "Complete various BfA quest lines across zones.", d = "Complete every listed quest achievement from the Battle for Azeroth campaign and storylines. Many of these quests have long timers or specific prerequisites you must track carefully.", x = 7 },
        [40956] = { e = 3, s = "c", r = "Complete exploration and lore achievements in BfA.", d = "Finish all exploration achievements in Zandalar and Kul Tiras to earn your mount. This includes visiting every zone location and completing lore-related tasks.", x = 7 },
        [40957] = { e = 2, s = "c", r = "Complete various War Effort objectives across zones.", d = "Clear all War Effort objectives across the world map. Some of these require specific faction reputations or defeating certain enemy groups in designated areas.", x = 7 },
        [40958] = { e = 2, s = "c", r = "Collect hearts and complete Heart Forge tasks.", d = "Complete all Heart of Azeroth achievements by engaging with the core mechanics of that expansion. This involves collecting resources and completing specific world quests.", x = 7 },
        [40959] = { e = 3, s = "c", r = "Complete various Black Empire defense objectives.", d = "Defeat the Black Empire threats by completing their associated quest lines and combat objectives. These often involve defending specific locations against waves of enemies.", x = 7 },
        [40960] = { e = 4, s = "g", r = "Defeat all Uldir bosses on Normal or higher.", d = "Clear all bosses in Uldir on Normal difficulty or higher to unlock this raid achievement. Ensure your group is prepared for the mechanics of each wing.", x = 7 },
        [40961] = { e = 4, s = "g", r = "Defeat all Battle of Dazar'alor wing bosses.", d = "Defeat all bosses in Battle of Dazar'alor on Normal difficulty or higher. This requires clearing all three wings of the raid instance successfully.", x = 7 },
        [40962] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses on Normal or higher.", d = "Queue for The Eternal Palace on Normal or higher difficulty and defeat all three bosses listed in the info. This is account-wide, so any character can contribute to progress.", x = 7 },
        [40963] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses on Normal or higher.", d = "Run Ny'alotha, the Waking City on Normal difficulty or higher until you have defeated every boss mentioned. Ensure your group composition handles the specific mechanics of each encounter.", x = 7 },
        [40977] = { e = 2, s = "s", r = "Single scenario completion takes a few hours solo.", d = "Complete the scenario 'The Codex of Chromie' during the Anniversary event to finish this achievement. Check your scenario list in the main menu to ensure you have started it.", x = 10 },
        [40979] = { e = 3, s = "g", r = "Requires finding and returning all 11 celebration crates.", d = "Locate and return all eleven Celebration Crates to the Crate Insurance Agent. These crates are scattered across major zones during the Anniversary event.", x = 10 },
        [40980] = { e = 2, s = "c", r = "Combines several easy pet battle achievements into one.", d = "Complete all ten sub-achievements listed in the info by battling various types of pets in Khaz Algar. This requires collecting specific pet encounters for each category.", x = 10 },
        [40984] = { e = 1, s = "g", r = "Voting is trivial; reaching 20 votes takes minutes.", d = "Visit the Fashion Frenzy event and cast twenty votes on different outfits to complete this goal. You can vote multiple times per outfit if available.", x = 10 },
        [40985] = { e = 3, s = "s", r = "Requires finding a specific mount during a limited event.", d = "Participate in Mount Mania by matching one mount from the list provided in the info. This is often a prerequisite for the next tier of this event chain.", x = 10 },
        [40986] = { e = 3, s = "g", r = "Requires matching 20 mounts during the Mount Mania event.", d = "Match twenty different mounts during Mount Mania to earn this achievement. Start with the first tier requirement before attempting this larger goal.", x = 10 },
        [40987] = { e = 1, s = "s", r = "Single vote is trivial; unlocks next achievement.", d = "Cast a single vote at the Fashion Frenzy event to unlock this title. This is the starting point for the Fashion Frenzy achievement chain.", x = 10 },
        [40988] = { e = 2, s = "s", r = "Simple exploration task using a pet disguise item.", d = "Use a pet disguiser item to transform your appearance and then explore various zones. Ensure you have the correct consumable or item equipped before leaving your base.", x = 10 },
        [40989] = { e = 1, s = "s", r = "Simple exploration task using a pet disguise item.", d = "Ride any of the special celebration balloons available during the event to complete this task. These are usually found in major cities or event hubs.", x = 10 },
        [40990] = { e = 2, s = "s", r = "Riding one balloon is quick and easy during the event.", x = 10 },
        [40991] = { e = 1, s = "c", r = "Ride four balloons; trivial event interaction.", d = "Ride all four celebration balloons by flying to the event zone and interacting with each color. Ensure you have a mount capable of flight, as these are often found in the air or on specific platforms.", x = 10 },
        [40992] = { e = 3, s = "g", r = "Interact with NPC 50 times; steady progress.", d = "Travel to Lorewalker Cho's location and repeatedly react to his stories until you reach the required count. This is account-wide, so any character can contribute to the progress.", x = 10 },
        [40993] = { e = 2, s = "c", r = "Listen to four specific stories; easy content.", d = "Locate Lorewalker Cho and listen to every unique story listed in the achievement description. Make sure to check your log after each interaction to confirm completion before moving on.", x = 10 },
        [40994] = { e = 3, s = "s", r = "Defeat one random world boss; RNG dependent.", d = "Participate in World Boss events during the Anniversary celebration and defeat at least one of the original bosses. These events are time-gated, so check the calendar for available dates.", x = 10 },
        [40995] = { e = 4, s = "c", r = "Defeat all six world bosses; long grind.", d = "Defeat every single original world boss listed during the Anniversary event window. Since this requires all previous ones, prioritize clearing each boss type before the event ends.", x = 10 },
        [40996] = { e = 3, s = "s", r = "Defeat one random world boss; RNG dependent.", d = "Join World Boss events to defeat at least one of the gatecrasher bosses. These are time-limited encounters, so plan your group composition carefully for each specific boss.", x = 10 },
        [40997] = { e = 4, s = "c", r = "Defeat all three gatecrasher bosses; long grind.", d = "Clear all remaining gatecrasher world bosses during the Anniversary celebration. This achievement builds on the previous one, so ensure you have defeated at least one first.", x = 10 },
        [40998] = { e = 2, s = "s", r = "Complete one Timewalking dungeon; easy task.", d = "Complete any single Classic Timewalking dungeon instance to earn points. You can choose from multiple dungeons, but remember that some may require specific group compositions or keys.", x = 10 },
        [40999] = { e = 5, s = "c", r = "Defeat all Blackrock Depths bosses; raid grind.", d = "Defeat every boss listed in the Blackrock Depths raid during the Anniversary event. This is a full-raid clear, so coordinate with your group to handle all encounters efficiently.", x = 10 },
        [41000] = { e = 3, s = "g", r = "Complete six Timewalking dungeons; steady grind.", d = "Finish at least six different Classic Timewalking dungeons, including multiple runs of Stratholme. Track your progress carefully since you need variety in the dungeons completed.", x = 10 },
        [41013] = { e = 2, s = "s", r = "Purchase one armor set; trivial shop task.", d = "Purchase any Tier 2 armor set offered during the Anniversary celebration to unlock this achievement. Check vendor shops or auction houses for available sets within the event timeframe.", x = 10 },
        [41015] = { e = 3, s = "g", r = "Find many missives in raid; steady grind.", d = "Explore Blackrock Depths and collect all Temporal Missives from Moira scattered throughout the raid zones. This requires thorough exploration of every area in the instance.", x = 10 },
        [41033] = { e = 2, s = "s", r = "Buy one item during a limited event.", d = "Buy your first Tier 2 set early, then wait for the Anniversary event to purchase a second one. Ensure you have enough gold and space in your bags before the sale ends.", x = 10 },
        [41042] = { e = 4, s = "c", h = { 169531, 169532, 169533 }, r = "Weekly quests with RNG elements and grind.", d = "Visit Siren Isle weekly and complete every listed quest immediately upon release. Do not delay, as these are time-gated weekly objectives that reset every week.", x = 10 },
        [41043] = { e = 3, s = "c", h = { 169564, 169565, 169566 }, r = "Contribute to excavations; moderate grind.", d = "Check the Command Map on Siren Isle and contribute resources to each excavation site. Prioritize sites that require specific materials you can gather nearby.", x = 10 },
        [41045] = { e = 3, s = "c", h = { 169589, 169590, 169591 }, r = "Complete a multi-step questline.", d = "Start the 'A Song of Secrets' questline as soon as it appears on your map. Follow the chain sequentially without skipping steps to avoid missing objectives.", x = 10 },
        [41046] = { e = 4, s = "c", h = { 169570, 169571, 169572 }, r = "Defeat many rare creatures; RNG dependent.", d = "Explore Siren Isle thoroughly and hunt down every rare creature listed. Some may be elusive, so check multiple zones and wait for spawn timers if needed.", x = 10 },
        [41050] = { e = 3, s = "c", h = { 169662, 169663, 169664 }, r = "Collect gems from various sources; moderate grind.", d = "Scout the entire map of Siren Isle to locate all Citrine gems. They are often in hidden or hard-to-reach spots, so use flying mounts to speed up collection.", x = 10 },
        [41052] = { e = 3, s = "c", r = "Complete a specific storyline; moderate effort.", d = "Find and complete the Lingering Shadows storyline quests. This will unlock a specific appearance reward, so finish it before moving on to other content.", x = 10 },
        [41081] = { e = 3, s = "c", h = { 169701, 169702, 169704 }, r = "Complete multiple races; RNG involved.", d = "Race through Undermine repeatedly to earn Bronze times for all Breakneck races. Focus on learning the optimal routes and shortcuts to improve your speed.", x = 10 },
        [41083] = { e = 3, s = "c", h = { 169714, 169715, 169716 }, r = "Repeat races with higher difficulty; RNG.", d = "After unlocking Bronze, race again to achieve Silver times in all Undermine Breakneck events. Practice your runs to shave off seconds and meet the higher threshold.", x = 10 },
        [41084] = { e = 3, s = "c", h = { 169723, 169724, 169725 }, r = "Repeat races with highest difficulty; RNG.", d = "Once you have Silver, push for Gold times in every race. This requires perfect execution and knowledge of the fastest paths through each track.", x = 10 },
        [41086] = { e = 3, s = "c", r = "Grind reputation to max rank; steady progress.", d = "Grind reputation with the Cartels of Undermine until you reach Rank 20. Focus on daily quests and world events that offer large chunks of reputation.", x = 10 },
        [41092] = { e = 3, s = "c", h = { 169872, 169874, 169875 }, r = "Catch pets in multiple zones; RNG involved.", d = "Travel to Undermine, Zandalar, and The Ringing Deeps to catch every listed battle pet. Use bait effectively and check rare spawns in each zone.", x = 10 },
        [41095] = { e = 3, s = "g", r = "Grinding 500 delves takes several hours.", d = "Start by queuing for any available delve to count toward your total of 500. This is a grind that requires no specific group composition, so play solo or with friends as you progress through the content.", x = 10 },
        [41096] = { e = 3, s = "g", r = "Grinding 1000 delves takes many hours.", d = "Once you hit 500 delves, unlock the next tier by completing an additional 500 runs. Treat this as a long-term goal since it builds on your previous progress without needing new mechanics.", x = 10 },
        [41097] = { e = 3, s = "g", r = "Looting 100 curiosities requires many runs.", d = "Focus on looting every mislaid curiosity item you find during delve runs to reach the count of 100. Do not miss these drops, as they are account-wide and essential for this specific achievement.", x = 10 },
        [41098] = { e = 3, s = "c", h = { 169936 }, r = "One variant is significantly harder than others.", d = "Complete all three story variants of Excavation Site 9 by selecting each available narrative option when entering the delve. Ensure you finish every variant before moving on to other content to avoid missing any requirements.", x = 10 },
        [41099] = { e = 3, s = "c", h = { 169940 }, r = "One variant is significantly harder than others.", d = "Finish all story variants for Sidestreet Sluice just like the previous site, making sure to experience every unique storyline offered. This requires revisiting the same location with different plot choices available each time.", x = 10 },
        [41100] = { e = 2, s = "s", r = "Finding chests is a single-step event.", d = "Search thoroughly for and open all four Sturdy Chests hidden within Excavation Site 9 during your runs. These chests are often in specific locations, so explore every corner of the delve to find them.", x = 10 },
        [41101] = { e = 2, s = "s", r = "Finding chests is a single-step event.", d = "Locate and open the four Sturdy Chests scattered throughout Sidestreet Sluice while completing its story variants. Be prepared to replay the delve multiple times if you miss a chest on your first attempt.", x = 10 },
        [41105] = { e = 3, s = "g", r = "Completing 100 puzzles takes several hours.", d = "Solve puzzles in any delve to accumulate 100 completions, but note that this requires unlocking the prerequisite achievement first. You can mix and match different delves to reach the puzzle count efficiently.", x = 10 },
        [41106] = { e = 4, s = "c", h = { 169955 }, r = "Some delves are much harder than others.", d = "Queue for every delve in Khaz Algar on Tier 4 or higher while playing a damage dealer role with lives remaining. This is a long grind requiring you to master each dungeon as DPS before moving to the next tier.", x = 10 },
        [41107] = { e = 4, s = "c", r = "Some delves are much harder than others.", d = "Repeat the same process as the damage dealer achievement but switch your class to a healer role for every delve in Khaz Algar on Tier 4 or higher. Ensure you survive with lives remaining throughout each run.", x = 10 },
        [41108] = { e = 4, s = "c", r = "Some delves are much harder than others.", d = "Play tank specs and complete all Khaz Algar delves on Tier 4 or higher while keeping your team alive with lives remaining. This requires strong positioning and survivability skills across every dungeon in the region.", x = 10 },
        [41109] = { e = 4, s = "c", h = { 170002 }, r = "Tier 8 delves are significantly harder.", d = "Unlock this achievement by first completing the Tier 4 version, then requeue for the same delves on Tier 8 or higher as a damage dealer. The grind increases significantly with the higher tier requirement, so plan your time accordingly.", x = 10 },
        [41110] = { e = 3, s = "g", r = "Grinding 12 delves as damage dealer with lives remaining.", d = "Unlock Algari Delver Damage Dealer II first, then queue every Khaz Algar delve on Tier 11 as a damage dealer while keeping lives. Ensure you do not die before the final boss to claim points for each instance.", x = 10 },
        [41111] = { e = 3, s = "g", r = "Grinding 15 delves as healer with lives remaining.", d = "Start by completing all delves on Tier 8 or higher as a healer with lives remaining, then progress to Tier 11 for the next tier. Do not skip any delve in the list provided in the achievement info.", x = 10 },
        [41112] = { e = 3, s = "g", r = "Grinding 15 delves as healer on Tier 11 with lives.", d = "After unlocking Algari Delver Healer II, defeat every Khaz Algar delve on Tier 11 as a healer without dying. This is account-wide, so coordinate with friends if you lack a healer spec.", x = 10 },
        [41113] = { e = 3, s = "g", r = "Grinding 15 delves as tank with lives remaining.", d = "Begin with Tier 8+ delves as a tank, then advance to Tier 11 once Algari Delver Tank II is unlocked. Always ensure the group survives until the final boss for credit.", x = 10 },
        [41114] = { e = 3, s = "g", r = "Grinding 15 delves as tank on Tier 11 with lives.", d = "Unlock Algari Delver Tank II before attempting Tier 11 runs as a tank. Complete every listed delve with lives remaining to finish this account-wide requirement.", x = 10 },
        [41115] = { e = 3, s = "g", r = "Grinding all delves three roles on Tier 4+ with lives.", d = "Complete all delves on Tier 4+ as a damage dealer, healer, and tank sequentially. You must switch specs or use different characters to cover each role across all instances.", x = 10 },
        [41116] = { e = 3, s = "g", r = "Grinding all delves three roles on Tier 8+ with lives.", d = "After finishing Algari Delver, repeat every Khaz Algar delve on Tier 8+ while playing as a damage dealer, healer, and tank. Ensure you have lives remaining in each run.", x = 10 },
        [41119] = { e = 2, s = "g", r = "Kill boss once after activating one machine in raid.", d = "In Liberation of Undermine Normal or higher, activate one Chip Defense Machine then defeat the One-Armed Bandit. Repeat this process to unlock subsequent ranks in the chain.", x = 10 },
        [41120] = { e = 2, s = "g", r = "Kill boss once after activating two machines in raid.", d = "Activate two Chip Defense Machines and defeat the One-Armed Bandit in Liberation of Undermine on Normal or higher. This requires unlocking One Rank Higher first.", x = 10 },
        [41121] = { e = 2, s = "g", r = "Kill boss once after activating three machines in raid.", d = "Activate three Chip Defense Machines before defeating the One-Armed Bandit in Liberation of Undermine on Normal difficulty or higher. Ensure you have completed Two Ranks Higher.", x = 10 },
        [41122] = { e = 2, s = "g", r = "Kill boss once after activating all four machines in raid.", d = "Activate all four Chip Defense Machines and defeat the One-Armed Bandit to earn the title The Reel Deal. This is the final step after Three Ranks Higher.", x = 10 },
        [41130] = { e = 2, s = "c", r = "Visit and honor seven specific NPCs across zones.", d = "Travel to Khaz Algar zones to honor the listed Elders and Archivists using the appropriate interaction. Complete this account-wide task by visiting each specific NPC location.", x = 9 },
        [41131] = { e = 2, s = "g", r = "Collecting 10 caches takes under an hour solo.", d = "Start by exploring Siren Isle to locate the ten Runed Storm Caches scattered across the map. These caches are not rare drops but require you to physically find and open each one. Ensure you have completed any prerequisite exploration tasks before focusing solely on these chests.", x = 10 },
        [41133] = { e = 4, s = "c", h = { 170149 }, r = "Requires completing other Isle achievements first.", d = "This achievement requires completing all other Siren Isle objectives first, so tackle them in order of difficulty. The final reward is a mount, making it essential to finish the entire zone's checklist without missing sub-achievements. Prioritize clearing world bosses and finding hidden items before opening caches.", x = 10 },
        [41149] = { e = 2, s = "g", r = "Reaching rank 15 is a short reputation grind.", d = "Focus on completing daily quests and reputation vendors for the Severed Threads faction in Siren Isle. Reach rank 15 quickly by grinding specific activities tied to this group. Do not delay this, as higher renown tiers often unlock better rewards or faster progression.", x = 10 },
        [41161] = { e = 2, s = "g", r = "Reaching rank 15 is a short reputation grind.", d = "Grind reputation with the Council of Dornogal through daily quests and world events in your current zone. Aim for rank 15 efficiently by focusing on high-yield activities like dungeon runs or specific NPC interactions. Avoid wasting time on low-value tasks that do not contribute to this faction's progress.", x = 10 },
        [41162] = { e = 3, s = "g", r = "Rank 25 requires more time than rank 15.", d = "After reaching rank 15 with the Council of Dornogal, continue grinding daily quests and events to reach max renown at rank 25. This is a straightforward progression path with no time gates or rare drops involved. Stay consistent with your faction activities to avoid falling behind on reputation gains.", x = 10 },
        [41164] = { e = 3, s = "g", r = "Rank 25 is a longer reputation grind.", d = "Once you have maxed out the Severed Threads, ensure you complete all remaining daily quests and events for them. There are no hidden requirements beyond reaching rank 25, so focus on efficient grinding. This achievement is account-wide, so coordinate with friends if needed to speed up the process.", x = 10 },
        [41165] = { e = 2, s = "g", r = "Reaching rank 15 is a short reputation grind.", d = "Begin by completing daily quests and world events associated with the Assembly of the Deeps faction. Reach rank 15 by focusing on high-yield activities like dungeon runs or specific NPC interactions. Avoid wasting time on low-value tasks that do not contribute to this faction's progress.", x = 10 },
        [41166] = { e = 3, s = "g", r = "Rank 25 requires more time than rank 15.", d = "After reaching rank 15 with the Assembly of the Deeps, continue grinding daily quests and events to reach max renown at rank 25. This is a straightforward progression path with no time gates or rare drops involved. Stay consistent with your faction activities to avoid falling behind on reputation gains.", x = 10 },
        [41167] = { e = 2, s = "g", r = "Reaching rank 15 is a short reputation grind.", d = "Focus on completing daily quests and reputation vendors for the Hallowfall Arathi faction in your current zone. Reach rank 15 quickly by grinding specific activities tied to this group. Do not delay this, as higher renown tiers often unlock better rewards or faster progression.", x = 10 },
        [41168] = { e = 3, s = "g", r = "Rank 25 requires more time than rank 15.", d = "After reaching rank 15 with the Hallowfall Arathi, continue grinding daily quests and events to reach max renown at rank 25. This is a straightforward progression path with no time gates or rare drops involved. Stay consistent with your faction activities to avoid falling behind on reputation gains.", x = 10 },
        [41169] = { e = 4, s = "c", h = { 165770, 165771, 165772 }, r = "Requires maxing three separate factions first.", d = "This achievement requires maxing out all four listed factions, so prioritize completing their respective daily quests and events. Start with the easiest factions first to build momentum before tackling more challenging ones. Ensure you have completed all prerequisite achievements for each faction before attempting this one.", x = 10 },
        [41170] = { e = 2, s = "g", r = "Reaching rank 15 is a short reputation grind.", d = "Grind reputation with the Maruuk Centaur through daily quests and world events in your current zone. Aim for rank 15 efficiently by focusing on high-yield activities like dungeon runs or specific NPC interactions. Avoid wasting time on low-value tasks that do not contribute to this faction's progress.", x = 9 },
        [41171] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Focus on completing daily quests and world events in Valdrakken to gain renown efficiently. This is an account-wide achievement, so any character can contribute progress.", x = 9 },
        [41172] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Prioritize the Dragonscale Expedition faction by doing their specific dailies and exploring relevant zones. Remember that this tracks across all characters on your account.", x = 9 },
        [41173] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Complete daily quests for the Iskaara Tuskarr in Nazjatar to reach the required renown level quickly. Progress is shared across your entire account.", x = 9 },
        [41174] = { e = 3, s = "g", r = "Requires grinding renown to a higher rank.", d = "Aim for Rank 25 with the Dragonscale Expedition by consistently completing their daily objectives and world events. This achievement unlocks at a higher renown tier than the basic rank 15 goal.", x = 9 },
        [41175] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Grind dailies in Nazjatar specifically for the Loamm Niffen faction to reach Rank 15. Ensure you are targeting the correct faction rewards during your daily routine.", x = 9 },
        [41176] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Reach Rank 15 with the Dream Wardens by completing their specific daily quests and exploring relevant zones. This is a prerequisite for the next tier achievement.", x = 9 },
        [41177] = { e = 3, s = "g", r = "Requires grinding renown to a higher rank.", d = "Continue grinding Dream Warden dailies to reach Rank 20, which requires you to already have Rank 15. Progress carries over automatically on your account.", x = 9 },
        [41179] = { e = 4, s = "c", h = { 139165 }, r = "Dominant effort is Iskaara Tuskarr grind.", d = "Max out all four major factions by completing their respective daily quests and world events consistently. This is a large achievement requiring significant time investment across multiple zones.", x = 9 },
        [41180] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Focus on Maruuk Centaur dailies in the Waking Shores to reach Rank 25 renown. Ensure you are claiming rewards from the correct faction vendor.", x = 9 },
        [41181] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Grind Iskaara Tuskarr dailies in Nazjatar until you hit Rank 30 renown. This requires consistent daily completion and may take several weeks depending on your playtime.", x = 9 },
        [41182] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Complete Valdrakken Accord dailies in Valdrakken to reach the maximum Rank 30 renown level. This is the highest renown tier for this major faction.", x = 9 },
        [41183] = { e = 3, s = "g", r = "Requires grinding renown with a faction.", d = "Reach Rank 20 with the Loamm Niffen by consistently completing their daily quests and world events. This achievement sits between the basic rank 15 and maximum renown goals.", x = 9 },
        [41184] = { e = 3, s = "c", r = "Grinding renown across multiple factions takes hours.", d = "Grind reputation with all six major Dragon Isles factions to reach Renown 15. This is account-wide and requires significant time investment through daily quests and world events.", x = 9 },
        [41185] = { e = 2, s = "s", r = "Complete specific quests during a storm event.", d = "Wait for a storm on Siren Isle before starting these specific quests. Ensure you have the required items ready, as this cannot be completed during calm weather.", x = 10 },
        [41186] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Complete all six sub-achievements on the Isle of Dorn to unlock this one. Focus on exploration and collecting treasures first to save time later.", x = 10 },
        [41187] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Finish the Ringing Deeps tasks including slime interactions and machine repairs. This area is account-wide, so coordinate with friends if you need help with rare drops.", x = 10 },
        [41188] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Clear Hallowfall by completing quests involving Lynx tracking and light mechanics. Some sub-tasks may require specific group compositions or rare mob kills.", x = 10 },
        [41189] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Explore Azj-Kahet thoroughly to find treasures and complete lore-based objectives. Be patient with world events that unlock certain sub-achievements over time.", x = 10 },
        [41201] = { e = 4, s = "c", r = "Requires completing several other major exploration achievements.", d = "Unlock this achievement only after completing all five previous exploration achievements listed in its info field. It serves as a capstone for the current expansion's content.", x = 10 },
        [41202] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Visit Zuldazar and complete Loa-related quests and treasure hunts. This is account-wide, so you can progress while leveling other characters or during downtime.", x = 7 },
        [41203] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Clear Nazmir by defeating bosses, collecting treasures, and interacting with environmental objectives. Some tasks may require specific raid keys or group assistance.", x = 7 },
        [41204] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Explore Vol'dun to complete sandfisher challenges and scavenger hunts. This area is account-wide, making it ideal for grinding while waiting for rare drops.", x = 7 },
        [41205] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Complete Tiragarde Sound quests involving naval battles and Freehold blessings. Some sub-achievements may require specific weather conditions or group coordination.", x = 7 },
        [41206] = { e = 3, s = "c", r = "Multiple exploration and collection tasks across zones.", d = "Finish Stormsong Valley tasks including beekeeping and mechanical repairs. This is account-wide, so prioritize world events and daily quests for efficiency.", x = 7 },
        [41207] = { e = 3, s = "c", h = { 170504, 170505 }, r = "Requires completing multiple Drustvar achievements.", d = "Start by completing the seven listed Drustvar achievements, which often require specific quests or exploration. Check your achievement tracker for any missing sub-goals like collecting items or defeating local rares. This is account-wide and time-gated until you finish all prerequisites in the zone.", x = 7 },
        [41208] = { e = 4, s = "g", r = "Grinding bike crashes and boss kills in raid.", d = "Crash your bike into every listed object in Undermine before engaging Vexie and the Geargrinders on Normal difficulty or higher. Ensure you hit each target at least once to register the crash, as missing one will require a full re-run. This is account-wide and can be done solo or in groups.", x = 10 },
        [41209] = { e = 3, s = "c", h = { 170387, 170390 }, r = "Need specific rare drops or event completions.", d = "Pick any four appearance achievements from the list that match your current gear or transmog collection. Equip the required items and complete the associated quests or activities to unlock them. This is account-wide, so coordinate with friends if some appearances require specific group content.", x = 10 },
        [41211] = { e = 5, s = "c", r = "Requires full raid group and specific dye.", d = "Gather a full party and dye every character the same color before entering Liberation of Undermine on Normal difficulty or higher. Defeat Mug'Zee and Heads of Security while maintaining this uniform appearance to secure the achievement. This is account-wide and requires careful coordination with your group's appearance settings.", x = 10 },
        [41212] = { e = 2, s = "g", r = "Simple donations across multiple taverns.", d = "Visit taverns in Khaz Algar and donate gold to Bar Tab Barrels at each listed location. You can do this solo, but ensure you visit all zones including Azj-kahet, Hallowfall, Isle of Dorn, Nerub'ar, and The Ringing Deeps. This is account-wide and does not require specific gear or group composition.", x = 10 },
        [41214] = { e = 3, s = "c", h = { 205791, 205792 }, r = "Complete all Worldsoul Memory events in zone.", d = "Complete both Worldsoul Memory events in Undermine by interacting with the required NPCs or objects during the event windows. These events are time-gated and may only appear at certain times, so check your calendar or community resources for schedules. This is account-wide and can be done solo.", x = 10 },
        [41215] = { e = 4, s = "g", r = "Requires Radiant Discord and rare spawns.", d = "Enter Undermine on Radiant Discord difficulty and hunt down each listed rare creature during Worldsoul Memory events. Some rares are elusive and may require multiple attempts or specific group strategies to defeat. This is account-wide and time-gated to the event windows in Undermine.", x = 10 },
        [41216] = { e = 3, s = "c", h = { 205819 }, r = "Collect 10 special encounters including a rare.", d = "Explore Undermine to find and defeat any ten of the listed special encounters, which include both rares and unique mobs. Some targets like Chief Foreman Gutso require multiple kills, so track your progress carefully. This is account-wide and can be done solo or in groups.", x = 10 },
        [41217] = { e = 3, s = "g", r = "Find hidden treasures scattered across zone.", d = "Search Undermine for hidden treasures such as unexploded fireworks, suspicious books, and other collectibles scattered throughout the zone. Use exploration tools or community guides to locate hard-to-find items like the Particularly Nice Lamp. This is account-wide and time-gated until all items are collected.", x = 10 },
        [41222] = { e = 3, s = "c", h = { 205980 }, r = "Defeat raid bosses on any difficulty.", d = "Defeat all bosses in Liberation of Undermine on any difficulty, starting with Normal if you prefer a lower challenge. Ensure you complete the normal version first as it is required for higher difficulties. This is account-wide and can be done solo or in groups.", x = 10 },
        [41223] = { e = 3, s = "c", h = { 205989 }, r = "Defeat raid bosses on Heroic difficulty.", d = "After completing the normal version, run Liberation of Undermine on Heroic difficulty to defeat all bosses again. Some mechanics are more challenging, so consider grouping with experienced players if needed. This is account-wide and requires prior completion of the normal version.", x = 10 },
        [41224] = { e = 4, s = "c", h = { 206027 }, r = "Requires Mythic difficulty and group coordination.", d = "Once you have cleared Heroic, tackle Mythic difficulty for Liberation of Undermine by defeating all bosses on this highest setting. Expect tougher mechanics and higher damage output, so prepare your group accordingly. This is account-wide and requires prior completion of the Heroic version.", x = 10 },
        [41225] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses on Normal.", d = "Complete the first wing of the Liberation of Undermine raid to unlock this achievement. It is account-wide and requires defeating Cauldron of Carnage or Rik Reverb.", x = 10 },
        [41226] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses on Normal.", d = "Progress through the second wing of the raid by defeating Stix Bunkjunker or Sprocketmonger Locknstock. This is account-wide and requires prior completion of Wing 1.", x = 10 },
        [41227] = { e = 3, s = "c", r = "Requires defeating multiple raid bosses on Normal.", d = "Finish the third wing by killing Vexie and the Geargrinders, One-Armed Bandit, or Mug'Zee. Ensure you have cleared Wings 1 and 2 first as this is account-wide.", x = 10 },
        [41228] = { e = 3, s = "c", r = "Requires defeating one raid boss on Normal.", d = "Defeat Chrome King Gallywix in the fourth wing to complete this specific raid achievement. Remember that all Undermine wings must be cleared sequentially for account-wide progress.", x = 10 },
        [41229] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Queue for Vexie and the Geargrinders on Mythic difficulty immediately after clearing the normal version. This is character-specific and cannot be shared with other accounts.", x = 10 },
        [41230] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Run Cauldron of Carnage on Mythic difficulty once you have finished the normal raid wing. Note that this is character-specific and requires a separate queue from the normal version.", x = 10 },
        [41231] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Defeat Rik Reverb on Mythic difficulty after clearing the normal wing. This achievement is tied to your specific character and cannot be earned by others.", x = 10 },
        [41232] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Kill Stix Bunkjunker on Mythic difficulty once the normal raid is complete. Remember that this is a character-specific requirement distinct from the account-wide normal version.", x = 10 },
        [41233] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Defeat Sprocketmonger Locknstock on Mythic difficulty after finishing the standard wing. This is character-specific and requires you to queue specifically for this boss.", x = 10 },
        [41234] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Run the One-Armed Bandit encounter on Mythic difficulty once the normal raid is done. This achievement is character-specific and must be earned by your own character.", x = 10 },
        [41235] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Defeat Mug'Zee on Mythic difficulty after clearing the normal wing. This is a character-specific achievement that requires you to queue for this specific boss.", x = 10 },
        [41236] = { e = 4, s = "c", r = "Mythic difficulty adds significant time and coordination.", d = "Complete Chrome King Gallywix on Mythic difficulty to earn both the achievement and the Liberator of Undermine title. This is character-specific and grants a unique reward upon completion.", x = 10 },
        [41286] = { e = 5, s = "c", h = { 206105, 208132, 208133 }, r = "Raid content with multiple difficult checklist requirements.", d = "Complete the listed sub-achievements in Liberation of Undermine to unlock this title. Ensure you finish all specific raid goals before claiming your reward, as missing any step will prevent completion.", x = 10 },
        [41287] = { e = 4, s = "s", r = "Single boss kill on a new raid instance.", d = "Defeat the Restless Heart in Windrunner Spire on Normal difficulty first. This is a straightforward dungeon goal that serves as the foundation for harder versions later.", x = 11 },
        [41288] = { e = 5, s = "s", r = "Heroic difficulty adds significant mechanical complexity.", d = "After clearing Normal, retry Windrunner Spire on Heroic to unlock this tier. You must defeat the boss again under these stricter mechanics to progress.", x = 11 },
        [41291] = { e = 5, s = "s", r = "Mythic difficulty requires high skill and coordination.", d = "Complete Heroic first, then challenge the dungeon on Mythic or Mythic Keystone difficulty. This final step requires high coordination and gear to succeed.", x = 11 },
        [41337] = { e = 5, s = "c", h = { 206293 }, r = "Requires raiding while managing a specific global state condition.", d = "Defeat Mug'Zee while every player has slept with the fishes in Liberation of Undermine Normal+. Coordinate a sleep event before engaging the boss to meet this unique condition.", x = 10 },
        [41338] = { e = 5, s = "s", r = "Specific boss kill requiring complex mechanics and setup.", d = "Activate both D.I.S.C.O.s during Hype Hustle before defeating Rik Reverb. Ensure you trigger these specific raid events early in the encounter to avoid failure.", x = 10 },
        [41339] = { e = 4, s = "s", r = "New dungeon boss kill on Normal difficulty.", d = "Defeat Geezle Gigazap in Operation: Floodgate on Normal difficulty. This is a standard dungeon goal that can be completed solo or with a small group.", x = 10 },
        [41340] = { e = 5, s = "s", r = "Heroic dungeon boss kill increases difficulty significantly.", d = "Clear Operation: Floodgate on Heroic difficulty after mastering the Normal version. The increased difficulty demands better gear and mechanics knowledge from your party.", x = 10 },
        [41341] = { e = 5, s = "s", r = "Mythic dungeon boss kill requires high-level play.", d = "Finish the dungeon on Mythic or Mythic Keystone for the final tier. This requires top-tier performance and is best attempted with a skilled group.", x = 10 },
        [41347] = { e = 5, s = "c", h = { 206312 }, r = "Raid boss kill with strict internal mechanic requirements.", d = "Defeat Chrome King Gallywix after detonating three Giga Controls during Giga Coils. Time your abilities to trigger these controls before engaging the boss for success.", x = 10 },
        [41349] = { e = 4, s = "g", r = "Grinding reputation to Honored requires substantial time.", d = "Reach Honored with all four Undermine cartels to earn this reputation achievement. Farm vendor drops or complete related quests efficiently to gain enough standing quickly.", x = 10 },
        [41350] = { e = 4, s = "g", r = "Grinding reputation to Exalted is a long-term task.", d = "Push Darkfuse Solutions reputation to Exalted for the title reward. Focus on daily quests and world events in their zone to accelerate progress toward this goal.", x = 10 },
        [41351] = { e = 4, s = "g", r = "Requires grinding reputation to Revered across four factions.", d = "Grind Cartel rep to Revered first, then farm specific vendors for the required items. Note that this is account-wide and requires significant gold or time-gated content completion.", x = 10 },
        [41352] = { e = 4, s = "g", r = "Requires grinding reputation to Exalted across four factions.", d = "Complete 'Cartels Bestie' before starting, then farm Exalted rep while collecting the massive item quantities needed. This is account-wide and involves heavy grinding of specific vendors.", x = 10 },
        [41522] = { e = 3, s = "g", r = "Grinding 1000 honor in War Mode takes several hours.", d = "Enable War Mode and queue for PvP in Undermine to earn honor quickly. Ensure you stay active in combat zones to maximize your honor gain efficiently.", x = 10 },
        [41525] = { e = 3, s = "s", r = "Requires obtaining a specific tier set on one character.", d = "Equip the Liberation of Undermine Tier 33 set on at least one character to complete this collection. Check your inventory for any missing pieces before equipping.", x = 10 },
        [41532] = { e = 2, s = "s", r = "Obtaining the Gob-Trotter from a delve is straightforward.", d = "Purchase or find the Delver's Gob-Trotter from delves or vendors to unlock this achievement. Ensure you have completed any prerequisite content if applicable.", x = 10 },
        [41537] = { e = 2, s = "g", r = "Raising a companion to level 70 takes some time but is easy.", d = "Level up your companion to 70 using appropriate quests or activities. Verify that 'Buddy System VI' is completed first as a prerequisite.", x = 10 },
        [41541] = { e = 3, s = "s", r = "Requires specific pets and defeating multiple trainers/bosses.", d = "Gather a team of level 25 Critter pets and defeat all specified trainers and bosses in Undermine. Ensure your pet team meets the exact type requirement before starting.", x = 10 },
        [41542] = { e = 3, s = "s", r = "Requires specific pets and defeating multiple trainers/bosses.", d = "Assemble a level 25 Aquatic pet team to tackle the designated trainers and bosses in Undermine. Confirm you have enough aquatic pets before attempting the challenge.", x = 10 },
        [41543] = { e = 3, s = "s", r = "Requires specific pets and defeating multiple trainers/bosses.", d = "Collect a full team of level 25 Beast pets to defeat the required trainers and bosses in Undermine. Prepare your team beforehand to avoid unnecessary retries.", x = 10 },
        [41544] = { e = 3, s = "s", r = "Requires specific pets and defeating multiple trainers/bosses.", d = "Gather a level 25 Dragonkin pet team to complete the trainer and boss challenges in Undermine. Ensure all pets meet the exact type requirement before starting.", x = 10 },
        [41545] = { e = 3, s = "s", r = "Requires specific pets and defeating multiple trainers/bosses.", d = "Form a level 25 Elemental pet team to defeat the specified trainers and bosses in Undermine. Verify your pet roster matches the elemental type needed.", x = 10 },
        [41546] = { e = 3, s = "s", r = "Requires specific pets and defeating multiple trainers/bosses.", d = "Assemble a level 25 Flying pet team to complete the trainer and boss objectives in Undermine. Check your pet collection for any missing flying pets before starting.", x = 10 },
        [41547] = { e = 3, s = "c", r = "Grinding 11+ battles with specific team type.", d = "Gather a team of five level 25 Humanoid pets and defeat all listed trainers and bosses in Undermine. Ensure you have the required pet before starting, as this is account-wide and cannot be completed with other types.", x = 10 },
        [41548] = { e = 3, s = "c", r = "Grinding 11+ battles with specific team type.", d = "Assemble a full team of level 25 Magic pets and clear every trainer and boss encounter in Undermine. This achievement requires specific pet types, so verify your collection meets the criteria before engaging combat.", x = 10 },
        [41549] = { e = 3, s = "c", r = "Grinding 11+ battles with specific team type.", d = "Build a squad of five level 25 Mechanical pets to defeat all designated trainers and bosses in Undermine. Start early since these are account-wide and require completing every single encounter listed.", x = 10 },
        [41550] = { e = 3, s = "c", r = "Grinding 11+ battles with specific team type.", d = "Collect a team of five level 25 Undead pets and systematically defeat all trainers and bosses in Undermine. Do not mix pet types, as the achievement strictly requires an all-Undead lineup for each battle.", x = 10 },
        [41551] = { e = 4, s = "c", r = "Requires completing other grinds plus a raid boss.", d = "Complete all nine individual Battler achievements listed in the info field to unlock this family-wide title. Prioritize gathering the necessary pets for each category before attempting the main achievement.", x = 10 },
        [41554] = { e = 4, s = "c", r = "Raid boss fight with specific consumable requirements.", d = "Defeat the Cauldron of Carnage boss while under the Hubris buff after consuming both Fireproof Punch and Shockproof Soda. This is a timed raid encounter on Normal or higher difficulty, so coordinate with your group carefully.", x = 10 },
        [41555] = { e = 3, s = "c", r = "Requires completing multiple sub-achievements in zone.", d = "Complete all listed Khaz Algar exploration achievements to earn this title and its reward. Focus on flight paths, glyphs, lore books, and allied race quests first to ensure no content is missed.", x = 10 },
        [41586] = { e = 2, s = "c", r = "Various simple exploration tasks and reading books.", d = "Finish all major Undermine activities including meta-activities, treasures, laws, reading, and friendship quests. This achievement covers broad exploration tasks, so check each sub-achievement in the info field for specific requirements.", x = 10 },
        [41587] = { e = 3, s = "c", r = "Requires exploring all map zones and finding lore.", d = "Travel across Undermine to reveal every hidden area on the world map. Use flying mounts and explore caves or tunnels to ensure no zones remain undiscovered before claiming this title.", x = 10 },
        [41588] = { e = 2, s = "g", r = "Kick cans until count reaches 25.", d = "Locate and kick Discarded Cans scattered throughout Undermine until you reach the required count. This task is repetitive but straightforward, so focus on high-density areas for efficiency.", x = 10 },
        [41589] = { e = 3, s = "g", r = "Complete 10 S.C.R.A.P. jobs in Undermine.", d = "Complete ten S.C.R.A.P. jobs in Undermine to progress toward this achievement. These jobs are likely found via a specific interface or NPC, so check your quest log for available contracts.", x = 10 },
        [41590] = { e = 3, s = "g", r = "Completing 10 jobs is a moderate grind.", x = 10 },
        [41591] = { e = 2, s = "g", r = "Grinding 25 jobs is easy solo in a new zone.", d = "Complete 25 S.C.R.A.P. jobs in Undermine by accepting them from the quest board or NPCs. This is a grind that requires no group but benefits from efficient travel between zones.", x = 10 },
        [41592] = { e = 3, s = "g", r = "Double the grind makes it moderate effort solo.", d = "After finishing the first tier, repeat the process to reach 50 total S.C.R.A.P. jobs. There are no time gates, so pace yourself over several play sessions.", x = 10 },
        [41593] = { e = 2, s = "c", r = "Visiting 7 locations is easy once jobs are known.", d = "Visit every distinct location in Undermine and complete at least one job in each area. Ensure you do not miss any of the seven listed zones before moving on.", x = 10 },
        [41594] = { e = 3, s = "g", r = "Requires finding specific trash mobs during jobs.", d = "During your S.C.R.A.P. jobs, look for and defeat the Gallagio Garbage mobs that spawn. This is a simple kill check with no specific timing requirements.", x = 10 },
        [41595] = { e = 2, s = "s", r = "Collecting a PvP set is trivial after unlocking.", d = "Equip any full armor set from The War Within PvP Season 2 to claim this collection achievement. You can obtain these sets through standard PvP rewards or transmog.", x = 10 },
        [41596] = { e = 4, s = "c", h = { 207031 }, r = "RNG mechanic on a raid boss adds significant difficulty.", d = "In Liberation of Undermine, ensure you clean up every Garbage Pile before the next Electromagnetic Sorting cast. This mechanic is crucial for defeating Stix Bunkjunker on Normal or higher difficulties.", x = 10 },
        [41597] = { e = 5, s = "c", h = { 207202, 207203, 207204 }, r = "Full raid clear with multiple unique sub-achievements.", d = "Complete all listed Manaforge Omega raid achievements regardless of difficulty tier. Start with Normal to unlock Heroic, then progress through the tiers for the mount reward.", x = 0 },
        [41598] = { e = 4, s = "c", h = { 207194, 207195 }, r = "Requires clearing a full raid on any difficulty.", d = "Defeat every boss in Manaforge Omega on any difficulty to unlock this base achievement. You can clear these individually or as part of a full raid run.", x = 10 },
        [41599] = { e = 5, s = "c", h = { 207186, 207187 }, r = "Heroic raid clear is hard and requires a group.", d = "Unlock Heroic difficulty first by completing the Normal tier, then defeat all bosses again on Heroic. This is a standard progression path with no hidden requirements.", x = 10 },
        [41600] = { e = 5, s = "c", h = { 207178, 207179 }, r = "Mythic raid clear is very hard and requires a group.", d = "Complete the entire Heroic tier before attempting Mythic runs. Defeat all bosses on Mythic difficulty to finish this final tier of the raid achievement chain.", x = 10 },
        [41601] = { e = 4, s = "c", h = { 207210, 207213 }, r = "Requires defeating specific wing bosses in a raid.", d = "Focus your raid runs on defeating the specific bosses listed in Wing 1 that bolster defenses. These are part of the standard encounter list for Manaforge Omega.", x = 10 },
        [41602] = { e = 4, s = "c", h = { 207215, 207216 }, r = "Requires defeating specific wing bosses in a raid.", d = "Target the specific bosses in Wing 2 that halt progress during your raid clears. Like other wing achievements, these drop upon defeating the designated encounters on any difficulty.", x = 10 },
        [41603] = { e = 5, s = "c", h = { 207218, 207219 }, r = "Requires defeating two specific raid bosses.", d = "Complete the Wing 3 raid to unlock this wing-wide achievement. Ensure you defeat both Nexus-King Salhadaar and Dimensius, the All-Devouring, as this is account-wide.", x = 10 },
        [41604] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "First earn the Mythic: Automaton achievement to unlock the Plexus Sentinel. Then run Manaforge Omega on Mythic difficulty and defeat the boss.", x = 10 },
        [41605] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "Unlock this by completing the Mythic: Silkworm prerequisite. Afterward, kill Loom'ithar during a Mythic+ or Mythic raid run in Manaforge Omega.", x = 10 },
        [41606] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "You must finish the Mythic: Binder achievement before attempting this boss. Defeat Soulbinder Naazindhri on Mythic difficulty to claim your points.", x = 10 },
        [41607] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "Complete the Mythic: Engineer prerequisite first. Then proceed to defeat Forgeweaver Araz in a Mythic difficulty instance of Manaforge Omega.", x = 10 },
        [41608] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "Unlock this by earning the Mythic: Hunters achievement. Once unlocked, kill The Soul Hunters on Mythic difficulty within Manaforge Omega.", x = 10 },
        [41609] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "Finish the Mythic: Glass Elemental prerequisite to unlock Fractillus. Defeat him on Mythic difficulty in Manaforge Omega to complete the task.", x = 10 },
        [41610] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "You need the Mythic: Salhadaar achievement unlocked first. Afterward, defeat Nexus-King Salhadaar specifically on Mythic difficulty in Manaforge Omega.", x = 10 },
        [41611] = { e = 5, s = "s", r = "Requires a specific Mythic difficulty kill.", d = "Unlock this by completing the Mythic: Dimensius prerequisite. Defeat Dimensius, the All-Devouring on Mythic difficulty to earn the Void Vanquisher title.", x = 10 },
        [41613] = { e = 5, s = "c", h = { 212689 }, r = "Requires a specific interaction before the Mythic boss.", d = "Complete the JZM achievement in Silkworm first. During the Loom'ithar encounter, ensure your group votes to either cower or cuddle before the fight starts.", x = 10 },
        [41614] = { e = 5, s = "c", h = { 212781 }, r = "Requires clearing a sub-boss area before the main boss.", d = "Finish the Haku achievement by defeating all Little Unbound Souls first. Then proceed to kill Soulbinder Naazindhri on Normal difficulty or higher.", x = 10 },
        [41615] = { e = 5, s = "c", h = { 212079 }, r = "Requires destroying a specific object before the boss.", d = "Defeat a Void Forged Echo in Manaforge Omega before killing Forgeweaver Araz. Ensure you are on Normal difficulty or higher when doing so.", x = 10 },
        [41616] = { e = 3, s = "c", r = "Requires specific blindfold usage count on raid boss.", d = "Ensure every player equips Adarus' spare blindfold at least once before engaging Soul Hunters on Normal or higher in Manaforge Omega. This requirement is account-wide and must be met by the entire group prior to the fight.", x = 10 },
        [41617] = { e = 3, s = "g", r = "Grinding wall destruction mechanic during raid fights.", d = "Focus your raid efforts on destroying fourth walls during Fractillus encounters until you reach 18 total destructions on Normal difficulty or higher. Coordinate with your team to maximize wall breaks efficiently before attempting the final kill.", x = 10 },
        [41618] = { e = 3, s = "c", h = { 214564 }, r = "Hidden assassin reveal is the main difficulty spike.", d = "Wait for the hidden assassin to reveal themselves during a Nexus-King Salhadaar fight in Manaforge Omega on Normal or higher before proceeding. Ensure the assassin is active and visible to the raid before defeating the boss.", x = 10 },
        [41619] = { e = 3, s = "c", r = "Requires specific mechanic interaction from all raid members.", d = "Allow every raid member to be hit by Reverse Gravity at least once during Dimensius encounters on Normal difficulty or higher. Do not use defensive abilities that prevent this effect, as it is required for all players.", x = 10 },
        [41626] = { e = 3, s = "g", r = "Grinding C.H.E.T.T. lists is the primary effort.", d = "Complete and turn in your first C.H.E.T.T. List to unlock the next achievement in the chain. This is an account-wide requirement, so ensure one character on your account finishes the list.", x = 10 },
        [41627] = { e = 3, s = "g", r = "Requires completing twice as many lists as previous.", d = "Turn in two completed C.H.E.T.T. Lists after unlocking the previous achievement. Continue completing lists until you have submitted two total to progress toward the next tier.", x = 10 },
        [41629] = { e = 3, s = "g", r = "Huge grind of 100 lists or waiting for title.", d = "Submit 100 completed C.H.E.T.T. Lists or wait for the Employee of the Month title to unlock this final tier. This is an account-wide goal requiring significant completion over time.", x = 10 },
        [41631] = { e = 3, s = "c", r = "Requires visiting multiple zones to honor flames.", d = "Honor the flames in all four specified zones of Khaz Algar: Azj-Kahet, Hallowfall, Isle of Dorn, and The Ringing Deeps. Complete these tasks to earn the Flame Warden title.", x = 10 },
        [41632] = { e = 3, s = "c", r = "Similar to previous, requires visiting multiple zones.", d = "Honor the flames in all four specified zones of Khaz Algar for the Flame Keeper title. Ensure you complete the necessary actions in Azj-Kahet, Hallowfall, Isle of Dorn, and The Ringing Deeps.", x = 10 },
        [41665] = { e = 3, s = "c", r = "Requires unlocking specific cosmetic or completing a feat.", d = "Unlock Mythic VFX or complete one of the listed feats of strength to earn Gallagio Highroller's Bombstone. Choose any of the available options like Chrome King Gallywix or Season 2 content.", x = 10 },
        [41694] = { e = 3, s = "s", r = "Single run with specific buff active on boss.", d = "Defeat Cauldron of Carnage in Liberation of Undermine on Normal difficulty or higher while wearing Flarendo's Biggest Fan buff. Ensure you have the buff active before engaging the boss.", x = 10 },
        [41695] = { e = 3, s = "s", r = "Single run with specific buff active on boss.", d = "Defeat Cauldron of Carnage in Liberation of Undermine on Normal difficulty or higher while wearing Torq's Biggest Fan buff. Activate the buff before starting the fight to secure the achievement.", x = 10 },
        [41706] = { e = 4, s = "c", h = { 207483 }, r = "Weekly RNG grind; Week 5 target is the hardest.", d = "Play Dastardly Duos every week to hit the rising score targets. You must complete all six weekly milestones in order; missing a week resets your progress for that tier.", x = 10 },
        [41707] = { e = 3, s = "g", r = "Grinding rare drops from damaged bosses.", d = "Defeat damaged bosses in Dastardly Duos to collect their gears. Aim for high-level matches where these variants appear frequently to gather the required twenty items quickly.", x = 10 },
        [41708] = { e = 2, s = "c", r = "Find and grab 5 specific rats in Undermine.", d = "Travel to Undermine and locate all five Grabbable Rats scattered around the zone. Interact with each one individually to complete this account-wide exploration goal.", x = 10 },
        [41711] = { e = 4, s = "s", r = "High-skill raid fight requiring perfect avoidance.", d = "Run Liberation of Undermine on Normal or higher without taking damage from specific boss abilities. Focus on dodging beams and magnets while maintaining zero hits until the kill.", x = 10 },
        [41714] = { e = 2, s = "c", r = "Collect cosmetic items from Delve trash mobs.", d = "Complete the prerequisite quest to unlock cosmetic slots for your Gob-Trotter. Then run delves repeatedly to find the specific items like the Harpoon and Green paint.", x = 10 },
        [41715] = { e = 3, s = "s", r = "Repeatable event requiring specific Vinnie interaction.", d = "Speak with Vinnie Sweets to select the Famous option during Dastardly Duos events. This unlocks a buff that helps you collect cheers more efficiently in matches.", x = 10 },
        [41716] = { e = 2, s = "c", h = { 207665 }, r = "Requires completing the Underdog achievement first.", d = "First earn the Duos Underdog achievement by dying three times then winning a match. Afterward, talk to Vinnie Sweets to unlock the Duo Darling buff for higher scores.", x = 10 },
        [41717] = { e = 3, s = "s", r = "Specific match condition: die 3 times then win.", d = "You must already have the Duo Darling achievement before attempting this one. Deliberately die three times in a single match and then secure the victory to finish it.", x = 10 },
        [41722] = { e = 3, s = "g", r = "Destroy 10 props in the Dastardly Duos event.", d = "Destroy ten Dastardly Duos props during the event to give workers job security. This action causes extra presents to spawn inside props for future runs.", x = 10 },
        [41723] = { e = 3, s = "s", r = "Grind companion XP to level 80.", d = "Ensure you have completed Buddy System VII before starting this chain. Raise your companion character to level 80 by completing its daily quests and gaining experience.", x = 10 },
        [41725] = { e = 4, s = "g", r = "Requires heavy RNG farming Echoes of N'Zoth.", d = "Purchase Echoes of N'Zoth from vendors or drops to fund research in the Hourglass. Buy enough currency to unlock every single item available for research in the vision system.", x = 7 },
        [41778] = { e = 2, s = "c", r = "Win two specific challenge mode races in Oasis.", d = "Locate the two challenge mode races in the Oasis zone and defeat the specific bosses there. Winning both races against the Slateback Alpha and Zooming Necroray completes this quest.", x = 10 },
        [41802] = { e = 3, s = "c", r = "Multiple questlines in one zone.", d = "Start these Eversong Woods quests at level 12 and follow the listed chain without interruption, as missing steps will lock progress permanently. Complete all sub-quests in order to earn the full 10 points before moving on.", x = 11 },
        [41803] = { e = 3, s = "c", r = "Multiple questlines in one zone.", d = "Begin the Zul'Aman campaign immediately upon reaching level 12, ensuring you finish every quest in the sequence to unlock the Amani appearance customization reward. Do not skip any steps, as this achievement is account-wide and time-gated by content availability.", x = 11 },
        [41804] = { e = 3, s = "c", r = "Multiple questlines in one zone.", d = "Head to Harandar at level 12 and complete the three-part questline starting with Of Caves and Cradles. Finish all tasks in order, as missing any step will prevent you from earning the achievement points.", x = 11 },
        [41805] = { e = 3, s = "c", r = "Multiple questlines with NPC companion.", d = "Travel to Arator's location at level 12 and follow the two-quest storyline involving The Path of Light and Regrets of the Past. Complete both quests consecutively to secure your 10 points without delay.", x = 11 },
        [41806] = { e = 3, s = "c", r = "Multiple questlines in one zone.", d = "Start the Voidstorm campaign at level 12 by completing Into the Abyss, followed by The Night's Veil and Dawn of Reckoning. Ensure you finish each quest in sequence, as skipping any will lock out the achievement permanently.", x = 11 },
        [41808] = { e = 2, s = "c", r = "Storyline quests in one area.", d = "Begin K'aresh storylines at level 11.2 and complete all listed quests including The Bees Knees and Nesingwary Necessities. Finish every task in order to unlock the Otherworldly Ecologist title and points.", x = 10 },
        [41809] = { e = 3, s = "g", r = "Daily quests for multiple species.", d = "Perform one daily quest for each species in the Oasis starting at level 11.2, covering all seven creatures listed. Check your calendar regularly, as missing a daily resets progress for that specific species.", x = 10 },
        [41810] = { e = 2, s = "c", r = "Play mini-game and upgrade podium.", d = "Summon the Winner's Podium and play Dastardly Duos repeatedly to maximize scores, item levels, and survival runs. Upgrade the podium by completing high-difficulty games to earn all required measures for this achievement.", x = 10 },
        [41811] = { e = 3, s = "g", r = "Level up multiple creatures.", d = "Raise every creature in the Oasis to its maximum level by completing the Raise Creatures to Max Level quests. Prioritize leveling each species fully before moving on, as incomplete integration blocks further progress.", x = 10 },
        [41812] = { e = 2, s = "c", r = "Recruit three specialist NPCs.", d = "Recruit specialists like a Botanist or Wildlife Expert at level 11.2 by completing their respective recruitment quests. Gather all three experts to assist in the Oasis and unlock the Expertly Done achievement points.", x = 10 },
        [41815] = { e = 3, s = "c", r = "Depends on other Oasis achievements.", d = "Complete all five prerequisite achievements in K'aresh, including Ecological Stability and Brokers Don't Care How You Win. Finish each sub-achievement fully before claiming the final 20 points for Ecological Succession.", x = 10 },
        [41818] = { e = 2, s = "s", r = "Complete one storyline quest chain.", d = "Finish the Rise of the Red Dawn storyline at level 11.2 by completing the single required quest. This unlocks the title of Stromgarde and awards 10 points upon completion.", x = 10 },
        [41820] = { e = 3, s = "s", r = "Storyline completion takes a few hours.", d = "Start this storyline immediately upon entering the War Within expansion to secure your title early. Focus on completing the main narrative quests without interruption, as missing key plot points will prevent progress.", x = 10 },
        [41853] = { e = 2, s = "s", r = "Single vision run is under an hour.", d = "Begin by defeating Alleria in the Revisited Horrific Vision of Stormwind to unlock the next tier. Ensure you have cleared the base vision first, as this is a sequential requirement for further challenges.", x = 7 },
        [41854] = { e = 3, s = "s", r = "Full vision run takes a few hours.", d = "Complete every objective in the Revisited Horrific Vision of Stormwind during one continuous session without leaving. This requires careful planning to finish all tasks before the instance resets or time expires.", x = 7 },
        [41855] = { e = 4, s = "s", r = "Requires masks and full vision run.", d = "Equip any five Faceless Masks and clear all objectives in the Revisited Horrific Vision of Stormwind in a single visit. Prioritize collecting masks beforehand, as this achievement is missable if you fail to complete the run with them equipped.", x = 7 },
        [41857] = { e = 3, s = "s", r = "Needs masks but single visit suffices.", d = "Finish any Revisited Horrific Vision while wearing at least one Faceless Mask to claim this title. You can do this after completing the full Horrific Visions run, so ensure you have masks available before starting.", x = 7 },
        [41858] = { e = 4, s = "s", r = "Requires six masks and full vision run.", d = "Gather six Faceless Masks and complete all objectives in a single Revisited Horrific Vision visit. This builds on previous mask achievements, so verify your inventory meets the count requirement before entering.", x = 7 },
        [41859] = { e = 3, s = "g", r = "Collecting 1000 items is a steady grind.", d = "Farm Displaced Corrupted Mementos from various sources until you reach 1000 total. Since this is account-wide, coordinate with friends if needed to speed up collection and avoid missing out on future rewards.", x = 7 },
        [41873] = { e = 2, s = "s", r = "Partial vision run takes under an hour.", d = "Enter any Revisited Horrific Vision and complete at least two objectives before defeating the boss in one go. Do not leave the instance prematurely, as partial progress may reset upon exiting.", x = 7 },
        [41874] = { e = 4, s = "s", r = "Requires five masks and full vision run.", d = "Equip five Faceless Masks and finish all objectives in a single Revisited Horrific Vision visit. This unlocks new weaponsmith rewards, so ensure you have the required masks before starting your run.", x = 7 },
        [41875] = { e = 2, s = "s", r = "Single Orgrimmar vision run is easy.", d = "Defeat Thrall in the Revisited Horrific Vision of Orgrimmar to complete this step. Make sure you have accessed the updated version of the vision, as older versions will not count toward this achievement.", x = 7 },
        [41876] = { e = 3, s = "s", r = "Full Orgrimmar vision run takes hours.", d = "Clear all objectives in the Revisited Horrific Vision of Orgrimmar during one uninterrupted session. Plan your route carefully to handle every task before time runs out or the instance resets.", x = 7 },
        [41879] = { e = 4, s = "s", r = "Requires masks and full Orgrimmar vision.", d = "Complete all objectives in the Revisited Horrific Vision of Orgrimmar while wearing five Faceless Masks in a single visit. Combine mask collection with a full run strategy to avoid needing to restart later.", x = 7 },
        [41889] = { e = 2, s = "c", r = "Collecting 8 masks is a moderate checklist grind.", d = "Farm the Faceless Masks from Horrific Visions until you have all eight. Once collected, immediately start Revisited runs to unlock the subsequent mask achievements in this chain.", x = 7 },
        [41890] = { e = 3, s = "c", r = "Requires unlocking visions and running full runs with 2 masks.", d = "Unlock Revisited Horrific Visions and equip exactly two Faceless Masks before starting a run. Complete the full vision objectives while wearing these specific masks to earn points.", x = 7 },
        [41891] = { e = 3, s = "c", r = "Requires unlocking visions and running full runs with 3 masks.", d = "After unlocking Revisited, equip three different Faceless Masks during a full vision run. Ensure you have already completed the previous mask achievement before attempting this one.", x = 7 },
        [41893] = { e = 3, s = "c", r = "Requires unlocking visions and running full runs with 4 masks.", d = "Equip four distinct Faceless Masks while completing a full Revisited Horrific Vision. This requires unlocking Revisited and finishing the prior Masked Trio achievement first.", x = 7 },
        [41894] = { e = 3, s = "c", r = "Requires unlocking visions and running full runs with 7 masks.", d = "Unlock Revisited and equip seven different Faceless Masks during a full vision run. You must complete the Masked Sextet achievement before attempting this Septet goal.", x = 7 },
        [41895] = { e = 2, s = "c", r = "Collecting all 8 masks is a moderate checklist grind.", d = "Equip all eight Faceless Masks simultaneously while completing a Revisited Horrific Vision. This is the final step in the mask progression chain after earning the Septet points.", x = 7 },
        [41896] = { e = 3, s = "g", r = "Grinding for 10k mementos takes several hours.", d = "Grind Displaced Corrupted Mementos from Horrific Visions until you reach 10,000. This is an account-wide goal, so farm efficiently across all characters to speed up progress.", x = 7 },
        [41897] = { e = 3, s = "g", r = "Grinding for 50k mementos takes many hours.", d = "Continue farming Displaced Corrupted Mementos from Horrific Visions until you hit 50,000. Since this is account-wide, keep running visions consistently without stopping to reach the higher threshold.", x = 7 },
        [41898] = { e = 3, s = "g", r = "Grinding for 75k mementos takes many hours.", d = "Farm Displaced Corrupted Mementos from Horrific Visions until you accumulate 75,000. This is a long-term account-wide goal requiring consistent vision runs over an extended period.", x = 7 },
        [41905] = { e = 2, s = "c", r = "Simple checklist of time spent in spotlight.", d = "Play Dastardly Duos matches and stay in the spotlight for increasing durations of 30, 60, and 90 seconds. You must remain stationary or move slowly within the light to track your time.", x = 10 },
        [41916] = { e = 2, s = "g", r = "Walking distance is trivial but requires multiple matches.", d = "Play Dastardly Duos matches while actively walking between objectives rather than running or flying. Accumulate distance by traversing the map carefully to reach the 500 to 4000 yard milestones.", x = 10 },
        [41922] = { e = 3, s = "c", r = "Requires winning matches without dying repeatedly.", d = "Play Dastardly Duos matches and avoid taking fatal damage until you win. You must complete consecutive victories without dying to progress through the streak requirements for this achievement.", x = 10 },
        [41928] = { e = 5, s = "c", h = { 209057 }, r = "Requires completing two difficult Horrific Visions.", d = "Complete both Revisited Horrific Visions first, then run the Even More Horrific Visions in Orgrimmar and Stormwind to unlock this account-wide pet. Ensure you finish all sub-quests within each vision before leaving, as progress carries over but specific completion flags may reset if not tracked carefully.", x = 7 },
        [41929] = { e = 5, s = "c", h = { 209060 }, r = "Requires completing two difficult Horrific Visions.", d = "Unlock the previous achievement first, then tackle The Most Horrific Vision instances in both cities along with We Have the Memories to earn the mount. This is account-wide, so coordinate with friends or use a group finder to clear all three required visions efficiently.", x = 7 },
        [41948] = { e = 3, s = "g", r = "Grind to defeat 2 bosses; manageable but tedious.", d = "Start by defeating any two Dastardly bosses from the list, noting that Rattlegore counts as one boss but requires multiple kills for later tiers. Progress through the chain sequentially, ensuring you track your total unique boss defeats to avoid missing intermediate steps.", x = 10 },
        [41949] = { e = 3, s = "g", r = "Grind to defeat 4 bosses; slightly more time.", d = "You must have completed the previous tier first; focus on defeating four distinct bosses, keeping in mind that Rattlegore needs four separate kills to count toward this specific milestone. Use a group finder or duo up with friends to clear these world events quickly.", x = 10 },
        [41950] = { e = 3, s = "g", r = "Grind to defeat 6 bosses; moderate time investment.", d = "Complete the prior tier before attempting this one, which requires six total boss defeats including multiple kills of Rattlegore. Plan your runs to maximize efficiency by targeting bosses you have already cleared in earlier tiers.", x = 10 },
        [41951] = { e = 3, s = "g", r = "Grind to defeat 8 bosses; significant time needed.", d = "Finish the previous achievement first, then defeat eight bosses total, ensuring you kill Rattlegore eight times as it is a repeatable target. Coordinate with a group to handle the higher difficulty requirements and track your progress carefully.", x = 10 },
        [41952] = { e = 3, s = "g", r = "Grind to defeat all 10 bosses; longest grind.", d = "Unlock all preceding tiers before attempting this final goal of defeating ten bosses, which includes killing Rattlegore ten times. This account-wide achievement requires persistent grinding across multiple world event instances until the counter reaches the maximum.", x = 10 },
        [41960] = { e = 2, s = "s", r = "Single dungeon kill on normal difficulty.", d = "Enter Murder Row dungeon and defeat Lithiel Cinderfury on Normal or Heroic difficulty to claim this point. Ensure you are prepared for the mechanics of this specific encounter before attempting the kill.", x = 11 },
        [41961] = { e = 3, s = "s", r = "Single dungeon kill on Heroic difficulty.", d = "First clear the normal version, then re-enter Murder Row on Heroic difficulty or higher to defeat Lithiel Cinderfury again. This step is mandatory before progressing to Mythic, so verify your group's gear and skill level first.", x = 11 },
        [41962] = { e = 5, s = "s", r = "Requires Mythic+ key; high skill/RNG dependency.", d = "Complete the Heroic tier first, then challenge Lithiel Cinderfury on Mythic or Mythic Keystone difficulty for this final point. Prepare for significantly increased mechanics and damage output during this run.", x = 11 },
        [41964] = { e = 5, s = "c", r = "Requires perfect run with all masks active.", d = "Unlock The Most Horrific Vision of Stormwind first, then enter the Revisited version with all eight Faceless Masks active to complete objectives in one visit. Do not leave the instance until all masks are active, as progress may reset otherwise.", x = 7 },
        [41965] = { e = 5, s = "c", r = "Requires perfect run with all masks active.", d = "Finish The Most Horrific Vision of Orgrimmar before attempting this one, ensuring you have all eight Faceless Masks equipped upon entry. Complete every objective in a single continuous run without leaving the instance to secure the achievement.", x = 7 },
        [41966] = { e = 5, s = "c", h = { 209179, 209180 }, r = "Requires high-level Horrific Visions runs with heavy RNG.", d = "Start the Revisited Horrific Visions campaign to unlock this meta achievement. Focus on completing the specific Stormwind and Orgrimmar visions listed in the requirements first.", x = 7 },
        [41970] = { e = 3, s = "c", r = "Campaign storylines take a few hours to complete.", d = "Begin the K'aresh storyline immediately after reaching Renown rank 11.2 to ensure you have access to all necessary campaign content for this questline.", x = 10 },
        [41978] = { e = 2, s = "g", r = "Collecting 2 warrants is quick solo play.", d = "Complete exactly two Warrant quests in K'aresh by defeating the listed targets like So'zer and Grubber. This unlocks the next stage of the bounty chain.", x = 10 },
        [41979] = { e = 3, s = "g", r = "Requires completing previous warrant quests first.", d = "Finish four total Warrant quests in K'aresh, ensuring you have already completed the Moonlighter achievement first. You will need to defeat specific targets multiple times.", x = 10 },
        [41980] = { e = 4, s = "g", r = "Completing all warrants involves significant grinding.", d = "Clear all remaining Warrants in K'aresh after completing Bounty Seeker. This requires defeating every listed target, including Xy'vox the Twisted four times.", x = 10 },
        [41983] = { e = 4, s = "g", r = "Gathering 25k mementos is a long collection grind.", d = "Farm Displaced Corrupted Mementos by running the Memento Mori scenario repeatedly until you reach the 25,000 count. This is a grind that requires significant time investment.", x = 7 },
        [41996] = { e = 3, s = "s", r = "Completing the scenario takes a few hours.", d = "Complete the Nightfall Scenario five separate times to earn this exploration achievement. Ensure you finish the full scenario each time to avoid missing progress.", x = 10 },
        [41997] = { e = 3, s = "g", r = "Reaching Renown 10 requires daily quests and time.", d = "Grind reputation with Flame's Radiance until you reach Renown rank 10. This is a straightforward grind but requires consistent participation in related activities.", x = 10 },
        [41998] = { e = 2, s = "g", r = "Completing 10 daily quests is relatively easy.", d = "Complete ten daily Incursion quests located in Hallowfall or Azj-Kahet. Check your daily quest log regularly to track progress toward this goal.", x = 10 },
        [41999] = { e = 3, s = "g", r = "Killing 5 rare elites takes some hunting time.", d = "Hunt and kill five specific Nightfall elites found in Hallowfall or Azj-Kahet. These are rare enemies, so be prepared for difficult encounters.", x = 10 },
        [42002] = { e = 1, s = "s", r = "Using the bullhorn once in a match is trivial.", d = "Use the Bullhorn of Calling item five times during a single Dastardly Duos match to unlock this world event achievement. Coordinate with your party for efficiency.", x = 10 },
        [42003] = { e = 2, s = "s", r = "Using the bullhorn ten times is easy solo.", d = "Use the Bullhorn of Calling ten times in one match after unlocking the previous stage. This requires a full team effort during a Dastardly Duos session.", x = 10 },
        [42004] = { e = 4, s = "c", h = { 209420 }, r = "Requires grinding Duos matches with specific item usage.", d = "Join a group and use the Bullhorn of Calling frequently during Dastardly Duos matches to call out enemies. Ensure your party uses it at least 15 times per match, as this is account-wide but requires active participation.", x = 10 },
        [42022] = { e = 3, s = "g", r = "Grinding reputation to max rank takes time.", d = "Focus on raising your reputation with The K'aresh Trust in the War Within expansion until you reach rank 20. This is an account-wide achievement, so any character can contribute to progress.", x = 10 },
        [42029] = { e = 5, s = "c", h = { 209568, 209569, 209570 }, r = "Legion raid bosses require group coordination and RNG.", d = "Queue for The Emerald Nightmare raid on Normal difficulty or higher and defeat all bosses. Note that this content is time-gated and may require a full group to complete efficiently.", x = 6 },
        [42030] = { e = 5, s = "c", h = { 209572, 209573, 209574 }, r = "Legion raid bosses require group coordination and RNG.", d = "Defeat every boss in The Nighthold raid on Normal difficulty or higher. This achievement is account-wide, so coordinate with friends or use the dungeon finder if you lack a group.", x = 6 },
        [42031] = { e = 5, s = "c", h = { 209577, 209578, 209579 }, r = "Legion raid bosses require group coordination and RNG.", d = "Clear all bosses in Tomb of Sargeras on Normal difficulty or higher. Be aware that this raid has specific mechanics and may require multiple attempts to complete all encounters.", x = 6 },
        [42032] = { e = 5, s = "c", h = { 209582, 209583, 209584 }, r = "Legion raid bosses require group coordination and RNG.", d = "Defeat all bosses in Antorus, the Burning Throne on Normal difficulty or higher. This is an account-wide achievement, so progress can be made by any character in your account.", x = 6 },
        [42045] = { e = 4, s = "c", h = { 209652, 209653, 209654 }, r = "Multiple questlines require travel and completion.", d = "Complete the entire Midnight storyline quest chain, which includes several specific quests listed in the info field. Ensure you finish all parts of the campaign to unlock this achievement.", x = 11 },
        [42114] = { e = 4, s = "c", h = { 218485, 218486, 218487 }, r = "Requires completing multiple distinct zone achievements.", d = "Work on multiple Broken Isles achievements simultaneously, such as becoming a Loremaster or collecting treasures from each zone. This is an account-wide goal that requires diverse exploration and quest completion.", x = 6 },
        [42117] = { e = 3, s = "c", h = { 209724, 209725, 209726 }, r = "Multiple questlines require travel and completion.", d = "Finish the max level questlines for The War of Light and Shadow, including specific quests like Foothold and The Voidspire. These are account-wide, so progress carries across all characters.", x = 11 },
        [42118] = { e = 3, s = "g", r = "Grinding a specific mechanic in a raid instance.", d = "Save all mice from atomization in Manaforge Omega on Normal difficulty or higher before defeating the Plexus Sentinel. This is a specific raid mechanic that must be completed to earn the achievement.", x = 10 },
        [42131] = { e = 3, s = "g", r = "Grinding honor requires time and War Mode usage.", d = "Enable War Mode and earn 1000 honor points specifically in K'aresh PvP zones. This is an account-wide achievement, so any character can contribute to reaching the required honor total.", x = 10 },
        [42187] = { e = 3, s = "s", r = "Requires completing a specific lorewalking campaign.", d = "Complete the Ethereals Lorewalking Campaign by finishing all associated quests, including the final quest for Ethereal Wisdom. This is an account-wide achievement with a decorative scroll reward upon completion.", x = 10 },
        [42188] = { e = 3, s = "c", r = "Requires completing a full campaign storyline.", d = "Start the Xal'atath Lorewalking Campaign in patch 11.1.7 to earn your reward. Ensure you are on a supported account since this is account-wide.", x = 10 },
        [42189] = { e = 3, s = "c", r = "Requires completing a full campaign storyline.", d = "Begin the Lich King Lorewalking Campaign available in patch 11.1.7. This achievement is account-wide, so any character can complete it for everyone.", x = 10 },
        [42191] = { e = 2, s = "g", r = "Buying tabs is quick but requires six purchases.", d = "Purchase six bank tabs from a banker NPC to unlock this achievement. You must buy them on different characters or use multiple accounts if needed.", x = 10 },
        [42270] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Complete the Death Knight Order Hall Campaign in Legion. Finish all class quests before patch changes affect availability.", x = 6 },
        [42271] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Finish the Demon Hunter Order Hall Campaign during Legion. Do not delay this as content may become unavailable later.", x = 6 },
        [42272] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Complete the Druid Order Hall Campaign in Legion. Ensure you finish all steps before leaving the expansion era.", x = 6 },
        [42273] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Finish the Hunter Order Hall Campaign in Legion. This is account-wide, so one character can complete it for your whole account.", x = 6 },
        [42274] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Complete the Mage Order Hall Campaign in Legion. Start this early as class hall content often gets removed after expansions end.", x = 6 },
        [42275] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Finish the Monk Order Hall Campaign in Legion. Make sure to complete all required quests before the expansion concludes.", x = 6 },
        [42276] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Complete the Paladin Order Hall Campaign in Legion. This is account-wide, so any character can finish it for your entire account.", x = 6 },
        [42277] = { e = 3, s = "c", r = "Requires completing a full class hall campaign.", d = "Finish the Priest Order Hall Campaign in Legion. Do not miss this opportunity as class hall content is often removed later.", x = 6 },
        [42278] = { e = 3, s = "c", r = "Requires completing multiple specific quests in sequence.", d = "Complete The Empty Cradle questline alongside Legends of the Haranir in patch 12.0. Check for specific local requirements to ensure progress.", x = 11 },
        [42279] = { e = 3, s = "s", r = "Complete a class campaign with multiple steps.", d = "Complete the Rogue Order Hall campaign in Legion. This is account-wide and grants a decor reward.", x = 6 },
        [42280] = { e = 3, s = "s", r = "Complete a class campaign with multiple steps.", d = "Finish the Shaman Order Hall campaign during Legion. It unlocks an account-wide decor item.", x = 6 },
        [42281] = { e = 3, s = "s", r = "Complete a class campaign with multiple steps.", d = "Complete the Warlock Order Hall campaign in Legion for your account-wide decor reward.", x = 6 },
        [42282] = { e = 3, s = "s", r = "Complete a class campaign with multiple steps.", d = "Finish the Warrior Order Hall campaign in Legion to earn the account-wide shield wall decor.", x = 6 },
        [42283] = { e = 4, s = "c", h = { 221302, 221303, 221304 }, r = "Grinding artisan achievements across zones is hard.", d = "You must complete all four Artisan of Azeroth achievements first. This unlocks a travel method for Dundun.", x = 11 },
        [42287] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Death Knight artifact hidden appearance in Legion to earn the account-wide decor reward.", x = 6 },
        [42288] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Demon Hunter artifact hidden appearance in Legion for your account-wide decor reward.", x = 6 },
        [42289] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Druid artifact hidden appearance in Legion to receive the account-wide cutting decor.", x = 6 },
        [42290] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Hunter artifact hidden appearance in Legion for the account-wide altar decor reward.", x = 6 },
        [42291] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Mage artifact hidden appearance in Legion to earn the account-wide conjured altar.", x = 6 },
        [42292] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Monk artifact hidden appearance in Legion for the account-wide forge decor reward.", x = 6 },
        [42293] = { e = 3, s = "s", r = "Unlock hidden artifact appearance via campaign steps.", d = "Unlock the Paladin artifact hidden appearance in Legion to receive the account-wide altar decor.", x = 6 },
        [42294] = { e = 3, s = "c", r = "Requires unlocking specific artifact appearance via class hall quest.", d = "Unlock the hidden Priest artifact appearance by completing the Legion Class Hall questline and leveling your character to level 80 in Legion Remix. This is account-wide, so any class on your account can unlock it for everyone.", x = 6 },
        [42295] = { e = 3, s = "c", r = "Requires unlocking specific artifact appearance via class hall quest.", d = "Complete the Rogue-specific artifact quest chain in Legion Remix to unlock the hidden Shadowblade appearance. Ensure you are playing a Rogue or have one on your account to access this content.", x = 6 },
        [42296] = { e = 3, s = "c", r = "Requires unlocking specific artifact appearance via class hall quest.", d = "Follow the Shaman artifact progression in Legion Remix to reveal the hidden Farseer appearance. This achievement is account-wide, allowing any Shaman on your account to complete it.", x = 6 },
        [42297] = { e = 3, s = "c", r = "Requires unlocking specific artifact appearance via class hall quest.", d = "Unlock the Warlock artifact by finishing the relevant Legion Remix questline for the Netherlord appearance. You must have a Warlock character at level 80 in Legion Remix to start this process.", x = 6 },
        [42298] = { e = 3, s = "c", r = "Requires unlocking specific artifact appearance via class hall quest.", d = "Complete the Warrior artifact quest chain in Legion Remix to unlock the hidden Battlelord appearance. This requires a level 80 Warrior in the Legion Remix environment.", x = 6 },
        [42299] = { e = 3, s = "s", r = "Complete a storyline campaign; moderate time investment.", d = "Start the Visions of a Shadowed Sun storyline immediately after patch 11.2.7, as it is time-gated and cannot be completed retroactively. Play through the campaign quests to finish this account-wide achievement.", x = 10 },
        [42301] = { e = 5, s = "g", r = "Grinding to level 80 in Remix mode is a long process.", d = "Begin playing Legion Remix mode and level your Timerunner character to 80 to claim this title. This is a legacy achievement that requires specific game mode access.", x = 6 },
        [42312] = { e = 4, s = "g", r = "Requires significant grinding to earn first artifact weapon.", d = "After reaching level 80 in Legion Remix, engage in content like dungeons or raids to earn your first Artifact Weapon for the Timerunner. This unlocks the next step in the artifact progression chain.", x = 6 },
        [42313] = { e = 2, s = "s", r = "Introductory experience; short quest chain to start journey.", d = "Accept the introductory quest for Legion Remix to officially begin your journey as a Timerunner. Complete this initial experience before attempting any other artifact-related achievements in the mode.", x = 6 },
        [42314] = { e = 5, s = "g", r = "Grinding 10k artifact power is a long, repetitive task.", d = "Grind content in Legion Remix to accumulate 10,000 Infinite Power on a single character. This is a significant time investment but unlocks the next tier of artifact power milestones.", x = 6 },
        [42315] = { e = 5, s = "g", r = "Grinding 50k artifact power is a very long, repetitive task.", d = "Continue farming content after reaching 10,000 power until you hit 50,000 Infinite Power on one character. Be prepared for a long grind as this requires substantial time in Legion Remix.", x = 6 },
        [42316] = { e = 4, s = "g", r = "Collecting full tier set from fractals requires many runs.", d = "Collect a full Tier 34 armor set from Manaforge Omega to complete this collection achievement. You must gather all pieces on at least one class, which may require multiple runs of the fractal.", x = 10 },
        [42317] = { e = 3, s = "c", r = "Multiple timed story quests requiring specific class and zone access.", d = "Use a Timerunner to complete all listed Azsuna quests in order. Ensure you finish the final quest twice as required by the description. This is account-wide and cannot be missed if done during the Legion Remix event.", x = 6 },
        [42318] = { e = 4, s = "g", r = "Requires farming reputation to Exalted with a high kill count.", d = "Grind reputation with the Court of Farondis until reaching Exalted status using a Timerunner. Focus on daily quests or world events in Azsuna to gain points quickly. This is account-wide and requires no specific group composition.", x = 6 },
        [42319] = { e = 3, s = "c", r = "Select two of several timed achievements in the Azsuna zone.", d = "Complete any two of the listed Azsuna achievements with a Timerunner. Prioritize solo-friendly tasks like Tour Azsuna or Looking for Group: Azsuna to save time. This is account-wide and unlocks the Fledgling Warden's Companion pet.", x = 6 },
        [42320] = { e = 4, s = "g", r = "Requires completing all Legion Remix dungeons with a timer.", d = "Queue for all Legion dungeons on any difficulty using a Timerunner. Start with normal difficulties to learn mechanics before attempting higher tiers if needed. This is account-wide and rewards Infinite Knowledge.", x = 6 },
        [42321] = { e = 5, s = "c", h = { 215398, 215400, 215401 }, r = "Requires clearing all Legion raids; Emerald Nightmare is the hardest.", d = "Complete all listed Legion raids on any difficulty using a Timerunner. Coordinate with friends or use the dungeon finder for efficient clearing. This is account-wide and unlocks a Bronze Cache and decor reward.", x = 6 },
        [42325] = { e = 4, s = "c", h = { 211461 }, r = "Requires defeating a specific Mythic+ boss or completing seasonal content.", d = "Choose one of the listed achievements to complete without wearing void gear. The Mythic: Dimensius achievement is often the most straightforward option for players. This is account-wide and rewards a K'areshi Voidstone.", x = 10 },
        [42328] = { e = 3, s = "g", r = "Requires leveling one character to 90; effort depends on starting level.", d = "Level one character to 90 to unlock the Warband Mentor bonus. Use experience boosters or group content to speed up the process. This is account-wide and provides a permanent XP buff for future leveling.", x = 11 },
        [42329] = { e = 3, s = "g", r = "Requires leveling a second character to 90; effort scales with count.", d = "Level two characters to 90 after completing the first mentor achievement. Create alts if necessary to maximize your XP gain from the previous bonus. This is account-wide and increases your XP buff further.", x = 11 },
        [42330] = { e = 3, s = "g", r = "Requires leveling a third character to 90; effort scales with count.", d = "Reach level 90 on three characters after unlocking the two-character milestone. Continue using alts or existing low-level characters to meet the requirement efficiently. This is account-wide and grants an even larger XP boost.", x = 11 },
        [42331] = { e = 3, s = "g", r = "Requires leveling a fourth character to 90; effort scales with count.", d = "Level four characters to 90 following the three-character achievement completion. Manage your character slots wisely as you need multiple alts for this goal. This is account-wide and significantly accelerates leveling for all characters.", x = 11 },
        [42332] = { e = 3, s = "g", r = "Requires leveling a fifth character to 90; effort scales with count.", d = "Achieve level 90 on five characters after completing the four-character milestone. Plan your alt creation carefully to ensure you can reach the final count without wasting time. This is account-wide and offers the maximum XP bonus available.", x = 11 },
        [42502] = { e = 3, s = "s", r = "Requires obtaining a second artifact weapon; partial progress does not matter.", d = "Obtain your second Artifact Weapon using a Timerunner after getting your first one. Check your collection to see which weapon you already own before starting. This is account-wide and requires completing the previous artifact achievement.", x = 6 },
        [42503] = { e = 3, s = "g", r = "Grinding artifact power is a long solo grind.", d = "Earn your third Artifact Weapon in Legion Remix by completing the previous tier and focusing on any class that drops weapons. This is account-wide, so coordinate with friends if you need specific weapon types.", x = 6 },
        [42504] = { e = 3, s = "s", r = "Leveling to 80 takes time but no RNG.", d = "Reach level 80 with a Paladin character to unlock this achievement; ensure you are playing in Legion Remix mode. No group is needed, but solo leveling may be slower depending on your gear.", x = 6 },
        [42505] = { e = 4, s = "g", r = "100k AP is a significant solo grind.", d = "Accumulate 100,000 Infinite Power on a single Timerunner by farming dungeons or world bosses efficiently. This requires completing the previous tier first and can be done account-wide across different characters.", x = 6 },
        [42506] = { e = 4, s = "g", r = "250k AP requires more grinding time.", d = "Continue farming content to reach 250,000 Infinite Power on one character after unlocking the prior tier. Plan your runs carefully as this is a cumulative goal tied to a single Timerunner.", x = 6 },
        [42507] = { e = 4, s = "g", r = "500k AP is a long solo grind.", d = "Push toward 500,000 Infinite Power by consistently running high-yield activities like Mythic+ dungeons or world bosses. Remember that progress resets if you switch characters, so stick with one Timerunner.", x = 6 },
        [42508] = { e = 4, s = "g", r = "750k AP continues the grinding effort.", d = "Aim for 750,000 Infinite Power on a single character by optimizing your farming routes and choosing efficient content. This step builds directly on the previous tier and requires sustained effort.", x = 6 },
        [42509] = { e = 4, s = "g", r = "1M AP is a very long solo grind.", d = "Reach 1,000,000 Infinite Power by maintaining steady progress through dungeons or raids. Avoid switching characters to prevent resetting your cumulative power count toward this goal.", x = 6 },
        [42510] = { e = 4, s = "g", r = "1.25M AP requires extensive grinding.", d = "Farm diligently to hit 1,250,000 Infinite Power on one Timerunner; consider grouping with others for faster completion. This achievement is account-wide but must be earned by a single character.", x = 6 },
        [42511] = { e = 4, s = "g", r = "1.5M AP is a massive solo grind.", d = "Continue accumulating power to reach 1,500,000 on a single character without switching accounts or characters. Use high-level content like Mythic+ dungeons for maximum efficiency.", x = 6 },
        [42512] = { e = 4, s = "g", r = "2M AP is an extremely long grind.", d = "Push toward 2,000,000 Infinite Power by focusing on consistent daily farming and avoiding interruptions. This tier requires dedication as it builds directly on the previous milestone.", x = 6 },
        [42513] = { e = 4, s = "g", r = "3M AP is a huge solo grind.", d = "Accumulate 3,000,000 Infinite Power on one character by maximizing your time in Legion Remix content. Stick to a single Timerunner to avoid resetting progress toward this goal.", x = 6 },
        [42514] = { e = 4, s = "g", r = "5M AP is the hardest solo grind.", d = "Reach the final milestone of 5,000,000 Infinite Power by persistently farming high-yield activities. This is the last step in the chain and requires unwavering focus on one character.", x = 6 },
        [42515] = { e = 3, s = "c", r = "Requires group for world boss and exploring zones.", d = "Use a Timerunner to reveal all covered areas, defeat rare elites, and recover treasures in Azsuna. Start with the main story quests to unlock zones quickly, then run around for rares and hidden chests. No group is needed for this part, but world bosses require a party.", x = 6 },
        [42516] = { e = 3, s = "g", r = "Exploring entire zone takes several hours of travel.", d = "Fly or use mounts to visit every named location listed in the info field to reveal them on the map. This is purely exploration-based, so take your time to ensure no zone segment is missed before logging off. No group required, but flying makes it significantly faster.", x = 6 },
        [42517] = { e = 3, s = "g", r = "Collecting eight scattered items across the zone.", d = "Search for and collect eight specific treasure items scattered throughout Azsuna. These often require checking quest givers or completing small sub-quests, so follow any active daily quests that mention treasures. Do not miss this if you plan to clear the zone later without a Timerunner.", x = 6 },
        [42518] = { e = 4, s = "c", h = { 212947 }, r = "Many encounters; Unbound Rift is a major RNG grind.", d = "Complete five of the listed special encounters, which include world bosses and rare spawns like Valiyaka or Mrrgrl. Check your quest log for active vignettes in Azsuna and prioritize those that appear as daily objectives. Some may require a group, so form one if an encounter fails to spawn solo.", x = 6 },
        [42519] = { e = 3, s = "c", r = "Two group dungeons take a few hours total.", d = "Gather a group to complete the Eye of Azshara dungeon and the Vault of the Wardens instance. These are group-only activities, so find a party via LFG or friends before entering. Clearing these unlocks the achievement immediately upon completion.", x = 6 },
        [42526] = { e = 4, s = "s", r = "World boss requires group and waiting for spawn.", d = "Defeat Calamir, the world boss in Azsuna, which requires a full raid group. Coordinate with other players to pull him down, as he has high health and mechanics that demand coordination. This is time-gated if you do not clear him during his spawn window.", x = 6 },
        [42527] = { e = 4, s = "s", r = "World boss requires group and waiting for spawn.", d = "Defeat Levantus, another world boss in Azsuna, similar to Calamir but with different mechanics. Ensure your group is ready for a tough fight involving multiple phases. Like other world bosses, this can be missable if you fail to kill him before he despawns.", x = 6 },
        [42528] = { e = 3, s = "g", r = "Exploring entire Highmountain zone takes several hours.", d = "Explore Highmountain by visiting all named locations on the map using a Timerunner. Fly around the zone systematically to ensure every area is revealed. This is account-wide and does not require a group, but flying is essential for efficiency.", x = 6 },
        [42529] = { e = 4, s = "s", r = "World boss requires group and waiting for spawn.", d = "Defeat Humongris in Val'Sharah, which is a world boss requiring a raid group. Prepare your party with appropriate gear and cooldowns before engaging. This encounter can be missed if you do not participate during its spawn time.", x = 6 },
        [42530] = { e = 4, s = "s", r = "World boss requires group and waiting for spawn.", d = "Defeat Si'vash on The Broken Shore, another world boss that needs a full group. Coordinate with other players to ensure the fight is completed successfully. Be aware of his mechanics and prepare for high damage phases to avoid wipes.", x = 6 },
        [42531] = { e = 4, s = "c", h = { 215592 }, r = "Heroic raid; Cenarius is a heavy RNG encounter.", d = "Clear Heroic difficulty in Emerald Nightmare by defeating all listed bosses including Nythendra and Cenarius. This requires a well-coordinated raid group with good gear and strategy. Do not attempt this solo or undergeared, as it is extremely challenging on Heroic.", x = 6 },
        [42533] = { e = 3, s = "s", r = "Single dungeon run takes about an hour with group.", d = "Form a group to complete Neltharion's Lair in Highmountain, which is a dungeon requiring coordination. Use the LFG tool to find players and clear the instance efficiently. This activity is group-only and cannot be completed solo.", x = 6 },
        [42534] = { e = 4, s = "g", r = "World boss requires group coordination and RNG.", d = "Queue for Argus Invasion Points and defeat Sotanathor during the event window. This is a world boss fight requiring a group, so coordinate with others or use LFG tools. Do not miss the invasion timer as the opportunity is time-gated.", x = 6 },
        [42535] = { e = 3, s = "g", r = "Exploration takes time but is doable solo.", d = "Travel to Eredath and interact with the Timerunner to reveal covered map areas. Ensure you visit all specific locations marked on your map before the event ends. This achievement tracks exploration progress automatically once triggered.", x = 6 },
        [42536] = { e = 4, s = "g", r = "World boss requires group coordination and RNG.", d = "Locate Nithogg in Stormheim and defeat him as a world boss during an active invasion point. You must be present for the entire fight duration to claim credit. Plan your group composition carefully since this is a high-level encounter.", x = 6 },
        [42537] = { e = 3, s = "c", h = { 211842 }, r = "Quest chain; March on Suramar is hardest.", d = "Complete all listed Suramar storyline quests using the Timerunner tool provided in the achievement tracker. Start with the earliest quest chain to ensure smooth progression through the narrative. Missing any single quest will prevent completion of this specific legacy goal.", x = 6 },
        [42538] = { e = 4, s = "g", r = "World boss requires group coordination and RNG.", d = "Participate in Argus Invasion Points and defeat Mistress Alluradel while she is active as a world boss. Coordinate with your raid group to handle her mechanics efficiently. The achievement requires defeating her specifically during the invasion event window.", x = 6 },
        [42539] = { e = 3, s = "g", r = "Requires completing 30 world quests.", d = "Complete thirty world quests across the Broken Isles using the Timerunner feature for tracking progress. Prioritize high-value world quest hubs like Dazar'alor or Suramar to maximize efficiency. Ensure you finish this tier before moving on to the next in the chain.", x = 6 },
        [42540] = { e = 3, s = "c", h = { 211824 }, r = "Two instances; Tomb of Sargeras is harder.", d = "Form a group and complete both Cathedral of Eternal Night and Tomb of Sargeras activities on The Broken Shore. These are specific group objectives within the raid instance, so coordinate with other players. Both instances must be cleared to earn the achievement points.", x = 6 },
        [42541] = { e = 3, s = "c", h = { 214234 }, r = "Pick two; Campaign is the main effort.", d = "Finish two achievements related to Highmountain, such as the campaign or world quests, using the Timerunner. Start with the main campaign questline to unlock subsequent content naturally. This meta-achievement rewards a pet upon completion of any two sub-goals.", x = 6 },
        [42542] = { e = 4, s = "g", r = "World boss requires group coordination and RNG.", d = "Defeat Drugon the Frostblood in Highmountain during an Invasion Point event. This is a world boss encounter that requires group coordination and timing. Wait for the invasion point to spawn before attempting the fight to ensure credit.", x = 6 },
        [42543] = { e = 5, s = "c", r = "Mythic raid bosses require high skill/group.", d = "Clear The Nighthold raid on Heroic difficulty by defeating all listed bosses including Gul'dan and Elisande. You must kill every enemy in the achievement list, which includes adds and main bosses. Ensure your group is prepared for Heroic mechanics before starting.", x = 6 },
        [42544] = { e = 4, s = "c", h = { 215637, 215630, 215634 }, r = "Requires full raid group and defeating all Nighthold bosses on Mythic.", d = "Run The Nighthold raid on Mythic difficulty and defeat all listed enemies including Gul'dan and Elisande. This requires a highly skilled group capable of handling Mythic-level mechanics. Coordinate with other players to ensure all bosses are killed efficiently.", x = 6 },
        [42547] = { e = 4, s = "g", r = "Requires killing many mobs for reputation.", d = "Earn Exalted reputation with the Highmountain Tribe by completing quests and world activities in the zone. Focus on daily quests and world events to gain reputation quickly. This achievement tracks total reputation gained, so consistent play is key.", x = 6 },
        [42549] = { e = 4, s = "c", h = { 214276, 214277, 214317 }, r = "Requires rare drops and specific encounters on Argus.", d = "Use a Timerunner character to complete two of the listed Argus achievements. Prioritize 'You Are Now Prepared!' as it unlocks other content, but ensure you have access to the Remix version of Legion.", x = 6 },
        [42551] = { e = 4, s = "c", h = { 211816, 211817 }, r = "Court of Stars and Nighthold are difficult group content.", d = "This requires a group to finish specific Suramar activities like The Arcway and Court of Stars. Form a party early since these are group-only objectives within the Suramar zone.", x = 6 },
        [42552] = { e = 3, s = "g", r = "Multiple storylines require significant time investment.", d = "Complete all Highmountain storylines with a Timerunner character to earn the memento. Ensure you have unlocked the Remix version of Legion before starting these quests.", x = 6 },
        [42553] = { e = 5, s = "c", h = { 215609, 215610, 215611 }, r = "Nighthold LFR bosses require raid coordination and RNG.", d = "Run The Nighthold on Raid Finder to defeat all listed bosses for the cache. This is account-wide, so any character can contribute once the raid is accessible.", x = 6 },
        [42554] = { e = 5, s = "c", h = { 215549, 215550 }, r = "Antorus LFR requires high-level group play and luck.", d = "Clear Antorus the Burning Throne on Raid Finder to defeat every boss listed. Note that this requires the Remix version of Legion and may have time gates if not done promptly.", x = 6 },
        [42555] = { e = 3, s = "g", r = "Requires completing 100 world quests over time.", d = "Complete exactly 100 world quests across the Broken Isles using a Timerunner character. Track your count carefully as this achievement is part of a tiered chain.", x = 6 },
        [42558] = { e = 4, s = "c", h = { 215605 }, r = "Trial of Valor LFR requires raid group and RNG.", d = "Defeat Odyn, Helya, and Guarm in Trial of Valor on Raid Finder. Use a Timerunner character to ensure you can access the Remix content if needed.", x = 6 },
        [42559] = { e = 3, s = "s", r = "World boss fight is difficult but obtainable solo/group.", d = "Find and defeat Ana-Mouz in Suramar for the cache. This is a world boss fight that may require specific conditions or timing depending on your server state.", x = 6 },
        [42560] = { e = 1, s = "g", r = "Exploration is straightforward once areas are known.", d = "Explore Antoran Wastes with a Timerunner to reveal covered map areas. Focus on finding hidden points of interest and defeating rare enemies in the zone.", x = 6 },
        [42564] = { e = 3, s = "c", h = { 214265 }, r = "Elusive Foes requires finding specific rare spawns.", d = "Tour Suramar by recovering treasures, defeating rares, and exploring the zone with a Timerunner. Complete the three sub-achievements to unlock the Lesser Bronze Cache reward.", x = 6 },
        [42565] = { e = 5, s = "c", h = { 215842, 215853 }, r = "Requires completing all Order Hall campaigns across classes.", d = "Finish all Order Hall Campaigns for every class using Timerunner characters. This is account-wide, so coordinate with friends or use multiple alts if possible.", x = 6 },
        [42567] = { e = 3, s = "c", h = { 214283 }, r = "Elusive Foes on Argus requires finding rare spawns.", d = "Tour Argus by recovering treasures, defeating elusive foes, and exploring the zone with a Timerunner. Ensure you have the Remix version of Legion to access this content.", x = 6 },
        [42570] = { e = 3, s = "g", r = "Requires completing 50 world quests with a specific companion.", d = "Complete 50 world quests with a Timerunner in Broken Isles. Start by finishing lower-tier achievements first to unlock this tier. Note that you must use the specific Remix version of Legion.", x = 6 },
        [42573] = { e = 3, s = "g", r = "Exploring covered map areas is time-consuming but straightforward.", d = "Explore Val'Sharah with a Timerunner to reveal covered map areas. This is account-wide, so ensure your character has visited every zone section. No special group is needed for this specific task.", x = 6 },
        [42574] = { e = 4, s = "c", h = { 215458 }, r = "Defeating a specific world boss during an invasion event.", d = "Defeat Matron Folnuna during an Invasion Point on Argus. Wait for the invasion event to start and then kill her quickly. This requires the Remix version of Legion and is account-wide.", x = 6 },
        [42575] = { e = 3, s = "g", r = "Killing three rare enemies in a zone is moderate effort.", d = "Kill three rare enemies in Antoran Wastes. These targets are often found near world bosses or in specific zones. Use a Timerunner to track your progress efficiently.", x = 6 },
        [42576] = { e = 5, s = "c", h = { 215657, 215658, 215659 }, r = "Requires clearing multiple bosses in a Mythic raid.", d = "Defeat all listed Mythic raid bosses in Tomb of Sargeras. You must clear the entire raid on Mythic difficulty to count for this achievement. This is account-wide and requires the Remix version.", x = 6 },
        [42577] = { e = 3, s = "g", r = "Finding two hidden treasures involves exploration and RNG.", d = "Find two lost treasures hidden throughout Suramar. Explore the city thoroughly, checking chests and secret areas. Use a Timerunner to ensure you are tracking progress correctly.", x = 6 },
        [42578] = { e = 4, s = "c", h = { 211811, 211812, 211813 }, r = "Requires completing multiple group instances in a zone.", d = "Complete group activities in Stormheim including Halls of Valor and Trial of Valor. You will need a party for these instances. Finish the campaign first if you haven't already.", x = 6 },
        [42579] = { e = 3, s = "g", r = "Killing three rare enemies in Highmountain is moderate effort.", d = "Defeat three rare enemies in Highmountain. Look for glowing or unique models that indicate rare spawns. Use a Timerunner to monitor your completion status.", x = 6 },
        [42580] = { e = 3, s = "g", r = "Killing three rare enemies in Val'Sharah is moderate effort.", d = "Defeat three rare enemies in Val'Sharah. These can be found in various zones within the region. Ensure you are playing on the Remix version of Legion.", x = 6 },
        [42581] = { e = 4, s = "c", h = { 215460 }, r = "Defeating a specific world boss during an invasion event.", d = "Defeat Inquisitor Meto during an Invasion Point on Argus. This is a world boss event, so wait for the invasion to begin. It is account-wide and requires the Remix version.", x = 6 },
        [42582] = { e = 3, s = "c", r = "Requires completing two of several available zone achievements.", d = "Complete two Stormheim achievements with a Timerunner. Prioritize finishing the main campaign and group activities first. This unlocks other related achievements in the chain.", x = 6 },
        [42583] = { e = 5, s = "c", h = { 215564, 215565, 215566 }, r = "Requires clearing multiple bosses in a Mythic raid.", d = "Defeat all Mythic raid bosses in Antorus the Burning Throne. Clear the entire raid to satisfy the requirement. This is account-wide and requires the Remix version of Legion.", x = 6 },
        [42586] = { e = 3, s = "c", r = "Requires completing multiple Legion quests with a specific character.", d = "Use a Timerunner to complete all Suramar questlines listed in the achievement info. Start with An Ancient Gift and finish with Jandvik's Jarl, ensuring you do not miss any intermediate quests like Breaking The Lightbreaker.", x = 6 },
        [42588] = { e = 3, s = "g", r = "Finding two hidden treasures involves searching and some luck.", d = "Search Krokuun for two hidden treasures, focusing on areas near major quest hubs or rare spawn points. This is account-wide, so coordinate with friends if you cannot find them alone quickly.", x = 6 },
        [42590] = { e = 3, s = "c", r = "Requires completing three sub-achievements in Stormheim zone.", d = "Join a Timerunner group to recover Stormheim treasures, defeat elusive foes, and reveal covered map areas. Complete the three specific quests listed in the info to finish this account-wide objective.", x = 6 },
        [42591] = { e = 3, s = "g", r = "Defeating three rare enemies requires finding and killing them.", d = "Locate and defeat three rare enemies scattered across Krokuun. These spawns can be tricky, so check your map for glowing markers or ask a group member to help track them down.", x = 6 },
        [42593] = { e = 4, s = "c", r = "Requires locating and recovering five specific items across Broken Isles.", d = "Gather a Timerunner group to hunt the five Pillars of Creation across the Broken Isles. You must complete the specific quests listed in the info for each pillar before the timer runs out.", x = 6 },
        [42594] = { e = 3, s = "c", r = "Requires completing three sub-achievements in Val'sharah zone.", d = "Use a Timerunner to explore Val'Sharah, defeat rare enemies, and find hidden treasures. Ensure you complete the three required quests listed in the info to claim your reward.", x = 6 },
        [42596] = { e = 3, s = "c", r = "Requires completing multiple Legion quests in Stormheim zone.", d = "Complete every Stormheim storyline quest with a Timerunner, starting from Greymane's Gambit and ending with The Champion of Stormheim. Do not skip any steps as missing one will prevent you from finishing the set.", x = 6 },
        [42603] = { e = 4, s = "c", r = "Requires defeating all raid bosses on Raid Finder difficulty.", d = "Run Emerald Nightmare on Raid Finder to defeat all listed bosses including Nythendra and Xavius. This is account-wide, so run it once with any group that has a Timerunner available.", x = 6 },
        [42604] = { e = 3, s = "s", r = "Defeating a specific world boss during an invasion event.", d = "Wait for an Invasion Point event on Argus to defeat Occularus. Since this is a world boss, you may need to queue up or wait for others to gather before engaging the encounter.", x = 6 },
        [42605] = { e = 3, s = "c", r = "Requires completing two of four available Suramar sub-achievements.", d = "Complete any two of the Suramar meta-achievements listed in the info with a Timerunner. You can choose between Campaign, Looking for Group, Tour, or The Nightfallen quests to reach your goal.", x = 6 },
        [42606] = { e = 3, s = "g", r = "Finding two hidden treasures involves searching and some luck.", d = "Search Stormheim for two lost treasures, often found in hard-to-reach corners or near rare spawns. This is account-wide, so you can help friends by showing them where the items are located.", x = 6 },
        [42608] = { e = 3, s = "g", r = "Exploring the zone to reveal covered map areas takes time.", d = "Explore every covered area of Stormheim with a Timerunner to reveal the map. Follow the specific quests listed in the info to ensure you do not miss any exploration objectives.", x = 6 },
        [42610] = { e = 5, s = "s", r = "Requires specific Legion Remix raid boss kill.", d = "Defeat The Soultakers world boss in Stormheim during the Legion Remix event. This is a rare drop achievement, so you must wait for the specific event window to occur.", x = 6 },
        [42612] = { e = 5, s = "c", h = { 211863, 211866, 211867 }, r = "Requires completing Argus Campaign with Timerunner.", d = "Complete the Argus Campaign quests with a Timerunner to earn Infinite Knowledge. Ensure you finish all three main campaign quests listed before the timer expires.", x = 6 },
        [42614] = { e = 5, s = "s", r = "Requires specific Legion Remix raid boss kill.", d = "Defeat Flotsam world boss in Highmountain during the Legion Remix event. Like other world bosses, this requires waiting for the specific event window to spawn.", x = 6 },
        [42615] = { e = 3, s = "g", r = "Grind Timeworn dungeons with key level 2+.", d = "Run any Timeworn Keystone dungeon with a key level of 2 or higher using a Timerunner. Start by finding dungeons that are easy to clear quickly to meet the time requirement.", x = 6 },
        [42616] = { e = 5, s = "s", r = "Requires specific Legion Remix invasion boss kill.", d = "Defeat Pit Lord Vilemus during an Invasion Point event on Argus. This is a rare drop, so you must be present when the world boss spawns during the event.", x = 6 },
        [42617] = { e = 3, s = "c", h = { 212914, 212915, 212916 }, r = "Requires completing multiple Val'Sharah storylines.", d = "Complete all Val'Sharah storylines with a Timerunner to earn the Perfected Epoch Memento. Check your quest log for the specific Archdruid and Nightmare quests listed in the info.", x = 6 },
        [42618] = { e = 3, s = "c", h = { 211826, 211827 }, r = "Requires completing Heroic Argus raids with group.", d = "Complete Heroic Seat of the Triumvirate and Antorus on Argus with a Timerunner. These are group activities, so find a party to run them efficiently before the timer runs out.", x = 6 },
        [42619] = { e = 5, s = "g", r = "Grind Exalted reputation with heavy RNG.", d = "Earn Exalted status with the Dreamweavers faction by completing quests or turning in items. Use a Timerunner to finish this quickly while the event is active.", x = 6 },
        [42620] = { e = 3, s = "g", r = "Grind exploration of Krokuun zone.", d = "Explore Krokuun to reveal covered areas on the world map using a Timerunner. Fly around the zone and interact with unexplored zones to complete this objective.", x = 6 },
        [42624] = { e = 3, s = "g", r = "Grind 10 world quests across Broken Isles.", d = "Complete 10 world quests across the Broken Isles with a Timerunner. Start by checking your quest log for available world quests in Stormheim, Highmountain, and Argus.", x = 6 },
        [42626] = { e = 3, s = "g", r = "Find hidden treasures in Eredath zone.", d = "Find two lost treasures hidden throughout Eredath to complete this achievement. Explore the zone thoroughly and look for interactive objects or glowing markers that indicate treasure locations.", x = 6 },
        [42627] = { e = 5, s = "g", r = "Grind Exalted reputation with heavy RNG.", d = "Earn Exalted status with Argussian Reach using a Timerunner. Complete faction quests or turn in items to increase your reputation quickly before the timer expires.", x = 6 },
        [42628] = { e = 5, s = "g", r = "Requires Exalted with a specific group; massive RNG grind.", d = "Start by joining a group with a Timerunner to reach Exalted status quickly, as this is account-wide and requires specific reputation grinding. Focus on completing daily quests for The Nightfallen faction in Suramar to accelerate progress without wasting time.", x = 6 },
        [42629] = { e = 3, s = "s", r = "Single world boss kill; requires coordination but not a raid.", d = "Travel to the Broken Shore during Legion Remix events to defeat Malificus, a world boss that may have limited spawn windows. Coordinate with other players since this encounter often requires group coordination and can be missed if you are not present when it appears.", x = 6 },
