        [42631] = { e = 3, s = "g", r = "Find two hidden treasures; moderate search time in one zone.", d = "Explore Antoran Wastes thoroughly while using a Timerunner to locate hidden treasures, which are often in hard-to-reach areas or require specific interactions. Complete this alongside other Hidden Treasures achievements to maximize your Bronze Cache rewards efficiently.", x = 6 },
        [42634] = { e = 3, s = "g", r = "Find two hidden treasures; moderate search time in one zone.", d = "Use a Timerunner to systematically search Highmountain for lost treasures, paying attention to quest markers and environmental clues that reveal their locations. This achievement is account-wide, so coordinate with friends if you need help finding specific items quickly.", x = 6 },
