        [42637] = { e = 3, s = "s", r = "Single world boss kill; requires coordination but not a raid.", d = "Locate Na'zak the Fiend in Suramar during Legion Remix events, as this world boss may not appear frequently. Bring a group to handle the encounter, which involves complex mechanics that require preparation and timing.", x = 6 },
        [42639] = { e = 3, s = "s", r = "Single world boss kill; requires coordination but not a raid.", d = "Complete Trial of Valor on Heroic difficulty by defeating key enemies like Odyn and Guarm, which is less demanding than Mythic but still requires group coordination. This achievement is account-wide, so you can work with friends to finish it faster.", x = 6 },
        [42640] = { e = 3, s = "g", r = "Kill three rare enemies; moderate time to find and kill them.", d = "Explore Stormheim to find three rare enemies, using a Timerunner to cover ground efficiently and avoid missing spawns. These foes often appear in specific zones or during certain events, so keep an eye on your surroundings while traveling.", x = 6 },
        [42642] = { e = 5, s = "c", h = { 214239 }, r = "Hidden Treasures is the hardest sub-achievement requiring extensive searching.", d = "Combine objectives by recovering treasures, defeating rares, and exploring Highmountain with a Timerunner to complete all sub-achievements at once. This approach saves time since the Tour Highmountain achievement requires finishing multiple related tasks.", x = 6 },
