        [42650] = { e = 3, s = "g", r = "Killing three rare elites in Suramar.", d = "Travel to Suramar and hunt rare enemies until you have defeated three different ones. Check your kill feed or tracking tools to confirm which rares you have eliminated.", x = 6 },
