        [42655] = { e = 4, s = "g", r = "Grinding Exalted with Legionfall faction.", d = "Grind reputation with The Armies of Legionfall faction until you reach Exalted status using a Timerunner. Complete daily quests and world events to speed up progress.", x = 6 },
        [42658] = { e = 4, s = "g", r = "Grinding Exalted with Valarjar faction.", d = "Earn Exalted reputation with the Valarjar faction through a Timerunner. Focus on daily quests, world bosses, and specific Valarjar activities to gain reputation quickly.", x = 6 },
        [42659] = { e = 3, s = "s", r = "Defeating Shar'thos is a single event.", d = "Locate and defeat Shar'thos in Suramar, which appears as a world boss event. Monitor your chat channel for spawn alerts or use tracking addons to find him.", x = 6 },
        [42661] = { e = 5, s = "c", h = { 215655 }, r = "Heroic Kil'jaeden is the hardest boss.", d = "Clear Tomb of Sargeras on Heroic difficulty by defeating all listed bosses. This requires a skilled group and multiple attempts due to the higher difficulty setting.", x = 6 },
