        [42664] = { e = 5, s = "c", h = { 215562 }, r = "Heroic Antorus is the hardest boss.", d = "Clear Antorus the Burning Throne on Heroic difficulty by defeating all listed bosses. Ensure your group is prepared for high-difficulty mechanics before starting.", x = 6 },
        [42665] = { e = 3, s = "g", r = "Exploring Suramar reveals covered map areas.", d = "Explore Suramar by revealing covered areas on the world map using a Timerunner. Travel to unexplored zones and interact with points of interest to complete this task.", x = 6 },
        [42666] = { e = 3, s = "c", h = { 214268, 214269, 214316 }, r = "Requires completing three specific Legion achievements with a Timerunner.", d = "Start by queuing for The Broken Shore with a Timerunner to unlock the necessary meta-achievement. Focus on completing Breaching the Tomb and Looking for Group: The Broken Shore first, as they are core objectives. Ensure you have the 11.2.5 Remix installed, or this content will not appear in your quest log.", x = 6 },
        [42668] = { e = 2, s = "g", r = "Finding two hidden treasures is a short exploration task.", d = "Explore Val'Sharah thoroughly to locate two lost treasures hidden within its environment. These items often require careful searching of specific zones rather than completing quests. Do not rush through the zone; take time to inspect corners and interact with suspicious objects.", x = 6 },
        [42669] = { e = 3, s = "s", r = "Defeating one world boss in Azsuna takes moderate time.", d = "Travel to Azsuna to find and defeat Withered J'im, a world boss that spawns periodically. Coordinate with other players if you cannot solo him quickly, as he can be challenging. Check the world map for his spawn location before engaging to avoid wasting time.", x = 6 },
        [42672] = { e = 3, s = "g", r = "Requires completing five Legion Assaults with a Timerunner.", d = "Queue for Legion Assaults across the Broken Isles and complete five total runs with a Timerunner. This achievement requires Defending the Broken Isles I first, so start there if you haven't already. Each assault counts toward the total, so track your progress carefully.", x = 6 },
        [42673] = { e = 2, s = "s", r = "Completing one Legion Assault is an easy solo task.", d = "Begin by completing one Legion Assault in the Broken Isles with a Timerunner to unlock this tier. Use the same method as previous tiers but ensure you have the prerequisite achievement. This is the first step in a chain leading to higher rewards.", x = 6 },
        [42674] = { e = 3, s = "g", r = "Requires completing 150 world quests across the Broken Isles.", d = "Complete 150 world quests across the Broken Isles using a Timerunner, which may require grinding multiple zones. Start with Broken Isles World Quests IV if it is not yet unlocked. Keep an eye on your quest log to ensure you are counting toward the correct total.", x = 6 },
        [42675] = { e = 3, s = "g", r = "Requires completing ten Legion Assaults with a Timerunner.", d = "After unlocking Defending the Broken Isles II, complete ten Legion Assaults in the Broken Isles with a Timerunner. This tier offers significant rewards, so prioritize it once prerequisites are met. Ensure you have enough time to queue for assaults without interruption.", x = 6 },
        [42676] = { e = 3, s = "g", r = "Raising a companion to level 100 requires significant grinding.", d = "Raise your companion to level 100 by completing delves and other leveling activities. Start with Buddy System IX if it is not yet unlocked. This process takes time, so plan your daily routine around companion experience gains.", x = 10 },
        [42677] = { e = 2, s = "s", r = "Obtaining the Mana-Skimmer is a straightforward unlock.", d = "Obtain the Delver's Mana-Skimmer by completing specific delves or world quests in The War Within. This item unlocks further cosmetic options, so secure it early. Check your inventory for any missing components if the achievement does not appear.", x = 10 },
        [42678] = { e = 3, s = "c", h = { 224472, 224474, 224476 }, r = "Collecting five specific cosmetic unlocks for the Mana-Skimmer.", d = "Collect all five cosmetic unlocks for the Delver's Mana-Skimmer, including Energy Thrusters and Void skins. These items may drop from specific delves or vendors. Ensure you have the base skimmer before attempting to collect these cosmetics.", x = 10 },
        [42679] = { e = 3, s = "g", r = "Finding and opening four hidden chests in Archival Assault.", d = "Find and open all four Sturdy Chests hidden in Archival Assault by exploring thoroughly. These chests are often located in hard-to-reach areas, so use flight paths or mounts to access them. Do not skip any section of the assault to avoid missing chests.", x = 10 },
        [42684] = { e = 3, s = "s", r = "Reaching level 80 with a Warrior takes moderate time.", d = "Reach level 80 with a Warrior class in Legion: Remix by completing leveling quests and dungeons. This achievement is account-wide, so you can use any character to help progress. Ensure you have the 11.2.5 Remix installed to access this content.", x = 6 },
        [42685] = { e = 3, s = "s", r = "Requires leveling a Death Knight to 80 in Remix.", d = "Start by leveling a Death Knight to 80 in Legion Remix. This is account-wide and grants a unique mount upon reaching the level cap.", x = 6 },
