        [42687] = { e = 3, s = "s", r = "Requires leveling a Hunter to 80 in Remix.", d = "Grind a Hunter to level 80 in Legion Remix for the mount reward. No specific group is needed for this leveling achievement.", x = 6 },
        [42688] = { e = 4, s = "g", r = "Grinding Timeworn dungeons with key level 7+.", d = "Complete any Timeworn Keystone dungeon with a key level of 7 or higher. You must already own the prerequisite Timeworn Keystone Apprentice achievement.", x = 6 },
        [42689] = { e = 5, s = "g", r = "High-level Timeworn dungeon grind requires significant time.", d = "Run a Timeworn Keystone dungeon with a key level of 15 or greater after unlocking the previous tier. This grants a bronze cache and decor.", x = 6 },
        [42690] = { e = 5, s = "g", r = "Key level 30+ Timeworn dungeons are very difficult.", d = "Achieve a key level of 30 or greater in a Timeworn Keystone dungeon to unlock the next step. You will receive an appearance reward upon completion.", x = 6 },
        [42691] = { e = 5, s = "g", r = "Key level 40+ Timeworn dungeons require heavy effort.", d = "Complete a Timeworn Keystone dungeon with a key level of 40 or higher. This finalizes the chain and awards you the title The Infernal.", x = 6 },
        [42692] = { e = 4, s = "c", h = { 214287, 214288, 214289 }, r = "Requires completing all 11 Legion dungeons; some are hard.", d = "Queue for every Legion dungeon listed in the info field on any difficulty. Make sure to defeat all bosses in each instance to count toward the total.", x = 6 },
