        [42699] = { e = 2, s = "s", r = "One-time death event in Heroic World Tier content.", d = "Queue for Heroic World Tier content as a Legion Timerunner and intentionally die to trigger the achievement. This is account-wide, so any character can complete it once the condition is met.", x = 6 },
