        [61017] = { e = 4, s = "g", r = "Collecting many rare items from random orbs is a long grind.", d = "Use Phase Diving orbs in the War Within zone to find and collect all listed Phase-Lost item appearances. This is account-wide, so ensure your main character picks up every drop before logging off.", x = 10 },
        [61024] = { e = 5, s = "s", r = "High-skill Mythic raid run with strict no-death requirement.", d = "Queue for Trial of Valor on Mythic Difficulty with a Paladin, Warrior, or Death Knight and complete the run without dying once. Since this is account-wide, any death by these classes counts toward the achievement.", x = 6 },
        [61025] = { e = 5, s = "s", r = "High-skill Mythic raid run with strict no-death requirement.", d = "Queue for Trial of Valor on Mythic Difficulty using a Hunter or Shaman and finish the dungeon without taking damage. Coordinate with your group to minimize deaths during high-damage encounters.", x = 6 },
        [61026] = { e = 5, s = "s", r = "High-skill Mythic raid run with strict no-death requirement.", d = "Complete Trial of Valor on Mythic Difficulty as a Rogue, Druid, Demon Hunter, or Monk without dying. Ensure your party composition supports these classes for optimal survival.", x = 6 },
        [61027] = { e = 5, s = "s", r = "High-skill Mythic raid run with strict no-death requirement.", d = "Queue for Trial of Valor on Mythic Difficulty with a Warlock, Mage, or Priest and avoid any deaths during the run. These caster classes require careful positioning to prevent accidental damage.", x = 6 },
        [61028] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Gather a team of level 25 Undead pets and defeat all listed trainers in Eastern Kingdoms. Note that Lydia Accoste requires twelve defeats, so plan your pet battles efficiently.", x = 11 },
        [61029] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Assemble a squad of level 25 Aquatic pets and challenge the same set of trainers across Eastern Kingdoms. Ensure your aquatic pets are fully leveled before starting to avoid unnecessary retries.", x = 11 },
        [61030] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Collect a team of level 25 Beast pets and defeat all required trainers in Eastern Kingdoms. Focus on high-level beast pets to maximize your chances against tough trainers.", x = 11 },
        [61031] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Gather a group of level 25 Critter pets and complete battles with all listed trainers in Eastern Kingdoms. These small pets may struggle, so prioritize easy encounters first.", x = 11 },
        [61032] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Assemble a team of level 25 Dragonkin pets and defeat the specified trainers in Eastern Kingdoms. Dragonkin pets are versatile, but ensure they are fully leveled for optimal performance.", x = 11 },
        [61033] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Collect a squad of level 25 Elemental pets and challenge all listed trainers in Eastern Kingdoms. Elemental pets can be powerful, but watch out for their specific weaknesses.", x = 11 },
        [61034] = { e = 4, s = "g", r = "Defeating many trainers with specific pet team is a grind.", d = "Gather a team of level 25 Flying pets and defeat all required trainers in Eastern Kingdoms. Flying pets offer mobility advantages, but ensure they are fully leveled before starting.", x = 11 },
        [61035] = { e = 2, s = "c", r = "Defeat 12 trainers with specific pet type.", d = "Gather a full team of level 25 Humanoid pets before starting. Defeat each trainer in Eastern Kingdoms one by one; Lydia Accoste requires twelve wins. This is account-wide and cannot be missed if you complete the fights.", x = 11 },
        [61036] = { e = 2, s = "c", r = "Defeat 12 trainers with Magic pets.", d = "Assemble a team of level 25 Magic pets to face Kalimdor trainers. Defeat all listed opponents sequentially; Lydia Accoste needs twelve victories. Ensure your pet types match the achievement requirement before engaging any trainer.", x = 11 },
        [61037] = { e = 2, s = "c", r = "Defeat 12 trainers with Mechanical pets.", d = "Build a team of level 25 Mechanical pets for Eastern Kingdoms trainers. Complete each fight in order, noting that Lydia Accoste requires twelve wins. This is account-wide and relies on having the correct pet types ready.", x = 11 },
        [61040] = { e = 3, s = "c", r = "Requires completing all other Battler achievements.", d = "Complete all eleven sub-achievements listed to earn this title. Start with any region's battler achievements first, as they unlock the prerequisite for this one. You will receive the Byrn pet upon completion.", x = 11 },
        [61041] = { e = 2, s = "c", r = "Defeat 12 trainers with Aquatic pets.", d = "Use a team of level 25 Aquatic pets to defeat Kalimdor trainers. Lydia Accoste requires twelve wins, so plan your battles accordingly. This is account-wide and can be done in any order after gathering the pets.", x = 11 },
        [61042] = { e = 2, s = "c", r = "Defeat 12 trainers with Beast pets.", d = "Equip a team of level 25 Beast pets for Kalimdor trainers. Defeat each trainer sequentially; Lydia Accoste needs twelve victories. Ensure your pet roster includes enough level 25 Beasts before starting.", x = 11 },
        [61043] = { e = 2, s = "c", r = "Defeat 12 trainers with Critter pets.", d = "Gather a team of level 25 Critter pets to face Kalimdor trainers. Complete all fights, noting Lydia Accoste requires twelve wins. This is account-wide and does not require specific quest progression.", x = 11 },
        [61044] = { e = 2, s = "c", r = "Defeat 12 trainers with Dragonkin pets.", d = "Assemble a team of level 25 Dragonkin pets for Kalimdor trainers. Defeat each opponent in order; Lydia Accoste needs twelve victories. Make sure your pet collection includes sufficient Dragonkin before beginning.", x = 11 },
        [61045] = { e = 2, s = "c", r = "Defeat 12 trainers with Elemental pets.", d = "Use a team of level 25 Elemental pets to defeat Kalimdor trainers. Complete all fights sequentially; Lydia Accoste requires twelve wins. This is account-wide and can be done anytime you have the right pets.", x = 11 },
        [61046] = { e = 2, s = "c", r = "Defeat 12 trainers with Flying pets.", d = "Equip a team of level 25 Flying pets for Kalimdor trainers. Defeat each trainer one by one; Lydia Accoste needs twelve victories. Ensure your pet roster has enough Flying pets before starting.", x = 11 },
        [61047] = { e = 2, s = "c", r = "Defeat 12 trainers with Humanoid pets.", d = "Gather a team of level 25 Humanoid pets for Kalimdor trainers. Complete all fights in order; Lydia Accoste requires twelve wins. This is account-wide and does not require specific quest progression.", x = 11 },
        [61048] = { e = 2, s = "c", r = "Defeat 12 trainers with Magic pets.", d = "Assemble a team of level 25 Magic pets for Kalimdor trainers. Defeat each opponent sequentially; Lydia Accoste needs twelve victories. Ensure your pet collection includes sufficient Magic pets before beginning.", x = 11 },
        [61049] = { e = 3, s = "c", r = "Grinding 12 trainers with specific pets is moderate.", d = "Build a level 25 Mechanical team and defeat each listed trainer individually across Kalimdor. Ensure you have access to all trainers before starting, as some may be missable or require specific zones.", x = 11 },
        [61050] = { e = 3, s = "c", r = "Grinding 12 trainers with specific pets is moderate.", d = "Construct a level 25 Undead team and clear the same trainer list found in the Mechanical achievement. This requires collecting specific undead pets first if you do not already possess them.", x = 11 },
        [61051] = { e = 4, s = "c", h = { 215168, 215169 }, r = "Requires completing two other grinding achievements first.", d = "Complete all ten sub-achievements listed in the info field to unlock this title. Start with the easiest categories like Humanoid or Magic Battler before tackling the harder ones.", x = 11 },
        [61052] = { e = 3, s = "g", r = "Collecting 120 moths is a steady grind.", d = "Explore Harandar thoroughly at night to find all twelve glowing moths, as they are hidden and missable if you do not check every corner.", x = 11 },
        [61053] = { e = 4, s = "g", r = "Requires Heroic World Tier and killing 50 specific enemies.", d = "Queue for Heroic World Tier content in Legion Remix and kill fifty empowered enemies. This is a grind that requires patience but has no time gate.", x = 6 },
        [61054] = { e = 4, s = "g", r = "Requires Heroic World Tier and completing 50 world quests.", d = "Complete fifty world quests in Heroic World Tier within the Legion Remix zone. Use group tools to speed up quest completion, as this is purely quantity-based.", x = 6 },
        [61055] = { e = 3, s = "g", r = "Activating 25 obelisks is a moderate grind.", d = "Locate and activate twenty-five timewarped obelisks in Heroic World Tier. These appear randomly, so you must check multiple zones or use a map tool to find them quickly.", x = 6 },
        [61056] = { e = 4, s = "g", r = "Requires Heroic World Tier and completing 30 world quests.", d = "Finish thirty world quests in Heroic World Tier as a prerequisite for the next tier. Focus on high-density quest areas to maximize your progress efficiently.", x = 6 },
        [61057] = { e = 3, s = "g", r = "Requires Heroic World Tier and completing 10 world quests.", d = "Complete ten world quests in Heroic World Tier to start the chain. This is an early step with no complex mechanics, just consistent grinding in the right zones.", x = 6 },
        [61058] = { e = 3, s = "g", r = "Requires Heroic World Tier and killing 10 specific enemies.", d = "Defeat ten empowered enemies in Heroic World Tier after unlocking Legionslayer I. These targets spawn during specific events or world quests, so keep your eye out for them.", x = 6 },
        [61059] = { e = 2, s = "g", r = "Killing one empowered enemy is easy in HWT.", d = "Kill a single empowered enemy in Heroic World Tier to begin the Legionslayer chain. This is often found during Legion Remix events or by checking world quest objectives.", x = 6 },
        [61060] = { e = 3, s = "g", r = "Activating 5 obelisks is a moderate grind.", d = "Activate five timewarped obelisks in Heroic World Tier as the first step of the series. These are random spawns, so you may need to travel across multiple zones to find them.", x = 6 },
        [61061] = { e = 3, s = "g", r = "Grinding obelisk activations takes a few hours.", d = "Start by finding the first Timewarped Obelisk in any Legion zone. Activate it while playing as a Timerunner on Heroic World Tier to begin the chain.", x = 6 },
        [61070] = { e = 4, s = "g", r = "Completing 100 world quests requires significant time.", d = "Grind world quests across all Broken Isles zones until you hit 100 completions. Ensure you are in Heroic World Tier and playing as a Timerunner throughout.", x = 6 },
        [61071] = { e = 3, s = "g", r = "Killing 200 empowered enemies is a moderate grind.", d = "Focus on defeating empowered enemies like bosses or rare mobs in Heroic World Tier. Aim for 200 kills while maintaining your Timerunner status.", x = 6 },
        [61072] = { e = 3, s = "g", r = "Activating 100 obelisks is a straightforward grind.", d = "Locate and activate Timewarped Obelisks scattered across the Broken Isles. You need to reach a total of 100 activations in Heroic World Tier.", x = 6 },
        [61073] = { e = 4, s = "c", h = { 215332, 215333, 215334 }, r = "Requires running all Legion dungeons on Heroic.", d = "Queue for every Legion dungeon listed in the info field on Heroic difficulty. Complete each instance once while logged in as a Timerunner.", x = 6 },
        [61074] = { e = 5, s = "c", h = { 215346, 215347, 215348 }, r = "Requires running all Legion dungeons on Mythic.", d = "Repeat the dungeon process but switch to Mythic difficulty for all Legion raids. Ensure you finish every single dungeon listed before moving on.", x = 6 },
        [61075] = { e = 4, s = "c", h = { 215404, 215405, 215406 }, r = "Requires clearing any Legion raid on Heroic.", d = "Pick any Legion raid and clear it on Heroic difficulty with a group. Once done, the achievement will unlock automatically for your account.", x = 6 },
        [61076] = { e = 3, s = "c", h = { 215479, 215480, 215481 }, r = "Requires defeating all Broken Isles world bosses.", d = "Travel to various Broken Isles zones to find and defeat all listed world bosses. These spawns are often random or tied to specific events.", x = 6 },
        [61077] = { e = 3, s = "c", h = { 215472, 215473, 215474 }, r = "Requires defeating all Argus invasion point bosses.", d = "Head to Argus and clear out every Invasion Point boss listed. Make sure you have the necessary reputation and quest progress first.", x = 6 },
        [61078] = { e = 5, s = "c", h = { 215416, 215417, 215418 }, r = "Requires clearing all Legion raids on Mythic.", d = "Clear all Legion raids on Mythic difficulty with a full group. This is a long-term goal requiring high gear and coordination.", x = 6 },
        [61079] = { e = 4, s = "c", h = { 215410, 215411, 215412 }, r = "Requires clearing all Legion raids on Heroic.", d = "Complete every Legion raid on Heroic difficulty to unlock the title. You do not need to clear them all in one session.", x = 6 },
        [61080] = { e = 3, s = "c", h = { 215494, 215495, 215496 }, r = "Requires defeating all Broken Shore world bosses.", d = "Visit the Broken Shore instance and defeat the four specific world bosses listed. These may require waiting for spawn timers or event triggers.", x = 6 },
        [61081] = { e = 2, s = "c", r = "Buy drinks from all races; trivial per race.", d = "Share Toasting Brew with every race in Arcantina, including all new ones like Lightforged Draenei and Mechagnome. Visit each NPC individually to toast them; this is account-wide so play with friends of different races if needed.", x = 11 },
        [61082] = { e = 3, s = "c", r = "Complete quests for all visitor pairs.", d = "Complete quests from every visitor pair in Arcantina by talking to them repeatedly until the quest completes. Some visitors may only appear at certain times, so check back regularly or use a group to speed up interactions.", x = 11 },
        [61083] = { e = 4, s = "c", r = "Grind to find and display many items.", d = "Find and display all listed decorative items in Arcantina, which are likely found as drops or rewards from specific activities. Check your inventory for these items and place them in the designated spots within the zone.", x = 11 },
        [61084] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Reach level 80 with a Rogue in Legion Remix to earn this achievement and its mount reward. Focus on leveling efficiently using group content or dungeons if you are already near the cap.", x = 6 },
        [61085] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Level a Monk to 80 in Legion Remix to complete this achievement. If you have other characters close to level 80, consider alts for faster completion.", x = 6 },
        [61086] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Bring a Druid to level 80 in Legion Remix; use group content or world quests to speed up the process if needed. This is account-wide so coordinate with friends if playing multiple characters.", x = 6 },
        [61087] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Level a Demon Hunter to 80 in Legion Remix, focusing on efficient leveling methods like dungeons or world quests. Ensure you are in the correct Remix realm if applicable.", x = 6 },
        [61088] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Reach level 80 with a Priest in Legion Remix; use group content or solo play depending on your preference. This achievement is account-wide so share progress with friends.", x = 6 },
        [61089] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Level a Mage to 80 in Legion Remix, utilizing efficient leveling strategies such as dungeons or world quests. Coordinate with friends if you want to speed up the process.", x = 6 },
        [61090] = { e = 5, s = "s", r = "Level a specific class in Remix; hard grind.", d = "Bring a Warlock to level 80 in Legion Remix; use group content or solo play depending on your preference. This achievement is account-wide so share progress with friends.", x = 6 },
        [61091] = { e = 4, s = "g", r = "Catch many rare wild pets across zones.", d = "Catch every wild pet listed in Eversong Woods, Zul'Aman, Harandar, and Voidstorm for the Midnight Safari achievement. Use a high-level character to catch these pets efficiently, as some may be rare or missable.", x = 11 },
        [61094] = { e = 5, s = "c", r = "Complete multiple family battler achievements.", d = "Complete both Family Battler achievements for Eastern Kingdoms and Kalimdor by defeating all required families in Pet Battles. This is account-wide so coordinate with friends if needed to speed up completion.", x = 11 },
        [61103] = { e = 2, s = "c", r = "Multiple storylines but manageable solo.", d = "Use a Timerunner to finish all Azsuna local quests, as this is account-wide and cannot be missed later. Focus on completing every zone story before leaving the area to ensure progress counts.", x = 6 },
        [61104] = { e = 2, s = "c", r = "Multiple storylines but manageable solo.", d = "Complete Highmountain's local storylines with a Timerunner while exploring the zone thoroughly. Do not skip any quest chains, as missing them now means you must wait for future content updates.", x = 6 },
        [61105] = { e = 2, s = "c", r = "Multiple storylines but manageable solo.", d = "Run through Stormheim with a Timerunner to finish all required local quests before the timer expires. Ensure you talk to every relevant NPC and complete each storyline segment.", x = 6 },
        [61106] = { e = 2, s = "c", r = "Multiple storylines but manageable solo.", d = "Use a Timerunner to clear Val'Sharah's local storylines, paying close attention to hidden quest objectives. Finish everything in one session to avoid missing out on account-wide progress.", x = 6 },
        [61107] = { e = 2, s = "c", r = "Multiple storylines but manageable solo.", d = "Complete Suramar's local quests with a Timerunner, making sure to visit all key locations and finish every storyline task. This achievement is account-wide, so coordinate with your character if needed.", x = 6 },
        [61108] = { e = 3, s = "c", r = "Requires prior Sojourner completion first.", d = "First complete the Sojourner of Azsuna achievement, then use a Timerunner to unlock the Lorerunner title. Ensure you have finished the Campaign: Azsuna prerequisite before starting the timer.", x = 6 },
        [61109] = { e = 3, s = "c", r = "Requires prior Sojourner completion first.", d = "Finish Highmountain's local storylines with a Timerunner first, then claim the Lorerunner of Highmountain achievement. Verify that both the Campaign and Sojourner prerequisites are met before using the timer.", x = 6 },
        [61110] = { e = 3, s = "c", r = "Requires prior Sojourner completion first.", d = "Complete Stormheim's local quests with a Timerunner to unlock the Lorerunner title afterward. Make sure you have finished the Campaign: Stormheim requirement before starting the timed run.", x = 6 },
        [61111] = { e = 3, s = "c", r = "Requires prior Sojourner completion first.", d = "Use a Timerunner to finish Val'Sharah's local storylines, then claim the Lorerunner of Val'Sharach achievement. Ensure both the Campaign and Sojourner prerequisites are completed first.", x = 6 },
        [61112] = { e = 3, s = "c", r = "Requires prior Sojourner completion first.", d = "Complete Suramar's local quests with a Timerunner to unlock the Lorerunner title afterward. Verify that you have finished the Campaign: Suramar requirement before starting the timed run.", x = 6 },
        [61113] = { e = 4, s = "c", r = "Needs multiple dungeon clears with timerunner.", d = "Run each of the four specified Legion dungeons on any difficulty with a Timerunner, ensuring you complete Neltharion's Lair, Maw of Souls, Halls of Valor, and Darkheart Thicket. This requires the 11.2.5 Remix expansion.", x = 6 },
        [61114] = { e = 4, s = "c", r = "Needs multiple dungeon clears with timerunner.", d = "Complete Eye of Azshara, The Arcway, and Court of Stars with a Timerunner to earn this achievement. Ensure you have the 11.2.5 Remix expansion installed before attempting these dungeons.", x = 6 },
        [61115] = { e = 4, s = "g", r = "Requires multiple timed dungeon clears.", d = "Queue for any Legion dungeon with a timer and clear the instance quickly to earn points. This achievement is account-wide, so ensure your character has access to all required dungeons before starting.", x = 6 },
        [61174] = { e = 3, s = "s", r = "Single scenario run with score requirement.", d = "Run the Withered Army Training scenario in Heroic World Tier and aim for a score of 200 or higher. You must complete this specific training instance to progress toward the achievement goal.", x = 6 },
        [61211] = { e = 1, s = "s", r = "Trivial house purchase action.", d = "Purchase your first house from the Auction House or housing vendor to unlock this milestone. Once bought, simply move into the property to claim the points.", x = 10 },
        [61212] = { e = 3, s = "s", r = "Single Mythic+ dungeon clear.", d = "Defeat Degentrius in Magisters' Terrace on Normal difficulty to complete this step. This is the first stage of the dungeon chain and unlocks further difficulties.", x = 11 },
        [61213] = { e = 4, s = "s", r = "Heroic difficulty adds significant skill demand.", d = "Return to Magisters' Terrace and defeat Degentrius on Heroic difficulty or higher. You must have completed the Normal version first before attempting this tier.", x = 11 },
        [61214] = { e = 5, s = "s", r = "Mythic difficulty requires high-end group play.", d = "Progress to Mythic or Mythic Keystone difficulty in Magisters' Terrace to finish the chain. Ensure you have cleared the Heroic version before starting this final stage.", x = 11 },
        [61218] = { e = 5, s = "g", r = "Requires many timed clears for exalted status.", d = "Earn Exalted reputation with The Wardens while running a timer dungeon. This is account-wide, so coordinate with friends or use a shared character if possible.", x = 6 },
        [61219] = { e = 3, s = "s", r = "Single world quest with RNG element.", d = "Complete the Harandar world quest Claw Enforcement while holding at least 15 stacks of Predator's Pursuit. Monitor your stack count carefully during the quest to avoid failure.", x = 11 },
        [61221] = { e = 2, s = "g", r = "Grinding honor in a zone is straightforward.", d = "Enable War Mode and farm honor in Eversong Woods until you reach 1000 points. This is account-wide, so any character can contribute toward the total progress.", x = 11 },
        [61222] = { e = 2, s = "g", r = "Grinding honor in a zone is straightforward.", d = "Activate War Mode and gather 1000 honor specifically within Zul'Aman zones. Focus your activities in this area to ensure the honor counts correctly for the achievement.", x = 11 },
        [61223] = { e = 2, s = "g", r = "Grinding honor in a zone is straightforward.", d = "Turn on War Mode and earn 1000 honor while exploring Harandar. Make sure you are in the correct zone, as honor earned elsewhere will not count toward this goal.", x = 11 },
        [61224] = { e = 2, s = "g", r = "Grinding honor in a zone is straightforward.", d = "Enable War Mode and collect 1000 honor inside Voidstorm zones. Stay within the designated area to ensure your progress is tracked accurately for the achievement.", x = 11 },
        [61225] = { e = 4, s = "c", r = "Requires completing 7 unique PvP world quests in Midnight.", d = "Start by queuing for PvP world quests in Midnight zone while War Mode is active. Complete each unique quest once, noting that some may require specific group compositions or rare spawns. This chain unlocks the next tier of repeatable objectives.", x = 11 },
        [61226] = { e = 4, s = "g", r = "Grinding 7 different quests to 10 kills each is time-consuming.", d = "Once the first tier is done, focus on repeating each of the seven world quests exactly ten times. Farm these efficiently by grouping with others to speed up kills and quest completion. Ensure you stay in Midnight zone throughout the process to track progress correctly.", x = 11 },
        [61227] = { e = 3, s = "g", r = "Gathering 50 honorable kills in a specific arena takes time.", d = "Enter Slayer's Rise arena mode and aim for 50 honorable kills against other players. This can be done quickly in ranked or casual arenas, so queue up immediately after unlocking the previous achievement. No special items are needed beyond standard PvP gear.", x = 11 },
        [61228] = { e = 4, s = "g", r = "Doubles the grind of the previous achievement to 100 kills.", d = "Continue farming honorable kills in Slayer's Rise until you reach 100 total. Since this builds on the previous goal, simply keep fighting in any PvP instance within the zone. Monitor your kill count carefully as it does not reset between sessions.", x = 11 },
        [61229] = { e = 5, s = "g", r = "Reaching 500 honorable kills is a very long grind.", d = "This stage requires a significant grind to 500 honorable kills in Slayer's Rise. Plan for several hours of arena play or world PvP to accumulate enough kills without interruption. There is no shortcut, so consistency is key to completing this milestone.", x = 11 },
        [61230] = { e = 4, s = "g", r = "Completing a specific quest chain 5 times in Midnight is hard.", d = "Locate and complete the Collecting Remains quest five times while in Midnight zone. These quests often appear randomly, so check your quest log frequently for new objectives. Grouping up can help find these locations faster if they are contested areas.", x = 11 },
        [61231] = { e = 3, s = "g", r = "Opening 5 crates is moderate but requires being in War Mode.", d = "Open five War Supply Crates in Midnight while War Mode is active to unlock this achievement. You can buy crates from vendors or get them as loot, but ensure you are in War Mode when opening them. This step prepares you for the larger crate-opening goal next.", x = 11 },
        [61232] = { e = 4, s = "g", r = "Opening 25 crates is a significant grind requiring War Mode.", d = "After unlocking the previous tier, open twenty-five more War Supply Crates in Midnight with War Mode enabled. Farm these by purchasing from vendors or looting drops during your regular PvP activities. Track your count to avoid missing the final few crates.", x = 11 },
        [61234] = { e = 4, s = "c", r = "Requires looting bounties in 4 specific zones while in War Mode.", d = "Travel through each zone listed in Midnight and kill a player to loot their bounty item. Make sure you are in War Mode and that the bounty is still available after the kill. Some zones may require traveling between sub-zones to find eligible targets.", x = 11 },
        [61238] = { e = 4, s = "g", r = "Looting 20 bounties is a long grind requiring PvP activity.", d = "Loot twenty bounties from slain players across all Midnight zones while in War Mode. This requires killing enough opponents to drop the items, so engage in frequent PvP encounters. Keep an eye on your inventory to ensure you collect each bounty before leaving the zone.", x = 11 },
        [61263] = { e = 4, s = "c", r = "Finding 9 unique hidden treasures across Harandar is difficult.", d = "Explore Harandar thoroughly to discover nine unique treasures hidden throughout the zone. These items often require solving small puzzles or finding specific interaction points. Use a map addon if available to track which treasures you have already found.", x = 11 },
        [61264] = { e = 5, s = "c", h = { 216663 }, r = "Defeating all rares including a raid boss equivalent is very hard.", d = "Defeat all thirteen rare creatures listed in Harandar, which may appear only at certain times or locations. Some rares are elusive and might need patience or group coordination to kill. Check the zone regularly as new rares can spawn over time.", x = 11 },
        [61265] = { e = 3, s = "s", r = "Requires specific event or rare drop.", d = "Start by locating the Spectral Battle Chests in Slayer's Rise and opening them to begin the chain. These chests are account-wide, so any character can contribute progress. Ensure you have access to the zone before attempting this.", x = 11 },
        [61266] = { e = 4, s = "g", r = "Grinding 10 chests is a long task.", d = "Continue opening Spectral Battle Chests until you reach ten total opens. Since this is account-wide, coordinate with friends or wait for others to help speed up progress. No special items are needed beyond the chests themselves.", x = 11 },
        [61308] = { e = 2, s = "s", r = "One unique decor is easy to find.", d = "Begin collecting unique decor of uncommon quality or higher by exploring zones and completing housing-related quests. Focus on acquiring at least one unique item to unlock the next step. This is account-wide, so share progress across characters.", x = 10 },
        [61309] = { e = 4, s = "g", r = "Collecting 50 unique items takes time.", d = "Aim to collect fifty unique decor items of uncommon quality or higher. Prioritize zones with high drop rates for rare decor and revisit them regularly. Keep track of your collection to avoid duplicates unnecessarily.", x = 10 },
        [61310] = { e = 4, s = "g", r = "Collecting 100 unique items is a grind.", d = "Expand your collection to one hundred unique decor items by exploring diverse zones and events. Use group activities or world bosses that drop rare decor for efficiency. Monitor your inventory to ensure you're tracking unique items correctly.", x = 10 },
        [61311] = { e = 4, s = "g", r = "Collecting 150 unique items is a grind.", d = "Collect one hundred fifty unique decor items by focusing on high-yield zones and events. Consider trading with other players if you lack specific rare decor. Stay consistent in your exploration to avoid missing out on time-gated content.", x = 10 },
        [61312] = { e = 4, s = "g", r = "Collecting 200 unique items is a grind.", d = "Gather two hundred unique decor items by revisiting zones and participating in seasonal events. Prioritize uncommon or rarer decor to maximize progress toward this milestone. Avoid focusing solely on common items to save time.", x = 10 },
        [61313] = { e = 4, s = "g", r = "Collecting 250 unique items is a grind.", d = "Reach two hundred fifty unique decor items by exploring new zones and checking event rewards. Trade with other players for rare decor you may not have found yet. Keep an eye on world events that offer unique decor drops.", x = 10 },
        [61314] = { e = 4, s = "g", r = "Collecting 300 unique items is a grind.", d = "Collect three hundred unique decor items by systematically revisiting zones and participating in all available events. Focus on acquiring uncommon or rarer decor to avoid wasting time on common items. Coordinate with friends for shared progress.", x = 10 },
        [61315] = { e = 4, s = "g", r = "Collecting 350 unique items is a grind.", d = "Gather three hundred fifty unique decor items by exploring diverse zones and trading with other players. Prioritize rare decor drops from world bosses or events to speed up progress. Avoid duplicates by tracking your collection carefully.", x = 10 },
        [61316] = { e = 4, s = "g", r = "Collecting 400 unique items is a grind.", d = "Collect four hundred unique decor items by focusing on high-yield zones and seasonal events. Trade with other players for rare decor you may not have found yet. Stay consistent in your exploration to avoid missing out on time-gated content.", x = 10 },
        [61317] = { e = 4, s = "g", r = "Collecting 450 unique items is a grind.", d = "Reach four hundred fifty unique decor items by revisiting zones and participating in all available events. Prioritize uncommon or rarer decor to maximize progress toward this milestone. Avoid focusing solely on common items to save time.", x = 10 },
        [61318] = { e = 4, s = "g", r = "Collecting 500 unique decor items is a long grind.", d = "Collect 500 unique uncommon or higher decor items by purchasing them from the Domicile Designer vendor. This is account-wide and requires no group, but ensure you buy distinct items rather than duplicates to progress efficiently.", x = 10 },
        [61323] = { e = 4, s = "g", r = "Killing 500 empowered enemies requires significant time.", d = "Complete this Legion Remix achievement only after finishing Legionslayer IV, as it requires defeating 500 empowered enemies in Heroic World Tier. Since the content is time-gated to the specific remix period, check your calendar before attempting these kills.", x = 6 },
        [61335] = { e = 2, s = "c", h = { 216907 }, r = "Most zones are easy; Eversong Woods is the hardest.", d = "Visit all five listed zones during the Midsummer event to honor the flames of Midnight for this Honor achievement. Ensure you are logged in during the active event window, as missing this time gate makes the achievement unobtainable.", x = 11 },
        [61336] = { e = 2, s = "c", h = { 216913 }, r = "Most zones are easy; Harandar is the hardest.", d = "Visit all five listed zones during the Midsummer event to honor the flames of Midnight for this Adventure achievement. Like the Honor version, this is time-gated and requires you to be online while the event is active.", x = 11 },
        [61337] = { e = 4, s = "g", r = "Completing a full campaign requires many hours of play.", d = "Finish the entire Legion Remix campaign storyline to unlock this title. Note that this content is only available during the specific Remixing Time window, so do not delay starting it until the last moment.", x = 6 },
        [61342] = { e = 2, s = "s", r = "Leveling one companion is straightforward and quick.", d = "Raise a single companion character from level 1 to 90 by completing their daily quests and gaining experience. This is account-wide, so you can use any character in your party to help the companion gain levels faster.", x = 10 },
        [61344] = { e = 3, s = "c", h = { 217520 }, r = "Most lore objects are easy; Part 2 of Wey'nan is hardest.", d = "Locate and interact with every lore object found within the Legends of the Haranir relic stories across the game world. Since these objects are missable if not collected during the event, prioritize finding them early in the expansion's lifecycle.", x = 11 },
        [61346] = { e = 3, s = "s", r = "Requires one specific raid encounter and mechanics.", d = "Defeat Crown of the Cosmos on Normal or higher difficulty after slaying a Fleshy Monstrosity and returning its meat to The Emptiness. This specific sequence must be completed in one run, so coordinate with your group to handle the meat return mechanic correctly.", x = 11 },
        [61366] = { e = 4, s = "c", h = { 217631 }, r = "Most bosses are standard; Crown of the Cosmos is hardest.", d = "Defeat all listed Voidspire bosses on any difficulty to claim this achievement. Start with Normal mode if you are new to the raid, then progress to Heroic and Mythic once you have unlocked the previous tiers.", x = 11 },
        [61367] = { e = 4, s = "c", h = { 217634 }, r = "Most bosses are standard; Midnight Falls is hardest.", d = "Defeat all listed March on Quel'Danas bosses on any difficulty to claim this achievement. Begin with Normal mode to learn the mechanics before attempting higher difficulties, as the raid is account-wide but requires a full group.", x = 11 },
        [61368] = { e = 5, s = "c", h = { 217641 }, r = "Heroic Voidspire needs a group; Crown of the Cosmos is hardest.", d = "Unlock Heroic: The Voidspire by first completing the Normal version of the raid. Defeat all bosses on Heroic difficulty to progress toward Mythic, ensuring you have the necessary gear and group composition for the increased challenge.", x = 11 },
        [61369] = { e = 5, s = "c", h = { 217644 }, r = "Heroic March on Quel'Danas needs a group; Midnight Falls is hardest.", d = "Unlock Heroic: March on Quel'Danas by first completing the Normal version of the raid. Defeat all bosses on Heroic difficulty to progress toward Mythic, ensuring you have the necessary gear and group composition for the increased challenge.", x = 11 },
        [61370] = { e = 5, s = "c", h = { 217646, 217648, 217650 }, r = "Requires full raid group and Mythic difficulty.", d = "Complete Heroic The Voidspire first to unlock Mythic. Defeat all seven bosses on Mythic difficulty for the main set and account-wide credit.", x = 11 },
        [61371] = { e = 5, s = "c", h = { 217653, 217654 }, r = "Requires full raid group and Mythic difficulty.", d = "Finish Heroic March on Quel'Danas before attempting Mythic. You must defeat both Belo'ren and Midnight Falls on Mythic to earn these points.", x = 11 },
        [61372] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Run The Voidspire on Mythic until Imperator Averzian drops. This is part of the larger set required for the Glory achievement.", x = 11 },
        [61373] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Defeat Vorasius in The Voidspire on Mythic difficulty. Ensure you have completed Heroic first to access this content.", x = 11 },
        [61374] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Kill Fallen-King Salhadaar in The Voidspire on Mythic. This boss is one of the seven required for the main raid set.", x = 11 },
        [61375] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Defeat Vaelgor and Ezzorak together in The Voidspire on Mythic. Coordinate your group to handle this multi-phase encounter effectively.", x = 11 },
        [61376] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Clear the Lightblinded Vanguard encounter in The Voidspire on Mythic. This is a standard boss kill within the raid instance.", x = 11 },
        [61377] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Defeat Crown of the Cosmos as the final boss of The Voidspire on Mythic. Be prepared to earn the Spirebane title upon completion.", x = 11 },
        [61378] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Run March on Quel'Danas on Mythic and defeat Belo'ren, Child of Al'ar. This is a prerequisite for the special egg achievement.", x = 11 },
        [61379] = { e = 5, s = "s", r = "Single boss on Mythic requires a raid.", d = "Kill Midnight Falls in March on Quel'Danas on Mythic. You will receive the Dawnbringer title after defeating this boss.", x = 11 },
        [61380] = { e = 5, s = "c", h = { 223420, 217672, 219370 }, r = "Requires completing multiple Mythic raid achievements.", d = "Complete every listed sub-achievement to unlock the Glory of the Midnight Raider set and the Tenebrous Harrower mount. Check each specific requirement carefully.", x = 11 },
        [61381] = { e = 5, s = "c", h = { 217674 }, r = "Requires specific egg infusion and Mythic boss kill.", d = "Infuse the Sunwell Egg with Light and Void magic before killing Belo'ren on Normal or higher difficulty. Do not kill him without the egg first.", x = 11 },
        [61386] = { e = 4, s = "g", r = "Grinding 15 kills on Normal is moderate but tedious.", d = "Complete Prey Normal Mode I first to unlock this tier. Defeat any of the listed targets fifteen times on Normal difficulty. Note that Petyoll the Razorleaf counts as multiple kills toward your total.", x = 11 },
        [61387] = { e = 2, s = "s", r = "Killing one target is easy and takes under an hour.", d = "Start by defeating just one Prey target on Normal difficulty to unlock the chain. You can choose any of the listed enemies in Orgrimmar or Thunder Bluff. This unlocks the next tier where you need fifteen kills.", x = 11 },
        [61388] = { e = 5, s = "g", r = "Grinding 15 kills on Hard difficulty is very hard.", d = "Unlock Hard Mode I first by killing one target on Hard difficulty. Then defeat fifteen targets on Hard mode to complete this achievement. Finishing this also grants the corresponding Normal Mode II achievement automatically.", x = 11 },
        [61389] = { e = 4, s = "s", r = "Killing one target on Hard is difficult but doable solo.", d = "Begin with any single Prey target on Hard difficulty to unlock the tier. Once unlocked, kill fifteen targets on Hard mode to finish. This completion will simultaneously grant you the Normal and Hard Mode II achievements.", x = 11 },
        [61391] = { e = 5, s = "g", r = "Grinding 15 kills on Nightmare is very hard and RNG heavy.", d = "Unlock Nightmare Mode I by defeating one target on Nightmare difficulty. Then kill fifteen targets on Nightmare mode to complete this tier. Finishing this grants both Hard and Normal achievements for the current rank automatically.", x = 11 },
        [61392] = { e = 4, s = "s", r = "Killing one target on Nightmare is hard due to mechanics.", d = "Start by killing one Prey target on Nightmare difficulty to unlock the next tier. Defeat fifteen targets on Nightmare mode to complete the achievement. This will also grant you the Hard and Normal achievements for this rank.", x = 11 },
        [61413] = { e = 1, s = "s", r = "Inviting to a brawl is trivial and takes minutes.", d = "Travel to Deeprun Tram and speak with Bizmo to get invited to a brawl. Ensure you have completed previous Brawler's Guild prerequisites if available in your region. This is account-wide so any character can claim it.", x = 10 },
        [61414] = { e = 1, s = "s", r = "Inviting to a brawl in Orgrimmar is trivial and fast.", d = "Go to The Valley of Honor in Orgrimmar and speak with the NPC at Brawl'gar Arena. You must be invited by an existing guild member or event host to trigger the achievement. This is account-wide and requires no specific class.", x = 10 },
        [61419] = { e = 2, s = "s", r = "Winning on ice is easy but requires finding the event.", d = "Participate in a brawl that takes place on ice terrain within Brawler's Guild. Focus on avoiding falls while dealing damage to opponents during the icy match. This achievement is account-wide and tracks your specific brawl participation.", x = 10 },
        [61420] = { e = 3, s = "s", r = "Winning without taking damage is moderate due to RNG.", d = "Win a brawl without taking any damage from enemy attacks or environmental hazards. Position yourself carefully to avoid hits while securing victory over all opponents. This is an account-wide achievement that records your flawless performance.", x = 10 },
        [61421] = { e = 3, s = "s", r = "Surviving a swamp brawl is moderate due to environmental hazards.", d = "Enter a swamp-themed brawl in Brawler's Guild and emerge as the winner. Avoid getting stuck in mud or taking damage from swamp creatures during the fight. This account-wide achievement tracks your success in these specific environmental conditions.", x = 10 },
        [61422] = { e = 3, s = "s", r = "Defending against thrown items is moderate and requires skill.", d = "Survive a brawl while throwing back items like fruit and fish at opponents. Stay mobile to dodge incoming projectiles while maintaining offensive pressure on enemies. This account-wide achievement requires you to actively engage in the crowd control mechanics.", x = 10 },
        [61423] = { e = 2, s = "s", r = "Win a specific brawl type; trivial once unlocked.", d = "Queue for Brawler's Guild matches and win using agility-based abilities to trigger the 'spring in your step' condition. This is account-wide, so any character can complete it once.", x = 10 },
        [61424] = { e = 2, s = "s", r = "Win a specific brawl type; trivial once unlocked.", d = "Focus on winning brawls where your health bar remains significantly higher than your opponent's throughout the fight. Ensure you survive long enough to meet the height requirement before the match ends.", x = 10 },
        [61425] = { e = 2, s = "s", r = "Win a specific brawl type; trivial once unlocked.", d = "Select a fast character and rush through Brawler's Guild matches without using defensive cooldowns that slow movement. Speed is key, so avoid unnecessary delays or complex rotations.", x = 10 },
        [61426] = { e = 3, s = "c", r = "Requires completing all other Brawler's Guild achievements first.", d = "Win brawls while unarmed by unequipping your weapon before entering the arena. This is account-wide, so one successful run unlocks it for all characters.", x = 10 },
        [61429] = { e = 3, s = "c", h = { 218206 }, r = "Requires completing all other Brawler's Guild achievements first.", d = "Complete every single Brawler's Guild Challenge Broker Gambit to earn this title. You must first finish all prerequisite achievements listed in the info field.", x = 10 },
        [61438] = { e = 2, s = "g", r = "Grind one profession to max; takes hours but straightforward.", d = "Grind one primary profession from the Midnight category to maximum skill, such as Alchemy or Enchanting. Focus on daily quests and world drops specific to that profession.", x = 11 },
        [61439] = { e = 3, s = "c", r = "Requires two professions maxed plus specific crafting achievements.", d = "Raise two different primary professions in the Midnight category to max level. You must already have Thalassian Profession Master before starting this chain.", x = 11 },
        [61440] = { e = 4, s = "c", h = { 218308 }, r = "Requires five professions maxed plus ten of each crafting skill.", d = "Max out five primary professions from the Midnight category, including gathering and crafting skills. This requires completing specific sub-achievements for each profession.", x = 11 },
        [61441] = { e = 5, s = "c", r = "Requires all professions maxed; massive time investment.", d = "Raise all primary professions in the Midnight category to maximum skill for a massive grind. Start with gathering professions first as they are easier to level quickly.", x = 11 },
        [61442] = { e = 2, s = "s", r = "Complete a specific lorewalking campaign; takes under an hour.", d = "Complete the Loa Lorewalking Campaign by following the quest chain introduced in patch 12.0.7. This is account-wide and rewards a decorative tome.", x = 11 },
        [61446] = { e = 3, s = "c", h = { 218395 }, r = "Requires completing multiple World PvP achievements first.", d = "Finish all listed World PvP achievements, including Uprising and Dedication in the Void. These are often time-gated or require specific events to trigger.", x = 11 },
        [61447] = { e = 2, s = "s", r = "Win a specific event; trivial once the event is active.", d = "Win a Slayer's Rise Event by defeating the opposing faction during scheduled world PvP windows. Check event timers carefully as these opportunities are limited.", x = 11 },
        [61448] = { e = 3, s = "g", r = "Requires winning 10 PvP events; moderate grind.", d = "Start by queuing for Horde Slayer's Rise events and focus on winning matches to build your count. This is a grind that requires consistent participation over time, so plan to play regularly until you reach 10 wins.", x = 11 },
        [61449] = { e = 3, s = "g", r = "Requires winning 25 PvP events; continues grind.", d = "Once you hit the first tier, continue playing Slayer's Rise events to reach the higher win threshold of 25. There are no special mechanics here; simply keep winning matches as you did for the previous achievement.", x = 11 },
        [61451] = { e = 4, s = "c", h = { 218479 }, r = "Meta achievement; dominated by War Within Pathfinder.", d = "Begin this massive collection by tackling the War Within Pathfinder and Glory of the Delver achievements first, as they guide you through new content. Ensure you also complete the older Midnight zone achievements like Nerub-ar Palace before the expansion launches to avoid missing any steps.", x = 10 },
        [61452] = { e = 3, s = "c", r = "Multiple optional storylines; moderate checklist effort.", d = "Start the Sojourner of Zul'Aman collection by accepting the optional storylines in Zul'Aman immediately upon entering the zone. These quests often require specific NPC interactions or completing minor sub-goals, so follow each quest marker carefully without skipping dialogue.", x = 11 },
        [61453] = { e = 3, s = "c", r = "Find all Songseekers in Zul'Aman; moderate grind.", d = "To complete this meta achievement, first finish all individual exploration tasks like finding treasures and exploring every corner of Zul'Aman. Then, ensure you have completed the Sojourner storylines and collected specific items like the Altar of Blessings to unlock the final requirement.", x = 11 },
        [61454] = { e = 2, s = "s", r = "Single dungeon run after specific quest steps.", d = "Head to The Dreamrift on Normal difficulty or higher to find Sergeant Quackers and pluck all his Corrupted Feathers. After rescuing him, defeat Chimaerus immediately to secure this achievement before moving on to other Midnight raids.", x = 11 },
        [61455] = { e = 3, s = "g", r = "Requires finding and killing multiple specific mobs in Zul'aman.", d = "Explore Zul'Aman thoroughly to locate every Shadowpine Songseeker, as they are scattered across different areas of the zone. Use a map or flight path to travel between zones efficiently, ensuring you check caves and high ground where these NPCs often hide.", x = 11 },
        [61463] = { e = 3, s = "g", r = "Requires 4 weeks of event participation; grind.", d = "This achievement is time-gated to the Turbulent Timeways V event, so wait for it to activate in your calendar. Once active, log in daily for four weeks to maintain your Mastery status and claim the reward before the window closes.", x = 11 },
        [61464] = { e = 2, s = "g", r = "Complete quest 5 times; easy to moderate grind.", d = "Complete the Sparks of War quest in Midnight five times by accepting it from the appropriate NPC after each event cycle. This is a simple repeatable task that does not require any special conditions beyond participating in the weekly PvP event.", x = 11 },
        [61465] = { e = 3, s = "g", r = "Complete quest 20 times; requires more time.", d = "After reaching five completions, continue doing the Sparks of War quest to reach twenty total wins. Since this builds on the previous achievement, ensure you keep track of your progress as it is account-wide and cumulative.", x = 11 },
        [61466] = { e = 4, s = "c", h = { 218779 }, r = "Defeat 15 bosses; dominated by Blind Hero RNG.", d = "Visit Brawler's Guild regularly to challenge and defeat exclusive bosses like Kirrawk and Johnny Awesome. This is a grind that requires finding groups or soloing depending on your gear level, so be prepared for varying difficulty levels across the fifteen required bosses.", x = 10 },
        [61467] = { e = 3, s = "s", r = "Complete a lorewalking campaign; moderate single step.", d = "Start the Elves of Quel'Thalas Lorewalking Campaign by accepting the initial quest from the relevant NPC in Silvermoon City. Follow the campaign steps sequentially, as missing a step may require restarting parts of the storyline to progress further.", x = 10 },
        [61487] = { e = 3, s = "s", r = "Single raid boss kill on Normal difficulty.", d = "Start with Normal difficulty in The Dreamrift to unlock the raid. This is account-wide, so any character can progress it for everyone.", x = 11 },
        [61488] = { e = 4, s = "s", r = "Heroic raid boss requires higher gear and skill.", d = "You must complete the Normal version first before attempting Heroic. Ensure your group composition is solid enough for increased mechanics.", x = 11 },
        [61489] = { e = 5, s = "s", r = "Mythic difficulty adds heavy mechanics and RNG.", d = "Finish Heroic to unlock Mythic, which grants the Dream-Eater title. This requires a well-coordinated group due to complex mechanics.", x = 11 },
        [61498] = { e = 2, s = "s", r = "Completing the final campaign chapter is quick.", d = "Complete the final chapter of the War Within campaign to earn the Azeroth's Vanguard title. Ensure all campaign quests are finished first.", x = 10 },
        [61506] = { e = 3, s = "c", h = { 219289 }, r = "Requires unlocking and completing a specific storyline.", d = "Unlock Haranir in your character options before starting their storyline. Complete the Harandar Campaign to unlock the entire Allied Race.", x = 11 },
        [61507] = { e = 4, s = "g", r = "Killing 14 rare mobs in Eversong Woods takes time.", d = "Farm Eversong Woods for rare spawns like Warden of Weeds and Cre'van. These are account-wide, so one kill counts for all characters.", x = 11 },
        [61508] = { e = 3, s = "s", r = "Single arena boss kill on Normal difficulty.", d = "Defeat Charonus in Voidscar Arena on Normal difficulty first. This is a dungeon achievement that unlocks the Heroic version next.", x = 11 },
        [61509] = { e = 4, s = "s", r = "Heroic arena requires better gear and coordination.", d = "Complete the Normal run before attempting Heroic difficulty or higher. Coordinate with your group to handle the increased challenge level.", x = 11 },
        [61510] = { e = 5, s = "s", r = "Mythic/Keystone difficulty adds significant challenge.", d = "Finish Heroic Voidscar Arena first to unlock Mythic. This requires a high-level group capable of handling extreme mechanics and damage output.", x = 11 },
        [61514] = { e = 3, s = "c", h = { 219336 }, r = "Requires specific group coordination before the fight.", d = "Have all party members kneel to Fallen-King Salhadaar before the fight starts in The Voidspire. This is account-wide and requires coordination.", x = 11 },
        [61520] = { e = 3, s = "g", r = "Exploring a large zone to reveal all points.", d = "Explore Harandar by visiting key locations like Fungara Village and The Den of Echoes. Use a flying mount to speed up map exploration.", x = 11 },
        [61565] = { e = 4, s = "c", h = { 219475 }, r = "Grinding multiple Heroic dungeons is time-consuming.", d = "Complete all listed Heroic War Within dungeons to earn the Moss Skipper pet. Start with easier dungeons like Cinderbrew Meadery before tackling harder ones.", x = 11 },
        [61566] = { e = 4, s = "c", h = { 219486, 219487, 219488 }, r = "Requires completing 10 specific Mythic dungeons.", d = "Queue for all listed Mythic War Within dungeons until each shows as complete. This is account-wide and requires finishing specific dungeon achievements first; no rare drops or time gates apply.", x = 11 },
        [61567] = { e = 3, s = "c", h = { 219499, 219873, 219498 }, r = "Requires completing 8 specific Heroic dungeons.", d = "Run Heroic versions of the listed Midnight dungeons to earn the pet reward. Complete all instances in any order since there are no missable mechanics or group restrictions mentioned.", x = 11 },
        [61568] = { e = 4, s = "c", h = { 219502, 219504, 219875 }, r = "Requires completing 9 specific Mythic dungeons.", d = "Progress through Mythic Midnight dungeons after unlocking the prerequisite Heroic versions. Ensure you finish every listed dungeon as account-wide progress tracks your completion automatically.", x = 11 },
        [61574] = { e = 3, s = "c", h = { 219530, 219531, 219532 }, r = "Requires learning lore for 8 specific relics.", d = "Read or complete quests related to each Legend of the Haranir relic listed. This is a lore-based achievement requiring no combat, so check quest logs for story updates in relevant zones.", x = 11 },
        [61576] = { e = 2, s = "g", r = "Discovering 12 glyphs in one zone is easy.", d = "Fly your Skyriding mount across Eversong Woods to discover every glyph location listed. No rare drops exist here; simply visit each named zone or landmark to trigger the discovery.", x = 11 },
        [61581] = { e = 2, s = "g", r = "Discovering 11 glyphs in one zone is easy.", d = "Travel to Zul'Aman and fly over each listed area to find the glyphs. This is purely exploration-based with no combat requirements or time limits involved.", x = 11 },
        [61582] = { e = 2, s = "g", r = "Discovering 9 glyphs in one zone is easy.", d = "Explore Harandar by flying near each named location to discover the required glyphs. Since this is account-wide, ensure your character has unlocked Skyriding before starting.", x = 11 },
        [61583] = { e = 2, s = "g", r = "Discovering 11 glyphs in one zone is easy.", d = "Fly through Voidstorm and visit every listed zone to find the hidden glyphs. There are no rare drops or complex mechanics; just cover all areas thoroughly.", x = 11 },
        [61584] = { e = 3, s = "c", h = { 219574, 219575, 219576 }, r = "Requires completing all four previous glyph hunts.", d = "Unlock Skyriding first, then complete all four region-specific Glyph Hunter achievements listed. Once done, you will receive the mount reward automatically upon finishing the final requirement.", x = 11 },
        [61586] = { e = 3, s = "s", r = "Collecting a PvP set takes time but is straightforward.", d = "Equip any full armor set from PvP Season 41 to claim this collection achievement. No combat is needed; simply wear the items in your inventory or bank while logged in.", x = 11 },
        [61635] = { e = 4, s = "c", h = { 219839, 219840, 219841 }, r = "Requires defeating 3 specific Mythic raid bosses.", d = "Defeat Imperator Averzian, Vorasius, and Fallen-King Salhadaar within The Voidspire. Ensure you progress through Wing 1 first as indicated by the prerequisite achievement requirement.", x = 11 },
        [61636] = { e = 4, s = "c", h = { 219843, 219844 }, r = "Requires defeating 2 specific Mythic raid bosses.", d = "Clear Wing 2 of The Voidspire by defeating Vaelgor & Ezzorak and Lightblinded Vanguard. This is a straightforward raid completion task with no special drop conditions or time gates.", x = 11 },
        [61637] = { e = 5, s = "c", h = { 219846 }, r = "Requires Voidspire Wing 3 completion and high-level raiding.", d = "Defeat the Crown of the Cosmos within The Voidspire to earn this account-wide achievement. Ensure you have completed the previous Wing 3 requirements before attempting this boss.", x = 11 },
        [61638] = { e = 4, s = "s", r = "Standard raid boss fight without prior requirements.", d = "Defeat Nalorakk in Den of Nalorakk on Normal difficulty first. This is the base requirement for the subsequent Heroic and Mythic versions of this dungeon.", x = 11 },
        [61639] = { e = 4, s = "s", r = "Standard raid boss fight without prior requirements.", d = "Defeat Rak'tul, Vessel of Souls in Maisara Caverns to unlock further progression. Complete this Normal run before moving on to the Heroic difficulty version.", x = 11 },
        [61640] = { e = 4, s = "s", r = "Standard raid boss fight without prior requirements.", d = "Defeat Lothraxion in Nexus-Point Xenas as a prerequisite for higher difficulties. Finish the Normal instance first to ensure you can access the next tier.", x = 11 },
        [61641] = { e = 4, s = "s", r = "Standard raid boss fight without prior requirements.", d = "Defeat Ziekket in The Blinding Vale on Normal difficulty to start the chain. This normal completion is required before you can attempt the Heroic version.", x = 11 },
        [61642] = { e = 5, s = "c", r = "Requires Heroic Den of Nalorakk completion first.", d = "You must first defeat Nalorakk on Normal difficulty before attempting this Heroic run. After clearing Heroic, you will be eligible for the Mythic version next.", x = 11 },
        [61643] = { e = 5, s = "c", r = "Requires Mythic Den of Nalorakk completion first.", d = "Complete the Heroic Den of Nalorakk first, as it is a strict requirement for this Mythic achievement. Do not attempt Mythic until you have cleared the Heroic tier.", x = 11 },
        [61644] = { e = 5, s = "c", r = "Requires Heroic Maisara Caverns completion first.", d = "Defeat Rak'tul, Vessel of Souls on Normal difficulty before attempting the Heroic version. This sequence is mandatory to unlock the next difficulty level.", x = 11 },
        [61645] = { e = 5, s = "c", r = "Requires Mythic Maisara Caverns completion first.", d = "Clear the Heroic Maisara Caverns first, as it is required for this Mythic achievement. Ensure you have completed the Heroic tier before starting Mythic runs.", x = 11 },
        [61646] = { e = 5, s = "c", r = "Requires Heroic Nexus-Point Xenas completion first.", d = "Defeat Lothraxion on Normal difficulty to unlock the Heroic version. Once Heroic is done, you can proceed to the Mythic Nexus-Point Xenas achievement.", x = 11 },
        [61647] = { e = 5, s = "c", r = "Requires Mythic Nexus-Point Xenas completion first.", d = "You must complete the Heroic Nexus-Point Xenas run before attempting this Mythic version. Follow the difficulty chain strictly to avoid missing out on rewards.", x = 11 },
        [61648] = { e = 5, s = "c", r = "Requires Heroic The Blinding Vale completion first.", d = "Defeat Ziekket on Normal difficulty first to unlock the Heroic achievement. After clearing Heroic, you will be ready for the Mythic version of The Blinding Vale.", x = 11 },
        [61649] = { e = 3, s = "s", r = "Requires running a specific Mythic+ dungeon once.", d = "Defeat Ziekket on Mythic or Mythic Keystone difficulty, which requires completing Heroic first. This is a time-gated raid achievement that cannot be earned retroactively.", x = 11 },
        [61678] = { e = 4, s = "c", h = { 219905 }, r = "Finding all Superior items is a long grind; Head is hardest.", d = "Equip Superior items with at least item level 220 in every slot to complete this character-specific goal. Ensure your gear meets the minimum threshold before claiming the achievement.", x = 11 },
        [61679] = { e = 3, s = "c", r = "Epic items are common; gear up takes moderate time.", d = "Switch to Epic or better gear with a minimum item level of 233 across all equipment slots. This is a straightforward gear swap once you have access to higher-tier items.", x = 11 },
        [61681] = { e = 4, s = "g", r = "Collecting 1 million Abundance is a massive long-term grind.", d = "Harvest Abundance resources until your lifetime total reaches one million, which tracks account-wide. Farming specific nodes or activities will help you reach this large number faster.", x = 11 },
        [61683] = { e = 2, s = "g", r = "5 PvP matches is trivial for any active player.", d = "Participate in five instanced PvP matches to start the chain of battle achievements. Any rated arena or battleground counts toward this requirement.", x = 10 },
        [61684] = { e = 3, s = "g", r = "20 PvP matches takes a few hours of play.", d = "Continue playing instanced PvP until you have participated in twenty matches total, building on your previous progress. Keep track of your match count as it is account-wide.", x = 10 },
        [61685] = { e = 4, s = "g", r = "50 PvP matches requires significant time investment.", d = "Play fifty instanced PvP matches to reach the proficient stage of the battle progression chain. Consistent participation in rated modes will help you achieve this milestone quickly.", x = 10 },
        [61686] = { e = 4, s = "g", r = "100 PvP matches is a long grind requiring patience.", d = "Accumulate one hundred instanced PvP matches by consistently queuing for arena or battlegrounds. This step bridges the gap between proficiency and expert status.", x = 10 },
        [61687] = { e = 5, s = "g", r = "200 PvP matches is a very long grind for most.", d = "Participate in two hundred instanced PvP matches to become a champion in battle. Maintain steady play to avoid falling behind on this long-term goal.", x = 10 },
        [61688] = { e = 5, s = "g", r = "300 PvP matches is an extreme time sink.", d = "Reach three hundred instanced PvP matches by continuing to queue for rated modes. This final step in the chain rewards you with a unique decor reward.", x = 10 },
        [61707] = { e = 4, s = "c", h = { 220408 }, r = "Completing many delves is a grind; Shadowguard Point is hardest.", d = "Complete all listed Midnight delves on any difficulty, starting with the initial set and progressing through the full list. Ensure you finish each delve before moving to the next tier.", x = 11 },
        [61708] = { e = 5, s = "c", h = { 220444 }, r = "Tier 4+ delves with lives remaining is a very hard grind.", d = "Finish the same delves again on Tier 4 or higher while keeping lives remaining for this advanced challenge. Plan your runs carefully to meet the higher difficulty requirement without dying.", x = 11 },
        [61709] = { e = 3, s = "c", r = "Requires completing ~22 delves on Tier 8+.", d = "Start with Tier 8 delves to unlock the chain, ensuring you finish each run with lives remaining. Progress through all listed locations sequentially as this is an account-wide requirement.", x = 11 },
        [61710] = { e = 4, s = "c", r = "Tier 11 difficulty makes each delve harder.", d = "Unlock this by first completing Delver of the Depths III: Midnight. Focus on finishing every delve at Tier 11 or higher while keeping at least one life bar active.", x = 11 },
        [61711] = { e = 3, s = "c", r = "Requires D/D role on ~22 delves Tier 4+.", d = "Begin as a damage dealer in Tier 4 delves, prioritizing DPS roles to unlock subsequent tiers. Ensure you survive each run with lives remaining before moving to the next difficulty.", x = 11 },
        [61712] = { e = 4, s = "c", r = "Tier 8 difficulty adds significant challenge.", d = "Unlock after finishing the first Damage Dealer achievement by running all delves at Tier 8 or higher. Maintain your damage output while ensuring you do not lose all lives in any encounter.", x = 11 },
        [61713] = { e = 5, s = "c", r = "Tier 11 difficulty makes this very hard.", d = "Complete this final tier by running every delve at Tier 11 as a damage dealer with lives remaining. This is account-wide, so coordinate with friends if you need specific keys or roles.", x = 11 },
        [61714] = { e = 3, s = "c", r = "Requires H role on ~22 delves Tier 4+.", d = "Start as a healer in Tier 4 delves to unlock the chain. Focus on keeping your group alive while ensuring you finish each run with at least one life bar intact.", x = 11 },
        [61715] = { e = 4, s = "c", r = "Tier 8 difficulty adds significant challenge.", d = "Unlock after finishing Healer I by completing all delves at Tier 8 or higher as a healer. Prioritize healing output and survival to meet the lives remaining requirement for each location.", x = 11 },
        [61716] = { e = 5, s = "c", r = "Tier 11 difficulty makes this very hard.", d = "Finish this tier by running every delve at Tier 11 as a healer with lives remaining. Coordinate with your group to ensure you are designated as the primary healer for credit.", x = 11 },
        [61717] = { e = 3, s = "c", r = "Requires T role on ~22 delves Tier 4+.", d = "Start as a tank in Tier 4 delves, focusing on threat generation and survival. Ensure you complete each run with lives remaining before progressing to higher tiers of this account-wide chain.", x = 11 },
        [61718] = { e = 4, s = "c", r = "Tier 8 difficulty adds significant challenge.", d = "Unlock after finishing Tank I by completing all delves at Tier 8 or higher as a tank. Maintain your tanking role and ensure you survive encounters without losing all lives.", x = 11 },
        [61719] = { e = 5, s = "c", r = "Tier 11 difficulty makes this very hard.", d = "Complete this final tier by running every delve at Tier 11 as a tank with lives remaining. Coordinate with your group to ensure you are designated as the primary tank for credit.", x = 11 },
        [61720] = { e = 5, s = "c", r = "Requires all roles on hardest delves.", d = "Unlock after completing Damage Dealer, Healer, and Tank I achievements. You must run every delve at Tier 4 or higher while playing each role separately, ensuring lives remain in all runs.", x = 11 },
        [61721] = { e = 3, s = "c", h = { 220561, 220562, 220563 }, r = "Requires three specific roles across multiple high-tier delves.", d = "Queue for Midnight Delve as a Damage Dealer, Healer, and Tank on Tier 8+ gear. Ensure you have lives remaining upon defeat to claim the Finery Funds reward.", x = 11 },
        [61722] = { e = 3, s = "g", r = "Collecting all available curios requires repeated runs.", d = "Complete all available curios for Valeera Sanguinar immediately after unlocking them in the delve menu. Do not miss any new curio drops as they may become unavailable later.", x = 11 },
        [61723] = { e = 3, s = "g", r = "Requires collecting rank 4 versions of all curios.", d = "Unlock Curio Enthusiast first, then grind to rank 4 for every single curious item. Check your collection frequently since some curios might be missable content.", x = 11 },
        [61724] = { e = 3, s = "c", h = { 220565, 220566, 220567 }, r = "Completing four distinct story variants of The Grudge Pit.", d = "Run The Grudge Pit multiple times until you have completed all four distinct story variants listed in the info field. Each run counts toward the total points required.", x = 11 },
        [61725] = { e = 3, s = "c", h = { 220601, 220602, 220603 }, r = "Completing four distinct story variants of Parhelion Plaza.", d = "Complete every story variant of Parhelion Plaza by finishing the specific objectives shown after entering the delve. Ensure you finish each unique scenario to earn full credit.", x = 11 },
        [61726] = { e = 3, s = "c", h = { 220589, 220590, 220591 }, r = "Completing four distinct story variants of Collegiate Calamity.", d = "Finish all four story variants of Collegiate Calamity within a single run or across multiple attempts if needed. Verify completion by checking your achievement progress after exiting.", x = 11 },
        [61727] = { e = 3, s = "c", h = { 220577, 220578, 220579 }, r = "Completing four distinct story variants of The Shadow Enclave.", d = "Run The Shadow Enclave repeatedly to unlock and complete all four required story variants. Be prepared for different objectives each time you enter the instance.", x = 11 },
        [61728] = { e = 3, s = "c", h = { 220569, 220570, 220571 }, r = "Completing three distinct story variants of The Darkway.", d = "Complete every story variant of The Darkway by fulfilling the specific end-game conditions listed in the info data. Do not skip any unique scenario endings.", x = 11 },
        [61729] = { e = 3, s = "c", h = { 220581, 220582, 220583 }, r = "Completing four distinct story variants of Atal'Aman.", d = "Finish all four story variants of Atal'Aman to secure your points. Each variant requires a specific set of objectives that must be met before leaving the delve.", x = 11 },
        [61730] = { e = 3, s = "c", h = { 220573, 220574, 220575 }, r = "Completing four distinct story variants of Twilight Crypts.", d = "Run Twilight Crypts until you have completed all four available story variants. Ensure you survive and meet the unique requirements for each scenario.", x = 11 },
        [61731] = { e = 3, s = "c", h = { 220585, 220586, 220587 }, r = "Completing three distinct story variants of The Gulf of Memory.", d = "Complete every story variant of The Gulf of Memory by achieving the specific goals listed in the info field. These objectives may vary between runs.", x = 11 },
        [61732] = { e = 3, s = "c", h = { 220597, 220598, 220599 }, r = "Completing three distinct story variants of Sunkiller Sanctum.", d = "Finish all three story variants of Sunkiller Sanctum to earn your points. Check your progress after each run to ensure no variant is missed.", x = 11 },
        [61733] = { e = 4, s = "c", h = { 220593, 220594, 220595 }, r = "Requires finding and completing multiple specific story variants.", d = "Complete all four Shadowguard Point story variants in any order since they are account-wide. Focus on finishing the main campaign first to unlock necessary items for these specific side stories.", x = 11 },
        [61734] = { e = 4, s = "c", h = { 220605 }, r = "Needs level 90 Warband to unlock Tier 4 content.", d = "Reach level 90 and finish the entire Midnight main story campaign with your Warband before attempting this tier. This unlocks Tier 4 delves and is required for all subsequent delve tiers.", x = 11 },
        [61739] = { e = 4, s = "c", r = "Requires completing many optional storylines in Harandar.", d = "Quest up the optional Harandar storylines after completing the main zone content to ensure you do not miss any hidden objectives. These quests are account-wide but require specific triggers found during exploration.", x = 11 },
        [61741] = { e = 5, s = "c", h = { 220623, 220624, 220625 }, r = "Requires completing numerous specific delve story variants.", d = "Finish every single delve achievement listed in the Delve Loremaster category before moving on to higher tiers. Some story variants may be missable if you do not complete them within a specific timeframe or after unlocking new content.", x = 11 },
        [61792] = { e = 3, s = "c", r = "Requires tagging opponents in the Prop Hunt event multiple times.", d = "Play Decor Duel matches and actively hunt for Spellbreaker opponents to tag them five times. This requires finding the Prop Hunt event mode and coordinating with teammates to locate hidden players.", x = 11 },
        [61793] = { e = 3, s = "c", r = "Requires tagging opponents in the Prop Hunt event multiple times.", d = "Participate in Decor Duel events specifically looking for Nullifier opponents to tag them five times. Ensure you are playing the correct Prop Hunt variant where Nullifiers appear as the target class.", x = 11 },
        [61832] = { e = 3, s = "g", r = "Requires completing a specific Tier 1 delve instance.", d = "Complete any Tier 1 delve immediately after unlocking it to progress toward Tier 2 access. Do not delay this step as you cannot unlock higher tiers without finishing the current one.", x = 11 },
        [61835] = { e = 4, s = "c", r = "Requires unlocking and completing Tier 2 delves after Tier 1.", d = "Finish a Tier 2 delve only after completing all Tier 1 requirements and unlocking the next tier. This is a strict chain progression so ensure your Warband has cleared the previous level first.", x = 11 },
        [61836] = { e = 4, s = "c", r = "Requires unlocking and completing Tier 3 delves after Tier 2.", d = "Clear a Tier 3 delve once you have fully completed Tier 2 content and unlocked this new tier. This step is mandatory before you can access the Endgame campaign or Tier 4 delves.", x = 11 },
        [61839] = { e = 4, s = "c", r = "Requires completing multiple exploration achievements across zones.", d = "Explore all listed Midnight achievements including specific zones like Eversong Woods and Voidstorm to unlock Finery Funds. Check your collection frequently as some exploration goals may be tied to rare events or hidden areas.", x = 11 },
        [61843] = { e = 5, s = "g", r = "Requires obtaining and equipping a full Tier 35 set on one class.", d = "Equip and level a full Tier 35 set from Midnight Season 1 on at least one character to claim this appearance achievement. You must collect all pieces of the set rather than just wearing them for a short time.", x = 11 },
        [61854] = { e = 3, s = "c", r = "Requires visiting and exploring all four major Midnight regions.", d = "Travel to and explore every major region in the Lands of Midnight including Harandar and Zul'Aman. Use the map markers to ensure you have visited all sub-zones required for this exploration goal.", x = 11 },
        [61855] = { e = 3, s = "c", r = "Requires visiting multiple locations in Eversong Woods.", d = "Explore Eversong Woods by visiting every listed location to reveal covered map areas. This is account-wide and requires reaching level 12, so ensure you have unlocked the zone first.", x = 11 },
        [61856] = { e = 3, s = "c", r = "Requires visiting multiple locations in Zul'Aman.", d = "Visit all specified points in Zul'Aman to complete this exploration achievement. It unlocks at level 12 and is account-wide, so check your map for any remaining covered zones.", x = 11 },
        [61857] = { e = 4, s = "c", r = "Requires unlocking Mythic VFX or completing a difficult raid.", d = "Travel to every location listed in Voidstorm to finish the exploration requirement. This zone becomes available at level 12, making it a time-gated achievement until then.", x = 11 },
        [61858] = { e = 4, s = "c", h = { 220807 }, r = "Requires completing an Elite Mythic+ dungeon or raid.", d = "Unlock Mythic VFX or complete one of the listed Midnight Season achievements to earn this appearance reward. These are account-wide and often require specific dungeon runs or raids.", x = 11 },
        [61859] = { e = 3, s = "c", r = "Requires visiting multiple flight masters in Midnight.", d = "Fly to each Flight Master in Midnight zones to discover their flight points for your Warband. Ensure you have unlocked the necessary zones before attempting this task.", x = 11 },
        [61860] = { e = 2, s = "s", r = "Simple flying action to a specific high location.", d = "Use a mount to fly high above Harandar near The Cradle to complete this exploration goal. You must be in the correct zone and likely need a flying mount.", x = 11 },
        [61861] = { e = 3, s = "g", r = "Requires chasing and returning multiple opportunistic mobs.", d = "Chase an Opportunistic Harrower back to its nest in Voidstorm to earn these points. This may require patience as the creature can be elusive or aggressive.", x = 11 },
        [61863] = { e = 2, s = "g", r = "Requires opening three chests in a delve instance.", d = "Locate and open all Sturdy Chests hidden within Atal'Aman delve instances. Since this is account-wide, ensure you have access to the delve content before starting.", x = 11 },
        [61864] = { e = 3, s = "c", r = "Requires completing several optional storylines in Voidstorm.", d = "Complete every optional storyline quest listed for Voidstorm to finish this achievement. These quests are account-wide and may require specific story progression or level 12+.", x = 11 },
        [61878] = { e = 2, s = "g", r = "Requires tagging five players in a specific game mode.", d = "Play as an Arcane Ranger in Decor Duel and successfully tag five opposing players. This event requires the 12.0.5 update and is best done with friends for efficiency.", x = 11 },
        [61879] = { e = 3, s = "s", r = "Requires winning a round with all hiders tagged quickly.", d = "Win a Seeker round in Decor Duel by tagging all hiders within two minutes. Coordinate with your team to cover the map quickly and efficiently.", x = 11 },
        [61880] = { e = 2, s = "s", r = "Requires hiding for a specific duration in a game mode.", d = "Hide as a Hider in Decor Duel and remain unfound for at least one minute and thirty seconds. Use stealth mechanics effectively to avoid detection by Seekers.", x = 11 },
        [61881] = { e = 2, s = "s", r = "Requires finding a specific event and playing as the last hider.", d = "Play as the Hider and focus on staying hidden until the round ends to become the last untagged player. This is account-wide, so coordinate with friends or wait for a full group match in Decor Duel.", x = 11 },
        [61882] = { e = 3, s = "g", r = "Grinding multiple runs to get found without being tagged.", d = "Aim to get detected by the Seekers without actually being tagged during the match. Use stealth abilities carefully to drop your 'Found' status while avoiding direct contact.", x = 11 },
        [61883] = { e = 3, s = "g", r = "Grinding multiple runs to survive the first minute untagged.", d = "Start immediately when the round begins and use all mobility skills to evade detection for the full first minute. Repeat this three times, as it is account-wide and requires multiple attempts.", x = 11 },
        [61886] = { e = 2, s = "s", r = "Buying upgrades from a vendor during the event.", d = "Visit the vendor in Decor Duel and purchase every available upgrade kit to unlock all abilities. Ensure you have enough gold or currency before starting, as this unlocks essential tools for other achievements.", x = 11 },
        [61887] = { e = 4, s = "c", r = "Requires completing all other achievements including grinds and delves.", d = "Complete all individual Decor Duel achievements listed in the info field first, then verify that every single one is finished. This final achievement requires 100% completion of the previous tasks.", x = 11 },
        [61892] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Enter The Shadow Enclave delve and locate every Sturdy Chest hidden within the map. Open each chest to complete this discovery set, noting that you need three successful runs per delve type.", x = 11 },
        [61893] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Navigate Parhelion Plaza carefully to find all concealed Sturdy Chests before exiting the delve. This is account-wide, so one successful run clears the requirement for your entire account.", x = 11 },
        [61894] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Explore Collegiate Calamity thoroughly to uncover and open every Sturdy Chest present in the area. Ensure you check hidden corners and interact with all objects to avoid missing any chests.", x = 11 },
        [61895] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Search The Darkway for all Sturdy Chests, paying attention to areas that may be obscured by darkness or fog. Open each chest to fulfill the requirement of three per delve.", x = 11 },
        [61896] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Investigate Twilight Crypts and open every Sturdy Chest you find within the dungeon. This task is account-wide, so one complete run with all chests opened will finish it.", x = 11 },
        [61897] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Find and open all Sturdy Chests hidden in The Grudge Pit during your delve run. Make sure to backtrack if necessary, as some chests may be in hard-to-reach spots.", x = 11 },
        [61898] = { e = 3, s = "g", r = "Grinding to find and open chests in a specific delve area.", d = "Locate every Sturdy Chest in The Gulf of Memory and open them to complete the discovery set. This is account-wide, so ensure you do not miss any chests before leaving the delve.", x = 11 },
        [61899] = { e = 2, s = "g", r = "Find and open 3 chests in a delve.", d = "Run Sunkiller Sanctum repeatedly until you find and open all three Sturdy Chests. This is account-wide, so any character can contribute to the progress.", x = 11 },
        [61900] = { e = 2, s = "g", r = "Find and open 3 chests in a delve.", d = "Complete Shadowguard Point by locating and opening every hidden Sturdy Chest inside. You must do this on multiple characters if needed to find all chests.", x = 11 },
        [61901] = { e = 4, s = "c", h = { 221059, 221060, 221061 }, r = "Open chests across many delves; some are rare spawns.", d = "Finish every Midnight delve listed in the info field to unlock the Treasure Seeker title. Prioritize delves with known chest locations or run them until you hit the daily limit.", x = 11 },
        [61906] = { e = 4, s = "c", h = { 221070, 221071, 221072 }, r = "Requires completing multiple other delve achievements.", d = "Unlock the Giganto Manis mount by completing the other Midnight achievements first. Ensure you have the Loremaster and Treasure Seeker titles before attempting this final step.", x = 11 },
        [61910] = { e = 3, s = "c", h = { 221078, 221079, 221080 }, r = "Complete three separate questlines in different zones.", d = "Travel to Borean Tundra, Highmountain, and Zul'Aman to finish King Mrgl-Mrgl's storylines. This is account-wide, so coordinate with friends if you need specific zones.", x = 11 },
        [61911] = { e = 4, s = "c", h = { 221095 }, r = "Requires raid coordination and precise timing on tethers.", d = "Form a full raid group for The Voidspire Normal or higher to break all Nullzone tethers within three seconds. Communication is key; use voice chat to coordinate the final pull.", x = 11 },
        [61912] = { e = 3, s = "c", h = { 221138, 221139, 221140 }, r = "Construct three different defenses during an event.", d = "Participate in the Stormarion Assault event and build every unique defense structure available. This often requires a full group to handle all objectives efficiently.", x = 11 },
        [61913] = { e = 3, s = "c", h = { 221143, 221144, 221145 }, r = "Complete three distinct waves of an assault event.", d = "Clear all three waves of the Stormarion Assault without failing any wave. Ensure your group composition is strong enough to handle the increasing difficulty.", x = 11 },
        [61916] = { e = 3, s = "s", r = "Complete a single questline to unlock a class.", d = "Complete the Rage of the Ren'dorei questline to unlock the Void Elf Demon Hunter class. This is account-wide and may require specific zone access or story progression.", x = 11 },
        [61922] = { e = 3, s = "c", h = { 221225 }, r = "Finish an assault event with specific health threshold.", d = "Finish the Stormarion Assault while keeping the Singularity Anchor above 90 percent health. Avoid taking too much damage during the final phase to meet this threshold.", x = 11 },
        [61936] = { e = 4, s = "s", r = "Requires raid coordination and specific aura mechanics.", d = "Gather a full raid group for The Voidspire Normal or higher and ensure every player has Maximum Aura before fighting the Lightblinded Vanguard. Coordinate aura management carefully during the encounter.", x = 11 },
        [61937] = { e = 2, s = "g", r = "Collect currency in a single zone over time.", d = "Visit Watha'nan Crypts in Eversong Woods to earn Abundance points until you reach 250,000 total. This is account-wide, so run the crypts frequently with any character.", x = 11 },
        [61938] = { e = 4, s = "g", r = "Requires farming a specific currency for 250k points.", d = "First unlock the Abundance system via its tutorial, then farm points specifically at the Loaknit Den in Zul'Aman. You must reach 100,000 lifetime points before this specific goal becomes available.", x = 11 },
        [61939] = { e = 4, s = "g", r = "Requires farming a specific currency for 250k points.", d = "Unlock the Abundance system first, then travel to Harandar to farm the Floaret Grotto location. Ensure you have met the 100,000 lifetime point requirement before attempting this sub-achievement.", x = 11 },
        [61940] = { e = 4, s = "g", r = "Requires farming a specific currency for 250k points.", d = "Complete the Abundance tutorial and reach the required lifetime points before heading to Voidstorm. Farm the Abundant Voidburrow until you accumulate 250,000 points there.", x = 11 },
        [61941] = { e = 2, s = "s", r = "Tutorial completion is quick and guided.", d = "Start by speaking with Dundun and Chel the Chip in Eversong Woods to finish the tutorial. This unlocks the entire Abundance system for your account.", x = 11 },
        [61942] = { e = 3, s = "s", r = "Requires creating a new character and leveling to 50.", d = "Create a new Haranir character and level it to 50 to claim the heritage armor. Note that this requirement is account-wide once unlocked.", x = 11 },
        [61943] = { e = 4, s = "c", h = { 221311, 221312, 221313 }, r = "Requires completing multiple distinct location-specific grinds.", d = "After unlocking Abundance, visit all four listed locations: Watha'nan Crypts, Loaknit Den, Floaret Grotto, and Abundant Voidburrow. Complete every event at each site to finish this collection.", x = 11 },
        [61953] = { e = 4, s = "g", r = "Winning 10 matches takes significant time and luck.", d = "Enter the Training Grounds arena and win ten matches in a row or over time. This is account-wide, so wins from any character count toward your total.", x = 11 },
        [61954] = { e = 4, s = "g", r = "Winning 25 matches is a long grind with RNG.", d = "Continue winning matches in the Training Grounds until you reach twenty-five total victories. You must already have completed the previous ten-win milestone.", x = 11 },
        [61955] = { e = 4, s = "g", r = "Winning 100 matches requires substantial time investment.", d = "Keep playing arena matches to reach one hundred total wins, building on your previous progress. This tracks account-wide across all characters.", x = 11 },
        [61956] = { e = 4, s = "g", r = "Winning 250 matches is a very long grind.", d = "Persist in winning Training Grounds matches until you hit two hundred fifty victories. There is no time limit, but it requires consistent play.", x = 11 },
        [61957] = { e = 3, s = "c", h = { 221344 }, r = "Most tasks are short quests; one involves a long raid.", d = "Complete every optional storyline listed in Eversong Woods, starting with the main local stories. This includes various side quests and is tracked account-wide.", x = 11 },
        [61958] = { e = 4, s = "c", h = { 221362, 221363 }, r = "Requires defeating 15 specific champions, some very hard.", d = "Defeat each of the fifteen specific Horde champions listed in the Training Grounds. You must kill every single one to complete this collection.", x = 11 },
        [61959] = { e = 3, s = "c", h = { 221915 }, r = "Requires killing 15 specific champions; one is a rare spawn.", d = "Queue for PvP training matches and kill each listed champion, noting that Ulfrik Stoutarm requires fifteen kills. Since this is account-wide, alternate characters can help speed up progress if you are stuck on specific champions.", x = 11 },
        [61960] = { e = 3, s = "g", r = "Collecting 12 hidden items across a large zone takes time.", d = "Explore Eversong Woods thoroughly to find hidden caches, safes, and gifts scattered in the environment. This achievement is account-wide, so ensure your main character visits every zone before logging off to avoid missing items.", x = 11 },
        [61961] = { e = 3, s = "c", h = { 221384 }, r = "Defending 5 runestones; one requires a specific rare spawn.", d = "Locate and defend all five runestones in Eversong Woods by standing near them while they are active. You must complete this within the Midnight event window, as runestones will not appear outside that time.", x = 11 },
        [62057] = { e = 3, s = "c", h = { 221640 }, r = "Place telescopes on peaks; one location requires a rare spawn.", d = "Travel to the highest peaks in Eversong Woods, Zul'Aman, Harandar, and Voidstorm to place telescopes on each location. This is account-wide, so coordinate with friends or wait for event windows if you cannot reach all zones quickly.", x = 11 },
        [62058] = { e = 4, s = "c", h = { 221691 }, r = "Raid achievement requiring coordination and RNG to feed hatchlings.", d = "In The Voidspire raid, ensure every player feeds a hatchling before engaging Vorasius to trigger the sleep mechanic. This requires full group coordination on Normal difficulty or higher, making it essential to communicate clearly during the encounter.", x = 11 },
        [62096] = { e = 5, s = "g", r = "Obtaining 600 mounts is a massive grind requiring heavy RNG.", d = "Collect mounts across all zones and activities until you reach 600 unique mounts for your character. Since this is account-wide, alternate characters can help gather rare mounts faster, but ensure each mount is usable by at least one character.", x = 11 },
        [62103] = { e = 5, s = "g", r = "Same as 62096; obtaining 600 mounts is a massive grind.", d = "This achievement mirrors the previous one for Alliance characters; follow the same strategy of collecting 600 mounts across all zones. Coordinate with friends or use alternate characters to speed up progress if needed.", x = 11 },
        [62104] = { e = 3, s = "c", h = { 222010 }, r = "Discover lore objects; one requires finding a rare spawn.", d = "Explore Midnight zones like Eversong Woods and Zul'Aman to find lore objects such as plaques, tablets, and murals. Some items are rare or hidden, so thoroughly search each zone during the event window.", x = 11 },
        [62105] = { e = 3, s = "s", r = "Single world quest with strict RNG mechanic; partial progress irrelevant.", d = "Complete the Voidstorm world quest Precision Excision without missing any shots from Lysikas. This requires precise timing and positioning, so practice the mechanics beforehand to avoid failure.", x = 11 },
        [62106] = { e = 4, s = "s", r = "Specific raid encounter condition with RNG element; partial progress irrelevant.", d = "In The Voidspire raid, defeat Imperator Averzian after he destroys your banners on Normal difficulty or higher. Coordinate with your group to ensure banners are destroyed before engaging him for credit.", x = 11 },
        [62107] = { e = 2, s = "c", r = "Perform emote in 3 maps; trivial once inside the zones.", d = "Use the /train emote in each Training Grounds map: The Battle for Gilneas, Arathi Basin, and Silvershard Mines. This is account-wide, so alternate characters can help complete it faster if needed.", x = 11 },
        [62108] = { e = 4, s = "c", h = { 221955 }, r = "Win without dying in 3 maps; one map has high difficulty.", d = "Win PvP matches in each Training Grounds map without dying to earn credit. This requires skilled gameplay and coordination with teammates, as dying resets progress for that specific map.", x = 11 },
        [62109] = { e = 1, s = "s", r = "Single match win; trivial if you know the mechanic.", d = "Queue for a Training Grounds match and focus on survival rather than aggressive flag pushing. Avoid taking unnecessary damage to ensure you win without dying, as this is the only requirement.", x = 11 },
        [62110] = { e = 3, s = "g", r = "Grind 10 specific PVP matches; moderate time investment.", d = "Complete all listed Midnight quest achievements first to unlock the Loremaster title. This is a collection goal with no time gate, so finish them at your own pace before attempting the main achievement.", x = 11 },
        [62111] = { e = 3, s = "g", r = "Grind 10 specific PVP matches; moderate time investment.", d = "Queue for Arathi Basin Training Grounds and prioritize securing all five flags simultaneously. Do not let the enemy team capture any flag, as losing control of even one will reset your progress toward this specific goal.", x = 11 },
        [62112] = { e = 3, s = "g", r = "Grind 10 specific PVP matches; moderate time investment.", d = "Play Battle for Gilneas Training Grounds matches while ensuring your team controls all three flags at once. Maintain map awareness to prevent the enemy from capturing any flag during the match.", x = 11 },
        [62113] = { e = 3, s = "g", r = "Grind 10 specific PVP matches; moderate time investment.", d = "In Silvershard Mines Training Grounds, focus on defending your mine carts aggressively. Never allow the opposing team to capture a cart, as losing even one will invalidate your progress toward this achievement.", x = 11 },
        [62114] = { e = 3, s = "g", r = "Grind 50 flag captures; steady progress in training mode.", d = "Queue for Arathi Basin Training Grounds and actively grab flags whenever possible. You need to collect fifty flags total, so participate in every flag contest regardless of whether you win the match.", x = 11 },
        [62115] = { e = 3, s = "g", r = "Grind 30 flag captures; steady progress in training mode.", d = "Play Battle for Gilneas Training Grounds matches and aim to capture thirty flags. Focus on securing flags quickly early in the match to maximize your count before the timer runs out.", x = 11 },
        [62116] = { e = 3, s = "g", r = "Grind 100 cart captures; steady progress in training mode.", d = "Queue for Silvershard Mines Training Grounds and prioritize capturing mine carts over winning the match. You must control one hundred carts total, so grab any cart that becomes available during gameplay.", x = 11 },
        [62117] = { e = 2, s = "g", r = "Collect 10 fish; easy solo activity with upgrades.", d = "Start Abyss Angler dives immediately after unlocking the ability to collect fish from Abyss Bubbles. Aim to catch ten Finnow Chum fish quickly, as this is the first step in the fishing upgrade chain.", x = 11 },
        [62118] = { e = 3, s = "g", r = "Grind 25 fish plus upgrade; slightly more than base.", d = "After collecting ten Finnow Chum, purchase the Plecofin Bait upgrade from Depthdiver Jeju. Continue diving to collect twenty-five total fish, noting that you must acquire the upgrade twice to complete this specific goal.", x = 11 },
        [62119] = { e = 4, s = "g", r = "Grind 50 fish plus upgrades; requires significant time.", d = "Purchase the Murkskimmer Meat upgrade after acquiring the previous bait upgrades. Dive repeatedly to reach fifty total fish, ensuring you have collected the required number of Plecofin Bait upgrades along the way.", x = 11 },
        [62120] = { e = 3, s = "c", h = { 222484, 222485, 222486 }, r = "Develop bonds with all Loa; checklist of separate steps.", d = "Visit the Altar of Blessings in Darnassus and interact with each Loa to develop bonds. Complete all individual Loa achievements first, as they are required to unlock worship for every Loa at the altar.", x = 11 },
        [62121] = { e = 4, s = "c", r = "Requires triggering many specific buffs across zones.", d = "Start by picking up the Altar of Blessings questline in Eversong Woods to unlock all buff effects. Activate each buff once while exploring or fighting normal content; this is account-wide and has no time gate.", x = 11 },
        [62122] = { e = 3, s = "g", r = "Grinding rare mobs in Zul'Aman takes time.", d = "Enter Zul'Aman and hunt for rare elites marked on your map, focusing on high-level zones like the upper levels. Some rares may require specific keys or group coordination, so be prepared to wait for drops.", x = 11 },
        [62125] = { e = 4, s = "c", r = "Finding 12 hidden treasures requires thorough exploration.", d = "Explore Zul'Aman thoroughly to find hidden chests and lootable objects scattered throughout the zone. Use a macro to quickly interact with every clickable object you encounter to avoid missing any treasures.", x = 11 },
        [62126] = { e = 4, s = "c", r = "Locating all hidden caches in Voidstorm is tedious.", d = "Travel to Voidstorm and search for glowing or suspicious items on the ground and in containers. Check every corner of the zone, as some treasures are hidden behind walls or require specific interactions.", x = 11 },
        [62130] = { e = 4, s = "g", r = "Killing all rare mobs in Voidstorm is a grind.", d = "Locate and defeat all rare elites in Voidstorm, which often appear near major landmarks or spawn points. These rares can be tough, so bring appropriate gear and consider grouping up for difficult encounters.", x = 11 },
        [62133] = { e = 3, s = "s", r = "Surviving one long encounter with the Hungering Presence.", d = "Enter Voidstorm and run away from the Hungering Presence until your timer reaches 60 seconds. Stay mobile and avoid aggro to maximize your evasion time without getting caught.", x = 11 },
        [62134] = { e = 3, s = "g", r = "Completing 5 specific War Mode hunts takes time.", d = "Enable War Mode and complete five Prey Hunts in any Midnight zone. These hunts are account-wide, so you can do them on any character once the feature is unlocked.", x = 11 },
        [62135] = { e = 4, s = "s", r = "Nightmare Hunts are difficult and RNG-dependent.", d = "Start a Nightmare Hunt while War Mode is active to earn this achievement. Ensure your group is ready for higher difficulty content, as these hunts are significantly more challenging than normal ones.", x = 11 },
        [62136] = { e = 5, s = "g", r = "Killing 50 players in a Nightmare Hunt is very hard.", d = "Join or form a group and engage in PvP during a Nightmare Hunt to kill other players. This achievement requires active participation in combat, so avoid passive playstyles that might miss the kill count.", x = 11 },
        [62137] = { e = 4, s = "c", r = "Defeating 10 ambushes requires finding specific events.", d = "Defeat ten Prey Ambushes by completing specific ambush objectives within the game. These events are time-limited and often require quick reaction times, so stay alert during hunts.", x = 11 },
        [62138] = { e = 5, s = "g", r = "Killing 100 ambush targets is a massive grind.", d = "Complete one hundred Prey Ambushes to unlock this achievement. Since it requires the previous one, ensure you have already defeated ten ambushes before attempting this milestone.", x = 11 },
        [62139] = { e = 4, s = "c", r = "Requires completing hunts in all four Midnight zones.", d = "Run a Prey Hunt in each of the four Midnight zones: Eversong Woods, Zul'Aman, Harandar, and Voidstorm. Complete at least one hunt per zone to satisfy the requirement for this account-wide achievement.", x = 11 },
        [62140] = { e = 3, s = "g", r = "Grinding 100 items during a specific event.", d = "Start by accepting the Kitchen Nightmare quest and immediately begin cooking while active. This is account-wide, so coordinate with friends to share the burden of 100 meals.", x = 11 },
        [62141] = { e = 3, s = "g", r = "Grinding 100 fish during a specific event.", d = "Accept the Look, I'm Just Trying To Fish Here quest and fish continuously during a hunt. Ensure you are in a valid Prey zone to count toward your total.", x = 11 },
        [62142] = { e = 3, s = "g", r = "Grinding 50 ripostes during ambush events.", d = "You must be ambushed by enemies to trigger Riposte counters for this achievement. Stay mobile and engage groups to maximize ambush opportunities.", x = 11 },
        [62143] = { e = 3, s = "g", r = "Grinding 100 trap interactions during hunts.", d = "Interact with any trap you encounter while on a hunt, as the counter tracks total interactions. Do not ignore traps even if they seem harmless.", x = 11 },
        [62144] = { e = 4, s = "c", h = { 222118 }, r = "Hard mode boss requires group coordination and RNG.", d = "Defeat either Magister Sunbreaker or Magistrix Emberlash on Hard mode to complete this. These bosses are account-wide and require a full group.", x = 11 },
        [62153] = { e = 4, s = "c", h = { 222179 }, r = "Hard mode boss requires group coordination and RNG.", d = "Take down Senior Tinker Ozwold or L-N-0R the Recycler on Hard mode for your reward. Ensure you have the correct gear for Hard difficulty.", x = 11 },
        [62154] = { e = 4, s = "c", h = { 222182 }, r = "Hard mode boss requires group coordination and RNG.", d = "Defeat Mordril Shadowfell or Deliah Gloomsong on Hard mode to claim your bust. These fights can be challenging, so prepare accordingly.", x = 11 },
        [62155] = { e = 4, s = "c", h = { 222185 }, r = "Hard mode boss requires group coordination and RNG.", d = "Kill Phaseblade Talasha or Nexus-Edge Hadim on Hard mode while in a group. This is account-wide, so you can help others progress.", x = 11 },
        [62156] = { e = 4, s = "c", h = { 222188 }, r = "Hard mode boss requires group coordination and RNG.", d = "Defeat Jo'zolo the Breaker or Zadu, Fist of Nalorakk on Hard mode. Coordinate with your party to handle their mechanics effectively.", x = 11 },
        [62157] = { e = 4, s = "c", h = { 222191 }, r = "Hard mode boss requires group coordination and RNG.", d = "Take out The Talon of Jan'alai or The Wing of Akil'zon on Hard mode. These are account-wide achievements, so team up for efficiency.", x = 11 },
        [62158] = { e = 4, s = "c", h = { 222194 }, r = "Hard mode boss requires group coordination and RNG.", d = "Defeat Ranger Swiftglade or Lieutenant Blazewing on Hard mode to complete this section. Ensure you are in a valid zone for the quest.", x = 11 },
        [62159] = { e = 4, s = "c", h = { 222197 }, r = "Hard mode boss requires group coordination and RNG.", d = "Kill Petyoll the Razorleaf or Lamyne of the Undercroft on Hard mode. This is account-wide, so coordinate with friends to finish quickly.", x = 11 },
        [62160] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Defeat High Vindicator Vureem or Crusader Luxia Maxwell on Hard mode to earn this achievement. Ensure you are in a group capable of handling the mechanics before attempting it.", x = 11 },
        [62161] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Challenge Praetor Singularis or Consul Nebulor on Hard mode for your points. These bosses require coordinated effort, so find a reliable raid group first.", x = 11 },
        [62162] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Take down Executor Kaenius or Imperator Enigmalia on Hard mode. Be prepared for complex mechanics that demand precise timing and positioning.", x = 11 },
        [62163] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Defeat Knight-Errant Bloodshatter or Vylenna the Defector on Hard mode. This encounter can be tricky, so study their abilities beforehand.", x = 11 },
        [62164] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Kill Lost Theldrin or Neydra the Starving on Hard mode. These enemies are tough, so ensure your group has sufficient healing and damage output.", x = 11 },
        [62165] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Conquer Thornspeaker Edgath or Thorn-Witch Liset on Hard mode. Their nature suggests they may have unique mechanics requiring specific strategies.", x = 11 },
        [62166] = { e = 4, s = "s", r = "Hard mode boss fight requires group coordination.", d = "Defeat Grothoz, the Burning Shadow or Dengzag, the Darkened Blaze on Hard mode. These bosses likely involve elemental mechanics to watch out for.", x = 11 },
        [62167] = { e = 5, s = "s", r = "Nightmare mode adds significant difficulty and RNG.", d = "Challenge Magister Sunbreaker or Magistrix Emberlash on Nightmare mode. This difficulty level requires a well-coordinated team with strong support capabilities.", x = 11 },
        [62168] = { e = 5, s = "s", r = "Nightmare mode adds significant difficulty and RNG.", d = "Defeat Senior Tinker Ozwold or L-N-0R the Recycler on Nightmare mode. Expect complex mechanics and high damage output from these inventors.", x = 11 },
        [62169] = { e = 5, s = "s", r = "Nightmare mode adds significant difficulty and RNG.", d = "Take down Mordril Shadowfell or Deliah Gloomsong on Nightmare mode. Their abilities may involve shadow magic, requiring careful avoidance strategies.", x = 11 },
        [62173] = { e = 5, s = "s", r = "Nightmare mode adds significant difficulty and RNG.", d = "Defeat Phaseblade Talasha or Nexus-Edge Hadim on Nightmare mode. These ethereal assassins likely have fast-paced mechanics demanding quick reactions.", x = 11 },
        [62174] = { e = 5, s = "s", r = "Nightmare mode adds significant difficulty and RNG.", d = "Challenge Jo'zolo the Breaker or Zadu, Fist of Nalorakk on Nightmare mode. Prepare for intense combat that tests your group's resilience and skill.", x = 11 },
        [62175] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat either The Talon of Jan'alai or The Wing of Akil'zon on Nightmare mode. These are account-wide achievements in the Prey raid, so coordinate with your group to ensure one boss is killed on Nightmare difficulty.", x = 11 },
        [62176] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Kill Ranger Swiftglade or Lieutenant Blazewing on Nightmare mode within the Prey raid. This is account-wide, so any character in your guild can contribute to completing this requirement once the condition is met.", x = 11 },
        [62177] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat Petyoll the Razorleaf or Lamyne of the Undercroft on Nightmare mode. Ensure you are running the Prey raid with a group capable of handling Nightmare difficulty to secure this account-wide credit.", x = 11 },
        [62178] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat High Vindicator Vureem or Crusader Luxia Maxwell on Nightmare mode. This requires running the Prey raid; make sure your group is prepared for the increased difficulty before attempting these bosses.", x = 11 },
        [62179] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Kill Praetor Singularis or Consul Nebulor on Nightmare mode in the Prey raid. Coordinate with your team to focus on one of these targets first to efficiently earn this account-wide achievement.", x = 11 },
        [62180] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat Executor Kaenius or Imperator Enigmalia on Nightmare mode. These are high-difficulty encounters in the Prey raid, so ensure your group composition is optimized for Nightmare before starting.", x = 11 },
        [62181] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat Knight-Errant Bloodshatter or Vylenna the Defector on Nightmare mode. This is account-wide, so once one character defeats either boss on Nightmare, all characters in your account will receive credit.", x = 11 },
        [62182] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Kill Lost Theldrin or Neydra the Starving on Nightmare mode. Run the Prey raid with a capable group to handle the Nightmare difficulty and secure this account-wide achievement quickly.", x = 11 },
        [62183] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat Thornspeaker Edgath or Thorn-Witch Liset on Nightmare mode. Focus your group's efforts on one of these two bosses in the Prey raid to complete this account-wide task efficiently.", x = 11 },
        [62184] = { e = 4, s = "s", r = "Nightmare mode raid boss requires group and RNG.", d = "Defeat Grothoz, the Burning Shadow or Dengzag, the Darkened Blaze on Nightmare mode. These are specific encounters in the Prey raid; ensure your group is ready for Nightmare difficulty before engaging.", x = 11 },
        [62185] = { e = 3, s = "g", r = "Collecting scattered items across a zone.", d = "Discover all twelve painter's easels located outdoors in Eversong Woods. Explore the zone thoroughly to find these hidden objects, as missing any will prevent you from earning this exploration achievement permanently.", x = 11 },
        [62186] = { e = 3, s = "c", h = { 222170 }, r = "Summoning rare spawn is the hardest step.", d = "Invite representatives from all four factions to Saltheril's Haven in Eversong Woods. You must physically invite each faction group to the haven; ensure you have access to the NPC who handles invitations for every faction.", x = 11 },
        [62187] = { e = 4, s = "c", r = "Requires finding and sampling 12 specific drinks.", d = "Visit Grand Magister Rommath in Eversong Woods to sample all listed drinks, which are account-wide and time-gated until level 12. Check your inventory for the specific drink items required before starting to ensure you have access to every option.", x = 11 },
        [62188] = { e = 3, s = "c", r = "Requires locating 5 specific NPCs near world trees.", d = "Locate each Haranir NPC near their respective world trees in Eversong Woods to listen to their stories. This is account-wide and requires finding specific NPCs, so verify you have spoken to all five listed individuals before claiming the achievement.", x = 11 },
        [62190] = { e = 4, s = "c", r = "Requires maxing reputation with 4 factions in Eversong.", d = "Grind reputation with all four Silvermoon Court factions in Eversong Woods until reaching maximum rank for each. Note that this is time-gated until level 12 and rewards a mount upon completion of all factions.", x = 11 },
        [62191] = { e = 3, s = "s", r = "Completing a specific questline takes a few hours.", d = "Complete the entire 'The Light's Summons' questline starting from the initial summoning event. Ensure you finish every step in the chain, as missing any part will prevent unlocking this account-wide achievement.", x = 11 },
        [62192] = { e = 4, s = "c", r = "Requires grinding renown to level 20 with 4 factions.", d = "Earn maximum renown with each of the four listed factions by completing daily quests and world events. This is account-wide and requires consistent engagement over time to reach the high renown thresholds for all groups.", x = 11 },
        [62193] = { e = 5, s = "c", r = "Requires defeating 8 dungeons as a damage dealer on Mythic.", d = "Queue for every Midnight dungeon as a damage dealer on Mythic or Mythic Keystone difficulty. You must defeat each dungeon once in this role, so switch classes if needed to meet the requirement.", x = 11 },
        [62194] = { e = 5, s = "c", r = "Requires defeating 8 dungeons as a healer on Mythic.", d = "Queue for every Midnight dungeon as a healer on Mythic or Mythic Keystone difficulty. Ensure you are designated as the healer by your group before entering each dungeon to track progress correctly.", x = 11 },
        [62195] = { e = 5, s = "c", r = "Requires defeating 8 dungeons as a tank on Mythic.", d = "Queue for every Midnight dungeon as a tank on Mythic or Mythic Keystone difficulty. You must be assigned the tank role in each instance, so bring appropriate gear and abilities to secure the title.", x = 11 },
        [62196] = { e = 5, s = "c", r = "Requires clearing all 8 dungeons in every role.", d = "Complete all Midnight dungeons once as a tank, healer, and damage dealer, which may require switching classes between runs. This is account-wide and requires defeating every dungeon in each role before claiming the achievement.", x = 11 },
        [62199] = { e = 3, s = "s", r = "Finding and joining a specific NPC takes some time.", d = "Find Chu'ke the possessed doll in Zul'Aman and join it to complete this exploration achievement. Ensure you have reached level 12 and are in the correct zone, as this is time-gated until then.", x = 11 },
        [62200] = { e = 3, s = "c", r = "Requires collecting 6 scattered items in Zul'Aman.", d = "Collect all lost gnome writings scattered throughout Zul'Aman by finding each specific item listed. This is account-wide and requires thorough exploration of the zone to locate every note or diary.", x = 11 },
        [62201] = { e = 3, s = "c", r = "Requires interacting with 5 specific frogs.", d = "Use a kiss ability on each princess frog NPC in Zul'Aman to complete this quirky achievement. Verify you have interacted with all five frogs, as missing one will prevent completion until revisited later.", x = 11 },
        [62202] = { e = 1, s = "s", r = "One-time event with no grind.", d = "Go to Zul'Aman and assist the Spiritpaw Runner immediately after reaching level 12, as this is a time-gated achievement tied to the Collector questline. Ensure you complete the run without dying to secure the points.", x = 11 },
        [62206] = { e = 4, s = "c", r = "Requires multiple roles and specific delves.", d = "Unlock Midnight Delver II first, then queue for Tier 11+ delves while playing each role with lives remaining. This requires account-wide progress and cannot be rushed by skipping roles.", x = 11 },
        [62207] = { e = 1, s = "g", r = "Very low count of fish to catch.", d = "Start Abyss Anglers dives early to catch at least three fish; this unlocks the Reinforced Joints upgrade needed for harder challenges. No special group is required, but efficiency helps.", x = 11 },
        [62208] = { e = 3, s = "g", r = "Requires upgrade and high fish count in one dive.", d = "Catch 25 fish in a single dive while having purchased the Reinforced Joints upgrade from Depthdiver Jeju. Plan your dives carefully to maximize catch count before running out of breath.", x = 11 },
        [62209] = { e = 4, s = "g", r = "High volume of fish required over time.", d = "Accumulate 500 total fish and buy the Depth Grease upgrade, which is mandatory for this milestone. This achievement builds on previous catches, so track your progress across multiple sessions.", x = 11 },
        [62210] = { e = 3, s = "c", r = "Collecting multiple rare creatures in dives.", d = "Collect all listed creatures during dives after acquiring Depth Grease; missing any species will delay completion. Use upgraded gear to increase spawn rates and catch efficiency.", x = 11 },
        [62211] = { e = 4, s = "c", r = "More creatures plus upgrade requirement.", d = "Gather the next set of creatures while owning Fathom-Tested Tank, which requires prior collection steps. Continue diving until you have caught every target listed in the achievement info.", x = 11 },
        [62212] = { e = 5, s = "c", r = "Many rare creatures and upgrade needed.", d = "Finish collecting the final group of creatures and purchase Nalorakk's Breath Tank to complete this tier. Ensure you do not miss any rare spawns during your dives.", x = 11 },
        [62213] = { e = 4, s = "g", r = "Requires finding many relics in dives.", d = "Explore dive zones thoroughly to find 50 Sunken Relics; these appear randomly so frequent diving increases your chances. No upgrades are strictly needed, but better gear helps survival.", x = 11 },
        [62214] = { e = 4, s = "g", r = "Requires finding rare ancient relics.", d = "Find 10 Ancient Relics and buy the Triple-Thread Net upgrade from Depthdiver Jeju. These relics are rarer than Sunken ones, so patience and extensive exploration are key.", x = 11 },
        [62217] = { e = 5, s = "c", r = "Depends on completing many other achievements.", d = "Complete all listed Abyss Anglers achievements before purchasing Idol of the Depths; this is a summary achievement requiring every sub-task to be finished first.", x = 11 },
        [62218] = { e = 1, s = "s", r = "Simple event with no grind.", d = "Intentionally run out of breath during any dive to earn these points. You can do this early on without upgrades, making it one of the easiest achievements to start.", x = 11 },
        [62219] = { e = 3, s = "g", r = "Requires multiple failed dives to trigger.", d = "Start the Abyss Anglers questline and dive deep to trigger a trench swim. Accept that getting forcibly removed is random; just keep diving until it happens.", x = 11 },
        [62220] = { e = 3, s = "g", r = "Needs timed ability use over many dives.", d = "During dives, monitor your breath bar closely. Use the Surface! ability immediately when it drops below ten seconds to complete this objective.", x = 11 },
        [62221] = { e = 3, s = "g", r = "Requires swimming through 25 fish schools.", d = "Swim through schools of fish while diving to count them toward your total. You must reach twenty-five in a single dive session without surfacing.", x = 11 },
        [62222] = { e = 3, s = "g", r = "Needs Brakpuffer knockbacks over many dives.", d = "Encounter Brakpuffers naturally during dives and let them knock you away. This is an encounter-based event, so patience while exploring the trench is key.", x = 11 },
        [62223] = { e = 4, s = "g", r = "Grinding 50 orders takes several hours.", d = "Purchase Midnight Alchemy Crafting Orders and complete fifty of them. These are account-wide, so any character can contribute to the total count.", x = 11 },
        [62232] = { e = 4, s = "g", r = "Grinding 50 blacksmithing orders takes time.", d = "Buy Blacksmithing orders from the vendor and craft items for others. Ensure you have enough materials before accepting each order to avoid delays.", x = 11 },
        [62233] = { e = 3, s = "c", r = "Weekly quests reset; grind dominates effort.", d = "Complete four weekly quests related to Midnight Enchanting supplies. Check the quest log regularly as these reset on a weekly schedule.", x = 11 },
        [62234] = { e = 4, s = "g", r = "Grinding 50 engineering orders takes time.", d = "Acquire Engineering crafting orders and fulfill fifty of them. Like other professions, this is account-wide, allowing multiple characters to help progress.", x = 11 },
        [62235] = { e = 4, s = "g", r = "Grinding 50 inscription orders takes time.", d = "Get Inscription crafting orders and complete fifty instances. Manage your ink and reagents carefully since these orders require specific materials.", x = 11 },
        [62236] = { e = 4, s = "g", r = "Grinding 50 jewelcrafting orders takes time.", d = "Purchase Jewelcrafting orders and craft the required items. This achievement is account-wide, so coordinate with friends if you lack a dedicated jeweler.", x = 11 },
        [62237] = { e = 4, s = "g", r = "Grinding 50 leatherworking orders takes time.", d = "Buy Leatherworking crafting orders and complete fifty of them. Gather hides and thread beforehand to ensure smooth completion of each order.", x = 11 },
        [62238] = { e = 4, s = "g", r = "Grinding 50 tailoring orders takes time.", d = "Acquire Tailoring crafting orders and fulfill fifty requests. Keep an eye on fabric availability as running out will halt progress temporarily.", x = 11 },
        [62239] = { e = 4, s = "c", h = { 222857 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Complete the prerequisite Midnight Alchemy achievements first. Then perform alchemy while in a dark environment to earn the title.", x = 11 },
        [62240] = { e = 4, s = "c", h = { 222860 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Finish all required Midnight Blacksmithing tasks before starting this one. Ensure you are crafting items at night for progress.", x = 11 },
        [62241] = { e = 4, s = "c", h = { 222863 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Unlock the prerequisite Enchanting achievements first. Then enchant gear during nighttime hours to complete the requirement.", x = 11 },
        [62242] = { e = 4, s = "c", h = { 222866 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Complete the Midnight Engineering prerequisites before attempting this. Craft engineering items while it is dark outside.", x = 11 },
        [62243] = { e = 4, s = "c", h = { 222869 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Finish all required Midnight Inscription achievements first. Inscribe glyphs or scrolls only when the game time is night.", x = 11 },
        [62244] = { e = 4, s = "c", h = { 222872 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Complete the prerequisite Jewelcrafting achievements before starting. Create jewelry while in a dark environment to progress.", x = 11 },
        [62245] = { e = 4, s = "c", h = { 222875 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Unlock the Leatherworking prerequisites first. Process leather goods during nighttime hours to earn the title.", x = 11 },
        [62246] = { e = 4, s = "c", h = { 222878 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Finish all required Midnight Tailoring achievements before starting. Tailor items while it is dark outside for credit.", x = 11 },
        [62247] = { e = 4, s = "g", r = "Requires completing four specific weekly quests each week.", d = "This requires completing four specific weekly quests found in the Herbalism section. Check your quest log regularly as these reset weekly.", x = 11 },
        [62248] = { e = 4, s = "g", r = "Requires completing four specific weekly quests each week.", d = "Locate and complete the four weekly Mining quests listed in the achievement info. These are time-gated and reset every week.", x = 11 },
        [62249] = { e = 4, s = "g", r = "Requires completing four specific weekly quests each week.", d = "Find the four required Skinning weekly quests and finish them promptly. Do not delay as they expire after one week.", x = 11 },
        [62250] = { e = 4, s = "c", h = { 222916 }, r = "Requires grinding rare midnight drops and weekly quests.", d = "Complete Herbalism at Midnight first, then finish Herbalism-on-Demand. Finally, claim this title by proving dedication to the craft.", x = 11 },
        [62251] = { e = 4, s = "c", h = { 222919, 222920 }, r = "Requires rare midnight spawns and specific mining.", d = "Unlock the Mining at Midnight and Mining-on-Demand achievements first to unlock this title. Farm ore nodes during specific event windows since these are time-gated content.", x = 11 },
        [62252] = { e = 4, s = "c", h = { 222922, 222923 }, r = "Requires rare midnight spawns and specific skinning.", d = "Complete Skinning at Midnight and Skinning-on-Demand prerequisites before claiming your title. Focus on skinning beasts during active Midnight events as this is time-limited.", x = 11 },
        [62256] = { e = 5, s = "c", h = { 223006, 223007 }, r = "Contains heavy RNG kills and rare loot drops.", d = "Start with the Z4 Meta Achievement requirement, then hunt for The Ultimate Predator and other Voidstorm tasks. Note that some objectives may be rare drops or require specific encounter conditions.", x = 11 },
        [62260] = { e = 4, s = "c", h = { 223022, 223029 }, r = "Requires rare spawns and specific event completion.", d = "Begin by helping the Hara'ti faction to unlock sub-achievements like Treasures of Harandar. Be aware that certain goals involve collecting items from limited-time events in Harandar.", x = 11 },
        [62261] = { e = 4, s = "c", h = { 223078, 223087 }, r = "Contains heavy RNG kills and rare loot drops.", d = "Unlock the Eversong Woods meta achievement first, then complete tasks like Runestone Rush and The Party Must Go On. Some objectives require finding specific rare spawns or completing event quests quickly.", x = 11 },
        [62262] = { e = 3, s = "g", r = "Requires farming reputation over many days.", d = "Grind reputation with Silvermoon Court through daily quests and world events until reaching rank 20. This is purely a time-gated grind with no shortcuts available.", x = 11 },
        [62263] = { e = 3, s = "g", r = "Requires farming reputation over many days.", d = "Farm Amani Tribe reputation via relevant zones and faction-specific activities until you hit rank 20. Expect this to take significant time depending on your current level and gear.", x = 11 },
        [62264] = { e = 3, s = "g", r = "Requires farming reputation over many days.", d = "Earn Hara'ti reputation by completing their specific quests and world events in the appropriate zone. This is a straightforward but lengthy grind requiring consistent daily participation.", x = 11 },
        [62265] = { e = 3, s = "g", r = "Requires farming reputation over many days.", d = "Reach rank 20 with The Singularity faction through targeted quests and activities. Ensure you are active during any special events that offer large reputation bonuses to speed up progress.", x = 11 },
        [62266] = { e = 4, s = "g", r = "10 million items requires significant time grinding.", d = "Accumulate 10 million Abundance by farming nodes during Abundance events, which occur on a timer. You must participate in these limited-time windows to make meaningful progress toward the goal.", x = 11 },
        [62267] = { e = 3, s = "s", r = "Single encounter with a rare spawn.", d = "Trigger Filo, Loa of Childhood's attack event to complete this objective. This is likely a rare drop or specific encounter that may require waiting for the right conditions.", x = 11 },
        [62268] = { e = 4, s = "s", r = "Requires waiting for specific rare event node.", d = "Locate and harvest an Artisan Node during an Abundance event to earn these points. These nodes only appear during specific timed events, so check your calendar for availability.", x = 11 },
        [62269] = { e = 1, s = "c", r = "Talk to NPCs in one zone; trivial.", d = "Unlock all Loa at the Altar of Blessings in Amani'Zar Village, starting with Kulzi and ending with Oe. This is account-wide and requires no specific order, but ensure you visit the altar after unlocking each spirit to claim the points.", x = 11 },
        [62270] = { e = 1, s = "s", r = "One NPC interaction; trivial.", d = "Speak to Du'gal the Alter Keeper in Amani'Zar Village to complete the Blessings of the Loa questline. Finish this early as it is account-wide and unlocks essential progression for other Midnight achievements.", x = 11 },
        [62271] = { e = 3, s = "g", r = "Catch 100 fish; moderate grind.", d = "Participate in Abyss Anglers dives until you catch 100 fish total across all zones. This is account-wide, so coordinate with friends to speed up the grind if needed.", x = 11 },
        [62272] = { e = 3, s = "g", r = "Earn points via dives; moderate grind.", d = "Accumulate 250,000 points in Abyss Anglers dives by completing daily challenges and catching rare fish. Track your progress carefully since this is a cumulative total that does not reset.", x = 11 },
        [62282] = { e = 4, s = "s", r = "Defeat raid boss; hard dungeon run.", d = "Defeat Zul'jan in the Altar of Fangs dungeon to earn these points. Ensure you are on the correct difficulty tier before starting, as lower difficulties do not count for higher-tier achievements.", x = 11 },
        [62283] = { e = 4, s = "s", r = "Heroic raid boss; harder dungeon run.", d = "Clear the Altar of Fangs dungeon on Heroic difficulty or higher to defeat Zul'jan and earn points. Do not start this until you have unlocked the Heroic version of the dungeon.", x = 11 },
        [62284] = { e = 5, s = "s", r = "Mythic raid boss; very hard difficulty.", d = "Complete the Altar of Fangs dungeon on Mythic or Mythic Keystone difficulty to defeat Zul'jan. This is the highest tier, so ensure your group is prepared for significant challenges.", x = 11 },
        [62288] = { e = 3, s = "g", r = "Place 5 telescopes; moderate exploration.", d = "Place telescopes on the five tallest peaks in Eversong Woods to complete this exploration achievement. Use a map or guide to locate the specific high points quickly.", x = 11 },
        [62289] = { e = 3, s = "g", r = "Place 5 telescopes; moderate exploration.", d = "Install telescopes on the five highest peaks within Zul'Aman to finish this task. Check your surroundings for elevated terrain features that match the telescope placement requirements.", x = 11 },
        [62290] = { e = 3, s = "g", r = "Place 5 telescopes; moderate exploration.", d = "Set up telescopes on the top five peaks in Harandar to claim these points. Explore the zone thoroughly to identify all valid locations for telescope installation.", x = 11 },
        [62291] = { e = 3, s = "g", r = "Place 5 telescopes; moderate exploration.", d = "Place telescopes on the five highest peaks in Voidstorm to complete this achievement. Be mindful of the zone's unique layout and ensure you visit each peak correctly.", x = 11 },
        [62297] = { e = 4, s = "c", h = { 223238 }, r = "Complete storylines; hardest is raid campaign.", d = "Complete all listed storylines in Zul'Aman and the Coiled Isle, including Legacy of the Amani and The Call of the Void. This is account-wide, so prioritize these quests early to avoid missing content later.", x = 11 },
        [62324] = { e = 3, s = "c", r = "Requires completing multiple distinct bonus events.", d = "Start by completing an Abundance event and ensure you earn points in every single score category. Since this is account-wide, coordinate with friends to cover all categories if needed.", x = 11 },
        [62325] = { e = 3, s = "c", r = "Requires triggering specific bonuses in four locations.", d = "Visit the four listed locations (Wath'anan Crypts, Loaknit Den, Floaret Grotto, Voidburrow) and trigger the Treasure Dundun Bonus in each one. This is account-wide, so bring a group to handle all zones efficiently.", x = 11 },
        [62326] = { e = 3, s = "c", r = "Requires triggering specific bonuses in four locations.", d = "Go to the same four locations as the previous achievement and find the Golden Glow creatures to trigger the bonus in each area. Do not miss any zone while hunting for these specific targets.", x = 11 },
        [62329] = { e = 3, s = "c", r = "Requires triggering specific bonuses in four locations.", d = "Trigger the Runaways Bonus in all four Abundance locations by interacting with the specific runaways present there. Ensure you visit every location listed in the info field to complete this account-wide goal.", x = 11 },
        [62330] = { e = 3, s = "c", r = "Requires triggering specific bonuses in four locations.", d = "Locate and trigger the Gigantic Harvest Bonus in each of the four designated Abundance zones. These events are time-limited, so check back frequently if you miss the initial spawn.", x = 11 },
        [62331] = { e = 3, s = "c", r = "Requires triggering specific bonuses in four locations.", d = "Find the material rain events in all four locations to trigger the Rain of Abundance bonus. Be patient as these drops may require waiting for the correct weather or event window.", x = 11 },
        [62332] = { e = 4, s = "c", r = "Meta achievement requiring completion of all sub-achievements.", d = "Complete all five prerequisite Abundance achievements listed in the info field before this meta achievement unlocks. Ensure you have earned points in every category and triggered all bonuses first.", x = 11 },
        [62333] = { e = 3, s = "g", r = "Requires harvesting a large amount of materials.", d = "Focus on harvesting materials during Abundance events until your total score reaches at least 10,000 in the Materials Harvested category. This requires significant grinding but is account-wide.", x = 11 },
        [62336] = { e = 3, s = "g", r = "Requires contributing a large amount of materials.", d = "Deposit harvested materials into the appropriate containers during events to reach the 10,000 point threshold for the Materials Contributed category. Coordinate with your group to maximize deposit efficiency.", x = 11 },
        [62337] = { e = 3, s = "g", r = "Requires harvesting basic nodes to reach score threshold.", d = "Prioritize gathering from Basic Nodes during Abundance events until you accumulate 10,000 points in that specific category. Avoid focusing too much on Artisan nodes if you need Basic points.", x = 11 },
        [62338] = { e = 3, s = "g", r = "Requires harvesting artisan nodes to reach score threshold.", d = "Target Artisan Nodes specifically during events to reach the 10,000 point requirement for this category. Do not confuse these with Basic Nodes as they count toward different achievements.", x = 11 },
        [62339] = { e = 3, s = "g", r = "Requires participating in bonus events to reach score.", d = "Participate in Bonus Events like Treasure Dunduns or Golden Glows to rack up points toward the 10,000 threshold. These events often yield higher scores than standard harvesting.", x = 11 },
        [62340] = { e = 4, s = "g", r = "Requires grinding specific points in a timed event.", d = "Focus your Abundance event runs on earning Large Orbs by completing high-yield tasks. Aim for a score of at least 10,000 in this specific category before the event ends to secure the achievement.", x = 11 },
        [62341] = { e = 5, s = "c", h = { 223308, 223309, 223310 }, r = "Meta achievement; some sub-achievements require heavy RNG or raids.", d = "Complete all individual Abundance sub-achievements listed in the requirements. This meta achievement unlocks only after you have finished every single one of the smaller scoring goals.", x = 11 },
        [62342] = { e = 5, s = "g", r = "Requires catching rare Mythic creatures multiple times.", d = "Participate in Abyss Anglers dives and specifically target Mythic creatures to catch them three times total. Ensure you are diving in areas where Mythic fish appear frequently to meet the count efficiently.", x = 11 },
        [62343] = { e = 5, s = "g", r = "Requires catching rare Mythic creatures six times.", d = "Catch Mythic creatures from Abyss Anglers dives six times in total. This requires significantly more time than the previous tier, so plan multiple diving sessions to reach the higher threshold.", x = 11 },
        [62351] = { e = 5, s = "c", h = { 223407, 223408 }, r = "Includes difficult fishing and trap-related sub-achievements.", d = "Complete all listed sub-achievements related to hunting and fishing activities to unlock this title. Verify that every specific requirement under the Prey category is finished before claiming the reward.", x = 11 },
        [62352] = { e = 4, s = "s", r = "Requires specific raid encounter or event participation.", d = "Enter The Voidspire or March on Quel'Danas and allow yourself to be consumed by the Devouring Host. This is a specific encounter outcome, so ensure you survive long enough to trigger the event.", x = 11 },
        [62357] = { e = 3, s = "g", r = "Requires harvesting a large amount of lumber in one zone.", d = "Harvest Ironwood Lumber until you reach a total of 250 units. Use your lumberjack profession or gatherer tools to speed up collection in relevant zones.", x = 11 },
        [62358] = { e = 3, s = "g", r = "Requires harvesting a large amount of lumber in Outland.", d = "Gather Olemba Lumber from Burning Crusade zones until you have collected 250 units. Focus your gathering efforts on areas where this specific wood type spawns abundantly.", x = 11 },
        [62359] = { e = 3, s = "g", r = "Requires harvesting a large amount of lumber in Northrend.", d = "Collect Coldwind Lumber in Wrath of the Lich King zones to reach the 250 unit goal. Utilize efficient gathering methods to minimize time spent in these specific regions.", x = 11 },
        [62360] = { e = 3, s = "g", r = "Requires harvesting a large amount of lumber in Cataclysm zones.", d = "Harvest Ashwood Lumber from Cataclysm zones until you have accumulated 250 units. Check zone maps for high-density Ashwood locations to complete this requirement quickly.", x = 11 },
        [62361] = { e = 3, s = "g", r = "Requires harvesting a large amount of bamboo in Pandaria.", d = "Gather Bamboo Lumber in Mists of Pandaria zones to reach the required 250 count. Bamboo grows rapidly in these areas, making it a straightforward farming task if you know the locations.", x = 11 },
        [62362] = { e = 3, s = "g", r = "Requires harvesting a large amount of lumber in Draenor.", d = "Harvest Shadowmoon Lumber from Warlords of Draenor zones until you have collected 250 units. Focus on the specific zones where this lumber type is available to avoid wasting time elsewhere.", x = 11 },
        [62363] = { e = 2, s = "g", r = "Grinding a specific resource in one zone.", d = "Harvest Fel-Touched Lumber in Legion zones until you have 250. This is account-wide and unlocks a mounted harvesting tool for that expansion.", x = 11 },
        [62364] = { e = 2, s = "g", r = "Grinding a specific resource in one zone.", d = "Gather Darkpine Lumber in Battle for Azeroth zones to reach the 250 count. Use your account-wide progress to complete this quickly.", x = 11 },
        [62365] = { e = 2, s = "g", r = "Grinding a specific resource in one zone.", d = "Collect Arden Lumber from Shadowlands zones until you hit 250. This unlocks the mounted harvesting ability specific to that expansion.", x = 11 },
        [62366] = { e = 2, s = "g", r = "Grinding a specific resource in one zone.", d = "Gather Dragonpine Lumber in Dragonflight zones to finish this part of the set. Ensure you are in the correct zone for drops.", x = 11 },
        [62369] = { e = 2, s = "g", r = "Grinding a specific resource in one zone.", d = "Harvest Dornic Fir Lumber in War Within zones to reach the goal. This is account-wide and grants a mounted harvesting tool.", x = 11 },
        [62370] = { e = 2, s = "g", r = "Grinding a specific resource in one zone.", d = "Collect Thalassian Lumber in Midnight zones until you have 250. Focus on these specific zones as drops are location-based.", x = 11 },
        [62371] = { e = 4, s = "g", r = "Requires farming many coupons over time.", d = "Start by collecting Community Coupons from vendors or events to reach 50. This is the first step in a long chain of housing achievements.", x = 11 },
        [62373] = { e = 4, s = "g", r = "Requires farming many coupons over time.", d = "Continue gathering Community Coupons to reach 250 total, as this requires completing the previous achievement first. Keep an eye on your coupon count.", x = 11 },
        [62374] = { e = 4, s = "g", r = "Requires farming many coupons over time.", d = "Gather more coupons to hit 500, following the chain from Coupon Collector. This is account-wide so progress carries over easily.", x = 11 },
        [62375] = { e = 4, s = "g", r = "Requires farming many coupons over time.", d = "Collect 1000 Community Coupons by continuing your daily or weekly coupon runs. Do not stop until you reach this milestone.", x = 11 },
        [62376] = { e = 4, s = "g", r = "Requires farming many coupons over time.", d = "Reach 2500 coupons by maintaining a steady collection pace. This is account-wide and builds directly on the previous tier.", x = 11 },
        [62377] = { e = 4, s = "g", r = "Requires farming many coupons over time.", d = "Finish the chain by collecting 5000 Community Coupons. Ensure you have completed all prior steps before attempting this final goal.", x = 11 },
        [62378] = { e = 1, s = "g", r = "Collecting coupons is a simple grind.", d = "Start by completing the prerequisite 'A Fist Full of Coupons' to unlock collection. Farm community events or specific vendors until you hit 10,000 coupons, noting this is account-wide so play with friends if needed.", x = 11 },
        [62383] = { e = 4, s = "c", h = { 223524, 223528, 223532 }, r = "Defeating many prey; some are rare or hard.", d = "Locate and defeat every listed Prey target on any difficulty, as missing one makes the achievement missable. Check your map for all icons and ensure you clear both normal and nightmare variants if applicable to the list.", x = 11 },
        [62385] = { e = 3, s = "s", r = "Unlocking a console requires specific steps.", d = "Progress through Voidstorm content until you fully unlock the Research Console in that zone. This is a time-gated milestone tied to specific story beats, so do not delay exploring the area after unlocking it.", x = 11 },
        [62386] = { e = 4, s = "c", h = { 223796, 223797, 223798 }, r = "Completing multiple Midnight raid achievements.", d = "Complete all four sub-achievements listed under this goal to rally against Xal'atath. Ensure you finish each individual task before claiming the mount reward, as the main achievement tracks overall completion.", x = 11 },
        [62403] = { e = 4, s = "s", r = "Requires specific nightmare hunt and debuff.", d = "Enter a Prey Hunt in Nightmare Mode and intentionally take damage from Lord Viscera's Cat Scratch debuff. You must complete the hunt while suffering this specific status effect to earn the points.", x = 11 },
        [62406] = { e = 4, s = "g", r = "Grinding memories for a raid achievement.", d = "Return exactly 12 Memories of Alleria to L'ura on March during the event window. Defeat Midnight Falls only after returning these items on Normal difficulty or higher to satisfy the criteria.", x = 11 },
        [62450] = { e = 1, s = "s", r = "Tier 1 ritual site is trivial.", d = "Begin by completing any Tier 1 Ritual Site to unlock this achievement. This is the first step in a chain, so prioritize finding and finishing basic ritual locations before advancing.", x = 11 },
        [62451] = { e = 2, s = "s", r = "Tier 2 ritual site is easy.", d = "Unlock Tier 2 Ritual Sites only after finishing the Tier 1 prerequisite. Complete any available Tier 2 site to progress, ensuring you have the previous tier unlocked first.", x = 11 },
        [62452] = { e = 3, s = "s", r = "Tier 3 ritual site takes moderate time.", d = "Finish a Tier 3 Ritual Site once you have completed the Tier 2 requirement. This continues the progression chain, so verify your ritual level before attempting higher tiers.", x = 11 },
        [62453] = { e = 3, s = "s", r = "Tier 4 ritual site is moderate effort.", d = "Complete a Tier 4 Ritual Site after unlocking Tier 3. Follow the sequential order of these achievements to avoid errors, as each tier gates the next.", x = 11 },
        [62454] = { e = 3, s = "s", r = "Tier 5 ritual site is moderate effort.", d = "Unlock and complete a Tier 5 Ritual Site only after finishing Tier 4. This step advances you further in the ritual chain, so ensure prior tiers are fully done.", x = 11 },
        [62460] = { e = 4, s = "c", h = { 224563, 224564, 224565 }, r = "Completing many pet battle achievements.", d = "Start by completing the base 'Family Battler of Outland' achievement first. Then systematically work through each sub-achievement listed to collect all required pet battle titles for the final reward.", x = 11 },
        [62461] = { e = 3, s = "c", r = "Requires collecting many specific pet battle achievements.", d = "Complete all individual Battler achievements first to unlock the final title. Ensure you have access to every required pet type before starting, as some are rare or missable. This is account-wide, so coordinate with friends if you lack specific pets.", x = 11 },
        [62466] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Gather a full team of level 25 Aquatic pets before attempting the Outland trainer battles. Visit each listed NPC in order to track progress and avoid missing any trainers. Do not rush; some encounters may require specific pet types to succeed.", x = 11 },
        [62467] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Collect all necessary Beast-type pets at level 25 prior to engaging Outland trainers. Test your team composition early to ensure you can defeat every trainer without failure. This achievement is account-wide, so share progress with others if needed.", x = 11 },
        [62468] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Assemble a complete set of Critter pets at level 25 before starting the Outland sequence. Check each NPC location carefully, as missing one trainer will delay completion. Some trainers may be time-gated or require specific quest flags to access.", x = 11 },
        [62469] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Secure all Dragonkin pets at level 25 and verify your team can handle Outland trainers. Progress through the list of NPCs systematically to avoid skipping any required battles. Be prepared for rare drops that might be needed for your pet roster.", x = 11 },
        [62470] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Build a full Elemental pet team at level 25 before tackling the Outland trainers. Ensure you have visited all listed NPCs and completed their respective battles. Some encounters may fail if your pet types are insufficient, so double-check your lineup first.", x = 11 },
        [62471] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Gather Flying pets at level 25 and test them against Outland trainers before proceeding. Visit each NPC in the provided list to confirm completion status. Avoid rushing through battles, as missing a trainer will require restarting the entire sequence.", x = 11 },
        [62472] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Collect Humanoid pets at level 25 and prepare for the Outland trainer challenges. Check off each NPC as you complete their battle to ensure no progress is lost. Some trainers may have unique mechanics that require specific pet strategies.", x = 11 },
        [62473] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Assemble a Magic pet team at level 25 and begin defeating Outland trainers systematically. Verify your progress after each encounter to avoid missing any required battles. Rare drops during these fights might be essential for completing other achievements.", x = 11 },
        [62474] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Gather Mechanical pets at level 25 before attempting the Outland trainer battles. Visit each NPC in order and ensure you complete every encounter without failure. Some trainers may require specific pet types to succeed, so plan your team accordingly.", x = 11 },
        [62475] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Collect Undead pets at level 25 and start the Outland trainer sequence. Track your progress carefully to avoid missing any NPCs or battles. This achievement is account-wide, so coordinate with friends if you lack certain pet types.", x = 11 },
        [62476] = { e = 3, s = "g", r = "Grinding trainers with specific pet types takes time.", d = "Build a full Aquatic pet team at level 25 before engaging Cataclysm trainers. Visit each listed NPC and complete their battles in order to avoid missing progress. Some encounters may be time-gated or require specific quest flags to access.", x = 11 },
        [62477] = { e = 3, s = "c", r = "Requires collecting specific pets and defeating trainers.", d = "Gather four level 25 Beast pets and defeat the specific Cataclysm trainers listed in the info. Ensure your team composition is correct before engaging each trainer to avoid wasting attempts.", x = 11 },
        [62478] = { e = 3, s = "c", r = "Requires collecting specific critter pets and defeating trainers.", d = "Collect four level 25 Critter pets and use them exclusively against the designated Cataclysm trainers. Verify pet types beforehand as this achievement requires a full team of that specific classification.", x = 11 },
        [62479] = { e = 3, s = "c", r = "Requires collecting specific dragonkin pets and defeating trainers.", d = "Acquire four level 25 Dragonkin pets to form your battle team for the required trainers. Confirm each pet's type matches the Dragonkin category before starting the sequence.", x = 11 },
        [62480] = { e = 3, s = "c", r = "Requires collecting specific elemental pets and defeating trainers.", d = "Find four level 25 Elemental pets and assemble a team consisting only of them. Defeat the listed Cataclysm trainers using this specific elemental composition to claim the points.", x = 11 },
        [62481] = { e = 3, s = "c", r = "Requires collecting specific flying pets and defeating trainers.", d = "Obtain four level 25 Flying pets and ensure your entire battle team consists of flyers. Engage the required trainers only after confirming all pets meet the flying requirement.", x = 11 },
        [62482] = { e = 3, s = "c", r = "Requires collecting specific humanoid pets and defeating trainers.", d = "Gather four level 25 Humanoid pets to create a valid team for the Cataclysm trainer battles. Double-check that every pet in your lineup is classified as Humanoid before fighting.", x = 11 },
        [62483] = { e = 3, s = "c", r = "Requires collecting specific magic pets and defeating trainers.", d = "Collect four level 25 Magic pets and use them as your sole team composition against the trainers. Verify the magic classification of each pet to ensure you meet the achievement criteria.", x = 11 },
        [62487] = { e = 3, s = "c", r = "Requires collecting specific mechanical pets and defeating trainers.", d = "Secure four level 25 Mechanical pets and build a team entirely from this type. Defeat the required trainers with this mechanical lineup to complete the Cataclysm battle challenge.", x = 11 },
        [62488] = { e = 3, s = "c", r = "Requires collecting specific undead pets and defeating trainers.", d = "Find four level 25 Undead pets and assemble a team where every member is undead. Proceed to defeat the listed trainers only after confirming your team meets this specific type requirement.", x = 11 },
        [62492] = { e = 3, s = "g", r = "Requires catching multiple wild pets in a zone.", d = "Travel to Coiled Isle and catch all eight wild pets listed in the info field. This is a collection achievement, so you must physically capture each unique pet shown.", x = 11 },
        [62493] = { e = 3, s = "s", r = "Single PvP match victory with no partial progress.", d = "Enter Slayer's Rise matches until you secure your first victory to unlock this point. Treat this as the initial step in a larger PvP progression chain.", x = 11 },
        [62494] = { e = 3, s = "g", r = "Requires winning 100 matches in a PvP mode.", d = "After unlocking the previous achievement, continue winning Slayer's Rise matches until you reach exactly one hundred total victories. This is a grind requiring consistent wins over time.", x = 11 },
        [62498] = { e = 1, s = "s", r = "First run of a new event type.", d = "Start by queuing for a Void Assault in Eversong immediately. Finish the strike or incursion to unlock the next tier. This is account-wide and requires no specific group composition.", x = 11 },
        [62499] = { e = 1, s = "s", r = "First run of a new event type.", d = "Queue for a Void Assault in Zul'Aman just like Eversong. Complete one run to claim the points. Remember this unlocks the chain for that zone specifically.", x = 11 },
        [62500] = { e = 3, s = "c", h = { 224818, 224819, 224827 }, r = "Requires visiting multiple neighborhoods.", d = "Visit Duskwood, Felwood, and Drustvar during Hallow's End events. Craft or collect candy in each neighborhood to finish all sub-requirements. Do this only when the seasonal event is active.", x = 11 },
        [62501] = { e = 2, s = "g", r = "Collecting 10 items is a short grind.", d = "Find ghost NPCs in any neighborhood during Hallow's End. Kill them and deposit the souls into the designated urns. You need ten total across all zones to finish.", x = 11 },
        [62502] = { e = 2, s = "g", r = "Using power-ups 3 times is quick.", d = "Join a Winter Veil tree defense activity with friends or a guild group. Use your power-up ability three times during the match. This is missable if you do not participate in the event.", x = 11 },
        [62506] = { e = 4, s = "s", r = "Requires Mythic difficulty and RNG.", d = "Participate in an Abyss Anglers dive and aim for Mythic difficulty creatures. Catch one specific target to earn the Pressurized Eyeglass reward. This is account-wide but requires active diving events.", x = 11 },
        [62507] = { e = 3, s = "g", r = "Grinding 5 runs after first completion.", d = "Complete five Void Strikes in Eversong after unlocking the base assault. These are cumulative and lead directly to the next tier. Queue frequently as strikes reset on a timer.", x = 11 },
        [62508] = { e = 4, s = "g", r = "Grinding 25 runs is a significant task.", d = "Finish twenty-five Void Strikes in Eversong to unlock the final tier. This requires significant time investment due to the high count. Ensure you have unlocked the previous Smasher achievement first.", x = 11 },
        [62509] = { e = 5, s = "g", r = "Grinding 50 runs is a long grind.", d = "Complete fifty Void Strikes in Eversong for the highest tier. This is a long-term goal requiring consistent queueing over many days. Do not stop until you hit the exact count needed.", x = 11 },
        [62510] = { e = 3, s = "g", r = "Grinding 5 runs after first completion.", d = "Complete five Void Strikes in Zul'Aman after unlocking the base assault. Follow the same progression as Eversong but in this specific zone. These counts are separate from Eversong progress.", x = 11 },
        [62511] = { e = 4, s = "g", r = "Grinding 25 runs is a significant task.", d = "Finish twenty-five Void Strikes in Zul'Aman to advance the chain. This is a grind similar to Eversong but tracks independently per zone. Plan your queue times around strike availability.", x = 11 },
        [62512] = { e = 5, s = "g", r = "Grinding 50 runs is a long grind.", d = "Complete fifty Void Strikes in Zul'Aman for the final tier. This requires substantial time commitment as it is a high-count objective. Unlock previous tiers before attempting this milestone.", x = 11 },
        [62513] = { e = 3, s = "g", r = "Grinding 100 accolades takes a few hours.", d = "Focus on completing Void Assaults and Ritual Sites to earn Field Accolades, as this is account-wide and requires active participation in these events. Prioritize high-density areas to reach the 100-point goal quickly without missing content gates.", x = 11 },
        [62514] = { e = 4, s = "c", r = "Requires controlling all five objectives simultaneously.", d = "Coordinate with your guild or group to secure all five key objectives during Slayer's Rise matches for this dominance achievement. Ensure you control Shenzar Refinery and both Bastions and Gates simultaneously, as winning without full control will not count.", x = 11 },
        [62516] = { e = 3, s = "s", r = "Single kill condition with no partial progress.", d = "During Slayer's Rise, target enemies at the Path of Predation immediately upon spawning to prevent them from dismounting. This requires quick reaction times and positioning, so focus your team's attention on this specific zone first.", x = 11 },
        [62517] = { e = 4, s = "g", r = "Killing rare ultradons is a long grind.", d = "Wait for the enemy faction to summon their ultradon at The Husk or Sparring Grounds before engaging it in Slayer's Rise. Do not leave these zones empty, as missing the spawn window makes this achievement impossible to complete later.", x = 11 },
        [62518] = { e = 3, s = "g", r = "Grinding 100 corrupted kills takes several hours.", d = "Defeat corrupted creatures during Void Strikes by targeting those afflicted with Apex Corruption, which appear frequently in Umbral Rift content. This is account-wide, so play regularly in these events to reach the 100-kill threshold efficiently.", x = 11 },
        [62521] = { e = 3, s = "s", r = "Single disruption event with no partial progress.", d = "Visit Broken Throne Ritual Site and disrupt it once to claim this simple objective-based achievement. No special conditions exist beyond simply interrupting the ritual mechanics at any tier.", x = 11 },
        [62522] = { e = 3, s = "s", r = "Single disruption event with no partial progress.", d = "Travel to Daggerspine Point Ritual Site and disrupt it once to complete this straightforward task. Ensure you are in the correct zone before starting, as these sites are location-specific.", x = 11 },
        [62523] = { e = 4, s = "c", r = "Requires specific high-tier disruption conditions.", d = "Disrupt Broken Throne Ritual Site specifically at Tier 5 difficulty to unlock this mastery version of the achievement. Check the site's current tier before engaging to avoid wasting attempts on lower levels.", x = 11 },
        [62524] = { e = 4, s = "c", r = "Requires disrupting site with many challenges active.", d = "Target Broken Throne Ritual Site while ensuring at least eight challenges are active simultaneously for this challenge variant. Monitor the challenge count closely, as dropping below eight will invalidate progress.", x = 11 },
        [62525] = { e = 5, s = "c", r = "Extreme tier requires high-level coordination and RNG.", d = "Combine Tier 5 difficulty with eight or more active challenges when disrupting Broken Throne Ritual Site for this extreme version. This is the hardest variant, so plan your run carefully to meet both conditions at once.", x = 11 },
        [62526] = { e = 3, s = "s", r = "Single disruption event with no partial progress.", d = "Disrupt Daggerspine Point Ritual Site specifically at Tier 5 difficulty to claim this mastery achievement. Verify the site's tier before starting, as lower tiers will not count toward this specific goal.", x = 11 },
        [62527] = { e = 4, s = "c", r = "Requires disrupting site under difficult challenge conditions.", d = "Disrupt Daggerspine Point Ritual Site while maintaining at least eight active challenges for this challenge variant. Keep track of the challenge counter throughout the fight to ensure you do not drop below the required threshold.", x = 11 },
        [62528] = { e = 4, s = "g", r = "Requires high-tier disruption with many challenges present.", d = "Start by completing the starter chain to unlock higher tiers, then queue for Daggerspine Point when it hits Tier 5 with eight challenges. Ensure you are not in a group if this specific extreme version requires solo play, though the description implies standard disruption rules apply.", x = 11 },
        [62529] = { e = 3, s = "g", r = "Simple completion but requires finding a ritual site.", d = "Begin your ritual journey by finding any active site and disrupting it while at least one challenge is present to unlock the next tier. This is the foundational step for all other ritual achievements in the chain.", x = 11 },
        [62530] = { e = 3, s = "g", r = "Requires completing a ritual with two challenges present.", d = "After unlocking the starter, repeat the process until you have completed a site with two challenges active simultaneously. Keep an eye on the challenge counter as it fluctuates during the event.", x = 11 },
        [62531] = { e = 4, s = "g", r = "Requires completing a ritual with four challenges present.", d = "Progress to this tier by ensuring your disruption occurs when four or more challenges are present at the ritual site. You must have already earned the previous achievement before attempting this one.", x = 11 },
        [62532] = { e = 4, s = "g", r = "Requires completing a ritual with six challenges present.", d = "Advance further by disrupting a site while six challenges are active, building on your progress from the adept tier. Monitor the challenge count closely as it changes dynamically during the event.", x = 11 },
        [62533] = { e = 5, s = "g", r = "Requires maximum difficulty disruption of a ritual site.", d = "Complete this final tier of the main chain by disrupting a site with eight challenges present, requiring you to have earned the handler achievement first. This represents the peak difficulty for standard ritual completion.", x = 11 },
        [62534] = { e = 5, s = "g", r = "Solo high-tier disruption with many challenges is very hard.", d = "This rogue version requires you to disrupt Broken Throne at Tier 5 with eight challenges while strictly avoiding being in a party. Solo queueing is mandatory, so do not accept invites during the event.", x = 11 },
        [62535] = { e = 5, s = "g", r = "Solo high-tier disruption with many challenges is very hard.", d = "Similar to the previous rogue achievement, target Daggerspine Point at Tier 5 with eight challenges present but ensure you are solo. The lack of party members is the key constraint here.", x = 11 },
        [62536] = { e = 4, s = "g", r = "Requires group play to disrupt a tier 4 ritual site.", d = "For this neighborhood watch variant, gather a group of three or more players and disrupt Broken Throne at Tier 4 regardless of challenge count. Forming a party is essential for this specific achievement.", x = 11 },
        [62537] = { e = 5, s = "g", r = "Group high-tier disruption with many challenges is very hard.", d = "Upgrade your team to handle Broken Throne at Tier 4 with eight challenges present while maintaining a party of three or more members. This combines high difficulty with group coordination requirements.", x = 11 },
        [62538] = { e = 4, s = "g", r = "Requires group play to disrupt a tier 4 ritual site.", d = "Switch targets to Daggerspine Point and repeat the neighborhood watch conditions: gather a party of three plus and disrupt the site at Tier 4. Focus on forming a group before engaging the ritual.", x = 11 },
        [62539] = { e = 5, s = "g", r = "Group high-tier disruption with many challenges is very hard.", d = "Complete this final team challenge by disrupting Daggerspine Point at Tier 4 with eight challenges present while in a party of three or more. Ensure your group size meets the requirement before starting the event.", x = 11 },
        [62540] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Find a Ritual Site in your zone and wait for the Tendrils challenge to spawn. Disrupt it by killing the adds or destroying the ritual object before time runs out.", x = 11 },
        [62541] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Locate a Ritual Site and watch for Tainted Corpses to appear near the altar. Quickly clear the corpses and defeat any nearby enemies to complete the disruption.", x = 11 },
        [62542] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Visit a Ritual Site and wait for Manifestations to manifest at the location. Eliminate these spectral entities promptly to successfully disrupt the ritual.", x = 11 },
        [62543] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Check active Ritual Sites for Patrols! challenges that spawn additional enemies. Focus fire on patrol members to clear the site before they overwhelm you.", x = 11 },
        [62544] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Monitor Ritual Sites for Magical Alarm Bells which trigger dangerous events. Interrupt the ritual immediately after the bells activate to prevent them from completing their goal.", x = 11 },
        [62545] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Seek out Ritual Sites hosting Malevolent Boons challenges. These often involve buffed enemies; prioritize killing the boon source or the main adds quickly.", x = 11 },
        [62546] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Find a Reinforced Ritual Site and prepare for tougher enemies or mechanics. Use your group's highest damage dealers to break through defenses before the timer ends.", x = 11 },
        [62547] = { e = 3, s = "c", r = "Requires finding specific rare ritual sites and defeating them.", d = "Look for Embers challenges at Ritual Sites which may involve environmental hazards. Clear the area of burning effects and enemies simultaneously to disrupt the site safely.", x = 11 },
        [62548] = { e = 4, s = "c", r = "Expert tier requires higher level content or better gear.", d = "This expert version requires Tier 5 difficulty; ensure you have a strong group before attempting. Wait for the Tendrils challenge on this high-tier site and focus all damage on it.", x = 11 },
        [62549] = { e = 4, s = "c", r = "Expert tier requires higher level content or better gear.", d = "Find a Tier 5 Ritual Site with Tainted Corpses active. Coordinate with your party to clear corpses efficiently while managing the increased difficulty of the encounter.", x = 11 },
        [62550] = { e = 4, s = "c", r = "Expert tier requires higher level content or better gear.", d = "Locate a Tier 5 site where Manifestations are present. These encounters are harder; use crowd control and burst damage to eliminate the manifestations before they heal or escape.", x = 11 },
        [62551] = { e = 4, s = "c", r = "Expert tier requires higher level content or better gear.", d = "Approach a Tier 5 Ritual Site with Patrols! spawning. The patrol groups will be larger and tougher, so maintain aggro management while disrupting the site quickly.", x = 11 },
        [62552] = { e = 3, s = "s", r = "Find and disrupt one specific challenge site.", d = "Complete this by disrupting any Tier 5 Ritual Site with the Magical Alarm Bells challenge. Focus on interrupting casters quickly to prevent the site from activating fully.", x = 11 },
        [62553] = { e = 3, s = "s", r = "Find and disrupt one specific challenge site.", d = "Target sites featuring the Malevolent Boons challenge and ensure you disrupt them before they complete their ritual. Avoid letting the boon effects trigger too many times.", x = 11 },
        [62554] = { e = 3, s = "s", r = "Find and disrupt one specific challenge site.", d = "Disrupt any Tier 5 Ritual Site marked with the Reinforced challenge. These sites often have extra defenses, so bring a group to handle them efficiently.", x = 11 },
        [62555] = { e = 3, s = "s", r = "Find and disrupt one specific challenge site.", d = "Find and disrupt a Tier 5 Ritual Site with the Embers challenge active. Watch for fire-based mechanics that can damage your party if ignored.", x = 11 },
        [62556] = { e = 4, s = "s", r = "High-difficulty single fight with strict damage limits.", d = "This requires disrupting a site with Tendrils and Manifestations while keeping all players hit no more than three times total. Coordinate dodges carefully to avoid taking excessive damage from these effects.", x = 11 },
        [62558] = { e = 3, s = "g", r = "Kill multiple patrols at a specific site.", d = "Kill at least three challenge patrols during a Tier 5 Ritual Site disruption to earn this achievement. Prioritize clearing patrol waves before focusing on the main site objective.", x = 11 },
        [62559] = { e = 4, s = "s", r = "High-difficulty single fight with strict survival limits.", d = "Disrupt a Tier 5 site with Malevolent Boons without destroying any dark obelisks. Use crowd control or kiting to neutralize threats while preserving the obelisk structures.", x = 11 },
        [62560] = { e = 4, s = "s", r = "High-difficulty single fight with strict survival limits.", d = "Complete a disruption on a Tier 5 Embers challenge site while leaving at least one ember active. Do not overkill the site; stop just before all embers are extinguished.", x = 11 },
        [62561] = { e = 3, s = "g", r = "Kill many creatures at a specific site.", d = "Disrupt a Reinforced Tier 5 site and kill more than fifty creatures during the encounter. Focus on pulling and killing adds aggressively to meet the kill count requirement.", x = 11 },
        [62562] = { e = 4, s = "c", h = { 225390, 225391, 225392 }, r = "Requires completing multiple distinct ritual site tasks.", d = "Unlock this by completing all listed Ritual Site sub-achievements first. Ensure you have access to Tier 5 content in Quel'Thalas before attempting these specific challenges.", x = 11 },
        [62563] = { e = 4, s = "c", h = { 225183, 225184, 225185 }, r = "Requires completing multiple distinct void assault tasks.", d = "Finish the Void Assault meta achievement and its associated sub-goals for Eversong and Zul'Aman. This unlocks the Unbound Manawyrm mount purchase option once all parts are done.", x = 11 },
        [62568] = { e = 4, s = "g", r = "Kill many enemies across various void content.", d = "Defeat two hundred fifty enemies across Void Strikes or Incursions to complete this account-wide goal. Grind these activities consistently as they contribute toward multiple other achievements simultaneously.", x = 11 },
        [62569] = { e = 3, s = "c", r = "Requires multiple Void Assault runs to find items.", d = "Start by collecting Dark Particles from Void Strikes and Incursions to unlock the Field Accolade. Talk to allies in major cities to exchange items for cores, scrolls, and missives. This is account-wide so coordinate with friends if you want faster progress.", x = 11 },
        [62570] = { e = 4, s = "g", r = "Grinding 15 specific high-level kills takes time.", d = "Focus on defeating elite enemies marked with advanced Void-Corruption during any Void Strike or Incursion. Do not worry about specific names; just look for the corruption effect on mobs. You need 15 kills, so grinding one strike repeatedly is efficient.", x = 11 },
        [62571] = { e = 3, s = "g", r = "Rescuing 50 NPCs requires multiple Void Assault runs.", d = "Rescue Forces of Azeroth by completing their small objectives before they are overwhelmed. These appear frequently during Void Assaults, so keep an eye on the minimap for rescue icons. Aim to clear the main event area quickly to maximize rescues per run.", x = 11 },
        [62572] = { e = 3, s = "g", r = "Tossing 50 batteries takes several Void Assault runs.", d = "Carry batteries and throw them at Ethereal Pylons when you see them spawn in Void Strikes or Incursions. This is a quick objective that does not require combat, making it easy to complete while fighting other targets. Ensure you have enough batteries before starting a new assault.", x = 11 },
        [62573] = { e = 4, s = "g", r = "Flying through 100 enemies requires many Void Assaults.", d = "Fly through swarming enemies during Void Assaults to count toward your total of 100. Use mounts or flying abilities to pass quickly through groups without engaging them in combat. This achievement is account-wide, so group up with friends who are also doing it.", x = 11 },
        [62574] = { e = 3, s = "g", r = "Earning 500 accolades takes multiple Void Assault runs.", d = "Earn Field Accolades by completing Ritual Sites challenges and Void Assaults objectives. Once you have 500, exchange them for the Accolade to Rest. Make sure you complete Outstanding in the Field first if required by your account status.", x = 11 },
        [62600] = { e = 3, s = "c", r = "Delivering three specific items requires one ritual run.", d = "Deliver one of each offering type to the Summoning Ritual event inside the Vaults of Atal'Utek. Gather items like eggs, ooze, and urns from nearby enemies or chests. Complete this during the active event window as it may not be available later.", x = 11 },
        [62601] = { e = 4, s = "c", h = { 225300 }, r = "Killing the boss is the hardest checklist item.", d = "Eliminate specific named threats within the Underbelly zone of the Vaults of Atal'Utek. Focus on bosses and elites listed in the achievement description. This is account-wide, so coordinate with a group to handle tough encounters efficiently.", x = 11 },
        [62604] = { e = 3, s = "c", r = "Dancing at three shrines requires one event run.", d = "Dance while defending each stone during the Cache of Three event in the Vaults of Atal'Utek. Use dance emotes or abilities when stones are under threat. Ensure you defend all three stones to complete the requirement for this 10-point achievement.", x = 11 },
        [62606] = { e = 3, s = "s", r = "Completing a single quest chain takes moderate time.", d = "Complete the quest The Omnium Reawakens to earn this achievement. Check your quest log for the specific task and follow its steps carefully. This is account-wide, so ensure your character completes it if you have not already.", x = 11 },
        [62621] = { e = 4, s = "c", h = { 225387 }, r = "Manifestations is the hardest challenge to unlock.", d = "Unlock all Ritual Sites challenges by defeating enemies associated with each challenge type. These include tendrils, tainted corpses, alarms, and more. Progress through different sites to encounter all challenge variants and unlock the full set.", x = 11 },
        [62622] = { e = 4, s = "g", r = "Grinding renown points takes significant time and effort.", d = "Increase your Ritual Sites Renown rank by completing daily and weekly activities in that zone. Reach Rank 8 by consistently earning renown points through quests and world events. This is account-wide, so group with others to speed up the process.", x = 11 },
        [62649] = { e = 3, s = "s", r = "Requires specific event timing and dungeon entry.", d = "Start this during the Earth and Sky event in Atal'Utek by collecting large wandering Soul Globes. Ensure you are present for the specific event window, as these globes do not appear otherwise.", x = 11 },
        [62759] = { e = 3, s = "g", r = "Grind to find 3 relics in one dive session.", d = "Complete a single Abyss Anglers dive to find three Sunken Relics scattered underwater. This is account-wide, so any character can contribute to the progress.", x = 11 },
        [62760] = { e = 3, s = "g", r = "Grind to catch fish from 3 bubbles in one dive.", d = "During one dive, catch fish from three Abyss Bubbles that float on the surface. Focus your attention on these specific targets rather than standard fishing spots.", x = 11 },
        [62761] = { e = 4, s = "g", r = "Long cumulative grind over many dives.", d = "Grind cumulative points across many dives until you reach one million total. This is account-wide, so play frequently to accumulate progress efficiently.", x = 11 },
        [62762] = { e = 3, s = "g", r = "Grind to swim through 250 fish schools.", d = "Swim through 250 different Schools of Fish during your Abyss Anglers sessions. Explore various zones in the trench to encounter diverse fish groups.", x = 11 },
        [62763] = { e = 4, s = "g", r = "Long grind collecting 250 treasures.", d = "Discover 250 Sunken or Ancient Treasures by exploring deep underwater areas. These items are account-wide, so maximize exploration time per dive.", x = 11 },
        [62772] = { e = 3, s = "g", r = "Grind to collect 100 fish from bubbles.", d = "Collect 100 fish from Abyss Bubbles over multiple dives. Prioritize these floating bubbles as your primary fishing target to track progress.", x = 11 },
        [62773] = { e = 4, s = "c", r = "Requires completing all other Abyss Angler achievements.", d = "Unlock all other Abyss Angler achievements listed in the info field to complete this one. Ensure you have finished every prerequisite achievement first.", x = 11 },
        [62774] = { e = 2, s = "s", r = "Simple interaction with air vents during dive.", d = "Regain your breath at either of the two air vents during a dive. Monitor your oxygen meter and swim to a vent before running out of air.", x = 11 },
        [62775] = { e = 3, s = "g", r = "Grind to capture specific small creatures.", d = "Use the Shallows Net or Triple-Thread Net to capture specific small creatures like Barbed Crawlers and Deep Whelks. Equip these nets before diving to catch the required targets.", x = 11 },
        [62776] = { e = 4, s = "c", r = "Requires catching every rarity fish type.", d = "Catch at least one fish of every rarity, from Common to Mythic, during your dives. Aim for Legendary and Mythic drops by exploring thoroughly and using high-tier gear.", x = 11 },
        [62777] = { e = 4, s = "g", r = "Grind to buy all upgrades from NPC.", d = "Purchase every upgrade available from Depthdiver Jeju, including tanks, nets, and bait. Visit the vendor regularly after unlocking new items to complete this checklist.", x = 11 },
        [62778] = { e = 3, s = "g", r = "Requires specific rare drops during a timed event.", d = "Start the Abyss Anglers questline to access dives, then focus on catching Epic rarity fish from Abyss Bubbles. This is account-wide so coordinate with friends if you need specific fish types quickly.", x = 11 },
        [62829] = { e = 2, s = "g", r = "Common failure events during the Abyss Anglers dive.", d = "Participate in Abyss Anglers dives and intentionally let yourself get caught by Axetooth Threshers or Fangrays. Do not overkill these enemies; dying to them counts toward the achievement.", x = 11 },
        [62832] = { e = 4, s = "g", r = "Requires catching only Mythic fish for a full score.", d = "Complete Abyss Anglers dives exclusively catching Mythic fish to earn points for this specific score requirement. Track your catch rarity carefully as mixing in lower tiers will reset progress.", x = 11 },
        [62873] = { e = 5, s = "c", h = { 229951 }, r = "Meta-achievement requiring multiple other difficult tasks.", d = "Unlock the Voidmancer's Starcarver mount meta-achievement first, then complete all listed sub-achievements across Val and Naigtal. This is account-wide so ensure you have access to both zones.", x = 11 },
        [62874] = { e = 5, s = "c", h = { 229957 }, r = "Meta-achievement requiring multiple other difficult tasks.", d = "Unlock the Netherforged Nullframe mount meta-achievement first, then finish all required sub-tasks in Naigtal. Prioritize completing the 'Into the Stars' prerequisite before tackling other objectives.", x = 11 },
        [62880] = { e = 3, s = "g", r = "Requires completing 8 specific world quests in Val.", d = "Complete eight different World Quests in Val by exploring the zone and accepting quests from various NPCs. Avoid repeating quest chains to ensure you meet the 'different' requirement.", x = 11 },
        [62881] = { e = 3, s = "g", r = "Requires defeating 6 rare creatures found in Val.", d = "Defeat six rare creatures in Val by checking local gossip text or rare spawn locations. Use a group if some rares require high-level tactics to defeat efficiently.", x = 11 },
        [62882] = { e = 3, s = "g", r = "Requires completing 8 specific world quests in Naigtal.", d = "Finish eight distinct World Quests in Naigtal, which involves exploring the swamp and interacting with unique environmental events. Ensure you track completed quest titles to avoid duplicates.", x = 11 },
        [62883] = { e = 3, s = "g", r = "Requires defeating 6 rare creatures found in Naigtal.", d = "Kill six rare creatures in Naigtal, including specific bosses like Interminable Uarn or Broxion. These spawns are often tied to world events or specific zones within the area.", x = 11 },
        [62887] = { e = 4, s = "g", r = "Requires completing 15 world quests on Heroic difficulty.", d = "Queue for Heroic World Tier content in Val or Naigtal and complete fifteen different World Quests. Note that some quests may only appear on Heroic difficulty, so check flags carefully.", x = 11 },
        [62901] = { e = 4, s = "g", r = "Requires defeating creatures with specific affixes on Heroic.", d = "Defeat ten creatures with specific Affixes like Arcane Presence or Steam Vents while in Heroic World Tier. Use a group to handle the increased difficulty of affixed enemies.", x = 11 },
        [62903] = { e = 3, s = "g", r = "Requires dissipating 5 storms in Val.", d = "Dissipate five Storms in Val by using appropriate abilities or items when they appear on the map. This is account-wide, so coordinate with friends if storms are rare spawns.", x = 11 },
        [62904] = { e = 1, s = "g", r = "Simple repeatable task with no RNG or difficulty.", d = "Start by accepting the Climate Strange: Naigtal quest to begin dissipating storms. You must complete this five times, so plan your rotations around the storm mechanics efficiently.", x = 11 },
        [62905] = { e = 3, s = "c", h = { 227657 }, r = "Requires defeating two specific raid bosses.", d = "Queue for Imperator Pertinax and Nexus-Captain Leth'ir immediately after unlocking the raid. Ensure you have a group ready as these are account-wide bosses requiring coordination.", x = 11 },
        [62909] = { e = 4, s = "c", h = { 227660 }, r = "Heroic difficulty adds significant time and RNG risk.", d = "Defeat the same two bosses but specifically in Heroic World Tier to earn this version. Make sure your gear and group composition meet the higher difficulty requirements before starting.", x = 11 },
        [62917] = { e = 3, s = "g", r = "Repeatable Heroic content; effort scales linearly with count.", d = "Focus on Val first to dissipate five storms in Heroic World Tier. This is account-wide, so coordinate with friends or use a finder if available for the heroic version.", x = 11 },
        [62919] = { e = 3, s = "g", r = "Repeatable Heroic content; effort scales linearly with count.", d = "Repeat the process for Naigtal in Heroic World Tier after completing Val. Ensure you track storm dissipation counts carefully to avoid missing the five-storm requirement.", x = 11 },
        [62940] = { e = 2, s = "c", r = "Requires completing a specific ritual site tier.", d = "Complete the prerequisite seminar quest before attempting any Tier 6 Ritual Site. Once unlocked, choose a site and finish it to gain progress toward this achievement.", x = 11 },
        [62941] = { e = 5, s = "c", h = { 227970 }, r = "Complex multi-stage event with strict challenge requirements.", d = "Visit both Broken Throne and Daggerspine Point Ritual Sites on Tier 6 with all eight challenges active. This is time-gated until Midnight ends, so prioritize it before the expansion concludes.", x = 11 },
        [63167] = { e = 3, s = "g", r = "Requires accumulating honor in a specific PvP zone.", d = "Enable War Mode and queue for Coiled Isle to earn honor. Accumulate 1000 honor points across multiple runs if needed, as this is account-wide and requires consistent participation.", x = 11 },
        [63170] = { e = 2, s = "c", r = "Find and open chests within a single delve instance.", d = "Explore Gnarldor Isle in Delves to locate all hidden Sturdy Chests. Open each one to complete the discovery requirement for this account-wide achievement.", x = 11 },
        [63171] = { e = 2, s = "c", r = "Find and open chests within a single delve instance.", d = "Travel to The Ring of Glory Delve and find every Sturdy Chest within the map. Opening all chests will grant you the points needed for this specific discovery achievement.", x = 11 },
        [63182] = { e = 4, s = "c", h = { 228854 }, r = "Requires completing multiple weekly ritual site studies.", d = "Accept Lady Darkglen's weekly studies and complete them in order from Week 1 through Week 6. Each week has unique objectives, so check her quest log regularly for new tasks.", x = 11 },
        [63237] = { e = 2, s = "s", r = "Single encounter defeat on any difficulty.", d = "Defeat Rotmire in Sporefall on any difficulty to unlock this achievement. You can do this solo or with a group, but ensure you are prepared for the boss mechanics regardless of difficulty level.", x = 11 },
        [63240] = { e = 4, s = "s", r = "Heroic raid boss requires group coordination and time.", d = "Queue for Rotmire on Heroic difficulty in Sporefall. This is account-wide, so any character can complete it once.", x = 11 },
        [63241] = { e = 5, s = "s", r = "Mythic raid boss is extremely difficult for a new player.", d = "Defeat Rotmire on Mythic difficulty in Sporefall. Ensure your group is prepared for higher mechanics as this is account-wide.", x = 11 },
        [63250] = { e = 4, s = "c", h = { 229087, 229133 }, r = "Requires specific mechanic execution on multiple bosses.", d = "Run The Venomous Abyss on Normal or higher and wait for Sentinels to use Vitriolic Stasis before killing them. This unlocks sub-achievements and is account-wide.", x = 11 },
        [63253] = { e = 2, s = "g", r = "Simple donation task across several zones.", d = "Visit taverns in Midnight zones like Eversong Woods or Zul'Aman during Brewfest to donate to Bar Tab Barrels. This is account-wide and time-gated to the event.", x = 11 },
        [63254] = { e = 5, s = "c", h = { 231541, 231542 }, r = "Depends on other hard raid achievements including Mythic.", d = "Complete all listed sub-achievements in The Venomous Abyss raid to unlock this Glory achievement. It grants a mount and is account-wide.", x = 11 },
        [63264] = { e = 5, s = "c", h = { 229643, 229644 }, r = "Requires completing multiple Heroic Void Assault achievements.", d = "Finish the specific Heroic Void Assault achievements listed to complete this set. This unlocks a purchasable reward and is account-wide.", x = 11 },
        [63325] = { e = 3, s = "g", r = "Collecting motes takes time but is straightforward.", d = "Earn five Motes of Omnial Inquiry in Void Assaults to use in the Omnium Folio. This unlocks a decor item and is account-wide.", x = 11 },
        [63348] = { e = 4, s = "c", h = { 229607, 229608 }, r = "Requires hunting rare spawns on Heroic World Tier.", d = "Defeat fifteen rare creatures in Val or Naigtal on Heroic World Tier. These rares are specific and require careful tracking to avoid missing any.", x = 11 },
        [63349] = { e = 3, s = "g", r = "Kill count during a specific world quest.", d = "Complete the world quest Until it is Done on Val while controlling the Ultradon Slayer to get kill credits. You need 100 kills for this account-wide achievement.", x = 11 },
        [63358] = { e = 4, s = "c", h = { 229658, 229659 }, r = "Requires finding and defeating all rare creatures.", d = "Defeat all twelve rare creatures listed on the Coiled Isle. This exploration achievement is account-wide and requires thorough map coverage.", x = 11 },
        [63359] = { e = 4, s = "c", h = { 229675, 229676 }, r = "Requires locating and interacting with hidden points.", d = "Discover all hidden treasures across the Coiled Isle by interacting with chests and objects. This unlocks a mount and is account-wide.", x = 11 },
        [63381] = { e = 4, s = "g", r = "Requires defeating a high number of specific enemies.", d = "Defeat 150 Curse Surges on the Coiled Isle to earn the title The Cursebreaker. Track your kills carefully as this is account-wide.", x = 11 },
        [63382] = { e = 4, s = "c", r = "Requires specific RNG event and account-wide status.", d = "Start this by accepting the 'Curse Surge Infestation' quest to begin the pregnancy process on Coiled Isle. Ensure you are in a group capable of handling high-level content, as the final step requires defeating specific bosses.", x = 11 },
        [63383] = { e = 2, s = "s", r = "Straightforward intro quest lines for NPCs.", d = "Begin these quests immediately after unlocking the Void Assaults feature, as they introduce the new characters Naigtal and Val. Complete them early to avoid missing any introductory dialogue or unique rewards tied to their arrival.", x = 11 },
        [63384] = { e = 3, s = "c", r = "Multiple standard quests on Val and Naigtal.", d = "Finish all listed quests on both Val and Naigtal before progressing further in the expansion storyline. These are often grouped together, so check your quest log regularly to ensure you do not miss any spatial reasoning puzzles or mushroom-related tasks.", x = 11 },
        [63385] = { e = 3, s = "c", r = "Several quest steps required on Naigtal.", d = "Focus entirely on Naigtal's specific quest lines involving Hal'hadar and Manaforge Reconnaissance. Do not delay these, as they may be tied to early game progression in that zone.", x = 11 },
        [63386] = { e = 3, s = "c", r = "Multiple quest steps required on Val.", d = "Complete the Frosty Domanaar Politics quests on Val, which include a title bout event. Make sure to participate in the specific arena matches listed to earn the required points.", x = 11 },
        [63390] = { e = 4, s = "g", r = "Grinding multiple bosses across the Coiled Isles.", d = "Defeat every Curse Surge boss listed, including Malformed Leviathan and Vassti, as this is account-wide. Prioritize clearing these encounters early since they are time-gated by the expansion's release date.", x = 11 },
        [63391] = { e = 5, s = "c", r = "High RNG requirement to hit all rings on boss.", d = "Enter The Venomous Abyss on Normal or higher difficulty and defeat Sszorak while jumping through every ring that appears. This requires precise movement mechanics, so practice dodging hazards before attempting the full achievement.", x = 11 },
        [63395] = { e = 4, s = "g", r = "Grinding multiple glyphs across the zone.", d = "Fly to each location listed in the Coiled Isles using Skyriding to discover all glyphs. Use a fast mount or flying ability to efficiently visit remote areas like The Wreck of Sethralis's Scales and Blistering Terrace.", x = 11 },
        [63397] = { e = 5, s = "c", r = "Requires specific raid mechanic and RNG drop.", d = "Defeat Vashnik only after you have successfully killed the Solidified Snake Venom boss in The Venomous Abyss. Ensure you are on Normal difficulty or higher, as this condition is strictly required for the achievement.", x = 11 },
        [63400] = { e = 2, s = "g", r = "Visiting scattered candy buckets is quick.", d = "Visit every Candy Bucket location across all Midnight zones during Hallow's End events. This is account-wide and time-gated to the holiday season, so plan your travel route to cover Eversong Woods, Harandar, Zul'Aman, and Voidstorm efficiently.", x = 11 },
        [63415] = { e = 3, s = "c", r = "Defeating four specific prey targets.", d = "Track down and defeat all four Prey targets from Coiled Isle: Janoa, Kursak, Batani, and Kadani. These are likely rare spawns or specific quest objectives, so check local gossip or quest markers for their locations.", x = 11 },
        [63416] = { e = 2, s = "s", r = "Completing one hunt instance is easy.", d = "Complete any single Prey Hunt in the Coiled Isle to earn this achievement. You do not need to finish all hunts, just one successful completion will grant the points.", x = 11 },
        [63418] = { e = 4, s = "c", r = "Requires specific dungeon run and boss kill on Normal+.", d = "Defeat Nek'zali, the Soulcoiler on Normal difficulty or higher after returning Kupamanduka to the Soulcoil Well in The Venomous Abyss. Ensure you have the required item before starting the encounter, as this is a specific sequence requirement.", x = 11 },
        [63432] = { e = 4, s = "g", r = "Grinding for all 10 unique gacha items takes significant time.", d = "Collect all twelve distinct offerings from Ofi's Cauldron by participating in the Cauldron Gacha event. Since these are random drops, be prepared to run multiple events or trade with friends if you miss any types.", x = 11 },
        [63434] = { e = 2, s = "g", r = "Leveling a companion is straightforward and fast.", d = "Raise your delve companion Valeera to level 70 by completing her Buddy System quests. This is account-wide and requires finishing the previous tier first before attempting this one.", x = 11 },
        [63435] = { e = 2, s = "g", r = "Continuing the companion level grind is easy.", d = "Continue raising Valeera from level 70 to 80 using delve content. Remember that this achievement unlocks only after you complete the prior level 70 milestone.", x = 11 },
        [63436] = { e = 3, s = "c", r = "Completing three distinct story variants requires some time.", d = "Complete every story variant of The Ring of Glory delve, including Open Night, Game Day, and Adopt-a-thon. Check your quest log regularly to ensure you have finished all available story branches.", x = 11 },
        [63437] = { e = 3, s = "c", r = "Completing three distinct story variants requires some time.", d = "Finish each story variant of the Gnarldor Isle delve, such as Olds and Ends and Minchi's Osseous Adventure. These stories are account-wide, so coordinate with friends if needed to cover all variants.", x = 11 },
        [63441] = { e = 4, s = "g", r = "Finding 15+ hidden souvenirs in housing is a tedious grind.", d = "Find every Secret Souvenir in your Razorwind Shores neighborhood during the Vacation Season endeavor. Some souvenirs may be hidden or require specific conditions, so explore thoroughly and check back periodically.", x = 10 },
        [63451] = { e = 4, s = "s", r = "Nightmare mode bosses are difficult and require good gear.", d = "Defeat Batani the Scaled or Kadani the Claw on Nightmare mode to earn this achievement. Ensure you are running the correct difficulty setting before engaging these bosses.", x = 11 },
        [63452] = { e = 4, s = "s", r = "Nightmare mode bosses are difficult and require good gear.", d = "Take down Janoa the Fang or Kursak the Coiled while on Nightmare mode. These encounters are part of the Prey expansion content and require appropriate gear for the higher difficulty.", x = 11 },
        [63453] = { e = 4, s = "s", r = "Nightmare mode boss fight is challenging without RNG help.", d = "Defeat Ral'kala, Terror of the Isle on Nightmare mode or with Curse of the Isle active. This is the first step in a chain, so complete it before moving to subsequent variants.", x = 11 },
        [63454] = { e = 5, s = "g", r = "Killing a specific boss 50 times on Nightmare is a long grind.", d = "Kill Ral'kala, Terror of the Isle fifty times while on Nightmare mode or with Curse of the Isle active. Track your kill count carefully as this is a repeat encounter requirement.", x = 11 },
        [63457] = { e = 3, s = "g", r = "Looting 100 relics from enemies is a moderate collection task.", d = "Loot 100 Ossified Relics from various sources in the Prey expansion. These items drop randomly, so engage multiple enemies and explore thoroughly to reach the required count.", x = 11 },
        [63472] = { e = 1, s = "s", r = "Collect a set on one class; trivial once gear is obtained.", d = "Equip the Tier 36 set from Midnight Season 2 on at least one character to complete this account-wide collection. Ensure you have access to the specific season content before starting, as appearances may not carry over if missed.", x = 11 },
        [63473] = { e = 2, s = "c", h = { 230752 }, r = "Unlock VFX is easiest; others require raiding or specific feats.", d = "Unlock the Mythic VFX achievement first, then defeat Ula'tek on Mythic difficulty or earn the Elite/Midnight Keystone Hero feats listed in the info. This is account-wide and requires specific raid progress.", x = 11 },
        [63476] = { e = 4, s = "g", r = "Mythic raid boss requires group coordination and multiple attempts.", d = "Defeat Ula'tek on Mythic difficulty to claim the Venom's End title. You must complete prior raid tiers first, as this is locked behind earlier achievements.", x = 11 },
        [63510] = { e = 2, s = "g", r = "Fishing score grind is steady but not excessively long.", d = "Fish in any zone to accumulate 2500 Midnight Anglin' Score in your journal. This is account-wide, so coordinate with friends if you need specific rare catches quickly.", x = 11 },
        [63512] = { e = 4, s = "g", r = "Collecting 10 rare fishing artifacts requires significant time and luck.", d = "Fish the Coiled Isle for all ten artifacts listed in the info. These items drop from Tokka's crewmates and require patience; check your inventory regularly to ensure none are missed.", x = 11 },
        [63519] = { e = 2, s = "s", r = "Complete a storyline quest chain; straightforward progression.", d = "Complete the Promise of Tomorrow storyline by finishing the associated quests Sins of the Past and To the Faithful. This unlocks the Light's Faithful title and is account-wide.", x = 11 },
        [63520] = { e = 4, s = "g", r = "Heroic raid requires group play and multiple boss kills.", d = "Clear all bosses in The Venomous Abyss on Heroic difficulty, including Ula'tek. You must finish this tier before attempting Mythic, so plan your group composition accordingly.", x = 11 },
        [63521] = { e = 4, s = "g", r = "Any difficulty raid clear still requires a full group run.", d = "Defeat every boss in The Venomous Abyss on any difficulty to unlock the base raid achievement. Start with Normal or Heroic if you are new to the content.", x = 11 },
        [63522] = { e = 5, s = "g", r = "Mythic raid with strict mechanics and high RNG dependency.", d = "Clear all bosses on Mythic difficulty after completing the Heroic tier. This is a significant time commitment, so ensure your group is well-gearred and coordinated.", x = 11 },
        [63523] = { e = 4, s = "s", r = "Single Mythic boss kill; requires group but no checklist.", d = "Defeat Nek'zali the Soulcoiler specifically on Mythic difficulty. You must have already completed the full Mythic raid tier before this individual boss achievement becomes available.", x = 11 },
        [63524] = { e = 4, s = "s", r = "Single Mythic boss kill; requires group but no checklist.", d = "Defeat Entombed Sentinels on Mythic difficulty as part of the full raid clear. Treat this like any other Mythic boss fight, requiring a solid group and strategy.", x = 11 },
        [63525] = { e = 4, s = "s", r = "Single Mythic boss kill; requires group but no checklist.", d = "Defeat The Lost Explorers on Mythic difficulty to complete this specific boss achievement. Ensure you have cleared the entire Mythic tier first before attempting this target.", x = 11 },
        [63526] = { e = 4, s = "s", r = "Mythic raid boss requires group and high skill.", d = "Queue for Vashnik the Malignant in The Venomous Abyss on Mythic difficulty. Ensure your group is ready as this boss requires specific mechanics and gear checks typical of Mythic raids.", x = 11 },
        [63527] = { e = 4, s = "s", r = "Mythic raid boss requires group and high skill.", d = "Defeat Sszorak in The Venomous Abyss on Mythic difficulty. Coordinate with your raid leader to handle the encounter efficiently since it is part of the main raid progression.", x = 11 },
        [63528] = { e = 4, s = "s", r = "Mythic raid boss requires group and high skill.", d = "Kill The Twin Fangs in The Venomous Abyss on Mythic difficulty. This boss requires a coordinated team effort, so ensure all members are prepared for the mechanics before starting.", x = 11 },
        [63529] = { e = 4, s = "s", r = "Mythic raid boss requires group and high skill.", d = "Defeat The Coiled Altar in The Venomous Abyss on Mythic difficulty. Focus on maintaining group survival and executing the required abilities to progress through this challenging encounter.", x = 11 },
        [63530] = { e = 4, s = "g", r = "Requires killing multiple bosses including hard Mythic ones.", d = "Complete Wing 1 of The Venomous Abyss by defeating Nek'zali the Soulcoiler, Entombed Sentinels, and Vashnik the Malignant. This achievement is account-wide, so ensure all characters on your account contribute to the kills.", x = 11 },
        [63531] = { e = 4, s = "g", r = "Requires killing multiple bosses including hard Mythic ones.", d = "Finish Wing 2 by defeating The Lost Explorers, Sszorak, and The Twin Fangs. Remember that this is an account-wide achievement, requiring all characters to participate in these specific boss kills.", x = 11 },
        [63532] = { e = 4, s = "g", r = "Requires killing multiple bosses including hard Mythic ones.", d = "Complete Wing 3 by defeating The Coiled Altar and Ula'tek. This final wing requires your entire account's characters to contribute to the necessary boss defeats for completion.", x = 11 },
        [63596] = { e = 3, s = "g", r = "Collecting 1000 snakes is a moderate time investment.", d = "Stomp on 1000 Insidious Snakes within the Vaults of Atal'Utek. This task can be done solo or in a group, but ensure you visit the correct area to find the snakes.", x = 11 },
        [63598] = { e = 4, s = "g", r = "Completing patrols involves difficult combat encounters.", d = "Complete all patrols within the Vaults of Atal'Utek for this account-wide achievement. Check each patrol location and complete them systematically to avoid missing any objectives.", x = 11 },
        [63599] = { e = 4, s = "g", r = "Incursions require completing multiple complex objectives.", d = "Finish all incursions in the Vaults of Atal'Utek. These are account-wide, so make sure every character on your account completes their respective incursion tasks.", x = 11 },
        [63600] = { e = 4, s = "g", r = "Strikes involve difficult combat and objective completion.", d = "Complete all strikes within the Vaults of Atal'Utek. This achievement is account-wide, requiring each character to complete their assigned strike objectives.", x = 11 },
        [63601] = { e = 4, s = "g", r = "Defeating Ancient Foes requires high-level group play.", d = "Defeat all Ancient Foes in the Vaults of Atal'Utek. Since this is an account-wide achievement, ensure all characters on your account contribute to defeating these specific enemies.", x = 11 },
        [63605] = { e = 3, s = "c", r = "Requires finding many hidden items in a housing zone.", d = "Start this during the Vacation Season endeavor. Explore your Founder's Point neighborhood thoroughly to locate all Secret Souvenirs, as missing any will make the achievement missable once the event ends.", x = 10 },
        [63606] = { e = 4, s = "c", r = "Depends on completing the previous checklist first.", d = "First complete the Souvenir Seeker achievements for both Razorwind Shores and Founder's Point. Once you have earned both individual titles, this account-wide achievement will automatically unlock.", x = 11 },
        [63608] = { e = 2, s = "s", r = "Collecting a specific PvP set is straightforward.", d = "Collect any full armor set from Midnight PvP Season 2 to earn this title. Ensure you participate in the specific PvP season events or use the correct gear sets available during that timeframe.", x = 11 },
        [63609] = { e = 4, s = "c", h = { 231282 }, r = "Requires defeating a boss before a specific event triggers.", d = "Defeat Ula'tek before the Greasy Hatchling breaks in The Venomous Abyss on Normal difficulty or higher. This is a timed encounter where you must prioritize killing the boss quickly to secure the pet reward.", x = 11 },
        [63610] = { e = 3, s = "c", r = "Finding scattered inscriptions takes some exploration time.", d = "Explore the Vaults of Atal'Utek to discover all Funerary Inscriptions scattered throughout the area. Read each inscription carefully as they are located in specific spots within the temple ruins.", x = 11 },
        [63619] = { e = 2, s = "c", r = "Completing visitor quests is a short task.", d = "Visit the Arcantina and complete quests from every available visitor NPC listed in the achievement requirements. Check your quest log regularly to ensure you have finished all current visitor tasks.", x = 11 },
        [63620] = { e = 1, s = "c", r = "Retrieving and placing two specific items is quick.", d = "Retrieve and display specific items like the Stormstout Brewery Lantern and Wooden Toy Sword in your Arcantina home. Place these decorations in any valid slot within your house to complete the requirement.", x = 11 },
        [63629] = { e = 4, s = "g", r = "Fishing for every fish on an island requires time.", d = "Fish every species available on The Coiled Isle using appropriate bait and locations. This is a grind that requires patience and checking all fishing spots to ensure you catch every unique fish listed.", x = 11 },
        [63630] = { e = 5, s = "c", h = { 231373, 231374 }, r = "Meta achievement requiring multiple difficult sub-tasks.", d = "Complete the meta achievement by finishing all sub-achievements listed under Assault the Vault. You must master various mechanics in the Vaults of Atal'Utek, including patrol rolls and incursion defenses.", x = 11 },
        [63631] = { e = 4, s = "g", r = "Reaching exalted reputation requires significant contribution.", d = "Grind reputation with Captain Tokka until you reach the Bloodsworn Crew rank. Focus on daily quests and world events in the Ula'tek zone to gain the necessary reputation points efficiently.", x = 11 },
        [63632] = { e = 4, s = "g", r = "Fishing multiple copies of specific rare fish takes time.", d = "Catch five of each specified fish to earn Trophy rank with them. This requires significant fishing time, so consider using high-level bait and visiting popular fishing zones on The Coiled Isle.", x = 11 },
        [63633] = { e = 2, s = "g", r = "Feeding a pet via world quests is moderately fast.", d = "Complete the world quest Ki'clak Snack Attack five times to feed him snacks. Once you have fed him the required amount, you will receive the pet reward and complete the achievement.", x = 11 },
        [63634] = { e = 1, s = "s", r = "Talk to NPC with specific item equipped.", d = "Equip The Coiled Huntress and speak to Captain Tokka immediately, as this is account-wide but requires the specific item. Ensure you have the fishing specialization active before talking to him to trigger the interaction.", x = 11 },
        [63635] = { e = 4, s = "c", h = { 231422, 231423, 231424 }, r = "Requires completing multiple sub-achievements including grinds.", d = "Complete all four prerequisite achievements listed in the info field first, then return to Captain Tokka for the final point and title. This is a gatekeeper achievement, so do not start it until the others are done.", x = 11 },
        [63636] = { e = 3, s = "g", r = "Unlock talent points via repeated actions.", d = "Unlock every talent point at the Altar of Corrosion within the Vaults of Atal'Utek by defeating enemies or completing activities that grant points. Check your talent tree frequently to ensure no points remain locked before finishing the zone.", x = 11 },
        [63639] = { e = 4, s = "c", h = { 231486, 231487, 231488 }, r = "Combines exploration with difficult sub-achievements.", d = "Finish all major Coiled Isle achievements, including exploration and storylines, as they are required to unlock this main zone completion goal. Treat this as a checklist of other achievements rather than a separate task.", x = 11 },
        [63640] = { e = 3, s = "g", r = "Explore map areas; steady progress reduces time.", d = "Travel to every named location on the Coiled Isle map to reveal covered areas and earn points for full exploration. Use a flying mount or glider to efficiently visit remote spots like Gnarldor Isle and Mlurkkr Mire.", x = 11 },
        [63641] = { e = 4, s = "c", h = { 231495, 231497, 231501 }, r = "Multiple optional storylines with some difficult quests.", d = "Complete all optional storylines listed in the info field, which include various NPC quests and local events scattered across the Coiled Isle. These are account-wide, so coordinate with friends if some parts require specific class abilities or group mechanics.", x = 11 },
        [63642] = { e = 4, s = "g", r = "Survive 100 snare barrages on high difficulty.", d = "Survive 100 Toxic Snare barrages on Hard or Nightmare mode by dodging traps in The Venomous Abyss or similar zones. This is a grind that requires patience and good positioning to avoid taking damage.", x = 11 },
        [63643] = { e = 3, s = "g", r = "Kill 150 pack scouts on hard mode.", d = "Kill 150 Pack Scouts on Hard or Nightmare mode, focusing on areas where these enemies spawn frequently. Use area-of-effect abilities to clear groups quickly and track your progress via the achievement tracker.", x = 11 },
        [63644] = { e = 3, s = "g", r = "Kill 200 venom-bloated pythons on high difficulty.", d = "Defeat 200 Venom-Bloated Pythons while in Hard or Nightmare mode, which may require finding specific lairs or dungeons where they appear. Be prepared for their venom attacks and use resistance gear if available.", x = 11 },
        [63645] = { e = 4, s = "c", h = { 231547 }, r = "Defeat raid boss including specific mechanic.", d = "Defeat The Lost Explorers including Hoji in The Venomous Abyss on Normal difficulty or higher to unlock this raid achievement. Ensure you have the right group composition to handle Hoji's mechanics effectively.", x = 11 },
        [63653] = { e = 4, s = "g", r = "Complete 250 patrols; steady grind reduces time.", d = "Complete 250 patrols within the Vaults of Atal'Utek by engaging enemies and completing patrol objectives. This is a time-gated grind, so plan your runs efficiently to avoid missing out on the mount reward.", x = 11 },
        [63656] = { e = 4, s = "c", h = { 231622, 231623, 231626 }, r = "Feed specific items in order before boss fight.", d = "Defeat the Twin Fangs after feeding Ithraz the specific slimes in the correct order during Ravenous Feast in The Venomous Abyss. Coordinate with your group to collect and feed items before engaging the final boss.", x = 11 },
        [63662] = { e = 2, s = "c", r = "Collecting scattered lore items in a zone takes under an hour solo.", d = "Search the Coiled Isle for lore objects like tablets and logs scattered across the map. Ensure you explore every corner of the zone to collect all items before leaving, as they do not respawn.", x = 11 },
        [63669] = { e = 4, s = "s", r = "Requires specific raid mechanics and group coordination on Normal+.", d = "Run The Venomous Abyss Normal or higher with a full group while maintaining the Unnerving Fixation debuff on everyone. Keep the buff active throughout the entire fight against The Coiled Altar to secure the achievement.", x = 11 },
        [63670] = { e = 4, s = "c", r = "Finding and comforting spirits in a raid instance requires a group.", d = "Complete the Honoring Da Spirits questline in The Venomous Abyss to find and comfort all trapped spirits. Speak with each NPC individually to trigger their specific Ancestral Vision event.", x = 11 },
        [63681] = { e = 4, s = "s", r = "Heroic raid boss kill requires a prepared group and strategy.", d = "Queue for Heroic difficulty of The Tidebound Grotto to defeat Nymrissa Wavecaller. This is a standard raid encounter requiring a coordinated group effort.", x = 11 },
        [63682] = { e = 5, s = "s", r = "Mythic raid boss kill is difficult and requires high-level groups.", d = "Challenge yourself by running The Tidebound Grotto on Mythic difficulty to defeat Nymrissa Wavecaller. Ensure your group is prepared for the increased mechanics and damage output.", x = 11 },
        [63683] = { e = 4, s = "s", r = "Any difficulty raid boss kill still requires a group effort.", d = "Defeat Nymrissa Wavecaller in The Tidebound Grotto on any difficulty setting to claim this basic raid achievement. Start with Normal if you are new to the encounter.", x = 11 },
        [63692] = { e = 4, s = "s", r = "First Mythic+ style boss kill requires a raid group.", d = "Begin by defeating Kith'ix in The Unbinding of Kith'ix on Normal difficulty. This is the first step in a chain that unlocks higher difficulties later.", x = 11 },
        [63693] = { e = 5, s = "c", r = "Heroic run depends on completing the base Mythic+ boss first.", d = "After completing the normal version, return to The Unbinding of Kith'ix for Heroic difficulty. You must defeat the boss again with the Heroic tag active.", x = 11 },
        [63694] = { e = 5, s = "c", r = "Mythic run depends on completing Heroic and base boss first.", d = "Complete the Heroic run first, then challenge yourself to Mythic difficulty where Kith'ix appears. Note that this requires finishing the previous tier in the chain.", x = 11 },
        [63695] = { e = 2, s = "g", r = "Winning 10 arena matches is easy with a casual group.", d = "Play ten matches of Training Grounds Arena against any opponent to win this initial milestone. You can queue randomly or pick specific opponents for practice.", x = 11 },
        [63696] = { e = 3, s = "g", r = "Winning 25 matches takes moderate time but shrinks steadily.", d = "Continue playing Training Grounds Arena until you have won twenty-five total matches. This extends the previous requirement and tests your consistency in PvP.", x = 11 },
        [63697] = { e = 4, s = "g", r = "Winning 100 matches is a long grind requiring consistent play.", d = "Play one hundred matches of Training Grounds Arena to complete this final tier. Be prepared for a long grind as this requires significant time investment.", x = 11 },
        [63698] = { e = 2, s = "g", r = "Grinding 250 wins is easy but requires time.", d = "Queue for Training Grounds matches and win 250 times. This is purely a grind requiring consistent wins; do not worry about specific arena types as any victory counts toward the total.", x = 11 },
        [63699] = { e = 2, s = "c", r = "Win in 4 arenas; no single arena dominates.", d = "Win at least one match in each of the four listed arenas to unlock this achievement. You can switch arenas between matches, so just ensure you visit all locations before quitting.", x = 11 },
        [63717] = { e = 3, s = "g", r = "Finding and opening 44 chests takes exploration time.", d = "Explore every corner of Kindo'jan's Labyrinth to find and open all 44 Sturdy Chests. This is a thorough exploration task where missing a chest means you must restart the delve.", x = 11 },
        [63718] = { e = 2, s = "s", r = "One specific door to open; trivial once found.", d = "Locate and interact with the single locked door hidden somewhere in the labyrinth. Once opened, this achievement completes instantly as it does not require multiple uses.", x = 11 },
        [63719] = { e = 2, s = "g", r = "Opening the door 20 times is a short grind.", d = "Open the same locked door 20 times total across your runs. You can do this by repeatedly entering the delve and finding the door again to rack up the count.", x = 11 },
        [63720] = { e = 2, s = "c", r = "Collecting 3 specific items; none are rare.", d = "Defeat or interact with all three Elemental Hexmasks during a single run of the labyrinth. Ensure you check every zone within the instance before leaving to collect these rare items.", x = 11 },
        [63721] = { e = 2, s = "s", r = "Completing one run is a single event step.", d = "Navigate through all nine chambers in one continuous run without dying or resetting. If you die, you must restart from the beginning to complete this specific single-run goal.", x = 11 },
        [63722] = { e = 3, s = "s", r = "Requires high-tier gear but still one run.", d = "Complete a full nine-chamber run specifically on Tier 11 difficulty. You may need to level up your gear or team composition before attempting this higher-difficulty version of the delve.", x = 11 },
        [63723] = { e = 3, s = "g", r = "Grinding 100 chambers is moderate time investment.", d = "Accumulate a total of 100 chamber completions across multiple runs. This is a long-term goal that can be tracked over time as you progress through the content repeatedly.", x = 11 },
        [63724] = { e = 1, s = "s", r = "Just entering the instance; takes minutes.", d = "Simply enter Kindo'jan's Labyrinth for your first visit to claim this achievement. No specific gear or level is required beyond what is needed to access the zone itself.", x = 11 },
        [63727] = { e = 2, s = "g", r = "Looting 10 items is a short collection task.", d = "Loot 10 Mislaid Treasures scattered throughout the labyrinth. These items drop from enemies or appear in chests, so thoroughly clear every room to ensure you find enough.", x = 11 },
        [63728] = { e = 3, s = "g", r = "Looting 50 items requires more time than 10.", d = "Continue looting Mislaid Treasures until you reach a total of 50. This builds directly on the previous achievement and requires significantly more thorough exploration over time.", x = 11 },
        [63838] = { e = 1, s = "g", r = "Reputation grind is trivial once started.", d = "This is an account-wide reputation achievement requiring rank 20 with Zul'jarra's Forces. Focus on completing daily quests and world events in the zone to gain reputation efficiently. Note that this content may be time-gated or unavailable depending on your server's current event schedule.", x = 11 },
        [64160] = { e = 2, s = "c", h = { 234918 }, r = "Quests are easy; one item is rare RNG.", d = "Complete all three specific candy quests in Duskwood during Hallow's End to earn this title. Ensure you collect the required items like Blighted Core Caramels before the event ends, as these drops are missable if the holiday concludes.", x = 11 },
        [64161] = { e = 2, s = "c", h = { 234922 }, r = "Quests are easy; one item is rare RNG.", d = "Finish the Felwood-themed candy quests by gathering items such as Felroot Crunch and Rotleaf Wafers. Since this is a seasonal event, start immediately upon launch to avoid missing the window for obtaining these rare drops.", x = 11 },
        [64162] = { e = 2, s = "c", h = { 234926 }, r = "Quests are easy; one item is rare RNG.", d = "You must complete all Drustvar candy quests involving Hexed Honeycombs and Witchbane Truffles before Hallow's End ends. This achievement is account-wide, so coordinate with friends if you need help finding specific quest givers in the zone.", x = 11 },
    },
